const OPENCORPUS_RECIPES = [{"id":"oc-plwb-7497","title":"American Pancakes","cuisine":"American","category":"Breakfast","ingredients":["500 ml wheat flour","500 ml buttermilk","1 tsp baking powder","1 tsp baking soda","1 egg","2 tbsp butter (for the batter)","1 tbsp sugar","0.5 tsp salt","to taste butter or oil (for frying)","to taste maple syrup (for serving)"],"steps":["Melt the butter in a saucepan and set aside to cool.","In one bowl, whisk together the wheat flour, salt, sugar, baking soda, and baking powder.","In a second bowl, whisk together the buttermilk, egg, and cooled melted butter.","Combine the dry ingredients with the wet ingredients, stir to combine, and refrigerate the batter for 60 minutes.","Heat butter or oil in a frying pan and fry small pancakes on both sides until golden.","Serve the warm pancakes drizzled with maple syrup."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ameryka%C5%84skie_nale%C5%9Bniki","page":"Książka kucharska/Amerykańskie naleśniki"},{"id":"oc-plwb-19566","title":"Brownies (double chocolate brownies)","cuisine":"American","category":"Cake","ingredients":["360 g unsalted butter","340 g semi-sweet chocolate","6 eggs","260 ml sugar","1 tbsp vanilla extract","255 ml plain flour","1 tsp salt","75 ml white chocolate chips","75 ml semi-sweet chocolate chips","2 tsp icing sugar (for dusting)"],"steps":["Preheat the oven to 175 °C and line a rectangular baking pan with baking paper.","Melt the unsalted butter and semi-sweet chocolate in a saucepan over low heat and let cool slightly.","Beat the eggs with sugar and vanilla extract in a separate bowl.","Combine the cooled chocolate with the egg mixture and beat thoroughly, then fold in the plain flour, salt, white chocolate chips, and semi-sweet chocolate chips.","Pour the batter into the prepared pan and bake for about 25 minutes at 175 °C, until the top becomes lighter and the centre remains slightly moist.","Slice the warm cake into squares, arrange on a serving plate, and dust with sifted icing sugar."],"time":45,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Brownies","page":"Książka kucharska/Brownies"},{"id":"oc-plwb-28071","title":"Carrot cake","cuisine":"American","category":"Cake","ingredients":["250 g wheat flour (2 cups (500 ml))","300 g carrots (2 cups (500 ml), coarsely grated)","250 ml vegetable oil (1 cup (250 ml))","3 eggs (3–4 eggs)","300 g sugar (1 1/2 cups (375 ml))","1 tsp baking soda","1 tsp baking powder","6 nuts (several, chopped)"],"steps":["Beat the eggs with the sugar until smooth and light.","Pour the oil into the egg mixture in a slow, steady stream while continuing to beat.","Sift the wheat flour, baking soda, and baking powder into a separate bowl, then mix thoroughly with the egg and oil mixture.","Fold the grated carrots and chopped nuts into the smooth batter until evenly distributed.","Transfer the batter into a baking tin and bake for 60 minutes in an oven preheated to 180 °C."],"time":80,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_marchewkowe","page":"Książka kucharska/Ciasto marchewkowe"},{"id":"oc-plwb-5483","title":"Charleston (warm chocolate brownie cake)","cuisine":"American","category":"Cake","ingredients":["500 g dark chocolate (61–85% cocoa content)","200 g butter","6 eggs","100 g plain flour","350 g sugar","100 ml whipping cream (30% fat, for the glaze)","to taste whipped cream (for serving)"],"steps":["Melt 400 g of dark chocolate (4 bars) together with the butter in a water bath, then let cool slightly.","Beat the whole eggs, add the plain flour and sugar, and mix into the cooled chocolate mixture.","Pour the batter onto a large baking sheet or baking pan and bake for 12 to 20 minutes in an oven preheated to 200 °C.","While the cake bakes, bring the whipping cream to a boil and melt the remaining 100 g of dark chocolate in it.","Pour the prepared chocolate glaze over the baked cake and serve warm with whipped cream."],"time":40,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Charleston","page":"Książka kucharska/Charleston"},{"id":"oc-plwb-31885","title":"Chleb jajeczny z Baltimore (Baltimore egg bread)","cuisine":"American","category":"Bread","ingredients":["2 eggs","750 ml plain flour","1 l milk","1 tbsp fat (melted)","1 tsp salt","0.25 tsp baking soda","1.5 tsp baking powder"],"steps":["Preheat the oven to 180 °C.","Beat the eggs thoroughly, then add the milk, plain flour, salt, baking soda, and baking powder.","Pour in the melted fat last and stir into a batter.","Pour the mixture into the tin and bake at 180 °C for about 40 minutes in the tin and for 10 minutes after unmoulding."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_jajeczny_z_Baltimore","page":"Książka kucharska/Chleb jajeczny z Baltimore"},{"id":"oc-plwb-31851","title":"Chleb kukurydziany Ciotki Karoliny (Aunt Caroline's cornbread)","cuisine":"American","category":"Bread","ingredients":["190 ml cornmeal","190 ml plain flour","3 tsp baking powder","1 tbsp sugar","0.33 tsp salt","1 egg (beaten)","190 ml milk (diluted with water)","2 tsp liquid fat (such as melted butter or fat rendered from pork fatback)"],"steps":["Preheat the oven to 190 °C and grease a shallow baking pan well.","Mix together the cornmeal, plain flour, baking powder, sugar, salt, beaten egg, milk, and liquid fat into a smooth batter.","Pour the batter into the prepared pan and bake for about 25 minutes at 190 °C."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_kukurydziany_Ciotki_Karoliny","page":"Książka kucharska/Chleb kukurydziany Ciotki Karoliny"},{"id":"oc-plwb-31889","title":"Chleb na soli (salt-rising bread)","cuisine":"American","category":"Bread","ingredients":["3 tbsp cornmeal (heaped)","1 l milk","1 tsp sugar","1.2 kg wheat flour (500 ml for the starter, with the remaining flour used to make the dough)","1 tsp salt","1 tbsp fat"],"steps":["Mix the cornmeal thoroughly with 500 ml of boiling milk and leave in a warm place overnight.","In the morning, warm the remaining 500 ml of milk and add it to the starter while still warm, along with the sugar and 500 ml of wheat flour.","Stir the mixture and rest in a warm spot for about 120 minutes until sponge-like and bubbly.","Add the salt, fat, and remaining wheat flour, then knead a soft dough for 15 minutes.","Shape into a loaf, rest to rise for 60–120 minutes, and then bake for 60 minutes in an oven preheated to 200 °C."],"time":90,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_na_soli","page":"Książka kucharska/Chleb na soli"},{"id":"oc-plwb-31938","title":"Ciastka plantatora (coconut and cereal-flake cookies)","cuisine":"American","category":"Cookie","ingredients":["2 eggs","250 ml sugar","375 ml cereal flakes (oat, spelt, or other cereal flakes)","165 ml desiccated coconut","0.25 tsp salt","0.5 tsp vanilla flavouring","2 tbsp butter"],"steps":["Preheat the oven to 180 °C and grease a baking sheet well.","Cream the sugar with the butter until smooth, then incorporate the well-beaten eggs.","Mix the batter with the cereal flakes, desiccated coconut, salt, and vanilla flavouring.","Drop spoonfuls of dough onto the prepared baking sheet and bake for 15–20 minutes at 180 °C."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciastka_plantatora","page":"Książka kucharska/Ciastka plantatora"},{"id":"oc-plwb-31892","title":"Cream of celery soup","cuisine":"American","category":"Soup","ingredients":["3 celery (stalks)","0.5 onion","750 ml milk (plus a splash of cold milk to blend the flour)","3 tbsp butter","3 tbsp plain flour","to taste salt","to taste pepper","250 ml sour cream"],"steps":["Finely chop the celery stalks and onion, place in a pot with 750 ml of milk, and simmer for 20 minutes.","Add the pre-melted butter and the flour smoothly blended with a splash of cold milk, bringing to a boil until thickened.","Season the soup with salt and pepper, stir in 250 ml of sour cream, mix well, and serve warm."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krem_z_selera","page":"Książka kucharska/Krem z selera"},{"id":"oc-plwb-13760","title":"Eggnog","cuisine":"American","category":"Drink","ingredients":["500 ml milk","250 ml whipping cream (30% fat)","100 g sugar","1 tsp grated nutmeg","2 eggs","100 ml rum","100 ml cognac"],"steps":["Separate the egg yolks from the whites.","Beat the egg yolks while slowly adding the sugar until pale and fluffy.","Stirring continuously, pour the rum and cognac into the yolks, then chill in a cool place for at least 3 hours.","Whip the egg whites until stiff peaks form, and whip the 30% whipping cream in a separate bowl.","Pour the milk into a glass bowl and gently fold in the alcoholic egg mixture, whipped cream, and beaten egg whites.","Pour the drink into glasses, dust with grated nutmeg, and serve."],"time":220,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Egg-nog","page":"Książka kucharska/Egg-nog"},{"id":"oc-plwb-31939","title":"Evening raisins (baked lemon-glazed raisins)","cuisine":"American","category":"Dessert","ingredients":["150 g raisins (chopped)","200 g sugar","1 lemon (juice and grated zest)","2 tbsp water"],"steps":["Grate the zest from the scalded lemon and squeeze out its juice.","Combine the chopped raisins with the lemon juice and zest, add the sugar, and pour in the water.","Transfer the mixture to a baking dish or use as a pastry filling, and bake for about 50 minutes in an oven preheated to 160 °C."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rodzynki_wieczorow%C4%85_por%C4%85","page":"Książka kucharska/Rodzynki wieczorową porą"},{"id":"oc-plwb-31883","title":"Fluffy cotton blossom (popovers)","cuisine":"American","category":"Bread","ingredients":["2 egg","240 ml milk","125 g plain flour","0.5 tsp salt"],"steps":["Beat the eggs in a bowl, pour in the milk, add the salt and plain flour, and whisk thoroughly into a smooth, thin batter.","Pour the batter into muffin cups or into a single baking dish.","Bake for about 40 minutes in an oven preheated to 160 °C, then finish baking for 5 minutes at 180 °C and serve immediately."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Puszysty_kwiat_bawe%C5%82ny","page":"Książka kucharska/Puszysty kwiat bawełny"},{"id":"oc-plwb-31897","title":"Frykas z jabłek (spiced apple and raisin relish)","cuisine":"American","category":"Preserve","ingredients":["3.2 kg apples","900 g raisins","500 ml vinegar","1.6 kg sugar","2 oranges (juice and pulp)","1 tsp ground cloves","2 tsp ground cinnamon"],"steps":["Peel and core the apples, then chop the fruit into small pieces.","Squeeze the juice and scoop out the pulp from the oranges.","In a large pot, combine the chopped apples, raisins, orange juice and pulp, sugar, vinegar, ground cloves, and cinnamon.","Simmer over moderate heat for 30 minutes, stirring occasionally, until the fruit is tender and the syrup thickens."],"time":60,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Frykas_z_jab%C5%82ek","page":"Książka kucharska/Frykas z jabłek"},{"id":"oc-plwb-20911","title":"Jajka w koszyczkach (egg in a basket)","cuisine":"American","category":"Breakfast","ingredients":["2 slice toast bread","2 eggs","2 tbsp butter","to taste salt","to taste black pepper"],"steps":["Cut round holes out of the centers of toast bread slices using a glass or a cookie cutter.","Butter the bread slices and the cut-out bread rounds on both sides.","Place the bread in a heated skillet and fry one side until golden brown.","Flip the bread slices over and crack one egg into the hole of each slice.","Season the eggs with salt and pepper, and fry until the egg whites are set."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_w_koszyczkach","page":"Książka kucharska/Jajka w koszyczkach"},{"id":"oc-plwb-31859","title":"Kawa luizjańska (Louisiana egg coffee)","cuisine":"American","category":"Drink","ingredients":["1 tsp ground coffee (heaping)","1 tsp egg white (a little)","250 ml water (mostly boiling, with a splash of cold water)"],"steps":["Scald a coffee pot with boiling water, add ground coffee, egg white, and a splash of cold water, then stir thoroughly.","Pour the remaining boiling water over the mixture and simmer gently over low heat for 5 minutes.","Set the pot in a warm place for 15 minutes without boiling to allow the grounds to settle, then pour the clear coffee."],"time":25,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kawa_luizja%C5%84ska","page":"Książka kucharska/Kawa luizjańska"},{"id":"oc-plwb-31862","title":"Kleik kukurydziany (cornmeal mush)","cuisine":"American","category":"Breakfast","ingredients":["875 ml water (boiling)","1 tsp salt","250 ml cornmeal"],"steps":["Bring 875 ml of water to a boil and add the salt.","Gradually sift 250 ml of cornmeal into the boiling water, stirring vigorously with your other hand the whole time to prevent lumps.","Cook the mixture over direct heat for about 10 minutes.","Transfer the pot over a water bath and steam the mush for 2 hours, then serve warm (or let cool in smaller portions, slice, and fry)."],"time":135,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kleik_kukurydziany","page":"Książka kucharska/Kleik kukurydziany"},{"id":"oc-plwb-31880","title":"Mississippi biscuits","cuisine":"American","category":"Bread","ingredients":["250 g wheat flour (approximately 2 cups (500 ml))","0.25 tsp baking soda","2 tbsp lard (or clarified butter)","1 tsp salt","1.5 tsp baking powder","to taste milk (amount needed to form a soft dough)"],"steps":["Combine the flour, baking powder, baking soda, and salt in a bowl.","Cut in the lard, then gradually pour in the milk and knead lightly into a soft dough.","Roll out the dough thinly, cut into pieces, and bake for about 8 minutes in an oven preheated to 200 °C."],"time":18,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciastka_z_Missisipi","page":"Książka kucharska/Ciastka z Missisipi"},{"id":"oc-plwb-31882","title":"Mother's potato pudding (maminy pudding z kartofli)","cuisine":"American","category":"Dessert","ingredients":["3 potatoes (medium)","200 g sugar","3 egg","1 tbsp butter (plus extra for greasing and topping)","500 ml milk","1 tsp vanilla sugar (optional)","to taste vanilla flavouring (optional)"],"steps":["Grate the peeled potatoes or boil and mash them into a smooth puree, and preheat the oven to 180 °C.","Whisk the sugar with the eggs, tablespoon of butter, and milk, adding the vanilla sugar and vanilla flavouring.","Combine the egg-milk mixture with the mashed potatoes and mix thoroughly.","Transfer the mixture into a buttered baking dish, dot with butter pieces on top, and bake for 60 minutes at 180 °C."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Maminy_pudding_z_kartofli","page":"Książka kucharska/Maminy pudding z kartofli"},{"id":"oc-plwb-31936","title":"Sałatka Waldorf (Waldorf salad)","cuisine":"American","category":"Salad","ingredients":["500 ml apples (approximately; chopped)","500 ml celery (approximately; chopped)","250 ml nuts (approximately)","to taste olive oil"],"steps":["Peel and core the apples, then dice the flesh.","Wash the celery stalks and slice them finely.","Combine the diced apples, celery and nuts in a bowl, drizzle with olive oil, and mix thoroughly."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_Waldorf","page":"Książka kucharska/Sałatka Waldorf"},{"id":"oc-plwb-31887","title":"Sałatka z kartofli (potato salad)","cuisine":"American","category":"Salad","ingredients":["5 potatoes (medium)","3 eggs","to taste parsley leaves","to taste celery","to taste salt","to taste pepper (black and red)","to taste olive oil"],"steps":["Boil the potatoes until tender, let cool, and cut into cubes.","Hard-boil the eggs, let cool, peel, and chop finely along with the parsley leaves.","Dice the celery into pieces matching the size of the potato cubes.","Combine all ingredients in a bowl, season with salt and black and red pepper, drizzle with olive oil, and mix thoroughly."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_kartofli","page":"Książka kucharska/Sałatka z kartofli"},{"id":"oc-plwb-19489","title":"Sex on the Beach cocktail","cuisine":"American","category":"Drink","ingredients":["25 ml vodka (plain)","25 ml peach schnapps","40 ml orange juice","40 ml cranberry juice","1 slice lemon slice (or lime or orange, for garnish)","to taste ice cubes"],"steps":["Pour the vodka, peach schnapps, orange juice, and cranberry juice into a cocktail shaker and shake vigorously.","Put a few ice cubes in a tall glass.","Pour the cocktail from the shaker into the glass and garnish with a slice of lemon, lime, or orange."],"time":5,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sex_on_the_Beach","page":"Książka kucharska/Sex on the Beach"},{"id":"oc-plwb-61734","title":"Cullen skink","cuisine":"British","category":"Soup","ingredients":["1 onion (medium, finely chopped)","400 g potatoes (about 2, peeled and cut into 1 cm cubes)","1 tbsp unsalted butter","250 g smoked cod (or other smoked white fish)","250 ml whole milk","0.5 bunch parsley leaves (chopped (or chives))"],"steps":["Melt the unsalted butter in a heavy saucepan over medium heat, add the finely chopped onion, and cook for 5–8 minutes until translucent.","Add the diced potatoes and 300 ml of water, bring to a boil, and simmer gently for 10–15 minutes.","In a separate pan, submerge the smoked cod in whole milk and poach gently for about 5 minutes until tender.","Lift the fish out with a slotted spoon, reserving the milk, let cool slightly, flake into large pieces, and discard any pin bones.","Pour the reserved poaching milk into the potato pot, add the flaked fish, simmer for another 5 minutes, and garnish with chopped parsley leaves before serving."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cullen_skink","page":"Książka kucharska/Cullen skink"},{"id":"oc-plws-38759","title":"English Mustard","cuisine":"British","category":"Sauce","ingredients":["200 g English mustard powder (orig. half a funt)","3 tbsp olive oil","250 ml tarragon vinegar (orig. 1 Polish kwaterka of strong tarragon vinegar, boiling)","2 tbsp sugar (or more to taste (in the second method, half a funt = 200 g of fine sugar))","1 tsp caramel (burnt sugar for colour)"],"steps":["Pour 200 g of English mustard powder into an earthenware bowl, drizzle with 3 tbsp of olive oil, and leave to stand for 12 hours.","Bring 250 ml (1 Polish kwaterka) of strong tarragon vinegar to a boil and pour the boiling liquid into the mustard a little at a time, beating constantly with a wooden pestle or spoon until completely cool.","Add 2 tbsp of sugar (or more to taste) and 1 tsp of burnt caramel for colour, and mix thoroughly (in the second method, mix the mustard directly with boiling tarragon vinegar, 200 g of fine sugar, and 1 tbsp of caramel, bring briefly to a boil over the heat, and stir until cool)."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Musztarda_angielska","page":"365 obiadów za 5 złotych/Musztarda angielska"},{"id":"oc-plws-499650","title":"German-style scrambled eggs","cuisine":"British","category":"Breakfast","ingredients":["6 eggs","1 tbsp plain wheat flour (heaping spoonful)","1 tsp salt","250 ml milk (or water)","to taste smoked fatback (generous amount for frying (or fatty pork belly))"],"steps":["Crack the eggs into a bowl, add the wheat flour and salt, and beat very thoroughly.","Pour in the milk and whisk until completely smooth and lump-free.","Render a generous portion of sliced smoked fatback in a skillet for about 4 minutes.","Pour the egg mixture into the hot fat and cook over low heat for about 4 minutes, lifting the set curds from the bottom with a spoon, then serve immediately."],"time":13,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_niemiecka_(Eierkuchen)","page":"100 potraw z jaj/Jajecznica niemiecka (Eierkuchen)"},{"id":"oc-plwb-61681","title":"Herbstmilch (Bavarian sour milk soup)","cuisine":"British","category":"Soup","ingredients":["400 g buttermilk","100 g sour cream","20 g 30% whipping cream","25 g plain flour","1 tsp salt"],"steps":["Whisk the buttermilk, sour cream, 30% whipping cream, plain flour, and salt together in a pot until completely smooth.","Cook over moderate heat at about 100 °C for 8 minutes, stirring constantly until the soup thickens slightly."],"time":13,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Herbstmilch","page":"Książka kucharska/Herbstmilch"},{"id":"oc-plwb-12755","title":"Kartoffelsalat (German potato salad)","cuisine":"British","category":"Salad","ingredients":["550 g potatoes (500–600 g)","2.5 fermented pickles (2–3, or vinegar pickles)","1.5 onions (1–2 pieces)","3.5 slice smoked meat (3–4 slices)","to taste mayonnaise (approx. 1–2 tablespoons)","to taste salt","to taste black pepper","to taste parsley leaves"],"steps":["Boil the potatoes in their skins, allow them to cool, peel, and cut into cubes.","Finely chop the fermented pickles and onions, then combine them with the potatoes.","Dice the smoked meat, render in a skillet until crisp, and add to the salad.","Season the salad with salt and pepper, mix with mayonnaise, and garnish with chopped parsley leaves."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kartoffelsalat","page":"Książka kucharska/Kartoffelsalat"},{"id":"oc-plwb-62051","title":"Pichelsteiner (Bavarian three-meat stew)","cuisine":"British","category":"Main","ingredients":["500 g mixed meat (beef, pork, lamb)","1 tsp butter (or margarine)","2 onions","4 carrots","1 celeriac","1 savoy cabbage","6 potatoes (medium)","625 ml meat broth","1 bay leaf","to taste salt","to taste black pepper"],"steps":["Cut the meat into small cubes and season with salt and pepper.","Peel the onions, slice them, and lightly brown in melted butter in a large saucepan, then add the meat and sauté over low heat for about 5 minutes.","Peel the carrots and potatoes and slice them, and dice the cleaned celeriac and savoy cabbage.","Layer the prepared vegetables over the browned meat without stirring, add the bay leaf, and pour over the meat broth.","Simmer covered over low heat for about 90 minutes, topping up with broth if needed."],"time":120,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pichelsteiner","page":"Książka kucharska/Pichelsteiner"},{"id":"oc-plwb-21650","title":"Traditional English tea","cuisine":"British","category":"Drink","ingredients":["3 tsp loose-leaf black tea (1 teaspoon per person plus 1 for the pot)","500 ml water","50 ml milk (or lemon slices)","2 slice lemon (alternatively instead of milk)","to taste sugar (white or brown)"],"steps":["Boil the water and warm the teapot by rinsing it with boiling water.","Put the loose tea into the teapot, pour in boiling water, cover, and steep for 3–5 minutes.","Pour a little milk into the bottom of the teacups or add a slice of lemon to each.","Pour the hot tea through a strainer into the cups and serve with sugar to taste."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Herbata_po_angielsku","page":"Książka kucharska/Herbata po angielsku"},{"id":"oc-plwb-61670","title":"Zupa naleśnikowa (German pancake soup / Flädlesuppe)","cuisine":"British","category":"Soup","ingredients":["500 g chicken breast","1.5 l water (6 glasses, cold)","1 tbsp olive oil","1 onion","3 carrots","3 potatoes","1 parsley root","0.25 celeriac (piece)","4 crepes (fried, sliced into strips)"],"steps":["Peel the onion, carrots, potatoes, parsley root, and celeriac, cut into pieces, drizzle with olive oil, and roast in the oven until tender.","Fry thin crepes, roll them up, and cut into narrow strips.","Cover the chicken breasts with 1.5 l (6 glasses) of cold water, simmer the poultry broth, then add the roasted vegetables and cook briefly together.","Distribute the crepe strips into bowls and ladle the hot soup over them."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_nale%C5%9Bnikowa","page":"Książka kucharska/Zupa naleśnikowa"},{"id":"oc-plwb-61669","title":"Zupa rumfordzka (Rumford's soup)","cuisine":"British","category":"Soup","ingredients":["300 g yellow split peas (halves)","4 potatoes (medium)","2 carrots","1 parsley root","0.25 celeriac (piece (about 1/4 of a small root))","50 g rice (or pearl barley)","2 bay leaves (leaves)","3 allspice (berries)","0.5 tsp ground caraway","to taste salt","to taste black pepper (freshly ground)","1.5 l water (for the vegetable broth (plus water to soak the peas and cook the rice))","to taste fatback (diced, to render cracklings)"],"steps":["Thoroughly rinse the peas that have been soaked in cold water for several hours or overnight.","Peel the potatoes, carrots, parsley root, and celeriac, and cook until tender in 1.5 l of lightly salted water with the bay leaves and allspice.","Drain the cooked vegetables, add the split peas and ground caraway to the strained broth, and cook for about 45 minutes until soft.","Blend the cooked peas together with the broth into a smooth purée and season with salt and freshly ground pepper.","Cook the rice or pearl barley separately until tender with the grains remaining separate, then dice the fatback and render it in a frying pan until the cracklings are crisp.","Add the diced cooked potatoes, cooked rice or groats, and fatback cracklings along with rendered fat to the pea soup, and simmer together for several more minutes; serve with croutons and chopped dill."],"time":600,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_rumfordzka","page":"Książka kucharska/Zupa rumfordzka"},{"id":"oc-plwb-19648","title":"Chinese toffee apples (Basi pingguo)","cuisine":"Chinese","category":"Dessert","ingredients":["4 apples (firm)","500 ml vegetable oil (for deep-frying and for caramel)","200 g sugar","65 g plain flour","40 g potato starch","1 egg","100 ml water (for thin batter and for chilling caramel)","1 pinch salt"],"steps":["Peel and core the apples, then cut the fruit into large chunks.","Whisk the plain flour, potato starch, egg, a pinch of salt, and water into a smooth, thin batter.","Dip the apple chunks into the batter, deep-fry in hot oil until golden, and drain on paper towels.","Heat one tablespoon of oil in a separate pan, add the sugar, and cook until a light caramel forms.","Add the fried apples to the caramel, toss quickly to coat, transfer to a greased plate, and dip briefly into cold water before eating so that the caramel hardens."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jab%C5%82ka_w_karmelu","page":"Książka kucharska/Jabłka w karmelu"},{"id":"oc-plwb-14007","title":"Chinese-style chicken fillets with mushrooms and walnuts","cuisine":"Chinese","category":"Main","ingredients":["4 single chicken breast fillet","6 tbsp soy sauce","4 celery stalks","200 g white button mushrooms","4 tbsp cooking oil","4 clove garlic","2 onion","4 tbsp walnuts (chopped)","to taste sesame seeds","to taste dried basil"],"steps":["Slice the chicken fillets crosswise into thin strips and marinate in the soy sauce.","Thinly slice the mushrooms and celery stalks, and finely chop the onion and garlic.","Cook the onion and garlic in part of the heated oil until translucent.","Add the chicken strips drained from the marinade, fry for 2 minutes, and transfer the meat to a plate.","In the remaining oil, sauté the mushrooms and celery, pour in the leftover soy sauce marinade, and simmer for a few minutes.","Return the meat to the pan, add the dried basil and chopped walnuts, stir well, and garnish with sesame seeds before serving."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Filety_z_kurczaka_po_chi%C5%84sku","page":"Książka kucharska/Filety z kurczaka po chińsku"},{"id":"oc-plwb-11552","title":"Chiński bulion (Chinese chicken and pork broth)","cuisine":"Chinese","category":"Soup","ingredients":["1 kg chicken backs","450 g pork bones","3 spring onions (or shallots, sliced)","1 tsp fresh ginger (minced or grated)","1 clove garlic","1 tsp salt","2.25 l water"],"steps":["Place the chicken backs, pork bones, sliced spring onions, minced fresh ginger, garlic, and salt in a large pot and add the water.","Stir the ingredients, bring the broth to a boil, and simmer gently over low heat for 15 minutes.","Skim off excess fat from the surface, strain the broth through a sieve, and let cool."],"time":25,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chi%C5%84ski_bulion","page":"Książka kucharska/Chiński bulion"},{"id":"oc-plwb-2683","title":"Cola chicken","cuisine":"Chinese","category":"Main","ingredients":["4 chicken breast","3.5 onion (3–4 onions)","2 tsp curry powder","2 clove garlic","500 ml ketchup","500 ml cola","60 ml soy sauce","to taste vegetable oil (for frying)"],"steps":["Chop the onion, crush the garlic, and cut the chicken breasts into small dice.","Heat a small amount of oil in a wok or deep frying pan.","Add the curry powder and garlic and fry for 1 minute, stirring constantly.","Add the chopped onion and fry for another 2 minutes, stirring.","Add the diced chicken and fry for 5–6 minutes, stirring regularly.","Pour in the ketchup, cola, and soy sauce, stir, and bring the sauce to a boil.","Reduce the heat and braise for 30 minutes, stirring occasionally, until the sauce thickens."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_w_Coli","page":"Książka kucharska/Kurczak w Coli"},{"id":"oc-plwb-18627","title":"Cucumber and daikon radish salad (Sałatka z ogórków i białej rzodkwi)","cuisine":"Chinese","category":"Salad","ingredients":["1 cucumber (medium)","1.5 daikon radish","3 tbsp light soy sauce","2 tbsp rice vinegar","1 pinch chili powder (generous pinch)","1 tsp sugar"],"steps":["Peel the daikon radish and cucumber, then grate coarsely or julienne into long, thin matchsticks.","Whisk the light soy sauce with the rice vinegar, sugar, and a generous pinch of chili powder until the sugar dissolves.","Mound the shredded vegetables into a high pyramid on a plate and drizzle with the prepared dressing."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_og%C3%B3rk%C3%B3w_i_bia%C5%82ej_rzodkwi","page":"Książka kucharska/Sałatka z ogórków i białej rzodkwi"},{"id":"oc-plwb-6574","title":"Kaczka po pekińsku (Peking duck)","cuisine":"Chinese","category":"Main","ingredients":["2 kg whole duck (1 whole duck)","2.5 tbsp honey (2–3 tablespoons)","to taste sesame oil","2 bunch scallions","to taste hoisin sauce","to taste plum sauce","to taste sweet soy sauce","1 cucumber","200 g wheat flour","100 ml water"],"steps":["Bring water to a boil in a large pot, place the cleaned duck in the boiling water and cook for 5 minutes, then remove and dry thoroughly.","Brush the duck with honey mixed with sweet soy sauce and hang in a dry, cool place for 60 minutes.","Brush the duck with honey again and leave in a cool place for another 420 minutes to dry.","Place the duck in an ovenproof dish in an oven preheated to 200 °C and roast for 45 minutes on each side.","In a bowl, mix the wheat flour with 100 ml of water, knead into a smooth dough, and set aside for 10 minutes.","Roll out the dough into thin pancakes, brush them with sesame oil, and fry in a pan.","Remove the roasted duck from the oven, separate the crispy skin, and slice the meat.","Cut the cucumber and scallions into thin strips. Arrange pieces of duck on the pancakes, drizzle the duck with hoisin and plum sauces, add the vegetables, and roll up."],"time":160,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kaczka_po_peki%C5%84sku","page":"Książka kucharska/Kaczka po pekińsku"},{"id":"oc-plwb-11550","title":"Kung Pao chicken","cuisine":"Chinese","category":"Main","ingredients":["450 g chicken meat (diced)","1 egg white","1 tsp salt","2 tbsp cornflour (cornstarch)","5 tbsp vegetable oil","1 clove garlic (crushed)","1 tbsp soy sauce","1 tbsp rice wine or dry sherry","1 tsp sugar","1 tsp wine vinegar or rice vinegar","1 tsp sesame oil","2 tbsp water","250 g rice (200–300 g)"],"steps":["Place the diced chicken into a bowl, add the egg white, salt, and 1 tablespoon of cornstarch, mix thoroughly, and set aside for 30 minutes.","Cook the rice according to the package instructions.","Heat 4 tablespoons of vegetable oil in a wok, stir-fry the chicken until lightly browned, and transfer to a plate.","Pour the remaining 1 tablespoon of vegetable oil into the wok, add the crushed garlic, and fry for 2 minutes.","Return the chicken to the wok and stir in the soy sauce, rice wine or sherry, sugar, vinegar, and sesame oil.","Mix the remaining 1 tablespoon of cornstarch with 2 tablespoons of water, pour into the wok, and simmer gently until the sauce thickens and becomes clear. Serve with rice."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kung_Pao_z_kurczakiem","page":"Książka kucharska/Kung Pao z kurczakiem"},{"id":"oc-plwb-18065","title":"Ryż po chińsku (Chinese stir-fried beef and rice)","cuisine":"Chinese","category":"Main","ingredients":["250 g rice","4 spring onions (with greens)","250 g beef","1 egg white","0.5 tsp sugar","2 tbsp soy sauce (half for marinade, half for stir-frying)","5 tbsp sunflower oil","2 tbsp dry white wine (half for marinade, half for stir-frying)","4 clove garlic","1 tsp potato starch","1 fresh ginger (piece of root)","3 napa cabbage leaves","375 ml water (for cooking the rice)","to taste salt","to taste black pepper"],"steps":["Rinse the rice, bring it to a boil in salted water, then wrap the pot in a blanket and leave for 240 minutes to swell.","Slice the beef into thin strips, and finely chop the spring onions with their greens, the garlic, and peeled ginger.","Mix the sugar, half the soy sauce, half the white wine, the potato starch, and the egg white, coat the beef strips in the marinade, and set aside for 15 minutes.","Heat the oil in a pan or wok, toss in the garlic and spring onions, add the marinated beef along with the marinade and chopped ginger, and stir-fry over high heat for 2 minutes, stirring continuously.","Pour in the remaining white wine and the rest of the soy sauce, and stir briefly.","Combine the stir-fried beef with the cooked rice, season with salt and pepper, and top with the shredded napa cabbage leaves."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ry%C5%BC_po_chi%C5%84sku","page":"Książka kucharska/Ryż po chińsku"},{"id":"oc-plwb-15014","title":"Sałatka po chińsku (Chinese pickled cabbage salad)","cuisine":"Chinese","category":"Salad","ingredients":["1 kg white cabbage","1 hot red chilli","1 fresh ginger (small piece)","3 tbsp white wine vinegar","2 tbsp light brown sugar","1 tbsp sesame oil","100 g peanuts","100 g almonds","1 tbsp salt"],"steps":["Rinse and dry the white cabbage, cut it into pieces about 6 cm long, transfer to a pot, sprinkle with the salt and brown sugar, and let stand for 120 minutes.","Halve the hot chilli, remove the seeds, and slice into thin strips; peel and finely chop the ginger.","Blanch the almonds in boiling water and slip off their skins.","Gently squeeze the excess liquid from the cabbage, combine with the sesame oil, wine vinegar, ginger, and chilli, and chill for another 120 minutes.","Before serving, scatter the peanuts and blanched almonds over the salad."],"time":260,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_po_chi%C5%84sku","page":"Książka kucharska/Sałatka po chińsku"},{"id":"oc-plwb-18788","title":"Sałatka z makaronu ryżowego i papryki (rice noodle and bell pepper salad)","cuisine":"Chinese","category":"Salad","ingredients":["1 red bell pepper","1 green bell pepper","1 orange bell pepper","0.5 rice noodles (half a packet)","7 wood ear mushrooms (dried)","1 cucumber","60 ml soy sauce","to taste hot paprika","to taste salt"],"steps":["Pour hot water over the dried wood ear mushrooms and rice noodles in separate bowls and soak for about 15 minutes, then drain.","Wash all three bell peppers, discard the seeds, and julienne the flesh along with the cucumber and soaked wood ear mushrooms into very thin strips.","Toss the rice noodles with the chopped vegetables and mushrooms, pour over the soy sauce, and season to taste with hot paprika and salt."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_makaronu_ry%C5%BCowego_i_papryki","page":"Książka kucharska/Sałatka z makaronu ryżowego i papryki"},{"id":"oc-plwb-18805","title":"Sweet and sour pork ribs (Żeberka na słodko-kwaśno)","cuisine":"Chinese","category":"Main","ingredients":["1 kg pork ribs","250 ml plum wine (1/4 liter)","1 tsp Chinese five-spice powder","2 tbsp soybean oil","0.5 bunch chives (half a bunch)","120 g plum sauce","3 tbsp Worcestershire sauce","to taste salt (for seasoning meat)"],"steps":["Mix the plum wine with Chinese spice, pour the marinade over the ribs, and set aside in a cool place for 60 minutes.","Remove the meat from the marinade (reserving the liquid) and pat dry with paper towels.","Fry the ribs in heated soybean oil and season lightly with salt.","Towards the end of frying, pour in the reserved marinade, add plum sauce and Worcestershire sauce, and cook while stirring until the sauce thickens.","Sprinkle the dish with chopped chives before serving."],"time":100,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%BBeberka_na_s%C5%82odko-kwa%C5%9Bno","page":"Książka kucharska/Żeberka na słodko-kwaśno"},{"id":"oc-plwb-12746","title":"Ajnlauf (Silesian drop noodle chicken soup)","cuisine":"European","category":"Soup","ingredients":["2.5 l chicken broth","2 eggs","4.5 tbsp wheat flour (4–5 tbsp)","1 tbsp water or milk","to taste parsley leaves"],"steps":["Whisk the eggs with a fork, gradually adding the wheat flour and one tablespoon of water or milk, and beat for about 4 minutes until a smooth batter with the consistency of thick sour cream forms.","Pour the batter in a thin stream into the boiling chicken broth while gently stirring the soup.","Cook briefly until the drop noodles float to the surface, then serve the soup sprinkled with chopped parsley leaves."],"time":15,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ajnlauf","page":"Książka kucharska/Ajnlauf"},{"id":"oc-plwb-24919","title":"Ajntopf (vegetable one-pot soup)","cuisine":"European","category":"Soup","ingredients":["2.5 l water or vegetable broth (or bone broth)","300 g potatoes","2 kohlrabi (large)","1 carrot (large)","1 celeriac (small)","1 parsley root with leaves","1 leek","0.25 savoy cabbage (quarter head)","1 tsp dill (chopped)","100 g margarine or butter","2 tsp wheat flour (level)","190 ml sour cream (3/4 glass)","to taste salt","to taste Maggi liquid seasoning","1 pinch caraway seeds","1 pinch basil"],"steps":["Wash and peel the potatoes, kohlrabi, carrot, celeriac, and parsley root, chop along with the leek and savoy cabbage, and cook in water or broth until tender.","Heat the margarine or butter in a small saucepan, sprinkle in the wheat flour, and cook to make a pale roux.","Stir the roux into the simmering soup, bring to a boil, and season with salt, Maggi seasoning, caraway, and basil.","Temper the sour cream with a few tablespoons of hot soup, pour into the pot, bring briefly to a boil, and serve sprinkled with chopped parsley leaves and dill."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ajntopf","page":"Książka kucharska/Ajntopf"},{"id":"oc-plws-553352","title":"Allasch Caraway Liqueur","cuisine":"European","category":"Drink","ingredients":["1250 g sugar (orig. one and a quarter kilograms)","1500 ml water (cold; orig. one and a half liters)","250 ml rectified spirit (for dissolving the essential oil; orig. a quarter of a liter)","40 caraway essential oil, drops (40 individual drops; orig. forty drops; the glossary does not specify drop volume, so the count was kept)","2000 ml rectified spirit (added after dissolving the essential oil; orig. two liters)"],"steps":["Dissolve 1250 g of sugar in 1500 ml of cold water.","Bring the solution to a boil and skim off the foam.","Mix 40 drops of caraway essential oil with 250 ml of rectified spirit.","Add the remaining 2000 ml of rectified spirit to the mixture.","Remove the syrup from the heat.","Pour the spirit mixture into the hot syrup, stirring constantly.","Transfer the liqueur to another vessel and leave to cool.","Pour it into bottles.","Seal the bottles tightly.","Leave the liqueur in a dry, cool place for three months."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Allasz","page":"Doświadczone sekreta smażenia konfitur i soków/Allasz"},{"id":"oc-plws-39070","title":"Almond cream blancmange (Blanc-manger)","cuisine":"European","category":"Dessert","ingredients":["4 calf's feet (orig. 4–5 pieces, or gelatine equivalent)","3 l water (orig. 3 kwarty, for simmering the stock)","2 egg whites (orig. a couple of whites, for clarifying the stock)","200 g sweet almonds (orig. 1/2 funt)","12 bitter almonds","2 tbsp milk (for pounding the almonds)","1 l sweet cream (orig. 1 kwarta)","200 g sugar (orig. 1/2 funt)","1 tsp olive oil (for greasing the mould)"],"steps":["Remove the large bones from the thoroughly washed calf's feet, cover with 3 l of water, and simmer over low heat for about 3–4 hours, skimming off foam and fat, until the meat falls apart.","Strain the stock through a sieve, leave overnight (about 8 hours) to set, scrape the fat and sediment off the bottom, then melt the jelly with beaten egg whites, clarify over low heat, strain through a cloth, and reduce to 250 ml; let cool.","Blanch the sweet and bitter almonds in boiling water, remove the skins, and pound in a mortar to a smooth paste, moistening with milk.","Bring 1 l of sweet cream to a boil, pour the boiling cream over the pounded almonds in a bowl, and let steep covered for 60 minutes.","Squeeze the almond mixture very firmly through a tightly woven cloth (you can pound the pulp again and rinse it with some of the same cream until the pulp is dry).","Stir 200 g of sugar and 250 ml of cold clarified calf's-foot stock into the strained almond cream and whisk briskly until the mixture begins to thicken.","Pour into a 1 l mould lightly brushed with olive oil and set in a cool place for about 4 hours (240 minutes) until completely firm."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Blanc-manger_czyli_galareta_migda%C5%82owa","page":"365 obiadów za 5 złotych/Blanc-manger czyli galareta migdałowa"},{"id":"oc-plws-1081085","title":"Almond Macaroons","cuisine":"European","category":"Cookie","ingredients":["400 g sweet almonds (originally 1 funt)","12.5 g bitter almonds (orig. 1 łut)","420 g sugar (originally a few sugar lumps for pounding the almonds, plus 1 funt (400 g) of fine sugar)","5 egg whites (whites, whipped to stiff peaks)","4 wafer sheets (sheets (or parchment paper))"],"steps":["Pound in a mortar or finely grind the sweet and bitter almonds with a few lumps of sugar.","Transfer the ground almonds to a saucepan, add 400 g of fine sugar, and heat over low heat, stirring constantly, until the paste dries slightly and no longer sticks to your fingers.","Remove the almond paste from the heat and let it cool completely.","Whip five egg whites to stiff peaks and fold thoroughly into the cold almond paste.","Spoon round portions of the batter onto wafer sheets or parchment paper and bake in a moderate oven (160 °C) for about 15–20 minutes until lightly golden."],"time":55,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Makaroniki","page":"Baby, placki i mazurki/Makaroniki"},{"id":"oc-plws-568715","title":"Almonds dried in sugar","cuisine":"European","category":"Snack","ingredients":["500 g almonds in their skins (unblanched, orig. half a kilogram)","500 g sugar (fine, orig. half a kilogram)","150 ml water (enough to cover the sugar)"],"steps":["Put the unpeeled almonds and the fine sugar into a wide heavy pan and pour in just enough water (about 150 ml) to cover the sugar.","Cook them together over moderate heat, stirring often, until the water has evaporated and the sugar begins to dry on the almonds.","Move the pan for a moment onto a lower heat and stir constantly with a wooden spoon until the sugar is completely dry. Then set it back on a higher heat and stir until the sugar coating browns lightly.","Tip the hot almonds onto a platter, separate them one by one with a fork so they do not stick, and put them for a few minutes into a gently heated oven (about 100 °C) to dry."],"time":35,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Migda%C5%82y_suszone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Migdały suszone w cukrze"},{"id":"oc-plws-1081071","title":"Andruty (Rolled wafer cookies)","cuisine":"European","category":"Cookie","ingredients":["2 eggs (whole)","250 ml plain wheat flour (orig. 1 historical Polish kwaterka of dry flour)","375 ml sweet cream (orig. one and a half historical Polish kwaterki of good-quality milk, or preferably cream)","75 g icing sugar (orig. 6 łuts of fine sugar)","to taste butter (for greasing the iron)"],"steps":["Beat the two whole eggs with the wheat flour, gradually adding the milk or sweet cream as for crêpe batter.","Add the fine sugar and whisk thoroughly into a smooth, thin batter.","Heat a flat chequered wafer iron (waffle iron for thin wafers) and brush it lightly with butter.","Pour a spoonful of batter onto the centre of the iron, close it, and bake for about 1–2 minutes until golden.","Lift the baked wafer from the iron and, while still hot, immediately roll it around a wooden dowel into a tube.","Set the finished wafers aside in an airy spot so they cool quickly and stay crisp."],"time":45,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Andruty","page":"Baby, placki i mazurki/Andruty"},{"id":"oc-plws-1081077","title":"Aniseed Sponge Drops","cuisine":"European","category":"Cookie","ingredients":["400 g icing sugar or caster sugar (originally 1 funt of fine sugar)","8 eggs (whole eggs)","300 g wheat flour (originally three-quarters of a funt of sifted flour, plus a little for dusting)","1 tsp aniseed (a small coffee spoonful)","1 tbsp butter (for greasing the molds or baking sheet)"],"steps":["Beat eight whole eggs with the fine sugar in a bowl for a full 30 minutes (or whip with a mixer into a thick, pale cream).","Add the sifted wheat flour and a teaspoon of aniseed and fold in gently but thoroughly.","Spoon the batter into small buttered molds, or spread it on a board and cut out rounds with a small floured glass, arranging them on a baking sheet.","Place immediately into a hot oven (190 °C) and bake for 20 minutes without brushing the tops of the cookies."],"time":60,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciastka_any%C5%BCowe","page":"Baby, placki i mazurki/Ciastka anyżowe"},{"id":"oc-plwb-19357","title":"Anyżki (Polish anise sponge cookies)","cuisine":"European","category":"Cookie","ingredients":["250 g sugar","300 g wheat flour (plus a little for dusting the baking sheet)","4 eggs","1 tsp aniseed"],"steps":["Grind the aniseeds in a spice grinder or crush them in a mortar.","Beat the eggs with sugar for 3–4 minutes until thick, pale, and ribbony.","Fold in the sifted wheat flour and ground aniseed gently with a spoon.","Drop small round portions of batter onto a flour-dusted baking sheet and bake in an oven preheated to 150–160 °C for about 15–20 minutes."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Any%C5%BCki","page":"Książka kucharska/Anyżki"},{"id":"oc-plws-568706","title":"Apple Balls Dried in Sugar","cuisine":"European","category":"Preserve","ingredients":["1 kg White Transparent apples (not overly ripe, for 500 g of scooped balls, with the peels and trimmings reserved for jelly)","1.2 kg sugar (1 kg for the syrup per 500 g of balls and approx. 200 g of finely crushed sugar for dusting)","500 ml water (2 glasses for the syrup, plus cold water for soaking and a small amount of water for boiling the peels)","2 lemon (juice of 1 lemon for the water and juice of a whole second lemon for the syrup)"],"steps":["Peel the slightly underripe White Transparent apples, scoop round balls from the flesh with a melon baller, and drop them immediately into cold water with the juice of 1 lemon.","Boil a syrup from 1 kg of sugar and 500 ml (2 glasses) of water until it begins to pearl, squeeze in the juice of the second lemon, and add the drained apple balls.","Simmer over low heat, removing with a slotted spoon onto platters those balls that have already become translucent, and adding the remaining raw ones.","Dust the cooled balls with finely crushed sugar, dry on sieves in a very lukewarm oven, and pack into jars or paper-lined boxes.","Boil the remaining apple peels and trimmings in a small amount of water, strain through linen cloth, combine with the syrup left over from cooking the balls, boil several times over low heat while skimming, and pour as a pale-yellow jelly into small jars."],"time":195,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82eczne_kuleczki_suszone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłeczne kuleczki suszone w cukrze"},{"id":"oc-plws-42447","title":"Apple fritters in egg batter (Jabłka smażone w cieście)","cuisine":"European","category":"Dessert","ingredients":["3 apples (preferably the Sztetyna variety)","to taste water (for briefly dipping the peeled apple slices)","3 egg yolks","1 tsp plain wheat flour","3 egg whites (beaten to stiff peaks)","to taste lard (or butter, generous amount for frying)","to taste sugar (generous amount for dusting)","to taste cinnamon (ground, for dusting with the sugar)"],"steps":["Peel and core the apples, slice them into rounds, and dip briefly in water so the batter clings well.","Beat the egg yolks with a teaspoon of wheat flour, whip the egg whites to stiff peaks, and gently fold the two together.","Heat a generous amount of lard or butter in a skillet or wide saucepan.","Dip the drained apple slices into the egg batter, lay them in the hot fat, and fry carefully on both sides for about 4–5 minutes until golden-orange.","Immediately after frying, shower the apple fritters thickly with cinnamon sugar and serve hot."],"time":30,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Jab%C5%82ka_sma%C5%BCone_w_cie%C5%9Bcie","page":"365 obiadów za 5 złotych/Jabłka smażone w cieście"},{"id":"oc-plws-474359","title":"Apple Marmalade with Orange Peel","cuisine":"European","category":"Preserve","ingredients":["1 kg tart apples (Weight after cooking down and sieving; use enough raw apples to yield 1 kg of puree; orig. a kilo of apple pulp.)","500 g sugar (orig. half a kilo of sugar)","to taste water (To cover the apples; volume not specified.)","2 boiled orange peel (Here the pcs unit means two handfuls, not two peels; orig. a couple of handfuls of boiled and very finely chopped orange peel; not converted to grams.)"],"steps":["Cut the tart apples into quarters.","Place the apples in an ovenproof dish and add water to cover.","Cover the dish tightly with a lid.","Leave the apples in an oven at about 150°C overnight.","Pass the apples through a sieve, separating the peels and cores.","Weigh out 1 kg of apple puree.","Mix the puree with 500 g of sugar.","Cook in a pot, stirring from the bottom with a wooden spoon so the mixture does not scorch.","Finely chop the boiled orange peel.","Toward the end of cooking, add two handfuls of the chopped peel.","Check on a saucer whether a sample of the marmalade sets slightly and does not spread.","Transfer the hot marmalade into warmed, dry ovenproof dishes.","Place the dishes overnight in an oven at about 150°C so the surface of the marmalade dries."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Konfitury%2C_kompoty_i_inne_konserwy_owocowe/Marmelada_jab%C5%82eczna","page":"Konfitury, kompoty i inne konserwy owocowe/Marmelada jabłeczna"},{"id":"oc-plws-42503","title":"Apple salad with anchovies, capers, and olives (sałatka z jabłek z sardelami)","cuisine":"European","category":"Salad","ingredients":["4 large tart apples (orig. 4 large Stettiner apples)","10 salted anchovies or anchovy fillets (orig. 10 anchovies)","1 tbsp capers","0.5 tbsp olives (finely chopped)","2 tbsp olive oil","1 tbsp wine vinegar","to taste black pepper"],"steps":["Peel the apples, coarsely grate (or dice very finely), and immediately splash with half the vinegar to prevent discolouring.","Rinse the anchovies to remove excess salt, bone, chop finely, and mix with the grated apples.","Add the capers, chopped olives, olive oil, and remaining vinegar to taste, season with pepper, toss thoroughly, and serve with boiled beef or roast meat."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sa%C5%82ata_z_jab%C5%82ek_z_serdelami","page":"365 obiadów za 5 złotych/Sałata z jabłek z serdelami"},{"id":"oc-plws-544358","title":"Apples Another Way","cuisine":"European","category":"Preserve","ingredients":["500 g White Transparent apples (half-unripe, peeled and cut into thin oblong strips)","2 lemon (juicy, squeezed juice with seeds removed)","750 g sugar (chopped into small pieces)","375 ml water (1.5 glasses for the syrup)","1 tbsp rum (for moistening the tissue paper rounds when sealing the jars)"],"steps":["Quickly peel the half-unripe White Transparent apples, cut into thin oblong strips, and immediately toss with the juice squeezed from 2 lemons.","Boil a thick, pearling syrup in a stoneware pan from 750 g of sugar and 375 ml (1.5 glasses) of water.","Add the prepared apples with the lemon juice to the boiling syrup and simmer for 15–20 minutes — first over higher and then over lower heat — until the preserve thickens.","Transfer the cooled preserve into jars, cover with a parchment round dipped in rum, tie tightly, and store in a cool, dry place."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82ka_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłka innym sposobem"},{"id":"oc-plws-568695","title":"Apples Dried in Sugar","cuisine":"European","category":"Preserve","ingredients":["500 g apples (large, of a choice variety, ripe, peeled whole and cored)","650 g sugar (500 g for the syrup and approx. 150 g of coarsely crushed and sifted sugar for dusting)","750 ml water (at least 3 glassfuls for the syrup, plus cold water for soaking)","1 lemon (juice for the cold water)","250 g thick apple preserve (for generously filling the cored apples)"],"steps":["Carefully peel the large apples, hollow out the cores without damaging the fruit, and submerge immediately in cold water acidulated with lemon juice.","Make a thin syrup from 500 g of sugar and 750 ml (3 glassfuls) of water, arrange the drained apples in a single layer, and cook gently until completely translucent without letting them fall apart.","Transfer the cooked apples to platters or a sieve and let cool completely, then fill each cavity generously with a heaped mound of thick apple preserve.","Coat each stuffed apple with sifted, coarsely crushed sugar and finish drying on sieves in a very low oven, taking care not to overdry the fruit."],"time":280,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82ka_suszone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłka suszone w cukrze"},{"id":"oc-plws-544357","title":"Apples in Syrup","cuisine":"European","category":"Preserve","ingredients":["500 g White Transparent apples (half-ripe, unpeeled, sliced into rounds with the cores removed)","1 kg sugar (for the syrup)","2 lemon (juice for the water, halved lemon for rubbing the slices, and thinly sliced peel for the jars)","0.5 vanilla bean (several small pieces for layering in the jars, optional)","500 ml water (for boiling the syrup, adding 2 tablespoons at a time during cooking, and cold water for soaking)"],"steps":["Slice the unpeeled White Transparent apples into rounds, remove the cores, and drop into cold water with lemon juice, then rub each slice on both sides with a lemon half after removing from the water.","Boil a moderately thin syrup from 1 kg of sugar and water, leave 1/3 of the syrup in the pan, and pour the rest into a separate vessel.","Arrange a single layer of apple slices on the boiling syrup and simmer over very low heat, skimming, until translucent.","Remove the cooked slices with a slotted spoon onto a platter, and before adding the next batch of apples, pour a little of the reserved cold syrup and 2 tablespoons of water into the pan so that the syrup stays pale.","Arrange the cooked apples in jars, layering with thinly sliced lemon peel or small pieces of vanilla bean, and pour the cooled pale syrup over them until the fruit is completely covered."],"time":75,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82ka","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłka"},{"id":"oc-plws-552227","title":"Apricot or peach ice","cuisine":"European","category":"Dessert","ingredients":["500 g ripe apricot or peach flesh (peeled and rubbed through a sieve, orig. half a kilogram)","500 g sugar (orig. half a kilogram)","1 l water (orig. 1 litre)","2 lemons (the squeezed juice)"],"steps":["Peel very ripe fresh apricots or peaches, remove the stones, and rub the flesh through a sieve, measuring out 500 g of purée.","Bring a syrup to the boil from 500 g of sugar, 1 litre of water and the juice of two lemons, and leave it to cool.","Mix the cooled syrup with the fruit purée, rub it through a sieve once more, pour it into an ice-cream maker, and freeze it (about 2–3 hours)."],"time":190,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_morelowe_lub_brzoskwiniowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody morelowe lub brzoskwiniowe"},{"id":"oc-plws-546286","title":"Apricots or peaches preserved in spirit","cuisine":"European","category":"Preserve","ingredients":["3 kg apricots or peaches (orig. 3 kilograms of ripe but not overripe apricots or peaches)","1.5 kg sugar (orig. a quarter kilogram (250 g) of sugar for every half kilogram (500 g) of fruit)","500 ml spirit (orig. half a litre of good spirit per 3 kg of fruit)","1.5 l water (500 ml (half a litre) of boiled water to dilute the spirit, and about 1 l of water for the thick syrup (plus boiling water for blanching the fruit))"],"steps":["Drop ripe but firm apricots or peaches into boiling water. When they float, lift them out and peel them, leaving the fruit whole with the stones (if the fruit is very ripe, do not blanch or peel it: wipe off the fuzz with a cloth and prick it with a wooden pin).","Cook a thick syrup from 1.5 kg of sugar and about 1 l of water (using 250 g of sugar for every 500 g of fruit). Put the fruit into the boiling syrup and bring it to the boil several times over low heat, taking care it does not burst.","Take the pan off the heat, lift the fruit out carefully, and pack it into a large jar.","Mix the still-hot syrup with 500 ml of good spirit diluted beforehand with 500 ml of boiled water, pour it over the fruit in the jar, and seal it."],"time":75,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_moreli_lub_brzoskwi%C5%84_w_spirytusie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z moreli lub brzoskwiń w spirytusie"},{"id":"oc-plws-548808","title":"Armenian-Style Currant Jelly","cuisine":"European","category":"Preserve","ingredients":["2 l red currants (cleaned and rinsed)","2 l white currants (cleaned and rinsed)","2 kg fine sugar (in a ratio of 1 kg per 1 l of strained juice)","50 ml water (for sprinkling the sugar, plus water for the water bath)"],"steps":["Place the cleaned and rinsed red and white currants into a covered stoneware vessel, set it in a pot of water, and heat over high heat without letting the berries themselves come to a boil.","As the currants release their juice, carefully ladle it off into a bowl, and transfer the remaining fruit into a linen bag hung to drain freely without squeezing.","Measure the collected juice and weigh out 1 kg of fine sugar for each 1 l of juice.","Place the sugar in a pan, sprinkle it with the water, and heat while stirring constantly with a spoon until half-dissolved and beginning to boil.","Pour the hot currant juice into the sugar, mix thoroughly, and boil together for 15 minutes, skimming off the foam carefully.","When a drop of jelly sets on a cold plate, pour it warm into well-heated jars and tie tightly once cooled."],"time":75,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_porzeczkowa_ormia%C5%84skim_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta porzeczkowa ormiańskim sposobem"},{"id":"oc-plws-543017","title":"Artichokes with butter and rusks","cuisine":"European","category":"Side","ingredients":["15 artichokes","15 ml crushed rusk (orig. 1 tbsp)","15 ml butter (orig. 1 tbsp)","to taste lemon (for the rinsing water)","to taste salt (for boiling)","to taste sugar (for boiling)","to taste water (for rinsing and boiling)"],"steps":["Trim the sharp tips from the artichoke leaves.","Remove the inedible fibrous chokes.","Rinse the artichokes in water with lemon.","Place the artichokes in a pot.","Cover them with boiling water seasoned with salt and sugar.","Boil for 30–40 minutes, until tender.","Drain the artichokes and arrange on a platter.","Brown the butter with the crushed rusk.","Pour the butter and rusk over the artichokes."],"time":null,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Karczochy","page":"Kucharka litewska (1913)/Karczochy"},{"id":"oc-plws-508367","title":"Asparagus omelette with cream","cuisine":"European","category":"Breakfast","ingredients":["6 eggs","250 g asparagus (young, diced)","to taste salt (for cooking the asparagus and seasoning the omelette)","1 tsp sugar","1 tsp plain wheat flour","75 ml sweet cream","1 pinch butter (a dab for the asparagus, plus extra for frying the omelette)"],"steps":["Cut the tips off the young asparagus, dice the stalks, and simmer the stalks in salted water with a teaspoon of sugar for about 8 minutes.","Add the asparagus tips to the nearly tender stalks, cook for another 3 minutes, and drain off the water.","Dust the cooked asparagus with a teaspoon of wheat flour, pour in the cream, boil briefly for 1 minute to form a thick sauce, and stir in a little fresh butter.","Beat the eggs with a pinch of salt, fry the omelette in butter for about 5 minutes, spoon the creamed asparagus into the center, fold in half, and serve immediately."],"time":28,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Omlet_ze_szparagami","page":"100 potraw z jaj/Omlet ze szparagami"},{"id":"oc-plws-450861","title":"Baba cytrynowa (lemon sponge cake)","cuisine":"European","category":"Cake","ingredients":["2 lemons","450 ml icing sugar (orig. 3 filiżanki (about 300 g))","15 egg yolks","150 ml wheat flour (orig. 1 filiżanka (about 90 g))","150 ml potato starch (orig. 1 filiżanka (about 100 g))","15 egg whites","15 g butter and breadcrumbs for the tin"],"steps":["Boil the whole lemons in water until soft, so a straw slips in easily. Halve them, discard the seeds, and grind the flesh and peel to an even mass.","Beat the lemon mass with the icing sugar in a bowl, and when it is smooth add 15 yolks one at a time, beating in one direction until pale and fluffy.","Whip the whites to a stiff foam.","Gently fold the whipped egg whites into the lemon-yolk mixture, alternating with the sifted wheat flour and potato starch and mixing lightly with a spoon.","Pour the batter into a buttered, crumbed baba tin and bake at 170 °C for about 60 minutes."],"time":120,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_cytrynowa","page":"Ciasta wielkanocne/Baba cytrynowa"},{"id":"oc-plws-450858","title":"Baba czekoladowa z mąką chlebową (chocolate cake with finely ground breadcrumbs)","cuisine":"European","category":"Cake","ingredients":["125 ml finely ground wholemeal breadcrumbs (orig. half a szklanka of dried grated wholemeal bread)","125 ml potato starch (orig. half a szklanka of potato starch)","14 egg yolks (orig. 12 to 15 yolks)","250 g sugar (orig. 20 deka for the yolks and 5 deka for the vanilla)","250 g chocolate (orig. 25 deka melted chocolate)","0.5 vanilla pod (pounded with sugar)","14 egg whites","15 g butter and breadcrumbs for the tin"],"steps":["Mix the sifted, finely ground dried wholemeal breadcrumbs with the potato starch.","Beat the yolks with 200 g of sugar until pale, add the chocolate melted over gentle heat and the vanilla pounded with the rest of the sugar, and beat to a smooth mass.","Whip the whites to a stiff foam.","Carefully fold the whipped egg whites into the chocolate mixture, gradually sprinkling in the mixture of finely ground breadcrumbs and potato starch a spoonful at a time.","Turn the batter into a buttered, crumbed tin and bake at 170 °C for about 60 minutes."],"time":105,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_czekoladowa","page":"Ciasta wielkanocne/Baba czekoladowa"},{"id":"oc-plws-450862","title":"Baba makowa (poppy-seed sponge cake)","cuisine":"European","category":"Cake","ingredients":["450 ml ground dry poppy seed (orig. 3 filiżanki (about 270 g))","15 egg yolks","250 g sugar (orig. 25 deka)","5 g bitter almonds (orig. a few bitter almonds, or a few drops of almond oil)","125 ml potato starch (orig. half a szklanka of potato starch (about 80 g))","15 egg whites","15 g butter and breadcrumbs for the tin"],"steps":["Grind the dry poppy seed twice in a mill to a very fine dust.","Beat 15 yolks with the sugar and the grated bitter almonds to a fluffy, pale mass.","Add the poppy seed to the beaten yolks and keep beating until the mass turns pale and clearly lightens.","Add the potato starch and stiffly beaten egg whites, folding gently with a spoon from the bottom upwards.","Turn it at once into a buttered, crumbed tin and bake at 175 °C for about 60 minutes."],"time":110,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_makowa","page":"Ciasta wielkanocne/Baba makowa"},{"id":"oc-plws-450854","title":"Baba migdałowa drożdżowa (almond yeast babka)","cuisine":"European","category":"Cake","ingredients":["100 g sweet almonds (orig. 10 deka)","10 g bitter almonds (orig. a dozen or so)","250 g wheat flour (orig. a quarter kilo)","250 ml milk (orig. 1 szklanka)","40 g fresh yeast (orig. 4 deka)","3 egg yolks","100 g sugar (orig. 10 deka)","100 g melted butter (orig. 10 deka)","2 g salt (orig. a little salt)","3 egg whites","15 g butter and breadcrumbs for the tin"],"steps":["Blanch the almonds, peel them, dry them, and grind them.","Make a starter from the flour, a glass of warm milk and the yeast, and leave it in a warm place to rise.","Add the yolks beaten with the sugar until fluffy, the melted butter and the salt, and beat the dough with a wooden spoon for 30 minutes. It is too soft to knead by hand.","Add the ground almonds and mix thoroughly, then gently fold in 3 egg whites beaten to stiff peaks.","Turn it at once into a buttered, crumbed tin, leave it covered in the warm to rise, and bake at 175 °C for about 45 minutes."],"time":135,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_migda%C5%82owa%2C_dro%C5%BCd%C5%BCowa","page":"Ciasta wielkanocne/Baba migdałowa, drożdżowa"},{"id":"oc-plws-450849","title":"Baba parzona (scalded yeast babka)","cuisine":"European","category":"Cake","ingredients":["1 l wheat flour (orig. 1 szklanka for scalding, plus 3 szklanki for the dough (ok. 600 g))","300 ml milk (orig. 1 szklanka of boiling milk for scalding, plus about 50 ml of warm milk for the yeast)","40 g fresh yeast (orig. 4 deka)","8 egg yolks","215 g sugar (orig. 20 deka for the dough i 1 łyżka for the vanilla)","250 ml clarified butter (orig. 1 szklanka (ok. 220 g))","5 g salt (orig. 1 łyżeczka od kawy)","5 g bitter almonds (orig. a few grated bitter almonds)","1 vanilla pod (orig. a two-cal piece)","5 g lemon zest (from 1/2 lemon)","15 g butter and breadcrumbs for the tin"],"steps":["Scald a glass of sifted flour with a glass of boiling milk and beat hard so no lumps form, then cool it slightly.","When the dough has cooled, add the yeast dissolved in warm milk and the well-beaten yolks, mix, and leave the starter in a warm place to rise.","When the starter has cracked, add 3 glasses of flour and beat for 40 minutes, then add the sugar, salt, grated bitter almonds, vanilla, grated lemon zest and the clarified butter.","Knead until the dough comes cleanly away from your hands, then fill a buttered, crumbed tin to 1/3 of its height.","Leave it in the warm until it has risen almost to the rim, then bake at 180 °C for about 60 minutes."],"time":180,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_parzona","page":"Ciasta wielkanocne/Baba parzona"},{"id":"oc-plws-450856","title":"Baba petynetowa (light yeast babka beaten over hot water)","cuisine":"European","category":"Cake","ingredients":["215 g sugar (orig. 20 deka for the yolks and 1 łyżka for the vanilla)","20 egg yolks","60 g fresh yeast (orig. 6 deka)","125 ml cream (orig. half a szklanka)","250 g wheat flour (orig. a quarter kilo)","2 g salt (orig. a pinch)","1 vanilla pod (orig. a two-cal piece)","100 g clarified butter (orig. 10 deka)","15 g butter and breadcrumbs for the tin"],"steps":["Place a bowl in a pan of hot water to form a water bath, then beat 20 yolks with the sugar in the bowl until very pale and thick.","Add the yeast dissolved in warm cream, the sifted flour, the salt and the pounded vanilla, and beat the dough steadily for 30 minutes.","Pour in the clarified butter and beat for another 30 minutes, then leave the bowl in a warm place to rise.","Turn the dough into a warmed, buttered, crumbed tin, filling it to 1/3 of its height, and leave it to rise almost to the rim.","Bake in an oven heated to 175 °C for about 45 minutes. Take it out very carefully, or this light babka will fall."],"time":195,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_petynetowa","page":"Ciasta wielkanocne/Baba petynetowa"},{"id":"oc-plws-450851","title":"Baba rodzynkowa (raisin yeast babka)","cuisine":"European","category":"Cake","ingredients":["500 g wheat flour (orig. a quarter kilo for the starter, plus another a quarter kilo for the dough)","250 ml milk or cream (orig. 1 szklanka)","60 g fresh yeast (orig. 6 deka)","6 egg yolks","150 g sugar (orig. 15 deka)","10 g bitter almonds (orig. ten)","25 g sweet almonds (orig. twenty)","80 g large seedless raisins (orig. 8 deka)","80 g sultanas (orig. 8 deka)","80 g currants (orig. 8 deka)","5 g salt (orig. 1 łyżeczka od kawy)","100 g melted butter (orig. 10 deka)","15 g butter and breadcrumbs for the tin"],"steps":["Make a starter from 250 g of flour, a glass of warm milk and the yeast, and leave it in the warm to rise.","Beat the yolks with the sugar until pale. Blanch the almonds, peel them and grind them. Rinse the raisins, dry them, and dust them with flour so they do not clump.","When the starter is moving, add the remaining 250 g of flour, the beaten yolks and the salt, and knead for about 30 minutes.","Pour in the melted warm butter, add the raisins and the ground almonds, mix well, and turn the dough into a buttered, crumbed tin, filling it to 1/3 of its height.","When the dough has risen almost to the top, bake in an oven heated to 180 °C for about 60 minutes."],"time":180,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_rodzynkowa","page":"Ciasta wielkanocne/Baba rodzynkowa"},{"id":"oc-plws-450848","title":"Baba szafranowa (saffron yeast babka)","cuisine":"European","category":"Cake","ingredients":["500 g wheat flour (orig. half a kilo)","30 g fresh yeast (orig. 3 deka)","250 ml milk (orig. 1 szklanka)","5 egg yolks","150 g sugar (orig. 15 deka)","1 g saffron (orig. a pinch soaked in food-grade rectified spirit)","50 ml food-grade rectified spirit (orig. 1 kieliszek)","5 g salt (orig. 1 łyżeczka od kawy)","100 g melted butter (orig. 10 deka)","50 g sultanas (orig. a handful of light raisins)","50 g candied orange peel (orig. a handful of candied peel)","15 g butter and breadcrumbs for the tin"],"steps":["The day before, pour a small glass of food-grade rectified spirit over a pinch of saffron and leave it to release its golden colour.","Make a starter from 125 g of flour, a glass of warm milk and the yeast, and leave it in a warm place to rise.","Beat the yolks with the sugar until pale. Once the starter begins to rise, add the remaining flour, beaten yolks, salt and saffron infusion.","Knead until the dough comes cleanly away from your hands, then pour in the melted warm butter, add the raisins and the candied orange peel, and knead smooth.","Turn it into a buttered, crumbed tin, leave it to rise to 2 fingers below the rim, and bake at 180 °C for about 50 minutes."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_szafranowa","page":"Ciasta wielkanocne/Baba szafranowa"},{"id":"oc-plws-450852","title":"Baba tarta (large yeast babka)","cuisine":"European","category":"Cake","ingredients":["1.6 kg wheat flour (orig. 80 deka for the starter, plus 80 deka for the dough)","120 g fresh yeast (orig. 12 deka)","250 ml milk (orig. 1 szklanka)","15 egg yolks","400 g sugar (orig. 40 deka)","250 ml clarified butter (orig. 1 szklanka of warm clarified butter)","5 g salt (orig. 1 łyżeczka od kawy)","15 egg whites","20 g butter and breadcrumbs for the tins (for two large tins)"],"steps":["Make a starter from 800 g of flour, a glass of warm milk and the yeast, and leave it in a warm place to rise.","Beat 15 yolks with 400 g of sugar until pale.","When the starter is moving, add the beaten yolks, the warm clarified butter, the salt and the remaining 800 g of flour, and knead the dough well.","At the end, fold in the stiff foam of 15 whites.","Divide the dough between two large buttered, crumbed tins and bake at 175 °C for about 60 minutes."],"time":210,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_tarta","page":"Ciasta wielkanocne/Baba tarta"},{"id":"oc-plws-450839","title":"Baba łatwa a smaczna (easy yeast babka)","cuisine":"European","category":"Cake","ingredients":["500 g wheat flour (orig. a quarter kilo for the starter, plus 250 g for the dough)","40 g fresh yeast (orig. 4 deka)","250 ml cream or milk (orig. 1 szklanka)","8 egg yolks","130 g sugar (orig. 10 deka do yolks i 2 łyżki for the vanilla)","1 vanilla pod (orig. a two-cal piece)","80 g clarified butter (orig. 8 deka)","5 g salt (orig. 1 łyżeczka od kawy)","50 ml milk (more if needed to knead the dough)","15 g butter and breadcrumbs for the tin"],"steps":["Stir the yeast into a glass of warm milk or cream, mix with 250 g of sifted warm flour, and leave the starter in a warm place to rise.","Beat 8 yolks with 100 g of sugar until pale, pound the vanilla with 2 spoonfuls of sugar, and clarify the butter and cool it slightly.","When the starter is moving, add the rest of the flour, the yolks, the vanilla, the salt and a little milk if needed. Knead until the dough comes cleanly away from your hands.","Pour in the melted butter (saving a little for the tin) and knead until the fat is fully absorbed.","Turn the dough into a buttered, crumbed tin, filling it to 1/3 of its height. Leave it covered in the warm until doubled, and bake in an oven heated to 180 °C for about 50 minutes."],"time":170,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Baba_%C5%82atwa_a_smaczna","page":"Ciasta wielkanocne/Baba łatwa a smaczna"},{"id":"oc-plwb-5766","title":"Babka herbaciana (Polish black tea bundt cake)","cuisine":"European","category":"Cake","ingredients":["250 g wheat flour","100 g sugar","80 g margarine (plus a little for the tin)","2 egg yolks","250 ml strong black tea (brewed infusion)","80 g raisins","1 tsp baking soda","1 tsp baking powder","0.5 tsp grated lemon zest","1 pinch salt","1 tbsp breadcrumbs (for dusting the tin)","to taste icing (optional, for drizzling)"],"steps":["Sort and rinse the raisins, place them in a pot with the strong tea, bring to a boil, then set aside to cool and drain.","Preheat the oven to 175 °C, grease a bundt cake tin with margarine, and dust with breadcrumbs.","Cream the margarine with the sugar until light and fluffy, then beat in the egg yolks, lemon zest, and salt.","Whisk the wheat flour with the baking soda and baking powder, add to the batter, and gradually pour in the cooled tea while mixing continuously.","Finally, fold in the raisins gently.","Transfer the batter to the prepared tin, bake for 50–60 minutes at 170–180 °C, and optionally drizzle with icing once cooled."],"time":80,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Babka_herbaciana","page":"Książka kucharska/Babka herbaciana"},{"id":"oc-plws-1080974","title":"Babka z mąki kartoflanej (Potato starch sponge bundt cake)","cuisine":"European","category":"Cake","ingredients":["15 egg yolks","300 g sugar (orig. three quarters of a historical Polish funt)","100 g sweet almonds (orig. a quarter of a historical Polish funt of almonds, including 4 bitter almonds)","4 bitter almonds (orig. 4 almonds)","1 lemon (juice squeezed from a whole lemon)","200 g potato starch (orig. half a historical Polish funt of potato starch)","15 egg whites (beaten to stiff peaks)","to taste clarified butter (for greasing the tin)","to taste breadcrumbs (for coating the tin)"],"steps":["Blanch the sweet and bitter almonds in boiling water, slip off their skins, and pound finely in a mortar or grind.","Beat the egg yolks with the sugar until fluffy and almost white, then stir in the ground almonds and the juice of the whole lemon.","Beat the remaining egg whites to very stiff peaks.","Add the potato starch and stiff egg whites alternately by the spoonful to the yolk mixture, folding gently so that the final addition is potato starch.","Grease a babka tin with clarified butter, coat with breadcrumbs, quickly pour in the batter, and place immediately in an oven well heated to 180 °C.","Bake for about 40–45 minutes until a skewer comes out clean."],"time":85,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Babka_z_m%C4%85ki_kartoflanej","page":"Baby, placki i mazurki/Babka z mąki kartoflanej"},{"id":"oc-plwb-18860","title":"Babka z rodzynkami (Polish yeast babka with raisins)","cuisine":"European","category":"Cake","ingredients":["500 g wheat flour","10 egg yolks","100 g sugar","100 g clarified butter (clarified, plus a little for the tin)","250 ml milk","30 g almonds (chopped)","0.5 vanilla bean","120 g sultana raisins","120 g standard raisins","60 g fresh yeast","0.5 tsp salt"],"steps":["Mix the fresh yeast with warm milk, a little sugar, and flour, allow to froth, then combine with the remaining wheat flour, egg yolks beaten with sugar, salt, and seeds scraped from the vanilla bean half.","Pour in the clarified butter and knead the yeast dough until smooth and elastic.","Scald both types of raisins with boiling water, pat dry, add to the dough along with the chopped almonds, and knead for another 30 minutes, then cover with a towel and let rise.","Transfer the risen dough into a buttered babka tin and let rise in a warm spot until it fills the tin.","Bake the tin in an oven preheated to 180 °C for about 60 minutes."],"time":120,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Babka_z_rodzynkami","page":"Książka kucharska/Babka z rodzynkami"},{"id":"oc-plwb-18690","title":"Babka ziemniaczana z mięsem (Potato and minced beef casserole)","cuisine":"European","category":"Main","ingredients":["500 g potatoes","40 g butter","3 eggs (separated into yolks and whites)","250 g boneless beef","1 egg","20 g fat for frying and baking dish","2 onions","125 ml sour cream","to taste salt","to taste black pepper"],"steps":["Boil the potatoes in salted water, let cool, peel, and pass through a food mill or meat grinder.","Set aside 1 teaspoon of the ground potatoes for the filling, then beat the rest with the butter and 3 egg yolks until smooth, seasoning with salt.","Beat the 3 egg whites until stiff peaks form and gently fold into the potato mixture.","Grind the beef, peel and chop the onions, fry in fat, then mix the meat with the onions, whole egg, sour cream, reserved teaspoon of potatoes, salt, and pepper.","Spread half of the potato mixture into a greased baking dish, top with the beef filling, cover with the remaining potato mixture, and bake for about 45 minutes at 180 °C."],"time":80,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Babka_ziemniaczana_z_mi%C4%99sem","page":"Książka kucharska/Babka ziemniaczana z mięsem"},{"id":"oc-plws-1080973","title":"Babki bez ambarasu (Easy thirty-yolk yeast babkas)","cuisine":"European","category":"Cake","ingredients":["2 l plain wheat flour (orig. half a garniec of well-sifted, warmed flour)","750 ml milk (orig. half a kwarta (500 ml) of unskimmed milk for the sponge, plus 1 kwaterka (250 ml) for the yeast)","75 g fresh yeast (orig. 6 łuts)","30 egg yolks (orig. half a kopa of well-beaten yolks)","375 ml clarified butter (orig. one and a half historical Polish kwaterki of lukewarm clarified butter (plus extra for greasing the tins))","400 g sugar (orig. 1 historical Polish funt)","to taste vanilla (or several pounded bitter almonds for aroma)"],"steps":["In a large bowl, combine half a kwarta (500 ml) of the milk with the yeast dissolved in a kwaterka (250 ml) of milk, gradually adding the sifted, warm flour.","Finally, pour in the egg yolks beaten until fluffy, mix very thoroughly with a spoon so no lumps of raw flour remain, dust the top with flour, and leave in a warm place (25–30 °C) to rise.","Once the dough has risen well, punch it down, pour in the lukewarm clarified butter, add the sugar and vanilla, and knead by hand for at least 1 hour until the dough pulls away from your hand.","Divide the dough among three buttered babka tins, filling them to 1/3 of their height, and set in a warm place until risen nearly to the rims.","Place the risen babkas in an oven preheated to 180 °C and bake for 45–60 minutes until a skewer comes out clean."],"time":300,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Babki_bez_ambarasu","page":"Baby, placki i mazurki/Babki bez ambarasu"},{"id":"oc-plws-1080971","title":"Baby parzone (Scalded-flour Easter yeast babkas)","cuisine":"European","category":"Cake","ingredients":["4 l plain wheat flour (orig. 1 garniec (1 kwarta = 1 l for scalding and 3 kwarty = 3 l for kneading))","1.5 l milk (orig. 5 kwaterki (1.25 l) of boiled milk for scalding the flour and 1 kwaterka (250 ml) for the yeast)","175 g fresh yeast (orig. 14 łuts)","60 egg yolks (orig. 1 kopa of egg yolks)","800 g icing sugar (orig. 2 historical Polish funts of grated sugar or fine powdered sugar (plus extra for dusting))","1 l clarified butter (orig. 1 historical Polish kwarta of lukewarm clarified butter (plus extra for greasing the tins))","1 tsp salt (orig. 1 small teaspoon)","1 vanilla pod (orig. 1 pod of pounded vanilla (or 2 łuts = 25 g of bitter almonds))","to taste breadcrumbs (for coating the tins)"],"steps":["From the measured garniec (4 l) of sifted, dry flour, take one kwarta (1 l) and scald it in a large bowl with the hot milk (1.25 l), pouring slowly and beating vigorously with a wooden spoon until the mixture cools to lukewarm.","Beat the egg yolks with the icing sugar in a bowl set over a warm water bath until pale, fluffy, and mousse-like.","Slowly pour the yeast dissolved in a kwaterka (250 ml) of milk and the yolks beaten with sugar into the lukewarm scalded flour, beat thoroughly into a smooth sponge, and leave in a warm place (about 30 °C) to rise.","Once the sponge has risen noticeably and cracked on top, pour in the lukewarm clarified butter, add a teaspoon of salt, and gradually work in the remaining 3 l of flour.","Knead the dough by hand for a full 1 hour, adding the pounded vanilla or bitter almonds toward the end, until the dough is smooth and pulls away from your hands.","Leave the dough in the bowl until doubled in bulk, then divide it among tall babka tins greased with clarified butter and coated with breadcrumbs (filling them to 1/3 of their height).","Leave in a warm, draught-free place until the dough fills the tins nearly to the rims, then place in an oven preheated to 180 °C for 45–60 minutes (test with a skewer).","Wait at most 5 minutes after removing from the oven, gently unmould the babkas, and brush thinly with fresh butter and dust with icing sugar to keep them fresh longer."],"time":480,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Baby_parzone","page":"Baby, placki i mazurki/Baby parzone"},{"id":"oc-plws-1080972","title":"Baby polskie (Traditional Polish yeast babkas)","cuisine":"European","category":"Cake","ingredients":["4 l plain wheat flour (orig. 1 kwarta (1 l) for scalding and 3 kwarty (3 l) for kneading)","1.5 l milk (orig. 3 kwaterki (750 ml) of boiled milk, half a kwarta (500 ml) of cold milk, and 1 kwaterka (250 ml) of lukewarm milk for the yeast)","175 g fresh yeast (orig. 14 łuts)","60 egg yolks (orig. 1 kopa of egg yolks)","500 ml clarified butter (orig. half a historical Polish kwarta)","600 g sugar (orig. 1.5 historical Polish funts)","1 pinch salt (orig. a little salt)","50 g almonds (orig. 4 łuts of grated almonds, or vanilla)","10 egg whites (orig. whites of 10 eggs beaten to stiff peaks)"],"steps":["Scald one kwarta (1 l) of the flour with three kwaterki (750 ml) of boiling milk, beating vigorously, and immediately pour in half a kwarta (500 ml) of cold milk.","Once the mixture has cooled to lukewarm, pour in the yeast dissolved in a kwaterka (250 ml) of lukewarm milk along with the egg yolks beaten over a water bath, mix well, rub through a coarse sieve, and set in a warm place to rise.","Once the sponge is bubbling, add the remaining 3 l of flour, pour in half a kwarta (500 ml) of clarified butter, add the sugar and salt, and knead by hand for a full 1 hour until the dough pulls away from your hands.","Toward the end of kneading, work in the grated almonds or vanilla.","Beat the ten egg whites to stiff peaks, fold them gently into the kneaded dough with a spoon, and immediately transfer the batter to prepared babka tins (filling them less than halfway).","Once the dough has risen nearly to the top of the tins, place immediately in an oven preheated to 185 °C and bake for 1 hour.","Unmould the baked babkas very carefully (historically they were laid on their sides on a soft pillow), taking care that they do not collapse."],"time":360,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Baby_polskie","page":"Baby, placki i mazurki/Baby polskie"},{"id":"oc-plws-1080970","title":"Baby zwyczajne (Everyday yeast babkas)","cuisine":"European","category":"Cake","ingredients":["4 l plain wheat flour (orig. 1 garniec of sifted, warmed flour)","1.25 l milk (orig. 1 kwarta (1 l) of lukewarm milk and 1 kwaterka (250 ml) for the yeast)","125 g fresh yeast (orig. 10 łuts)","35 egg yolks (orig. 30–40 yolks)","8 egg whites (orig. 8 egg whites beaten to stiff peaks (added when using 30 yolks))","600 g sugar (orig. 1.5 historical Polish funts)","400 g clarified butter (orig. 1 historical Polish funt (plus extra for greasing the tins))","25 g bitter almonds (orig. 2 łuts)","200 g raisins (orig. half a historical Polish funt of seedless raisins)","to taste breadcrumbs (for coating the tins)"],"steps":["Sift the flour into a large bowl and warm it slightly, make a well in the centre, pour in a kwarta (1 l) of lukewarm milk and the yeast dissolved in a kwaterka (250 ml) of milk, mix with part of the flour into a thin sponge, and leave to rise.","Once the sponge is actively bubbling, pour in the beaten egg yolks (along with the stiffly beaten whites of 8 eggs if using the smaller number of yolks), and add the sugar, clarified butter, pounded bitter almonds, and raisins.","Knead the dough by hand for a full 1 hour, then transfer immediately to tins greased with butter and coated with breadcrumbs.","Set the tins in a warm place until the dough rises to 3/4 of their height.","Place in an oven preheated to 180 °C and bake for 1 hour."],"time":300,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Baby_zwyczajne","page":"Baby, placki i mazurki/Baby zwyczajne"},{"id":"oc-plwb-23611","title":"Bajaderka (Polish chocolate rum cake slice)","cuisine":"European","category":"Cake","ingredients":["500 g wheat flour","250 g butter","200 g powdered sugar (or less)","2 eggs","1 tbsp baking powder","1 tbsp cocoa powder","250 ml milk (1 glass)","300 g jam (1 jar)","to taste dried fruit and nuts","50 ml rum (1 small glass)"],"steps":["Knead a shortcrust pastry from the wheat flour, butter, powdered sugar, eggs, and baking powder, divide into two halves, and bake into two cake layers at 180 °C.","Finely crumble one of the baked layers while it is still hot, then mix with the milk, cocoa, rum, dried fruit, and nuts until evenly combined.","Spread jam over the second baked layer, then spread the prepared dried fruit and nut mixture evenly over the top."],"time":70,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bajaderka","page":"Książka kucharska/Bajaderka"},{"id":"oc-plwb-16031","title":"Bajgus torte (Tort Bajgus)","cuisine":"European","category":"Cake","ingredients":["5 tbsp cake flour","5 eggs","7 tbsp sugar","80 g potato starch","3 tbsp cocoa powder","500 g whipping cream","5 apples","1.5 l apple juice","to taste vanilla sugar","1 tbsp gelatine","to taste fat (for greasing the cake tin)","to taste water (minimal amount to dissolve gelatine)"],"steps":["Separate the egg whites from the yolks, beat the whites until stiff while slowly adding the sugar, and add the yolks towards the end.","Combine the cake flour with the potato starch and cocoa powder, then gently fold into the egg mixture.","Pour the batter into a greased springform cake tin 20–22 cm in diameter, bake at 180 °C for about 30 minutes, and once cooled, slice the sponge horizontally into two layers.","Peel the apples, cut them into pieces, simmer in the apple juice for a few minutes, and drain thoroughly.","Whip 300 g of whipping cream with the vanilla sugar, pour in the gelatine dissolved in a minimal amount of water, and fold the cream into the drained apples.","Layer the sponge discs with the apple cream, and spread the remaining 200 g of whipped cream over the top and sides of the torte."],"time":85,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tort_Bajgus","page":"Książka kucharska/Tort Bajgus"},{"id":"oc-plwb-18772","title":"Baked apples with almonds","cuisine":"European","category":"Dessert","ingredients":["6 tart apples (large)","100 g sugar","100 g butter","3 tbsp flaked almonds","100 ml orange juice","1 tbsp ground cinnamon"],"steps":["Wash and peel the tart apples, cut them in half, and scoop out the cores.","Grease a baking dish with some of the butter, arrange the apple halves hollow-side up, and drizzle with orange juice.","Place a knob of the remaining butter into each hollow, and sprinkle the tops with sugar, ground cinnamon, and flaked almonds.","Bake in an oven preheated to 180 °C for about 30 minutes."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Deser_jab%C5%82kowy_z_migda%C5%82ami","page":"Książka kucharska/Deser jabłkowy z migdałami"},{"id":"oc-plws-543009","title":"Baked cabbage with béchamel and mutton breast","cuisine":"European","category":"Main","ingredients":["2 white cabbage (heads; orig. 2–3 heads; lower bound used)","15 ml wheat flour (orig. 1 tbsp)","3 egg yolks (orig. 3–4; lower bound used)","15 ml butter (for the sauce; orig. 1 tbsp)","250 ml milk (orig. 1 szklanka)","1 mutton breast, boiled and fried in butter and rusks (prepared ingredient; rusk coating)","to taste salt (for the water)","to taste water (for boiling the cabbage)"],"steps":["Cut the cabbage into pieces the size of łazanki pasta squares.","Boil the cabbage in salted water until tender.","Drain the cabbage.","Melt the butter.","Fry the flour in the butter.","Thin the roux with the milk.","Stir in the egg yolks.","Heat the sauce, stirring.","Transfer the cabbage to an ovenproof dish.","Pour the sauce over the cabbage.","Bake the cabbage in the oven until the top is browned.","Serve with the mutton breast boiled and fried in butter and rusks."],"time":null,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kapusta_z_biszamelem%2C_ok%C5%82adana_mostkiem_ciel%C4%99cym_lub_baranim","page":"Kucharka litewska (1913)/Kapusta z biszamelem, okładana mostkiem cielęcym lub baranim"},{"id":"oc-plws-502141","title":"Baked egg and ham timbales","cuisine":"European","category":"Main","ingredients":["to taste butter (for generously greasing six molds)","8 eggs","250 ml sweet cream (or whole milk)","to taste salt (a pinch)","100 g cooked ham (lean, finely diced (or cooked tongue))","to taste tomato sauce (pure, smooth, for pouring over before serving)"],"steps":["Generously butter six tall metal timbale molds or ramekins.","Beat the eggs thoroughly with the sweet cream and a pinch of salt, stir in the finely diced cooked ham, and divide the mixture among the molds.","Set the molds in a deep roasting pan filled with hot water reaching halfway up their sides.","Bake in the water bath in an oven preheated to 170 °C for about 25 minutes until the egg custard is completely set.","Carefully unmold the timbales onto a serving platter, pour hot pure tomato sauce over them, and serve immediately."],"time":40,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Timbalki_z_jaj_z_szynk%C4%85","page":"100 potraw z jaj/Timbalki z jaj z szynką"},{"id":"oc-plwb-18811","title":"Baked leeks with Emmental cheese (Pory zapiekane)","cuisine":"European","category":"Side","ingredients":["1 kg leeks (white parts only)","250 ml milk","100 g Emmental cheese (freshly grated)","2 tsp margarine","2 tbsp wheat flour","3 tbsp sour cream","1 tbsp parsley leaves (chopped)","0.5 tsp salt","1 pinch nutmeg","to taste white pepper","0.5 tsp dried thyme","0.5 tsp dried tarragon","2 l water (for boiling leeks)"],"steps":["Trim the white parts of the leeks, slice in half lengthwise, wash thoroughly, and boil for about 20 minutes in 2 litres of water with a pinch of nutmeg.","Grease a baking dish with half a teaspoon of margarine, lift out the cooked leeks, drain well, and arrange in the dish.","Make a blond roux with the remaining margarine and wheat flour, gradually whisk in the milk, and bring to a boil.","Stir the sour cream, salt, white pepper, thyme, and tarragon into the sauce and mix well.","Pour the sauce over the leeks, scatter with chopped parsley leaves and grated Emmental, and bake in an oven preheated to 200 °C until the cheese turns golden brown."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pory_zapiekane","page":"Książka kucharska/Pory zapiekane"},{"id":"oc-plws-502302","title":"Baked pasta and hard-boiled eggs in horseradish sauce","cuisine":"European","category":"Main","ingredients":["7 eggs (6 hard-boiled and 1 raw to enrich the sauce)","200 g pasta (broken into small pieces)","2 tbsp butter (1 tbsp for the pasta and 1 tbsp for the roux, plus extra for greasing the dish and drizzling on top)","1 horseradish (sizable root, finely grated)","to taste salt","1 tsp sugar","to taste vinegar","1 tbsp plain wheat flour","375 ml broth (or water)","125 ml sour cream","to taste breadcrumbs (for sprinkling on top)"],"steps":["Grate the horseradish root, salt it lightly, mix with a teaspoon of sugar, drizzle with vinegar, and let stand for 120 minutes to mellow its pungency.","Hard-boil six eggs for 10 minutes, peel, and slice into rounds or quarters.","Cook the broken pasta in salted boiling water for about 8 minutes, drain, and toss with a tablespoon of butter.","Butter an ovenproof serving dish and arrange alternating rows of cooked pasta and hard-boiled eggs.","Cook a tablespoon of butter with the wheat flour, stir in the broth, add the sour cream and marinated horseradish, and simmer together for 3 minutes. Let cool slightly, then temper with the beaten raw egg.","Pour the horseradish sauce over the pasta and eggs, sprinkle with breadcrumbs, drizzle with melted butter, and bake in an oven preheated to 190 °C for about 15 minutes until golden brown."],"time":175,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_z_makaronem_i_chrzanem","page":"100 potraw z jaj/Jaja z makaronem i chrzanem"},{"id":"oc-plws-44902","title":"Baked pike-perch au gratin with mushrooms (sandacz au gratin)","cuisine":"European","category":"Main","ingredients":["1.6 kg pike-perch (orig. 3–5 Polish funty (4 funty taken as 1.6 kg))","300 g button mushrooms (peeled and finely chopped)","250 g butter (orig. 1/2 Polish funt (200 g) for topping + 50 g for the dish and mushrooms)","250 ml dry white wine (orig. 1 szklanka)","100 g breadcrumbs","1 bunch fresh flat-leaf parsley (finely chopped)","to taste black pepper","to taste salt"],"steps":["Fillet the cleaned pike-perch lengthwise into two halves, remove the backbone, salt, and let rest in a cool place for 3.5 hours (210 minutes).","Peel and finely chop the mushrooms, scald briefly with boiling water, drain, salt, and braise in 25 g of butter over low heat for 15 minutes.","Grease a metal platter or gratin dish heavily with 25 g of butter, dust with some breadcrumbs, sprinkle with half the parsley, and spread half the braised mushrooms.","Lay both fish halves flat side by side, pour over the white wine, and top with the remaining mushrooms, remaining parsley, pepper, and a thick layer of breadcrumbs.","Dot the surface evenly with pieces of the remaining 200 g of butter.","Bake in a hot oven at 210 °C for about 45 minutes without basting, turning the dish occasionally, until a thick, golden, crisp crust forms on top."],"time":300,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sandacz_z_pieczarkami%2C_zwany_au_gratin","page":"365 obiadów za 5 złotych/Sandacz z pieczarkami, zwany au gratin"},{"id":"oc-plwb-14343","title":"Baked salmon (Pieczony łosoś)","cuisine":"European","category":"Main","ingredients":["500 g salmon fillet","to taste lemon juice","4 slice lemon (sliced)","2 tsp butter (chilled)","to taste fresh basil (chopped)","to taste fish seasoning blend"],"steps":["Wash and dry the salmon, rub with fish seasoning, sprinkle with chopped basil, drizzle with lemon juice, and refrigerate for about 3 hours.","Cut the chilled butter into small pieces and distribute them across the top of the fish.","Place the salmon in an oven roasting sleeve and bake for about 20 minutes in an oven preheated to 180 °C.","Garnish the baked salmon with lemon slices before serving."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pieczony_%C5%82oso%C5%9B","page":"Książka kucharska/Pieczony łosoś"},{"id":"oc-plws-499663","title":"Baked scrambled eggs with herring and onion","cuisine":"European","category":"Breakfast","ingredients":["10 eggs","2 salted herrings (well-soaked, skinned, and boned)","1 onion (large, grated)","2 tbsp butter (1 generous tbsp for frying the herring and onion, plus extra before baking)","10 tbsp sweet cream (or milk (1 tbsp per egg))","to taste salt (a tiny pinch)"],"steps":["Skin and bone the well-soaked herrings and chop them finely; grate the onion.","Sauté the chopped herring and grated onion in a tablespoon of butter in a deep ovenproof skillet for about 5 minutes, then add the second tablespoon of butter.","Beat the eggs with the cream and a tiny pinch of salt, and pour over the hot herring layer without stirring.","Transfer the skillet to an oven preheated to 190 °C for about 10 minutes until the eggs set, and serve immediately, scooping all the way from the bottom."],"time":30,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_ze_%C5%9Bledziem","page":"100 potraw z jaj/Jajecznica ze śledziem"},{"id":"oc-plws-44907","title":"Baked soufflé sponge omelette (Grzybek)","cuisine":"European","category":"Dessert","ingredients":["6 egg yolks","2 tbsp plain wheat flour","1 tbsp sugar (for the batter, plus extra for dusting)","6 egg whites (beaten to stiff peaks)","to taste clarified butter (generous amount for the hot skillet)","to taste fruit juice (optional, for pouring over before serving)"],"steps":["Beat the egg yolks with the wheat flour and a tablespoon of sugar in a bowl for about 15 minutes until pale and fluffy.","Whip the egg whites to stiff peaks and fold them very gently into the beaten yolks at the last moment.","Heat a heavy ovenproof skillet until very hot, pour in a generous layer of clarified butter, and spread the egg foam in the pan.","Transfer the skillet to an oven preheated to 180 °C and bake for 10 minutes.","Serve the hot omelette dusted with sugar or drizzled with fruit juice, or cut into 8 pieces and arrange around braised spinach or sorrel."],"time":30,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Grzybek","page":"365 obiadów za 5 złotych/Grzybek"},{"id":"oc-plwb-15693","title":"Baked spinach gratin (Szpinak zapiekany)","cuisine":"European","category":"Side","ingredients":["1 kg fresh spinach (leaves)","100 g lean cured pork loin (ogonówka)","2 eggs","2 clove garlic","1 onion","1 tbsp margarine","125 ml low-fat milk","1 tsp olive oil","1 tbsp soup seasoning","1 pinch nutmeg","to taste white pepper"],"steps":["Sort and rinse the spinach, blanch for 1 minute in salted boiling water, rinse with cold water, drain, and chop.","Peel and chop the onion and garlic, cook them gently in the margarine with the pan covered, then add the spinach and cook for about 2 minutes to evaporate excess moisture.","Chop the lean cured pork loin and mix with the spinach.","Whisk the eggs with milk and soup seasoning, and season with nutmeg and white pepper.","Grease a baking dish with olive oil, add the spinach, pour over the egg-milk mixture, and bake in an oven preheated to 200 °C for 10 minutes."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szpinak_zapiekany","page":"Książka kucharska/Szpinak zapiekany"},{"id":"oc-plws-579462","title":"Baked sturgeon with mustard sauce","cuisine":"European","category":"Main","ingredients":["1600 g sturgeon (orig. 4–5 funty; range 1600–2000 g, lower bound used; historical measure, converted approximately)","to taste salt","1 carrot","1 parsley root","2 onion (Divide between the vegetable bed and the egg mixture.)","2 eggs","to taste bread (For grating and sprinkling over the fish; the source does not specify the portion size.)","250 ml wine (orig. 1 kwaterka)","125 ml vinegar (orig. ½ kwaterka)","250 ml bouillon (orig. 1 szklanka)","2 tbsp mustard (orig. 2–3 tbsp; lower bound used.)","1.5 tbsp butter (orig. 1½ tbsp; for the baking sheet and for frying the onion.)"],"steps":["Cut the carrot, parsley root, and part of the onion into slices.","Grease a baking sheet with part of the butter.","Line the baking sheet with the sliced vegetables.","Clean the sturgeon.","Salt the fish and lay it on the vegetables.","Chop the remaining onion.","Sauté the chopped onion in the remaining butter.","Leave the sautéed onion to cool.","Mix the cooled onion with the beaten eggs.","Coat the fish with the onion and egg mixture.","Grate the bread and sprinkle it over the fish.","Bake the fish in an oven preheated to 220 °C until cooked through.","Remove the fish from the baking sheet.","Boil the baked vegetables with the wine, bouillon, vinegar, and mustard.","Pour the sauce over the fish."],"time":null,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Jesiotrzyna_pieczona_z_sosem_musztardowym","page":"Kucharka litewska (1913)/Jesiotrzyna pieczona z sosem musztardowym"},{"id":"oc-plwb-18592","title":"Baked turkey breast in orange-cheese sauce (Pierś indyka z serem)","cuisine":"European","category":"Main","ingredients":["6 slice turkey breast fillet (sliced, about 600 g)","50 g wheat flour (for coating the meat)","to taste salt","250 ml milk","100 g butter","50 g hard cheese (ser żółty) (grated)","3 tbsp sour cream 18% (thick)","3 tbsp wheat flour (for the roux)","to taste black pepper","to taste nutmeg","30 ml orange liqueur","30 ml orange juice"],"steps":["Dredge the turkey breast slices in 50 g of wheat flour mixed with salt, brown on both sides in a tablespoon of butter, and transfer to a baking dish.","Make a roux from the remaining butter and 3 tablespoons of wheat flour, whisk in the milk, and season with salt, pepper, and nutmeg.","Pour the orange liqueur and orange juice into the sauce, stir in most of the grated cheese, and heat, stirring until the cheese has melted.","Remove the sauce from the heat, stir in the sour cream, pour over the cutlets in the dish, scatter with the remaining cheese, and bake for 10 minutes in an oven preheated to 200 °C."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pier%C5%9B_indyka_z_serem","page":"Książka kucharska/Pierś indyka z serem"},{"id":"oc-plwb-18622","title":"Baked zucchini with tomatoes and oscypek cheese","cuisine":"European","category":"Side","ingredients":["1 zucchini","2 tomatoes","1 smoked oscypek sheep's milk cheese (medium-sized)","1 garlic (1 head)","1 bunch fresh basil","3 tbsp olive oil","to taste salt"],"steps":["Cut the oscypek into thin slices, and blanch the tomatoes in boiling water, peel and slice them.","Wash the zucchini, slice into rounds about 1 cm thick, sprinkle with salt, set aside for 15 minutes, and then fry briefly.","Crush the peeled garlic cloves through a press and stir with the olive oil and a pinch of salt.","Arrange the zucchini slices in a baking dish, brush with the garlic oil, and layer the chopped fresh basil, tomato slices, and oscypek on top.","Bake for about 10 minutes in an oven preheated to 180 °C."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cukinia_zapiekana_z_pomidorami_i_oscypkiem","page":"Książka kucharska/Cukinia zapiekana z pomidorami i oscypkiem"},{"id":"oc-plws-569051","title":"Baranina wędzona w żołądku baranim (cold-smoked mutton in sheep stomach, kindziuk barani)","cuisine":"European","category":"Preserve","ingredients":["5 kg mutton (rack, breast, neck, shoulder, or leg cuts trimmed of excess fat)","500 g salt (orig. half a kilo)","1 tsp potassium nitrate (optional, to preserve the pink colour of the meat)","1 tbsp black pepper (crushed)","6 bay leaf (crumbled)","1 tbsp coriander seeds (whole seeds)","2 tbsp marjoram (dried)","1 sheep stomach (thoroughly cleaned and salted, for stuffing the meat)"],"steps":["Trim the mutton of excess suet and rub thoroughly with the salt mixed with black pepper, crumbled bay leaf, coriander, marjoram, and optionally a teaspoon of potassium nitrate.","Pack the seasoned meat as tightly as possible into a thoroughly cleaned and salted sheep stomach, then sew the opening shut with strong thread.","Hang the stuffed stomach for a few days in a breezy place to dry well in the wind.","Cold-smoke in dense, cold smoke for about 10 days, then air out and store in a cool, dark larder; serve boiled and hot with horseradish, cold as a cured meat, or as a meat addition to borscht and potato soup."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/Baranina_w%C4%99dzona","page":"Domowe wędliny/Baranina wędzona"},{"id":"oc-plws-546607","title":"Barley Krupnik Soup with Root Vegetables","cuisine":"European","category":"Soup","ingredients":["150 g barley groats (orig. 15 dkg)","1 carrot (whole)","1 parsley root (whole)","1 onion (whole)","2.25 l water (orig. 2 and a quarter liters)","40 g pork fatback (orig. 4 dkg)","2 black peppercorns (whole peppercorns)","1 bay leaf (whole leaf)","to taste salt (to taste)","1 tbsp fresh dill or flat-leaf parsley (for serving)"],"steps":["Peel and finely dice the carrot, parsley root, and onion.","Put the barley groats and diced vegetables into a pot, pour in 2.25 liters of water, add the peppercorns, bay leaf, and salt, and simmer slowly until the broth reduces to about 1.5 liters.","Finely dice the pork fatback, render in a skillet until golden cracklings form, pour into the soup, and simmer together for another 15 minutes.","Ladle the piping hot barley soup into a tureen and sprinkle with chopped dill or parsley."],"time":75,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Krupnik_j%C4%99czmienny_z_jarzynami","page":"109 potraw/Krupnik jęczmienny z jarzynami"},{"id":"oc-plwb-6263","title":"Barszcz biały (Polish white borscht with wild mushrooms)","cuisine":"European","category":"Soup","ingredients":["70 g dried mushrooms (60–80 g)","750 ml water","750 ml white borscht sour starter","250 ml sour cream","1 onion","1 tbsp butter","to taste salt","to taste black pepper"],"steps":["Rinse the dried mushrooms, cover them with lukewarm water, and leave to soak overnight.","The next day, cook the mushrooms until tender in the same water, then strain the broth.","Peel and finely chop the onion, cook in butter until translucent, and add to the mushroom broth.","Pour the white borscht sour starter into the pot and bring to a boil.","Stir in the sour cream, season the soup to taste with salt and pepper, and heat briefly."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Barszcz_bia%C5%82y","page":"Książka kucharska/Barszcz biały"},{"id":"oc-plwb-3678","title":"Barszcz biskupi (Lviv-style beetroot borscht with egg)","cuisine":"European","category":"Soup","ingredients":["1 l meat broth","800 g young beetroots","4 eggs","to taste salt","to taste black pepper","to taste sugar","to taste lemon juice"],"steps":["Clean and rinse the young beetroots, bake them until tender in the oven (about 45–50 minutes at 190 °C), then peel and grate on a coarse grater.","Wash the eggs and crack them into a bowl with cool or lukewarm broth.","Place the bowl over a water bath and whisk the broth with the eggs for about 10 minutes, until the mixture thickens and becomes frothy.","Combine the whisked broth with the grated beetroots and season to taste with salt, pepper, sugar, and lemon juice."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Barszcz_biskupi","page":"Książka kucharska/Barszcz biskupi"},{"id":"oc-plwb-10355","title":"Barszcz czerwony (Clear Polish beetroot borscht)","cuisine":"European","category":"Soup","ingredients":["3 beetroots (medium, sliced into half-moons)","2 slice wholemeal bread (crumbled)","4 garlic (heads cut in half)","1 kg beetroots","5 g dried mushrooms","80 g onion","100 g apple","2 green leek leaves","1 fresh thyme (sprig)","1 bay leaf","2 parsley leaves (sprigs)","1 celery rib (rib)","2 clove garlic","10 g sugar","1 lemon juice (squeezed from 1 lemon)","to taste marjoram","to taste salt","to taste whole black peppercorns","to taste red wine vinegar","1 l water or beef broth"],"steps":["5 days before cooking the borscht, prepare the beet sour: place half-slices of 3 beetroots, crumbled wholemeal bread, and halved garlic heads into a jar, cover with lukewarm water, seal, and keep in a dark place at room temperature, then strain once fermented.","Rinse the dried mushrooms thoroughly, soak them in water, and simmer separately in the same liquid, then carefully pour off the clear mushroom broth from the sediment.","Slice the beetroots and onion, cut the unpeeled apple into wedges, and cut the peeled garlic cloves in half.","Cover the prepared vegetables with cold water or clear beef broth, add the cooked mushrooms along with their broth, leek leaves, thyme, bay leaf, parsley leaves, celery rib, marjoram, and whole peppercorns.","Pour in the beet sour starter, bring to a boil, and simmer gently for at most 10 minutes.","Toward the end of cooking, stir in the lemon juice and a splash of red wine vinegar, then leave the unstrained borscht in a cool place until the next day.","The next day, strain the borscht, heat thoroughly without letting it boil, and season to taste with salt, sugar, and pepper."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Barszcz_czerwony","page":"Książka kucharska/Barszcz czerwony"},{"id":"oc-plws-546598","title":"Barszcz czysty z ziemniakami (clear beetroot soup with potatoes)","cuisine":"European","category":"Soup","ingredients":["500 g red beetroots (orig. 50 dkg)","1 parsley root (whole root)","1 carrot (whole)","1 onion (whole)","2 l water (for the vegetable stock)","2 black peppercorns (whole peppercorns)","1 bay leaf (whole leaf)","to taste salt (to taste)","1 tbsp vinegar or citric acid (1 tablespoon of vinegar or 1 teaspoon of citric acid)","500 g potatoes (orig. 50 dkg, boiled or baked in their skins)"],"steps":["Wash the beetroots thoroughly and boil or bake them whole in their skins until tender.","Simmer the parsley root, carrot, and onion in 2 liters of water with the bay leaf, peppercorns, and salt to taste to make a vegetable stock.","Peel the cooked beetroots, cut them into thin julienne strips, add to the hot stock, and bring briefly to a single boil (if serving the borscht in cups, cut the beetroots into 4–6 pieces, simmer in the stock for 10 minutes, and strain).","Season the borscht with vinegar or citric acid so that it regains its deep ruby color.","Separately boil the potatoes in their skins and peel them just before serving (or bake them in the oven and serve in their skins) alongside the hot borscht."],"time":80,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Barszcz_czysty","page":"109 potraw/Barszcz czysty"},{"id":"oc-plwb-3682","title":"Barszcz dziedzica (Squire's Lviv-style beetroot borscht)","cuisine":"European","category":"Soup","ingredients":["1.5 l water","500 g young beetroots","100 g young carrots","100 g young parsley root (root)","100 g young celeriac (root)","250 g boneless beef","100 g butter","250 ml sour cream 18%","20 g wheat flour","to taste salt","to taste black pepper","to taste sugar","to taste marjoram","to taste garlic","to taste lemon juice"],"steps":["Wash, peel, and rinse the beetroots, carrots, parsley root, and celeriac, then grind them in a meat grinder together with the beef.","Melt the butter in a pot, add the minced vegetables with meat, and fry until lightly browned.","Pour in the water, add salt, and simmer over low heat until the ingredients are tender.","Mix the sour cream with the wheat flour and pour into the simmering borscht.","Season the soup with pepper, sugar, marjoram, pressed garlic, and lemon juice, then simmer for a few more minutes."],"time":70,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Barszcz_dziedzica","page":"Książka kucharska/Barszcz dziedzica"},{"id":"oc-plwb-19091","title":"Barszcz lwowski (Lviv-style borscht with beef and crab apples)","cuisine":"European","category":"Soup","ingredients":["500 g beef on the bone","2 l water","500 g small red beetroots","1 soup greens without cabbage (carrot, parsley root, celeriac, leek)","1 bay leaf","4 allspice berries (3–4 berries)","4 whole black peppercorns (3–4 berries)","1 onion","1 clove","2 lemons","200 g crab apple preserves","250 ml thick sour cream","1 tbsp wheat flour","1 tsp marjoram","to taste salt","to taste ground black pepper"],"steps":["Cover the beef and soup greens with water, add the onion studded with a clove, bay leaf, allspice, and peppercorns, simmer into a rich broth, and strain.","Scrub the beetroots, roast them in the oven until tender, peel, and either coarsely grate or slice into matchsticks.","Peel the lemons, slice them thinly, and discard any seeds.","Place the beetroots, lemon slices, and crab apple preserves into a saucepan, pour in the strained beef broth, and simmer for a few minutes.","Add the diced cooked beef and hand-crushed marjoram, then season to taste with salt and ground pepper.","Whisk the thick sour cream with the wheat flour, stir into the borscht, and heat gently while stirring constantly."],"time":120,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Barszcz_lwowski","page":"Książka kucharska/Barszcz lwowski"},{"id":"oc-plwb-18661","title":"Batter-fried eggs","cuisine":"European","category":"Snack","ingredients":["250 ml milk","100 g plain flour","3 egg whites","8 eggs","150 g frying fat","2 tbsp sugar","to taste salt","to taste black pepper"],"steps":["Whisk the milk with part of the plain flour and a pinch of salt to form a batter slightly thicker than pancake batter.","Beat the egg whites with the sugar until stiff peaks form, then gently fold into the batter.","Cook the whole eggs to medium-hard, peel them, cut them into halves, and season with salt and black pepper.","Dredge the egg halves in the remaining flour, dip them in the batter, and fry in hot fat until golden brown."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_w_cie%C5%9Bcie","page":"Książka kucharska/Jajka w cieście"},{"id":"oc-plwb-21804","title":"Battered fried zucchini","cuisine":"European","category":"Side","ingredients":["65 g wheat flour","125 ml water","3 eggs","0.25 tsp salt","to taste frying oil (for frying)","1 zucchini"],"steps":["Wash and slice the zucchini into rounds, season with salt, let stand for 30 minutes, and pat dry with paper towels.","Whisk the eggs into the water, then gradually beat in the flour and a pinch of salt to form a batter slightly thicker than pancake batter.","Heat the oil in a frying pan, dip the zucchini slices into the batter, and fry for 1.5–2 minutes on each side until crisp and golden."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cukinia_w_cie%C5%9Bcie","page":"Książka kucharska/Cukinia w cieście"},{"id":"oc-plws-1081032","title":"Baumkuchen (Sękacz spit cake)","cuisine":"European","category":"Cake","ingredients":["800 g butter (orig. 2 historical Polish funts of fresh butter (plus extra for greasing the paper))","40 egg yolks (orig. from 40 eggs)","800 g sugar (orig. 2 historical Polish funts of sugar (plus extra for the icing))","3 g cinnamon (orig. a quarter of a łut (about 3.1 g))","1 tsp lemon zest (grated)","40 egg whites (orig. from 40 eggs, beaten to stiff peaks (plus extra whites for the icing))","800 g potato starch (orig. 2 historical Polish funts of potato starch)","2 l whipping cream (orig. 2 historical Polish kwarty of rich cream)"],"steps":["Mount a conical wooden sękacz roller on a spit, wrap it in buttered paper, and bind closely with thin twine.","Cream the butter in a large mixing bowl with a wooden pestle until it has the consistency of cream. Continue beating for an hour, adding the egg yolks one at a time alternately with spoonfuls of sugar until all 40 yolks are incorporated.","Stir in the cinnamon and grated lemon zest.","Beat the egg whites to stiff peaks and fold them into the batter alternately by the spoonful with the potato starch, then finally pour in the 2 l of sweet whipping cream.","Heat the wooden roller rotating on the spit over the fire (or in a sękacz oven) with a drip pan set underneath to catch the excess batter.","Ladle a thin coat of batter over the rotating roller and brown it, then apply successive coats (6–8 layers in total), letting the dripping batter form the characteristic gnarls and spikes.","Once baked and slightly cooled, trim the sides evenly with a knife, untie the string, and slide the cake off the roller. When completely cold, coat unevenly with an egg-white and sugar glaze to resemble birch bark."],"time":150,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Baumkuchen","page":"Baby, placki i mazurki/Baumkuchen"},{"id":"oc-plwb-13991","title":"Benedictine soup (Zupa benedyktyńska)","cuisine":"European","category":"Soup","ingredients":["800 ml vegetable broth (instant)","200 g frozen porcini mushrooms","2 onions","4 eggs","250 g potatoes","100 g butter (half a block)","to taste all-purpose soup seasoning","to taste vinegar (for the egg poaching water)","1 l water (for poaching the eggs)"],"steps":["Thaw the porcini mushrooms, rinse them, and dice them.","Peel the onions, slice into feathers, and fry in butter until golden, then add the mushrooms and continue frying.","Transfer the mushrooms and onions to the broth, add the peeled and finely diced potatoes, season with soup seasoning, and cook until the potatoes are tender.","Crack the eggs into boiling water with vinegar in a separate pot so that they gently set.","Ladle the soup into bowls and serve each portion with a poached egg."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_benedykty%C5%84ska","page":"Książka kucharska/Zupa benedyktyńska"},{"id":"oc-plws-550044","title":"Benedictine-style herbal liqueur","cuisine":"European","category":"Drink","ingredients":["2.5 g saffron (orig. 1/4 dekagram of saffron)","250 ml rum (orig. a quarter litre of very good rum)","2 l spirit (orig. half a litre (500 ml) for soaking the roots, plus one and a half litres (1.5 l) poured through paper)","10 g angelica root (orig. 1 dekagram of fresh angelica, or dried angelica crushed in a mortar)","15 g juniper berries (orig. 1.5 dekagrams of lightly crushed juniper)","0.2 g yellow gentian root (orig. a scrap of Gentiana lutea root the size of half a pea)","1 vanilla pod (orig. 1 vanilla pod)","2 kg sugar (orig. 2 kilograms of crushed sugar)","1.25 l water (orig. one and a quarter litres of cold water)"],"steps":["Soak 2.5 g of saffron in 250 ml of very good rum for 24 hours.","In a separate vessel, combine 500 ml of the best spirit with 10 g of fresh angelica or crushed dried angelica, 15 g of lightly crushed juniper berries, a piece of yellow gentian root (Gentiana lutea) the size of half a pea, and 1 vanilla pod. Leave to soak in the shade for 3 days.","After 3 days, pour 1.5 l of plain spirit through filter paper into a three-litre demijohn, add the filtered spirit from the herbs and the rum with the saffron, and mix well.","Cook a syrup from 2 kg of crushed sugar and 1.25 l of cold water, skim it carefully, pour the boiling syrup into a bowl, and cool it completely.","Pour the aromatic spirit gradually into the cooled syrup, stirring constantly. Cover for a few hours, then bottle, cork, seal with wax, and keep in a cool place for 6 months before serving."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_benedykty%C5%84ski","page":"Doświadczone sekreta smażenia konfitur i soków/Likier benedyktyński"},{"id":"oc-plwb-9356","title":"Bigos (Polish hunter's stew)","cuisine":"European","category":"Main","ingredients":["2 kg fresh white cabbage","2 kg sauerkraut","750 g pork or game meat (0.5–1 kg)","500 g kiełbasa (0.25–1 kg, regular, hunter's, or Silesian)","350 g smoked bacon (0.25–0.5 kg)","5 wild forest mushrooms (fresh or dried)","250 g onion","to taste dried or smoked prunes","2 bay leaf","to taste whole black peppercorns","to taste salt"],"steps":["Finely shred the fresh cabbage and sauerkraut, place in a large pot, add the wild mushrooms, bay leaves, whole black peppercorns, and salt, and braise until tender for 2–3 hours.","Dice the smoked bacon and render the fat in a frying pan.","In the rendered bacon fat, fry the chopped onion, sliced meat, and kiełbasa until browned.","Drain any excess liquid from the stewed cabbage if needed, then add the fried meat, kiełbasa, bacon, and onion to the pot along with the pan drippings.","Add the dried prunes and simmer over low heat for several hours (ideally in stages over 2–3 days), until the bigos turns thick and dark brown."],"time":280,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bigos","page":"Książka kucharska/Bigos"},{"id":"oc-plwb-21694","title":"Bigos hultajski (Roguish Polish hunter's stew)","cuisine":"European","category":"Main","ingredients":["1.5 l sauerkraut","750 ml beef broth","1 tbsp wheat flour","1 onion","3.5 tbsp lard or fatback (3–4 tbsp)","850 g roasted or boiled beef (0.75–1 kg)","to taste kiełbasa (optional)"],"steps":["Melt 2.5 tablespoons of lard or diced fatback in the bottom of a pot, add the sauerkraut, pour in the beef broth, and braise for about 30 minutes.","Dice the roasted or boiled beef finely and transfer to the pot with the sauerkraut.","Peel and chop the onion, fry in the remaining tablespoon of lard with the wheat flour into a golden roux, and stir into the bigos.","Simmer everything together over low heat, stirring occasionally until the bigos darkens, and stir in sliced fried kiełbasa before serving."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bigos_hultajski","page":"Książka kucharska/Bigos hultajski"},{"id":"oc-plwb-15701","title":"Bigos z papryki (Polish bell pepper and sausage stew)","cuisine":"European","category":"Main","ingredients":["1 kg red bell pepper","100 g pearl beans","250 g kiełbasa","2 tbsp oil","2 onions","2.5 tbsp tomato purée (2–3 tbsp)","190 ml sour cream","1 tbsp wheat flour","to taste salt","to taste black pepper","to taste hot paprika powder","to taste marjoram"],"steps":["Sort and rinse the pearl beans, cover with cold water, bring to a boil, and let stand for 120 minutes, then drain, add fresh water, and simmer until tender.","Wash the red bell peppers, remove the seeds, dice the flesh, and braise in 1 tablespoon of oil.","Slice the kiełbasa into half-moons and fry in a skillet until browned.","Peel and finely chop the onions, dust with wheat flour, and lightly brown in the remaining oil and rendered sausage fat.","Combine the onions with the braised peppers, cooked beans, kiełbasa, tomato purée, and sour cream.","Simmer everything together briefly and season to taste with salt, pepper, hot paprika powder, and marjoram."],"time":90,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bigos_z_papryki","page":"Książka kucharska/Bigos z papryki"},{"id":"oc-plws-555162","title":"Bilberry Compote Preserve Another Way","cuisine":"European","category":"Preserve","ingredients":["2 l bilberries (large, ripe wild bilberries)","1.5 kg sugar (chopped into small pieces)","750 ml water (3 glasses of hot water for the syrup, plus boiling water for scalding the berries)"],"steps":["Carefully pick over 2 l of bilberries, cover with boiling water in a bowl, and drain immediately on a sieve.","Boil a syrup from 1.5 kg of sugar and 750 ml (3 glasses) of hot water, and skim it thoroughly.","Add the scalded bilberries to the boiling syrup, cook for a few minutes over high heat, and then simmer for 15 minutes over low heat.","Transfer the cooled preserve into jars, seal tightly, and pasteurize in a pot of water lined with hay or in the oven."],"time":60,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_bor%C3%B3wek_czyli_czernic_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z borówek czyli czernic innym sposobem"},{"id":"oc-plws-580458","title":"Bliny bardzo smaczne (yeast blini)","cuisine":"European","category":"Breakfast","ingredients":["400 g plain wheat flour (part for scalding, the rest for thickening the batter)","40 g fresh yeast","to taste milk (part boiling for scalding the flour, part lukewarm for mixing the batter to sour-cream consistency)","2 egg yolks","2 egg whites (beaten to stiff peaks)","to taste salt"],"steps":["Bring part of the milk to a boil, pour the boiling milk over half of the wheat flour, and beat thoroughly until the mixture cools.","Add the crumbled fresh yeast, the remaining dry wheat flour, and enough lukewarm milk to make a batter the consistency of sour cream.","Add the egg yolks beaten with a pinch of salt, mix well, and leave the batter in a warm place for about 45 minutes to rise.","Beat the egg whites to stiff peaks and gently fold them into the risen batter.","Fry the blini in a hot pan for 2–3 minutes per side until golden brown."],"time":80,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Bliny_bardzo_smaczne","page":"100 postnych i jarskich dań/Bliny bardzo smaczne"},{"id":"oc-plws-580456","title":"Bliny gryczane zaparzane (scalded buckwheat blini)","cuisine":"European","category":"Breakfast","ingredients":["400 g buckwheat flour","400 g plain wheat flour","40 g fresh yeast","500 ml water (lukewarm)","to taste salt","500 ml milk (boiling)","200 g butter (melted)","4 egg yolks"],"steps":["Dissolve the fresh yeast in the lukewarm water, mix with the wheat flour, cover, and leave in a warm place for about 45 minutes to rise.","Salt the risen sponge, add the buckwheat flour, and mix thoroughly.","Bring the milk to a boil, pour it boiling hot into the batter, and beat with a wooden spoon until completely smooth.","Once the batter has cooled slightly, add the melted butter and egg yolks and beat well again.","Leave the batter to rise a second time for about 30 minutes, then fry the blini in a hot pan for 2–3 minutes per side."],"time":115,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Bliny_gryczane%2C_zaparzane","page":"100 postnych i jarskich dań/Bliny gryczane, zaparzane"},{"id":"oc-plws-580459","title":"Bliny kartoflane (potato blini)","cuisine":"European","category":"Main","ingredients":["150 g wheat roll","125 ml milk (for dissolving the yeast and soaking the roll)","3 egg yolks","3 tbsp sour cream (thick)","to taste salt","500 g potatoes (raw, grated)","40 g fresh yeast","3 egg whites (beaten to stiff peaks)"],"steps":["Soak the wheat roll in a little milk, squeeze it out, and pass it through a mincer, then dissolve the fresh yeast in the remaining lukewarm milk.","Grate the raw potatoes on a fine grater and mix them with the minced roll, egg yolks, thick sour cream, salt, and dissolved yeast.","Leave the batter in a warm place for about 40 minutes to rise.","Just before frying, beat the egg whites to stiff peaks and fold them gently into the batter so that it does not deflate.","Fry the blini in a hot pan for about 3 minutes per side until golden."],"time":80,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Bliny_kartoflane","page":"100 postnych i jarskich dań/Bliny kartoflane"},{"id":"oc-plws-580457","title":"Bliny pszenne (wheat blini)","cuisine":"European","category":"Breakfast","ingredients":["600 g plain wheat flour (divided into two equal parts of 300 g each)","30 g fresh yeast","375 ml water (lukewarm)","to taste salt","3 egg yolks","100 g butter (melted)","375 ml milk (lukewarm)","3 egg whites (beaten to stiff peaks)"],"steps":["Dissolve the fresh yeast in the lukewarm water, mix with half of the wheat flour, season with salt, beat well, and leave in a warm place for about 40 minutes to rise.","Add the egg yolks, melted butter, remaining wheat flour, and lukewarm milk to the risen sponge, then beat thoroughly with a wooden spoon.","Leave the batter in a warm place for another 30 minutes to rise a second time.","Beat the egg whites to stiff peaks and fold them carefully into the risen batter.","Immediately fry the blini in a hot pan for 2–3 minutes per side until golden brown."],"time":100,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Bliny_pszenne","page":"100 postnych i jarskich dań/Bliny pszenne"},{"id":"oc-plwb-18664","title":"Boczek pieczony (Polish roasted pork belly with cracklings)","cuisine":"European","category":"Main","ingredients":["1 kg lean pork belly","3 onions","4 clove garlic","1 tbsp marjoram","to taste salt","to taste black pepper","to taste ground paprika"],"steps":["Peel the garlic and mash it into a paste with the salt.","Rinse the pork belly, cut off a slice about 1 cm thick, and rub the remaining roast with the garlic paste, then season with marjoram, pepper, and ground paprika.","Wrap the seasoned pork belly in cling film and chill in a cool place for about 2 hours.","Place the meat in a roasting pan, dice the reserved pork belly slice, render in a skillet until crisp cracklings form, and pour the hot fat over the roast.","Roast the pork belly for about 45 minutes in an oven preheated to 200 °C.","Peel the onions, cut them into wedges, add to the roasting pan, and roast everything for another 15 minutes, then serve the pork topped with onions and cracklings."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Boczek_pieczony","page":"Książka kucharska/Boczek pieczony"},{"id":"oc-plwb-16854","title":"Bogrács (Hungarian goulash soup with csipetke)","cuisine":"European","category":"Soup","ingredients":["500 g stewing beef","500 g potatoes","2 tomatoes","2 onions (large)","1 green bell pepper","1 red bell pepper","80 g lard","1 egg","1 clove garlic","240 g wheat flour","0.5 tsp caraway seeds","to taste salt","to taste paprika powder"],"steps":["Dice the beef, peel and chop the onions, dust with paprika powder, and fry together in melted lard until browned.","Add the finely minced garlic and caraway, pour in a splash of water, cover, and braise over low heat for about 90 minutes until the meat is tender.","Dice the potatoes and tomatoes, cut the green and red bell peppers into strips, add to the pot with water, season with salt, and simmer for about 15 minutes until the potatoes are tender.","Knead a stiff dough from the wheat flour, egg, and a pinch of salt, then pinch off small noodles (csipetke) directly into the simmering soup.","Cook for a few minutes more until the pinched noodles float to the surface."],"time":140,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bogracz","page":"Książka kucharska/Bogracz"},{"id":"oc-plws-546718","title":"Boiled Broad Beans with Pork Cracklings","cuisine":"European","category":"Side","ingredients":["200 g dried broad beans (orig. 1 cup of large or small broad beans)","750 ml water (cold, for soaking and boiling the broad beans)","40 g pork fatback (orig. 4 dkg, finely diced)","to taste salt (to taste)"],"steps":["Cover the dried broad beans with cold water and leave to soak overnight.","The next day, cook the broad beans in the same water with salt over low heat until the beans are very soft and begin to split open, then drain.","Fry the finely diced pork fatback in a skillet until golden cracklings form, pour over the hot broad beans, and serve immediately."],"time":545,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/B%C3%B3b_(bober)","page":"109 potraw/Bób (bober)"},{"id":"oc-plws-40164","title":"Boiled calf's head à la vinaigrette","cuisine":"European","category":"Main","ingredients":["1 calf's head with skin (scalded)","1 lemon (for juice to rub the head)","1 tbsp plain wheat flour","300 g soup vegetables (włoszczyzna) (sliced)","1 bay leaf","4 allspice berries and black peppercorns","4 l water (for boiling)","100 ml mild vinegar (for the cold sauce)","6 cornichons (pickled gherkins) (finely chopped)","0.5 bunch fresh dill or chives (chopped)","0.5 bunch fresh parsley (chopped)","to taste salt"],"steps":["Soak the scalded calf's head with its skin in cold water for 24 hours (1440 minutes), changing the water several times.","The next day, pat the head dry, rub it all over with lemon juice, and sew it tightly into a clean white linen cloth.","In a large pot, whisk the wheat flour with a little water, add the sliced soup vegetables, bay leaf, allspice, peppercorns, and salt, lay in the cloth-wrapped head, add enough water to cover completely, and simmer over low heat for 3.5 hours (210 minutes) until tender.","Meanwhile, prepare the cold vinaigrette: stir the finely chopped cornichons, dill (or chives), and parsley into the mild salted vinegar.","Lift the tender head from the stock, cut open the cloth, carefully remove the brains, slice the meat with the skin, garnish with the brains, and serve hot with the cold vinegar sauce."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/G%C5%82%C3%B3wka_ciel%C4%99ca_%C3%A1_la_vinegrette","page":"365 obiadów za 5 złotych/Główka cielęca á la vinegrette"},{"id":"oc-plws-42501","title":"Boiled carrot and onion salad (sałatka z marchwi)","cuisine":"European","category":"Salad","ingredients":["10 carrots (Name: medium-sized carrots; note: null)","1 onion (Name: small onion; note: null)","2 tbsp olive oil","1 tbsp vinegar","to taste black pepper","to taste salt"],"steps":["Boil the scraped carrots until completely tender in salted water for about 25 minutes and drain.","While still hot, slice the carrots as thinly as possible (halving thicker roots lengthwise first) directly into a salad bowl.","Finely chop raw onion directly over the steaming carrots so it softens in the residual heat.","Drizzle with olive oil and vinegar, season with pepper and a pinch of salt, toss, and let stand for 60 minutes before serving."],"time":100,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sa%C5%82ata_z_marchwi","page":"365 obiadów za 5 złotych/Sałata z marchwi"},{"id":"oc-plws-546729","title":"Boiled White Beans with Rendered Pork Fat","cuisine":"European","category":"Side","ingredients":["200 g dried white beans (orig. 1 cup)","750 ml water (cold, for soaking and boiling the beans)","to taste salt","30 g pork fatback (orig. 3 dkg, rendered)"],"steps":["Cover the beans with cold water and leave to soak overnight.","The next day, boil the beans until completely tender, seasoning with salt toward the end of cooking, and drain.","Toss the hot beans with the rendered pork fatback and serve immediately."],"time":560,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Fasola_z_sosami","page":"109 potraw/Fasola z sosami"},{"id":"oc-plws-39661","title":"Bone-in roast beef (rostbef z kością)","cuisine":"European","category":"Main","ingredients":["4 kg bone-in roast sirloin or rump of beef (orig. 10–15 Polish funty (10 funty taken as 4 kg))","1.2 kg potatoes (peeled, to roast alongside the meat)","1 horseradish root (grated or shaved into curls)","to taste salt"],"steps":["Rub a large cut of fatty bone-in sirloin or rump beef with salt and place it in a roasting pan.","Place the pan in a very hot oven (220 °C) and roast the beef for 120 minutes, turning frequently so it browns evenly without scorching.","During roasting, arrange peeled potatoes around the beef, and when the pan drippings reduce, prick the roast in several spots to release fresh juices.","Carve the roasted meat into thick slices, arrange on a platter surrounded by the roasted potatoes and shaved horseradish, and ladle over the pan juices."],"time":135,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Rost-Beef","page":"365 obiadów za 5 złotych/Rost-Beef"},{"id":"oc-plwb-26180","title":"Borsos tokány (Hungarian peppered beef stew)","cuisine":"European","category":"Main","ingredients":["100 g lard","150 g onions","1 kg boneless beef (neck, shoulder, or topside)","140 g fresh bell peppers","60 g tomatoes","to taste salt","1 clove garlic (small clove)","to taste black pepper (generously)","to taste water (small amount for braising)"],"steps":["Cut the beef into strips about 3 cm long, and finely chop the onion and fry in the pot in the hot lard until golden.","Salt the meat, add to the pot with the onion, and cook stirring until it releases its juices.","Add a small clove of garlic and a splash of water, cover, and braise over low heat in minimal liquid, adding water as needed to prevent scorching.","When the meat is half-tender, reduce the liquid until only the fat remains, then add the tomato pulp and diced bell pepper.","Continue simmering uncovered over low heat until the beef is fully tender, and season generously with freshly cracked black pepper towards the end."],"time":110,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Toka%C5%84_z_pieprzem","page":"Książka kucharska/Tokań z pieprzem"},{"id":"oc-plwb-6845","title":"Botwinka z patelni (pan-fried young beet greens)","cuisine":"European","category":"Side","ingredients":["1 bunch young beet greens (leaves and baby beetroots)","to taste onion","to taste olive oil (or vegetable oil)","to taste lemon juice (from about half a lemon or apple cider vinegar)","to taste black pepper (freshly ground)"],"steps":["Rinse the beet greens thoroughly, trim the leaves from the baby beetroots, scrub or peel the beetroots and slice them, then cut the stems into 3 cm pieces and chop the leaves into slightly longer ribbons.","Dice the onion and fry it in heated olive oil over fairly high heat.","Add the sliced beetroots and stems to the pan, and after a moment pour in the lemon juice.","Toss in the beet leaves, add a splash of water if needed, and braise covered for several minutes.","Sprinkle the dish with freshly ground black pepper before serving."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Botwinka_z_patelni","page":"Książka kucharska/Botwinka z patelni"},{"id":"oc-plwb-16268","title":"Braised chicken legs with mushrooms and sour cream (Udka z kurczaka z pieczarkami)","cuisine":"European","category":"Main","ingredients":["2 chicken legs","150 g button mushrooms","1 celery (stalk)","1 onion (medium)","1 tbsp butter","1 clove garlic","1 bay leaf","1 pinch thyme","125 ml sour cream","1 tbsp coarse wheat flour (krupczatka)","to taste pepper","to taste salt","60 ml water"],"steps":["Cut the chicken legs in half, season with salt and pepper, brown in the butter until the skin is golden and crisp, then transfer to a separate dish.","Add the sliced celery and onion to the same fat, sauté for a few minutes, and add to the chicken.","Add the thickly sliced button mushrooms to the pan, fry until browned, and set aside.","Briefly sauté the minced garlic without letting it brown, pour in 60 ml of water, and bring to the boil, scraping up the browned bits from the bottom.","Return the chicken, celery, and onion to the pan, add the bay leaf and thyme, cover, and braise over very low heat until the meat begins to fall off the bone, then add the mushrooms for a few minutes.","Pour in the sour cream thoroughly whisked with the coarse wheat flour, bring to a simmer until the sauce thickens, and season to taste with salt."],"time":60,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Udka_z_kurczaka_z_pieczarkami","page":"Książka kucharska/Udka z kurczaka z pieczarkami"},{"id":"oc-plws-546719","title":"Braised Potato-Stuffed Onions","cuisine":"European","category":"Main","ingredients":["450 g onion (orig. 4 large onions (or 8 medium) weighing 40–50 dkg in total)","2 potatoes (whole, boiled and grated)","40 g pork fatback (orig. 4 dkg)","to taste salt","200 ml water (for adding liquid during braising)"],"steps":["Peel the large onions and hollow out their centers, leaving walls about 1 cm thick.","Finely dice the pork fatback and render it in a skillet until crisp cracklings form, reserving the rendered fat.","Finely chop the hollowed-out onion centers, mix them with the boiled and grated potatoes and the pork cracklings, and heap the filling into the onion shells.","Heat the rendered pork fat in a shallow saucepan, arrange the stuffed onions inside, season with salt, and pour in water to reach halfway up their sides.","Braise covered over low heat until the liquid has almost completely evaporated and the onions are tender, and serve in the same dish."],"time":70,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Cebula_nadziewana","page":"109 potraw/Cebula nadziewana"},{"id":"oc-plws-45019","title":"Braised rice with mushroom sauce and shallots (ryż duszony z pieczarkami)","cuisine":"European","category":"Main","ingredients":["200 g white rice (orig. 1/2 Polish funt)","45 g butter (about 30 g for rice and 1 tbsp (15 g) for sauce)","1.5 tbsp plain wheat flour (1/2 tbsp for rice and 1 tbsp for sauce)","250 ml water (for braising rice and boiling mushrooms)","2 fresh flat-leaf parsley (sprigs)","150 g button mushrooms","4 shallots","0.5 lemon (for juice)","2 egg yolks","to taste black pepper","to taste salt"],"steps":["Scald the rice with boiling water, drain, steep in cold water for 30 minutes, then drain again.","Melt 30 g of butter in a saucepan, add the drained rice, dust with half a tablespoon of plain wheat flour, stir, splash with a few tablespoons of water, season with salt, pepper, and parsley sprigs, and braise covered over very low heat for about 25 minutes until tender.","In a separate saucepan, simmer the button mushrooms and whole peeled shallots in a little salted water for about 15 minutes, then drain, reserving the cooking liquid.","Make a pale roux with the remaining 15 g of butter and 1 tbsp of flour, whisk in the mushroom cooking liquid, add the juice of half a lemon, and bring to a boil. Remove from the heat and stir in the beaten egg yolks.","Discard the parsley sprigs, mound the tender rice onto a platter, arrange the cooked shallots and mushrooms on top, and pour over the hot sauce."],"time":80,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ry%C5%BC_z_sosem_pieczarkowym","page":"365 obiadów za 5 złotych/Ryż z sosem pieczarkowym"},{"id":"oc-plws-45189","title":"Braised savoy cabbage (Kapusta włoska duszona)","cuisine":"European","category":"Side","ingredients":["1 savoy cabbage (orig. 1 head of savoy cabbage)","to taste water (for parboiling the cabbage)","1 tbsp butter (for the roux, plus a piece for braising the cabbage)","to taste beef broth (or mutton broth or bouillon, for braising)","1 tbsp plain wheat flour (for the roux)","to taste sugar (lightly caramelized into the roux)","to taste salt"],"steps":["Strip the tough outer leaves from the savoy cabbage, cut into quarters, and rinse.","Parboil the cabbage quarters for about 10 minutes in boiling salted water, then drain and squeeze firmly.","Place a piece of butter and the squeezed cabbage in a saucepan, pour in the broth, cover, and braise over low heat for about 30 minutes until the liquid evaporates and the cabbage is tender.","In a separate pan, cook a tablespoon of butter with a tablespoon of wheat flour and a little sugar until golden, taking care not to scorch the roux.","Stir the golden roux into the cabbage and braise together for another 5 minutes."],"time":60,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kapusta_w%C5%82oska","page":"365 obiadów za 5 złotych/Kapusta włoska"},{"id":"oc-plws-546629","title":"Braised Stuffed Whole Chicken Galantine","cuisine":"European","category":"Main","ingredients":["1.35 kg stewing hen (orig. 1 hen weighing 125–150 dkg)","200 g stale bread roll (orig. 20 dkg)","2.5 potatoes (orig. 2–3 large boiled potatoes)","20 g fresh dill and flat-leaf parsley (orig. a handful)","1 egg (large)","60 g lard or margarine (orig. 6 dkg: 20 g for the stuffing and 40 g for browning)","250 ml water (for soaking the roll, mixing the stuffing, and basting during braising)","to taste salt"],"steps":["Slit the skin down the back of the hen with a sharp knife and carefully peel it off in one piece without tearing, then sew up the wing and leg openings with kitchen twine.","Strip all the meat cleanly from the bones and pass it twice through a meat grinder (the second time using a fine pate plate together with the soaked and squeezed bread roll and the boiled potatoes).","Add 20 g of fat, the egg, chopped dill and parsley, salt, and a few tablespoons of water to the ground mixture, and knead thoroughly until completely smooth and uniform.","Stuff the chicken skin loosely with the forcemeat, sew up the slit along the back with strong twine, and reshape into a whole bird.","Brown the stuffed hen in a Dutch oven in the remaining 40 g of hot fat, then add a splash of water and braise covered for at least 60 minutes, basting frequently; slice thinly with a sharp knife and serve hot or cold."],"time":135,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kura_faszerowana","page":"109 potraw/Kura faszerowana"},{"id":"oc-plwb-14011","title":"Braised veal with prunes","cuisine":"European","category":"Main","ingredients":["1 kg veal leg (round)","300 g fatback","3 tbsp butter","375 ml dry white wine","375 ml broth (from a bouillon cube)","1 onion","100 g prunes","to taste salt","to taste black pepper"],"steps":["Cut the fatback into strips, bard the veal leg with them, and tie the meat securely with kitchen twine.","Brown the meat on all sides in heated butter, then transfer it to a roasting pan.","Peel and slice the onion, arrange it around the meat, then pour in the broth and dry white wine, and season with salt and pepper.","Braise covered over low heat for about 120 minutes, adding the prunes to the pan halfway through the cooking time.","Let the meat cool slightly, cut into slices, surround with the braised onion and prunes, and spoon over the pan juices."],"time":140,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciel%C4%99cina_ze_%C5%9Bliwkami","page":"Książka kucharska/Cielęcina ze śliwkami"},{"id":"oc-plwb-15621","title":"Braised veal with spring vegetables","cuisine":"European","category":"Main","ingredients":["400 g veal","200 g green beans","150 g green peas (fresh)","1 bunch white asparagus (fresh)","4 tomatoes","2 clove garlic","4 tbsp vegetable oil","to taste salt","to taste black pepper"],"steps":["Rinse the veal, trim any sinew and cut into pieces, then brown in 2 tablespoons of oil, transfer to a saucepan, cover, and braise with a splash of water.","Wash the green beans and cut into smaller pieces, and rinse and drain the fresh green peas.","Rinse the white asparagus, snap off the woody ends, and briefly parboil in water.","Wash the tomatoes, dice them, and saute in the remaining oil.","Add the green beans, peas, asparagus along with its cooking liquid, and tomatoes to the braising meat, simmer until tender, and season with crushed garlic, salt, and pepper."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciel%C4%99cina_duszona","page":"Książka kucharska/Cielęcina duszona"},{"id":"oc-plws-40158","title":"Breaded Calf's Brain Cutlets (Kotlety z mózgu cielęcego)","cuisine":"European","category":"Main","ingredients":["1 calf's brain (or beef brain (approx. 350 g))","to taste water (cold for soaking and hot for parboiling)","3 tbsp vinegar (orig. several spoonfuls of vinegar)","to taste salt","1 egg (beaten, for breading)","4 tbsp breadcrumbs (for breading)","3 tbsp clarified butter (for frying)"],"steps":["Soak the calf's or beef brain in cold water for 60 minutes.","Cover the soaked brain with hot salted water and several tablespoons of vinegar, bring to a boil, parboil briefly, drain, and let cool.","Gently peel the outer membrane and veins from the cooled brain, then slice it into flat cutlets.","Dip the brain slices in beaten egg, coat in breadcrumbs, and fry in hot clarified butter on both sides until golden brown; serve as a main dish or as an accompaniment to vegetables and fricassees."],"time":90,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kotlety_z_m%C3%B3zgu_ciel%C4%99cego","page":"365 obiadów za 5 złotych/Kotlety z mózgu cielęcego"},{"id":"oc-plwb-19208","title":"Breaded chicken cutlets (Pierś z kurczaka panierowana)","cuisine":"European","category":"Main","ingredients":["400 g chicken breast fillet","80 g breadcrumbs","1 egg","0.33 tsp granulated garlic (or 2 crushed garlic cloves)","to taste curry powder","to taste chicken seasoning","to taste salt","to taste black pepper","3 tbsp sunflower oil (for frying)"],"steps":["Wash and dry the chicken breast, divide into 4 portions, and gently pound with a meat mallet.","Beat the egg in a shallow dish with the granulated garlic, curry powder, chicken seasoning, salt, and pepper.","Dip the cutlets in the egg mixture, then coat in breadcrumbs, pressing the crumb coating firmly with your hands.","Fry the cutlets in hot sunflower oil on both sides until golden brown."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pier%C5%9B_z_kurczaka_panierowana","page":"Książka kucharska/Pierś z kurczaka panierowana"},{"id":"oc-plws-1081063","title":"Briosze (Brioche buns)","cuisine":"European","category":"Bread","ingredients":["500 g plain wheat flour (orig. 1 funt (400 g) for the dough and a quarter of a funt (100 g) for the sponge (plus extra for dusting))","6 eggs (orig. 6 whole eggs for the dough (plus 1 for brushing before baking))","400 g butter (orig. 1 historical Polish funt of unsalted butter (plus a little for the baking sheet))","25 g fresh yeast (orig. 2 łuts)","to taste water (lukewarm, or milk, for mixing the yeast sponge)","1 tbsp icing sugar (orig. 1 large tablespoon of fine sugar)"],"steps":["In a separate bowl, mix 100 g (a quarter of a funt) of the flour with the yeast and a little lukewarm water or milk into a sponge, and set aside to rise.","Mound the remaining 400 g (1 funt) of flour on a pastry board, break in the 6 eggs, and crumble the unsalted butter into the flour.","Once the yeast sponge is bubbling, pour it onto the board with the flour, butter, and eggs, add a large tablespoon of icing sugar, and work gently from underneath into a smooth dough.","Transfer the dough to a floured bowl and leave overnight in a room at moderate temperature.","The next day, turn the dough out onto the board, knead thoroughly, and return it to the floured bowl to rise a little more.","Divide the dough into small buns, top the centre of each with a separately shaped small ball of dough, and set on a buttered baking sheet to rise.","Brush the risen brioches with beaten egg and bake in an oven preheated to 200 °C for about 15–20 minutes until golden brown."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Briosze","page":"Baby, placki i mazurki/Briosze"},{"id":"oc-plws-38748","title":"Broth or white wine Hollandaise sauce (sos holenderski)","cuisine":"European","category":"Sauce","ingredients":["100 g fresh butter","3 egg yolks","1 tbsp plain wheat flour","1 tbsp lemon juice","1 tsp sugar","150 ml meat broth or dry white wine","to taste salt"],"steps":["Beat the fresh butter until light and fluffy, whisk in the egg yolks, plain wheat flour, lemon juice, sugar, and a pinch of salt.","Pour in the meat broth or white wine and whisk until smooth.","Set the saucepan over very low heat and warm while whisking continuously without letting it boil until the sauce rises and thickens."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_holenderski","page":"365 obiadów za 5 złotych/Sos holenderski"},{"id":"oc-plws-38738","title":"Brown caper sauce (sos kaparowy rumiany)","cuisine":"European","category":"Sauce","ingredients":["1 tbsp butter","1 tbsp plain wheat flour","250 ml meat bouillon (orig. 1 szklanka)","2 tbsp capers","1 tbsp lemon juice","2 tsp sugar (orig. 2 cubes + a bit of caramel)"],"steps":["Melt and brown the butter in a saucepan, stir in plain wheat flour, and cook to a dark golden roux.","Whisk 250 ml of hot meat bouillon into the roux, stirring thoroughly until smooth.","Add the capers, lemon juice, and sugar, caramelising some of the sugar beforehand if desired for a darker colour. Bring everything to a boil and pour over the hot meat."],"time":15,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_kaparowy","page":"365 obiadów za 5 złotych/Sos kaparowy"},{"id":"oc-plws-38739","title":"Brown gherkin sauce (sos korniszonowy rumiany)","cuisine":"European","category":"Sauce","ingredients":["1 tbsp butter","1 tbsp plain wheat flour","250 ml bouillon or meat broth","4 pickled gherkins (sliced)","1 tbsp vinegar","2 tsp sugar (1 tsp for sauce and 1 tsp for caramel)"],"steps":["Simmer the sliced gherkins for a few minutes in a separate small pot in a few tablespoons of broth until tender.","Brown the butter with plain wheat flour in a saucepan and whisk in the remaining hot broth, stirring constantly.","Stir the gherkins along with their simmering liquid into the sauce, season with vinegar, sugar, and caramelised sugar, and bring to a boil."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_korniszonowy_rumiany","page":"365 obiadów za 5 złotych/Sos korniszonowy rumiany"},{"id":"oc-plws-580433","title":"Brukiew lub kalarepa faszerowana (stuffed rutabaga or kohlrabi)","cuisine":"European","category":"Main","ingredients":["1 rutabaga (young (or young kohlrabi))","to taste butter (for gently cooking the flesh and baking in the saucepan)","1 onion (finely chopped)","2 button mushrooms (or wild mushrooms, finely chopped)","1 egg","to taste vegetable broth (or water for braising)","to taste sour cream (for the sauce)","to taste salt"],"steps":["Peel the young rutabaga, parboil it in boiling water for about 15 minutes until half-tender, then hollow out the centre with a metal teaspoon.","Cook the scooped-out rutabaga flesh gently with butter, covered, for 10 minutes and mash thoroughly, then fry the onion and chopped mushrooms separately in butter.","Mix the mashed pulp with the fried onion, mushrooms, a little butter, and the egg, then pack the filling back into the hollowed rutabaga, shaping a dome on top.","Place the stuffed rutabaga in a small saucepan with melted butter, pour in the vegetable broth, add the sour cream, and season with salt.","Bring to a boil over high heat, then braise gently over low heat for about 20 minutes until the rutabaga is tender and the sauce reduces to one-third of its volume.","Serve the rutabaga hot with the reduced braising sauce spooned over it."],"time":60,"servings":2,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Brukiew_lub_kalarepa_faszerowana","page":"100 postnych i jarskich dań/Brukiew lub kalarepa faszerowana"},{"id":"oc-plws-543007","title":"Brussels sprouts with butter and rusks","cuisine":"European","category":"Side","ingredients":["400 g Brussels sprouts (small heads only; orig. 1 funt; historical measure, converted approximately)","15 ml butter (orig. 1 tbsp)","to taste salt (for the water; the tablespoon in the ingredient list refers to the butter)","1 rusks (1–2 pieces)"],"steps":["Detach the small Brussels sprout heads from the stalk, discarding the large leaves and stalk.","Boil the Brussels sprouts in boiling salted water.","Drain the Brussels sprouts.","Transfer the Brussels sprouts to a platter.","Crush the rusks.","Brown the butter with the crushed rusks.","Pour the butter and rusks over the Brussels sprouts."],"time":null,"servings":2,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kapusta_pod_nazw%C4%85%3A_wyrostki_brukselskie","page":"Kucharka litewska (1913)/Kapusta pod nazwą: wyrostki brukselskie"},{"id":"oc-plws-44964","title":"Buckwheat Groats in Mushroom Broth (Kasza na grzybowym smaku)","cuisine":"European","category":"Side","ingredients":["1 l fine buckwheat groats (orig. 1 kwarta (approximately 800 g))","220 ml butter (orig. nearly 1 kwaterka, melted and hot)","1.5 l dried mushroom broth (orig. enough to reach 1 cal (2.5 cm) above the groats)","to taste salt"],"steps":["Pour the fine buckwheat groats into a saucepan and pour the hot melted butter over them.","Season the groats with salt and pour in the dried mushroom broth to a height of about 2.5 cm above the level of the groats.","Cover the pan with a tight-fitting lid and cook over very low heat for 60 minutes, shaking the pan frequently so the groats absorb the broth evenly without sticking."],"time":70,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kasza_na_grzybowym_smaku","page":"365 obiadów za 5 złotych/Kasza na grzybowym smaku"},{"id":"oc-plws-1081047","title":"Buckwheat-flour torte","cuisine":"European","category":"Cake","ingredients":["200 g butter (orig. half a funt)","200 g icing sugar (orig. half a funt)","100 g ground almonds, skins left on (orig. a quarter funt)","4 eggs","150 g buckwheat flour (orig. 1.5 quarters funta)","2 g ground vanilla (orig. a little vanilla)","150 g sharp jam","100 g clear icing","15 g butter and gluten-free breadcrumbs for the tin"],"steps":["Beat the soft butter until fluffy, adding the eggs one at a time, then the sugar, the ground almonds and the vanilla.","At the end, sprinkle in the buckwheat flour a spoonful at a time, folding the ingredients together gently.","Pour the batter into a springform tin buttered and sprinkled with gluten-free breadcrumbs.","Bake in an oven heated to 175 °C for about 40 minutes, until a skewer comes out clean.","Once cool, cut the cake into two or three layers, fill them with sharp jam, reassemble, and pour clear icing over the top."],"time":70,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Tort_z_m%C4%85ki_gryczanej","page":"Baby, placki i mazurki/Tort z mąki gryczanej"},{"id":"oc-plws-580392","title":"Budyń grzybowy (savory mushroom pudding)","cuisine":"European","category":"Main","ingredients":["100 g dried mushrooms (young)","to taste butter (for frying the onion and mushrooms and greasing the mould)","2 onion (finely chopped)","100 g wheat roll (two rolls)","to taste milk (for soaking the rolls)","4 egg yolks","4 egg whites (beaten to stiff peaks)","to taste salt","to taste black pepper","to taste breadcrumbs (for dusting the pudding mould)"],"steps":["Boil the dried mushrooms in water until tender, about 30 minutes, drain (reserving the broth for a sauce), and chop them very finely.","Fry the chopped mushrooms in butter together with the finely chopped onions for about 8 minutes.","Soak the wheat rolls in milk, squeeze them out, and mash until smooth, then mix with the mushrooms, egg yolks, salt, and pepper.","Beat the egg whites to stiff peaks and gently fold them into the mushroom mixture.","Butter a pudding mould, dust it with breadcrumbs, transfer the mixture into the mould, cover tightly with a lid, and steam for 60 minutes."],"time":90,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Budy%C5%84_grzybowy","page":"100 postnych i jarskich dań/Budyń grzybowy"},{"id":"oc-plws-580394","title":"Budyń z jaglanej kaszy (savory millet pudding)","cuisine":"European","category":"Main","ingredients":["300 g millet groats","to taste milk (for cooking the groats)","1 tbsp butter (a generous tablespoon for the mixture, plus extra for greasing the mould)","1 bunch fresh dill (chopped (a handful))","to taste salt","4 egg yolks","4 egg whites (beaten to stiff peaks)","to taste breadcrumbs (for dusting the pudding mould)"],"steps":["Scald the millet groats three times with boiling water, draining the water each time to remove any bitterness.","Cook the millet groats in milk until tender, about 20 minutes, and set aside to cool.","Add the butter, chopped dill, salt, and egg yolks to the cooled millet and beat thoroughly until smooth.","Beat the egg whites to stiff peaks and fold them carefully into the millet mixture.","Butter a pudding mould, dust it with breadcrumbs, fill with the mixture, close tightly with a lid, and steam for 60 minutes."],"time":90,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Budy%C5%84_z_jaglanej_kaszy","page":"100 postnych i jarskich dań/Budyń z jaglanej kaszy"},{"id":"oc-plws-580275","title":"Budyń z kapusty słodkiej (savory cabbage pudding)","cuisine":"European","category":"Main","ingredients":["1 white cabbage (large head (or savoy cabbage))","2 tbsp plain wheat flour (heaped)","1 tbsp butter (a generous tablespoon for the roux, plus extra for the mould and serving)","500 ml milk","to taste salt (for blanching the cabbage and seasoning the mixture)","to taste white pepper","4 egg yolks","4 egg whites (beaten to stiff peaks)","to taste breadcrumbs (for dusting the mould)"],"steps":["Finely shred the cabbage, blanch it in boiling salted water for about 5 minutes, drain thoroughly, and squeeze out the excess water.","Cook the wheat flour with the butter over low heat without browning, whisk in the milk, and cook, stirring, for about 5 minutes until thick.","Mix the squeezed cabbage with the thick milk sauce, season with salt and white pepper, stir in the egg yolks, and finally fold in the stiffly beaten egg whites.","Butter a pudding mould, dust it with breadcrumbs, pack in the cabbage mixture, and fasten the lid tightly.","Steam the pudding for 60 minutes, then unmould onto a platter and serve with melted butter."],"time":90,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Budy%C5%84_z_kapusty_s%C5%82odkiej","page":"100 postnych i jarskich dań/Budyń z kapusty słodkiej"},{"id":"oc-plws-580393","title":"Budyń z kartofli (savory potato pudding)","cuisine":"European","category":"Main","ingredients":["1 kg potatoes (peeled)","2 onion (large, mild)","to taste butter (for cooking the onions, greasing the mould, and pouring over)","1 bunch fresh dill (finely chopped (a handful))","to taste salt","to taste white pepper","125 ml sour cream","4 egg yolks","4 egg whites (beaten to stiff peaks)","to taste breadcrumbs (for dusting the pudding mould)"],"steps":["Boil the peeled potatoes in salted water until tender, about 25 minutes, drain the water, and let them steam dry covered.","Cook the chopped onions gently in butter for about 8 minutes without browning them, then pass them through a mincer together with the potatoes.","Add the chopped dill, salt, white pepper, sour cream, and egg yolks to the potato mixture and mix thoroughly.","Beat the egg whites to stiff peaks and gently fold them into the potato mixture.","Transfer the mixture to a buttered and breadcrumb-dusted pudding mould, cover tightly with a lid, and steam for 60 minutes.","Unmould the finished pudding onto a platter and serve hot drizzled with browned butter."],"time":95,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Budy%C5%84_z_kartofli","page":"100 postnych i jarskich dań/Budyń z kartofli"},{"id":"oc-plws-580277","title":"Budyń ze szpinaku (savory spinach pudding)","cuisine":"European","category":"Main","ingredients":["1 kg spinach (fresh)","to taste salt (for blanching the spinach and seasoning the mixture)","100 g wheat roll (two small rolls for the mixture, plus extra for croutons to serve)","to taste milk (for soaking the rolls)","to taste nutmeg (grated)","4 egg yolks","4 egg whites (beaten to stiff peaks)","to taste butter (for greasing the mould, browning the croutons, and pouring over the pudding)","to taste breadcrumbs (for dusting the pudding mould)"],"steps":["Pick over and wash the spinach, blanch it in boiling salted water for about 3 minutes, drain thoroughly, and pass it through a mincer.","Soak the two rolls in milk, squeeze them out, and mash until smooth, then mix with the spinach, salt, nutmeg, and egg yolks.","Beat the egg whites to stiff peaks and gently fold them into the spinach mixture.","Butter a pudding mould, dust it with breadcrumbs, fill with the mixture, close tightly with a lid, and steam for 60 minutes.","Turn the pudding out onto a platter immediately after steaming, pour browned butter over it, and surround with butter-fried bread croutons."],"time":90,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Budy%C5%84_ze_szpinaku","page":"100 postnych i jarskich dań/Budyń ze szpinaku"},{"id":"oc-plws-45177","title":"Butter-Glazed Chestnuts (Kasztany w maśle smażone)","cuisine":"European","category":"Side","ingredients":["400 g fresh sweet chestnuts (orig. 1 funt (enough for a duck or capon; for a turkey, 2–3 funty, or 800–1200 g))","100 g unsalted butter (orig. a generous quarter funt per 1 funt of chestnuts)","100 g caster sugar (orig. a quarter funt of caster sugar per 1 funt of chestnuts)","to taste water (cold, for boiling the chestnuts)","to taste salt (for salting the water)"],"steps":["Place the whole, unscored chestnuts in a pot of cold water, salt lightly during cooking, and boil for about 25–30 minutes, as with potatoes, until tender and easy to peel.","Drain the water and carefully peel the warm chestnuts.","Melt the unsalted butter in a saucepan, add the peeled chestnuts, and sprinkle in the caster sugar.","Stir thoroughly and cook over low heat for about 10 minutes, stirring frequently, until the chestnuts are coated in a buttery sugar glaze.","Arrange the hot chestnuts around a roast duck, turkey, or other roast poultry on a serving platter."],"time":60,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kasztany_w_ma%C5%9Ble_sma%C5%BCone","page":"365 obiadów za 5 złotych/Kasztany w maśle smażone"},{"id":"oc-plws-38754","title":"Béchamel sauce with egg yolks (biszamel)","cuisine":"European","category":"Sauce","ingredients":["100 g butter (orig. 1/4 funt)","1 tbsp plain wheat flour (heaping)","125 ml thick unsweetened cream (orig. 1/2 kwaterka)","3 egg yolks (orig. 3–4 yolks)"],"steps":["Cream the cold fresh butter with a full tablespoon of wheat flour until completely smooth.","Set the saucepan over the heat, bring the butter and flour briefly to a bubble, and whisk in the sweet cream, stirring constantly.","Boil until thickened, rub through a sieve, and set aside until completely cool.","Whisk the egg yolks thoroughly into the cooled sauce; spoon over roast veal or turkey, or use to top sliced boiled beef before baking."],"time":25,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Biszamel","page":"365 obiadów za 5 złotych/Biszamel"},{"id":"oc-plws-542851","title":"Cabbage stuffed with mushroom filling","cuisine":"European","category":"Main","ingredients":["2 white or savoy cabbage (heads; orig. 2–3 heads; lower bound used)","30 ml butter (orig. 1–2 tbsp; upper bound used, for the filling and sauce)","125 ml rice (dry; orig. ½ szklanka)","8 dried porcini mushrooms (orig. 8–10; lower bound used)","to taste salt","to taste black pepper","2 onion","2 eggs","15 ml wheat flour (orig. 1 tbsp)","2 rusks (crushed, for sprinkling)","to taste water (for boiling and for the sauce; mushroom cooking broth may be used for the sauce)"],"steps":["Clean the cabbage and cut each head into four quarters.","Parboil the cabbage in salted water, leaving it half-firm.","Drain and squeeze out the cabbage.","Boil the porcini mushrooms in water.","Chop the cooked mushrooms and the onions.","Sauté the mushrooms and onions in part of the butter.","Boil the rice in water.","Mix the mushrooms with the rice, salt, pepper, and eggs.","Place the filling between the leaves of the cabbage quarters.","Tie the quarters with kitchen twine.","Pack the cabbage tightly in a saucepan.","Prepare a sauce from the flour, remaining butter, and boiling water or mushroom cooking broth.","Pour the sauce over the cabbage.","Cook gently, covered, until tender.","Sprinkle with the crushed rusks before serving."],"time":null,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kapusta_s%C5%82odka%2C_nadziewana_farszem_grzybowym","page":"Kucharka litewska (1913)/Kapusta słodka, nadziewana farszem grzybowym"},{"id":"oc-plws-568740","title":"Candied Dried Greengage Plums","cuisine":"European","category":"Preserve","ingredients":["500 g half-ripe green greengage plums (orig. half a kilogram)","500 g sugar (orig. half a kilogram)","to taste water (for soaking, warming, cooling, and the syrup; amount not specified)","to taste sugar (additionally for subsequent thickenings of the syrup and for generously sprinkling the fruit; amount not specified)"],"steps":["Prick the half-ripe greengage plums deeply with a wooden skewer and place into cold water.","Transfer them to hot, non-boiling water and warm until softened.","Cool them briefly in cold water.","Drain the fruit and place into a jar.","Cook a thin syrup from 500 g of sugar and water.","Cool the syrup.","Pour the cooled syrup over the greengage plums and press down lightly so they are completely submerged without being crushed.","Repeat the pouring about five times, each time draining off the syrup, adding a little sugar, boiling it, and cooling before pouring over the fruit again.","On the final boiling, simmer the greengage plums in the syrup.","Sprinkle the fruit generously with fine sugar.","Dry the greengage plums to obtain a dry preserve."],"time":null,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/%C5%9Aliwki_Rengloty_suszone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Śliwki Rengloty suszone w cukrze"},{"id":"oc-plws-568688","title":"Candied Dried Lemons","cuisine":"European","category":"Preserve","ingredients":["500 g lemons (ripe, unblemished; orig. half a kilogram)","750 g sugar (for the initial syrup; orig. three-quarters of a kilogram)","to taste sugar (additional for subsequent boilings of the syrup; amount not specified)","to taste water (for soaking, boiling, rinsing, and the syrup; amounts not specified)"],"steps":["Soak the lemons in water for 7200 minutes, changing the water every 1440 minutes.","Cover the fruit with fresh water in a pot.","Boil until tender enough to be easily pierced.","Leave the lemons in the water to cool.","Cut the fruit into lengthwise strips.","Rinse the strips thoroughly in clean water.","Boil a light syrup from 750 g of sugar and water.","Leave the syrup to cool completely.","Arrange the lemons in a jar and cover with the cooled syrup.","Over several days, repeat boiling the drained syrup, adding a little extra sugar each time.","After each boiling, cool the syrup before pouring it over the lemons again.","Repeat the steeping until the lemons lose their rawness.","After the final boiling, leave the lemons in the syrup for a longer period.","Remove the strips from the syrup and spread them out on platters.","Leave to air-dry at room temperature."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Cytryny_suszone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Cytryny suszone w cukrze"},{"id":"oc-plws-568742","title":"Candied Dried Mirabelle Plums","cuisine":"European","category":"Preserve","ingredients":["500 g ripe mirabelle plums (orig. half a kilogram)","500 g sugar (for the syrup; orig. half a kilogram)","to taste water (for soaking, blanching, cooling, and the syrup; amount not specified)"],"steps":["Prick the ripe mirabelle plums with a needle or wooden skewer and immediately place into cold water.","Scald the fruit with hot water until softened.","Transfer them back to cold water to cool.","Drain the mirabelle plums thoroughly on a sieve.","Cook a thick syrup from the sugar and water.","Cool the syrup.","Arrange the mirabelle plums in a jar and pour the cooled syrup over them.","Press the fruit down lightly with a glass tumbler so they remain submerged.","Repeat the pouring over 5760 minutes, or four days, using a warmer syrup each time.","Dry the syrup-infused fruit to obtain a dry preserve."],"time":null,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/%C5%9Aliwki_mirabelki_suszone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Śliwki mirabelki suszone w cukrze"},{"id":"oc-plws-555198","title":"Canned apples","cuisine":"European","category":"Preserve","ingredients":["1 kg apples (early transparent apples that are not overripe, or ripe Stettin apples or reinettes, peeled, cored and halved)","1 lemon (juice for the cold water while peeling, and for the syrup at the end of the brief cooking)","750 g sugar (about 500 g for the light syrup, plus 250 g added before the jars are filled)","500 ml water (for the syrup (plus cold well water to hold the peeled apples))"],"steps":["Peel the apples, remove the cores, cut the fruit in half, and drop the halves at once into cold water acidulated with the juice of half a lemon.","Cook a light syrup from 500 g of sugar and 500 ml of water, skim it, add the drained apple halves, and cook carefully for a few minutes until just soft, squeezing in the rest of the lemon juice at the end.","Lift the apples gently with a slotted spoon onto a sieve to drain, and once they have cooled a little pack them into jars.","Add 250 g of sugar to the remaining syrup, bring it to the boil several times, skim it, and once cool pour it over the apples in the jars.","Seal the jars, stand them in a kettle lined with hay or a cloth, and pasteurize for 25 minutes from the moment the water boils."],"time":70,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_jab%C5%82ek","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z jabłek"},{"id":"oc-plws-555207","title":"Canned apricots in heavy syrup","cuisine":"European","category":"Preserve","ingredients":["1 kg apricots (fine, ripe but not overripe)","1.2 kg sugar (about 450 g for the first light syrup and 750 g for the fresh thick syrup in the jars)","1 l water (500 ml for each of the two syrups (plus cold water for heating and for the 10-hour soak))"],"steps":["Lay ripe, firm apricots in an earthenware or enamel pan, cover them with cold water, and heat over low heat until the fruit is soft enough.","Lift the apricots out with a slotted spoon into a porcelain bowl of fresh cold water and leave them for 10 hours.","Drain the fruit, cover it with a light cooled syrup of 450 g of sugar and 500 ml of water, and leave it for 24 hours.","The next day, pour off the first syrup, pack the apricots into jars, and cover them with a fresh thick syrup cooked from 750 g of sugar and 500 ml of water.","Seal the jars and pasteurize them in a kettle of water for 20–25 minutes from the moment the water boils."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_moreli","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z moreli"},{"id":"oc-plws-555197","title":"Canned bergamot pears","cuisine":"European","category":"Preserve","ingredients":["1 kg bergamot pears (or sugar pears or panny, peeled whole with the stems left on, or halved with the cores removed)","2 lemon (juice of 1 lemon in the cold water while peeling, and juice of 1 lemon in the syrup)","750 g sugar (about 500 g for the first light syrup, plus 250 g added when the syrup is boiled again)","500 ml water (for the syrup (plus cold water to hold the peeled pears))"],"steps":["Peel the bergamot pears, leaving the trimmed stems (or halve the fruit and remove the cores), and drop each one at once into cold water with the juice of 1 lemon.","Cook a light syrup from 500 g of sugar and 500 ml of water, skim it, squeeze in the juice of the second lemon, and put the pears into the boiling syrup.","Cook the pears briefly, then lift them with a slotted spoon onto a sieve to drain and pack them into jars.","Add the remaining 250 g of sugar to the syrup, bring it to the boil, skim it carefully, cool it, and pour it over the pears in the jars.","Seal the jars, stand them in a kettle of water, and pasteurize for 30 minutes from the moment the water boils. Take them out only after the water bath has cooled completely."],"time":80,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_gruszek","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z gruszek"},{"id":"oc-plws-555201","title":"Canned blackberries","cuisine":"European","category":"Preserve","ingredients":["1 kg blackberries (fine, ripe, picked over)","500 g sugar (for a syrup of ordinary thickness)","500 ml water (for the syrup)"],"steps":["Pick over the ripe blackberries carefully, removing leaves and bits of debris, and fill the jars to the top without shaking them, so the fruit is not crushed.","Cook and cool a syrup from 500 g of sugar and 500 ml of water, then pour it over the blackberries in the jars.","Seal the jars and pasteurize them in a kettle lined with hay (or in the oven) for at most 15 minutes from the moment the water boils."],"time":45,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_jerzyn","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z jerzyn"},{"id":"oc-plws-555209","title":"Canned currants","cuisine":"European","category":"Preserve","ingredients":["1 kg currants (large ripe red or white currants, the stalks removed carefully (optionally mixed with raspberries))","750 g sugar (for a very thick syrup)","400 ml water (for the thick syrup)"],"steps":["Strip large ripe currants gently from the stalks, taking care the fruit stays whole and does not release its juice.","Fill the jars with the currants without shaking them (optionally layered with raspberries), leaving about 7.5 cm (3 cal) of headspace.","Cover the fruit with a very thick syrup cooked from 750 g of sugar and 400 ml of water, seal the jars, and pasteurize them in a kettle of water (or in the oven) for at most 15 minutes from the moment the water boils."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_porzeczek","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z porzeczek"},{"id":"oc-plws-555258","title":"Canned grapes","cuisine":"European","category":"Preserve","ingredients":["1 kg grapes (large, fine, half-ripe bunches)","600 g sugar (for a thick syrup)","400 ml water (for cooking the thick syrup)"],"steps":["Pack large, fine, half-ripe bunches of grapes into jars.","Cook a thick syrup from 600 g of sugar and 400 ml of water, cool it, and pour it over the grapes in the jars.","Seal the jars and pasteurize them in a kettle of water for about 20 minutes from the moment the water boils (or for 10 minutes if the grapes are riper). Once cool, store them in a dry, cool place."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_winogron","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z winogron"},{"id":"oc-plws-555212","title":"Canned greengages","cuisine":"European","category":"Preserve","ingredients":["60 greengages (orig. 1 kopa (60 pieces, about 2 kg) of firm, underripe, unblemished greengages)","5 g alum (orig. a quarter deka (2.5 g) for the brief cooking, and half a teaspoon (about 2.5 g) for the soak, per 1 kopa of greengages)","1.5 kg sugar (about 500 g for the first light syrup and 1 kg for the fresh thick syrup in the jars)","1.5 l water (for both syrups (plus boiled water for heating, and cold soft water for soaking and rinsing the plums))","2 tsp rum (orig. 1 teaspoon of good rum on top of each jar (optional))"],"steps":["Choose sound, slightly underripe greengages, prick them densely with a wooden pin, pack them tightly in a pan, cover them with boiled water with 2.5 g of alum per 60 fruit, and heat until air bubbles appear and the plums soften, without letting the water boil.","Transfer the greengages to a porcelain bowl of cold soft water mixed with half a teaspoon of alum and soak them for 3 hours. Then pour off the water and rinse the fruit very thoroughly in several changes of cold water.","Cover the rinsed greengages with a light syrup of 500 g of sugar and 750 ml of water and leave them for 24 hours.","The next day, pour off the first syrup, pack the greengages into jars, cover them with a fresh, thick, cold syrup of 1 kg of sugar and 750 ml of water, pour 1 teaspoon of good rum on top of each jar, seal, and pasteurize in a kettle of water for 20–30 minutes from the moment the water boils."],"time":600,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_Renglot","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z Renglot"},{"id":"oc-plws-555205","title":"Canned melon in rum syrup","cuisine":"European","category":"Preserve","ingredients":["1 kg melon (ripe pineapple melon, peeled, seeded and cut into cubes or sticks)","1.2 kg sugar (about 450 g for the first light syrup and 750 g for the fresh thick syrup in the jars)","1 l water (500 ml for each of the two syrups (plus cold water for heating and rinsing the melon))","4 tbsp rum (orig. 2 tablespoons of very good rum in each jar)"],"steps":["Peel a ripe pineapple melon, remove the seeds, and cut the flesh into moderately sized oblong or square pieces.","Put the melon in a pan, cover it with cold water, and heat it until the pieces soften, without letting the water boil.","Pour off the hot water, rinse the melon several times with cold water in a colander so it cools quickly, and drain it well.","Cover the cooled melon with a light syrup cooked from 450 g of sugar and 500 ml of water, and leave it for 24 hours.","The next day, pour off the first syrup, pack the melon into jars, cover it with a fresh thick syrup of 750 g of sugar and 500 ml of water, add 2 tablespoons of good rum to each jar, seal, and pasteurize in a kettle of water for 20 minutes from the moment the water boils."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_melonu","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z melonu"},{"id":"oc-plws-555202","title":"Canned raspberries","cuisine":"European","category":"Preserve","ingredients":["1 kg raspberries (freshly picked on a dry, fine day, large and picked over)","600 g sugar (for a thick syrup)","400 ml water (for cooking the thick syrup)"],"steps":["Pick over large raspberries gathered on a dry day and fill the jars without shaking them, so the fruit is not crushed.","Cook a thick syrup from 600 g of sugar and 400 ml of water, cool it, and pour it over the raspberries in the jars.","Seal the jars, stand them in a kettle of water lined with hay or a cloth, and cook over low heat for exactly 15 minutes from the moment the water boils."],"time":45,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_malin","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z malin"},{"id":"oc-plws-555253","title":"Canned sour cherries","cuisine":"European","category":"Preserve","ingredients":["500 g sour cherries (orig. half a kilogram of Łutówka or Hiszpanka sour cherries, with the stones left in or removed)","500 g sugar (orig. half a kilogram of sugar chopped into small pieces)","375 ml water (orig. one and a half szklanki of water for the syrup)"],"steps":["Cook a thick syrup from 500 g of finely crushed sugar and 375 ml of water, and skim it carefully.","Drop 500 g of prepared cherries (with the stones or stoned) into the boiling syrup and cook over low heat for about 5 minutes.","Take the pan off the heat. Once the cherries have cooled a little, pack them with the syrup into jars (you can also cover raw cherries in the jars with the thick syrup).","Seal the jars, stand them in a kettle lined with hay and filled with cold water, and pasteurize for 20 minutes from the moment the water boils (or bake them in the oven)."],"time":60,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_wi%C5%9Bni","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z wiśni"},{"id":"oc-plws-555236","title":"Canned strawberries","cuisine":"European","category":"Preserve","ingredients":["500 g strawberries (orig. half a kilogram of ripe but not overripe strawberries picked on a dry, sunny day)","500 g sugar (orig. half a kilogram of sugar chopped into small pieces)","375 ml water (orig. one and a half szklanki of water)","2 tsp rum (orig. 1 teaspoon of very good rum in each jar)"],"steps":["Hull 500 g of freshly picked ripe strawberries.","Cook a syrup from 500 g of finely crushed sugar and 375 ml of water, and skim it carefully.","Drop the strawberries into the boiling syrup, take the pan off the heat at once, and leave the fruit in the syrup at the side of the stove for 15 minutes. Then cool it.","Pack the cooled strawberries and syrup into jars, pour 1 teaspoon of very good rum into each, seal, and pasteurize in a kettle of water for 10–12 minutes from the moment the water boils."],"time":55,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_truskawek","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z truskawek"},{"id":"oc-plws-555199","title":"Canned whole crabapples in heavy syrup","cuisine":"European","category":"Preserve","ingredients":["1 kg crabapples (sound, with the stems trimmed to 1/4 of their length)","1.2 kg sugar (about 450 g for the first light syrup and 750 g for the fresh thick syrup in the jars)","1 l water (500 ml for each of the two syrups (plus hot water for softening the crabapples))"],"steps":["Trim the crabapples, cut the stems so that 1/4 of their length remains, remove the flower ends, and prick the fruit densely with a wooden pin.","Put the crabapples into a pan of hot water and heat over low heat until they soften, without letting the water boil, so the fruit does not burst.","Pour off the water, cover the soft crabapples with a light syrup made ahead from 450 g of sugar and 500 ml of water, and leave them for 24 hours.","After a full day, pour off the first syrup, pack the crabapples into jars, shaking so they settle evenly, and cover them with a fresh thick syrup of 750 g of sugar and 500 ml of water.","Seal the jars and pasteurize them in a kettle of water for 20–25 minutes from the moment the water boils."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_jab%C5%82uszek_rajskich","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z jabłuszek rajskich"},{"id":"oc-plws-555210","title":"Canned węgierka plums","cuisine":"European","category":"Preserve","ingredients":["500 g węgierka plums (orig. half a kilogram of ripe but firm węgierka plums)","650 g sugar (orig. half a kilogram (500 g) of sugar for the first syrup, plus about 150 g of sugar to reboil the syrup before the jars are filled)","500 ml water (orig. 2 szklanki of water for the syrup (plus hot water for blanching in the peeled version))"],"steps":["For the version with the skins on, wipe 500 g of firm węgierka plums with a cloth, put them in an earthenware pan, cover them with a boiling thick syrup cooked from 500 g of sugar and 500 ml of water, and leave them until the next day.","On the second day, pack the plums tightly into jars. Boil the poured-off syrup with an extra 150 g of sugar to the right thickness, cool it completely, pour it over the fruit, seal the jars, and pasteurize over low heat for 60 minutes from the moment the water in the kettle boils (or in the oven).","For the peeled version, blanch the plums a few at a time in hot water and peel them carefully with a small knife. Drop them into a boiling, skimmed syrup of 500 g of sugar and 500 ml of water, move the pan to the side of the stove for 15 minutes, and then cool completely.","Pack the peeled plums tightly into jars, reboil the syrup with an extra 150 g of sugar, cool it, pour it over the fruit, seal, and pasteurize in a kettle of water (or in the oven) for 45 minutes (three quarters of an hour) from the moment the water boils."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_ze_%C5%9Bliwek_w%C4%99gierek","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa ze śliwek węgierek"},{"id":"oc-plws-555208","title":"Canned young walnuts","cuisine":"European","category":"Preserve","ingredients":["500 g young walnuts (fresh, the thin skin peeled carefully with a penknife)","500 g sugar (for a syrup of ordinary thickness)","500 ml water (for the syrup)"],"steps":["Peel young fresh walnuts carefully with a penknife so they are completely white, and pack them into jars.","Cook a syrup of ordinary thickness from 500 g of sugar and 500 ml of water, skim it carefully, cool it, and pour it over the walnuts.","Seal the jars and pasteurize them in a kettle of water lined with hay (or in the oven) for about 25–30 minutes. Take the jars out of the kettle only after the water has cooled completely."],"time":80,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_orzech%C3%B3w_w%C5%82oskich","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z orzechów włoskich"},{"id":"oc-plws-577951","title":"Capon with juniper","cuisine":"European","category":"Main","ingredients":["1 capon","7.5 ml juniper berries (orig. ½ tbsp; the source mentions juniper in the stuffing and on the surface of the capon without specifying how the amount is divided)","30 ml butter (orig. 2 tbsp; half for the stuffing, half for rubbing)","250 ml breadcrumbs (orig. 1 kwaterka; historical measure, converted approximately)","3 eggs","1 rusk (source states 1–2 pieces; lower bound used; crushed)","to taste salt"],"steps":["Salt the capon.","Crush the juniper berries.","Mix the breadcrumbs with the eggs, half of the butter, and part of the juniper.","Fill the capon with the stuffing.","Rub the capon with the remaining butter mixed with the rest of the juniper.","Wrap the capon in baking paper.","Roast the capon in a roasting pan in an oven at 180 °C.","Remove the paper.","Sprinkle the capon with the crushed rusk.","Finish roasting the capon until browned.","Spoon the roasting juices over the capon."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kap%C5%82on_z_sosem_ja%C5%82owcowym","page":"Kucharka litewska (1913)/Kapłon z sosem jałowcowym"},{"id":"oc-plws-577952","title":"Capons with truffle sauce","cuisine":"European","category":"Main","ingredients":["2 cleaned capons","1 carrot (1–2 pieces)","1 parsley root","1 leek","1 onion","100 g pork fatback (orig. ¼ funt; historical measure, converted approximately)","to taste salt","to taste allspice","3 bay leaves (3–4 leaves)","4 cloves (4–5 pieces)","500 ml bouillon (500–625 ml; orig. 2–2½ szklanki; historical measure, converted approximately)","5 truffles (5–6 pieces)","50 ml rum (orig. 1 kieliszek; historical measure, converted approximately)","50 ml red wine (orig. 1 kieliszek; historical measure, converted approximately)","50 ml olive oil (orig. 1 kieliszek; the method confirms equal volumes of olive oil, wine, and rum; historical measure, converted approximately)","to taste portable soup cake (a piece; the source does not specify the weight)"],"steps":["Cut the carrot, parsley root, leek, and onion.","Cut the fatback into slices.","Line the bottom of a casserole with the vegetables and part of the fatback.","Place the capons on the vegetables.","Cover the capons with the remaining fatback.","Add the salt, allspice, bay leaves, and cloves.","Pour in the bouillon.","Braise, covered, until the meat is tender.","Cut the capons into portions.","Cut the truffles into slices.","Pour the wine, rum, and olive oil over the truffles.","Add the portable soup cake and the braising juices from the capons.","Bring the sauce to a boil.","Pour the truffle sauce over the capons."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kap%C5%82ony_z_sosem_truflowym","page":"Kucharka litewska (1913)/Kapłony z sosem truflowym"},{"id":"oc-plws-550046","title":"Capuchin-style spice liqueur","cuisine":"European","category":"Drink","ingredients":["2.5 l spirit (orig. 1 litre for soaking the roots, plus one and a half litres (1.5 l) of plain spirit added to the syrup)","140 g sweet-flag rhizome (orig. 14 dekagrams of sweet-flag root)","140 g myrrh (orig. 14 dekagrams of myrrh)","140 g cinnamon (orig. 14 dekagrams of cinnamon)","80 g angelica root (orig. 8 dekagrams of angelica)","300 g dried orange peel (orig. 30 dekagrams of dried orange peel)","100 g saffron (orig. named twice in the printing: 8 dekagrams (80 g) and 2 dekagrams (20 g))","10 g nutmeg (orig. 1 dekagram of nutmeg)","40 g cloves (orig. 4 dekagrams of cloves)","40 g ginger (orig. 4 dekagrams of ginger)","1 vanilla pod (orig. 1 large vanilla pod)","4 small green oranges (orig. 4 small unripe bitter oranges)","2.5 kg sugar (orig. 2.5 kilograms of crushed sugar)","1.25 l water (orig. 1.25 litres of cold water)"],"steps":["Combine 1 l of the best spirit with 140 g of sweet-flag rhizome, 140 g of myrrh, 140 g of cinnamon, 80 g of angelica root, 300 g of dried orange peel, 100 g of saffron, 10 g of nutmeg, 40 g of cloves, 40 g of ginger, 1 large vanilla pod and 4 small green oranges. Leave to soak for exactly 3 days.","After 3 days, strain the infusion off the roots through soft white flannel.","Bring a syrup to the boil from 2.5 kg of crushed sugar and 1.25 l of cold water, then leave it to cool completely.","Slowly pour 1.5 l of plain spirit and the strained spice infusion into the completely cold syrup, stirring constantly. Leave for 60 minutes, then filter through paper, bottle, cork, seal with wax, and leave for a year before serving."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_kapucy%C5%84ski","page":"Doświadczone sekreta smażenia konfitur i soków/Likier kapucyński"},{"id":"oc-plws-552234","title":"Caramel ice cream","cuisine":"European","category":"Dessert","ingredients":["280 g sugar (orig. a quarter kilogram (250 g) for caramelizing, plus 2 tablespoons (30 g) for beating with the yolks)","1250 ml whipping cream (thick: 1 l of boiling cream for the caramel, plus 250 ml (a quarter litre) of cold cream for the yolks)","4 egg yolks (count)"],"steps":["Put 250 g of sugar into a heavy pan and heat it until it caramelizes to a light brown. Then pour in 1 litre of boiling thick cream gradually, stirring constantly until the caramel has dissolved, and cool it.","Beat four egg yolks with two tablespoons (30 g) of sugar and 250 ml of cold cream until thick, then combine with the cooled caramel cream.","Heat the mixture over very low heat, stirring all the time, until it thickens. Do not let it boil.","Cool the caramel cream completely, pour it into an ice-cream maker, and freeze it (about 2–3 hours)."],"time":200,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_karmelkowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody karmelkowe"},{"id":"oc-plws-579413","title":"Carp fried in a rusk coating","cuisine":"European","category":"Main","ingredients":["1600 g carp (orig. 4–5 funty; 1600–2000 g, lower bound used)","to taste salt","2 eggs","6 rusks (crushed; orig. 6–7 rusks; lower bound used)","30 ml butter (orig. 2 tbsp; for frying the fish and parsley)","to taste parsley leaves"],"steps":["Scale and gut the carp.","Split the carp and rinse it.","Cut the fish into portions.","Score the skin along the back.","Sprinkle the fish with salt.","Set aside to absorb the salt.","Pat the fish dry.","Beat the eggs.","Crush the rusks.","Dip the carp pieces in the eggs.","Coat the fish in the crushed rusks.","Heat most of the butter.","Fry the carp until golden brown.","Fry the parsley in the remaining butter.","Serve the carp sprinkled with the parsley."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Karp%E2%80%99_opiekany","page":"Kucharka litewska (1913)/Karp’ opiekany"},{"id":"oc-plws-579412","title":"Carp in red wine, with scales","cuisine":"European","category":"Main","ingredients":["1600 g carp with scales and reserved blood (orig. 4–5 funty; 1600–2000 g (historical measure, converted approximately))","to taste salt","1 pinch ground cinnamon (orig. a pinch)","4 cloves (4–5 pieces; pounded.)","750 ml red wine (orig. 1 bottle; approximate conversion)","62.5 ml vinegar (orig. ¼ szklanka)","500 ml strong bouillon with soup vegetables (orig. ½ kwarta (historical measure, converted approximately))","50 ml olive oil (orig. 1 kieliszek; approximate conversion)","1 lemon","5 sugar lumps (5–6 lumps; size not specified.)"],"steps":["Split the gutted carp with its scales left on and cut it into pieces, reserving the blood.","Arrange the fish together with the blood in a pot.","Sprinkle with salt, cinnamon, and pounded cloves.","Cut the lemon into slices.","Add the wine, vinegar, bouillon with soup vegetables, olive oil, lemon, and sugar.","Cook, covered, over high heat until the fish is cooked and the sauce has reduced."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Karp%E2%80%99_w_winie_czerwonem%2C_z_%C5%82usk%C4%85","page":"Kucharka litewska (1913)/Karp’ w winie czerwonem, z łuską"},{"id":"oc-plwb-15666","title":"Carrot and honey salad (Surówka marchwiowa z miodem)","cuisine":"European","category":"Salad","ingredients":["4 carrots","4 tbsp raisins","3 tsp honey","0.25 tsp hot ground paprika"],"steps":["Peel the carrots, grate on a very fine grater, and mix with the hot paprika.","Parboil the raisins for 2 minutes in 250 ml of water and drain.","Combine the grated carrot with the raisins, drizzle with honey, and mix thoroughly.","Squeeze excess liquid from the salad and let rest for 5 minutes before serving."],"time":17,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sur%C3%B3wka_marchwiowa_z_miodem","page":"Książka kucharska/Surówka marchwiowa z miodem"},{"id":"oc-plws-542840","title":"Cauliflower with butter and rusks","cuisine":"European","category":"Side","ingredients":["2 cauliflower (orig. 2–3 heads; lower bound used)","to taste salt","15 ml butter (orig. 1 tbsp)","2 rusks (crushed)","to taste vinegar (for rinsing; amount not specified)","to taste water (for rinsing and boiling; volume not specified)"],"steps":["Remove the cauliflower leaves.","Divide the cauliflowers, checking inside the florets.","Rinse the cauliflowers in water with vinegar.","Boil the cauliflowers in boiling salted water.","Drain the cauliflowers in a sieve.","Brown the butter with the crushed rusks.","Arrange the cauliflowers on a platter with the florets facing up.","Pour the butter and rusks over the cauliflowers."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kalafjory","page":"Kucharka litewska (1913)/Kalafjory"},{"id":"oc-plwb-57966","title":"Cepeliny (Lithuanian stuffed potato dumplings)","cuisine":"European","category":"Main","ingredients":["20 large potatoes (15 boiled and 5 raw)","to taste salt","500 g beef tenderloin","1 tbsp beef suet","1 clove garlic","to taste black pepper","to taste marjoram","to taste butter (melted, or sour cream for serving)"],"steps":["Finely mince the beef tenderloin and beef suet with a knife, add the garlic mashed with salt, black pepper, and marjoram, and knead into a smooth filling.","Wash and peel 5 large raw potatoes, grate them, and squeeze out the juice into a bowl. Once the starch settles at the bottom, pour off the liquid and return the starch to the grated potatoes.","Mash 15 cooked large potatoes thoroughly, combine with the raw potato mixture, season with salt, and knead into a cohesive dough.","Shape portions of dough into large apple-sized balls, flatten, fill with a portion of the meat filling, and seal into large oval dumplings.","Lower the cepeliny into boiling salted water, simmer for 30 minutes, remove with a slotted spoon, and serve drizzled with melted butter."],"time":75,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cepeliny","page":"Książka kucharska/Cepeliny"},{"id":"oc-plws-474258","title":"Chestnut Preserves","cuisine":"European","category":"Preserve","ingredients":["1 kg sweet chestnuts (orig. a kilo of chestnuts)","1.5 kg sugar (750 g for the first syrup, the rest for subsequent boilings; orig. one and a half kilos of sugar.)","to taste water (For soaking, boiling, and the syrup; amount not specified.)","to taste vanilla (orig. with a large piece of vanilla; piece size not specified.)","to taste benzoin (The source does not specify the dose; to_taste indicates an unspecified amount rather than seasoning to taste.)"],"steps":["Soak the raw chestnuts in water for several hours, i.e., several hundred minutes.","Peel off the outer shells of the chestnuts.","Boil the chestnuts in water.","Remove the thin inner skins, taking care not to break the chestnuts.","Arrange the chestnuts in a jar or pot.","Boil a thick syrup from 750 g of sugar, water, and vanilla.","Leave the syrup to cool.","Pour the cold syrup over the chestnuts and set aside for 2880 minutes.","Pour off the syrup and boil it with part of the remaining sugar.","Cool the syrup until lukewarm.","Pour it over the chestnuts again and set aside for another 2880 minutes.","Pour off the syrup and boil it with the rest of the sugar until very thick.","Add the benzoin.","Pour the hot syrup over the chestnuts.","Once completely cooled, cover and tie the jar."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Konfitury%2C_kompoty_i_inne_konserwy_owocowe/Kasztany","page":"Konfitury, kompoty i inne konserwy owocowe/Kasztany"},{"id":"oc-plws-39076","title":"Chestnut Purée with Whipped Cream (Kasztany z bitą śmietaną)","cuisine":"European","category":"Dessert","ingredients":["1 l 30% heavy cream (orig. 1 kwarta of thick sweet cream, for whipping)","200 g icing sugar (orig. half a funt of sifted sugar, for the cream)","to taste vanilla (for the cream)","800 g fresh sweet chestnuts (orig. 2 funty, for the chestnut mixture)","400 g sugar (orig. 1 funt, for the chestnut mixture)","1 tsp potato starch (orig. 1 teaspoon of potato starch, for the chestnut mixture)","1 tbsp 30% heavy cream (for the chestnut mixture)","to taste water (for boiling the chestnuts)"],"steps":["In a cool place, whip the thick cream with the sifted icing sugar and vanilla, skimming off the whipped foam with a spoon and draining any liquid that collects at the bottom.","Cover the fresh chestnuts with water, boil until tender, drain, and carefully peel off the skins.","Mash the hot chestnuts and press them through a fine colander or sieve, just like potatoes.","Thoroughly mix the sieved chestnuts with the sugar, potato starch, and 1 tablespoon of cream.","Mound the whipped cream in the centre of a serving platter, then press the chestnut mixture through a wire sieve or potato ricer directly onto the platter in a ring around the whipped cream."],"time":65,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kasztany_z_bit%C4%85_%C5%9Bmietan%C4%85","page":"365 obiadów za 5 złotych/Kasztany z bitą śmietaną"},{"id":"oc-plws-1081041","title":"Chestnut torte","cuisine":"European","category":"Cake","ingredients":["150 g butter (orig. 12 łutów young butter)","50 g sweet almonds (orig. 4 łuty)","150 g roasted sweet chestnuts (orig. 12 łutów after roasting and peeling)","200 g icing sugar (orig. half a funt)","7 egg yolks","7 egg whites","15 g butter and breadcrumbs for the tin"],"steps":["Rub the roasted, peeled sweet chestnuts through a fine sieve.","Beat the soft butter until fluffy, and add the ground almonds, the rubbed chestnuts and the icing sugar.","Without changing the direction of beating, add the yolks one at a time and beat for 20 minutes in all.","Whip the whites to a stiff foam. Fold the chestnut mixture gently into the foam (add the mixture to the foam, not the other way round).","Turn the batter into a buttered, crumbed springform tin, bake at 175 °C for 30 minutes, and serve warm, dusted with icing sugar or finished with icing."],"time":70,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Torcik_z_kasztan%C3%B3w","page":"Baby, placki i mazurki/Torcik z kasztanów"},{"id":"oc-plws-568708","title":"Chestnuts Candied in Sugar","cuisine":"European","category":"Snack","ingredients":["500 g sweet chestnuts (fine, large)","375 g sugar (for the caramel syrup)","125 ml water (0.5 glass for the syrup, plus water for boiling the chestnuts and cold water with ice)"],"steps":["Place 500 g of chestnuts into a pot of cold water, boil until tender, and then remove one at a time from under the lid to peel them while still hot.","Boil a thick, nearly browned caramel syrup from 375 g of sugar and 125 ml (0.5 glass) of water.","Drop the hot peeled chestnuts into the boiling syrup and toss thoroughly to coat them in the glaze.","Remove the chestnuts one by one with a wooden skewer, dip for a split second in cold water with ice, and arrange side by side on a porcelain platter for immediate serving."],"time":75,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Kasztany_sma%C5%BCone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Kasztany smażone w cukrze"},{"id":"oc-plwb-18776","title":"Chicken breast with bell peppers in curry sauce (Pierś kurczaka z papryką)","cuisine":"European","category":"Main","ingredients":["200 g chicken breast fillet","1 red bell pepper","1 yellow bell pepper","1 green bell pepper","to taste curry powder (generous amount)","to taste salt","2 tbsp vegetable oil (for frying)","100 ml water (to make a little sauce)"],"steps":["Wash the chicken breast, cut into cubes, season with salt, and sauté in hot oil until tender.","Wash the red, yellow, and green bell peppers, remove the seeds, and cut the flesh into strips.","Add the pepper strips and curry powder to the chicken and fry together briefly.","Pour in a little water to form a light sauce and simmer covered until the peppers are tender."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pier%C5%9B_kurczaka_z_papryk%C4%85","page":"Książka kucharska/Pierś kurczaka z papryką"},{"id":"oc-plwb-61767","title":"Chicken in creamy mushroom sauce","cuisine":"European","category":"Main","ingredients":["700 g chicken breast fillet","2 clove garlic","2 tbsp olive oil","0.75 tsp poultry seasoning","0.33 tsp salt","1 pinch black pepper","150 g white mushrooms or other mushrooms","150 ml vegetable broth","150 ml whipping cream 30%","1 tbsp plain flour","1 tbsp vegetable oil","1 tsp fresh dill or parsley (chopped, optional)"],"steps":["Dice the chicken breast fillet, mix with the pressed garlic, salt, pepper, poultry seasoning, and olive oil, and set aside to marinate for at least 60 minutes.","Heat the vegetable oil in a pan and sear the marinated chicken for 2 minutes.","Add the sliced mushrooms and fry everything together for another 3 minutes.","Pour in the vegetable broth and the whipping cream whisked with the flour, and simmer over low heat for 5 minutes until the sauce is thick and creamy.","Scatter over the chopped dill or parsley before serving."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_w_sosie_pieczarkowym","page":"Książka kucharska/Kurczak w sosie pieczarkowym"},{"id":"oc-plwb-14303","title":"Chilled creamy zucchini soup","cuisine":"European","category":"Soup","ingredients":["500 g zucchini","1 onion","2 potatoes","125 ml milk","1 tbsp potato starch","to taste chives","2 tbsp olive oil","500 ml water","to taste salt","to taste pepper"],"steps":["Wash the zucchini, trim the ends, shave a few thin ribbons or slices for serving, and dice the remainder. Peel and dice the potatoes, and peel and slice the onion into rings.","Heat the olive oil in a frying pan, sauté the onion, add the diced zucchini, and cook, stirring, for 5 minutes.","Transfer the vegetables to a pot, pour in the milk and 500 ml of water, add the potatoes, season with salt and pepper, and simmer covered for 25 minutes.","Blend the soup until silky smooth, stir in the potato starch, and cook over low heat for 10 minutes, stirring constantly.","Cool the soup thoroughly and serve garnished with the reserved zucchini slices and chopped chives."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kremowy_ch%C5%82odnik_z_cukinii","page":"Książka kucharska/Kremowy chłodnik z cukinii"},{"id":"oc-plwb-18617","title":"Chilled lemon mousse","cuisine":"European","category":"Dessert","ingredients":["1 vanilla sugar (packet)","1 lemon","2 eggs","1 whipping cream 30% (container)","4 tsp gelatin","6 tbsp sugar"],"steps":["Separate the egg whites from the yolks. Beat the yolks with the sugar and vanilla sugar until pale and thick.","Scald the lemon with boiling water, finely grate the zest and squeeze the juice, then add both to the beaten yolks.","Dissolve the gelatin in a small amount of hot water, allow to cool slightly, and stir into the yolk mixture.","In separate bowls, whip the egg whites until stiff and whip the cream, then gently fold both into the lemon mixture.","Spoon the mousse into dessert dishes and refrigerate until set."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krem_cytrynowy","page":"Książka kucharska/Krem cytrynowy"},{"id":"oc-plws-39046","title":"Chilled moulded wine sago dessert (sago na winie z formy)","cuisine":"European","category":"Dessert","ingredients":["200 g sago pearls (orig. 1/2 Polish funt)","1 l hot water (to cook the sago)","250 ml white or red wine (orig. 1 szklanka)","0.5 lemon (for juice)","180 g sugar (orig. nearly 1/2 Polish funt)","1 tsp grated orange zest","1 tsp olive oil (to grease the mould)","1 orange (cut into segments)","100 ml pineapple or punch syrup (for drizzling before serving)"],"steps":["Cook the sago in plenty of hot water for about 15–20 minutes until translucent, then pour off excess water.","Add the wine to the cooked sago, squeeze in juice from half a lemon, add sugar and grated orange zest, and simmer over low heat for about 10 minutes until very thick.","Spoon the hot mixture into a lightly oiled mould and chill for about 3 hours (180 minutes) until firmly set.","Before serving, unmould onto a platter, arrange orange segments around, and drizzle with pineapple or punch syrup."],"time":225,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sago_z_formy_na_zimno","page":"365 obiadów za 5 złotych/Sago z formy na zimno"},{"id":"oc-plws-39058","title":"Chilled Semolina Pudding with Nuts and Cream Skins (Kaszka z orzechami na zimno)","cuisine":"European","category":"Dessert","ingredients":["300 g walnuts or hazelnuts (orig. 3/4 funt of any nuts)","4 bitter almonds (orig. several pieces)","to taste water (for blanching and sprinkling the nuts while grinding)","1 l 30% heavy cream (orig. 1 kwarta)","250 ml semolina (orig. 1 kwaterka (approximately 180 g), or fine buckwheat groats)","100 g sugar (orig. 1/4 funt (plus a little for sprinkling the cream skins))","to taste whole-fruit preserves (for garnishing before serving)"],"steps":["Blanch the nuts and bitter almonds in boiling water, peel off their skins, and pound them in a mortar or grind into a fine paste, sprinkling with a little water to keep them from releasing oil.","Heat the whipping cream over very low heat and carefully lift off the skins as they form into a separate dish.","Once you have collected enough cream skins, stir the semolina or fine buckwheat groats into the remaining cream and cook into a loose porridge.","Add the ground nuts and sugar to the cooked porridge and mix thoroughly.","Layer the porridge onto an ovenproof platter (optionally bordered with a pastry rim), alternating it with the reserved cream skins dusted with sugar.","Place the platter into a warm oven preheated to 140–150 °C for a dozen or so minutes, then let cool and garnish with whole-fruit preserves before serving."],"time":85,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kaszka_z_orzechami_na_zimno","page":"365 obiadów za 5 złotych/Kaszka z orzechami na zimno"},{"id":"oc-plwb-22488","title":"Chleb na młodziach (Old Polish yeast bread)","cuisine":"European","category":"Bread","ingredients":["8 l flour (warmed, dry)","2 l milk (or water)","50 g fresh yeast (fresh)","to taste salt"],"steps":["Mix the warmed dry flour with the milk and yeast.","Add salt, knead the dough, and leave in a warm place to rise.","Shape loaves on a pastry board and set aside for a second rise.","Place the risen loaves into a hot oven and bake until the crust is crisp and golden brown, brushing the top with water during baking."],"time":105,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_na_m%C5%82odziach","page":"Książka kucharska/Chleb na młodziach"},{"id":"oc-plwb-22482","title":"Chleb na pyrach (Greater Poland sourdough potato bread)","cuisine":"European","category":"Bread","ingredients":["4 kg rye flour","1 kg potatoes","50 g fresh yeast (fresh)","2 l water (1.5–2.5 l water, buttermilk, or soured milk)","to taste sourdough starter (leftover dough from previous baking)"],"steps":["Pour part of the water over the sourdough starter and leave in a warm spot for 1440 minutes.","Peel the potatoes, boil until tender, mash thoroughly, and pour in the remaining water.","Add some of the rye flour and the yeast to the potatoes, mix the resulting loose sponge with the prepared sourdough starter, and leave overnight.","Gradually add the remaining rye flour, knead the dough thoroughly, and leave in a warm spot to rise for about 180 minutes.","Shape into a loaf and bake for 120 minutes in a preheated oven."],"time":180,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_na_pyrach","page":"Książka kucharska/Chleb na pyrach"},{"id":"oc-plwb-22492","title":"Chleb na ziemniakach (Polish potato bread with coriander)","cuisine":"European","category":"Bread","ingredients":["1 kg wheat flour","500 g potatoes","40 g fresh yeast (fresh)","300 ml milk","300 ml water","0.5 tsp ground coriander","to taste salt"],"steps":["Peel the potatoes, boil until tender, drain, steam off moisture, and mash thoroughly.","Combine the wheat flour with salt and ground coriander, pour in the yeast dissolved in 100 ml of lukewarm water, and set aside for the sponge to rise.","Warm the milk with the remaining 200 ml of water, add along with the potatoes to the flour, and knead into a smooth dough.","Cover the dough and leave to rise for 90 minutes, then knead it again and shape a loaf on a baking sheet or in a baking tin.","Rest for 10 minutes, then bake the bread in an oven preheated to 225 °C for 45 minutes."],"time":75,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_na_ziemniakach","page":"Książka kucharska/Chleb na ziemniakach"},{"id":"oc-plws-1080964","title":"Chleb pytlowy na drożdżach (Bolted rye bread made with hop yeast)","cuisine":"European","category":"Bread","ingredients":["1 dried hops (orig. 1 handful of dry hops)","500 ml water (orig. half a historical Polish kwarta of water for the hop decoction (plus water for mixing the dough and pouring over the loaves))","17 l bolted rye flour (orig. 1 kwarta (1 l) for scalding with hops, 2 garnce (8 l) for the sponge, and 2 garnce (8 l) for kneading the dough)","1 sourdough starter (orig. an egg-sized piece of dough reserved from a previous baking)","125 ml salt (orig. półkwaterek of salt)","to taste caraway seeds (a little, optional)"],"steps":["Boil a handful of dried hops in half a kwarta (500 ml) of water, then strain the boiling decoction through a sieve into a pot to scald 1 kwarta (1 l) of the rye flour, beating the mixture for 30 minutes.","Once cooled to lukewarm, add an egg-sized piece of raw bread dough from a previous baking, knead thoroughly until lump-free, and leave in a warm place overnight.","The next day, mix 2 garnce (8 l) of the rye flour with the prepared hop yeast and lukewarm water, stir well, and leave in a warm place to rise.","Once the sponge has risen and begins to drop slightly, add a półkwaterek (125 ml) of salt and a little caraway, work in the remaining 2 garnce (8 l) of rye flour, knead the dough very thoroughly, and leave in the trough for 3 hours to rise.","Shape into small loaves and set them to rise again on boards or in floured bowls, brushing the loaves with warm water.","Before sliding into a hot oven (about 210 °C), pour boiling water over the loaves, space them apart, and bake for 1–1.5 hours until the loaves feel light in the hand.","Immediately after removing from the oven, brush the crust with clean water using a pastry brush."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Chleb_pytlowy_na_dro%C5%BCd%C5%BCach","page":"Baby, placki i mazurki/Chleb pytlowy na drożdżach"},{"id":"oc-plwb-22551","title":"Chleb razowy z ziarnami (seeded wholemeal sourdough bread)","cuisine":"European","category":"Bread","ingredients":["1.5 l water (or milk)","2 tbsp salt","2 tbsp honey","1 tbsp sugar","to taste sourdough starter","2 l spelt flour (or 1.25 l wholewheat flour and 750 ml wholemeal rye flour)","250 ml sunflower seeds","250 ml pumpkin seeds","250 ml sesame seeds","250 ml rolled oats","250 ml flaxseed","250 ml wheat bran","250 ml toasted buckwheat groats (toasted)","250 ml walnuts","190 ml prunes","125 ml raisins (pre-soaked)"],"steps":["Prepare the sourdough starter by mixing a portion of dough from the previous bake with water and resting for 1440 minutes.","Combine the water, sunflower seeds, pumpkin seeds, sesame seeds, rolled oats, flaxseed, wheat bran, buckwheat groats, walnuts, prunes, soaked raisins, salt, honey, and sugar in a large bowl.","Add the spelt flour and sourdough starter and mix to form a thick dough.","Divide the dough between two loaf tins lined with baking paper and leave overnight to rise.","Bake the bread in an oven preheated to 180 °C for 90–105 minutes, and after unmoulding, brush the hot loaves with water."],"time":135,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_razowy_z_ziarnami","page":"Książka kucharska/Chleb razowy z ziarnami"},{"id":"oc-plwb-22506","title":"Chleb turecki (sweet honey bread, also called żulik)","cuisine":"European","category":"Bread","ingredients":["1 kg plain flour","100 g natural honey","100 g sugar","250 ml milk (plus 2 tbsp for brushing)","3 eggs","50 g butter (melted)","60 g fresh yeast (fresh)","50 g raisins","30 g ground almonds","1 pinch salt"],"steps":["Sift and gently warm the plain flour, then mix the yeast with natural honey, half of the milk, and a little flour, setting aside to rise.","Beat the eggs with sugar (reserving a little egg for brushing), pour in the remaining milk, combine with the risen sponge, and knead with the rest of the flour.","Gradually incorporate the melted butter while kneading thoroughly, finishing with the raisins and salt.","Shape the dough into logs, place them into greased loaf tins up to 3/4 of their height, cover, and rest in a warm place for 60 minutes to rise.","Brush the risen loaves with the reserved egg beaten with a little milk, sprinkle with ground almonds, and bake in a thoroughly preheated oven."],"time":85,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_turecki","page":"Książka kucharska/Chleb turecki"},{"id":"oc-plwb-22499","title":"Chleb w cieście (savory Polish bread in egg batter)","cuisine":"European","category":"Breakfast","ingredients":["to taste stale bread (several thin slices)","375 ml milk","2 eggs","to taste plain flour (to pancake batter consistency)","to taste salt","to taste cooking fat"],"steps":["Separate the egg yolks from the whites, then whisk the yolks with milk, salt, and plain flour into a thin pancake-style batter.","Beat the egg whites to stiff peaks and gently fold into the prepared batter.","Dip the thin slices of stale bread into the batter and fry on both sides in hot cooking fat until golden brown."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_w_cie%C5%9Bcie","page":"Książka kucharska/Chleb w cieście"},{"id":"oc-plwb-22495","title":"Chleb wiejski (Greater Poland country whey rye bread)","cuisine":"European","category":"Bread","ingredients":["16 kg rye flour","5 l whey (or buttermilk)","3 l whole milk","125 g fresh yeast (fresh)","to taste salt"],"steps":["Knead a dough from 12 kg of rye flour, the whey, whole milk, and yeast, and leave in a warm spot to rise for 300 minutes.","Add the remaining 4 kg of rye flour and salt, knead the dough again, and rest for 30 minutes.","Shape the risen dough into 4 loaves, wait 15 minutes, and bake in a hot oven."],"time":135,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_wiejski","page":"Książka kucharska/Chleb wiejski"},{"id":"oc-plwb-22497","title":"Chleb z dyni (Greater Poland sourdough pumpkin rye bread)","cuisine":"European","category":"Bread","ingredients":["1.5 kg pumpkin (1–2 kg)","7 kg rye flour (6–8 kg)","100 g fresh yeast (fresh)","120 ml rye sourdough starter","to taste buttermilk (or soured milk)"],"steps":["Boil the pumpkin until tender, then rub through a sieve or blend with buttermilk.","Add part of the rye flour, rye sourdough starter, and yeast to the pumpkin, stir, and leave overnight (720 minutes).","Add the remaining rye flour, knead the dough thoroughly, and set aside to rise for 120–180 minutes.","Shape into loaves and bake in a preheated oven for 90 minutes."],"time":135,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_z_dyni","page":"Książka kucharska/Chleb z dyni"},{"id":"oc-plwb-22496","title":"Chleb żytni (rye bread with whey)","cuisine":"European","category":"Bread","ingredients":["4 kg rye flour","200 g fresh yeast (fresh)","2.8 l whey (or water)"],"steps":["Dissolve the yeast in whey with a portion of the rye flour, cover, and leave in a warm place overnight.","Add the remaining rye flour to the risen pre-ferment, knead into a thick dough, and set aside to rise.","Divide the risen dough into portions, shape loaves, arrange on a baking sheet, and rest briefly in a warm spot.","Bake the loaves for 120 minutes, then sprinkle the hot bread with cooled boiled water after removing it from the oven."],"time":160,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_%C5%BCytni","page":"Książka kucharska/Chleb żytni"},{"id":"oc-plws-1080961","title":"Chleb żytni na kwasie (Polish sourdough rye bread)","cuisine":"European","category":"Bread","ingredients":["250 ml raw bread dough (orig. 1 glass of raw dough reserved from a previous baking to dry as starter)","13 l rye flour (orig. 3 garnce (12 l) for the main dough, plus about 1 kwarta (1 l) for drying the starter and making the evening sponge)","1 l water (orig. 1 historical Polish kwarta of warm water for refreshing the starter overnight)","3 l whey (orig. 3 historical Polish kwarty of whey, water, or fresh milk)","3 tsp salt (orig. 1 teaspoon per garniec of flour)","to taste caraway seeds (or dill, optional)"],"steps":["To prepare the dry sourdough starter (at least 3 days in advance), crumble a glass of raw bread dough and rub it thoroughly with enough rye flour to form a dry, flour-like powder; transfer to a linen bag and dry in an airy place.","In the evening, tip the dried starter into a bowl, pour in a kwarta (1 l) of warm water, and mix with enough rye flour to make a batter as thick as sour cream; cover and leave in a warm place overnight until doubled in volume.","In the morning, sift 3 garnce (12 l) of rye flour into a kneading trough, set half aside for adding later, and into the other half pour 3 kwarty (3 l) of whey, water, or milk, add all the risen overnight starter and 3 teaspoons of salt, and beat thoroughly.","Leave the sponge in a warm place for 3 hours to rise.","Gradually work in the reserved half of the rye flour, along with optional caraway or dill, kneading thoroughly and vigorously. Leave in a warm place to rise again.","Shape into medium loaves (traditionally the loaves were proved by floating them in a trough of warm water until they rose to the surface, then scalded with boiling water) or leave to rise on a floured board.","Place the loaves in a hot oven (about 210 °C) and bake for 1 hour. After 30 minutes, pour hot water over the tops so the baked crust will be glossy."],"time":60,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Chleb_na_kwasie","page":"Baby, placki i mazurki/Chleb na kwasie"},{"id":"oc-plwb-22498","title":"Chlebki twarożkowe (small farmer's cheese loaves)","cuisine":"European","category":"Bread","ingredients":["250 g farmer's cheese","500 g plain flour","1 tbsp butter","1 egg","1 baking powder (packet)"],"steps":["Sift the plain flour with the baking powder, add the farmer's cheese, butter, and some of the egg (reserving a little yolk for brushing), and knead thoroughly.","Chill the kneaded dough in a cool place for about 30 minutes.","Roll the dough into a log, slice into equal portions, and shape each into a small loaf.","Arrange the rolls on a greased baking sheet, brush the tops with the reserved egg yolk, and bake in a preheated oven until golden brown."],"time":70,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chlebki_twaro%C5%BCkowe","page":"Książka kucharska/Chlebki twarożkowe"},{"id":"oc-plwb-18819","title":"Chocolate and walnut truffles (Trufle czekoladowo-orzechowe)","cuisine":"European","category":"Dessert","ingredients":["240 g walnuts (shelled)","100 g yeast cake (ciasto drożdżowe) (crumbled)","250 g sugar","2 lemons (juice of both and grated zest of half)","50 ml rum","60 g chocolate","125 ml milk","30 g desiccated coconut"],"steps":["Grind the shelled walnuts and mix them with the crumbled yeast cake and sugar.","Add the rum, the juice squeezed from two lemons, and the grated zest of half a lemon.","Warm the milk, melt the chocolate in it, pour into the dry ingredients, and knead into a pliable paste.","Shape the mixture into balls about 4 cm in diameter, roll each in desiccated coconut, and arrange on a platter to dry."],"time":65,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Trufle_czekoladowo-orzechowe","page":"Książka kucharska/Trufle czekoladowo-orzechowe"},{"id":"oc-plws-552229","title":"Chocolate ice cream","cuisine":"European","category":"Dessert","ingredients":["375 g dessert or dark chocolate (grated, orig. one and a half quarters of a kilogram of vanilla chocolate)","2 l whipping cream (hot, orig. 2 litres)","10 egg yolks (count)","500 g icing sugar or caster sugar (orig. half a kilogram of fine sugar)"],"steps":["Grate the chocolate and pour 2 litres of hot whipping cream over it, stirring constantly until the chocolate has dissolved completely.","Beat ten yolks with fine sugar in a pan to a pale, fluffy mass.","Set the pan of yolks over very low heat and pour in the hot chocolate cream gradually, beating with a whisk all the time, until the mixture thickens. Do not let it boil.","Strain the cream through a sieve, cool it thoroughly, pour it into an ice-cream maker, and freeze it (about 2–3 hours)."],"time":200,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_czekoladowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody czekoladowe"},{"id":"oc-plws-1081045","title":"Chocolate torte on Karlsbad wafers","cuisine":"European","category":"Cake","ingredients":["5 round wafer sheets (orig. Karlsbad wafers (opłatki))","100 g chocolate (orig. a quarter funt)","100 g sugar (orig. a quarter funt)","30 ml whipping cream (30%) (orig. 2 łyżki)","5 g butter (orig. a small łyżeczka)"],"steps":["Mix broken or grated chocolate, sugar, sweet cream and a teaspoon of butter in a small saucepan.","Cook the mixture over low heat, stirring all the time, until it has reduced by half and starts to pull into a thick mass.","Take it off the heat and, while it is still hot, spread it with a knife over round wafer sheets, stacking them on a plate lined with paper.","Cover with the last wafer, pour the remaining chocolate over the top and sides of the little torte, and leave it to set."],"time":30,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Torcik_czekoladowy_na_op%C5%82atkach_karlsbadzkich","page":"Baby, placki i mazurki/Torcik czekoladowy na opłatkach karlsbadzkich"},{"id":"oc-plwb-21474","title":"Chokeberry bread pudding","cuisine":"European","category":"Cake","ingredients":["200 g wheat bread","500 ml black chokeberries (aronia)","1 lemon","100 g sugar","1 tbsp butter","2 tbsp breadcrumbs","125 ml milk","1 egg"],"steps":["Whisk the milk with the egg in a wide shallow bowl and soak the slices of wheat bread in this mixture.","Rinse the chokeberries, toss with the sugar, and combine with the peeled, pureed lemon.","Butter a baking dish generously and dust with breadcrumbs.","Layer the soaked bread and chokeberry mixture alternately in the dish, ending with a layer of bread, and pour any remaining egg-milk mixture over the top.","Bake in an oven preheated to 180 °C for about 30 minutes."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_z_aroni%C4%85","page":"Książka kucharska/Ciasto z aronią"},{"id":"oc-plws-1081073","title":"Choux Pastry Almond Squares","cuisine":"European","category":"Cookie","ingredients":["200 g butter (originally half a funt of clarified or fresh butter, plus a little for greasing the baking sheet)","500 ml water (originally half a kwarta (historical Polish measure))","2.5 tbsp sugar (a scant tablespoon for the water, a tablespoon for the batter, and sugar for sprinkling with the almonds)","300 g wheat flour (originally half a kwarta (500 ml) of fine flour)","7.5 eggs (orig. 1 whole egg for the hot paste and 6–7 eggs after cooling)","50 g sweet almonds (finely chopped, for sprinkling on top)"],"steps":["Bring the water, butter, and a scant tablespoon of sugar to a boil in a saucepan.","Gradually add the wheat flour over low heat, stirring vigorously with a spoon for several minutes until the paste thickens and pulls away from the sides of the pan.","Transfer the hot paste to a bowl, immediately beat in one egg, and once cooled, beat in the remaining 6–7 eggs one at a time, thoroughly beating the batter with a spoon each time along with an additional tablespoon of sugar.","Spread the dough in a thin layer on a greased baking sheet, cut into large squares with a knife and sprinkle generously with chopped almonds mixed with sugar.","Place the baking sheet into a hot oven (210 °C) and bake for about 20–25 minutes until the squares puff up high and turn golden brown."],"time":55,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciasto_parzone","page":"Baby, placki i mazurki/Ciasto parzone"},{"id":"oc-plws-39075","title":"Choux pastry for doughnuts, rings, and cream puffs (Ciasto parzone)","cuisine":"European","category":"Other","ingredients":["500 ml water (orig. 1/2 kwarta)","200 g butter (orig. 1 kwaterka)","300 g plain wheat flour (orig. 1/2 kwarta)","8 eggs","1 tbsp sugar (plus extra for dusting)","1 pinch salt"],"steps":["In a saucepan, bring 500 ml of water to a boil with the butter and a pinch of salt.","Gradually pour the wheat flour into the boiling liquid, beating vigorously over the heat for several minutes until the paste pulls away from the sides of the pan into a smooth ball.","Remove the pan from the heat, let cool slightly, then beat in the eggs one at a time along with the sugar, mixing thoroughly after each egg until smooth and glossy.","Pipe rings or round puffs onto a greased baking sheet and bake in an oven preheated to 200 °C for about 20–25 minutes (or drop spoonfuls into hot fat and fry until golden)."],"time":55,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ciasto_parzone","page":"365 obiadów za 5 złotych/Ciasto parzone"},{"id":"oc-plws-39478","title":"Choux Pastry Soup Dumplings (Kluski parzone)","cuisine":"European","category":"Side","ingredients":["125 ml butter (orig. half a kwaterka (approximately 115 g))","250 ml water (orig. 1 kwaterka)","250 ml wheat flour (orig. 1 kwaterka (approximately 160 g))","2.5 egg (orig. 2–3 whole eggs)","to taste broth (boiling, for cooking the dumplings)"],"steps":["Bring the water and butter to a boil in a small saucepan.","Dump all the wheat flour into the boiling liquid at once and stir vigorously over low heat until the dough forms a smooth ball and pulls away from the sides of the pan.","Remove the pan from the heat and let the mixture cool slightly, then beat in the eggs one at a time, mixing until completely smooth after each addition.","Drop small spoonfuls of the choux batter into boiling broth and cook over low heat until the dumplings float and puff up."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kluski_parzone","page":"365 obiadów za 5 złotych/Kluski parzone"},{"id":"oc-plws-548329","title":"Christmas Eve Kutia (Wheat Berry and Poppy Seed Pudding)","cuisine":"European","category":"Dessert","ingredients":["250 g whole wheat berries (orig. 25 dkg)","200 g poppy seeds (orig. 20 dkg)","1.5 l water (cold water for soaking and boiling the wheat plus boiling water for scalding the poppy seeds)","100 g sugar or honey (to taste)"],"steps":["Soak the whole wheat berries in cold water overnight, and scald the poppy seeds with boiling water in a separate bowl and leave overnight as well.","The next day, boil the soaked wheat berries in fresh water until completely tender, then drain.","Drain the poppy seeds, pat them dry, and pass twice through a meat grinder fitted with a fine plate.","Mix the ground poppy seeds with the cooked wheat berries and sweeten to taste with sugar or honey."],"time":585,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kutja_wiligijna","page":"109 potraw/Kutja wiligijna"},{"id":"oc-plws-1081028","title":"Christmas Eve Makagigi-Style Honey Mazurek (Mazurek miodowy na podobieństwo makagigi)","cuisine":"European","category":"Cake","ingredients":["250 ml honey (orig. 1 kwaterka raw honey)","0.5 orange (peel from half an orange)","150 ml grated wholemeal bread (orig. a generous half kwaterka grated wholemeal bread (approx. 80 g))","6 cloves (pounded and sifted)","1 pinch mace (a small piece, pounded and sifted)","4 wafer sheets (thick sheets (opłatki))"],"steps":["Boil the peel from half an orange until tender, trim away the bitter white pith (albedo), and chop finely.","Caramelize 250 ml (1 kwaterka) of honey in a stoneware or heavy-bottomed saucepan until golden brown.","Stir the chopped orange peel, 150 ml of grated wholemeal bread, and the pounded, sifted cloves and mace into the hot honey, then bring briefly to a boil together.","Pour the hot mixture onto thick wafer sheets, leave until completely set and hardened, and then slice diagonally into diamonds."],"time":55,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Mazurek_miodowy_na_podobie%C5%84stwo_makagigi_(na_wilj%C4%99)","page":"Baby, placki i mazurki/Mazurek miodowy na podobieństwo makagigi (na wilję)"},{"id":"oc-plwb-18333","title":"Chrzanica (Polish Podhale horseradish soup)","cuisine":"European","category":"Soup","ingredients":["3.5 tbsp grated horseradish (3–4 tbsp)","150 g smoked pork belly","150 g kiełbasa (Polish sausage)","150 g smoked highland pork","250 ml thick sour cream","1 tbsp plain flour","1 tsp lemon juice","4 eggs","to taste salt","to taste black pepper"],"steps":["Bring water to a boil in a pot with the smoked pork belly, kiełbasa, and smoked highland pork, simmer until the meats are tender, then remove them from the broth.","Whisk the thick sour cream with plain flour, stir into the broth, and simmer until the soup thickens.","Add the grated horseradish and lemon juice, then season the soup to taste with salt and black pepper.","Dice the cooked pork belly, kiełbasa, and smoked pork, and return them to the soup.","Hard-boil the eggs, peel them, and serve in the hot chrzanica."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chrzanica","page":"Książka kucharska/Chrzanica"},{"id":"oc-plwb-24368","title":"Chłodnik litewski (Lithuanian cold beetroot soup)","cuisine":"European","category":"Soup","ingredients":["1 bunch young beet greens with baby beetroots","1 beetroot","to taste radishes","2 cucumbers","1 bunch dill","1 clove garlic","1 l kefir (or buttermilk)","500 ml plain yogurt (or sour cream)","to taste salt","to taste black pepper"],"steps":["Finely chop the young beet greens and baby beetroots, cut the peeled beetroot into thin strips, add a little water, boil for about 20 minutes, and leave to cool.","Peel and finely dice the cucumbers, slice the radishes, chop the dill, and press the garlic.","Combine the cooled broth, including the beetroot and beet greens, with the kefir and plain yogurt.","Add the cucumbers, radishes, dill, and garlic, season with salt and black pepper, stir well, and chill in the refrigerator before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ch%C5%82odnik_litewski","page":"Książka kucharska/Chłodnik litewski"},{"id":"oc-plwb-18671","title":"Chłodnik ogórkowy (Polish cold cucumber soup)","cuisine":"European","category":"Soup","ingredients":["500 g cucumbers","1 bunch parsley leaves","3.5 celery (3–4 stalks)","1 clove garlic","500 ml vegetable broth","250 ml plain yogurt","2 tbsp butter","1 tbsp plain flour","to taste lemon juice","to taste salt","to taste black pepper"],"steps":["Peel the cucumbers, halve lengthwise, scrape out the seeds with a spoon, and dice the flesh, then finely chop the parsley leaves and celery.","Melt the butter in a saucepan, add the prepared vegetables, and cook for 3–4 minutes.","Dust the vegetables with plain flour, stir, pour in the hot vegetable broth, and simmer for 5 minutes over low heat.","Let the broth cool, then blend until smooth and velvety.","Stir in the plain yogurt, add the pressed garlic, season with lemon juice, salt, and black pepper, and chill thoroughly before serving."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ch%C5%82odnik_og%C3%B3rkowy","page":"Książka kucharska/Chłodnik ogórkowy"},{"id":"oc-plwb-19270","title":"Chłodnik po polsku (traditional Polish cold beetroot soup)","cuisine":"European","category":"Soup","ingredients":["2 beetroots","2 eggs","200 g chicken meat (for cooking)","1 cucumber","10 radishes","1 l soured milk","to taste fresh dill","to taste parsley leaves","to taste salt"],"steps":["Wash and boil the beetroots until tender, then cool, peel, and grate on a coarse box grater.","Cook the chicken meat and chop finely, and hard-boil the eggs, peel, and dice into chunks.","Peel the cucumber and cut it into thin strips, grate the radishes, and finely chop the dill and parsley leaves.","Whisk the soured milk, stir in all prepared ingredients with the herbs, season to taste with salt, and serve well chilled."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ch%C5%82odnik_po_polsku","page":"Książka kucharska/Chłodnik po polsku"},{"id":"oc-plwb-12169","title":"Ciapkapusta (Silesian mashed potatoes with sauerkraut)","cuisine":"European","category":"Side","ingredients":["1 kg sauerkraut","1 kg potatoes","4 onion","200 g smoked bacon","50 g pork fatback","to taste salt","to taste black pepper"],"steps":["Rinse the sauerkraut and boil until tender in a separate pot, while boiling the peeled potatoes in another pot.","Peel and finely dice the onion, and cut the smoked bacon and pork fatback into small cubes.","Render the pork fatback in a skillet, add the smoked bacon and diced onion, and fry until golden.","Drain and finely chop the cooked sauerkraut, combine with the mashed potatoes and the fried bacon and onion, mix well, and season to taste with salt and black pepper."],"time":55,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciapkapusta","page":"Książka kucharska/Ciapkapusta"},{"id":"oc-plwb-32250","title":"Ciasteczka maślane (Polish vanilla butter cookies)","cuisine":"European","category":"Cookie","ingredients":["200 g butter","390 g plain flour","190 ml icing sugar","1 egg","1 tbsp vanilla sugar","1 tsp baking powder","1 pinch salt"],"steps":["Chop the butter into the plain flour, icing sugar, egg, vanilla sugar, baking powder, and salt with a knife, then quickly knead into a smooth dough.","Chill the dough in the refrigerator for 15–20 minutes to firm up slightly.","Shape the dough into small balls, arrange on a baking sheet lined with baking paper, and flatten with the bottom of a glass.","Bake in an oven preheated to 200 °C for 8–9 minutes until the edges are lightly golden, then allow to firm up on the sheet before removing."],"time":39,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasteczka_ma%C5%9Blane","page":"Książka kucharska/Ciasteczka maślane"},{"id":"oc-plwb-18078","title":"Ciasteczka różane (Polish rose petal shortbread cookies)","cuisine":"European","category":"Cookie","ingredients":["500 g plain flour","300 g butter","100 g sugar","200 g almonds (chopped)","2 egg yolks","2 tsp baking powder","200 g icing sugar","to taste rose water","to taste rose petal preserve"],"steps":["Cream the butter with a mixer, then beat in the egg yolks, sugar, chopped almonds, plain flour, and baking powder, kneading into a smooth dough.","Roll out the dough on a pastry board and cut out cookies.","Bake for about 20 minutes in an oven preheated to 170 °C.","After removing from the oven, sprinkle the cookies with rose water, sandwich with rose petal preserve, and dust with icing sugar."],"time":45,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasteczka_r%C3%B3%C5%BCane","page":"Książka kucharska/Ciasteczka różane"},{"id":"oc-plwb-16428","title":"Ciastka andrzejkowe (Polish St. Andrew's Day fortune cookies)","cuisine":"European","category":"Cookie","ingredients":["100 g plain flour","100 g sugar","100 g butter","1 vanilla sugar (packet)","4 egg whites","50 ml water (for boiling a thick syrup (corrected from 500 ml))"],"steps":["Stir the sugar into the water, boil into a syrup, and set aside to cool.","Cream the cooled syrup with the butter and vanilla sugar, then add the egg whites and plain flour, mixing thoroughly.","Preheat the oven to 180 °C. Spoon thin rounds of batter onto a baking sheet lined with baking paper and bake for about 10 minutes.","Remove the baking sheet, let the cookies cool slightly, place fortune papers onto the warm rounds, and fold into crescent shapes.","Bake the shaped cookies for another 5 minutes at 180 °C."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciastka_andrzejkowe","page":"Książka kucharska/Ciastka andrzejkowe"},{"id":"oc-plwb-21748","title":"Ciasto drożdżowe (Polish sweet yeast cake)","cuisine":"European","category":"Cake","ingredients":["500 g wheat flour","75 g fresh yeast","250 ml milk","3 eggs","100 g sugar","50 g butter","2 tbsp vegetable oil","0.5 tsp salt","to taste raisins (optional)"],"steps":["Warm the milk slightly, sift the flour with salt into a bowl, and make a well in the centre.","Crumble the fresh yeast into the well, add a pinch of sugar, pour in some warm milk, stir with a little flour, and leave the starter for 15–20 minutes.","Melt the butter in a saucepan and beat the egg yolks with the remaining sugar until pale.","Combine the flour and risen starter with the beaten egg yolks and remaining warm milk, kneading into a smooth dough.","Work in the melted butter and vegetable oil, knead until the dough comes away cleanly from your hands, shape into a ball, cover, and let rise for 30–120 minutes.","Punch down the dough, knead in the raisins, transfer to a baking tin, brush the top with egg white, and bake for 40 minutes in an oven preheated to 180 °C."],"time":100,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_dro%C5%BCd%C5%BCowe","page":"Książka kucharska/Ciasto drożdżowe"},{"id":"oc-plwb-62044","title":"Ciasto kruche (shortcrust pastry with streusel)","cuisine":"European","category":"Cake","ingredients":["100 g wheat flour","50 g potato starch","80 g sugar","80 g butter","1 egg","16 g vanilla sugar","1 tsp baking powder","150 g wheat flour","100 g sugar","100 g butter","16 g vanilla sugar"],"steps":["Sift 100 g of wheat flour with the potato starch and baking powder, add 80 g of sugar, 80 g of butter, the egg, and a packet of vanilla sugar, and knead quickly into a shortcrust base dough.","In a separate bowl, rub together the streusel crumble ingredients: 150 g of wheat flour, 100 g of sugar, 100 g of butter, and the second packet of vanilla sugar.","Place both prepared doughs in the refrigerator to chill for 30 minutes.","Line a baking tin with the chilled base dough, crumble the streusel evenly across the top, and bake for 60 minutes in an oven preheated to 175 °C."],"time":105,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_kruche","page":"Książka kucharska/Ciasto kruche"},{"id":"oc-plwb-21738","title":"Ciasto na pierogi (pierogi dough)","cuisine":"European","category":"Other","ingredients":["375 g plain wheat flour","190 ml hot water","60 ml cold water","1 egg (optional)","0.5 tsp salt"],"steps":["Sift the wheat flour into a large mixing bowl and combine with the salt.","Gradually pour in the hot water while stirring with a wooden spoon, then leave to rest for 10 minutes.","Add the cold water and egg, mix with the spoon, and let rest again for 10 minutes.","Turn the dough onto a floured board and knead by hand for about 5 minutes until soft and supple.","Roll the dough out thinly, cut out circles with a glass, spoon filling into the centres, pinch the edges closed, and boil the pierogi in salted boiling water until they float."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_na_pierogi","page":"Książka kucharska/Ciasto na pierogi"},{"id":"oc-plwb-22189","title":"Ciasto ze śliwkami (Polish plum cake)","cuisine":"European","category":"Cake","ingredients":["500 g węgierka plums (prune plums)","300 g wheat flour","4 eggs","200 g butter","150 g icing sugar","1 pinch salt","2 tsp baking powder","to taste vanilla flavouring"],"steps":["Wash and dry the węgierka plums, halve each one, and remove the stones.","Whip the egg whites with a pinch of salt until stiff peaks form, then gradually beat in the icing sugar followed by the egg yolks one by one.","Melt the butter in a saucepan, mix the wheat flour with the baking powder, and add alternating spoonfuls of butter and flour to the egg mixture along with the vanilla flavouring, stirring continuously.","Pour the batter into the prepared tin, arrange the plum halves on top skin-side down, and bake for 50 minutes in an oven preheated to 180 °C."],"time":70,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_ze_%C5%9Bliwkami","page":"Książka kucharska/Ciasto ze śliwkami"},{"id":"oc-plwb-19269","title":"Cielęcina litewska (Lithuanian-style roast veal)","cuisine":"European","category":"Main","ingredients":["2 kg boneless veal leg (hind leg)","1 carrot","1 parsley root","1 onion (large)","0.5 celeriac","3 tbsp spicy mustard","100 g fatback","to taste salt","1 tbsp butter","20 g wheat flour (approximately 20 g for thickening the sauce (corrected from 1 tsp))","250 ml sour cream (1 cup (250 ml))"],"steps":["Peel the carrot, parsley root, and celeriac and grate them, and peel and finely chop the onion.","Mix the prepared vegetables with the spicy mustard, rub all over the veal, place in an earthenware crock, press down with a plate, and chill for 3 days.","Season the marinated veal with salt, lard it with the fatback strips, and transfer to a roasting pan greased with butter.","Roast in an oven preheated to 200 °C for 10 minutes, then lower the temperature to 180 °C and roast for another 80 minutes, basting with melted butter and the juices from marinating.","Shortly before the end of roasting, pour over the sour cream mixed with the wheat flour and bake for a few minutes."],"time":120,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciel%C4%99cina_litewska","page":"Książka kucharska/Cielęcina litewska"},{"id":"oc-plwb-2594","title":"Ciulim (Lelów potato and meat bake)","cuisine":"European","category":"Main","ingredients":["2 kg potatoes","1 kg pork ribs","6 poultry wings (preferably goose wings)","3 onion","200 g raw pork belly","200 g lard","to taste salt","to taste black pepper","1 pinch ground paprika","to taste ground ginger","to taste marjoram"],"steps":["Cut the ribs into small pieces, prepare the poultry wings, rub the meat with salt, pepper, and ginger, and set aside for about 120 minutes.","Peel the potatoes and grate them.","Dice the raw pork belly and onion, then fry them together in some of the lard until the onion is golden.","Combine the grated potatoes with the fried pork belly and onion, and season the mixture with salt, pepper, paprika, and marjoram.","Grease a pot with the remaining lard and layer the potato mixture alternating with the ribs and poultry wings.","Bake slowly in an oven preheated to about 100 °C for 480 minutes (preferably overnight) and serve hot."],"time":510,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciulim","page":"Książka kucharska/Ciulim"},{"id":"oc-plws-1081058","title":"Classic Puff Pastry","cuisine":"European","category":"Other","ingredients":["400 g wheat flour (originally 1 funt)","1 egg (whole egg)","1 tbsp vinegar or rectified spirit","150 ml water (cold, enough to make the dough supple without sticking to the rolling pin)","400 g butter (originally 1 funt, chilled in cold water and squeezed dry)"],"steps":["Wash the butter in very cold water and leave it in the water for an hour, then squeeze firmly in a cloth to remove excess water and roll out through the cloth into a square about 2.5 cm thick.","Knead a smooth, elastic dough from the flour, egg, a tablespoon of vinegar or spirit, and cold water, and let rest on the board for about fifteen minutes.","Roll out the dough in a cool place to the thickness of a finger, place the square of butter in the center, and fold the edges of the dough over it like an envelope.","Roll out the dough carefully in one forward motion away from yourself to a thickness of about 1 cm, fold into three or four layers, and set aside in a cool place for 10 minutes.","Repeat the rolling, folding, and 10-minute chilling a total of four times.","Roll out the finished pastry, shape your pastries, and bake in a very hot oven (220 °C) for about 15–20 minutes."],"time":150,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciasto_francuskie","page":"Baby, placki i mazurki/Ciasto francuskie"},{"id":"oc-plws-42458","title":"Classic puff pastry for savoury pies, small filled pastries, or sweet pastries","cuisine":"European","category":"Bread","ingredients":["400 g plain wheat flour (orig. 1 funt + a little for dusting)","400 g butter (orig. 1 funt)","1 egg","150 ml cold water (for kneading a supple dough)"],"steps":["An hour (60 minutes) before making the pastry, work the butter in cold water to wash out excess salt, leave it in cold water to firm up, then pat thoroughly dry in a cloth and shape into a flat block about 2.5 cm thick.","Knead a smooth, supple dough from the wheat flour, egg, and cold water, work it on a pastry board, and let it rest for a dozen or so minutes.","In a cool room, flatten the dough, set the block of cold butter in the centre, and fold the edges of the dough over it like an envelope.","Roll the pastry out carefully in a single forward motion to a thickness of about 1.2 cm, fold in three, and chill in a cool place for 10 minutes.","Repeat the rolling, three-fold turn, and 10-minute chilling four times.","Always place savoury pies, small filled pastries, or sweet pastries made from this dough directly into a very hot oven (210–220 °C) and bake for about 20–25 minutes until flaky layers form."],"time":155,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ciasto_francuzkie_do_pasztetu%2C_pasztecik%C3%B3w%2C_lub_ciastek","page":"365 obiadów za 5 złotych/Ciasto francuzkie do pasztetu, pasztecików, lub ciastek"},{"id":"oc-plws-1081049","title":"Classic Vanilla Meringues","cuisine":"European","category":"Cookie","ingredients":["12 egg whites (whites)","400 g icing sugar (originally 1 funt of sugar sifted through a fine sieve)","0.5 vanilla pod (pounded and sifted)"],"steps":["Sift the icing sugar mixed with the pounded half vanilla pod through a fine sieve.","Whip twelve egg whites to very stiff peaks.","Without stopping whipping, slowly add the vanilla icing sugar a little at a time until all of it is incorporated and the meringue is thick and glossy.","Spoon portions of the meringue onto a baking sheet lined with parchment paper.","Place the baking sheet into a preheated low oven (110–120 °C), dry for about 60 minutes, then turn off the oven and leave the meringues inside until the next day to dry completely."],"time":570,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Marengi_zwyczajne","page":"Baby, placki i mazurki/Marengi zwyczajne"},{"id":"oc-plws-38730","title":"Clear beef broth (rosół wołowy czysty)","cuisine":"European","category":"Soup","ingredients":["2 kg bone-in beef for broth (orig. 5 Polish funty (1 funt per person for a rich broth or 1/2 funt for a lighter one))","3 l water (cold spring or filtered water)","3 parsley root (orig. 5 thin or 3 thicker)","1 celeriac (quartered)","2 leeks","2 carrots","1 onion (unpeeled)","2 dried mushrooms (orig. 1–2 whole)","1 pinch mace","2 tbsp fresh flat-leaf parsley (finely chopped, for tureen)","to taste salt"],"steps":["Rinse the beef thoroughly in cold water, place in a pot, cover with 3 l of fresh cold water, salt, and simmer very gently for about 60 minutes, regularly skimming the scum.","Once no more scum forms, remove the pot from the heat, add 1 tbsp of cold water, skim off excess fat, and strain the broth through a fine sieve. Rinse the meat and return it to a clean pot with the strained broth.","Bring the broth back to a boil and add the parsley roots, celeriac, leeks, carrots, the whole onion roasted in its skin, dried mushrooms, and mace.","Simmer the broth over very low heat for another 2.5–3 hours (150–180 minutes) until the meat and vegetables are thoroughly tender.","Before serving, take the pot off the heat briefly, skim off the remaining surface fat, and strain the clear broth into a tureen containing chopped parsley."],"time":250,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ros%C3%B3%C5%82_lub_bulion_czysty","page":"365 obiadów za 5 złotych/Rosół lub bulion czysty"},{"id":"oc-plwb-19476","title":"Cocoa jam cake","cuisine":"European","category":"Cake","ingredients":["500 g wheat flour","2 tsp baking soda","250 ml milk (1 cup (250 ml))","100 g sugar (1/2 cup (125 ml))","2 eggs","250 g margarine (1 block)","2 tbsp cocoa powder","250 g strawberry jam (1 small jar)","to taste orange flavouring"],"steps":["Melt the margarine in a small saucepan, allow to cool, and whisk together with the milk.","Beat the eggs with the sugar until light and fluffy, then pour in the margarine and milk mixture.","Sift the flour with the baking soda and cocoa powder into the egg mixture and stir to incorporate.","Add the strawberry jam and orange flavouring and mix slowly until combined.","Pour the batter into a baking pan and bake for about 45 minutes in an oven preheated to 180 °C."],"time":60,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_z_d%C5%BCemem","page":"Książka kucharska/Ciasto z dżemem"},{"id":"oc-plwb-13604","title":"Cod in hazelnut sauce","cuisine":"European","category":"Main","ingredients":["400 g cod fillets","0.5 tsp butter","to taste lemon juice","to taste breadcrumbs","to taste salt","to taste black pepper","150 g hazelnuts","250 ml milk","50 g grated semi-hard cheese","2 tbsp cherry liqueur","to taste nutmeg"],"steps":["Finely chop the hazelnuts, combine them with the grated cheese, milk, and cherry liqueur, and season the sauce with nutmeg, salt, and pepper.","Drizzle the cod fillets with lemon juice, season with salt and pepper, and set aside for a few minutes.","Arrange the fish in a baking dish, pour over the hazelnut sauce, sprinkle with breadcrumbs, and top with shavings of butter.","Place the dish into the preheated oven and bake for about 30 minutes at 180 °C."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Dorsz_w_sosie_orzechowym","page":"Książka kucharska/Dorsz w sosie orzechowym"},{"id":"oc-plws-552233","title":"Coffee ice cream","cuisine":"European","category":"Dessert","ingredients":["2 l whipping cream (fresh and thick, orig. 2 litres)","125 g roasted coffee beans (freshly roasted whole mocha beans, orig. half a quarter kilogram)","10 egg yolks (count)","500 g icing sugar or caster sugar (orig. half a kilogram of fine sugar)"],"steps":["Bring 2 litres of thick cream to the boil, add the whole beans of freshly roasted coffee, cover, and leave it to cool completely so the cream takes on the coffee aroma. Then strain it through a sieve.","Beat ten yolks with fine sugar in a pan, set it over very low heat, and pour in the strained coffee cream gradually.","Beat constantly with a whisk over low heat until the cream has thickened well. Do not let it boil.","Strain the thickened cream through a sieve, cool it, pour it into an ice-cream maker, and freeze it (about 2–3 hours)."],"time":230,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_kawowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody kawowe"},{"id":"oc-plws-550043","title":"Coffee liqueur","cuisine":"European","category":"Drink","ingredients":["1 l spirit (orig. 1 litre of the best spirit)","875 ml water (orig. a quarter litre (250 ml) of boiling water for the spirit, and two and a half szklanki (2.5 szklanki = 625 ml) of cold water for the syrup)","1 vanilla pod (orig. 1 large vanilla pod)","35 mocha coffee beans (orig. 35 mocha beans roasted light brown)","1.25 kg sugar (orig. one and a quarter kilograms of crushed sugar)"],"steps":["Mix 1 l of the best spirit with 250 ml of boiling water, pour it into a demijohn, add 1 large vanilla pod, and leave it in the shade in a warm room for 4 days.","After 4 days, take out the vanilla pod, add 35 mocha beans roasted light brown to the spirit, and leave it for 7 days.","After a week, strain the spirit through white flannel. Cook a syrup from 1.25 kg of crushed sugar and 625 ml of cold water, skim it carefully after a single boil, and cool it completely.","Pour the strained coffee spirit into the cold syrup, mix well, filter it, bottle it, cork it, and keep it in a cool place for 6 months before serving."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_kawowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier kawowy"},{"id":"oc-plwb-18094","title":"Cold green herb soup (Zielony chłodnik)","cuisine":"European","category":"Soup","ingredients":["1 bunch radishes (bunch)","1 English cucumber (medium)","0.5 bunch chives (half a bunch)","0.5 bunch dill (half a bunch)","0.5 bunch parsley leaves (half a bunch)","500 ml plain yogurt","250 ml still mineral water (250 ml)","1 sorrel (handful)","2 clove garlic","3 tbsp vegetable oil (for frying croutons)","to taste soy sauce","2 Kaiser rolls (rolls for croutons)","to taste salt","to taste black pepper"],"steps":["Wash the radishes and cut into half-slices, and peel and finely dice the cucumber.","Rinse the sorrel thoroughly, remove the stems, and finely chop the leaves together with chives, dill, and parsley leaves.","Whisk the yogurt with mineral water, add the chopped vegetables and greens, and season with soy sauce, salt, pepper, and crushed garlic.","Place the soup in the refrigerator to chill.","Dice the Kaiser rolls, fry in hot oil until golden, and serve the croutons with the chilled soup."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zielony_ch%C5%82odnik","page":"Książka kucharska/Zielony chłodnik"},{"id":"oc-plwb-16995","title":"Cold horseradish and yogurt sauce","cuisine":"European","category":"Sauce","ingredients":["3 tbsp mayonnaise","3 tbsp plain yogurt","to taste lemon juice (a few drops)","3 tsp grated horseradish","2 tsp pickled peppercorns","to taste salt","to taste black pepper"],"steps":["Mix the mayonnaise with the plain yogurt in a small bowl, then add the grated horseradish and a few drops of lemon juice.","Combine the ingredients thoroughly, stir in the pickled peppercorns, and season the sauce to taste with salt and black pepper."],"time":5,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_chrzanowy","page":"Książka kucharska/Sos chrzanowy"},{"id":"oc-plwb-7851","title":"Cold horseradish cream sauce","cuisine":"European","category":"Sauce","ingredients":["2 horseradish roots (medium)","0.5 lemon juice (squeezed from half a large lemon)","1 tsp icing sugar","250 ml whipping cream","3 hard-boiled eggs (yolks only)","to taste salt"],"steps":["Grate the horseradish roots on a fine grater, transfer to a fine sieve, pour boiling water over them, and set aside to cool.","Remove the yolks from the hard-boiled eggs and mash them with the lemon juice into a smooth paste.","Add the whipping cream and cooled horseradish to the egg yolks, then season everything to taste with icing sugar and salt.","Wrap the bowl in aluminium foil and chill until the next day (for about 12 hours) so the flavours meld."],"time":600,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_chrzanowy_ze_%C5%9Bmietan%C4%85","page":"Książka kucharska/Sos chrzanowy ze śmietaną"},{"id":"oc-plwb-16835","title":"Cold radish and yogurt soup","cuisine":"European","category":"Soup","ingredients":["3 bunch radishes","200 ml plain yogurt","100 ml whipping cream 30%","1 tbsp fresh herbs (chopped)","to taste lemon juice","to taste salt","to taste pepper"],"steps":["Wash the radishes and trim the ends. Reserve a few for garnish, and chop and blend the remainder with the plain yogurt.","Add a few drops of lemon juice and a pinch of salt to the whipping cream, whip until stiff, and gently fold into the blended yogurt mixture.","Season the cold soup with salt and pepper, stir thoroughly, and chill in the refrigerator.","Ladle into bowls, scatter over the chopped herbs, and garnish with pieces of the reserved radishes."],"time":null,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kremowy_ch%C5%82odnik","page":"Książka kucharska/Kremowy chłodnik"},{"id":"oc-plws-546742","title":"Cold vegetable pâté (pasztet jarzynowy na zimno)","cuisine":"European","category":"Other","ingredients":["200 g dry white beans (orig. 1 szklanka)","5 large potatoes (orig. 5 very large potatoes)","100 g mustard (orig. 10 dkg)","100 g lard or fatback (orig. 10 dkg)","1 egg","1 tsp marjoram","to taste salt"],"steps":["Soak the white beans overnight (for about 8 hours) in cold water, then boil until tender for about 40 minutes and drain.","Boil the potatoes in their skins, peel, and thoroughly mash or pass through a ricer.","Mince the cooked beans in a meat grinder and combine with the mashed potatoes, egg, lard or finely chopped fatback, and mustard.","Season the mixture to taste with salt and marjoram, and knead thoroughly.","Transfer the mixture to a greased pâté mould and cook in a water bath for 90 minutes after the water returns to a boil.","Cool the pâté completely and serve cold with bread."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Pasztet_z_jarzyn_na_zimno","page":"109 potraw/Pasztet z jarzyn na zimno"},{"id":"oc-plwb-21442","title":"Colourful mixed salad (Surówka kolorowa)","cuisine":"European","category":"Salad","ingredients":["1 green lettuce (head)","1 radicchio (head)","2 tomatoes","2 onions","1 bunch radishes","1 cucumber (small)","2 tbsp farmer's cheese","165 ml plain yogurt","2 tbsp parsley (chopped)","2 tbsp vinegar","to taste salt","to taste pepper"],"steps":["Wash and dry the green lettuce and radicchio, then tear the leaves into small pieces.","Slice the cucumber, tomatoes, and radishes into rounds, and cut the peeled onions into rings.","Gently toss the sliced vegetables with the lettuces.","Blend the farmer's cheese with the plain yogurt and chopped parsley, season with vinegar, salt, and pepper, and drizzle the dressing over the salad."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sur%C3%B3wka_kolorowa","page":"Książka kucharska/Surówka kolorowa"},{"id":"oc-plws-451178","title":"Cooked chocolate icing","cuisine":"European","category":"Sauce","ingredients":["400 g grated chocolate (orig. 40 deka)","400 g sugar (orig. 40 deka)","250 ml milk (orig. 1 szklanka)","20 g butter (orig. a small łyżka of sweet cream butter)"],"steps":["Combine the grated chocolate, the sugar, the milk and the butter in a small saucepan.","Cook over low heat, stirring with a spoon the whole time, until the icing is clearly thicker and has a smooth shine.","While it is still warm and pourable, pour it at once over baked babkas, sheet cakes or tortes."],"time":15,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Lukier_czekoladowy","page":"Ciasta wielkanocne/Lukier czekoladowy"},{"id":"oc-plws-544051","title":"Cornelian Cherry Preserves in Wine","cuisine":"European","category":"Preserve","ingredients":["500 g Cornelian cherries (well-ripened, to be pitted)","750 g sugar","500 ml French wine (alternatively a light Hungarian wine)"],"steps":["Pit the Cornelian cherries.","Bring a syrup of the sugar and wine to a boil.","Skim the foam carefully from the syrup.","Add the prepared Cornelian cherries.","Simmer over very low heat for 60 minutes, skimming the foam carefully and removing the pot from the heat while skimming.","Check the thickness of the syrup by placing a drop on a knife.","Set the preserves aside to cool completely once the syrup has thickened.","Transfer into jars.","Store in a cool, dry place."],"time":60,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Dere%C5%84_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Dereń innym sposobem"},{"id":"oc-plwb-14005","title":"Cornflake-crusted chicken cutlets (Pierś z kurczaka inaczej)","cuisine":"European","category":"Main","ingredients":["4 chicken breast fillets (about 600 g)","2 tbsp cornflakes","to taste poultry seasoning","2 tbsp wheat flour","to taste salt","to taste black pepper","2 egg whites","1 tsp sweet ground paprika","4 tbsp vegetable oil (for frying)","to taste parsley leaves and dill (for garnish)"],"steps":["Slice each chicken breast fillet lengthwise into 2 thinner cutlets and season with salt, pepper, poultry seasoning, and sweet paprika.","Finely crush the cornflakes, and lightly beat the egg whites in a shallow bowl.","Dredge the chicken pieces sequentially in wheat flour, beaten egg white, and crushed cornflakes.","Fry the cutlets in hot vegetable oil on both sides until golden, and garnish with sprigs of parsley leaves and dill before serving."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pier%C5%9B_z_kurczaka_inaczej","page":"Książka kucharska/Pierś z kurczaka inaczej"},{"id":"oc-plws-1080963","title":"Country Yeast Bread with Whey","cuisine":"European","category":"Bread","ingredients":["2.4 kg bread flour (orig. 1 garniec (4 l): half for the sponge and half for the dough, plus a little for dusting)","1 l whey (lukewarm, non-sour, originally 1 kwarta (historical Polish measure))","50 g fresh yeast (orig. 4 łut)","1 tbsp salt","to taste water or beer (for brushing the loaves before baking)"],"steps":["Dissolve the yeast in 250 ml of lukewarm, sweet whey, add another 250 ml of whey, and mix with half of the flour (approx. 1.2 kg) to form a loose sponge.","Set the sponge aside in a warm place for about 60 minutes until it is visibly bubbling and active.","Pour in the remaining 500 ml of whey, add the rest of the flour and a tablespoon of salt, knead the dough at length until it pulls away from your hands, and set aside again to rise.","Transfer the risen dough onto a floured board and shape three round, smooth loaves, tucking the edges of the dough underneath.","Set the loaves aside to proof, brushing their surface several times with a pastry brush dipped in water or beer.","Bake in a very hot oven (220–230 °C) for about 50–60 minutes."],"time":360,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Chleb_wiejski_na_dro%C5%BCd%C5%BCach","page":"Baby, placki i mazurki/Chleb wiejski na drożdżach"},{"id":"oc-plwb-21559","title":"Country-style bean and barley soup (Wiejska zupa z fasolą)","cuisine":"European","category":"Soup","ingredients":["250 g white beans","150 g barley groats","1 bunch Polish soup vegetables (włoszczyzna)","300 g bone-in pork","100 g kiełbasa (Polish sausage)","1 onion","2 clove garlic","5 allspice berries (berries)","5 black peppercorns (peppercorns)","5 juniper berries (berries)","1 bay leaf","to taste salt","1 tsp caraway seeds","1 pinch dried marjoram","to taste water (for soaking beans and making broth)"],"steps":["Cover the white beans with water, add the caraway seeds, and leave to soak overnight (about 12 hours), then bring to the boil and set aside.","Cover the bone-in pork with water, add salt, peppercorns, and allspice berries, and bring to the boil.","Add the trimmed soup vegetables, crushed juniper berries, and bay leaf to the broth, and simmer for 60 minutes.","Add the barley groats and parboiled beans to the soup and continue cooking until the ingredients are tender.","Chop the onion and garlic, slice the kiełbasa, fry everything together in a skillet, transfer to the soup pot, season with a pinch of marjoram, and simmer briefly."],"time":600,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wiejska_zupa_z_fasol%C4%85","page":"Książka kucharska/Wiejska zupa z fasolą"},{"id":"oc-plws-544360","title":"Crabapples","cuisine":"European","category":"Preserve","ingredients":["500 g crabapples (freshly picked, not overly ripe, blemish-free)","1.38 kg sugar (500 g on the first day, 750 g on the second day, and 125 g on the third day)","250 ml water (1 glass for the syrup, plus cold water for parboiling and chilling the fruit)"],"steps":["Clean the crabapples, prick with a wooden pin, place in a pan of cold water, and heat very carefully over low heat until slightly softened without bursting.","Drain the parboiled crabapples, cover briefly with cold water, then drain thoroughly on a sieve.","Briefly boil a light syrup from 500 g of sugar and 250 ml (1 glass) of water, cool it, and pour over the crabapples for a day.","On the second day, drain the syrup, add 750 g of sugar, bring to a boil, and pour the warm syrup back over the fruit.","On the third day, drain the syrup, add the remaining 125 g of sugar, bring to a boil, drop in the crabapples for a brief single boil, and transfer to jars once cooled."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82uszka_rajskie","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłuszka rajskie"},{"id":"oc-plws-544361","title":"Crabapples Another Way","cuisine":"European","category":"Preserve","ingredients":["500 g crabapples (fine, not overripe, blemish-free)","750 g sugar (or up to 1 kg if more syrup is desired)","1.5 l water (for the syrup, plus cold, boiling, and ice-cold water with ice for blanching the fruit)","1 tbsp rose syrup or vanilla (optional for aroma)"],"steps":["Trim the crabapple stems in half, prick the fruit deeply with a wooden pin, and submerge in cold water for 15 minutes.","Transfer the crabapples to boiling water for 10 minutes, then remove and submerge in cold water with ice for 30 minutes, and dry thoroughly.","Boil a fairly thick syrup from 750 g of sugar and water (optionally with rose syrup or vanilla), add the dried crabapples, and simmer slowly, skimming carefully.","Remove the fruit onto a platter as each piece softens, and once completely cooled, pack into jars, cover with the syrup, and tie tightly."],"time":105,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82uszka_rajskie_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłuszka rajskie innym sposobem"},{"id":"oc-plws-568696","title":"Crabapples Dried in Sugar","cuisine":"European","category":"Preserve","ingredients":["500 g crabapples (fully ripe, hand-picked from the tree)","600 g sugar (500 g for the syrup and approx. 100 g for the final dusting)","375 ml water (1.5 glasses for the syrup, plus cold and boiling water for scalding the fruit)"],"steps":["Prick the ripe crabapples with a wooden pin, trim the stems in half, and drop into cold water.","Cover the drained fruit with boiling water, let stand for 15 minutes, then rinse again in cold water and drain.","Boil a moderately thin syrup from 500 g of sugar and 375 ml (1.5 glasses) of water, and cook the crabapples in batches, removing the fruit as it softens so that it does not overcook.","Arrange the cooled crabapples on sieves and dry in a very lukewarm oven or in the sun, brushing with a feather dipped in clear syrup and dusting with sugar before the final drying."],"time":215,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82uszka_rajskie_suszone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłuszka rajskie suszone w cukrze"},{"id":"oc-plws-547344","title":"Crabapples pickled in vinegar","cuisine":"European","category":"Preserve","ingredients":["1 kg crabapples (fine, left whole)","1 l vinegar (orig. 1 litre of good vinegar)","750 g sugar (orig. three quarters of a kilogram of sugar)","2 g cinnamon (a piece of bark)","6 cloves (a few)","0.5 vanilla pod (a small piece (optional))","1 l water (boiling, for blanching the crabapples)"],"steps":["Prick the crabapples with a thin wooden pin and blanch them in boiling water.","Bring a syrup to the boil from 1 l of good vinegar, 750 g of sugar, cinnamon, cloves and, if you like, a small piece of vanilla.","Drop the drained crabapples into the boiling vinegar syrup and cook over a moderate heat until soft.","Lift out the soft crabapples and pack them into jars. Reduce the syrup until thick, skimming all the time, cool it, and pour it over the fruit (if after a few days the syrup thins, pour it off, boil it again, and pour it back once cool). Seal the jars and store them in a dry, cool place."],"time":75,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_jab%C5%82uszek_rajskich_w_occie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z jabłuszek rajskich w occie"},{"id":"oc-plws-552231","title":"Cranberry ice","cuisine":"European","category":"Dessert","ingredients":["750 g sugar (orig. three quarters of a kilogram)","1 l water (orig. 1 litre)","15 sweet almonds (blanched, peeled and crushed, orig. a dozen or so)","500 ml freshly pressed cranberry juice (orig. half a litre)"],"steps":["Bring a syrup to the boil from 750 g of sugar and 1 litre of water, adding a dozen or so blanched and crushed sweet almonds to the boiling syrup.","Take the boiled syrup off the heat to cool, then pour in 500 ml of pressed cranberry juice.","Strain the whole thing through thick cloth or a sieve, pour it into an ice-cream maker, and freeze it (about 2–3 hours)."],"time":195,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_%C5%BCurawinowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody żurawinowe"},{"id":"oc-plws-548830","title":"Cranberry Jelly","cuisine":"European","category":"Preserve","ingredients":["1 kg cranberries (picked over and rinsed)","1 kg fine sugar (fine)","50 ml water (for sprinkling the sugar)"],"steps":["Pick over the cranberries to remove leaves and stems, rinse thoroughly, and drain.","Place the fine sugar in a stoneware pan, sprinkle it with the water, and spread the cleaned cranberries on top.","Set the pan over high heat and heat without stirring with a spoon until the berries begin to burst and the syrup bubbles.","Bring the mixture to a boil three times, removing from the heat and skimming off the foam each time, then simmer over low heat for just under 15 minutes.","Strain the hot mixture through a fine sieve or muslin and pour the clear juice into warmed jars."],"time":50,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_%C5%BCurawinowa","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta żurawinowa"},{"id":"oc-plws-44924","title":"Crayfish simmered in red wine (raki w czerwonym winie)","cuisine":"European","category":"Main","ingredients":["30 live crayfish (orig. half kopa (30 pcs))","1 onion (sliced into rings)","1 bunch fresh flat-leaf parsley (part for cooking and part for garnish)","0.5 bunch fresh dill sprigs","250 ml dry red wine (orig. 1 szklanka)","2 pinch salt","2 pinch black pepper"],"steps":["Rinse the crayfish very thoroughly in plenty of cold water and drain.","Place the crayfish into a three-litre pot, add the sliced onion, sprigs of parsley and dill, salt, pepper, and red wine.","Cover the pot tightly and cook over high heat for 10 minutes, shaking the pot several times until the crayfish turn a vivid red.","Discard the cooked onion and herbs, pile the hot crayfish onto a napkin-lined platter, and garnish with fresh parsley."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Raki","page":"365 obiadów za 5 złotych/Raki"},{"id":"oc-plwb-16892","title":"Cream and fruit-custard sponge cake (Tort śmietanowy)","cuisine":"European","category":"Cake","ingredients":["6 eggs","200 g sugar","125 g cake flour","65 g potato starch","1 tsp baking powder","1 tsp vinegar","1 pinch salt","1 l orange and apple juice","400 ml whipping cream","3 custard powder (packets)","4 tsp gelatine","to taste sugar (for the custard)"],"steps":["Beat the egg whites with a pinch of salt and sugar until stiff peaks form, add the egg yolks mixed with vinegar and baking powder, then gently fold in the sifted cake flour and potato starch.","Pour the batter into the tin, bake at 180 °C for about 40 minutes, and once cooled, slice the sponge horizontally into two layers.","Dissolve the custard powder with sugar in 500 ml of the orange-apple juice, pour into the remaining 500 ml of simmering juice, and cook into a thick custard.","Whip the cream until stiff and combine with the dissolved gelatine.","Spread the custard filling over one sponge half, spread most of the whipped cream over the other, and once cooled and set, sandwich the two halves together.","Spread the remaining whipped cream over the top of the cake and refrigerate for about 60 minutes to chill."],"time":145,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tort_%C5%9Bmietanowy","page":"Książka kucharska/Tort śmietanowy"},{"id":"oc-plws-552210","title":"Cream ice","cuisine":"European","category":"Dessert","ingredients":["1.5 l whipping cream (fresh and thick, orig. one and a half litres)","1 vanilla pod (a small pod)","12 egg yolks (count)","500 g icing sugar or caster sugar (orig. half a kilogram of very fine sugar)"],"steps":["Bring 1.5 litres of fresh thick cream to the boil with a split vanilla pod.","Beat 12 yolks with 500 g of very fine sugar in a pan with a whisk until the mass thickens noticeably and turns pale.","Set the pan of yolks over very low heat and pour in the boiling cream gradually, beating with a whisk all the time, until the cream thickens and rises a little. Do not let it boil or the yolks curdle.","Move the pan to a cool place and stir the cream until completely cold. Then pour it into an ice-cream maker and freeze it, stirring every 15 minutes until fully set (about 2–3 hours)."],"time":200,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_%C5%9Bmietankowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody śmietankowe"},{"id":"oc-plwb-34295","title":"Creamy broccoli sauce","cuisine":"European","category":"Sauce","ingredients":["1 broccoli (large head)","1 onion (medium)","0.5 carrot (optional)","0.5 parsley root (optional)","250 ml vegetable broth","2 tbsp butter","1 tsp vegetable oil","to taste water (for parboiling the broccoli)","to taste salt","to taste black pepper","to taste sugar","125 ml sour cream (optional)"],"steps":["Rinse the broccoli, parboil for a few minutes in water with salt and a pinch of sugar, drain, and divide into florets.","Dice the onion, salt it, and set aside for a few minutes to soften, and grate the carrot and parsley root.","Heat the butter and vegetable oil in a deep skillet or wok and cook the onion until tender.","Pour in the vegetable broth, add the grated carrot, parsley root, and broccoli florets, season with black pepper, and simmer for several minutes, stirring occasionally.","Puree the simmered vegetables into a smooth sauce (or leave some florets whole) and stir in the sour cream at the end."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_broku%C5%82owy","page":"Książka kucharska/Sos brokułowy"},{"id":"oc-plws-579506","title":"Crucian carp baked in sour cream","cuisine":"European","category":"Main","ingredients":["2000 g crucian carp (orig. 5 funty)","to taste salt","22.5 ml butter (orig. 1½ tbsp)","375 ml sour cream (orig. 1½ szklanki)","1 rusks (crushed; orig. 1–2 rusks; lower bound used)"],"steps":["Clean and salt the crucian carp.","Fry the fish in the butter until golden brown.","Arrange the fish in an ovenproof dish.","Pour the sour cream over them.","Sprinkle with the crushed rusk.","Bake in the oven until the top is browned.","Serve in the dish in which the fish was baked."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Karasie_zapiekane_w_%C5%9Bmietanie","page":"Kucharka litewska (1913)/Karasie zapiekane w śmietanie"},{"id":"oc-plws-1081003","title":"Crustless Raisin Mazurek (Mazurek rodzynkowy bez ciasta)","cuisine":"European","category":"Cake","ingredients":["200 g sultanas (orig. half a funt Turkish raisins)","200 g Zante currants (orig. half a funt small black Corinthian currants)","200 g sweet almonds (orig. half a funt blanched almonds)","400 g sugar (orig. 1 funt)","100 g potato starch (orig. a quarter funt potato starch)","4 egg (well beaten)","1 tsp warm spices (ground cinnamon, cloves, and mace or nutmeg)","4 wafer sheets (sheets (opłatki), for the base)"],"steps":["Pound in a mortar (or grind) 200 g each of sultanas, currants, and blanched, peeled almonds, grinding them together with 400 g of sugar.","Stir in 100 g of potato starch, pour in 4 well-beaten eggs, add 1 teaspoon of ground warm spices (cinnamon, cloves, nutmeg or mace), and mix thoroughly.","Spread the mixture onto wafer sheets in a 2 cm layer and bake in a moderate oven (175 °C) for about 25 minutes."],"time":55,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Mazurek_rodzynkowy_bez_ciasta","page":"Baby, placki i mazurki/Mazurek rodzynkowy bez ciasta"},{"id":"oc-plws-548805","title":"Currant Jelly Another Way","cuisine":"European","category":"Preserve","ingredients":["4 l currants (ripe, stemmed and rinsed)","250 ml water (for moistening the fruit)","2 kg sugar (chopped into pieces, in a ratio of 1 kg per 1 l of strained juice)"],"steps":["Transfer the stemmed and rinsed currants to a stoneware pan, add 250 ml of water, and heat on a hot stove, stirring, until the berries burst and soften.","Transfer the hot fruit onto a fine sieve and leave until the juice has drained completely.","Measure the volume of the collected juice and weigh out 1 kg of finely chopped sugar for each 1 l of juice.","Place the sugar into a clean pan, pour the strained currant juice over it, and set over very high heat.","Bring the syrup to a boil five times, removing the pan from the heat and thoroughly skimming off the foam each time.","Test a drop on a cold plate to see if the jelly sets, then pour it hot (without straining again) into warmed jars and seal once cooled."],"time":65,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_porzeczkowa_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta porzeczkowa innym sposobem"},{"id":"oc-plws-555186","title":"Czerechy (sour–sweet cherry hybrids) preserved in syrup","cuisine":"European","category":"Preserve","ingredients":["1 kg czerechy (sour–sweet cherry hybrids) (large ripe Kleparów czerechy (or ordinary sweet cherries))","500 g sugar (for a standard sugar syrup)","500 ml water (for the syrup)"],"steps":["Remove the stems from large ripe czerechy, wipe each fruit with a clean cloth, and fill the jars to the top.","Make a standard sugar syrup with 500 g of sugar and 500 ml of water, and pour it over the fruit in the jars.","Seal the jars tightly (originally with a clean cloth and a bladder, or with albumin paper tied with string), stand them in a kettle or a pot of water, and pasteurize for about 20–25 minutes.","Leave the jars in the kettle until the water has cooled completely, and store them in a cool place."],"time":55,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_czerech","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z czerech"},{"id":"oc-plwb-61746","title":"Czernina (Polish duck blood soup)","cuisine":"European","category":"Soup","ingredients":["500 g poultry giblets for broth (poultry giblet broth base)","2 l water","1 celeriac","2 carrots","1 leek","1 parsley root","200 ml duck blood (coagulated or mixed with vinegar)","1 tbsp wheat flour","1 tbsp wine vinegar","1 tsp dried marjoram","4 bay leaves","4 allspice berries (berries)","6 black peppercorns (a few peppercorns)","1 tsp salt","0.5 tsp ground black pepper","1 tsp sugar"],"steps":["Cover the poultry giblets with water, add the trimmed celeriac, carrots, leek, parsley root, bay leaves, allspice berries, and black peppercorns, and simmer into a flavourful broth.","Strain the cooked broth through a sieve.","Whisk the duck blood thoroughly with the wine vinegar and flour, temper with a ladle of hot broth, and pour slowly into the simmering soup while stirring constantly.","Season the soup with salt, ground pepper, sugar, and dried marjoram to achieve a distinct sweet-sour balance, and bring to a brief boil."],"time":85,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Czernina","page":"Książka kucharska/Czernina"},{"id":"oc-plwb-61678","title":"Czosnianka (Highlander garlic soup)","cuisine":"European","category":"Soup","ingredients":["4 potatoes (medium)","2 garlic (2 heads)","2 onion (medium)","1 l vegetable broth","180 g smoked tofu (1 block)","4 bay leaves","5 allspice berries (berries)","1 tbsp dried mint","7 tbsp sour cream 18% (6–8 tbsp (18–22% fat))","to taste salt","to taste freshly ground black pepper"],"steps":["Peel and dice the potatoes and onions, cut the smoked tofu into small cubes, and slice the peeled garlic cloves.","In a soup pot, saute the garlic, onion, some of the smoked tofu, and the dried mint with a pinch of salt until the onion turns translucent.","Add the bay leaves, allspice berries, remaining smoked tofu, and diced potatoes, cover with vegetable broth, and cook until the potatoes are tender.","Take a ladleful of hot soup, mix it with the sour cream, pour it back into the pot, and season to taste with salt and freshly ground pepper."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Czosnianka","page":"Książka kucharska/Czosnianka"},{"id":"oc-plwb-7886","title":"Delicate spring herb sauce (Sos wiosenny delikatny)","cuisine":"European","category":"Sauce","ingredients":["250 ml sour cream (creamy)","250 ml plain yogurt","4 spring onions (small)","1 tbsp dill (measured in a heaped spoonful)","1 tbsp chives (measured in a heaped spoonful)","1 tbsp parsley (measured in a heaped spoonful)","1 tbsp cress (measured in a heaped spoonful)","1 tbsp borage leaves (measured in a heaped spoonful, or young sorrel shoots)","to taste salt","to taste pepper"],"steps":["Finely chop the spring onions, dill, chives, parsley, cress, and young borage or sorrel leaves.","Pour the plain yogurt into a bowl, add the chopped herbs and onions, and fold in the lightly whipped sour cream.","Season the sauce to taste with salt and pepper and let rest for 10 minutes before serving."],"time":20,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_wiosenny_delikatny","page":"Książka kucharska/Sos wiosenny delikatny"},{"id":"oc-plwb-7765","title":"Deluxe button mushroom sauce","cuisine":"European","category":"Sauce","ingredients":["300 g button mushrooms (small)","2 tbsp butter","1 tbsp plain flour","3 tbsp milk","250 ml thick sour cream","to taste salt","to taste white pepper (freshly ground)"],"steps":["Rinse and thoroughly dry the small button mushrooms, then fry them in a saucepan with melted butter for about 5 minutes, shaking the pan often so they brown evenly.","Cover the saucepan and cook the mushrooms gently over low heat for another 5 minutes.","Whisk the flour into the milk until free of lumps, combine with the thick sour cream, and lightly beat until frothy.","Pour the frothed sour cream over the mushrooms, season with salt and freshly ground white pepper, and heat for no more than 3 minutes until the sauce thickens, then serve immediately."],"time":25,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_pieczarkowy_luksusowy","page":"Książka kucharska/Sos pieczarkowy luksusowy"},{"id":"oc-plws-38750","title":"Dill and sour cream white sauce (sos biały z koperkiem)","cuisine":"European","category":"Sauce","ingredients":["1 tbsp plain wheat flour","1 tbsp butter","250 ml meat broth or fish stock","2 tbsp sour cream (orig. a couple tbsp)","1 tbsp fresh dill (finely chopped)","to taste sugar","to taste salt"],"steps":["Melt butter in a saucepan and cook the plain wheat flour into a pale white roux without browning.","Whisk the hot broth or fish stock vigorously into the roux until smooth.","Stir in the sour cream, chopped dill, a pinch of salt, and optional sugar, bring briefly to a boil, and ladle over fricassee or fish."],"time":15,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_bia%C5%82y","page":"365 obiadów za 5 złotych/Sos biały"},{"id":"oc-plws-569437","title":"Domowa biała kiełbasa wieprzowa do smażenia (homemade fresh pork kiełbasa for frying)","cuisine":"European","category":"Main","ingredients":["4 kg pork (half lean pork and half fatty, well-marbled pork)","100 g salt (orig. 10 dag)","1 tbsp marjoram (rubbed)","10 g black pepper (orig. 1 dag, ground)","500 g onion (orig. half a kilo, grated or ground)","625 ml cold water or pork bone stock (orig. 2 to 3 szklanki (500–750 ml))","3 clove garlic (orig. a couple of cloves mashed with salt, optional)","1 thin pork casings (cleaned, for stuffing)"],"steps":["Chop 4 kg of pork (2 kg lean and 2 kg fatty, well-marbled) very finely with a sharp knife.","Add 100 g of salt, a tablespoon of rubbed marjoram, 10 g of black pepper, 500 g of grated onion, and optionally garlic mashed with salt.","Knead the meat for a long time, gradually adding 500 to 750 ml (2–3 szklanki) of cold water or bone stock until the meat absorbs all the liquid.","Stuff the meat mixture into pork casings (not too tightly, so they do not burst during cooking) and prick any air pockets with a fine needle.","Simmer and fry the kiełbasa (Polish sausages) just before serving, or store hanging from a rod in a dry, cool larder."],"time":115,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/Kie%C5%82basy_do_sma%C5%BCenia","page":"Domowe wędliny/Kiełbasy do smażenia"},{"id":"oc-plws-580274","title":"Domowy makaron zapiekany (baked homemade egg noodles with mushrooms)","cuisine":"European","category":"Main","ingredients":["600 g plain wheat flour","1 egg (whole)","0.5 tsp salt (for the dough, plus extra for the boiling water and mushroom filling)","to taste water (enough to knead a firm dough, plus water for boiling)","200 g dried mushrooms (young)","2 onion (chopped)","1 tbsp plain wheat flour (a generous tablespoon for thickening the mushrooms)","to taste black pepper","1 tbsp butter (melted for the noodles, plus extra for the filling, baking dish, and top)","2 eggs (whole, for mixing with the noodles)","to taste breadcrumbs (for dusting the baking dish and sprinkling on top)","to taste hard cheese (grated, sharp, for sprinkling on top)"],"steps":["Knead a very firm dough from the wheat flour, egg, salt, and a small amount of water, roll it out as thinly as possible, let it dry slightly, cut into strips, and shred finely into thin noodles.","Boil the slightly dried noodles in plenty of salted boiling water for about 5 minutes, drain in a colander, and rinse with cold water.","Boil the dried mushrooms in water until tender, about 30 minutes, reserve the broth, slice the mushrooms into strips, and fry them in butter with the chopped onions for 8 minutes.","Sprinkle the mushrooms with the wheat flour, stir in the reserved mushroom broth to make a thick sauce, bring to a boil, and season with salt and pepper.","Toss the cooked noodles with the melted butter and whole eggs.","Butter a shallow baking dish and dust it with breadcrumbs, spread half of the noodles on the bottom, cover with the mushroom filling, and top with the remaining noodles.","Sprinkle the top generously with grated cheese mixed in equal parts with breadcrumbs, dot with pieces of butter, and bake in an oven preheated to 180 °C for about 30 minutes until golden brown."],"time":105,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Domowy_makaron_zapiekany_Farsze%3A_1%2C_2%2C_3%2C_4%2C_5.","page":"100 postnych i jarskich dań/Domowy makaron zapiekany Farsze: 1, 2, 3, 4, 5."},{"id":"oc-plwb-19325","title":"Dorsz po lwowsku (Lviv-style cod meatballs)","cuisine":"European","category":"Main","ingredients":["700 g cod","100 g prunes","125 ml mayonnaise","1 white bread roll","250 ml milk","100 g onion","1 egg","200 ml dry white wine","2 l vegetable broth","to taste salt","to taste black pepper"],"steps":["Soak the prunes in water for 120 minutes, then add the dry white wine, bring to a boil, blend into a smooth puree, and once cooled, stir into the mayonnaise.","Fillet the cod, removing bones and skin, and soak the bread roll in milk, then squeeze out excess liquid.","Mince the cod fillets together with the squeezed bread, chopped onion, and egg, then season the mixture with salt and pepper.","Shape the fish mixture into small meatballs and poach gently in the vegetable broth over low heat for 30 minutes.","Remove the poached meatballs from the broth, spoon over the prune-mayonnaise sauce, and serve warm or chilled."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Dorsz_po_lwowsku","page":"Książka kucharska/Dorsz po lwowsku"},{"id":"oc-plws-555159","title":"Double-steeped canned peeled peaches","cuisine":"European","category":"Preserve","ingredients":["1 kg peaches (ripe, unblemished, peeled carefully)","1.2 kg sugar (about 450 g for the first light syrup and 750 g for the fresh thick syrup in the jars)","1 l water (500 ml for each of the two syrups (plus cold water for heating and for the 24-hour soak))"],"steps":["Peel ripe peaches carefully with a small knife, put them in an earthenware or enamel pan of cold water, and heat over low heat until the water steams (do not let it boil) and the fruit softens.","Transfer the hot peaches to a pan of fresh cold water and leave them there for 24 hours.","The next day, pour off the water, cover the fruit with a light syrup cooked from 450 g of sugar and 500 ml of water, and leave it for another 24 hours.","After a full day, pour off the first syrup (it can be used for compotes or cordials). Pack the peaches whole or halved into jars and cover them with a fresh thick syrup of 750 g of sugar and 500 ml of water.","Seal the jars, stand them in a kettle lined with hay or a cloth, and pasteurize for 25 minutes from the moment the water boils."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_brzoskwi%C5%84%2C_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z brzoskwiń, innym sposobem"},{"id":"oc-plws-546626","title":"Dried fruit compote (suszenina wigilijna)","cuisine":"European","category":"Soup","ingredients":["250 g mixed dried fruit: apples, pears, and prunes (orig. 25 dkg)","100 g sugar (orig. 10 dkg)","3 l water","1 tbsp potato starch (heaping)","3 whole cloves (orig. a few cloves)","1 cinnamon stick"],"steps":["Rinse the dried fruit thoroughly and soak overnight (for about 8 hours) in 3 l of cold water sweetened with sugar.","The next day, chop the plumped fruit into smaller pieces and simmer in the same water together with the cloves and cinnamon stick for about 35 minutes until completely tender.","Mix the potato starch with a little cold water, stir it into the simmering fruit, and bring briefly to a boil while stirring.","Allow the dish to cool completely before serving."],"time":535,"servings":7,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Suszenina","page":"109 potraw/Suszenina"},{"id":"oc-plws-547717","title":"Dried Peeled Pears","cuisine":"European","category":"Preserve","ingredients":["2 kg pears (large, ripe, not overly juicy, of a choice variety)","200 g sugar (for lightly sprinkling the layers under the press)","1 l water (cold, for submerging the peeled pears)"],"steps":["Peel the ripe pears, cut them in half, remove the cores, and drop the fruit immediately into cold water.","Remove the pears from the water, drain, arrange on baking sheets, and place into a lukewarm oven until slightly wilted.","Take out the fruit, smooth each piece by hand, and return to the lukewarm oven.","Pack the still-undried pears tightly in layers in a vessel, sprinkling lightly with sugar, cover with a wooden board, weight down with a stone, and leave under the press for several days.","Remove the pressed pears, finish drying in a lukewarm oven, and pack into dry jars."],"time":240,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_obierane","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki obierane"},{"id":"oc-plws-547718","title":"Dried Peeled Pears (Alternative Method)","cuisine":"European","category":"Preserve","ingredients":["2 kg pears (fully ripe, peeled and cored)","1.5 l water (cold, for soaking and cooking the pears)","250 g sugar (part for cooking in the water, the rest crushed for dusting on top)","300 g thick apple preserve (optional, for stuffing the pears)","2 tsp lemon or orange zest (grated, for mixing with the sugar for dusting)"],"steps":["Peel the ripe pears, remove the cores, and submerge the fruit in cold water.","Cover the drained pears in a pot with fresh cold water and a little sugar, and cook until completely tender (subsequent batches of fruit can be cooked in the same liquid by adding a little water).","Remove the cooked pears, optionally fill the cavities with thick apple preserve, and dry slowly in a very low oven.","Sprinkle the fruit with crushed sugar mixed with grated lemon or orange zest, then finish drying until the candied pears are dry, soft, and translucent."],"time":285,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_obierane_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki obierane innym sposobem"},{"id":"oc-plws-1081027","title":"Dry Walnut Mazurek (Mazurek orzechowy suchy)","cuisine":"European","category":"Cake","ingredients":["400 g wheat flour (orig. 1 funt)","400 g butter (orig. 1 funt fresh butter (plus a little for greasing the baking sheet))","400 g walnuts (orig. 1 funt shelled walnuts or hazelnuts)","400 g sugar (orig. 1 funt)","6 g cinnamon (orig. half a łut (6.25 g), pounded and sifted)","2 egg (whole)","2 egg white (extra)","100 g clear icing (for glazing after cooling)"],"steps":["Knead 400 g of wheat flour with 400 g of fresh butter on a pastry board in a very cool place.","Pound 400 g of shelled walnuts or hazelnuts in a mortar, gradually adding 400 g of sugar.","Combine the flour-and-butter mixture on the board with the nuts pounded with sugar, 6 g of sifted cinnamon, 2 whole eggs, and 2 egg whites, and knead very thoroughly.","Press the shortcrust dough out by hand directly onto a buttered baking sheet (without paper) and bake in a moderate oven (175 °C) for 30 minutes.","Once completely cool, carefully lift the mazurek from the baking sheet and coat with clear icing."],"time":75,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Mazurek_orzechowy_suchy","page":"Baby, placki i mazurki/Mazurek orzechowy suchy"},{"id":"oc-plws-577999","title":"Ducks with brown sauce","cuisine":"European","category":"Main","ingredients":["2 duck (source states 2–3 birds; lower bound used)","15 ml butter (orig. 1 tbsp; for roasting)","to taste salt","15 ml butter (orig. 1 tbsp)","15 ml wheat flour (orig. 1 tbsp)","250 ml bouillon (orig. 1 szklanka; strong)","15 ml capers (orig. 1–2 tbsp; lower bound used)","2 sugar lumps (orig. 2–3 lumps; lower bound used; weight of lumps not specified)"],"steps":["Salt the ducks.","Roast the ducks in a roasting pan in an oven at 180 °C, using the butter reserved for roasting.","Brown the butter reserved for the sauce.","Fry the flour in it, stirring so that no lumps form.","Pour in the bouillon.","Bring the sauce to a boil.","Strain the sauce.","Add the capers and sugar.","Simmer the sauce briefly.","Pour the sauce over the ducks cut into portions."],"time":null,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kaczki_z_sosem_brunatnym","page":"Kucharka litewska (1913)/Kaczki z sosem brunatnym"},{"id":"oc-plws-578003","title":"Ducks with homemade noodles and mushrooms","cuisine":"European","category":"Main","ingredients":["2 duck (source states 2–3 birds; lower bound used)","to taste salt","to taste black pepper","3 cloves (source states 3–4 pieces; lower bound used; crushed)","750 ml wheat flour (orig. 3 szklanki; amount from the ingredient list, differing from the amount in the method)","3 eggs (two for the noodles, one for the stuffing)","2 egg yolks","8 dried porcini mushrooms (source states 8–10 pieces; lower bound used; reserve the cooking broth)","15 ml butter (orig. 1 tbsp)","7.5 ml wheat flour (orig. ½ tbsp)","250 ml sour cream (orig. 1–1½ szklanki; lower bound used)","to taste water (for cooking the mushrooms and noodles; the source does not specify the volume)"],"steps":["Slit the ducks along the back and remove the bones, leaving the leg and wing bones in place.","Season the ducks with salt, pepper, and crushed cloves.","Boil the porcini mushrooms in water, reserving the cooking broth.","Chop part of the cooked porcini for the stuffing, reserving the rest for braising and the sauce.","Knead a noodle dough from 750 ml of flour and two eggs.","Roll out the dough and cut it into noodles.","Boil the noodles in water and drain.","Mix the noodles with the remaining egg, egg yolks, chopped porcini, butter, and salt.","Fill the ducks with the stuffing and sew the openings shut.","Pour the mushroom broth with part of the reserved mushrooms over the ducks in a casserole.","Braise, covered, until tender.","Cut the ducks into portions.","Mix the sour cream with 7.5 ml of flour.","Combine the braising liquid with the sour cream and the remaining sliced mushrooms.","Pour the sauce over the duck portions."],"time":null,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kaczki_z_makaronem_domowym_i_grzybami","page":"Kucharka litewska (1913)/Kaczki z makaronem domowym i grzybami"},{"id":"oc-plws-44945","title":"Dutch-style rice with fatback and tomato sauce (ryż po holendersku)","cuisine":"European","category":"Main","ingredients":["400 g white rice (orig. 1 Polish funt)","1 l cold water (orig. 1 Polish kwarta, for parboiling the rice and fatback)","200 g pork fatback (Name: fresh pork fatback; note: orig. 1/2 Polish funt)","500 ml meat broth or bouillon (orig. 1/2 Polish kwarta)","2 tbsp tomato purée or paste","1 tbsp plain wheat flour","1 tbsp butter","1 pinch crushed black pepper","to taste salt"],"steps":["Cover the rinsed rice with 1 l of cold water, boil for 5 minutes, then drain in a sieve and rinse with cold water.","Parboil the fatback diced into thick cubes for 5 minutes in boiling water, drain, dry the pan, return the fatback, and fry until nicely browned.","Pour 500 ml of broth or bouillon over the browned fatback, add a pinch of crushed black pepper, stir in the parboiled rice, season with salt, and simmer over low heat for 20 minutes, stirring frequently so the rice does not stick.","In a separate saucepan, cook the tomato purée with butter and plain wheat flour into a smooth sauce.","Remove the cooked rice from heat, fold in the tomato sauce, mix thoroughly, and mound onto a serving platter."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ry%C5%BC_po_holendersku","page":"365 obiadów za 5 złotych/Ryż po holendersku"},{"id":"oc-plwb-14175","title":"Easter walnut and chocolate bundt cake (Wielkanocna babka z orzechami i czekoladą)","cuisine":"European","category":"Cake","ingredients":["4 eggs","125 g plain flour","150 g sugar","100 g butter (plus extra for greasing the tin)","1 pinch salt","3 tbsp milk","1 tsp baking powder","150 g walnuts (chopped)","50 g semi-sweet dark chocolate","to taste icing sugar (for dusting)","to taste breadcrumbs (for dusting the tin)"],"steps":["Preheat the oven to 180 °C, and grease a bundt cake tin with butter and dust it with breadcrumbs.","Beat the eggs with the butter, sugar, and a pinch of salt, then add the plain flour, baking powder, and milk, mixing until smooth and combined.","Add the chopped walnuts and finely chopped chocolate, then gently fold into the batter with a spoon.","Pour the batter into the prepared tin and bake for about 60 minutes.","Remove the baked bundt cake from the tin, let cool, and dust with icing sugar before serving."],"time":80,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wielkanocna_babka_z_orzechami_i_czekolad%C4%85","page":"Książka kucharska/Wielkanocna babka z orzechami i czekoladą"},{"id":"oc-plws-501836","title":"Egg croquettes","cuisine":"European","category":"Main","ingredients":["11 eggs (8 hard-boiled, 2 raw for binding, and 1 beaten for breading)","2 tbsp plain wheat flour (for the white sauce, plus extra for dredging)","1 tbsp butter (generous spoonful)","250 ml milk","to taste fresh dill (chopped (or chives))","to taste salt","to taste black pepper","to taste breadcrumbs (for stiffening the mixture and for coating)","to taste lard (or frying oil for deep-frying)"],"steps":["Hard-boil eight eggs for 10 minutes, cool, peel, and chop finely.","Cook two tablespoons of wheat flour with a generous tablespoon of butter without browning, whisk in the milk, and simmer for about 4 minutes, stirring, until a very thick white sauce forms; let cool slightly.","Combine the thick sauce with the chopped hard-boiled eggs, chopped dill, salt, pepper, two raw eggs, and enough breadcrumbs for the mixture to hold its shape firmly.","Shape the mixture into egg-sized oval croquettes and coat each one just before frying in wheat flour, beaten egg, and breadcrumbs.","Deep-fry the croquettes in hot lard for about 3–4 minutes until golden brown and serve immediately."],"time":45,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Krokietki_z_jaj","page":"100 potraw z jaj/Krokietki z jaj"},{"id":"oc-plwb-16504","title":"Egg, mushroom and walnut croquettes","cuisine":"European","category":"Snack","ingredients":["6 eggs","4 white mushrooms","2 tbsp plain flour","5 tbsp breadcrumbs","1 tbsp parsley (chopped)","to taste vegetable oil (for frying)","1 tbsp walnuts (chopped)","to taste salt","to taste pepper"],"steps":["Clean the mushrooms, cut them into small dice, and sauté in heated oil.","Hard-boil 4 of the eggs, cool, peel, and dice them finely.","Combine the sautéed mushrooms with the diced eggs, parsley, and chopped walnuts, crack in 1 raw egg, season with salt and pepper, and mix into a cohesive mixture.","Shape into small oval patties, dredge successively in flour, the remaining beaten egg, and breadcrumbs, then fry in hot oil until golden brown."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krokieciki_z_orzechami","page":"Książka kucharska/Krokieciki z orzechami"},{"id":"oc-plws-508384","title":"Eggs baked in tomatoes","cuisine":"European","category":"Main","ingredients":["10 tomatoes (large, tall)","to taste salt","10 eggs (small, poached)","to taste butter (for melting in the pan)","to taste broth (enough to come halfway up the tomatoes)","to taste hard cheese (sharp, grated)"],"steps":["Poach the small eggs in boiling water for 3 minutes, transfer to cold water, and carefully remove the shells.","Slice the tops off the tomatoes, scoop out the seeds and juice with a spoon, and lightly salt the insides.","Place one peeled poached egg in each hollowed-out tomato and cover with the sliced-off tomato top.","Melt butter in a wide shallow pan, set the stuffed tomatoes side by side, salt lightly on top, and pour in enough broth to reach halfway up their sides.","Braise gently over low heat (or bake in the oven at 180 °C) for about 20 minutes until the broth reduces by half and the tomatoes are tender.","Scatter the hot tomatoes generously with grated sharp cheese and serve in the same dish."],"time":45,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_zapiekane_w_pomidorach","page":"100 potraw z jaj/Jaja zapiekane w pomidorach"},{"id":"oc-plwb-13745","title":"Exquisite button mushroom soup (Wykwintna zupa pieczarkowa)","cuisine":"European","category":"Soup","ingredients":["400 g button mushrooms","1 carrot","200 g broccoli","1 onion","1.5 l vegetable broth (1.5 l)","125 ml sour cream (125 ml)","100 g noodles","1 pinch thyme","to taste nutmeg","to taste lemon juice","2 tbsp butter (for frying)","to taste salt","to taste black pepper"],"steps":["Rinse the mushrooms, cut them into thin slices, and fry in butter until golden.","Peel the carrot and onion, dice them, add to the mushrooms, and fry for a moment longer.","Cover the vegetables with vegetable broth, add the broccoli florets and a pinch of thyme, and simmer over low heat for about 20 minutes.","Cook the noodles separately according to the package instructions and drain.","Stir the sour cream, nutmeg, lemon juice, salt, and pepper into the soup, add the cooked noodles, and heat through."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wykwintna_zupa_pieczarkowa","page":"Książka kucharska/Wykwintna zupa pieczarkowa"},{"id":"oc-plwb-7772","title":"Exquisite tomato sauce","cuisine":"European","category":"Sauce","ingredients":["1 kg ripe tomatoes (large)","1 onion (large)","1 clove garlic (large)","3 tbsp olive oil","1 bay leaf","to taste salt","to taste black pepper","1 tsp sugar (level)","1 tsp mixed herbs (heaped (basil, thyme, sage, oregano))"],"steps":["Scald the tomatoes with boiling water, peel off the skin, and cut into wedges, removing the seeds.","Finely chop the onion and garlic and fry in heated olive oil until light straw-yellow.","Add the tomato wedges, bay leaf, herb mix, sugar, salt, and pepper.","Simmer the sauce over moderate heat for 15 minutes, stirring frequently, and adjust seasoning to taste at the end if needed."],"time":25,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_pomidorowy_wykwintny","page":"Książka kucharska/Sos pomidorowy wykwintny"},{"id":"oc-plws-580051","title":"Farsz ryżowo-cebulowy do postnych pasztecików (rice and onion filling for Lenten soup pastries)","cuisine":"European","category":"Other","ingredients":["2 tbsp rice","to taste water (for boiling the rice)","1 onion (mild Spanish onion, finely diced)","1 tbsp butter","to taste salt","to taste white pepper (ground)"],"steps":["Boil the rice in water in a pot for about 12 minutes so that it remains slightly firm, then drain thoroughly.","Peel and finely dice the onion, then fry it in a skillet in hot butter for about 8 minutes until pale golden.","Mix the drained rice with the fried onion and its butter, season with salt and white pepper, and use for filling soup pastries."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Paszteciki_do_zup_postne","page":"100 postnych i jarskich dań/Paszteciki do zup postne"},{"id":"oc-plwb-20881","title":"Fasolka po bretońsku (Breton-style beans with kiełbasa and bacon)","cuisine":"European","category":"Main","ingredients":["500 g Jaś white runner beans","500 g kiełbasa (Polish sausage, Silesian or standard)","250 g smoked bacon","4 tbsp tomato paste (3–4 tablespoons)","1 tbsp plain flour","1.5 l water (for boiling the beans)","to taste salt","to taste black pepper","to taste allspice berries","to taste bay leaf","1 tsp sweet paprika","1 tsp hot paprika","to taste marjoram"],"steps":["Rinse the beans, cover with water, soak for 12 hours, and then drain.","In a pot, bring 1.5 liters of fresh water to a boil, add the drained beans, a chunk of bacon, the bay leaf, and allspice berries, season with salt, and simmer covered for 60–90 minutes until the beans are tender.","Dice the remaining smoked bacon and fry gently in a dry skillet until the fat renders out.","Slice the kiełbasa, add it to the skillet with the bacon, and sauté together.","Mash a few cooked beans and dilute the tomato paste with a little of the cooking broth.","Add the diluted tomato paste, mashed beans, and the browned bacon and kiełbasa with their rendered fat to the pot.","Season the stew with sweet and hot paprika, black pepper, and a generous amount of marjoram.","Whisk the flour with a small amount of broth from the pot, stir into the stew, and simmer for another 15 minutes."],"time":125,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fasolka_po_breto%C5%84sku","page":"Książka kucharska/Fasolka po bretońsku"},{"id":"oc-plwb-2729","title":"Fasolka szparagowa w cieście naleśnikowym (batter-fried green beans)","cuisine":"European","category":"Side","ingredients":["500 g green beans (yellow wax or green)","1 egg","150 g plain flour","125 ml milk","100 ml water (for the batter)","1 tsp salt (for boiling the beans)","3 tbsp cooking oil (for frying)"],"steps":["Trim the green beans, boil them until tender in water with a teaspoon of salt, and drain.","Add the flour to a bowl, crack in the egg, pour in the milk and water, and blend into a batter with the consistency of thick cream.","Transfer the drained beans into the bowl with the batter and toss until the pods are evenly coated.","Heat the oil in a pan, add the battered bean pods, and fry on both sides until golden brown."],"time":30,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fasolka_szparagowa_w_cie%C5%9Bcie_nale%C5%9Bnikowym","page":"Książka kucharska/Fasolka szparagowa w cieście naleśnikowym"},{"id":"oc-plwb-14304","title":"Fasolka szparagowa z cząbrem (green beans with tomatoes and savory)","cuisine":"European","category":"Side","ingredients":["500 g green beans","4 tomatoes (3–4 pieces)","1 tbsp olive oil","to taste lemon juice","to taste savory (dried or fresh)","to taste salt","to taste sugar"],"steps":["Wash the green beans, trim the ends, remove any strings, and cut the pods into pieces about 5 cm long.","Boil the green beans with salt and sugar until tender, then drain.","Blanch the tomatoes, peel off their skins, and dice the flesh.","Drizzle the cooked beans with olive oil and lemon juice, toss with the diced tomatoes, and sprinkle with chopped savory."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fasolka_szparagowa_z_cz%C4%85brem","page":"Książka kucharska/Fasolka szparagowa z cząbrem"},{"id":"oc-plwb-13746","title":"Fasolowa na ostro (spicy Polish beef and bean soup)","cuisine":"European","category":"Soup","ingredients":["100 g Jaś white runner beans","200 g beef","2 onion","400 g canned tomatoes (with juices)","2 tbsp olive oil","5 clove garlic","1 tbsp ginger","1 tbsp wine vinegar","1 pinch chili powder","1 l water (for soaking the beans and cooking the soup)","to taste herbs (for garnish)","to taste salt","to taste black pepper"],"steps":["Cover the beans with part of the water and leave to soak overnight, then drain.","Cut the beef into cubes, sear in the heated olive oil, and remove from the pot.","In the remaining fat, cook the chopped onion and garlic until translucent.","Add the crushed canned tomatoes with their juices, season with chili, ginger, and wine vinegar, stir thoroughly, and bring to a boil.","Return the browned beef to the pot, add the water, cover, and simmer for about 30 minutes.","Add the drained beans and simmer the soup for another hour, until the beans and meat are tender.","Season the soup to taste with salt and pepper, and sprinkle with herbs before serving."],"time":120,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fasolowa_na_ostro","page":"Książka kucharska/Fasolowa na ostro"},{"id":"oc-plwb-16801","title":"Fasolowa po chłopsku (peasant-style bean soup)","cuisine":"European","category":"Soup","ingredients":["300 g beans","2 clove garlic","250 ml sour cream","2 tbsp plain flour","1 bay leaf","2 l water (for soaking and boiling)","to taste salt"],"steps":["Rinse and pick over the beans, cover with part of the water, and leave to soak overnight.","Top up the water in the pot to about 2 liters and begin cooking the beans.","When the beans are halfway tender, add the peeled garlic cloves, bay leaf, and salt, and cook until completely soft.","Whisk the sour cream with the flour, pour through a fine sieve into the simmering soup, and bring to a boil again."],"time":105,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fasolowa_po_ch%C5%82opsku","page":"Książka kucharska/Fasolowa po chłopsku"},{"id":"oc-plwb-7891","title":"Faszerowane pomidory (stuffed tomatoes with cheese and peas)","cuisine":"European","category":"Snack","ingredients":["8 tomatoes (ripe and firm)","400 g canned green peas (undrained)","250 g sharp hard cheese","125 ml mayonnaise","to taste salt","to taste black pepper","8 lettuce leaves (medium length)","to taste parsley leaves (chopped)"],"steps":["Slice off the tomato tops and scoop out the pulp and seeds with a teaspoon.","Lightly season the inside of the tomatoes with salt and pepper, then set aside in a cool place.","Cut the cheese into small cubes the size of green peas, and drain the peas from their brine.","Mix the cheese and peas with the mayonnaise, and season the filling to taste with salt and pepper.","Fill the hollowed tomatoes with the prepared filling, arrange on lettuce leaves, sprinkle with chopped parsley leaves, and serve immediately."],"time":20,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Faszerowane_pomidory","page":"Książka kucharska/Faszerowane pomidory"},{"id":"oc-plwb-16670","title":"Faworki (angel wings)","cuisine":"European","category":"Cookie","ingredients":["225 g plain flour","4 egg yolks","1 tbsp rectified spirit or vinegar","3 tbsp thick sour cream","750 g lard (for deep frying)","to taste icing sugar (for dusting)","to taste vanilla sugar (for dusting)"],"steps":["Knead an elastic dough from the plain flour, egg yolks, thick sour cream, and spirit or vinegar.","Fold, roll, and beat the dough repeatedly with a mallet or rolling pin until air bubbles appear, then cover with a kitchen towel and let rest for 60 minutes.","Cut off a portion of dough at a time, dust lightly with flour, roll out paper-thin, and slice into strips about 4 cm wide.","Make a slit in the center of each strip and pull one end through the slit to form a ribbon bow.","Melt and heat the lard in a wide pot and fry the faworki in batches on both sides until golden.","Remove the fried faworki with a fork, drain on paper towels, and, while still hot, sift over icing sugar mixed with vanilla sugar."],"time":120,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Faworki","page":"Książka kucharska/Faworki"},{"id":"oc-plwb-18753","title":"Firm cheese and egg salad (Sałatka z jajkami)","cuisine":"European","category":"Salad","ingredients":["150 g firm cheese","4 eggs","2 scallions","1 green bell pepper","3 tbsp canned green peas","2 leeks","to taste fresh chives (chopped)","4 tbsp olive oil","2 tbsp mustard","1 tbsp lemon juice","to taste salt","to taste black pepper"],"steps":["Hard-boil the eggs, let cool, peel, and cut into bite-sized pieces.","Trim the scallions and leeks, slicing them on an angle, and cut the seeded green bell pepper into thin matchsticks.","Cut the firm cheese into small dice and combine in a salad bowl with the sliced vegetables, canned peas, eggs, and chopped chives.","Whisk the olive oil with lemon juice, mustard, salt, and pepper into a smooth dressing.","Pour the dressing over the salad, cover, and let rest for about 30 minutes before serving."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_jajkami","page":"Książka kucharska/Sałatka z jajkami"},{"id":"oc-plwb-14947","title":"Fish schnitzels (Sznycle z ryby)","cuisine":"European","category":"Main","ingredients":["750 g fish","2 onions","125 ml milk","7 eggs","1 bread roll","to taste salt","to taste pepper","to taste breadcrumbs (for coating)","to taste fat for frying"],"steps":["Clean and rinse the fish, remove skin, and fillet the meat.","Soak the bread roll in milk for about 10 minutes, and peel the onions and cut into chunks.","Squeeze out the bread roll and mince in a meat grinder together with the fish and onions, then add 2 eggs, salt, and pepper, and knead the mixture thoroughly.","Shape into small patties, coat in breadcrumbs, fry in hot fat until golden, and place on plates.","Fry sunny-side-up eggs using the remaining 5 eggs and place one on top of each patty."],"time":40,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sznycle_z_ryby","page":"Książka kucharska/Sznycle z ryby"},{"id":"oc-plws-520723","title":"Fish Soufflé","cuisine":"European","category":"Main","ingredients":["600 g fish flesh (raw or cooked, boneless; orig. sixty dag)","400 g boiled potatoes (orig. forty dag)","100 g butter (for the mixture; orig. ten dag)","3 eggs (separate the yolks from the whites; use both parts)","to taste salt","to taste pepper","to taste butter (for greasing the dish; amount not specified)","to taste breadcrumbs (for sprinkling; amount not specified)"],"steps":["Remove the bones from the fish.","Grind the fish together with the boiled potatoes.","Cream 100 g of butter until fluffy.","Add the ground fish and potatoes and beat thoroughly.","Separate the egg yolks from the whites.","Add the yolks, salt, and pepper to the mixture, then beat thoroughly.","Beat the egg whites until stiff.","Grease a baking dish with additional butter.","Preheat the oven to 180 °C.","Just before baking, gently fold the beaten egg whites into the mixture.","Mound the mixture into a dome in the dish and sprinkle with breadcrumbs.","Bake for 30 minutes.","Serve the soufflé immediately after removing from the oven, before it falls."],"time":30,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Jedz_ryby/Suflet_z_ryby","page":"Jedz ryby/Suflet z ryby"},{"id":"oc-plwb-18779","title":"Flaki na kwaśnicy (beef tripe soup in sauerkraut juice)","cuisine":"European","category":"Soup","ingredients":["500 g cleaned beef tripe","1 l sauerkraut juice (brine) (approx. 1 liter)","1 large onion","1 tbsp plain flour","2 tbsp lard","3 allspice berries (2–3 berries)","1 tsp dried marjoram (rubbed)","1 bay leaf","1.5 l water (for parboiling tripe and thinning roux)","to taste salt","to taste black pepper"],"steps":["Wash the beef tripe thoroughly, cover with hot water in a pot, parboil, and drain.","Cover the tripe with fresh boiling water, parboil again, drain, let cool, and slice into thin strips.","Transfer the sliced tripe to a soup pot, pour in the sauerkraut juice, add the bay leaf and allspice berries, and simmer until tender.","Season the broth with salt, black pepper, and marjoram.","Peel and finely chop the onion, fry it in the heated lard until golden, then add the flour and make a roux.","Thin the roux with a small amount of lukewarm water, whisk into the tripe soup, and bring to a boil."],"time":115,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Flaki_na_kwa%C5%9Bnicy","page":"Książka kucharska/Flaki na kwaśnicy"},{"id":"oc-plws-44997","title":"Fluffy boiled buckwheat groats (Kasza gryczana na sypko)","cuisine":"European","category":"Side","ingredients":["1 l water (orig. 1 kwarta)","1 tbsp butter (for cooking, plus extra butter or fatback for serving)","to taste salt","500 ml buckwheat groats (orig. 1/2 kwarta)"],"steps":["Bring the water to a boil in a pot with a tablespoon of butter and salt.","Gradually pour the buckwheat groats into the boiling water, stirring constantly with a spoon.","Lower the heat to very low and cook covered for about 15–20 minutes until the groats absorb the water and become tender.","Turn the fluffy groats out onto a platter and drizzle with melted butter or rendered fatback."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kasza_gryczana_na_sypko","page":"365 obiadów za 5 złotych/Kasza gryczana na sypko"},{"id":"oc-plwb-14619","title":"Francuskie sakiewki z twarogiem (puff pastry parcels with quark and raisins)","cuisine":"European","category":"Cake","ingredients":["300 g puff pastry","250 g quark (farmer's cheese)","4 tbsp sour cream","100 g raisins","3 tbsp icing sugar","1 egg yolk (for the filling)","1 egg (for egg wash)"],"steps":["Mash the quark in a bowl and mix with the sour cream, raisins, icing sugar, and egg yolk until smooth.","Preheat the oven to 210 °C.","Roll out the puff pastry to a thickness of 3–4 mm and cut into 9 cm squares.","Place a teaspoon of quark filling in the center of each square and pinch opposite corners together to form parcels.","Arrange the parcels on a baking sheet lined with baking paper, brush with beaten egg, and bake for 15 minutes."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Francuskie_sakiewki_z_twarogiem","page":"Książka kucharska/Francuskie sakiewki z twarogiem"},{"id":"oc-plws-39477","title":"French Soup Dumplings without Beaten Egg Whites (Kluski francuskie bez piany)","cuisine":"European","category":"Side","ingredients":["4 egg yolk","4 tbsp butter (orig. 4 spoonfuls of fresh butter)","4 tbsp wheat flour (for the batter (plus a little for coating the balls))","to taste salt","to taste broth (rosół) (hot, for cooking the dumplings)"],"steps":["Cream the 4 egg yolks with 4 tablespoons of fresh butter until pale and whitish.","Gradually beat in the wheat flour 1 tablespoon at a time, add a pinch of salt, and beat continuously for 30 minutes until the mixture reaches the consistency of thick cream.","Shape the mixture on a pastry board into small round balls, roll them lightly in flour, and let rest briefly.","Drop the dumplings into boiling broth and cook until they float to the surface; serve in clear broth or in the sauce of a lemon-free chicken fricassee."],"time":40,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kluski_francuzkie_bez_piany","page":"365 obiadów za 5 złotych/Kluski francuzkie bez piany"},{"id":"oc-plws-40198","title":"French toast with mulled wine and raisin sauce (Grzanki z winem)","cuisine":"European","category":"Dessert","ingredients":["1 wheat roll (orig. 1 roll, outer crust grated off)","to taste sweet cream (for soaking the roll)","1 egg (beaten)","to taste breadcrumbs (sifted, for a light dusting)","to taste clarified butter (for frying)","to taste red wine (or white wine, for the sauce)","to taste sugar (for the wine sauce and for dusting the croutons)","1 cinnamon stick (orig. 1 piece of cinnamon stick, for the sauce)","to taste raisins (generous amount, mixed varieties)","to taste cinnamon (ground, for dusting the croutons with sugar)"],"steps":["Grate the outer crust off the wheat roll and slice the loaf lengthwise.","Dip the slices in sweet cream, then in beaten egg, and dust lightly with sifted breadcrumbs.","Fry the croutons in hot clarified butter for about 6–8 minutes, turning twice, until richly browned.","In a small saucepan, bring the red wine to a boil with sugar, a piece of cinnamon stick, and plenty of raisins, and cook for about 5 minutes.","Dust the fried croutons with cinnamon sugar and serve with the hot wine sauce in a sauceboat."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Grzanki_z_winem","page":"365 obiadów za 5 złotych/Grzanki z winem"},{"id":"oc-plws-579404","title":"French-style carp","cuisine":"European","category":"Main","ingredients":["1600 g carp (orig. 4–5 funty; 1600–2000 g (historical measure, converted approximately))","to taste salt","250 ml wine vinegar (orig. 1 szklanka; for scalding the fish and for the stock)","1 lemon","2 onion","2 bay leaf (2–3 leaves)","4 cloves (4–5 pieces)","8 allspice and black peppercorns (A total of 8–10 berries/corns; the source does not specify the ratio of the two spices.)","to taste water (For the stock: two parts water to one part vinegar, just enough to cover the fish.)","to taste parsley leaves (For sprinkling.)","to taste olive oil (For serving.)","to taste vinegar (For serving.)"],"steps":["Clean the carp, keep the head, and cut the fish into crosswise steaks.","Arrange the pieces side by side, pour part of the boiled wine vinegar over them, and cover while preparing the stock.","Pour the remaining wine vinegar into a pot and add twice as much water, just enough to cover the fish.","Cut the lemon into slices and chop the onion finely.","Bring the stock to a boil with the lemon, onion, bay leaves, cloves, allspice, black pepper, and salt.","Place first the head and then the carp steaks into the stock and cook over high heat until the fish is done.","Cover the cooked fish with baking paper.","Transfer the carp to a platter with the cooked onion and lemon.","Sprinkle with parsley leaves and serve with olive oil and vinegar."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Karp%E2%80%99_po_francusku","page":"Kucharka litewska (1913)/Karp’ po francusku"},{"id":"oc-plws-544171","title":"French-Style Pears","cuisine":"European","category":"Preserve","ingredients":["500 g pears (panny or bon chrétien varieties, peeled and quartered)","1 kg fine sugar (for layering with the pears)","2 lemon (juice of 1 lemon for the water and the juice and thinly sliced peel of a second lemon for the preserve)","2 tbsp rum (good quality, for sprinkling the layers)","1 l water (cold, for soaking the pears after peeling)"],"steps":["Peel the pears, halve them, remove the cores, cut into quarters, and drop into cold water acidulated with the juice of 1 lemon.","In a bowl, arrange alternating layers of fine sugar and drained pear quarters, sprinkling each layer with the juice of the second lemon and a little rum; let stand until the next day.","On the second day, remove the pears from the bowl, pour the resulting syrup into a pan, bring to a boil, and skim thoroughly.","Add the pears to the boiling syrup and simmer until the syrup thickens and the fruit becomes translucent.","Once completely cooled, transfer the preserve into jars, adding thinly sliced lemon peel, and seal tightly."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_sposobem_francuzkim","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki sposobem francuzkim"},{"id":"oc-plws-546703","title":"Fresh herring baked with potatoes (śledzie zapiekane z kartoflami)","cuisine":"European","category":"Main","ingredients":["500 g fresh herrings (orig. 50 dkg)","500 g potatoes (orig. 50 dkg)","150 g onion (orig. 15 dkg)","1 tbsp plain wheat flour","1 tbsp vegetable oil (for roux and greasing dish)","50 g sour cream (orig. 5 dkg)","1 bay leaf","to taste peppercorns","to taste salt"],"steps":["Clean the fresh herrings, salt, and let stand for 60 minutes, then simmer in a small amount of water with a piece of onion, peppercorns, and bay leaf for about 10 minutes.","Remove the cooked herrings, debone, and break into generous chunks, reserving the poaching liquid.","Boil the potatoes in their skins, peel, and slice into rounds, and slice the remaining raw onion into very thin rings.","Prepare a pale roux from the plain wheat flour and part of the vegetable oil, whisk in the herring broth, bring to a boil, and stir in the sour cream.","Grease a baking dish with the remaining oil, layer the potatoes and herring pieces interspersed with raw onion slices, pour over the sauce, and bake in an oven preheated to 180 °C for 40 minutes."],"time":145,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/%C5%9Awie%C5%BCe_%C5%9Bledzie_duszone_z_kartoflami","page":"109 potraw/Świeże śledzie duszone z kartoflami"},{"id":"oc-plws-546704","title":"Fresh herring Greek-style (śledzie po grecku)","cuisine":"European","category":"Main","ingredients":["1 kg fresh herrings","1 kg mixed vegetables: carrots, parsley root, onion, and savoy or white cabbage","1 leek","0.5 celeriac (celery root)","2 tbsp tomato paste","2 tbsp vegetable oil","125 ml vinegar (orig. 1/2 cup)","1 bay leaf","to taste black pepper","to taste salt"],"steps":["Clean the fresh herrings, salt, halve lengthwise, and cut each half crosswise into 3 equal portions.","Poach the herring pieces in very little water with pepper and bay leaf for about 10 minutes, then cool and transfer to a serving platter, reserving the poaching liquid.","Cut the carrots, parsley root, onion, cabbage, leek, and celeriac into julienne strips and braise gently in the herring broth with vegetable oil for about 25 minutes until tender.","Add the tomato paste and vinegar to the tender vegetables and bring briefly to a boil.","Cover the arranged herrings on the platter with a generous layer of braised vegetables and refrigerate for 24 hours (1440 minutes) before serving."],"time":600,"servings":7,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/%C5%9Awie%C5%BCe_%C5%9Bledzie_po_grecku","page":"109 potraw/Świeże śledzie po grecku"},{"id":"oc-plwb-14582","title":"Fresh vegetable salad with cheese (Surówka ze świeżych warzyw)","cuisine":"European","category":"Salad","ingredients":["300 g tomatoes","1 cucumber","1 onion","1 bell pepper","100 g firm cheese","3 clove garlic","3 tbsp olive oil","3 tbsp wine vinegar","to taste fresh herbs","to taste salt","to taste pepper"],"steps":["Wash and dry the tomatoes, cucumber, and bell pepper; slice tomatoes and cucumber into rounds, and cut cored bell pepper into thin rings.","Peel and finely mince the onion and garlic, and cut the firm cheese into small batons.","Rub a salad bowl with garlic and whisk together the olive oil, wine vinegar, minced garlic, salt, and pepper inside.","Toss the salad ingredients with the dressing in the bowl, and sprinkle with finely chopped fresh herbs just before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sur%C3%B3wka_ze_%C5%9Bwie%C5%BCych_warzyw","page":"Książka kucharska/Surówka ze świeżych warzyw"},{"id":"oc-plwb-7773","title":"Fresh yellow knight mushroom sauce (Sos ze świeżych zielonek)","cuisine":"European","category":"Sauce","ingredients":["14 yellow knight mushrooms (Tricholoma equestre) (12–15 large caps)","1 tbsp butter (measured in a heaped spoonful)","250 ml broth (from bouillon or stock)","2 onions (large)","1 tbsp plain flour","3 tbsp whipping cream","1 tbsp dill (chopped, measured in a heaped spoonful)"],"steps":["Wash, drain, and very finely chop the mushroom caps, and peel and chop the onions.","Melt the butter in a pan, cook the chopped onion until translucent, then add the mushrooms and fry, stirring frequently, until most liquid evaporates.","Dust the mushrooms with flour, cook briefly while stirring continuously, then pour in the broth and bring to a boil.","Remove the sauce from the heat, stir in the whipping cream and chopped dill, and serve hot without boiling again."],"time":25,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_ze_%C5%9Bwie%C5%BCych_zielonek","page":"Książka kucharska/Sos ze świeżych zielonek"},{"id":"oc-plws-546738","title":"Fried salsify (salsefia smażona)","cuisine":"European","category":"Side","ingredients":["500 g salsify roots (orig. 0.5 kg)","1 tbsp plain wheat flour or oat flour","2 tbsp vegetable oil","to taste salt"],"steps":["Thoroughly scrape the salsify roots, rinse, and boil until tender in salted water for about 20–25 minutes.","Drain the cooked salsify, pat dry on paper towels, and dredge in plain wheat or oat flour.","Heat the vegetable oil in a skillet and fry the salsify for about 5–8 minutes on all sides until golden brown."],"time":45,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Salsefja_sma%C5%BCona","page":"109 potraw/Salsefja smażona"},{"id":"oc-plws-552235","title":"Frozen cream parfait","cuisine":"European","category":"Dessert","ingredients":["10 egg yolks (count)","500 g icing sugar or caster sugar (orig. a quarter kilogram twice (250 g for the yolks and 250 g for the whipped cream))","250 ml milk (orig. 1 szklanka)","750 ml whipping cream or double cream (thick, orig. three quarters of a litre)","1 vanilla pod (a small pod, crushed)","250 g candied fruit (finely chopped dry preserves for the mixture and for lining the mould, orig. a quarter kilogram)"],"steps":["Beat ten yolks until white with 250 g of fine sugar and 250 ml of milk. Warm them over very low heat, stirring constantly and not letting them boil, then cool them thoroughly in a cold bath.","Whip 750 ml of thick cream until stiff. Fold in the remaining 250 g of fine sugar, the crushed vanilla pod, and most of the finely chopped candied fruit.","Fold the whipped cream gently into the cooled yolk mixture.","Line a metal mould with paper, sprinkle the remaining candied fruit over the bottom, pour in the cream, cover it tightly, and put it in the freezer (or pack it in ice and salt) for about 3–4 hours, until frozen through."],"time":255,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_z_kremem","page":"Doświadczone sekreta smażenia konfitur i soków/Lody z kremem"},{"id":"oc-plwb-18676","title":"Frozen mocha cheesecake (Sernik kawowy)","cuisine":"European","category":"Cake","ingredients":["250 g homogenised curd cheese","1 sweetened condensed milk (can)","2 tbsp instant coffee","250 ml whipped cream","100 g chocolate","2 tbsp milk","375 ml biscuits (crushed)","200 g butter","125 ml sugar"],"steps":["Melt the butter, mix with the crushed biscuits and sugar, and press the crumb mixture firmly into the base and sides of a springform tin.","Dissolve the instant coffee in 1 tbsp of hot water, and melt the broken chocolate in 2 tbsp of warm milk.","Beat the homogenised curd cheese with the condensed milk, dissolved coffee, and melted chocolate until smooth and fluffy.","Gently fold the whipped cream into the coffee-cheese mixture and spread into the prepared crust.","Cover the tin with foil and freeze for 12 hours until firm."],"time":600,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sernik_kawowy","page":"Książka kucharska/Sernik kawowy"},{"id":"oc-plwb-18423","title":"Galaretka mleczno-migdałowa (almond blancmange jelly)","cuisine":"European","category":"Dessert","ingredients":["500 ml whole milk (3.2%)","5 bitter almonds","60 g sweet almonds","135 g sugar","20 g gelatin powder (two 10 g sachets)","50 ml water (boiled and cooled, for grinding almonds and softening gelatin)"],"steps":["Blanch the sweet and bitter almonds, peel off their skins, and pound finely in a mortar or bowl.","Grind the crushed almonds, adding cooled water a few drops at a time, until a thick paste forms.","Bring the milk to a boil and slowly pour it hot into the almond paste, stirring in the sugar continuously.","Soften the gelatin in the remaining water, dissolve it completely, and combine with the warm almond milk.","Refrigerate the mixture, and as soon as it begins to set, ladle into dessert bowls and chill until completely set."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Galaretka_mleczno-migda%C5%82owa","page":"Książka kucharska/Galaretka mleczno-migdałowa"},{"id":"oc-plwb-17863","title":"Galaretka pikantna (savory apple and herb jelly)","cuisine":"European","category":"Preserve","ingredients":["1.5 kg tart cooking apples","250 ml wine vinegar (250 ml)","3 tbsp chopped fresh sage leaves","1 tbsp chopped fresh basil leaves","1 tbsp chopped fresh mint leaves","1 l water (boiled, approx. 1 liter)","800 g sugar (approx. 200 g (250 ml by volume) per 250 ml of strained juice)"],"steps":["Wash and dry the apples, cut into quarters, and core them.","Transfer the apples to a large pot, add the basil, mint, and 2 tablespoons of sage, then pour in the water and wine vinegar.","Bring to a boil, cover, and simmer over low heat, stirring occasionally, until the apples break down completely.","Transfer the pulp to a jelly bag suspended over a pot and leave overnight to strain naturally without squeezing.","Measure the strained juice, add 200 g of sugar for every 250 ml of juice, and simmer for about 30 minutes, stirring and skimming off foam.","Toward the end of boiling, stir in the remaining tablespoon of sage.","Ladle the hot jelly into sterilised small jars, seal tightly, and leave to cool under a towel."],"time":90,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Galaretka_pikantna","page":"Książka kucharska/Galaretka pikantna"},{"id":"oc-plwb-18573","title":"Gofry z sera białego (quark waffles)","cuisine":"European","category":"Dessert","ingredients":["500 g quark or farmer's cheese","200 g butter","4 tbsp honey","6 eggs","1 lemon (juice and finely grated zest)","to taste ground cinnamon","400 g plain flour","1 tsp baking powder"],"steps":["Separate the egg yolks from the whites, grate the zest from the lemon, and squeeze out its juice.","Cream the butter with the honey and egg yolks until fluffy.","Continuing to beat, gradually add the quark, lemon zest and juice, cinnamon, and flour mixed with baking powder.","Whip the egg whites until stiff peaks form and gently fold them into the batter.","Use a large spoon to portion the batter onto a preheated waffle maker and cook until golden brown."],"time":45,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gofry_z_sera_bia%C5%82ego","page":"Książka kucharska/Gofry z sera białego"},{"id":"oc-plws-555156","title":"Gooseberry Compote Preserve","cuisine":"European","category":"Preserve","ingredients":["1 kg gooseberries (ripe but not overripe: green, yellow, or red)","500 g sugar (chopped into small pieces)","250 ml water (for the syrup)"],"steps":["Clean the ripe gooseberries, carefully trimming off the stems and blossom ends with a small knife without piercing the skin of the fruit.","Boil a medium-thick syrup from 500 g of sugar and 250 ml of water, and skim it thoroughly.","Drop the gooseberries into the hot syrup and the moment the syrup begins to boil again, remove the pan immediately from the heat and leave to cool completely.","Transfer the cold gooseberries with the syrup into jars, leaving approx. 5 cm of headspace at the top, seal tightly, and pasteurize in a pot of water lined with hay or a cloth for 15 minutes from the moment the water boils."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_agrestu","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z agrestu"},{"id":"oc-plws-555157","title":"Gooseberry Compote Preserve Another Way","cuisine":"European","category":"Preserve","ingredients":["1 kg gooseberries (large, ripe: red, yellow, or green)","500 g sugar (for the syrup)","250 ml water (1 glass per 500 g of sugar)"],"steps":["Carefully trim the stems from the ripe gooseberries with a small knife, wipe the berries with a clean cloth, and pack directly into jars.","Boil a medium-thick syrup from 500 g of sugar and 250 ml (1 glass) of water, skim thoroughly, and let cool completely.","Pour the cold syrup over the gooseberries in the jars to 3/4 of the height of the vessel.","Seal the jars tightly, place in a kettle or pot of cold water, and pasteurize for approx. 25–30 minutes after the water comes to a boil, then leave in the water until cooled."],"time":75,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_agrestu_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z agrestu innym sposobem"},{"id":"oc-plws-543493","title":"Gooseberry Preserves","cuisine":"European","category":"Preserve","ingredients":["500 g unripe gooseberries (large, fleshy; orig. half a kilogram)","1 kg sugar (divide into two equal parts; orig. one kilogram)","to taste vanilla (piece of a pod tied in thin muslin)","to taste water (for soaking, blanching, chilling, and preparing a light syrup; amount not specified)","to taste ice (for chilling the water)"],"steps":["Clean the gooseberries and remove the seeds with a thin tool.","Place the cleaned fruit into cold water.","Transfer the drained gooseberries into boiling water and remove the pot from the heat until the fruit turns slightly pale and softens.","Transfer the fruit with a slotted spoon into ice-cold water.","Leave the gooseberries in the ice water in a cool place for about 120 minutes.","Drain the fruit thoroughly on a sieve.","Prepare a light syrup from water and 500 g of sugar, adding the vanilla tied in thin muslin.","Pour the completely cooled syrup over the gooseberries in a jar.","Set the fruit in the syrup aside for about 1440 minutes.","Pour off the syrup and boil it with the remaining 500 g of sugar.","Pour the completely cooled syrup over the gooseberries again.","Repeat pouring off, boiling, cooling the syrup, and pouring it over the fruit twice more, waiting about 1440 minutes each time.","Bring the gooseberries to a boil in the thickened syrup, heating them only briefly.","Transfer the preserves to a bowl to cool.","Pack the cooled preserves into very clean, thoroughly dried jars."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Agrest","page":"Doświadczone sekreta smażenia konfitur i soków/Agrest"},{"id":"oc-plws-544777","title":"Gorzkie pomarańczki w syropie (Bitter oranges in syrup)","cuisine":"European","category":"Preserve","ingredients":["500 g bitter oranges (orig. half a kilogr.)","1000 g sugar (orig. one kilogr.; divide into 500 g, 250 g, and 250 g)","to taste light sugar syrup (for the first pouring; amount and proportions not specified)","to taste water (for soaking, boiling, and preparing the main syrup; amount not specified)"],"steps":["Soak the bitter oranges in cold water for 14 400 minutes, changing the water daily.","Prick each bitter orange thoroughly with a wooden toothpick.","Cover with fresh water and boil for 210 minutes.","Drain the oranges and wrap them gently in a clean cloth so they cool slowly without losing their shape.","Cover the cold bitter oranges with light sugar syrup and set aside for 1440 minutes.","Pour off all the light syrup.","Prepare a fresh syrup from 500 g sugar and water, the quantity of which is unspecified by the source.","Pour the lukewarm syrup over the oranges and set aside for 1440 minutes.","Remove the oranges, dissolve another 250 g sugar in the syrup, and pour the warmer syrup over the fruit for the next 1440 minutes.","Pour off the syrup, add the remaining 250 g sugar, and pour even hotter syrup over the fruit for 1440 minutes.","On the fourth day, heat the drained syrup to a boil and pour it over the fruit for another 1440 minutes.","On the fifth day, place the oranges into the boiling syrup and bring to a boil several times.","Once completely cooled, transfer into jars, seal, and store in a cool, dry place."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Pomara%C5%84czki","page":"Doświadczone sekreta smażenia konfitur i soków/Pomarańczki"},{"id":"oc-plws-546636","title":"Goulash and Poached Eggs on Toasted Rolls","cuisine":"European","category":"Main","ingredients":["2 oblong crusty rolls (larger oblong rolls known as parki)","200 g beef, veal, or pork (orig. 20 dkg of tender meat)","2 onion (whole)","40 g lard or margarine (orig. 4 dkg)","2 eggs (2 large or 4 small eggs)","1 tbsp wheat flour","250 ml water (for braising the goulash sauce)","to taste salt","1 tsp ground paprika"],"steps":["Slice the rolls in half lengthwise and scoop out their soft centers (which can be dried for breadcrumbs).","Mince the meat and onions as finely as possible, brown them together in hot fat, sprinkle with flour, pour in water, season with salt, and simmer over low heat until tender, stirring in the paprika toward the end to form a thick, rich red sauce.","Poach the eggs or soft-boil them (for 3 minutes) and peel.","Spoon a tablespoon of the hot goulash sauce into each hollowed roll half, place the halved large eggs (or whole small eggs) on top, and cover with the remaining sauce.","Place the filled rolls into a hot oven (200 °C) for a few minutes until piping hot and serve immediately."],"time":70,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Gulasz_na_grzankach_z_jajami","page":"109 potraw/Gulasz na grzankach z jajami"},{"id":"oc-plwb-15166","title":"Gourmet mixed meat skewers (Szaszłyki smakosza)","cuisine":"European","category":"Main","ingredients":["200 g pork neck (collar)","200 g pork loin","200 g poultry meat","200 g smoked kiełbasa (Polish sausage)","3 bell peppers (2–3 multicoloured)","3 onions (2–3)","2.5 tbsp marjoram (2–3 tbsp)","2 tsp mustard","3 clove garlic","3 tbsp olive oil","3 tbsp soy sauce","to taste pepper"],"steps":["Chop the garlic and mix with the olive oil, soy sauce, mustard, marjoram, and pepper.","Cut the pork neck, pork loin, and poultry into large cubes, add to the marinade, and chill in the refrigerator for at least 120 minutes.","Cut the smoked kiełbasa into thick rounds, bell peppers into squares matching the meat, and onions into slices.","Thread onto skewers alternately bell pepper, onion, the different meats, and slices of kiełbasa.","Grill the skewers for 10–15 minutes on a well-heated grill, then wrap them in aluminium foil and leave them at the edge of the grill for another 10 minutes."],"time":165,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szasz%C5%82yki_smakosza","page":"Książka kucharska/Szaszłyki smakosza"},{"id":"oc-plws-45190","title":"Gołąbki (stuffed cabbage rolls with pork and rice)","cuisine":"European","category":"Main","ingredients":["1 white cabbage (orig. a head of white cabbage, using the softest leaves)","to taste water (for parboiling the cabbage leaves)","400 g pork (orig. 1 funt of raw pork, finely chopped)","2 tbsp butter (1 tbsp (or lard) for the filling and 1 tbsp for the roux)","1 onion (large, grated)","to taste fresh parsley (chopped)","to taste salt (for the water and the meat)","to taste black pepper","to taste rice (parboiled beforehand in broth or water)","2 egg yolks (for the cooled filling)","to taste broth (hot, for braising the cabbage rolls)","1 tbsp plain wheat flour (for the roux)","1.5 tbsp sour cream (orig. 1–2 tbsp sour cream)"],"steps":["Separate the softest leaves from the head of white cabbage, parboil them for 3–5 minutes in boiling salted water, and lift them into a bowl.","Finely mince or grind the raw pork, place in a saucepan with 1 tablespoon of butter, the grated onion, chopped parsley, salt, pepper, and parboiled rice, and braise together for 15 minutes.","Cool the braised meat mixture, then beat in the egg yolks until well combined.","Place portions of filling on the parboiled cabbage leaves, roll up neatly into tight parcels, and pack them side by side in a wide saucepan.","Pour hot broth over the cabbage rolls and simmer uncovered over very low heat for about 45 minutes until the cabbage is tender.","Brown a tablespoon of wheat flour in the remaining tablespoon of butter, whisk in the sour cream, and stir into the braising liquid around the cabbage rolls."],"time":100,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kapusta_nadziewana","page":"365 obiadów za 5 złotych/Kapusta nadziewana"},{"id":"oc-plwb-32459","title":"Gołąbki z kapustą i pomidorami (stuffed cabbage rolls in tomato sauce)","cuisine":"European","category":"Main","ingredients":["1 head of savoy cabbage (about 1.5 kg)","600 g ground pork (from pork leg or shoulder)","1 onion (large)","1 tbsp cooking oil (for cooking the onion until translucent and parboiling the cabbage)","100 g cooked rice","1.5 l broth","200 g tomato paste or tomato passata","1 tbsp plain flour","1 tbsp potato starch","50 ml water (cold, for mixing with the flour and starch to make a slurry)","to taste salt","to taste black pepper","to taste basil","to taste oregano"],"steps":["Core the cabbage, place it core-side down in boiling water with a little oil, and parboil for about 10 minutes.","Peel off the softened leaves with tongs, plunge into cold water to stop cooking, and gently shave down the thick central ribs.","Dice the onion, cook in the remaining oil until translucent, and mix with the minced pork and cooled rice.","Season the filling with salt and pepper, shape into oblong portions, and wrap tightly in the cabbage leaves, folding the sides inward.","Line the bottom of a pot with a few cabbage leaves, pack the rolls tightly together seam-side down, pour in the broth, cover, and simmer for 50–60 minutes until the cabbage is tender.","Transfer the cooked cabbage rolls from the pot to a dish, and stir the tomato paste or passata into the remaining cooking liquid.","Whisk the plain flour and potato starch into the cold water, pour slowly into the simmering sauce, season with salt, pepper, basil, and oregano, and simmer for a few minutes more."],"time":115,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Go%C5%82%C4%85bki_z_kapust%C4%85_i_pomidorami","page":"Książka kucharska/Gołąbki z kapustą i pomidorami"},{"id":"oc-plwb-31412","title":"Gołąbki z kaszą i mięsem (cabbage rolls with barley and pork in sour cream sauce)","cuisine":"European","category":"Main","ingredients":["1.5 kg head of cabbage","200 g minced pork collar (neck)","250 g barley groats or rice (fine pearl barley groats, whole pearl barley, or rice)","50 g onion","30 g cooking fat for frying and cooking the barley","to taste salt","to taste black pepper","125 ml sour cream","10 g plain flour","1 bouillon cube (stock cube)","250 ml water (boiling, for pouring over cabbage rolls)"],"steps":["Rinse the head of cabbage, core it, separate the leaves, and blanch them in batches in boiling water; drain, cool, and lightly flatten the thick central ribs with a mallet.","Cook the barley or rice with some of the fat, and fry the chopped onion in the remaining fat until golden.","In a bowl, mix the cooked barley or rice with the browned onion and raw minced meat, and season with salt and pepper.","Spoon a portion of filling onto each cabbage leaf, fold the opposite sides inward, and roll tightly into a parcel.","Line the bottom of a roasting dish with a few cabbage leaves, pack the cabbage rolls tightly on top, and cover with another layer of leaves.","Pour 250 ml of boiling salted water over the rolls and place in an oven preheated to 180 °C; once the top leaves brown, cover the dish, lower the temperature to 160 °C, and braise until tender.","Remove the top leaves, pour over the sour cream whisked with the flour and crumbled bouillon cube, and bake for another 10 minutes."],"time":110,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Go%C5%82%C4%85bki_z_kasz%C4%85_i_mi%C4%99sem","page":"Książka kucharska/Gołąbki z kaszą i mięsem"},{"id":"oc-plwb-16996","title":"Gołąbki z orzechami (cabbage rolls with pork and walnuts)","cuisine":"European","category":"Main","ingredients":["8 savoy cabbage leaves","30 g walnuts","1 bell pepper","50 g pork belly","600 g ground pork","to taste dried mint leaves (a few leaves)","to taste ground paprika","4 tbsp plain flour","2 eggs","100 g butter","to taste salt","to taste black pepper"],"steps":["Blanch the savoy cabbage leaves briefly in boiling water and drain them thoroughly.","Finely chop the walnuts, core and finely dice the bell pepper, and finely dice the pork belly.","Season the ground pork with salt, pepper, ground paprika, and crumbled dried mint.","Add the flour, eggs, diced pepper, pork belly, and walnuts to the meat and knead the mixture thoroughly.","Divide the filling among the cabbage leaves, roll them up into parcels, and tie with kitchen twine.","Arrange the cabbage rolls in an ovenproof dish, dot with butter, cover, and bake for 30 minutes in an oven preheated to 200 °C."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Go%C5%82%C4%85bki_z_orzechami","page":"Książka kucharska/Gołąbki z orzechami"},{"id":"oc-plwb-31359","title":"Gołąbki zawijane w liście funkii (rice and mushroom rolls in hosta leaves)","cuisine":"European","category":"Main","ingredients":["30 young hosta leaves (about 30 leaves)","150 g rice (100–200 g)","2 onions","100 g button mushrooms or oyster mushrooms","3 tbsp soy sauce (a few tablespoons)","2 tbsp butter or vegetable fat (for frying)","125 ml olive oil (approx. 125 ml)","125 ml water (approx. 125 ml for pouring over)","to taste fresh ginger","to taste salt"],"steps":["Cook the rice until tender and drain.","Finely chop the onions, ginger, and button or oyster mushrooms, then fry in the butter or vegetable fat until the onions begin to brown.","Add the cooked rice, pour in the soy sauce, mix well, and season with salt if needed.","Blanch the young hosta leaves for a few minutes in boiling water until pliable, then drain.","Place about 1 tablespoon of filling on each hosta leaf and roll into small parcels.","Arrange the rolls in a baking dish, pour over the olive oil and water, and bake in an oven preheated to 180 °C for at least 50 minutes."],"time":100,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Go%C5%82%C4%85bki_zawijane_w_li%C5%9Bcie_funkii","page":"Książka kucharska/Gołąbki zawijane w liście funkii"},{"id":"oc-plws-552230","title":"Grape ice","cuisine":"European","category":"Dessert","ingredients":["2000 g ripe sweet grapes (orig. 2 kilograms)","500 g sugar (fine, orig. half a kilogram)","1 l water (orig. 1 litre)","0.5 lemon (the juice of half a lemon)"],"steps":["Pull the grapes off the stems, crush them, press the juice, and rub it through a fine sieve.","Bring a syrup to the boil from 500 g of fine sugar, 1 litre of water and the juice of half a lemon, then leave it to cool.","Mix the cooled syrup with the fresh grape juice, pour it into an ice-cream maker, and freeze it (about 2–3 hours)."],"time":190,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_winogronowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody winogronowe"},{"id":"oc-plwb-7764","title":"Grape sauce (Sos winogronowy)","cuisine":"European","category":"Sauce","ingredients":["250 ml heavy cream (thick)","250 ml mayonnaise","250 ml white grapes (seeded and chopped)","to taste icing sugar","to taste salt","to taste pepper","to taste lemon juice"],"steps":["Whip the cream with a pinch of salt until light and fluffy.","Gently fold the whipped cream into the mayonnaise along with the seeded, chopped white grapes.","Season the sauce to taste with lemon juice, salt, pepper, and icing sugar.","Chill the prepared sauce in the refrigerator for 15 minutes and serve no later than 30 minutes after preparation."],"time":25,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_winogronowy","page":"Książka kucharska/Sos winogronowy"},{"id":"oc-plws-1080997","title":"Grated Orange Mazurek (Mazurek z tartemi pomarańczami)","cuisine":"European","category":"Cake","ingredients":["400 g wheat flour (orig. 1 funt)","200 g butter (orig. half a funt)","2 egg","100 g sugar (orig. a quarter funt)","1 tbsp arrack","2 lemon (whole, grated without seeds)","4 orange (large, whole, grated along with their juice without seeds)","800 g powdered sugar (orig. 2 funt fine sugar)","50 g candied orange peel (cut into oblong rectangles, for garnish)"],"steps":["Knead a shortcrust dough from 400 g of wheat flour, 200 g of butter, 2 eggs, 100 g of sugar, and a splash of arrack, roll out thinly on a baking sheet, and bake in a moderate oven (180 °C, about 15 minutes).","Grate 2 whole lemons and 4 large oranges along with their juice, carefully discarding all seeds.","Beat the grated citrus fruit with 800 g of fine sugar, transfer to a saucepan, and cook over the heat for about 30 minutes, stirring constantly, until the excess moisture evaporates and the mixture thickens considerably.","Spread the hot orange mixture in a thick layer over the freshly baked shortcrust base, leave to dry on the surface, and garnish with pieces of candied orange peel."],"time":75,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Mazurek_z_tartemi_pomara%C5%84czami","page":"Baby, placki i mazurki/Mazurek z tartemi pomarańczami"},{"id":"oc-plwb-18569","title":"Green bean salad (Sałatka z fasolki szparagowej)","cuisine":"European","category":"Salad","ingredients":["500 g green beans","to taste tarragon vinegar","to taste salt","to taste black pepper","to taste vegetable oil","1 tbsp onion (finely chopped)"],"steps":["Rinse the green beans, trim the ends, remove any strings, and cut the pods into bite-sized lengths.","Cook the beans in salted boiling water until tender, drain in a colander, and let cool completely.","Drizzle the cooled beans with tarragon vinegar and oil, add the chopped onion, season with salt and pepper, and toss thoroughly.","Chill the salad in the refrigerator before serving."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_fasolki_szparagowej","page":"Książka kucharska/Sałatka z fasolki szparagowej"},{"id":"oc-plws-42498","title":"Green lettuce salad with olive oil, tarragon vinegar, and eggs","cuisine":"European","category":"Salad","ingredients":["2 butterhead lettuce (orig. ratio given per 1 head (assumed 2 heads for 4 servings))","4 tbsp olive oil (orig. 2 tbsp per head)","2 tbsp tarragon vinegar (orig. 1 tbsp per head)","2 eggs (hard-boiled)","2 pinch salt (orig. 1 pinch per head)","to taste black pepper","to taste sugar"],"steps":["Hard-boil the eggs (about 10 minutes), cool, peel, and cut into quarters.","Trim the lettuce heads, rinse in cold water, and dry very thoroughly, gently squeezing out excess water.","Place the lettuce leaves in a salad bowl, drizzle first with the olive oil alone, and toss gently so the oil coats each leaf.","Next add the tarragon vinegar, then finally sprinkle with salt, pepper, and a little sugar. Toss carefully and thoroughly for a while.","Garnish the top with hard-boiled egg quarters and serve immediately."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sa%C5%82ata","page":"365 obiadów za 5 złotych/Sałata"},{"id":"oc-plws-546289","title":"Green walnuts preserved in spirit","cuisine":"European","category":"Preserve","ingredients":["1 kg young green walnuts (completely soft, the skin peeled carefully)","1 lemon (the squeezed juice goes into the boiling water while the walnuts cook)","750 g sugar (for a thick syrup)","750 ml water (500 ml for the syrup and 250 ml of boiled water to dilute the spirit (plus boiling water for cooking the walnuts))","500 ml spirit (90%, diluted with boiled water)"],"steps":["Peel young green, completely soft walnuts carefully with a penknife and drop them into boiling water acidulated with the juice of 1 lemon.","When the walnuts are soft, drain them and cover them with a thick syrup cooked from 750 g of sugar and 500 ml of water.","For 3 days in a row, pour off the syrup each day, bring it to the boil, and pour it back over the walnuts.","On the fourth day, pack the walnuts into a jar, reduce the syrup until thick, mix it with 500 ml of spirit diluted with 250 ml of boiled water, strain it through fine-weave muslin over the walnuts, and seal the jar."],"time":45,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_orzech%C3%B3w_w%C5%82oskich_w_spirytusie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z orzechów włoskich w spirytusie"},{"id":"oc-plwb-61672","title":"Green zucchini and pepper cream soup (Zielona zupa)","cuisine":"European","category":"Soup","ingredients":["1 onion","2 zucchini","2 green bell peppers","3 clove garlic","1 broccoli soup seasoning mix (packet)","100 g feta cheese (for serving)","2 tbsp olive oil","1.2 l water (about 1.2 liters)","1 pinch salt","1 pinch black pepper"],"steps":["Peel and finely chop the onion and garlic, wash, seed, and slice the bell peppers, and dice the zucchini.","Heat the olive oil in a pot, cook the onion and garlic until translucent, then add the green bell pepper and sauté briefly.","Add the diced zucchini and broccoli soup seasoning, pour in about 1.2 liters of water, and simmer over low heat until the vegetables are tender.","Blend the cooked soup until smooth, season with salt and pepper, and serve with pieces of feta cheese."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zielona_zupa","page":"Książka kucharska/Zielona zupa"},{"id":"oc-plws-546287","title":"Greengages preserved in spirit","cuisine":"European","category":"Preserve","ingredients":["1.5 kg greengages (orig. one and a half kilograms of ripe but not overripe greengages (or mirabelles or pale plums))","2 lemon (the squeezed juice goes into the boiling water to keep the greengages green)","50 g spinach (orig. 1 handful of green spinach in the boiling water to keep the colour)","750 g sugar (orig. a quarter kilogram (250 g) of sugar for every half kilogram (500 g) of fruit)","500 ml spirit (orig. half a litre of good spirit)","1 l water (500 ml (half a litre) of boiled water to dilute the spirit, and 500 ml of water for the thick syrup (plus boiling and cold water for blanching))"],"steps":["Wipe ripe greengages with a cloth, prick them densely with a wooden pin, and drop them into boiling water with the juice of 2 lemons and a handful of green spinach.","Move the pan at once onto a lower heat. When the plums float, lift them out into cold water, and once completely cool drain them on a sieve.","Cook a thick syrup from 750 g of sugar and 500 ml of water, add the drained greengages, bring it to the boil a couple of times, and leave them in the syrup until the next day.","On the second day, pour off the syrup, boil it, and pour it back over the plums.","On the third day, pour off the syrup, bring it to the boil, skim it carefully, mix it with 500 ml of spirit diluted with 500 ml of boiled water, and pour the cooled spirit syrup over the greengages packed in a jar. Seal it."],"time":45,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_renglot_w_spirytusie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z renglot w spirytusie"},{"id":"oc-plws-579463","title":"Grilled sturgeon","cuisine":"European","category":"Main","ingredients":["1600 g sturgeon (orig. 4–5 funty; range 1600–2000 g, lower bound used; historical measure, converted approximately)","to taste salt","1 pinch black pepper (orig. a pinch)","1 onion","2 tbsp olive oil (orig. 2 tbsp)","1 tbsp butter (orig. 1 tbsp)","to taste mustard sauce (Prepared sauce for serving; the source does not give its ingredients.)"],"steps":["Scald and clean the sturgeon.","Cut the fish into thin slices.","Finely chop the onion and press out its juice.","Sprinkle the fish with salt, pepper, and the onion.","Drizzle the fish with olive oil.","Leave the fish in the marinade for 120 minutes.","Brush the fish with butter.","Grill the fish over glowing coals on both sides until browned and cooked through.","Serve with the mustard sauce."],"time":120,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Jesiotr_z_rusztu","page":"Kucharka litewska (1913)/Jesiotr z rusztu"},{"id":"oc-plwb-15763","title":"Grilled zander (Sandacz z rusztu)","cuisine":"European","category":"Main","ingredients":["1 kg zander","35 g butter (some melted for brushing, the rest for serving)","1 tbsp vegetable oil (for greasing the grate)","to taste salt","1 tsp parsley leaves (chopped)"],"steps":["Clean and rinse the zander, fillet with the skin on, and cut into portions.","Dust the fish portions with salt and set aside in a cool place for 60 minutes.","Pat the fish dry with paper towels and brush with a portion of the melted butter.","Brush the preheated grill grate with vegetable oil, arrange the zander portions, and grill for about 5 minutes on each side until the skin is crisp and golden and the flesh is succulent.","Transfer the grilled fish to a serving platter, scatter chopped parsley leaves on top, and arrange pats of the remaining butter alongside."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sandacz_z_rusztu","page":"Książka kucharska/Sandacz z rusztu"},{"id":"oc-plwb-6257","title":"Grochówka (Polish pea soup)","cuisine":"European","category":"Soup","ingredients":["500 g dried yellow peas","150 g smoked bacon","500 g potatoes","1 onion","2 l water","to taste marjoram","to taste black pepper","to taste salt"],"steps":["Cover the peas with water, add two-thirds of the smoked bacon, and cook until the peas break down completely.","Peel and dice the potatoes, add them to the soup, and cook until tender.","Dice the remaining smoked bacon, render it in a frying pan into cracklings, add the chopped onion, and fry until golden.","Transfer the cracklings and onion into the soup pot and season to taste with salt, black pepper, and marjoram."],"time":105,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Groch%C3%B3wka","page":"Książka kucharska/Grochówka"},{"id":"oc-plws-1080969","title":"Ground Poppy Seed Filling for Cakes","cuisine":"European","category":"Other","ingredients":["400 g poppy seeds (originally 1 funt)","2 l water (boiling water for scalding the poppy seeds twice)","100 g sweet almonds (originally a quarter of a funt, peeled and ground)","3 bitter almonds (whole, ground together with the sweet almonds)","200 g sugar (originally half a funt of granulated sugar)","125 ml arrack or rum (originally 1 półkwaterek (historical Polish measure; a small glass))"],"steps":["Pour boiling water over the poppy seeds and let stand for 2 hours, then drain the water, pour fresh boiling water over the poppy seeds again, and leave for another 2 hours.","Drain the plumped poppy seeds thoroughly in a fine sieve.","Pound or finely grind the blanched sweet almonds together with three bitter almonds.","Combine the drained poppy seeds with the almonds and sugar and grind thoroughly for about an hour, or pass the mixture through a grinder three times and then beat until smooth, gradually adding the arrack a teaspoon at a time.","Use the finished poppy seed filling between cake layers or to make filled yeast rolls."],"time":310,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Mak_wiercony_do_przek%C5%82adania_ciast","page":"Baby, placki i mazurki/Mak wiercony do przekładania ciast"},{"id":"oc-plws-39489","title":"Grzanki do zup z parmezanem (Parmesan soup croutons)","cuisine":"European","category":"Side","ingredients":["1 wheat roll (orig. 1 roll, crust trimmed off)","to taste butter (unsalted or clarified, melted)","to taste Parmesan cheese (grated)"],"steps":["Trim the crust off the wheat roll on all sides and cut the crumb into even slices.","Melt the fresh unsalted butter or clarified butter in a small saucepan.","Dip each slice of roll into the melted butter so it soaks through, and immediately coat generously with grated Parmesan.","Arrange the croutons on a baking sheet and place in an oven preheated to 160 °C for 30 minutes before serving the soup."],"time":40,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Grzanki_do_zup_z_parmezanem","page":"365 obiadów za 5 złotych/Grzanki do zup z parmezanem"},{"id":"oc-plws-39490","title":"Grzanki rozmaite do zup (Breaded soup croutons)","cuisine":"European","category":"Side","ingredients":["1 wheat roll (orig. 1 roll)","to taste sweet cream (or milk, for soaking the roll)","1 egg (beaten)","to taste breadcrumbs (for coating)","to taste clarified butter (for frying)","to taste sugar (optional, when serving with fruit soup)"],"steps":["Cut the wheat roll into slices, then halve each slice.","Dip the half-slices in sweet cream or milk, then in beaten egg, and coat in breadcrumbs.","Heat clarified butter in a skillet and fry the croutons on both sides for about 5–8 minutes until golden brown.","Serve with tomato or sorrel soup, or dust with sugar before serving with fruit soups."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Grzanki_rozmaite","page":"365 obiadów za 5 złotych/Grzanki rozmaite"},{"id":"oc-plws-546699","title":"Grzybek z rybkami (soufflé pancake with small fish)","cuisine":"European","category":"Main","ingredients":["2 eggs (whole, yolks and whites separated)","200 g wheat flour (orig. 20 dkg)","250 ml water (enough to make a batter slightly thicker than crepe batter)","200 g fried small fish (orig. 20 dkg of fried and cooled small fish)","to taste salt","40 g vegetable oil or lard (orig. 4 dkg, divided into two equal portions)"],"steps":["Beat the egg yolks with the wheat flour, salt, and enough water to form a batter slightly thicker than crepe batter.","Whip the egg whites to stiff peaks and gently fold them into the batter.","Heat half of the fat in a skillet, pour in the batter, and cook slowly until browned underneath and beginning to set on top.","Scatter the fried small fish over the top of the pancake, flip it over onto the freshly heated second half of the fat, finish frying briefly, and serve hot straight from the skillet."],"time":30,"servings":2,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Grzybek_z_rybkami","page":"109 potraw/Grzybek z rybkami"},{"id":"oc-plws-580438","title":"Grzyby suszone faszerowane (stuffed dried mushrooms)","cuisine":"European","category":"Main","ingredients":["15 dried mushrooms (10 large caps for stuffing and 5 smaller mushrooms for chopping into the filling)","to taste butter (for the onion and baking the mushrooms)","1 onion (finely chopped)","1 egg (large)","to taste breadcrumbs (enough to bind the filling)","1 tbsp sour cream (for the pan sauce, plus extra for spooning over the mushrooms before baking)","2 tbsp water (for deglazing the pan, plus water for boiling the mushrooms)","to taste mashed potatoes (for serving)"],"steps":["Boil all the dried mushrooms in water until tender, about 30 minutes, and drain.","Press the ten large mushroom caps between two small boards to squeeze out excess water, and finely chop their stems along with the smaller mushrooms.","Fry the chopped onion in butter for 5 minutes, mix with the chopped mushrooms, egg, and enough breadcrumbs to hold the mixture together, then mound the filling onto the large mushroom caps.","Arrange the stuffed mushrooms in an ovenproof skillet with melted butter, drizzle with butter, spoon sour cream over them, and bake in an oven preheated to 180 °C for about 15 minutes.","Mound the mashed potatoes in the centre of a serving platter and arrange the baked mushrooms around them.","Pour two tablespoons of water and a tablespoon of sour cream into the baking skillet, boil for 1 minute, and pour the resulting pan sauce over the mashed potatoes."],"time":70,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Grzyby_suszone_faszerowane","page":"100 postnych i jarskich dań/Grzyby suszone faszerowane"},{"id":"oc-plws-580477","title":"Grzyby w koszyku (creamed mushrooms in a bread bowl)","cuisine":"European","category":"Main","ingredients":["500 g wheat loaf (large, round, day-old)","to taste butter (for brushing the loaf and cooking the mushrooms)","to taste hard cheese (sharp, coarsely grated)","750 g porcini mushrooms (fresh (or button mushrooms))","1 onion (finely chopped)","1 tbsp plain wheat flour","250 ml sour cream"],"steps":["Grate off the outer crust of the day-old half-kilogram wheat loaf on a coarse grater, slice off the top about 2 cm thick, and hollow out the centre with a spoon, leaving walls 2 cm thick.","Brush the hollowed loaf and the cut lid thinly inside and out with butter, sprinkle generously with grated sharp cheese, and bake in the oven at 160 °C for about 10 minutes until the cheese melts and the bread is lightly toasted.","Meanwhile, cook the sliced porcini mushrooms gently in butter with the chopped onion for about 15 minutes, then sprinkle with the wheat flour, pour in the sour cream, and simmer for another 5 minutes until the sauce is very thick.","Fill the toasted bread basket with the thick creamed mushrooms, replace the top lid, and return to the oven preheated to 180 °C for 10 minutes.","Serve the dish immediately from the oven while the bread remains crisp."],"time":55,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Grzyby_w_koszyku","page":"100 postnych i jarskich dań/Grzyby w koszyku"},{"id":"oc-plws-580472","title":"Grzyby z kaszą gryczaną (porcini mushrooms with buckwheat groats)","cuisine":"European","category":"Main","ingredients":["200 g buckwheat groats","to taste water (for cooking the groats until fluffy)","1 tbsp butter (for the groats, plus extra for greasing the dish and cooking the mushrooms)","500 g porcini mushrooms (fresh)","1 onion (finely chopped)","250 ml sour cream"],"steps":["Cook the buckwheat groats in water with a tablespoon of butter for about 15 minutes until tender and fluffy.","Cook the sliced porcini mushrooms gently in butter with the chopped onion for about 15 minutes, then stir in the sour cream.","Butter an ovenproof dish, spread the cooked buckwheat groats over the bottom, and spoon the creamed mushrooms on top without mixing the layers.","Place the dish in an oven preheated to 180 °C for 5 minutes and serve hot."],"time":50,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Grzyby_z_kasz%C4%85_gryczan%C4%85","page":"100 postnych i jarskich dań/Grzyby z kaszą gryczaną"},{"id":"oc-plws-1081100","title":"Gum Arabic Cough Drops","cuisine":"European","category":"Dessert","ingredients":["1000 g powdered gum arabic","1000 g icing sugar or caster sugar (plus a little for dusting the table)","1000 ml water (orig. 1000 g spring water)","100 ml orange blossom water or rosewater (orig. 100 g)","12 egg whites (whites)","2 tbsp wheat flour or potato starch (for dusting the table with icing sugar)"],"steps":["Quickly rinse the gum arabic with cold water, cover with 1 liter of water, and warm gently until completely dissolved, then strain the solution through a fine cloth.","Add the sugar to the strained solution and reduce over low heat until it has the consistency of a thick syrup.","Gradually add the orange blossom water (or rosewater) and egg whites, stirring constantly over very low heat until the mixture becomes very thick and pliable like dough.","Turn the thick mass out onto a table dusted with flour sifted with icing sugar, roll out, and cut into even cubes."],"time":90,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Cukierki_gumowe_od_kaszlu","page":"Baby, placki i mazurki/Cukierki gumowe od kaszlu"},{"id":"oc-plwb-62937","title":"Gęsie udka wolno pieczone w białym winie (slow-roasted goose legs in white wine)","cuisine":"European","category":"Main","ingredients":["2 goose legs (fresh or thawed)","100 ml white wine (dry or semi-dry)","1 tsp potato starch (for thickening the sauce)","2 tbsp water (cold, for mixing with the starch to make a slurry)","2 clove garlic (pressed)","2 fresh rosemary (sprigs)","0.5 tsp sea salt","0.5 tsp freshly ground black pepper","0.5 tsp sweet paprika"],"steps":["Clean and pat dry the goose legs, rub with the pressed garlic, sea salt, pepper, and sweet paprika, drape with the rosemary sprigs, cover, and chill in the refrigerator for at least 10 hours.","Take the meat out of the refrigerator 30 minutes before roasting, place in a baking dish over the rosemary sprigs, and pour in the white wine.","Cover the dish tightly and roast in an oven preheated to 120 °C for 3.5 hours.","Remove the lid, brush any seasonings from the skin into the sauce, raise the oven temperature to 180 °C, and roast uncovered for another 30 minutes, basting with the pan juices.","Remove the roasted legs, pour off the pan drippings, skim the rendered fat off the top, and transfer the remaining dark juices to a saucepan and bring to a boil.","Whisk the potato starch into cold water, pour into the simmering sauce, and stir vigorously until thickened."],"time":260,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/G%C4%99sie_udka_wolno_pieczone_w_bia%C5%82ym_winie","page":"Książka kucharska/Gęsie udka wolno pieczone w białym winie"},{"id":"oc-plwb-21735","title":"Gęś pieczona z jabłkami (roast goose with apples and caraway)","cuisine":"European","category":"Main","ingredients":["1 whole goose (approx. 3–4 kg)","to taste salt","0.5 tsp caraway seeds","1 fresh marjoram (sprig, optional)","1.5 kg tart apples (a dozen or so small apples for stuffing and a few larger apples to bake separately)","2 onions","3 tbsp broth (2–3 tablespoons)","1 tbsp plain flour"],"steps":["Wash and dry the goose, then rub it inside and out with salt and caraway seeds.","Stuff the goose cavity with the small tart apples and the sprig of marjoram, then sew the opening closed.","Peel and slice the onions, arranging them across the bottom of the roasting pan beneath the goose.","Roast the goose in an oven preheated to 180 °C for about 2.5 hours, basting first with the broth and later with rendered pan juices; bake the larger apples separately toward the end of roasting.","Pour off the pan drippings, whisk with the flour, and simmer briefly until thickened into gravy.","Arrange the roast goose on a serving platter, surround with the large baked apples, and spoon some of the gravy over top."],"time":180,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/G%C4%99%C5%9B_pieczona_z_jab%C5%82kami","page":"Książka kucharska/Gęś pieczona z jabłkami"},{"id":"oc-plws-569427","title":"Głowizna wielkanocna nadziewana (stuffed pig's head galantine)","cuisine":"European","category":"Main","ingredients":["1 pig's head (salted, with brain and tongue removed)","1.5 kg minced pork, beef, or veal (orig. 1 to 1.5 kg, for the forcemeat)","2 wheat rolls (soaked, for the forcemeat)","2 eggs (raw, for the forcemeat)","400 g smoked bacon and ham (orig. 40 dag, sliced)","400 g calf's liver (orig. 40 dag, soaked and sliced)","6 hard-boiled eggs (cut into quarters)","12 gherkins (orig. a dozen or so)","1 bunch Polish soup vegetables (włoszczyzna, as for broth)","1 onion","4 tbsp vinegar (orig. several tablespoons of strong vinegar)","3 bay leaf","to taste black pepper","to taste salt"],"steps":["Remove all bones from the salted pig's head without damaging the skin, then sew the snout and eye openings shut with strong thread.","Prepare a seasoned forcemeat from 1.5 kg of minced pork, beef, or veal mixed with soaked bread roll, 2 eggs, and seasonings, as for minced-meat patties.","Pack the head in layers with the meat forcemeat, slices of smoked bacon and ham (400 g), soaked calf's liver (400 g), quarters from 6 hard-boiled eggs, and gherkins.","Sew the neck opening closed with clean linen, splint the ears with wooden sticks tied with string to preserve their shape (and optionally sew the entire head into a cloth).","Place the stuffed head in a large pot along with the removed bones, soup vegetables, onion, bay leaf, black pepper, and salt, cover with hot water and several tablespoons of vinegar, and simmer gently for 3 hours from the moment it boils.","Remove the head, let it cool, and remove the threads; reduce the cooking stock to a clear jelly, let it set, and use it to garnish the sliced galantine."],"time":270,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/G%C5%82owizna","page":"Domowe wędliny/Głowizna"},{"id":"oc-plwb-61110","title":"Halászlé (Hungarian fisherman's soup)","cuisine":"European","category":"Soup","ingredients":["1 carp (medium)","500 g tench, perch, and roach","2 tbsp lard","2 onions","2 hot peppers","2 sweet bell peppers (mild)","3 tomatoes","5 clove garlic","to taste salt","to taste pepper","to taste water (for cooking the soup)"],"steps":["Gut and rinse the fish, cut the cleaned carp into steaks, and rub with salt.","Melt the lard in a cast-iron kettle or deep pot and sauté the chopped onions with the sliced hot peppers.","Add the whole small fish (tench, perch, and roach) with heads and bones to the pot, cover with water, add the sliced sweet peppers, and salt.","Simmer the broth over low heat for 90 minutes, gently swirling the pot occasionally, and add the peeled tomatoes towards the end of cooking.","Once the tomatoes have broken down, pass the broth through a sieve, return it to the pot, top up with water if needed, and bring to the boil.","Add the crushed garlic cloves, season with pepper, add the carp steaks, and cook for about 7 minutes longer."],"time":130,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/W%C4%99gierska_zupa_rybna","page":"Książka kucharska/Węgierska zupa rybna"},{"id":"oc-plws-508385","title":"Ham and egg tartlets","cuisine":"European","category":"Snack","ingredients":["400 g plain wheat flour","200 g butter (or lard)","2 tbsp sour cream","to taste salt (for the pastry and the eggs)","10 tbsp ham (marbled, cut into strips (1 tbsp per tartlet across 10 tartlets))","10 eggs (1 egg per tartlet)","to taste hard cheese (grated)","to taste black pepper"],"steps":["Knead a shortcrust pastry from the wheat flour, butter, sour cream, and a pinch of salt; cover with a bowl and let rest for 60 minutes.","Roll the dough out very thinly, line ten metal tartlet tins, weight with dried peas for blind baking, and bake in an oven preheated to 190 °C for about 18 minutes until golden.","Remove the dried baking peas from the pre-baked shells, set the tartlets on a baking sheet, and spoon a tablespoon of ham strips into each shell.","Crack one raw egg into each tartlet over the ham, season with salt and pepper, and sprinkle with grated cheese.","Return to the oven at 180 °C for about 7 minutes until the whites are nicely set, and serve warm."],"time":105,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Tartletki_z_jaj_z_szynk%C4%85","page":"100 potraw z jaj/Tartletki z jaj z szynką"},{"id":"oc-plws-508361","title":"Ham omelette","cuisine":"European","category":"Breakfast","ingredients":["6 eggs","100 g ham (cooked or raw, marbled with fat)","to taste butter (for frying the omelette)","to taste salt"],"steps":["Cut the marbled ham into very thin strips.","Beat the eggs with a pinch of salt, pour into a skillet with hot melted butter, and cook for about 3 minutes until set underneath while still slightly runny on top.","Scatter the ham strips evenly over the omelette and cook for another 2 minutes until the ham is heated through and its fat turns translucent.","Fold the omelette in half (or fold both edges toward the centre), transfer to a serving platter, and serve immediately while hot."],"time":11,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Omlet_z_szynk%C4%85","page":"100 potraw z jaj/Omlet z szynką"},{"id":"oc-plws-39732","title":"Hamburg-style beefsteak with eggs and mushrooms","cuisine":"European","category":"Main","ingredients":["180 g beef tenderloin or top rump (orig. 1 thick round piece)","1 tsp olive oil","0.5 tsp butter","1 large white onion (sliced into rounds)","1 tbsp mushrooms or saffron milk caps braised in butter","4 small boiled potatoes (orig. several small potatoes)","2 eggs","2 tbsp strong meat bouillon","to taste salt"],"steps":["Shape the thick piece of beef with a knife or rolling pin into a round medallion (without pounding it flat), brush with olive oil, and salt lightly.","In a small round skillet (about 15 cm in diameter), heat half a teaspoon of butter over high heat until lightly browned.","Toss the sliced white onion into the butter and immediately lay the meat on top; sear briskly over high heat for about 3–4 minutes.","Once browned underneath, turn the meat carefully with a fork (without piercing it or pressing out the juices).","Arrange a spoonful of butter-braised mushrooms or saffron milk caps on one side of the meat, the small boiled potatoes on the other side, and carefully crack an egg into each of the two remaining sides.","Cook for another 2–3 minutes until the egg whites set while the beef stays pink and juicy inside, then spoon the hot strong bouillon over everything and serve right in the little skillet."],"time":20,"servings":1,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Befsztyk_po_hamburgsku","page":"365 obiadów za 5 złotych/Befsztyk po hamburgsku"},{"id":"oc-plws-548146","title":"Hard Candies","cuisine":"European","category":"Snack","ingredients":["500 g sugar (in lumps)","100 ml water (as much as the sugar absorbs when dipped)","2 tbsp vinegar (very good, strong)","0.25 tsp flavoring oil (a few drops of rose, vanilla, lemon, or peppermint oil)","1 tsp olive oil (for greasing the marble slab)"],"steps":["Dip 500 g of sugar briefly in water until it stops hissing, then transfer to a saucepan and set over high heat.","Once the sugar comes to a boil, pour in 2 tablespoons of strong vinegar and boil until the caramel thickens and a drop plunged into cold water becomes brittle and snaps when bitten.","Add a few drops of the chosen flavoring oil (rose, vanilla, lemon, or peppermint), stir quickly, and pour the mixture onto a marble slab greased with olive oil.","When the candy cools slightly while still pliable, score it into strips, and once completely cooled, break into pieces and wrap in colored papers."],"time":40,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Karmelki","page":"Doświadczone sekreta smażenia konfitur i soków/Karmelki"},{"id":"oc-plws-1081020","title":"Hard-Boiled Egg Mazurek (Mazurek z twardych jaj)","cuisine":"European","category":"Cake","ingredients":["200 g sweet almonds (orig. half a funt, finely chopped)","200 g hard-boiled egg yolk (orig. half a funt yolks from 10–12 hard-boiled eggs)","200 g powdered sugar (orig. half a funt fine sugar (plus optional sugar or icing for the top))","0.5 vanilla bean (half a pod, pounded)","6 egg white (raw, beaten to stiff peaks)","6 wafer sheets (sheets (opłatki) glued together)"],"steps":["Mash 200 g of yolks from 10–12 hard-boiled eggs thoroughly with a spoon in a bowl, then cream them with 200 g of fine sugar, the pounded half vanilla bean, and 200 g of finely chopped sweet almonds.","Beat 6 raw egg whites to stiff peaks and fold thoroughly into the egg-yolk and almond mixture.","Spread the mixture over 6 wafer sheets glued together (if you do not plan to ice the mazurek after baking, sprinkle the top with sugar before placing it in the oven).","Place in a low oven (140–150 °C) for about 25 minutes until the mazurek dries out well, and optionally glaze after removing from the oven."],"time":65,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Mazurek_z_twardych_jaj","page":"Baby, placki i mazurki/Mazurek z twardych jaj"},{"id":"oc-plws-502303","title":"Hard-boiled eggs in hot anchovy cream sauce","cuisine":"European","category":"Main","ingredients":["3 salted anchovies (soaked and boned (or 1 ulik-style salted herring))","1 onion (large, grated)","1 tbsp butter","1 tbsp plain wheat flour","250 ml water","250 ml sour cream","to taste black pepper","10 eggs (hard-boiled)"],"steps":["Hard-boil the eggs for 10 minutes, peel, and halve them lengthwise.","Bone the soaked anchovies and chop them very finely.","Sauté the grated onion in a tablespoon of butter for 4 minutes, add the minced anchovies, and cook together for another 3 minutes until they form a smooth paste.","Dust the paste with wheat flour, stir in the water and sour cream, season with black pepper, and simmer over low heat for 3 minutes, stirring constantly.","Arrange the egg halves on a serving platter, pour the hot anchovy sauce over them, and serve immediately."],"time":40,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_z_sosem_sardelowym","page":"100 potraw z jaj/Jaja z sosem sardelowym"},{"id":"oc-plwb-16534","title":"Hard-boiled eggs on spring vegetable slaw","cuisine":"European","category":"Salad","ingredients":["6 eggs","4 carrots","1 bunch spring onions","1 lettuce","400 g canned sweetcorn","70 g plain yogurt (1/3 container)","70 g sour cream (1/3 container)","1 tsp mustard","to taste parsley leaves","to taste salt","to taste black pepper"],"steps":["Hard-boil the eggs, let them cool, and peel them.","Trim and chop the spring onions, peel and coarsely grate the carrots, drain the sweetcorn, and rinse and dry the lettuce.","In a small bowl, whisk the plain yogurt with the sour cream and mustard, then season the dressing with salt and black pepper.","Combine the spring onions, grated carrots, and sweetcorn in a large bowl.","Arrange the lettuce leaves on plates, top with the vegetables, drizzle with the dressing, arrange the halved eggs on top, and garnish with parsley leaves."],"time":25,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_na_jarzynce","page":"Książka kucharska/Jajka na jarzynce"},{"id":"oc-plws-550039","title":"Hawthorn liqueur","cuisine":"European","category":"Drink","ingredients":["1 l ripe hawthorn (orig. 1 litre of ripe, frost-nipped hawthorn (about 600 g))","1 l spirit (orig. 1 litre of the best spirit (1.5 l in the less sweet version))","1 l rye vodka (orig. 1 litre of clean, strong rye vodka (1.5 l in the less sweet version))","1 kg sugar candy (orig. 1 kilogram of finely crushed sugar candy)"],"steps":["Put 1 l of ripe, frost-nipped hawthorn into a bowl and crush the fruit thoroughly with a rolling pin.","Transfer the crushed hawthorn to a demijohn, pour in 1 l of the best spirit mixed beforehand with 1 l of strong rye vodka (or 1.5 l of each spirit in the less sweet version), and add 1 kg of finely crushed sugar candy.","Leave the demijohn in a warm place for 10 days, shaking it every day.","After 10 days, filter the liqueur, bottle it, cork it, and store it in a cool place."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_g%C5%82ogowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier głogowy"},{"id":"oc-plws-544158","title":"Hawthorn or Rosehip Preserve","cuisine":"European","category":"Preserve","ingredients":["500 g garden hawthorn berries (large, ripe, weighed after pitting)","1.5 kg sugar (for the thick syrup)","500 ml water (2 glasses for the syrup, plus cold and boiling water for soaking and blanching the fruit)","1 lemon (juice of the whole lemon and a few small pieces of peel)","3 tbsp gooseberry juice (optional, for acidifying the syrup)"],"steps":["Remove the stems from large garden hawthorn berries picked before the frosts, pit the seeds, and drop the berries immediately into cold water.","Transfer the rinsed berries to boiling water and blanch covered until tender, taking care that they do not burst.","Transfer the parboiled hawthorn berries twice into progressively colder water, then spread on a sieve to drain thoroughly.","For every 500 g of pitted hawthorn berries, boil a syrup from 1.5 kg of sugar and 500 ml of water, adding the juice of 1 lemon, a few pieces of lemon peel, and optionally a few tablespoons of gooseberry juice.","When the syrup becomes clear and begins to pearl, add the drained hawthorn berries and simmer slowly until the fruit becomes translucent and sinks to the bottom; once cooled, transfer to jars."],"time":105,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/G%C5%82%C3%B3g_czyli_Hecze_pecze","page":"Doświadczone sekreta smażenia konfitur i soków/Głóg czyli Hecze pecze"},{"id":"oc-plws-544162","title":"Hawthorn Preserve Another Way","cuisine":"European","category":"Preserve","ingredients":["500 g hawthorn berries (ripe, weighed after pitting)","1 kg sugar (divided into portions: 500 g on the first day and 250 g each on the second and third days)","0.5 lemon (juice squeezed in toward the end of cooking)","500 ml water (for boiling the syrup and cold water for soaking and blanching the hawthorn berries)"],"steps":["Pit the hawthorn berries, dropping them into cold water, then rinse and simmer in fresh water over very low heat until soft without bursting.","Drain the hawthorn berries in a colander, rinse with cold water, and leave on a sieve to drain.","Boil a light syrup from 500 g of sugar and water, skim, strain through muslin, and pour lukewarm over the fruit in a bowl for a day.","On the second day, drain the syrup, add 250 g of sugar, bring to a boil, skim, strain, and pour the lukewarm syrup back over the hawthorn berries.","On the third day, drain the syrup, add the remaining 250 g of sugar, bring to a boil, strain, add the hawthorn berries and the juice of half a lemon, and simmer over low heat for 15 minutes; once cooled, transfer to jars."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/G%C5%82%C3%B3g_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Głóg innym sposobem"},{"id":"oc-plws-544163","title":"Hawthorn Preserve Yet Another Way","cuisine":"European","category":"Preserve","ingredients":["500 g hawthorn berries (ripe, weighed after pitting)","1 kg sugar (for the syrup)","250 ml water (1 glass for the syrup, plus boiling water for blanching the fruit)","250 ml white wine (for the syrup)"],"steps":["Remove the stems from ripe hawthorn berries, pit the seeds, weigh out 500 g of fruit, blanch in boiling water until tender (taking care that they do not burst), and drain on a sieve.","Boil a thick syrup from 1 kg of sugar, 250 ml of water, and 250 ml of white wine, skimming off the foam carefully.","Add the drained hawthorn berries to the boiling syrup and cook for 30 minutes — first over higher and then over lower heat.","Transfer the cooled preserve into jars, tie tightly, and store in a cool, dry place."],"time":105,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/G%C5%82%C3%B3g_jeszcze_na_inny_spos%C3%B3b","page":"Doświadczone sekreta smażenia konfitur i soków/Głóg jeszcze na inny sposób"},{"id":"oc-plwb-12748","title":"Hekele (Silesian herring and egg spread)","cuisine":"European","category":"Snack","ingredients":["3 salted herring","3 eggs","1 onion","1 fermented (brine) pickle","to taste black pepper"],"steps":["Hard-boil the eggs, let them cool, and peel them.","Soak the salted herring in cold water and remove any bones.","Grind the herring fillets in a meat grinder together with the eggs, peeled onion, and fermented pickle.","Season the mixture with black pepper to taste and mix thoroughly."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Hekele","page":"Książka kucharska/Hekele"},{"id":"oc-plwb-21449","title":"Herb-marinated breaded schnitzels (Sznycle z ziołami)","cuisine":"European","category":"Main","ingredients":["750 g turkey schnitzels","2 clove garlic","2 tbsp lemon juice","1 tsp marjoram","1 tsp thyme","2 eggs","to taste plain flour (for coating)","to taste breadcrumbs (for coating)","to taste vegetable oil (3 tbsp for the marinade, plus extra for frying)","to taste salt","to taste pepper"],"steps":["Lightly pound the turkey schnitzels with a dampened meat mallet.","Mix 3 tablespoons of oil with the lemon juice, finely chopped garlic, marjoram, thyme, salt, and pepper.","Brush the schnitzels with the marinade and chill in the refrigerator for 60 minutes.","Dredge the marinated schnitzels in flour, dip in beaten eggs, coat with breadcrumbs, and fry in hot oil on both sides until golden brown."],"time":90,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sznycle_z_zio%C5%82ami","page":"Książka kucharska/Sznycle z ziołami"},{"id":"oc-plwb-13997","title":"Herb-marinated herring","cuisine":"European","category":"Snack","ingredients":["500 g herring fillets","3 tsp sugar (level)","1 tsp dried marjoram","1 tsp dried oregano","1 tsp ground allspice","2 onions","80 ml vegetable oil"],"steps":["Mix the sugar, marjoram, oregano, and ground allspice with the vegetable oil to create a herb marinade.","Cut the onions into quarters, slice into thin strips, combine with the marinade, and set aside for about 15 minutes for the flavours to meld.","Cut the herring fillets into bite-sized pieces, add to the onion in marinade, mix well, and chill in the refrigerator for about 30 minutes before serving."],"time":55,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%9Aledzie_w_zio%C5%82ach","page":"Książka kucharska/Śledzie w ziołach"},{"id":"oc-plwb-14003","title":"Herb-roasted pork loin (Schab pieczony w ziołach)","cuisine":"European","category":"Main","ingredients":["1.25 kg boneless pork loin","3 celery stalks","3 shallots","2 tsp dried oregano","2 tsp dried thyme","2 tsp black peppercorns (coarsely ground)","1 bunch parsley leaves","2 tsp olive oil","to taste salt"],"steps":["Rinse and pat the pork loin dry, trimming away any silver skin.","Peel the shallots, wash and pat dry the parsley leaves and celery stalks, then finely chop everything.","Mix the chopped vegetables with the oregano, thyme, and coarsely ground black pepper.","Rub the pork with olive oil, coat it evenly on all sides in the herb-vegetable mixture, and let stand for 10 minutes.","Place the roast in a heatproof dish, put it in an oven preheated to 240 °C, and bake for 15 minutes.","Reduce the oven temperature to 180 °C and bake for another 30 minutes.","Remove the roasted pork loin from the oven, season with salt, cover with a cloth for 10 minutes, and carve into thick slices."],"time":65,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Schab_pieczony_w_zio%C5%82ach","page":"Książka kucharska/Schab pieczony w ziołach"},{"id":"oc-plws-39479","title":"Homemade Cut Egg Noodles (Kluski krajane)","cuisine":"European","category":"Side","ingredients":["500 ml wheat flour (orig. half a kwarta (approximately 325 g))","1 egg","100 ml water (for kneading the dough and water for boiling and rinsing the noodles)","to taste salt (for salting the water)"],"steps":["Knead a medium-firm dough from the wheat flour, egg, and a small amount of water, then roll it out thinly.","Cut the sheet of dough into strips about 2–3 cm (two fingers) wide, stack 3–4 strips on top of one another, and slice crosswise into finer or thicker noodles (or cut narrower strips into tiny squares).","Bring salted water to a boil in a pot, drop in the noodles, and cook until they float to the surface.","Drain the noodles in a colander, rinse with cold water to keep them from sticking together, and transfer to a tureen of clear broth (for mushroom or fish soup you may drop them directly into the simmering soup, but for clear broth always boil them separately so the broth does not turn cloudy)."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kluski_krajane","page":"365 obiadów za 5 złotych/Kluski krajane"},{"id":"oc-plws-551551","title":"Homemade maraschino made with raspberry and sour-cherry juice","cuisine":"European","category":"Drink","ingredients":["2.5 l cooked raspberry juice (orig. two and a half litres)","1 l cooked sour-cherry juice (orig. 1 litre)","750 ml orange-flower water (orig. three quarters of a litre)","3250 g icing sugar or caster sugar (orig. three and a quarter kilograms of fine sugar)"],"steps":["Pour 2.5 litres of raspberry juice, 1 litre of sour-cherry juice and 750 ml of orange-flower water into a large glass demijohn.","Mix the juices and dissolve 3250 g of fine sugar in them cold.","Stopper the demijohn tightly and leave it undisturbed for 6 months, until the liquid is completely clear.","Draw off the clear liquid into bottles, filtering the sediment from the bottom through filter paper. Cork the bottles, seal with sealing wax, and store in a cool, dry place."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Maraskino","page":"Doświadczone sekreta smażenia konfitur i soków/Maraskino"},{"id":"oc-plws-546635","title":"Homestyle Meat Goulash","cuisine":"European","category":"Main","ingredients":["400 g beef, veal, or pork (orig. 40 dkg of tender meat free of sinew)","40 g lard or margarine (orig. 4 dkg)","2 onion (medium)","500 ml water (for braising the meat and thinning the flour)","1 tbsp wheat flour","1 tsp ground paprika (orig. 1 coffee spoon)","to taste salt"],"steps":["Cut the meat into walnut-sized pieces, pound lightly, season with salt, and brown well on all sides in hot fat.","Transfer the browned meat to a saucepan along with the sliced onions, pour in water, and braise slowly under a lid until completely tender.","Blend a tablespoon of wheat flour with a little cold water, stir into the tender meat, add the ground paprika, and simmer for a few minutes longer until a generous, thick gravy forms."],"time":95,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Gulasz","page":"109 potraw/Gulasz"},{"id":"oc-plwb-14722","title":"Honey-roasted chicken","cuisine":"European","category":"Main","ingredients":["1.5 kg whole chicken","3 tbsp margarine (vegetable spread)","4 tbsp honey","to taste lemon juice","0.5 tsp nutmeg","to taste salt","to taste pepper","125 ml water"],"steps":["Rinse and pat dry the chicken, cut off the neck and wings, and rub the carcass inside and out with salt, pepper, and lemon juice.","Melt the margarine in a pan, mix with the honey and nutmeg, and brush the glaze inside the cavity and all over the outside of the chicken.","Place the chicken in a roasting tin, spoon over the remaining glaze, and pour 125 ml of water into the bottom of the tin.","Roast in the oven for about 90 minutes, basting frequently with the pan juices.","Remove the roasted chicken, carve into portions, and spoon over the pan sauce."],"time":90,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_w_miodzie","page":"Książka kucharska/Kurczak w miodzie"},{"id":"oc-plws-548312","title":"Honeyless spiced gingerbread (piernik bez miodu)","cuisine":"European","category":"Cake","ingredients":["500 g plain wheat flour (orig. 50 dkg)","250 g sugar (orig. 25 dkg (200 g for egg yolks and 50 g for caramel))","3 eggs (separated into yolks and whites)","1 tsp ground mixed spice: cloves, allspice, and cinnamon","1 tbsp lard or vegetable oil (plus extra for greasing cake pan)","280 ml water (orig. 1 cup (250 ml) + a few tbsp (30 ml) for caramel)","3 tsp baking powder (orig. 1 packet baking powder)","2 tbsp breadcrumbs (for coating springform pan)"],"steps":["Beat the egg yolks with 200 g of sugar and 1 tbsp of lard or oil until pale and fluffy.","Caramelise the remaining 50 g of sugar in a skillet to a dark caramel, dissolve in 30 ml of water, then bring to a boil with the mixed spice and the remaining 250 ml of water.","Mix the plain wheat flour with baking powder, gradually pour in the hot caramel mixture while stirring continuously, then combine thoroughly with the beaten egg yolks.","Whip the egg whites to stiff peaks and fold gently into the batter.","Transfer the batter into a springform pan greased with fat and dusted with breadcrumbs. Bake in an oven preheated to 160–170 °C for 45–60 minutes."],"time":85,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Piernik_bez_miodu","page":"109 potraw/Piernik bez miodu"},{"id":"oc-plws-546640","title":"Horsemeat pâté (pasztet z koniny)","cuisine":"European","category":"Other","ingredients":["750 g tender horsemeat (orig. 75 dkg)","125 ml vinegar (orig. 1/2 cup)","5 large onions (orig. 4–5 whole)","400 g fatty pork belly (orig. 40 dkg)","6 very large potatoes (orig. 5–6 whole)","2 eggs (large)","1 tsp marjoram","to taste allspice berries","to taste nutmeg (freshly grated)","to taste black pepper","to taste salt","2 tbsp breadcrumbs (for coating the pan)"],"steps":["Marinate the horsemeat in vinegar with allspice berries, then braise covered until tender for about 90 minutes.","Braise the pork belly separately with whole peeled onions, and boil the potatoes in their skins, peel, and add to the tender pork belly.","Pass the braised horsemeat, pork belly, onions, and potatoes twice through the fine plate of a meat grinder.","Transfer the mixture to a bowl, season with salt, pepper, grated nutmeg, and marjoram, beat in the whole eggs, and beat thoroughly for about 30 minutes.","Transfer the mixture into a springform pan greased with braising fat and dusted with breadcrumbs, then bake in an oven preheated to 180 °C for 60 minutes.","Once the pâté cools slightly, turn it out onto a board and set in a cold place overnight (for about 8 hours). The next day, slice thinly."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Pasztet_z_koniny","page":"109 potraw/Pasztet z koniny"},{"id":"oc-plwb-7870","title":"Horseradish and apple cream sauce","cuisine":"European","category":"Sauce","ingredients":["2 horseradish roots (medium)","2 apples (tart)","to taste lemon juice","1 tsp icing sugar","1 pinch salt","250 ml whipping cream"],"steps":["Grate the horseradish roots on a fine grater, transfer to a sieve, pour boiling water over them, and leave to cool.","Peel the apples, grate them on the same grater, and immediately mix with the lemon juice and chilled horseradish.","Add the whipping cream, season with icing sugar, a pinch of salt, and extra lemon juice if needed, and serve within 2 hours of preparation."],"time":15,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_chrzanowy_z_jab%C5%82kami","page":"Książka kucharska/Sos chrzanowy z jabłkami"},{"id":"oc-plwb-7876","title":"Horseradish cream sauce with white wine","cuisine":"European","category":"Sauce","ingredients":["1 horseradish root (large)","125 ml dry white wine","500 ml whipping cream","1 tbsp sour cherry juice","1 tbsp redcurrant juice","1 tbsp mild Polish mustard","to taste lemon juice","1 tsp icing sugar","to taste salt"],"steps":["Grate the horseradish on a fine grater, place on a sieve, scald with boiling water, and leave to drain and cool.","Combine the cooled horseradish with dry white wine, whipping cream, sour cherry juice, redcurrant juice, and mild Polish mustard.","Season the sauce carefully with icing sugar, lemon juice, and salt, stir thoroughly, and serve within 2 hours of preparation."],"time":15,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_chrzanowy_z_winem","page":"Książka kucharska/Sos chrzanowy z winem"},{"id":"oc-plws-580460","title":"Hreczuchy (buckwheat fritters)","cuisine":"European","category":"Main","ingredients":["250 ml buckwheat flour","to taste sour cream (for mixing the batter and for serving)","to taste salt","to taste butter (for deep-frying (mixed in equal parts with coconut oil))","to taste coconut oil (for frying)"],"steps":["Mix the buckwheat flour with enough sour cream to form a thick batter that drops easily from a spoon, and season with salt.","Heat equal parts of butter and coconut oil in a deep skillet.","Drop spoonfuls of the batter into the hot fat and fry the fritters for about 3 minutes per side until golden brown.","Drain the fried hreczuchy on paper towels to remove excess fat and serve hot with sour cream."],"time":25,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Hreczuchy","page":"100 postnych i jarskich dań/Hreczuchy"},{"id":"oc-plws-580400","title":"Hreczuchy ze śmietaną (buckwheat patties with sour cream)","cuisine":"European","category":"Main","ingredients":["500 g buckwheat flour (plus a little extra for dusting)","to taste water (boiling, for scalding the flour)","1 tbsp butter (for the dough, plus extra for frying)","to taste salt (for the dough and cheese filling)","400 g farmer's cheese (not sour, pressed dry)","2 eggs (whole)","1 tsp sugar (for the cheese filling (plus optional extra for serving))","to taste coconut oil (added to the butter for frying)","to taste sour cream (for serving)"],"steps":["Mix the buckwheat flour with boiling salted water and a tablespoon of butter to form a thick paste, then set aside until completely cool.","Press the farmer's cheese dry and mash it thoroughly with the eggs, salt, and a teaspoon of sugar until smooth.","Shape the cooled buckwheat dough into thin rounds, dusting them with buckwheat flour, place a portion of the cheese filling on each, and pinch the edges tightly so the cheese does not leak out.","Fry the hreczuchy in hot butter mixed with coconut oil for about 4 minutes per side until deeply golden brown.","Serve the hot hreczuchy with sour cream."],"time":55,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Hreczuchy_ze_%C5%9Bmietan%C4%85","page":"100 postnych i jarskich dań/Hreczuchy ze śmietaną"},{"id":"oc-plwb-15532","title":"Hungarian beef goulash with wine","cuisine":"European","category":"Main","ingredients":["500 g beef stew meat","200 g potatoes","4 onions","2 red and green bell peppers (1–2 pods)","60 g tomato paste","200 ml dry wine","250 ml water (for basting during braising)","80 g lard or vegetable oil","to taste ground red paprika","1 bay leaf","to taste caraway seeds","to taste salt"],"steps":["Cut the beef into small, uniform pieces and brown in a pot in heated lard or oil.","Add the chopped onion, bay leaf, and caraway, then braise over low heat, adding splashes of water from time to time.","Toward the end of braising, season with salt, add the chopped fresh bell peppers, ground paprika, tomato paste, wine, and peeled diced potatoes.","Cook everything covered until the meat and potatoes are tender."],"time":110,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gulasz_w%C4%99gierski_na_winie","page":"Książka kucharska/Gulasz węgierski na winie"},{"id":"oc-plwb-18842","title":"Hungarian-style cucumber salad (mizeria po węgiersku)","cuisine":"European","category":"Salad","ingredients":["500 g cucumbers (salad cucumbers)","1 onion (small)","1.5 tbsp wine vinegar (or cider vinegar)","to taste water (to dilute vinegar)","to taste sweet ground paprika","to taste salt","to taste black pepper"],"steps":["Wash and dry the cucumbers, then slice them thinly.","Peel the onion, slice into rings, combine with the cucumbers, sprinkle lightly with salt, and let stand for 60 minutes.","Dilute the wine vinegar with a little water, stir into the accumulated cucumber juices, and season with salt and pepper.","Chill the salad in the refrigerator, and dust with sweet ground paprika before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mizeria_po_w%C4%99giersku","page":"Książka kucharska/Mizeria po węgiersku"},{"id":"oc-plwb-18558","title":"Ice cream cheesecake (Sernik lodowy)","cuisine":"European","category":"Cake","ingredients":["1 sponge cake base","to taste lemon juice (for the punch)","50 ml vodka","1 kg farmer's cheese","250 ml plain yogurt (or cream)","5.5 tbsp gelatine","250 ml icing sugar","1 canned peaches in syrup (can, half for the filling and half for garnish)","2 pears","1 banana","100 g raisins","200 ml ice cream (for serving)"],"steps":["Place the sponge cake base into the bottom of a springform tin and soak it with a punch made from about 330 ml of water, lemon juice, and vodka.","Pass the farmer's cheese through a mincer three times, then cream it with the icing sugar and plain yogurt or cream.","Dissolve the gelatine in a small amount of boiling water, allow to cool, and mix into the cheese mixture along with the raisins and half of the diced peaches.","Pour the setting cheese mixture over the sponge base and refrigerate until completely firm.","Slice the pears, banana, and remaining peaches, and arrange them over the chilled cheesecake along with scoops of ice cream just before serving."],"time":40,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sernik_lodowy","page":"Książka kucharska/Sernik lodowy"},{"id":"oc-plws-548160","title":"Iced Coffee","cuisine":"European","category":"Drink","ingredients":["500 ml black coffee (strong, freshly brewed)","250 ml heavy whipping cream (fresh, well chilled)","2 tbsp sugar (fine, for lightly sweetening the cream)"],"steps":["Brew strong black coffee, pour into bottles, cork tightly, and pack in ice until thoroughly chilled.","Whip the fresh heavy cream to stiff peaks, sweeten lightly with sugar, mix gently, and set the bowl in ice as well.","To serve, pour the cold coffee into cups, add a portion of ice-chilled whipped cream, stir very gently, and top with another portion of whipped cream."],"time":70,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Kawa_mro%C5%BCona","page":"Doświadczone sekreta smażenia konfitur i soków/Kawa mrożona"},{"id":"oc-plws-42504","title":"Italian-style mixed vegetable salad with pickles and herring (sałatka włoska ze śledziem)","cuisine":"European","category":"Salad","ingredients":["1 beetroot","12 potatoes (orig. around a dozen)","2 carrots (orig. a couple)","60 g dry white beans (orig. 1 handful)","2 celeriac","1 tbsp pickled gherkins (sliced into strips)","150 g pickled saffron milk caps and mushrooms","2 tbsp pickled shallots and capers","1 salted herring (or 12 anchovies)","4 tbsp olive oil","2 tbsp vinegar","1 tsp sugar","to taste black pepper","to taste salt"],"steps":["Boil the beetroot, potatoes, carrots, white beans, and celeriac separately in salted water until tender, then cool, peel the root vegetables, and cut into thin strips.","Cut the gherkins, pickled mushrooms, some of the saffron milk caps, and pickled shallots into strips. Combine with the vegetables, reserving the beetroot until the end, and add the capers.","Debone the herring, chop finely, and add to the salad mixture.","Pour in olive oil and vinegar, season with pepper, sugar, and salt if needed, fold in the beetroot strips at the very end to minimize discolouration, and toss gently.","Transfer the salad into a serving bowl and garnish with whole pickled saffron milk caps."],"time":90,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sa%C5%82ata_z_r%C3%B3%C5%BCnych_jarzyn_i_pikl%C3%B3w","page":"365 obiadów za 5 złotych/Sałata z różnych jarzyn i piklów"},{"id":"oc-plws-568702","title":"Jabłeczne serki (Apple Cheese, Alternative Method)","cuisine":"European","category":"Preserve","ingredients":["2 kg tart apples (of a choice variety, peeled and cut up)","100 ml water (a splash for moistening the apples during cooking)","500 g sugar (to taste)","30 g candied orange peel (very finely chopped)","0.5 tsp cinnamon (finely crushed and sifted)","0.25 tsp cloves (finely crushed and sifted)","1 pinch mace (finely crushed and sifted)"],"steps":["Peel the tart apples, remove the cores, cut into pieces, and cook covered in a stoneware pot with a splash of water until soft.","Press the cooked apples through a colander or fine sieve and return the puree to the pan.","Add sugar to taste, the sifted cloves, cinnamon, and mace, and the finely chopped candied orange peel.","Cook the mixture over low heat, stirring constantly, until the thick paste pulls away from the sides of the pan.","Pack the mixture into a dampened, thoroughly wrung-out linen bag, shape, and leave under a press or heavy stone for 2–3 days; remove and finish drying in a low oven or a sunny, well-ventilated place."],"time":180,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82eczne_serki_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłeczne serki innym sposobem"},{"id":"oc-plws-568705","title":"Jabłeczne serki krystalizowane (Crystallized Apple Cheese)","cuisine":"European","category":"Preserve","ingredients":["1.5 kg tart apples (summer or autumn apples of a choice variety, peeled and grated)","600 g fine sugar (approximately 3 glassfuls; 1 glassful of sugar per 1 glassful of drained apple pulp)","150 g granulated sugar (coarsely crushed, for coating the cut-out rounds)","1 tsp olive oil (fresh, for greasing the platter)"],"steps":["Peel the tart apples, grate them on a grater, and drain off the excess juice (which can be used for jelly).","Measure the drained apple pulp and add a glassful (approximately 200 g) of fine sugar for each glassful (250 ml) of pulp.","Transfer the combined mixture to a wide pan and cook over low heat, stirring constantly, until it becomes uniform and translucent.","Pour onto a platter lightly greased with fresh olive oil and place in a low oven for several hours to dry slightly.","Cut out small rounds with a small cutter or liqueur glass, coat with coarsely crushed granulated sugar, and finish drying on boards or sieves in a very low oven."],"time":280,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82eczne_serki_krystalizowane","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłeczne serki krystalizowane"},{"id":"oc-plws-568704","title":"Jabłeczne serki suszone z miodem (Apple Cheese Dried with Honey)","cuisine":"European","category":"Preserve","ingredients":["5 kg tart apples (peeled and cut up, for 4 kg of baked and sieved puree)","1 kg honey (good quality, per 4 kg of apple puree)","30 g candied orange peel (finely chopped)","1 tsp lemon zest (freshly grated)","1 tsp cinnamon (finely crushed and sifted)","0.5 tsp cloves (finely crushed and sifted)","1 pinch black pepper (finely crushed and sifted)","1 tsp almond oil (optional for greasing the linen bags instead of wetting them in cold water)"],"steps":["Peel the tart apples, remove the cores, cut into pieces, place in earthenware pots, and bake in a warm oven for approx. 8 hours until completely soft, then press through a colander.","Weigh out 1 kg of honey per 4 kg of sieved apple puree, bring the honey to a boil in a saucepan, and mix with the sifted spices (cinnamon, cloves, a pinch of black pepper), grated lemon zest, and chopped candied orange peel.","Combine the spiced honey with the apple puree and cook together for 10–15 minutes, stirring constantly.","Pack the hot mixture into linen bags (dipped in cold water and wrung out, or greased with almond oil), shape into round loaves, and place under a press for 6–7 days.","Remove the shaped apple cheeses from the bags and dry on wooden boards in a very low oven or a sunny, well-ventilated place."],"time":510,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82eczne_serki_suszone_z_miodem","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłeczne serki suszone z miodem"},{"id":"oc-plws-580441","title":"Jaja faszerowane (stuffed eggs in shells)","cuisine":"European","category":"Snack","ingredients":["6 eggs (4 large hard-boiled and 2 raw to bind the mixture)","1 bunch chives (finely chopped)","to taste butter (for frying the chives and pan-frying the stuffed eggs)","to taste fresh dill (chopped)","to taste parsley leaves (chopped)","3 tbsp breadcrumbs (a handful, for thickening and sprinkling)","to taste sour cream (just enough to keep the mixture moist)"],"steps":["Hard-boil four eggs for 10 minutes, cool them, and cut them lengthwise in half right through the shells using a very sharp knife.","Carefully scoop out the whites and yolks, keeping the half-shells intact, and finely chop the cooked eggs.","Sauté the chopped chives in butter for 2 minutes and mix them with the chopped eggs, two raw eggs, dill, parsley leaves, breadcrumbs, and a little sour cream.","Fill the reserved half-shells with the prepared stuffing.","Place the stuffed eggs cut-side down in a skillet with hot butter and fry for about 3–4 minutes until golden."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Jaja_faszerowane","page":"100 postnych i jarskich dań/Jaja faszerowane"},{"id":"oc-plws-501835","title":"Jaja na grzankach z cynaderkami (poached eggs on toast with veal kidneys)","cuisine":"European","category":"Breakfast","ingredients":["2 veal kidneys (with their surrounding suet)","to taste butter (for braising the kidneys and browning the toast)","to taste salt (for the kidneys and the poaching water)","10 slice wheat roll (oval slices for toast)","10 eggs (for poaching)","to taste water (for soaking the kidneys and poaching the eggs)","2 tbsp vinegar (for the egg poaching water)","to taste Parmesan cheese (grated)"],"steps":["Soak the veal kidneys thoroughly in cold water for 20 minutes, pat dry, and braise whole in butter along with their surrounding fat for about 15 minutes until tender.","Salt the braised kidneys and cut each one into ten very thin slices.","Brown the oval slices of wheat roll on both sides in butter for about 3 minutes, taking care not to dry them out.","Bring salted water with vinegar to a boil in a wide saucepan, carefully crack in the eggs, and poach them for 2–3 minutes until the whites are set and the yolks remain runny.","Place two slices of kidney on each warm slice of toast, top each with a poached egg, sprinkle generously with grated Parmesan, drizzle with the hot fat from cooking the kidneys, and serve immediately."],"time":55,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_na_grzankach_z_cynaderkami","page":"100 potraw z jaj/Jaja na grzankach z cynaderkami"},{"id":"oc-plws-499844","title":"Jaja na occie (eggs poached in tarragon vinegar butter)","cuisine":"European","category":"Breakfast","ingredients":["50 g butter","125 ml tarragon vinegar","190 ml water","10 eggs (8–10 eggs)","to taste salt (fine)","to taste white pepper (or ground paprika)"],"steps":["Melt the butter in a large metal platter or deep skillet, pour in the tarragon vinegar and water, bring to a boil together, and remove the pan from the heat.","Carefully crack the eggs into the hot liquid so that the yolks remain intact.","Return the pan to low heat and cook slowly for about 4–5 minutes, lightly scoring the whites with a spoon so they set evenly.","Sprinkle the set eggs with fine salt, place a tiny pinch of white pepper on each yolk, and serve immediately in the same dish."],"time":13,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_na_occie","page":"100 potraw z jaj/Jaja na occie"},{"id":"oc-plws-501604","title":"Jaja na pomidorach (eggs baked in tomato halves)","cuisine":"European","category":"Breakfast","ingredients":["10 eggs","5 tomatoes (very large, flat)","to taste butter (for searing and baking the tomatoes)","to taste salt","to taste black pepper"],"steps":["Halve the large tomatoes horizontally and scoop out the seeds and juice with a teaspoon.","Heat an ovenproof skillet with a little butter and sear the tomato halves cut-side down for about 3 minutes.","Turn the tomatoes cut-side up, add a piece of butter to the skillet, crack one egg into each tomato half, and season with salt and pepper.","Place the skillet in an oven preheated to 200 °C and bake for 10 minutes until the whites are set.","Serve directly in the skillet, or transfer to a platter and spoon the butter and tomato pan juices over the top."],"time":30,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_na_pomidorach","page":"100 potraw z jaj/Jaja na pomidorach"},{"id":"oc-plws-501603","title":"Jaja na szynce lub słoninie (eggs fried on ham or fatback)","cuisine":"European","category":"Breakfast","ingredients":["150 g ham (marbled with fat, cut into 6 equal slices (or pork belly or smoked fatback))","6 eggs (one per slice of cured meat)","to taste salt (for the yolks only)","to taste black pepper"],"steps":["Cut the marbled ham into six thin, large, even slices.","Arrange the ham slices evenly in a cold skillet, set over the heat, and fry for about 3 minutes until the fat turns translucent, then remove the skillet from the heat.","Crack one egg onto each slice of meat, return the skillet to very low heat, and cook slowly for about 4 minutes, gently parting the whites so they set evenly.","Sprinkle only the yolks with salt and pepper and serve immediately in the same skillet."],"time":13,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_na_szynce_lub_s%C5%82oninie","page":"100 potraw z jaj/Jaja na szynce lub słoninie"},{"id":"oc-plws-502301","title":"Jaja na twardo z sosem pomidorowym (hard-boiled eggs baked in tomato sauce)","cuisine":"European","category":"Main","ingredients":["10 eggs (8–10 eggs)","1 tbsp butter (for the roux, plus extra for the tomatoes and greasing the platter)","1 tsp butter (sweet cream butter, for finishing the sauce)","1 tbsp plain wheat flour","375 ml broth (or water)","3 tomatoes (fresh, pressed through a sieve)","to taste salt","to taste black pepper","2 tbsp sour cream (thick)","to taste hard cheese (sharp, grated)"],"steps":["Hard-boil the eggs for 10 minutes, transfer to cold water, peel, and halve lengthwise.","Cook a tablespoon of butter with the wheat flour over low heat without browning, then whisk in the broth until a smooth sauce forms.","Sauté the sieved fresh tomatoes separately in butter for 5 minutes, combine with the sauce, season with salt and pepper, stir in the sour cream, bring once to a boil, and whisk in a teaspoon of fresh butter.","Arrange the egg halves on a buttered ovenproof platter, pour the tomato sauce over them, and sprinkle with grated sharp cheese.","Place the dish in an oven preheated to 190 °C for 5 minutes until the cheese melts, and serve hot."],"time":40,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_na_twardo_z_sosem_pomidorowym","page":"100 potraw z jaj/Jaja na twardo z sosem pomidorowym"},{"id":"oc-plws-499843","title":"Jaja na śmietanie (eggs gently cooked in sour cream)","cuisine":"European","category":"Breakfast","ingredients":["50 g butter","250 ml sour cream","to taste salt (fine)","to taste black pepper","10 eggs"],"steps":["Melt the butter in a metal platter or wide skillet, pour in the sour cream, boil briefly for 1 minute, season lightly with salt and pepper, and remove from the heat.","Carefully crack the ten eggs into the sour cream and return the pan to low heat.","Cook slowly for about 5 minutes until the whites are set, and sprinkle them with fine salt.","Tilt the pan slightly, scoop up the hot sour cream sauce with a spoon, and baste the tops of the eggs, especially the yolks, then serve immediately."],"time":13,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_na_%C5%9Bmietanie","page":"100 potraw z jaj/Jaja na śmietanie"},{"id":"oc-plws-502543","title":"Jaja nadziewane (pan-fried stuffed eggs in shells)","cuisine":"European","category":"Snack","ingredients":["8 eggs (6 hard-boiled and 2 raw to bind the filling)","to taste fresh dill (finely chopped)","to taste parsley leaves (chopped for the filling and sprigs for garnish)","to taste chives (finely chopped)","to taste breadcrumbs (for thickening the filling)","to taste salt","to taste black pepper","1 tbsp butter (creamed or melted for the mixture, plus extra for frying)"],"steps":["Hard-boil six eggs for 10 minutes, let cool, and cut lengthwise in half through the shells with a very sharp knife.","Carefully scoop out the whites and yolks without damaging the shells, and chop them medium-fine.","Mix the chopped eggs with the dill, parsley leaves, chives, breadcrumbs, salt, pepper, a tablespoon of butter, and two raw eggs until uniform.","Pack the prepared filling into the half-shells.","Place the stuffed shells filling-side down in a skillet with browned butter, cover with a lid, and fry for about 4 minutes until the filling sets and browns, then garnish with parsley and serve."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_nadziewane","page":"100 potraw z jaj/Jaja nadziewane"},{"id":"oc-plws-502912","title":"Jaja nadziewane grzybami (eggs stuffed with porcini mushrooms in shells)","cuisine":"European","category":"Snack","ingredients":["250 g porcini mushrooms (fresh (or 5 large dried mushrooms))","7 eggs (5 large hard-boiled and 2 raw (plus 6 empty half-shells))","1 onion (finely chopped)","to taste butter (for the onion, filling, and frying the shells)","to taste fresh dill (chopped)","to taste salt (for boiling the mushrooms and seasoning the filling)","to taste black pepper"],"steps":["Boil five eggs hard for 10 minutes, cut them lengthwise in half with their shells using a sharp knife, scoop out the insides, and chop finely, reserving the shells.","Boil the cleaned porcini mushrooms in salted water for about 15 minutes, drain, and chop finely.","Fry the finely chopped onion in butter for 5 minutes and mix it with the chopped mushrooms, hard-boiled eggs, chopped dill, a little melted butter, salt, pepper, and two raw eggs.","Fill sixteen egg half-shells with the prepared mixture.","Fry the stuffed shells filling-side down in hot butter for about 4 minutes until golden brown, and serve hot."],"time":50,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_nadziewane_grzybami","page":"100 potraw z jaj/Jaja nadziewane grzybami"},{"id":"oc-plws-502546","title":"Jaja nadziewane mięsem (baked meat-stuffed eggs in shells)","cuisine":"European","category":"Snack","ingredients":["8 eggs (6 large hard-boiled and 2 raw, halved lengthwise in their shells)","200 g roast meat (or boiled meat (beef, poultry, or game))","to taste butter (for frying the meat and onion)","1 onion (large, finely chopped)","to taste salt","to taste black pepper","to taste hard cheese (sharp, grated)"],"steps":["Boil six eggs hard for 10 minutes, cut them lengthwise in half right through the shells with a very sharp knife, scoop out the whites and yolks, and chop finely.","Pass the roast meat through a mincer or chop it finely, and fry in butter with the chopped onion for about 5 minutes.","Using a sharp knife, halve the two raw eggs lengthwise as well, reserving their half-shells, and mix their contents with the fried meat, chopped hard-boiled eggs, salt, and pepper.","Fill all sixteen half-shells with the prepared stuffing, shaping a dome on each, and sprinkle generously with grated sharp cheese.","Set the stuffed shells in a roasting pan and bake in an oven preheated to 180 °C for 15 minutes until golden brown."],"time":50,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_nadziewane_mi%C4%99sem","page":"100 potraw z jaj/Jaja nadziewane mięsem"},{"id":"oc-plws-502544","title":"Jaja nadziewane rakami i ryżem (eggs stuffed with crayfish and rice)","cuisine":"European","category":"Snack","ingredients":["5 eggs (3 hard-boiled and 2 raw (plus reserved empty half-shells))","150 ml rice","1 tbsp butter (for cooking the rice, plus extra for frying the stuffed shells)","15 crayfish (whole)","to taste salt","to taste fresh dill (chopped)"],"steps":["Hard-boil three eggs for 10 minutes, halve lengthwise through the shells with a sharp knife, scoop out the contents, and chop finely.","Cook the rice in salted water with a tablespoon of butter for about 18 minutes until fluffy, then let cool.","Cook the crayfish in boiling water for about 10 minutes, remove the meat from the shells, and chop it finely.","Mix the crayfish meat thoroughly with the cooked rice, chopped hard-boiled eggs, salt, chopped dill, and two raw eggs.","Pack the filling into the prepared egg half-shells and fry them filling-side down in hot butter for about 4 minutes until golden."],"time":60,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_nadziewane_rakami_i_ry%C5%BCem","page":"100 potraw z jaj/Jaja nadziewane rakami i ryżem"},{"id":"oc-plws-502914","title":"Jaja poszetowe smażone (deep-fried breaded poached eggs)","cuisine":"European","category":"Main","ingredients":["11 eggs (10 for poaching and 1 beaten for breading)","to taste water (for poaching the eggs)","2 tbsp vinegar (for poaching the eggs)","to taste salt (for the water and seasoning)","to taste plain wheat flour (for dredging the eggs)","to taste breadcrumbs (for breading)","to taste lard (or oil for deep-frying)","to taste parsley leaves (sprigs for garnish)","1 lemon (cut into quarters)","to taste tomato sauce (plain, for serving)"],"steps":["Bring salted water with vinegar to a boil in a wide saucepan, carefully crack in ten eggs, and poach them for 2–3 minutes until the whites are firm and the yolks remain liquid, then remove, trim the edges neatly, and let cool.","Coat each cooled and dried poached egg thoroughly in wheat flour, then in beaten raw egg, and finally in breadcrumbs.","Lower the breaded eggs into a deep layer of very hot lard and fry for about 2 minutes until golden brown.","Drain the fried eggs on paper towels, arrange on a platter, garnish with parsley sprigs and lemon quarters, and serve with plain tomato sauce."],"time":35,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_poszetowe_sma%C5%BCone","page":"100 potraw z jaj/Jaja poszetowe smażone"},{"id":"oc-plws-502913","title":"Jaja poszetowe w sosie szczawiowym (poached eggs in sorrel sauce)","cuisine":"European","category":"Main","ingredients":["8 eggs (for poaching)","to taste water (for poaching the eggs)","2 tbsp vinegar (for the egg poaching water)","250 g sorrel (young leaves)","1 tbsp butter (a generous tablespoon)","1 tbsp plain wheat flour","4 tbsp vegetable broth (or meat broth)","2 tbsp sour cream","to taste salt","1 tsp sugar"],"steps":["Wash the young sorrel leaves, drain in a sieve, dry, pass through a mincer, and cook gently in butter for about 5 minutes.","Sprinkle the cooked sorrel with the wheat flour, pour in the vegetable broth and sour cream, season with salt and sugar, and simmer together for 3 minutes.","Bring salted water with vinegar to a boil in a wide saucepan, carefully crack in the eggs, and poach for 2–3 minutes until the whites are set and the yolks remain runny.","Arrange the poached eggs on an ovenproof platter, pour the hot sorrel sauce over them, heat briefly for 2 minutes, and serve."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_poszetowe_w_sosie_szczawiowym","page":"100 potraw z jaj/Jaja poszetowe w sosie szczawiowym"},{"id":"oc-plws-499842","title":"Jaja sadzone na maśle (sunny-side up eggs fried in butter)","cuisine":"European","category":"Breakfast","ingredients":["10 eggs","90 g butter (80–100 g)","to taste salt (very fine)","to taste white pepper"],"steps":["Melt the butter in a large skillet or metal platter and remove the pan from the heat.","Carefully crack the eggs in side by side so that the yolks remain whole.","Set the skillet over low heat and cook slowly for about 4–5 minutes, lightly scoring the whites with a spoon so the hot butter sets them evenly and basting the yolks with butter.","Sprinkle the setting eggs with fine salt and a pinch of white pepper, and serve immediately once the whites are set."],"time":11,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_sadzone_na_ma%C5%9Ble","page":"100 potraw z jaj/Jaja sadzone na maśle"},{"id":"oc-plws-501606","title":"Jaja w muszelkach (baked eggs in scallop shells)","cuisine":"European","category":"Breakfast","ingredients":["1 egg (one per shell)","10 g butter (a hazelnut-sized piece for the top, plus extra for greasing the shell)","to taste breadcrumbs (for dusting the shell and sprinkling over the egg)","to taste salt","to taste hard cheese (sharp, grated)"],"steps":["Generously butter an ovenproof scallop shell or small ramekin and dust it with breadcrumbs.","Set the shell level on a baking sheet, crack one egg into the centre, and season lightly with salt.","Sprinkle the top of the egg with breadcrumbs and grated sharp cheese, and dot with about 10 g of butter.","Place in an oven preheated to 180 °C and bake for 10–15 minutes until the breadcrumbs are golden brown, then serve immediately."],"time":17,"servings":1,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_w_muszelkach","page":"100 potraw z jaj/Jaja w muszelkach"},{"id":"oc-plws-501831","title":"Jaja w muszelkach z serem (baked eggs in gougère rings)","cuisine":"European","category":"Snack","ingredients":["250 ml water","125 ml butter (for the choux pastry, plus extra for greasing the shells)","190 ml plain wheat flour","2 eggs (whole, for the choux pastry)","30 g Parmesan cheese (grated, for the choux pastry)","10 eggs (one for the centre of each shell)","30 g Parmesan cheese (grated, for sprinkling on top)"],"steps":["Bring the water and butter to a boil in a small saucepan, dump the wheat flour into the boiling liquid, and beat vigorously with a spoon for about 3 minutes until the dough pulls away from the sides of the pan.","Remove the pan from the heat, continue beating until slightly cooled, then beat in the two eggs and 30 g of grated Parmesan cheese and work into a smooth dough.","Generously butter ten scallop shells or ramekins and pipe or shape a thin ring of choux pastry around the rim of each like a bagel.","Set the shells on a baking sheet, crack one egg into the centre of each pastry ring, and sprinkle the tops with the remaining 30 g of grated Parmesan cheese.","Place in an oven preheated to 220 °C and bake for about 15 minutes until the pastry puffs high and browns lightly and the cheese forms a glossy glaze."],"time":40,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_w_muszelkach_z_serem","page":"100 potraw z jaj/Jaja w muszelkach z serem"},{"id":"oc-plws-501650","title":"Jaja w muszelkach z szynką (baked eggs with ham in ramekins)","cuisine":"European","category":"Breakfast","ingredients":["200 g ham (raw or cooked, cut into thin strips)","to taste butter (for greasing the shells and drizzling on top)","to taste breadcrumbs (for dusting the shells and sprinkling over the eggs)","10 eggs (small, 1 for each of the 10 shells)","to taste hard cheese (sharp, grated)"],"steps":["Cut the ham into very thin strips.","Generously butter ten scallop shells or ramekins, dust them with breadcrumbs, and line them with a layer of ham, making a slight hollow in the centre of each.","Set the shells level on a baking sheet, crack one egg into each, sprinkle with breadcrumbs and grated sharp cheese, and drizzle with melted butter.","Place in an oven preheated to 170 °C and bake for 15–20 minutes until the cheese melts and forms a thin crust."],"time":35,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_w_muszelkach_z_szynk%C4%85","page":"100 potraw z jaj/Jaja w muszelkach z szynką"},{"id":"oc-plws-501649","title":"Jaja w muszelkach z wermiszelem (baked eggs in vermicelli nests)","cuisine":"European","category":"Main","ingredients":["200 g vermicelli pasta (fine)","1 tbsp butter (for the pasta, plus extra for greasing the shells)","50 g hard cheese (sharp, grated, for the pasta plus extra for sprinkling on top)","10 eggs (small, 1 for each of the 10 shells)","to taste salt"],"steps":["Boil the vermicelli pasta in boiling water for about 4 minutes, drain, rinse with cold water, and toss with a tablespoon of butter and 50 g of grated sharp cheese.","Generously butter ten scallop shells or ramekins and arrange the pasta inside them in the shape of nests with a hollow centre.","Set the shells level on a baking sheet, crack one egg into the centre of each nest, season lightly with salt, and sprinkle generously with grated cheese.","Place in an oven preheated to 180 °C and bake for 15 minutes until the whites are set and the cheese is golden."],"time":35,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_w_muszelkach_z_wermiszelem","page":"100 potraw z jaj/Jaja w muszelkach z wermiszelem"},{"id":"oc-plws-508391","title":"Jaja w sosie chrzanowym (hard-boiled eggs in horseradish sauce)","cuisine":"European","category":"Snack","ingredients":["1 tbsp butter","1 tbsp plain wheat flour","150 ml broth (or water)","1 horseradish (large root, grated)","to taste salt","to taste sugar","to taste vinegar","250 ml sour cream","10 eggs (10–12 eggs)"],"steps":["Grate the horseradish root on a fine grater, season with salt and sugar, sprinkle with vinegar, and let stand for about 120 minutes to lose its harsh pungency.","Cook the butter and wheat flour over low heat without browning, whisk in the broth, simmer for 3 minutes until thickened, and let cool.","Mix the cooled white sauce with the marinated horseradish and sour cream.","Hard-boil the eggs for 10 minutes, let cool, peel, halve, and arrange on a platter.","Spoon the thick horseradish sauce over the egg halves and chill for about 20 minutes before serving so the flavours meld."],"time":165,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_w_sosie_chrzanowym","page":"100 potraw z jaj/Jaja w sosie chrzanowym"},{"id":"oc-plws-508390","title":"Jaja w sosie majonezowym (eggs mayonnaise)","cuisine":"European","category":"Snack","ingredients":["1 tsp plain wheat flour","1 tsp butter","2 tbsp broth (or boiled water (plus a splash of cold liquid to thin the sauce))","2 egg yolks (raw)","to taste salt","1 tsp sugar","1 pinch mustard (a knife-tip's worth)","1 tbsp vinegar","6 tbsp olive oil","1 lemon (squeezed juice)","10 eggs (10–12 eggs, hard-boiled)"],"steps":["Hard-boil the eggs for 10 minutes, cool in cold water, peel, and halve lengthwise.","Simmer a teaspoon of wheat flour with a teaspoon of butter and two tablespoons of broth in a small saucepan for 2 minutes, then cool completely.","Add the raw egg yolks, salt, sugar, a dab of mustard, and vinegar to the cooled base, and whisk vigorously while trickling in the olive oil a few drops at a time until a thick, smooth mayonnaise forms.","Squeeze the lemon juice into the mayonnaise and thin it with a splash of cold broth to the consistency of a coating sauce.","Arrange the egg halves on a platter, pour the mayonnaise sauce over them, and chill for about 120 minutes before serving."],"time":152,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_w_sosie_majonezowym","page":"100 potraw z jaj/Jaja w sosie majonezowym"},{"id":"oc-plws-499845","title":"Jaja w sosie pomidorowym (eggs poached in tomato sauce)","cuisine":"European","category":"Breakfast","ingredients":["500 ml tomato sauce (fairly thin)","10 eggs (8–10 eggs)","to taste salt (fine)"],"steps":["Warm the tomato sauce, set aside a few spoonfuls in a warm place, and pour the rest into a deep metal platter or wide skillet.","Carefully crack the eggs into the warm sauce, taking care not to break the yolks.","Cook the eggs in the sauce over very low heat for about 5–6 minutes, gently scoring the whites with a knife so they set faster and more evenly.","Sprinkle the set eggs with fine salt, spoon a teaspoon of the reserved warm tomato sauce over each yolk, and serve immediately."],"time":13,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_w_sosie_pomidorowym","page":"100 potraw z jaj/Jaja w sosie pomidorowym"},{"id":"oc-plws-508379","title":"Jaja z beszamelem (soft-boiled eggs gratinated with béchamel)","cuisine":"European","category":"Main","ingredients":["1 tbsp butter (a generous tablespoon for the béchamel, plus extra for greasing the platter)","1 tbsp plain wheat flour (a generous tablespoon)","1 l milk (or sweet cream)","to taste salt","12 eggs (2 raw for the béchamel and 10 soft-boiled peeled eggs)","4 tbsp Parmesan cheese (grated, sharp (a handful for the sauce and extra for sprinkling on top))"],"steps":["Cook a tablespoon of butter with the wheat flour over low heat without browning, whisk in the milk, season lightly with salt, simmer for about 5 minutes, and set aside to cool slightly.","Meanwhile, boil ten eggs in their shells in boiling water for 3 minutes, plunge into cold water, and peel carefully.","Beat two raw eggs into the cooled béchamel, add half of the grated Parmesan cheese, and mix thoroughly.","Butter an ovenproof platter, spread one-third of the béchamel on the bottom, arrange the peeled soft-boiled eggs on top, and cover with the remaining sauce in a dome.","Sprinkle the top generously with the remaining grated Parmesan cheese and bake in an oven preheated to 200 °C for 15 minutes until golden brown, then serve immediately."],"time":45,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_z_beszamelem","page":"100 potraw z jaj/Jaja z beszamelem"},{"id":"oc-plws-501651","title":"Jaja z cebulą w muszelkach (baked eggs with onion and smoked fatback in ramekins)","cuisine":"European","category":"Breakfast","ingredients":["150 g smoked fatback (finely diced)","2 onion (large sweet onions, finely chopped)","1 tsp butter (a small teaspoon)","to taste black pepper","10 eggs (small, 1 for each of the 10 shells)"],"steps":["Cut the smoked fatback into very fine dice, and finely chop the large onions.","Cook the chopped onions gently with a teaspoon of butter over low heat for about 10 minutes until soft, then mix with the diced fatback, season lightly with pepper, and let cool.","Divide the cooled onion and fatback mixture among ten scallop shells or ramekins, making a hollow in the centre of each.","Set the shells level on a baking sheet and crack one egg into the centre of each without salting them.","Place in an oven preheated to 180 °C and bake for 15 minutes until the whites are set."],"time":45,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_z_cebul%C4%85_w_muszelkach","page":"100 potraw z jaj/Jaja z cebulą w muszelkach"},{"id":"oc-plws-45021","title":"Jajecznica (classic Polish scrambled eggs)","cuisine":"European","category":"Breakfast","ingredients":["1 tbsp butter (fresh)","6 eggs (whole)","to taste salt","to taste black pepper (optional)","to taste chives (chopped, optional)"],"steps":["Heat a tablespoon of fresh butter in a small saucepan or skillet until hot.","Beat the whole eggs in a bowl for exactly 1 minute, no longer.","Pour the beaten eggs into the hot butter and cook for 5 minutes, stirring constantly with a spoon.","Season the finished scrambled eggs with salt and, if desired, black pepper and chopped chives."],"time":7,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Jajecznica","page":"365 obiadów za 5 złotych/Jajecznica"},{"id":"oc-plws-499647","title":"Jajecznica na maśle (Polish scrambled eggs in butter)","cuisine":"European","category":"Breakfast","ingredients":["4 eggs (large (2–3 pieces per person))","50 g butter","to taste salt"],"steps":["Crack the eggs into a bowl, season lightly with salt, and beat thoroughly with a spoon or whisk.","Melt the butter in a skillet until hot and foaming, without letting it brown.","Pour the beaten eggs into the hot butter and cook over low heat for about 3–4 minutes.","As the eggs begin to set on the bottom, gently lift them with a spoon in large curds and serve hot as soon as they are set."],"time":7,"servings":2,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_na_ma%C5%9Ble","page":"100 potraw z jaj/Jajecznica na maśle"},{"id":"oc-plwb-23402","title":"Jajecznica po bacowsku (Highlander scrambled eggs with oscypek and wholemeal croutons)","cuisine":"European","category":"Breakfast","ingredients":["6 eggs","3 slice wholemeal bread","3 tbsp grated oscypek cheese","2.5 tbsp milk (2–3 tablespoons)","50 g fatback","0.25 tsp ground lovage","1 tsp fresh lovage or parsley leaves (finely chopped)","to taste salt"],"steps":["Cut the slices of wholemeal bread into small cubes.","Whisk the eggs thoroughly with the milk, ground lovage, and grated oscypek cheese.","Finely dice the fatback, render in a skillet, and lightly brown the bread cubes in the rendered fat.","Pour in the egg mixture, add salt, cook over low heat while stirring until softly set, and sprinkle with chopped lovage or parsley leaves."],"time":15,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajecznica_po_bacowsku","page":"Książka kucharska/Jajecznica po bacowsku"},{"id":"oc-plws-580475","title":"Jajecznica z grzybami (baked eggs with porcini mushrooms)","cuisine":"European","category":"Breakfast","ingredients":["500 g porcini mushrooms (fresh (or slippery jack mushrooms))","to taste butter (for cooking the mushrooms)","1 onion (chopped)","1 tbsp plain wheat flour","250 ml sour cream","to taste salt","to taste black pepper","5 eggs","250 ml milk"],"steps":["Clean the porcini mushrooms, slice them into strips, and cook gently in butter with the chopped onion for about 12 minutes.","Sprinkle the mushrooms with the wheat flour, pour in the sour cream, season with salt and pepper, simmer for 3 minutes, and transfer to a shallow ovenproof dish.","Beat the eggs with the milk and a pinch of salt, then pour the egg mixture over the mushrooms without stirring.","Place the dish in an oven preheated to 200 °C for about 10 minutes until the eggs are set, and serve immediately."],"time":40,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Jajecznica_z_grzybami","page":"100 postnych i jarskich dań/Jajecznica z grzybami"},{"id":"oc-plws-1080966","title":"Jajeczniki (Polish Egg-Enriched Bread Rolls)","cuisine":"European","category":"Bread","ingredients":["2.4 kg wheat flour (orig. 1 garniec (4 l): half a garniec for the sponge and half a garniec for kneading, plus a little for dusting)","1 l milk (lukewarm, originally 3 kwaterki (750 ml) for the sponge and 1 kwaterka (250 ml) for dissolving the yeast)","100 g fresh yeast (orig. 8 łut)","30 egg yolks (originally half a kopa of egg yolks (a historical Polish counting measure), or 10 whole eggs and 10 yolks)","500 ml clarified butter (originally half a kwarta (historical Polish measure), plus butter for greasing the baking sheets)","400 g sugar (originally 1 funt)","1 tsp salt","to taste grated lemon zest","1 egg (beaten with water for brushing the rolls)","2 tbsp water (for beating the egg and brushing after baking)"],"steps":["Mix half of the flour (approx. 1.2 kg) with 750 ml of lukewarm milk, pour in the yeast dissolved in the remaining 250 ml of milk, dust the top with flour, cover, and set aside in a warm place to rise.","When the sponge rises and cracks on the surface, pour in the beaten egg yolks, melted clarified butter, sugar, salt, and grated lemon zest, and mix thoroughly.","Gradually add the remaining flour (approx. 1.2 kg) and knead the dough by hand for about 30 minutes until it pulls away from your hands, then cover and set aside to rise.","Shape rolls from the risen dough on a floured board, arrange on greased baking sheets, and leave to rise again.","Brush the risen rolls several times with an egg beaten with water and bake in a hot oven (200 °C) for about 20–25 minutes, then brush immediately after baking with cold water or translucent glaze."],"time":205,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Jajeczniki%2C_czyli_bu%C5%82ki_jajeczne","page":"Baby, placki i mazurki/Jajeczniki, czyli bułki jajeczne"},{"id":"oc-plwb-18807","title":"Jajka faszerowane (Polish deviled eggs with cheese and sweetcorn)","cuisine":"European","category":"Snack","ingredients":["6 eggs","50 g grated semi-hard cheese","4 tbsp canned sweetcorn (canned)","6 tbsp thick sour cream","2 radishes","1 tbsp radish sprouts","1 tbsp chives (chopped)","2 tbsp mayonnaise","1 tsp mustard","to taste salt","to taste black pepper"],"steps":["Hard-boil the eggs, let them cool, peel, and cut in half lengthwise.","Remove the egg yolks and mash until smooth with the grated cheese, thick sour cream, mayonnaise, and mustard.","Stir the drained sweetcorn and chopped chives into the yolk mixture, and season to taste with salt and black pepper.","Fill the hollowed egg whites with the prepared mixture, arrange on a platter, and garnish with radish slices and radish sprouts."],"time":25,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_faszerowane","page":"Książka kucharska/Jajka faszerowane"},{"id":"oc-plwb-18704","title":"Jajka nadziewane wiosennym farszem (Spring-herb stuffed eggs in shells)","cuisine":"European","category":"Snack","ingredients":["8 eggs","10 ml sour cream","3 tbsp breadcrumbs","70 g butter","to taste parsley leaves (sprigs)","to taste chives","to taste dill","to taste salt","to taste black pepper"],"steps":["Hard-boil the eggs, let cool, and slice each in half lengthwise through the shell.","Scoop out the yolks and part of the whites, creating hollows in the shell halves for the filling.","Chop the scooped yolks and whites, combine with washed and chopped parsley leaves, chives, and dill, add the softened butter, sour cream, salt, and black pepper, mix, and chill in the refrigerator for 30 minutes.","Spoon the chilled filling into the eggshell halves, dust with breadcrumbs, and garnish with fresh herb leaves."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_nadziewane_wiosennym_farszem","page":"Książka kucharska/Jajka nadziewane wiosennym farszem"},{"id":"oc-plwb-16861","title":"Jajka panierowane (Polish breaded fried eggs)","cuisine":"European","category":"Snack","ingredients":["5 hard-boiled eggs","1 raw egg","3 tbsp milk (a few tablespoons)","110 g breadcrumbs","4 tbsp chives (chopped)","to taste mayonnaise","to taste salt","to taste black pepper","3 tbsp vegetable oil (for frying)","to taste lettuce (leaves)","to taste bell pepper (sliced)","to taste parsley leaves"],"steps":["Peel the hard-boiled eggs and slice them in half lengthwise.","Whisk the raw egg with the milk and season with salt and black pepper.","Coat the egg halves in the egg mixture and breadcrumbs, fry in hot oil until golden, and transfer to a serving platter.","Once the eggs have cooled, drizzle with mayonnaise, garnish with lettuce leaves and sliced bell pepper, and sprinkle chopped chives and parsley leaves on top."],"time":30,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_panierowane","page":"Książka kucharska/Jajka panierowane"},{"id":"oc-plwb-18886","title":"Jajka w sosie szczypiorkowym (hard-boiled eggs in chive cream sauce)","cuisine":"European","category":"Breakfast","ingredients":["4 eggs","1.5 tbsp chives (1–2 tbsp chopped)","125 ml sour cream (half a glass)","1 egg yolk (raw)","to taste salt","to taste sugar","to taste lemon juice","1 tsp mustard"],"steps":["Hard-boil the eggs, let them cool, peel, slice lengthwise in half, and arrange on a platter.","Whisk the egg yolk with mustard and a pinch of sugar until smooth, gradually beating in the sour cream in small portions.","Fold in the chopped chives, season to taste with salt, sugar, and lemon juice, and pour over the eggs."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_w_sosie_szczypiorkowym","page":"Książka kucharska/Jajka w sosie szczypiorkowym"},{"id":"oc-plwb-18773","title":"Jajka w sosie wielkanocnym (Polish Easter eggs in horseradish cream sauce)","cuisine":"European","category":"Breakfast","ingredients":["11 eggs (10 hard-boiled, 1 raw)","80 ml sour cream 22%","1 tbsp horseradish (grated)","1 tbsp fresh dill (chopped)","3 tbsp chives (chopped)","to taste sugar","to taste salt"],"steps":["Hard-boil 10 eggs, let them cool, and peel them.","Press one hard-boiled egg through a sieve and mix with sour cream 22%, horseradish, the remaining raw egg, dill, and chives.","Season the sauce to taste with salt and sugar.","Cut the remaining hard-boiled eggs in half lengthwise, arrange on a platter, and pour over the prepared sauce."],"time":25,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_w_sosie_wielkanocnym","page":"Książka kucharska/Jajka w sosie wielkanocnym"},{"id":"oc-plws-544486","title":"Jam of whole apricots","cuisine":"European","category":"Preserve","ingredients":["500 g apricots (almost ripe, firm, whole with the stone, orig. half a kilogram)","1000 g sugar (orig. 1 kilogram (500 g on the first day, plus 500 g added gradually over the next 3 days))","500 ml water (hot, for blanching the apricots and for the syrup)"],"steps":["Prick almost-ripe firm apricots densely with a wooden toothpick right to the stone, cover them with hot (not boiling) water so it covers them, and leave them for 60 minutes.","Lift out the apricots. Cook a syrup from the blanching water and 500 g of sugar, put the slightly cooled apricots into it, bring it to the boil a few times over low heat, and leave it until the next day.","For the next 3 days, take the apricots out each day, strain the syrup, add a portion of the remaining sugar (500 g in all), bring the syrup to the boil, skim it, and put the apricots back so they boil once in the syrup, shaking the pan often.","Once fully cooked and cool, pack the apricots and syrup into scalded jars and seal them."],"time":45,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Morele","page":"Doświadczone sekreta smażenia konfitur i soków/Morele"},{"id":"oc-plwb-15335","title":"Jarzynowa zupa krem (creamy Polish vegetable soup with dill)","cuisine":"European","category":"Soup","ingredients":["2 carrots (small)","1 parsley root (small)","50 g celeriac (a piece)","1 leek (small)","1 onion (small)","1 tomato (ripe)","100 g broccoli (a few florets)","2 potatoes","2 tbsp 22% sour cream","2 tbsp soup seasoning or a bouillon cube (or 1 cube)","2 tbsp fresh dill (chopped)","to taste black pepper","to taste salt","750 ml water (3 szklanki of boiling water)"],"steps":["Wash, peel, and roughly chop the carrots, parsley root, celeriac, leek, onion, tomato, broccoli, and potatoes.","Place the vegetables in a pot, pour over boiling water, add the soup seasoning, and cook covered until tender.","Allow the soup to cool slightly, blend until smooth, and stir in sour cream (22% fat) tempered with a few spoonfuls of hot broth.","Season to taste with salt and pepper, and serve sprinkled with chopped dill."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jarzynowa_zupa_krem","page":"Książka kucharska/Jarzynowa zupa krem"},{"id":"oc-plwb-21732","title":"Kaczka z jabłkami (Polish roast duck with apples and marjoram)","cuisine":"European","category":"Main","ingredients":["1 whole duck","to taste salt","0.5 tsp caraway seeds (optional)","1 tsp marjoram","12 tart apples (about a dozen)","1 onion (optional)","1 tbsp butter","2.5 tbsp broth (2–3 tablespoons)","0.5 tbsp wheat flour"],"steps":["Rinse and pat dry the duck, then rub inside and out with salt, caraway seeds, and marjoram.","Quarter the tart apples, stuff the duck cavity with them, and top with sliced onion.","Place the duck in a roasting pan and roast in the oven, basting initially with broth and later brushing with butter, turning frequently.","Mix the pan juices with the wheat flour and bring briefly to a boil.","Place the roasted duck on a platter, surround with apples, and drizzle with the thickened gravy."],"time":145,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kaczka_z_jab%C5%82kami","page":"Książka kucharska/Kaczka z jabłkami"},{"id":"oc-plwb-14693","title":"Kalafior w sosie serowym (baked cauliflower in cheese and ham sauce)","cuisine":"European","category":"Main","ingredients":["1 cauliflower","to taste lemon juice","to taste salt","50 g wheat flour","100 g grated hard or semi-hard cheese","4 tbsp sour cream","50 g ham","1 bouillon cube","1 bunch chives (a few sprigs)","500 ml water (2 szklanki for the sauce)"],"steps":["Wash the cauliflower and cook in water with salt and lemon juice, then drain.","Bring 500 ml of water with the bouillon cube to a boil in a saucepan, pour in the wheat flour mixed with a little cold water, and bring back to a boil.","Add the grated hard or semi-hard cheese, ham cut into strips, and sour cream to the sauce, stir, and add finely chopped chives.","Arrange the cauliflower in a baking dish, pour over the cheese sauce, and bake in a preheated oven for about 10 minutes."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kalafior_w_sosie_serowym","page":"Książka kucharska/Kalafior w sosie serowym"},{"id":"oc-plwb-18655","title":"Kalafior zapiekany z serem (baked cauliflower with cheese and breadcrumbs)","cuisine":"European","category":"Side","ingredients":["1 cauliflower (large)","150 g grated hard or semi-hard cheese","2 tbsp butter","2 tbsp breadcrumbs","1 pinch nutmeg","1 tsp lemon juice","1 bunch fresh dill","to taste sugar","to taste salt"],"steps":["Cook the cauliflower until tender-crisp in water with salt, sugar, and lemon juice, then drain and separate into florets.","Arrange the cauliflower florets in a baking dish and drizzle with melted butter.","Sprinkle the cauliflower with grated hard or semi-hard cheese and breadcrumbs mixed with nutmeg.","Place the dish in a preheated oven and bake until the cheese melts and the breadcrumbs turn golden.","Before serving, sprinkle the dish with chopped dill."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kalafior_zapiekany_z_serem","page":"Książka kucharska/Kalafior zapiekany z serem"},{"id":"oc-plwb-16859","title":"Kalarepa faszerowana (stuffed kohlrabi with veal and cream sauce)","cuisine":"European","category":"Main","ingredients":["4 kohlrabi (small)","200 g minced veal","500 ml broth (from a bouillon cube)","1 onion","2 tbsp butter (for frying and baking)","100 ml sour cream","to taste parsley leaves","to taste salt","to taste black pepper","to taste nutmeg"],"steps":["Trim the kohlrabi, cut off tops, hollow out the flesh, and parboil the hollowed bulbs in broth, then drain.","Peel and chop the onion, cook until translucent in part of the butter, add the minced veal, fry lightly, and season with salt, pepper, and nutmeg.","Gently stew the scooped-out kohlrabi flesh in the fat left from frying the meat, add 125 ml of broth, and stew until tender.","Add chopped parsley leaves and sour cream to the cooked flesh, blend until smooth, and stir part of the sauce into the meat.","Fill the kohlrabi with the meat stuffing, arrange in a greased baking dish, dot with the remaining butter, and bake for about 20 minutes."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kalarepa_faszerowana","page":"Książka kucharska/Kalarepa faszerowana"},{"id":"oc-plws-580431","title":"Kapusta faszerowana (stuffed whole savoy cabbage)","cuisine":"European","category":"Main","ingredients":["2 savoy cabbage (heads: one whole for stuffing, the other for the filling)","2 onion (finely chopped)","to taste butter (for the onions and browning the cabbage)","to taste salt (for blanching the cabbage and seasoning the filling)","to taste black pepper","3 tbsp tomato paste (2 tbsp for the filling and 1 tbsp for the sauce)","to taste sour cream (for basting during braising)"],"steps":["Blanch one head of savoy cabbage in boiling salted water for about 8 minutes, drain on a cloth, and carefully fold back the leaves without detaching them from the core.","Boil the second head of cabbage until tender, about 20 minutes, drain, and chop finely.","Fry the chopped onions in butter for 5 minutes, mix with the chopped cabbage and two tablespoons of tomato paste, and season with salt and pepper.","Pack the filling between the folded-back leaves of the first cabbage head, reshape it into a whole head, and tie with cotton twine so it holds its shape.","Brown the stuffed cabbage head in butter in a casserole on all sides for about 10 minutes until golden.","Baste the cabbage with sour cream mixed with the remaining tomato paste and braise covered over low heat for about 30 minutes until tender.","Transfer the cabbage to a platter, remove the twine, cut into wedges, and serve with the strained braising sauce."],"time":90,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Kapusta_faszerowana","page":"100 postnych i jarskich dań/Kapusta faszerowana"},{"id":"oc-plwb-16934","title":"Kapusta pekińska z pieczarkami (napa cabbage salad with mushrooms)","cuisine":"European","category":"Salad","ingredients":["1 napa cabbage","200 g button mushrooms","to taste lemon juice","1 onion (large)","2 clove garlic","4 tbsp vinegar","4 tbsp vegetable oil","to taste sugar","to taste salt","to taste parsley leaves","2 tbsp water (for braising mushrooms)"],"steps":["Finely shred the napa cabbage and transfer it to a bowl.","Clean the mushrooms, quarter them, drizzle with lemon juice, season with salt, and cook gently, covered, with water over low heat for a few minutes.","Add chopped parsley leaves to the mushrooms, mix, and combine with the shredded cabbage.","Finely chop the onion, whisk with crushed garlic, oil, vinegar, and sugar, and pour the prepared dressing over the salad."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kapusta_peki%C5%84ska_z_pieczarkami","page":"Książka kucharska/Kapusta pekińska z pieczarkami"},{"id":"oc-plwb-18795","title":"Kapusta w kolorach tęczy (rainbow layered pickled cabbage with wild mushrooms)","cuisine":"European","category":"Preserve","ingredients":["280 g white cabbage (cukrowa variety)","280 g savoy cabbage","280 g red cabbage","280 g carrots","280 g beetroots","280 g yellow knight and green tricholoma mushrooms","55 g salt (50–60 g)","1 tbsp caraway seeds","6 black peppercorns (a few peppercorns)","4 cloves (a few)","to taste sugar"],"steps":["Shred the white cabbage, savoy cabbage, and red cabbage separately.","Peel the carrots and beetroots, then coarsely grate them.","Briefly blanch the caps of the wild tricholoma mushrooms in boiling water, then dry them.","Layer into a two-liter jar sequentially: white cabbage, green tricholomas, beetroots, savoy cabbage, yellow knights, carrots, and red cabbage, sprinkling the layers with salt, sugar, caraway seeds, black peppercorns, and cloves, packing down tightly with a pestle.","Leave the firmly packed ferment in a warm place for 3 days, then move to a cool, dark place for a few days.","Seal the jar with a lid and pasteurize for 15–20 minutes in a water bath at 80 °C."],"time":65,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kapusta_w_kolorach_t%C4%99czy","page":"Książka kucharska/Kapusta w kolorach tęczy"},{"id":"oc-plwb-62724","title":"Kapusta z fasolą i kaszą jaglaną (Subcarpathian Christmas sauerkraut with white beans and millet)","cuisine":"European","category":"Main","ingredients":["1.5 kg sauerkraut","400 g large white runner beans (Jaś) (dry)","300 g millet","1 onion","3 tbsp butter or linseed oil (to taste)","to taste salt (for cooking beans)","2 l water (for soaking and cooking)"],"steps":["Rinse the large white runner beans, cover with cold water, and leave to soak overnight.","Boil the beans until tender in their lightly salted soaking liquid, then drain.","Briefly parboil the sauerkraut, drain, cover with fresh cold water, and simmer gently over low heat until it starts to soften.","Rinse the millet, spread in an even layer on top of the simmering sauerkraut, and cook over very low heat without stirring until the millet absorbs the liquid and softens.","Finely chop the onion and cook until translucent in a skillet with butter or linseed oil.","Add the cooked beans and sautéed onion with fat into the pot with cabbage and millet, mix thoroughly, and chill for at least 12 hours before reheating."],"time":120,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kapusta_z_fasol%C4%85_i_kasz%C4%85_jaglan%C4%85","page":"Książka kucharska/Kapusta z fasolą i kaszą jaglaną"},{"id":"oc-plwb-21741","title":"Kapusta z grzybami (braised fresh cabbage and sauerkraut with forest mushrooms).","cuisine":"European","category":"Side","ingredients":["500 g white cabbage","500 g sauerkraut","30 g dried forest mushrooms","1 tbsp butter","1 tbsp wheat flour","1 tbsp sugar","to taste salt","to taste black pepper","1 l water (for soaking mushrooms and cooking cabbage)"],"steps":["Soak the dried forest mushrooms in water for at least 60 minutes.","Shred the white cabbage, cook in salted water for 30 minutes, and drain.","Add the sauerkraut and soaked mushrooms, cover, and cook gently for another 30 minutes, adding the mushroom soaking liquid as needed.","Cook butter and wheat flour in a skillet to make a roux and caramelize the sugar.","Stir the roux and caramelized sugar into the cabbage and season with salt and pepper."],"time":125,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kapusta_z_grzybami","page":"Książka kucharska/Kapusta z grzybami"},{"id":"oc-plws-546734","title":"Kapusta z grzybami (sauerkraut with mushrooms)","cuisine":"European","category":"Side","ingredients":["1.5 kg sauerkraut (orig. 1 and a half kg)","7 dried wild mushrooms (orig. 6–8 large mushrooms)","300 ml water (for soaking the mushrooms and blending the flour)","4 tbsp vegetable oil","2 tbsp wheat flour","2 onion (whole)","1 tbsp sugar"],"steps":["Soak the dried mushrooms overnight in a small amount of water.","Put the sauerkraut into a pot, add the oil and chopped onions, and braise under a lid.","When the sauerkraut is half tender, add the soaked mushrooms along with their soaking liquid and continue braising until completely tender.","Stir in a tablespoon of sugar, thicken the sauerkraut with the wheat flour blended in a little water, and bring to a boil once more.","Mound the sauerkraut on a platter and arrange the whole mushrooms around it."],"time":585,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kapusta_z_grzybami","page":"109 potraw/Kapusta z grzybami"},{"id":"oc-plwb-14329","title":"Kapusta zapiekana z orzechami (baked young cabbage with walnuts)","cuisine":"European","category":"Side","ingredients":["2 cabbage (small heads)","50 g butter","3 tbsp wheat flour","250 ml milk","3 tbsp breadcrumbs","10 walnuts","to taste salt","to taste black pepper"],"steps":["Remove outer cabbage leaves, wash the heads, cut into quarters, and boil in salted water for 8–10 minutes after boiling, then drain in a colander.","Melt half of the butter in a pan, stir in the wheat flour, and cook over low heat, stirring constantly.","Slowly whisk in the milk, cook until the sauce thickens, and season with salt and pepper.","Grease a baking dish with the remaining butter, arrange the cabbage, pour over the sauce, and sprinkle with breadcrumbs and finely chopped walnuts.","Bake in an oven preheated to 200 °C for about 15 minutes."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kapusta_zapiekana_z_orzechami","page":"Książka kucharska/Kapusta zapiekana z orzechami"},{"id":"oc-plwb-1507","title":"Kapuśniak (Polish sauerkraut soup)","cuisine":"European","category":"Soup","ingredients":["500 g sauerkraut","100 g smoked bacon","300 g potatoes","1 onion","1 clove garlic","2 bay leaves","2 bouillon cubes","to taste salt","to taste black pepper","2 l water"],"steps":["Rinse the sauerkraut in a colander under running water, drain well, and chop finely.","Dice the smoked bacon, peel and finely chop the onion, and peel, rinse, and dice the potatoes.","Fry the bacon in a large skillet, add the onion, and cook until golden brown.","Add the chopped sauerkraut, fry for 3–4 minutes, then pour in a little water, cover, and braise over low heat for 10 minutes.","Bring water to a boil in a pot, add the potatoes, and cook for 10 minutes, then add the braised sauerkraut with bacon and onion.","Dissolve the crumbled bouillon cubes in a small amount of water and pour into the soup.","Add the bay leaves and garlic mashed with salt, season with pepper, cover, and simmer for another 15 minutes."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kapu%C5%9Bniak","page":"Książka kucharska/Kapuśniak"},{"id":"oc-plws-514790","title":"Kapuśniak (Polish sauerkraut soup)","cuisine":"European","category":"Soup","ingredients":["1200 g beef (orig. 3 funty; historical measure, converted approximately)","600 g pork (orig. 1½ funty; historical measure, converted approximately)","to taste salt","4 dried mushrooms (4–5 pieces)","to taste allspice (a few berries)","2 black peppercorns (2–3 peppercorns)","2 bay leaves (2–3 leaves)","1 l sauerkraut juice (orig. 1 kwarta; historical measure, converted approximately; amount from the ingredient list)","1 l sauerkraut (orig. 1 kwarta; volume of sauerkraut; historical measure, converted approximately)","2 egg whites (for clarifying)","2 onion","4 l water (at least 4 l; orig. a garniec or more; historical measure, converted approximately)"],"steps":["Place the beef and pork in a pot.","Add the mushrooms, whole peeled onions, sauerkraut, salt, allspice, peppercorns, and bay leaves.","Cover with the water.","Cook until the meat is tender.","Strain the broth, reserving the pork for serving.","Skim the fat from the surface of the broth.","Add the sauerkraut juice to the broth.","Clarify the hot broth with the egg whites, heating until they set.","Strain the broth again.","Cut the pork into pieces.","Add the pork to the soup before serving."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kapu%C5%9Bniak","page":"Kucharka litewska (1913)/Kapuśniak"},{"id":"oc-plws-546605","title":"Kapuśniak leniwy (lazy fresh cabbage soup)","cuisine":"European","category":"Soup","ingredients":["200 g pork bones (orig. 20 dkg)","800 g white cabbage (1 small head)","400 g potatoes (orig. 40 dkg)","1 carrot (whole)","1 parsley root (whole)","1 onion (whole)","1.5 l water (orig. one and a half liters for the broth)","1 tbsp wheat flour","100 g sour cream or milk (orig. 10 dkg sour cream or 1 szklanka (250 ml) milk)","4 black peppercorns (a few peppercorns)","1 bay leaf (whole leaf)","to taste salt (to taste)","1 tbsp fresh or dried dill (for serving)"],"steps":["Boil 1.5 liters of broth from the pork bones, carrot, parsley root, onion, peppercorns, bay leaf, and salt.","Cut the white cabbage into wedges, scald with boiling water, add to the strained broth, and simmer.","About 20 minutes before serving, add the peeled and diced potatoes.","When the potatoes are tender, thicken the soup with the wheat flour blended in a little cold water and bring to a boil.","Pour the hot cabbage soup into a tureen over the sour cream tempered with a few tablespoons of hot soup, and sprinkle with dill."],"time":80,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kapu%C5%9Bniak_leniwy","page":"109 potraw/Kapuśniak leniwy"},{"id":"oc-plwb-22068","title":"Karkówka pieczona (Polish roast pork neck with caraway and marjoram)","cuisine":"European","category":"Main","ingredients":["10 pork neck steaks","1.5 tsp ground caraway","2 onions (large)","2 tsp marjoram","250 ml broth","to taste salt","to taste vegetable oil (for frying)"],"steps":["Rinse and pat dry the pork neck steaks, then rub with salt, ground caraway, and marjoram.","Sear the meat in hot oil on both sides until golden brown.","Arrange the pork steaks in a roasting pan and scatter finely chopped onions over them.","Bake in an oven preheated to 150 °C for about 90 minutes, basting occasionally with broth."],"time":120,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kark%C3%B3wka_pieczona","page":"Książka kucharska/Karkówka pieczona"},{"id":"oc-plwb-12757","title":"Karminadle (Silesian broth meat patties)","cuisine":"European","category":"Main","ingredients":["750 g beef or poultry meat (0.5–1 kg, soup meat)","500 g soup greens (włoszczyzna) (carrot, parsley root, celeriac, white cabbage)","1 egg (raw)","1 onions (large or 2 small)","75 g breadcrumbs (50–100 g)","to taste salt","to taste black pepper","3 allspice (berries)","3 bay leaves","1.5 l water (for cooking meat and vegetables)","to taste oil (for frying)"],"steps":["Rinse the meat and simmer in water until tender (for 45–60 minutes) with the peeled soup greens, allspice berries, bay leaves, salt, and pepper.","Remove the cooked meat and vegetables from the broth, debone the meat, and grind both in a meat grinder.","Peel the onion, finely dice it, and add to the minced meat and vegetable mixture.","Crack in the egg, add breadcrumbs, season with salt and pepper, and knead the mixture thoroughly.","Shape into round patties about 1.5 cm thick and 5 cm in diameter.","Fry the patties in hot oil for 2 minutes on each side."],"time":90,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Karminadle","page":"Książka kucharska/Karminadle"},{"id":"oc-plwb-18859","title":"Karp w pieczarkach (pan-fried carp baked with mushrooms and cream)","cuisine":"European","category":"Main","ingredients":["750 g carp fillets","200 g button mushrooms","200 ml sour cream (1 kubek)","2 onions","2 tbsp wheat flour (for coating)","to taste salt","to taste black pepper","to taste vegetable oil (for frying)"],"steps":["Cut the carp fillets into portions, rub with salt and pepper, and set aside briefly in a cool place.","Dredge the fish pieces in wheat flour, fry in hot oil, and transfer to a baking dish.","Peel and slice the mushrooms and onions, sauté in a pan, and spread over the fish.","Pour over the sour cream and bake in an oven preheated to 180 °C for 10 minutes until the fish absorbs the cream."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Karp_w_pieczarkach","page":"Książka kucharska/Karp w pieczarkach"},{"id":"oc-plwb-18685","title":"Karp w piwie (Polish carp braised in lager with root vegetables)","cuisine":"European","category":"Main","ingredients":["1 carp (medium)","30 g wheat flour (originally 10 g)","150 g butter","80 g onion","50 g celeriac","60 g parsley root","100 g button mushrooms","200 ml lager beer","to taste salt","to taste black pepper"],"steps":["Fillet the carp, cut into portions, season with salt and pepper, dust with wheat flour, and sear in part of the butter.","Peel the onion, celeriac, parsley root, and mushrooms, cut into strips, and cook gently, covered, in the remaining butter until tender.","Pour the lager beer over the vegetables, arrange the seared fish on top, cover, and braise together for about 15 minutes."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Karp_w_piwie","page":"Książka kucharska/Karp w piwie"},{"id":"oc-plwb-14417","title":"Kartoflanka (Polish potato soup with smoked bacon and wild mushrooms)","cuisine":"European","category":"Soup","ingredients":["2 l meat broth","2 dried forest mushrooms","50 g smoked bacon","1 onion","1 bunch soup greens (włoszczyzna)","1 kg potatoes","to taste parsley leaves or dill","200 ml sour cream 12% (1 tub)"],"steps":["Add the soup greens, crumbled dried mushrooms, and peeled, diced potatoes to the meat broth, then simmer for about 15 minutes.","Remove the cooked greens from the soup, chop them finely, and return them to the pot.","Fry the diced smoked bacon in a skillet, add the chopped onion, sauté until golden, and transfer everything into the soup.","Temper the 12% sour cream with a few spoonfuls of hot broth, pour it into the pot, and bring to a boil.","Before serving, sprinkle the soup generously with chopped parsley leaves or dill."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kartoflanka","page":"Książka kucharska/Kartoflanka"},{"id":"oc-plwb-16935","title":"Kartoflanka po węgiersku (Hungarian-style potato soup with browned pasta)","cuisine":"European","category":"Soup","ingredients":["50 g pork fatback","100 g pasta (large shapes)","2 tbsp sweet paprika powder","250 g potatoes","to taste salt","1 l water"],"steps":["Finely dice the pork fatback and render it in a pot.","Add the pasta into the hot fat and fry until golden brown.","Stir in the sweet paprika powder quickly, then add the peeled, diced potatoes.","Pour in water, season with salt to taste, and simmer over low heat, stirring occasionally, until the potatoes and pasta are tender."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kartoflanka_po_w%C4%99giersku","page":"Książka kucharska/Kartoflanka po węgiersku"},{"id":"oc-plwb-21722","title":"Kartofle nadziewane grzybami (stuffed potatoes with wild mushrooms and leeks)","cuisine":"European","category":"Main","ingredients":["30 potatoes","9 fresh or dried forest mushrooms (8–10 pieces)","300 g butter (250–370 g)","1 egg (whole)","2 egg yolks","2 leeks","3 tbsp breadcrumbs","4 tbsp broth (a few tablespoons)","to taste salt","to taste black pepper"],"steps":["Rinse the fresh or dried mushrooms, simmer until tender while reserving the cooking broth, and finely chop.","Chop the leeks and sauté them in a tablespoon of butter.","Combine the leeks with mushrooms, breadcrumbs, whole egg, and yolks, then season the stuffing with salt and pepper.","Wash and peel the potatoes, slice a thin flat piece off the bottom for stability, cut a larger lid off the top, and hollow out the center of each potato with a teaspoon.","Fill the hollowed potatoes with the mushroom stuffing, replace the potato lids, and arrange closely in a wide braising pot.","Pour over the remaining melted butter and broth combined with mushroom cooking liquid, cover, and braise until tender."],"time":90,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kartofle_nadziewane_grzybami","page":"Książka kucharska/Kartofle nadziewane grzybami"},{"id":"oc-plws-580406","title":"Kartofle z sosem chrzanowym (baked potatoes with horseradish sauce)","cuisine":"European","category":"Main","ingredients":["1 kg potatoes","5 eggs","5 tomatoes","to taste butter (for greasing the dish and dotting the vegetables)","750 ml horseradish sauce (thick, made with sour cream)","to taste breadcrumbs (for sprinkling on top)"],"steps":["Boil the unpeeled potatoes until tender, about 25 minutes, peel while still hot, and cut into slices.","Boil the eggs hard for 10 minutes, peel, and slice them, then slice the washed tomatoes as well.","Butter a baking dish, arrange the slices of potato, egg, and tomato in rows, and dot with pieces of butter.","Pour the thick horseradish and sour cream sauce evenly over the dish and sprinkle the top with breadcrumbs.","Place the dish in an oven preheated to 200 °C and bake for 10 minutes until the top is lightly browned."],"time":55,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Kartofle_z_sosem_chrzanowym","page":"100 postnych i jarskich dań/Kartofle z sosem chrzanowym"},{"id":"oc-plwb-21721","title":"Kartofle zapiekane ze śledziem (Polish potato and herring bake)","cuisine":"European","category":"Main","ingredients":["2 kg potatoes","2 onions","2.5 tbsp butter (2–3 tablespoons)","4 herring (2 whole salted herrings or 4 fillets in oil)","3 tbsp breadcrumbs (a few tablespoons)","to taste salt","250 ml sour cream (1 szklanka, optional)"],"steps":["Boil the potatoes in their jackets with salt, let cool, peel, and cut into thin slices.","Soak the herrings if salted, debone, and finely chop the fillets.","Peel and chop the onions, and sauté in a tablespoon of butter.","Grease a baking dish with butter and layer the potatoes, herring, and sautéed onions.","Top with breadcrumbs and drizzle with remaining melted butter or sour cream.","Bake for 20–30 minutes in an oven preheated to 200 °C."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kartofle_zapiekane_ze_%C5%9Bledziem","page":"Książka kucharska/Kartofle zapiekane ze śledziem"},{"id":"oc-plwb-21723","title":"Kartofle zapiekane ze śmietaną (baked potatoes in sour cream and onions)","cuisine":"European","category":"Side","ingredients":["2 kg potatoes","300 ml sour cream (1–1.5 glasses of thick sour cream)","to taste salt","0.5 onion (optional)","0.5 tbsp butter (optional)"],"steps":["Boil potatoes in their jackets, let cool, peel, and cut into slices or cubes.","Chop the onion and sauté in butter.","Transfer potatoes and sautéed onion to a baking dish, season with salt, add sour cream, and toss gently.","Bake in an oven preheated to 200 °C until the sour cream thickens and turns lightly golden."],"time":65,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kartofle_zapiekane_ze_%C5%9Bmietan%C4%85","page":"Książka kucharska/Kartofle zapiekane ze śmietaną"},{"id":"oc-plws-546712","title":"Kartofle — bomby (whole golden roasted potatoes)","cuisine":"European","category":"Side","ingredients":["10 potatoes (orig. 8–12 evenly sized potatoes)","1 l water (for parboiling and shocking the potatoes)","2 tbsp vegetable oil","to taste salt"],"steps":["Parboil the evenly sized potatoes in their skins until half tender, then plunge them briefly into cold water and slip off their thin skins.","Heat two tablespoons of oil in a roasting pan or deep skillet, arrange the peeled potatoes inside, and sprinkle with salt.","Roast in a hot oven (200 °C) or covered on the stovetop, turning several times, until evenly browned on all sides."],"time":50,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kartofle_%E2%80%94_bomby","page":"109 potraw/Kartofle — bomby"},{"id":"oc-plwb-21754","title":"Kasza gryczana z fetą (buckwheat groats with feta, sun-dried tomatoes, and olives)","cuisine":"European","category":"Main","ingredients":["200 g buckwheat groats","300 g feta cheese (or goat cheese or bryndza)","1 bunch parsley leaves","1 tbsp butter","1 tbsp olive oil","3.5 sun-dried tomatoes (3–4 pieces)","150 g black olives (1 small glass (150 ml))","400 ml hot water (in 1:2 ratio)","to taste salt"],"steps":["Pour hot water over the buckwheat groats, add salt and butter, and cook with lid slightly ajar over very low heat for 15 minutes without stirring.","Remove the pot from the heat and leave covered for 10–30 minutes until the groats absorb all the liquid.","Dice the feta cheese, slice sun-dried tomatoes into thin strips, and cut black olives into rings.","Finely chop the parsley leaves and fold all ingredients into the warm buckwheat with olive oil."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kasza_gryczana_z_fet%C4%85","page":"Książka kucharska/Kasza gryczana z fetą"},{"id":"oc-plwb-17906","title":"Kasza trzebiatowska po rycersku (Trzebiatów knight-style barley with pork and pork belly)","cuisine":"European","category":"Main","ingredients":["500 g barley groats","500 g vegetables for broth (carrot, celeriac, parsley root)","200 g raw pork belly","200 g minced pork","5 canned tomatoes (or 500 ml tomato paste)","3 onions (medium)","3 tbsp lard","to taste salt","to taste white pepper","2.5 tsp curry powder (2–3 teaspoons)","1.5 l water (for broth)"],"steps":["Cook the broth vegetables in water, pour the broth over the barley groats in a large pot at a 1:3 ratio, add curry powder, and cook until the grains are separate.","Dice the raw pork belly and fry in melted lard until golden.","Add finely chopped onion, and after 2–3 minutes add the minced pork and fry together for about 15 minutes.","Add coarsely diced canned tomatoes, season with salt and white pepper, and stir well.","Combine the skillet contents into the pot with hot cooked barley, mix thoroughly, and let rest covered for 15 minutes before serving."],"time":65,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kasza_trzebiatowska_po_rycersku","page":"Książka kucharska/Kasza trzebiatowska po rycersku"},{"id":"oc-plwb-18626","title":"Kaszanka smażona (fried Polish blood sausage with apples and oscypek).","cuisine":"European","category":"Main","ingredients":["800 g kaszanka (Polish blood sausage)","2 tart apples (firm)","3 onions","150 g oscypek (smoked sheep cheese) or firm cheese","6 tbsp vegetable oil","6 fresh marjoram (sprigs)"],"steps":["Peel casing from the kaszanka, slice into rounds, and fry in 2 tablespoons of oil until crispy.","Wash the apples, cut into eighths, and fry in another 2 tablespoons of oil until golden.","Peel the onions, slice them, and sauté in the remaining 2 tablespoons of oil.","Arrange the apples at the bottom of a baking dish, cover with the sautéed onions and chopped fresh marjoram.","Layer the slices of kaszanka on top, sprinkle with grated oscypek or firm cheese, and bake for 15–20 minutes in an oven preheated to 180 °C."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kaszanka_sma%C5%BCona","page":"Książka kucharska/Kaszanka smażona"},{"id":"oc-plwb-16277","title":"Keks (Polish fruitcake)","cuisine":"European","category":"Cake","ingredients":["5 eggs","250 g sugar","200 g plain flour","250 ml mixed dried fruit and nuts (assorted dried fruit and nuts)"],"steps":["Separate the egg whites from the yolks, beat the whites until stiff peaks form, and chill in the refrigerator.","Beat the egg yolks with the sugar until pale, then, stirring constantly, fold in the dried fruit and nuts dusted with a little plain flour.","Gradually fold in the remaining plain flour 1 tbsp at a time, and finally gently fold in the chilled beaten egg whites.","Transfer the batter to a loaf tin and bake for about 40 minutes in an oven preheated to 160 °C, then increase the temperature to 180 °C and bake for another 10 minutes."],"time":75,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Keks","page":"Książka kucharska/Keks"},{"id":"oc-plws-569442","title":"Kiełbasa gęsia wędzona (cold-smoked goose, beef, and pork sausage)","cuisine":"European","category":"Preserve","ingredients":["750 g goose meat from legs and carcasses (1 part (per 3 kg total meat))","750 g tender beef (orig. the same amount as the goose meat)","1.5 kg pork neck (orig. twice as much marbled pork neck)","250 g raw goose fat (orig. a quarter kilo per 3 kg meat, ground)","100 g salt (as for smoked kiełbasa (Polish sausage))","1 tbsp black pepper (finely pounded)","1 tsp allspice (finely pounded)","1 tbsp marjoram (powdered)","1 tsp coriander seeds (finely pounded)","0.5 tsp potassium nitrate (for curing)","1 medium casings (cleaned, for stuffing)"],"steps":["Cut the goose meat from legs and carcasses (750 g), an equal amount of tender beef (750 g), and twice the amount of marbled pork neck (1.5 kg) with a sharp knife into tiny dice.","For 3 kg of meat, add 250 g of ground raw goose fat along with salt, potassium nitrate, and finely powdered black pepper, allspice, marjoram, and coriander, then mix thoroughly.","Pack the seasoned meat into a bowl, press down with a weighted board, and keep for 3 days in a cool storeroom.","Stuff the mixture as tightly as possible into medium-wide casings and air-dry for 2–3 days in the wind.","Cold-smoke the kiełbasa (Polish sausages) for about a week."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/Kie%C5%82basa_g%C4%99sia","page":"Domowe wędliny/Kiełbasa gęsia"},{"id":"oc-plwb-21713","title":"Kiełbaski w piwie (sausages braised in beer)","cuisine":"European","category":"Main","ingredients":["6 kiełbaski (small Polish sausages) (5–6 small sausages)","300 ml pale beer","1 tbsp butter","1 bouillon cube","1 onion","3 tbsp breadcrumbs","1 tbsp capers (or lemon juice or vinegar)"],"steps":["Arrange the small Polish sausages in a saucepan and pour in 300 ml of pale beer.","Add the butter, crumbled bouillon cube, and sliced onion.","Heat everything over low heat, making sure the sausages do not burn.","Just before boiling, stir in the breadcrumbs and capers, mixing thoroughly until the sauce thickens slightly."],"time":20,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kie%C5%82baski_w_piwie","page":"Książka kucharska/Kiełbaski w piwie"},{"id":"oc-plwb-28619","title":"Kisiel malinowy (raspberry fruit kissel)","cuisine":"European","category":"Dessert","ingredients":["500 ml water (plus a little cold water to dissolve the starch)","2 tbsp potato starch","6 tbsp sugar","250 ml raspberries"],"steps":["Bring 500 ml of water to a boil in a saucepan.","Dissolve the potato starch together with the sugar in a small amount of cold water.","Pour the slurry into the boiling water, stirring vigorously all the while, until the kissel thickens.","Finally, stir in the crushed raspberries and mix thoroughly."],"time":10,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kisiel_malinowy","page":"Książka kucharska/Kisiel malinowy"},{"id":"oc-plwb-16983","title":"Kisiel mleczno-migdałowy (milk pudding with almonds)","cuisine":"European","category":"Dessert","ingredients":["375 ml milk","1 tbsp potato starch (heaped)","to taste vanilla flavouring (5–6 drops)","3 almonds"],"steps":["Skin the almonds and chop them finely.","Bring 250 ml of the milk to a boil in a saucepan. Thoroughly mix the heaped tablespoon of potato starch into the remaining 125 ml of cold milk until smooth.","Slowly pour the slurry into the simmering milk, stirring vigorously all the while.","Add the chopped almonds and vanilla flavouring and cook briefly until thickened, then pour the dessert into dessert bowls rinsed with cold water."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kisiel_mleczno-migda%C5%82owy","page":"Książka kucharska/Kisiel mleczno-migdałowy"},{"id":"oc-plwb-6491","title":"Kisiel mleczny piegowaty (spotted milk pudding)","cuisine":"European","category":"Dessert","ingredients":["1 custard powder with sugar (packet (cream, vanilla, banana, chocolate, or almond flavour))","200 g bilberries","500 ml milk","1 tbsp butter (or margarine)","to taste whipped cream (for decoration)"],"steps":["Sort through the bilberries, rinse them, and pat dry.","Cook the pudding in the milk with the butter according to the package instructions.","Set the prepared pudding aside to cool to room temperature.","Mix the cooled pudding with the bilberries, transfer into small bowls, and chill.","Before serving, decorate the dessert with dollops of whipped cream."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kisiel_mleczny_piegowaty","page":"Książka kucharska/Kisiel mleczny piegowaty"},{"id":"oc-plwb-61674","title":"Kiszczonka (Polish blood sausage soup)","cuisine":"European","category":"Soup","ingredients":["1.5 l water","1 bunch Polish soup vegetables (włoszczyzna) (bunch)","500 g potatoes","500 g kaszanka (blood sausage) (any type)","1 onion","180 g 18% sour cream","to taste salt","to taste pepper","to taste marjoram"],"steps":["Peel the potatoes and dice them, remove the casing from the blood sausage, and peel and halve the onion.","Place the potatoes, skinned blood sausage, bunch of soup vegetables, and onion in a pot, pour in 1.5 l of water, and cook for about 20 minutes until the potatoes are tender.","Remove the bunch of soup vegetables from the broth, separate the cooked carrot, slice it, and return it to the pot.","Season the soup with salt, pepper, and marjoram, stir in the 18% sour cream, and bring briefly to a boil before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kiszczonka","page":"Książka kucharska/Kiszczonka"},{"id":"oc-plws-569444","title":"Kiszki kaszane (buckwheat blood sausage, kaszanka)","cuisine":"European","category":"Main","ingredients":["2 l buckwheat groats (orig. 2 kwarty of buckwheat groats (or 1 l of barley groats scalded with hot milk))","2 l pork blood (orig. 2 kwarty, strained to remove clots)","1 l rendered pork intestinal fat (orig. 1 kwarta of rendered intestinal fat)","3 tbsp marjoram (orig. 1 handful of rubbed marjoram)","1 tsp allspice (ground)","to taste salt (for the mixture and the poaching water)","to taste black pepper","1 pork casings (strong, cleaned)"],"steps":["Mix 2 l of buckwheat groats with 2 l of strained pork blood and 1 l of rendered pork fat.","Season the mixture with salt, black pepper, a handful of rubbed marjoram, and ground allspice, and mix thoroughly.","Fill strong pork casings halfway with the mixture (so the groats have room to swell) and tie or pin the ends securely.","Place the sausages in a large pot of well-salted boiling water, bring back to a boil, and cook over very low heat for about 45–60 minutes until the groats are tender, taking care that the casings do not burst.","Remove the cooked blood sausages, cool, and store in a cool, dry place; to serve, cut into thick slices and fry in melted fresh fatback."],"time":120,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/Kiszki_kaszane","page":"Domowe wędliny/Kiszki kaszane"},{"id":"oc-plwb-16179","title":"Kiszona kapusta (homemade sauerkraut)","cuisine":"European","category":"Preserve","ingredients":["10 kg white cabbage","250 g salt (200–300 g)","10 g caraway seeds","500 g carrots"],"steps":["Shred the white cabbage, grate the carrots on a coarse grater, and mix the vegetables with the salt and caraway seeds.","Line the bottom of a barrel or stoneware crock with whole cabbage leaves, then pack the shredded vegetables in layers, tamping them down firmly until juices release and leaving about 10 cm of headspace from the rim.","Cover the top with cabbage leaves, place a flat plate or wooden disc over them, and weigh down with a scalded stone or a jar filled with water.","Leave the crock for 3 days at room temperature for fermentation to start, then transfer to a cool place at 8–10 °C.","Ensure the cabbage remains completely submerged in brine, topping up if necessary with a brine made from 1 tbsp of salt per 1 l of water."],"time":60,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kiszona_kapusta","page":"Książka kucharska/Kiszona kapusta"},{"id":"oc-plwb-19649","title":"Kiszone ogórki (brined sour pickles)","cuisine":"European","category":"Preserve","ingredients":["9 small pickling cucumbers","2 clove garlic","1 dill with umbels (sprig)","1 horseradish root (piece)","to taste allspice berries (a few berries)","to taste black peppercorns (a few peppercorns)","to taste sour cherry or vine leaves (optional, 1–3 leaves)","0.5 tsp rock salt","500 ml water (hot)"],"steps":["Wash the cucumbers very thoroughly and pack them tightly upright into a sterilised one-litre jar.","Add the halved garlic cloves, dill sprig, peeled piece of horseradish root, allspice berries, peppercorns, and optionally the sour cherry or vine leaves.","Dissolve half a teaspoon of rock salt in 500 ml of hot water and pour over the cucumbers in the jar.","Tightly screw on the jar lid, invert it, and then pasteurise for 15 minutes in an oven preheated to 90 °C."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kiszone_og%C3%B3rki","page":"Książka kucharska/Kiszone ogórki"},{"id":"oc-plws-450876","title":"Klasyczny tort wiedeński z konfiturą malinową (Viennese four-layer butter torte with raspberry jam)","cuisine":"European","category":"Cake","ingredients":["400 g butter (orig. 40 dag, plus a little for greasing the paper)","400 g icing sugar (orig. 40 dag)","8 eggs (separated into yolks and whites)","20 bitter almonds (scalded, peeled, and finely pounded)","400 g plain flour (orig. 40 dag)","300 g raspberry preserves or redcurrant jelly (for filling the layers and garnishing)","to taste lemon fondant (for icing the top)"],"steps":["Beat 400 g of butter until fluffy, add 400 g of icing sugar, and beat in 8 egg yolks one at a time, stirring in one direction until the mixture doubles in volume.","Add 20 scalded, peeled, and finely pounded bitter almonds, and gradually beat in 400 g of plain flour a few spoonfuls at a time, beating thoroughly (about 15–20 minutes with a mixer; historically an hour by hand).","Beat the 8 egg whites until stiff and fold gently into the batter.","Spread the batter over 4 buttered rounds of baking paper the size of a large plate and bake in a moderately warm oven (about 170 °C); peel off the paper immediately after removing from the oven.","Sandwich the baked rounds with a thin layer of raspberry preserves or redcurrant jelly, ice the top with lemon fondant, dry for a few minutes in a warm oven, and garnish with preserves drained of syrup."],"time":115,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_wiede%C5%84ski","page":"Ciasta wielkanocne/Tort wiedeński"},{"id":"oc-plws-580425","title":"Klops z soczewicy (lentil loaf with soubise sauce)","cuisine":"European","category":"Main","ingredients":["300 g lentils (soaked overnight)","1 tbsp butter (for the lentil mixture, plus extra for baking the loaf and cooking the vegetables)","2 eggs","to taste plain wheat flour (enough to form a firm, flat layer)","to taste breadcrumbs (for sprinkling over the loaf near the end of baking)","500 g carrots (young)","1 onion (finely chopped, for the filling)","to taste fresh dill (chopped)","5 onion (for the sauce)","1 tbsp butter (for cooking the onions for the sauce)","1 tsp butter (sweet cream butter, for finishing the sauce)","1 tbsp plain wheat flour (for thickening the sauce)","250 ml milk (or sweet cream)","to taste salt (for the lentil mixture and sauce)","to taste white pepper (for the lentil mixture and sauce)"],"steps":["Soak the lentils in water overnight, then boil them in the same water until tender, about 35 minutes, drain, and dry briefly over the heat.","Pass the hot lentils through a mincer, season with salt and white pepper, and add a tablespoon of butter, the eggs, and enough wheat flour to knead into a mixture that can be shaped into a flat layer about 2 cm thick.","Cook the young carrots gently in butter, covered, for 15 minutes until tender, chop them finely, and mix with the onion fried in butter and the chopped dill.","Spread the carrot filling over the lentil layer, roll it up tightly like a roulade, and transfer carefully to a roasting pan with browned butter.","Bake the loaf in an oven preheated to 180 °C for about 35 minutes, basting frequently with butter, then sprinkle with breadcrumbs near the end of baking and brown.","Make the soubise sauce: cook the five cut onions gently in a tablespoon of butter, covered, for 15 minutes without browning. Pass them through a mincer, season with salt, sprinkle with a tablespoon of wheat flour, pour in the milk, and bring briefly to a boil. Remove from the heat and stir in a teaspoon of fresh butter and a pinch of white pepper.","Slice the baked lentil loaf and serve hot with the onion sauce in a sauceboat."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Klops_z_soczewicy","page":"100 postnych i jarskich dań/Klops z soczewicy"},{"id":"oc-plwb-18733","title":"Klopsy (braised pork and rice meatballs)","cuisine":"European","category":"Main","ingredients":["500 g pork neck","4 onions","2 carrots","125 ml vegetable oil","to taste salt","to taste pepper","to taste sweet ground paprika","2 tbsp tomato paste","250 ml rice (raw)"],"steps":["Grind the pork collar in a meat grinder, season with salt, pepper, and sweet paprika, and mix with 250 ml of raw rice.","Dice the onions, cook until translucent in 125 ml of heated oil, add the coarsely grated carrots, and fry for 5 minutes over low heat.","Stir the tomato paste into the sautéed vegetables and set aside to cool.","Add one-third of the stewed carrots and onions to the meat-and-rice mixture, mix thoroughly, and shape into small meatballs.","Spread the remaining vegetables over the bottom of a deep pan, arrange the shaped meatballs on top, add a splash of water, and braise, covered, for about 40 minutes."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Klopsy","page":"Książka kucharska/Klopsy"},{"id":"oc-plwb-14270","title":"Kluski biołe (kluski śląskie) (white Silesian dumplings)","cuisine":"European","category":"Side","ingredients":["1.5 kg boiled potatoes","to taste potato starch (in a volume equal to one-quarter of the mashed potatoes)","1 egg","1 pinch salt (optional)"],"steps":["Pass the cooked potatoes through a ricer into a bowl and level their surface with your hand.","Remove one-quarter of the potato mixture from the bowl, and fill the resulting hollow with potato starch.","Return the removed potatoes to the bowl, crack in the egg, add a pinch of salt, and knead by hand into a smooth, uniform dough.","Shape the dough into small, slightly flattened balls.","Drop the dumplings into boiling water, and once they float to the surface, lower the heat and cook for another 5–10 minutes."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kluski_bio%C5%82e_(kluski_%C5%9Bl%C4%85skie)","page":"Książka kucharska/Kluski biołe (kluski śląskie)"},{"id":"oc-plwb-12877","title":"Kluski na parze (steamed yeast dumplings)","cuisine":"European","category":"Main","ingredients":["500 g plain flour","40 g fresh yeast","200 ml milk","65 g butter (60–70 g, very soft, plus extra for drizzling)","1 egg","2 tbsp sugar (plus extra for sprinkling)","1 pinch salt"],"steps":["Mash the yeast with 1 tsp of sugar, 1 tsp of plain flour, and 75 ml of warm milk to make a starter.","Pour the remaining plain flour into a bowl, make a well, pour in the starter, cover with a cloth, and set aside for about 30 minutes until active.","Add the egg, remaining milk, very soft butter, remaining sugar, and a pinch of salt to the bowl, and knead the dough by hand or with a mixer until smooth.","Dust the dough with plain flour, roll out to a thickness of 1.5 cm, and cut out rounds with a round cutter.","Cover the shaped dumplings with a cloth and leave for about 30 minutes to double in volume.","Arrange the risen dumplings in batches on a steamer insert and steam, covered, for 5–10 minutes.","Serve the ready dumplings drizzled with butter and sprinkled with sugar."],"time":85,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kluski_na_parze","page":"Książka kucharska/Kluski na parze"},{"id":"oc-plwb-18623","title":"Kluski orzechowe (baked dumplings with walnuts)","cuisine":"European","category":"Main","ingredients":["300 g plain flour","1 egg","2 tbsp soy flour","100 ml water (for the dough, plus 1.5 l for boiling)","20 g butter","50 g walnuts (finely chopped)","to taste salt"],"steps":["Bring 1.5 l of salted water to a boil in a pot.","Sift the plain flour onto a pastry board, add the egg, soy flour, and 100 ml of water, and knead into a fairly soft dough.","Cut small dumplings from the dough, drop them into the salted boiling water, cook for several minutes over low heat, then drain and rinse with cold water.","Grease an ovenproof dish with a generous layer of butter, transfer the cooked dumplings into it, and bake briefly in the oven.","Serve the dumplings hot, sprinkled with the finely chopped walnuts."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kluski_orzechowe","page":"Książka kucharska/Kluski orzechowe"},{"id":"oc-plwb-18821","title":"Kluski z bryndzą (bryndza cheese dumplings)","cuisine":"European","category":"Main","ingredients":["250 g bryndza cheese","350 g plain flour","1 egg","125 ml plain yogurt","1 bunch dill","to taste salt"],"steps":["Cream the bryndza cheese in a bowl with a wooden spoon until smooth, and rinse and finely chop the dill.","Add 125 ml of plain yogurt, the chopped dill, sifted plain flour, and egg to the bryndza, and knead into a firm dough.","Cover the dough and set aside for 60 minutes to rest.","Roll out the dough fairly thickly on a floured board and cut into small squares.","Drop the dumplings in batches into salted boiling water, cook until they float to the surface, then remove to a sieve and rinse with warm water."],"time":85,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kluski_z_bryndz%C4%85","page":"Książka kucharska/Kluski z bryndzą"},{"id":"oc-plwb-2755","title":"Kluski śląskie (Silesian potato dumplings)","cuisine":"European","category":"Side","ingredients":["1 kg potatoes","250 g potato starch (plus extra for dusting)","to taste egg (optional)","to taste salt"],"steps":["Peel the potatoes and boil them in salted water until tender.","Pass the cooked potatoes through a ricer or mash thoroughly with a potato masher.","Add the potato starch, salt, and optionally the egg, then knead into a uniform dough.","Dust your hands with potato starch, shape the dough into small balls, flatten them slightly, and press a dimple into the centre of each dumpling with your finger.","Coat the shaped dumplings in potato starch and drop them in batches into salted boiling water.","Once the dumplings float to the surface, lower the heat and cook for about 5 minutes, then drain."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kluski_%C5%9Bl%C4%85skie","page":"Książka kucharska/Kluski śląskie"},{"id":"oc-plwb-61766","title":"Kluski śląskie z sosem grzybowym (Silesian potato dumplings with mushroom sauce)","cuisine":"European","category":"Main","ingredients":["1 kg cooked potatoes (preferably from the previous day)","40 g plain flour","60 g potato starch","250 ml water (for the sauce)","1 egg","1 pinch salt","1 dried mushrooms (packet)","1 onion","1 clove garlic","125 ml sour cream","0.5 bunch parsley","1 tbsp vegetable oil (for frying)"],"steps":["Soak the dried mushrooms in water, and once softened, drain them, reserving the liquid, and slice into strips.","Pass the cooked potatoes through a ricer, add the egg, a pinch of salt, the plain flour, and the potato starch, and quickly knead into a uniform dough.","Roll the dough into logs, cut them into two-centimetre pieces, and shape into balls with a dimple in the centre.","Drop the dumplings into salted boiling water, cook until they float to the surface, then drain.","Heat the oil in a frying pan and sauté the sliced mushrooms along with the finely chopped onion and garlic.","Pour the mushroom soaking liquid and 250 ml of fresh water into the pan, add 125 ml of sour cream, and cook for several minutes until the sauce thickens, then spoon over the dumplings and sprinkle with chopped parsley."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kluski_%C5%9Bl%C4%85skie_z_sosem_grzybowym","page":"Książka kucharska/Kluski śląskie z sosem grzybowym"},{"id":"oc-plws-580462","title":"Knedle (savory bread dumplings)","cuisine":"European","category":"Main","ingredients":["500 ml breadcrumbs","750 ml milk (boiling)","3 egg yolks","1 tbsp butter (for creaming with the yolks, plus extra for browning the onions and pouring over the dumplings)","3 tbsp plain wheat flour (for the mixture, plus extra for coating the dumplings)","3 onion (2 finely chopped for the mixture and 1 for the browned butter topping)","3 egg whites (beaten to stiff peaks)","to taste salt (for the mixture and boiling water)"],"steps":["Pour the hot milk over the breadcrumbs and let stand for 10 minutes to swell.","Finely chop the onions and fry them in butter for about 8 minutes until golden brown, reserving part of the onions and butter for topping the finished dumplings.","Cream the egg yolks with a tablespoon of butter until pale, add three tablespoons of wheat flour, the browned onion, and the soaked breadcrumbs, season with salt, and gently fold in the stiffly beaten egg whites.","Shape the mixture into round dumplings and roll each one in wheat flour.","Drop the dumplings into boiling salted water in a large pot and boil for about 10 minutes, then lift out with a slotted spoon onto a platter and pour plenty of onion-browned butter over them."],"time":45,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Knedle","page":"100 postnych i jarskich dań/Knedle"},{"id":"oc-plwb-12698","title":"Knedle z wiśniami (cherry potato dumplings)","cuisine":"European","category":"Main","ingredients":["1 kg potatoes","375 ml plain flour","1 egg","to taste salt","500 g sour cherries (pitted)","to taste sugar","1 vanilla sugar (packet)","to taste butter","to taste breadcrumbs"],"steps":["Wash the potatoes, boil until tender, peel, and pass through a grinder.","Add the plain flour, egg, and salt to the potatoes and briefly knead into a uniform dough.","Roll the dough into logs 2.5 cm in diameter and cut them into equal rounds.","Place the pitted sour cherries sprinkled with sugar and vanilla sugar onto each dough disc, then pinch the edges together and roll into a ball.","Drop the knedle in batches into salted boiling water, bring back to a boil, and cook until they float.","Serve the knedle drizzled with melted butter, dusted with breadcrumbs, and sprinkled with sugar."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Knedle_z_wi%C5%9Bniami","page":"Książka kucharska/Knedle z wiśniami"},{"id":"oc-plwb-15326","title":"Knedle ze śliwkami (plum dumplings)","cuisine":"European","category":"Main","ingredients":["600 g potatoes","300 g plain flour","500 g plums (pitted)","2 eggs","to taste salt","to taste butter (for the breadcrumb topping)","to taste breadcrumbs (for the breadcrumb topping)"],"steps":["Peel the potatoes, boil until tender, pass through a meat grinder, and cool completely.","Turn the cold potatoes out onto a pastry board, add the plain flour, eggs, and salt, and knead into a uniform dough.","Roll the dough into a log about 4 cm in diameter and cut it into rounds 2 cm thick.","Flatten each round in your hand, place a pitted plum in the centre, pinch the edges together firmly, and shape into a ball.","Drop the knedle into salted boiling water and cook for about 10 minutes after they float to the surface.","Drain the cooked knedle and serve with breadcrumbs fried in butter."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Knedle_ze_%C5%9Bliwkami","page":"Książka kucharska/Knedle ze śliwkami"},{"id":"oc-plwb-17825","title":"Kolorowa papryka (pickled mixed bell peppers)","cuisine":"European","category":"Preserve","ingredients":["1 kg mixed red, yellow, and green bell peppers","250 ml vinegar","250 ml water","1 pinch tarragon","1 pinch nutmeg (grated)","to taste allspice berries (a few berries)","to taste whole cloves (a few cloves)","to taste mustard seeds (a few seeds)","to taste peppercorns (a few peppercorns)","to taste salt","to taste sugar"],"steps":["Wash the peppers, blanch them briefly in boiling water, then rinse with cold water.","Remove the seeds, slice the peppers into fairly wide strips, and pack them in layers into jars.","Bring 250 ml of water to a boil with 250 ml of vinegar, the tarragon, grated nutmeg, allspice berries, cloves, mustard seeds, peppercorns, salt, and sugar.","Pour the boiling brine over the peppers, seal the jars tightly, and pasteurise for about 20 minutes."],"time":40,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kolorowa_papryka","page":"Książka kucharska/Kolorowa papryka"},{"id":"oc-plwb-14306","title":"Kolorowa papryka w oliwie (marinated bell peppers in olive oil)","cuisine":"European","category":"Salad","ingredients":["2 green bell pepper (whole)","2 red bell pepper (whole)","2 yellow bell pepper (whole)","4 clove garlic","1 bunch parsley","1 fileciki helskie (canned fish fillets) (can)","85 ml olive oil","to taste salt"],"steps":["Finely chop the parsley, and divide the peeled garlic: mince three cloves through a press, and slice one clove thinly.","Wash the green, red, and yellow bell peppers, remove the seeds, and cut the pods into 2–3 cm pieces.","Toss the peppers with the minced garlic and arrange on a serving platter.","Scatter the chopped parsley and garlic slices over the top and arrange the fileciki helskie fish fillets over them.","Season with salt, drizzle with 85 ml of olive oil, and leave overnight in a cool place."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kolorowa_papryka_w_oliwie","page":"Książka kucharska/Kolorowa papryka w oliwie"},{"id":"oc-plwb-17903","title":"Kolorowa sałatka warzywna (colourful vegetable salad with creamy dressing)","cuisine":"European","category":"Salad","ingredients":["2 bunch radishes","2 tomatoes","1 courgette (small)","2 red bell peppers","1 kohlrabi","0.25 bunch chives","0.5 bunch dill","2 tbsp garden cress","3 tbsp sour cream","1 tbsp vinegar","1 tbsp medium-hot mustard","5 tbsp vegetable oil","to taste salt","to taste pepper"],"steps":["Wash and dry all the vegetables, cut the radishes into rounds, finely dice the tomatoes, and slice the courgette into matchsticks.","Halve the red bell peppers, remove the seeds, and slice the flesh into thin strips, then grate the peeled kohlrabi on a coarse grater.","Finely chop the chives and dill, and toss them in a bowl with the chopped vegetables and cress.","Whisk together the sour cream, vinegar, and mustard, season with salt and pepper, then gradually pour in the oil, whisking until a thick, creamy dressing forms.","Pour the dressing over the salad, toss thoroughly, and set aside for about 10 minutes before serving."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kolorowa_sa%C5%82atka_warzywna","page":"Książka kucharska/Kolorowa sałatka warzywna"},{"id":"oc-plwb-14327","title":"Kolorowa zapiekanka (colourful vegetable bake)","cuisine":"European","category":"Main","ingredients":["2 tomatoes (large)","500 g pumpkin","500 g broccoli","1 turnip (small, or white icicle radish)","500 g Brussels sprouts","1 clove garlic","4 tbsp firm cheese (grated)","2 tbsp butter","1 tbsp plain flour (heaped)","250 ml milk","to taste nutmeg","to taste oregano","to taste salt","to taste pepper"],"steps":["Wash the vegetables, peel the pumpkin and turnip and slice them, blanch and peel the tomatoes and cut into slices, and divide the broccoli into florets.","Parboil the Brussels sprouts and turnip in salted boiling water for 5 minutes, and the broccoli florets for 2–3 minutes, then drain the vegetables in a sieve and cut the Brussels sprouts in half.","Melt 1 tbsp of butter in a saucepan, stir in a heaped tablespoon of plain flour, pour in 250 ml of cold milk, season with salt, pepper, and a pinch of nutmeg, and cook, stirring, until the sauce thickens.","Rub a baking dish with the cut clove of garlic and grease with the remaining tablespoon of butter, then arrange the prepared vegetables in it.","Dust the vegetables with grated nutmeg and oregano, pour over the sauce, and sprinkle with grated firm cheese.","Bake in an oven preheated to 180 °C for 30 minutes."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kolorowa_zapiekanka","page":"Książka kucharska/Kolorowa zapiekanka"},{"id":"oc-plwb-19422","title":"Kompot jabłkowy (apple compote drink)","cuisine":"European","category":"Drink","ingredients":["500 ml water","125 g sugar (100–150 g)","400 g apples"],"steps":["Wash the apples thoroughly, cut them into halves or smaller wedges, and core them.","Bring 500 ml of water to a boil in a pot, add the prepared apples, and cook for about 5 minutes.","Strain the decoction into a vessel, sweeten the warm kompot with sugar, stir thoroughly, and chill before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kompot_jab%C5%82kowy","page":"Książka kucharska/Kompot jabłkowy"},{"id":"oc-plwb-25762","title":"Kompot z suszonych owoców (dried fruit compote drink)","cuisine":"European","category":"Drink","ingredients":["300 g dried apples, pears, and apricots","100 g prunes","to taste lemon zest","to taste orange zest","1 lemon (juice)","1 tbsp sugar","1.5 l boiled water"],"steps":["Place the dried apples, pears, apricots, and prunes in a sieve and rinse them with hot water.","Pour 1.5 l of cold boiled water over the fruit and leave to soak overnight.","Transfer the water with the soaked fruit to a pot, add the sugar, freshly squeezed lemon juice, lemon zest, and orange zest.","Simmer the kompot over low heat until all the fruit is tender, and serve chilled."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kompot_z_suszonych_owoc%C3%B3w","page":"Książka kucharska/Kompot z suszonych owoców"},{"id":"oc-plws-544764","title":"Konfitura z białych porzeczek z pestkami (White currant preserve with seeds)","cuisine":"European","category":"Preserve","ingredients":["500 g white currants (orig. half a kilogr.; leave the seeds in)","750 g sugar (orig. three quarters of a kilogr.)","to taste water (for rinsing and preparing very thick syrup; amount not specified)"],"steps":["Rinse the white currants in cold water.","Leave on a sieve until very well drained.","Prepare a very thick syrup from sugar and water; the source does not specify the water amount.","Add the currants to the vigorously boiling syrup.","Simmer over low heat for about 15 minutes, skimming off the foam very carefully."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Porzeczki_bia%C5%82e","page":"Doświadczone sekreta smażenia konfitur i soków/Porzeczki białe"},{"id":"oc-plws-544770","title":"Konfitura z białych poziomek ananasowych (White pineberry preserve)","cuisine":"European","category":"Preserve","ingredients":["500 g white pineberries (large, ripe, and dry; orig. half a kilogr.)","to taste rum (for generous sprinkling over the fruit; amount not specified)","1000 g sugar (orig. one kilogr.)","375 ml water (orig. one and a half szklanki)"],"steps":["Select large, ripe, and dry white pineberries.","Arrange the berries on plates in a single layer.","Sprinkle the berries generously with rum.","Chill the berries in the refrigerator for 240–300 minutes.","Crush the sugar.","Place the sugar and water in a pot.","Bring the syrup to a boil, carefully skimming the foam.","Cook the syrup until it thickens and begins to pearl.","Add the chilled berries to the syrup.","Cook over moderate heat, frequently and gently shaking the pot and skimming the foam.","Reduce the heat and simmer until the syrup with fruit thickens.","Cool the preserve.","Transfer the preserve into jars.","Seal the jars with lids."],"time":300,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Poziomki_bia%C5%82e_ananasowe","page":"Doświadczone sekreta smażenia konfitur i soków/Poziomki białe ananasowe"},{"id":"oc-plws-544773","title":"Konfitura z czerwonych pomidorów (Red tomato preserve)","cuisine":"European","category":"Preserve","ingredients":["500 g ripe red tomatoes (orig. half a kilogr.)","to taste rum (for sprinkling over the tomatoes; amount not specified)","1000 g sugar (orig. one kilogr.)","375 ml water (orig. one and a half szklanki)","1 lemon (squeeze the juice)"],"steps":["Cut the tomatoes in half and scoop out the seeds.","Arrange the halves on a platter and sprinkle with rum.","Set aside in a cool place for 1440 minutes.","Boil the sugar with water into a thick syrup and skim off the foam carefully.","Add the tomatoes to the syrup and cook first over higher, then lower heat until the syrup thickens.","Towards the end, stir in the lemon juice and bring to a boil again.","Cool the preserve, transfer into jars, and seal."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Pomidory_czerwone","page":"Doświadczone sekreta smażenia konfitur i soków/Pomidory czerwone"},{"id":"oc-plws-544766","title":"Konfitura z poziomek (Wild strawberry preserve)","cuisine":"European","category":"Preserve","ingredients":["500 g wild strawberries (large, dry, and not overripe; orig. half a kilogr.)","1000 g sugar (orig. one kilogr.)","500 ml water (upper value of the 375–500 ml range; orig. one and a half or two small szklanki)"],"steps":["Select large, dry, and not overripe wild strawberries.","Crush the sugar.","Place the sugar and water in a pot.","Cook a thick syrup, carefully skimming the foam, until it begins to pearl.","Add the wild strawberries to the syrup.","Bring the preserve to a boil three times over moderate heat, moving the pot off the heat each time to skim the foam.","Continue cooking over low heat for about 15 minutes, shaking the pot frequently.","Test a drop of syrup on a cold knife: it should run off slowly and thicken as it flows.","Cool the preserve.","Transfer the preserve into jars.","Seal the jars with lids."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Poziomki","page":"Doświadczone sekreta smażenia konfitur i soków/Poziomki"},{"id":"oc-plws-544707","title":"Konfitura z zielonych orzechów włoskich (green walnut preserve)","cuisine":"European","category":"Preserve","ingredients":["500 g green walnuts (young, soft; orig. half a kilogr.)","750 g sugar (orig. three quarters of a kilogr.)","2 whole cloves (for studding the walnuts; orig. a few)","to taste cinnamon bark pieces (for studding the walnuts; amount not specified)","to taste water (for soaking the walnuts and cloves, boiling, and syrup; amount not specified)"],"steps":["Prick the walnuts thoroughly all over with a wooden skewer.","Soak them in cold water for 12960 minutes, changing the water morning and evening.","Drain the walnuts in a sieve.","Boil them in fresh water until a thick skewer pierces them easily.","Drain the boiled walnuts in a sieve.","Soak the cloves in water.","Stud the walnuts with the soaked cloves and small pieces of cinnamon.","Cook a syrup from 750 g sugar and water.","Simmer the walnuts in the boiling syrup until soft.","Set everything aside to cool.","Transfer the walnuts into jars.","Boil the remaining syrup until thickened.","Pour the completely cooled syrup over the walnuts.","If the syrup becomes watery after some time, boil it again and pour it over the walnuts once cooled."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Orzechy_w%C5%82oskie","page":"Doświadczone sekreta smażenia konfitur i soków/Orzechy włoskie"},{"id":"oc-plws-544771","title":"Konfitura z zielonych pomidorów (Green tomato preserve)","cuisine":"European","category":"Preserve","ingredients":["500 g green tomatoes (orig. half a kilogr.)","750 g sugar (orig. three quarters or one kilogr.; source allows 750–1000 g)","250 ml water for syrup (orig. a szklanka)","1 lemon (squeeze the juice)","to taste water for parboiling (enough to cover the tomatoes)"],"steps":["Cut the tomatoes in half and remove the seeds.","Cover with cold water and bring slowly to a boil.","Remove the tomatoes and drain in a sieve lined with a clean cloth.","Boil half of the sugar with 250 ml water and skim off the foam.","Add the lemon juice and bring the syrup to a boil again.","Pour the hot syrup over the tomatoes and set aside overnight, approximately 720 minutes.","The next day, remove the tomatoes and add the remaining sugar to the syrup.","Boil the syrup, skim off the foam, and add the tomatoes.","Simmer until the syrup thickens.","Cool the preserve, transfer into jars, and seal."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Pomidory_zielone","page":"Doświadczone sekreta smażenia konfitur i soków/Pomidory zielone"},{"id":"oc-plwb-31673","title":"Kopytka marchewkowe z sosem szczawiowym (potato and carrot dumplings with sorrel sauce)","cuisine":"European","category":"Main","ingredients":["1.25 kg potatoes","3 carrots","500 ml plain flour","2 tbsp potato starch","2 eggs","200 g sorrel","375 ml vegetable stock (from cooking the carrots)","3 tbsp butter","125 ml sour cream","2 tbsp plain flour","to taste salt","to taste pepper","to taste sugar"],"steps":["Boil the carrots until tender in about 375 ml of water, reserving the resulting vegetable stock for the sauce, then peel the cooked carrots and pass through a ricer.","Wash the sorrel, trim the tough stems, and sauté the leaves in butter until softened and darkened, then pass them through a sieve or blend.","Pour 375 ml of hot vegetable stock and 125 ml of sour cream mixed with 2 tbsp of plain flour into the sorrel, bring to a boil, and season to taste with salt, pepper, and sugar.","Peel the potatoes, boil them in salted water, and pass them through a ricer while still warm.","Mix the riced potatoes and carrots with 500 ml of plain flour, the potato starch, and the eggs, add salt, and knead into a soft dough on a pastry board.","Divide the dough into portions, roll out into logs 1.5 cm thick on a floured pastry board, flatten slightly, and cut diagonally with a damp knife into pieces 3–4 cm long.","Drop the kopytka in batches into salted boiling water, stir gently, and cook for 1–2 minutes after they float to the surface, then remove with a slotted spoon and serve with the sorrel sauce."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kopytka_marchewkowe_z_sosem_szczawiowym","page":"Książka kucharska/Kopytka marchewkowe z sosem szczawiowym"},{"id":"oc-plwb-17583","title":"Korniszony (cornichons / pickled baby gherkins)","cuisine":"European","category":"Preserve","ingredients":["1 kg small pickling cucumbers","125 ml spring onion (sliced)","1 carrot","250 ml vinegar (6% acidity)","625 ml water","1 tbsp sugar","1 tsp salt","6 black peppercorns (5–7 peppercorns)","6 allspice berries (5–7 berries)","2 whole cloves","2 bay leaves","to taste dill seeds (dry)"],"steps":["Wash the small cucumbers, then pour boiling water over them, followed by cold water.","Peel the carrot and slice into decorative stars, then pack the cucumbers tightly into jars, layering them with the spring onion slices, carrot, and dry dill seeds.","Bring 625 ml of water to a boil with 250 ml of 6% vinegar, the sugar, salt, peppercorns, allspice, cloves, and bay leaves, then leave the pickling brine to cool.","Pour the cooled vinegar brine over the cucumbers in the jars, seal tightly, and pasteurise for about 25 minutes."],"time":50,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Korniszony","page":"Książka kucharska/Korniszony"},{"id":"oc-plwb-18804","title":"Korzenna pieczeń z gruszkami (spiced roast pork shoulder with pears)","cuisine":"European","category":"Main","ingredients":["1 kg pork shoulder","6 pears (5–6 small pears)","4 tbsp wholegrain French mustard (with mustard seeds)","5 tbsp vegetable oil","to taste lemon juice","100 ml red wine","3 bay leaves","3 clove garlic","3 whole cloves","1 tsp ground ginger","1 tsp curry powder","to taste thyme","to taste salt"],"steps":["Make several 1 cm deep cuts in the pork shoulder and insert crushed garlic, crushed cloves, and bay leaves into the slits.","Rub the meat with the ground ginger, curry powder, and thyme.","Mix the wholegrain mustard with the oil, lemon juice, red wine, and a pinch of salt, pour the marinade over the meat, and refrigerate overnight.","Roast the marinated pork shoulder for 60 minutes, turning often and basting with the pan juices.","Surround the roast with the peeled pears and bake for another 30 minutes."],"time":115,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Korzenna_piecze%C5%84_z_gruszkami","page":"Książka kucharska/Korzenna pieczeń z gruszkami"},{"id":"oc-plwb-18077","title":"Kotlety chlebowe (bread and onion patties)","cuisine":"European","category":"Main","ingredients":["1 kg stale white bread","750 ml milk","4 onions","2 eggs","2 tbsp sunflower seeds","0.5 bunch parsley","to taste salt","to taste pepper","to taste vegetable oil (for frying)"],"steps":["Slice the stale white bread and soak it in 750 ml of milk.","Squeeze out the soaked bread and mince it through a grinder along with the peeled onions.","Toast the sunflower seeds in a dry pan and finely chop the parsley.","Add the eggs, sunflower seeds, and 2 tbsp of chopped parsley to the bread mixture, season with salt and freshly ground pepper, mix thoroughly, and shape into patties.","Fry the patties in well-heated oil on both sides until golden brown, then drain excess fat."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_chlebowe","page":"Książka kucharska/Kotlety chlebowe"},{"id":"oc-plwb-14009","title":"Kotlety mielone z farszem z ziół (herb-butter stuffed beef patties)","cuisine":"European","category":"Main","ingredients":["500 g minced beef","50 g butter","1 stale bread roll","0.5 bunch parsley leaves","0.5 bunch chives","0.5 bunch fresh thyme","2 clove garlic","1 onion","1 tbsp plain yogurt","1 tbsp mustard","2 eggs","to taste vegetable oil (for frying)","to taste salt","to taste pepper"],"steps":["Cream the butter with finely chopped parsley, chives, thyme, and minced garlic.","Transfer the herb butter to a piping bag, pipe out 6 equal portions, and place them in the freezer to set.","Soak the stale roll, squeeze dry, and combine with the minced beef, chopped onion, plain yogurt, mustard, and eggs.","Season the meat mixture with salt and pepper, knead thoroughly, and divide into 6 portions.","Place a frozen herb butter portion into the centre of each meat portion, shape into tightly sealed patties, and fry in hot oil on both sides."],"time":40,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_mielone_z_farszem_z_zi%C3%B3%C5%82","page":"Książka kucharska/Kotlety mielone z farszem z ziół"},{"id":"oc-plwb-14468","title":"Kotlety mielone z nadzieniem serowym (minced meat patties with cheese filling)","cuisine":"European","category":"Main","ingredients":["800 g minced beef","2 eggs","1 stale bread roll","4 tbsp sour cream","150 g mozzarella","0.5 bunch parsley","1 tbsp marjoram","1 onion","3 tbsp vegetable oil","to taste salt","to taste pepper"],"steps":["Peel the onion, chop finely, and cook until translucent in 1 tbsp of oil.","Soak the stale roll, squeeze out excess liquid, and mix with the minced meat, eggs, and sautéed onion, seasoning the mixture with salt, pepper, and marjoram.","Finely chop the mozzarella and parsley, and mix them with the sour cream.","Divide the meat mixture into 8 equal flattened patties, top 4 of them with the cheese filling, cover with the remaining 4 portions of meat, and seal the edges thoroughly.","Fry the patties on both sides in the remaining oil, then lower the heat towards the end, add a splash of water, and braise for several minutes."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_mielone_z_nadzieniem_serowym","page":"Książka kucharska/Kotlety mielone z nadzieniem serowym"},{"id":"oc-plwb-21432","title":"Kotlety schabowe faszerowane serem i ziołami (pork cutlets stuffed with herb cheese)","cuisine":"European","category":"Main","ingredients":["1 kg boneless pork loin","300 g firm cheese (grated)","100 g butter","1 tsp thyme","1 tsp oregano","1 tsp parsley (chopped)","1 tsp dill (chopped)","1 egg yolk","4 tbsp plain flour","2 tbsp breadcrumbs","4 tbsp vegetable oil","to taste salt","to taste pepper"],"steps":["Cut the pork loin into slices and pound thoroughly with a meat mallet.","Mix the butter, thyme, and oregano with the grated firm cheese, then add the egg yolk, breadcrumbs, chopped parsley, dill, salt, and pepper to knead into a uniform filling.","Place a portion of filling in the centre of each cutlet, fold the meat in half, and fasten the edges with toothpicks.","Season the assembled cutlets with salt and pepper, dredge in plain flour, and fry in hot oil on both sides until golden brown.","Remove the toothpicks from the fried cutlets before serving."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_schabowe_faszerowane_serem_i_zio%C5%82ami","page":"Książka kucharska/Kotlety schabowe faszerowane serem i ziołami"},{"id":"oc-plwb-13766","title":"Kotlety schabowe z ananasem (pork cutlets with pineapple and cheese)","cuisine":"European","category":"Main","ingredients":["500 g boneless pork loin","1 red bell pepper","1 canned pineapple (can, with syrup)","1 onion","1 egg","to taste olive oil (for frying)","to taste pepper","to taste salt","to taste meat seasoning","to taste honey","to taste firm cheese (sliced)","to taste breadcrumbs"],"steps":["Wash and dry the pork loin, cut into slices, and pound lightly with a meat mallet.","Season the meat with salt, pepper, and meat seasoning, coat in the beaten egg and breadcrumbs, and fry in heated olive oil until golden.","In a second frying pan, heat olive oil and sauté the diced pineapple, chopped red bell pepper, and chopped onion until softened.","Pour a splash of the pineapple syrup from the can into the pan, add the honey, and braise everything for 5 minutes.","Top the fried pork cutlets with the braised pineapple, bell pepper, and onion mixture and the sliced firm cheese, then warm covered for a moment until the cheese melts."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_schabowe_z_ananasem","page":"Książka kucharska/Kotlety schabowe z ananasem"},{"id":"oc-plwb-19353","title":"Kotlety w sosie musztardowym (pork cutlets in mustard cream sauce)","cuisine":"European","category":"Main","ingredients":["8 pork loin or tenderloin cutlets","100 ml broth","200 ml sour cream","5 tbsp wholegrain mustard","4 tbsp vegetable oil","4 tbsp plain flour","to taste salt","to taste pepper"],"steps":["Season the pork cutlets with salt and pepper, dredge in plain flour, and brown on both sides in well-heated oil, then pour off excess fat.","Pour 100 ml of broth over the meat and braise, covered, for about 10 minutes.","Add 200 ml of sour cream and braise everything for another 10 minutes.","Stir the wholegrain mustard into the sauce and cook briefly to combine the flavours."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_w_sosie_musztardowym","page":"Książka kucharska/Kotlety w sosie musztardowym"},{"id":"oc-plwb-22552","title":"Kotlety wieprzowe w śmietanie (pork cutlets braised with potatoes in sour cream)","cuisine":"European","category":"Main","ingredients":["4 pork cutlets","1 onion (medium)","50 g cooking fat","250 ml sour cream","500 g potatoes","1 clove garlic","1 tsp sweet paprika","1 tbsp green bell pepper (chopped)","to taste salt"],"steps":["Rinse the pork cutlets, pound with a mallet, season with salt, and brown on both sides in hot fat, then remove from the pan.","In the same fat, sauté the finely chopped onion and crushed garlic, add a splash of water, stir in the ground sweet paprika and chopped green bell pepper, and bring to a simmer.","Peel the potatoes, cut them into slices, and transfer to the pan with the onion.","Arrange the browned cutlets over the potatoes and braise, covered, until tender.","Towards the end of braising, pour in 250 ml of sour cream, shake the pan gently, then transfer the dish to a preheated oven and bake briefly."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_wieprzowe_w_%C5%9Bmietanie","page":"Książka kucharska/Kotlety wieprzowe w śmietanie"},{"id":"oc-plws-580412","title":"Kotlety z fasoli (white bean and walnut cutlets)","cuisine":"European","category":"Main","ingredients":["300 g white beans (preferably large runner beans, soaked overnight)","to taste water (cold, for soaking and boiling the beans)","1 tbsp butter (for the bean mixture, plus plenty of extra butter for frying)","5 walnuts (finely crushed)","3 eggs (2 whole for the mixture and 1 beaten for breading)","to taste plain wheat flour (for dusting the board)","to taste breadcrumbs (for generously coating the cutlets)"],"steps":["Cover the white beans with cold water in a bowl and leave to soak overnight for about 480 minutes.","Boil the beans in the same water until tender for about 75 minutes, drain off the liquid, and leave the pot covered for 5 minutes so the white beans dry thoroughly.","Pass the still-hot beans through a mincer until smooth.","Cream 1 tablespoon of butter in a small bowl until fluffy, add the finely crushed walnuts, 2 whole eggs, and the minced beans, and beat for 5 minutes until uniform.","Turn the mixture out onto a board dusted with wheat flour, shape into 10 neat cutlets, brush them with the remaining beaten egg, and coat thickly in breadcrumbs.","Heat a generous amount of butter in a skillet, fry the cutlets on both sides until golden for about 10 minutes, and remove them carefully from the skillet, as they are very delicate."],"time":600,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Kotlety_z_fasoli","page":"100 postnych i jarskich dań/Kotlety z fasoli"},{"id":"oc-plws-580421","title":"Kotlety z jaj (hard-boiled egg cutlets)","cuisine":"European","category":"Main","ingredients":["11 eggs (8 hard-boiled, 2 raw for the mixture, and 1 beaten for breading)","1 tbsp plain wheat flour (for the white roux)","1 tbsp butter (for the roux, plus extra for frying)","250 ml milk","to taste fresh dill (or chives, finely chopped)","to taste salt","to taste black pepper","to taste breadcrumbs (for thickening the mixture and breading)"],"steps":["Boil 8 eggs hard for 10 minutes, cool them in cold water, peel, and chop finely.","Cook 1 tablespoon of wheat flour with 1 tablespoon of butter over low heat for 2 minutes without browning, then pour in the milk and cook for 3 minutes, stirring, until a thick sauce forms.","Mix the chopped eggs with the thick sauce, add the chopped dill, 2 raw eggs, salt, pepper, and enough breadcrumbs for the mixture to hold together well.","Shape the mixture into cutlets, dip each one in the remaining beaten egg, and coat thoroughly in breadcrumbs.","Heat the butter in a skillet and fry the cutlets for about 10 minutes on both sides until golden brown."],"time":45,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Kotlety_z_jaj","page":"100 postnych i jarskich dań/Kotlety z jaj"},{"id":"oc-plwb-27350","title":"Kotlety z kaszy gryczanej i ziemniaków (buckwheat and potato patties)","cuisine":"European","category":"Main","ingredients":["3 tbsp cooked potatoes","6 tbsp cooked buckwheat groats","1 onion","1 egg","1 tbsp potato starch","2 tbsp plain flour (or wholemeal)","2 tbsp breadcrumbs","to taste dill (or parsley)","to taste salt","to taste pepper","to taste thyme","to taste vegetable oil (for frying)","0.5 tbsp butter (for cooking the groats)"],"steps":["Cook the buckwheat groats until fluffy in salted water with the butter for 15 minutes over low heat, then leave covered for 10–30 minutes to absorb the liquid, and measure out 6 tbsp.","Boil the potatoes until tender, mash them, and measure out 3 tbsp.","Peel the onion, chop finely, and cook until translucent in a frying pan.","Combine the cooked buckwheat groats, potatoes, and translucent onion with the egg, potato starch, plain flour, and chopped dill.","Season the mixture to taste with salt, pepper, and thyme, and mix thoroughly.","Shape into patties, coat in breadcrumbs, and fry in hot oil on both sides until golden brown."],"time":50,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_z_kaszy_gryczanej_i_ziemniak%C3%B3w","page":"Książka kucharska/Kotlety z kaszy gryczanej i ziemniaków"},{"id":"oc-plwb-16990","title":"Kotlety z kaszy jęczmiennej (Barley groats and mushroom cutlets)","cuisine":"European","category":"Main","ingredients":["250 g barley groats","30 g dried mushrooms","1 onion","100 g cooking fat","2 eggs","to taste breadcrumbs (for coating)","to taste salt","to taste pepper"],"steps":["Cook the barley groats until tender yet distinct.","Rinse the dried mushrooms, soak them for 60 minutes in lukewarm boiled water, then simmer in the same water for about 50 minutes.","Pass the cooked mushrooms, peeled onion, and half of the groats through a mincer. Add the remaining groats, crack in the eggs, season with salt and pepper, and work into a cohesive mixture.","Turn the mixture onto a pastry board dusted with breadcrumbs, shape into a thick log, and divide into 10 portions.","Form into patties, coat in breadcrumbs, and fry in hot fat until golden brown."],"time":60,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_z_kaszy_j%C4%99czmiennej","page":"Książka kucharska/Kotlety z kaszy jęczmiennej"},{"id":"oc-plwb-6121","title":"Kotlety z piersi kurczaka z cebulą (Chopped chicken breast cutlets with onion)","cuisine":"European","category":"Main","ingredients":["400 g chicken breast","1 onion","3 eggs","5 tbsp vegetable oil","5 tbsp potato starch (level tablespoons)","1 tsp all-purpose vegetable seasoning (such as Vegeta)","to taste salt","to taste pepper","to taste ground paprika"],"steps":["Finely dice the onion and chicken breasts, and separate the egg whites from the yolks.","Add the vegetable seasoning, salt, pepper, and ground paprika to the onion, then mix in the egg yolks, oil, and potato starch until thoroughly combined.","Whip the egg whites to stiff peaks, then gently fold them into the onion mixture along with the diced chicken.","Chill the mixture in the refrigerator for at least 2 hours.","Shape portions of the mixture into cutlets and fry them in a pan until golden brown."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_z_piersi_kurczaka_z_cebul%C4%85","page":"Książka kucharska/Kotlety z piersi kurczaka z cebulą"},{"id":"oc-plws-580416","title":"Kotlety z włoszczyzny (root vegetable cutlets)","cuisine":"European","category":"Main","ingredients":["2 carrots (large)","2 parsley root (large)","3 onion","1 celeriac","2 leeks","to taste salt","2 eggs","to taste breadcrumbs (for binding the mixture and coating the cutlets)","to taste butter (generous amount for frying)"],"steps":["Peel and boil the carrots, parsley root, onions, celeriac, and leeks until tender for about 35 minutes, then drain thoroughly and cool.","Pass the cooled vegetables through a mincer.","Season the minced vegetables with salt, beat in the eggs, and add enough breadcrumbs that the mixture can be easily shaped into cutlets.","Shape into cutlets and coat them on all sides in breadcrumbs.","Heat a generous amount of butter in a skillet and fry the cutlets for about 10 minutes on both sides until golden brown."],"time":65,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Kotlety_z_w%C5%82oszczyzny","page":"100 postnych i jarskich dań/Kotlety z włoszczyzny"},{"id":"oc-plws-580419","title":"Kotlety ze szpinaku (spinach and potato cutlets)","cuisine":"European","category":"Main","ingredients":["1 kg spinach (fresh)","to taste salt (for the boiling water and the mixture)","250 g potatoes","2 eggs (1 large for the mixture and 1 beaten for brushing the cutlets)","1.5 tbsp butter (0.5 tbsp for the mixture, 1 tbsp for the sauce, and extra for frying)","to taste breadcrumbs (for binding the mixture and breading)","1 tbsp sour cream (for the sauce)"],"steps":["Peel the potatoes, boil them until tender for 20 minutes, cool, and pass through a mincer.","Plunge the spinach into boiling salted water, boil for 3 minutes, drain in a sieve, squeeze dry, and chop finely or pass through a mincer.","Mix the spinach with the minced potatoes, add 1 large egg, 0.5 tablespoon of butter, and enough breadcrumbs to form a firm mixture, and knead well.","Shape into neat small cutlets, brush with the second beaten egg, and coat in breadcrumbs.","Fry the cutlets in hot butter for about 10 minutes on both sides until golden brown.","Bring the sour cream and 1 tablespoon of butter to a boil in a small saucepan for 2 minutes and serve in a sauceboat alongside the fried cutlets."],"time":60,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Kotlety_ze_szpinaku","page":"100 postnych i jarskich dań/Kotlety ze szpinaku"},{"id":"oc-plwb-4103","title":"Kołocz śląski z posypką (Silesian streusel yeast cake)","cuisine":"European","category":"Cake","ingredients":["1 kg plain flour","60 g fresh yeast","500 ml milk (approx., plus extra for brushing the dough)","200 g butter","200 g sugar (plus 1 tbsp for brushing the dough)","4 egg yolks","2 eggs","to taste lemon zest (grated)","to taste vanilla sugar","to taste salt","to taste fat (for greasing the baking pans)","500 g plain flour","250 g butter (chilled, or margarine)","250 g caster sugar","1 vanilla sugar (packet)"],"steps":["Prepare a starter from the yeast, some of the warm milk, and a little plain flour, then set aside to rise.","Beat the whole eggs and egg yolks with the sugar until light and fluffy.","Add the risen starter, beaten eggs and yolks, remaining milk, salt, grated lemon zest, vanilla sugar, and melted butter to the sifted plain flour.","Knead thoroughly into a smooth yeast dough, cover, and set aside in a warm place to rise.","Prepare the streusel: mix the plain flour with the caster sugar and packet of vanilla sugar, add the chilled butter cut into small pieces, chop and briefly work into crumbs, then chill in the refrigerator.","Grease the baking pans with fat, turn out the risen dough, and stretch it out with greased hands.","Set the dough aside in a warm place for a moment to rise again, then brush the top with the milk mixed with 1 tbsp of sugar and scatter the chilled streusel thickly over it.","Place the baking pan in the preheated oven and bake for 45–50 minutes."],"time":95,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ko%C5%82ocz_%C5%9Bl%C4%85ski_z_posypk%C4%85","page":"Książka kucharska/Kołocz śląski z posypką"},{"id":"oc-plws-39066","title":"Krem owocowy (Fruit mousse)","cuisine":"European","category":"Dessert","ingredients":["200 g fresh wild strawberries, raspberries, or apricots (orig. half a funt of ripe fruit)","200 g icing sugar or caster sugar (orig. half a funt of fine sugar)","6 g gelatine (orig. half a łut (about 6.25 g))","125 ml water (orig. half a kwaterka, for dissolving the gelatine)","6 egg whites (whole whites)","to taste almond oil (for greasing the serving bowl)"],"steps":["Press the ripe wild strawberries, raspberries, or apricots through a fine sieve.","Combine the fruit purée with the fine sugar and beat vigorously until light and fluffy.","Dissolve the gelatine in the hot water and let it cool slightly, and beat the egg whites separately to stiff peaks.","Combine the fruit mixture with the dissolved gelatine and stiff egg whites, folding gently.","Spoon the mousse into a serving bowl greased with almond oil and refrigerate for at least 3 hours until set."],"time":210,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Krem_owocowy","page":"365 obiadów za 5 złotych/Krem owocowy"},{"id":"oc-plws-39677","title":"Krem pomarańczowy (Orange mousse)","cuisine":"European","category":"Dessert","ingredients":["4 oranges (whole fruit (juice and zest; plus extra quarters for garnish))","1 lemon (large fruit, squeezed juice)","5 eggs (whole eggs, yolks and whites separated)","200 g sugar (orig. half a funt, rubbed against the orange peel)","25 g gelatine (orig. 2 łuts)","250 ml water (orig. 1 kwaterka, for dissolving the gelatine)","to taste olive oil (for greasing the mould)","to taste candied orange peel (thin strips for garnish)"],"steps":["Rub the sugar against the scalded peel of the oranges, then squeeze the juice from all four oranges and the large lemon.","Beat the egg yolks with the sugar until pale and fluffy, pour in the squeezed citrus juice, and warm over low heat, stirring constantly without letting it boil, then set aside to cool.","Dissolve the gelatine in the hot water, let it cool, pour it into the cooled egg and orange mixture, and whisk everything together until it begins to thicken.","Beat the remaining egg whites to stiff peaks, fold gently into the thickening cream, transfer to a mould greased with olive oil, and leave in a cool place until completely set (about 3 hours).","Unmould the cream onto a platter and surround with quarters of fresh orange and thin strips of candied orange peel."],"time":220,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Krem_pomara%C5%84czowy","page":"365 obiadów za 5 złotych/Krem pomarańczowy"},{"id":"oc-plws-39040","title":"Krem poziomkowy lub malinowy (Wild strawberry or raspberry Bavarian cream)","cuisine":"European","category":"Dessert","ingredients":["1000 g raspberries or wild strawberries (orig. half a garniec (2 l) of fresh berries for 2 szklanki (500 ml) of purée)","4 egg whites (whole whites)","200 g sugar (orig. half a funt of fine sugar, plus a little for dusting the mould)","500 ml whipping cream 30% (orig. half a kwarta of thick sweet cream)","200 ml calf's-foot jelly stock or dissolved gelatine (originally a scant Polish kwaterka of stock from 2–3 calf's feet (modern equivalent: about 15 g gelatine in 200 ml water))"],"steps":["Press the fresh raspberries or wild strawberries through a fine sieve to obtain 2 szklanki (500 ml) of smooth purée.","Combine the fruit purée with the egg whites and fine sugar and whisk until the mixture thickens noticeably.","Separately whip the thick whipping cream until stiff.","Fold the whipped fruit mixture together with the whipped cream and lukewarm jelly stock (or dissolved gelatine) until gently combined.","Transfer the cream to a mould rinsed with cold water and dusted with sugar, then refrigerate for about 3 hours until set."],"time":210,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Krem_poziomkowy_lub_malinowy","page":"365 obiadów za 5 złotych/Krem poziomkowy lub malinowy"},{"id":"oc-plws-39059","title":"Krem z brzoskwiń (Peach whip jelly mousse)","cuisine":"European","category":"Dessert","ingredients":["150 ml freshly squeezed peach juice (orig. 12 łuts (about 150 g))","150 g sugar (orig. 12 łuts)","to taste red food colouring or raspberry juice (a few drops for colour (orig. alkermes juice))","12.5 g gelatine (orig. 1 łut)","50 ml water (orig. 1 small glass, for dissolving the gelatine)","6 egg whites (whole whites)","to taste olive oil (for greasing the mould)"],"steps":["Beat the squeezed peach juice with the sugar for about 30 minutes (or more briefly with an electric mixer at high speed) until thick and fluffy.","Tint the mixture with a few drops of red food colouring or fruit juice.","Dissolve the gelatine in the hot water, let it cool slightly, and pour it into the peach mixture.","Beat the egg whites to very stiff peaks and fold gently into the cream.","Transfer the mousse to a mould greased with olive oil and leave in a cool place or refrigerator for 6–8 hours until completely set."],"time":465,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Krem_z_brzoskwi%C5%84","page":"365 obiadów za 5 złotych/Krem z brzoskwiń"},{"id":"oc-plwb-21743","title":"Krokiety z kapustą i grzybami (Polish croquettes with sauerkraut and mushrooms)","cuisine":"European","category":"Main","ingredients":["12 cooked crêpes (a dozen or so)","1 kg sauerkraut","1 dried mushrooms (handful)","2 tbsp butter","1 tbsp plain flour","1 egg (raw)","1 breadcrumbs (handful)","to taste vegetable oil (for frying)","to taste water (for soaking mushrooms and boiling sauerkraut)"],"steps":["Soak the dried mushrooms in water for at least 60 minutes.","Squeeze excess brine from the sauerkraut, place in a large pot, cover with water, and boil for 30 minutes.","Drain the cooking water from the sauerkraut, add the chopped soaked mushrooms and 1 tablespoon of butter, and braise for another 30 minutes.","Prepare a brown roux with the remaining 1 tablespoon of butter and the flour, then stir it into the sauerkraut towards the end of braising.","Spoon 2–3 tablespoons of filling onto each crêpe, fold two opposing edges inward, and roll up tightly.","Dredge the croquettes in beaten egg and breadcrumbs, then fry in hot oil for 2–3 minutes until crisp and golden brown."],"time":65,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krokiety_z_kapust%C4%85_i_grzybami","page":"Książka kucharska/Krokiety z kapustą i grzybami"},{"id":"oc-plwb-21744","title":"Krokiety z mięsem (Polish meat-filled crêpe croquettes)","cuisine":"European","category":"Main","ingredients":["12 cooked crêpes (a dozen or so)","750 g cooked or roasted meat","1 tbsp butter or oil","1 onion","to taste salt","to taste pepper","1 egg (raw)","1 breadcrumbs (handful)","to taste vegetable oil (for frying)"],"steps":["Pass the cooked or roasted meat through a meat grinder or mince it very finely.","Finely dice the onion, cook until translucent in the butter or oil, then add the ground meat and season the filling with salt and pepper.","Place 2–3 tablespoons of filling onto each crêpe, fold two sides inward, and roll into a cylinder.","Coat the croquettes in beaten egg and breadcrumbs, then fry in hot oil for 2–3 minutes on each side."],"time":15,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krokiety_z_mi%C4%99sem","page":"Książka kucharska/Krokiety z mięsem"},{"id":"oc-plwb-16118","title":"Krokodyle łzy (Ginger and lemon nalewka)","cuisine":"European","category":"Drink","ingredients":["100 g fresh ginger","100 g sugar","3 tbsp honey","2 lemons (thick-skinned)","750 ml vodka"],"steps":["Wash and dry the ginger, then cut it into thin slices. Scald the lemons with boiling water and slice into eighths.","Transfer the ginger and lemons to a large jar, cover with the sugar, add the honey, and pour in the vodka.","Seal the jar tightly, shake well, and leave for about 2 months, shaking the jar every few days.","After 2 months, strain the liqueur, decant into bottles, seal tightly, and age for another 30 days before serving."],"time":null,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krokodyle_%C5%82zy","page":"Książka kucharska/Krokodyle łzy"},{"id":"oc-plwb-20820","title":"Krupnik (barley soup)","cuisine":"European","category":"Soup","ingredients":["500 g beef on the bone","6 tbsp pearl barley","5.5 potatoes (5–6 potatoes)","2.5 carrots (2–3 carrots)","2 parsley root","1 celeriac (piece)","4 dried mushrooms","1 bay leaf","to taste black pepper (whole peppercorns and ground)","3 allspice (several berries)","to taste salt","1 bunch lovage, celery leaves, and leek (several herb sprigs and a piece of leek)","to taste parsley (chopped)","to taste water (for simmering the broth)"],"steps":["Place the beef on the bone into a pot of about 3 l capacity, cover with water, add the bay leaf, peppercorns, and allspice berries, and simmer, skimming off any foam that rises.","Once the stock stops foaming, add the rinsed lovage sprigs, celery leaves, leek, peeled celeriac, parsley roots, diced carrots, and dried mushrooms, and cook together.","Add the scalded (rinsed with boiling water) pearl barley and simmer over very low heat for 30 minutes.","Add the peeled and diced potatoes and simmer until tender, then discard the spent herb sprigs.","Season the krupnik to taste with salt and pepper and stir in the chopped fresh parsley."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krupnik","page":"Książka kucharska/Krupnik"},{"id":"oc-plws-39019","title":"Krupnik (Polish barley soup)","cuisine":"European","category":"Soup","ingredients":["500 g beef bones and trimmings (for a light broth)","2 l water (about 1.5 l for the broth and 0.5 l for cooking the groats)","200 g barley groats or pearl barley (originally 1 Polish kwaterka (250 ml) of barley, spelt, or pearl barley groats)","30 g butter (orig. a piece of butter)","to taste parsley leaves (finely chopped)","to taste salt"],"steps":["Simmer a light, clear broth from the beef bones and trimmings in salted water, then strain.","In a separate pot, cook the barley groats or pearl barley until thick and well softened.","Add the butter to the hot groats and beat thoroughly with a spoon into a smooth, creamy mass.","Thin the buttered groats with the hot beef broth, add the finely chopped parsley leaves, bring to a boil together, and serve."],"time":75,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Krupnik","page":"365 obiadów za 5 złotych/Krupnik"},{"id":"oc-plwb-56118","title":"Kruszonka (Streusel crumb topping)","cuisine":"European","category":"Other","ingredients":["300 g plain flour","150 g sugar","150 g butter","1 pinch salt"],"steps":["Place the plain flour, sugar, and a pinch of salt into a bowl, then add the butter.","Rub the ingredients together with your hands (or initially using the dough hook attachment of a mixer, then finishing by hand) until evenly combined into coarse crumbs.","Scatter the streusel over cake batter before baking, or spread onto a parchment-lined baking sheet and bake separately in an oven preheated to 200 °C for about 20 minutes until golden brown."],"time":30,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kruszonka","page":"Książka kucharska/Kruszonka"},{"id":"oc-plwb-10521","title":"Krówki (Polish milk fudge)","cuisine":"European","category":"Dessert","ingredients":["500 ml milk","375 ml sugar","1 tbsp butter (plus extra for greasing the dish)"],"steps":["Combine the milk and sugar in a heavy-bottomed pot and bring to a boil.","Reduce the heat and simmer slowly, stirring regularly and scraping down the sides of the pot, until the mixture turns golden and a drop placed on a plate sets quickly.","Remove the pot from the heat, add the butter, and beat the mixture vigorously with a wooden spoon.","Pour the mixture into a shallow greased dish, wait a few minutes, and slice into bars using a knife dipped in cold water."],"time":null,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kr%C3%B3wki","page":"Książka kucharska/Krówki"},{"id":"oc-plwb-21753","title":"Kulebiak z kwaśną kapustą (Sauerkraut and fish coulibiac)","cuisine":"European","category":"Main","ingredients":["1 yeast dough (portion of dough)","750 ml sauerkraut","1 onion","750 g fish","125 g butter","to taste salt","to taste pepper"],"steps":["Rinse the sauerkraut, squeeze dry, and chop finely.","Finely chop the onion, sauté in the butter, add the sauerkraut, season with pepper, and braise together until the cabbage is tender.","Debone the fish, cut into small pieces, season with salt, pan-fry separately, and fold into the braised sauerkraut.","Roll out the yeast dough to a thickness of about 1 cm, spread over the sauerkraut and fish filling, fold the dough over, and seal the edges securely.","Bake the coulibiac in a well-heated oven for about 50 minutes."],"time":75,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kulebiak_z_kwa%C5%9Bn%C4%85_kapust%C4%85","page":"Książka kucharska/Kulebiak z kwaśną kapustą"},{"id":"oc-plwb-21749","title":"Kulebiak z mięsem (Meat coulibiac)","cuisine":"European","category":"Main","ingredients":["1 yeast or rich butter pastry (portion of dough)","1.25 kg roasted or boiled meat (such as veal, pork, or beef) (1–1.5 kg)","1 onion","125 g butter","4.5 eggs (4–5 eggs)","2.5 tbsp broth (2–3 tbsp)","to taste salt","to taste pepper"],"steps":["Chop the onion and cook until translucent in the butter.","Pass the meat through a meat grinder, add to the onion, pour in the broth, season with salt and pepper, and braise for several minutes.","Cool the meat filling and pass it through the grinder a second time or mince it very finely.","Hard-boil the eggs, cool, peel, and dice finely.","Roll out the pastry to a thickness of about 1 cm, spread a layer of meat over it, cover with a layer of chopped eggs, and finish with another layer of meat.","Fold the pastry over the filling, seal the edges securely, and bake in a well-heated oven for about 50 minutes."],"time":60,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kulebiak_z_mi%C4%99sem","page":"Książka kucharska/Kulebiak z mięsem"},{"id":"oc-plwb-21750","title":"Kulebiak z rybą (Fish coulibiac)","cuisine":"European","category":"Main","ingredients":["1 yeast dough (portion of dough)","1.25 kg fish (1–1.5 kg)","1 onion (optional)","1.5 tbsp butter (1–2 tbsp)","1 sprats or sardines in oil (can, optional)","100 g rice (1 bag)","to taste eggs (hard-boiled; listed in the preparation instructions)","to taste salt","to taste pepper"],"steps":["Chop the onion and sauté in the butter. Fry the fish, let it cool, remove all bones, and finely chop together with the onion.","Hard-boil the eggs and dice finely, and cook the rice until fluffy.","Combine the chopped fish with the diced eggs and rice, and season the filling with salt and pepper.","Roll out the yeast dough to a thickness of about 1 cm, spread over the fish filling, and top with sprats or sardines if using.","Enclose the filling in the dough, seal the edges securely, and bake in a well-heated oven for about 50 minutes."],"time":65,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kulebiak_z_ryb%C4%85","page":"Książka kucharska/Kulebiak z rybą"},{"id":"oc-plwb-21751","title":"Kulebiak ze słodką kapustą (Cabbage and egg coulibiac)","cuisine":"European","category":"Main","ingredients":["1 yeast or puff pastry (portion of dough)","1 white cabbage (head)","5 eggs","1.5 onion (1–2 onions)","1 tbsp butter","to taste salt","to taste pepper","to taste water (for boiling cabbage)"],"steps":["Cut the head of cabbage into quarters and boil in salted water until tender.","Drain and squeeze excess liquid from the cabbage, remove the core, and finely chop the leaves.","Hard-boil the eggs, cool, peel, and dice finely. Finely chop the onion and sauté in the butter.","Combine the chopped cabbage with the diced eggs and buttered onions, then season the filling with salt and pepper.","Roll out the dough to a thickness of about 1 cm, spread the cabbage filling over, fold the dough over, and seal the edges securely.","Bake the coulibiac in a well-heated oven for about 50 minutes."],"time":70,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kulebiak_ze_s%C5%82odk%C4%85_kapust%C4%85","page":"Książka kucharska/Kulebiak ze słodką kapustą"},{"id":"oc-plws-550085","title":"Kurczaki pieczone z beszamelem (Roast chickens glazed with béchamel)","cuisine":"European","category":"Main","ingredients":["2 chicken (large, meaty, unstuffed)","15 ml wheat flour (orig. a tablespoon)","15 ml butter (orig. a tablespoon)","250 ml sweet cream (orig. a szklanka)","1 egg (large)","to taste salt"],"steps":["Roast the chickens in the oven until golden brown and tender.","Cook the flour in the butter without letting it brown.","Whisk the sweet cream into the roux.","Bring the sauce to a boil.","Set the sauce aside to cool slightly.","Whisk the cooled sauce with the egg and salt.","Coat the chickens with a very thin layer of the sauce, repeating the basting two or three times.","Bake the chickens in the oven until the sauce forms a golden crust.","Carve the chickens carefully into pieces, keeping the sauce crust intact.","Serve immediately while hot."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Dr%C3%B3b%2C_sposoby_przyrz%C4%85dzania/Kurcz%C4%99ta_pieczone_z_beszamelem","page":"Drób, sposoby przyrządzania/Kurczęta pieczone z beszamelem"},{"id":"oc-plwb-30832","title":"Kurki duszone w śmietanie (Chanterelles braised in sour cream)","cuisine":"European","category":"Sauce","ingredients":["400 g chanterelles","0.5 bunch fresh dill","1 onion (large)","3 tbsp butter","250 g sour cream 12%","to taste salt","to taste pepper"],"steps":["Slice the onion and cook until translucent in the melted butter.","Add the washed and cleaned chanterelles, stir in half of the finely chopped dill as they cook, and braise over medium heat for about 20 minutes until excess moisture has evaporated.","Remove the pan from the heat, season the chanterelles with salt and pepper, stir in the sour cream and remaining dill, and warm through briefly before serving."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurki_duszone_w_%C5%9Bmietanie","page":"Książka kucharska/Kurki duszone w śmietanie"},{"id":"oc-plws-44958","title":"Kuropatwy duszone (Braised partridges in sour cream)","cuisine":"European","category":"Main","ingredients":["3 partridges (whole birds, cleaned and larded with pork fatback)","50 g butter (for braising)","to taste juniper berries (several berries)","2 tbsp sour cream 18% (sour)","1 lemon (whole fruit, squeezed juice)","1 tbsp breadcrumbs (for sprinkling before serving)","to taste salt"],"steps":["Roast the cleaned and larded partridges halfway on a spit or in an oven preheated to 200 °C for about 15–20 minutes, then cut them in half.","Transfer the partridge halves to a casserole with the melted butter and a few juniper berries, and pour in the pan drippings from roasting.","Add two tablespoons of sour cream and the juice squeezed from the whole lemon, cover, and braise over low heat for about 20 minutes until the sauce thickens.","Remove the juniper berries, arrange the partridges on a platter, spoon the sauce over them, and sprinkle with browned breadcrumbs."],"time":60,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kuropatwy_duszone","page":"365 obiadów za 5 złotych/Kuropatwy duszone"},{"id":"oc-plwb-7892","title":"Kutia (Christmas wheat pudding)","cuisine":"European","category":"Dessert","ingredients":["250 ml hulled wheat berries","250 ml dry poppy seeds","250 ml icing sugar","4 tbsp runny honey","50 ml brandy or wine brandy","100 g sultana raisins","3 tbsp chopped nuts (heaped tablespoons)","3 tbsp candied orange peel (heaped tablespoons, candied in syrup)","250 ml whipping cream","to taste dried fruit (apricots, dates, prunes) (for garnish)","to taste water (for soaking and cooking)"],"steps":["Rinse the hulled wheat berries, cover with lukewarm water, and leave to soak overnight.","The next day, drain the wheat, cover with fresh water, and boil until tender, changing the cooking water three times, then drain thoroughly in a sieve.","Rinse the poppy seeds, pour over 500 ml of boiling water, simmer over low heat for 20 minutes, and leave to cool.","Pour the brandy over the raisins and leave them to soak.","Drain the cooled poppy seeds in a fine sieve and pass them twice through a mincer, alternating with the icing sugar during the second grind.","Combine the ground poppy seeds with honey, the drained raisins (reserving the soaking liquid), candied orange peel, cream, chopped nuts, and cooked wheat berries.","Shape the mixture into a mound on a serving dish and refrigerate until chilled.","Before serving, arrange the sliced dried fruit around the edges and drizzle with the reserved soaking alcohol."],"time":null,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kutia","page":"Książka kucharska/Kutia"},{"id":"oc-plwb-2776","title":"Kwaśnica (Polish highland sauerkraut soup)","cuisine":"European","category":"Soup","ingredients":["500 g fatty meat (mutton or pork: jowl, collar, shoulder, or ribs) (can be smoked)","300 g sauerkraut","to taste dried or fresh mushrooms","4 allspice (3–5 berries)","1 bay leaf","2 clove garlic","to taste sauerkraut juice","to taste potatoes (boiled separately, for serving)","to taste water (for cooking)"],"steps":["If using dried mushrooms, soak them beforehand in water until softened and reserve the soaking liquid.","Rinse the meat and place it in a pot together with the bay leaf, allspice berries, and mushrooms (along with their soaking liquid).","Pour in enough water to just cover the ingredients and simmer over medium heat until the meat is tender.","Add the sauerkraut without squeezing out its liquid, then add sauerkraut juice until the soup is distinctly sour.","Simmer the soup gently until the sauerkraut is tender, adding the garlic towards the end of cooking.","Boil the potatoes separately. Arrange a portion of the simmered meat and boiled potatoes in bowls and ladle over the hot kwaśnica."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kwa%C5%9Bnica","page":"Książka kucharska/Kwaśnica"},{"id":"oc-plwb-24918","title":"Kwaśnica Żywiecka (Żywiec-style sauerkraut soup)","cuisine":"European","category":"Soup","ingredients":["800 g bone-in pork loin","700 g sauerkraut","2 l water","80 g onion","50 g dried mushrooms","250 g soup greens","1 clove garlic","1 tsp salt","1 pinch black pepper"],"steps":["Simmer the bone-in pork loin and soup greens in 2 l of lightly salted water until the meat is tender, then remove the pork loin, debone, and divide into portions.","In a separate pot, cook the sauerkraut with the finely diced onion until tender.","Cook the dried mushrooms separately and slice them into strips.","Combine the meat-vegetable broth with the cooked sauerkraut, mushrooms, and pork loin portions.","Add the garlic crushed through a garlic press, season with salt and pepper, and bring to a boil."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kwa%C5%9Bnica_%C5%BBywiecka","page":"Książka kucharska/Kwaśnica Żywiecka"},{"id":"oc-plws-545139","title":"Large Yellow Plum Preserve","cuisine":"European","category":"Preserve","ingredients":["500 g large yellow plums (orig. half a kilogram)","1 kg sugar (orig. one kilogram)","to taste water (for scalding, cooling, and the syrup; amount not specified)","to taste ice (for the cooling bath; amount not specified)"],"steps":["Prick each plum with a wooden skewer and place into cold water.","Scald the plums with boiling water until tender.","Transfer the plums to cold water with ice.","Prepare a syrup from the sugar and water.","Pour the syrup over the plums for four days, using an increasingly hotter syrup each time.","Leave the fruit in the syrup between pourings until the next day, about 1440 minutes.","On the fifth day, simmer the plums in the syrup slowly, with pauses, until the syrup thickens, taking care that the fruit do not fall apart."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/%C5%9Aliwki_%C5%BC%C3%B3%C5%82te_du%C5%BCe","page":"Doświadczone sekreta smażenia konfitur i soków/Śliwki żółte duże"},{"id":"oc-plwb-17771","title":"Layered ladyfinger pudding cake","cuisine":"European","category":"Dessert","ingredients":["240 g ladyfinger biscuits","80 g sweet-cream pudding powder (2 packets (or vanilla pudding))","80 g chocolate pudding powder","1.5 l milk","2 kiwi fruit (peeled and diced)","2 tbsp gelatin powder","8 tbsp sugar","80 ml cold water","1 tbsp vanillin sugar"],"steps":["Line a deep round cake tin with aluminum foil and line the bottom and sides with ladyfinger biscuits.","Soak the gelatin in cold water, then warm gently until completely dissolved.","Cook the chocolate pudding with half the milk and half the sugar, blend with half the dissolved gelatin, pour over the biscuit base, and top with a radial layer of ladyfingers.","Cook the sweet-cream pudding with the remaining milk, sugar, and the vanillin sugar.","Stir the remaining gelatin and the diced kiwi into the warm cream pudding, spread over the ladyfingers, and chill in the refrigerator until set."],"time":45,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Deser_budyniowy","page":"Książka kucharska/Deser budyniowy"},{"id":"oc-plwb-18847","title":"Legumina czekoladowa (chilled chocolate pudding)","cuisine":"European","category":"Dessert","ingredients":["250 g dark chocolate","3 tbsp brewed coffee (very strong)","5 egg","125 g sugar","6 tsp gelatin","200 ml whipped cream","50 ml cognac","to taste powdered sugar","1 orange (juice and grated zest)"],"steps":["Grate 100 g of dark chocolate into curls and set aside. Break the remaining 150 g of chocolate into pieces, melt over a water bath, and combine with the strong coffee, orange juice, and finely grated orange zest.","Whisk the eggs with sugar over a water bath for about 10 minutes, then set aside to cool.","Soak the gelatin in a small amount of lukewarm water to bloom, then fold it together with 200 ml of whipped cream into the chocolate mixture.","Fold the chocolate mixture into the cooled egg mixture and season with 50 ml of cognac.","Collar a soufflé dish with a strip of baking parchment extending above the rim, pour in the mixture, and refrigerate for 3 hours.","Before serving, remove the parchment collar and dust the top with the reserved chocolate curls mixed with powdered sugar."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Legumina_czekoladowa","page":"Książka kucharska/Legumina czekoladowa"},{"id":"oc-plws-40189","title":"Legumina migdałowa z ryżu (Almond and rice blancmange)","cuisine":"European","category":"Dessert","ingredients":["200 g white rice or rice flour (orig. half a funt of rice pounded into flour and sifted)","200 g sweet almonds (orig. half a funt)","200 g sugar (orig. half a funt of fine sugar)","1 l whole milk (orig. 1 kwarta of unskimmed milk)","1 pinch salt","to taste olive oil (for greasing the mould)","to taste raspberry syrup (for pouring over when serving)"],"steps":["Grind the rice into fine flour and sift through a fine mesh sieve (or use ready-made rice flour).","Blanch the almonds in boiling water, slip off their skins, and grind finely or pound in a mortar, then mix with the rice flour and fine sugar.","Bring the milk to a boil in a saucepan with a pinch of salt and add the rice-and-almond mixture spoonful by spoonful, whisking briskly the whole time.","Cook over low heat, stirring constantly, until the mixture becomes very thick and glossy.","Spoon the hot pudding into a deep mould or bowl greased with olive oil and refrigerate for about 3 hours until set; before serving, unmould onto a platter and pour raspberry syrup over the top."],"time":220,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Legumina_migda%C5%82owa_z_ry%C5%BCu","page":"365 obiadów za 5 złotych/Legumina migdałowa z ryżu"},{"id":"oc-plws-39693","title":"Legumina parzona (Steamed choux pastry pudding)","cuisine":"European","category":"Dessert","ingredients":["250 ml milk (orig. 1 kwaterka)","100 g clarified butter (orig. 8 łuts)","150 g potato starch or plain wheat flour (originally 1 Polish kwaterka (250 ml) of potato starch or wheat flour)","8 eggs (whole eggs, yolks and whites separated)","1 tbsp sugar (large tablespoon)","1 pinch salt","1 tbsp butter (for greasing the mould)","1 tbsp breadcrumbs (for coating the mould)","1.5 l water (boiling water for the water bath)"],"steps":["Bring the milk and clarified butter to a boil in a saucepan.","Gradually add the potato starch or wheat flour, stirring vigorously with a spoon over low heat until the paste thickens and pulls away from the sides of the pan, then set aside to cool.","Beat the cooled paste, adding the egg yolks one at a time, along with a large tablespoon of sugar and a pinch of salt.","Beat the egg whites to stiff peaks and fold them gently into the egg batter.","Transfer the batter to a mould greased with butter and coated with breadcrumbs, set the mould in a wide pot of boiling water, and cook in the water bath over medium heat for 60 minutes, replenishing the boiling water as needed."],"time":95,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Legumina_parzona","page":"365 obiadów za 5 złotych/Legumina parzona"},{"id":"oc-plws-39687","title":"Legumina z cytryny lub pomarańczy (Whole lemon or orange soufflé pudding)","cuisine":"European","category":"Dessert","ingredients":["1 lemon or orange (large fruit, scrubbed and grated whole without seeds)","200 g sugar (orig. 1 full glass)","10.5 eggs (orig. 9–12 eggs, yolks and whites separated)","1 tsp potato starch or plain wheat flour (level teaspoon)","1 tbsp butter (for greasing the baking dish)"],"steps":["Wash and scald a large lemon or orange, then grate the whole fruit on a fine grater, carefully discarding all seeds.","Transfer the grated fruit to a bowl, add the sugar, and beat for about 30 minutes (or whisk with an electric mixer), adding the egg yolks one by one along with a level teaspoon of flour until the mixture is as thick as cream.","Beat the egg whites to stiff peaks and fold them carefully into the citrus mixture with a spoon.","Spoon the mixture into a buttered ovenproof serving dish and bake in an oven preheated to 170 °C for 15 minutes, taking care not to overbake the soufflé."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Legumina_z_cytryny_lub_pomara%C5%84czy","page":"365 obiadów za 5 złotych/Legumina z cytryny lub pomarańczy"},{"id":"oc-plws-39694","title":"Legumina z jabłek w papilotach (Baked apples wrapped in crêpes)","cuisine":"European","category":"Dessert","ingredients":["4 eggs (whole eggs, yolks and stiffly beaten whites separated, for the crêpe batter)","150 g plain wheat flour (originally 1 Polish kwaterka (250 ml), for the crêpe batter)","500 ml milk (orig. half a kwarta, for the crêpe batter)","2 tbsp clarified butter (1 teaspoon for the batter, the rest for frying the crêpes and drizzling on top)","10 apples (small fruit, such as Papierówka or Reinette apples)","1 l water (boiling water for scalding the apples)","150 g fruit preserves or jam (for stuffing the apples (or raisins with sugar and cinnamon))","1 tbsp butter (for greasing the baking dish)","1 tbsp breadcrumbs (for coating the baking dish)","to taste sugar (for sprinkling before serving)","to taste ground cinnamon (for sprinkling before serving)"],"steps":["Whisk the egg yolks with the flour, milk, and a teaspoon of melted butter, gently fold in the stiffly beaten egg whites, then fry thin crêpes in clarified butter and let cool.","Peel and core the apples, plunge the whole fruit into boiling water for at most 5 minutes (without boiling them), and drain on a sieve.","Fill the hollowed apple centres with fruit preserves or jam and wrap each apple in a separate crêpe.","Grease an ovenproof casserole or baking dish with butter, coat with breadcrumbs, and line the bottom with crêpes.","Arrange the crêpe-wrapped apples in the dish, fill the gaps with the remaining crêpes, and drizzle the top with a full tablespoon of clarified butter.","Bake in an oven preheated to 190 °C for about 60 minutes, then turn out onto a platter and sprinkle with sugar mixed with cinnamon."],"time":105,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Legumina_z_jab%C5%82ek_w_papilotach","page":"365 obiadów za 5 złotych/Legumina z jabłek w papilotach"},{"id":"oc-plws-42464","title":"Legumina z jabłek, konfitur i marengów (Apple, preserve and meringue tart)","cuisine":"European","category":"Dessert","ingredients":["160 g plain wheat flour (originally 1 full Polish kwaterka (250 ml), for the pastry)","100 g butter (orig. a quarter funt, for the pastry)","2 tbsp sugar (for the pastry)","16 apples (10 apples for the marmalade and about 6 apples poached whole)","500 ml water (for poaching the whole apples)","200 g fruit preserves (generous amount, for the marmalade layer and for stuffing the whole apples)","5 egg whites (whole whites, for the meringue)","250 g icing sugar (originally half a Polish funt (200 g) for the meringue, plus sugar for the apple marmalade and for sprinkling on top)","30 g almonds (chopped, for sprinkling over the meringue)"],"steps":["Knead a shortcrust pastry from the wheat flour, butter, and two tablespoons of sugar, line an ovenproof platter or tart tin with it, and blind-bake until golden in an oven preheated to 190 °C (about 20 minutes).","Prepare a thick apple marmalade by stewing 10 peeled apples with a little sugar. Peel and core the remaining apples, parboil them whole, and stuff them with fruit preserves.","Spread the apple marmalade over the pre-baked crust, spoon a layer of fruit preserves on top, and arrange the whole stuffed apples over it.","Beat 5 egg whites to stiff peaks, fold in 200 g of fine sugar, and spread the meringue over the fruit.","Sprinkle the top with sugar and chopped almonds and bake in an oven preheated to 160 °C for 15 minutes, taking care not to let the meringue burn."],"time":90,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Legumina_z_jab%C5%82ek%2C_konfitur_i_mareng%C3%B3w","page":"365 obiadów za 5 złotych/Legumina z jabłek, konfitur i marengów"},{"id":"oc-plws-39665","title":"Legumina z kwaśnej śmietany (Sour cream soufflé pudding)","cuisine":"European","category":"Dessert","ingredients":["500 ml sour cream 18% (orig. half a kwarta of good sour cream)","1 tbsp plain wheat flour (heaped tablespoon)","6 eggs (whole eggs, yolks and whites separated)","2 tbsp sugar (rubbed beforehand against a lemon peel)","1 lemon (whole fruit (peel for rubbing the sugar plus 1 teaspoon of juice))","1 pinch salt","1 tbsp clarified butter (for greasing the baking dish)"],"steps":["Slowly beat the sour cream with a heaped tablespoon of wheat flour and the six egg yolks until smooth and lump-free.","Add two tablespoons of lemon-rubbed sugar, a teaspoon of lemon juice, and a pinch of salt, and mix thoroughly.","Just before placing in the oven, beat the egg whites to stiff peaks and fold them gradually and gently into the sour cream mixture.","Pour the batter into a baking dish greased with clarified butter and place immediately in an oven preheated to 180 °C for about 20 minutes."],"time":35,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Legumina_z_kwa%C5%9Bn%C3%A9j_%C5%9Bmietany","page":"365 obiadów za 5 złotych/Legumina z kwaśnéj śmietany"},{"id":"oc-plws-39720","title":"Legumina z poziomek (Wild strawberry soufflé pudding)","cuisine":"European","category":"Dessert","ingredients":["450 g wild strawberries (orig. 3 glasses (750 ml))","125 ml dry white wine (orig. half a glass of French wine)","2 tbsp butter (1 tablespoon for cooking the wild strawberries and 1 tablespoon for greasing the mould)","10 eggs (whole eggs, yolks and whites separated)","400 g sugar (orig. 2 mugs)","1 tbsp potato starch (heaped tablespoon)"],"steps":["Cook the wild strawberries gently with half a glass of white wine and a tablespoon of butter for about 5 minutes, then press through a sieve and let cool.","Beat the ten egg yolks with the sugar until pale and fluffy.","Beat the egg whites to stiff peaks and add them, together with a heaped tablespoon of potato starch and the cooled wild strawberry purée, to the beaten yolks.","Fold everything together gently, transfer to a buttered mould, and bake in an oven preheated to 180 °C for 20 minutes."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Legumina_z_poziomek","page":"365 obiadów za 5 złotych/Legumina z poziomek"},{"id":"oc-plws-39726","title":"Lemon jelly","cuisine":"European","category":"Dessert","ingredients":["400 g sugar (orig. 1 funt)","750 ml water (orig. 500 ml for the syrup + 250 ml gelatine solution)","4 lemons (3 for juice and 1 small sliced and seeded)","25 g gelatine or isinglass (orig. 2 łuty)"],"steps":["Pour 500 ml of water over the sugar, bring to a simmer over low heat, and skim off the foam.","Squeeze the clear juice of 3 lemons into the syrup and add the fourth small lemon, sliced with the seeds removed; simmer over low heat for about 15 minutes until no more foam rises.","Dissolve the gelatine in the remaining 250 ml of warm water (or simmer the isinglass down to that volume) and combine with the hot lemon syrup.","Strain the mixture through a cloth or napkin, pour into a mould, and leave in a cool place for about 4 hours (240 minutes) until completely set."],"time":280,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Galareta_cytrynowa","page":"365 obiadów za 5 złotych/Galareta cytrynowa"},{"id":"oc-plws-550037","title":"Lemon liqueur","cuisine":"European","category":"Drink","ingredients":["2 lemon (fresh; the yellow peel pared thinly and lightly dried at room temperature)","0.5 vanilla pod (orig. half a vanilla pod)","1.5 l spirit (orig. 1 litre for macerating the peel, plus 0.5 litre of plain spirit added at the end)","1 kg sugar (orig. 1 kilogram of crushed sugar)","500 ml water (orig. half a litre of cold boiled water)"],"steps":["Pare the yellow peel thinly from 2 fresh lemons and immediately leave it to dry slightly at room temperature to remove the sharp bitterness.","Put the lightly dried lemon peel and half a vanilla pod into a demijohn with 1 l of the best spirit, cover the opening with a clean cloth tied securely in place, and leave in the shade for 4 days.","After 4 days, cook a syrup from 1 kg of crushed sugar and 500 ml of cold boiled water. Skim it carefully after a single boil, and cool it completely.","Slowly pour the lemon spirit strained through muslin and an extra 500 ml of plain spirit into the cold syrup, stirring constantly and keeping the vessel partly covered. Then bottle the clear liqueur."],"time":10,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_cytrynowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier cytrynowy"},{"id":"oc-plws-552218","title":"Lemon or orange ice","cuisine":"European","category":"Dessert","ingredients":["500 g sugar (in pieces, rubbed on the lemon peel, orig. half a kilogram)","1 l water (orig. 1 litre)","6 lemons (peel for rubbing the sugar, and the squeezed juice)","1 tsp rum (optional, in the cooled syrup)"],"steps":["Rub pieces of sugar on the yellow peel of six washed lemons, cover them with 1 litre of water, bring a thick syrup to the boil, and leave it to cool completely.","Squeeze the juice of all six lemons into the cold syrup (and, if you like, a teaspoon of rum), mix well, and strain through a fine sieve.","Pour the mixture into an ice-cream maker and freeze it until smooth (about 2–3 hours)."],"time":190,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_cytrynowe_lub_pomara%C5%84czowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody cytrynowe lub pomarańczowe"},{"id":"oc-plws-544010","title":"Lemon Preserves","cuisine":"European","category":"Preserve","ingredients":["5 lemons (the source specifies 5–6 pieces; 5 was used)","1500 g sugar (divide into three 500 g portions; orig. one and a half kilograms)","to taste water (for soaking, boiling, and the syrup; amounts not specified)"],"steps":["Soak the lemons in boiled, cold water for 14400 minutes, changing the water every 1440 minutes.","Prick the fruit densely with a wooden skewer.","Arrange the lemons side by side in a pot and cover with fresh, boiled, cooled water.","Simmer over low heat for about 300 minutes, until the fruit is completely tender.","Transfer the tender lemons to a platter lined with a cloth.","Leave to cool completely, if necessary until the next day, about 1440 minutes.","Cut the fruit into slices or quarters and remove the seeds.","Boil a light syrup from the first 500 g of sugar and water.","Cool the syrup before pouring it over the lemons.","Leave the lemons in the syrup until the next day, about 1440 minutes.","Pour off the syrup, add the second 500 g of sugar, and bring to a boil, skimming off the foam.","Pour the lukewarm syrup over the lemons and leave until the third day, about 1440 minutes.","Pour off the syrup, add the final 500 g of sugar, and bring to a boil, skimming off the foam.","Pour the slightly warmer, but not hot, syrup over the lemons and leave for 7200 minutes.","If the syrup becomes watery, boil it again until thickened, cool it, and pour it back over the fruit; after a few hours, transfer into jars, seal, and store in a cool, dry place."],"time":300,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Cytryny","page":"Doświadczone sekreta smażenia konfitur i soków/Cytryny"},{"id":"oc-plws-544012","title":"Lemon Preserves Steeped in Cold Syrup","cuisine":"European","category":"Preserve","ingredients":["500 g lemons (weight after boiling, slicing, and removing seeds; orig. half a kilogram)","1000 g sugar (added gradually over four days; orig. one kilogram)","to taste water (for soaking, boiling, rinsing, and the syrup; amounts not specified)"],"steps":["Soak the lemons in water for 7200 minutes, changing the water every 1440 minutes.","Cover the fruit with cold, boiled water in a pot.","Boil until tender enough to be easily pierced.","Leave the lemons in the water to cool slowly.","Cut the fruit into slices.","Remove the seeds.","Weigh out 500 g of the prepared lemons.","Rinse the slices with water.","Drain the lemons and place them in a jar.","Boil a light syrup from part of the sugar and water, reserving the rest of the sugar for the following days.","Cool the syrup completely and pour it over the lemons.","Leave until the next day, about 1440 minutes.","On the second day, pour off the syrup, add part of the remaining sugar, and bring to a boil again.","Cool the syrup before pouring it over the lemons again.","Repeat pouring off, adding sugar, boiling, and cooling the syrup on the third and fourth days, waiting about 1440 minutes between steepings and using 1000 g of sugar in total."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Cytryny_troch%C4%99_odmiennie","page":"Doświadczone sekreta smażenia konfitur i soków/Cytryny trochę odmiennie"},{"id":"oc-plwb-16348","title":"Leniwe pierogi (farmer's cheese dumplings)","cuisine":"European","category":"Main","ingredients":["400 g farmer's cheese (well drained, not sour)","4 egg","150 g wheat flour (heaped)","50 g butter","2 tbsp breadcrumbs","to taste salt"],"steps":["Bring 2–3 liters of lightly salted water to a boil in a wide pot.","Press the farmer's cheese through a ricer or sieve into a deep bowl, crack in the eggs, add a small knob of butter, a pinch of salt, and two-thirds of the prepared flour, then mix into a light, fluffy dough.","Turn the dough onto a pastry board dusted with the remaining flour, shape into rolls about 2 cm in diameter, flatten them slightly, and cut diagonally into pieces.","Drop the dumplings in batches into the boiling water and cook for 1–2 minutes after they float to the surface, stirring gently.","Remove the cooked dumplings with a slotted spoon onto a platter.","Brown the breadcrumbs in a dry frying pan, remove from the heat, add the remaining butter, stir until melted, and pour over the leniwe dumplings."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Leniwe_pierogi","page":"Książka kucharska/Leniwe pierogi"},{"id":"oc-plws-39036","title":"Lenten almond milk blancmange (Galareta migdałowa postna)","cuisine":"European","category":"Dessert","ingredients":["300 g sweet almonds (orig. 3/4 funt)","12 bitter almonds (orig. 12 pieces as in the base recipe)","1.25 l boiling water (orig. 1 kwarta (1 l) + 1 kwaterka (250 ml))","300 g sugar (orig. 3/4 funt)","37.5 g isinglass or gelatine (orig. 3 łuty boiled down to 250 ml)","250 ml water for dissolving the isinglass (orig. 1 kwaterka)"],"steps":["Blanch the sweet and bitter almonds in boiling water, slip off the skins, and pound in a mortar or grind to a smooth paste.","Pour 1 l of boiling water over the pounded almonds, let steep covered for 60 minutes, then wring firmly through a dense cloth.","Pound the almond pressings a second time, pour in the remaining 250 ml of hot water, and wring through the cloth again to extract a rich almond milk.","Simmer the isinglass or gelatine in 250 ml of water until dissolved and strain.","Stir the sugar and cooled isinglass or gelatine solution into the almond milk, whisk briskly until slightly thickened, pour into a mould, and set in a cool place for about 4 hours (240 minutes) until firm."],"time":350,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Galareta_migda%C5%82owa_postna","page":"365 obiadów za 5 złotych/Galareta migdałowa postna"},{"id":"oc-plws-1081067","title":"Lenten Boiled Obwarzanki Rings (Obarzaneczki postne)","cuisine":"European","category":"Bread","ingredients":["2 l wheat flour (orig. half a garniec flour (approx. 1.3 kg, plus a little for dusting the baking sheets))","50 g fresh yeast (orig. 4 łuty)","500 ml water (lukewarm, for kneading the dough (plus boiling water for poaching the rings))","2 tsp salt (for the dough and for sprinkling)","2 tbsp poppy seeds (or nigella seeds or coarse salt, for sprinkling)"],"steps":["Knead a fairly firm dough (like noodle dough) from 2 liters of wheat flour, 50 g of fresh yeast dissolved in lukewarm water, and salt.","Shape the dough into round or double-twisted oblong obwarzanki rings and set aside in a warm place for 30 minutes to rise slightly.","Drop the risen rings in batches into rapidly boiling water in a wide pot and poach for no longer than 2 minutes.","Lift the obwarzanki out with a slotted spoon, sprinkle with poppy seeds, coarse salt, or nigella seeds, arrange on floured baking sheets, and bake in a hot oven (210 °C) for about 15–20 minutes until lightly browned."],"time":75,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Obarzaneczki_postne","page":"Baby, placki i mazurki/Obarzaneczki postne"},{"id":"oc-plwb-21460","title":"Likier jajeczny na mleku (milk egg liqueur)","cuisine":"European","category":"Drink","ingredients":["12 egg yolk","850 g sugar (800–900 g)","1 l milk","500 ml rectified spirit"],"steps":["Boil 1 l of milk and set aside to cool until lukewarm.","Thoroughly whisk the egg yolks with sugar into a pale, fluffy cream.","Without stopping whisking, gradually pour in the lukewarm milk until the ingredients are thoroughly combined.","Slowly pour in 500 ml of rectified spirit while stirring vigorously for a while, then pour the liqueur into bottles and cork tightly."],"time":30,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Likier_jajeczny_na_mleku","page":"Książka kucharska/Likier jajeczny na mleku"},{"id":"oc-plwb-19214","title":"Likier kresowy (Borderlands linden flower liqueur)","cuisine":"European","category":"Drink","ingredients":["3 fresh linden blossoms (handfuls)","1.5 l rectified spirit 70%","1 l sugar syrup","100 ml lemon juice"],"steps":["Place the fresh linden blossoms into a large jar and pour in 1.5 l of 70% rectified spirit.","Seal the jar tightly and set aside in a dark, warm place for 14 days, shaking it from time to time.","Strain the infusion through fine cloth and pour it into 1 l of hot sugar syrup mixed with 100 ml of lemon juice.","Stir the liquid thoroughly, strain again through cloth, and bottle."],"time":25,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Likier_kresowy","page":"Książka kucharska/Likier kresowy"},{"id":"oc-plwb-17187","title":"Likier Wisielec (suspended orange liqueur)","cuisine":"European","category":"Drink","ingredients":["1 orange (large)","1 l plain, unflavoured vodka","to taste cloves (a few whole cloves)","250 g sugar cubes"],"steps":["Pour the vodka into a tall jar, add the sugar cubes, and stir until completely dissolved.","Thoroughly wash the orange, scald it with boiling water, pat dry, and stud its peel with the cloves.","Thread a thick string through the center of the orange and suspend the fruit under the lid of the jar so it does not touch the liquid.","Seal the jar tightly and set aside for about 2 months."],"time":15,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Likier_Wisielec","page":"Książka kucharska/Likier Wisielec"},{"id":"oc-plwb-19256","title":"Likier z czarnego bzu (elderberry liqueur)","cuisine":"European","category":"Drink","ingredients":["1 kg elderberries (ripe)","1 l rectified spirit","500 g sugar","8 cloves (6–10 whole cloves)","1 cinnamon bark (piece)","1 lemon zest (grated zest from 1 lemon)","1 l water"],"steps":["Wash and dry the elderberries, then transfer them into a jar.","Mix 1 l of rectified spirit with 250 ml of water, pour over the fruit, seal the jar tightly, and set aside for 2 weeks, shaking it daily.","Bring 750 ml of water to a boil with the grated lemon zest, cloves, and cinnamon bark, cover, and simmer over low heat for about 10 minutes.","Add the sugar, cook to a thick syrup, skim off any foam, and remove the pot from the heat.","Decant the spirit infusion from the fruit and gradually pour it into the syrup, stirring constantly, then pour everything into a jar and seal tightly.","After 3 days, filter the liqueur thoroughly, pour into bottles, cork, and set aside for 3 months."],"time":40,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Likier_z_czarnego_bzu","page":"Książka kucharska/Likier z czarnego bzu"},{"id":"oc-plwb-18678","title":"Likier z czarnych jagód (wild bilberry liqueur)","cuisine":"European","category":"Drink","ingredients":["200 g bilberries","10 g cloves","10 g orange peel (finely chopped)","20 g cinnamon bark","1 l rectified spirit","1.5 kg honey","500 ml water"],"steps":["Place the bilberries, cloves, orange peel, and cinnamon bark into a demijohn and pour in the rectified spirit.","Cork the vessel tightly, shake vigorously, and set aside for 3 weeks, swirling the contents from time to time.","Boil 500 ml of water with the honey, skim off any scum, and remove the pot from the heat.","Gradually pour the filtered spirit infusion into the hot honey mixture, stirring constantly.","Pour everything back into the demijohn, cork tightly, and set aside for another 3 weeks, then filter again, bottle, and leave in a cool, dark place for several months."],"time":35,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Likier_z_czarnych_jag%C3%B3d","page":"Książka kucharska/Likier z czarnych jagód"},{"id":"oc-plwb-21323","title":"Lin po góralsku (Highlander-style tench)","cuisine":"European","category":"Main","ingredients":["1 kg tench","1 bunch spring onion with chives","1 l milk","50 g butter","500 ml tomato sauce (thick)","1 lemon","to taste salt","to taste wheat flour (for dusting)"],"steps":["Separate the chives from the spring onions and chop them finely. Soak the onions for 60 minutes in 1 l of milk, then drain, fry in butter for 2–3 minutes, and simmer in 500 ml of thick tomato sauce.","Clean and gut the tench, slice into thin strips, season with salt, and drizzle with lemon juice.","Coat the fish pieces in flour and fry until golden.","Transfer the fish to an ovenproof dish, pour over the tomato and onion sauce, and bake for about 15 minutes in an oven preheated to 180 °C.","After removing from the oven, sprinkle the dish with the finely chopped chives."],"time":100,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lin_po_g%C3%B3ralsku","page":"Książka kucharska/Lin po góralsku"},{"id":"oc-plwb-18777","title":"Lingonberry and pear preserve","cuisine":"European","category":"Preserve","ingredients":["1 kg lingonberries (red cowberries)","500 g pears (ripe, sweet small field pears)","500 g sugar","250 ml water","1 lemon"],"steps":["Bring the water to a boil in a pot with the sugar and finely grated lemon zest to form a clear syrup.","Add the sorted lingonberries to the syrup and simmer gently over low heat until slightly thickened.","Peel the pears thinly while keeping the stems intact, add them to the lingonberries, and simmer gently until translucent, then stir in the freshly squeezed lemon juice.","Carefully ladle the hot lingonberries and pears into sterilized jars, seal immediately, and leave covered with a towel until cool."],"time":70,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Czerwone_bor%C3%B3wki_z_gruszkami","page":"Książka kucharska/Czerwone borówki z gruszkami"},{"id":"oc-plws-474250","title":"Lingonberry Preserves with Apples and Pears","cuisine":"European","category":"Preserve","ingredients":["1 kg lingonberries (Weight after blanching; orig. a kilo.)","500 g sweet apples (Cut into balls or strips; orig. half a kilo.)","500 g pears (Peeled; orig. the same amount, i.e., half a kilo, as the apples.)","1 kg sugar (orig. a kilo.)","to taste water (For blanching the lingonberries and preparing a light syrup; volume not specified.)"],"steps":["Sort the lingonberries.","Blanch the lingonberries in boiling water for 1 minute.","Drain the lingonberries on a sieve.","Cut the apples into strips or balls.","Peel the pears.","Boil a light syrup from the sugar and water.","Add the lingonberries, apples, and pears to the syrup.","Simmer the fruit over low heat until the apples and pears soften and turn red.","Transfer the hot preserves into jars.","Leave the preserves to cool completely.","Tie parchment paper over the cooled jars."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Konfitury%2C_kompoty_i_inne_konserwy_owocowe/Bor%C3%B3wki","page":"Konfitury, kompoty i inne konserwy owocowe/Borówki"},{"id":"oc-plws-503333","title":"Lithuanian-style puffed omelette","cuisine":"European","category":"Breakfast","ingredients":["5 egg yolks","5 egg whites (beaten to stiff peaks)","5 tsp plain wheat flour","250 ml milk (or sweet cream)","to taste salt","to taste butter (generous amount for frying)"],"steps":["Beat the egg yolks with the wheat flour, a pinch of salt, and the milk until smooth and lump-free.","Whip the egg whites to stiff peaks and fold them carefully into the yolk batter.","Heat a generous amount of butter in a skillet, pour in the egg mixture, and cook over medium heat for about 8–10 minutes, taking care not to burn the bottom, until the omelette rises and sets.","Fold the finished omelette in half, slide onto a platter, and serve immediately."],"time":20,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Omlet_litewski","page":"100 potraw z jaj/Omlet litewski"},{"id":"oc-plws-39067","title":"Liście szczawiowe na rosole (Sorrel leaf broth with poached eggs)","cuisine":"European","category":"Soup","ingredients":["1.5 l meat broth (rich, clear)","1 fresh sorrel leaves (large handful of rinsed and dried leaves)","4 eggs (whole eggs, poached)","1 l water (for poaching the eggs)","to taste salt"],"steps":["Rinse and dry the sorrel leaves, place them in a smaller pot, pour in part of the hot broth, salt lightly, and simmer over low heat for about 20–30 minutes.","Pour the remaining hot broth into a soup tureen and add enough of the cooked sorrel leaves and their cooking liquid to give the soup a pleasantly tangy flavour.","Separately poach the eggs in boiling water.","Place the poached eggs directly into deep soup plates and ladle the hot sorrel soup over them."],"time":45,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Li%C5%9Bcie_szczawiowe_na_rosole","page":"365 obiadów za 5 złotych/Liście szczawiowe na rosole"},{"id":"oc-plwb-55040","title":"Lody owocowe (fruit and meringue ice cream)","cuisine":"European","category":"Dessert","ingredients":["300 ml whipping cream 30%","125 ml meringues (crushed)","250 ml raspberries and red grapes","4 tbsp sugar","250 ml water","2 peach"],"steps":["Cut the grapes in half lengthwise, place in a pot together with the raspberries, add 4 tablespoons of sugar, and pour in 250 ml of water.","Simmer the fruit over low heat for 20–30 minutes until a syrup forms, then set aside to cool completely.","Whip 300 ml of 30% whipping cream until stiff, add 125 ml of crushed meringues, diced peaches, and 2–4 tablespoons of the cooled fruit in syrup.","Gently fold the mixture and place in the freezer until set."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lody_owocowe","page":"Książka kucharska/Lody owocowe"},{"id":"oc-plwb-18818","title":"Lody z sosem orzechowym (ice cream with warm nut sauce)","cuisine":"European","category":"Dessert","ingredients":["1 condensed milk (can)","2 egg yolk","2 tsp butter","125 ml desiccated coconut","80 ml walnuts (chopped)","80 ml hazelnuts (chopped)","0.25 tsp vanilla flavouring oil","1 l ice cream (any flavour)"],"steps":["Whisk the condensed milk with the egg yolks in a saucepan and add the butter.","Heat the mixture over low heat for about 10 minutes, stirring constantly, until it thickens and comes to a simmer.","Add the vanilla flavouring oil and heat for another 2–3 minutes, stirring continuously.","Remove the saucepan from the heat, stir in the chopped walnuts, hazelnuts, and 125 ml of desiccated coconut, and mix well.","Scoop portions of ice cream and ladle the warm nut sauce over them."],"time":23,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lody_z_sosem_orzechowym","page":"Książka kucharska/Lody z sosem orzechowym"},{"id":"oc-plwb-55038","title":"Lody śmietankowe (traditional cream ice cream)","cuisine":"European","category":"Dessert","ingredients":["400 ml whipping cream (30–36%)","200 ml milk","65 g sugar"],"steps":["Pour 200 ml of whipping cream into a pot, add 65 g of sugar, and heat over low heat, stirring constantly, until the sugar dissolves completely.","Remove the pot from the heat, pour into a container, add the remaining 200 ml of whipping cream and 200 ml of milk, and mix thoroughly with a whisk or hand mixer.","Place the container in the refrigerator and chill the mixture.","Freeze the chilled mixture in an ice cream maker according to the manufacturer's instructions, or place the container in the freezer for 3–4 hours, blending the contents every 30 minutes to break up ice crystals."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lody_%C5%9Bmietankowe","page":"Książka kucharska/Lody śmietankowe"},{"id":"oc-plws-451176","title":"Lukier na białkach (Royal icing)","cuisine":"European","category":"Sauce","ingredients":["500 g icing sugar (sifted, orig. half a kilo of icing sugar or pounded loaf sugar)","4 egg whites (very fresh, 1–2 more if needed depending on egg size)","1 lemon (juice of a whole lemon squeezed through a strainer)"],"steps":["Tip the sifted icing sugar into a ceramic grinding bowl or mixing bowl, add the four fresh egg whites, and beat in one direction with a wooden pestle until smooth and fluffy (add one more egg white if needed).","Squeeze in the juice of a whole lemon through a fine strainer to make the icing whiter and firmer.","Beat the icing for a long time (about 15–20 minutes by hand or 8–10 minutes with a mixer) until it reaches a spreadable consistency that covers the cake smoothly and dries with a glossy sheen.","Spread the icing over baked babkas or sheet cakes, arrange dried fruit and nuts on the wet glaze, and place the cake in a barely warm oven (about 70–80 °C) for a few minutes to dry the icing."],"time":25,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Lukier_na_bia%C5%82kach","page":"Ciasta wielkanocne/Lukier na białkach"},{"id":"oc-plwb-19092","title":"Lviv-style stuffed veal roulades (Zrazy cielęce zawijane po lwowsku)","cuisine":"European","category":"Main","ingredients":["550 g boneless veal (500–600 g)","30 g fat (for searing)","50 g fatback (for filling)","100 g fermented pickles (for filling)","100 g carrots (for filling)","100 g parsley root (for filling)","100 g onion (chopped, for filling)","125 ml sour cream (1/8 liter, for sauce)","2 tbsp all-purpose flour (for dusting roulades and thickening sauce)","125 ml water (1/8 liter, for braising)","to taste salt","to taste black pepper","to taste mustard (for coating the meat)"],"steps":["Cut the veal into wide slices, pound into thin cutlets, spread each thinly with mustard, and sprinkle with chopped onion.","Cut the fatback, carrots, parsley root, and fermented pickles into batons, season with pepper, place on the meat slices, and roll up tightly, securing with toothpicks.","Dust the roulades with salt and some flour, and brown well on all sides in heated fat.","Transfer the roulades to a shallow pot, pour in the pan drippings and 125 ml of water, and simmer covered slowly until tender.","When the roulades are tender, sprinkle the remaining flour over the sauce, season with pepper, bring to a boil, and stir in the sour cream.","Arrange the roulades on a platter, spoon over the sauce, and serve with buckwheat groats, barley groats, or potatoes, alongside a raw vegetable salad and cooked vegetables."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zrazy_ciel%C4%99ce_zawijane_po_lwowsku","page":"Książka kucharska/Zrazy cielęce zawijane po lwowsku"},{"id":"oc-plwb-15531","title":"Lángos (Hungarian fried flatbreads)","cuisine":"European","category":"Snack","ingredients":["3 potatoes (boiled and pressed through a potato ricer)","30 g fresh yeast","200 ml milk (warm)","1 tsp sugar","400 g wheat flour","3 tsp vegetable oil (for the dough)","2 tsp salt","to taste vegetable oil (for deep frying)"],"steps":["Dissolve the yeast and sugar in a small amount of warm milk and set aside in a warm place for 10–15 minutes for the starter to rise.","Place the flour into a bowl, pour in the yeast starter, and add the riced potatoes along with 3 teaspoons of oil.","Knead into a uniform dough, gradually adding the rest of the 200 ml of warm milk and the salt.","Cover the dough and set aside for about 60 minutes to rise, then knead it once more.","Tear off pieces of dough, shape into thin flatbreads with your fingers, and deep-fry in hot oil on both sides until golden."],"time":95,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Langosze","page":"Książka kucharska/Langosze"},{"id":"oc-plwb-19515","title":"Maczki drożdżowe (yeast poppy seed pinwheels)","cuisine":"European","category":"Cookie","ingredients":["625 g wheat flour","500 g margarine","2 egg","3 tbsp sugar","100 g fresh yeast","1 poppy seed filling (large can)","2 egg yolk (for brushing)","250 ml sour cream"],"steps":["Chop the margarine into the flour, add the whole eggs and the yeast mixed with 250 ml of sour cream and the sugar, then knead into a smooth dough.","Place the kneaded dough into the refrigerator for 30 minutes.","Roll out the chilled dough into thin sheets and spread the poppy seed filling over them.","Roll the dough into logs, slice into pieces 3 cm long, and arrange loosely on a baking sheet.","Brush the pastries with beaten egg yolks and bake for about 30 minutes in an oven preheated to 170 °C."],"time":80,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Maczki_dro%C5%BCd%C5%BCowe","page":"Książka kucharska/Maczki drożdżowe"},{"id":"oc-plws-1081098","title":"Makagigi (Polish Poppy Seed and Honey Brittle)","cuisine":"European","category":"Cookie","ingredients":["200 g sugar (originally half a funt)","60 ml water (for a thick sugar syrup and for moistening the board)","800 g poppy seeds (originally 1 kwarta (1 l))","250 ml honey (originally 1 full kwaterka (historical Polish measure))","0.5 tbsp wheat flour"],"steps":["Boil a thick syrup from the sugar and a little water, and in a second saucepan heat the dry poppy seeds until very hot.","Pour the finished sugar syrup into the hot poppy seeds, mix thoroughly, and add the honey.","Cook the mixture over low heat, stirring constantly, until it releases a distinct aroma of toasted poppy seeds.","Add half a tablespoon of wheat flour and cook for about 10 minutes longer, stirring constantly.","Turn the hot mixture out onto a marble slab or wooden board generously moistened with cold water, roll out thinly with a wet rolling pin, and cut into squares; once cooled, store in an airtight tin."],"time":45,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Makagigi","page":"Baby, placki i mazurki/Makagigi"},{"id":"oc-plwb-18867","title":"Makagigi (poppy seed and walnut brittle)","cuisine":"European","category":"Dessert","ingredients":["250 ml honey","125 ml sugar","250 ml poppy seeds (dry)","1 ml almond extract","125 ml walnuts (chopped)","to taste olive oil (for greasing the baking sheet)"],"steps":["Bring 250 ml of honey to a boil in a pot with 125 ml of sugar and 250 ml of dry poppy seeds.","Cook the mixture over low heat, stirring constantly, until lightly browned.","Stir in 125 ml of chopped walnuts, add the almond extract, and mix thoroughly.","Turn the hot mixture onto an oiled baking sheet, allow to set, and then slice with a sharp knife into squares or diamonds."],"time":25,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makagigi","page":"Książka kucharska/Makagigi"},{"id":"oc-plws-1081099","title":"Makagigi tłuczeńce (Spiced Honey, Nut and Rye Wafer Confection)","cuisine":"European","category":"Cookie","ingredients":["200 g rye flour (for a flatbread to be ground into a kwaterka (approximately 150 g) of baked rye flatbread meal)","100 ml water (for kneading the rye flatbread)","1 l honey (originally 1 kwarta (historical Polish measure))","200 g sweet almonds or other nuts (originally half a funt, washed and chopped)","50 g candied orange peel (finely chopped)","0.3 tsp ground cinnamon (1 level teaspoon in total together with the ginger and cloves)","0.3 tsp ground ginger","0.3 tsp ground cloves","8 wafer sheets (sheets, for lining and covering the mixture)"],"steps":["Knead a simple dough from the rye flour and water, bake it into a flatbread in the oven (190 °C, approx. 20 minutes) until well browned, and once cooled, pound in a mortar or grind into meal and sift through a sieve.","Pour the honey into a saucepan and add the chopped almonds (or other nuts), chopped orange peel and 150 g (1 kwaterka) of meal made from the baked rye flatbread.","Cook the mixture over low heat, stirring constantly, until it thickens like caramel.","Add a level teaspoon of the sifted spices (cinnamon, ginger, and cloves) and mix well.","Spread the hot mixture over wafer sheets, cover the top with a second layer of wafer sheets, leave until the next day to firm up, and then cut into pieces."],"time":560,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Makagigi_tak_zwane_t%C5%82ucze%C5%84ce","page":"Baby, placki i mazurki/Makagigi tak zwane tłuczeńce"},{"id":"oc-plws-39474","title":"Makaron (Homemade egg noodles for broth)","cuisine":"European","category":"Side","ingredients":["300 g plain wheat flour (originally half a Polish kwarta (500 ml) of finest wheat flour)","3 eggs (whole eggs)","1.5 l meat broth (or salted water, for boiling and serving the noodles)"],"steps":["Knead a very stiff, smooth dough from the wheat flour and whole eggs alone.","Roll the dough out on a pastry board as thinly as possible, avoiding excess flour for dusting, and leave the sheets for about 30 minutes to dry slightly.","Cut the slightly dried dough into strips about 5–6 cm wide, stack the strips three high, roll them up together into a cylinder, and slice with a sharp knife into very fine threads.","Toss the cut noodles loosely with your fingers across the board to dry a little longer.","About 15 minutes before serving, ladle part of the broth into a smaller pot, bring to a boil, and drop in the noodles; as soon as they float to the surface, pour them along with their cooking broth into the tureen containing the rest of the hot broth."],"time":70,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Makaron","page":"365 obiadów za 5 złotych/Makaron"},{"id":"oc-plwb-1430","title":"Makaron w śmietanowym sosie (pasta with steamed vegetables and creamy cheese sauce)","cuisine":"European","category":"Main","ingredients":["300 g farfalle pasta","250 g broccoli","250 g zucchini","1 bunch carrots","240 g canned green peas (drained)","50 g anchovy fillets","4 tbsp whipping cream (30% fat)","100 g processed cheese","to taste salt","to taste black pepper"],"steps":["Cook the farfalle pasta al dente and drain.","Wash the broccoli, zucchini, and carrots, steam them until tender, then cut into smaller pieces.","Toss the hot pasta with the chopped vegetables and drained green peas, and season with salt and pepper.","Heat the whipping cream with the processed cheese in a saucepan, stirring until smooth.","Pour the warm creamy cheese sauce over the pasta and vegetables, and garnish with anchovy fillets."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_w_%C5%9Bmietanowym_sosie","page":"Książka kucharska/Makaron w śmietanowym sosie"},{"id":"oc-plwb-1440","title":"Makaron z jesiennymi grzybami (pasta with honey mushrooms in sour cream sauce)","cuisine":"European","category":"Main","ingredients":["400 g farfalle pasta","400 g honey mushrooms","1 onion","125 ml sour cream 18%","1 tbsp butter","1 tsp wheat flour","3 tbsp water","to taste thyme","to taste lemon juice","to taste salt","to taste black pepper"],"steps":["Cook the farfalle pasta al dente and drain.","Clean, wash, and slice the honey mushrooms, and peel and finely chop the onion.","Melt the butter in a pan and sauté the chopped onion.","Add the sliced honey mushrooms to the onion, season with salt, pour in the water, and braise covered until tender.","Dust the mushrooms with wheat flour, cook for a moment longer, then pour in the sour cream and bring to a boil.","Season the sauce with salt, pepper, lemon juice, and thyme, and toss with the warm pasta."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_jesiennymi_grzybami","page":"Książka kucharska/Makaron z jesiennymi grzybami"},{"id":"oc-plwb-1512","title":"Makaron z mortadelą (pasta with fried mortadella and breadcrumbs)","cuisine":"European","category":"Main","ingredients":["500 g pasta","100 g mortadella","2 tbsp butter","2 tbsp breadcrumbs","to taste salt","to taste black pepper"],"steps":["Cook the pasta al dente and drain.","Cut the mortadella into thin strips and sauté in melted butter.","Add the cooked pasta and breadcrumbs to the pan and fry everything together for a moment, stirring.","Season the dish to taste with salt and pepper."],"time":17,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_mortadel%C4%85","page":"Książka kucharska/Makaron z mortadelą"},{"id":"oc-plwb-1514","title":"Makaron z oscypkiem (spaghetti with smoked oscypek cheese and black pepper)","cuisine":"European","category":"Main","ingredients":["500 g spaghetti pasta","4 tbsp oscypek cheese (grated)","2 tsp black pepper (ground)","4 tbsp pasta cooking water"],"steps":["Cook the spaghetti pasta al dente, reserve 4 tablespoons of the pasta cooking water, and drain the rest.","Toss the hot spaghetti with the grated oscypek cheese, ground pepper, and reserved pasta cooking water."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_oscypkiem","page":"Książka kucharska/Makaron z oscypkiem"},{"id":"oc-plwb-1531","title":"Makaron z papryką (pasta with bell pepper and sour cream sauce)","cuisine":"European","category":"Main","ingredients":["400 g pasta","3 bell pepper","125 ml sour cream 18% (thick)","3 tbsp salad dressing (ready-made)","to taste dried basil","to taste salt","to taste black pepper","to taste semi-hard cheese (grated)"],"steps":["Cook the pasta al dente and drain.","Wash the bell peppers, remove the seed cores, finely dice the flesh, and mix it with the sour cream and salad dressing.","Season the sauce with salt, pepper, and dried basil.","Pour the prepared bell pepper sauce over the hot pasta and sprinkle with grated cheese."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_papryk%C4%85","page":"Książka kucharska/Makaron z papryką"},{"id":"oc-plwb-1533","title":"Makaron z pomidorowym sosem (pasta with tomato and sour cream sauce)","cuisine":"European","category":"Main","ingredients":["400 g pasta","800 g canned tomatoes (in juice)","1 onion","2 tbsp sour cream 18% (thick)","1 clove garlic","to taste vegetable oil (for frying)","to taste semi-hard cheese (sharp, grated)","to taste salt","to taste black pepper"],"steps":["Cook the pasta al dente and drain.","Peel and chop the onion, then fry it in heated vegetable oil.","Add the canned tomatoes to the onion and fry together for a few minutes.","Stir in the sour cream and mashed garlic clove, then season the sauce with salt and pepper.","Toss the sauce with the warm pasta and sprinkle with the sharp cheese."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_pomidorowym_sosem","page":"Książka kucharska/Makaron z pomidorowym sosem"},{"id":"oc-plwb-1534","title":"Makaron z szynką i serowym sosem (baked pasta with ham and Emmental cheese sauce)","cuisine":"European","category":"Main","ingredients":["400 g pasta tubes","250 g ham","250 ml light cream 12% (low-fat)","200 g Emmental cheese","1 tbsp butter (for greasing the baking dish)","to taste nutmeg (grated)","to taste dill (chopped)","to taste salt"],"steps":["Cook the pasta tubes al dente and drain, then preheat the oven to 200 °C.","Cut the ham into narrow strips, toss with the cooked pasta, and season with salt and grated nutmeg.","Transfer the pasta and ham mixture to a buttered ovenproof dish.","Grate the Emmental cheese, mix half of it with the light cream and a pinch of salt, and pour the sauce over the pasta.","Sprinkle the top with the remaining Emmental cheese and bake for 20 minutes at 200 °C, then scatter with chopped dill before serving."],"time":38,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_szynk%C4%85_i_serowym_sosem","page":"Książka kucharska/Makaron z szynką i serowym sosem"},{"id":"oc-plwb-12745","title":"Makówki (Silesian poppy seed bread pudding)","cuisine":"European","category":"Dessert","ingredients":["1 challah bread (or other white bread)","500 g poppy seeds (ground)","1 l milk","3 tbsp butter","5 tbsp sugar (or honey)","16 g vanilla sugar","100 g walnuts (shelled)","50 g almonds","100 g dried figs","100 g raisins","30 g desiccated coconut"],"steps":["Cut the challah bread into slices.","Bring the milk, sugar, vanilla sugar, and butter to a boil in a pot, add the ground poppy seeds, and simmer over low heat for 10–15 minutes until thick, stirring constantly.","Cut the dried figs into thin slices, and scald and drain the walnuts, almonds, and raisins; stir most of the dried fruits and nuts into the simmering poppy seed mixture, then remove from the heat.","Arrange alternating layers of challah slices and poppy seed mixture in a bowl, finishing with the poppy seed mixture.","Garnish the top with the remaining almonds, walnuts, and raisins, and sprinkle with desiccated coconut."],"time":40,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mak%C3%B3wki","page":"Książka kucharska/Makówki"},{"id":"oc-plwb-19132","title":"Malinowa pianka (raspberry yogurt mousse)","cuisine":"European","category":"Dessert","ingredients":["300 g raspberries","300 g plain yogurt","1 egg (yolk and white separated)","1 egg white","16 g vanilla sugar","2 tbsp sugar","3 tsp gelatin powder","1 tsp lemon juice","to taste water (to dissolve gelatin)","to taste lemon balm (leaves for decoration)"],"steps":["Rub half of the raspberries through a sieve into a smooth puree, set aside 4 whole raspberries for garnish, and divide the remaining berries among four dessert cups.","Dissolve the gelatin in a small amount of water, and separate the egg white from the yolk.","Whisk the plain yogurt thoroughly with the egg yolk, raspberry puree, lemon juice, sugar, and vanilla sugar, then mix in the dissolved gelatin and place in the refrigerator.","Beat both egg whites until stiff peaks form and gently fold into the yogurt mixture as it begins to set.","Pour the prepared mousse over the raspberries in the cups, chill for 60 minutes in the refrigerator, and garnish with the reserved raspberries and lemon balm leaves before serving."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Malinowa_pianka","page":"Książka kucharska/Malinowa pianka"},{"id":"oc-plwb-16926","title":"Marchewka w sosie ziołowym (carrot and celeriac salad in herb yogurt dressing)","cuisine":"European","category":"Salad","ingredients":["200 g carrots","100 g celeriac","1 tbsp raisins","250 ml plain yogurt","1 tsp sweet ground paprika","1 apple","to taste lettuce (leaves for serving)","to taste grated lemon zest","to taste mustard","to taste fresh herbs (finely chopped)","to taste salt","to taste black pepper"],"steps":["Peel the carrots and celeriac and finely dice them or grate on a coarse grater.","Add the raisins to the vegetables, toss together, season with salt and pepper, and set aside.","Whisk the plain yogurt thoroughly with the sweet paprika, grated lemon zest, pepper, mustard, and finely chopped herbs.","Dress the carrots and celeriac with the yogurt sauce, arrange on lettuce leaves, and garnish with apple slices."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Marchewka_w_sosie_zio%C5%82owym","page":"Książka kucharska/Marchewka w sosie ziołowym"},{"id":"oc-plws-44934","title":"Marinated herrings in sweet cream and milt dressing (śledzie w śmietance)","cuisine":"European","category":"Preserve","ingredients":["10 salted herrings with milt (soaked)","250 ml fresh cream (orig. 1 kwaterka)","3 onion (sliced)","150 ml boiled and cooled vinegar","to taste peppercorns","to taste allspice berries"],"steps":["Soak the salted herrings in cold water for at least 36 hours (2160 minutes), then drain, pat dry with a cloth, and fillet, reserving the milt.","Layer the herrings in a glass jar alternating with onion slices, peppercorns, and allspice berries.","Chop the extracted herring milt, press through a fine sieve, blend with the sweet cream, and thin with boiled, cooled vinegar.","Pour the prepared sauce over the herrings and set in a cold place overnight (for about 8 hours). The next day they are ready to serve."],"time":600,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/%C5%9Aledzie_marynowane","page":"365 obiadów za 5 złotych/Śledzie marynowane"},{"id":"oc-plws-1081086","title":"Marzipan Sugar Leaves","cuisine":"European","category":"Cookie","ingredients":["400 g icing sugar (originally 1 funt of pounded sugar, half for working with the almonds and egg whites and half for kneading)","37.5 g sweet almonds (orig. 3 łut, blanched and peeled)","2 egg whites (whites)","2 tbsp wheat flour (for dusting the board when rolling)"],"steps":["Pound the blanched and peeled sweet almonds in a mortar into a smooth paste, gradually adding the icing sugar a spoonful at a time.","Beat in two egg whites and continue grinding while adding icing sugar until you have used half of its total amount (200 g).","Turn the beaten mixture out onto a board and knead with the remaining 200 g of icing sugar into a smooth dough.","Roll out the dough thinly on a board lightly dusted with flour and cut out leaf shapes with a cutter.","Arrange the leaves on a parchment-lined baking sheet and dry in a low oven (140–150 °C) for about 15 minutes until they take on a delicate color."],"time":50,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Marcepanowe_listki","page":"Baby, placki i mazurki/Marcepanowe listki"},{"id":"oc-plws-451183","title":"Masa kawowa „Mocca” (Mocha buttercream filling)","cuisine":"European","category":"Sauce","ingredients":["250 g butter (softened, orig. a quarter kilo of sweet-cream butter)","400 g icing sugar (orig. 40 dag)","5 egg yolks (whole yolks)","4 tbsp strong black coffee (very strong brew of real coffee without chicory)"],"steps":["Beat the softened butter until pale and fluffy.","Continuing to beat, gradually add the icing sugar a tablespoon at a time along with the five egg yolks one by one.","Slowly dribble in four tablespoons of very strong, cooled black coffee and beat until thoroughly combined.","If the mixture begins to curdle and resists absorbing the coffee, set the bowl briefly in a larger vessel of hot water until the emulsion comes together, then remove and continue beating in a cool place until completely cold."],"time":25,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Masa_kawowa_%E2%80%9EMocca%E2%80%9C","page":"Ciasta wielkanocne/Masa kawowa „Mocca“"},{"id":"oc-plws-451186","title":"Masa ponczowa (Lemon and rum punch cake filling)","cuisine":"European","category":"Sauce","ingredients":["4 eggs (whole)","200 g sugar (orig. 20 dag)","1 lemon (grated zest and squeezed juice of a whole lemon)","1 tbsp plain wheat flour","300 ml water (orig. 1–1.5 szklanki)","50 ml rum or arrack (orig. 1 generous kieliszek)"],"steps":["Beat the four whole eggs with the sugar until pale and fluffy.","Add the grated zest and squeezed juice of the whole lemon, a tablespoon of plain wheat flour, and 300 ml of water, then mix thoroughly.","Warm the mixture over low heat, beating constantly, until it thickens noticeably.","Remove the pan from the heat, pour in a kieliszek of rum or arrack, and continue beating until completely cool; before filling the torte, sprinkle the cake layers with an appropriate spirit or syrup."],"time":25,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Masa_ponczowa","page":"Ciasta wielkanocne/Masa ponczowa"},{"id":"oc-plws-38760","title":"Masło serdelowe (anchovy butter)","cuisine":"European","category":"Sauce","ingredients":["200 g anchovy fillets (orig. half a funt of anchovies)","200 g butter (orig. half a funt of fresh butter)","to taste black pepper","to taste chives (finely chopped (optional))"],"steps":["Rinse the anchovy fillets in cold water, pat dry, and pound in a mortar into a smooth paste.","Cream the pounded anchovies with 200 g of fresh butter and a pinch of pepper, then rub the mixture through a fine sieve.","Mix the butter well (optionally adding finely chopped chives) and serve with roast beef tenderloin or capon."],"time":20,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Mas%C5%82o_serdelowe","page":"365 obiadów za 5 złotych/Masło serdelowe"},{"id":"oc-plwb-448","title":"Mayonnaise","cuisine":"European","category":"Sauce","ingredients":["2 egg yolk (raw)","2 tbsp mustard","250 ml vegetable oil","to taste salt","to taste black pepper"],"steps":["Place the raw egg yolks into a bowl, add the mustard, and whisk thoroughly with a kitchen whisk.","Slowly pour in 250 ml of vegetable oil in small portions while whisking constantly, taking care that the emulsion does not split.","Whisk until a uniform, stiff emulsion forms, and finally season to taste with salt and black pepper."],"time":10,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Majonez","page":"Książka kucharska/Majonez"},{"id":"oc-plwb-7881","title":"Mayonnaise and egg sauce","cuisine":"European","category":"Sauce","ingredients":["250 ml mayonnaise","250 ml sour cream (thick)","2 hard-boiled eggs","2 tbsp mild Polish mustard","to taste salt","to taste black pepper","to taste icing sugar","to taste lemon juice"],"steps":["Separate the yolks and whites of the hard-boiled eggs; mash the yolks with the mild Polish mustard and lemon juice until smooth, and finely chop the egg whites.","Add the mayonnaise and lightly whisked sour cream to the mashed yolks, stir, and season to taste with salt, pepper, and icing sugar.","Stir in the chopped egg whites, combine well, and pour into a sauce boat; serve within an hour of preparation."],"time":15,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_majonezowo-jajeczny","page":"Książka kucharska/Sos majonezowo-jajeczny"},{"id":"oc-plwb-18686","title":"Mazowiecka potrawka z kury (Masovian chicken fricassee in milk sauce)","cuisine":"European","category":"Main","ingredients":["1 stewing hen (large)","100 g pork fatback (salted)","20 g butter","250 ml milk","40 g wheat flour","1 l water (enough to cover the meat)","to taste parsley leaves (finely chopped)","to taste salt","to taste black pepper"],"steps":["Rinse the hen, cut it into a dozen or so pieces, put them in a saucepan, and add enough water to cover the meat.","Cut the pork fatback into strips, add to the pan, cover tightly with a lid, and braise until the meat is tender and the liquid has evaporated.","Melt the butter in a pan, add the wheat flour, and cook a pale blond roux without letting it brown.","Pour the milk into the roux, bring to a boil while stirring, and season the sauce to taste with salt and pepper.","Arrange the tender pieces of chicken on a serving platter, ladle over the hot milk sauce, and sprinkle with finely chopped parsley leaves."],"time":110,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mazowiecka_potrawka_z_kury","page":"Książka kucharska/Mazowiecka potrawka z kury"},{"id":"oc-plws-451172","title":"Mazurek bakaliowy (Dried-fruit and nut Easter cake)","cuisine":"European","category":"Cake","ingredients":["200 g large Malaga raisins (orig. 20 dag)","200 g sultana raisins (seedless, orig. 20 dag)","200 g Zante currants (small dark raisins, orig. 20 dag)","200 g dried figs (cut into thin strips, orig. 20 dag)","200 g dried dates (pitted and cut into thin strips, orig. 20 dag)","200 g sweet almonds (blanched and cut into thin slivers, orig. 20 dag)","100 g candied lemon or orange peel (finely chopped, orig. 10 dag)","12 eggs (separated into 12 yolks and 12 whites)","750 g icing sugar (orig. 75 dag)","3 communion-style wafer sheets (for the bases of three mazureks)"],"steps":["Prepare the dried fruit and nuts: pick over the Malaga raisins, sultanas, and currants, cut the figs, dates, and blanched almonds into thin strips, and finely chop the candied citrus peel.","Beat the 12 egg yolks with the icing sugar until pale and fluffy, then stir in the prepared fruit and nuts.","Whip the 12 egg whites to stiff peaks and fold gently into the fruit mixture.","Spread in a thick layer over three wafer sheets (or par-baked shortcrust bases), bake in an oven preheated to 180 °C for about 30 minutes until golden, then crack the oven door slightly open and let the cakes dry for another 30 minutes."],"time":105,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_bakaljowy","page":"Ciasta wielkanocne/Mazurek bakaljowy"},{"id":"oc-plws-451116","title":"Mazurek bakaliowy na białkach (Meringue dried-fruit Easter cake)","cuisine":"European","category":"Cake","ingredients":["250 g dried figs (cut into strips, orig. a quarter kilo)","250 g Zante currants (cleaned, orig. a quarter kilo)","50 g candied lemon or orange peel (cut into fine strips, orig. a few pieces)","8 egg whites (whole whites)","500 g icing sugar (orig. half a kilo)","1 communion-style wafer sheet (for the base)","1 tbsp plain wheat flour (for dusting the baking sheet under the wafer)"],"steps":["Cut the dried figs and candied lemon or orange peel into thin strips and pick over the currants.","Whip the eight egg whites to stiff peaks, fold in the icing sugar, and gently mix in the prepared dried fruit.","Lay the wafer sheet on a flour-dusted baking sheet and spread the meringue-and-fruit mixture over it in an even layer.","Place the mazurek in a very low oven (about 120–130 °C) and dry for about 2 hours until lightly golden on top and thoroughly crisp."],"time":145,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_bakaljowy_na_bia%C5%82kach","page":"Ciasta wielkanocne/Mazurek bakaljowy na białkach"},{"id":"oc-plws-451132","title":"Mazurek cygański (Gypsy-style fruit and almond Easter cake)","cuisine":"European","category":"Cake","ingredients":["360 g sugar (orig. 3 filiżanki)","5 eggs (whole)","240 g plain wheat flour (dry, orig. 3 filiżanki)","200 g sultana raisins (seedless, orig. 2 filiżanki)","200 g Zante currants (small dark raisins, orig. 2 filiżanki)","200 g unblanched almonds (cut into thin strips with skins on, orig. 2 filiżanki)","50 g candied orange or lemon peel (optional, orig. half a filiżanka)","1 tbsp butter (for greasing the mould)","1 tbsp breadcrumbs (for dusting the mould)"],"steps":["Beat the five whole eggs with the sugar until pale and fluffy.","Fold in the dry plain wheat flour, sultanas, currants, thinly slivered unblanched almonds, and optional candied citrus peel, mixing thoroughly.","Spread the batter evenly into a paper-lined baking tray greased with butter and dusted with breadcrumbs.","Bake in an oven preheated to 180 °C for about 30–35 minutes; serve plain or glazed with translucent punch icing."],"time":60,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_cyga%C5%84ski","page":"Ciasta wielkanocne/Mazurek cygański"},{"id":"oc-plwb-5399","title":"Mazurek cytrynowy (lemon Polish Easter flat cake)","cuisine":"European","category":"Cake","ingredients":["140 g powdered sugar","140 g butter","160 g wheat flour","3 egg yolk (hard-boiled)","150 ml lemon juice","300 ml sugar","6 egg","1 lemon","150 ml sugar","100 ml water","to taste almond flakes (for decoration)"],"steps":["Rub the hard-boiled egg yolks through a sieve, chop the butter with the wheat flour, combine with the yolks and powdered sugar, and quickly knead with fingertips into coarse crumbs.","Chill the dough in the freezer, press evenly and flat onto a square baking tin, and bake at 150 °C until the edges are lightly browned, then cool.","Mix the lemon juice, 300 ml of sugar, and the eggs, and whisk in a water bath for 6–8 minutes until thick.","Chill the lemon mixture until set and spread in an even layer over the baked crust.","Bring the water to a boil with the remaining 150 ml of sugar in a wide pot.","Scrub the lemon, cut into very thin slices, place in the boiling syrup, and cook over high heat, shaking the pot, until the white pith becomes translucent.","Cool the lemon slices slightly, arrange them on top of the lemon layer, decorate with almond flakes, and store the cake in a cool place."],"time":65,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mazurek_cytrynowy","page":"Książka kucharska/Mazurek cytrynowy"},{"id":"oc-plws-451121","title":"Mazurek cytrynowy (Whole-lemon Easter mazurek cake)","cuisine":"European","category":"Cake","ingredients":["2 lemons (whole)","20 g sugar cubes (several cubes for rubbing the zest from the lemons)","500 ml water (for boiling the whole lemons)","400 g icing sugar (orig. 40 dag)","6 eggs (separated into 6 yolks and 6 whites)","90 g potato starch (orig. 1 filiżanka of potato starch)","1 tbsp butter (for greasing the mould)","1 tbsp breadcrumbs (for dusting the mould)","100 g lemon or punch fondant icing (for thinly glazing after baking)"],"steps":["Rub the yellow zest off two washed lemons using sugar cubes and crush the cubes to a powder, then boil the lemons whole in water until completely soft (about 25 minutes).","Cut open the boiled lemons, discard the pips, and pass the pulp and peel through a mincer or sieve.","Combine the puréed lemons with the icing sugar and beat, adding the egg yolks one by one along with the potato starch and the crushed lemon-zest sugar.","Whip the egg whites to stiff peaks, fold gently into the lemon mixture, and spread into a shallow tray (about 21 × 34 cm) lined with paper greased with butter and dusted with breadcrumbs.","Bake in a low oven (about 150–160 °C) for about 50 minutes until baked through and slightly dried out, then glaze thinly with lemon or punch fondant once cool."],"time":105,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_cytrynowy","page":"Ciasta wielkanocne/Mazurek cytrynowy"},{"id":"oc-plws-451134","title":"Mazurek czekoladowy gotowany (Boiled chocolate and almond fudge mazurek)","cuisine":"European","category":"Cake","ingredients":["400 g dark or bittersweet chocolate (orig. 40 dag vanilla chocolate)","400 g sweet almonds (blanched and finely grated, orig. 40 dag)","400 g sugar (orig. 40 dag)","250 ml water (orig. 1 szklanka)","1 tbsp butter (generous tablespoon of sweet-cream butter)","1 tbsp wild strawberry or strawberry preserves (large tablespoon)","1 communion-style wafer sheet (for lining the mould)"],"steps":["Boil a thick syrup from the sugar and a szklanka of water in a saucepan, as for fruit preserves.","Stir in the finely grated sweet almonds and cook briefly over low heat, then add the broken chocolate, generous tablespoon of butter, and large tablespoon of wild strawberry or strawberry preserves.","Cook everything over low heat, stirring constantly from the bottom so the mixture does not scorch.","Once it begins to thicken, drop a few drops onto a cold saucer — when a drop holds its shape and does not stick to the fingers, pour the mixture into a wafer-lined tray and leave for about 2 hours to set."],"time":165,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_czekoladowy_gotowany","page":"Ciasta wielkanocne/Mazurek czekoladowy gotowany"},{"id":"oc-plws-451124","title":"Mazurek czekoladowy pospolity (Everyday chocolate and breadcrumb Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["400 g sugar (orig. 40 dag)","8 eggs (separated into 8 yolks and 8 whites)","200 g dark or bittersweet chocolate (grated, orig. 20 dag vanilla chocolate)","215 g breadcrumbs (orig. 20 dag (200 g) for the batter plus about 1 tbsp for dusting the mould)","1 tbsp butter (for greasing the mould)"],"steps":["Beat the eight egg yolks with the sugar until pale and fluffy.","Stir in the grated chocolate and 200 g of breadcrumbs.","Whip the eight egg whites to stiff peaks and fold carefully into the chocolate mixture.","Transfer the batter to a paper-lined tray greased with butter and dusted with breadcrumbs, bake in a moderate oven (about 165 °C) for about 35–40 minutes, and dry slightly at the end."],"time":70,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_czekoladowy_pospolity","page":"Ciasta wielkanocne/Mazurek czekoladowy pospolity"},{"id":"oc-plws-1081005","title":"Mazurek daktylowy (Date Mazurek, a Polish Easter Flat Cake)","cuisine":"European","category":"Cake","ingredients":["6 egg whites (whites)","400 g icing sugar (originally 1 funt of icing sugar)","1 lemon (whole, freshly squeezed juice)","400 g sweet almonds (originally 1 funt, finely and thinly sliced)","1 pinch vanilla (pounded)","4 wafer sheets (sheets)"],"steps":["Beat six egg whites with the icing sugar until a completely white, thick icing forms.","Squeeze in the juice of one lemon, add the thinly slivered almonds and a pinch of vanilla, and mix thoroughly.","Spread the mixture over wafer sheets arranged on a baking sheet.","Place into a moderate oven (150–160 °C) for about 20 minutes until the cake dries thoroughly."],"time":55,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Mazurek_daktylowy","page":"Baby, placki i mazurki/Mazurek daktylowy"},{"id":"oc-plws-451123","title":"Mazurek królewski (Royal almond butter Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["415 g butter (orig. 40 dag (400 g) for the batter plus about 1 tbsp for greasing the mould)","400 g icing sugar (orig. 40 dag)","8 egg yolks (whole yolks)","200 g sweet almonds (orig. 15 dag (150 g) blanched and finely grated for the batter plus about 50 g whole for decorating the top)","10 bitter almonds (blanched and finely grated)","400 g plain wheat flour (dry, orig. 40 dag)","1 tbsp breadcrumbs (for dusting the mould)"],"steps":["Beat 400 g of softened butter with the icing sugar, adding the eight egg yolks one at a time, until the mixture turns pale and fluffy.","Stir in 150 g of blanched, finely ground sweet almonds and 10 ground bitter almonds, continuing to beat.","Fold in the sifted dry plain wheat flour, mix thoroughly, and spread the batter into a shallow tray lined with paper greased with butter and dusted with breadcrumbs.","Stud the top with whole sweet almonds and bake in a moderate oven (about 175 °C) for about 30–35 minutes; once cooled, you may glaze the mazurek with boiled chocolate icing or translucent fondant."],"time":70,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_kr%C3%B3lewski","page":"Ciasta wielkanocne/Mazurek królewski"},{"id":"oc-plws-1081017","title":"Mazurek Layered with Preserves (Mazurek przekładany konfiturami)","cuisine":"European","category":"Cake","ingredients":["400 g sweet almonds (orig. 1 funt blanched and peeled almonds)","400 g sugar (orig. 1 funt)","400 g unsalted butter (orig. 1 funt fresh butter (plus a little for greasing the baking sheets))","600 g wheat flour (orig. 1.5 funt)","3 egg (whole)","50 cloves (pounded)","50 cassia buds (50 pounded cassia buds (or 1 tsp ground cinnamon))","400 g fruit marmalade (hawthorn or raspberry marmalade, or currant jelly, for layering)"],"steps":["Pound the blanched almonds in a mortar and knead them at length in a cool place with 400 g of sugar, 400 g of unsalted butter, 600 g of wheat flour, 3 eggs, 50 pounded cloves, and 50 pounded cassia buds.","Divide the dough into 4 portions, roll each out as thinly as possible, and bake separately on baking sheets or sheets of paper thinly greased with butter (about 10–12 minutes at 180 °C).","Spread the hot pastry layers immediately after baking with hawthorn or raspberry marmalade or currant jelly, stack them one on top of another, and leave until the next day so they bond firmly together.","The next day, optionally ice the top and cut the mazurek into pieces."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Mazurek_przek%C5%82adany_konfiturami","page":"Baby, placki i mazurki/Mazurek przekładany konfiturami"},{"id":"oc-plwb-19271","title":"Mazurek makowy (poppy seed Polish Easter shortbread)","cuisine":"European","category":"Cake","ingredients":["250 ml poppy seeds","120 g butter (plus extra for the baking sheet)","120 g sugar","120 g wheat flour","2 egg (part for brushing the top)","1 pinch ground nutmeg","1 pinch ground cinnamon","1 pinch ground cloves (ground)","1 tsp powdered sugar","1 tbsp walnuts (chopped)"],"steps":["Scald the poppy seeds and drain them thoroughly.","Finely chop the butter with the wheat flour on a pastry board, add the drained poppy seeds, sugar, most of the beaten eggs, and a pinch each of nutmeg, cinnamon, and cloves.","Knead into a smooth dough and refrigerate for 30 minutes.","Roll out the chilled dough, transfer onto a buttered baking sheet, brush the top with the remaining beaten egg, and sprinkle with powdered sugar mixed with chopped walnuts.","Bake in an oven preheated to 160 °C for about 30 minutes."],"time":70,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mazurek_makowy","page":"Książka kucharska/Mazurek makowy"},{"id":"oc-plws-451129","title":"Mazurek makowy (Poppy-seed shortcrust Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["500 g blue or white poppy seeds (orig. half a kilo)","500 g plain wheat flour (orig. twice a quarter kilo)","250 g butter (orig. a quarter kilo)","3 eggs (2 for the dough plus 1 for brushing the top)","3 tbsp sour cream 18% (enough to bind the dough smoothly)","0.25 tsp almond or lemon oil (orig. 3 drops)","3 tbsp coarse crystal sugar (for generously sprinkling the top)"],"steps":["Knead a shortcrust dough from the poppy seeds, plain wheat flour, butter, two eggs, three drops of almond or lemon oil, and enough sour cream to make the dough smooth and workable.","Roll the dough out on a baking sheet to a thickness of about 1.5 cm (finger-thick).","Brush the top with beaten egg, sprinkle generously with coarse crystal sugar, and bake in an oven preheated to 180 °C for about 25–30 minutes."],"time":55,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_makowy","page":"Ciasta wielkanocne/Mazurek makowy"},{"id":"oc-plws-451170","title":"Mazurek migdałowy kruchy (Tender almond and hard-boiled egg yolk Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["12 hard-boiled egg yolks (whole yolks)","400 g sweet almonds (blanched, peeled, and ground, orig. 40 dag)","15 bitter almonds (blanched, peeled, and ground, orig. a dozen or so)","400 g icing sugar (orig. 40 dag)","2 eggs (raw whole eggs)","1 tbsp butter (for greasing the baking paper)","1 tbsp breadcrumbs (for dusting the baking paper)","150 g lemon or chocolate fondant icing (for glazing after baking)"],"steps":["Blanch the sweet and bitter almonds in boiling water, slip off the skins, dry thoroughly, and grind finely in a nut mill.","Mash and grind the hard-boiled egg yolks by themselves in a grinding bowl, then gradually work in the icing sugar, ground almonds, and finally the two whole raw eggs until smooth.","Spread the mixture in a thin layer over a sheet of baking paper greased with butter and dusted with breadcrumbs.","Bake in a moderate oven (about 165 °C) for about 30–35 minutes, and once cooled, glaze with lemon or chocolate fondant."],"time":75,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_migda%C5%82owy_kruchy","page":"Ciasta wielkanocne/Mazurek migdałowy kruchy"},{"id":"oc-plws-451117","title":"Mazurek migdałowy na białkach (Almond meringue Easter mazurek on wafer)","cuisine":"European","category":"Cake","ingredients":["250 g sweet almonds (orig. a quarter kilo)","15 bitter almonds (orig. a dozen or so)","8 egg whites (whipped to stiff peaks)","400 g icing sugar (orig. 40 dag)","1 communion-style wafer sheet (for the base)","50 g candied orange or lemon peel (cut into strips for decorating the top)"],"steps":["Blanch the almonds in boiling water, peel, dry lightly without browning, and grind finely in a nut mill.","Whip the eight egg whites to stiff peaks, then gently fold in the icing sugar and ground almonds.","Spread the mixture in an even layer over the prepared wafer sheet and decorate the top with strips of candied orange or lemon peel.","Place in a low oven (about 130–140 °C) for about 60 minutes so the mazurek dries slowly and turns only faintly golden on top."],"time":90,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_migda%C5%82owy_na_bia%C5%82kach","page":"Ciasta wielkanocne/Mazurek migdałowy na białkach"},{"id":"oc-plws-451136","title":"Mazurek orzechowy na miodzie (Honey, walnut and almond nougat Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["800 g walnuts and hazelnuts (shelled and cut into strips, orig. 80 dag)","400 g unblanched almonds (cut into strips, orig. 40 dag)","400 g honey (orig. 40 dag)","400 g sugar (orig. 40 dag)","12 egg whites (whipped to stiff peaks)","2 communion-style wafer sheets (for the base)","1 tbsp plain wheat flour (for dusting the baking sheets under the wafers)"],"steps":["Cut the shelled walnuts, hazelnuts, and almonds into thin strips.","Heat the honey and sugar without water in a wide, heavy-bottomed pan; once lightly caramelized, tip in the walnuts, hazelnuts, and almonds and toast together over low heat, stirring so they do not burn.","Whip the 12 egg whites to stiff peaks, spoon them into the hot honey-nut mixture, and cook over low heat, stirring constantly, until the foam first puffs up high and then subsides slightly and thickens.","Spread the mixture in a layer about 2.5 cm thick over wafer sheets laid on flour-dusted baking sheets and set in a moderate oven (about 160 °C) for 15–20 minutes until lightly golden."],"time":75,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_orzechowy_na_miodzie","page":"Ciasta wielkanocne/Mazurek orzechowy na miodzie"},{"id":"oc-plws-451115","title":"Mazurek oszczędny (Economical egg-yolk and raisin Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["200 g butter (orig. 20 dag)","200 g icing sugar (orig. 20 dag, or 300 g for a sweeter cake)","8 egg yolks (whole yolks)","10 bitter almonds (blanched and finely pounded)","1 pinch salt (orig. on the tip of a knife)","1 pinch bicarbonate of soda (orig. on the tip of a knife)","200 g plain wheat flour (orig. 20 dag)","200 g potato starch (orig. 20 dag of potato starch)","50 g sultana raisins (seedless, orig. 1 handful)","50 g Zante currants (small dark raisins, orig. 1 handful)"],"steps":["Beat the softened butter until creamy, add the icing sugar and eight egg yolks, and continue beating until light and fluffy.","Add the finely pounded bitter almonds, pinch of salt, pinch of bicarbonate of soda, plain wheat flour, potato starch, and both kinds of raisins.","Knead thoroughly into a smooth dough, roll out to a thickness of about 1 cm, and bake in an oven preheated to 180 °C for about 20–25 minutes until golden brown."],"time":50,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_oszcz%C4%99dny","page":"Ciasta wielkanocne/Mazurek oszczędny"},{"id":"oc-plwb-1504","title":"Mazurek pomarańczowy (Polish Easter orange flat cake)","cuisine":"European","category":"Cake","ingredients":["480 g krupczatka flour (coarse wheat flour)","70 g margarine","250 ml powdered sugar","3 egg yolk (2 for the dough, 1 for brushing)","2.5 tbsp sour cream 18% (optional, if the dough is too dry)","75 g orange jelly powder","1 orange","100 g raisins","100 g almonds (or other nuts)"],"steps":["Sift the krupczatka flour onto a pastry board, add the margarine and powdered sugar, and chop together with a knife.","Add two egg yolks (and sour cream if the mixture is too dry) and quickly knead into a dough, then wrap and chill in the refrigerator for 30 minutes.","Roll out the chilled dough to a thickness of about 7 mm, transfer to a baking sheet, shape a decorative rim around the edges using dough ropes, and brush it with the remaining beaten egg yolk.","Bake the crust in an oven preheated to 180 °C for about 25 minutes until golden, then set aside to cool completely.","Prepare the orange jelly according to the package instructions and set aside until it begins to set.","Scald the orange, peel off the skin and white pith, remove the seeds, and divide into segments.","Rinse and scald the raisins, then skin and chop the almonds.","Arrange the orange segments on the cooled crust, sprinkle with raisins and almonds, pour over the setting jelly, and leave until completely set before slicing."],"time":70,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mazurek_pomara%C5%84czowy","page":"Książka kucharska/Mazurek pomarańczowy"},{"id":"oc-plws-451163","title":"Mazurek prababek (Great-grandmothers' no-bake chocolate, almond and rye-crumb mazurek)","cuisine":"European","category":"Cake","ingredients":["400 g butter (orig. 40 dag sweet-cream butter)","400 g dark or bittersweet chocolate (grated, orig. 40 dag vanilla chocolate)","400 g icing sugar (orig. 40 dag)","400 g sweet almonds (roasted until golden and finely ground, orig. 40 dag)","6 tbsp grated dark wholemeal rye bread (dried, pounded, and sifted through the finest sieve)","2 tbsp whipping cream 30% (optional, if the mixture is too dry)","4 communion-style wafer sheets (for the bottom and top of two mazureks)"],"steps":["Beat the softened butter in a grinding bowl or mixing bowl with the grated chocolate, icing sugar, golden-roasted and finely ground almonds, and finely sifted rye breadcrumbs (if the mixture is too dry, add 2 tablespoons of thick whipping cream).","Spread the mixture in a layer about 1.5 cm thick (finger-thick) over two wafer sheets and cover the tops with two more wafer sheets.","Weight the mazureks down with a small board and weight, chill in a cool place or refrigerator for at least 4 hours, and bring to the table just before serving."],"time":270,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_prababek","page":"Ciasta wielkanocne/Mazurek prababek"},{"id":"oc-plws-451171","title":"Mazurek rodzynkowy kruchy (Shortcrust currant and almond Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["400 g plain wheat flour (orig. 40 dag)","400 g icing sugar (orig. 40 dag)","10 egg yolks (whole yolks)","215 g butter (orig. 20 dag (200 g) for the dough plus about 1 tbsp for greasing the baking sheet)","2 tbsp whipping cream 30% (thick sweet cream)","400 g Zante currants (orig. 40 dag)","150 g sweet almonds (orig. 10 dag (100 g) finely chopped for the dough plus about 50 g slivered for the top)","5 bitter almonds (finely chopped, orig. several almonds)","100 g candied orange and lemon peel (orig. 10 dag)","1 egg (for brushing the top)","2 tbsp coarse crystal sugar (for sprinkling the top)"],"steps":["Knead a soft shortcrust dough from the plain wheat flour, icing sugar, ten egg yolks, 200 g of butter, and two tablespoons of thick sweet cream.","Work in the currants, 100 g of finely chopped sweet almonds, several chopped bitter almonds, and the candied orange and lemon peel until evenly distributed through the dough.","Press the dough out onto a buttered baking sheet to a thickness of about 1.5 cm (finger-thick), brush the top with beaten egg, and scatter with coarse crystal sugar and slivered almonds.","Bake in an oven preheated to 180 °C for about 30–35 minutes until well browned."],"time":65,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_rodzynkowy_kruchy","page":"Ciasta wielkanocne/Mazurek rodzynkowy kruchy"},{"id":"oc-plws-451133","title":"Mazurek różany (Rose-petal jam layered shortcrust Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["500 g plain wheat flour (orig. half a kilo)","200 g butter (orig. 20 dag)","200 g sugar (orig. 20 dag)","2 tbsp sour cream 18% (thick sour cream)","200 g rose-petal preserves (orig. about 20 dag)","150 g lemon fondant icing made with rosewater (tinted with a few drops of pink food colouring)","50 g almonds or pistachios (coarsely chopped, for sprinkling the top)"],"steps":["Knead a shortcrust dough from the plain wheat flour, butter, sugar, and two tablespoons of thick sour cream, then chill in a cool place or refrigerator for about 2 hours.","Divide the chilled dough into two portions, roll out into two thin sheets, and bake in an oven preheated to 190 °C for about 20–25 minutes until deeply golden.","Sandwich the baked layers with the rose-petal preserves.","Spread the top with pink lemon fondant prepared with rosewater and scatter with coarsely chopped almonds or green pistachios."],"time":175,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_r%C3%B3%C5%BCany","page":"Ciasta wielkanocne/Mazurek różany"},{"id":"oc-plws-451128","title":"Mazurek w zimnej wodzie podchodzący (Water-risen yeast Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["500 g plain wheat flour (orig. half a kilo)","30 g fresh yeast (orig. 3 dag)","100 g butter (orig. 10 dag)","4 egg yolks (whole yolks)","250 ml milk (orig. 1 szklanka)","150 g sugar (orig. 15 dag, kneaded in after the dough rises in water)","1 pinch ground mace or cardamom (for aroma)","1 egg (for brushing the top)","50 g sweet almonds (slivered, for sprinkling the top)","50 g raisins (for sprinkling the top)","2 tbsp coarse crystal sugar (for sprinkling the top)"],"steps":["In the evening, knead a smooth dough from the plain wheat flour, crumbled fresh yeast, butter, four egg yolks, and a szklanka of lukewarm milk, working it until it comes away cleanly from your hands.","Wrap the dough loosely in a clean, damp cloth, leaving enough extra space for it to double in volume, and submerge it overnight in a vessel of cold water.","In the morning, once the risen dough has floated to the surface, unwrap it from the cloth, add 150 g of sugar and a pinch of mace or cardamom, knead thoroughly again, and let rise a second time at room temperature (for about 60 minutes).","Roll the dough out thinly on a baking sheet, brush with beaten egg, scatter generously with slivered almonds, raisins, and coarse crystal sugar, and bake in an oven preheated to 190 °C for about 20–25 minutes."],"time":595,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_w_zimnej_wodzie_podchodz%C4%85cy","page":"Ciasta wielkanocne/Mazurek w zimnej wodzie podchodzący"},{"id":"oc-plws-451169","title":"Mazurek z gotowanych żółtek (Hard-boiled egg yolk shortbread Easter mazurek)","cuisine":"European","category":"Cake","ingredients":["12 hard-boiled egg yolks (whole yolks)","265 g butter (orig. a quarter kilo (250 g) sweet-cream butter for the dough plus about 1 tbsp for greasing the mould)","400 g icing sugar (orig. 40 dag)","1 lemon (finely grated zest)","4 eggs (whole raw eggs)","50 ml rum or arrack (orig. 1 kieliszek)","500 g plain wheat flour (dry, orig. half a kilo)","1 tbsp breadcrumbs (for dusting the mould)","150 g punch or lemon fondant icing (for glazing the top the day after baking)"],"steps":["Grind the 12 hard-boiled egg yolks to a smooth paste in a grinding bowl with a wooden pestle.","Add 250 g of softened butter, the icing sugar, finely grated lemon zest, and four whole raw eggs, beating until the mixture becomes fluffy and doubles in volume.","Pour in a kieliszek of rum or arrack, add the dry plain wheat flour, and beat for about another 30 minutes, or less time with a stand mixer.","Transfer the mixture to a tin lined with buttered paper dusted with breadcrumbs, smooth the top, and bake in an oven preheated to 180 °C for about 30–35 minutes. The next day, once completely cool, carefully remove the tin and coat the mazurek thickly with punch or lemon fondant."],"time":575,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_z_gotowanych_%C5%BC%C3%B3%C5%82tek","page":"Ciasta wielkanocne/Mazurek z gotowanych żółtek"},{"id":"oc-plws-451175","title":"Mazurek „Duchesse” (No-bake chocolate and roasted almond Easter cake)","cuisine":"European","category":"Cake","ingredients":["12 hard-boiled egg yolks (whole yolks)","400 g icing sugar (orig. 40 dag, for the chocolate paste)","400 g dark or bittersweet chocolate (grated, orig. 40 dag vanilla chocolate)","200 g sweet almonds (roasted and ground, orig. 20 dag)","2 wafer sheets (equal-sized sheets)","200 g butter (orig. 20 dag sweet-cream butter)","200 g icing sugar (orig. 20 dag)","200 g sweet almonds (roasted and ground, orig. 20 dag)","200 g sugar (orig. 20 dag)","200 g dark or bittersweet chocolate (orig. 20 dag)","125 ml whipping cream 30% (orig. half a szklanka)","1 tbsp butter (orig. 1 tbsp sweet-cream butter)"],"steps":["Mash and grind the 12 hard-boiled egg yolks in a grinding bowl with 400 g of icing sugar, 400 g of grated chocolate, and 200 g of ground roasted almonds, working the mixture until it moistens and becomes completely smooth.","Spread the chocolate-almond paste evenly over two matching wafer sheets.","Cream the softened butter (200 g) until fluffy with 200 g of icing sugar and 200 g of ground roasted almonds.","Sandwich the two wafer-backed layers with the almond buttercream, weight down with a small board and weight, and leave in a cool place overnight (about 8 hours).","The next day, boil a glaze from 200 g of sugar, 200 g of chocolate, 125 ml of whipping cream, and a tablespoon of butter; as it begins to thicken, pour it over the mazurek and leave to set."],"time":555,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_%E2%80%9EDuchesse%E2%80%9C","page":"Ciasta wielkanocne/Mazurek „Duchesse“"},{"id":"oc-plws-451135","title":"Mazurek „Dzień i noc” (Day and Night marzipan and chocolate fudge Easter cake)","cuisine":"European","category":"Cake","ingredients":["400 g sweet almonds (orig. 40 dag)","15 bitter almonds (orig. a dozen or so)","400 g icing sugar (orig. 40 dag)","2 tbsp rosewater (added a little at a time to knead a smooth marzipan)","1 communion-style wafer sheet (large sheet for lining the mould)","400 g dark or bittersweet chocolate (grated, orig. 40 dag)","415 g sugar (orig. 40 dag (400 g) plus 1 tbsp (15 g) for pounding with the vanilla)","0.5 vanilla pod (piece of pod pounded with a tablespoon of sugar)","250 ml whipping cream 30% (thick, orig. 1 szklanka)"],"steps":["Blanch the almonds in boiling water, slip off the skins, dry thoroughly in a cloth, and grind finely in an almond mill or on a fine grater.","Mix the ground almonds thoroughly with the icing sugar and knead, adding rosewater a little at a time, until a smooth marzipan paste forms.","Press the marzipan in an even layer into a shallow tray formed from a wafer sheet.","Combine the grated chocolate, sugar, vanilla pounded with a tablespoon of sugar, and thick whipping cream in a saucepan and cook over low heat, stirring frequently to prevent scorching.","Once the fudge begins to thicken, test by dropping a little onto a cold saucer — if it holds its shape and does not stick to the fingers, pour it over the marzipan layer and leave until the next day to set completely before slicing."],"time":540,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_%E2%80%9EDzie%C5%84_i_noc%E2%80%9C","page":"Ciasta wielkanocne/Mazurek „Dzień i noc“"},{"id":"oc-plws-451174","title":"Mazurek „Toinon” (Layered roasted-almond meringue Easter cake)","cuisine":"European","category":"Cake","ingredients":["600 g sweet almonds (blanched, lightly roasted, and finely ground, orig. 60 dag)","600 g icing sugar (orig. 60 dag)","8 egg whites (whipped to stiff peaks)","2 communion-style wafer sheets (for the two thin layers)","200 g butter (orig. 20 dag sweet-cream butter)","200 g icing sugar (orig. 20 dag)","200 g sweet almonds (blanched, roasted, and finely ground, orig. the remaining 20 dag)"],"steps":["Lightly roast all the blanched almonds (800 g in total) in a dry pan or oven until golden, grind finely in a nut mill, and divide into two unequal portions: 600 g and 200 g.","Fold 600 g of the ground almonds with 600 g of icing sugar and the stiffly whipped whites of 8 eggs, spread over two wafer sheets, and bake two thin layers in an oven preheated to 160 °C for about 25–30 minutes, then cool.","Beat the softened butter until fluffy and mix with 200 g of icing sugar and the remaining 200 g of ground almonds.","Sandwich the cooled almond layers with the almond buttercream, press under a board and weight, and leave in a cool place overnight so the layers bond firmly."],"time":545,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Mazurek_%E2%80%9EToinon%E2%80%9C","page":"Ciasta wielkanocne/Mazurek „Toinon“"},{"id":"oc-plws-568709","title":"Melon dried in sugar","cuisine":"European","category":"Preserve","ingredients":["500 g green half-ripe melon (peeled and cut into square pieces, orig. half a kilogram)","1000 g sugar (750 g for the syrups over several days (500 g + 250 g), plus 250 g for the thick glaze for drying)","750 ml water (for the syrups, plus water for softening and shocking the melon)"],"steps":["Peel a green half-ripe melon, cut out the centre, and cut the flesh into neat square pieces. Cover them with cold water and heat slowly until just soft, then drain them on a sieve, rinse them with cold water, and drain them (you may cover them the first night with a light syrup, which you pour off in the morning).","On the second day, cook a fresh syrup from 500 g of sugar and 300 ml of water, cover the melon with the hot syrup, and leave it for a day.","On the third day, pour off the syrup, add 250 g of sugar, bring it to the boil, and cover the melon with the boiling syrup. On the fourth day, boil the syrup together with the melon a few times and cool it.","To dry the fruit, lift the pieces onto a sieve to drain. Cook a very thick syrup from the remaining 250 g of sugar to the thread stage, add the melon, bring it to the boil once, cool it while stirring with a spoon, and lift the pieces onto a platter to dry."],"time":45,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Melon_suszony_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Melon suszony w cukrze"},{"id":"oc-plws-552226","title":"Melon ice","cuisine":"European","category":"Dessert","ingredients":["500 g ripe melon flesh (scooped out and rubbed through a sieve, orig. half a kilogram)","500 g sugar (orig. half a kilogram)","1 l water (orig. 1 litre)","2 lemons (the squeezed juice)"],"steps":["Cut a ripe, fragrant melon in half, remove the seeds, and rub the flesh through a sieve, measuring out 500 g of purée.","Bring a syrup to the boil from 500 g of sugar, 1 litre of water and the juice of two lemons, then cool it completely.","Combine the cold syrup with the melon purée, rub the whole thing through a sieve once more, pour it into an ice-cream maker, and freeze it (about 2–3 hours)."],"time":190,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_melonowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody melonowe"},{"id":"oc-plws-544476","title":"Melon jam with rum","cuisine":"European","category":"Preserve","ingredients":["500 g half-ripe melon (peeled and seeded, orig. half a kilogram of raw melon)","1000 g sugar (orig. 1 kilogram)","375 ml water (orig. 1.5 small glasses for the syrup, plus water for the brief cooking and iced water for shocking)","50 ml rum (for sprinkling the melon generously)"],"steps":["Peel a half-ripe melon, cut out the seed cavity, and cut the flesh into neat long square pieces about the size of small apple quarters.","Put the melon into a pot, cover it with cold water, and cook for about 10 minutes until just soft (do not let it fall apart). Then drain it in a colander, rinse it several times with iced water, and leave it for 60 minutes to drain.","Pack the drained melon tightly on a platter, sprinkle it generously with good rum, and leave it for 3 hours.","Bring a thick syrup to the boil from 1 kg of sugar and 375 ml of water, add the melon and the rum, and cook first over a higher heat and then over a lower and lower heat, skimming, until the syrup thickens. Once cool, pack it into jars."],"time":305,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Melon","page":"Doświadczone sekreta smażenia konfitur i soków/Melon"},{"id":"oc-plws-544480","title":"Melon jam, another way","cuisine":"European","category":"Preserve","ingredients":["500 g half-ripe melon (peeled and cut into square pieces, orig. half a kilogram)","1000 g sugar (1 kg in all: 500 g on the first day, 250 g on the second and 250 g on the third)","500 ml water (for the syrup, plus boiling water for the brief cooking)"],"steps":["Peel a half-ripe melon, remove the seed cavity, cut the flesh into square pieces, drop them into boiling water, and bring it once to a hard boil (do not let them fall apart). Then drain them and put them in a bowl.","Cook a fairly thick syrup from 500 g of sugar and 350 ml of water, cover the melon with the warm syrup, and leave it for 24 hours.","On the second day, pour the syrup off through muslin, add 250 g of sugar, bring it to the boil, and cover the melon with the hot syrup for another day.","On the third day, pour off the syrup again, add the remaining 250 g of sugar, boil it until thick, drop the melon into the boiling syrup, bring them to the boil once together, and once cool pack them into jars."],"time":35,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Melon_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Melon innym sposobem"},{"id":"oc-plws-544482","title":"Melon jam, Bukovina way","cuisine":"European","category":"Preserve","ingredients":["500 g half-ripe melon (peeled and cut into pieces, orig. half a kilogram)","15 g slaked food-grade lime (calcium hydroxide for the bath that firms the fruit, orig. half a handful per 1 melon)","2 l water (for soaking, rinsing, the brief boil, and the syrup)","1000 g sugar (orig. 1 kilogram (750 g for the first syrup and 250 g on the third day))","1 lemon (the squeezed juice)","30 ml rum (orig. 1 small glass)"],"steps":["Peel a fleshy half-ripe melon, remove the seed cavity, cut the flesh into neat pieces, and soak them for 12 hours in water with 15 g of slaked food-grade lime.","Take out the pieces, rinse them very thoroughly in several waters, then soak them in clean cold water for 2 days, changing the water several times. After that, cover them with fresh cold water, bring it to the boil once, drain them on a sieve, and cool them.","Cook a syrup from 750 g of sugar and 350 ml of water, add the cooled melon, bring it to the boil once, and leave it in the syrup for 24 hours.","For the next 2 days, take the pieces out each day, prick them densely with a wooden toothpick, and put them back into the strained, reboiled syrup.","On the third day, take out the melon, add the remaining 250 g of sugar, the lemon juice and a small glass (30 ml) of rum to the syrup, boil it until thick, put the melon back in, bring it once to a good boil, and once cool pack it into jars."],"time":45,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Melon_bukowi%C5%84skim_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Melon bukowińskim sposobem"},{"id":"oc-plwb-18846","title":"Migdałowy pischinger (almond chocolate wafer cake)","cuisine":"European","category":"Cake","ingredients":["10 wafer sheets (round)","1 tbsp butter","150 g sugar","150 g almonds (coarsely chopped)","to taste chocolate leaves (for decoration)","to taste vegetable oil (for greasing foil)","150 g dark chocolate","200 g butter","250 ml milk","4 tbsp vanilla pudding powder","80 g granulated sugar (granulated)","80 g powdered sugar"],"steps":["Melt 1 tablespoon of butter in a saucepan, add 150 g of sugar, simmer for about 10 minutes while stirring, then add the chopped almonds.","Spread the hot almond mixture over aluminium foil greased with vegetable oil, let cool, place between two sheets of baking paper, and crush with a rolling pin.","Mix 2 tablespoons of milk with the vanilla pudding powder, pour into the remaining milk brought to a boil with 80 g of sugar, cook briefly until thickened, and let cool.","Melt the dark chocolate in a water bath and let it cool slightly.","Beat 200 g of butter with the powdered sugar, add a spoonful at a time to the cooled pudding, and finally stir in the melted chocolate.","Set aside one-third of the cream, and use the rest to sandwich the wafer sheets, stacking them on top of each other.","Spread half of the reserved cream over the top and sides of the torte, coat with the crushed almond brittle, and pipe rosettes along the border with the remaining cream, decorating with chocolate leaves."],"time":55,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Migda%C5%82owy_pischinger","page":"Książka kucharska/Migdałowy pischinger"},{"id":"oc-plwb-62615","title":"Minced beef skewers (Szaszłyki z mielonej wołowiny)","cuisine":"European","category":"Main","ingredients":["800 g minced beef (or beef and pork blend)","1 onion (large, very finely chopped)","3 clove garlic (pressed)","1 egg","3 tbsp breadcrumbs","2 tbsp vegetable oil (plus extra for brushing the grill)","1 tsp dried thyme","1 tsp dried rosemary","1 tsp sweet paprika","0.5 tsp hot paprika (optional)","1 tsp salt","0.5 tsp black pepper (freshly ground)","200 g button mushrooms (small, cleaned)","19 cherry tomatoes (18–20)","to taste fresh sage (or parsley leaves, for serving)"],"steps":["In a large bowl, combine the minced beef, very finely chopped onion, pressed garlic, egg, breadcrumbs, 2 tablespoons of oil, thyme, rosemary, sweet and hot paprika, salt, and pepper.","Knead the mixture for several minutes until sticky and homogenous, then chill in the refrigerator for 30 minutes (in the meantime, soak wooden skewers in water for 20 minutes).","Clean and dry the button mushrooms (halving any larger ones), and wash and dry the cherry tomatoes.","Shape the meat mixture into elongated rolls or balls and thread them onto skewers, alternating with the button mushrooms and cherry tomatoes.","Preheat the grill or grill pan, brush the surface with a little oil, and grill the skewers for 12–15 minutes, turning frequently, until the meat is cooked through and the vegetables are browned.","Rest the cooked skewers for 3 minutes, sprinkle with chopped sage or parsley leaves, and serve hot."],"time":68,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szasz%C5%82yki_z_mielonej_wo%C5%82owiny","page":"Książka kucharska/Szaszłyki z mielonej wołowiny"},{"id":"oc-plws-546687","title":"Minced Ruffe Fish Cutlets","cuisine":"European","category":"Main","ingredients":["600 g ruffe or other small freshwater fish (orig. 60 dkg)","100 g stale bread roll (orig. 10 dkg)","150 ml water (for soaking the roll)","2 potatoes (large, boiled and peeled)","1 egg (whole)","1 onion (large, grated)","60 g wheat or oat flour (orig. 6 dkg, for dredging the cutlets)","to taste salt","to taste ground black pepper","50 g vegetable oil (orig. 5 dkg, for frying)"],"steps":["Clean the ruffe thoroughly, cut off the heads and gills, and soak the bread roll in water and squeeze dry.","Pass the fish twice through a meat grinder, grinding it the second time together with the squeezed roll, boiled potatoes, and grated onion.","Beat in the egg, season the mixture with salt and pepper, and knead at length by hand until completely smooth and uniform.","Shape eight cutlets, dredge them in flour, and fry on both sides in hot oil until golden brown."],"time":55,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kotlety_z_jazgarzy","page":"109 potraw/Kotlety z jazgarzy"},{"id":"oc-plws-548313","title":"Mint gingerbread cookies (pierniczki miętowe)","cuisine":"European","category":"Cookie","ingredients":["450 g plain wheat flour (orig. 3 cups + extra for dusting baking sheet)","190 ml water (orig. 3/4 cup)","0.5 tsp baker's ammonia powder (ammonium bicarbonate)","100 g sugar (orig. 1/2 cup)","to taste peppermint oil (orig. 12 drops)"],"steps":["Knead the plain wheat flour, water, sugar, baker's ammonia, and peppermint oil into a uniform, smooth dough.","Shape the dough into balls the size of a small walnut (about 20–25 g), remembering that they expand significantly during baking.","Arrange the balls spaced apart on a baking sheet dusted with plain wheat flour and bake in an oven preheated to 180 °C for about 15 minutes until very lightly golden."],"time":35,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Pierniczki_mi%C4%99towe","page":"109 potraw/Pierniczki miętowe"},{"id":"oc-plws-550062","title":"Mint liqueur","cuisine":"European","category":"Drink","ingredients":["350 g fresh peppermint (orig. 35 dekagrams of fresh peppermint (or 25 dekagrams = 250 g of dried mint))","1.25 l spirit (orig. a quarter litre (250 ml) for soaking the mint, plus 1 litre poured into the cooled syrup)","1.25 kg sugar (orig. one and a quarter kilograms of crushed sugar)","750 ml water (orig. three quarters of a litre of cold water)","1.5 ml mint essence (orig. 30 drops of pharmacy-supplied mint essence (oil))","1 pinch food-grade chlorophyll (a few drops of spirit-soluble chlorophyll for colour (optional))"],"steps":["Soak 350 g of fresh peppermint (or 250 g of dried mint) in 250 ml of the best spirit for 24 hours.","The next day, bring a syrup of 1.25 kg of crushed sugar and 750 ml of cold water to the boil once, take it off the heat, and once it has cooled a little pour in 1 l of plain spirit, stirring all the time.","When the syrup and spirit are completely cold, add 250 ml of the spirit strained off the mint and 30 drops (about 1.5 ml) of mint essence (and, if you like, a few drops of spirit-soluble chlorophyll for a bright green colour).","Mix the liqueur thoroughly, immediately filter through paper, bottle, cork, seal with wax, and keep in a cool place for 6 months before serving."],"time":10,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_mi%C4%99towy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier miętowy"},{"id":"oc-plws-545138","title":"Mirabelle Plum Preserve","cuisine":"European","category":"Preserve","ingredients":["500 g ripe mirabelle plums (orig. half a kilogram)","1 kg sugar (half for the first syrup, the remainder for subsequent thickenings; orig. one kilogram)","to taste water (for soaking, blanching, cooling, and the syrup; amount not specified)"],"steps":["Prick each mirabelle plum with a wooden skewer and immediately place into cold water.","Drain the fruit.","Scald them with boiling water in a pot until softened.","Transfer the mirabelle plums to very cold water.","Cook a light syrup from 500 g of sugar and water.","Cool the syrup completely.","Drain the mirabelle plums and cover with the cold syrup, pressing the fruit down lightly so they are completely submerged.","Leave until the next day, for about 1440 minutes.","Remove the fruit, add part of the remaining sugar to the syrup, and bring it to a boil.","Cool the syrup until lukewarm, pour it over the fruit, and leave for another 1440 minutes or so.","Remove the fruit, boil the syrup with the rest of the sugar, and pour the hot syrup over the mirabelle plums.","Leave until the fourth day, for another 1440 minutes or so.","Simmer the mirabelle plums in the boiling syrup, taking care not to overcook them.","Pack the fruit tightly into jars, pour the syrup over them, and press down lightly so they remain submerged."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/%C5%9Aliwki_mirabelki","page":"Doświadczone sekreta smażenia konfitur i soków/Śliwki mirabelki"},{"id":"oc-plws-547346","title":"Mixed fruit pickled in wine vinegar","cuisine":"European","category":"Preserve","ingredients":["1.25 l wine vinegar (orig. one and a quarter litres of the best wine vinegar)","2 kg sugar (orig. 2 kilograms of sugar chopped into small pieces)","500 g sour cherries (łutówki) (orig. half a kilogram of red sour cherries)","5 g cloves (orig. half a deka of cloves)","10 g cinnamon (orig. 1 deka of cinnamon)","500 g apricots (orig. half a kilogram, halved and stoned)","500 g melon (cut into pieces)","500 g greengages (orig. half a kilogram of ripe greengages (optionally also bergamot or bonkreta pears, early transparent apples, and węgierka plums))","500 ml dry white wine (orig. half a litre of white French wine, to top up the syrup if needed)"],"steps":["Bring 1.25 l of the best wine vinegar to the boil with 2 kg of finely crushed sugar, pour it into an earthenware jar, and once completely cool add 500 g of red Łutówka sour cherries.","After 2 days, pour the syrup into a pan, add 5 g of cloves and 10 g of cinnamon, bring it to the boil, and pour it boiling over the cherries.","When apricots come into season, pour off the syrup from the cherries and cool it. Put 500 g of halved, stoned apricots into the cold syrup, bring it to the boil, and pour it hot over the cherries.","In the same way, as each fruit ripens, pour off and cool the syrup, add 500 g of cut melon and 500 g of ripe greengages (and, if you like, bergamot pears, summer early transparents and węgierka plums), bring it to the boil, and pour it over the fruit already in the jar. If there is not enough syrup, add 500 ml of dry white wine and boil them together."],"time":60,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_rozmaitych_mieszanych_owoc%C3%B3w_w_occie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z rozmaitych mieszanych owoców w occie"},{"id":"oc-plwb-14547","title":"Mięsne serduszka z brzoskwinią (breaded heart-shaped chicken cutlets with canned peach)","cuisine":"European","category":"Main","ingredients":["2 chicken breast fillet","400 g canned peaches (halves)","1 egg","to taste breadcrumbs (for breading)","to taste chicken seasoning","to taste vegetable oil (for frying)","to taste salt","to taste black pepper"],"steps":["Rinse and dry the chicken breast fillets, then gently pound them, shaping each cutlet like a heart.","Season the meat with salt, pepper, and chicken seasoning, then coat in the beaten egg and breadcrumbs.","Fry the breaded cutlets in heated vegetable oil on both sides until golden.","Place a drained canned peach half on top of each fried cutlet and serve hot."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mi%C4%99sne_serduszka_z_brzoskwini%C4%85","page":"Książka kucharska/Mięsne serduszka z brzoskwinią"},{"id":"oc-plwb-15765","title":"Mięso z owocami (braised chicken with fruit)","cuisine":"European","category":"Main","ingredients":["100 g chicken meat","100 g fresh fruit (any variety)","1 tsp butter (flat teaspoon)","to taste sugar","to taste salt"],"steps":["Clean, wash, and cut the fruit into pieces.","Melt the butter in a frying pan, add the cut fruit, and braise for about 15 minutes.","Cut the chicken meat into large cubes, add to the fruit in the pan, and braise together for a few more minutes until the meat is tender.","Season the dish to taste with salt and sugar."],"time":25,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mi%C4%99so_z_owocami","page":"Książka kucharska/Mięso z owocami"},{"id":"oc-plws-39060","title":"Mleczko (steamed egg custard)","cuisine":"European","category":"Dessert","ingredients":["10 egg (whole)","200 g sugar (orig. half a funt)","1 pinch vanilla (crushed (or 15 bitter almonds pounded with a little milk and squeezed through a cloth))","1.25 l single cream 12% (orig. misprinted as 5 kwarta (an obvious typesetting error for 5 kwaterka = 1.25 l of light cream or whole milk))","to taste fruit preserves (for garnishing before serving)"],"steps":["Beat 10 whole eggs thoroughly with 200 g of sugar and crushed vanilla (or almond milk squeezed through a cloth from 15 pounded bitter almonds).","Thin the egg mixture with light cream or whole milk and strain through a fine sieve into a pudding mould.","Set the covered mould in a pot of boiling water and steam (like a steamed pudding) for about 35 minutes, until a knife inserted into the centre comes out completely clean.","Remove the mould from the boiling water, place it in a vessel of cold water until completely chilled, and before serving unmould onto a platter and garnish with fruit preserves or serve with a cream sauce."],"time":110,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Mleczko","page":"365 obiadów za 5 złotych/Mleczko"},{"id":"oc-plwb-12744","title":"Modro kapusta (Silesian braised red cabbage with bacon)","cuisine":"European","category":"Side","ingredients":["1 red cabbage","1.5 onion","100 g smoked bacon (or other smoked meat)","2.5 tbsp vinegar (5%)","1 tsp sugar","to taste salt","to taste black pepper"],"steps":["Shred the red cabbage, boil until tender, and drain off any excess liquid.","Season the cooked cabbage with vinegar, sugar, salt, and pepper.","Finely dice the onion and smoked bacon, fry the bacon with the onion, and add to the cabbage.","Toss all ingredients together thoroughly before serving."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Modro_kapusta","page":"Książka kucharska/Modro kapusta"},{"id":"oc-plws-546715","title":"Molded Potato and Sheep Cheese Bake","cuisine":"European","category":"Main","ingredients":["1 kg potatoes","150 g onion (orig. 15 dkg, finely chopped)","2 tbsp vegetable oil or lard (for the mixture plus a little for greasing the mold)","50 g bryndza sheep cheese or green herb cheese (orig. 5 dkg)","to taste salt","2 tbsp grated dry bread or breadcrumbs (for coating the mold)"],"steps":["Peel the potatoes and cut them into very thin julienne strips.","Season the potatoes with salt and mix thoroughly with the finely chopped onion, oil or melted lard, and crumbled bryndza (or grated cheese).","Grease a baking mold with fat, coat with grated bread or breadcrumbs, and pack the potato mixture into the mold, pressing it down as firmly as possible.","Bake in a hot oven (200 °C) for 60 minutes, then unmold onto a platter and serve hot."],"time":85,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kartofle_wypiekane_z_formy","page":"109 potraw/Kartofle wypiekane z formy"},{"id":"oc-plwb-15331","title":"Morelowy przysmak (apricot two-layer cake with almonds)","cuisine":"European","category":"Cake","ingredients":["150 g wheat flour","100 g butter","1 egg","1 pinch salt","200 g wheat flour","125 g butter","100 g sugar","16 g vanilla sugar (1 packet)","2 egg","1 tsp baking powder","500 g apricots","4 tbsp apricot jam","2 tbsp almond flakes","to taste margarine (for greasing the pan)"],"steps":["Quickly knead a shortcrust pastry from 150 g of wheat flour, 100 g of butter, one egg, and salt, wrap in plastic wrap, and chill in the refrigerator.","Wash the apricots, cut in half, and remove the pits.","Beat 125 g of butter with the sugar, vanilla sugar, and two eggs until fluffy, then gradually add 200 g of wheat flour mixed with the baking powder, beating continuously.","Grease the bottom and sides of a 26 cm springform pan with margarine, line the base with the rolled-out shortcrust pastry, and spread the batter on top.","Smooth the top with a knife, arrange the apricot halves while pressing them gently into the batter, and bake for about 60 minutes in an oven preheated to 200 °C, then transfer to a platter and cool.","Warm the apricot jam in a saucepan over low heat, stirring until liquefied, brush it over the top of the cake, and sprinkle with almond flakes."],"time":95,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Morelowy_przysmak","page":"Książka kucharska/Morelowy przysmak"},{"id":"oc-plwb-19930","title":"Morszczuk duszony (braised hake with apples, tomatoes and white wine)","cuisine":"European","category":"Main","ingredients":["700 g hake fillet","200 g tomatoes","250 g apples","150 ml dry white wine","1 tbsp parsley leaves (chopped)","0.5 lemon (juice)","4 tbsp wheat flour","50 ml vegetable oil","to taste salt","to taste black pepper"],"steps":["Wash and gently dry the hake fillets, drizzle with the juice squeezed from the half lemon, season with salt and pepper, and set aside in a cool place for 2 hours.","Cut each apple into eight wedges and remove the cores, then scald, peel, and chop the tomatoes.","Dredge the marinated fillets in wheat flour and fry on both sides in heated vegetable oil until golden.","Arrange the apple wedges and tomatoes around the fish in the pan, pour in the dry white wine, and braise covered over low heat for 5–10 minutes.","Sprinkle the finished dish with chopped parsley leaves before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Morszczuk_duszony","page":"Książka kucharska/Morszczuk duszony"},{"id":"oc-plws-40795","title":"Mostek barani z ryżem (breast of mutton with rice)","cuisine":"European","category":"Main","ingredients":["800 g breast of mutton (cut into pieces after parboiling)","1 bunch soup vegetables (for cooking the breast)","1 onion (whole, for the stock)","to taste salt","1.5 l water (for cooking the breast and stock)","200 g rice (orig. half a funt)","3 tbsp butter (part for braising the rice and part for browning the shallots)","6 shallot (whole, lightly browned in butter)"],"steps":["Wash the breast of mutton, place it in a pot of water, bring to a boil and skim. Add the soup vegetables, whole onion and salt, then cook until the meat is partially tender.","Scald the rice with boiling water, rinse with cold water, and drain.","Melt a piece of butter in a saucepan, add the rice, moisten with strained mutton broth, and braise over low heat until the grains swell slightly.","Cut the half-cooked breast of mutton into pieces, add them to the rice, and continue braising together, gradually moistening with mutton broth (you may also add a few small onions).","Transfer the meat and rice to a serving platter and pour butter with whole, lightly browned shallots over the top."],"time":90,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Mostek_barani_z_ry%C5%BCem","page":"365 obiadów za 5 złotych/Mostek barani z ryżem"},{"id":"oc-plws-39674","title":"Mostek cielęcy nadziewany (stuffed breast of veal)","cuisine":"European","category":"Main","ingredients":["1.2 kg breast of veal (fatty, thick)","2 wheat roll (orig. 2 white rolls, with the crust grated off)","150 ml milk (warm, for soaking the rolls)","150 g fatback (orig. a quarter to half a funt (100–200 g) of fresh fatback)","1 onion (grated and scalded with hot water)","200 g calf's liver (orig. half a calf's liver, finely chopped)","100 g button mushrooms (fresh braised in butter or pickled)","3 tbsp butter (1 tbsp for the stuffing and approx. 2 tbsp for basting the roast)","3 egg (whole, for the stuffing)","1 pinch allspice (ground)","1 pinch mace (ground)","to taste salt","to taste black pepper"],"steps":["Soak the breast of veal for 60 minutes in cold water, rinse, pat dry, cut a pocket in it for stuffing, and rub with salt.","Grate the crust off 2 rolls and soak them in warm milk.","Chop the fresh fatback very finely and sweat it covered together with the grated and boiling-water-scalded onion so that they soften without browning.","Mix the sweated fatback and onion with the finely chopped calf's liver, mushrooms, soaked rolls, 1 tbsp of butter, 3 whole eggs, salt, pepper, allspice, and mace.","Fill the veal breast with the prepared stuffing and sew the opening shut.","Place the breast immediately into a hot oven preheated to 200 °C and roast for about 75 minutes, basting regularly with melted butter without adding water (alternatively, braise the breast in a casserole lined with slices of fatback)."],"time":165,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Mostek_ciel%C4%99cy_nadziewany","page":"365 obiadów za 5 złotych/Mostek cielęcy nadziewany"},{"id":"oc-plws-39688","title":"Mostek cielęcy z ryżem (breast of veal with rice)","cuisine":"European","category":"Main","ingredients":["800 g breast of veal (for 4 people)","1 bunch soup vegetables (for cooking the breast)","to taste salt","1.5 l water (for cooking the breast)","100 g rice (orig. a quarter funt of rice (for 4 people))","2 tbsp butter (1 tbsp for braising the rice and 1 tbsp for browning the breadcrumbs)","1 tbsp breadcrumbs (for browning in butter (or strong bouillon for pouring over))"],"steps":["Wash the breast of veal, parboil briefly and skim off the scum, then boil until tender with the soup vegetables and salt.","Scald the rice twice with boiling water, rinse with cold water, transfer to a saucepan, cover with strained veal broth, add 1 tbsp of butter, and braise covered until the grains are completely tender.","Place the sliced cooked veal breast into the hot rice so that it heats through thoroughly.","Arrange the meat on a platter alternating with the rice and pour strong reduced bouillon or butter with browned breadcrumbs over the top."],"time":75,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Mostek_ciel%C4%99cy_z_ry%C5%BCem","page":"365 obiadów za 5 złotych/Mostek cielęcy z ryżem"},{"id":"oc-plwb-21454","title":"Murzynek (Polish cocoa cake with coconut)","cuisine":"European","category":"Cake","ingredients":["300 g wheat flour (plus extra for dusting dried fruits and nuts)","4 egg","300 g sugar","3 tbsp cocoa powder","7 tbsp water","2 tsp baking powder","16 g vanilla sugar","250 g margarine (plus extra for the tin)","to taste dried fruit and nuts","to taste desiccated coconut (for sprinkling)","to taste breadcrumbs (for dusting the tin)"],"steps":["Place the margarine in a saucepan, add the sugar and cocoa powder, pour in the water, and bring to a boil while stirring until the ingredients dissolve.","Cool the cocoa mixture and set aside 125 ml of it for the glaze.","Add the eggs, wheat flour, baking powder, vanilla sugar, and flour-dusted dried fruit and nuts to the remaining mixture and stir thoroughly into a batter.","Grease a baking tin with margarine, dust with breadcrumbs, pour in the batter, and bake for about 40 minutes in an oven preheated to 180 °C.","Cool the baked cake, drizzle with the reserved cocoa glaze, and sprinkle with desiccated coconut."],"time":65,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Murzynek","page":"Książka kucharska/Murzynek"},{"id":"oc-plwb-18672","title":"Mushroom and root vegetable stew","cuisine":"European","category":"Main","ingredients":["150 g white button mushrooms","200 g carrots","100 g celeriac","100 g green beans","2 onions","1 tbsp butter (originally half a teaspoon)","250 ml vegetable broth (from 1 stock cube)","1 tbsp plain flour","to taste sweet ground paprika","to taste basil"],"steps":["Clean, peel, and rinse the mushrooms, carrots, celeriac, green beans, and onions, then chop everything into small pieces.","Melt the butter in a saucepan and saute the chopped onion.","Add the remaining vegetables and mushrooms, pour in the vegetable broth, and braise covered until tender.","Season the stew with basil and sweet paprika, and thicken with flour towards the end of simmering."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gulasz_z_pieczarkami","page":"Książka kucharska/Gulasz z pieczarkami"},{"id":"oc-plws-38756","title":"Mustard sauce for fish and kiełbasa (Polish sausage)","cuisine":"European","category":"Sauce","ingredients":["1 tbsp butter","1 tbsp plain wheat flour","250 ml meat bouillon or fish stock","1 tsp English mustard powder or hot mustard (heaping)","2 tbsp dry white wine","1 tbsp vinegar","1 tsp sugar","0.5 lemon (cut into thin slices)"],"steps":["Melt butter in a saucepan, stir in plain wheat flour, and cook into a golden roux.","Whisk the hot bouillon or fish stock vigorously into the roux until smooth.","Add the English mustard, white wine, vinegar, sugar, and lemon slices, bring to a boil and cook for a few minutes, then pour over cooked fish (pike-perch, sturgeon, or eel) or kiełbasa (Polish sausage)."],"time":15,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_musztardowy","page":"365 obiadów za 5 złotych/Sos musztardowy"},{"id":"oc-plws-580402","title":"Mędrzyki (Polish quark patties)","cuisine":"European","category":"Main","ingredients":["500 g farmer's cheese (twaróg) (fresh, mild)","2 eggs (whole)","to taste plain wheat flour (enough to work into a smooth dough)","to taste salt","1 tsp sugar","to taste butter (for frying)","to taste coconut oil (added to the butter for frying to prevent burning)","to taste sour cream (fresh, thick, for serving)"],"steps":["Pass the farmer's cheese through a mincer into a bowl.","Add the whole eggs, salt, sugar, and enough wheat flour to knead a smooth, pliable dough.","Shape the dough into round balls, flatten them with your palm, and press a dimple in the centre of each patty with your finger.","Heat the butter with a little coconut oil in a skillet and fry the mędrzyki for about 15 minutes on both sides until golden brown.","Serve hot with fresh, thick sour cream in a sauceboat."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/M%C4%99drzyki","page":"100 postnych i jarskich dań/Mędrzyki"},{"id":"oc-plws-580448","title":"Nadzienie z fasolki szparagowej do omletu (green bean and buttered breadcrumb omelette filling)","cuisine":"European","category":"Other","ingredients":["200 g green beans (green or yellow wax beans)","to taste salt (for boiling the green beans)","to taste butter (generous amount, for browning the breadcrumbs)","to taste breadcrumbs"],"steps":["String the green beans, drop them whole into boiling salted water, and boil for about 12 minutes until tender, then drain.","Melt a generous amount of butter in a skillet, add the breadcrumbs, and fry for 3 minutes until golden brown.","Toss the hot green beans with the butter-browned breadcrumbs and spoon the filling into an omelette."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Nadzienie_z_fasoli_zielonej","page":"100 postnych i jarskich dań/Nadzienie z fasoli zielonej"},{"id":"oc-plwb-30750","title":"Nalewka ajerkoniak (traditional Polish advocaat / egg liqueur)","cuisine":"European","category":"Drink","ingredients":["7 egg yolks","500 g icing sugar","440 ml boiled milk (chilled)","250 ml rectified spirit","to taste vanilla"],"steps":["Beat or whisk the egg yolks with the icing sugar and vanilla until smooth and fluffy.","Gradually pour in the cold boiled milk while continuing to whisk.","Add the rectified spirit in a slow thin stream, whisk until fully emulsified, and bottle the advocaat."],"time":15,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_ajerkoniak","page":"Książka kucharska/Nalewka ajerkoniak"},{"id":"oc-plwb-30751","title":"Nalewka ajerkoniak na 1 litr (steamed advocaat with brandy, 1-litre batch)","cuisine":"European","category":"Drink","ingredients":["8 egg yolks","500 ml sugar","375 ml milk","310 ml rectified spirit","50 g brandy (winiak)","to taste vanilla"],"steps":["Whisk the egg yolks with sugar over a double boiler until thick, pale, and ribbony.","Bring the milk and vanilla to a boil and slowly pour it into the whisked yolks, stirring constantly.","Cool the mixture, stir in the rectified spirit and brandy, mix thoroughly, and bottle the advocaat."],"time":30,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_ajerkoniak_na_1_litr","page":"Książka kucharska/Nalewka ajerkoniak na 1 litr"},{"id":"oc-plwb-30752","title":"Nalewka ajerkoniak na gęsto (thick homemade advocaat with powdered milk)","cuisine":"European","category":"Drink","ingredients":["500 ml vodka","7 egg yolks","375 ml icing sugar","4 tbsp milk","7 tbsp milk powder","to taste vanilla sugar"],"steps":["Whisk the egg yolks with icing sugar and vanilla sugar over a double boiler until pale and fluffy.","Whisk in the milk and milk powder until smooth, then let the mixture cool completely.","Slowly stream in the vodka while stirring constantly until uniformly smooth, then pour the liqueur into bottles."],"time":25,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_ajerkoniak_na_g%C4%99sto","page":"Książka kucharska/Nalewka ajerkoniak na gęsto"},{"id":"oc-plwb-30753","title":"Nalewka ajerkoniak pyszny (butter-enriched advocaat liqueur)","cuisine":"European","category":"Drink","ingredients":["6 egg yolks","200 g butter (fresh, softened)","500 ml icing sugar","500 ml vodka","to taste vanilla sugar"],"steps":["Beat the egg yolks with icing sugar and vanilla sugar until pale, fluffy, and voluminous.","Gradually beat in the softened butter one tablespoon at a time, continuing to whisk until completely smooth.","Slowly pour in the vodka, beating constantly until fully incorporated."],"time":15,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_ajerkoniak_pyszny","page":"Książka kucharska/Nalewka ajerkoniak pyszny"},{"id":"oc-plwb-30756","title":"Nalewka Fałszywy koniak (mock cognac infused vodka with prunes and tea)","cuisine":"European","category":"Drink","ingredients":["500 ml pure vodka","1 tbsp honey","2 tsp black tea (loose-leaf)","2 dried prunes"],"steps":["Pour the vodka into a bottle or jar, add the honey, loose black tea, and dried prunes, and stir.","Seal the container tightly and refrigerate for 14 days.","Filter the infusion through filter paper or a coffee filter and decant into a clean bottle."],"time":10,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_Fa%C5%82szywy_koniak","page":"Książka kucharska/Nalewka Fałszywy koniak"},{"id":"oc-plwb-18774","title":"Nalewka gruszkowa (spiced pear liqueur)","cuisine":"European","category":"Drink","ingredients":["2 kg pears","1.5 l rectified spirit","1.5 kg sugar","250 ml rum","1 pinch ground cloves"],"steps":["Wash the pears, chop them into pieces, blend, and chill for a few hours until the sediment settles to the bottom.","Carefully siphon the clear juice from above the sediment and pour it into a pot.","Add the sugar and heat over low heat, stirring continuously until completely dissolved.","Allow the pear syrup to cool, pour in the rectified spirit and rum, and season with ground cloves.","Pour the liquid into a demijohn, seal tightly, and age for 3 months, then filter again."],"time":40,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_gruszkowa","page":"Książka kucharska/Nalewka gruszkowa"},{"id":"oc-plwb-17829","title":"Nalewka Smocza Krew (Dragon's Blood raspberry liqueur)","cuisine":"European","category":"Drink","ingredients":["1.5 kg raspberries","1 kg sugar","1 l rectified spirit"],"steps":["Sort the raspberries, blend them, mix thoroughly with the sugar, and transfer the fruit puree to a large jar.","Cover the jar with cheesecloth and leave in a sunny spot for 2 days.","Pour in the rectified spirit, stir thoroughly, seal the jar, and after 3 days strain the liquid from the fruit.","Set the liquid aside for a week until the sediment settles to the bottom, then carefully filter the liqueur through a coffee filter.","Pour the clear liqueur into bottles, seal tightly, and age in a dark place for about 6 months."],"time":30,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_Smocza_Krew","page":"Książka kucharska/Nalewka Smocza Krew"},{"id":"oc-plwb-22024","title":"Naleśniki (basic Polish crepes)","cuisine":"European","category":"Main","ingredients":["2 eggs","125 ml water","125 ml plain flour","0.25 tsp salt","2 tbsp vegetable oil (for the batter and frying)"],"steps":["Crack the eggs into a bowl, pour in the water, and whisk together.","Gradually add the flour and salt while whisking continuously, until a smooth, lump-free batter with the consistency of sour cream forms.","Stir a splash of oil into the batter and refrigerate for 30 minutes.","Heat a thin film of oil in a frying pan and ladle in portions of batter, tilting the pan to coat the surface evenly.","Fry thin crepes on both sides until golden."],"time":50,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nale%C5%9Bniki","page":"Książka kucharska/Naleśniki"},{"id":"oc-plwb-17714","title":"Naleśniki z czereśniami (sweet cherry crepes)","cuisine":"European","category":"Dessert","ingredients":["500 ml milk","250 g plain flour","450 g sweet cherries","3 eggs","2 tbsp icing sugar","1 tbsp vegetable oil","1 tbsp butter (for frying)"],"steps":["Blend the milk with the icing sugar, flour, eggs, and oil into a smooth batter, cover, and refrigerate for 30 minutes.","Wash the sweet cherries, halve them, remove the stones, and drain slightly.","Fold the cherries into the batter and return the mixture to the refrigerator for another 30 minutes.","Grease a hot skillet with butter and fry thick crepes on both sides until golden brown."],"time":95,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nale%C5%9Bniki_z_czere%C5%9Bniami","page":"Książka kucharska/Naleśniki z czereśniami"},{"id":"oc-plws-42434","title":"Naleśniki z konfiturami, jabłkami lub serem (crêpes with preserves, apples or quark)","cuisine":"European","category":"Dessert","ingredients":["5 egg (5 egg yolks for the batter and 5 egg whites beaten into stiff peaks)","3 tbsp clarified butter (1 tbsp of cold butter for the batter and approx. 2 tbsp for frying and pan-browning)","250 ml wheat flour (orig. 1 Polish kwaterka (approx. 160 g))","1 pinch salt","500 ml milk (orig. half a Polish kwarta)","200 g fruit preserves (or plum butter, stewed apple marmalade with cinnamon, or fresh quark rubbed with butter, egg and raisins)","2 tbsp sugar (for sprinkling)","0.5 tsp cinnamon (for sprinkling)"],"steps":["Beat 5 egg yolks with 1 tbsp of cold clarified butter, 250 ml of wheat flour, and a pinch of salt, then gradually pour in 500 ml of milk, beating into a thin, pourable batter.","Just before frying, beat 5 egg whites into stiff peaks and gently fold into the crêpe batter.","Heat a frying pan until very hot, brush thinly with clarified butter, pour in portions of batter, and swirl quickly to coat the entire surface; fry briefly and stack the cooked crêpes on an upturned soup plate.","Spread each crêpe with fruit preserves, plum butter, apple marmalade, or sweetened quark filling, and fold into triangles or roll into cylinders.","Brown the folded crêpes on both sides in clarified butter until golden and serve sprinkled with sugar and cinnamon."],"time":40,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Nale%C5%9Bniki_z_konfiturami%2C_jab%C5%82kami_lub_s%C3%A9rem","page":"365 obiadów za 5 złotych/Naleśniki z konfiturami, jabłkami lub sérem"},{"id":"oc-plwb-19265","title":"Naleśniki z kwiatem akacji (acacia blossom crepes)","cuisine":"European","category":"Dessert","ingredients":["500 ml milk","4 eggs","200 g plain flour","1 tbsp sugar (level)","1 pinch salt","to taste black locust (acacia) blossoms","150 g margarine (for frying)"],"steps":["Whisk the milk with 2 whole eggs, 2 egg yolks, plain flour, sugar, and a pinch of salt into a smooth batter.","Rinse the acacia blossoms, drain them thoroughly, and fold into the batter.","Beat the remaining 2 egg whites to stiff peaks and gently fold them into the batter.","Melt margarine in a skillet and fry thin crepes about 2 mm thick on both sides until golden."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nale%C5%9Bniki_z_kwiatem_akacji","page":"Książka kucharska/Naleśniki z kwiatem akacji"},{"id":"oc-plwb-22118","title":"Naleśnikowy tort warzywny (savoury vegetable crepe cake)","cuisine":"European","category":"Main","ingredients":["8 cooked crepes","800 g canned chopped tomatoes (2 cans)","2 onions","6 clove garlic","1 leek","300 g semi-hard cheese","450 g frozen spinach (1 package)","to taste dried oregano","to taste salt","to taste black pepper","2 tbsp olive oil (for frying)"],"steps":["Finely chop one onion and 3 cloves of garlic, and sauté in heated olive oil.","Add the canned tomatoes, season with salt and pepper, simmer over low heat until the sauce is very thick, and stir in the oregano at the end.","Finely slice the leek, blanch it in boiling water until slightly softened, and drain.","Chop the remaining onion and garlic, cook gently with the spinach in a covered pan, and season with salt and pepper.","Grate the cheese, then layer the crepes in a springform tin alternately with spinach, tomato sauce, grated cheese, and leek, finishing with a crepe topped with sauce and cheese.","Bake in an oven preheated to 180 °C for about 10 minutes, until the cheese on top is fully melted."],"time":55,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nale%C5%9Bnikowy_tort_warzywny","page":"Książka kucharska/Naleśnikowy tort warzywny"},{"id":"oc-plwb-14148","title":"Napa cabbage salad with firm cheese (Sałatka z kapusty pekińskiej)","cuisine":"European","category":"Salad","ingredients":["0.5 napa cabbage (head)","1 chicory","1 cucumber","1 red bell pepper","0.5 leek","150 g firm cheese","to taste parsley leaves (chopped)","to taste lemon juice","5 tbsp vegetable oil","2 tbsp wine vinegar","2 clove garlic","1 tbsp basil","to taste sugar","to taste salt","to taste black pepper"],"steps":["Press the garlic through a garlic press and whisk together with the oil, wine vinegar, basil, a pinch of sugar, salt, and pepper.","Wash the vegetables, remove the core from the chicory, then finely shred the napa cabbage, chicory, and leek, and sprinkle with lemon juice.","Slice the cucumber into rounds, and cut the red bell pepper and firm cheese into dice.","Combine all the ingredients in a salad bowl, pour over the dressing, and scatter the chopped parsley leaves over the top."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_kapusty_peki%C5%84skiej","page":"Książka kucharska/Sałatka z kapusty pekińskiej"},{"id":"oc-plwb-18041","title":"Napa cabbage salad with walnuts and raisins (Sałatka z kapusty pekińskiej i orzechów)","cuisine":"European","category":"Salad","ingredients":["1 napa cabbage (small head)","200 ml mayonnaise","2 tbsp sour cream","1 tbsp pickled garlic (chopped)","100 g walnuts","50 g raisins"],"steps":["Whisk together the mayonnaise, sour cream, and finely chopped pickled garlic.","Wash and finely shred the napa cabbage, toss it with the dressing, and set aside for 30 minutes.","Chop the walnuts, add them to the salad along with the raisins, and mix thoroughly before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_kapusty_peki%C5%84skiej_i_orzech%C3%B3w","page":"Książka kucharska/Sałatka z kapusty pekińskiej i orzechów"},{"id":"oc-plws-1081046","title":"No-bake chocolate torte","cuisine":"European","category":"Cake","ingredients":["150 g chocolate (orig. a quarter funt for the mixture, plus 4 łuty for the glaze)","150 g sweet almonds (orig. a quarter funt for the mixture, plus 4 łuty for the filling)","215 g sugar (orig. half a funt for the mixture and 1 łyżka for the filling)","10 hard-boiled egg yolks (rubbed through a sieve)","1 wafer sheet (a round wafer for the base)","0.5 vanilla pod (pounded)","45 ml whipping cream (30%) (1 łyżka do nadzienia i 2 łyżki for the glaze)"],"steps":["Mix grated chocolate, blanched peeled ground almonds, sugar and hard-boiled yolks rubbed through a sieve. Knead it by hand into an even, pliable mass and divide it in two.","Lay a round wafer on a flat plate and spread and press half the chocolate mixture evenly over it with your hands.","For the filling, beat finely ground almonds with a spoonful of sugar, pounded vanilla and a spoonful of cream, and spread that layer on the chocolate base.","Cover with the second half of the chocolate mixture and smooth the top.","Melt the remaining chocolate in 2 spoonfuls of hot cream, pour it over the whole torte, and leave it in a cool place to set."],"time":45,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Torcik_czekoladowy%2C_robiony_bez_ognia","page":"Baby, placki i mazurki/Torcik czekoladowy, robiony bez ognia"},{"id":"oc-plwb-16566","title":"No-bake layered vanilla quark and jelly cake (Torcik bez pieczenia)","cuisine":"European","category":"Dessert","ingredients":["3 vanilla quark cheese (serek homogenizowany) (tubs)","2 yellow fruit jelly (packets)","2 red fruit jelly (packets)","to taste fresh fruit","1.5 l water (boiling, for dissolving the jelly)"],"steps":["Dissolve the first packet of jelly in 375 ml of hot water, cool, blend with one tub of vanilla quark, pour into a springform cake tin, and refrigerate until set.","Dissolve the second jelly of a different colour in 375 ml of water, cool, combine with the second tub of quark, pour over the set first layer, and chill again.","Prepare the third layer in the same way with another jelly and the third tub of quark, pour into the tin, and arrange fresh fruit on top.","Once the third layer has set, pour the fourth, cooled jelly dissolved in 375 ml of water over the fruit, and refrigerate the cake until completely set."],"time":260,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Torcik_bez_pieczenia","page":"Książka kucharska/Torcik bez pieczenia"},{"id":"oc-plwb-14551","title":"No-bake lemon biscuit dessert","cuisine":"European","category":"Dessert","ingredients":["250 g butter","400 g biscuits (tea cookies)","4 eggs","2 lemons","7 tbsp icing sugar","4 tbsp raisins","3 tbsp candied orange peel (finely chopped)","2 mandarins","1 tbsp almonds"],"steps":["Beat the butter with the icing sugar until pale and fluffy, then mix in the grated lemon zest.","Continuing to beat, add the egg yolks one at a time and pour in half of the juice squeezed from the lemons.","Pour boiling water over the raisins, drain them, and fold into the mixture along with the finely chopped candied orange peel and crushed biscuits.","Whip the egg whites to stiff peaks, gently fold them into the mixture, transfer the dessert to a bowl, cover, and chill in the refrigerator for about 120 minutes.","Before serving, decorate the top with mandarin segments and blanched, peeled almonds."],"time":30,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Deser_z_herbatnikami","page":"Książka kucharska/Deser z herbatnikami"},{"id":"oc-plwb-7899","title":"Nut and chocolate torte (Tort orzechowy z czekoladą)","cuisine":"European","category":"Cake","ingredients":["5 eggs","300 g nuts (finely chopped)","120 g icing sugar","1 lemon (squeezed juice of the whole lemon)","2 tbsp breadcrumbs (heaped, plus extra for dusting the tin)","to taste fat (for greasing the tin)","200 g dark chocolate (hard)","2 tbsp sweet cream","to taste nut halves or candied fruit (for decoration)","to taste whipped cream (for serving)"],"steps":["Preheat the oven to 160 °C, grease a medium springform cake tin with fat, and dust it generously with breadcrumbs.","Mix the finely chopped nuts with two heaped tablespoons of breadcrumbs.","Separate the egg yolks from the whites, beat the yolks with the icing sugar until pale and fluffy, and stir in the lemon juice.","Add the prepared nuts to the yolk mixture, top with the stiffly beaten egg whites, and gently fold together.","Transfer the batter to the springform tin and bake for 50–55 minutes, until the top is golden and the sides slightly pull away from the tin.","Leave the baked cake in the tin for a few minutes, then turn it out onto a board to cool completely.","Place the cooled torte on aluminium foil, pour over a thick glaze of dark chocolate melted with cream, decorate with nut halves or candied fruit, and serve with whipped cream."],"time":145,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tort_orzechowy_z_czekolad%C4%85","page":"Książka kucharska/Tort orzechowy z czekoladą"},{"id":"oc-plws-39668","title":"Nóżki cielęce osmażone w cieście (batter-fried calf's feet)","cuisine":"European","category":"Main","ingredients":["4 calf's feet (cleaned and soaked, with the large bone removed)","to taste water (for boiling the feet)","to taste salt","2 tbsp wheat flour (1 tbsp for dusting the feet and 1 tbsp for the batter)","2 egg (2 egg yolks beaten with flour and stiffly beaten whites from 2 eggs)","3 tbsp clarified butter (for frying)"],"steps":["Clean and soak the calf's feet, remove the large bones, and boil in salted water until completely tender.","Remove the tender feet, let cool slightly, split each lengthwise in half between the hooves, and dust the pieces with wheat flour.","Beat 2 egg yolks with 1 tbsp of wheat flour, beat 2 egg whites into stiff peaks, and gently fold together into a fluffy batter.","Dip the halved feet into the batter and fry in hot clarified butter until golden; serve with lettuce salad or a fruit sauce."],"time":150,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/N%C3%B3%C5%BCki_ciel%C4%99ce_osma%C5%BCone_w_cia%C5%9Bcie","page":"365 obiadów za 5 złotych/Nóżki cielęce osmażone w ciaście"},{"id":"oc-plws-39425","title":"Old Polish spiced beer and bread soup (Gramatka z piwa)","cuisine":"European","category":"Soup","ingredients":["1 l pale or dark beer (orig. 1 kwarta)","80 g stale bread (orig. a good handful, grated)","30 g raisins","1 tbsp butter","to taste cinnamon","to taste cloves"],"steps":["Grate the stale bread on a fine grater.","Pour the beer into a pot, add the grated bread, raisins, cinnamon, cloves, and butter.","Bring to a boil over medium heat, stirring for a few minutes until the bread softens and lightly thickens the soup, then pour into a tureen and serve hot."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Gramatka_z_piwa","page":"365 obiadów za 5 złotych/Gramatka z piwa"},{"id":"oc-plwb-7887","title":"Old Polish spicy egg sauce","cuisine":"European","category":"Sauce","ingredients":["4 hard-boiled eggs","3 lemons (large, juiced)","250 ml heavy cream (thick)","1 onion","1 tbsp parsley (heaped, chopped)","1 tbsp grated horseradish (heaped)","to taste salt","to taste icing sugar"],"steps":["Slice the hard-boiled eggs in half lengthwise, remove the yolks, and finely chop the egg whites.","Squeeze the juice from the lemons, discarding the seeds, then mash the yolks with the lemon juice in a bowl until smooth.","Add the thick cream a spoonful at a time, then stir in the onion mashed with a pinch of salt, the grated horseradish, chopped parsley, and icing sugar.","Add the chopped whites, mix again, adjust seasoning to taste if necessary, then wrap the dish in aluminium foil and refrigerate for a few hours (about 3 hours)."],"time":195,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_staropolski_pikantny","page":"Książka kucharska/Sos staropolski pikantny"},{"id":"oc-plws-546714","title":"Old Potatoes Cooked Like New Potatoes","cuisine":"European","category":"Side","ingredients":["800 g potatoes (orig. 80 dkg of large old potatoes)","1.5 l water (cold water for soaking overnight and water for boiling)","60 g lard or vegetable oil (orig. 6 dkg)","to taste salt","1 tsp fresh or dried dill","1 tsp fresh or dried flat-leaf parsley"],"steps":["Peel the large old potatoes and soak them overnight in cold water.","The next day, cut the potatoes into walnut-sized cubes and boil in plenty of salted water, taking care not to overcook them.","Drain the potatoes thoroughly, toss quickly with the hot lard or oil and chopped dill and parsley, and serve immediately."],"time":515,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kartofle_stare%2C_jak_m%C5%82ode","page":"109 potraw/Kartofle stare, jak młode"},{"id":"oc-plws-508365","title":"Omelette stuffed with creamed porcini mushrooms","cuisine":"European","category":"Main","ingredients":["6 eggs","250 g porcini mushrooms (fresh)","to taste butter (for braising the mushrooms and frying the omelette)","1 onion (finely chopped)","1 tsp plain wheat flour","2 tbsp sour cream","to taste salt"],"steps":["Clean and slice the porcini mushrooms, then braise in butter with the finely chopped onion for about 12 minutes until tender.","Dust the mushrooms with a teaspoon of wheat flour, stir in the sour cream, season with salt, and simmer for 2 minutes until a very thick sauce forms.","Beat the eggs with a pinch of salt, pour into a skillet with hot butter, and cook the omelette for about 5 minutes.","Spoon the hot creamed mushrooms over one half of the omelette, fold the other half over, and serve immediately."],"time":35,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Omlet_z_grzybami","page":"100 potraw z jaj/Omlet z grzybami"},{"id":"oc-plws-39685","title":"Omleciki czyli blinki bez drożdży (small omelette pancakes without yeast)","cuisine":"European","category":"Dessert","ingredients":["4 egg (4 egg yolks and stiffly beaten whites from 4 eggs)","1 pinch salt","250 ml wheat flour (orig. 1 Polish kwaterka of fine wheat flour (approx. 160 g))","1 tbsp sour cream 18% (sour cream or sweet cream)","3 tbsp clarified butter (or lard, for frying)","2 tbsp sugar (for sprinkling)","0.5 tsp cinnamon (for sprinkling)"],"steps":["Beat 4 egg yolks vigorously with a pinch of salt, add 250 ml of wheat flour, and stir in 1 tbsp of sour cream.","Beat 4 egg whites into stiff peaks and fold into the yolk mixture to form a fairly loose, fluffy batter.","Heat clarified butter or lard in a frying pan and drop the batter by the spoonful, 3–4 small pancakes at a time.","Fry the pancakes on both sides until golden brown, adding more fat to the pan as needed.","Arrange the hot pancakes on a platter, sprinkle with sugar mixed with cinnamon, and serve with fruit syrup, sour cream, or chaudeau sauce."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Omleciki_czyli_blinki_bez_dro%C5%BCd%C5%BCy","page":"365 obiadów za 5 złotych/Omleciki czyli blinki bez drożdży"},{"id":"oc-plws-39722","title":"Omlet biszkoptowy z konfiturami (sponge omelette with fruit preserves)","cuisine":"European","category":"Dessert","ingredients":["6 egg (6 egg yolks and stiffly beaten whites from 6 eggs)","4 tbsp sugar (3 tbsp for the batter and 1 tbsp for sprinkling)","2 tbsp wheat flour","1 tbsp butter (for the shallow pan)","150 g fruit preserves (or thick fruit syrup, for filling)"],"steps":["Beat 6 egg yolks with 3 tbsp of sugar until pale and fluffy, then stir in 2 tbsp of wheat flour.","Beat 6 egg whites into stiff peaks and carefully fold into the yolk mixture.","Heat the butter in a shallow ovenproof pan or skillet, pour in the egg mixture, and place in a hot oven (200 °C) for at most 20 minutes.","Transfer the baked omelette to a serving platter, spoon the fruit preserves onto one half, fold the other half over, and sprinkle the top with sugar."],"time":35,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Omlet_biszkoptowy_z_konfiturami","page":"365 obiadów za 5 złotych/Omlet biszkoptowy z konfiturami"},{"id":"oc-plwb-14981","title":"Omlet gruszkowy (sweet pear omelette)","cuisine":"European","category":"Dessert","ingredients":["4 pears","0.5 tsp butter","1 tbsp honey","2 eggs","2 tbsp breadcrumbs","2 tbsp water","to taste grated lemon zest","to taste salt"],"steps":["Peel the pears, cut them in half, core them, and slice into smaller pieces.","Melt the butter in a frying pan or wide saucepan, add the pears and honey, and braise for about 10 minutes.","Crack the eggs into a bowl, add the breadcrumbs, pour in the water, season with salt and lemon zest, and mix well.","Pour the egg mixture over the braised fruit and fry covered for about 10 minutes.","Flip the omelette over and cook uncovered for another 5 minutes."],"time":35,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Omlet_gruszkowy","page":"Książka kucharska/Omlet gruszkowy"},{"id":"oc-plwb-17002","title":"Omlet z serem i ziołami (cheese and herb omelette)","cuisine":"European","category":"Breakfast","ingredients":["4 eggs","8 tbsp plain flour","100 g semi-hard cheese (grated)","1 bunch chives (chopped)","4 tbsp water","2 tbsp vegetable oil (for frying)","to taste salt"],"steps":["Separate the egg yolks from the whites; in a saucepan, mix the yolks with salt and flour, and pour in the water.","Heat the mixture over low heat for about 15 minutes, until the batter thickens and puffs.","Beat the egg whites until stiff, then fold them into the batter along with the grated cheese and part of the chopped chives.","Heat oil in a frying pan and fry four pale golden omelettes.","Transfer the omelettes to plates, sprinkle with the remaining chives, and serve hot."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Omlet_z_serem_i_zio%C5%82ami","page":"Książka kucharska/Omlet z serem i ziołami"},{"id":"oc-plws-1081052","title":"Opaque White Royal Icing","cuisine":"European","category":"Sauce","ingredients":["400 g icing sugar (originally 1 funt)","4 egg whites (whites)","1 lemon (whole, freshly squeezed juice)","to taste arrack or rum (optional, for punch-flavored icing)"],"steps":["Place the sifted icing sugar and four egg whites in a bowl.","Beat the ingredients in one direction for at least 30 minutes (or whip with a mixer on low speed) until a snow-white, thick icing forms.","Add freshly squeezed lemon juice to taste (along with a little arrack if a punch flavor is desired) and mix thoroughly."],"time":30,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Lukier_zwyczajny_bia%C5%82y%2C_kredowy","page":"Baby, placki i mazurki/Lukier zwyczajny biały, kredowy"},{"id":"oc-plws-550061","title":"Orange and lemon liqueur “Luizan”","cuisine":"European","category":"Drink","ingredients":["8 malinówka oranges (whole, each studded with 2 cloves)","6 lemons (fine, whole, each studded with 2 cloves)","28 cloves (2 cloves stuck into each of 8 oranges and 6 lemons)","1 vanilla pod (a large pod)","1 cinnamon stick (1 stick of cinnamon bark)","4 l spirit (orig. 4 litres of the best spirit)","4.2 kg sugar (orig. 1 kilogram of finely crushed sugar for each of the 4 litres of spirit (4 kg), plus about 200 g for a light syrup for the 2-day rinse of the fruit)","2.5 l water (orig. half a litre of cold water for each of the 4 litres of spirit (2 l), plus about 500 ml for the light syrup)"],"steps":["Stud 8 malinówka oranges and 6 lemons with 2 cloves each (28 cloves in all). Pack them in an eight-litre demijohn with a wide neck, add 1 large vanilla pod and 1 cinnamon stick, cover them with 4 l of the best spirit, seal it, and leave it in the shade at room temperature for 2 weeks.","After 2 weeks, pour off the spirit and cover the fruit with a very light cold syrup of 200 g of sugar and 500 ml of water for 2 days, to draw out the rest of the alcohol (then pour this first light syrup off into lesser vodkas).","Cook the proper syrup from 4 kg of finely crushed sugar and 2 l of cold water (1 kg of sugar and 500 ml of water per litre of spirit), skim it carefully, take it off the heat after a single boil, and cool it completely.","Pour the strained citrus spirit a little at a time into the cold syrup, stirring constantly. Then filter it, bottle it, cork it, and leave it in a cool place for 8 months before serving."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_pomara%C5%84czowo_cytrynowy_%E2%80%9ELuizan%E2%80%9C","page":"Doświadczone sekreta smażenia konfitur i soków/Likier pomarańczowo cytrynowy „Luizan“"},{"id":"oc-plws-42461","title":"Orange Compote in Candied Peel Syrup (Kompot z pomarańczy)","cuisine":"European","category":"Dessert","ingredients":["4.5 orange (orig. 4–5 oranges, including thinly pared zest from 1 orange)","200 g sugar (orig. half a funt)","250 ml water (orig. 1 szklanka)"],"steps":["Wash and scald one orange, thinly pare off only the orange zest (without the white pith), and cut it into very fine julienne strips.","Boil the water and sugar in a saucepan into a thick syrup, add the strips of orange zest, and bring to a boil several times.","Peel all the oranges, divide them into segments while carefully removing all white pith, and arrange in a serving bowl.","Pour the hot syrup along with the cooked zest over the orange segments."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Komput_z_pomara%C5%84cz","page":"365 obiadów za 5 złotych/Komput z pomarańcz"},{"id":"oc-plws-39697","title":"Orange jelly","cuisine":"European","category":"Dessert","ingredients":["400 g sugar cubes (orig. 1 funt)","6 large oranges","4 lemons","1 l water (orig. 500 ml for the syrup + 500 ml for dissolving the gelatine)","37.5 g gelatine or isinglass (orig. 3 łuty)"],"steps":["Rub the sugar cubes on all sides against the scrubbed rind of 6 fresh oranges so the sugar absorbs the aromatic orange oil.","Pour 500 ml of water over the zested sugar and simmer over low heat, skimming off the foam.","Squeeze the juice of 4 lemons and the oranges through a fine sieve and bring to a boil with the syrup; you may reserve some oranges and separate them into segments to arrange in the jelly.","Dissolve the gelatine or isinglass in the remaining 500 ml of warm water, combine with the hot citrus syrup, and strain through a tightly woven cloth.","Pour the jelly into a mould (optionally arranging orange segments inside) and leave in a cool place for about 4 hours (240 minutes) until set."],"time":280,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Galareta_pomara%C5%84czowa","page":"365 obiadów za 5 złotych/Galareta pomarańczowa"},{"id":"oc-plws-550060","title":"Orange liqueur","cuisine":"European","category":"Drink","ingredients":["13 oranges (orig. 12 ripe malinówka oranges, peeled and divided into segments with the white pith and the seeds removed, plus the thick peel of 1 fresh orange)","1 l spirit (orig. 1 litre of the best spirit)","1 kg sugar (orig. 1 kilogram of sugar for the syrup)","500 ml water (orig. half a litre of water for the syrup)","250 ml pineapple syrup (orig. 1 szklanka of pineapple syrup)","250 ml rum (orig. 1 szklanka of the best rum)"],"steps":["Peel 12 ripe malinówka oranges carefully, remove the white bitter layer and the seeds, divide the flesh into segments in their thin membranes, put them in a demijohn, cover them with 1 l of the best spirit, and leave it in the shade for 3 weeks.","After 3 weeks, pour off the spirit, cover the orange segments with a cold syrup made from 1 kg of sugar and 500 ml of water, and leave it for 4 days.","After 4 days, pour off the syrup, mix it with the spirit set aside earlier, pour it back into the demijohn, add the thick peel of 1 fresh orange, and leave it for exactly 3 days.","Pour the liquid off the orange peel, add 250 ml of pineapple syrup and 250 ml of the best rum, mix well, filter it through paper, bottle it, cork it, and keep it in a cool place for 3 months before serving."],"time":10,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_pomara%C5%84czowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier pomarańczowy"},{"id":"oc-plws-546883","title":"Orange marmalade","cuisine":"European","category":"Preserve","ingredients":["3000 g ripe oranges (orig. 3 kilograms)","3 l water (for the day-long soak, and fresh water for the three-hour cooking)","3000 g sugar (fine, orig. 3 kilograms)","1 lemon (a juicy one, the juice squeezed through a sieve)"],"steps":["Wash and dry 3 kg of ripe oranges, slice them thinly, peel and all, discarding the seeds. Put them in an earthenware or enamel pot, cover them with water, and leave them covered for a full day (24 hours).","The next day, pour off the soaking water, transfer the orange slices to a wide pan, cover them with fresh water, and cook over low heat for 3 hours, carefully lifting out any seeds that float up.","Pour the liquor into a separate bowl, and mash the soft oranges in a bowl or blend them to a smooth mass.","Put the mashed oranges back in the pan, pour in the liquor you set aside, add 3 kg of fine sugar, and cook over low heat for about 1.5 hours, until the syrup is clear and thick.","Near the end, squeeze the juice of one juicy lemon through a sieve, mix, and pack the warm marmalade into scalded jars."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Marmolada_pomara%C5%84czowa","page":"Doświadczone sekreta smażenia konfitur i soków/Marmolada pomarańczowa"},{"id":"oc-plws-1081040","title":"Orange torte on shortcrust","cuisine":"European","category":"Cake","ingredients":["4 oranges (thick-skinned)","400 g sugar (orig. 1 funt)","15 g butter (orig. 1 łyżka)","200 g wheat flour (orig. half a funt flour)","100 g beef suet or butter (orig. a quarter funt of kidney suet or butter)","100 g sugar for the pastry (orig. a quarter funt)","1 egg","15 g butter for the tin"],"steps":["Cut the flesh out of the oranges and remove the seeds. Boil the peels in water until soft, drain them, and grate them to a smooth pulp.","Mix the peel pulp with the rubbed flesh, 400 g of sugar and a spoonful of butter, pour it into a saucepan, and cook over low heat for 1 hour until thick.","Knead a shortcrust from the flour, 100 g of fat (suet or butter), 100 g of sugar and the egg, and line the base and sides of a springform tin with it.","Bake the base in an oven heated to 180 °C until it is half done.","Spread the orange mixture on the half-baked base and finish baking at 170 °C for about 45 minutes."],"time":210,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Tort_pomara%C5%84czowy","page":"Baby, placki i mazurki/Tort pomarańczowy"},{"id":"oc-plws-1081053","title":"Orange Zest Sugar Paste and Glaze for Cakes","cuisine":"European","category":"Sauce","ingredients":["200 g sugar cubes (originally half a funt for one cake)","2 oranges (thick-skinned, for rubbing the sugar and squeezing the juice)","3 tbsp water","1 tbsp lemon or sour orange juice (for beating the glaze)"],"steps":["Rub the sugar cubes against the scalded, thick rind of the oranges until they are completely saturated with essential oils and turn yellow.","Pound the rubbed sugar in a mortar into a moist paste (which can be stored in an airtight glass jar).","To prepare the glaze for one cake, pour three tablespoons of water over 200 g of the orange sugar paste and boil to the thread stage (approx. 106–110 °C).","Pour the boiled syrup into a porcelain bowl, let cool, and beat with a pestle or spoon into a smooth glaze, adding lemon or sour orange juice a little at a time, then pour immediately over a sponge cake just taken from the oven."],"time":30,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Konserwa_pomara%C5%84czowa_do_tort%C3%B3w","page":"Baby, placki i mazurki/Konserwa pomarańczowa do tortów"},{"id":"oc-plwb-19273","title":"Oscypek smażony (pan-fried smoked highland sheep's cheese)","cuisine":"European","category":"Snack","ingredients":["1 Oscypek (smoked highland sheep's cheese)","1 tbsp butter","3 tbsp cranberry or cowberry preserve"],"steps":["Cut the Oscypek cheese into slices about 0.5 cm thick.","Heat the butter in a frying pan and fry the cheese slices on both sides until golden brown.","Arrange the hot Oscypek slices on a warmed serving dish and serve with cowberries or cranberries."],"time":10,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Oscypek_sma%C5%BCony","page":"Książka kucharska/Oscypek smażony"},{"id":"oc-plws-546633","title":"Oszczędne kotlety schabowe (thrifty breaded pork cutlets)","cuisine":"European","category":"Main","ingredients":["400 g boneless pork loin or leg (orig. 40 dkg)","1 tbsp plain wheat flour","60 g lard or vegetable oil (orig. 6 dkg (10 g for roux and 50 g for frying))","50 ml water (for thinning the roux)","100 g dry breadcrumbs or oat flour (orig. 10 dkg)","to taste salt"],"steps":["Slice the pork into 4 equal cutlets and pound vigorously with a mallet to prevent shrinking during frying.","Prepare a thick roux from the plain wheat flour, 10 g of lard or oil, and a splash of water as for a dense sauce, and let cool.","Coat the pounded cutlets with the roux paste and dredge in finely crushed breadcrumbs or oat flour.","Fry the cutlets in the remaining 50 g of hot lard or oil for about 4–5 minutes on each side until golden, salt after frying, and serve piping hot."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Sznycle_wieprzowe","page":"109 potraw/Sznycle wieprzowe"},{"id":"oc-plws-546632","title":"Oszczędne sznycle cielęce (thrifty veal schnitzels)","cuisine":"European","category":"Main","ingredients":["400 g veal schnitzel meat (orig. 40 dkg)","1 tbsp plain wheat flour","60 g lard or refined vegetable oil (orig. 6 dkg (10 g for roux and 50 g for frying))","50 ml water (for thinning the roux)","100 g dry breadcrumbs (orig. 10 dkg)","to taste salt"],"steps":["Cook a thick roux from the plain wheat flour, 10 g of lard or oil, and a splash of water as for a rich sauce, then let it cool.","Slice the veal into 4 equal cutlets, pound thoroughly with a meat mallet, and leave on a board for about 2 hours (120 minutes).","Just before frying, spread the cutlets thickly with the cooled roux and coat thoroughly in finely crushed breadcrumbs.","Fry in the remaining 50 g of moderately heated lard or oil for about 4–5 minutes on each side until golden. Season with fine salt immediately after frying."],"time":150,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Sznycle_ciel%C4%99ce","page":"109 potraw/Sznycle cielęce"},{"id":"oc-plws-42443","title":"Oszczędny i łatwy pasztet (economical and easy pâté)","cuisine":"European","category":"Main","ingredients":["2 hare forequarter (from 2 hares along with the heads)","14 quail (orig. 6–8 pairs of waxwings (nowadays quails or squabs))","500 g fatback (orig. 1 funt (400 g) of unsalted fatback for the forcemeat and approx. 100 g for larding the meat)","1 bunch soup vegetables (for the stock)","2 dried mushrooms (for the stock)","to taste spices (bay leaf, allspice, mace)","2 calf's liver (grated)","2 hare liver (grated)","3 onion (2 large onions half-baked in the oven for the forcemeat and 1 for the stock)","450 g butter (orig. 1 funt (400 g) of fresh butter for the forcemeat, approx. 35 g for roasting the hares and 1 tbsp (15 g) for the sauce)","4 wheat roll (round, with the crust grated off, soaked in milk and squeezed dry)","300 ml milk (for soaking the rolls)","0.5 clove garlic (grated (optional))","4 egg yolk","to taste salt","to taste black pepper","300 g puff pastry (for the rim and lid of the pâté)","50 g bouillon tablet (orig. 4 łuty of bouillon dissolved in 500 ml (half a kwarta) of hare stock)","1 tbsp wheat flour (for the sauce)","1 tsp lemon juice (for the sauce)","1 tsp capers (for the sauce)"],"steps":["Trim the sinews carefully from the hare forequarters, lard with fatback, salt, and roast in the oven while basting with butter, and fry the larded small birds over low heat in a skillet.","Simmer the bones, heads and trimmings from the hare forequarters with the soup vegetables, 1 onion, 2 dried mushrooms, bay leaf, allspice, mace and salt, reducing the stock to at most 500 ml (half a kwarta); remove the brains and pick the remaining meat from the bones, then pound them in a mortar.","Grate the calf's and hare livers, finely chop 400 g of unsalted fatback and 2 half-baked onions, place everything over 400 g of butter in a shallow pan, and bake uncovered in a moderate oven (160 °C) for 30 minutes, stirring frequently.","Combine the braised livers with the pounded hare meat, 4 milk-soaked, mashed, and squeezed rolls, salt, pepper, a pinch of mace, half a grated garlic clove, and 4 egg yolks, and knead the forcemeat thoroughly.","In a deep metal or ovenproof dish, alternate layers of forcemeat, pieces of roast hare with the larger bones removed, and roasted birds, finishing with a layer of forcemeat.","Place the pâté 60 minutes before serving into a moderate oven (170 °C); after 30 minutes cover the top with a puff-pastry lid and bake for another 15–30 minutes.","Dissolve 50 g of concentrated bouillon in the reduced hare stock, thicken with a roux of 1 tbsp of butter and 1 tbsp of flour, season with 1 tsp of lemon juice and 1 tsp of capers, and serve separately in a sauceboat."],"time":210,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Oszcz%C4%99dny_i_%C5%82atwy_pasztet","page":"365 obiadów za 5 złotych/Oszczędny i łatwy pasztet"},{"id":"oc-plwb-17001","title":"Oven-baked vegetables with breadcrumbs (Warzywa z piekarnika)","cuisine":"European","category":"Side","ingredients":["1 tsp butter (for greasing the baking sheet and topping)","150 g broccoli","1 cauliflower (small)","2 carrots","1 green courgette","1 yellow courgette","1 bunch fresh parsley","3 tbsp breadcrumbs","to taste salt","to taste pepper","500 ml water (for parboiling the vegetables)"],"steps":["Preheat the oven to 190 °C and grease a baking sheet with a little butter.","Divide the broccoli and cauliflower into florets, and slice the peeled carrots and rinsed courgettes into rounds.","Bring 500 ml of salted water to the boil in a pot, add the broccoli, cauliflower, and carrots, and simmer over low heat for 5 minutes, adding the courgette slices for the final minute.","Drain the vegetables, arrange them on the baking sheet, season with salt and pepper, sprinkle with breadcrumbs mixed with chopped fresh parsley, and dot with butter flakes.","Bake the vegetables for 30 minutes, turning them occasionally."],"time":51,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Warzywa_z_piekarnika","page":"Książka kucharska/Warzywa z piekarnika"},{"id":"oc-plwb-27934","title":"Owsianka z musem jabłkowym (rolled oat porridge with apple puree)","cuisine":"European","category":"Breakfast","ingredients":["250 ml rolled oats (jumbo oats)","250 ml milk","250 ml water","1 pinch salt","to taste apple puree (for serving)"],"steps":["Add the rolled oats to a saucepan, pour in the milk and water, and add a pinch of salt.","Cook over low heat, stirring occasionally, until the oats soften and absorb the liquid.","Spoon the porridge into a bowl and top with apple puree."],"time":15,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Owsianka_z_musem_jab%C5%82kowym","page":"Książka kucharska/Owsianka z musem jabłkowym"},{"id":"oc-plws-39706","title":"Ozór na szaro (beef tongue in Polish grey sauce)","cuisine":"European","category":"Main","ingredients":["1 beef tongue (approx. 1.2 kg)","1 bunch soup vegetables (for boiling the tongue)","to taste spices (bay leaf, allspice, black peppercorns)","to taste salt (for boiling the tongue)","2 l water (for boiling the tongue (plus a drop to moisten the sugar))","2 tsp sugar (orig. a couple of lumps of sugar, for caramel)","1 tbsp butter (for the roux)","1 tbsp wheat flour (for the roux)","125 ml vinegar (orig. half a szklanka)","60 ml red wine (or white)","1 tsp lemon peel","30 g raisins (orig. a handful of raisins and almonds)","30 g almonds (blanched and peeled)"],"steps":["Wash the tongue, parboil it in water until partially tender, remove it, and peel off the tough skin.","Return the peeled tongue to the pot, add the soup vegetables, spices, and salt, cover with fresh water, and boil until completely tender.","Moisten the sugar with a drop of water and caramelise it in a pan until dark, then add 1 tbsp of butter and 1 tbsp of wheat flour and fry briefly together.","Thin the roux with broth from the tongue, add 125 ml (half a szklanka) of vinegar, the wine, and lemon peel, bring to a boil, and strain the sauce through a sieve.","Add the thoroughly washed raisins and blanched, peeled almonds to the strained sauce.","Slice the tender tongue on the bias, place the slices in the sauce, and bring to a boil together before serving."],"time":170,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Oz%C3%B3r_na_szaro","page":"365 obiadów za 5 złotych/Ozór na szaro"},{"id":"oc-plws-39696","title":"Ozór z chrzanem do sztuki mięsa (cured beef tongue with horseradish, served with boiled beef)","cuisine":"European","category":"Main","ingredients":["1 beef tongue (approx. 1.2 kg)","40 g salt (for rubbing the tongue)","0.5 tsp potassium nitrate (nowadays curing salt can be used)","to taste water (for rinsing and boiling the tongue)","100 g horseradish (raw, grated, to serve)","2 tbsp vinegar (for seasoning the horseradish)"],"steps":["Clean the beef tongue thoroughly of slime and trim off excess gristle at the base without rinsing the meat in water.","Rub the tongue thoroughly with salt mixed with half a teaspoon of saltpetre, place in an earthenware or glass bowl, cover with a plate, and leave in a cool place for 10 days, turning the meat daily and rubbing it with the resulting brine.","After 10 days, rinse the tongue several times in cold water, place in a pot of water, and simmer for about 2.5 hours until completely tender.","Peel the skin off the hot tongue, cut the meat into diagonal slices, and serve alongside boiled beef with freshly grated horseradish seasoned with vinegar."],"time":150,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Oz%C3%B3r_z_chrzanem_do_sztuki_mi%C4%99sa","page":"365 obiadów za 5 złotych/Ozór z chrzanem do sztuki mięsa"},{"id":"oc-plws-548319","title":"Paluszki na soku owocowym (fruit syrup cookie sticks)","cuisine":"European","category":"Cookie","ingredients":["450 g plain wheat flour (orig. 3 cups)","150 g sugar (orig. 15 dkg)","2 eggs","1.5 tsp baking powder (orig. half packet baking powder)","to taste raspberry, currant, or strawberry fruit syrup (to achieve the right dough consistency)"],"steps":["Beat the eggs with the sugar until pale and fluffy.","Add the plain wheat flour mixed with the baking powder.","Gradually pour in enough raspberry, currant, or strawberry fruit syrup to knead a moderately soft, elastic dough, then knead it well.","Roll the dough into thin ropes and cut into pieces about 12 cm long.","Bake in an oven preheated to 180 °C for about 20 minutes until golden."],"time":45,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Paluszki_na_soku_owocowym","page":"109 potraw/Paluszki na soku owocowym"},{"id":"oc-plws-547951","title":"Pan-Fried Barley Groat Cakes","cuisine":"European","category":"Side","ingredients":["200 g barley groats (orig. 1 cup)","600 ml water (for cooking thick groats)","2 tbsp wheat flour (for dredging)","to taste salt","2 tbsp vegetable oil or lard"],"steps":["Cook the barley groats in salted water until thick.","Spread the hot groats on a platter in an even layer about 1 cm thick and leave to cool completely until firm.","Cut the chilled barley into even squares, dredge each piece in wheat flour, and fry on both sides in hot oil or lard until lightly browned."],"time":90,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kasza_j%C4%99czmienna%2C_sma%C5%BCona","page":"109 potraw/Kasza jęczmienna, smażona"},{"id":"oc-plws-546728","title":"Pan-Fried Braised Pumpkin Slices","cuisine":"European","category":"Side","ingredients":["600 g ripe pumpkin (orig. 60 dkg)","1 tbsp wheat flour (for dredging)","2 tbsp vegetable oil or lard (2 tablespoons of oil or 40 g (4 dkg) of lard)","to taste salt","1 bouillon cube (whole cube)","100 ml water (for dissolving the bouillon cube and adding liquid during braising)"],"steps":["Peel the pumpkin, remove the seeds and stringy pulp, and cut into even pieces about 1.5 cm thick.","Season the pumpkin pieces with salt and dredge them in wheat flour.","Slowly brown the pumpkin in hot oil or lard, then cover and braise until tender, adding hot water with the dissolved bouillon cube as needed."],"time":40,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Dynia_(bania)_sma%C5%BCona","page":"109 potraw/Dynia (bania) smażona"},{"id":"oc-plws-546739","title":"Pan-Fried Jerusalem Artichokes","cuisine":"European","category":"Side","ingredients":["500 g Jerusalem artichokes (orig. half a kg of tubers)","1 tbsp wheat flour (for dredging)","2 tbsp vegetable oil (for frying)","to taste salt","0.5 tsp sugar (orig. a small amount of saccharin for the cooking water)"],"steps":["Scrape the Jerusalem artichoke tubers clean and boil them until tender in salted water with a touch of sugar.","Remove the cooked tubers from the water, pat dry, and cut larger ones into thick slices.","Dredge the slices in wheat flour and fry in hot oil on both sides until golden brown."],"time":40,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Bulwa_sma%C5%BCona","page":"109 potraw/Bulwa smażona"},{"id":"oc-plwb-14404","title":"Pan-fried liver with rhubarb and apple sauce (Wątróbka z rabarbarem)","cuisine":"European","category":"Main","ingredients":["500 g liver","200 g rhubarb","100 g tart apples","2 onions (small)","1 tsp butter","2 tbsp wine vinegar","100 ml meat broth","1 tsp gravy","to taste salt","to taste pepper","3 tsp sugar","200 g cooking fat","to taste plain flour (for coating)","to taste fresh parsley (for garnish)"],"steps":["Peel the apples and onions and cut them into large dice, and cut the washed and trimmed rhubarb into one-centimetre pieces.","Add the onion and rhubarb to the melted butter, add the apples, pour in the meat broth and wine vinegar, and bring to the boil.","Thicken the sauce with a teaspoon of gravy, simmer over low heat for a minute, and season with salt, pepper, and sugar.","Coat the liver slices in flour, fry in the hot fat for 3 minutes on each side, season with salt and pepper, then serve drizzled with the rhubarb sauce and sprinkled with fresh parsley."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/W%C4%85tr%C3%B3bka_z_rabarbarem","page":"Książka kucharska/Wątróbka z rabarbarem"},{"id":"oc-plws-546697","title":"Pan-fried skewered small fish (rybki smażone na oleju)","cuisine":"European","category":"Main","ingredients":["500 g small freshwater fish (orig. 50 dkg)","2 tbsp plain wheat flour","45 g vegetable oil (orig. 4–5 dkg)","to taste salt"],"steps":["Thoroughly clean the small fish (for ruffe, cut off heads and gills), rinse, pat dry, and salt.","Thread the fish in groups of 6–8 onto thin wooden skewers and dredge in plain wheat flour.","Fry in well-heated vegetable oil for about 4–5 minutes per side until golden brown."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Rybki_sma%C5%BCone_na_oleju","page":"109 potraw/Rybki smażone na oleju"},{"id":"oc-plws-39704","title":"Pan-seared beefsteak in butter (Befsztyk wołowy)","cuisine":"European","category":"Main","ingredients":["450 g beef tenderloin, sirloin, or top rump (orig. 3 thick thumb-width slices)","30 g butter (orig. 1/2 tbsp for frying plus 3 pieces of butter for the plate)","to taste salt"],"steps":["Trim the beef carefully of any silverskin and fat and cut into 3 thick slices about 2.5 cm thick; do not pound the meat or salt it before searing.","Heat about 10 g of butter in a flat skillet until foaming briskly and lightly browned.","Lay the beef slices in the skillet spaced apart and sear over very high heat for about 3–4 minutes without moving them until browned underneath.","Turn the steaks carefully with a fork, salt the browned top immediately, and sear for another 3–4 minutes over high heat.","Transfer the meat to a warm plate topped with 3 pieces of fresh butter (about 20 g), salt the second side, and press gently with the flat of a knife so a little meat juice mingles with the butter.","Return the steaks to the hot skillet for a dozen or so seconds, then place them back on the plate with the butter juices and spoon the pan drippings over them. Total cooking time should not exceed 10 minutes."],"time":20,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Befsztyk","page":"365 obiadów za 5 złotych/Befsztyk"},{"id":"oc-plwb-16511","title":"Panczkraut (Silesian cabbage and mashed potatoes)","cuisine":"European","category":"Side","ingredients":["500 g white cabbage","to taste caraway seeds","500 g sauerkraut","500 g potatoes","100 g smoked fatback","1 onion","2 tbsp plain flour","3 tbsp pork rib broth","to taste salt","to taste black pepper","to taste liquid seasoning (Maggi type) (optional)"],"steps":["Shred the white cabbage and boil until tender with caraway seeds, and cook the sauerkraut in a separate pot.","Peel the potatoes, boil until tender, drain, and mash thoroughly.","Finely dice the smoked fatback, render it in a skillet, lightly fry the chopped onion in the rendered fat, and sprinkle with flour to make a roux.","Combine both cooked cabbages with the mashed potatoes in a large pot.","Add the fatback and onion roux and pour in the pork rib broth.","Season with pepper, salt, and optional liquid seasoning, and stir thoroughly."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Panczkraut","page":"Książka kucharska/Panczkraut"},{"id":"oc-plwb-18854","title":"Parówki nadziewane serem (cheese-stuffed bacon-wrapped frankfurters)","cuisine":"European","category":"Snack","ingredients":["8 frankfurters","150 g semi-hard cheese","2 tbsp mustard","8 slice smoked bacon (thin slices)","1 tbsp butter (melted)"],"steps":["Warm the frankfurters slightly, slit each lengthwise down the centre, and spread with mustard.","Cut the cheese into strips, tuck them into the slits, wrap each frankfurter with a slice of bacon, and secure with a toothpick.","Arrange the frankfurters on a baking tray, drizzle with melted butter, and bake for 10 minutes in an oven preheated to 200 °C, until the cheese melts and the bacon browns."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Par%C3%B3wki_nadziewane_serem","page":"Książka kucharska/Parówki nadziewane serem"},{"id":"oc-plwb-41025","title":"Pascha (traditional Polish Easter cooked quark dessert)","cuisine":"European","category":"Dessert","ingredients":["1 kg farmer's cheese (quark) (minced or sieved)","250 g sugar","5 eggs (large)","250 g butter (melted)","500 ml sour cream","0.5 vanilla pod (cut into 3–4 pieces)","250 g almonds (blanched and chopped)","125 ml candied lemon and orange peel (chopped)","125 ml raisins"],"steps":["Separate the egg yolks from the whites; beat the yolks with sugar until pale and fluffy, then mix in the sour cream.","Slowly stream in the cooled melted butter while whisking, then gradually beat in the sieved farmer's cheese.","Beat the egg whites until stiff and fold them gently into the cheese mixture along with the chopped almonds, candied peel, raisins, and vanilla pod pieces.","Transfer the mixture to a heavy-bottomed pot and heat over low heat, stirring constantly, until the first bubbles appear without letting it boil.","Remove the pot from the heat, fish out the pieces of vanilla pod, and allow the custard to cool, stirring regularly.","Spoon the mixture into a mold lined with cheesecloth, press with a weight, and chill in the refrigerator to drain and firm up."],"time":60,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pascha","page":"Książka kucharska/Pascha"},{"id":"oc-plwb-16992","title":"Pasta and feta salad (Sałatka z makaronem i fetą)","cuisine":"European","category":"Salad","ingredients":["300 g ham","300 g feta cheese","300 g pasta","1 red bell pepper","1 cucumber","0.5 canned sweetcorn (can, drained)","2 tbsp olive oil","to taste all-purpose seasoning, such as Vegeta","to taste salt","to taste black pepper"],"steps":["Cook the pasta in salted boiling water until al dente, drain, and let cool.","Wash and dry the bell pepper and cucumber, then cut them into dice along with the feta cheese.","Drain the canned sweetcorn, and slice the ham into strips or thin slices.","Toss all ingredients together in a large bowl, drizzle with olive oil, and season to taste with all-purpose seasoning, salt, and pepper."],"time":20,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_makaronem_i_fet%C4%85","page":"Książka kucharska/Sałatka z makaronem i fetą"},{"id":"oc-plwb-62521","title":"Pasta serowo‑czosnkowa (Polish cheese and garlic spread)","cuisine":"European","category":"Sauce","ingredients":["500 g hard cheese (preferably sharp)","300 ml mayonnaise","1 garlic (whole head)","3 tbsp boiled water (cooled, optional to thin)","to taste salt","to taste black pepper"],"steps":["Grate the cheese on the fine holes of a box grater and transfer to a bowl.","Peel the garlic cloves, pass them through a garlic press, and add to the grated cheese.","Add the mayonnaise and stir thoroughly until a uniform paste forms.","If needed, stir in cold boiled water one tablespoon at a time until the mixture reaches the consistency of very thick sour cream.","Season the spread with salt and pepper, then refrigerate for at least 60 minutes before serving."],"time":15,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pasta_serowo%E2%80%91czosnkowa","page":"Książka kucharska/Pasta serowo‑czosnkowa"},{"id":"oc-plws-42478","title":"Paszteciki do zupy (savoury pastries served with soup)","cuisine":"European","category":"Snack","ingredients":["250 ml sour cream 18% (orig. 1 Polish kwaterka of thick, not too sour cream)","500 ml wheat flour (orig. half a kwarta of flour (approx. 325 g))","1 egg (beaten with a little water, for brushing the pastries)","400 g boiled or roast beef (orig. 1 funt of boiled or roast meat)","100 g fatback (orig. a quarter funt of fresh fatback or butter (plus butter for the baking sheet))","1 onion (grated and scalded with boiling water)","1 tbsp meat broth","2 egg (raw, for the stuffing)","200 g calf's brain (or beef brain, parboiled in salted water, deveined and cut into large cubes)","to taste salt","to taste black pepper"],"steps":["Mix 250 ml of thick sour cream with 500 ml of wheat flour in a bowl with a spoon, then knead the dough on a pastry board.","Finely chop the boiled or roast beef, mix with melted fatback or hot butter, the grated and scalded onion, salt, pepper, and 1 tbsp of broth, let cool, and beat in 2 raw eggs.","Parboil the calf's or beef brain in salted water, remove the membranes, and cut into large cubes.","Pinch off pieces of dough the size of a large walnut, roll them into balls, flatten with your fingers, and roll out lightly into round discs.","Place a portion of the dark meat stuffing on each disc, top with a layer of cubed white brain, and pinch the edges of the dough together over the filling into a lengthwise scalloped ridge.","Arrange the pastries on a buttered baking sheet, brush with egg beaten with water, and bake in a very hot oven (220 °C) for 15–20 minutes until golden; serve hot with clear broth, bouillon, or borscht."],"time":70,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Paszteciki_do_zupy","page":"365 obiadów za 5 złotych/Paszteciki do zupy"},{"id":"oc-plws-42467","title":"Paszteciki postne (Lenten eggs and fish served in shells)","cuisine":"European","category":"Snack","ingredients":["6 egg","to taste salt","1.5 tbsp butter (1 tbsp of fresh butter for the scrambled eggs and half a tbsp for greasing the shells)","1 pinch chives (finely chopped (optional))","150 g smoked salmon (cut into thin strips (or anchovies, or smoked vendace or flounder))"],"steps":["Lightly beat 6 eggs with a pinch of salt.","Melt 1 tbsp of fresh butter in a small saucepan, pour in the eggs, and cook over low heat, stirring constantly, until a smooth, thick scramble forms; towards the end stir in a pinch of chopped chives.","Butter the baking shells and spoon a portion of scrambled eggs onto one side of each shell, arranging strips of smoked salmon or other smoked fish on the opposite side."],"time":15,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Paszteciki_postne","page":"365 obiadów za 5 złotych/Paszteciki postne"},{"id":"oc-plws-42454","title":"Paszteciki w kruchym cieście (shortcrust pastry tartlets)","cuisine":"European","category":"Snack","ingredients":["500 ml wheat flour (orig. half a kwarta (approx. 325 g))","200 g butter (orig. half a funt of fresh butter (plus extra for greasing the moulds))","1 egg","1 pinch salt (for the pastry (plus for salting the filling))","2 calf's brain (approx. 300 g)","1 bunch veal spinal marrow (orig. a bunch of veal spinal marrow (approx. 150 g))","1 tbsp butter (fresh, for the sauce)","0.5 tbsp wheat flour (for the sauce)","1 lemon (squeezed juice)","1 tbsp meat broth","1 pinch caster sugar (on the tip of a knife)","2 egg yolk (for thickening the sauce)","100 g button mushrooms (fresh braised in butter or small pickled)","0.5 bunch parsley leaves (fried in clarified butter, for sprinkling)","1 tbsp clarified butter (for frying the parsley leaves)"],"steps":["Knead a shortcrust pastry in a cool place from 500 ml of wheat flour, 200 g of butter, 1 egg, and a pinch of salt.","Roll out the pastry, line buttered fluted metal tartlet tins with it, and bake in a moderately hot oven (180 °C) for 15 minutes until golden, then unmould the shells.","Parboil 2 calf's brains and the veal spinal marrow, peel off the membranes, cut into pieces, and salt lightly.","Mix 1 tbsp of fresh butter with half a tablespoon of wheat flour in an unheated small saucepan. Squeeze in the juice of a whole lemon, add 1 tbsp of broth and a pinch of sugar, and bring to a boil, then thicken the sauce with 2 egg yolks.","Add the cut brains, spinal marrow, and butter-braised (or pickled) mushrooms to the finished sauce and stir gently.","Fill the baked shortcrust tartlet shells with the ragout, sprinkle the tops with parsley leaves fried in clarified butter, and place briefly in a warm oven to heat through."],"time":75,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Paszteciki_w_kruchem_cie%C5%9Bcie","page":"365 obiadów za 5 złotych/Paszteciki w kruchem cieście"},{"id":"oc-plws-42468","title":"Paszteciki w kąchach z łososia, węgorza lub szczupaka (salmon, eel or pike baked in shells)","cuisine":"European","category":"Snack","ingredients":["800 g salmon (orig. 2 funt of raw fish (salmon, eel or pike), or 1 funt (400 g) of boned fish)","1 bunch soup vegetables (for boiling the fish)","to taste salt (for boiling the fish)","1 l water (for boiling the fish and stock)","3 tbsp butter (1 large tbsp for the sauce and approx. 2 tbsp for greasing the shells and browning the breadcrumbs)","1 tbsp wheat flour","0.5 lemon (juice squeezed through a strainer)","1 tbsp capers (drained of vinegar (or 6 soaked and chopped anchovies))","3 tbsp breadcrumbs (for browning in butter)"],"steps":["Boil the fish (salmon, eel, or pike) in water with the soup vegetables and salt, let cool, bone carefully, and flake into small pieces with a fork.","Make a blond roux in a small saucepan from 1 large tbsp of butter and 1 tbsp of wheat flour, stirring constantly, and thin with strained fish cooking liquid into a smooth sauce.","Squeeze the juice of half a lemon through a strainer into the sauce, add 1 tbsp of drained capers (or 6 soaked, chopped anchovies), fold in the flaked fish, and mix thoroughly.","Spoon the fish mixture into buttered baking shells, top generously with breadcrumbs browned in butter, and place for 15 minutes in a preheated oven (180 °C) until heated through."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Paszteciki_w_k%C4%85chach_z_%C5%82ososia%2C_w%C4%99gorza_lub_szczupaka","page":"365 obiadów za 5 złotych/Paszteciki w kąchach z łososia, węgorza lub szczupaka"},{"id":"oc-plwb-21737","title":"Paszteciki z grzybami (baked mushroom pastries)","cuisine":"European","category":"Snack","ingredients":["300 g butter pastry dough for paszteciki (1 portion)","1 tbsp butter","1 tbsp plain flour","1 onion","12 dried mushrooms","2 tbsp sour cream 18%","2 tbsp breadcrumbs","to taste salt","to taste black pepper"],"steps":["Boil the dried mushrooms until tender, drain well, and finely chop.","Melt the butter in a skillet, add the finely chopped onion and flour, and sauté lightly.","Add the chopped mushrooms and sour cream, season with salt and pepper, cook until the filling thickens, and let cool.","Roll out the butter pastry, cut out small rounds or squares, spoon a portion of filling onto each, fold in half, and crimp the edges.","Sprinkle the pastries with breadcrumbs and bake in an oven preheated to 200 °C for 15–20 minutes."],"time":65,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Paszteciki_z_grzybami","page":"Książka kucharska/Paszteciki z grzybami"},{"id":"oc-plwb-21747","title":"Paszteciki z mięsem (beef-filled sour cream pastries)","cuisine":"European","category":"Snack","ingredients":["250 ml 18% sour cream (thick)","500 ml plain flour","500 g cooked or roasted beef","125 g butter (or pork fatback)","1 onion","1 tbsp broth","2 tbsp breadcrumbs (optional)","3 eggs (2 for filling, 1 for egg wash)","to taste salt","to taste black pepper"],"steps":["Mince the cooked beef in a meat grinder or chop it very finely, and mix with the melted butter.","Grate the onion, blanch it with boiling water, drain well, and add to the beef along with the broth and optional breadcrumbs.","Let the meat mixture cool, beat in 2 eggs, season with salt and pepper, and mix thoroughly.","In a bowl, mix the sour cream with the sifted flour, knead into a smooth dough on a pastry board, and divide into walnut-sized balls.","Flatten each ball and roll gently into a small round or oval disc.","Place a portion of filling onto each disc, fold in the sides, and pinch the edges firmly closed at the top.","Arrange the pastries on a buttered baking sheet, brush with beaten egg, and bake in an oven preheated to 200 °C for 15–20 minutes."],"time":60,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Paszteciki_z_mi%C4%99sem","page":"Książka kucharska/Paszteciki z mięsem"},{"id":"oc-plws-42479","title":"Paszteciki z mózgu w naleśnikach (breaded crêpe rolls with calf's brain filling)","cuisine":"European","category":"Snack","ingredients":["3 egg (for the crêpes)","250 ml milk (orig. 1 Polish kwaterka of milk, for the crêpes)","125 ml wheat flour (approx. 80 g, for the crêpes)","1 calf's brain (parboiled and cleaned (approx. 150 g))","2 tbsp butter (for the onion and braising the mushrooms)","1 onion (grated)","100 g button mushrooms (chopped and braised in butter)","2 tbsp meat broth (orig. a couple of tablespoons of broth)","0.5 lemon (squeezed juice)","1 egg yolk (for the stuffing)","1 egg (beaten, for breading)","4 tbsp breadcrumbs (for breading)","3 tbsp clarified butter (for frying the crêpe rolls and parsley leaves)","0.5 bunch parsley leaves (in small sprigs, fried in butter with the crêpes)","to taste salt","to taste black pepper"],"steps":["Fry thin crêpes from a batter made with 3 eggs, 250 ml of milk, wheat flour, and a pinch of salt.","Mash the parboiled calf's brain with a spoon or pestle, transfer to a small saucepan with the butter and grated onion, add the chopped butter-braised mushrooms, 2 tbsp of broth, the juice of half a lemon, salt, and pepper, and cook together briefly until thickened.","Let the filling cool slightly, beat in 1 egg yolk, and mix thoroughly.","Spread the crêpes with the filling, roll into cylinders (or overlap the crêpes side by side, lay a cylinder of filling across, roll up together, and cut into oblong logs), dip in beaten egg, and coat in breadcrumbs.","Fry the crêpe rolls in hot clarified butter until golden brown, tossing small sprigs of parsley into the pan towards the end, and serve sprinkled with the crisp fried parsley."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Paszteciki_z_m%C3%B3zgu_w_nale%C5%9Bnikach","page":"365 obiadów za 5 złotych/Paszteciki z mózgu w naleśnikach"},{"id":"oc-plws-42459","title":"Paszteciki z raków (crayfish-filled pastry cases)","cuisine":"European","category":"Snack","ingredients":["500 g puff pastry (or shortcrust butter pastry, for 20 bouchées)","20 crayfish (medium)","1 tbsp butter","1 tbsp wheat flour","2 tbsp sour cream 18% (sour)","1 tbsp dill (finely chopped)","2 egg yolk","to taste salt (for parboiling the crayfish and for the filling)","to taste black pepper"],"steps":["Parboil 20 medium crayfish in salted water, remove the meat from the tails and claws, and chop it finely.","Sauté the chopped crayfish meat in a small saucepan with 1 tbsp of butter and 1 tbsp of wheat flour.","Add 2 tbsp of sour cream, the chopped dill, salt, pepper, and 2 egg yolks, and heat over low heat, stirring, until the filling thickens.","Fill 20 baked puff-pastry shells with the filling and place briefly in the oven to heat through (or shape pastries from raw shortcrust butter pastry and bake in an oven preheated to 190 °C for about 15–20 minutes)."],"time":65,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Paszteciki_z_rak%C3%B3w","page":"365 obiadów za 5 złotych/Paszteciki z raków"},{"id":"oc-plwb-21740","title":"Paszteciki z rybą (puff pastry fish pasties)","cuisine":"European","category":"Snack","ingredients":["1 puff pastry (packet (about 350 g))","750 g white fish fillets","2 onions","1.5 tbsp butter","3 hard-boiled eggs","1 egg (raw, for egg wash)","to taste salt","to taste black pepper"],"steps":["Finely chop the fish and season with salt and pepper.","Chop the onions and fry in melted butter, then add the fish and sauté together for about 5 minutes.","Let the cooked fish and onion cool, chop finely, and combine with the finely diced hard-boiled eggs.","Roll out the puff pastry and cut out an even number of rounds with a glass, cutting a smaller hole in the centre of half of them using a small shot glass.","Brush the solid rounds with beaten raw egg, top with portions of fish filling, cover with the rounds with holes in the centre, and seal the edges firmly.","Bake the pasties in an oven preheated to 200 °C for 10–15 minutes until golden brown."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Paszteciki_z_ryb%C4%85","page":"Książka kucharska/Paszteciki z rybą"},{"id":"oc-plws-580054","title":"Pasztet jarski w kruczym cieście (layered vegetarian pie in shortcrust pastry)","cuisine":"European","category":"Main","ingredients":["800 g plain wheat flour (for the shortcrust pastry, plus a little extra for dusting the mushrooms)","400 g butter (for the shortcrust pastry, plus extra for the rice, mushrooms, and pumpkin)","to taste salt (for the pastry and filling)","to taste water (cold for the pastry and for boiling the rice)","200 g rice","2 tbsp tomato paste","to taste black pepper","500 g porcini mushrooms (fresh or canned)","1 onion (finely chopped)","to taste sour cream (for thickening the mushrooms)","4 eggs (hard-boiled)","500 g pumpkin (peeled, cut into finger-thick slices)","1 egg yolk (for brushing the top crust)"],"steps":["Quickly knead a shortcrust pastry from the wheat flour, butter, salt, and cold water; reserve one-quarter of the pastry for the top, and line the bottom and sides of a springform pan with the rest.","Boil the rice in water for 15 minutes until fluffy, drain, and mix with 1 tablespoon of melted butter, the tomato paste, salt, and pepper.","Slice the porcini mushrooms and chop the onion, cook them gently in butter for 15 minutes, then dust with a little wheat flour, stir in the sour cream, and bring to a boil until thick.","Boil the eggs hard for 10 minutes, cool, peel, and slice them, and cook the pumpkin slices gently in butter for 10 minutes until tender; let all the filling layers cool.","Preheat the oven to 220 °C and arrange alternating layers of rice, porcini mushrooms, pumpkin, and eggs in the pastry-lined pan until all the ingredients are used.","Cover the pie with the rolled-out reserved pastry, crimp the edges tightly, prick the top with a fork, and brush with the egg yolk.","Place the pie in the oven preheated to 220 °C and bake for 40 minutes until golden brown."],"time":120,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Pasztet_jarski","page":"100 postnych i jarskich dań/Pasztet jarski"},{"id":"oc-plws-42463","title":"Pasztet na zimno (cold meat terrine)","cuisine":"European","category":"Main","ingredients":["800 g roast beef (beef roasting joint; orig. 2 funt of beef for roasting)","800 g pork tenderloin (orig. 2 funt)","800 g roast veal (veal roasting joint; orig. 2 funt of veal for roasting)","400 g calf's liver (orig. 1 calf's liver)","3 tbsp butter (for braising or roasting the meats)","100 g dried mushrooms (orig. a quarter funt of boiled mushrooms along with their cooking liquid)","400 g fatback (orig. 1 funt of boiled fatback cut into small cubes)","4 calf's feet (boiled down in water to 500 ml (half a kwarta) of strong calf's-foot jelly stock)","2 l water (for boiling down the calf's feet and cooking the mushrooms)","0.5 tsp allspice (ground)","to taste black pepper","to taste salt"],"steps":["Braise the beef, pork tenderloin, veal, and calf's liver in a casserole, or roast them in a roasting pan, basting with butter. Then chop finely and pound in a mortar (or grind) into a smooth paste.","Boil 4 calf's feet in a separate pot, reducing the stock to about 500 ml (half a kwarta) of strong gelatinous stock. In another small pot, boil the mushrooms and chop them finely.","Boil the fatback until tender and cut it into small cubes.","Combine the pounded meats with the chopped mushrooms, diced fatback, salt, pepper, and allspice.","Pour in the calf's-foot jelly stock and the mushroom cooking liquid and mix very thoroughly (for a more festive version, you may add the meat from half a roasted hare or a few small game birds).","Pack the mixture into a mould or bowl, set in a cool place for several hours until completely firm, and before serving unmould onto a platter and cut into slices."],"time":480,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pasztet_na_zimno","page":"365 obiadów za 5 złotych/Pasztet na zimno"},{"id":"oc-plws-42506","title":"Pasztet na zimno z gęsi (cold goose pâté)","cuisine":"European","category":"Main","ingredients":["1 goose (fat, cleaned, along with the liver)","2 partridge","1 calf's liver (approx. 400 g)","2 tbsp butter (for braising the livers)","400 g fatback (orig. 1 funt of fresh fatback)","500 ml meat bouillon (orig. half a kwarta of bouillon made by dissolving a quarter funt (100 g) of good bouillon tablet)","1 clove garlic (grated)","1 pinch mace (ground)","to taste salt","to taste black pepper"],"steps":["Roast the cleaned goose and 2 partridges unstuffed in the oven, let cool, remove the meat from the bones, skin, and sinews, chop finely, and pound in a mortar.","Braise the calf's liver and goose liver separately while basting with butter, then cool and grate.","Boil 400 g of fresh fatback, let cool, and cut into small cubes.","Rub the pounded poultry meat and grated livers through a coarse sieve, moistening with 500 ml of strong, jelly-like bouillon.","Season the sieved mixture with salt, pepper, a pinch of mace, and the grated garlic clove, fold in the diced fatback, and mix thoroughly.","Pack the mixture into a mould and leave in a cool place until completely set; serve the sliced pâté with olive oil and vinegar."],"time":420,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pasztet_na_zimno_z_g%C4%99si","page":"365 obiadów za 5 złotych/Pasztet na zimno z gęsi"},{"id":"oc-plws-42438","title":"Pasztet w pyzie (pull-apart meat-filled yeast buns)","cuisine":"European","category":"Main","ingredients":["1 l wheat flour (orig. 1 kwarta of flour (approx. 650 g))","25 g fresh yeast (orig. 2 Polish łuty)","250 ml milk (orig. 1 Polish kwaterka)","4 egg (for the dough)","2 tbsp butter (for the dough)","100 g clarified butter (melted, for dipping the buns, pouring over in the casserole and greasing the pan)","2 tbsp breadcrumbs (for dusting the casserole)","400 g boiled or roast beef (or roast veal, chopped as finely as possible)","2 tbsp butter (generous amount, for the stuffing)","1 onion (large, grated)","3 tbsp breadcrumbs (orig. 1 handful, for the stuffing)","2 egg (whole, for the stuffing)","to taste salt","to taste black pepper"],"steps":["Make a sponge from 250 ml of warm milk, 25 g of fresh yeast and some of the wheat flour. Once it rises, pour in 4 beaten eggs and 2 tbsp of melted butter, add the remainder of the 1 litre of flour, knead thoroughly into a soft dough, and leave to rise.","Melt 2 heaped tbsp of butter in a frying pan, sauté a large grated onion in it, add the finely minced beef or veal, a handful of breadcrumbs, 2 eggs, salt, and pepper, and mix the stuffing thoroughly.","Pull off pieces of the risen dough, flatten them in your palm into rounds, place a portion of meat stuffing in the centre (you may fill some buns with plum butter), and seal into round buns.","Dip each bun in melted clarified butter and arrange them side by side in a casserole greased with butter and dusted with breadcrumbs, filling the vessel halfway up.","Pour the remaining melted butter over the arranged buns, leave to rise a second time, and bake in a well-heated oven (190 °C) for 45 minutes; unmould onto a platter before serving."],"time":135,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pasztet_w_pyzie","page":"365 obiadów za 5 złotych/Pasztet w pyzie"},{"id":"oc-plws-546631","title":"Pasztet z gołębi w naleśnikach (pigeon pie in crêpes)","cuisine":"European","category":"Main","ingredients":["2 pigeons with giblets (orig. pair of pigeons)","300 g Polish soup vegetables (włoszczyzna) (orig. soup vegetables as for broth)","2 l water (for cooking the broth and crêpes)","200 g pearl barley (orig. 1 cup)","200 g green peas (orig. 1 cup)","60 g fatback (orig. 6 dkg)","180 g plain wheat flour (orig. 1 cup (150 g) for crêpes and 2 tbsp (30 g) for the sauce)","1 egg","1 pork rind (fatback rind) (for greasing the skillet and baking dish)","20 g cooking fat for sauce (orig. 2 dkg)","50 g sour cream (orig. 5 dkg)","to taste salt","to taste pepper"],"steps":["Cook a rich broth from the pigeons and soup vegetables in about 2 l of salted water for about 60 minutes. Set aside 500 ml of clear broth for preparing the sauce.","Remove the cooked pigeons, separate the meat from the larger bones, and chop it along with the giblets into medium pieces.","Cook the pearl barley and green peas separately in salted water until tender, and slice the fatback into thin flakes.","Whisk a batter from 150 g of plain wheat flour, the egg, water, and a pinch of salt, and fry 12 very thin crêpes in a skillet rubbed with fatback rind.","Grease a shallow saucepan or springform tin with fatback rind and line the bottom and sides with crêpes. Arrange alternating layers of barley, pigeon meat and giblets, cooked vegetables, green peas, and fatback flakes, seasoning with salt and pepper.","Once filled, cover the top with the remaining crêpes and bake in an oven preheated to 180 °C for about 40 minutes until well browned.","Heat 20 g of fat, cook a roux with the remaining 30 g of plain wheat flour, whisk in 500 ml of the reserved broth, bring to a boil, and finish with the sour cream, salt, and pepper. Turn the baked pie onto a platter and serve with the white sauce."],"time":180,"servings":7,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Pasztet_z_go%C5%82%C4%99bi","page":"109 potraw/Pasztet z gołębi"},{"id":"oc-plwb-30864","title":"Pańska skórka (Warsaw two-tone honey-raspberry nougat candy)","cuisine":"European","category":"Dessert","ingredients":["2 egg whites","250 ml sugar","125 ml water","125 ml honey","1 tbsp vanilla sugar","1 tbsp raspberry juice (or food colouring)"],"steps":["Combine the sugar, honey, and water in a saucepan and simmer over low heat for about 20 minutes, until the syrup reaches 160–170 °C.","Beat the egg whites to stiff peaks, then pour in the hot syrup in a thin stream while whisking continuously, until the meringue is glossy and bright white.","Add the vanilla sugar and beat briefly to combine.","Spread half of the white nougat mixture into a tin lined with baking paper.","Stir the raspberry juice into the remaining mixture, spread the pink layer over the white, leave in a cool place until completely set, and cut into cubes."],"time":35,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pa%C5%84ska_sk%C3%B3rka","page":"Książka kucharska/Pańska skórka"},{"id":"oc-plws-555158","title":"Peaches in syrup","cuisine":"European","category":"Preserve","ingredients":["1 kg peaches (ripe but firm, unblemished)","750 g sugar (for a very thick syrup)","500 ml water (for cooking the thick syrup (plus warm water for blanching the peaches))"],"steps":["Choose ripe, sound peaches with no spots, prick each one with a wooden pin or a toothpick, and put them in a pan of warm water.","Heat the fruit over low heat until the water is steaming hard (do not let it boil) and the skin of a peach lifted out to test slips off easily.","Pour off the water, dry the peaches briefly on a sieve, and peel them at once before they firm up again (you may also leave the skins on). Leave the fruit whole or cut it in half and remove the stones.","Pack the peaches into jars and cover them with a very thick syrup made ahead from 750 g of sugar and 500 ml of water. Seal the jars tightly (originally they were tied with a bladder).","Stand the jars in a kettle or a tall pot of water and pasteurize for a good 30 minutes from the moment the water boils (or bake them in the oven). Once cool, store them in a cool place."],"time":70,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_brzoskwi%C5%84","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z brzoskwiń"},{"id":"oc-plws-544169","title":"Pears (Alternative Method)","cuisine":"European","category":"Preserve","ingredients":["500 g pears (medium-sized, half-ripe pears (bon chrétien, cukrówki, bergamoty, or panny varieties))","1.5 kg sugar (750 g for the first syrup and 250 g added on each of the 3 following days)","625 ml water (2.5 glassfuls for the syrup, plus cold and hot water for soaking and parboiling the pears)","2 lemon (juice of 1 lemon for the cold water and juice of 1 lemon for the syrup)"],"steps":["Peel the pears, leaving the stems intact, remove the cores from the bottom, and immediately place the fruit in cold water acidulated with the juice of 1 lemon.","Transfer the pears to a pan of hot water, cook until tender (until a straw passes easily through the fruit), and spread on a sieve to drain completely.","Make a syrup from 750 g of sugar and 625 ml (2.5 glassfuls) of water, skim, add the juice of the second lemon, let cool, and pour over the pears in a dish.","For the next three days, drain the syrup daily, strain through a fine sieve or muslin, add 250 g of sugar each day, boil and skim, and pour the progressively warmer syrup back over the pears.","On the fourth day, place the pears into the cooled syrup, bring to a single boil, skim, and once completely cooled, pack into dry jars."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki innym sposobem"},{"id":"oc-plws-568693","title":"Pears Dried in Honey, Stuffed","cuisine":"European","category":"Preserve","ingredients":["1 kg pears (large, of a choice variety, peeled and cored, with the peels reserved for the decoction)","750 ml water (for boiling the peels into 2 glasses (500 ml) of strained decoction)","250 ml honey (1 glass per 2 glasses of strained decoction)","100 g almonds (crushed, for the filling)","50 g candied citron or orange peel (finely crushed candied lemon peel or orange peel)","0.5 tsp cinnamon or vanilla (for the filling)","150 g fine sugar (for repeated dusting during drying)"],"steps":["Peel the large pears and neatly hollow out the cores, then cover the peels and cores with water in a pot and boil into a concentrated decoction.","Strain 500 ml (2 glasses) of the peel decoction, combine with 250 ml (1 glass) of honey, bring to a boil, and cook the pears in this syrup until tender, taking care that they do not fall apart.","Remove the pears onto a sieve to drain and cool, then stuff them with a mixture of crushed almonds, finely chopped candied citron or orange peel, and cinnamon or vanilla.","Boil down the remaining honey syrup until thick.","Dip the stuffed pears in the thick honey syrup, dust with fine sugar, and dry repeatedly in a lukewarm oven or in the sun; once completely cooled, pack into jars."],"time":300,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_suszone_w_miodzie%2C_nadziewane","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki suszone w miodzie, nadziewane"},{"id":"oc-plws-568694","title":"Pears Dried in Honey, Stuffed Another Way","cuisine":"European","category":"Preserve","ingredients":["1.5 kg pears (approx. 1 kg of large pears for stuffing plus 500 g of peeled pears for the filling and the peels for the decoction)","500 g apples (peeled, for the filling mixture)","300 g honey (cooled for the beer decoction plus a little for sweetening the filling)","250 ml beer (mixed half-and-half with the honey and peel decoction)","30 g orange peel (boiled and finely chopped)","0.5 tsp cinnamon (ground)","0.25 tsp cloves (crushed)","500 ml water (for boiling the peels into a decoction)"],"steps":["Cook the large pears in the peel decoction combined with the cooled honey and beer until they turn yellow and translucent, taking care that they do not overcook.","Remove the pears onto a sieve and flatten each one slightly.","Prepare the filling: cook the peeled apples and smaller pears, press through a sieve, add the boiled and chopped orange peel, cinnamon, cloves, and a little honey, cook down until thick, and cool.","Stuff the pears generously with the spiced fruit mixture.","Boil down the cooking liquid from the pears into a thick syrup, dip the stuffed fruit in it, and dry in a slow oven over several days, repeating the dipping in syrup daily to give them a glossy finish."],"time":240,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_suszone_w_miodzie%2C_nadziewane_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki suszone w miodzie, nadziewane innym sposobem"},{"id":"oc-plws-568691","title":"Pears Dried in Rock Sugar","cuisine":"European","category":"Preserve","ingredients":["1 kg pears (large, ripe, of a choice variety, peeled whole with stems intact)","500 g rock sugar (finely crushed rock sugar, for repeated coating)","1 lemon (juice for the cold water)","2 l water (cold, soft water for soaking and cooking the pears)"],"steps":["Peel the pears whole without trimming the stems, and place immediately into cold water acidulated with lemon juice.","Arrange the peeled pears in a large stoneware pan, cover with cold soft water, and cook until a straw passes easily through them.","Remove the fruit with a slotted spoon onto a sieve, and when slightly cooled, gently flatten each pear on its side with a silver spoon.","Arrange the flattened pears on sieves, coat each with finely crushed rock sugar, and place in a very low oven overnight.","Turn the fruit daily, add a fresh coating of crushed rock sugar, and dry again in a low oven until a crystalline coating forms; pack in boxes with paper between the layers."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_suszone_w_cukrze_lodowatym","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki suszone w cukrze lodowatym"},{"id":"oc-plws-568690","title":"Pears Dried in Sugar Another Way","cuisine":"European","category":"Preserve","ingredients":["2 kg pears (half-ripe, of a choice variety, peeled with stems left on)","2.25 kg sugar (1 kg on the first day, 250 g 3 times over the following days, and approx. 500 g of fresh sugar for drying)","750 ml water (3 glasses for the syrup, plus cold water for soaking and parboiling the pears)","1 lemon (juice for the cold water when peeling and parboiling)"],"steps":["Peel the pears, leaving the stems intact (halve large ones), remove the cores, and submerge in cold water with lemon juice.","Transfer the pears to a stoneware pan with fresh cold water and a little lemon juice, cook covered until tender (without overcooking), and drain on a sieve.","Boil a light syrup from 1 kg of sugar and 750 ml (3 glasses) of water, skim, cool, and pour over the pears.","For the next three days, drain the syrup daily, add 250 g of sugar each day, bring to a boil, and pour the progressively warmer syrup over the pears.","On the fourth day, place the pears into the thick syrup, bring to a single boil, skim, cool, and store in jars covered with the syrup.","As needed, remove a portion of pears onto a sieve to drain, then dip them in freshly boiled, very thick sugar syrup (cooked to the thread stage) and dry on a wire sieve, or coat in fine sugar and dry in a lukewarm oven."],"time":180,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_suszone_w_cukrze_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki suszone w cukrze innym sposobem"},{"id":"oc-plws-544165","title":"Pears in Syrup","cuisine":"European","category":"Preserve","ingredients":["500 g pears (unripe white varieties such as Williams bon chrétien, peeled and cored from the bottom)","750 g sugar (chopped into small pieces, divided into two equal parts)","2 lemon (juice of 1 lemon for the water and juice of 1 lemon for the syrup)","0.5 vanilla bean (piece of pod tied in muslin, optional for aroma)","500 ml water (for the syrup and cold water for soaking the peeled pears)"],"steps":["Peel the pears, trim the stems in half, core the seeds from the bottom, and place the fruit immediately into cold water acidulated with the juice of 1 lemon.","Boil a light syrup from half of the sugar (375 g) and the water, squeeze in the juice of the second lemon, add the drained pears, and cook until tender, then leave in the syrup until the next day.","On the second day, drain the syrup, add the remaining 375 g of sugar and the piece of vanilla bean tied in muslin, and bring to a boil.","Add the pears to the boiling syrup and simmer over low heat until translucent.","Once cooled, arrange the pears with the syrup in jars, tie tightly, and store in a cool, dry place."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki"},{"id":"oc-plws-546288","title":"Pears preserved in spirit","cuisine":"European","category":"Preserve","ingredients":["1.5 kg pears (smaller, not too ripe, of a fine variety)","1 lemon (a juicy one; the squeezed juice goes into the cold water while peeling)","500 g sugar (orig. half a kilogram of sugar per 1.5 kg of pears)","750 ml water (2 szklanki (500 ml) for the syrup, plus about 250 ml of boiled water to dilute the spirit (and water for softening and soaking the pears))","500 ml spirit (90%, diluted with boiled water)"],"steps":["Put the pears into hot water and keep them over low heat until they soften slightly and peel easily. Peel them and drop them at once into cold water with the juice of 1 juicy lemon.","Cook a syrup from 500 g of sugar and 500 ml of water, put the pears into the boiling syrup, bring it to the boil once, and leave it until the next day.","On the second and the third day, pour off the syrup, bring it to the boil, put the pears back in, and bring it to the boil once more, taking care the fruit does not become too soft.","Pack the cooled pears into a jar. Mix the boiled-down syrup with 500 ml of spirit diluted with 250 ml of boiled water, pour it over the fruit, and seal the jar."],"time":45,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_gruszek_w_spirytusie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z gruszek w spirytusie"},{"id":"oc-plws-546710","title":"Peeled Oat-Dusted Roasted Potatoes","cuisine":"European","category":"Side","ingredients":["1 kg potatoes (orig. 12 medium potatoes)","1 tbsp oat flour (for dredging)","1 tbsp salt (for salting the potatoes generously)"],"steps":["Peel the medium-sized potatoes, salt them generously on all sides, and let stand for at least 60 minutes.","Dredge the salted potatoes evenly in the oat flour.","Arrange the potatoes on a baking tray and roast in a hot oven (200 °C) for about 40–45 minutes until tender and golden brown."],"time":120,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kartofle_pieczone_bez_%C5%82upin","page":"109 potraw/Kartofle pieczone bez łupin"},{"id":"oc-plws-547338","title":"Peeled plums pickled in vinegar","cuisine":"European","category":"Preserve","ingredients":["1 kg węgierka plums (orig. 1 kilogram of ripe węgierka plums, peeled)","500 g sugar (orig. half a kilogram of sugar per 1 kg of plums)","500 ml vinegar (orig. half a litre of very good vinegar per 1 kg of plums)","2 g cinnamon (a piece of bark)","6 cloves (a few)"],"steps":["Peel 1 kg of ripe węgierka plums.","Bring 500 ml of very good vinegar to the boil in a pan with 500 g of sugar, cinnamon and cloves.","Drop the peeled plums briefly into the boiling vinegar liquor and bring it to the boil once. Then lift out the fruit, pack it into jars, and cover it with the well-cooled liquor.","Seal the jars, stand them in a kettle of cold water, and pasteurize for 30 minutes from the moment the water boils. Leave the jars in the water until completely cool, wipe them dry, and store them in a dry, cool place."],"time":80,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_ze_%C5%9Bliwek_obieranych_w_occie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa ze śliwek obieranych w occie"},{"id":"oc-plwb-14199","title":"Pejzanka (Polish rustic cabbage, bean, and sausage soup)","cuisine":"European","category":"Soup","ingredients":["500 g kiełbasa (Polish sausage)","500 g pork ribs","300 g white cabbage","1 onion","1 bunch soup greens (włoszczyzna)","2 tbsp vegetable oil","100 g dried white beans","750 g potatoes","200 g tomato purée (passata)","1 clove garlic","4 allspice","to taste salt","to taste black pepper","to taste parsley leaves (chopped)","2.5 l water (for broth and cooking beans)"],"steps":["Soak the white beans in water, then cook until tender in a separate pot.","Cover the pork ribs with water, simmer to make a meat broth, and strain it.","Clean and chop the soup greens, shred the cabbage, and braise the vegetables together covered.","Peel the potatoes, dice them, and cook in the strained rib broth, then add the braised vegetables and cooked beans.","Slice the kiełbasa, dice the onion, sauté both in hot vegetable oil, and add to the soup pot.","Add the tomato purée, allspice berries, pressed garlic clove, salt and pepper, bring to a boil, and serve sprinkled with parsley leaves."],"time":120,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pejzanka","page":"Książka kucharska/Pejzanka"},{"id":"oc-plwb-18778","title":"Peppery beef goulash (Wołowy gulasz z pieprzem)","cuisine":"European","category":"Main","ingredients":["1 kg beef","100 g lard","150 g onions","140 g fresh bell pepper","60 g tomatoes","to taste salt","1 clove garlic (small clove)","to taste black pepper (generous amount)","to taste water (for adding during braising)"],"steps":["Cut the beef into strips about 3 cm long, and chop the onions and fry in lard until golden.","Salt the meat, add to the pot with the onions, and brown until it releases juices.","Add a small clove of garlic, splash with a little water, and braise in a small amount of liquid, stirring occasionally and adding water as needed.","When the meat is half-tender, reduce the liquid until only the fat remains, add tomato pulp and diced bell pepper, and continue to cook uncovered over low heat.","Towards the end of cooking, season the goulash generously with black pepper so that it has a distinctly peppery flavor and aroma."],"time":110,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wo%C5%82owy_gulasz_z_pieprzem","page":"Książka kucharska/Wołowy gulasz z pieprzem"},{"id":"oc-plws-39056","title":"Pianka z konfiturami (baked meringue with fruit preserves)","cuisine":"European","category":"Dessert","ingredients":["10 egg white","400 g caster sugar (orig. 1 funt of fine sugar)","1 tbsp fruit preserves (raspberry or cherry, drained of syrup)","30 g almonds (chopped or flaked, for sprinkling)"],"steps":["Beat 10 egg whites into stiff peaks.","Gradually fold in 400 g of caster sugar and 1 tbsp of raspberry or cherry preserves drained of syrup, mixing gently.","Pile the meringue onto an ovenproof platter, sprinkle the top with almonds, and place for 15 minutes in a warm oven (150 °C)."],"time":30,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pianka_z_konfiturami","page":"365 obiadów za 5 złotych/Pianka z konfiturami"},{"id":"oc-plws-547343","title":"Pickled melon in spiced vinegar","cuisine":"European","category":"Preserve","ingredients":["750 g melon (orig. three quarters of a kilogram of half-ripe melon, cut into pieces)","1 l water (cold, for blanching the melon)","500 ml vinegar (orig. half a litre of good vinegar)","500 g sugar (orig. half a kilogram of sugar)","6 cloves (added on the fourth day)","2 g cinnamon (a piece of bark, added on the fourth day)"],"steps":["Cut a half-ripe melon into neat pieces, put them in an earthenware or enamel pan, cover with cold water, and heat over low heat until the fruit softens, without letting the water boil. Then drain.","For 750 g of melon, bring 500 ml of good vinegar and 500 g of sugar to the boil together, cool the syrup, and pour it lukewarm over the pieces of fruit.","Every day for 4 days, pour off the syrup, reduce it, and pour it back over the melon, each time a little thicker. On the fourth day, add cloves and cinnamon while the syrup boils.","Once completely cool, pack the preserve into jars, seal them, and store them in a dry, cool pantry."],"time":45,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_melona_w_occie_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z melona w occie innym sposobem"},{"id":"oc-plws-40192","title":"Pieczeń barania duszona ze śmietaną (mutton braised with sour cream)","cuisine":"European","category":"Main","ingredients":["1.6 kg roast mutton (mutton roasting joint; leg or shoulder trimmed of membranes and excess fat)","500 ml vinegar (boiled with spices, for marinating the meat and basting while braising)","100 g fatback (for larding the meat or sliced on the bottom of the casserole)","2 tbsp butter (orig. a piece of butter)","0.5 celeriac (sliced)","1 parsley root (sliced)","1 onion (sliced)","6 juniper berries (orig. a few berries (optional))","1.5 tbsp wheat flour (for dusting the meat)","500 ml sour cream 18% (orig. half a kwarta of sour cream)","150 ml water (or broth, for basting while braising)","to taste salt"],"steps":["Trim the mutton roast of membranes and excess fat and marinate for 2–3 days in a cool place in vinegar boiled with spices.","Remove the meat from the marinade, pat dry, lard with fatback, and rub with salt.","Melt the butter in a casserole, scatter the sliced celeriac, parsley root, onion, and juniper berries over the bottom, lay the roast on top, moisten with 1–2 tbsp of vinegar from the marinade, and braise over low heat, turning frequently and basting with a spoonful of water or broth at a time, until the meat browns.","Remove the browned roast, dust it on all sides with wheat flour, and rub the braising liquid and vegetables through a sieve.","Return the joint to the casserole, pour over the sieved sauce and 500 ml (half a kwarta) of sour cream, and braise covered until completely tender (before serving, you may add small shallots, capers or olives to the sauce)."],"time":120,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Piecze%C5%84_barania_duszona_ze_%C5%9Bmietan%C4%85","page":"365 obiadów za 5 złotych/Pieczeń barania duszona ze śmietaną"},{"id":"oc-plws-39659","title":"Pieczeń cielęca (roast veal)","cuisine":"European","category":"Main","ingredients":["2 kg roast veal (veal roasting joint; a quarter of a young calf)","150 g fatback (fresh, cut into strips for larding)","to taste salt","60 g butter (for basting the roast while cooking)","2 tbsp breadcrumbs (for sprinkling towards the end of roasting)","100 g butter (orig. a quarter funt of butter)","1 tbsp wheat flour","250 ml whipping cream 30% (orig. 1 Polish kwaterka of cream)","2 egg yolk"],"steps":["Wash the quarter of veal, rinse, and leave for 60 minutes in clean cold water.","Remove the meat from the water, pat dry, lard thickly with strips of fresh fatback, rub with salt, and let stand for at most 60 minutes.","Roast the veal on a spit or in an oven preheated to 190 °C for about 2 hours, basting regularly with melted butter and collecting the drippings in the roasting pan.","Towards the end of roasting, sprinkle the top of the meat with breadcrumbs, drizzle with butter, and brown, then serve on a platter drizzled with its own pan juices (alternatively, bring 100 g of butter to a boil with 1 tbsp of flour and 250 ml of cream, cool, mix with 2 egg yolks and the pan juices, and baste the roast with this sauce while finishing)."],"time":255,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Piecze%C5%84_ciel%C4%99ca","page":"365 obiadów za 5 złotych/Pieczeń cielęca"},{"id":"oc-plws-39666","title":"Pieczeń huzarska (Hussar-style stuffed roast beef)","cuisine":"European","category":"Main","ingredients":["1.6 kg roasting beef (orig. several funt of good meat (approx. 4 funt))","to taste salt","4 tbsp butter (approx. 3 tbsp for basting while roasting and 1 large tbsp for the stuffing)","2 onion (orig. a couple of baked onions)","3 tbsp breadcrumbs (or grated bread, enough to thicken the stuffing)","2 egg yolk (orig. a couple of egg yolks)","to taste black pepper"],"steps":["Pound a cut of good beef well, salt it, and roast in an oven preheated to 190 °C (or on a spit) for about 90 minutes, basting frequently with melted butter, until the meat is browned and nearly tender.","Mash 2 baked onions into a smooth paste with 1 large tbsp of butter, pepper, breadcrumbs, and 2 egg yolks to form a thick stuffing (optionally adding finely chopped herring).","Remove the par-roasted beef, slice it diagonally at close intervals without cutting all the way through the bottom, and pack each cut with the onion stuffing.","Transfer the stuffed roast to a casserole, moisten with the pan juices collected during roasting, cover with a lid, and braise over low heat or in the oven for 30 minutes; serve with braised cabbage or potatoes."],"time":145,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Piecze%C5%84_huzarska","page":"365 obiadów za 5 złotych/Pieczeń huzarska"},{"id":"oc-plws-39686","title":"Pieczeń wołowa siekana (Polish minced beef roast)","cuisine":"European","category":"Main","ingredients":["2 kg beef (preferably beef round, orig. 5 historical Polish funty)","4 eggs","to taste salt","to taste black pepper","1 onion (roasted in the oven and rubbed through a sieve)","1 tbsp breadcrumbs","60 g butter (a tablespoon for the mixture and an extra portion for greasing the roasting tin)","100 g pork fatback (diced into thick cubes)","100 ml sour cream (for spooning over near the end of baking)"],"steps":["Finely mince the beef or pass it through a meat grinder.","Roast the whole onion in the oven until tender, then rub it through a fine-mesh sieve.","To the minced meat add the sieved onion, whole eggs, breadcrumbs, a tablespoon of softened butter, the diced fatback, and salt and pepper to taste.","Knead the mixture thoroughly by hand until cohesive and firm, then shape it into an oblong loaf.","Generously butter a roasting tin, place the loaf inside, and bake in an oven preheated to 180 °C for about 45 minutes.","Towards the end of baking, spoon the sour cream over the top of the roast, bake until nicely browned, and serve hot or sliced cold."],"time":75,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Piecze%C5%84_wo%C5%82owa_siekana","page":"365 obiadów za 5 złotych/Pieczeń wołowa siekana"},{"id":"oc-plws-39689","title":"Pieczeń wołowa z rożna (spit-roasted marinated beef)","cuisine":"European","category":"Main","ingredients":["1.8 kg beef (centre-cut beef round or rump, orig. 4–5 historical Polish funty)","500 ml wine vinegar (mild, for marinating the meat overnight)","150 g pork fatback (fresh, cut into thin strips for larding)","150 g butter (melted, for continuously basting the roast)","50 ml water (for the roasting tin under the meat)","to taste salt (for seasoning 15 minutes before roasting)","1 kg potatoes (optional, to arrange around the roast in the tin)"],"steps":["Trim the beef of any sinew and excess fat, pour mild vinegar over it, and set aside in a cool place overnight (or longer) to tenderise.","Remove the meat from the vinegar, pat dry with a cloth, and lard densely with strips of fatback.","About 15 minutes before roasting, salt the meat thoroughly on all sides (tying with kitchen twine if needed to hold its shape).","Place the meat on a rack over a roasting tin containing a few tablespoons of water (and optionally peeled potatoes) or thread onto a spit.","Transfer to an oven preheated to 220 °C and roast over high heat for 45–60 minutes, basting frequently with melted butter and turning once the first side has browned.","Remove the juicy roast, let it rest for 10 minutes before carving, and serve sliced with the buttery pan juices."],"time":570,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Piecze%C5%84_wo%C5%82owa_z_ro%C5%BCna","page":"365 obiadów za 5 złotych/Pieczeń wołowa z rożna"},{"id":"oc-plwb-14278","title":"Pieczona biała kiełbasa (baked Polish white sausage with onions)","cuisine":"European","category":"Main","ingredients":["700 g raw white kiełbasa (biała kiełbasa)","2 onion","1 tbsp lard","to taste salt"],"steps":["Coil the white sausage into a wreath, prick in a few spots with a fork, parboil with salt over low heat for about 10 minutes, then remove and drain.","Peel the onions and slice them into half-moons.","Preheat the oven to 200 °C, place the sausage in a roasting pan over melted lard, surround with the onions, and bake for about 30 minutes.","Serve the hot sausage topped with the roasted onions."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pieczona_bia%C5%82a_kie%C5%82basa","page":"Książka kucharska/Pieczona biała kiełbasa"},{"id":"oc-plws-44960","title":"Pieczony zając z sosem z wątróbki i krwi (Roast hare with liver and blood sauce)","cuisine":"European","category":"Main","ingredients":["1 hare (dressed, with the liver and blood reserved)","to taste olive oil (for rubbing the meat before sprinkling with vinegar)","to taste vinegar (for sprinkling the meat and preserving the blood)","1 tbsp butter (for the sauce, plus extra for basting the roast)","to taste sour cream (for basting the hare during roasting)","1 hare liver (finely chopped or mashed for the sauce)","1 onion (grated)","0.5 tbsp plain wheat flour (orig. half a tablespoon)","125 ml dry white wine (orig. half a glass)","to taste broth (a little, for thinning the sauce)","to taste salt","to taste black pepper","to taste hare blood (preserved with a little vinegar)"],"steps":["Trim the hare of membranes and sinews, rub with olive oil, sprinkle with vinegar, and prepare like venison (larded with pork fatback).","Place the hare in a roasting pan (optionally rubbing the top with a piece of hare liver for a glossy finish) and roast in an oven preheated to 190 °C for about 60–75 minutes, basting frequently with butter and sour cream.","Finely chop or mash the hare liver and fry it in a tablespoon of butter together with the grated onion.","Stir in half a tablespoon of flour, pour in half a glass of white wine and a little broth, season with salt and pepper, bring to a boil together, and press through a sieve.","Enrich the strained sauce with the hare blood preserved in vinegar, bring briefly to a boil once more, and pour over the roasted hare."],"time":115,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zaj%C4%85c","page":"365 obiadów za 5 złotych/Zając"},{"id":"oc-plwb-1341","title":"Piernik (traditional Polish spiced gingerbread)","cuisine":"European","category":"Cake","ingredients":["250 ml milk","6 tsp baking soda (level)","860 g sugar (for the batter and for caramel)","250 ml grain coffee (strong brew)","500 g butter (or lard, or a half-and-half mixture)","1 kg buckwheat honey","1 kg wheat flour","1 kg rye flour","to taste cloves (ground)","to taste ground ginger","to taste cardamom (ground)","to taste cinnamon (ground)","to taste nutmeg (grated)","to taste anise (ground)","to taste dried lavender (crushed)","to taste black pepper (ground)","to taste ground coriander","to taste allspice (crushed)","1 bay leaf (crushed in a mortar)","1 tsp salt","300 ml rectified spirit","80 g walnuts (chopped)","50 g candied orange peel (finely chopped)","6 eggs (1 yolk reserved for brushing the top)","2.5 tbsp cocoa powder (optional)"],"steps":["Dissolve the baking soda in the milk.","Add 4 tablespoons of sugar to a pan, caramelise, and dissolve with the brewed grain coffee.","In a wide saucepan, combine the remaining sugar with the caramel, add the butter and buckwheat honey, and heat gently over low heat, stirring and skimming any foam, without letting it boil.","Sift the wheat and rye flour into a large pot, add the mortar-crushed cloves, ginger, cardamom, cinnamon, nutmeg, anise, lavender, pepper, coriander, allspice, and bay leaf (2–4 tablespoons of spices in total), along with the salt and cocoa powder, then mix thoroughly.","Remove the hot honey mixture from the heat, slowly pour in the spirit, add everything to the spiced flour, and stir thoroughly from the bottom.","Add the baking soda dissolved in milk, chopped walnuts, orange peel, and eggs (reserving one yolk for brushing), and knead the dough by hand on a pastry board.","Dust the kneaded dough with flour, cover with cloths, and set aside in a cool place for 3–4 weeks to mature.","Preheat the oven to 220 °C, roll out the matured dough thickly onto a rectangular baking sheet, brush the top with the reserved egg yolk, and bake for 25–35 minutes."],"time":95,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Piernik","page":"Książka kucharska/Piernik"},{"id":"oc-plws-548311","title":"Piernik owsiany z marchwią (oat and carrot gingerbread)","cuisine":"European","category":"Cake","ingredients":["600 g oat flour (orig. 60 dkg)","200 g plain wheat flour (orig. 20 dkg)","200 g sugar (orig. 20 dkg)","600 g carrots (orig. 60 dkg)","1 tsp baking soda","1 egg","1 tbsp vegetable oil (plus extra for greasing the tin)","1 tsp crushed mixed spices: black pepper, allspice, cloves, cinnamon, ginger, and mace","2 tbsp breadcrumbs (for dusting the tin)"],"steps":["Peel the carrots and grate them on the finest grater.","Thoroughly knead the grated carrots with the oat flour and plain wheat flour.","Add the sugar, egg, vegetable oil, baking soda, and crushed spices, then knead the dough for about 30 minutes.","Transfer the dough to a baking tin greased with oil and dusted with breadcrumbs.","Bake in an oven preheated to 180 °C for about 50 minutes until a skewer inserted in the center comes out clean."],"time":95,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Piernik_owsiany","page":"109 potraw/Piernik owsiany"},{"id":"oc-plws-44931","title":"Pierogi gotowane z kapustą (boiled sauerkraut and herring pierogi)","cuisine":"European","category":"Main","ingredients":["500 g sauerkraut","40 g dried forest mushrooms","1 salted herring (lightly soaked, boned, and finely chopped)","1 onion (chopped)","40 g butter (for frying the onion and filling)","to taste black pepper","400 g plain flour","200 ml water (hot)","0.5 tsp salt","100 g pork fatback (rendered into cracklings)"],"steps":["Boil the sauerkraut in water without squeezing out its juice, drain in a colander, and chop finely.","Cook the dried mushrooms separately in a small amount of water until tender and chop finely.","Carefully debone the soaked herring and chop finely with a knife.","Melt butter in a frying pan, cook the chopped onion until translucent, add the sauerkraut, mushrooms, and herring, mix well, season with pepper, and fry briefly.","Knead plain flour, hot water, and salt into an elastic dough and roll it out thinly.","Cut out rounds, spoon portions of cooled filling into the centre, seal the edges securely, and drop in batches into salted boiling water.","Cook for about 3–4 minutes from the moment they float to the surface.","Transfer with a slotted spoon to a platter and top with melted fatback cracklings."],"time":80,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pierogi_gotowane_z_kapust%C4%85","page":"365 obiadów za 5 złotych/Pierogi gotowane z kapustą"},{"id":"oc-plws-580463","title":"Pierogi gryczane w papilotach (buckwheat pierogi baked in paper)","cuisine":"European","category":"Main","ingredients":["3 eggs (2 for the dough and 1 for mashing with the farmer's cheese)","500 ml buckwheat flour (2 szklanki)","to taste sour cream (for mixing the dough and for the sauce)","to taste salt","to taste butter (melted for brushing the paper and for boiling with the sour cream)","to taste farmer's cheese (1 tbsp per pieróg)"],"steps":["Preheat the oven to 220 °C and beat 2 eggs in a bowl with the buckwheat flour, salt, and enough sour cream to form a fairly soft dough.","Mash the farmer's cheese in a separate bowl with the remaining 1 egg until smooth.","Brush sheets of baking paper with melted butter, spread a thin round of buckwheat dough on each, and place a spoonful of the farmer's cheese filling in the centre.","Fold each pieróg in half together with the paper, crimp the edges of the paper packets tightly, and arrange them on a baking sheet.","Place the baking sheet in the oven preheated to 220 °C and bake for about 20 minutes until the paper browns.","Boil an extra portion of sour cream with butter in a small saucepan for 5 minutes and serve in a sauceboat alongside the baked pierogi."],"time":55,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Pierogi_gryczane_w_papilotach","page":"100 postnych i jarskich dań/Pierogi gryczane w papilotach"},{"id":"oc-plws-44965","title":"Pierogi leniwe (lazy curd cheese dumplings)","cuisine":"European","category":"Main","ingredients":["800 g farmer's cheese (fresh, well drained of whey, orig. 1 historical Polish kwarta)","6 egg yolks","6 egg whites (whipped to stiff peaks)","30 g butter (a tablespoon for the dough, orig. a spoon of butter)","1 pinch salt","2 tbsp plain flour (for the dough, plus extra for dusting the work surface)","50 g raisins (small black raisins)","60 g clarified butter (melted, for drizzling)","2 tbsp sugar (for sprinkling on the platter)"],"steps":["Squeeze excess whey from the farmer's cheese through a cloth, then beat it in a bowl with a tablespoon of softened butter, the egg yolks, and a pinch of salt.","Add two tablespoons of plain flour and the rinsed raisins to the cheese mixture, beating until smooth.","Whisk the egg whites until stiff peaks form, then gently fold them into the cheese mixture with a spoon.","Turn the mixture onto a generously floured board, shape into a long log, flatten slightly, score the top in a crosshatch pattern with a knife, and cut diagonally into dumplings.","Drop the dumplings into salted boiling water and cook gently for 2–3 minutes after they float to the surface.","Remove with a slotted spoon to a platter, drizzle with hot clarified butter, and sprinkle with sugar."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pierogi_leniwe","page":"365 obiadów za 5 złotych/Pierogi leniwe"},{"id":"oc-plwb-21745","title":"Pierogi ruskie (potato and cheese dumplings)","cuisine":"European","category":"Main","ingredients":["1 pierogi dough (1 batch (from about 500 g flour))","750 g potatoes","300 g quark (farmer's cheese)","2 onions","1 tbsp butter (or oil)","to taste salt","to taste black pepper","1 clove garlic (optional)"],"steps":["Peel the potatoes, boil until tender in salted water, drain, and mash into a smooth puree.","Peel and finely dice the onions, then cook until translucent in melted butter.","Combine the mashed potatoes with the cooked onions and crumbled quark, then season with salt, black pepper, and pressed garlic.","Roll out the pierogi dough thinly, cut out rounds with a drinking glass, place a tablespoon of filling on each, fold in half, and pinch the edges together.","Drop the pierogi into salted boiling water and cook until they float to the surface."],"time":75,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pierogi_ruskie","page":"Książka kucharska/Pierogi ruskie"},{"id":"oc-plws-44919","title":"Pierogi z grzybami (dried mushroom pierogi)","cuisine":"European","category":"Main","ingredients":["100 g dried forest mushrooms (young dried wild forest mushrooms)","2 onion (finely chopped)","30 g butter (a tablespoon for frying the onion)","2 eggs","to taste salt","to taste black pepper","400 g plain flour","200 ml water (warm)","1 egg","50 g butter (for drizzling)","1 onion (for browning in butter)"],"steps":["Rinse the dried mushrooms, scald with boiling water, simmer in a small amount of water until tender, and chop finely.","Melt a tablespoon of butter in a frying pan and cook two chopped onions until translucent.","Remove the pan from the heat, combine the onions with the chopped mushrooms, crack in two eggs, and season with salt and pepper.","Knead plain flour, warm water, egg, and a pinch of salt into a springy dumpling dough and roll out thinly on a work surface.","Cut out rounds, place portions of mushroom filling in the centre, seal the edges securely, and drop into salted boiling water.","Boil the pierogi for 3–4 minutes from the moment they float to the surface.","Lift out with a slotted spoon onto a platter and drizzle with hot butter and browned onion."],"time":70,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pierogi_z_grzybami","page":"365 obiadów za 5 złotych/Pierogi z grzybami"},{"id":"oc-plwb-21742","title":"Pierogi z kapustą i grzybami (sauerkraut and mushroom pierogi)","cuisine":"European","category":"Main","ingredients":["1 pierogi dough (1 batch (from about 500 g flour))","1 kg sauerkraut","40 g dried wild mushrooms","2 tbsp butter","1 tbsp wheat flour (for the roux)","2 l water (for soaking mushrooms and boiling sauerkraut and pierogi)","to taste salt (for boiling pierogi)"],"steps":["Soak the dried mushrooms in water for at least 60 minutes.","Squeeze excess brine from the sauerkraut, place in a pot, cover with water, and simmer for 30 minutes.","Drain the sauerkraut, add the chopped mushrooms and a tablespoon of butter, and braise covered for another 30 minutes.","Make a dark roux with the remaining tablespoon of butter and flour, stir into the cabbage and mushrooms, and allow the filling to cool.","Roll out the pierogi dough thinly, cut out rounds with a glass, place a spoonful of filling on each, fold in half, and seal the edges firmly.","Boil the pierogi in batches in salted boiling water until they float to the surface."],"time":135,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pierogi_z_kapust%C4%85_i_grzybami","page":"Książka kucharska/Pierogi z kapustą i grzybami"},{"id":"oc-plwb-6270","title":"Pierogi z owocami (fruit pierogi)","cuisine":"European","category":"Main","ingredients":["480 g wheat flour","250 ml water (for the dough, plus 2 l for boiling)","1 egg (small)","1 kg seasonal fruit (strawberries, blueberries, pitted cherries, or blackberries)","75 g breadcrumbs","1 tbsp olive oil (for boiling)"],"steps":["Knead a smooth dough from wheat flour, water, and egg, roll out into thin sheets, and cut out rounds with a wide glass.","Wash the fruit, drain thoroughly, and toss with breadcrumbs.","Place spoonfuls of fruit filling onto the dough rounds, dab the edges with a little cold water, fold in half, and pinch the edges firmly to seal.","Bring 2 litres of water with olive oil to a boil in a large pot and drop the pierogi in batches of 5–6 into the boiling water.","Stir gently with a wooden spoon, and once they float to the surface, boil for another 2–3 minutes, then remove with a slotted spoon and drain."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pierogi_z_owocami","page":"Książka kucharska/Pierogi z owocami"},{"id":"oc-plws-44941","title":"Pierożki gryczane (buckwheat and curd cheese parcels in cabbage)","cuisine":"European","category":"Main","ingredients":["600 g buckwheat flour (1 historical Polish kwarta, orig. a kwarta of buckwheat flour)","400 ml sour cream (thick, fresh sour cream added gradually)","1 tsp salt","400 g farmer's cheese (curd cheese beaten with eggs and butter)","2 eggs","30 g butter","1 white cabbage (large scalded leaves for wrapping the dumplings)","50 g clarified butter (or sour cream with sugar)"],"steps":["Work the buckwheat flour in a bowl with a rolling pin for about 30 minutes, gradually adding thick sour cream a tablespoon at a time and adding the salt, until smooth and pliable.","Beat the farmer's cheese with eggs and softened butter into a smooth filling.","Remove large leaves from the cabbage head and blanch them briefly in boiling water until softened.","Place a portion of buckwheat dough onto each cabbage leaf, spoon cheese filling into the centre, and fold the leaf in half, enclosing the dough and cheese completely.","Arrange the parcels on a baking sheet and bake in an oven preheated to 190 °C for about 30 minutes.","When the leaves soften and the dough inside turns yellowish, remove from the oven and serve with clarified butter or sour cream and sugar."],"time":75,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Piero%C5%BCki_gryczane","page":"365 obiadów za 5 złotych/Pierożki gryczane"},{"id":"oc-plws-40191","title":"Pierożki kruche z konfiturami (fried shortcrust jam dumplings)","cuisine":"European","category":"Cookie","ingredients":["600 g plain flour (1 historical Polish kwarta, orig. a kwarta of flour)","30 g butter (1 tablespoon)","7 egg yolks","125 ml milk (half a kwaterka, orig. half a kwaterka of milk)","250 g fruit preserves (thick cherry or rose petal preserve)","500 g lard (or clarified butter for deep frying)","2 tbsp icing sugar (for dusting)"],"steps":["Sift the flour onto a pastry board, add softened butter, 7 egg yolks, and milk, then knead into a cohesive, smooth short pastry.","Roll out the dough to a thickness of about 3 mm.","Cut out rounds using a glass, spoon thick preserves into the centre, and crimp the edges tightly to form small turnovers.","In a deep saucepan heat lard or clarified butter to about 175 °C.","Fry the dumplings in batches of several at a time on both sides until golden brown, just like doughnuts.","Remove with a slotted spoon, drain on a sieve or paper towels, and dust with icing sugar before serving."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Piero%C5%BCki_kruche","page":"365 obiadów za 5 złotych/Pierożki kruche"},{"id":"oc-plwb-26934","title":"Pierożki pieczone z borowikiem (baked porcini pastries)","cuisine":"European","category":"Main","ingredients":["480 g wheat flour","150 g butter","2 egg yolks","2.5 tbsp sour cream","to taste salt","1 egg (beaten, for egg wash)","800 g sauerkraut","100 g dried porcini","100 g butter","1 onion","3 tbsp vegetable oil","to taste salt","to taste black pepper","500 ml water (for soaking and cooking mushrooms)"],"steps":["Soak the dried porcini in water for 2 hours, boil until tender, drain (reserving the broth), and chop finely.","Squeeze and rinse the sauerkraut, then braise it in the mushroom broth with 100 g of butter.","Dice the onion, sauté in hot vegetable oil, add along with the chopped porcini to the sauerkraut, and braise until liquid evaporates, then season with salt and pepper and let cool.","Cut 150 g of chilled butter into the sifted flour, add the egg yolks, sour cream and salt, knead into a dough, and refrigerate for several hours.","Roll out the chilled dough, cut out squares or rounds, spoon portions of filling onto them, and crimp the edges tightly.","Brush the tops of the pastries with beaten egg and bake in an oven preheated to 180 °C until golden brown."],"time":90,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Piero%C5%BCki_pieczone_z_borowikiem","page":"Książka kucharska/Pierożki pieczone z borowikiem"},{"id":"oc-plws-39667","title":"Pierożki z gotowanym mięsem (boiled beef pierogi)","cuisine":"European","category":"Main","ingredients":["500 g cooked beef (beef used to make broth)","20 g dried forest mushrooms (cooked, or fresh button mushrooms)","1 onion (roasted and grated)","30 g butter (for frying the onion)","2 tbsp breadcrumbs","2 eggs","to taste salt","to taste black pepper","400 g plain flour","1 egg","180 ml water (warm)","50 g butter","2 tbsp breadcrumbs (for browning in butter)"],"steps":["Finely chop or grind the cooked beef from the stockpot along with the cooked mushrooms.","Melt butter in a saucepan, add the roasted grated onion, then stir in the minced meat and mushrooms, breadcrumbs, salt, pepper, and eggs to make a cohesive filling.","Knead plain flour, egg, warm water, and a pinch of salt into an elastic dumpling dough and roll out thinly.","Place small spoonfuls of filling on the dough, fold over, and cut out small dumplings with a cutter or small glass.","Drop into salted boiling water and cook for 3–4 minutes from the moment they float to the surface, then drain.","Transfer to a platter and pour hot butter browned with breadcrumbs over the top (or optionally pan-fry the dumplings until crisp and golden)."],"time":65,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Piero%C5%BCki_z_mi%C4%99sem","page":"365 obiadów za 5 złotych/Pierożki z mięsem"},{"id":"oc-plwb-16577","title":"Pikle z ogórków (Polish sweet and sour pickled cucumbers)","cuisine":"European","category":"Preserve","ingredients":["2 kg field cucumbers (ripe)","125 ml spirit vinegar 10%","7 tbsp sugar (level)","50 g salt","2.5 tsp yellow mustard seeds","to taste allspice berries (a few grains per jar)","625 ml water"],"steps":["Wash and peel the cucumbers, cut in half lengthwise, scrape out the seeds with a spoon, and cut the halves lengthwise into 4 long spears.","Layer the prepared cucumbers in a bowl, sprinkle with salt, and let stand for 12 hours, then drain in a colander and pack into sterilized jars.","Bring a brine of water, sugar, mustard seeds, and vinegar to a boil, then pour the hot liquid over the cucumbers in the jars.","Add a few allspice berries to each jar, seal tightly with lids, and pasteurise in a water bath for about 30 minutes."],"time":60,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pikle_z_og%C3%B3rk%C3%B3w","page":"Książka kucharska/Pikle z ogórków"},{"id":"oc-plwb-18683","title":"Pikle ze śliwek (spiced pickled plums)","cuisine":"European","category":"Preserve","ingredients":["1 kg prune plums (węgierki)","2 tbsp spirit vinegar 10%","750 g sugar","1 cinnamon stick (a generous piece)","6 clove garlic","100 ml water (for the syrup)"],"steps":["Wash the prune plums, remove the stones, and transfer the fruit to a pot.","Bring a syrup of sugar, vinegar, water, cinnamon stick, and peeled garlic cloves to a boil, skimming off foam, then cool slightly and pour over the plums for 24 hours.","On the second and third days, drain the syrup from the fruit, bring it to a rolling boil, and pour it hot back over the plums.","On the fourth day, simmer the plums in the syrup for 10 minutes, then ladle hot into sterilised jars and seal tightly."],"time":55,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pikle_ze_%C5%9Bliwek","page":"Książka kucharska/Pikle ze śliwek"},{"id":"oc-plwb-17830","title":"Pilaw z pęczaku (pearl barley pilaf with vegetables and walnuts)","cuisine":"European","category":"Main","ingredients":["250 g pearl barley","200 g broccoli (cut into florets)","200 g cauliflower (cut into florets)","1 onion","1 carrot","1 chili pepper","100 g walnuts (shelled)","3 tbsp vegetable oil","to taste soy sauce","1 tsp all-purpose vegetable seasoning","to taste salt","to taste black pepper","1 l water (boiling)"],"steps":["Rinse the pearl barley, chop the onion and cook until translucent in hot oil in a saucepan, then add the barley and sauté together for 2–3 minutes.","Pour in a litre of boiling water, add the vegetable seasoning, and simmer covered for about 30 minutes until the barley is tender.","Blanch the cauliflower and broccoli florets for 3 minutes in salted boiling water and drain thoroughly.","Grate the carrot, and slice the seeded chili pepper into thin strips.","Add the prepared vegetables to the barley, cook together for 10 minutes, and season with soy sauce, salt, and pepper.","Toast the walnuts in a dry skillet and scatter them over the dish before serving."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pilaw_z_p%C4%99czaku","page":"Książka kucharska/Pilaw z pęczaku"},{"id":"oc-plws-552223","title":"Pineapple ice","cuisine":"European","category":"Dessert","ingredients":["1 fresh pineapple (peeled: half grated, half cut into very thin slices)","500 g sugar (orig. half a kilogram)","1 l water (orig. 1 litre)","3 lemons (the squeezed juice)"],"steps":["Peel a fresh pineapple, grate half of it, and cut the other half into very thin small slices.","Bring a syrup to the boil from 500 g of sugar and 1 litre of water, skim it carefully, pour part of the hot syrup over the pineapple slices, bring it briefly to the boil, and leave them to soften.","Squeeze the juice of three lemons into the remaining syrup, add the grated pineapple together with the syrup from the slices, mix, and strain through a sieve.","Add the drained pineapple slices to the strained liquid, pour it into an ice-cream maker, and freeze it to a smooth sorbet (about 2–3 hours)."],"time":195,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_ananasowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody ananasowe"},{"id":"oc-plws-543494","title":"Pineapple in Syrup","cuisine":"European","category":"Preserve","ingredients":["500 g pineapple (peeled; orig. half a kilogram)","1000 g caster sugar (for layering over the pineapple; orig. one kilogram)","1000 g sugar (for the separate syrup; orig. one kilogram)","to taste water (for moistening the sugar for the syrup, only as much as the sugar absorbs; amount not specified)"],"steps":["Peel the pineapple and cut it into thin slices.","Layer 500 g of pineapple in a glass jar, sprinkling generously with 1000 g of caster sugar.","Leave the jar in a warm place for 1440 minutes so the sugar dissolves.","Moisten the remaining 1000 g of sugar with as much water as the sugar absorbs.","Boil into a fairly thick syrup.","Add the pineapple along with its released juice to the boiling syrup.","Bring the mixture to a boil several times over low heat.","Pour into a bowl and leave until the next day.","The next day, boil again until the syrup thickens.","Test a drop of syrup on a cold knife: stop cooking when the drop thickens and does not spread.","Leave the pineapple to cool.","Pour the excess syrup into bottles."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Ananasy_w_syropie","page":"Doświadczone sekreta smażenia konfitur i soków/Ananasy w syropie"},{"id":"oc-plws-39675","title":"Pineapple jelly","cuisine":"European","category":"Dessert","ingredients":["37.5 g gelatine or isinglass (orig. 3 łuty)","500 ml water (orig. 1/2 kwarta)","1 lemon (sliced, seeded)","500 ml pineapple syrup (orig. 1/2 kwarta)"],"steps":["Dissolve or simmer the gelatine or finely chopped isinglass over low heat in 500 ml of water.","Add the sliced, carefully seeded lemon to the dissolved liquid and simmer over very low heat for 15 minutes.","Remove the pot from the heat, lift out the lemon slices, and strain the liquid through a dense cloth or napkin, letting it drip through without squeezing.","Mix the strained liquid with the clear pineapple syrup, pour into a mould, and set in a cool place for about 4 hours (240 minutes) until firm."],"time":280,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Galareta_ananasowa","page":"365 obiadów za 5 złotych/Galareta ananasowa"},{"id":"oc-plws-550035","title":"Pineapple liqueur","cuisine":"European","category":"Drink","ingredients":["1 pineapple (a fine, very ripe one, sliced thinly)","2 l spirit (orig. 2 litres of the best spirit)","10 g vanilla pod (orig. 1 dekagram of vanilla, left whole)","2.5 kg sugar (orig. 1.25 kilograms of sugar per litre of spirit)","1 l water (orig. half a litre of water per litre of spirit)"],"steps":["Slice a very ripe pineapple thinly, put it in a demijohn, add 10 g of whole vanilla, and cover it with 2 l of the best spirit.","Tie the vessel tightly and leave it in the shade for 10 days.","After 10 days, pour off the spirit and strain it through muslin. Cover the pineapple slices left in the bottle with a cold, carefully skimmed syrup cooked from 2.5 kg of sugar and 1 l of water (1.25 kg of sugar and 500 ml of water per litre of spirit) and leave it for 7 days, so the syrup draws out the rest of the aroma and the alcohol.","After a week, pour the syrup off the pineapple and combine it with the spirit set aside earlier, pouring the spirit slowly into the syrup. Filter it through paper, bottle it, cork it firmly, and leave it for 2 months before serving."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_ananasowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier ananasowy"},{"id":"oc-plwb-7883","title":"Pineapple mayonnaise sauce","cuisine":"European","category":"Sauce","ingredients":["4 tbsp olive oil","4 tbsp lemon juice","4 tbsp mayonnaise (thick)","4 tbsp pineapple juice","4 slice pineapple","1 tsp mild Polish mustard","to taste salt","to taste black pepper","0.5 tsp icing sugar"],"steps":["Whisk the olive oil with the lemon juice, then add the mayonnaise and pineapple juice, whisking until a smooth, thick sauce forms.","Finely chop the pineapple slices or blend them into a puree.","Add the chopped pineapple, mild Polish mustard, icing sugar, salt, and pepper, mix well, and serve within 30 minutes of preparation."],"time":10,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_majonezowy_z_ananasem","page":"Książka kucharska/Sos majonezowy z ananasem"},{"id":"oc-plws-543499","title":"Pineapple Preserves","cuisine":"European","category":"Preserve","ingredients":["500 g pineapple (peeled and trimmed; orig. half a kilogram)","1250 g sugar (divide into two equal parts; orig. one and a quarter kilograms)","to taste water (only as much as the sugar absorbs when moistened; amount not specified)"],"steps":["Peel and trim the pineapple.","Cut it into slices and weigh out 500 g.","Moisten 625 g of sugar with only as much water as the sugar absorbs.","Boil it into a thick syrup, skimming the foam carefully.","Pour the slightly cooled syrup over the pineapple and leave in a cool place until the next day.","On the second day, pour the syrup off into a pot.","Add the remaining 625 g of sugar and bring to a boil, skimming off the foam.","Pour the syrup, slightly warmer than before, over the pineapple and leave until the third day.","On the third day, pour off and boil the syrup again without adding sugar.","Pour the even warmer, thick syrup over the fruit and leave until the fourth day.","On the fourth day, place the pineapple into the rapidly boiling syrup.","Simmer over very low heat for a few minutes."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Ananasy","page":"Doświadczone sekreta smażenia konfitur i soków/Ananasy"},{"id":"oc-plws-450872","title":"Placek kruchy z serem (Traditional Polish shortcrust Easter cheesecake)","cuisine":"European","category":"Cake","ingredients":["500 g plain wheat flour (orig. half a kilo)","250 g butter (orig. a quarter kilo of rich butter)","250 g sugar (orig. a quarter kilo, for the pastry)","1000 g unsalted quark (well pressed, orig. 1 kilo)","250 g sugar (orig. a quarter kilo, for the cheese filling)","7 eggs (separated into 7 yolks and 7 whites)","150 g clarified butter (orig. 15 dag)","0.5 vanilla pod (pounded piece)","1 lemon (grated zest)","0.25 tsp almond oil (several drops)","50 g Zante currants (orig. 1 handful of small dark raisins)","50 ml rum or arrack (orig. 1 kieliszek)"],"steps":["Knead a shortcrust pastry from 500 g of plain wheat flour, 250 g of butter, and 250 g of sugar, roll out thinly, line a large shallow baking sheet, chill for 60 minutes, and par-bake in an oven preheated to 180 °C for about 15 minutes until lightly golden.","Pass the well-pressed quark through a mincer, add 250 g of sugar, seven egg yolks, melted clarified butter, pounded vanilla, grated lemon zest, and a few drops of almond oil, and beat together until smooth and fluffy.","Fold a handful of currants, a kieliszek of rum or arrack, and the stiffly beaten whites of seven eggs into the cheese mixture.","Spread the cheese mixture in a thick layer over the par-baked shortcrust base and bake in an oven preheated to 175 °C for 60 minutes; after removing from the oven, you may glaze the top with thin punch icing."],"time":175,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Placek_kruchy_z_serem","page":"Ciasta wielkanocne/Placek kruchy z serem"},{"id":"oc-plwb-16077","title":"Placek królewski (Polish royal layered honey and sponge cake)","cuisine":"European","category":"Cake","ingredients":["300 g wheat flour","150 g margarine","1 tbsp sour cream","100 g sugar","2 tbsp honey","1 tsp baking soda (level)","4 eggs","200 g sugar","80 g wheat flour","90 g potato starch","1 tsp baking powder (level)","750 ml milk","3 tbsp sugar","1 tbsp vanilla-flavoured sugar","2 tbsp potato starch","2 tbsp wheat flour","250 g margarine"],"steps":["Quickly knead the shortcrust pastry from wheat flour, margarine, sour cream, sugar, honey, and baking soda, divide it into 2 equal parts, and bake two separate layers on a rectangular baking sheet at 180 °C for about 15–20 minutes.","For the sponge cake, whip the egg whites until soft peaks form, gradually add the sugar and whip until stiff peaks form, then gently fold in the egg yolks, both flours, and baking powder.","Pour the sponge batter into a baking pan of the same size and bake at 180 °C for about 25 minutes, then let all cake layers cool.","For the custard, set aside about 125 ml of milk and mix the wheat flour and potato starch into it, then bring the remaining milk to a boil with margarine, sugar and vanilla-flavoured sugar.","Slowly pour the starch slurry into the boiling milk, whisking vigorously until the custard thickens.","Assemble the cooled cake layers with the hot custard cream in order: shortcrust layer, half the cream, sponge layer, remaining cream, and the second shortcrust layer."],"time":95,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Placek_kr%C3%B3lewski","page":"Książka kucharska/Placek królewski"},{"id":"oc-plws-450868","title":"Placek pomarańczowy (Layered candied-orange Easter yeast cake)","cuisine":"European","category":"Cake","ingredients":["500 ml milk (orig. 2 szklanki)","1000 g plain wheat flour (orig. 4 szklanki (640 g) for the sponge, plus about 360 g for kneading the dough)","50 g fresh yeast (orig. 5 dag)","1 tsp salt","4 eggs (whole)","300 g sugar (orig. 1.5 szklanki, for the dough)","185 ml clarified butter (orig. 3/4 szklanki)","1 lemon (grated zest)","3 oranges (large thick-skinned: grated zest of 2 oranges for the dough, and all 3 sliced for the syrup)","400 g sugar (orig. 40 dag, for the orange syrup)","500 ml water (orig. 2 szklanki, for the syrup)","1 tbsp butter (for greasing the tins)","2 tbsp breadcrumbs (for dusting the tins)"],"steps":["Bring 500 ml of milk to a boil, cool until lukewarm, mix with 640 g of plain wheat flour and the yeast dissolved in a little of the lukewarm milk, cover with a cloth, and set in a warm place to rise.","Once the sponge has risen, add a teaspoon of salt, four eggs beaten with 300 g of sugar, the melted clarified butter, and the remaining flour (about 360 g), kneading a soft dough until it pulls away from the hand; finally work in the grated zest of the lemon and two oranges and set aside for a second rise.","Cut the three thick-skinned oranges into thin slices with the peel on, remove the pips, and simmer in a syrup made from 400 g of sugar and 500 ml of water until translucent, then drain on a sieve (reserving the syrup).","Layer the risen dough into two tins greased with butter and dusted with breadcrumbs, alternating layers of dough with slices of candied orange and finishing with a layer of dough on top.","Set the tins in a warm place for a third rise, then bake in an oven preheated to 180 °C for about 35–40 minutes; meanwhile boil down the reserved orange syrup until thick and brush it over the hot cakes immediately upon removing them from the oven."],"time":240,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Placek_pomara%C5%84czowy","page":"Ciasta wielkanocne/Placek pomarańczowy"},{"id":"oc-plws-450875","title":"Placek z marmoladą (Shortcrust fruit-jam and almond meringue sheet cake)","cuisine":"European","category":"Cake","ingredients":["500 g plain wheat flour (orig. half a kilo)","250 g butter (orig. a quarter kilo)","250 g sugar (orig. a quarter kilo)","300 g fruit jam (apple, plum, apricot, gooseberry, or raspberry)","6 egg whites (whipped to stiff peaks)","100 g icing sugar (orig. 10 dag)","50 g sweet almonds (toasted until golden and chopped)"],"steps":["Knead a shortcrust dough from the plain wheat flour, butter, and sugar, roll out thinly, fit into a shallow baking sheet, and chill in the refrigerator for 60 minutes.","Transfer the chilled pastry to an oven preheated to 180 °C, bake for about 20 minutes until lightly golden, and cool completely.","Spread the cooled shortcrust base with a thick layer of the chosen fruit jam.","Whip the six egg whites to stiff peaks, fold in the icing sugar, spread the meringue over the jam layer, scatter with chopped toasted almonds, and dry in a very low oven (about 120 °C) for about 60 minutes until crisp like meringue."],"time":165,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Placek_z_marmelad%C4%85","page":"Ciasta wielkanocne/Placek z marmeladą"},{"id":"oc-plws-1080983","title":"Placek ze śliwkami (yeast sheet cake with plums)","cuisine":"European","category":"Cake","ingredients":["1 l wheat flour (orig. 1 kwarta)","250 ml milk (orig. 1 kwaterka)","25 g fresh yeast (orig. 2 łuty)","5 g butter (orig. 1 łyżeczka)","100 g sugar (orig. a quarter funt)","3 egg yolks","500 g plums (pitted halves)","10 g butter for the tin","50 g sugar for sprinkling (before and after baking)"],"steps":["Stir the yeast with warm milk and part of the flour in a bowl, and leave the starter in a warm place until it rises.","When the starter is moving, add a teaspoon of butter, the sugar, the yolks and the rest of the flour, knead to a smooth yeast dough, and leave it until doubled.","Stretch the risen dough lightly on a buttered baking sheet.","Lay the plum halves closely on top, skin side down, leave the cake to rise again, and sprinkle with part of the sugar.","Bake in an oven heated to 190 °C for about 30 minutes, and sprinkle with the rest of the sugar as soon as it comes out."],"time":120,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Placki_ze_%C5%9Bliwkami","page":"Baby, placki i mazurki/Placki ze śliwkami"},{"id":"oc-plws-547957","title":"Placki owsiane z ziemniakami (oat and potato yeast pancakes)","cuisine":"European","category":"Main","ingredients":["250 g oat flour (orig. 25 dkg)","250 g cooked potatoes (orig. 25 dkg, boiled in their jackets)","10 g fresh yeast (orig. 1 dkg)","250 ml lukewarm water (orig. 1 cup)","1 raw potato","100 g vegetable oil (orig. 10 dkg)","to taste salt"],"steps":["Dissolve the fresh yeast in 250 ml of lukewarm water, mix with the oat flour, and set in a warm place for about 30 minutes to rise.","Peel the jacket-boiled potatoes and press them through a ricer, and peel and grate the raw potato on a fine grater.","Add the mashed cooked potatoes and grated raw potato to the risen yeast mixture, salt to taste, and thoroughly work the batter.","Heat the vegetable oil well in a skillet and fry large pancakes the full width of the pan for about 4–5 minutes on each side until golden. Serve piping hot."],"time":65,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Placki_owsiane","page":"109 potraw/Placki owsiane"},{"id":"oc-plwb-42597","title":"Placki z cukinii (Polish zucchini herb fritters)","cuisine":"European","category":"Main","ingredients":["500 g zucchini","2 eggs","4 tbsp wheat flour","2 tbsp parsley leaves (chopped)","2 tbsp fresh mint (chopped)","2 tbsp dill (chopped)","to taste salt","to taste black pepper","to taste hot ground paprika","3 tbsp vegetable oil (for frying)"],"steps":["Wash and peel the zucchini, grate on a fine grater, and squeeze out excess moisture thoroughly.","Transfer the squeezed zucchini to a bowl, crack in the eggs, add sifted wheat flour, chopped parsley leaves, fresh mint, and dill.","Season the mixture with salt, black pepper, and hot paprika, and stir into a cohesive batter.","Heat oil in a skillet, drop spoonfuls of batter, fry the fritters on both sides until golden brown, and drain on kitchen paper."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Placki_z_cukinii","page":"Książka kucharska/Placki z cukinii"},{"id":"oc-plws-546708","title":"Placki ziemniaczane (crispy potato pancakes)","cuisine":"European","category":"Main","ingredients":["1.2 kg large potatoes (orig. 1 kg 20 dkg)","50 g vegetable oil (orig. 5 dkg (2 tbsp))","to taste salt"],"steps":["Peel, rinse, and grate the potatoes on a fine grater.","If the grated potato mass releases excess liquid, pour off 1 tbsp of liquid from the surface, then season with salt to taste and stir.","Heat the vegetable oil well in a skillet, spoon out portions of the mixture (about 16 small pancakes in total), and fry thin pancakes for about 3–4 minutes on each side until deeply browned."],"time":40,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Racuchy_kartoflane","page":"109 potraw/Racuchy kartoflane"},{"id":"oc-plwb-13055","title":"Placki ziemniaczane (potato pancakes)","cuisine":"European","category":"Main","ingredients":["6 potatoes (medium-sized (about 800 g))","1 onion","1 egg","4.5 tbsp wheat flour","1 tsp salt","4 tbsp vegetable oil (or lard for frying)"],"steps":["Wash and thinly peel the potatoes, rinse them again, and grate on a box grater into a bowl.","Peel the onion, finely dice it, and add to the grated potatoes along with the egg, wheat flour, and salt.","Mix the batter thoroughly with a spoon until the potatoes and onion release their juices and the mixture becomes cohesive.","Heat the fat well in a skillet and drop spoonfuls of the potato batter into the hot pan, stirring the mixture in the bowl before each batch.","Fry the pancakes on both sides until golden brown, flipping them with a spatula."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Placki_ziemniaczane","page":"Książka kucharska/Placki ziemniaczane"},{"id":"oc-plws-547336","title":"Plums pickled in spiced vinegar","cuisine":"European","category":"Preserve","ingredients":["1 kg węgierka plums (orig. 1 kilogram of fine ripe węgierka plums, the bloom wiped off)","500 g sugar (orig. half a kilogram of sugar chopped into small pieces)","375 ml vinegar (orig. one and a half szklanki of the best, not too strong vinegar)","20 cloves (for studding the plums in several places)","2 g cinnamon (a piece of bark, added on the third day)","10 g lemon peel (thinly sliced, added on the third day)","375 ml dry red wine (optional in the wine variant (orig. 1 bottle = 750 ml of red wine and 500 ml of vinegar per 2 kg of plums))"],"steps":["Wipe the bloom off 1 kg of ripe węgierka plums, stud each one in several places with cloves, and pack them in an earthenware jar.","Bring 500 g of finely crushed sugar to the boil with 375 ml of good vinegar (for a milder version use 250 ml of strong vinegar and 375 ml of dry red wine per 1 kg of plums), skim carefully, and pour the lukewarm liquor over the plums.","On the second day, pour off the vinegar liquor, bring it to the boil, and pour it a little warmer over the plums.","On the third day, pour off the liquor again, add cinnamon and thinly sliced lemon peel, bring it to the boil, and pour it boiling over the plums.","On the fourth day, pour off the liquor, bring it to the boil, add the plums, and bring it once gently to the boil so the skins do not burst. Cool completely, pack into a jar, seal, and store in a dry, cool pantry."],"time":35,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_ze_%C5%9Bliwek_w_occie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa ze śliwek w occie"},{"id":"oc-plws-555211","title":"Plums preserved in syrup","cuisine":"European","category":"Preserve","ingredients":["1 kg plums (white, yellow, red or green, ripe, large and unblemished)","1.2 kg sugar (about 450 g for the first light syrup and 750 g for the fresh thick syrup in the jars)","1 l water (500 ml for each of the two syrups (plus cold water for heating and for the 3-hour soak))"],"steps":["Prick ripe, sound plums with a wooden pin, put them in a pan of cold water, and heat them until the first bubbles show on the surface, without letting the water boil hard.","Pour off the hot water and put the plums into cold water for 3 hours, so they firm up well.","After 3 hours, drain the plums, cover them with a light lukewarm syrup of 450 g of sugar and 500 ml of water, and leave them in it for 24 hours.","The next day, pour off the first syrup (it can be used for fruit soups or cordials), pack the plums into jars, cover them with a fresh thick syrup of 750 g of sugar and 500 ml of water, seal, and pasteurize in a kettle of water (or in the oven) for about 25–30 minutes. Take the jars out only after the water has cooled."],"time":600,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_rozmaitych_%C5%9Bliwek","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z rozmaitych śliwek"},{"id":"oc-plws-42487","title":"Poached Apple Compote (Kompot z jabłek)","cuisine":"European","category":"Dessert","ingredients":["10 apples (large, tart varieties (e.g. White Transparent or Reinette))","200 g sugar (orig. half a funt)","250 ml water (orig. 1 kwaterka for the syrup, plus cold water for soaking the apples)","1 cinnamon stick (a piece of bark)","250 ml white wine (orig. 1 szklanka of French or Rhine wine)","to taste whole-fruit preserves (and apple or currant jelly, optionally for garnish)"],"steps":["Peel the apples, cut them in half, remove the cores, and drop the fruit immediately into cold water to prevent browning.","In a wide, shallow saucepan, bring 250 ml of water, the sugar, the piece of cinnamon stick, and the white wine to a boil to form a light syrup.","Place the first batch (10 halves) of apples into the boiling syrup, poach until tender while taking care they do not fall apart, and lift out with a slotted spoon into a serving bowl.","Poach the remaining 10 apple halves in the same manner and arrange them in the bowl.","Strain the remaining syrup, reduce over higher heat until slightly thickened, and pour over the arranged apples; before serving, you may garnish the dessert with whole-fruit preserves and fruit jelly."],"time":45,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Komput_z_jab%C5%82ek","page":"365 obiadów za 5 złotych/Komput z jabłek"},{"id":"oc-plws-42469","title":"Poached Sour Cherry Compote (Kompot z wiśni)","cuisine":"European","category":"Dessert","ingredients":["60 sour cherries (orig. 1 kopa (60 cherries, preferably Morello sour cherries, unpitted))","100 g sugar (orig. a quarter funt)","125 ml water (orig. half a szklanka)"],"steps":["Wash the sour cherries and remove the stems, leaving the stones inside the fruit.","Boil the water and sugar in a small saucepan into a thick syrup.","Drop the cherries into the boiling syrup, bring to a boil several times over low heat, and pour everything into a serving bowl."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Komput_z_wisien","page":"365 obiadów za 5 złotych/Komput z wisien"},{"id":"oc-plws-551543","title":"Podolian cordial of sweet and sour cherries","cuisine":"European","category":"Drink","ingredients":["1000 g black sweet cherries (orig. 2 parts)","500 g ripe sour cherries (orig. 1 part (a third of all the fruit))","1 l 95% rectified spirit (to cover the fruit; orig. the syrup proportion is given per 1 litre of drawn-off spirit)","300 g sugar (orig. from a quarter kilogram (250 g) to one and a half quarters of a kilogram (375 g) per 1 l of spirit)","250 ml water (orig. a quarter litre for the syrup)"],"steps":["Put two parts of black sweet cherries (1000 g) and one part of ripe sour cherries (500 g) into a demijohn, cover them with spirit, and leave it in a shaded place for 3 months.","After 3 months, pour the spirit off the fruit and strain it through white flannel or thick muslin.","For every 1 litre of drawn-off spirit, cook a syrup from 300 g of sugar and 250 ml of water, then pour the still-hot syrup into the cold fruit spirit and mix well.","Bottle the cordial, cork it, and leave it in a cool place for another 6 months to mature fully."],"time":10,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Nalewka_podolska_z_czere%C5%9Bni_i_wi%C5%9Bni","page":"Doświadczone sekreta smażenia konfitur i soków/Nalewka podolska z czereśni i wiśni"},{"id":"oc-plws-450884","title":"Podłużny tort czekoladowy łatwy do krojenia (oblong chocolate almond loaf torte)","cuisine":"European","category":"Cake","ingredients":["10 eggs (separated into yolks and whites)","250 g icing sugar (orig. a quarter kilo)","250 g chocolate (orig. a quarter kilo, melted)","250 ml breadcrumbs (orig. 1 szklanka for the batter plus a little for dusting the tin)","6 bitter almonds (orig. a few, pounded)","15 g butter (for greasing the tin)","to taste chocolate fondant (for icing)","50 g sweet almonds (cut into thin slivers for studding the top)"],"steps":["Beat 10 egg yolks with 250 g of icing sugar until pale, add 250 g of melted chocolate, and continue beating until the mixture visibly increases in volume.","Stir in 250 ml (1 szklanka) of breadcrumbs and a few finely pounded bitter almonds, then gently fold in the stiffly beaten whites from the 10 eggs.","Transfer the batter to an oblong loaf tin greased with butter and dusted with breadcrumbs, and bake in a moderately warm oven (about 165–170 °C) for about 45–50 minutes.","Unmould the cake, let it cool completely, ice with chocolate fondant, and stud thickly with sweet almonds cut into thin slivers."],"time":85,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_czekoladowy%2C_%C5%82atwy_do_krajania","page":"Ciasta wielkanocne/Tort czekoladowy, łatwy do krajania"},{"id":"oc-plws-44963","title":"Polish carp in grey sauce (Karp na szaro)","cuisine":"European","category":"Main","ingredients":["1 carp (orig. 1 carp with its blood and milt or roe)","to taste vinegar (salted and boiled, for catching the carp blood)","to taste salt (toasted salt, for salting the carp steaks and the vinegar)","to taste beer (for simmering the vegetable court-bouillon)","1 parsley root","1 celeriac","1 leek","1 carrot","1 dried mushrooms (orig. 1 mushroom)","2 onion (orig. a couple of onions)","to taste black pepper (whole peppercorns)","to taste allspice","1 bay leaf (orig. bay leaf)","2 cloves (orig. a couple of cloves)","1 slice rye bread (a piece of crust)","1 tbsp butter (for the roux)","1 tbsp plain wheat flour (for the roux)","2 tsp sugar (orig. a couple of sugar lumps)","1 tsp caramel (burnt sugar)","125 ml red wine (orig. half a szklanka, or the juice of half a lemon)","1 raisins (orig. 1 handful of scalded raisins)","0.5 lemon (a little peel for the broth, plus slices for garnish)"],"steps":["While dressing the carp, catch its blood in boiled salted vinegar, then cut the cleaned fish into steaks (dzwonka) and salt them along with the milt or roe.","Simmer a court-bouillon in beer with the parsley root, celeriac, leek, carrot, dried mushroom, onions, peppercorns, allspice, bay leaf, and cloves for about 25 minutes.","Place the carp head on the bottom of a pot, lay the fish steaks on top, add the lemon peel and rye bread crust, pour in the hot beer broth, and boil briskly over high heat for about 20 minutes.","In a separate saucepan, brown a tablespoon of butter with a tablespoon of wheat flour and let cool slightly.","Whisk the carp blood in vinegar into the cooled roux, add the sugar and burnt caramel, and thin with the fish cooking liquor.","Pour the red wine into the sauce, add the scalded raisins, and simmer over low heat for about 10 minutes until thickened.","Arrange the cooked carp on a platter, garnish with lemon slices and raisins, and pour the hot grey sauce generously over the fish."],"time":100,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Karp_na_szaro","page":"365 obiadów za 5 złotych/Karp na szaro"},{"id":"oc-plwb-8983","title":"Polish dried mushroom sauce with sour cream","cuisine":"European","category":"Sauce","ingredients":["25 g dried mushrooms","1 onion (medium)","30 g butter","1 tbsp plain flour","0.5 bouillon cube","125 ml sour cream (thick)","to taste water (for soaking and boiling the mushrooms)","to taste salt","to taste black pepper"],"steps":["Thoroughly rinse the dried mushrooms in warm water, soak for about 2 hours, then cook in the soaking liquid until tender and drain, reserving the broth.","Dice the onion, brown it in part of the butter, stir in the flour, and mix well.","Blend the roux with about 125 ml of cold mushroom broth, bring to a boil, and dissolve the half bouillon cube into the sauce.","Add the sour cream and remaining butter, stir in the chopped mushrooms, and season the sauce to taste with salt and black pepper."],"time":180,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_grzybowy","page":"Książka kucharska/Sos grzybowy"},{"id":"oc-plwb-19153","title":"Polish meatloaf with porcini mushrooms and bacon (Pieczeń z grzybami)","cuisine":"European","category":"Main","ingredients":["1 kg ground beef and pork","2 onions (large)","1 kaiser roll","2 eggs","to taste salt","to taste black pepper","to taste nutmeg","3 frozen porcini mushrooms","200 g smoked bacon (sliced)","1 tbsp gelatine powder","125 ml broth (hot)","100 ml water (for soaking the bread roll)"],"steps":["Soak the kaiser roll in water, squeeze out thoroughly, and combine with the minced meat.","Peel and finely chop the onions, add to the meat along with the eggs, season with salt, pepper, and nutmeg, and knead the mixture thoroughly.","Slice the porcini mushrooms and gently fold them into the meat mixture.","Line a loaf tin with slices of smoked bacon, fill with the meat mixture, press down lightly, and bake for 40–50 minutes in an oven preheated to 180 °C.","Dissolve the gelatine in the hot broth, chill until set, cut the aspic into cubes, and arrange around the cooled meatloaf."],"time":75,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Piecze%C5%84_z_grzybami","page":"Książka kucharska/Pieczeń z grzybami"},{"id":"oc-plwb-16849","title":"Polish mushroom noodle soup (Zupa grzybowa z makaronem)","cuisine":"European","category":"Soup","ingredients":["60 g dried mushrooms (porcini, slippery jacks, or bay boletes) (50–70 g)","1 bunch Polish soup vegetables (włoszczyzna) (bunch)","5 black peppercorns (a few peppercorns)","4 allspice (a few berries)","to taste vinegar or lemon juice","to taste salt","250 g pasta (ribbons, penne, or shells)","1.5 l water (for cooking the stock)","to taste dill or parsley leaves (chopped, for serving)","1 tbsp butter (for the roux)","1 tbsp all-purpose flour (for the roux)","1 onion (small (or half a larger one), finely chopped, for the roux)"],"steps":["Scald the dried mushrooms with boiling water, rinse them, and simmer gently covered.","Peel and wash the soup vegetables, add whole to the mushrooms along with peppercorns and allspice berries, simmer for 25–30 minutes, then strain the broth.","Slice the caps of the cooked mushrooms into thin strips, return them to the broth, and season the soup with salt and vinegar or lemon juice.","Melt a tablespoon of butter in a skillet, sauté the finely chopped onion and transfer it to the soup, then briefly cook a tablespoon of flour in the remaining fat until it loses its raw taste without browning. Whisk in a few tablespoons of broth and pour into the pot. Optionally, stir in sour cream.","Cook the pasta separately, drain, rinse with cold water, divide among plates, ladle hot soup over, and serve with chopped dill or parsley leaves."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_grzybowa_z_makaronem","page":"Książka kucharska/Zupa grzybowa z makaronem"},{"id":"oc-plws-546619","title":"Polish Vegetable and Cabbage Milk Soup (Miszkulancja)","cuisine":"European","category":"Soup","ingredients":["2 carrot (whole)","1 parsley root (whole)","1 leek (whole)","400 g white or Savoy cabbage (orig. 40 dkg)","400 g potatoes (orig. 40 dkg)","2 black peppercorns (whole peppercorns)","1 bay leaf (whole leaf)","500 ml milk (orig. half a liter)","1.5 l water (orig. one and a half liters)","to taste salt (to taste)","30 g butter or rendered pork fatback (orig. 3 dkg)"],"steps":["Peel the carrots, parsley root, and leek, cut into thin strips, and bring to a boil in 1.5 liters of salted water.","Add the coarsely chopped cabbage, peppercorns, and bay leaf, and simmer over low heat.","About 20 minutes before serving, add the peeled and diced potatoes.","After the potatoes have cooked for 10 minutes, pour in the milk and simmer for another 10 minutes until all the vegetables are tender, then pour the soup into a tureen with the butter or rendered pork fatback."],"time":60,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Miszkulancja_z_mlekiem","page":"109 potraw/Miszkulancja z mlekiem"},{"id":"oc-plws-1081061","title":"Poppy Seed Lattice Pastries","cuisine":"European","category":"Cookie","ingredients":["500 g yeast dough, Danish pastry, or puff pastry (for round bases with a rim and a lattice for the top)","400 g poppy seeds (originally 1 funt, ground dry without scalding)","400 g sugar (originally 1 funt)","100 g sweet almonds (orig. 8 łut, peeled and finely ground)","8 egg yolks (whole yolks)","4 eggs (whole eggs)","0.25 tsp ground cinnamon (half a teaspoon together with the cloves)","0.25 tsp ground cloves","100 g translucent sugar glaze (for brushing after baking)"],"steps":["Thoroughly grind the dry poppy seeds with the sugar and the blanched, finely ground almonds.","Beat the egg yolks and whole eggs into the poppy seed mixture one at a time, add the ground cinnamon and cloves, and mix thoroughly.","Shape round bases with a raised rim from the yeast or puff pastry so that the poppy seed filling does not run out.","Spread a layer of the poppy seed filling about 1.5–2 cm thick onto the pastry bases and arrange a thin lattice of pastry strips on top.","Place the pastries immediately into a hot oven (200 °C) and bake for 15–20 minutes.","As soon as you take them out of the oven, brush the hot pastries with translucent sugar glaze."],"time":65,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciasteczka_makowe","page":"Baby, placki i mazurki/Ciasteczka makowe"},{"id":"oc-plwb-7900","title":"Poppy seed torte (Torcik makowy)","cuisine":"European","category":"Cake","ingredients":["300 g dry poppy seeds","300 g icing sugar","125 g butter (or vegetable margarine)","2 egg yolks","3 tbsp sugar","4 tbsp runny honey","100 g raisins","3 tbsp candied orange peel","3 tbsp chopped mixed dried fruit and nuts (heaped: figs, dates, apricots, and nuts)","4 tsp cocoa powder","4 tsp water","4 tsp butter (heaped)","100 g sugar","to taste vanilla sugar"],"steps":["Pour boiling water over the dry poppy seeds, simmer over very low heat for 10 minutes, then drain thoroughly on a fine sieve and let cool.","Pass the cooled poppy seeds three times through a meat grinder, adding alternating tablespoons of poppy seeds and icing sugar during the third grinding.","Beat the butter with three tablespoons of sugar until pale and fluffy, add the egg yolks one by one, then, continuing to beat, add the honey, ground poppy seeds, raisins, candied orange peel, and chopped mixed dried fruit and nuts.","Transfer the poppy seed mixture to a medium springform cake tin lined with cling film, press down firmly, and refrigerate for about 12 hours.","Place the cocoa powder, water, four teaspoons of butter, sugar, and vanilla sugar in a saucepan, bring to the boil, and simmer over low heat for 7 minutes, stirring constantly.","Remove the saucepan from the heat, place it in a bowl of cold water for one minute, and beat the glaze until it begins to thicken.","Turn the chilled torte out onto a serving platter, pour over the thickening cocoa glaze immediately, and chill again before slicing into portions."],"time":600,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Torcik_makowy","page":"Książka kucharska/Torcik makowy"},{"id":"oc-plws-1081030","title":"Poppy-seed torte","cuisine":"European","category":"Cake","ingredients":["300 g dry poppy seed (orig. 24 łuty dry grey poppy seed)","400 g sugar (orig. 1 funt)","100 g sweet and bitter almonds (orig. 8 łutów)","10 eggs (whole eggs)","6 egg yolks","3 g ground cinnamon and cloves (orig. half a łyżeczka)","15 g butter for the tin","150 g sharp jam for the filling","100 g punch icing"],"steps":["Grind the dry poppy seed three times to a fine dust, or pound it with the sugar in a bowl.","Add the ground almonds, cinnamon and cloves, then beat in the whole eggs and the extra yolks one at a time until the mixture has grown a great deal and turned pale.","Pour the batter into a buttered springform tin.","Bake in an oven heated to 175 °C for about 45 minutes.","Once cool, cut the torte into two layers, fill it with sharp jam, and pour punch icing over it."],"time":105,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Tort_makowy","page":"Baby, placki i mazurki/Tort makowy"},{"id":"oc-plwb-18174","title":"Pork braised in beer with caraway (Wieprzowina z piwem)","cuisine":"European","category":"Main","ingredients":["600 g boneless pork","1 tbsp lard or vegetable oil","250 ml beer (1 glass (250 ml))","2 tbsp grated dry bread","1 tbsp caraway seeds","to taste salt","to taste ground black pepper","1 onion","to taste water (to top up the gravy if needed)"],"steps":["Rinse and pat dry the pork, cut into thin strips, brown in the hot lard or oil, and transfer to a pot.","Peel and chop the onion, cook until translucent in the fat left from frying the meat, and transfer to the pot.","Add the caraway seeds, salt, and black pepper, pour over the beer and top up with water if needed, then cover and braise until tender.","Add the grated dry bread, stir, and simmer for another 3–5 minutes until the sauce thickens."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wieprzowina_z_piwem","page":"Książka kucharska/Wieprzowina z piwem"},{"id":"oc-plws-42433","title":"Pork kidneys braised in Madeira sauce","cuisine":"European","category":"Main","ingredients":["2 pork kidneys (orig. large pork kidneys)","1 tbsp butter","1.5 tbsp plain wheat flour (1 tbsp for the roux and 1/2 tbsp for dusting)","125 ml meat bouillon (orig. half of 1 kwaterka (125 ml))","125 ml Madeira wine (orig. half of 1 kwaterka (125 ml))","1 onion","to taste black pepper","to taste salt"],"steps":["Roast the onion in the oven until soft, peel, and mash or rub through a sieve to a smooth purée.","Trim the pork kidneys, parboil several times in boiling water while skimming carefully (about 15 minutes), then cool and cut into thin slices.","Brown the butter with 1 tablespoon of wheat flour in a skillet or saucepan, whisk in the bouillon and Madeira wine, stir in the sieved roasted onion, and bring the sauce to a boil.","Season the sliced kidneys with salt, dust with the remaining wheat flour and pepper, add to the sauce, and braise covered over low heat for about 60 minutes until tender."],"time":110,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Cynadry_wieprzowe_w_maderze","page":"365 obiadów za 5 złotych/Cynadry wieprzowe w maderze"},{"id":"oc-plwb-16499","title":"Pork liver soup (Wątrobianka)","cuisine":"European","category":"Soup","ingredients":["400 g pork liver","50 g butter","1 tbsp plain flour","to taste meat broth (for simmering the soup)","2 egg yolks","to taste salt"],"steps":["Trim the pork liver, chop it finely, and braise gently in the butter.","Dust the liver with plain flour and cook gently for a moment longer, stirring.","Pour in the meat broth and simmer over low heat until tender.","Pass the soup through a sieve, bring back to the boil, season with salt, and pour hot into a tureen over the whisked egg yolks."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/W%C4%85trobianka","page":"Książka kucharska/Wątrobianka"},{"id":"oc-plwb-14176","title":"Pork loin roasted in fresh herbs and pork belly (Schab pieczony w świeżych ziołach)","cuisine":"European","category":"Main","ingredients":["1.5 kg boneless pork loin","2.5 slice fresh pork belly strips (wide, for wrapping around the roast)","1 bunch fresh thyme","1 bunch fresh mint","4 fresh rosemary sprigs","to taste sea salt","to taste mixed peppercorns (coarsely ground)","200 g butter","4.5 tbsp olive oil","250 ml dry white wine (half at the start, half after 30 minutes of roasting)"],"steps":["Rub the pork loin with sea salt, coarsely ground pepper, and part of the torn fresh herbs, then press the remaining herbs all over the outside of the meat.","Wrap the pork loin in strips of fresh pork belly, tie securely with kitchen twine, and place in a roasting pan.","Cut the butter into strips and arrange on top of the meat, drizzle everything with olive oil, and pour half of the white wine into the bottom of the roasting pan.","Place the roasting pan in an oven preheated to 200 °C, baste the meat with the remaining wine after 30 minutes, and continue roasting for another 60–90 minutes.","Remove the roasted pork loin from the oven, cover loosely with aluminium foil, and let rest for 30 minutes before carving."],"time":125,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Schab_pieczony_w_%C5%9Bwie%C5%BCych_zio%C5%82ach","page":"Książka kucharska/Schab pieczony w świeżych ziołach"},{"id":"oc-plwb-21940","title":"Pork loin skewers (Szaszłyki ze schabu)","cuisine":"European","category":"Main","ingredients":["400 g boneless pork loin","500 g baby potatoes","100 g pork belly (sliced)","1 red bell pepper","1 grapes (small bunch)","3 tbsp olive oil","1 tsp sweet ground paprika","to taste salt","to taste pepper"],"steps":["Peel the baby potatoes and parboil in salted water until half-tender, then drain.","Rinse the pork loin and cut into large cubes. Rub the potatoes and meat with a mixture of olive oil, ground paprika, salt, and pepper, then leave in a cool place for 30 minutes.","Wrap the parboiled potatoes in slices of pork belly, and cut the red bell pepper into chunks.","Thread the pork belly-wrapped potatoes, pork loin cubes, grapes, and bell pepper alternately onto skewers.","Cook the skewers on a preheated grill or in the oven for about 15 minutes, turning every few minutes to cook all sides."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szasz%C5%82yki_ze_schabu","page":"Książka kucharska/Szaszłyki ze schabu"},{"id":"oc-plwb-13998","title":"Pork loin stuffed with dried fruit (Schab nadziewany suszonymi owocami)","cuisine":"European","category":"Main","ingredients":["1 kg boneless pork loin","100 g dried apricots","100 g dried prunes","2 tbsp butter","100 ml dry red wine","1 clove garlic","to taste dried marjoram","to taste salt","to taste black pepper"],"steps":["Wash and pat the pork loin dry, rub it with salt, pepper, marjoram, and crushed garlic, then cover and refrigerate for about 60 minutes.","Pour the red wine over the dried apricots and prunes and set aside to soak.","Cut a deep pocket lengthwise along the grain of the meat and stuff it with the soaked fruit.","Sear the pork loin in hot melted butter on all sides until golden brown.","Transfer the meat to a roasting pan, pour over the pan fat, remaining wine, and a few tablespoons of water, and cover with a lid.","Roast for 60 minutes in an oven preheated to 180 °C, basting the meat frequently with the pan juices."],"time":90,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Schab_nadziewany_suszonymi_owocami","page":"Książka kucharska/Schab nadziewany suszonymi owocami"},{"id":"oc-plwb-26877","title":"Pork steaks with apple and onion sauce (Steki wieprzowe)","cuisine":"European","category":"Main","ingredients":["500 g pork neck (collar)","4 tbsp lard","1 tsp mustard","1 tsp honey","to taste lemon juice","to taste olive oil","1 pinch Polish herb and spice seasoning (pieprz ziołowy)","1 pinch salt","1 pinch herbes de Provence","1 pinch ginger","1 clove garlic (crushed)","2 onions (large)","2 apples (small and soft)"],"steps":["Take the pork collar out of the refrigerator 30 minutes before preparation, slice into steaks, trim membranes, and pound the meat very lightly.","Mix the mustard, honey, lemon juice, a little olive oil, Polish herb and spice seasoning, salt, some of the herbes de Provence, ginger and crushed garlic. Brush the marinade over the steaks and leave for 10 minutes.","Finely chop the onions and fry in olive oil with herbes de Provence until tender, then add the finely chopped apples and remaining marinade and fry for a few minutes.","Get the lard very hot in a skillet, quickly sear the steaks on both sides and edges, transfer to a roasting tin, and pour the pan drippings into the onion-apple sauce.","Place the steaks in an oven preheated to 140 °C, raise the temperature to 180 °C, bake for 12 minutes, and serve with the onion-apple sauce."],"time":75,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Steki_wieprzowe","page":"Książka kucharska/Steki wieprzowe"},{"id":"oc-plws-508400","title":"Potato and hard-boiled egg salad with olive oil and herbs","cuisine":"European","category":"Salad","ingredients":["5 eggs","5 potatoes (medium, even-sized)","to taste chives (finely chopped)","to taste fresh dill (finely chopped)","to taste salt","to taste black pepper","to taste olive oil (generous amount for dressing)","1 lemon (freshly squeezed juice (or tarragon vinegar))"],"steps":["Boil the unpeeled potatoes for about 25 minutes until tender, and hard-boil the eggs in a separate pot for 10 minutes.","Cool and peel both the potatoes and the eggs, then slice them into even rounds.","Arrange alternating rows of potato slices and egg slices in a salad bowl, scatter generously with finely chopped chives and dill, and season with salt and pepper.","Drizzle generously with olive oil and freshly squeezed lemon juice, then chill in a cool place for about 120 minutes before serving so the flavors meld."],"time":160,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Sa%C5%82atka_z_jaj_z_kartoflami","page":"100 potraw z jaj/Sałatka z jaj z kartoflami"},{"id":"oc-plws-543035","title":"Potato balls fried in butter","cuisine":"European","category":"Side","ingredients":["1 l potatoes (orig. 1–1½ kwarty; 1–1.5 l, volume measure of potatoes (historical measure, converted approximately))","2 tbsp butter (orig. a couple of tbsp; 30 ml, described in the method as a generous amount)","to taste fine salt","to taste water (Boiling, for scalding.)"],"steps":["Peel the raw potatoes.","Using a melon baller, scoop small balls from the potatoes.","Scald the balls with boiling water.","Season the balls with fine salt.","Melt the butter in a frying pan or saucepan.","Fry the potato balls in the butter until tender."],"time":null,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kartofle_sma%C5%BCone_w_ca%C5%82ku","page":"Kucharka litewska (1913)/Kartofle smażone w całku"},{"id":"oc-plwb-14353","title":"Potato salad with egg (Sałatka ziemniaczana z jajkiem)","cuisine":"European","category":"Salad","ingredients":["3 tomatoes (ripe)","250 g potatoes","250 g celeriac","1 onion (large)","2 eggs (hard-boiled)","2 tbsp parsley leaves (chopped)","3 tbsp olive oil","1 tbsp lemon juice","to taste salt","to taste black pepper"],"steps":["Whisk together the olive oil and lemon juice, season with salt and pepper, and set the dressing aside.","Peel the potatoes, boil until tender, allow to cool, and slice into thick half-rounds.","Peel and wash the celeriac, pat dry, and cut into thin matchsticks, then cut the tomatoes into wedges.","In a salad bowl, combine the potatoes, celeriac, and tomatoes, then arrange onion rings and eggs cut into eighths on top.","Scatter the chopped parsley leaves over the salad and drizzle with the prepared dressing."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_ziemniaczana_z_jajkiem","page":"Książka kucharska/Sałatka ziemniaczana z jajkiem"},{"id":"oc-plws-42505","title":"Potato salad with herring and gherkins (sałatka ziemniaczana ze śledziem)","cuisine":"European","category":"Salad","ingredients":["1.2 kg potatoes (orig. half a garniec (2 Polish kwarty))","1 salted herring with milt (whole, unsoaked)","4 pickled gherkins (orig. several whole)","1 small onion","2 tbsp olive oil","1 tbsp vinegar","1 pinch sugar","to taste black pepper"],"steps":["Boil the potatoes in their skins until tender (for about 25 minutes), let cool, peel, and cut into strips, slices, or dice.","Clean the herring (without soaking) of skin and bones, and dice the meat together with the milt finely.","Slice the pickled gherkins thinly and grate the onion.","Combine the potatoes, herring with milt, gherkins, and onion in a salad bowl, add vinegar and olive oil, season with pepper and a pinch of sugar, and toss thoroughly."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sa%C5%82ata_z_kartofli_ze_%C5%9Bledziami","page":"365 obiadów za 5 złotych/Sałata z kartofli ze śledziami"},{"id":"oc-plwb-19468","title":"Potato salad with pickled mushrooms (Sałatka ziemniaczana)","cuisine":"European","category":"Salad","ingredients":["600 g potatoes","100 g pickled button mushrooms (and 2 tbsp brine for the dressing)","100 ml sour cream (thick)","50 ml olive oil","2 tbsp fresh chives (chopped)","to taste salt","to taste black pepper"],"steps":["Boil the potatoes in their jackets until tender, let cool slightly, peel, and dice into cubes.","Drain the pickled button mushrooms (reserving 2 tbsp of the brine) and dice the mushrooms.","Whisk together the sour cream, olive oil, and 2 tbsp of the mushroom brine, then season the dressing with salt and pepper.","Combine the potatoes, pickled mushrooms, and chopped chives, pour over the dressing, toss well, and chill in a cool place for 30 minutes."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_ziemniaczana","page":"Książka kucharska/Sałatka ziemniaczana"},{"id":"oc-plws-543021","title":"Potatoes fried with onion","cuisine":"European","category":"Side","ingredients":["2 l potatoes (orig. ½–three quarters of a garniec; 2–3 l, volume measure of potatoes (historical measure, converted approximately))","2 tbsp butter (orig. 2 tbsp; 30 ml)","0.5 onion (Optional.)","to taste salt"],"steps":["Peel and rinse the potatoes.","Cut the potatoes into slices and season with salt.","Chop the onion, if using.","Melt the butter in a saucepan.","Sauté the onion in the butter.","Add the potatoes.","Cook gently, covered, over low heat until the potatoes are tender and browned."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kartofle_sma%C5%BCone","page":"Kucharka litewska (1913)/Kartofle smażone"},{"id":"oc-plwb-17188","title":"Potatoes in sour cream sauce (Ziemniaki w sosie śmietanowym)","cuisine":"European","category":"Side","ingredients":["800 g potatoes","4 tbsp thick sour cream","3 tbsp chives (chopped)","3 tbsp vegetable oil (1 tablespoon for the pan, 2 tablespoons for the sauce)","to taste nutmeg","to taste salt","to taste black pepper"],"steps":["Boil the potatoes in their skins, peel them, and cut into slices.","Arrange the potato slices on a baking sheet greased with 1 tablespoon of oil and season with salt and pepper.","Mix the remaining 2 tablespoons of oil with the sour cream, season with nutmeg, and pour the sauce over the potatoes.","Bake in an oven preheated to 180 °C for about 30 minutes, and sprinkle with chopped chives before serving."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ziemniaki_w_sosie_%C5%9Bmietanowym","page":"Książka kucharska/Ziemniaki w sosie śmietanowym"},{"id":"oc-plws-39727","title":"Potrawa z główki cielęcej w sosie cytrynowo-winnym (calf's head with lemon-wine sauce)","cuisine":"European","category":"Main","ingredients":["2 kg calf's head (cleaned, with brains)","1 bunch soup greens","to taste salt","2 eggs","100 g breadcrumbs","60 g clarified butter (for browning)","30 g butter (1 tablespoon)","1 tbsp plain flour","100 ml dry white wine (dry)","1 lemon (juice and grated zest)","1 tsp sugar"],"steps":["Soak the calf's head in cold water for an hour, remove the brain, scald the meat with boiling water, and skim off any foam.","Simmer the head with soup greens and salt over low heat for about 2 hours until tender, then remove and cut into serving pieces.","Coat pieces of cooked calf's head in beaten egg and breadcrumbs, then brown in the oven with clarified butter.","Cut the parboiled brain into slices, dip in egg yolk and breadcrumbs, and fry in a pan until golden.","In a saucepan brown a tablespoon of butter with a tablespoon of flour, whisk in stock from the head, add white wine, lemon juice, grated lemon zest, and sugar, and bring to a simmer.","Arrange the browned calf's head on a platter, garnish with brain cutlets, and pour the hot lemon-wine sauce over the top."],"time":195,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Potrawa_z_g%C5%82%C3%B3wki_ciel%C4%99cej","page":"365 obiadów za 5 złotych/Potrawa z główki cielęcej"},{"id":"oc-plws-44996","title":"Potrawa z kaczki lub kury duszona z ryżem (braised duck or chicken with rice)","cuisine":"European","category":"Main","ingredients":["1.8 kg duck (or chicken, cut into serving portions)","60 g butter (for braising poultry)","2 parsley root","0.5 celeriac","1 leek","2 carrot","1 pinch nutmeg","to taste salt","300 g rice (scalded before braising)","30 g butter (1 tablespoon for the rice)","1 tsp plain flour (for thickening the sauce)"],"steps":["Cut the prepared bird into serving pieces, place into a pot, add a knob of butter, peeled sliced root vegetables, and a splash of water and salt.","Braise covered over low heat for about 50 minutes, turning the meat pieces occasionally.","In a separate pot scald the rice with boiling water, drain, add a tablespoon of butter, and braise over low heat, gradually spooning in braising broth from the poultry until tender and fluffy.","Arrange the tender meat in the centre of a platter with breasts on top, and form a border of braised rice all around.","Strain the meat broth, thicken with a little flour whisked with a tablespoon of water, season with a pinch of nutmeg, bring to a brief boil, and pour over the meat and rice."],"time":80,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Potrawa_z_kaczek_lub_kur_z_ry%C5%BCem","page":"365 obiadów za 5 złotych/Potrawa z kaczek lub kur z ryżem"},{"id":"oc-plws-44998","title":"Potrawa z kaczki z białą kapustą (braised duck with white cabbage)","cuisine":"European","category":"Main","ingredients":["1.8 kg duck (jointed into pieces)","1 bunch soup greens","3 allspice berries","1 bay leaf","to taste salt","2 white cabbage (small heads of sweet white cabbage)","30 g butter (1 tablespoon)","1 tbsp plain flour","2 tbsp dill (or finely chopped onion)","100 ml sour cream (thick sour cream)","3 tbsp breadcrumbs (for sprinkling on top)"],"steps":["Cover jointed duck with a small amount of water, add soup greens, allspice, bay leaf, and salt, and simmer over low heat until tender (about 45 minutes).","Trim the cabbage heads, cook in salted water, drain, and cut into quarters.","In a saucepan make a roux with a tablespoon of butter and a tablespoon of flour, add chopped dill, whisk in duck broth, pour in sour cream, and cook until thick.","In a baking dish arrange duck pieces alternately with cabbage quarters, pour the prepared sauce over, and sprinkle with breadcrumbs.","Bake in an oven preheated to 180 °C for 15 minutes until lightly browned and bubbling."],"time":80,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Potrawa_z_kaczek_z_kapust%C4%85_s%C5%82odk%C4%85","page":"365 obiadów za 5 złotych/Potrawa z kaczek z kapustą słodką"},{"id":"oc-plws-45018","title":"Potrawa z kur lub kapłonów po staropolsku (old Polish chicken or capon dish)","cuisine":"European","category":"Main","ingredients":["2.5 kg chicken (two poulards or chickens, orig. two poulards or chickens)","2 bunch soup greens (coarsely cut soup vegetables)","20 g dried forest mushrooms (white porcini)","1 pinch mace","to taste salt","200 g button mushrooms (fresh, cooked with lemon juice)","100 g butter (orig. a quarter of a historical Polish funt of fresh butter)","2 tbsp plain flour","0.5 lemon (juice)","0.5 tsp sugar","2 egg yolks","50 ml white wine (Rhenish)","200 g puff pastry (baked pastry rim around the platter)"],"steps":["Clean the chickens, cut into neat portions, rinse, place into a pot, and season with salt.","Add plenty of soup greens, dried porcini, and mace, then simmer gently covered for 2–2.5 hours in their own juices with minimal water so the broth is rich.","Cook fresh button mushrooms separately in a small amount of water with lemon juice.","In a saucepan rub butter with flour, blend with mushroom cooking liquid and strained chicken broth, and bring to a boil; add lemon juice and sugar.","Remove the sauce from the heat, temper with two egg yolks beaten with a little cooled broth, add a small glass of Rhenish wine, and warm gently without boiling.","Arrange chicken pieces in the centre of a platter with breasts on top, garnish with mushrooms and a hot baked puff pastry border, and coat with velvety sauce."],"time":180,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Potrawa_z_kur_lub_kap%C5%82on%C3%B3w","page":"365 obiadów za 5 złotych/Potrawa z kur lub kapłonów"},{"id":"oc-plws-45004","title":"Potrawa z kurcząt z warzywami i rakami (chicken fricassee with crayfish and spring vegetables)","cuisine":"European","category":"Main","ingredients":["1.2 kg chicken (young chicken quartered)","1 bunch soup greens","0.5 cauliflower (separated into florets)","to taste salt","200 g asparagus (cut into batons)","2 carrot","100 g crayfish tails (cooked)","30 g butter (1 tablespoon)","1 tbsp plain flour","2 tbsp parsley (finely chopped)"],"steps":["Place chicken in a pot with water, soup greens, cauliflower florets, and salt; simmer over gentle heat until tender (about 25–30 minutes).","Remove the chicken and divide into quarters, transferring the cauliflower florets to a plate.","Cook the chopped asparagus and carrots separately.","In a saucepan melt a tablespoon of butter, blend in a tablespoon of flour, pour in reduced chicken broth, add chopped parsley, and stir constantly until the sauce thickens.","Add the chicken pieces, cooked cauliflower, asparagus, carrots, and crayfish tails to the sauce, and warm everything together gently.","Arrange the chicken on a serving platter, garnish with the vegetables and crayfish tails, and coat generously with the velvety sauce."],"time":70,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Potrawa_z_kurcz%C4%85t","page":"365 obiadów za 5 złotych/Potrawa z kurcząt"},{"id":"oc-plws-39718","title":"Potrawa z mostku cielęcego z warzywami i rakami (veal breast fricassee with vegetables and crayfish)","cuisine":"European","category":"Main","ingredients":["1.2 kg veal breast (cut into chunks)","1 bunch soup greens","to taste salt","30 g butter (1 tablespoon)","1 tbsp plain flour","100 g crayfish tails (cooked)","0.5 cauliflower (separated into florets and cooked)","200 g asparagus (cut into pieces and cooked)","1 tbsp parsley (finely chopped)","200 g calf's brains (parboiled and fried in breadcrumbs)","1 egg","40 g breadcrumbs"],"steps":["Cut veal breast into pieces, blanch briefly in boiling water, skim, and rinse under cold water.","Transfer the meat to a pot, cover with strained broth, add soup greens and salt, and simmer over low heat for 60–80 minutes until completely tender.","In a saucepan make a roux with a tablespoon of butter and a tablespoon of flour, whisk in veal broth, and simmer until thick.","Add cooked crayfish tails, cauliflower florets, asparagus, and chopped parsley to the sauce and bring to a simmer.","Parboil the calf's brain, slice, coat in beaten egg and breadcrumbs, and fry in butter until golden.","Arrange pieces of veal on a platter, pour hot vegetable and crayfish sauce over them, and garnish around the edge with crisp brain cutlets."],"time":120,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Potrawa_z_mostku_ciel%C4%99cego","page":"365 obiadów za 5 złotych/Potrawa z mostku cielęcego"},{"id":"oc-plwb-21733","title":"Potrawka z kaczek z kapustą (duck fricassee with cabbage)","cuisine":"European","category":"Main","ingredients":["2 duck (whole carcasses)","1.5 white cabbage (1–2 heads)","2 carrot","1 parsley root","1 leek","1 onion","6 allspice berries (5–6 berries)","3 bay leaf (2–3 pcs)","1 tbsp butter","1 tbsp plain flour (for the roux)","2 tbsp breadcrumbs","3 fresh dill (2–3 sprigs, chopped)","3 tbsp sour cream (thick, a few tablespoons)","to taste salt"],"steps":["Boil the heads of white cabbage in salted water, drain, and cut into quarters.","Quarter the ducks and cook until tender in water with the carrots, parsley root, leek, onion, allspice berries, and bay leaves.","Arrange the cooked duck portions in a baking dish alternating with the cabbage quarters, and sprinkle with breadcrumbs.","Sauté 1 tablespoon of plain flour with 1 tablespoon of butter in a skillet, add the chopped dill, whisk in broth from cooking the ducks, stir in the sour cream, and cook for a few minutes, stirring constantly until the sauce thickens.","Pour the prepared sauce over the duck and cabbage and bake for about 15 minutes in an oven preheated to 200 °C."],"time":135,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Potrawka_z_kaczek_z_kapust%C4%85","page":"Książka kucharska/Potrawka z kaczek z kapustą"},{"id":"oc-plwb-14405","title":"Potrawka z kurczaka (Braised chicken with root vegetables)","cuisine":"European","category":"Main","ingredients":["2 chicken leg","2 chicken breast fillet","1 celeriac","2 carrots","1 parsley root","1 onion","to taste parsley","1 bay leaf","to taste allspice","to taste salt","to taste pepper","to taste vegetable oil (for frying)","to taste water (for braising)"],"steps":["Brown the chicken legs and breast fillets in heated oil until golden.","Peel and wash the celeriac, carrots, and parsley root, grate them coarsely, and slice the onion.","In a separate pan with a splash of oil, braise the grated vegetables gently with the onion.","Transfer the braised vegetables to the pot with the chicken, then add the bay leaf, allspice berries, chopped parsley, salt, and pepper.","Braise everything for about 30 minutes, adding a little water as needed."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_w_potrawce","page":"Książka kucharska/Kurczak w potrawce"},{"id":"oc-plws-40798","title":"Potrawka z pieczeni baraniej z agrestem (mutton fricassee with gooseberries)","cuisine":"European","category":"Main","ingredients":["500 g roast mutton (slices of leftover roast)","30 g butter (1 tablespoon)","1 tbsp plain flour","250 ml broth (1 szklanka)","150 g gooseberries (unripe, stemmed, orig. 1 kwaterka)","1 tbsp sugar"],"steps":["Carve leftover roast mutton into neat slices.","Brown a tablespoon of butter in a saucepan, add a tablespoon of flour, and fry the roux, stirring constantly.","Whisk the hot broth and defatted roast juices into the roux.","Add the stemmed unripe gooseberries and sugar, then cook gently for a few minutes until the gooseberries soften slightly.","Add the roast mutton slices to the sauce, warm thoroughly for 5 minutes, and transfer onto a serving platter."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Potrawka_z_pieczeni_baraniej_z_agrestem","page":"365 obiadów za 5 złotych/Potrawka z pieczeni baraniej z agrestem"},{"id":"oc-plws-546634","title":"Pounded beef steaks (bitki wołowe)","cuisine":"European","category":"Main","ingredients":["400 g boneless beef (orig. 40 dkg)","1 large onion","40 g lard or margarine (orig. 4 dkg)","1 tbsp plain wheat flour","2 dried mushrooms (orig. 1–2 whole)","300 ml water (orig. 1 cup (250 ml) for braising + 50 ml for flour)","to taste salt","to taste black pepper"],"steps":["Soak the dried mushrooms overnight (for about 8 hours) in cold water, then slice into thin strips, reserving the soaking water.","Cut the beef across the grain into 4 large or 8 smaller steaks, pound thoroughly with a meat mallet, salt, and dust lightly with pepper.","Sear the steaks on well-heated lard or margarine and transfer to a saucepan.","Add the finely chopped onion and mushroom strips, pour in 250 ml of water along with the mushroom soaking liquid, and braise gently covered for about 60–70 minutes until tender.","Before serving, whisk the plain wheat flour in 50 ml of cold water, stir into the sauce, and bring briefly to a boil."],"time":575,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Zrazy_wo%C5%82owe%2C_bite","page":"109 potraw/Zrazy wołowe, bite"},{"id":"oc-plwb-6256","title":"Poznań-style potato and dried mushroom soup (Zupa ziemniaczana z grzybami po poznańsku)","cuisine":"European","category":"Soup","ingredients":["250 g Polish soup vegetables (włoszczyzna)","20 g dried mushrooms","to taste allspice","1 bay leaf (leaf)","450 g potatoes","40 g fat (for the roux)","30 g onion (for the roux)","30 g all-purpose flour (for the roux)","1.5 l water (for cooking the stock)","to taste salt","to taste vinegar"],"steps":["Rinse and clean the soup vegetables and dried mushrooms, cover with water, and cook a stock with allspice and the bay leaf.","Peel the potatoes and dice them.","Once the vegetables in the stock are tender, strain the stock and cook the diced potatoes in it, then chop the cooked soup vegetables and mushrooms.","Chop the onion and cook gently covered in fat, then add the flour and brown the roux.","Thicken the soup with the roux and bring to a boil, stirring constantly.","Add the chopped vegetables and mushrooms to the soup, and finally season with salt and vinegar to taste."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ziemniaczana_z_grzybami","page":"Książka kucharska/Ziemniaczana z grzybami"},{"id":"oc-plwb-18570","title":"Poznański budyń orzechowy (Poznań baked walnut pudding)","cuisine":"European","category":"Dessert","ingredients":["8 egg (yolks and whites separated)","200 g sugar","240 g walnuts (finely chopped)","2.5 tbsp breadcrumbs (2–3 tbsp, sifted)","10 g butter (for greasing the pan)"],"steps":["Separate the egg yolks from the whites, beat the yolks with the sugar until pale and fluffy, then gradually stir in the finely chopped walnuts.","Whip the egg whites to stiff peaks and fold into the walnut mixture one spoonful at a time.","Add the sifted breadcrumbs and fold gently but thoroughly.","Transfer the mixture into a buttered baking dish and bake for 40 minutes in an oven preheated to 150 °C."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pozna%C5%84ski_budy%C5%84_orzechowy","page":"Książka kucharska/Poznański budyń orzechowy"},{"id":"oc-plwb-31418","title":"Pralinki lipowe (linden truffles)","cuisine":"European","category":"Dessert","ingredients":["70 g unripe linden fruit (preferably small-leaved linden)","3 tbsp dried linden flowers (about 2 tsp per 1 tbsp fruit)","1 tsp icing sugar (or honey)","1.5 tsp grapeseed oil (1–2 tsp, or coconut oil)","1 tsp cocoa powder (optional, or instant coffee or liqueur)"],"steps":["Remove stems from the green, unripe linden fruits, lightly toast them in a dry skillet, and crush in a mortar or blend in a food processor until smooth.","Add the crushed dried linden flowers, icing sugar or honey, and optionally cocoa powder, instant coffee, or liqueur, and mix thoroughly.","Slowly pour in the grapeseed oil or melted coconut oil, kneading until a sticky, malleable paste forms.","Shape into six truffles by hand or in small moulds and chill thoroughly in the refrigerator before serving."],"time":25,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pralinki_lipowe","page":"Książka kucharska/Pralinki lipowe"},{"id":"oc-plws-45000","title":"Prażucha (toasted flour porridge with fatback cracklings)","cuisine":"European","category":"Main","ingredients":["250 g plain flour (or buckwheat flour, dry-toasted in a saucepan)","250 ml water (boiling, orig. a kwaterka of water for four people)","1 tsp salt","150 g pork fatback (fresh fatback rendered into crisp cracklings)"],"steps":["Place plain or buckwheat flour into a dry saucepan and toast over low heat, stirring constantly with a spoon until evenly browned and fragrant.","Sift the toasted flour through a fine sieve to remove any lumps.","In a separate saucepan bring a kwaterka (250 ml) of water to a boil with salt.","Gradually sprinkle the flour into the boiling water, stirring vigorously with a spoon over low heat until a thick, uniform dough forms that pulls away from the sides.","Dice the fatback and render in a frying pan until crisp and golden.","Spoon portions of prażucha onto a platter using a spoon dipped in fat, and pour generous amounts of hot cracklings over the top."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pra%C5%BCucha","page":"365 obiadów za 5 złotych/Prażucha"},{"id":"oc-plwb-61280","title":"Processed cheese pasta sauce (Sos z serkiem topionym do makaronu)","cuisine":"European","category":"Sauce","ingredients":["2 tbsp plain flour","2 tbsp butter","250 ml milk","100 g processed cheese (plain cream or flavoured)","to taste salt","to taste pepper"],"steps":["Melt the butter in a saucepan, add the flour, and mix thoroughly.","Stirring continuously, pour in the milk gradually to dissolve lumps, and heat until the sauce thickens.","Add the processed cheese, stir over low heat until completely melted, and season to taste with salt and pepper."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_z_serkiem_topionym_do_makaronu","page":"Książka kucharska/Sos z serkiem topionym do makaronu"},{"id":"oc-plws-42432","title":"Prosię w galarecie (suckling pig in clear savoury aspic)","cuisine":"European","category":"Snack","ingredients":["2 kg suckling pig (young, cut into serving portions)","1 bunch soup greens","1 onion","1 dried forest mushrooms","3 tbsp wine vinegar (strong wine vinegar)","4 allspice berries","2 bay leaf","to taste salt","2 egg whites (for clarifying the broth)"],"steps":["Cut cleaned suckling pig into neat serving portions, bring to a boil in water, and skim off foam.","Add soup greens, onion, dried mushroom, vinegar, allspice, bay leaves, and salt, and simmer over low heat until the meat is tender (about 60–75 minutes).","Lift out the cooked meat, rinse briefly in cold water, and arrange decoratively in a glass bowl or mould.","Boil down the broth, strain through a cloth, clarify with lightly beaten egg whites, and filter again.","Pour the cooled, clear broth over the meat in the dish and place in a cold spot until the aspic sets completely.","Serve with vinegar and olive oil or horseradish sauce."],"time":120,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Prosi%C4%99_w_galarecie","page":"365 obiadów za 5 złotych/Prosię w galarecie"},{"id":"oc-plws-1081042","title":"Provence torte","cuisine":"European","category":"Cake","ingredients":["400 g almonds (orig. 1 funt blanched and pounded)","400 g icing sugar (orig. half a funt for the layers and half a funt do kremu)","12 egg whites","400 g hazelnuts (orig. a funt of Turkish hazelnuts in the shell (dried and ground once peeled))","200 g butter (orig. half a funt young butter)","30 ml whipping cream (30%) (orig. two łyżki)","100 g punch icing (orig. punch icing)"],"steps":["Grind the blanched, peeled, dried almonds finely with 200 g of icing sugar and sift them.","Whip the whites to a stiff foam, quickly fold in the almonds and sugar, spread the mixture on two cake tins lined with baking paper, and bake at 150 °C for 30 minutes so they do not brown too much.","For the cream, toast the hazelnuts, rub off the skins, grind and sift them. Beat the butter until fluffy, add 200 g of icing sugar, the nuts and the cream, mix, and chill in the refrigerator for 1–2 hours.","When the cream has set, sandwich the cooled almond layers with it to make the torte.","Pour punch icing over the top and, once it has dried, cut with a knife dipped in hot water."],"time":180,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Tort_%E2%80%9Eprovence%E2%80%9D","page":"Baby, placki i mazurki/Tort „provence”"},{"id":"oc-plwb-31888","title":"Przekładaniec (chocolate chip muffins)","cuisine":"European","category":"Cake","ingredients":["640 g plain flour","4 tsp baking powder","200 g sugar","4 tsp vanilla sugar","2 egg","250 ml vegetable oil","500 ml milk","200 g milk chocolate"],"steps":["Combine the plain flour, baking powder, sugar, and vanilla sugar in a large bowl.","Add the eggs, vegetable oil, and milk, and stir until well combined into a uniform batter.","Preheat the oven to 160 °C, line a baking sheet with muffin cups, and fill them with batter to a depth of about 1 cm.","Break the milk chocolate into chunks and press them into the batter in the muffin cups so they do not protrude above the surface.","Place the muffin cups into the preheated oven and bake the muffins for about 25 minutes."],"time":40,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Przek%C5%82adaniec","page":"Książka kucharska/Przekładaniec"},{"id":"oc-plwb-18814","title":"Pstrąg po królewsku (royal-style trout with celery)","cuisine":"European","category":"Main","ingredients":["4 trout (small)","200 g celery","1 leek","2 tbsp butter (part for frying, part for drizzling with breadcrumbs)","500 ml white wine","2 tbsp breadcrumbs","to taste caraway","to taste sweet paprika","1 lemon (sliced, for garnish)","to taste salt","to taste pepper"],"steps":["Gut and clean the trout, cut into steaks, rinse and pat dry, then coat in sweet paprika and season with salt, pepper, and caraway.","Melt part of the butter in a skillet, sear the fish pieces on both sides until golden, pour in the white wine, and bake for 10 minutes in an oven preheated to 200 °C.","Cut the celery stalks into pieces about 10 cm long, scald with boiling water, and drain; slice the leek into thin ribbons and use them to tie the celery into bundles.","Arrange the baked trout and celery bundles on a platter, drizzle with the remaining melted butter mixed with browned breadcrumbs, and garnish with lemon slices."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pstr%C4%85g_po_kr%C3%B3lewsku","page":"Książka kucharska/Pstrąg po królewsku"},{"id":"oc-plwb-14171","title":"Pstrąg w folii (foil-baked trout)","cuisine":"European","category":"Main","ingredients":["4 trout (gutted)","2 lemon (juiced)","6 tbsp butter (melted)","4 clove garlic (pressed through a press)","1 bunch parsley leaves (chopped)","to taste salt","to taste pepper"],"steps":["Mix the melted butter with the freshly squeezed lemon juice, pressed garlic, chopped parsley leaves, salt, and pepper.","Immerse the cleaned trout in the prepared butter mixture and let marinate for about 60 minutes, turning them several times.","Wrap each fish tightly along with its marinade in aluminium foil.","Bake the trout in an oven preheated to 200 °C for about 20 minutes."],"time":95,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pstr%C4%85g_w_folii","page":"Książka kucharska/Pstrąg w folii"},{"id":"oc-plwb-16998","title":"Pstrąg w winie (trout in white wine)","cuisine":"European","category":"Main","ingredients":["6 trout","6 tbsp olive oil","375 ml dry white wine","6 slice lemon (for serving)","6 fresh rosemary (sprigs)","to taste salt","to taste pepper"],"steps":["Clean and gut the trout, trim the fins, remove the gills and eyes, then wash thoroughly and pat dry.","Drizzle each fish with olive oil and let stand for 30 minutes.","Season the trout with salt and pepper, and insert a sprig of fresh rosemary into the cavity of each fish.","Place the trout on a preheated grill rack and cook, basting occasionally with dry white wine, then serve with lemon slices."],"time":65,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pstr%C4%85g_w_winie","page":"Książka kucharska/Pstrąg w winie"},{"id":"oc-plwb-13748","title":"Pstrąg z boczkiem i migdałami (trout with pork belly and almonds)","cuisine":"European","category":"Main","ingredients":["4 trout","12 slice pork belly","100 g flaked almonds (2/3 for the garlic butter, 1/3 for browning)","120 g butter (100 g to beat with the almonds, 20 g to brown the flakes)","1 clove garlic","3 tbsp lemon juice","to taste salt","to taste pepper"],"steps":["Peel and finely mince the garlic, then beat it with 100 g of butter and two-thirds of the flaked almonds, seasoning with salt and pepper.","Brown the remaining flaked almonds in a skillet with the remaining 20 g of butter.","Clean and wash the trout, pat dry, and spread the inside of each fish with the almond-garlic butter.","Wrap each fish in three slices of pork belly, wrap tightly in aluminium foil, and bake for about 8 minutes on each side.","Before serving, drizzle the trout with the butter and browned almonds and with lemon juice."],"time":31,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pstr%C4%85g_z_boczkiem_i_migda%C5%82ami","page":"Książka kucharska/Pstrąg z boczkiem i migdałami"},{"id":"oc-plws-40199","title":"Ptysie parzone czyli pączki zaparzane (fried choux pastry doughnuts)","cuisine":"European","category":"Dessert","ingredients":["250 ml water (1 kwaterka, orig. a kwaterka of water)","125 g clarified butter (half a kwaterka, orig. half a kwaterka of clarified butter)","150 g plain flour (1 kwaterka, orig. a kwaterka of fine flour)","5 eggs (beaten in one by one into slightly cooled dough)","500 g lard (or lard with butter for deep frying)","2 tbsp icing sugar"],"steps":["In a saucepan bring a kwaterka (250 ml) of water to a boil with clarified butter (125 g).","When boiling, dump in sifted flour all at once and stir vigorously with a wooden spoon over low heat until glossy and pulling cleanly away from the pan.","Remove the dough from the heat, cool slightly, then beat in the eggs one at a time, beating thoroughly after each until the mixture is light and uniform.","In a deep saucepan heat lard or clarified butter to about 175 °C.","Dip a spoon into melted butter, scoop walnut-sized portions of dough, and drop into the hot fat.","Fry until golden on both sides, remove with a slotted spoon to drain on a sieve, sprinkle with icing sugar, and serve with chaudeau sauce or fruit juice."],"time":40,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ptysie_parzone_czyli_p%C4%85czki_zaparzane","page":"365 obiadów za 5 złotych/Ptysie parzone czyli pączki zaparzane"},{"id":"oc-plws-1081080","title":"Puff Pastry Cream Horns with Italian Meringue","cuisine":"European","category":"Cookie","ingredients":["400 g puff pastry (originally pastry made with half a funt (200 g) of flour)","1 egg (whole, beaten for brushing the horns)","2 tbsp icing sugar (for dusting the horns before baking)","6 egg whites (whites, for the meringue cream)","200 g sugar (for boiling a thick syrup to the thread or pearl stage)","60 ml water (for boiling the sugar syrup)"],"steps":["Roll stiff parchment paper into tubes the thickness of a candle (or use metal cream horn molds).","Roll out the puff pastry to the thickness of the back of a knife (approximately 2–3 mm), cut into strips and wrap around the prepared tubes.","Arrange the horns on a baking sheet, brush with beaten egg, dust with icing sugar, and bake until golden in a hot oven (210 °C, approx. 15–20 minutes), then slide out the paper forms.","Boil a very thick syrup from the sugar and water (to approx. 115–118 °C, the pearl stage), and whip six egg whites to stiff peaks.","Remove the saucepan with the hot syrup from the heat and pour the whipped egg whites into it while whisking constantly into a smooth, glossy meringue cream.","Immediately after whipping, pipe the cream into the baked pastry horns using a pastry bag."],"time":50,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciastka_francuskie_w_rurkach_z_pian%C4%85_z_bia%C5%82ek","page":"Baby, placki i mazurki/Ciastka francuskie w rurkach z pianą z białek"},{"id":"oc-plwb-10522","title":"Puffed rice caramel cones (Szyszki)","cuisine":"European","category":"Dessert","ingredients":["80 g puffed rice","400 g cream fudge (krówki) or toffee candies","1 tbsp butter"],"steps":["Unwrap the cream candies and transfer them to a pot together with the butter.","Heat the ingredients over low heat, stirring, until the fudge candies and butter have completely melted.","Gradually pour in the puffed rice and mix thoroughly so the grains are evenly coated in the caramel mixture.","Put on plastic gloves and shape the warm mixture into oblong cones, then set aside to firm up (if the mixture cools and hardens too much during shaping, warm it slightly)."],"time":40,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szyszki","page":"Książka kucharska/Szyszki"},{"id":"oc-plws-45014","title":"Pularda z serdelami (spit-roasted poulard with anchovy butter)","cuisine":"European","category":"Main","ingredients":["1.8 kg poulard (or capon, orig. capon or poulard)","to taste salt","1 tbsp plain flour (for dusting halfway through roasting)","100 g butter (for continuously basting during roasting)","2 tbsp breadcrumbs (for sprinkling near the end of roasting)","30 g anchovy butter (1 tablespoon butter creamed with anchovies)"],"steps":["Thoroughly clean, rinse, and dry the poulard, rub with salt inside and out, and truss the legs with kitchen twine.","Secure the bird on a spit or place on a rack in an oven preheated to 190 °C.","Roast for about 70–80 minutes, basting frequently with melted butter.","Halfway through roasting dust the bird lightly with flour, and 10 minutes before the end sprinkle with breadcrumbs and pan drippings for a crisp skin.","Immediately upon removing from the oven, insert a tablespoon of anchovy butter (or butter creamed with freshly ground pepper) into the cavity.","Carve the poultry into portions and serve with the pan butter juices."],"time":95,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pularda_z_serdelami","page":"365 obiadów za 5 złotych/Pularda z serdelami"},{"id":"oc-plws-39481","title":"Pulpety wołowe do barszczu (beef meatballs for borscht)","cuisine":"European","category":"Soup","ingredients":["200 g beef (tender beef, orig. half a historical Polish funt)","100 g beef suet (or beef marrow, orig. a quarter of a historical Polish funt)","1 onion (roasted in the oven and mashed to a paste)","1 egg","2 tbsp breadcrumbs","to taste salt","to taste black pepper"],"steps":["Very finely mince the beef and suet (or marrow) with a knife or pass through a grinder twice.","Roast the whole onion in the oven and mash to a smooth puree.","In a bowl combine the minced meat, suet, mashed onion, egg, breadcrumbs, salt, and pepper, kneading to a cohesive mixture.","Roll the mixture into tiny balls the size of a hazelnut.","Drop the meatballs directly into simmering borscht and cook gently for about 5–7 minutes until they float to the surface.","Serve the hot borscht with meatballs in a tureen or in individual soup plates."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pulpety_do_barszczu","page":"365 obiadów za 5 złotych/Pulpety do barszczu"},{"id":"oc-plws-39485","title":"Pulpety ze szczupaka (pike quenelles)","cuisine":"European","category":"Soup","ingredients":["800 g pike (pike fillet without skin or bones)","30 g butter (1 tablespoon)","1 onion (finely grated)","1 white roll (soaked in milk and well squeezed)","100 ml milk (for soaking the bread)","2 eggs","2 tbsp plain flour (for dusting the board)","to taste salt"],"steps":["Skin and debone the pike, then very finely mince with a knife or pass through a grinder.","Soak the roll in milk and squeeze out thoroughly.","Add softened butter, grated onion, squeezed roll, eggs, and salt to the fish, and knead into a uniform, fluffy paste.","Dust the work surface with flour and roll the paste into thick finger-length cylinders.","Drop the dumplings into a pot of salted boiling water (or fish stock) and cook gently for about 5 minutes until they float to the surface.","Lift onto a colander, cool slightly, and slice diagonally into a soup tureen (or serve whole in white cream sauce)."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pulpety_z_ryb","page":"365 obiadów za 5 złotych/Pulpety z ryb"},{"id":"oc-plws-552224","title":"Punch ice","cuisine":"European","category":"Dessert","ingredients":["250 g sugar (in pieces, rubbed on the orange peel, orig. a quarter kilogram)","500 ml water (orig. half a litre)","185 ml strong black-tea infusion (brewed leaf tea, orig. 3/4 szklanka)","4 oranges (juicy ones: peel for rubbing the sugar, and the squeezed juice)","3 lemons (the squeezed juice)","30 ml maraschino (orig. a small liqueur glass)"],"steps":["Rub the sugar on the peel of four oranges, cover it with 500 ml of water, bring the syrup to the boil, and leave it to cool.","Pour 185 ml of strong black-tea infusion into the cooled syrup, together with the juice of four oranges and three lemons strained through a sieve, and mix well.","Pour the mixture into an ice-cream maker and start freezing. When the mass is half set, pour in a small glass (30 ml) of maraschino and finish freezing (about 2–3 hours in all)."],"time":190,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_ponczowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody ponczowe"},{"id":"oc-plws-580396","title":"Pyzy drożdżowe z cebulą gotowane na parze (steamed yeast dumplings stuffed with onion)","cuisine":"European","category":"Main","ingredients":["600 g plain wheat flour (200 g for the sponge and 400 g for kneading the dough)","20 g fresh yeast","500 ml milk (lukewarm)","1 tbsp butter (for the dough, plus extra for the onions, mould, and pouring over)","2 eggs (whole)","to taste salt","1 tsp sugar","to taste breadcrumbs (for dusting the mould)","500 g onion (finely chopped)"],"steps":["Mix 200 g of the wheat flour with the crumbled fresh yeast and lukewarm milk, then leave the sponge in a warm place for 20 minutes to rise.","Add the remaining 400 g of wheat flour, 1 tablespoon of butter, the eggs, salt, and sugar to the risen sponge, knead for 10 minutes until the dough pulls away from your hands, and leave to rise for 30 minutes.","Peel and finely chop the onions, then cook them gently in butter for 15 minutes until soft.","Butter a pudding mould and dust it with breadcrumbs.","With hands dipped in melted butter, pinch off small pieces of the risen dough, flatten them, stuff each with a teaspoon of braised onion, and layer the balls halfway up the mould.","Cover the mould tightly with its lid, steam for 90 minutes, then turn the dumplings out onto a platter and pour melted butter over them."],"time":165,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Pyzy_z_cebul%C4%85","page":"100 postnych i jarskich dań/Pyzy z cebulą"},{"id":"oc-plwb-16880","title":"Pyzy z mięsem (potato dumplings stuffed with meat)","cuisine":"European","category":"Main","ingredients":["1 kg potatoes","2 egg","240 g plain flour","250 g cooked veal","250 g cooked beef","125 ml sour cream","1 white bread roll","1 onion","1 tbsp tomato paste","100 g button mushrooms (a few)","1 tbsp cooking oil","to taste salt","to taste pepper","1 bunch chives (chopped)"],"steps":["Boil the potatoes, let them cool, and pass through a meat grinder or ricer.","Add the plain flour, eggs, and salt to the potatoes, knead into a uniform dough, roll into a log, and cut into equal pieces.","Chop the onion and button mushrooms, and brown in hot oil.","Soak the bread roll, squeeze out excess liquid, and grind together with the cooked veal and beef, then mix with the sautéed onion and mushrooms, tomato paste, and sour cream, seasoning with salt and pepper.","Place portions of meat filling onto the dough pieces, shape into round dumplings, and boil in salted water until they float to the surface.","Remove the cooked dumplings with a slotted spoon and sprinkle with chopped chives before serving."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pyzy_z_mi%C4%99sem","page":"Książka kucharska/Pyzy z mięsem"},{"id":"oc-plws-569438","title":"Półgęski litewskie wędzone na kości (Lithuanian cold-smoked bone-in goose breasts)","cuisine":"European","category":"Preserve","ingredients":["10 bone-in goose breasts (from large fattened geese (about 16 kg in total))","500 g salt (orig. 50 dag, toasted)","20 g potassium nitrate (orig. 2 dag)","40 g coriander seeds (orig. 4 dag, coarsely crushed)","10 g black pepper (orig. 1 dag, coarsely crushed)","5 g allspice (orig. 0.5 dag, coarsely crushed)","10 g bay leaf (orig. 1 dag, crumbled)","6 cloves (orig. a few, coarsely crushed)"],"steps":["Cut the whole breasts on the bone from large, fattened geese (10 breasts weighing about 16 kg in total).","Mix 500 g of toasted salt with 20 g of potassium nitrate and the coarsely crushed spices: 40 g of coriander, 10 g of black pepper, 5 g of allspice, 10 g of bay leaf, and a few cloves.","Pack the goose breasts in a deep vessel, sprinkling each layer with the spiced salt, press down with a weighted board, and leave for 2 days in a moderately warm room.","Move the vessel to a cool larder and cure for up to 3 weeks, turning the breasts from top to bottom every day.","Before smoking, wipe the goose breasts dry, wrap in paper, tie with string, hang for a day in a breezy place to dry completely, and cold-smoke for a week."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/P%C3%B3%C5%82g%C4%99ski_litewskie","page":"Domowe wędliny/Półgęski litewskie"},{"id":"oc-plws-569439","title":"Półgęski zwijane bez kości wędzone (rolled boneless cold-smoked goose breasts)","cuisine":"European","category":"Preserve","ingredients":["2 fattened geese (large, dressed)","150 g salt (for rubbing)","1 tsp potassium nitrate (for curing)","1 tsp black pepper (coarsely crushed)","1 tsp allspice (coarsely crushed)","6 cloves (coarsely crushed)","0.5 lemon (finely chopped zest)","1 tbsp coriander seeds (coarsely crushed)"],"steps":["Clean and singe large fattened geese carefully, slit them down the back, and bone them completely without damaging the skin or meat.","Rub the boned birds with salt and potassium nitrate, and sprinkle with coarsely crushed black pepper, allspice, cloves, coriander, and finely chopped lemon zest.","Pack the geese in pairs, skin-side out, in a deep vessel, press down with a weighted board, and cure for 8 days, turning them from top to bottom daily and basting with the brine they release.","Remove the geese from the brine, wipe thoroughly dry, roll up lengthwise into a tight cylinder (splitting very large birds lengthwise down the breastbone first) so the meatier breast sections remain in the centre, and sew shut with thick thread.","Wrap the rolls in paper, tie with twine, hang for several hours in a breezy place to dry well, and cold-smoke for a week in completely cool smoke."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/P%C3%B3%C5%82g%C4%99ski_zwijane","page":"Domowe wędliny/Półgęski zwijane"},{"id":"oc-plws-1081088","title":"Pączki (scalded Polish doughnuts)","cuisine":"European","category":"Cake","ingredients":["1.5 l wheat flour (orig. half a kwarta for scalding, plus 1 kwarta for the dough)","750 ml milk (orig. half a kwarta of boiling milk for scalding, and 1 kwaterka for the yeast)","15 egg yolks","200 g sugar (orig. half a funt)","50 g fresh yeast (orig. 4 łuty)","10 egg whites","100 g melted butter (orig. a quarter funt young butter)","2 g salt (orig. a pinch)","5 g lemon zest","500 g lard for frying","200 g jam for the filling","50 g icing sugar for dusting"],"steps":["Scald half a litre of flour with half a litre of boiling milk, rub it smooth, and cool it.","Beat the yolks with the sugar to a white mass, mix in the scalded flour, the yeast dissolved in a kwaterka of milk, and the stiffly whipped whites, and leave the starter in a warm place to rise.","Add a litre of flour, the salt, the grated lemon zest and the melted warm butter to the risen starter. Knead hard for about an hour, until the dough comes cleanly away from your hands, then leave it in the warm to rise further.","When the dough is moving, tear off even pieces, flatten them lightly, put a teaspoon of thick jam on each, pinch the edges shut, and shape round doughnuts.","Set the doughnuts seam side down on a floured board and leave them to rise under a cloth.","Heat the lard in a wide pan to 175 °C. Fry the risen doughnuts in batches, covered, until browned, turn them, and finish uncovered. Drain on paper and dust with icing sugar."],"time":270,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Wyborne_p%C4%85czki_parzone","page":"Baby, placki i mazurki/Wyborne pączki parzone"},{"id":"oc-plwb-19420","title":"Pączki (traditional Polish doughnuts)","cuisine":"European","category":"Dessert","ingredients":["100 g fresh yeast","1 kg plain flour","500 ml milk","6 egg yolks","1 egg","125 g sugar","to taste vanilla","1 lemon (juice and grated zest)","1 pinch salt","25 ml rectified spirit","6 tbsp vegetable oil (for the dough)","400 g thick fruit jam","1 kg lard (or oil, for deep-frying)","100 g icing sugar (for dusting)"],"steps":["Mash the fresh yeast with part of the warm milk, 200 g of flour, and a tablespoon of sugar, then set the starter in a warm place to rise.","Beat the egg yolks and whole egg with the remaining sugar, then add the rest of the flour, the risen starter, remaining milk, lemon juice and zest, vanilla, salt, and rectified spirit.","Knead the dough until smooth, glossy, and coming cleanly away from your hands, gradually pouring in the oil toward the end.","Cover the dough and leave in a warm place for 15 minutes to prove.","Shape the dough into rounds, place a portion of marmolada (firm fruit preserve) in the centre, pinch the edges firmly to seal into balls, and arrange on a floured pastry board covered with a cloth to rise.","Heat the lard until very hot in a deep pot and fry the doughnuts in batches on both sides until golden brown.","Drain the fried doughnuts on paper towels and dust with icing sugar."],"time":90,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/P%C4%85czki","page":"Książka kucharska/Pączki"},{"id":"oc-plws-45180","title":"Pączki kartoflane (baked potato puffs)","cuisine":"European","category":"Side","ingredients":["1.5 kg potatoes (orig. half a Polish garniec (2 l) of peeled potatoes)","to taste salt (for boiling the potatoes and for the mixture)","2 tbsp sour cream 18% (sour)","2 tbsp butter (1 tbsp for the mixture and 1 tbsp for greasing the baking sheet)","3 egg yolk (for the mixture)","1 onion (grated (optional))","1 egg (beaten, for brushing the tops)","2 tbsp breadcrumbs (for sprinkling the tops)"],"steps":["Peel the potatoes, boil in salted water until tender, drain, let steam dry, and grate or mash thoroughly so that no lumps remain.","Add 2 tbsp of sour cream, 1 tbsp of butter, 3 egg yolks, salt to taste, and optionally grated onion to the potato mixture, and beat thoroughly.","Spoon the mixture in round mounds onto a buttered baking sheet.","Brush the top of each puff with beaten egg and sprinkle with breadcrumbs.","Place the baking sheet in a well-heated oven (190 °C) and bake for about 15–20 minutes until golden; serve after soup instead of pastries or as a garnish around a roast."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/P%C4%85czki_kartoflane","page":"365 obiadów za 5 złotych/Pączki kartoflane"},{"id":"oc-plwb-14463","title":"Quick tomato and pepper salad (Szybka sałatka z pomidorów z papryką)","cuisine":"European","category":"Salad","ingredients":["2 tomatoes","1 onion","1 cucumber","1 red bell pepper","to taste chives","to taste salt","to taste pepper","1 tsp vegetable oil","to taste lemon juice"],"steps":["Wash and drain the vegetables, then peel the onion and cut into rings.","Halve the bell pepper, remove the seeds and cut the flesh into strips. Slice the unpeeled cucumber and quarter the tomatoes.","Transfer the vegetables to a bowl, season with salt and pepper, and drizzle with the oil whisked with lemon juice.","Scatter chopped chives over the salad and toss thoroughly."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szybka_sa%C5%82atka_z_pomidor%C3%B3w_z_papryk%C4%85","page":"Książka kucharska/Szybka sałatka z pomidorów z papryką"},{"id":"oc-plws-546709","title":"Racuchy ziemniaczane z mąką owsianą (potato and oat flour pancakes)","cuisine":"European","category":"Main","ingredients":["1 kg potatoes (large)","250 g oat flour (orig. 25 dkg)","2 tbsp vegetable oil","to taste salt"],"steps":["Peel the raw potatoes and grate them on a fine grater.","Add the sifted oat flour, season with salt, and mix thoroughly into a uniform mixture.","Heat the vegetable oil well in a skillet and fry fairly large, thin pancakes on both sides for about 3–4 minutes until golden."],"time":40,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Racuchy_kartoflane_z_owsian%C4%85_m%C4%85k%C4%85","page":"109 potraw/Racuchy kartoflane z owsianą mąką"},{"id":"oc-plws-40193","title":"Racuszki drożdżowe (small yeast pancakes)","cuisine":"European","category":"Main","ingredients":["600 g plain wheat flour (orig. 1 Polish kwarta)","25 g fresh yeast (orig. 2 łuty)","300 ml lukewarm milk (to start the dough)","4 egg yolks","1 tbsp butter","2 tbsp sugar (1 tbsp for dough and 1 tbsp for dusting)","1 pinch salt","200 g lard (for frying)","to taste ground cinnamon (optional, for dusting)"],"steps":["Mix the plain wheat flour with the yeast dissolved in lukewarm milk and set in a warm place for about 30 minutes until bubbling.","Add the egg yolks, butter, 1 tbsp of sugar, and a pinch of salt, mix thoroughly to form a thick batter, and let rise for 60 minutes.","Heat the lard in a wide saucepan and drop round spoonfuls of the risen dough into the hot fat.","Fry the pancakes on both sides until golden brown, lift out with a slotted spoon to drain, and immediately sprinkle with the remaining sugar mixed with cinnamon."],"time":125,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Racuszki","page":"365 obiadów za 5 złotych/Racuszki"},{"id":"oc-plwb-10335","title":"Raffaello (no-bake coconut slice)","cuisine":"European","category":"Cake","ingredients":["200 g shredded coconut (100 g for the cream, 100 g for sprinkling on top)","1 l milk (250 ml to bring to a boil, 750 ml to mix with flour and yolks)","3 tbsp plain flour","3 tbsp potato starch","3 egg yolk","16 g vanilla sugar","300 g butter (or margarine)","360 g crackers"],"steps":["In a heavy-bottomed pot, bring 250 ml of milk to a boil with 100 g of shredded coconut and the vanilla sugar.","In a separate bowl, thoroughly mix the remaining 750 ml of milk with the plain flour, potato starch, and egg yolks.","Slowly pour the mixture into the boiling milk while stirring constantly until a thick custard forms, then set aside to cool completely.","Beat the softened butter or margarine with a mixer, gradually adding the cooled coconut custard one spoonful at a time.","Line the bottom of a square baking pan with a layer of crackers and spread half of the cream over them.","Arrange a second layer of crackers, spread the remaining cream, sprinkle the top with the rest of the shredded coconut, and chill in the refrigerator."],"time":40,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Raffaello","page":"Książka kucharska/Raffaello"},{"id":"oc-plwb-15323","title":"Rainbow no-bake cheesecake (Sernik tęczowy)","cuisine":"European","category":"Cake","ingredients":["6 homogenised curd cheese (containers)","450 g icing sugar","200 g butter","5 egg yolks","4 fruit jelly powder (packets in different colours)","2 tbsp gelatine"],"steps":["Pour 100 ml of cold water over the gelatine, and once it has swelled, heat gently until completely dissolved, then set aside to cool.","Dissolve each of the four fruit jellies separately in half the amount of boiling water indicated on the packet, then let cool.","Beat the softened butter with the icing sugar and egg yolks, blend in the homogenised curd cheese until smooth, and divide the mixture into five equal portions.","Mix the first portion of the cheese mixture with the dissolved gelatine, and stir one cooled fruit jelly into each of the remaining four portions.","Pour the first white layer into the base of a springform tin and refrigerate until set, then pour each successive colourful layer on top after the previous one has fully set."],"time":50,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sernik_t%C4%99czowy","page":"Książka kucharska/Sernik tęczowy"},{"id":"oc-plws-1080982","title":"Raisin filling for sheet cakes and crepes","cuisine":"European","category":"Sauce","ingredients":["200 g raisins (orig. half a funt)","100 g sugar (orig. a quarter funt)","25 ml lemon juice (from 1/2 lemon)"],"steps":["Rinse the large raisins, pick out any seeds, and chop them finely with a knife.","Put the raisins in a bowl, add the sugar and the freshly squeezed juice of half a lemon.","Grind the mixture with a pestle, or blend it, into a thick, tangy paste and use it to fill baked sheet cakes or crepes."],"time":15,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Prze%C5%82o%C5%BCenie_do_plack%C3%B3w%2C_a_nawet_nale%C5%9Bnik%C3%B3w","page":"Baby, placki i mazurki/Przełożenie do placków, a nawet naleśników"},{"id":"oc-plws-551529","title":"Raspberry cordial on raspberry juice","cuisine":"European","category":"Drink","ingredients":["1000 g fresh ripe raspberries (to fill the demijohn)","1125 ml 95% rectified spirit (orig. 1.5 bottles of drawn-off spirit infusion, plus a few teaspoons at the end)","750 ml raspberry juice cooked with sugar (not too thick, orig. 1 bottle of juice per 1.5 bottles of spirit)"],"steps":["Put fresh ripe raspberries into a glass demijohn, cover them with plain spirit, and stand it in a sunny window for 10 days, until the fruit has turned completely pale.","Pour the spirit infusion off the fruit and combine it with cooked raspberry juice at 750 ml of juice per 1125 ml of drawn-off spirit.","Leave the demijohn for a few days in a window that gets the morning sun, shaking it now and then so the liquids combine well.","Strain the cordial (adding, if you like, two teaspoons of plain spirit), bottle it in clear bottles, cork it, and store it in the cellar."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Nalewka_malinowa","page":"Doświadczone sekreta smażenia konfitur i soków/Nalewka malinowa"},{"id":"oc-plws-551532","title":"Raspberry cordial, another way","cuisine":"European","category":"Drink","ingredients":["2400 g fresh ripe raspberries (orig. 4 litres)","3000 g sugar (orig. 3 kilograms)","8 l water (orig. 8 litres)","2 l 95% rectified spirit (orig. 2 litres)"],"steps":["Bring a light syrup to the boil from 3 kg of sugar and 8 litres of water, then cool it completely.","Put 2400 g (4 litres) of ripe fresh raspberries into a very large demijohn, cover them with the cold syrup and 2 litres of spirit, and seal it.","Leave the demijohn in a warm place out of the sun for 12 days, shaking it twice a day.","After 12 days, when the sediment has settled and the cordial is clear, pour it carefully into dry bottles, cork them, and store them in a cool, dry place."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Nalewka_malinowa_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Nalewka malinowa innym sposobem"},{"id":"oc-plws-544467","title":"Raspberry jam","cuisine":"European","category":"Preserve","ingredients":["500 g fresh raspberries (large, picked on a dry day, orig. half a kilogram)","1000 g sugar (orig. 1 kilogram)","500 ml water (orig. 2 szklanki)"],"steps":["Pick over large firm raspberries very carefully, lay them in a single layer on platters or plates, and put them overnight (about 8 hours) in a cool cellar or the refrigerator.","The next day, cook a syrup from 1 kg of sugar and 500 ml of water, skimming carefully, until it is clear and begins to bead.","Tip the raspberries into the boiling syrup without taking the pan off the heat, and cook first over a higher heat and then over a lower one, shaking the pan often so the fruit cooks evenly.","Skim the foam that rises with a spoon, gently, without touching the raspberries themselves, until a drop of syrup taken on a knife begins to thicken and falls slowly.","Leave the jam to cool completely, then spoon the fruit into scalded jars, cover them with the syrup strained through a small sieve, and seal them."],"time":545,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Maliny","page":"Doświadczone sekreta smażenia konfitur i soków/Maliny"},{"id":"oc-plws-544472","title":"Raspberry jam covered with hot syrup","cuisine":"European","category":"Preserve","ingredients":["500 g fresh raspberries (large and dry, orig. half a kilogram)","1000 g sugar (orig. 1 kilogram)","375 ml water (orig. 1.5 szklanki, for the syrup)"],"steps":["Bring a thick syrup to the boil from 1 kg of sugar and 375 ml of water.","Put the picked-over raspberries into a stoneware or enamel pan stood in a bowl of cold water, cover the fruit with the hot syrup, and leave it overnight (about 8 hours) in a cool place or the refrigerator.","The next day, bring the raspberries to the boil in the syrup, skim carefully, and cook first over a higher heat and then over a lower and lower heat until the right thickness.","Lift out the floating seeds with a teaspoon, cool the jam, and pack it into scalded jars."],"time":530,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Maliny_jeszcze_inaczej","page":"Doświadczone sekreta smażenia konfitur i soków/Maliny jeszcze inaczej"},{"id":"oc-plws-544470","title":"Raspberry jam, Bukovina way","cuisine":"European","category":"Preserve","ingredients":["500 g fresh raspberries (large, not overripe, orig. half a kilogram)","1000 g sugar (orig. 1 kilogram)","2 tbsp rum (for sprinkling the raspberries before chilling)","375 ml water (orig. at most 1.5 szklanki)"],"steps":["Pick over large firm raspberries carefully, lay them on a platter, sprinkle them with good rum, and put them on ice or in a very cold refrigerator for about 3 hours.","Cook a very thick syrup from 1 kg of sugar and 375 ml of water.","Tip the chilled raspberries straight into the boiling syrup over a very high heat so they come quickly to the boil and rise to the top. Then move the pan at once onto a bowl of ice to cool fast.","Repeat the quick boil over very high heat and the cooling on ice four times (five times if needed), skimming carefully each time and lifting out the seeds that float up.","Pack the cooled raspberries into jars and cover them with the clear syrup strained through a fine sieve."],"time":240,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Maliny_bukowi%C5%84skim_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Maliny bukowińskim sposobem"},{"id":"oc-plws-544471","title":"Raspberry jam, the plain way","cuisine":"European","category":"Preserve","ingredients":["1000 g sugar (orig. 1 kilogram)","500 g fresh raspberries (dry, not overripe, orig. half a kilogram)","400 ml water (orig. 2 small szklanki)"],"steps":["Pick over dry firm raspberries carefully, removing the stems.","Put the sugar into a wide pan, pour in 400 ml of water, bring it to the boil and skim it, cooking the syrup until it is clear, thick and beginning to bead.","Drop the raspberries into the boiling syrup and cook slowly, first over a higher heat and then over low heat, skimming carefully with a spoon so the fruit is not crushed.","When a drop of syrup taken on a knife thickens and falls slowly, take the pan off the heat, cool the jam, lift the loose seeds out of the syrup on a sieve, and pack the raspberries with the clear syrup into jars."],"time":65,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Maliny_zwyk%C5%82ym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Maliny zwykłym sposobem"},{"id":"oc-plws-39701","title":"Raspberry jelly","cuisine":"European","category":"Dessert","ingredients":["25 g gelatine or isinglass (orig. 2 łuty)","250 ml warm water (orig. 1 kwaterka)","750 ml sweet raspberry juice or syrup (orig. 3 kwaterki)","2 lemons (for juice)"],"steps":["Pour 250 ml of warm water over the gelatine and dissolve thoroughly without boiling (if using isinglass, simmer it over low heat down to 250 ml), then strain through a dense napkin.","Mix the dissolved gelatine with 750 ml of clear raspberry juice.","Squeeze the clear juice of 2 lemons through muslin into the mixture and stir.","Pour the jelly into a 1 l mould and leave in a cool place for about 4 hours (240 minutes) until set; wrap the mould briefly in a cloth dipped in hot water before unmoulding onto a platter."],"time":265,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Galareta_malinowa","page":"365 obiadów za 5 złotych/Galareta malinowa"},{"id":"oc-plws-548800","title":"Raspberry Jelly","cuisine":"European","category":"Preserve","ingredients":["1 l raspberries (fresh, picked over)","500 ml red currants (fresh)","1.2 kg fine sugar (approx. 1.5 l; in a ratio of 0.5 l sugar per 0.5 l fruit)"],"steps":["Pick over the raspberries and red currants, place them in a wide stoneware or copper pan, and cover with the fine sugar.","Place the pan over very high heat and bring the fruit to a boil without stirring with a spoon.","Bring the mixture to a boil three times, removing the pan from the heat and carefully skimming off the foam each time.","Pour the hot mixture onto a very fine sieve set over a bowl, and pour the clear strained juice immediately into jars.","Leave the jelly in the jars until completely cooled and set, then tie with parchment paper and store in a cool, dry place."],"time":45,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_malinowa","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta malinowa"},{"id":"oc-plws-548802","title":"Raspberry Jelly Another Way","cuisine":"European","category":"Preserve","ingredients":["1.5 kg raspberries (ripe, for 2 glasses (500 ml) of strained juice)","250 ml gooseberry or currant juice (freshly pressed and strained)","1.2 kg fine sugar (6 glasses (2 glasses of sugar per 1 glass of mixed juice))","1 l water (hot, for the water bath)"],"steps":["Place the picked-over raspberries into a stoneware pot, set it inside a larger pot of hot water, and heat on the stove (or in a warm oven) until the fruit releases its juice.","Pour the heated raspberries onto a sieve and drain the clear juice without pressing.","Measure 500 ml of the strained raspberry juice, combine with 250 ml of gooseberry or currant juice, and add 1.2 kg of fine sugar.","Cook the mixture first over higher and then over lower heat, removing the pan from the burner several times and carefully skimming off the foam.","Test with a drop on a cold saucer to see if the jelly sets; pour hot into warmed jars and seal tightly once cooled."],"time":75,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_malinowa_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta malinowa innym sposobem"},{"id":"oc-plws-550048","title":"Raspberry liqueur","cuisine":"European","category":"Drink","ingredients":["5 l raspberries (orig. about 3 litres of fresh ripe raspberries for the first pour, and about 2 litres (half a 4-litre demijohn) for the second)","1.5 l spirit (the best, enough to cover the raspberries completely (yielding about 1 l of filtered infusion))","1.5 kg sugar (orig. one and a half kilograms of crushed sugar per 1 litre of filtered spirit)","750 ml water (orig. 3 szklanki of cold water per 1.5 kg of sugar)"],"steps":["Put 3 l of freshly picked ripe raspberries into a four-litre demijohn, cover them with the best spirit so it covers the fruit with a little to spare, and leave it in the shade for 24 hours.","After a day, pour off the spirit, discard the spent fruit, fill the demijohn halfway (about 2 l) with fresh raspberries, cover them with the spirit you poured off, and leave it in the shade again for exactly 24 hours.","Pour off the raspberry spirit a second time and filter it at once through paper.","For every 1 l of filtered spirit, dissolve 1.5 kg of crushed sugar in 750 ml of cold water, bring to the boil, skim carefully, cool completely, and combine with the raspberry spirit, stirring constantly. Bottle, cork, seal with wax, and keep in a cool cellar for 8 months."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_malinowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier malinowy"},{"id":"oc-plws-520720","title":"Raw Fish Cutlets","cuisine":"European","category":"Main","ingredients":["600 g fish flesh (skinless and boneless; orig. sixty dag)","150 g bread roll (soaked in water and squeezed well; orig. fifteen dag)","100 g onion (grated; orig. ten dag)","1 egg (large; two small ones can be used)","to taste salt","to taste pepper (a small amount)","to taste breadcrumbs (for breading; amount not specified)","to taste lard (for frying; amount not specified)"],"steps":["Separate the flesh of the cleaned fish from the bones and carefully remove any remaining bones.","Soak the bread roll in water and squeeze it out well.","Grate the onion.","Grind the fish, bread roll, and onion together.","Knead the mixture with the egg, salt, and a small amount of pepper until uniform.","Shape into fairly thin cutlets.","Coat the cutlets in breadcrumbs.","Fry the cutlets in lard."],"time":null,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/Jedz_ryby/Kotlety_z_ryby_surowej","page":"Jedz ryby/Kotlety z ryby surowej"},{"id":"oc-plwb-21800","title":"Red cabbage and apple salad (Surówka z czerwonej kapusty)","cuisine":"European","category":"Salad","ingredients":["1 red cabbage (small head)","3 tart apples (2–3)","5 fermented (brine) pickles (5–6)","2.5 tbsp vegetable oil (2–3 tbsp)","to taste salt"],"steps":["Remove the outer leaves from the red cabbage, wash the head, and shred finely.","Peel the tart apples and dice them or grate on a coarse grater.","Dice the fermented pickles.","Mix all ingredients together, drizzle with oil, and season to taste with salt."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sur%C3%B3wka_z_czerwonej_kapusty","page":"Książka kucharska/Surówka z czerwonej kapusty"},{"id":"oc-plwb-14308","title":"Red cabbage salad with mandarins (Surówka z kapusty)","cuisine":"European","category":"Salad","ingredients":["1 red cabbage (small head)","2 mandarin oranges","50 g almonds","2 tbsp sunflower oil","to taste orange juice","to taste ginger","to taste salt","to taste sugar"],"steps":["Rinse the red cabbage and shred finely, removing the core and thickest ribs.","Peel the mandarins and divide into segments.","Scald the almonds with boiling water, slip off skins, and cut into slivers.","Transfer the cabbage to a salad bowl, drizzle with orange juice and sunflower oil, toss with the mandarins and almonds, and season to taste with salt, sugar, and ginger."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sur%C3%B3wka_z_kapusty","page":"Książka kucharska/Surówka z kapusty"},{"id":"oc-plws-548803","title":"Red Currant Jelly","cuisine":"European","category":"Preserve","ingredients":["1 kg red currants (stemmed and rinsed)","750 g fine sugar (fine, sifted)","250 g raspberries (ripe, optional for aroma)"],"steps":["Stem the currants, rinse in cold water, and drain (optionally adding the ripe raspberries).","In a stoneware pan, arrange alternating layers of fine sugar and fruit until all ingredients are used.","Place the pan over the heat, bring to a boil, and skim off the foam three times, removing the pan from the burner each time.","Strain the hot mixture through a fine sieve into a bowl, then pour the clear juice back into the washed pan.","Bring the juice to a boil once more, skim off the foam, pour into warmed jars while hot, and cover and secure the jars once cooled."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_porzeczkowa","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta porzeczkowa"},{"id":"oc-plws-1081082","title":"Rhubarb Pastry Slices","cuisine":"European","category":"Cake","ingredients":["500 g shortcrust or puff pastry (for two thin layers on a baking sheet)","400 g rhubarb stalks (originally 1 funt)","400 g sugar (originally 1 funt, for the marmalade syrup)","1 l water (boiling water for blanching the rhubarb and a little water for the syrup)","1 tbsp rosewater (for brushing the top of the pastry)","3 tbsp icing sugar (for generous dusting before baking)"],"steps":["Peel the outer strings from the rhubarb stalks, cut into smaller pieces, drop into boiling water, boil briefly, and drain in a sieve.","Boil a thick syrup from the sugar and a little water, add the blanched rhubarb, and cook until a thick marmalade forms, then let cool.","Roll out half of the shortcrust or puff pastry into a thin sheet on a baking tray and spread the layer of rhubarb marmalade over it.","Cover the filling with a second thin sheet of pastry and lightly score the top into portions with a knife to make slicing easier after baking.","Brush the top with rosewater, dust generously with icing sugar, and bake in a hot oven (200 °C) for about 25–30 minutes."],"time":75,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciastka_z_rabarbarum","page":"Baby, placki i mazurki/Ciastka z rabarbarum"},{"id":"oc-plws-474239","title":"Ripe Gooseberry Preserves","cuisine":"European","category":"Preserve","ingredients":["1 kg ripe gooseberries (Preferably uniform berries of a red variety; orig. a kilo.)","1 kg sugar (orig. a kilo.)","to taste vanilla (Small piece of a pod; orig. a little bit.)"],"steps":["Cook the ripe gooseberries with the sugar into preserves.","Add the vanilla to the forming syrup while cooking."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Konfitury%2C_kompoty_i_inne_konserwy_owocowe/Agrest","page":"Konfitury, kompoty i inne konserwy owocowe/Agrest"},{"id":"oc-plws-580404","title":"Risotto jarskie zapiekane z grzybami i pomidorami (baked vegetarian mushroom and tomato risotto)","cuisine":"European","category":"Main","ingredients":["100 g dried mushrooms (young, or 200 g fresh button mushrooms)","to taste water (for the mushroom and vegetable broth)","1 carrot","1 parsley root","1 celeriac (piece)","1 leek","3 onion (1 for the broth and 2 finely chopped for the rice)","150 ml olive oil (1 small cup (150 ml))","300 g rice","to taste butter (for frying the mushrooms and tomatoes)","5 tomatoes (large, ripe)","to taste Parmesan cheese (sharp grated cheese for sprinkling on top)","to taste sour cream (for making a sauce with the remaining mushroom broth)"],"steps":["Put the dried mushrooms, carrot, parsley root, celeriac, leek, and 1 onion into a pot, cover with water, and simmer the broth for 30 minutes.","Heat the olive oil in a saucepan, add the remaining 2 finely chopped onions, and cook until translucent for 5 minutes, then add the rice and fry, stirring, until lightly yellowed.","Add the hot mushroom broth a few spoonfuls at a time and cook gently, stirring, for about 15 minutes until the rice is completely tender.","Slice the cooked dried mushrooms and the tomatoes and sauté them separately in a skillet in butter.","Preheat the oven to 200 °C, layer the rice, mushrooms, and tomatoes in a deep ovenproof dish, finish with a layer of rice, sprinkle generously with grated Parmesan cheese, and bake for 5 minutes until the cheese melts.","Mix the remaining mushroom broth with the sour cream, bring briefly to a boil, and serve the sauce in a sauceboat alongside the risotto."],"time":75,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Risotto_jarskie","page":"100 postnych i jarskich dań/Risotto jarskie"},{"id":"oc-plwb-21712","title":"Roast bone-in pork loin stuffed with cabbage and apples (Schab nadziewany kapustą i jabłkami)","cuisine":"European","category":"Main","ingredients":["2.25 kg bone-in pork loin with rind","1 white cabbage (head)","4 tart apples (large)","1 tbsp lard","2 onions (part finely diced for stuffing, part sliced for topping)","to taste salt"],"steps":["Shred the cabbage, pour boiling water over it in a colander, and drain thoroughly.","Peel the tart apples and dice them finely or grate on a coarse box grater.","Finely chop one onion and sauté it in hot lard, then slice the other onion.","Toss the cabbage with the apples and sautéed onion, and season the stuffing with salt.","Make deep incisions in the pork loin, stuff the prepared filling beneath the skin and between the rib bones, and tie securely with kitchen string.","Transfer the meat to a roasting pan and roast for 120 minutes in an oven preheated to 200 °C.","Baste the pork with the pan drippings 15 minutes before the end of roasting and arrange the remaining onion slices over the top."],"time":150,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Schab_nadziewany_kapust%C4%85_i_jab%C5%82kami","page":"Książka kucharska/Schab nadziewany kapustą i jabłkami"},{"id":"oc-plws-577945","title":"Roast capon","cuisine":"European","category":"Main","ingredients":["1 capon","to taste salt","15 ml butter (orig. 1 tbsp)","1 rusk (source states 1–2 pieces; lower bound used; crushed)"],"steps":["Clean and dress the capon.","Salt the capon.","Wrap the capon in baking paper.","Roast the capon in a roasting pan in an oven at 180 °C, basting with butter, until cooked through.","Sprinkle the roasted capon with the crushed rusk.","Spoon the butter collected in the roasting pan over the capon."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kap%C5%82on_na_pieczyste","page":"Kucharka litewska (1913)/Kapłon na pieczyste"},{"id":"oc-plwb-14006","title":"Roast chicken legs with potatoes and garlic (Udka z kurczaka z ziemniakami)","cuisine":"European","category":"Main","ingredients":["4 chicken legs","1 kg potatoes","2 garlic (heads)","to taste poultry seasoning","to taste all-purpose vegetable seasoning (Vegeta type)","to taste mixed herbs (any)","2 tbsp mayonnaise","to taste cooking oil (for greasing the baking sheet)"],"steps":["Preheat the oven to 180 °C and grease a baking sheet with oil.","Sprinkle the chicken legs with poultry seasoning and all-purpose seasoning, then arrange them on the baking sheet.","Peel the potatoes, cut them into quarters, and arrange them around the chicken legs along with the unpeeled cloves from the two heads of garlic.","Brush the chicken legs with mayonnaise, sprinkle everything again with seasonings and herbs, and roast for about 50 minutes until the meat is browned and the potatoes are tender and golden."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Udka_z_kurczaka_z_ziemniakami","page":"Książka kucharska/Udka z kurczaka z ziemniakami"},{"id":"oc-plws-45022","title":"Roast goose stuffed with apples (Gęś pieczona)","cuisine":"European","category":"Main","ingredients":["1 young goose (approx. 3.5–4 kg)","6 tart cooking apples (for stuffing the goose)","3 onion (orig. several onions)","1 tbsp marjoram","1 tbsp plain wheat flour (1/2 tbsp for dusting the goose and 1/2 tbsp for the gravy)","150 ml water (for basting at the start of roasting)","1 tbsp sugar (for sprinkling the roasted apples)","to taste salt"],"steps":["Rub the thoroughly cleaned young goose inside and out with salt.","Fill the cavity of the goose with small whole or quartered tart apples tossed with marjoram, then sew up the opening with kitchen twine.","Spread the sliced onions in a roasting pan, set the goose on top, and roast in an oven preheated to 180 °C for about 3 hours (180 minutes), basting at first with water and then with the rendered fat and pan juices.","Toward the end of roasting, dust the top of the goose with half of the wheat flour so the skin browns deeply.","Transfer the roast goose to a platter, scoop the roasted apples out of the cavity, arrange them around the bird, and sprinkle them with sugar.","Skim the excess clear goose fat from the roasting pan, dust the onion pan juices with the remaining half tablespoon of wheat flour, bring to a boil, and pour the gravy over the goose."],"time":210,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/G%C4%99%C5%9B_pieczona_nadziewana","page":"365 obiadów za 5 złotych/Gęś pieczona nadziewana"},{"id":"oc-plwb-12554","title":"Roast pork loin with almonds (Schab w migdałach)","cuisine":"European","category":"Main","ingredients":["1.5 kg boneless pork loin","80 ml dry white wine (1 tbsp reserved for the almond paste, the rest for the marinade)","2 tbsp margarine","3 tbsp honey","4 tbsp flaked almonds","2 tbsp lemon juice","to taste traditional Polish meat seasoning","to taste salt","to taste black pepper (ground)"],"steps":["Rub the pork loin with salt, pepper, and traditional Polish seasoning, then prick the meat deeply all over.","Drizzle the pork with the lemon juice and wine (reserving 1 tbsp of wine for later), then refrigerate for 3 hours.","Tie the marinated roast with kitchen twine and brown on all sides in hot melted margarine.","Transfer the pork loin to a baking dish and roast for about 60 minutes in an oven preheated to 180 °C, basting regularly with the pan juices.","Place the flaked almonds in a plastic bag, crush them into smaller pieces, and mix with the honey and reserved tablespoon of wine.","Remove the roast from the oven, cut away the twine, spread the almond paste evenly over the top, and bake for another 10–15 minutes at 180 °C."],"time":105,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Schab_w_migda%C5%82ach","page":"Książka kucharska/Schab w migdałach"},{"id":"oc-plws-44999","title":"Roast stuffed turkey (Indyk pieczony nadziewany)","cuisine":"European","category":"Main","ingredients":["1 turkey (orig. 1 turkey or hen turkey)","to taste pork fatback (fresh, cut into thin strips for larding and diced for the stuffing)","1 turkey liver (finely chopped)","1 breadcrumbs (orig. 1 grated roll for the stuffing, plus extra for sprinkling toward the end of roasting)","1 onion (roasted and finely chopped)","2 eggs (whole)","1 tbsp butter (for the stuffing, plus extra melted butter for basting)","to taste salt (for rubbing the turkey and seasoning the stuffing)","to taste black pepper","1 pinch mace (a small amount)","1 tsp sugar (optional, for the stuffing)","1 raisins (orig. 1 handful of sultanas or currants, rinsed)"],"steps":["Clean the turkey thoroughly, rinse, pat dry, insert thin strips of fatback at close intervals into the breast and thighs, and rub well inside and out with salt.","Finely chop the turkey liver and roasted onion and mix with the breadcrumbs, whole eggs, a tablespoon of butter, diced fresh fatback, salt, pepper, mace, sugar, and rinsed raisins.","Fill the neck cavity (crop) of the turkey with the stuffing and sew the opening shut with strong kitchen twine.","Place the turkey in an oven preheated to 220 °C for 30 minutes, then lower the heat to 180 °C and roast for about 90 minutes longer, basting frequently with melted butter.","Toward the end of roasting, sprinkle the turkey with breadcrumbs and finish roasting until the skin is evenly golden brown."],"time":165,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Indyk_pieczony_nadziewany","page":"365 obiadów za 5 złotych/Indyk pieczony nadziewany"},{"id":"oc-plwb-14286","title":"Roast turkey breast stuffed with peaches (Pierś indyka z brzoskwiniami)","cuisine":"European","category":"Main","ingredients":["800 g turkey breast fillet","250 ml orange juice","5 peaches","to taste salt","to taste white pepper"],"steps":["Wash and dry the turkey fillet, place in a bowl, pour over the orange juice, cover, and refrigerate for about 60 minutes.","Blanch the peaches, peel the skin, cut in half, remove the pits, and dice the flesh.","Remove the meat from the orange juice, drain, cut a deep pocket into it, stuff with the peach pieces, and secure the edges with toothpicks.","Season the fillet with salt and white pepper, wrap tightly in aluminium foil, place in a roasting pan, and bake for about 60 minutes in an oven preheated to 200 °C."],"time":80,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pier%C5%9B_indyka_z_brzoskwiniami","page":"Książka kucharska/Pierś indyka z brzoskwiniami"},{"id":"oc-plws-577935","title":"Roast turkey with liver stuffing","cuisine":"European","category":"Main","ingredients":["1 turkey","100 g butter (orig. ¼ funt; historical measure, converted approximately)","to taste salt","1 calf's liver","1 French roll","250 ml milk (orig. a szklanka or 1½; source allows 250–375 ml, lower bound used.)","3 egg yolks","2 eggs","1 tbsp butter (orig. 1 tbsp)","125 ml raisins (orig. ½ szklanka)","2 sugar lumps (orig. 2 lumps; weight of lumps not specified.)","to taste allspice"],"steps":["Clean the turkey.","Leave the turkey in the refrigerator to tenderize for several days, that is, for more than 2880 minutes.","Season the turkey with salt.","Cook the liver until tender.","Finely chop the liver.","Soak the bread roll in the milk and squeeze it out.","Mix the liver with the bread roll, egg yolks, eggs, the butter for the stuffing, raisins, sugar, allspice, and salt.","Stuff the skin at the neck of the turkey with the filling, and if needed also its cavity.","Preheat the oven to 180 °C.","Roast the turkey in a roasting pan until cooked through, basting with the butter reserved for roasting."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Indyk_pieczony%2C_nadziewany","page":"Kucharka litewska (1913)/Indyk pieczony, nadziewany"},{"id":"oc-plws-1081062","title":"Rogale drożdżowe (yeast crescents)","cuisine":"European","category":"Bread","ingredients":["2 l wheat flour (orig. half a garniec)","50 g fresh yeast (orig. 4 łuty)","500 ml milk (orig. half a kwarta)","200 g melted butter (orig. 1 kwaterka)","6 eggs","1 egg for glazing"],"steps":["Dissolve the yeast in part of the warm milk with a little flour, and leave the starter in a warm place until it begins to move.","Add the rest of the milk, the beaten eggs, the melted warm butter and the rest of the flour to the risen starter, and knead until the dough is smooth and elastic.","Leave the dough to rise in a warm place, and when it has doubled, roll it out and cut triangles or diamonds.","Roll each crescent from the wide edge toward the point, set them on a baking sheet, and leave them to rise again.","Brush the risen crescents with beaten egg and bake in an oven heated to 200 °C for about 20 minutes, until golden."],"time":140,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Rogale_dro%C5%BCd%C5%BCowe","page":"Baby, placki i mazurki/Rogale drożdżowe"},{"id":"oc-plwb-19152","title":"Rolada fantazyjna (pork and beef meatloaf roll with potatoes)","cuisine":"European","category":"Main","ingredients":["350 g pork","350 g lean beef","1 egg","1 onion (chopped)","2 kaiser roll","1 tsp mustard","1 tbsp cooking oil (for greasing the foil)","6 potatoes","125 ml sour cream","75 ml mixed fresh herbs (chives, basil, parsley leaves) (chopped)","to taste pepper","to taste salt"],"steps":["Soak the kaiser rolls in water, squeeze out excess liquid, and grind in a meat grinder together with the pork and beef.","Add the egg, chopped onion, mustard, salt, and pepper to the meat and mix thoroughly.","Spread the meat into a layer 1.5 cm thick on an oiled sheet of baking foil, sprinkle with chopped fresh herbs, and roll into a roulade without rolling the foil inside.","Arrange peeled, salted potatoes around the roulade and drizzle them with sour cream.","Wrap the edges of the foil to seal the entire dish, prick the foil on top, transfer to a roasting pan, add a splash of water, and bake for 60 minutes in an oven preheated to 200 °C."],"time":85,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rolada_fantazyjna","page":"Książka kucharska/Rolada fantazyjna"},{"id":"oc-plwb-18494","title":"Rolada serowa (cheese roulade)","cuisine":"European","category":"Snack","ingredients":["500 g firm cheese (in one piece)","200 g cooked ham","2 egg","2 carrot","400 g canned green peas (drained)","0.5 bunch parsley leaves (chopped)","200 g butter","100 g processed cheese","to taste salt","to taste pepper"],"steps":["Beat the softened butter with the processed cheese until smooth and stir in the chopped parsley leaves.","Boil the carrots and eggs until hard-boiled, cool, peel, and dice finely along with the ham, then fold into the butter-cheese mixture with the drained peas, seasoning with salt and pepper.","Place the piece of firm cheese into a sealed plastic bag and submerge in boiling water, turning until the cheese softens.","Remove the warm cheese from the bag and roll it out into a rectangle about 1 cm thick.","Spread the prepared filling over the cheese sheet, roll tightly into a log, wrap in aluminium foil, and chill in the refrigerator for about 2 hours before slicing."],"time":170,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rolada_serowa","page":"Książka kucharska/Rolada serowa"},{"id":"oc-plws-569434","title":"Rolada wieprzowa gotowana w żołądku (pressed pork, ham, and fatback roll boiled in stomach)","cuisine":"European","category":"Preserve","ingredients":["500 g fresh fatback (orig. 0.5 kg, cut into strips)","500 g smoked ham (orig. 0.5 kg, cut into strips)","2 kg fresh pork (moderately lean, cut into strips)","2 pig's ears (finely chopped after discarding the thick cartilage)","2 Spanish onion (finely chopped)","2 clove garlic (mashed)","1 tbsp marjoram (to taste)","4 bay leaf (for the filling and cooking liquid)","1 tsp allspice (for the filling and cooking liquid)","to taste black pepper (for the filling and cooking liquid)","to taste salt","100 ml vinegar (for acidulating the cooking water and moistening the wrapping cloth)","1 pork stomach (from a small pig, thoroughly cleaned)"],"steps":["Cut 500 g of fresh fatback, 500 g of smoked ham, and 2 kg of moderately lean fresh pork into strips, and finely chop 2 pig's ears (after removing the thick cartilage).","Add 2 finely chopped Spanish onions, 2 mashed cloves of garlic, and salt, black pepper, allspice, crumbled bay leaf, and marjoram to taste, then mix everything thoroughly.","Pack the meat mixture into a thoroughly cleaned pork stomach and sew the opening shut with strong thread.","Place the roll in a pot of water acidulated with vinegar along with bay leaf, black pepper, and allspice, and simmer gently for 2 hours from the moment it boils.","Remove the cooked roll, press firmly under a weighted board, and keep in a cool place for 24 hours before serving; store wrapped in a cloth moistened with vinegar."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/Rolada_wieprzowa","page":"Domowe wędliny/Rolada wieprzowa"},{"id":"oc-plwb-12759","title":"Rolada śląska (Silesian beef roulade)","cuisine":"European","category":"Main","ingredients":["500 g raw beef suitable for roasting","50 g smoked bacon","2 brine pickle (1–2 pcs)","1 onion (small)","1 tbsp mustard (level)","1 tbsp tomato paste (level)","50 g lard","to taste salt","to taste ground black pepper","1 tbsp plain flour (for thickening the sauce)","2 tbsp sour cream (for thickening the sauce)"],"steps":["Rinse the beef, slice it into cutlets, and pound gently with a water-moistened meat mallet.","Rub the meat slices with salt and pepper, then spread each with mustard and tomato paste.","Cut the onion, brine pickles, and smoked bacon into thin strips and place them onto the beef slices.","Roll the meat tightly into roulades and secure with toothpicks or tie with white kitchen twine.","Melt the lard in a saucepan, add the roulades, and brown thoroughly on all sides.","Add water or broth to the pan, cover, and braise for about 60 minutes until the roulades are tender.","Remove the toothpicks or twine from the finished roulades, thicken the sauce with sour cream stirred with plain flour, and bring briefly to a boil."],"time":90,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rolada_%C5%9Bl%C4%85ska","page":"Książka kucharska/Rolada śląska"},{"id":"oc-plwb-14810","title":"Roladki rybne z grzybami (fish rolls with porcini mushrooms)","cuisine":"European","category":"Main","ingredients":["1 kg white sea fish fillet (fresh, skinless (sole, halibut, or cod))","200 g smoked bacon (lean, sliced)","to taste fresh thyme","2 tbsp lemon juice (for drizzling over the fish)","to taste fish seasoning","3 tbsp plain flour (for coating the rolls)","3 tbsp cooking oil (for searing)","500 g porcini mushrooms","1 tbsp butter","125 ml sour cream","1 egg","1 tbsp breadcrumbs","1 tbsp parsley leaves (chopped)","1 tbsp chives (chopped)","to taste salt","to taste pepper","500 ml vegetable broth","1 egg yolk","2 tbsp plain flour","2 tbsp butter","2 tbsp capers","0.5 lemon (juice and grated zest)","to taste salt","to taste pepper","1 pinch sugar"],"steps":["Rinse the fish fillets, pat dry with paper towels, drizzle with lemon juice, dust with fish seasoning, and refrigerate covered.","Pour 250 ml of cold water over the capers and set aside to soak.","Clean and finely chop the porcini, place into a dry hot skillet and cook until liquid evaporates, then add 1 tablespoon of butter and braise until tender.","Remove the mushrooms from the heat, mix with chopped parsley leaves, chives, egg, sour cream, and breadcrumbs, and season with salt and pepper.","Cut the chilled fillets into portions, spread the mushroom filling over each, roll up, wrap each roll in a slice of bacon, and secure with a toothpick.","Dredge the rolls in flour, sear on all sides in hot oil, transfer to a roasting pan, sprinkle with fresh thyme, and bake for 10–15 minutes in an oven preheated to 180 °C, basting with pan drippings.","Make a blond roux from 2 tablespoons of butter and 2 tablespoons of flour, whisk in the cool vegetable broth, and cook stirring constantly until the sauce thickens.","Stir the juice and zest of half a lemon into the sauce, remove from heat, temper in the egg yolk, add the drained capers, and season with salt, pepper, and a pinch of sugar."],"time":65,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Roladki_rybne_z_grzybami","page":"Książka kucharska/Roladki rybne z grzybami"},{"id":"oc-plwb-22160","title":"Roladki z warzywami (turkey roulades with vegetables)","cuisine":"European","category":"Main","ingredients":["5 turkey cutlet","10 slice pork belly","1 zucchini","3 carrot","2 tbsp butter (1 tbsp for the vegetables, 1 tbsp for searing the rolls)","125 ml broth","2 tbsp mustard","1 bunch parsley leaves (chopped)","1 tbsp cooking oil (for searing)","to taste salt","to taste pepper"],"steps":["Peel the zucchini and carrots, slice lengthwise into strips, sauté in 1 tablespoon of butter, add the broth, and braise for 5 minutes.","Pound the turkey cutlets lightly, season with salt and pepper, and spread with mustard.","Place two slices of pork belly, the braised vegetable strips, and chopped parsley leaves onto each meat slice.","Roll the meat tightly into roulades so the ends of the vegetables stick out slightly, and secure with toothpicks.","Sear the rolls on all sides in the remaining butter and oil, add a splash of water, and simmer covered for 20–30 minutes."],"time":55,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Roladki_z_warzywami","page":"Książka kucharska/Roladki z warzywami"},{"id":"oc-plwb-17996","title":"Rolmopsy z musztardą (rollmops with mustard)","cuisine":"European","category":"Snack","ingredients":["4 matjes herring fillet (fillets)","4 egg","4 tbsp honey mustard","2 tbsp olive oil","2 tbsp olives (sliced)","2 parsley leaves (sprigs)","to taste salt","to taste pepper"],"steps":["Hard-boil the eggs, cool, and peel, reserving a few wedges for garnish, then mash the rest with olive oil and honey mustard, seasoning with salt and pepper.","Spread the prepared egg-mustard paste onto the matjes herring fillets and cut each lengthwise in half.","Roll up eight rolls and arrange them on a serving platter.","Garnish the rollmops with reserved egg wedges, olive slices, and parsley leaves."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rolmopsy_z_musztard%C4%85","page":"Książka kucharska/Rolmopsy z musztardą"},{"id":"oc-plws-552222","title":"Rose ice","cuisine":"European","category":"Dessert","ingredients":["1 l water (orig. 1 litre)","375 g sugar (orig. one and a half quarters of a kilogram)","2 lemons (the squeezed juice)","500 ml rose syrup (orig. half a litre)"],"steps":["Bring a thick syrup to the boil from 1 litre of water and 375 g of sugar, then cool it completely.","Squeeze the juice of two lemons into the cooled syrup, pour in 500 ml of rose syrup, and mix well.","Pour the mixture into an ice-cream maker and freeze it to a smooth sorbet (about 2–3 hours)."],"time":190,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_r%C3%B3%C5%BCanne","page":"Doświadczone sekreta smażenia konfitur i soków/Lody różanne"},{"id":"oc-plws-550056","title":"Rose liqueur","cuisine":"European","category":"Drink","ingredients":["2 l spirit (orig. 2 litres of the best spirit)","0.4 ml rose oil (orig. 8 drops of rose oil)","3 kg sugar (orig. 3 kilograms of crushed sugar)","1.5 l water (orig. one and a half litres of cold water)","2 tsp alkermes (orig. 2 teaspoons of alkermes for colour)"],"steps":["Pour 2 l of the best spirit into a demijohn, add 8 drops (about 0.4 ml) of rose oil, cork it tightly, and leave it in the shade for 24 hours.","The next day, cook a syrup from 3 kg of crushed sugar and 1.5 l of cold water, skim it carefully, and once it boils take it off the heat and cool it completely.","Pour the aromatic spirit a little at a time into the completely cold syrup, stirring constantly, then pour it back into the demijohn and leave it in the shade until the next day.","The following day, add 2 teaspoons of alkermes to give it a pink colour, leave it in the demijohn for another 4 days, then bottle it, cork it, and keep it in a cool place for 4 months before serving."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_r%C3%B3%C5%BCanny","page":"Doświadczone sekreta smażenia konfitur i soków/Likier różanny"},{"id":"oc-plws-550059","title":"Rose liqueur, another way","cuisine":"European","category":"Drink","ingredients":["750 g sugar-rose petals (the white tips removed: 500 g for the maceration in spirit and 250 g for the syrup)","750 ml 95% rectified spirit (enough to cover the rose petals in the demijohn)","1000 g sugar (orig. 1 kilogram)","500 ml water or rose water (for cooking the syrup)","1 lemon (the squeezed juice)","3 tsp currant juice (optional, a few teaspoons of clear juice for colour)"],"steps":["Cut the pale tips off sugar-rose petals, put 500 g of petals into a glass demijohn or a large jar, cover them with spirit so it covers them completely, and leave it in a shaded place for 4 days.","Cook a syrup from 1 kg of sugar and 500 ml of water (or rose water), add the remaining 250 g of trimmed rose petals, squeeze in the lemon juice (and, if you like, a few teaspoons of currant juice for colour), and cook briefly over low heat.","Combine the cooled rose syrup with the spirit infusion, petals and all, and leave it in the closed demijohn for a few more days.","Strain the finished liqueur through thick muslin or gauze and bottle it."],"time":20,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_z_r%C3%B3%C5%BC_innym_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Likier z róż innym sposobem"},{"id":"oc-plws-548817","title":"Rose Petal Jelly","cuisine":"European","category":"Preserve","ingredients":["1 kg rose petals suitable for preserves (fresh, trimmed of their white bases)","4 l gooseberries (half-ripe)","1.5 l water (boiling: 1 l for cooking the gooseberries and approx. 0.5 l for scalding the rose petals)","1.5 kg sugar (broken into small pieces)"],"steps":["Pick over the rose petals, trim off the white bases, place in a stoneware pot, and add just enough boiling water to cover; cover and leave until completely cool.","Bring 1 l of water to a boil, add 4 l of half-ripe gooseberries, cook until the juice is released, and strain through a sieve.","Place 1.5 kg of sugar in a stoneware pan and add 750 ml (3 glassfuls) of strained gooseberry juice and 250 ml (1 glassful) of rose infusion.","Bring the mixture to a boil three times over high heat, removing from the burner and skimming the foam each time, then simmer over low heat until thickened.","Strain the hot jelly through a fine sieve and pour immediately into warmed jars."],"time":100,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_r%C3%B3%C5%BCanna","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta różanna"},{"id":"oc-plwb-16993","title":"Rosół babuni (traditional Polish beef and chicken broth)","cuisine":"European","category":"Soup","ingredients":["0.5 chicken (half a chicken)","400 g beef","1 bunch Polish soup vegetables (carrot, parsley root, celeriac and leek) (with cabbage)","1 onion","1 dried mushroom","1 bay leaf","5 black peppercorns","3 allspice berries","to taste salt","3 crêpes (cooked, for serving)","2 l water"],"steps":["Place the beef and half chicken into a pot, add the rinsed soup vegetables without the cabbage, dried mushroom, bay leaf, black peppercorns, and allspice berries.","Pour 2 litres of water over the ingredients, bring to a boil, reduce the heat, and simmer gently for an hour, skimming any foam from the surface regularly.","After an hour of simmering, add the cabbage from the soup vegetables and the onion charred in a dry skillet, then simmer for another hour.","Remove the meat and vegetables, strain the broth through a fine sieve, season with salt, and heat thoroughly.","Roll the crêpes into tight cylinders, slice into thin ribbons, and serve with hot broth ladled over them."],"time":135,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ros%C3%B3%C5%82_babuni","page":"Książka kucharska/Rosół babuni"},{"id":"oc-plwb-15969","title":"Rosół rybno-grzybowy po mazursku (Masurian fish and mushroom broth)","cuisine":"European","category":"Soup","ingredients":["1 kg pikeperch (or pike)","1 bunch Polish soup vegetables (carrot, parsley root, celeriac and leek) (to cook 2 l of broth)","50 g dried porcini","to taste salt","2 bay leaf","4 allspice berries","1 egg white (for clarifying the broth)","2 l water"],"steps":["Soak the dried porcini in water, then simmer in a separate pot until tender.","Make 2 litres of stock from the Polish soup vegetables, bay leaf, allspice berries, and salt, add the cleaned pikeperch or pike, and simmer gently until the fish is tender.","Combine the strained fish stock with the mushroom broth.","Clarify the hot broth with egg white, strain through a sieve, and serve."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ros%C3%B3%C5%82_rybno-grzybowy_po_mazursku","page":"Książka kucharska/Rosół rybno-grzybowy po mazursku"},{"id":"oc-plws-549970","title":"Rosół z kurczęcia (Delicate young-chicken broth)","cuisine":"European","category":"Soup","ingredients":["500 g chicken (small, whole, thoroughly cleaned; orig. half-kilo)","1.25 l water (for a 500 g chicken; orig. a litre and a quarter)","1 parsley root (generous)","1 carrot (large)","1 fresh dill (a generous sprig)","to taste salt (for the chicken and the broth)"],"steps":["Rub the cleaned chicken with salt.","Truss the chicken so it does not fall apart during cooking.","Bring the water to a boil with the parsley root, carrot, and dill.","Lower the chicken into the boiling stock.","Bring the broth back to a boil over high heat.","Skim the foam from the surface of the broth.","Lower the heat so that the broth barely trembles.","Season the broth with salt.","Simmer a small chicken for about 25 minutes until cooked through; an older chicken may require up to 45 minutes.","Cut the cooked chicken into quarters.","Serve the chicken in the broth."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/Dr%C3%B3b%2C_sposoby_przyrz%C4%85dzania/Ros%C3%B3%C5%82_z_kurcz%C4%99cia","page":"Drób, sposoby przyrządzania/Rosół z kurczęcia"},{"id":"oc-plws-42470","title":"Rough puff pastry for small savoury pies","cuisine":"European","category":"Snack","ingredients":["400 g plain wheat flour (orig. 1 funt)","200 g butter (orig. 1/2 funt, chilled)","4 eggs (3 for the dough and 1 for sealing and brushing)","3 tbsp water or sweet cream (orig. several tablespoons)"],"steps":["Knead a uniform dough from the wheat flour, chilled butter, 3 eggs, and the water or sweet cream.","Roll the dough out thinly, fold in four, and roll out again; repeat the folding and rolling 2–3 times, then let the folded dough rest for 10 minutes.","Roll the pastry out again into a thin sheet and cut out round discs with a glass or cutter.","Brush the edges of half the discs with egg white, place your chosen filling in the centre, cover with a second disc of pastry, seal the edges, and brush the tops with beaten egg.","Place in a well-heated oven (200 °C) and bake for 30 minutes until golden brown."],"time":75,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ciasto_ma%C5%9Blane_do_pasztecik%C3%B3w","page":"365 obiadów za 5 złotych/Ciasto maślane do pasztecików"},{"id":"oc-plws-544362","title":"Rowanberries in Syrup","cuisine":"European","category":"Preserve","ingredients":["500 g rowanberries (very ripe, picked after the first frosts)","1 kg sugar (chopped into small pieces, or 750 g for a tarter flavor)","375 ml water (1.5 glasses for the syrup, plus boiling and cold water for scalding the berries)","2 tbsp rose water (optional for aroma)"],"steps":["Prick each frost-sweetened rowanberry with a wooden pin, scald with boiling water, immediately rinse with cold water on a sieve, and leave to drain thoroughly (omit the scalding for a sharper flavor).","Boil a syrup from 1 kg of sugar, 375 ml (1.5 glasses) of water, and optionally 2 tablespoons of rose water, and let cool.","Add the drained rowanberries to the cooled syrup and leave overnight.","On the second day, simmer the preserve — first over higher and then over lower heat — skimming carefully and taking care that the syrup does not thicken excessively; once cooled, transfer to jars."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jarz%C4%99bina","page":"Doświadczone sekreta smażenia konfitur i soków/Jarzębina"},{"id":"oc-plws-550041","title":"Rowanberry liqueur","cuisine":"European","category":"Drink","ingredients":["2 l rowanberries (orig. several litres of fine, ripe, lightly frost-nipped rowanberries)","1 l spirit (the best, enough to cover the rowanberries completely)","1 kg sugar (orig. 1 kilogram of crushed sugar per 1 litre of spirit)","375 ml water (orig. one and a half szklanki of cold water for the syrup, per 1 l of spirit (plus boiling water for blanching the rowanberries several times))"],"steps":["Pour boiling water several times over 2 l of ripe, lightly frost-nipped rowanberries in a colander, and leave them to drain well.","Put the blanched rowanberries into a large demijohn, cover them with 1 l of the best spirit so the fruit is completely covered, seal it, and leave it in a warm room for 1 month.","After a month, pour off and strain the rowan spirit. Cook a syrup from 1 kg of crushed sugar and 375 ml of cold water, skim it carefully, and cool it.","Mix the clarified, cooled syrup with the strained rowanberry spirit, pour into a clean demijohn, cork, and leave in a cool place for another month. Then filter through paper, bottle, cork, seal with wax, and leave for 6 months before serving."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_jarz%C4%99binowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier jarzębinowy"},{"id":"oc-plwb-18794","title":"Rowanberry, pear and apple jam","cuisine":"European","category":"Preserve","ingredients":["1 kg rowanberries","500 g pears","500 g apples","1 kg sugar","250 ml water","1 tsp lemon juice"],"steps":["Sort through the rowanberries, blanch them in boiling water, and drain well; peel and core the pears and apples, then cut into quarters.","Prepare a syrup by boiling the water and sugar, add the drained rowanberries, and simmer briefly.","Add the sliced apples and pears and cook over very low heat until the fruit turns translucent and the jam thickens nicely.","Stir in the lemon juice, ladle the hot jam into sterilized jars, seal tightly, and leave covered to cool slowly."],"time":90,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/D%C5%BCem_z_jarz%C4%99biny%2C_gruszek_i_jab%C5%82ek","page":"Książka kucharska/Dżem z jarzębiny, gruszek i jabłek"},{"id":"oc-plws-546603","title":"Ruffe fish soup with quenelles (zupa rybna z jazgarzy z pulpetami)","cuisine":"European","category":"Soup","ingredients":["500 g ruffe fish (orig. 50 dkg)","100 g stale wheat roll (orig. 10 dkg)","1 egg (small)","2 large onions (1 whole for broth and 1 whole for fish mixture)","30 g plain wheat flour (orig. 3 dkg)","1.5 l water (for simmering fish broth)","1 bay leaf","to taste black pepper","to taste salt"],"steps":["Carefully fillet the meat from the raw ruffe, and using the heads, bones, one onion, bay leaf, and pepper, simmer a fish broth in 1.5 l of salted water for about 30 minutes, then strain.","Mince the fish fillets in a meat grinder, add the second onion (finely grated) and the soaked and well-squeezed bread roll, then chop with a cleaver on a pastry board until a smooth paste forms.","Season the mixture with salt and pepper, beat in the egg, and knead thoroughly once more.","Shape the mixture into rolls the thickness of a slender candle, dredge in plain wheat flour, and simmer in the boiling fish broth for about 10 minutes.","Slice the cooked rolls into thin rounds and serve in the hot broth."],"time":85,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Zupa_rybna_z_pulpetami","page":"109 potraw/Zupa rybna z pulpetami"},{"id":"oc-plwb-61736","title":"Rumpuć (Wielkopolska meat and vegetable soup)","cuisine":"European","category":"Soup","ingredients":["500 g beef (diced)","500 g pork shoulder (diced)","300 g smoked bacon (cut into pieces)","500 g sauerkraut","0.25 savoy cabbage (shredded)","500 g potatoes (cut into pieces)","2 onion (chopped)","3 carrot (cut into pieces)","2 apple (tart, cut into pieces)","150 g butter","190 g tomato paste","2 bay leaf","3 allspice berries","1 tsp ground caraway","to taste salt","to taste pepper"],"steps":["Place the diced beef into a large pot of water, add the bay leaves, allspice berries, and salt, and simmer gently.","Melt the butter in a skillet, brown the diced pork shoulder, smoked bacon, and onion, and transfer everything into the pot with the beef.","Add the shredded savoy cabbage, sauerkraut, cut carrots, and potatoes, and cook until the meat and vegetables are tender.","Toward the end of cooking, stir in the tomato paste, add the tart apples cut into pieces, and season the soup with salt, pepper, and ground caraway."],"time":120,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rumpu%C4%87","page":"Książka kucharska/Rumpuć"},{"id":"oc-plws-546630","title":"Russian Kurnik (Chicken and Buckwheat Crepe Pie)","cuisine":"European","category":"Main","ingredients":["160 g wheat flour (orig. 1 cup, for the crepes)","2 eggs (1 raw egg for the crepe batter and 1 hard-boiled egg for the filling)","600 ml water (for the crepe batter and for cooking the groats with the mushrooms)","1 pork fatback rind (for greasing the skillet)","600 g cooked chicken meat (orig. meat picked from half a hen cooked for broth)","5 dried wild mushrooms (a few mushrooms)","200 g unroasted buckwheat groats (orig. 1 cup of white cracked buckwheat groats)","60 g margarine or lard (orig. 6 dkg, for the pan and the filling)","4 tbsp chicken broth (a few tablespoons for moistening the filling)","to taste salt"],"steps":["Whisk the raw egg with the wheat flour, a pinch of salt, and water, and fry 12–15 thin crepes in a skillet greased with the pork fatback rind.","Cook the white buckwheat groats until fluffy together with the dried mushrooms, then remove the mushrooms and chop them finely.","Pull the meat from the half cooked hen into bite-sized pieces, and coarsely chop the hard-boiled egg.","Gently toss together the chicken meat, buckwheat groats, chopped mushrooms, and hard-boiled egg, adding a few tablespoons of broth and most of the melted fat.","Grease a springform pan or shallow baking dish with the remaining fat, line the bottom and sides with the crepes, pack in the filling, cover the top with a crepe, and bake in a hot oven (190 °C) for about 25–30 minutes until golden."],"time":90,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kurnik_rosyjski","page":"109 potraw/Kurnik rosyjski"},{"id":"oc-plwb-13755","title":"Ryba duszona z bakaliami (fish braised with dried fruit and nuts)","cuisine":"European","category":"Main","ingredients":["800 g sea fish fillet","1 onion (chopped)","2 tbsp walnuts (chopped)","2 tbsp raisins","2 apple (tart)","100 g prunes","1 tbsp butter","1 tbsp plain flour","2 tbsp lemon juice","4 cloves (a few)","to taste salt","to taste pepper","2 tbsp cooking oil (for frying)"],"steps":["Cut the fish fillets into smaller portions, drizzle with lemon juice, and set aside for 30 minutes.","Drain the fish, season with salt and pepper, dredge in flour, fry in hot oil until golden, and transfer to a pot.","Add the scalded raisins, finely chopped apples and prunes, chopped onion, butter, and cloves to the fish.","Pour in a small amount of hot water and braise covered for about 15 minutes.","Towards the end of braising, stir in the chopped walnuts and mix gently."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_duszona_z_bakaliami","page":"Książka kucharska/Ryba duszona z bakaliami"},{"id":"oc-plwb-14019","title":"Ryba duszona z warzywami (fish braised with vegetables)","cuisine":"European","category":"Main","ingredients":["400 g fried fish","4 carrot","1 parsley root","2 onion","70 g tomato paste","1 lemon (sliced, for garnish)","1 tbsp butter","2 tbsp cooking oil","to taste salt","to taste pepper"],"steps":["Clean and peel the carrots and parsley root, then grate them on a coarse grater.","Melt the butter in a skillet and lightly sauté the grated root vegetables.","Peel the onions, chop them finely, and cook in hot oil until translucent.","Combine the onion with the sautéed carrot and parsley root, add a little boiling water, cover, and braise until tender.","Stir in the tomato paste, season the sauce with salt and pepper, add the fried fish pieces, and heat through.","Divide the dish among plates and garnish with lemon slices."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_duszona_z_warzywami","page":"Książka kucharska/Ryba duszona z warzywami"},{"id":"oc-plws-546694","title":"Ryba faszerowana po żydowsku z drobnych rybek (Jewish-style minced small-fish roll)","cuisine":"European","category":"Main","ingredients":["1 kg small freshwater fish (cleaned; if using ruffe, remove heads and gills)","5 onions (4 whole for fish mixture and 1 whole for broth)","150 g stale wheat roll (orig. 15 dkg)","150 g boiled potatoes (orig. 15 dkg)","2 eggs (large)","250 ml ice-cold water (orig. 1 szklanka, for mixing the fish mixture + water for the broth)","1 tbsp vegetable oil or lard (for greasing cloth napkin)","1 bay leaf","to taste allspice berries","to taste black pepper","to taste salt"],"steps":["Pass the cleaned small fish through a meat grinder together with 4 onions, the soaked and squeezed wheat roll, and the boiled, peeled potatoes.","Turn the mixture onto a pastry board and chop with a cleaver or knead, gradually adding 250 ml of ice-cold water until smooth and sticky.","Beat in the eggs, season with salt and plenty of pepper, and mix thoroughly once more.","Scald a clean linen napkin with boiling water, wring out thoroughly, and grease the center with oil or lard. Shape the fish mixture into an oblong roll, wrap in the napkin, and tie with kitchen twine.","Boil a court bouillon from the remaining onion, bay leaf, allspice berries, pepper, and salt, cool slightly, lower in the fish roll, bring to a boil, and simmer gently for 60 minutes.","Once cooked, remove the fish roll, immediately unwrap from the napkin so it does not stick, wrap loosely again, and keep warm in the broth until serving, then slice finger-thick."],"time":120,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Ryba_faszerowana_po_%C5%BCydowsku_z_drobnych_rybek","page":"109 potraw/Ryba faszerowana po żydowsku z drobnych rybek"},{"id":"oc-plwb-18064","title":"Ryba gotowana (poached fish with egg and herbs)","cuisine":"European","category":"Main","ingredients":["1 kg fresh fish (cleaned and gutted)","1 l vegetable broth","2 onion (cut into half-moons)","40 g butter (cold)","4 egg","2 tbsp parsley leaves (chopped fresh herbs)","0.5 lemon (sliced)","to taste salt"],"steps":["Place the cleaned fish and sliced onion into the salted vegetable broth and simmer gently for about 20 minutes.","Carefully transfer the fish with a slotted spoon to a platter and arrange the cooked onion beside it.","Hard-boil the eggs, cool, peel, and chop very finely.","Sprinkle the hot fish with chopped egg and fresh herbs, and top each portion with a pat of cold butter and a lemon slice."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_gotowana","page":"Książka kucharska/Ryba gotowana"},{"id":"oc-plwb-3526","title":"Ryba po grecku (Polish Greek-style fish)","cuisine":"European","category":"Main","ingredients":["400 g fish fillet","1 onion","1 bay leaf","3 allspice berries","to taste ground black pepper","to taste salt","450 g Polish soup vegetables (carrot, parsley root, celeriac and leek) (400–500 g)","6 tbsp cooking oil","6 tsp ketchup","2 tsp plain flour","to taste sugar","to taste lemon juice (for the sauce)","to taste parsley leaves (chopped, for garnish)"],"steps":["Poach the fish fillets in broth made with part of the soup vegetables, the bay leaf, allspice berries, salt, and pepper, then remove the fish and reserve 250 ml of the poaching broth.","Clean the remaining vegetables and onion, then shred or finely dice them.","Heat the oil in a skillet, add the shredded vegetables, season with salt, and fry for about 5 minutes.","Pour in 250 ml of the fish broth and simmer the vegetables covered until tender.","Mix the flour with a small amount of water, ketchup, salt, sugar, and lemon juice, stir into the braised vegetables, and simmer together for about 3 minutes.","Arrange the poached fish in a serving dish, cover with the hot vegetables in sauce, and sprinkle with chopped parsley leaves."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_po_grecku","page":"Książka kucharska/Ryba po grecku"},{"id":"oc-plwb-19263","title":"Ryba po podhalańsku (Podhale-style baked fish)","cuisine":"European","category":"Main","ingredients":["800 g pollock fillet","3 potatoes","80 g celeriac","100 g carrot","1 onion (large)","2 clove garlic (chopped)","70 g prunes","2 tbsp sour cream","150 ml tomato juice (thick)","1 tbsp parsley leaves (chopped)","1.5 tbsp lemon juice","2 tbsp plain flour","2 tbsp butter","40 ml cooking oil","to taste salt","to taste pepper"],"steps":["Soak the prunes in water, drain, and cut into thin strips.","Rinse and pat dry the pollock fillets, drizzle with the juice of half a lemon, season with salt and pepper, dredge in flour, and fry in part of the oil on both sides until golden.","Peel the vegetables, slice the potatoes and carrots, dice the celeriac, and slice the onion into half-moons.","Sauté the prepared vegetables in a roasting dish in the remaining oil, then stir in the butter and prune strips near the end of cooking.","Arrange the fried fish on top of the vegetables, pour over the thick tomato juice mixed with sour cream, minced garlic, salt, and pepper, and bake for 10–15 minutes in an oven preheated to 180 °C.","Sprinkle the hot dish with chopped parsley leaves before serving."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_po_podhala%C5%84sku","page":"Książka kucharska/Ryba po podhalańsku"},{"id":"oc-plwb-18345","title":"Ryba w pomidorach (baked fish with tomatoes)","cuisine":"European","category":"Main","ingredients":["400 g fresh fish","200 g tomato (cut into thick slices)","20 g plain flour","2 tbsp cooking oil (half to rub the fish, half for drizzling)","1 tbsp parsley leaves (chopped)","1 tsp sweet paprika","to taste salt"],"steps":["Clean, gut, and rinse the fish, then divide into portions and season with salt.","Mix 1 tablespoon of oil with the flour and sweet paprika, and rub the resulting paste over the fish pieces.","Arrange the fish on a baking sheet and top with thick slices of fresh tomatoes.","Sprinkle with chopped parsley leaves, drizzle with the remaining tablespoon of oil, lightly salt, and bake in an oven preheated to 180 °C for about 25 minutes."],"time":40,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_w_pomidorach","page":"Książka kucharska/Ryba w pomidorach"},{"id":"oc-plwb-13749","title":"Ryba w sosie koperkowym (fish in dill sauce)","cuisine":"European","category":"Main","ingredients":["800 g fish fillets (any kind of fish, fresh or frozen)","500 g button mushrooms","3 onions","1 tbsp butter","250 ml sour cream","250 ml dry white wine","4 tbsp dill (chopped)","to taste lemon juice (for drizzling)","to taste salt"],"steps":["Rinse and pat dry the fish fillets, drizzle with lemon juice, set aside for about 15 minutes to dry, and then sprinkle with salt.","Peel the onions and finely chop them; peel the mushrooms and slice them thinly.","Cook the onion and mushrooms gently, covered, in the melted butter, arrange the fish on top, and pour in the white wine.","Braise the fish until tender, then remove the fillets and keep them in a warm place.","Stir the sour cream into the braising liquid, bring the sauce to a boil, stir in the chopped dill, season with salt to taste, and pour over the fish."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_w_sosie_koperkowym","page":"Książka kucharska/Ryba w sosie koperkowym"},{"id":"oc-plwb-13752","title":"Ryba w sosie pieczarkowym (fish in mushroom sauce)","cuisine":"European","category":"Main","ingredients":["800 g fish fillets","100 g button mushrooms","250 ml sour cream","1 tsp butter","to taste sweet paprika","to taste lemon juice","to taste salt","to taste black pepper","to taste parsley (for serving)"],"steps":["Arrange the fish fillets in an ovenproof baking dish, add a splash of water, season with salt and pepper, and sprinkle with lemon juice.","Cover the dish with aluminum foil, place in an oven preheated to 200 °C, and bake for about 20 minutes.","Melt the butter in a saucepan, add the thinly sliced mushrooms, pour in the sour cream, and season with sweet paprika, salt, and pepper.","Heat the sauce gently over low heat, taking care not to let it boil.","Transfer the hot fish to plates, spoon the mushroom sauce over the top, and sprinkle with parsley."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_w_sosie_pieczarkowym","page":"Książka kucharska/Ryba w sosie pieczarkowym"},{"id":"oc-plwb-13992","title":"Ryba w sosie wiosennym (fish in spring yogurt sauce)","cuisine":"European","category":"Main","ingredients":["4 cod fillets","1 fresh cucumber (small)","50 g green grapes","150 g plain yogurt (thick)","0.5 tsp mint syrup","2 tsp lemon juice","to taste salt","to taste black pepper","to taste cucumber slices (for garnish)"],"steps":["Arrange the cod fillets in a shallow microwave-safe dish, sprinkle with lemon juice, and cook in the microwave for about 5 minutes.","Peel the small cucumber, scoop out the seeds, and finely dice the flesh.","Cut the grapes in half, remove the seeds, and set aside a few halves for garnish.","Stir the thick plain yogurt with the mint syrup, diced cucumber, and remaining grapes, then season the sauce with salt and pepper.","Spoon the sauce over the fish and heat in the microwave for another 3 minutes.","Garnish the dish with cucumber slices and the reserved grape halves, then serve."],"time":18,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_w_sosie_wiosennym","page":"Książka kucharska/Ryba w sosie wiosennym"},{"id":"oc-plwb-14723","title":"Ryba w sosie zielonym (poached fish in parsley and sour cream sauce)","cuisine":"European","category":"Main","ingredients":["1 kg fish (cut into portions)","1 l vegetable broth","20 g butter","20 g plain flour","120 ml sour cream","125 ml dry white wine","to taste parsley (finely chopped)","to taste salt"],"steps":["Place the portioned fish into a pot with the vegetable broth, simmer gently for about 20 minutes, then transfer to a serving platter.","Prepare a light roux in a skillet with the butter and flour, then gradually whisk in the hot fish cooking broth.","Stir the sour cream and dry white wine into the sauce, and season with salt to taste.","Add the finely chopped parsley, simmer the sauce for another moment, and pour over the fish portions on the platter."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_w_sosie_zielonym","page":"Książka kucharska/Ryba w sosie zielonym"},{"id":"oc-plwb-13754","title":"Ryba z czosnkiem (baked fish with garlic)","cuisine":"European","category":"Main","ingredients":["4 fish fillets","4 onions (small)","2 clove garlic","4 tsp oil","2 tsp parsley (chopped)","2 tomatoes","3 tbsp dry white wine","2 tbsp breadcrumbs","to taste salt","to taste black pepper"],"steps":["Preheat the oven to 180 °C and place a lightly oiled baking dish inside.","Sprinkle the bottom of the hot dish with parsley and 1 teaspoon of finely chopped onion, then heat for a few minutes.","Place the fish fillets in the dish, season with salt and pepper, and top with the pressed garlic and remaining chopped onion.","Arrange tomato slices over the fillets, drizzle with the white wine and remaining oil, and sprinkle with breadcrumbs.","Bake the fish in the oven at 180 °C for 20 minutes."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_z_czosnkiem","page":"Książka kucharska/Ryba z czosnkiem"},{"id":"oc-plwb-14194","title":"Ryba z ryżem i warzywami (fish patties with rice and vegetables)","cuisine":"European","category":"Main","ingredients":["500 g fish fillets","100 g rice","100 g broccoli (small florets)","1 carrot","2 eggs (1 for the mixture, 1 for breading)","250 ml breadcrumbs (half for the mixture, half for breading)","1 onion","125 ml plain flour (for coating)","to taste salt","to taste black pepper","to taste oil (for frying)"],"steps":["Boil the carrot and broccoli florets until tender-crisp, let them cool, and chop very finely.","Peel the onion, chop finely, and sauté in a little heated oil until translucent.","Rinse and pat dry the fish fillets, then finely mince them.","Combine the minced fish with the vegetables, onion, half of the breadcrumbs, and one egg, season with salt and pepper, and mix thoroughly.","Shape the mixture into small, flat patties, dredge in flour, dip into the second beaten egg, coat in the remaining breadcrumbs, and fry in oil until golden brown.","Cook the rice until fluffy and serve with the hot fish patties."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_z_ry%C5%BCem_i_warzywami","page":"Książka kucharska/Ryba z ryżem i warzywami"},{"id":"oc-plwb-14342","title":"Ryba zapiekana z ziemniakami (fish baked with potatoes)","cuisine":"European","category":"Main","ingredients":["600 g fish fillets","500 g potatoes","500 ml milk","1 onion","2 tbsp margarine","1 tbsp parsley (chopped)","to taste salt"],"steps":["Rinse and pat dry the fish fillets, then season them with salt.","Peel the potatoes and cut them into slices; peel and finely chop the onion.","Grease a baking dish with margarine, lay the fish fillets on the bottom, and arrange the potato slices and chopped onion on top.","Season everything with salt and pour in the milk.","Bake for about 60 minutes in an oven preheated to 150 °C, and sprinkle with chopped parsley before serving."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_zapiekana_z_ziemniakami","page":"Książka kucharska/Ryba zapiekana z ziemniakami"},{"id":"oc-plwb-18665","title":"Rydze panierowane (breaded saffron milk caps)","cuisine":"European","category":"Snack","ingredients":["700 g saffron milk caps","1 tbsp plain flour","2 eggs","125 ml breadcrumbs (sifted)","100 g lard","2 tbsp dill (chopped)","to taste salt","to taste black pepper"],"steps":["Clean the saffron milk caps, cut off the stems, gently rinse the caps under running water, dry thoroughly, and dust with plain flour.","Beat the eggs with a fork in a shallow bowl and season with salt.","Dip the mushroom caps into the beaten egg, then dredge them in the sifted breadcrumbs.","Fry the breaded mushrooms on both sides in well-heated lard until golden brown.","Before serving, dust the piping-hot saffron milk caps with freshly ground pepper and sprinkle with chopped dill."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rydze_panierowane","page":"Książka kucharska/Rydze panierowane"},{"id":"oc-plws-580476","title":"Rydze zapiekane z ryżem (baked saffron milk cap mushrooms with rice and cheese)","cuisine":"European","category":"Main","ingredients":["200 g rice","to taste water (for cooking the rice until fluffy)","1 tbsp butter (for the mushrooms, plus a little extra for the rice and onion)","1 kg saffron milk cap mushrooms (rydze) (fresh, dry-cleaned)","1 onion (sliced into strips)","to taste firm cheese (sharp, coarsely grated)"],"steps":["Briefly sauté the rice in a little butter, pour in the water, and cook until fluffy for about 15 minutes.","Dry-clean the saffron milk cap mushrooms and fry them until golden brown in 1 tablespoon of butter for about 10 minutes.","Slice the onion into strips and fry separately in butter until golden.","Preheat the oven to 180 °C, toss the rice, mushrooms, and onion together in an ovenproof dish, sprinkle the top generously with coarsely grated cheese, and bake for 15 minutes."],"time":55,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Rydze_z_ry%C5%BCem","page":"100 postnych i jarskich dań/Rydze z ryżem"},{"id":"oc-plwb-23477","title":"Ryż po myśliwsku (hunter's style baked rice with chicken and mushrooms)","cuisine":"European","category":"Main","ingredients":["2 chicken breast fillets","200 g rice","1 onion (large)","250 g button mushrooms","to taste parsley (chopped)","1 firm cheese (handful, grated)","1 vegetable stock cube","250 ml sour cream","to taste butter (for frying, 2 tbsp for the rice, for greasing the dish, and shavings for topping)","to taste salt","to taste hunter's seasoning blend"],"steps":["Peel the large onion, finely chop it, and cook in heated butter until translucent without browning.","Clean the button mushrooms, slice them, add to the onion, and cook gently covered over low heat until tender.","Dice the chicken fillets, sprinkle with salt, coat in the hunter's seasoning blend, and brown in butter.","Cook the rice in broth prepared from the vegetable stock cube, drain well, and toss with 2 tablespoons of butter.","Combine the rice with the browned chicken and gently stewed mushrooms and onion, then transfer everything to a greased baking dish.","Mix the sour cream with the grated firm cheese and chopped parsley, pour over the casserole, and dot the top with cold butter shavings.","Bake in a well-preheated oven at 180 °C for about 60 minutes."],"time":85,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ry%C5%BC_po_my%C5%9Bliwsku","page":"Książka kucharska/Ryż po myśliwsku"},{"id":"oc-plws-45277","title":"Saffron milk caps braised in butter (rydze duszone w maśle)","cuisine":"European","category":"Side","ingredients":["1 kg fresh saffron milk cap mushrooms (orig. half a garniec (2 Polish kwarty))","200 g butter (orig. 1/2 Polish funt)","100 g finely chopped onion, parsley root, and celeriac (orig. 2 handfuls total)","40 g breadcrumbs (orig. 1 handful)","to taste black pepper","to taste salt"],"steps":["Clean the fresh saffron milk caps, rinse several times in cold water, and drain.","Melt the butter in a saucepan, add the mushrooms, salt immediately, and place over low heat.","Once the mushrooms release their juices, add the finely chopped onion, parsley root, and celeriac, cover, and cook gently over low heat for about 30 minutes, shaking the pan often, until the liquid evaporates and only the mushrooms and clear butter remain.","Dust the mushrooms with pepper and breadcrumbs, toss, heat briefly, and serve hot."],"time":55,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Rydze_w_ma%C5%9Ble","page":"365 obiadów za 5 złotych/Rydze w maśle"},{"id":"oc-plws-39045","title":"Sago dessert with whipped cream and preserves (sago z bitą śmietaną)","cuisine":"European","category":"Dessert","ingredients":["6 g white sago pearls (orig. 1/2 łut (approx. 6 g; possibly a source misprint for 1/2 Polish funt = 200 g))","1 l milk (to cook the sago)","1 l double cream (orig. 1 Polish kwarta)","200 g sugar (orig. 1/2 Polish funt)","to taste vanilla","3 tbsp fruit preserves (for decoration)"],"steps":["Drop the white sago into plenty of boiling milk and simmer over low heat for about 15–20 minutes until tender, then drain excess milk through a sieve and let cool.","Whip the well-chilled double cream with sugar and vanilla into stiff, airy peaks.","Gradually fold the cooled sago spoonful by spoonful into the whipped cream until combined.","Transfer the mixture to a serving platter and garnish with fruit preserves."],"time":40,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sago_z_bit%C4%85_%C5%9Bmietan%C4%85","page":"365 obiadów za 5 złotych/Sago z bitą śmietaną"},{"id":"oc-plwb-16456","title":"Sakiewki z rybą i ryżem (cabbage bundles with smoked fish and rice)","cuisine":"European","category":"Snack","ingredients":["12 cabbage leaves","125 ml rice","2 spring onions","200 g smoked fish","1 carrot (large)","3 vinegar pickles","150 g mayonnaise","to taste salt","to taste black pepper"],"steps":["Peel the carrot, cut into long ribbons, parboil for 2 minutes in salted boiling water, and drain.","Blanch the cabbage leaves briefly in boiling water, remove, drain, and let cool.","Boil the rice until tender, drain well, and let cool completely.","Dice the vinegar pickles, divide the smoked fish into small pieces, and finely chop the spring onions.","Mix the cooled rice with the smoked fish, cucumbers, spring onions, and mayonnaise, and season the filling with salt and pepper.","Spoon portions of filling onto the cabbage leaves, gather the edges into little pouches, secure with toothpicks, and tie with the carrot ribbons."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sakiewki_z_ryb%C4%85_i_ry%C5%BCem","page":"Książka kucharska/Sakiewki z rybą i ryżem"},{"id":"oc-plws-1081075","title":"Salted Caraway Breadsticks (Paluszki słone)","cuisine":"European","category":"Snack","ingredients":["500 ml wheat flour (orig. half a kwarta flour (approx. 325 g))","100 g butter (orig. a quarter funt fresh butter (for the yeast-free shortcrust version, half a funt = 200 g butter and 1 egg))","12.5 g fresh yeast (orig. 1 łut)","2 tbsp milk (for dissolving the yeast)","1 tsp salt (half a teaspoon for the dough and half a teaspoon for sprinkling)","1 tsp sugar","0.5 tsp caraway seeds (well cleaned)","1 egg (beaten with a splash of water, for brushing)"],"steps":["Knead together 500 ml of wheat flour, 100 g of fresh butter, 12.5 g of yeast dissolved in 2 tablespoons of milk, half a teaspoon of salt, 1 teaspoon of sugar, and half a teaspoon of caraway seeds.","Once the dough starts to rise, work it in the bowl until it pulls away from your hands, and let it rise slightly again.","Divide the dough on a pastry board into equal pieces and roll between your palms into thin breadsticks 10 cm long (in the second method, knead a yeast-free shortcrust dough from 500 ml of flour, 200 g of butter, 1 egg, half a teaspoon of salt, 1 teaspoon of sugar, and half a teaspoon of caraway seeds and roll into sticks right away).","Arrange the sticks on a baking sheet, brush with egg beaten with water, sprinkle with salt, and bake in a hot oven (200 °C) for at most 10 minutes until golden."],"time":70,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Paluszki_s%C5%82one","page":"Baby, placki i mazurki/Paluszki słone"},{"id":"oc-plws-543013","title":"Sauerkraut with mushrooms and sour cream","cuisine":"European","category":"Side","ingredients":["1.5 l sauerkraut (orig. 1½ kwarty; volume of sauerkraut; historical measure, converted approximately)","15 ml butter (orig. 1 tbsp)","250 ml sour cream (orig. 1 szklanka; amount from the ingredient list; historical measure, converted approximately)","6 dried porcini mushrooms (6–7 pieces)","15 ml wheat flour (orig. 1 tbsp)","to taste salt","to taste black pepper"],"steps":["Boil the porcini mushrooms in water until tender, reserving the broth.","Shred the cooked mushrooms.","Scald the sauerkraut with boiling water.","Drain the sauerkraut.","Pour the mushroom broth over the sauerkraut.","Add the shredded porcini.","Season with salt and pepper.","Simmer the sauerkraut with the mushrooms.","Add the sour cream.","Brown the flour in the butter.","Stir the roux into the sauerkraut.","Cook gently, covered, until tender."],"time":null,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kapusta_kwa%C5%9Bna_z_grzybami_i_%C5%9Bmietan%C4%85","page":"Kucharka litewska (1913)/Kapusta kwaśna z grzybami i śmietaną"},{"id":"oc-plws-542846","title":"Savoy cabbage cooked gently with roux","cuisine":"European","category":"Side","ingredients":["3 savoy cabbage (heads; orig. 3–4 heads; lower bound used)","125 ml bouillon (orig. ½ szklanka; composition of the bouillon is not specified)","30 ml butter (orig. 1–2 tbsp; upper bound used, for cooking the cabbage and for the roux)","15 ml wheat flour (orig. 1 tbsp)","to taste salt (for the water)","to taste water (for parboiling and rinsing the cabbage)"],"steps":["Remove the outer leaves of the cabbage.","Cut the heads into quarters.","Rinse the cabbage.","Parboil the cabbage in boiling salted water.","Drain the cabbage.","Rinse it with cold water and squeeze it out.","Pack the cabbage tightly in a saucepan.","Add the bouillon and half of the butter.","Cook until tender and most of the liquid has evaporated.","Fry the flour in the remaining butter until pale golden.","Add the roux to the cabbage.","Cook gently, covered, a little longer until the sauce thickens."],"time":null,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kapusta_zielona_sawojka%2C_czyli_w%C5%82oska","page":"Kucharka litewska (1913)/Kapusta zielona sawojka, czyli włoska"},{"id":"oc-plwb-14553","title":"Sałata zielona w kremie szynkowym (lettuce in creamy ham sauce)","cuisine":"European","category":"Side","ingredients":["2 green lettuce (heads)","50 g ham","125 ml whipping cream","20 g plain flour","20 g butter","to taste lemon juice","to taste salt"],"steps":["Trim and rinse the heads of lettuce, place them in a pot of salted water, and simmer for about 10 minutes, then drain, reserving the cooking liquid, and keep warm.","Melt the butter in a pan, stir in the flour to make a roux, and gradually whisk in the reserved lettuce cooking broth until a smooth, light sauce forms.","Season the sauce with lemon juice and salt, stir in the finely chopped ham, and gently fold in the whipped cream.","Arrange the warm lettuce on a serving platter, pour the sauce over while leaving the green leaf tips exposed, and serve the remaining sauce in a gravy boat."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82ata_zielona_w_kremie_szynkowym","page":"Książka kucharska/Sałata zielona w kremie szynkowym"},{"id":"oc-plwb-18680","title":"Sałatka grzybowa (pickled mushroom and potato salad)","cuisine":"European","category":"Salad","ingredients":["500 ml fermented mushrooms","2 onions","2 potatoes (boiled)","1 apple (tart)","3 tbsp oil (part for sautéing, remainder for the salad)","6 clove garlic","to taste salt","to taste black pepper"],"steps":["Soak the fermented mushrooms in cold water for several hours, changing the water a few times, then drain well and slice into strips.","Peel the tart apple and grate it coarsely on a box grater.","Peel the onions and dice them along with the boiled potatoes, then sauté briefly in part of the oil and allow to cool.","Peel the garlic cloves and press them through a garlic press.","Combine all the ingredients in a bowl, drizzle with the remaining oil, season with salt and pepper, mix thoroughly, and chill before serving."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_grzybowa","page":"Książka kucharska/Sałatka grzybowa"},{"id":"oc-plwb-23609","title":"Sałatka gyros (Polish layered chicken gyros salad)","cuisine":"European","category":"Salad","ingredients":["750 g chicken breast (500–1000 g)","1 canned sweetcorn (can, drained)","1 canned chickpeas (can, drained, optional)","3 vinegar pickles or fermented brine pickles (or 1 fresh cucumber)","2 tomatoes (2–3 pieces, optional)","200 g napa cabbage","1 tsp gyros seasoning blend","1 tbsp mayonnaise","to taste ketchup (a few tablespoons)","to taste olive oil (optional)","to taste salt","to taste black pepper"],"steps":["Dice the chicken breast, coat in gyros seasoning blend, fry in a skillet for 10–15 minutes, and let cool.","Shred the napa cabbage, dice the cucumbers, and slice or dice the tomatoes.","Spread the cooled chicken pieces across the bottom of a salad bowl and spread over a few tablespoons of ketchup.","Arrange the next layers: diced cucumbers, drained sweetcorn, and optionally the drained chickpeas.","Spread a layer of mayonnaise over the top, arrange the tomatoes, and cover everything with the shredded napa cabbage.","Season the top with salt and pepper and optionally drizzle with olive oil."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_gyros","page":"Książka kucharska/Sałatka gyros"},{"id":"oc-plwb-23614","title":"Sałatka kebabowa (kebab-spiced meat salad with garlic sauce)","cuisine":"European","category":"Salad","ingredients":["350 g pork or chicken breast","to taste oil (for frying)","1 tsp sweet paprika","1 tsp hot chilli pepper powder","4 tbsp oil or olive oil","2 tbsp herbes de Provence","1 lettuce","3 tomatoes (medium)","1 fresh cucumber (small)","2 onions (large)","190 ml mayonnaise (approx.)","190 ml plain yogurt (approx.)","1 pinch salt","to taste black pepper","to taste garlic (pressed through a garlic press)"],"steps":["Mix together the sweet paprika, hot chilli powder, herbes de Provence, and 4 tablespoons of oil or olive oil.","Cut the meat into thin strips, coat thoroughly in the prepared marinade, and refrigerate for 30 minutes.","Fry the marinated meat over high heat in the hot oil until cooked through.","Tear the lettuce leaves into pieces, cut the tomatoes into wedges, slice the cucumber and onions thinly, and combine the vegetables in a bowl.","Whisk the mayonnaise with the plain yogurt, stir in the pressed garlic, and season the sauce with salt and pepper.","Toss the chopped vegetables with the garlic sauce and three-quarters of the cooked meat, then scatter the remaining meat over the top."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_kebabowa","page":"Książka kucharska/Sałatka kebabowa"},{"id":"oc-plwb-15270","title":"Sałatka letnia (summer feta and sweetcorn salad)","cuisine":"European","category":"Salad","ingredients":["200 g feta cheese","1 canned sweetcorn (can, drained)","2 tomatoes","5 vinegar pickles","1 red bell pepper","2 apples","to taste mayonnaise","to taste salt","to taste black pepper","to taste fresh herbs (for garnish)"],"steps":["Wash the tomatoes and cut them into slices.","Peel and core the apples, then dice the apples, vinegar pickles, red bell pepper and feta cheese.","Add the drained sweetcorn, mayonnaise, salt, and pepper, and gently toss all the ingredients together.","Garnish the top of the salad with tomato slices and fresh herbs."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_letnia","page":"Książka kucharska/Sałatka letnia"},{"id":"oc-plwb-16473","title":"Sałatka pieczarkowa (marinated mushroom salad)","cuisine":"European","category":"Salad","ingredients":["500 g button mushrooms","1 green lettuce","4 tbsp vinegar","to taste salt","to taste caraway","2 tbsp oil","to taste sugar","to taste lemon juice","to taste white pepper","to taste parsley (chopped)"],"steps":["Clean, rinse, and thinly slice the button mushrooms, then cook them gently covered in a skillet with a splash of water, salt, caraway, and lemon juice.","Whisk the vinegar with the oil, sugar, white pepper, and finely chopped parsley.","Arrange the washed green lettuce leaves on a platter, top with the cooled mushrooms, drizzle with the prepared marinade, and chill in the refrigerator for 30 minutes."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_pieczarkowa","page":"Książka kucharska/Sałatka pieczarkowa"},{"id":"oc-plwb-10436","title":"Sałatka pikantna (spiced fruit salad)","cuisine":"European","category":"Salad","ingredients":["2 peaches (large)","2 pears (medium)","1 apple","100 g red gooseberries","1 lemon (juiced)","125 ml white wine","1 pinch ground ginger","1 pinch ground nutmeg","1 pinch icing sugar"],"steps":["Peel the peaches, pears, and apple, remove the pits and cores, cut the fruit into large dice, and sprinkle with freshly squeezed lemon juice.","Wash the red gooseberries and slice them in half lengthwise.","Mix all the fruit in a bowl, add a pinch each of ground ginger, nutmeg, and icing sugar, and pour in the white wine.","Set the salad aside for 60 minutes for the flavours to meld, then serve as an accompaniment to roast meat."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_pikantna","page":"Książka kucharska/Sałatka pikantna"},{"id":"oc-plwb-7889","title":"Sałatka serowa (cheese salad)","cuisine":"European","category":"Salad","ingredients":["300 g firm cheese (2 thick slices, 150 g each, of different varieties, such as Emmental and Gouda)","2 eggs (hard-boiled)","2 red onion","2 vinegar pickles","2 tbsp fresh herbs (heaped, chopped)","125 ml mayonnaise","125 ml sour cream (thick)","to taste salt","to taste black pepper","to taste lettuce leaves (for lining the bowl and garnishing)"],"steps":["Cut both types of cheese into thin strips, dice the vinegar pickles, and cut the red onion into thin slivers.","Chop the hard-boiled eggs.","Mix the mayonnaise with the thick sour cream, combine with the chopped ingredients and fresh herbs, season with salt and pepper, and toss gently.","Line a shallow salad bowl with part of the lettuce leaves, spread the prepared mixture over them, and chill in the refrigerator for 15 minutes.","Before serving, sprinkle the top with thin strips shredded from the remaining lettuce leaves."],"time":20,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_serowa","page":"Książka kucharska/Sałatka serowa"},{"id":"oc-plwb-19354","title":"Sałatka szegedyńska (Szeged-style potato and pickle salad)","cuisine":"European","category":"Salad","ingredients":["300 g potatoes","2 half-sour pickles","1 red bell pepper","2 tomatoes (medium)","0.5 lettuce","2 eggs","4 tbsp olive oil","to taste vinegar","to taste salt","to taste black pepper"],"steps":["Boil the potatoes in their skins until tender, allow to cool, and peel them; hard-boil and peel the eggs.","Remove the core and seeds from the red bell pepper and cut the flesh into strips.","Slice the potatoes, half-sour pickles, hard-boiled eggs, and tomatoes, and tear the lettuce leaves into bite-sized pieces.","Combine all ingredients in a salad bowl, drizzle with olive oil, season with salt, pepper, and vinegar, and gently toss."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_szegedy%C5%84ska","page":"Książka kucharska/Sałatka szegedyńska"},{"id":"oc-plwb-18662","title":"Sałatka szparagowa (asparagus salad with parsley dressing)","cuisine":"European","category":"Salad","ingredients":["500 g asparagus","to taste vinegar","to taste salt","to taste oil","1 tsp sugar","1 bunch parsley"],"steps":["Trim the asparagus, tie the spears into a bunch with kitchen twine, and cook standing upright in a tall pot of boiling water.","Drain the cooked asparagus, remove the twine, and cut the stalks into smaller pieces.","Finely chop the parsley and mix it with the vinegar diluted with a splash of water, sugar, salt, and oil.","Pour the prepared dressing over the asparagus and place the salad in the refrigerator to chill."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_szparagowa","page":"Książka kucharska/Sałatka szparagowa"},{"id":"oc-plwb-7888","title":"Sałatka wielkanocna (Easter salad)","cuisine":"European","category":"Salad","ingredients":["6 eggs (hard-boiled)","1 tbsp horseradish (freshly grated)","1 lemon (juiced)","250 ml sour cream","2 apples (tart)","1 onion","2 potatoes (boiled in their skins)","4 quail eggs (hard-boiled, for garnish)","to taste garden cress (sprigs for garnish)","to taste salt","to taste sugar","to taste white pepper (freshly ground)"],"steps":["Grate the horseradish on a fine grater, immediately pour over the freshly squeezed lemon juice, and mix thoroughly.","Peel the boiled eggs and potatoes; peel and core the apples.","Cut the eggs, potatoes, and apples into uniform dice, and finely chop the onion.","Combine the diced ingredients with the horseradish in lemon juice.","Season the sour cream with salt, sugar, and white pepper, pour over the salad, and toss together.","Cover the dish tightly with aluminum foil and chill in a cool place for 60 minutes.","Before serving, garnish the top with sprigs of garden cress and halved hard-boiled quail eggs."],"time":30,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_wielkanocna","page":"Książka kucharska/Sałatka wielkanocna"},{"id":"oc-plwb-10326","title":"Sałatka winogronowo-porzeczkowa (grape and currant salad)","cuisine":"European","category":"Salad","ingredients":["1 green lettuce (head)","150 g Solan cheese or feta","250 g grapes","2 tbsp currants (stemmed)","1 tbsp parsley (chopped)","to taste vinaigrette","to taste salt"],"steps":["Wash and dry the lettuce leaves, then cut them into narrow strips.","Cut the cheese into batons.","Halve the grapes and remove the seeds, then rinse and dry the currants.","Combine all the prepared ingredients in a bowl, season lightly with salt, sprinkle with parsley, and drizzle with the vinaigrette.","Toss the salad gently and serve immediately."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_winogronowo-porzeczkowa","page":"Książka kucharska/Sałatka winogronowo-porzeczkowa"},{"id":"oc-plwb-17189","title":"Sałatka wiosenna (spring vegetable and egg salad)","cuisine":"European","category":"Salad","ingredients":["1 green lettuce (head)","2 fresh cucumbers","1 bunch radishes","3 eggs","1 canned green peas (can, drained)","125 ml mayonnaise","125 ml sour cream","to taste salt","to taste black pepper"],"steps":["Wash and dry the lettuce leaves, then tear them into bite-sized pieces.","Wash the radishes, peel the fresh cucumbers, and slice both vegetables thinly.","Hard-boil the eggs, let them cool, peel, and chop.","Transfer all the vegetables to a bowl, add the drained canned peas and chopped eggs.","Whisk the mayonnaise with the sour cream, pour the dressing over the ingredients, season with salt and pepper, and gently toss."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_wiosenna","page":"Książka kucharska/Sałatka wiosenna"},{"id":"oc-plwb-15958","title":"Sałatka z ananasem i orzechami (chicken, pineapple, and walnut salad)","cuisine":"European","category":"Salad","ingredients":["1 canned sweetcorn (can, drained)","1 canned pineapple (can, drained)","3 eggs","1 chicken breast fillet","1 walnuts (handful)","1 pickled celeriac (small jar, drained)","to taste mayonnaise","to taste salt","to taste black pepper"],"steps":["Soak the walnuts briefly, drain well, and roughly chop them.","Boil the chicken breast fillet until tender, let cool, dice, and transfer to a bowl with the walnuts.","Drain the canned pineapple, pickled celeriac, and sweetcorn, chop the pineapple into chunks, and add to the bowl.","Hard-boil the eggs, let them cool, peel, and chop into pieces.","Combine all ingredients with the mayonnaise, season with salt and pepper, and toss gently."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_ananasem_i_orzechami","page":"Książka kucharska/Sałatka z ananasem i orzechami"},{"id":"oc-plwb-21431","title":"Sałatka świąteczna (festive sausage and potato salad)","cuisine":"European","category":"Salad","ingredients":["1 kg potatoes","2 eggs (large)","2 apples (tart)","6 vinegar pickles (5–6 pickles)","150 g kiełbasa (Polish sausage)","250 ml plain yogurt","100 g mayonnaise","1 onion (small)","to taste salt","to taste black pepper","to taste hot ground paprika","1 tbsp lemon juice"],"steps":["Boil the potatoes in their skins, let them cool completely, peel, and cut into slices.","Hard-boil the eggs, let them cool, peel, and finely chop.","Dice the peeled apples, vinegar pickles, small onion and kiełbasa.","Mix the plain yogurt with the mayonnaise and season the dressing with lemon juice, salt, pepper and hot paprika.","Pour the dressing over the prepared ingredients, toss gently, and chill in the refrigerator before serving."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_%C5%9Bwi%C4%85teczna","page":"Książka kucharska/Sałatka świąteczna"},{"id":"oc-plwb-7869","title":"Scalded horseradish cream sauce","cuisine":"European","category":"Sauce","ingredients":["2 horseradish roots (medium)","1 tbsp butter (heaped)","250 ml whipping cream","to taste lemon juice","to taste salt","to taste sugar"],"steps":["Grate the horseradish roots on a fine grater, place on a sieve, pour boiling water over them, and leave to drain.","Melt the butter in a saucepan, add the drained horseradish, and fry for 1 minute while stirring constantly, then remove from heat.","Pour in the whipping cream, return the saucepan to low heat, and warm gently without bringing to a boil.","Remove the sauce from heat, season to taste with lemon juice, salt, and sugar, and set aside to cool.","Wrap the cooled sauce tightly in aluminium foil and chill in the refrigerator until the next day (about 12 hours) before serving."],"time":600,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_chrzanowy_parzony","page":"Książka kucharska/Sos chrzanowy parzony"},{"id":"oc-plws-42500","title":"Scalded red cabbage salad (sałatka z czerwonej kapusty)","cuisine":"European","category":"Salad","ingredients":["1 red cabbage (good-sized head)","1.5 l boiling water (to scald the cabbage)","3 tbsp olive oil","1 tbsp sugar","2 tbsp vinegar","to taste salt"],"steps":["Shred the red cabbage very finely, place in a bowl, cover with boiling water, and let stand for about 30 minutes until the water cools.","Drain off the water, squeeze the cabbage very firmly to remove excess moisture, and transfer to a salad bowl.","Season the cabbage with salt, dress with vinegar and olive oil, add sugar, and mix thoroughly.","Set the salad aside for 60 minutes before serving to let the flavours meld."],"time":110,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sa%C5%82ata_z_kapusty_czerwon%C3%A9j","page":"365 obiadów za 5 złotych/Sałata z kapusty czerwonéj"},{"id":"oc-plws-1080962","title":"Scalded Sifted Rye Bread","cuisine":"European","category":"Bread","ingredients":["12 kg sifted rye flour (orig. 5 garnce (20 l): 2 garnce (approx. 4.8 kg) for scalding and 3 garnce (approx. 7.2 kg) for kneading the dough)","8 l water (boiling water for scalding the flour, lukewarm water for kneading the dough, and water for brushing the loaves)","3 tbsp salt (to taste)"],"steps":["On the morning of the first day, place 2/5 of the sifted rye flour (approx. 4.8 kg) into a kneading trough or large bowl and scald with boiling water, stirring into a loose, fairly thin mash.","Set the scalded mash aside in a warm place for 24 hours until well fermented.","The next day, add the remaining 3/5 of the flour (approx. 7.2 kg), add the salt, and pour in enough lukewarm water to obtain a suitably thick dough, then knead vigorously for about 60 minutes.","Leave the kneaded dough in a warm place for 8–10 hours until visibly risen.","Shape round loaves, brush their tops with water, and bake in a very hot oven (230–240 °C) for about 60 minutes.","Immediately after removing from the oven, moisten the hot loaves with water again."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Chleb_%C5%BCytni%2C_pytlowy%2C_parzony","page":"Baby, placki i mazurki/Chleb żytni, pytlowy, parzony"},{"id":"oc-plwb-19356","title":"Schnitzels stuffed with cress and farmer's cheese (Sznycle nadziewane kiełkami i twarogiem)","cuisine":"European","category":"Main","ingredients":["600 g turkey schnitzels","100 g farmer's cheese","100 g butter","1 bunch parsley","1 cress sprouts (handful)","to taste salt","to taste pepper"],"steps":["Wash and chop the parsley, snip the cress sprouts with scissors, then mix with 50 g of butter and the farmer's cheese, and season with salt and pepper.","Wash and dry the turkey schnitzels, cut a pocket into the centre of each, fill with the cheese stuffing, and secure with a toothpick.","Fry the schnitzels for 10–15 minutes on both sides in the remaining butter, seasoning with salt and pepper during frying, and serve immediately from the pan."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sznycle_nadziewane_kie%C5%82kami_i_twarogiem","page":"Książka kucharska/Sznycle nadziewane kiełkami i twarogiem"},{"id":"oc-plwb-25854","title":"Scrambled eggs with cheese","cuisine":"European","category":"Breakfast","ingredients":["4 eggs","50 g butter or lard","100 g semi-hard cheese (Gouda or mozzarella)","to taste salt","to taste black pepper","to taste marjoram"],"steps":["Coarsely grate the cheese.","Melt the butter or lard in a skillet, crack in the eggs, season with salt, black pepper, and marjoram, and stir gently.","Sprinkle the grated cheese over the eggs and cook gently covered for a moment until the cheese melts and the eggs set."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajecznica_z_serem","page":"Książka kucharska/Jajecznica z serem"},{"id":"oc-plws-499666","title":"Scrambled eggs with cheese croutons","cuisine":"European","category":"Breakfast","ingredients":["2 wheat rolls (cut into small, even cubes)","to taste butter (for drizzling the croutons and cooking the eggs)","to taste hard cheese (sharp, grated)","10 eggs (8–10 pieces)","to taste salt"],"steps":["Cut the wheat rolls with a sharp knife into small, even cubes, spread on a baking sheet, drizzle generously with melted butter, and sprinkle with grated sharp cheese.","Bake the croutons in an oven preheated to 190 °C for about 10 minutes, tossing frequently, until golden and very crisp, then keep warm.","Beat the eggs with a pinch of salt, pour into a skillet with hot melted butter, and cook over low heat for about 5 minutes, lifting the set curds from the bottom.","Scatter the hot, crisp cheese croutons over the scrambled eggs and serve immediately in the same pan."],"time":25,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_z_grzaneczkami","page":"100 potraw z jaj/Jajecznica z grzaneczkami"},{"id":"oc-plws-499655","title":"Scrambled eggs with dried mushrooms","cuisine":"European","category":"Breakfast","ingredients":["10 eggs","250 ml water (for simmering the mushrooms)","5 dried mushrooms (young)","1 tbsp butter (a generous tablespoon for the sauce, plus extra for the onion and eggs)","0.5 tbsp plain wheat flour","0.5 onion (grated)","2 tbsp sour cream","to taste salt"],"steps":["Simmer the dried mushrooms in 250 ml of water for about 20 minutes until tender; drain, reserving the broth, and cut the mushrooms into thin strips.","Sauté the grated half onion in butter for 3 minutes, add a tablespoon of butter and the wheat flour, whisk in the reserved mushroom broth, season with salt, simmer for 3 minutes, and finish with the sour cream.","Beat the eggs with a pinch of salt and scramble in hot butter over low heat for about 5 minutes.","Gently fold the mushroom strips into the scrambled eggs, spoon the hot mushroom sauce over the top, and serve immediately."],"time":45,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_z_grzybami","page":"100 potraw z jaj/Jajecznica z grzybami"},{"id":"oc-plws-499652","title":"Scrambled eggs with ham","cuisine":"European","category":"Breakfast","ingredients":["10 eggs","150 g ham (marbled with fat, cooked or raw, cut into thin strips)","to taste butter (for cooking)","to taste salt (a small pinch)"],"steps":["Cut the marbled ham into thin strips.","Crack the eggs into a bowl, season very lightly with salt, and beat (if using raw ham, stir it directly into the beaten eggs).","Melt butter in a skillet, pour in the eggs, and cook over low heat for about 4–5 minutes; if using cooked ham, fold it into the eggs as they begin to set.","Serve the hot scrambled eggs immediately once set."],"time":11,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_z_szynk%C4%85","page":"100 potraw z jaj/Jajecznica z szynką"},{"id":"oc-plws-499653","title":"Scrambled eggs with Parmesan and cream","cuisine":"European","category":"Breakfast","ingredients":["6 eggs (very fresh)","150 ml sweet cream","50 g Parmesan cheese (grated (half mixed in, half for sprinkling))","to taste salt (a tiny pinch)","to taste butter (for frying the croutons and scrambling the eggs)","to taste wheat roll (for croutons to serve alongside)"],"steps":["Slice or cube the wheat roll and fry in butter for about 3 minutes until golden brown.","Beat the eggs with the sweet cream, stir in half of the grated Parmesan, and add only a tiny pinch of salt if needed.","Heat butter in a skillet, pour in the egg mixture, and cook over low heat for about 4–5 minutes, gently lifting the setting curds from the bottom with a spoon.","Sprinkle the finished scrambled eggs with the remaining Parmesan, arrange the warm croutons around them, and serve immediately."],"time":18,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_z_parmezanem","page":"100 potraw z jaj/Jajecznica z parmezanem"},{"id":"oc-plws-499656","title":"Scrambled eggs with Polish sausage (Jajecznica z kiełbasą)","cuisine":"European","category":"Breakfast","ingredients":["10 eggs","150 g Polish sausage (kiełbasa) (regular, Kraków-style or serdelowa Polish sausage)","to taste butter (or lard for frying)","to taste salt (a small pinch)"],"steps":["Cut thin sausage into rounds, or thicker sausage into large dice.","Brown the sausage pieces on both sides in hot butter for about 4 minutes, then lift them out of the pan and keep warm.","Beat the eggs with a tiny pinch of salt, pour into the drippings left in the skillet, and cook over low heat for about 4 minutes until set.","Fold the browned sausage into the finished scrambled eggs and serve immediately."],"time":13,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_z_kie%C5%82bas%C4%85","page":"100 potraw z jaj/Jajecznica z kiełbasą"},{"id":"oc-plws-499648","title":"Scrambled eggs with smoked fatback cracklings","cuisine":"European","category":"Breakfast","ingredients":["10 eggs","150 g smoked fatback (or fatty, marbled pork belly)","to taste salt (a small pinch)"],"steps":["Trim the rind from the smoked fatback, cut it into thin slices, and render in a skillet for about 4 minutes without browning the cracklings or drying them out too much.","Lift the cracklings onto a plate with a slotted spoon and keep warm.","Beat the eggs with a minimal pinch of salt, pour into the hot rendered fat in the skillet, and cook slowly over low heat for about 3–4 minutes, lifting the set curds from the bottom.","Just before the eggs finish setting, fold the reserved cracklings back in and serve hot right from the skillet."],"time":13,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_ze_s%C5%82onin%C4%85","page":"100 potraw z jaj/Jajecznica ze słoniną"},{"id":"oc-plws-499665","title":"Scrambled eggs with young asparagus","cuisine":"European","category":"Breakfast","ingredients":["250 g asparagus (young, well-trimmed and peeled)","to taste salt (for cooking the asparagus and seasoning the eggs)","1 tsp sugar (for the asparagus cooking water)","to taste water (a small amount for cooking the asparagus)","10 eggs","to taste butter (for scrambling the eggs)"],"steps":["Cut the tips off the trimmed asparagus and dice the tender stalks into small cubes.","Simmer the diced stalks in a small amount of salted water with a teaspoon of sugar for about 8 minutes; when nearly tender, add the tips and cook for another 3 minutes until only about two tablespoons of cooking liquid remain.","Beat the eggs with a pinch of salt, pour into a skillet with hot melted butter, and cook over low heat for about 4 minutes.","As the eggs begin to set, fold in the hot asparagus along with the spoonfuls of reduced cooking liquid, stir gently, and serve immediately."],"time":25,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_ze_szparagami","page":"100 potraw z jaj/Jajecznica ze szparagami"},{"id":"oc-plwb-16445","title":"Semolina sponge cake","cuisine":"European","category":"Cake","ingredients":["90 g semolina","100 g sugar","3 eggs","1 tbsp vanilla sugar","250 ml fruit juice (any flavour)","to taste raisins","to taste whipped cream (for serving)"],"steps":["Beat the egg yolks with half the sugar and the vanilla sugar, and whip the egg whites to stiff peaks with the remaining sugar.","Gently fold the whipped whites into the yolk mixture, sprinkle in the semolina and raisins, and mix carefully.","Pour the batter into a small loaf pan and bake for 30 minutes in an oven preheated to 180 °C.","Remove the cake from the oven, pour the fruit juice evenly over the top, and return to the oven for 5 minutes.","Cool the cake completely, remove from the pan, and decorate with whipped cream before serving."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_z_manny","page":"Książka kucharska/Ciasto z manny"},{"id":"oc-plwb-14694","title":"Sernik truskawkowy (no-bake strawberry cheesecake)","cuisine":"European","category":"Cake","ingredients":["750 g farmer's cheese","200 g butter","3 egg yolks","200 g icing sugar (most for the cheese filling, a little for the puree)","350 g strawberries (about 250 ml once blended into puree, plus a few whole strawberries for decoration)","1 sponge biscuits (packet, for the base of a springform tin)","1 vanilla sugar (packet)","4 tsp gelatine (2/3 for the cheese filling, 1/3 for the strawberry mousse)"],"steps":["Pour a little cold water over the gelatine to swell, then add a splash of boiling water and heat gently while stirring until completely dissolved.","Beat the softened butter with the icing sugar and egg yolks until fluffy, add the vanilla sugar, and pour in 2/3 of the cooled gelatine.","Mince the farmer's cheese and combine thoroughly with the creamed butter mixture.","Line the base of a springform tin with sponge biscuits, spread the cheese mixture evenly over them, and chill in the refrigerator to set.","Blend the strawberries into a smooth puree (about 250 ml), stir in the remaining 1/3 of the gelatine, and sweeten with a little icing sugar to taste.","Pour the setting strawberry mousse over the cheesecake, decorate with whole strawberries, and chill again in the refrigerator."],"time":35,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sernik_truskawkowy","page":"Książka kucharska/Sernik truskawkowy"},{"id":"oc-plwb-23610","title":"Sernik z rosą (dewdrop cheesecake)","cuisine":"European","category":"Cake","ingredients":["1.5 kg farmer's cheese","125 ml vegetable oil","750 ml milk","250 ml sugar","1 cream-flavoured pudding powder (packet)","2 eggs (whole)","4 egg yolks","to taste lemon flavouring","300 g plain flour","2 tsp baking powder","2 egg yolks","1 egg (whole)","100 g margarine","6 egg whites (reserved from separated eggs)","250 ml sugar (for the meringue)"],"steps":["Knead the plain flour, baking powder, 2 egg yolks, 1 whole egg, and margarine into a smooth dough, then press it evenly into the base and sides of a baking tin.","Mince the farmer's cheese twice, then blend it with the oil, milk, sugar, pudding powder, 2 whole eggs, 4 egg yolks, and lemon flavouring.","Pour the liquid cheese mixture over the prepared crust and bake in an oven preheated to 180 °C for 50 minutes.","Whip the 6 egg whites until stiff peaks form, gradually beating in the sugar.","Spread the egg-white topping over the partially baked cheesecake and bake for another 15 minutes at 180 °C, then leave to cool until dewdrops appear on the surface."],"time":95,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sernik_z_ros%C4%85","page":"Książka kucharska/Sernik z rosą"},{"id":"oc-plws-1081081","title":"Shortcrust Cream Tartlets","cuisine":"European","category":"Cookie","ingredients":["200 g butter (originally half a funt of fresh butter, plus a little for greasing the molds)","100 g icing sugar or caster sugar (originally a quarter of a funt of fine sugar)","2 eggs (whole eggs)","300 g wheat flour (originally three-quarters of a funt)","2 egg yolks (yolks)","1 tbsp icing sugar or caster sugar","125 ml whipping cream (originally 1 półkwaterek (historical Polish measure) of rich cream)","1 pinch vanilla (pounded)"],"steps":["Cream 200 g of butter until fluffy, add 100 g of fine sugar, 2 whole eggs, and 300 g of wheat flour, and quickly knead by hand into a uniform, very tender shortcrust dough.","Shape thin rounds on a board and line the bottoms and sides of greased fluted tartlet molds (reserving part of the dough for covering the tops).","In a small saucepan, whisk 2 egg yolks with a tablespoon of sugar, the whipping cream, and the vanilla, and heat over low heat, stirring constantly, until the custard thickens, then set aside in a cool place to cool.","Place a spoonful of cooled custard into each mold, cover with a flat round of dough, and press the edges together, trimming off any excess dough.","Bake in a moderate oven (180 °C) for 20 minutes."],"time":65,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciastka_%C5%9Bmietankowe","page":"Baby, placki i mazurki/Ciastka śmietankowe"},{"id":"oc-plws-1081084","title":"Shortcrust Fruit Tartlets","cuisine":"European","category":"Cookie","ingredients":["300 g wheat flour (originally half a kwarta, or three-quarters of a funt (historical Polish measures))","200 g butter (originally half a funt)","100 g sugar (originally a quarter of a funt)","1 egg (whole (yolk for the dough, white for brushing the rims))","50 g sweet almonds (orig. 4 łut, peeled and finely ground)","200 g fruit preserves or fruit cooked down until thick (e.g. gooseberries, cherries, wild strawberries, currants, raspberries, or apples)"],"steps":["Knead a shortcrust dough from the wheat flour, cold butter, sugar, one egg yolk, and finely ground almonds.","Roll out the dough on a board and cut out round bases with a glass.","Brush the edges of each round with egg white and attach a narrow strip of the same dough all around to form a rim.","Arrange the tartlets on a baking sheet and bake in a moderate oven (180 °C) for about 15–20 minutes until golden.","After removing the tartlets from the oven, fill their centers with preserves or fruit cooked down with sugar until thick."],"time":50,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciastka_z_owocami_na_kruchem_cie%C5%9Bcie","page":"Baby, placki i mazurki/Ciastka z owocami na kruchem cieście"},{"id":"oc-plws-39074","title":"Shortcrust tartlets with whipped cream","cuisine":"European","category":"Cookie","ingredients":["150 g plain wheat flour (orig. 1 kwaterka)","1 tbsp butter (generous spoonful)","115 g sugar (orig. 1 tbsp (15 g) for the pastry and 1/4 funt (100 g) for the cream)","1 egg","1 tsp lard (for greasing the tins)","250 ml whipping cream (orig. 1 kwaterka)","to taste vanilla"],"steps":["Knead a smooth pastry from the wheat flour, butter, 15 g of sugar, and the egg, then roll it out thinly.","Lightly grease fluted metal tartlet tins with lard and line them neatly with the pastry, pressing it into the ridges.","Bake in an oven preheated to 170–180 °C for about 20 minutes, unmould the tartlet shells immediately after baking, and let cool.","Whip the cream until stiff, fold in the remaining 100 g of sugar and the vanilla, and fill the cooled tartlet shells just before serving."],"time":50,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ciastka_z_kremem","page":"365 obiadów za 5 złotych/Ciastka z kremem"},{"id":"oc-plwb-2765","title":"Siemieniotka (Silesian Christmas Eve hemp seed soup)","cuisine":"European","category":"Soup","ingredients":["300 g hemp seeds (whole)","2 l water (or half water and half milk)","1 tbsp vegetable oil (or butter)","2 onions","2 tbsp plain flour","1.5 tsp sugar","2 wheat rolls (for croutons)","to taste salt","to taste black pepper"],"steps":["Rinse the hemp seeds, pour part of the boiling water over them, and cook until the seeds start to burst, then drain through a sieve, reserving the cooking liquid.","Transfer the drained seeds to a pot, add a small splash of boiling water, and cook while mashing thoroughly until a white milk is released, adding more water little by little if necessary.","Pour the reserved liquid over the mashed hemp seeds, add the sliced onion, and simmer over low heat until gruel-like in consistency, then strain or leave the onion in.","Prepare a dark roux from the vegetable oil and flour, stir it into the soup, and season to taste with salt, pepper, and sugar.","Dice the rolls finely, toast until golden croutons form, arrange on plates, and ladle hot siemieniotka over them."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Siemieniotka","page":"Książka kucharska/Siemieniotka"},{"id":"oc-plwb-12948","title":"Silesian miner-style stuffed pork loin (Schab po sztygarsku)","cuisine":"European","category":"Main","ingredients":["1 kg boneless pork loin","1 Silesian kiełbasa (casing removed)","1 tbsp lard (for browning)","200 ml water (or broth, for basting and 150–200 ml for the sauce)","1 onion (thinly sliced)","3.5 clove garlic","1.5 tbsp plain flour","to taste caraway seeds","to taste sweet paprika","to taste salt","to taste black pepper","to taste sour cream (for the gravy)","to taste liquid seasoning (such as Maggi) (a few drops for the gravy)"],"steps":["Cut a deep pocket lengthwise through the center of the pork loin and insert the skinned Silesian kiełbasa inside.","Rub the pork with salt and pepper, then sear it on all sides in hot lard until browned.","Transfer the meat to a roasting pan, pour in water or broth, cover, and braise in an oven preheated to 180 °C for about 30 minutes.","Remove the lid, sprinkle the pork with caraway and sweet paprika, scatter the sliced onions and garlic cloves around it, and roast uncovered for another 20 minutes, adding more water if needed.","Remove the roasted meat, stir the flour into 150–200 ml of cold water until smooth, pour into the roasting pan juices, and bring to a boil, stirring constantly.","Season the thickened gravy with sour cream and a few drops of liquid seasoning, and serve with the sliced pork loin."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Schab_po_sztygarsku","page":"Książka kucharska/Schab po sztygarsku"},{"id":"oc-plws-568724","title":"Skórki pomarańczowe suszone w cukrze (Candied dried orange peels)","cuisine":"European","category":"Preserve","ingredients":["500 g thick orange peels (orig. half a kilogr.; from large oranges, weighed before boiling)","to taste light sugar syrup (enough to cover the peels; proportions not specified)","500 g sugar for second syrup (orig. half a kilogr.)","375 ml water for second syrup (orig. one and a half szklanki)","500 g sugar for thickening (orig. half a kilogr.)","to taste water for soaking and boiling (for soaking and boiling; enough to cover the peels)"],"steps":["Score the peels of large oranges into six sections, remove them gently, and weigh 500 g before boiling.","Soak the peels in cold water for 7200 minutes, changing the water daily.","Cover with fresh water and boil for about 120 minutes until the peels are completely tender.","Drain the water and cover the peels with cold water for 1440 minutes.","Drain the peels in a sieve.","Cover them with lukewarm, light syrup so they are submerged, and leave until the next day.","Pour off the first syrup and drain the peels thoroughly again.","Boil 500 g sugar with 375 ml water and pour the hot syrup over the peels.","Set aside for 1440 minutes.","Drain the peels, add the remaining 500 g sugar to the syrup, and boil without adding water until thickened.","Pour the hot syrup over the peels and leave until the fourth day.","On the fourth day, pour off and boil the syrup, add the peels, bring to a boil again, and leave to cool.","Remove the peels onto a sieve for several hours, saving the syrup.","Boil half of the reserved syrup until dipping a fork and blowing on it releases sugar threads instead of drops.","Place the peels into the syrup and stir for a few minutes; when the sugar begins to cool, remove from heat, keep stirring, then lift the peels with a fork onto a sieve or platter to dry naturally."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Pomara%C5%84czowe_sk%C3%B3rki_suszone_w_cukrze","page":"Doświadczone sekreta smażenia konfitur i soków/Pomarańczowe skórki suszone w cukrze"},{"id":"oc-plwb-19358","title":"Smalec ziołowy (Polish herbal lard spread with apple and prune)","cuisine":"European","category":"Other","ingredients":["1 kg pork fatback","2 apples (tart)","2 prunes","to taste water (boiled, for soaking the prunes)","to taste salt","1 tsp dried marjoram","1 tsp dried thyme"],"steps":["Soak the prunes in boiled water for about 15 minutes, then slice into thin strips.","Peel the tart apples and cut into thin slices.","Dice the fatback finely and render slowly in a pot, being careful not to over-brown the cracklings.","Remove the rendered lard from heat, add the apples and prunes, and season with salt, marjoram, and thyme.","Stir the mixture for about 15 minutes until the lard begins to set, then transfer to stoneware crocks or jars."],"time":75,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Smalec_zio%C5%82owy","page":"Książka kucharska/Smalec ziołowy"},{"id":"oc-plws-546696","title":"Small fish fried in batter (rybki w klarze)","cuisine":"European","category":"Main","ingredients":["500 g small freshwater fish (orig. 50 dkg)","2 tbsp plain wheat flour","1 egg (small, separated into yolk and white)","50 ml water (to dilute the batter)","60 g vegetable oil (orig. 6 dkg)","to taste salt"],"steps":["Clean the fish (for ruffe, cut off heads and gills; leave smelts whole), salt, and set aside for 60 minutes.","Thread the fish in bunches of 6–8 onto thin skewers.","Whisk the plain wheat flour with the egg yolk, water, and a pinch of salt to make a batter the consistency of sour cream, then gently fold in the egg white beaten to stiff peaks.","Dip the skewered fish into the batter and fry in well-heated vegetable oil for about 4–5 minutes per side until golden."],"time":90,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Rybki_sma%C5%BCone_w_klarze","page":"109 potraw/Rybki smażone w klarze"},{"id":"oc-plws-547967","title":"Smoked Cod in Olive Oil","cuisine":"European","category":"Other","ingredients":["400 g smoked cod (orig. 40 dkg)","100 g refined vegetable oil (orig. 10 dkg)","1 pinch ground black pepper"],"steps":["Carefully remove the skin and bones from the smoked cod and break the flesh into neat, even lengthwise pieces.","Arrange the pieces of fish in a serving dish, season with a pinch of freshly ground black pepper, and pour the oil over them.","Set aside in a cool place for 24 hours before serving so the fish absorbs the oil."],"time":600,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Dorsz_w%C4%99dzony_w_oliwie","page":"109 potraw/Dorsz wędzony w oliwie"},{"id":"oc-plwb-16890","title":"Smoked fish, potato and egg casserole (Zapiekanka z rybą wędzoną)","cuisine":"European","category":"Main","ingredients":["1.5 kg potatoes","200 g onions","1 tsp margarine (for sautéing the onion and greasing the dish)","3 eggs","300 g smoked fish","200 ml sour cream (1 tub)","10 g all-purpose flour","to taste parsley leaves (chopped)","to taste salt","to taste black pepper"],"steps":["Boil the potatoes in their skins, cool, peel, and slice into rounds.","Peel the onions, slice into half-rings, and sauté in fat.","Hard-boil the eggs, peel and slice them, and skin, debone, and flake the smoked fish into small pieces.","Grease an ovenproof baking dish with fat and arrange a layer of potatoes, then a layer of onion, fish, and eggs, and cover with the remaining potatoes on top.","Whisk the sour cream with flour, season with salt and pepper, pour over the casserole, sprinkle with chopped parsley, and bake in the oven."],"time":65,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_z_ryb%C4%85_w%C4%99dzon%C4%85","page":"Książka kucharska/Zapiekanka z rybą wędzoną"},{"id":"oc-plwb-15968","title":"Smoked mackerel salad (Sałatka z wędzonej makreli)","cuisine":"European","category":"Salad","ingredients":["1 smoked mackerel (large)","3 eggs","3 fermented pickles","3 potatoes (small)","1 onion","to taste mayonnaise","to taste black pepper","to taste fresh chives (optional, chopped)"],"steps":["Boil the potatoes in their jackets until tender, then let cool, peel, and dice.","Hard-boil the eggs, let cool, peel, and dice.","Dice the fermented pickles and finely chop the onion.","Remove the skin and bones from the smoked mackerel and flake the flesh into bite-sized pieces.","Gently toss all the ingredients with mayonnaise, season to taste with black pepper, and sprinkle with chopped chives before serving."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_w%C4%99dzonej_makreli","page":"Książka kucharska/Sałatka z wędzonej makreli"},{"id":"oc-plwb-16928","title":"Smoked turkey and farmer's cheese salad (Sałatka z indykiem)","cuisine":"European","category":"Salad","ingredients":["100 g smoked turkey breast","2 tomatoes","1 pickled cucumber in vinegar","100 g farmer's cheese","2 tbsp plain yogurt","1 tsp vegetable oil","to taste grated horseradish","to taste mustard","to taste vinegar","to taste salt","to taste black pepper"],"steps":["Mash and beat the farmer's cheese with plain yogurt, oil, horseradish, and mustard until smooth, then season to taste with vinegar, salt, and pepper.","Peel the tomatoes and vinegar pickle, then dice them into small cubes.","Dice the smoked turkey breast into bite-sized pieces, combine with the vegetables, and toss with the prepared farmer's cheese dressing."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_indykiem","page":"Książka kucharska/Sałatka z indykiem"},{"id":"oc-plwb-13911","title":"Snikers (Polish honey walnut and caramel layer cake)","cuisine":"European","category":"Cake","ingredients":["560 g plain flour","150 g sugar","2 eggs","2 egg yolks","200 g baking margarine (plus a little for greasing the pans)","3 tbsp milk","3 tbsp honey","2 tsp baking soda","1 vanilla sugar (packet)","125 g baking margarine","4 tbsp sugar","2 tbsp honey","200 g walnuts (chopped)","1 cream-flavoured custard powder (packet)","to taste milk (reduced by one third compared to the package instructions)","to taste margarine (for creaming the custard)","2 tsp instant coffee (dissolved in a little water)","1 sweetened condensed milk (can)"],"steps":["Sift the flour with the baking soda onto a pastry board, chop in 200 g of margarine, then add 150 g of sugar, eggs, egg yolks, 3 tablespoons of milk, 3 tablespoons of honey, and vanilla sugar, knead into a smooth dough, and divide into three equal parts.","Line three greased and parchment-lined 20 × 30 cm rectangular baking pans with the rolled-out dough.","Heat 125 g of margarine in a saucepan with 4 tablespoons of sugar, 2 tablespoons of honey, and chopped walnuts, pour the hot topping over one of the dough layers, and bake all three layers in the oven (about 15–20 minutes at 180 °C), then cool.","Cook the custard in one-third less milk than directed on the packet, let cool, and then beat with the margarine and 2 teaspoons of dissolved coffee.","Place the unopened can of condensed milk in a pot of water, boil for 180 minutes to make thick dulce de leche, and cool.","Spread the custard cream over the first baked cake layer, cover with the second layer spread with caramel, and top with the third layer finished with the walnut topping."],"time":305,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Snikers","page":"Książka kucharska/Snikers"},{"id":"oc-plws-499649","title":"Soft scrambled eggs with milk","cuisine":"European","category":"Breakfast","ingredients":["1 egg","1 tbsp milk (1–1.5 tbsp per egg (or sweet cream))","to taste butter (for cooking)","to taste salt"],"steps":["Crack the egg into a bowl, salt lightly, add the milk, and beat thoroughly with a spoon or whisk.","Melt the butter in a small skillet without letting it brown.","Pour the egg mixture into the skillet and cook over very low heat for about 3–4 minutes, gently pushing the setting curds with a spoon so they stay in larger pieces.","Serve immediately in the same pan as soon as the eggs are set, before they become watery."],"time":7,"servings":1,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_z_mlekiem","page":"100 potraw z jaj/Jajecznica z mlekiem"},{"id":"oc-plws-548323","title":"Solanki owsiane z kminkiem (savoury oat and potato caraway crackers)","cuisine":"European","category":"Snack","ingredients":["300 g oat flour (orig. 2 szklanki)","5 cooked potatoes (passed through a ricer)","2 tbsp vegetable oil","1 egg (small)","2 tbsp salt","1 tbsp caraway seeds","0.75 tsp baking powder (orig. 1/4 packet baking powder)"],"steps":["Sift the oat flour into a bowl and mix with the baking powder, salt, and caraway seeds.","Add the riced cooked potatoes, vegetable oil, and egg, and knead everything into a firm, cohesive dough.","Roll out the dough very thinly and stamp out rounds using a drinking glass.","Arrange the rounds on a baking sheet and bake in an oven preheated to 180 °C for about 15 minutes until lightly browned."],"time":40,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Solanki_owsiane","page":"109 potraw/Solanki owsiane"},{"id":"oc-plwb-13750","title":"Sole in sour cream and dill sauce","cuisine":"European","category":"Main","ingredients":["2 sole fillets","0.5 lemon juice (squeezed from half a lemon)","0.5 bunch fresh dill","250 ml sour cream","to taste salt"],"steps":["Drizzle the sole fillets with lemon juice and set aside in a cool place for 10 minutes.","Heat a dry skillet without fat, place the fillets in it, and fry for about 4 minutes on each side.","Meanwhile, mix the sour cream with finely chopped dill and season generously with salt.","Pour the prepared sour cream and dill sauce over the fish and simmer gently for about 5 minutes more."],"time":28,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sola_w_%C5%9Bmietanie","page":"Książka kucharska/Sola w śmietanie"},{"id":"oc-plwb-19267","title":"Sos chlebowy po lwowsku (Lviv-style bread sauce)","cuisine":"European","category":"Sauce","ingredients":["50 g dried white bread","50 g dried wholemeal bread","400 ml broth","1 tbsp butter","2 egg yolks","to taste salt","to taste black pepper","to taste lemon juice"],"steps":["Grate the dried wheat bread and wholemeal bread on a fine grater.","Sauté the grated bread in melted butter until lightly browned, then pour in the broth and simmer over low heat for 3 minutes.","Remove from heat, whisk in the egg yolks vigorously, and finally season the sauce with salt, pepper, and lemon juice."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_chlebowy_po_lwowsku","page":"Książka kucharska/Sos chlebowy po lwowsku"},{"id":"oc-plws-546705","title":"Sos chrzanowy do ryb (horseradish sauce for fish)","cuisine":"European","category":"Sauce","ingredients":["30 g plain wheat flour (orig. heaped tbsp, about 3 dkg)","1 tsp vegetable oil","500 ml fish or vegetable stock (orig. 2 cups)","1 horseradish root (freshly grated)","50 g sour cream (orig. 50 dkg — corrected typographical error to 5 dkg as in other variants)","to taste vinegar","to taste sugar","to taste salt"],"steps":["Cook the plain wheat flour in vegetable oil into a pale roux, whisk in 500 ml of fish or vegetable stock, and bring to a simmer to form a smooth white sauce.","Finely grate the horseradish root, sprinkle with salt, and drizzle with vinegar.","Add the grated horseradish to the simmering sauce, bring to a boil, stir in the sour cream, and season to taste with a pinch of sugar."],"time":20,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Sosy_do_ryb","page":"109 potraw/Sosy do ryb"},{"id":"oc-plwb-7877","title":"Sos chrzanowy wykwintny (gourmet horseradish sauce)","cuisine":"European","category":"Sauce","ingredients":["4 tbsp mayonnaise (thick)","4 tbsp sour cream (creamy)","2 tbsp grated horseradish (freshly grated)","4 peaches from Polish kompot (halves, plus optionally 1 tablespoon of liquid from the kompot)","1 orange (large, seedless)","2 hard-boiled eggs (yolks only)","to taste salt","to taste white pepper","to taste icing sugar","to taste lemon juice"],"steps":["Peel the orange and thoroughly remove the membranes from the segments, then roughly chop the peach halves from the kompot.","Remove the yolks from the hard-boiled eggs, place in a food processor with the freshly grated horseradish, peaches, and orange, and blend until smooth.","Add the sour cream and mayonnaise, mix, and season to taste with salt, white pepper, icing sugar, and lemon juice. If too thick, thin with a tablespoon of liquid from the peach kompot."],"time":20,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_chrzanowy_wykwintny","page":"Książka kucharska/Sos chrzanowy wykwintny"},{"id":"oc-plws-38742","title":"Sos ogórkowy (pickled cucumber sauce)","cuisine":"European","category":"Sauce","ingredients":["1 tbsp plain wheat flour","1 tbsp butter","250 ml dried mushroom stock (for thinning the roux)","100 ml fermented cucumber brine (or boiled vinegar to taste)","3 fermented pickled cucumbers (orig. several cucumbers, diced)","2 tsp sugar (orig. a couple of pieces of sugar, browned into caramel)"],"steps":["Brown 1 tablespoon of plain wheat flour with 1 tablespoon of butter in a frying pan or small saucepan.","Thin the roux with the hot dried mushroom stock and pour in the fermented cucumber brine (or boiled vinegar if the brine is too mild).","Add the finely diced fermented pickled cucumbers and the sugar previously browned into caramel.","Bring the sauce to the boil several times and pour it over boiled beef or meatless potato or herring cutlets on a serving platter."],"time":15,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_og%C3%B3rkowy","page":"365 obiadów za 5 złotych/Sos ogórkowy"},{"id":"oc-plws-38740","title":"Sos pieczarkowy biały (white mushroom sauce)","cuisine":"European","category":"Sauce","ingredients":["6 button mushrooms (orig. 6 pieces)","0.5 lemon (half, juiced and seedless)","100 ml water (a small amount for parboiling the mushrooms)","1 tbsp clarified butter","1 tbsp plain wheat flour","200 ml clear meat broth (or light soup-vegetable stock)","125 ml white wine (orig. half a glass)"],"steps":["Clean and rinse the button mushrooms, slice them into strips, and boil until tender in a small amount of water with the juice squeezed from half a lemon so they keep their pale colour.","Heat 1 tablespoon of clarified butter in a separate small saucepan, add 1 tablespoon of plain wheat flour, and cook briefly into a pale roux without browning.","Thin the pale roux with the mushroom cooking liquid along with the mushrooms themselves and the hot meat broth or soup-vegetable stock.","Pour in the white wine, stir thoroughly, and bring everything to the boil; serve with roast poultry or cutlets."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_pieczarkowy_bia%C5%82y","page":"365 obiadów za 5 złotych/Sos pieczarkowy biały"},{"id":"oc-plws-38752","title":"Sos pomidorowy (fresh tomato sauce)","cuisine":"European","category":"Sauce","ingredients":["10 tomatoes (large, ripe)","2 tbsp butter (1 tablespoon for stewing the tomatoes and 1 tablespoon for the roux)","250 ml meat stock (rich, for moistening the tomatoes and thinning the sauce)","2 tsp sugar","1 tbsp plain wheat flour","to taste salt"],"steps":["Wash and cut up the large, ripe tomatoes, then cook them gently in butter in a saucepan, moistening with a little meat stock, until they break down completely into a pulp.","Press the cooked tomatoes through a sieve so that only the seeds remain behind, and mix the purée with 2 teaspoons of sugar.","In a separate small saucepan, cook 1 tablespoon of butter with 1 tablespoon of plain wheat flour into a pale roux.","Combine the roux with the tomato purée, season with salt to taste, and thin with the rich meat stock to a fairly thick consistency.","Bring the sauce to the boil and serve with boiled beef, mutton, duck, or goose."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_pomidorowy","page":"365 obiadów za 5 złotych/Sos pomidorowy"},{"id":"oc-plwb-7767","title":"Sos staropolski z suszonych grzybów (Old Polish dried mushroom sauce)","cuisine":"European","category":"Sauce","ingredients":["50 g dried mushrooms (preferably porcini)","1 onion (large)","2 tbsp butter","1 tbsp plain flour","750 ml water (bottled table water or water from an Oligocene aquifer)","to taste salt","to taste white pepper (finely ground)"],"steps":["Rinse the dried mushrooms, place them in a pot with 750 ml of water, add the onion cut into quarters, and simmer over low heat until the mushrooms are tender.","Strain the mushroom broth, discard the cooked onion, and finely grind the softened mushrooms in a meat grinder or mince them in a food processor.","Melt the butter in a saucepan, add the flour, and fry briefly without browning.","Whisk the strained mushroom broth into the roux, bring to a boil, add the ground mushrooms, and season to taste with salt and white pepper."],"time":35,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_staropolski_z_suszonych_grzyb%C3%B3w","page":"Książka kucharska/Sos staropolski z suszonych grzybów"},{"id":"oc-plwb-7774","title":"Sos staropolski ze świeżych grzybów (Old Polish fresh wild mushroom sauce)","cuisine":"European","category":"Sauce","ingredients":["14 fresh wild mushroom caps (porcini, scaber-stalk boletes, or bay boletes)","1 onion (large)","2 tbsp butter (heaped)","1 tbsp plain flour (heaped)","125 ml sour cream","250 ml broth (may be from concentrate)","1 tbsp fresh dill (heaped, chopped)","to taste salt","to taste black pepper"],"steps":["Clean and rinse the wild mushroom caps, chop them very finely, and finely dice the onion.","Cook the onion in melted butter until translucent, add the mushrooms, cover, and simmer gently over low heat, stirring occasionally, until most liquid evaporates.","Dust the mushrooms with the flour and cook for a moment, stirring, until the raw flour flavour is gone.","Pour in the broth, bring the sauce to a boil, and season lightly with salt and pepper.","Remove the pan from the heat. Just before serving, stir in the lightly whisked sour cream and chopped dill, and serve without reheating."],"time":30,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_staropolski_ze_%C5%9Bwie%C5%BCych_grzyb%C3%B3w","page":"Książka kucharska/Sos staropolski ze świeżych grzybów"},{"id":"oc-plws-38743","title":"Sos szary z rodzynkami (Polish grey sauce with raisins)","cuisine":"European","category":"Sauce","ingredients":["1 tbsp plain wheat flour","1 tbsp butter","250 ml meat stock (or fish stock (for carp or bream))","100 ml white wine (for thinning the sauce together with the stock)","2 tsp sugar (orig. a couple of pieces, moistened with water and browned into caramel)","1 tsp water (for moistening the sugar)","1 raisins (a handful of large raisins)","1 tbsp vinegar (boiled)","1 lemon (cut into slices)"],"steps":["Cook 1 tablespoon of plain wheat flour with 1 tablespoon of butter in a small saucepan into a roux, thin with the meat stock (or fish stock) and white wine, and bring to the boil.","Moisten the sugar with a little water and brown it in a small pan into a dark caramel, then pour it into the sauce.","Add the thoroughly rinsed large raisins and 1 tablespoon of boiled vinegar, and simmer together for a few minutes.","Just before serving, add the sliced lemon to the sauce; serve with boiled tongue, calf's feet, or fish (carp, bream)."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_szary_z_rodzenkami","page":"365 obiadów za 5 złotych/Sos szary z rodzenkami"},{"id":"oc-plws-38745","title":"Sos szczypiorkowy (chive sauce)","cuisine":"European","category":"Sauce","ingredients":["1 tbsp plain wheat flour","1 tbsp butter","250 ml clear meat broth (for thinning the roux)","1 tbsp vinegar (strong)","1 chives (a handful, finely chopped)"],"steps":["Cook 1 tablespoon of plain wheat flour with 1 tablespoon of butter in a small saucepan into a roux and thin with the hot meat broth.","Pour in 1 tablespoon of strong vinegar and stir in a handful of finely chopped fresh chives.","Boil the sauce vigorously for a moment and serve hot with boiled beef."],"time":15,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_szczypiorkowy","page":"365 obiadów za 5 złotych/Sos szczypiorkowy"},{"id":"oc-plwb-7884","title":"Sos tatarski delikatny (mild tartar sauce)","cuisine":"European","category":"Sauce","ingredients":["250 ml mayonnaise (thick)","125 ml sour cream","1 tbsp pickled mushrooms (chopped, measured in a heaped spoonful)","1 vinegar pickle","1 onion (medium)","1 tbsp mild Polish mustard (musztarda delikatesowa)","to taste icing sugar","to taste lemon juice","to taste salt","to taste pepper","1 tsp vinegar from the pickled mushrooms","1 hot pickled pepper"],"steps":["Finely chop the onion, scald with boiling water in a sieve, refresh with cold water, and set aside to drain.","Finely chop the vinegar pickle and the hot pickled pepper.","Combine the mayonnaise with the sour cream and fold in the onion, pickle, pepper, and pickled mushrooms.","Season the sauce with mustard, salt, icing sugar, pepper, lemon juice, and mushroom marinade vinegar, and serve within an hour of preparation."],"time":15,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_tatarski_delikatny","page":"Książka kucharska/Sos tatarski delikatny"},{"id":"oc-plws-39054","title":"Sos tatarski zimny do święconego lub do śniadania zimnego (cold egg-yolk tartar sauce)","cuisine":"European","category":"Sauce","ingredients":["10 eggs (hard-boiled (only the yolks are used in the sauce))","1 tbsp caster sugar (a generous spoonful (optional))","4 tbsp olive oil","3 tsp English mustard","2 tbsp vinegar (strong, enough to give a fairly thick consistency)","to taste chives (finely chopped (or capers))"],"steps":["Hard-boil the 10 eggs, cool, peel, and remove the yolks.","Mash the yolks in a bowl into a completely smooth paste, add a generous tablespoon of caster sugar (optional), and gradually work in the 4 tablespoons of olive oil.","Stir in the 3 teaspoons of English mustard and gradually add the strong vinegar a little at a time until the sauce reaches a smooth, fairly thick consistency.","Add the finely chopped chives or capers, mix well, and serve cold with cured meats, cold roasts, or eggs."],"time":25,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_tatarski_zimny_do_%C5%9Bwi%C4%99conego_lub_do_%C5%9Bniadania_zimnego","page":"365 obiadów za 5 złotych/Sos tatarski zimny do święconego lub do śniadania zimnego"},{"id":"oc-plws-38755","title":"Sos z soków do budyniu (fruit juice sauce for puddings)","cuisine":"European","category":"Sauce","ingredients":["250 ml fruit juice (orig. 1 szklanka of any fruit juice)","125 ml red wine (orig. half a szklanka)","250 ml water (orig. 1 szklanka)","1 tbsp potato starch (orig. 1 tablespoon of potato starch)","2 tbsp sugar (orig. a couple of tablespoons)"],"steps":["Thoroughly mix 1 tablespoon of potato starch with 250 ml of cold water to make a smooth slurry.","Pour the mixture into a small saucepan, add the fruit juice, red wine, and sugar, and stir well.","Heat over low heat, stirring constantly, until the sauce comes to the boil and thickens; serve with steamed pudding or other warm sweet dishes."],"time":10,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_z_sok%C3%B3w_do_budyniu","page":"365 obiadów za 5 złotych/Sos z soków do budyniu"},{"id":"oc-plws-38753","title":"Sos śmietankowy (vanilla cream sauce)","cuisine":"European","category":"Sauce","ingredients":["530 ml whipping cream (orig. half a Polish quart (500 ml) for boiling and 2 tablespoons (30 ml) of cold cream for beating the yolks)","2 tbsp sugar","0.5 vanilla pod (a piece of pod, crushed and tied in muslin or cheesecloth)","4 egg yolks"],"steps":["Bring 500 ml of whipping cream to the boil in a small saucepan with 2 tablespoons of sugar and the crushed piece of vanilla pod tied in cheesecloth, then set aside to cool.","Whisk 4 egg yolks with 2 tablespoons of cold whipping cream.","Remove the vanilla from the cooled cream and combine the cream with the whisked egg yolks.","Heat the sauce over very low heat, stirring constantly, until it thickens (taking care not to let it boil); once cooled, serve with cold sweet puddings."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_%C5%9Bmietankowy","page":"365 obiadów za 5 złotych/Sos śmietankowy"},{"id":"oc-plws-547340","title":"Sour cherries pickled in vinegar","cuisine":"European","category":"Preserve","ingredients":["2 l sour cherries (orig. 2 litres of dark sour cherries or red Łutówka sour cherries (about 1.4 kg), stemmed)","500 g sugar (orig. half a kilogram of sugar per 2 litres of cherries)","250 ml vinegar (orig. a quarter litre of good vinegar per 2 litres of cherries)","15 cloves (orig. a dozen or so cloves, added on the third day)","2 g cinnamon (a piece of bark, added on the third day)"],"steps":["Stem 2 l of dark sour cherries or red Łutówka sour cherries and put them in an earthenware jar or a porcelain bowl.","Bring 250 ml of good vinegar to the boil with 500 g of sugar, cool it, and pour it over the cherries until the next day.","On the second day, pour off the vinegar liquor, boil it, and pour the warm syrup over the cherries.","On the third day, pour off the syrup again, add a dozen or so cloves and a little cinnamon, bring it to the boil, and pour it boiling over the fruit.","On the fourth day, pour off the syrup, bring it to the boil, add the cherries, and bring it to the boil once. Once cool, pack the fruit into jars so it is completely covered by the syrup, seal, and store in a dry, cool place."],"time":30,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_wisie%C5%84_w_occie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z wisień w occie"},{"id":"oc-plws-546285","title":"Sour cherries preserved in spirit","cuisine":"European","category":"Preserve","ingredients":["1 kg sour cherries (łutówki) (orig. 1 kilogram of ripe, freshly picked sour cherries, stems trimmed to half their length)","4 g cinnamon (orig. about 2 small pieces of cinnamon bark)","0.5 tsp coriander seed (a few seeds)","250 g sugar (orig. a quarter kilogram of sugar per 1 kilogram of cherries)","250 ml spirit (orig. 1/3 part of the best spirit to 2/3 parts of boiled water)","750 ml water (500 ml of boiled water to dilute the spirit (2/3 of the volume) and about 250 ml for the thick syrup (plus boiling water for blanching the cherries))"],"steps":["Trim the stems of 1 kg of freshly picked, ripe Łutówka sour cherries to half their length, scald the fruit with boiling water, and leave it for 5 minutes on a warm metal tray to dry.","Prick each cherry with a wooden pin and pack them in a jar with 2 small pieces of cinnamon and a little coriander.","Cook a thick syrup from 250 g of sugar and 250 ml of water and pour it hot over the cherries in the jar until the next day.","The next day, add diluted spirit made from 250 ml of the best spirit (1/3 part) and 500 ml of boiled water (2/3 parts). Tie a cover securely over the jar and leave it in the sun for 4 weeks. Discard the spices before serving."],"time":20,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_wisie%C5%84_w_spirytusie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z wisień w spirytusie"},{"id":"oc-plws-554220","title":"Sour Cherry Syrup","cuisine":"European","category":"Drink","ingredients":["4 l sour cherries (Ripe, rinsed, and pitted; orig. four liters.)","1 l water (orig. a liter.)","1 kg sugar (Amount per 1 l of obtained juice, not for the whole batch; orig. one kilogram.)"],"steps":["Drop the sour cherries into 1 l of boiling water.","Bring the sour cherries to a strong boil several times.","Pour the contents of the pot into a loosely woven linen bag.","Tie the bag tightly and, as the juice drains, retie it progressively lower.","Strain the juice through muslin or a fine strainer.","Set the juice aside for about 120 minutes for the sediment to settle.","Measure the clear juice.","Pour the juice over crushed sugar, keeping a ratio of 1 kg of sugar per 1 l of juice.","Leave the mixture until the sugar dissolves.","Bring the syrup to a boil, skimming the foam carefully and simmering over low heat toward the end.","Leave the syrup to cool.","Pour the syrup into bottles.","Seal the bottles and store in a dry, cool place."],"time":120,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Sok_wi%C5%9Bniowy","page":"Doświadczone sekreta smażenia konfitur i soków/Sok wiśniowy"},{"id":"oc-plws-1080984","title":"Sour Cherry Yeast Flatbread Cake (Placki z wiśniami)","cuisine":"European","category":"Cake","ingredients":["500 g yeast dough (or puff pastry, for a very thin base)","800 g sour cherries (szklanki sour cherries, pitted)","150 g powdered sugar (part for macerating the cherries 1 hour before baking, part for generously dusting the hot cake)"],"steps":["Pit the sour cherries, toss them with fine sugar, and let stand for 60 minutes to release their juice.","Stretch a very thin layer of yeast dough (or puff pastry) onto a baking sheet and leave to rise.","Pour off the juice released by the cherries, arrange the fruit densely over the risen dough, and place immediately into a hot oven with stronger bottom heat (200 °C, about 20–25 minutes).","As soon as you remove the cake from the oven, dust the hot top generously with sugar."],"time":115,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Placki_z_wi%C5%9Bniami","page":"Baby, placki i mazurki/Placki z wiśniami"},{"id":"oc-plws-543012","title":"Sour white cabbage with apples","cuisine":"European","category":"Side","ingredients":["2 white cabbage (heads; orig. 2 heads)","500 ml bouillon (orig. a couple of szklanki; taken as 2 szklanki; historical measure, converted approximately)","15 ml wheat flour (orig. 1 tbsp)","45 ml rendered pork fat (45–60 ml, without cracklings; orig. 3–4 tbsp)","5 sour apples (5–7 pieces, depending on tartness)","to taste salt","to taste black pepper"],"steps":["Shred the cabbage.","Scald the cabbage with boiling water.","Squeeze out the cabbage.","Transfer the cabbage to a saucepan.","Pour the hot bouillon over the cabbage.","Add the salt, pepper, and part of the fat.","Peel the apples.","Cut up the apples.","Add the apples to the cabbage.","Cook the cabbage and apples gently, covered, until tender.","Brown the flour in the remaining fat.","Stir the roux into the cabbage.","Cook off the excess liquid."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kapusta_bia%C5%82a_na_kwa%C5%9Bno_z_jab%C5%82kami","page":"Kucharka litewska (1913)/Kapusta biała na kwaśno z jabłkami"},{"id":"oc-plwb-17472","title":"Spiced marinated herring","cuisine":"European","category":"Snack","ingredients":["1 kg herrings","1 lemon (juice and scalded zest)","5 whole cloves","8 allspice berries (berries)","3 bay leaves","4 juniper berries (berries)","3 tsp mustard seeds","6 tbsp vegetable oil","2 onions","2 tsp sugar","to taste salt (for seasoning the onion before serving)"],"steps":["Rinse the herrings, cut into 3–4 cm pieces, and layer in a large jar.","Crush the cloves, allspice, bay leaves, and juniper berries, mix with the mustard seeds and sugar, and slice one of the onions into rings.","Sprinkle each layer of herring with the spice mixture, layer with onion rings, drizzle with lemon juice and vegetable oil, and top with strips of scalded lemon zest.","Close the jar and chill in a cool place for 2–3 days (at least 48 hours).","An hour before serving, remove the herrings from the marinade, discard spices, arrange the fish on a platter, garnish with the second onion diced and salted, then chill before serving."],"time":600,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%9Aledzie_w_marynacie_korzennej","page":"Książka kucharska/Śledzie w marynacie korzennej"},{"id":"oc-plws-547342","title":"Spiced pickled melon in vinegar syrup","cuisine":"European","category":"Preserve","ingredients":["500 g melon (orig. half a kilogram of ripe but firm melon, peeled and cut into pieces)","500 ml vinegar (cold, good vinegar for cooking the melon)","750 g sugar (orig. 500 g on the first day, 125 g (half a quarter kilogram) on the second day, and about 125 g on the third)","250 ml water (orig. 1 szklanka of water for the syrup)","6 cloves (added on the third day)","2 g cinnamon (a piece of bark, added on the third day)"],"steps":["Peel a ripe but not overripe melon, cut it into neat pieces, put them in a wide pan, cover with cold good vinegar, and cook covered until soft. Then pour off the vinegar.","For every 500 g of melon, cook a syrup from 500 g of sugar and 250 ml of water, and cover the pieces with the lukewarm syrup until the next day.","On the second day, pour off the syrup, add 125 g of finely crushed sugar, bring it to the boil, and pour it hot over the melon.","On the third day, pour off the syrup again, add the remaining 125 g of sugar, the cloves and the cinnamon, bring it to the boil, pour the hot syrup over the melon, and leave it to cool.","On the fourth day, pack the melon and syrup into jars (if after a few days the syrup is too thin, pour it off once more, boil it, and pour it back once cool) and store them in a dry, cool place."],"time":45,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_melona_w_occie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z melona w occie"},{"id":"oc-plws-547341","title":"Spiced pickled pears in vinegar syrup","cuisine":"European","category":"Preserve","ingredients":["1 kg pears (bergamot, bonkreta or muscatel pears, peeled and cored)","500 ml vinegar (orig. half a litre of good vinegar per 1 kg of pears)","1.5 kg sugar (orig. one and a half kilograms of sugar per 1 kg of pears)","6 cloves (orig. about six cloves)","2 g cinnamon (a piece of bark)"],"steps":["Peel the pears, remove the cores, halve the larger fruit and leave the smaller ones whole.","Bring 500 ml of good vinegar to the boil with 1.5 kg of sugar, 6 cloves and a piece of cinnamon. Add the pears and cook over low heat for about 60 minutes, until soft.","Lift the soft pears with a slotted spoon onto a sieve to drain well, and once cool pack them into jars.","Boil the remaining syrup a few more times so it thickens, skim it carefully, cool it, and pour it over the pears in the jars.","After a few days, pour the syrup off the pears, boil it a couple of times, and pour it back over the fruit once cool. After another 2 days, do this one last time. Once cool, seal the jars and store them in a dry, cool place."],"time":90,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_gruszek_w_occie","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z gruszek w occie"},{"id":"oc-plwb-7885","title":"Spicy tartar sauce (Sos tatarski pikantny)","cuisine":"European","category":"Sauce","ingredients":["250 ml mayonnaise","125 ml sour cream (thick)","2 pickled peppers","1 tart apple (large)","1 tsp mild mustard","1 pinch cayenne pepper","to taste salt","to taste white pepper","to taste icing sugar","2 tbsp fresh herbs (measured in heaped spoonfuls, such as parsley, dill, chives and cress)"],"steps":["Very finely chop the pickled peppers, peeled apple, and fresh herbs.","Combine the mayonnaise with the sour cream, add the chopped ingredients, and mix.","Season the sauce with mild mustard, cayenne pepper, salt, white pepper, and icing sugar.","Cover the dish tightly with aluminium foil and chill in a cool place for 60 minutes before serving."],"time":70,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_tatarski_pikantny","page":"Książka kucharska/Sos tatarski pikantny"},{"id":"oc-plws-1081039","title":"Sponge torte with lemon and almond cream","cuisine":"European","category":"Cake","ingredients":["2 sponge layers (baked in round tins)","2 lemons","400 g sugar (orig. 1 funt)","400 g almonds (orig. 1 funt blanched and pounded)","100 g punch icing (orig. punch icing)","50 g jam for decorating"],"steps":["Boil the whole lemons in water until soft, chop them, remove every seed, and cook them for 15 minutes over low heat in a thick syrup made with part of the sugar.","Grind or pound the blanched, peeled almonds finely.","Mix the lemons with the almonds and the rest of the sugar, and beat the mixture in a bowl or mixer to a smooth paste.","While the lemon-almond cream is still warm, spread it between the baked, cooled sponge layers.","Cover the assembled torte with punch icing and decorate it with whatever jam you like."],"time":90,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Tort_biszkoptowy","page":"Baby, placki i mazurki/Tort biszkoptowy"},{"id":"oc-plwb-7762","title":"Spring sauce (Sos wiosenny)","cuisine":"European","category":"Sauce","ingredients":["250 ml mayonnaise","125 ml sour cream (thick)","2 tbsp plain yogurt","1 tbsp pickled mushrooms (chopped, e.g. button mushrooms)","6 tbsp fresh herbs (chopped, measured in heaped spoonfuls)","2 tbsp radishes (grated, measured in heaped spoonfuls)","to taste salt","to taste pepper"],"steps":["Combine the mayonnaise, thick sour cream, and plain yogurt in a bowl.","Add the chopped pickled mushrooms, grated radishes, and chopped fresh herbs.","Mix the sauce thoroughly, season to taste with salt and pepper, and serve immediately after preparing."],"time":10,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_wiosenny","page":"Książka kucharska/Sos wiosenny"},{"id":"oc-plwb-13765","title":"Staropolska zupa cebulowa (Old Polish onion soup)","cuisine":"European","category":"Soup","ingredients":["100 g wholemeal bread (crusts removed)","250 g onions","2 tbsp butter","3 egg yolks","125 ml sour cream","to taste salt"],"steps":["Dice the crustless wholemeal bread, arrange it in an ovenproof dish with half the butter, and bake until browned and dried.","Peel and chop the onions, then cook them gently, covered, in the remaining butter.","Add the browned wholemeal bread to the onions, pour in 1.5 litres of boiled water, and simmer gently for about 30 minutes.","Pass the soup through a sieve, bring it back to a boil, stir in the egg yolks mixed with sour cream, and season to taste with salt."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Staropolska_zupa_cebulowa","page":"Książka kucharska/Staropolska zupa cebulowa"},{"id":"oc-plws-39708","title":"Steamed bread pudding with raisins and almonds","cuisine":"European","category":"Dessert","ingredients":["6 eggs (yolks and whites separated)","60 g butter (orig. 3 tbsp + a little for greasing the mould)","200 g sugar (orig. 1 kubek)","300 g white wheat breadcrumbs (orig. half a kwarta or 3 kubki, sifted)","550 ml whole milk (orig. generous half a kwarta)","40 g dried currants (orig. 1 handful)","40 g sultana raisins (orig. 1 handful)","30 g sweet almonds (orig. a little, blanched and chopped)","6 bitter almonds (pounded to a paste)","1 pinch salt"],"steps":["Cream the egg yolks with the butter in a large bowl or mortar, gradually adding the sugar until pale and fluffy.","Stir in the sifted breadcrumbs and pour in the milk slowly, stirring constantly to prevent lumps.","Add the rinsed and dried currants and sultanas, chopped sweet almonds, pounded bitter almonds, and a pinch of salt; mix and let stand for about 20 minutes so the breadcrumbs swell.","Just before filling the mould, whip the egg whites to stiff peaks and fold them gently into the batter.","Spoon the mixture into a buttered and breadcrumb-dusted tube pudding mould, seal tightly, and set in a wide pot with boiling water reaching about 4 cm up the sides.","Boil briskly under a lid for at least 75 minutes, topping up with boiling water as needed. Remove the mould and turn the pudding out onto a platter."],"time":120,"servings":7,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Budy%C5%84_z_bu%C5%82ki","page":"365 obiadów za 5 złotych/Budyń z bułki"},{"id":"oc-plws-547943","title":"Steamed Millet Pudding","cuisine":"European","category":"Main","ingredients":["200 g millet groats (orig. 1 cup)","1 l water (boiling water for scalding the groats twice)","500 ml milk (orig. 1/2 liter for cooking the groats (plus an optional 500 ml for serving))","2 eggs (whole, yolks and whites separated)","40 g pork fatback (orig. 4 dkg, plus a little fat for the mold)","1 tsp sugar","to taste salt (to taste)","1 tbsp fresh dill (optional, chopped)"],"steps":["Rinse the millet groats thoroughly and scald them twice with boiling water to remove any bitterness.","Pour the groats into the boiling milk, cook over low heat until they begin to thicken, then place the covered pot into a preheated oven (160 °C) for 30 minutes and let cool.","Pour the rendered pork fatback into the cooled millet, beat in two egg yolks one at a time, and season with a teaspoon of sugar, salt to taste, and chopped dill.","Gently fold in the stiffly whipped egg whites, transfer the mixture to a greased and tightly sealed pudding mold, and steam in a water bath for 90 minutes from the moment the water returns to a boil."],"time":160,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Budy%C5%84_z_kaszy_jaglanej","page":"109 potraw/Budyń z kaszy jaglanej"},{"id":"oc-plws-546700","title":"Steamed Minced Fish Pudding","cuisine":"European","category":"Main","ingredients":["800 g small freshwater fish (orig. 80 dkg, raw or cooked from broth)","2 tbsp wheat flour","200 g potatoes (orig. 20 dkg, boiled and peeled)","2 eggs (large, yolks and whites separated)","2 onion (large)","60 g vegetable oil (orig. 6 dkg: for the onion, roux, and greasing the mold)","150 ml water or fish stock (for thinning the roux)","to taste salt","to taste ground white or black pepper","1 pinch nutmeg (grated)","1 tbsp fresh or dried dill","2 tbsp breadcrumbs (for coating the mold)"],"steps":["Braise the chopped onions in a teaspoon of oil, then pass the cleaned small fish (raw or cooked) through a meat grinder together with the onions and boiled potatoes.","Make a roux from the flour and the remaining oil, thin it with water or stock to the consistency of a thick sauce, and combine with the minced fish mixture.","Beat two egg yolks into the mixture, work thoroughly, season with salt, pepper, grated nutmeg, and chopped dill, and finally fold in the stiffly whipped egg whites.","Transfer the mixture into a pudding mold greased with oil and coated with breadcrumbs, then cover tightly with a lid.","Place the mold into a pot of boiling water and steam in the water bath for 75 minutes from the moment the water returns to a boil, then unmold onto a platter."],"time":125,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Budy%C5%84_z_drobnych_rybek","page":"109 potraw/Budyń z drobnych rybek"},{"id":"oc-plws-546736","title":"Steamed White Cabbage Pudding","cuisine":"European","category":"Main","ingredients":["1.5 kg white cabbage (orig. 1.5 kg of sweet cabbage)","40 g lard (orig. 4 dkg, plus a little for greasing the mold)","4 tbsp wheat flour","500 ml cabbage cooking liquid (orig. 2 cups of the water in which the cabbage was boiled)","2 eggs (whole, yolks and whites separated)","to taste salt","to taste ground black pepper","3 tbsp breadcrumbs (for generously coating the mold)"],"steps":["Boil the whole head of white cabbage in salted water or vegetable stock, reserving 500 ml of the cooking liquid, then cut out the core and finely shred the cabbage.","Make a roux from the lard and wheat flour, thin it with 500 ml of the cabbage cooking liquid, and mix with the shredded cabbage.","Beat the mixture with two egg yolks, season with salt and pepper, and finally fold in the stiffly whipped egg whites.","Transfer the mixture to a pudding mold greased with fat and generously coated with breadcrumbs, cover tightly with a lid, and steam in a pot of boiling water for 75 minutes."],"time":125,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Budy%C5%84_z_kapusty","page":"109 potraw/Budyń z kapusty"},{"id":"oc-plws-40187","title":"Steamed yeast dumpling cake (pyza drożdżowa na parze)","cuisine":"European","category":"Dessert","ingredients":["600 g plain wheat flour (orig. 1 Polish kwarta)","250 ml milk (orig. 1 kwaterka)","4 eggs","12.5 g fresh yeast (orig. 1 łut)","50 g butter (2 tbsp for dough + for mould and drizzling)","2 tbsp sugar (plus for sprinkling)"],"steps":["Combine part of the plain wheat flour with lukewarm milk mixed with yeast to make a starter and set aside in a warm place for about 30 minutes to rise.","Once the starter has risen, add the remaining plain wheat flour, eggs, 2 tbsp of butter, and sugar, kneading vigorously in a bowl until smooth and elastic.","Transfer the dough into a buttered mould (or shape into round buns, dip each in melted butter, and arrange closely together filling the pan halfway) and let rise for about 40 minutes.","Cover the mould tightly with a lid, place in a larger pot with boiling water reaching a depth of about 5 cm, and steam for 60 minutes, replenishing boiling water as needed.","Turn the steamed dumpling cake out onto a platter, drizzle with melted butter, and dust with sugar."],"time":150,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pyza","page":"365 obiadów za 5 złotych/Pyza"},{"id":"oc-plws-42476","title":"Stewed Gooseberry Compote (Kompot z agrestu)","cuisine":"European","category":"Dessert","ingredients":["1 l gooseberries (orig. 1 kwarta of half-ripe gooseberries (approximately 600 g))","220 g sugar (orig. more than half a funt)","250 ml water (orig. 1 kwaterka for the syrup, plus boiling water for scalding the gooseberries)"],"steps":["Top and tail the half-ripe gooseberries, place them in a sieve or colander, scald several times with boiling water, and drain thoroughly.","Boil 250 ml of water with the sugar in a small saucepan to make a clear syrup.","Drop the drained gooseberries into the boiling syrup, bring to a boil several times over low heat until the fruit softens without bursting, and transfer to a serving bowl."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Komput_z_agrestu","page":"365 obiadów za 5 złotych/Komput z agrestu"},{"id":"oc-plws-42473","title":"Stewed Prune Compote (Kompot z suszonych śliwek)","cuisine":"European","category":"Dessert","ingredients":["200 g prunes (orig. half a funt of French prunes or dried white Greek plums)","100 g sugar (orig. a quarter funt)","1 cinnamon stick (a piece of bark)","to taste lemon peel (a piece)","300 ml water (enough to cover the prunes (plus lukewarm water for rinsing))"],"steps":["Rinse the prunes in lukewarm water, transfer to a saucepan, and pour in enough fresh water to cover the fruit.","Add the sugar, a piece of cinnamon bark, and the lemon peel, and simmer over low heat until the prunes are completely tender.","Transfer the tender prunes to a serving bowl, strain the cooking syrup through a sieve, and pour it over the fruit."],"time":30,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Komput_z_suszonych_%C5%9Bliwek","page":"365 obiadów za 5 złotych/Komput z suszonych śliwek"},{"id":"oc-plwb-17673","title":"Strawberries with rice and yogurt (Truskawki z ryżem i jogurtem)","cuisine":"European","category":"Dessert","ingredients":["5 strawberries","100 g cooked rice","100 g plain yogurt","to taste cane sugar (optional)","to taste maple syrup (optional)"],"steps":["Wash and hull the strawberries, then arrange them in the bottom of a bowl.","Cover the fruit with a layer of cooked rice and spoon over the plain yogurt.","Optionally sprinkle the top with cane sugar and drizzle with maple syrup."],"time":5,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Truskawki_z_ry%C5%BCem_i_jogurtem","page":"Książka kucharska/Truskawki z ryżem i jogurtem"},{"id":"oc-plwb-28294","title":"Strawberry crumble traybake (Truskawkowe ciasto z kruszonką)","cuisine":"European","category":"Cake","ingredients":["500 g plain flour","2 tsp baking powder","190 g margarine (soft)","200 g sugar","16 g vanilla sugar","2 eggs (whole)","2 egg yolks","3 tbsp sour cream","500 g strawberries","to taste icing sugar (for dusting)","30 g plain flour","2.5 tbsp sugar","1 tsp vanilla sugar","30 g butter"],"steps":["Rub the plain flour, sugar, vanilla sugar, and butter together into a crumble, then place it in the refrigerator.","Mix the flour for the dough with the baking powder, cut in the soft margarine, add the whole eggs, egg yolks, sugar, vanilla sugar, and sour cream, knead into a uniform dough, and chill in the refrigerator for 30 minutes.","Roll out the chilled dough, line a large baking tray lined with baking paper, and blind-bake until lightly golden for about 30 minutes at 180 °C.","Remove the pre-baked base from the oven, let cool slightly, arrange the washed, hulled, and halved strawberries on top, and scatter with the chilled crumble.","Bake the cake for another 15 minutes at 180 °C until golden, and once cool, dust with icing sugar."],"time":100,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Truskawkowe_ciasto_z_kruszonk%C4%85","page":"Książka kucharska/Truskawkowe ciasto z kruszonką"},{"id":"oc-plwb-19647","title":"Strawberry jam","cuisine":"European","category":"Preserve","ingredients":["1 kg strawberries","500 g sugar","to taste jam sugar (gelling sugar) (amount according to package instructions)"],"steps":["Hull and sort the ripe strawberries, rinse thoroughly under cold running water, and drain well.","Transfer the strawberries to a wide pot, cover with the sugar, and set aside for a few hours until the sugar begins to dissolve.","Simmer the strawberries over low heat for about 60 minutes, stirring frequently.","Add the jam sugar and heat for another 10 minutes, stirring constantly, then transfer the hot jam to clean jars and seal tightly."],"time":100,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/D%C5%BCem_truskawkowy","page":"Książka kucharska/Dżem truskawkowy"},{"id":"oc-plws-474266","title":"Strawberry Jam","cuisine":"European","category":"Preserve","ingredients":["1 kg strawberries (Leave half whole and crush the other half; orig. a kilo of the total prepared fruit.)","1 kg sugar (orig. a kilo of sugar)","to taste water (Minimal amount to dissolve the sugar; plus 15 ml for each benzoin tablet; orig. in a tablespoon of boiled water.)","1 benzoin tablets (Ratio per kilogram of finished jam, not the number of tablets for the whole batch; orig. one benzoin tablet per kilo of jam.)"],"steps":["Leave half of the strawberries whole.","Crush the remaining strawberries with a wooden spoon.","Dissolve the sugar over heat in a minimal amount of water, taking care not to scorch it.","Add the whole and crushed fruit.","Boil over high heat, stirring frequently, until the mixture becomes translucent.","Dissolve a benzoin tablet for each kilogram of finished jam in 15 ml of boiled water per tablet.","Stir the dissolved benzoin into the jam.","Transfer the hot jam into thoroughly warmed jars."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Konfitury%2C_kompoty_i_inne_konserwy_owocowe/Jam_truskawkowy","page":"Konfitury, kompoty i inne konserwy owocowe/Jam truskawkowy"},{"id":"oc-plws-548820","title":"Strawberry Jelly","cuisine":"European","category":"Preserve","ingredients":["2 l strawberries (ripe, preferably pineapple variety, hulled)","1 l white currants (stemmed)","1.5 kg fine sugar (fine)"],"steps":["Hull the strawberries and stem the white currants, place them in a stoneware pan, and cover with the fine sugar on top.","Set the pan over high heat and bring to a boil without stirring with a spoon.","Bring the mixture to a boil three times, removing the pan from the heat and thoroughly skimming off the foam each time.","On the fourth boil, pour the contents of the pan onto a fine sieve set over a bowl.","Pour the strained hot juice immediately into jars, leave to set, and tie tightly."],"time":50,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_truskawkowa","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta truskawkowa"},{"id":"oc-plws-1080967","title":"Strucle parzone (scalded sweet yeast loaves)","cuisine":"European","category":"Cake","ingredients":["4 l wheat flour (orig. half a kwarta for scalding, plus 3.5 kwarty to add)","1 l milk (orig. 3 kwaterki for scalding and 1 kwaterka for the yeast)","150 g fresh yeast (orig. 12 łutów)","30 egg yolks (orig. half a kopa)","400 g clarified butter (orig. 1 funt)","400 g sugar (orig. 1 funt)","5 g salt (orig. 1 łyżeczka)","100 g raisins (orig. a quarter funt)","50 g almonds (orig. 4 łuty blanched and cut into strips)","1 egg for glazing","50 g coarse sugar and almonds for sprinkling"],"steps":["Scald half a litre of flour with three kwaterki of boiling milk, beat it smooth with no lumps, and cool it.","Dissolve the yeast in a kwaterka of warm milk, mix it into the scalded flour, and leave it in a warm place until the starter has risen.","Beat the yolks with the sugar and salt, pour them into the risen starter, add the clarified butter and the rest of the sifted flour, and knead hard until the dough comes cleanly away from your hands.","Mix in the raisins and slivered almonds, divide the dough into portions and shape into long loaves, pressing a groove lengthwise down the centre with a rolling pin.","Set them on a baking sheet to rise, brush with beaten egg, sprinkle with coarse sugar and almonds, and bake at 180 °C for 45 minutes. Slide them onto a wooden board as soon as they are done."],"time":225,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Strucle_parzone","page":"Baby, placki i mazurki/Strucle parzone"},{"id":"oc-plws-547979","title":"Strucle postne drożdżowe (Lenten yeast loaves)","cuisine":"European","category":"Bread","ingredients":["2 kg plain wheat flour (orig. 2 kg total)","60 g fresh yeast (orig. 6 dkg)","750 ml lukewarm water (orig. 3 cups)","1 tsp salt (heaped)","190 ml vegetable oil (orig. 3/4 cup)","2 tbsp honey (orig. 2 tbsp honey and 25 saccharin tablets)","to taste almond flavouring (orig. 5–6 drops)","to taste poppy seeds or nigella seeds (for sprinkling on top)"],"steps":["Mix about 450 g of plain wheat flour with 750 ml of lukewarm water, the dissolved fresh yeast, and salt, beat vigorously, and leave in a warm place for about 45 minutes until the sponge rises and cracks on the surface.","Pour the vegetable oil, honey, and almond flavouring into the risen sponge, add the remaining plain wheat flour, and knead well until the dense dough no longer sticks to your hands.","Set the dough aside to rise again, then divide into 6 portions, shape into oblong loaves, and place on flour-dusted baking sheets.","Let the loaves rise a third time, brush the tops with water mixed with a little honey, and sprinkle with poppy seeds or nigella seeds.","Bake in an oven preheated to 180 °C for about 40 minutes until the loaves feel light and release easily from the sheet."],"time":190,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Strucle_postne","page":"109 potraw/Strucle postne"},{"id":"oc-plws-580466","title":"Strudel z serem (Polish quark cheese strudel)","cuisine":"European","category":"Cake","ingredients":["3 eggs (1 for the dough and 2 for the cheese filling)","250 ml water (1 szklanka)","2 tsp salt (1 tsp for the dough and 1 tsp for the cheese filling)","to taste plain wheat flour (approximately 350–400 g, as needed to form the dough, plus extra for dusting the tablecloth)","600 g farmer's cheese (well pressed, mild)","125 ml sour cream (half a szklanka)","1 tbsp sugar","to taste butter (melted, for sprinkling the dough and greasing the baking dish)"],"steps":["Knead a supple, medium-soft dough from 1 egg, the water, 1 teaspoon of salt, and the wheat flour, then beat it against the board for 10 minutes, cover with a warm bowl, and let rest for 60 minutes.","Roll out the dough, transfer it to a tablecloth dusted with wheat flour, stretch it carefully with your fingers from the centre outwards until paper-thin, and let dry slightly for 30 minutes.","Beat the farmer's cheese with the remaining 2 eggs, sour cream, 1 teaspoon of salt, and sugar until smooth.","Sprinkle the stretched dough with melted butter, spread the cheese filling thinly over it, and roll it up into a long log with the aid of the tablecloth.","Preheat the oven to 220 °C, butter a shallow baking dish, coil the strudel carefully into a spiral, and drizzle the top with melted butter.","Bake the strudel in the oven preheated to 220 °C for 60 minutes until golden brown."],"time":180,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Strudel_z_serem","page":"100 postnych i jarskich dań/Strudel z serem"},{"id":"oc-plwb-13612","title":"Stuffed baked potatoes (Ziemniaki faszerowane)","cuisine":"European","category":"Main","ingredients":["8 potatoes (for hollowing out)","2 carrots (for the filling)","1 parsley root (root, for the filling)","1 celeriac (small celeriac, for the filling)","1 onion (for the filling)","50 g firm cheese (grated)","200 ml kefir (half a tub)","to taste parsley leaves (chopped, for garnishing)","1 tsp butter (for braising vegetables)","to taste salt","to taste black pepper"],"steps":["Peel the potatoes and hollow out their centers.","Peel the carrots, parsley root, and celeriac and grate them on a coarse grater, then peel and finely chop the onion.","Melt the butter in a pan, add the prepared vegetables, season with salt and pepper, and cook gently covered until tender.","Fill the potatoes with the prepared stuffing and arrange them in a baking dish.","Mix the kefir with the grated firm cheese, pour over the potatoes, and bake in the oven.","Before serving hot, sprinkle the dish with chopped parsley leaves."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ziemniaki_faszerowane","page":"Książka kucharska/Ziemniaki faszerowane"},{"id":"oc-plws-546726","title":"Stuffed Baked Rutabaga","cuisine":"European","category":"Main","ingredients":["800 g rutabaga (orig. 2 medium rutabagas weighing approx. 80 dkg)","30 g pork fatback (orig. 3 dkg)","2 onion (whole)","2 potatoes (whole, boiled)","to taste salt","1 pinch ground black pepper"],"steps":["Wash the unpeeled rutabagas thoroughly and boil them whole until tender in water or vegetable stock, and boil the potatoes separately.","Cut the cooked rutabagas in half and scoop out the flesh, leaving walls about 1 cm thick.","Finely chop the onion and braise it in a skillet with the diced pork fatback.","Chop or mash the scooped-out rutabaga flesh, combine it with the braised onion and pork fatback as well as the grated boiled potatoes, and season with salt and pepper.","Heap the filling into the hollowed rutabaga halves and bake in a hot oven (190 °C) for about 15–20 minutes until browned on top."],"time":85,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Brukiew_nadziewana","page":"109 potraw/Brukiew nadziewana"},{"id":"oc-plws-44949","title":"Stuffed fried herrings (śledzie smażone nadziewane)","cuisine":"European","category":"Main","ingredients":["4 salted herrings with milt","1 onion (very finely chopped)","1 tbsp butter (for stuffing)","80 g breadcrumbs (orig. 1 handful (40 g) for stuffing + 40 g for breading)","2 eggs (1 whole for stuffing and 1 whole for breading)","2 tbsp clarified butter (for frying)","to taste black pepper"],"steps":["Soak the herrings in cold water for at least 36 hours (2160 minutes), then drain and pat dry thoroughly with paper towels.","Without skinning, clean the herrings through the belly cavity, extract the milt, and mince it very finely together with the onion.","Combine the minced milt and onion with 1 tbsp of butter, half the breadcrumbs, 1 egg, and pepper into a uniform stuffing, and fill the herring bellies.","Dip the stuffed herrings in the second beaten egg, dredge in remaining breadcrumbs, and fry in hot clarified butter for about 5–6 minutes per side until golden brown."],"time":600,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/%C5%9Aledzie_sma%C5%BCone_nadziewane","page":"365 obiadów za 5 złotych/Śledzie smażone nadziewane"},{"id":"oc-plws-547974","title":"Stynki marynowane w occie (pickled fried smelt)","cuisine":"European","category":"Preserve","ingredients":["500 g European smelt (orig. 50 dkg, larger fish)","1 tbsp plain wheat flour","2 tbsp vegetable oil","250 ml mild vinegar (orig. 1 szklanka)","1 bay leaf","to taste black peppercorns","to taste salt"],"steps":["Clean, gut, rinse, dry, salt, and dredge the larger smelt in plain wheat flour.","Fry the fish in hot vegetable oil for about 8–10 minutes, cool completely, and arrange in a bowl or jar.","Bring the vinegar to a boil with the peppercorns and bay leaf, then let cool until lukewarm.","Pour the lukewarm vinegar marinade over the smelt and leave in a cool place overnight (about 8 hours). Serve the next day."],"time":515,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Stynki_marynowane","page":"109 potraw/Stynki marynowane"},{"id":"oc-plws-1081069","title":"Sucharki papieskie (papal rusks)","cuisine":"European","category":"Cookie","ingredients":["7 eggs (about 420 g, weighed in the shell)","420 g sugar (the weight of 7 eggs)","360 g wheat flour (the weight of 6 eggs)","5 g lemon zest (or pounded anise)","15 ml olive oil for the baking sheet"],"steps":["Beat the whole eggs with the sugar in a bowl until the mixture is pale and fluffy.","Fold the sifted flour and the grated lemon zest (or pounded anise) into the beaten mixture with a spoon.","Pour the batter onto a baking sheet greased with olive oil and bake in an oven preheated to 180 °C for about 25 minutes, until nicely browned.","Take the cake out and let it cool.","Slice the cooled cake thinly with a sharp knife, lay the slices on a sheet, and dry them in a very slow oven heated to 120 °C for about 20 minutes."],"time":75,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Sucharki_papieskie","page":"Baby, placki i mazurki/Sucharki papieskie"},{"id":"oc-plws-42448","title":"Suflet z ryżu (baked rice soufflé)","cuisine":"European","category":"Dessert","ingredients":["200 g rice (orig. half a funt)","500 ml whole milk (orig. half a kwarta of whole milk)","1 tbsp butter (fresh)","100 g sugar (for cooking the rice, plus coarse sugar for sprinkling on top)","5 bitter almonds (blanched and pounded)","8 eggs (orig. 8 yolks and the stiffly beaten whites of 8 eggs)","30 g sweet almonds (slivered or sliced, for sprinkling on top)","to taste whole-fruit preserves (for garnishing after baking)"],"steps":["Cook the rice in 500 ml of whole milk with the tablespoon of butter and the sugar over low heat until completely soft, taking care that it does not catch on the bottom.","Let the cooked rice cool slightly, then mash it in a mortar-style mixing bowl with the 5 blanched, peeled, finely pounded bitter almonds.","Beat the 8 egg yolks into the rice mixture and mix thoroughly.","Beat the 8 egg whites to stiff peaks, gently fold them into the rice mixture with a spoon, and immediately transfer to an ovenproof serving platter.","Sprinkle the top with coarse sugar and sliced almonds, and place in an oven preheated to 170 °C.","Bake until the soufflé rises and turns golden brown, then garnish with whole-fruit preserves and serve immediately."],"time":75,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Suflet_z_ry%C5%BCu","page":"365 obiadów za 5 złotych/Suflet z ryżu"},{"id":"oc-plws-501605","title":"Sunny-side up eggs with porcini or button mushrooms","cuisine":"European","category":"Breakfast","ingredients":["500 g porcini mushrooms (young, fresh (or 250 g button mushrooms))","2 tbsp butter (1 tbsp for frying the mushrooms and 1 tbsp for the eggs)","1 onion (large, finely chopped)","to taste salt","250 ml water","10 eggs (8–10 eggs)"],"steps":["Clean the young porcini mushrooms, slice them into thin strips, and fry in a large skillet in a tablespoon of butter with the finely chopped onion for about 12 minutes, then season with salt to taste.","Transfer the fried mushrooms and onion to a small saucepan and keep warm.","Add the second tablespoon of butter and the water to the same skillet, bring to a boil, take briefly off the heat, and carefully crack the eggs in side by side.","Set the skillet over low heat and cook gently for about 5 minutes until the whites are set while the yolks remain runny.","Scatter the reserved warm mushrooms over the finished eggs and serve immediately right from the skillet."],"time":35,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_z_grzybami_lub_pieczarkami","page":"100 potraw z jaj/Jaja z grzybami lub pieczarkami"},{"id":"oc-plwb-16933","title":"Sweet rice and fruit salad (Sałatka z ryżem i owocami)","cuisine":"European","category":"Salad","ingredients":["250 ml rice","125 ml heavy cream","2 egg yolks","50 g raisins","2 apples","150 g dried prunes","1 peaches (can, drained)","4 tbsp sugar","to taste vanilla sugar"],"steps":["Cook the rice until fluffy with grains separated, then set aside to cool.","Soak the dried prunes and raisins in warm water, then drain thoroughly and cut the prunes into thin strips.","Drain the canned peaches and dice them along with the fresh apples.","In a small saucepan, whisk the egg yolks with the sugar, pour in the heavy cream, and cook over very low heat, whisking constantly, until the sauce thickens.","Mix the cooked rice with the fresh and dried fruit, pour over the warm cream sauce, and dust with vanilla sugar."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_ry%C5%BCem_i_owocami","page":"Książka kucharska/Sałatka z ryżem i owocami"},{"id":"oc-plwb-13773","title":"Sweet roasted pork loin (Schab na słodko)","cuisine":"European","category":"Main","ingredients":["600 g boneless pork loin","1 tsp dried rosemary","1 clove garlic","2 tbsp honey","1 tbsp vegetable oil","250 ml apple juice","50 g raisins","to taste salt","to taste black pepper"],"steps":["Peel and crush the garlic through a press, then mix with the rosemary, honey, oil, salt, and pepper.","Coat the pork loin thoroughly in the marinade, cover, and refrigerate overnight.","Preheat the oven to 220 °C, transfer the meat to a heatproof roasting dish, and bake for about 15 minutes until it begins to brown.","Pour the apple juice into the dish, cover with a lid, reduce the oven temperature to 160 °C, and roast for about 60 minutes.","Stir the raisins into the pan sauce a few minutes before the end of roasting."],"time":90,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Schab_na_s%C5%82odko","page":"Książka kucharska/Schab na słodko"},{"id":"oc-plwb-5555","title":"Szarlotka (Polish apple pie)","cuisine":"European","category":"Cake","ingredients":["300 g plain flour","100 g butter (or margarine)","100 g sugar","1 egg yolk","2 tbsp sour cream","1 tsp baking powder","1 kg apples (Antonovka or Reinette)","2 tbsp icing sugar","1 pinch salt","to taste cinnamon (optional)"],"steps":["Mix the flour with the baking powder, add the diced butter, and chop the ingredients together with a knife.","Add the salt, sugar, egg yolk, and sour cream, quickly knead into a dough, and chill in the refrigerator for about 30 minutes.","Peel and core the apples, then cut them into small slices or grate them on a coarse grater.","Roll out half of the dough, line the bottom and high edges of a greased and floured springform tin, and prick the base with a fork.","Bake the base in an oven preheated to 200 °C for about 10 minutes, then remove and cool in the tin.","Spread the prepared apples over the partially baked base, shape the remaining dough into rolls as thick as your little finger, and arrange them in a lattice on top.","Bake the apple pie at 200 °C for about 40 minutes until golden, then dust the hot pastry with icing sugar and cinnamon."],"time":110,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szarlotka","page":"Książka kucharska/Szarlotka"},{"id":"oc-plwb-4104","title":"Szałot (Silesian potato and herring salad)","cuisine":"European","category":"Salad","ingredients":["750 g potatoes","2 salted herrings","2 fermented (brine) pickles","1 onion (large)","to taste vinegar (or pickle brine)","100 g smoked fatback (or smoked bacon)","1 tsp caraway seeds","to taste salt","to taste pepper","1 apple (tart, optional)"],"steps":["Wash the potatoes and boil in their skins in water seasoned with caraway seeds, then cool, peel, and cut into large dice.","Soak the salted herrings in cold water for about 60 minutes, remove skin and bones, and slice into thin strips.","Peel the fermented pickles, onion, and optionally the apple, then dice everything finely.","Combine the potatoes, herrings, pickles, onion, and apple, seasoning with salt, pepper, and vinegar or pickle brine.","Finely dice the smoked fatback or bacon, render in a skillet, pour over the salad together with the rendered fat, and toss gently."],"time":100,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sza%C5%82ot","page":"Książka kucharska/Szałot"},{"id":"oc-plws-44950","title":"Szczupak lub sandacz w majonezie w całości (whole poached pike or zander in aspic mayonnaise)","cuisine":"European","category":"Main","ingredients":["3.6 kg pike (orig. a pike or zander weighing 8–10 funt (3.2–4 kg))","1 bunch soup vegetables (a bunch, for the court-bouillon)","1 onion (for the court-bouillon)","2.5 l water (for the vegetable court-bouillon)","to taste salt (for salting the fish and seasoning the mayonnaise)","25 g gelatine (orig. 2 łut of gelatine (or 3 łut = 37.5 g if making extra cubed aspic for garnish))","750 ml fish cooking stock (orig. 3 kwaterki of stock from cooking the fish)","250 ml olive oil (orig. 1 szklanka)","1 tbsp vinegar (strong, lightly sweetened)","to taste assorted garnishes (gherkins, cooked carrot and beetroot, green peas, capers, olives, pickled mushrooms, hard-boiled eggs, corn salad)"],"steps":["Clean the pike or zander whole, rub it inside and out with salt, and leave in a cool place for several hours.","In a large pot, boil a court-bouillon from the soup vegetables, onion, and spices.","Wrap the fish in a clean linen cloth (or bind just the head with cloth), place in a wide pan, cover with the warm vegetable court-bouillon, and poach covered over low heat until the flesh is tender without falling apart.","Carefully lift the hot fish from the pan, unwrap the cloth, and lay it whole on a long platter to cool completely.","Pour 750 ml (3 historical Polish kwaterki) of the fish cooking stock over 25 g of gelatine and boil until the liquid reduces by half, then strain the stock and let cool.","Add 250 ml of olive oil, 1 tablespoon of strong sweetened vinegar, and a pinch of salt to the cooled liquid jelly, and whisk until the mixture turns into a thick, white mayonnaise foam and begins to set.","Coat the cold fish completely with a thick layer of the whipped mayonnaise and garnish the top with decoratively cut gherkins, carrot, beetroot, green peas, capers, olives, pickled mushrooms, hard-boiled eggs, and corn salad leaves."],"time":385,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Szczupak_lub_sandacz_w_majonezie_w_ca%C5%82o%C5%9Bci","page":"365 obiadów za 5 złotych/Szczupak lub sandacz w majonezie w całości"},{"id":"oc-plwb-14641","title":"Szpajza (Silesian layered egg mousse)","cuisine":"European","category":"Dessert","ingredients":["4 eggs","200 g sugar","4 tsp gelatine","0.5 lemon (juiced)","20 ml vodka (unflavoured)","1 tbsp cocoa powder"],"steps":["Soak the gelatine in a small amount of cold water, dissolve in a hot water bath, and cool slightly.","Whip the egg whites to stiff peaks, and in a second bowl beat the egg yolks with sugar until light and fluffy.","Gently fold the egg white foam into the beaten yolks and stir in the dissolved gelatine.","Divide the mousse into two equal portions: add the lemon juice to the first, and cocoa dissolved in vodka to the second, mixing both thoroughly.","Layer both portions alternately into dessert dishes, smoothing the top with a spoon, and chill in the refrigerator for about 60 minutes to set."],"time":80,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szpajza","page":"Książka kucharska/Szpajza"},{"id":"oc-plws-45272","title":"Szparagi (boiled white asparagus with buttered breadcrumbs)","cuisine":"European","category":"Side","ingredients":["22 white asparagus (orig. tied in bundles of 10–12 spears (approx. 2 bundles))","to taste water (boiling for cooking and cold for refreshing the asparagus)","to taste salt (for salting the water)","1 tsp sugar (orig. a lump of sugar)","2 tbsp breadcrumbs (for browning in butter)","3 tbsp butter (for browning the breadcrumbs (plus clarified butter in a sauceboat))"],"steps":["Select fresh white asparagus with purple-tinged tips, gently scrape off the thin outer skin holding the knife flat, and tie with kitchen string into bundles of 10–12 spears.","Place the asparagus bundles into a pot of generously salted boiling water with a lump of sugar and boil over high heat for about 20 minutes, taking care not to overcook them.","Lift out the cooked asparagus, dip them for a split second into cold water, remove the strings, and arrange on a platter with the tips pointing towards the centre.","Spoon the breadcrumbs browned in butter over the asparagus, and serve melted clarified butter or chaudeau sauce separately in a sauceboat."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Szparagi","page":"365 obiadów za 5 złotych/Szparagi"},{"id":"oc-plws-45273","title":"Szparagi zielone, podane na sposób zielonego groszku (diced green asparagus in cream sauce)","cuisine":"European","category":"Side","ingredients":["30 green asparagus (orig. half a kopa (30 spears))","to taste water (for boiling the asparagus)","to taste salt (for boiling the asparagus and for the sauce)","1 tbsp plain wheat flour","2 tbsp butter (1 tablespoon for the roux and 1 tablespoon of fresh butter for the sauce)","1 tsp caster sugar","2 egg yolks","125 ml whipping cream (orig. half a kwaterka of sweet cream)"],"steps":["Wash the green asparagus, cut off the tips, halve the thicker stalks lengthwise, and cut everything into fine pea-sized dice.","Boil the diced asparagus in salted water until completely tender, then drain.","In a small saucepan, cook 1 tablespoon of plain wheat flour with 1 tablespoon of butter into a roux, then add a pinch of salt, 1 teaspoon of caster sugar, the second tablespoon of fresh butter, 2 egg yolks, and 125 ml of whipping cream.","Heat the sauce over low heat, stirring constantly with a spoon, until the butter melts and the sauce is thoroughly heated and thickened.","Add the cooked asparagus to the hot sauce, stir over the heat for a moment, and serve immediately."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Szparagi_zielone%2C_podane_na_spos%C3%B3b_zielonego_groszku","page":"365 obiadów za 5 złotych/Szparagi zielone, podane na sposób zielonego groszku"},{"id":"oc-plws-39662","title":"Sztufada (larded braised beef)","cuisine":"European","category":"Main","ingredients":["2.4 kg beef rump (orig. at least 6 funt)","150 g pork fatback (cut into thick strips for larding the meat)","2 tbsp butter (orig. a piece of butter for the bottom of the pot)","2 tbsp vinegar (for sprinkling the meat)","2 onion (orig. a couple of onions, chopped)","2 carrot (chopped)","1 beetroot (chopped)","0.5 celeriac (chopped)","1 parsley root (chopped)","3 allspice berries (orig. a couple of berries)","2 tbsp plain wheat flour (for dusting the meat before browning)","to taste salt","to taste black pepper"],"steps":["Pound a large piece of beef rump well, pierce it deeply with a knife, and lard it with thick strips of pork fatback dusted with black pepper, then rub the entire roast with salt and pepper.","Heat a deep casserole dish thoroughly, put the butter on the bottom, place the meat inside, sprinkle it with vinegar, and braise covered over low heat until it releases its juices.","Add the finely chopped onions, carrots, beetroot, celeriac, parsley root, and allspice berries, cover, and braise slowly until the meat is completely tender.","Remove the tender roast, dust it on all sides with plain wheat flour, press the braising juices through a sieve, and skim the rendered fat from the surface.","Pour the skimmed fat back into the pot, brown the flour-dusted roast in it, then pour in the sieved sauce and boil briefly together.","Transfer the braised beef to a platter, skim any excess fat from the surface of the sauce once more, and pour the sauce over the meat."],"time":210,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sztufada","page":"365 obiadów za 5 złotych/Sztufada"},{"id":"oc-plws-39699","title":"Sztufada w galarecie (larded braised beef in aspic)","cuisine":"European","category":"Main","ingredients":["2.8 kg beef roasting joint (orig. 6–8 funt (2.4–3.2 kg))","150 g pork fatback (cut into thick strips for larding the meat)","2 tbsp butter (for browning the roast)","2 calf's feet (cleaned and cut into pieces)","1 bunch soup vegetables (a large bunch (carrot, parsley root, celeriac), finely chopped)","1 beetroot (finely chopped)","2 onion (finely chopped)","1 l water (enough to cover the vegetables and calf's feet well)","to taste salt","to taste black pepper (for the fatback)"],"steps":["Lard the beef roast with thick strips of pork fatback dusted with black pepper, rub the meat with salt, and set aside for just under 60 minutes.","Heat the butter in a large casserole pot, add the roast, and brown it well on all sides, turning frequently.","Add the cleaned and chopped calf's feet along with the finely chopped soup vegetables, beetroot, and onion, then pour in enough water to cover the vegetables.","Cover the pot with a tight-fitting lid and braise over very low heat for 3 hours.","Transfer the tender roast to a deep bowl, press all the braising liquid and vegetables through a fine sieve directly over the meat, and leave in a cool place for about 4 hours until completely set.","Unmould the chilled roast from the bowl, slice it together with the aspic, and serve cold."],"time":510,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sztufada_w_galarecie","page":"365 obiadów za 5 złotych/Sztufada w galarecie"},{"id":"oc-plws-39702","title":"Szynka z cielęciny (cured and larded roast leg of veal)","cuisine":"European","category":"Main","ingredients":["5.4 kg leg of veal (orig. a hindquarter of veal weighing 12–15 funt (4.8–6 kg))","50 g salt (orig. 4 łut)","6 g potassium nitrate (orig. 1/2 łut of crushed saltpetre (modern curing salt may be used instead))","1 tbsp coriander seeds","1 tbsp juniper berries (crushed)","250 ml wine vinegar (mild, hot)","150 g pork fatback (fresh, cut into strips for larding)","3 tbsp butter (for basting during roasting)","100 ml sour cream (for basting during roasting)","2 tbsp breadcrumbs (for sprinkling towards the end of roasting)"],"steps":["Rub the leg of veal with the salt mixed with saltpetre, sprinkle with the coriander seeds, place under a weight in a stoneware crock, and cure in a cool place for 10 to 21 days, turning the meat daily and basting it with the juices released.","Remove the meat from the brine, rub it with the crushed juniper berries, pour the hot mild vinegar over it, and leave for about 12 hours.","Rinse the veal in the same vinegar, pat dry, and lard it densely with strips of fresh pork fatback.","Roast on a spit or in an oven preheated to 180 °C for about 2.5 hours, basting regularly with melted butter and sour cream.","Towards the end of roasting, sprinkle the top of the meat with breadcrumbs so they brown; serve warm or cold, for example as part of the blessed Easter meal."],"time":150,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Szynka_z_ciel%C4%99ciny","page":"365 obiadów za 5 złotych/Szynka z cielęciny"},{"id":"oc-plwb-4953","title":"Tartar sauce (Sos tatarski)","cuisine":"European","category":"Sauce","ingredients":["250 ml mayonnaise","2 fermented (brine) pickles","2 vinegar pickles","1 canned peas (can, drained)","1 leek (about 10 cm of the white part)","to taste salt","to taste pepper","to taste horseradish (optional)"],"steps":["Finely dice the fermented pickles and vinegar pickles.","Mince the white part of the leek as finely as possible and sprinkle with salt.","Combine the diced pickles and leek with the drained peas and mayonnaise.","Season the sauce with pepper and optionally a touch of horseradish, then mix thoroughly."],"time":10,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_tatarski","page":"Książka kucharska/Sos tatarski"},{"id":"oc-plws-546885","title":"Thick bilberry jam with pears","cuisine":"European","category":"Preserve","ingredients":["2400 g bilberries (ripe, orig. 4 litres of bilberries)","1000 g sugar (orig. 1 kilogram)","250 ml water (for the syrup, plus boiling water for blanching the berries)","4 pears (peeled and chopped very finely, orig. a few)","50 g candied orange peel (finely chopped, orig. 1 handful)"],"steps":["Blanch ripe bilberries in boiling water and turn them onto a sieve to drain well.","Cook a syrup in a wide pan from 1 kg of sugar and 250 ml of water, add the drained berries, and bring it to the boil.","When the berries begin to boil, add peeled, very finely chopped pears and finely chopped candied orange peel.","Cook everything over low heat, stirring often, until the jam reaches the desired consistency, then pack into jars."],"time":90,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Marmolada_bor%C3%B3wkowa","page":"Doświadczone sekreta smażenia konfitur i soków/Marmolada borówkowa"},{"id":"oc-plws-546881","title":"Thick gooseberry jam","cuisine":"European","category":"Preserve","ingredients":["2000 g unripe gooseberries (orig. 3 litres)","1500 g sugar (orig. one and a half kilograms)","750 ml water (orig. 3 szklanki)"],"steps":["Remove the stems from unripe gooseberries and chop them very finely.","Bring a syrup made with 1.5 kg of sugar and 750 ml of water to the boil. Add the chopped gooseberries and cook over low heat, stirring often with a wooden spoon, until the jam is very thick and pulls away from the bottom of the pan.","Pack the hot jam into an earthenware pot or scalded jars. If too thin, dry it in a gently heated oven first. Let cool, then seal tightly."],"time":105,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Marmolada_agrestowa","page":"Doświadczone sekreta smażenia konfitur i soków/Marmolada agrestowa"},{"id":"oc-plws-546884","title":"Thick plum jam","cuisine":"European","category":"Preserve","ingredients":["3000 g ripe węgierka plums (orig. 3 kilograms)","2 l water (boiling water for blanching the plums, and cold water for shocking them)","1000 g sugar (fine, orig. 1 kilogram)","5 whole cloves (wrapped in muslin, orig. a few)"],"steps":["Blanch ripe węgierka plums in boiling water, slip off the skins, and drop them at once into cold water so they do not darken.","Drain the peeled plums, cut them in half, remove the stones, and pack them in a wide pot in layers with 1 kg of fine sugar, adding not a drop of water.","Put a few cloves wrapped in muslin into the pot and cook the plums over moderate heat, stirring often with a wooden spatula.","When the jam is very thick and no longer sticks to a cold saucer, remove the cloves and pack the hot jam into scalded jars."],"time":135,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Marmolada_%C5%9Bliwkowa","page":"Doświadczone sekreta smażenia konfitur i soków/Marmolada śliwkowa"},{"id":"oc-plws-548322","title":"Thin Potato and Poppy Seed Cookies","cuisine":"European","category":"Cookie","ingredients":["500 g wheat flour (orig. 50 dkg)","500 g boiled potatoes (orig. 50 dkg, riced)","150 g sugar (orig. 15 dkg)","20 g fresh yeast (orig. 2 dkg)","150 g vegetable oil or lard (orig. 15 dkg)","100 g poppy seeds (orig. 10 dkg)"],"steps":["Combine the wheat flour with the boiled and riced potatoes, sugar, crumbled fresh yeast, oil or lard, and dry poppy seeds, and knead into a fairly firm dough.","Roll out the dough on a board as thinly as possible and cut out round cookies with a glass.","Arrange the cookies on a baking sheet and bake in a preheated oven (180–190 °C) for about 15–20 minutes until lightly golden."],"time":50,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Paluszki_makowe","page":"109 potraw/Paluszki makowe"},{"id":"oc-plws-546604","title":"Thrifty Sauerkraut Soup (Kapusniak Oszczedny)","cuisine":"European","category":"Soup","ingredients":["500 g sauerkraut (orig. 50 dkg of mild sauerkraut)","100 g pork fatback rinds (orig. 10 dkg)","1.5 l water (for cooking the soup and blending the flour)","1 carrot (whole)","1 parsley root (whole)","1 onion (whole)","2 black peppercorns (whole peppercorns)","1 bay leaf (whole leaf)","to taste salt (to taste if needed)","30 g wheat flour (orig. 3 dkg (1 heaped tablespoon))"],"steps":["Place the sauerkraut and pork fatback rinds in a pot, pour in the water, add the peppercorns and bay leaf, and simmer slowly until the sauerkraut and rinds begin to soften.","Add the peeled and halved carrot, parsley root, and onion, and continue simmering covered over low heat until all the vegetables are completely tender.","Just before serving, remove the pork rinds, dice them finely, and return them to the soup.","Thicken the soup with the wheat flour blended in cold water, season with salt if needed, bring to a boil together, and serve."],"time":105,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Kapu%C5%9Bniak_oszcz%C4%99dny","page":"109 potraw/Kapuśniak oszczędny"},{"id":"oc-plws-580269","title":"Timbale z makaronu (pasta timbale)","cuisine":"European","category":"Main","ingredients":["400 g long Italian pasta (cooked whole)","200 g finely broken pasta","to taste salt (for boiling the pasta and seasoning the mixture)","to taste butter (for greasing the mould and dotting the top)","to taste breadcrumbs (for dusting the mould)","500 ml mushroom sauce (thick, made from fresh or dried mushrooms (plus extra for serving))","2 eggs (whole)","to taste nutmeg (grated)","to taste white pepper","to taste marjoram (rubbed)"],"steps":["Cook the long Italian pasta whole in well-salted water for about 10 minutes, and in a separate pot cook the finely broken pasta for 8 minutes, then drain both.","Generously butter a smooth metal mould and dust it with breadcrumbs.","Line the bottom and sides of the mould with the long pasta coiled in a spiral so that no gaps remain, reserving some of the long strands for the top.","Mix the thick mushroom sauce with the whole eggs and the cooked broken pasta, then season the mixture with salt, nutmeg, white pepper, and marjoram.","Fill the centre of the mould with the pasta mixture, cover with the reserved long pasta, and dot the top with pieces of butter.","Preheat the oven to 180 °C and bake uncovered for about 35 minutes (or cover the mould tightly with a lid and steam for 45 minutes).","Unmould the finished timbale onto a platter and serve hot with additional mushroom sauce."],"time":75,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/%E2%80%9ETimbale%E2%80%9C_z_makaronu","page":"100 postnych i jarskich dań/„Timbale“ z makaronu"},{"id":"oc-plws-580272","title":"Timbale z ryżu (rice timbale)","cuisine":"European","category":"Main","ingredients":["250 ml rice (for the smooth lining mixture)","1 tsp butter (for mashing into the rice mixture)","2 eggs","1 tbsp butter (for frying the onion, plus extra for the mushrooms, mould, and top)","1 onion (finely chopped)","250 ml rice (braised until fluffy)","to taste vegetable broth (or salted water for moistening the rice)","250 g button mushrooms (or young porcini)","4 tomatoes (large, ripe, cut into coarse dice)","to taste salt","to taste breadcrumbs (for dusting the mould)","to taste tomato sauce (plain, for serving)"],"steps":["Boil the first portion of rice in water until very soft, about 25 minutes, then drain, salt, and mash thoroughly with a spoon along with the teaspoon of butter and the eggs until completely smooth.","Cook the finely chopped onion in a tablespoon of butter until translucent, add the second portion of rice, and fry over low heat, stirring constantly, for about 5 minutes until the rice turns slightly yellow.","Gradually add the vegetable broth a few spoonfuls at a time and cook the rice gently, covered, over low heat for about 20 minutes until tender and fluffy.","Cook the cut button mushrooms gently in butter, covered, for 10 minutes, and cut the tomatoes into coarse dice.","Generously butter a smooth mould, dust it with breadcrumbs, and line the bottom and sides with part of the mashed rice mixture.","Fill the centre of the mould with the fluffy rice layered with the cooked mushrooms and tomatoes, cover with the remaining mashed rice mixture, and dot the top with pieces of butter.","Place the mould in an oven preheated to 180 °C and bake for about 60 minutes until golden brown (or cover with a lid and steam for 60 minutes).","Unmould the timbale onto a platter and serve with plain tomato sauce."],"time":95,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/%E2%80%9ETimbale%E2%80%9C_z_ry%C5%BCu","page":"100 postnych i jarskich dań/„Timbale“ z ryżu"},{"id":"oc-plwb-14698","title":"Tomatoes stuffed with blue cheese and salami (Pomidory faszerowane salami)","cuisine":"European","category":"Snack","ingredients":["10 tomatoes","150 g Rokpol blue cheese","150 g salami (sliced)","5 vinegar pickles (gherkins) (small)","1 bunch chives (chopped)","1 tbsp walnuts (chopped)","1 tsp grated horseradish","2 tbsp plain yogurt","2 tbsp mayonnaise","to taste hot ground paprika","to taste salt"],"steps":["Wash the tomatoes, slice off the tops, and scoop out the pulp, leaving a half-centimetre shell around the skin.","Mash the Rokpol blue cheese with a fork, add the chopped tomato pulp, finely shredded salami, finely diced gherkins, and chopped chives.","Mix the ingredients with the chopped walnuts, grated horseradish, yogurt, and mayonnaise, then season to taste with hot paprika and salt.","Fill the hollowed tomatoes with the prepared stuffing and top with the reserved tomato caps."],"time":20,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pomidory_faszerowane_salami","page":"Książka kucharska/Pomidory faszerowane salami"},{"id":"oc-plws-451113","title":"Torcik migdałowy na opłatkach (No-bake almond cream wafer torte)","cuisine":"European","category":"Cake","ingredients":["6 communion-style wafer sheets (large dinner-plate-sized sheets)","200 g sweet almonds (blanched and finely ground, orig. 20 dag)","5 bitter almonds (blanched and finely ground, orig. several almonds)","100 g butter (orig. 10 dag)","3 egg yolks (whole yolks)","200 g icing sugar (orig. 20 dag)","150 g chocolate fondant icing (boiled, for glazing the top)"],"steps":["Finely grind the blanched sweet and bitter almonds in a nut mill.","Beat the softened butter until creamy, and in a separate bowl beat the three egg yolks with the icing sugar until pale, then combine both mixtures with the ground almonds.","Spread five of the wafer sheets thinly with the almond cream, stack them one on top of another, cover with the sixth wafer sheet, weight down with a small board, and leave in a cool place for about 3 hours until firm.","Glaze the firm torte with boiled chocolate fondant."],"time":210,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Torcik_migda%C5%82owy_na_op%C5%82atkach","page":"Ciasta wielkanocne/Torcik migdałowy na opłatkach"},{"id":"oc-plws-450891","title":"Torcik z orzechów laskowych na opłatku (hazelnut wafer torte)","cuisine":"European","category":"Cake","ingredients":["4 eggs","400 g sugar (orig. 40 dag)","400 g hazelnuts (orig. 40 dag, ground)","2 wafer sheets (rounds the size of a plate)","100 g sweet-cream butter (orig. 10 dag)","100 g icing sugar (orig. 10 dag)","100 g hazelnuts (orig. 10 dag, ground for the cream)","2 eggs (raw, for the cream)","to taste clear sugar fondant (for icing the top)","to taste hazelnuts (toasted, for garnishing)"],"steps":["Beat 4 eggs with 400 g of sugar until pale, then mix in 400 g of ground hazelnuts.","Spread the hazelnut mixture over 2 plate-sized wafer rounds and bake in a moderately warm oven (about 160–170 °C) for about 25–30 minutes.","Beat 100 g of sweet-cream butter until fluffy, add 100 g of icing sugar, 100 g of ground hazelnuts, and 2 eggs, and beat until smooth.","Sandwich the cooled wafer rounds with the prepared hazelnut cream.","Ice the top of the torte with clear fondant and garnish with toasted hazelnuts."],"time":70,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Torcik_z_orzech%C3%B3w_laskowych","page":"Ciasta wielkanocne/Torcik z orzechów laskowych"},{"id":"oc-plws-450889","title":"Tort aleksandryjski (Alexandrian shortcrust layer torte)","cuisine":"European","category":"Cake","ingredients":["500 g plain flour (orig. half a kilo)","400 g butter (orig. 40 dag)","400 g sugar (orig. 40 dag)","375 ml whipping cream or whole milk (orig. 1.5 szklanki)","125 ml sugar (orig. half a szklanka (about 110 g))","0.5 vanilla pod (pod pounded with sugar)","100 g sweet-cream butter (orig. 10 dag)","2 eggs (whole)","1 tbsp plain flour","to taste punch fondant or apricot jam (for coating the torte)","to taste almonds (coarsely chopped and lightly toasted)"],"steps":["Knead a shortcrust dough from 500 g of plain flour, 400 g of butter, and 400 g of sugar, and chill it in a cool place for about 30–40 minutes.","Divide the dough into 3 equal parts, roll each out into a plate-sized round, and bake in an oven preheated to 180 °C until deeply golden brown.","In a saucepan, mix 375 ml of whipping cream or milk, 125 ml of sugar, the vanilla pounded with sugar, 100 g of sweet-cream butter, 2 eggs, and a tablespoon of plain flour.","Heat the mixture over low heat, stirring constantly, until thickened without letting it come to a boil, then remove from the heat and continue beating until it cools slightly.","Spread the cream over two of the baked rounds, stack them, and top with the third layer.","Coat the entire torte with punch fondant or apricot jam and sprinkle with coarsely chopped, lightly toasted almonds."],"time":135,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_aleksandryjski","page":"Ciasta wielkanocne/Tort aleksandryjski"},{"id":"oc-plws-450881","title":"Tort czekoladowy z masą migdałowo-likierową (chocolate almond torte with maraschino almond cream)","cuisine":"European","category":"Cake","ingredients":["10 eggs (separated into yolks and whites)","250 g icing sugar (orig. a quarter kilo)","250 g chocolate (orig. a quarter kilo, grated)","0.5 vanilla pod (piece of pod pounded with sugar)","250 g almonds (orig. a quarter kilo, ground with their skins)","15 g butter (for greasing the tin)","2 tbsp breadcrumbs (for dusting the tin)","250 g almonds (orig. a quarter kilo, scalded, peeled, and ground)","250 g sugar (orig. a quarter kilo, for the syrup)","250 ml water (orig. 1 szklanka)","1 lemon (squeezed juice)","50 ml maraschino liqueur or crème de cacao (orig. a large kieliszek)","to taste chocolate fondant (for icing the top)"],"steps":["Beat 10 egg yolks with 250 g of icing sugar, then add 250 g of grated chocolate, the vanilla pounded with sugar, and 250 g of almonds ground with their skins.","Beat the 10 egg whites until stiff, fold gently into the chocolate mixture, transfer to a cake tin greased with butter and dusted with breadcrumbs, and bake at 170 °C for about 45–50 minutes.","Leave the torte until the next day to cool completely, then slice it with a sharp knife into 3 equal layers.","Boil a light syrup from 250 g of sugar and 250 ml of water, pour it over 250 g of scalded, peeled, and ground almonds, and beat in a bowl until smooth.","Squeeze the juice of a whole lemon into the almond mixture and pour in 50 ml of maraschino or cocoa liqueur.","Sandwich the three layers of the torte with the prepared almond mixture, ice the top with chocolate fondant, and let stand for 6 hours before serving so the cake absorbs the aroma of the filling."],"time":600,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_czekoladowy","page":"Ciasta wielkanocne/Tort czekoladowy"},{"id":"oc-plws-450892","title":"Tort hiszpański bezowy z bitą śmietaną (Spanish tiered meringue and whipped cream torte)","cuisine":"European","category":"Cake","ingredients":["15 egg whites","400 g icing sugar (orig. 40 dag)","1 l heavy whipping cream (sweet, for whipping)","250 g icing sugar (orig. a quarter kilo)","0.5 vanilla pod (pounded with the icing sugar)","to taste fruit preserves (drained of syrup, for garnishing)","to taste candied citrus peel (candied citrus peel, for garnishing)","to taste small chocolates (for garnishing)"],"steps":["Beat 15 egg whites until very stiff and fold in 400 g of icing sugar.","Cut 6 progressively smaller rounds from oiled baking paper, spread the meringue mixture over them, and smooth with a knife.","Dry the meringue rounds in a very low oven (about 100–110 °C) for about 2 hours until completely dry, then cool and carefully peel off the paper.","An hour before serving, whip 1 l of sweet heavy cream and fold in 250 g of icing sugar pounded with vanilla.","Place the largest meringue round on a platter, cover with whipped cream, and stack the remaining rounds in decreasing order with whipped cream between each layer, covering the top round as well.","Garnish the torte with preserves drained of syrup, candied citrus peel, and small chocolates, and serve shortly after assembly."],"time":210,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_hiszpa%C5%84ski","page":"Ciasta wielkanocne/Tort hiszpański"},{"id":"oc-plws-451107","title":"Tort kawowy „Mocca” (Mocha coffee buttercream sponge torte)","cuisine":"European","category":"Cake","ingredients":["12 eggs (separated into yolks and whites)","400 g icing sugar (orig. 40 dag)","100 g potato starch (orig. 10 dag)","150 g plain flour (orig. 15 dag)","15 g butter (for greasing the tin)","2 tbsp breadcrumbs (for dusting the tin)","10 egg yolks (or 5 egg yolks and 2 tablespoons plain flour in the economical version)","200 g sugar (orig. 20 dag)","250 ml strong black coffee (orig. 1 szklanka of freshly brewed coffee without chicory)","300 g sweet-cream butter (orig. 30 dag)"],"steps":["Beat 12 egg yolks with 400 g of icing sugar until pale, then fold in a spoonful at a time a mixture of 100 g of potato starch and 150 g of plain flour, alternating with the stiffly beaten whites from the 12 eggs.","Transfer the batter to a cake tin greased with butter and dusted with breadcrumbs, bake in a low oven (about 160–165 °C) for about 45–50 minutes, and leave until the next day.","The next day, slice the sponge horizontally with a very sharp knife into 4 equal layers.","Whisk 10 egg yolks with 200 g of sugar and 250 ml of very strong coffee over low heat until thickened (taking care that the yolks do not curdle), then let cool.","Beat 300 g of sweet-cream butter until fluffy and gradually beat in the cooled coffee custard.","Spread three sponge layers with the cream, cover with the fourth, coat the top and sides of the torte with the remaining cream, pipe decorative rosettes on top, and chill for 2 hours before serving."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_kawowy_%E2%80%9EMocca%E2%80%9C","page":"Ciasta wielkanocne/Tort kawowy „Mocca“"},{"id":"oc-plws-451111","title":"Tort makaronikowy z kratką migdałową i konfiturami (almond macaroon lattice torte)","cuisine":"European","category":"Cake","ingredients":["400 g sweet almonds (orig. 40 dag, scalded, peeled, dried, and ground)","15 bitter almonds (orig. a dozen or so, scalded, peeled, and ground)","15 egg whites (beaten until stiff)","300 g icing sugar (orig. 30 dag)","1 wafer sheet (large round)","1 tbsp plain flour (for dusting the baking sheet)","to taste lemon fondant (for filling the spaces between the lattice)","to taste fruit preserves (drained of syrup, for garnishing)"],"steps":["Scald 400 g of sweet almonds and a dozen or so bitter almonds with boiling water, peel, dry thoroughly, and grind in a mill, then mix on a board with 300 g of icing sugar and divide into two equal parts.","Beat 15 egg whites until stiff. Combine half of the almonds with half of the beaten whites, spread in an even layer over a large wafer round placed on a flour-dusted baking sheet, and bake in a low oven (about 140 °C) until lightly golden.","Remove the parbaked base and let it cool slightly. Re-whip the remaining egg whites until stiff, mix with the remaining almonds, and fashion a decorative rim and lattice over the baked round.","Return the torte to a low oven (about 120–130 °C) so the lattice colours lightly and dries like a meringue, then remove and cool completely.","Fill the spaces between the lattice bars with lemon fondant and garnish with fruit preserves drained of syrup."],"time":105,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_makaronikowy","page":"Ciasta wielkanocne/Tort makaronikowy"},{"id":"oc-plws-451110","title":"Tort morelowy na biszkopcie (apricot jam and liqueur sponge torte)","cuisine":"European","category":"Cake","ingredients":["12 eggs (separated into yolks and whites)","400 g icing sugar (per recipe no. 18 in the same book)","100 g potato starch (per recipe no. 18 in the same book)","150 g plain flour (per recipe no. 18 in the same book)","15 g butter (for greasing the tin)","2 tbsp breadcrumbs (for dusting the tin)","90 ml abricotine apricot liqueur (orig. 3 liqueur glasses (1 per layer))","400 g apricot jam (for filling and coating the top and sides)","to taste preserved apricots (whole fruit, for garnishing)"],"steps":["Bake a sponge cake as for the Mocha coffee torte: beat 12 egg yolks with 400 g of icing sugar, gently fold in 100 g of potato starch, 150 g of plain flour, and the stiffly beaten whites from the 12 eggs, transfer to a tin greased with butter and dusted with breadcrumbs, and bake at 160–165 °C for about 45–50 minutes.","Leave the baked sponge until the next day, then slice it horizontally into 3 equal layers.","Sprinkle each sponge layer with 30 ml of abricotine apricot liqueur, spread thinly with apricot jam, and stack together.","Coat the top and sides of the torte with the same apricot jam and garnish with whole apricots from preserves or compote."],"time":600,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_morelowy","page":"Ciasta wielkanocne/Tort morelowy"},{"id":"oc-plws-450877","title":"Tort piaskowy przekładany marmoladą (sand cake torte with plum or apricot jam)","cuisine":"European","category":"Cake","ingredients":["400 g sugar (orig. 40 dag)","10 eggs (whole)","10 egg yolks (additional)","400 g clarified butter (orig. 40 dag, plus a little butter for the tin)","200 g plain flour (orig. 20 dag)","200 g potato starch (orig. 20 dag)","2 tbsp breadcrumbs (for dusting the tin)","250 g plum or apricot jam (for filling the torte)","to taste punch fondant (for icing the top)"],"steps":["Beat 400 g of sugar with 10 whole eggs until pale, then add 10 egg yolks one at a time along with 400 g of cooled clarified butter a spoonful at a time.","Once the mixture has risen and turned pale, stir in 200 g of plain flour and 200 g of potato starch and mix thoroughly.","Transfer the batter to a cake tin greased with butter and dusted with breadcrumbs, and bake in a moderately warm oven (about 165–170 °C) for about 50–60 minutes.","Once completely cooled, slice the torte horizontally in half and sandwich with plum or apricot jam.","Ice the top of the torte with punch fondant and dry for a few minutes in a warm oven."],"time":105,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_piaskowy","page":"Ciasta wielkanocne/Tort piaskowy"},{"id":"oc-plws-450890","title":"Tort z orzechów włoskich z pomadką kawową (walnut torte with almond-walnut cream and coffee fondant)","cuisine":"European","category":"Cake","ingredients":["400 g walnuts (orig. 40 dag, shelled and ground)","16 eggs (separated into yolks and whites)","400 g icing sugar (orig. 40 dag)","4 tbsp breadcrumbs (for the batter plus extra for dusting the tins)","20 g butter (for greasing the two tins)","100 g almonds (orig. 10 dag, peeled and ground)","100 g walnuts (orig. 10 dag ground for the cream plus halves for garnishing)","200 g icing sugar (orig. 20 dag)","2 eggs (whole, for the cream)","100 g butter (orig. 10 dag)","75 ml heavy whipping cream (orig. half a filiżanka of thick sweet cream)","to taste coffee fondant (for icing the top)"],"steps":["Grind 400 g of shelled walnuts in a nut mill.","Beat 16 egg yolks with 400 g of icing sugar, add the ground walnuts and 4 tablespoons of breadcrumbs, beat thoroughly, and gently fold in the stiffly beaten whites from the 16 eggs.","Divide the batter between two cake tins greased with butter and dusted with breadcrumbs, and bake at 170 °C for about 35–40 minutes.","Prepare the cream: mix 100 g of ground almonds, 100 g of ground walnuts, 200 g of icing sugar, 2 whole eggs, 100 g of butter, and 75 ml (half a filiżanka) of thick sweet cream, then heat over low heat, stirring constantly, until thickened without letting it boil.","Sandwich the cooled cake layers with the prepared cream, ice the top with coffee fondant, and garnish with walnut halves."],"time":105,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Tort_orzechowy","page":"Ciasta wielkanocne/Tort orzechowy"},{"id":"oc-plws-1081090","title":"Toruński piernik niezawodny (reliable Toruń gingerbread)","cuisine":"European","category":"Cake","ingredients":["1.2 kg honey (orig. 3 funty)","125 ml water (orig. półkwaterek)","5 g ground dried orange peel (orig. 1 łyżeczka od kawy)","5 g ground cloves (orig. 1 łyżeczka)","10 g ground anise (orig. 2 small łyżeczki)","2 l rye flour (orig. 2 kwarty of warmed, sifted rye flour)","4 eggs","50 g bicarbonate of soda (orig. 4 łuty potash / potassium carbonate)","50 ml food-grade rectified spirit (orig. 1 kieliszek)","1 egg yolk","100 g almonds (some chopped, some left whole to decorate)","100 g candied orange peel"],"steps":["Boil the honey in a saucepan with the water, dried orange peel, cloves and anise until it darkens slightly.","Scald the sifted, warmed rye flour with the hot honey, beating hard with a wooden spoon to a smooth dough with no lumps.","Beat 4 eggs into the hot dough, mix well, and leave it in a cool place to cool.","Add the baking soda or potash dissolved in a small glass of food-grade rectified spirit, the yolk, chopped almonds and candied peel to the cooled dough. Knead into a very firm, elastic dough.","Roll the dough out about 2–3 cm thick on a baking sheet lined with baking paper or on a waxed baking sheet. Brush with beaten egg, decorate with whole almonds and bake at 180 °C for about 45 minutes."],"time":135,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Toru%C5%84ski_piernik_niezawodny","page":"Baby, placki i mazurki/Toruński piernik niezawodny"},{"id":"oc-plws-1081087","title":"Traditional Glazed Marzipan Pastries","cuisine":"European","category":"Cookie","ingredients":["400 g sweet almonds (originally 1 funt)","50 g bitter almonds (orig. 4 łut)","400 g sugar (originally 1 funt of white sugar)","2 tbsp rosewater (for grinding the paste and attaching the rims)","0.5 tsp orange blossom water (a few drops)","2 tbsp icing sugar or wheat flour (for dusting the board)","400 g icing sugar (originally 1 funt of ground sugar for the icing)","1 lemon (whole, freshly squeezed juice)","1 tbsp water (for the icing)","100 g candied fruit (cut into strips or triangles, for garnishing)"],"steps":["Briefly scald the sweet and bitter almonds with hot water, slip off their skins, spread on a cloth to dry completely, and grate on the finest grater.","Combine the grated almonds with 400 g of finely ground sugar and work in a bowl with the rosewater and a few drops of orange blossom water into a very stiff paste, then set aside in a cool place for 3–4 days.","Roll out the aged marzipan paste on a board dusted with icing sugar to a thickness of about 1 cm, cut out hearts, stars, or other shapes with cutters, and attach a narrow marzipan rim moistened with rosewater around the edges.","Arrange the marzipan pastries on a parchment-lined baking sheet and broil briefly under the top oven element (approx. 4–5 minutes at 200 °C) until browned only on top while remaining pale underneath.","Beat 400 g of icing sugar with the lemon juice and a tablespoon of water into a thick, glossy icing (beating for about an hour or using a mixer).","Spread the icing over the cooled marzipan pastries, leave in a warm place until the glaze sets, and garnish with pieces of candied fruit."],"time":10,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Marcepany","page":"Baby, placki i mazurki/Marcepany"},{"id":"oc-plws-1081070","title":"Traditional molded wafers","cuisine":"European","category":"Cookie","ingredients":["8 eggs","150 g wheat flour (orig. 1 kwaterka (ok. 250 ml / 150 g))","15 g clarified butter (orig. 1 łyżka and more for the iron)","100 g sugar (orig. a quarter funt)","250 ml milk (orig. 1 kwaterka)","30 g sugar and cinnamon for sprinkling"],"steps":["Separate the yolks from the whites. Beat the yolks with the sugar, add the flour, a spoonful of clarified butter and the milk, and mix well.","Whip the whites to a stiff foam and fold them gently into the batter.","Heat a wafer iron or waffle iron until very hot, grease it with a brush of clarified butter, and pour in portions of batter.","Cook the wafers on both sides until golden, and sprinkle them with sugar mixed with cinnamon as soon as they come out."],"time":35,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Wafle","page":"Baby, placki i mazurki/Wafle"},{"id":"oc-plwb-15265","title":"Traditional Wodzionka (Silesian bread and garlic soup)","cuisine":"European","category":"Soup","ingredients":["2.5 slice stale bread (2–3 slices)","1 tbsp fat (e.g. lard or butter)","to taste liquid seasoning (Maggi type)","to taste salt","to taste black pepper","1.5 clove garlic (1–2 cloves)","400 ml boiling water (for pouring over the ingredients in the soup plate)"],"steps":["Dice the stale bread and finely chop the peeled garlic.","Place the bread, garlic, fat, and seasonings in a deep soup plate.","Pour the boiling water over everything and stir."],"time":10,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wodzionka_tradycyjna","page":"Książka kucharska/Wodzionka tradycyjna"},{"id":"oc-plws-569058","title":"Tradycyjna kiełbasa wiejska wędzona (cold-smoked Polish country pork and beef kiełbasa)","cuisine":"European","category":"Preserve","ingredients":["6.75 kg marbled pork (in a ratio of 3 parts pork to 1 part beef (per 9 kg meat))","2.25 kg lean beef (in a ratio of 1 part beef to 3 parts pork (per 9 kg meat))","400 g salt (orig. 40 dag per 9 kg meat)","15 g potassium nitrate (orig. 1.5 dag)","20 g black pepper (orig. 2 dag, pounded)","10 g allspice (orig. 1 dag, pounded)","6 clove garlic (orig. several cloves, mashed)","1 pork casings (medium-thin, for stuffing)"],"steps":["Finely chop marbled pork and lean, tender beef with a sharp knife in a 3:1 ratio (e.g. 6.75 kg of pork and 2.25 kg of beef for a 9 kg batch).","For 9 kg of meat, add 400 g of salt, 15 g of potassium nitrate, 20 g of crushed black pepper, 10 g of crushed allspice, and mashed garlic, and knead the mixture very thoroughly.","Stuff the mixture into medium-thin pork casings and hang the kiełbasa (Polish sausages) on rods in a cool, frost-free larder for 7 days.","Before smoking, air-dry the kiełbasa (Polish sausages) for a few hours in the wind, then smoke for about a week in cool smoke."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Domowe_w%C4%99dliny/Kie%C5%82basy_w%C4%99dzone","page":"Domowe wędliny/Kiełbasy wędzone"},{"id":"oc-plws-1081051","title":"Translucent White Fondant Glaze","cuisine":"European","category":"Sauce","ingredients":["800 g sugar (originally 2 funt)","250 ml water (as much as the sugar absorbs)","1 tbsp spirit or wine vinegar","2 tbsp rosewater, arrack, or lemon juice (for thinning the fondant paste before glazing)"],"steps":["Pour as much water over the sugar in a saucepan as it will absorb, set over the heat, and add a tablespoon of vinegar while boiling.","Boil the syrup to the thread stage (approx. 106–110 °C), then pour it out onto a porcelain platter or marble slab to cool completely.","Transfer the cooled syrup to a bowl and beat with a wooden pestle or mixer until it turns completely white and transforms into a smooth, thick fondant paste.","Before use, thin the required portion of fondant with rosewater for yeast cakes, or with arrack and lemon juice for pączki (Polish doughnuts) and mazurki (Polish Easter flat cakes), then brush onto the slightly cooled baked goods."],"time":45,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Lukier_bia%C5%82y%2C_przezroczysty","page":"Baby, placki i mazurki/Lukier biały, przezroczysty"},{"id":"oc-plws-582250","title":"Turkey à la Daube","cuisine":"European","category":"Main","ingredients":["1 turkey (large and plump)","500 g veal (orig. 1¼ funt; converted assuming 1 funt = 400 g)","1 liver","1 French roll (quantity according to the ingredient list)","to taste milk (for soaking the roll; amount not specified in the source)","200 g butter (orig. half a funt; converted assuming 1 funt = 400 g)","2 onion","to taste butter (for frying the onion; no separate amount specified in the source)","to taste pepper","to taste salt","7 eggs (quantity according to the ingredient list)","133.33 g cooked ham (orig. ⅓ funt; converted assuming 1 funt = 400 g)","5 eggs (for separate egg-white and egg-yolk omelets)","to taste gherkins (for layering; amount not specified in the source)","to taste broth (for cooking the turkey; volume and composition not specified in the source)","to taste mayonnaise (for garnish)","to taste mustard sauce (for serving)"],"steps":["Bone the turkey completely by slitting along the back, keeping the skin and meat intact.","Salt the turkey.","Soak the roll in milk.","Fry the chopped onion in the butter intended for frying.","Grind the membrane-trimmed veal and liver together with the soaked roll, 200 g of butter, the onion, seven eggs, and pepper.","Slice the cooked ham.","Separate the whites from the yolks of the five eggs intended for the omelets.","Fry one omelet from the whites and a separate one from the yolks.","Fill the turkey with alternating layers of forcemeat, ham, gherkins, and omelets.","Sew up the opening in the turkey.","Wrap the turkey in a clean cloth and tie with kitchen twine.","Simmer in the broth for 180 minutes.","Remove the turkey and leave it wrapped until completely cooled.","Unwrap the cooled turkey.","Serve the sliced turkey garnished with mayonnaise and accompanied by mustard sauce."],"time":180,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/A_la_daube_z_indyka","page":"Kucharka litewska (1913)/A la daube z indyka"},{"id":"oc-plws-568700","title":"Two-Tone Apple Pastila","cuisine":"European","category":"Preserve","ingredients":["4 kg tart apples (small, summer or autumn apples of a choice variety)","2.5 kg fine sugar (500 g of sugar per 500 g of strained apple puree)","100 ml water (a splash for moistening the apples while cooking down)","2 tsp alkermes (juice or liqueur made from szkarłatnica (pokeweed), for tinting half the mixture pink)","0.25 tsp rose oil (a few drops for the pink half of the mixture, optional)"],"steps":["Peel 4 kg of tart apples, cut into pieces, add a splash of water, and cook until soft.","Press the hot apples through a colander, weigh the resulting puree, and add 500 g of fine sugar for every 500 g of puree.","Stir thoroughly in a pan and reduce over high heat, stirring constantly, until the paste pulls away from the sides; remove immediately to avoid overcooking.","Divide the hot mixture into two equal parts: leave one half white, and tint the other half pink with 2 teaspoons of alkermes and optionally a few drops of rose oil.","Transfer both portions to platters, bringing the two colors together; once cooled, cut into pieces of any desired shape and dry in a very low oven or a warm room."],"time":225,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Jab%C5%82eczna_pastila_dwukolorowa","page":"Doświadczone sekreta smażenia konfitur i soków/Jabłeczna pastila dwukolorowa"},{"id":"oc-plws-544170","title":"Unpeeled Pears","cuisine":"European","category":"Preserve","ingredients":["500 g bergamot pears (half-ripe, unpeeled)","1 kg sugar (500 g on the first day and 500 g on the second day)","375 ml water (1.5 glasses for the first syrup, plus cold water for soaking)"],"steps":["Select fine, half-ripe bergamot pears, prick them densely with a pin, trim the stems slightly, core the seeds from the bottom, and drop into cold water.","Boil a thin syrup from 500 g of sugar and 375 ml (1.5 glasses) of water, add the drained pears, and cook until tender, then set aside until the next day.","On the second day, drain the syrup, strain through a fine sieve or muslin, add the remaining 500 g of sugar, and simmer with the pears until the syrup thickens properly.","Transfer the cooled pears together with the syrup into jars and seal tightly."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Gruszki_nieobierane","page":"Doświadczone sekreta smażenia konfitur i soków/Gruszki nieobierane"},{"id":"oc-plws-39483","title":"Uszka do barszczu (small meat and mushroom dumplings for borscht)","cuisine":"European","category":"Side","ingredients":["300 g boiled or roast beef (finely minced, for the filling)","50 g pork fatback (finely minced together with the meat, for the filling)","1 tbsp butter (for the filling)","1 onion (grated or baked, for the filling)","1.5 dried mushrooms (orig. 1–2 cooked and chopped mushrooms along with a splash of their cooking stock)","2 tbsp breadcrumbs (for the filling)","2 eggs (orig. a couple of whole eggs, for the filling)","to taste salt (for the filling and for the boiling water)","to taste black pepper (for the filling)","500 ml plain wheat flour (orig. half a Polish quart (approx. 325 g), for the dough)","1 egg (for the dough)","120 ml water (for kneading the dough and sealing the edges (plus boiling water for cooking the dumplings))"],"steps":["Chop the boiled or roast beef very finely together with the piece of pork fatback.","Melt 1 tablespoon of butter in a small saucepan, add the grated or baked onion, heat briefly without browning, and remove from the heat.","Add the minced beef and fatback, finely chopped cooked dried mushrooms, a splash of mushroom stock, breadcrumbs, 2 eggs, salt, and black pepper to the saucepan, and mix the filling thoroughly.","Knead a moderately soft dough from 500 ml of plain wheat flour, 1 egg, and water, roll it out thinly, and cut into small squares.","Place a portion of filling on each square, moisten the edges with water or egg white, fold in half diagonally into a triangle, and pinch the two opposite corners together to form an ear-shaped dumpling.","Drop the uszka into salted boiling water, cook until they float to the surface, drain, and transfer to a tureen of borscht (for a meatless version, make the filling with dried mushrooms alone and fry the boiled dumplings in clarified butter)."],"time":55,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Uszka_do_barszczu","page":"365 obiadów za 5 złotych/Uszka do barszczu"},{"id":"oc-plwb-21739","title":"Uszka dumplings for borscht (Uszka do barszczu)","cuisine":"European","category":"Side","ingredients":["1 pierogi dough (portion of rolled dough)","500 g cooked or roasted beef (such as from broth)","1 tbsp butter","1 onion","3 dried mushrooms (cooked)","3 tbsp mushroom broth","2 eggs","to taste salt","to taste pepper","1 breadcrumbs (handful)"],"steps":["Pass the cooked beef through a meat grinder or chop it very finely.","Peel and chop the onion, then fry it in a tablespoon of butter.","Add the ground beef, finely chopped cooked mushrooms, and a few tablespoons of mushroom broth to the onion.","Add a handful of breadcrumbs, crack in two eggs, season with salt and pepper, and mix the filling thoroughly.","Cut the thinly rolled dough into small squares, place a teaspoon of filling on each, fold diagonally into a triangle, pinch the edges firmly, and join two opposite corners together.","Cook the uszka in salted boiling water until they float to the surface."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Uszka_do_barszczu","page":"Książka kucharska/Uszka do barszczu"},{"id":"oc-plws-550054","title":"Vanilla liqueur","cuisine":"European","category":"Drink","ingredients":["2.5 l spirit (orig. 2.5 litres of the best spirit)","80 g vanilla pod (orig. 8 dekagrams of vanilla)","3 kg sugar (orig. 3 kilograms of crushed sugar)","1.5 l water (orig. one and a half litres of cold water)"],"steps":["Pour 2.5 l of the best spirit into a demijohn, add 80 g of vanilla pods, cork it tightly, and leave it in a room, in the shade, for 2 weeks.","After 2 weeks, pour the spirit through soft white flannel and filter it through paper.","Bring a syrup to the boil from 3 kg of crushed sugar and 1.5 l of cold water, skim it carefully, and once it is boiling well take it off the heat and cool it completely.","Pour the filtered vanilla spirit into the completely cold syrup, stirring constantly, and leave for 2 hours. Then bottle, cork, seal with wax, and keep in a cool place for 3 months before serving."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_waniliowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier waniliowy"},{"id":"oc-plws-546741","title":"Vegetable pâté baked in crêpes (pasztet z jarzyn w naleśnikach)","cuisine":"European","category":"Main","ingredients":["1 kg mixed soup vegetables: carrots, parsley root, onion, and cabbage","3 dried mushrooms","3 potatoes","30 g fatback (orig. 3 dkg)","1 egg (large, for crêpes)","150 g plain wheat flour (orig. 1 cup)","250 ml water (for crêpe batter)","1 fatback rind (pork rind) (for frying crêpes and greasing baking pan)","to taste salt","to taste black pepper or ground paprika"],"steps":["Boil the mixed vegetables, potatoes, and dried mushrooms until tender (for about 30 minutes, e.g. as a soup broth), then drain and chop finely.","Dice the fatback, render into cracklings, and mix with the chopped vegetables, mushrooms, and potatoes; season with salt and pepper or paprika.","Prepare a batter from the plain wheat flour, egg, water, and a pinch of salt, and fry 10–12 thin crêpes in a pan rubbed with fatback rind.","Grease a shallow saucepan or baking dish with the fatback rind and line it with crêpes so that they hang over the edges.","Fill with the vegetable filling, fold the crêpes over tightly to cover, and bake in an oven preheated to 180 °C for 30 minutes.","Turn the finished pâté out of the mould onto a platter and serve hot."],"time":105,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Pasztet_z_jarzyn_w_nale%C5%9Bnikach","page":"109 potraw/Pasztet z jarzyn w naleśnikach"},{"id":"oc-plwb-21939","title":"Viennese cheesecake in chocolate (Sernik wiedeński w czekoladzie)","cuisine":"European","category":"Cake","ingredients":["500 g farmer's cheese","8 eggs (separated)","1 tbsp icing sugar (heaped)","80 g butter (part for the batter, a little for greasing the tin)","1 vanilla pudding powder (packet)","100 g mixed dried fruit and nuts","200 g dark chocolate","to taste sour cherry preserve (for serving)","to taste breadcrumbs (for dusting the tin)"],"steps":["Pass the farmer's cheese through a mincer three times, beat it with the egg yolks and softened butter, then mix in the vanilla pudding powder and mixed dried fruit and nuts.","Whip the egg whites with a pinch of salt and the icing sugar until stiff, then gently fold into the cheese batter.","Grease a springform tin with butter and dust with breadcrumbs, pour in the batter, and bake in an oven preheated to 170 °C for 75 minutes.","Melt the broken dark chocolate in a water bath and pour it over the baked cheesecake.","Serve slices of the cheesecake with sour cherry preserve."],"time":105,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sernik_wiede%C5%84ski_w_czekoladzie","page":"Książka kucharska/Sernik wiedeński w czekoladzie"},{"id":"oc-plwb-17748","title":"Vilnius-style cold sorrel soup (Wileńska zupa szczawiowa)","cuisine":"European","category":"Soup","ingredients":["500 g fresh sorrel","1 bunch chives","1 bunch fresh dill","2 clove garlic","250 ml thick sour cream","to taste salt","4 eggs","to taste water (boiling water for cooking the sorrel)"],"steps":["Wash the fresh sorrel, chop it finely, simmer for 2–3 minutes in lightly salted boiling water, and let cool.","Boil the eggs until hard, cool, peel, and cut into quarters.","Peel and chop the garlic, mash it with salt, and add to the cooled sorrel.","Wash and finely chop the dill and chives, add to the soup, pour in the thick sour cream, mix thoroughly, and chill in the refrigerator.","Serve the chilled soup topped with the hard-boiled egg quarters."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wile%C5%84ska_zupa_szczawiowa","page":"Książka kucharska/Wileńska zupa szczawiowa"},{"id":"oc-plws-451187","title":"Walnut cream for tortes","cuisine":"European","category":"Sauce","ingredients":["500 ml double cream (36%) (orig. half a litre)","150 g icing sugar (orig. 15 deka)","150 g ground walnuts (orig. 15 deka)"],"steps":["Pound the walnuts finely in a mortar, or grind them.","Whip the thick, chilled cream to a stiff foam.","Fold the icing sugar and the ground walnuts gently into the whipped cream, and use it at once to fill torte layers generously."],"time":15,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/Ciasta_wielkanocne/Krem_orzechowy","page":"Ciasta wielkanocne/Krem orzechowy"},{"id":"oc-plwb-20374","title":"Walnut glaze (Polewa orzechowa)","cuisine":"European","category":"Other","ingredients":["125 g baking margarine","4 tbsp sugar","2 tbsp honey","200 g walnuts (chopped)","1 tbsp water"],"steps":["Pour a tablespoon of water into a pot, add the sliced margarine, sprinkle in the sugar, and add the honey.","Heat the ingredients over low heat, stirring until the sugar has completely dissolved.","Stir in the chopped walnuts towards the end of cooking, heat together briefly, and mix thoroughly."],"time":15,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Polewa_orzechowa","page":"Książka kucharska/Polewa orzechowa"},{"id":"oc-plws-38757","title":"Warm creamed horseradish sauce with egg yolks","cuisine":"European","category":"Sauce","ingredients":["3 horseradish root (orig. several roots)","3 tbsp sour cream","1 tsp sugar","0.5 tbsp plain wheat flour","1 tsp lemon juice (orig. a little)","2 egg yolks","to taste salt"],"steps":["Peel the horseradish roots and grate them on a fine grater.","Transfer the grated horseradish to a small saucepan, add the sour cream, sugar, and wheat flour, beat vigorously, drizzle with lemon juice, and bring to a boil.","Take the saucepan off high heat, whisk in the egg yolks, and warm briefly while stirring constantly (without letting it boil), then season with salt to taste and serve."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Chrzan_ze_%C5%9Bmietan%C4%85","page":"365 obiadów za 5 złotych/Chrzan ze śmietaną"},{"id":"oc-plwb-6262","title":"Warm garlic roux sauce","cuisine":"European","category":"Sauce","ingredients":["40 g lard","40 g plain flour","2 clove garlic","500 ml broth","to taste vinegar","to taste salt","to taste black pepper"],"steps":["Melt the lard in a saucepan, stir in the flour, and prepare a light roux.","Add the finely chopped garlic and fry briefly.","Pour in the broth, whisk the roux until smooth, season with salt, and simmer for several minutes until thickened.","Finally, season the sauce to taste with black pepper and a splash of vinegar."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_czosnkowy","page":"Książka kucharska/Sos czosnkowy"},{"id":"oc-plwb-19197","title":"Warm pickle sauce","cuisine":"European","category":"Sauce","ingredients":["150 g fermented pickles","250 ml meat broth","60 ml pickle brine","35 g lard","60 ml sour cream","1 egg yolk","1 tbsp plain flour (heaped)","to taste salt","to taste black pepper"],"steps":["Melt the lard in a saucepan, stir in the flour, make a roux, and whisk in the cold meat broth.","Dice the fermented pickles, simmer gently in the pickle brine, then combine with the whisked roux and bring to a boil.","Whisk the egg yolk with the sour cream, stir into the sauce, and season to taste with salt and pepper."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_og%C3%B3rkowy","page":"Książka kucharska/Sos ogórkowy"},{"id":"oc-plwb-18667","title":"Warm turkey salad with tender vegetables","cuisine":"European","category":"Salad","ingredients":["300 g turkey breast","150 g plain yogurt (small container)","4 carrots","1 kohlrabi (large)","150 g green beans","1 lettuce","to taste parsley leaves","1 tbsp lemon juice","2 tbsp vegetable oil","to taste salt","to taste black pepper"],"steps":["Wash and peel the carrots and kohlrabi, trim the green beans, chop the vegetables into bite-sized pieces, and cook in salted boiling water for about 3 minutes, then drain and cool.","Cut the turkey breast into thin strips, sear in heated oil, and season with salt and black pepper.","Whisk the plain yogurt with the lemon juice and chopped parsley leaves, and season with salt and black pepper.","Arrange the washed lettuce leaves on a platter, top with the cooled vegetables and turkey strips, and drizzle with the yogurt dressing."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Indyk_z_warzywami","page":"Książka kucharska/Indyk z warzywami"},{"id":"oc-plws-544484","title":"Watermelon Rind in Syrup","cuisine":"European","category":"Preserve","ingredients":["500 g watermelon rind (white layer of watermelon trimmed of the green skin and pink flesh)","1 kg sugar (in lumps for the syrup plus a little fine sugar for dusting)","2.5 lemon (juice of 0.5 lemon for the cold water and grated zest and juice of 2 lemons for the syrup)","375 ml water (1.5 glasses for the syrup, plus cold and boiling water for parboiling the rind)"],"steps":["Trim the white layer of watermelon rind of its green outer skin and pink flesh, submerge in cold water with the juice of half a lemon, then cut into even squares or strips and parboil in boiling water until it begins to soften.","Rub the zest of 2 lemons onto the sugar lumps (1 kg), chop the sugar, place in a stoneware pan, pour in 375 ml (1.5 glasses) of water, and boil a thick syrup with the juice of the 2 lemons.","Add the parboiled watermelon rind to the boiling syrup and simmer very slowly over low heat, skimming thoroughly.","During cooking, remove the pan from the heat several times and lightly dust the fruit on top with fine sugar; cool the finished preserve and transfer to jars."],"time":100,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Kawon","page":"Doświadczone sekreta smażenia konfitur i soków/Kawon"},{"id":"oc-plws-543717","title":"Watermelon Rind Preserves with Ginger","cuisine":"European","category":"Preserve","ingredients":["500 g white watermelon rind (trimmed; orig. half a kilogram)","1000 g sugar (orig. a kilogram)","to taste ginger (for generous sprinkling; amount not specified)","to taste white pepper (for sprinkling; amount not specified)","to taste water (for parboiling and preparing the syrup; amount not specified)"],"steps":["Trim the white part of the watermelon rind and cut it into oblong pieces.","Drop the pieces into boiling water and parboil, leaving them still slightly firm.","Drain them on a sieve.","Trim the pieces to an even shape and arrange them on a platter.","Sprinkle generously with ginger and white pepper.","Leave for 1440 minutes.","Prepare a clear syrup from 1000 g of sugar and water.","Pour the cooled syrup over the watermelon rind.","For the next three days, repeat pouring off, straining through muslin, boiling, and cooling the syrup before pouring it over the fruit again.","When the syrup is sufficiently thick, place the watermelon rind into the boiling syrup and bring to a boil once.","Remove the watermelon rind pieces and leave them to cool.","Arrange the watermelon rind in jars.","Pour the cooled, clarified syrup over it."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Arbuz_z_imbierem","page":"Doświadczone sekreta smażenia konfitur i soków/Arbuz z imbierem"},{"id":"oc-plws-547971","title":"White cabbage and apple slaw (surówka z kapusty i jabłka)","cuisine":"European","category":"Salad","ingredients":["400 g white cabbage (orig. 40 dkg sugar cabbage)","1 tart apple (Antonówka)","1 tsp citric acid","1 tbsp water (to dissolve citric acid)","1 tbsp sugar","1 tbsp vegetable oil","to taste salt"],"steps":["Shred the white cabbage very finely, and peel and grate or equally finely shred the Antonówka apple.","Combine the cabbage with the apple, season with salt, and sprinkle with sugar.","Dissolve the citric acid in 1 tbsp of water, pour over the salad together with the vegetable oil, and toss thoroughly.","Cover the dish and set aside for 6 hours (360 minutes) to let the cabbage soften and absorb the seasonings before serving."],"time":375,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Sur%C3%B3wka_z_kapusty_z_jab%C5%82kiem","page":"109 potraw/Surówka z kapusty z jabłkiem"},{"id":"oc-plwb-16263","title":"White cabbage and apricot salad (Sałatka z morelami)","cuisine":"European","category":"Salad","ingredients":["300 g white cabbage","2 apples","200 g apricots from compote (drained)","50 g dried prunes","50 g dried apples","1 lemon (juiced)","2 tbsp olive oil","3.5 tbsp apricot compote liquid (reserved from the fruit)","to taste cayenne pepper","to taste salt","to taste parsley leaves (chopped)"],"steps":["Soak the prunes and dried apples in apricot compote liquid until softened, then cut them and the apricots from the compote into smaller pieces.","Finely shred the white cabbage, cut the fresh apples into thin quarter-slices, and combine with the fruit.","Mix the lemon juice with the olive oil, 3–4 tbsp of apricot compote liquid, salt, and a pinch of cayenne pepper.","Pour the prepared dressing over the salad, toss thoroughly, and sprinkle with chopped parsley leaves."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_morelami","page":"Książka kucharska/Sałatka z morelami"},{"id":"oc-plws-543011","title":"White cabbage with mutton","cuisine":"European","category":"Main","ingredients":["3 white cabbage (3–4 heads; orig. 3–4 heads)","2 mutton breasts","to taste salt","to taste black pepper","15 ml wheat flour (orig. 1 tbsp)","15 ml butter (orig. 1 tbsp)","to taste mutton cooking broth (for pouring over the cabbage; reserve the broth obtained from parboiling the mutton breasts)"],"steps":["Remove the outer leaves of the cabbage.","Cut the cabbage heads into quarters.","Boil the cabbage in salted water for 15 minutes.","Drain the cabbage.","Parboil the mutton breasts in water until half tender, reserving the broth.","Rinse the meat with cold water.","Skim the fat from the broth.","Cut the mutton into pieces.","Arrange alternating layers of cabbage and mutton in a casserole, finishing with cabbage.","Season the top with salt and pepper.","Pour the mutton broth over the layers.","Braise, covered.","At 60 minutes before serving, brown the flour in the butter.","Add the roux to the cabbage.","Braise until tender, cooking off the excess liquid."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Kucharka_litewska_(1913)/Kapusta_bia%C5%82a_z_baranin%C4%85_lub_flakami","page":"Kucharka litewska (1913)/Kapusta biała z baraniną lub flakami"},{"id":"oc-plws-38749","title":"White lemon sauce for poultry and fish (sos cytrynowy biały)","cuisine":"European","category":"Sauce","ingredients":["1 tbsp butter","1 tbsp plain wheat flour","250 ml poultry broth or fish stock","1 lemon (for juice)","50 ml dry white wine or dried mushroom broth","1 tsp sugar","to taste salt"],"steps":["Melt butter in a saucepan and cook the plain wheat flour to a pale roux without browning.","Whisk the hot poultry broth or fish stock into the roux, stirring until smooth.","Squeeze in the juice of a whole lemon, add white wine or mushroom broth, sugar, and a pinch of salt, bring briefly to a boil, and ladle over the dish."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_cytrynowy","page":"365 obiadów za 5 złotych/Sos cytrynowy"},{"id":"oc-plws-39473","title":"White rice cooked for soups (ryż gotowany na biało do zup)","cuisine":"European","category":"Side","ingredients":["100 g white rice (orig. 1/4 Polish funt)","500 ml water (orig. a pot holding half a Polish kwarta (500 ml), plus water for scalding and soaking)","0.5 tbsp butter","to taste salt"],"steps":["Place the rice in a bowl, pour over hot water, stir, and drain off the cloudy water; repeat the hot water scalding a second time.","Cover the scalded rice with cold water and leave for 60 minutes to make it snow-white, then drain.","Transfer the rice to a half-litre saucepan, cover with warm water, and simmer over low heat for about 15–20 minutes, stirring frequently so it does not scorch.","When the rice begins to soften, add the salt and butter, cook until fully tender, remove from the heat, and serve in the soup tureen or separately on a plate."],"time":90,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ry%C5%BC","page":"365 obiadów za 5 złotych/Ryż"},{"id":"oc-plwb-25779","title":"White sugar glaze","cuisine":"European","category":"Other","ingredients":["2 egg (whites only)","200 g powdered sugar","1 tbsp water (boiled)","0.5 lemon (juiced)"],"steps":["Crack the eggs and separate the whites from the yolks.","Lightly beat the egg whites with a fork, add 200 g of powdered sugar, and stir.","Add 1 tablespoon of boiled water and beat the mixture until smooth.","Pour in the juice from half a lemon and mix the icing thoroughly."],"time":10,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lukier","page":"Książka kucharska/Lukier"},{"id":"oc-plws-544047","title":"White Sweet Cherry Preserves","cuisine":"European","category":"Preserve","ingredients":["500 g white sweet cherries (to be pitted)","1 kg sugar","to taste water (for a very thick syrup; amount not specified, inferred from the source's instruction to prepare the syrup without rose water)","to taste vanilla (piece of a pod wrapped in muslin; the source does not specify the size)"],"steps":["Pit the sweet cherries.","Boil a very thick syrup from the sugar and water.","Wrap a piece of vanilla in white muslin.","Place the wrapped vanilla into the syrup.","Add the sweet cherries to the syrup.","Cook briefly so the fruit does not lose its color.","Set the preserves aside to cool.","Transfer into jars.","Seal the jars tightly."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Czere%C5%9Bnie_bia%C5%82e","page":"Doświadczone sekreta smażenia konfitur i soków/Czereśnie białe"},{"id":"oc-plws-548810","title":"Wild Strawberry Jelly","cuisine":"European","category":"Preserve","ingredients":["1 kg wild strawberries (ripe, for 2 glasses (500 ml) of pressed juice)","250 ml gooseberry juice (freshly pressed)","600 g fine sugar (3 glasses (1 glass of sugar per 1 glass of mixed juice))"],"steps":["Crush the ripe wild strawberries and press the juice through a fine sieve or muslin.","Bring the wild strawberry juice alone to a boil, skim it thoroughly, and strain again through a fine sieve.","Measure 500 ml of the clarified wild strawberry juice, mix with 250 ml of gooseberry juice, and add 600 g of fine sugar.","Place the pan over high heat and bring to a boil three times, removing from the burner and skimming off the foam each time.","Lower the heat and finish cooking the jelly while stirring constantly until it begins to set, then pour hot into warmed jars."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Galareta_poziomkowa","page":"Doświadczone sekreta smażenia konfitur i soków/Galareta poziomkowa"},{"id":"oc-plws-550052","title":"Wild-strawberry liqueur","cuisine":"European","category":"Drink","ingredients":["2 l wild strawberries (ripe and fresh, filling the demijohn to 3/4 of its volume)","1 l spirit (the best, enough to cover the wild strawberries with some to spare)","1 kg sugar (orig. 1 kilogram of crushed sugar per litre of spirit)","500 ml water (orig. half a litre of cold water per litre of spirit)"],"steps":["Fill a good-sized demijohn to 3/4 of its height with fresh ripe wild strawberries, cover them with 1 l of the best spirit so it covers the fruit with some to spare, and leave it for 24 hours.","The next day, pour the spirit off the wild strawberries and filter it through paper (the fruit left behind can be covered with sugar for 8 days, strained without pressing, and combined with plain spirit at 500 ml of spirit per 1 l of juice as a second, lighter liqueur).","Bring a syrup to the boil from 1 kg of crushed sugar and 500 ml of cold water for every litre of filtered spirit, then take it off the heat and cool it completely.","Pour the filtered wild-strawberry spirit into the cold syrup, stirring constantly, leave it for 2 hours, then bottle it, cork it, and keep it in a cool cellar for 6 months before serving."],"time":10,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_poziomkowy","page":"Doświadczone sekreta smażenia konfitur i soków/Likier poziomkowy"},{"id":"oc-plws-552215","title":"Wild-strawberry or raspberry ice","cuisine":"European","category":"Dessert","ingredients":["1000 g ripe wild strawberries or raspberries (fresh, orig. 1 kilogram)","500 g sugar (orig. half a kilogram)","1 l water (orig. 1 litre)","2 lemons (the squeezed juice)","1 tsp alkermes or pomegranate juice (optional, to deepen the colour and the aroma)"],"steps":["Rub fresh ripe wild strawberries or raspberries through a fine sieve.","Bring a syrup to the boil from 500 g of sugar and 1 litre of water, skimming carefully. Squeeze in the juice of two lemons while it cooks, and leave it to cool completely.","Pour the sieved fruit pulp into the cold syrup (and, if you like, a teaspoon of alkermes), mix well, and freeze it in an ice-cream maker (about 2–3 hours)."],"time":190,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Lody_poziomkowe_lub_malinowe","page":"Doświadczone sekreta smażenia konfitur i soków/Lody poziomkowe lub malinowe"},{"id":"oc-plws-39427","title":"Wine sago soup (zupa z sago na winie)","cuisine":"European","category":"Soup","ingredients":["100 g white or red sago pearls (orig. 1/4 Polish funt)","1 l white or red wine (orig. 1 Polish kwarta)","1 l water (orig. 500 ml for wine + 500 ml to boil sago)","300 g sugar (orig. 3/4 Polish funt)","1 lemon (zest for simmering and slices for tureen)","1 cinnamon stick","3 whole cloves (orig. a few cloves)"],"steps":["Scald the sago pearls with hot water, drain in a sieve, and rinse with cold water.","Cover the sago with 500 ml of fresh water and cook over low heat for about 15–20 minutes, stirring constantly until the pearls turn translucent.","In a separate pot, bring the wine to a boil with the remaining 500 ml of water, sugar, lemon zest, cinnamon stick, and cloves.","Add the cooked sago pearls to the hot wine, heat gently together briefly, and ladle into a tureen lined with lemon slices."],"time":40,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sago_na_winie","page":"365 obiadów za 5 złotych/Sago na winie"},{"id":"oc-plwb-12747","title":"Wodzionka (Silesian bread and garlic soup)","cuisine":"European","category":"Soup","ingredients":["2 l water","5 slice stale bread (medium slices)","2.5 clove garlic (2–3 cloves)","80 g homemade lard","to taste salt"],"steps":["Peel the garlic and mash it with salt.","Add the mashed garlic to boiling water with lard, remove the pot from the heat, and season with salt to taste.","Dice the stale bread and add it to the soup immediately before serving.","In variant II (with potatoes), boil 1 kg of potatoes separately, mash them with cracklings made from 50 g of fatback and 1 small onion, arrange on plates in a cone shape, and pour hot wodzianka over them; in a related variant (germuszka), cook down 6 slices of bread in 2 l of water with a teaspoon of caraway and salt, pour in 2 beaten eggs, bring to a boil, and finish with 2 tablespoons of butter."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wodzianka","page":"Książka kucharska/Wodzianka"},{"id":"oc-plwb-6494","title":"Wuzetka (Warsaw chocolate and cream cakes)","cuisine":"European","category":"Cake","ingredients":["8 eggs (for the sponge cake)","200 g granulated sugar (250 ml, for the sponge cake)","7 tbsp all-purpose flour (for the sponge cake)","3 tbsp cocoa powder (for the sponge cake)","1 pinch salt (for the sponge cake)","1 l heavy cream (36% fat) (chilled, for the cream)","2 tsp gelatin (for the cream)","3 tbsp icing sugar (for the cream)","3 tbsp cold water (a few tablespoons, for soaking the gelatin)","to taste blackcurrant jam (for spreading over the sponge layer)","to taste chocolate glaze (preferably dark (or melted dark chocolate with a tablespoon of oil))","to taste soaking syrup for the cake (e.g. strong tea with sugar and vodka, or sugar syrup with rum essence)"],"steps":["Beat the egg yolks with sugar until pale and fluffy, and in a separate bowl beat the egg whites with a pinch of salt until stiff peaks form.","Sift the all-purpose flour and cocoa powder through a sieve and mix.","Gradually fold the beaten yolks into the whipped whites, stirring gently, then add the flour and cocoa in batches and carefully combine.","Transfer the batter to a baking pan (e.g. rectangular approx. 30 × 20 cm lined with parchment paper), place in an oven preheated to 180 °C, and bake for 30 minutes (in an alternative version at 160 °C for 30–40 minutes; it is best to bake the sponge cake one day ahead).","Cut the cooled sponge horizontally with a long knife into two equal layers.","Soak the gelatin in a few tablespoons of cold water, then dissolve it by heating over low heat.","Whip the well-chilled cream, adding the icing sugar and cooled liquid gelatin towards the end of whipping.","Soak the bottom layer with syrup, spread most of the whipped cream (reserving some for decoration), and cover with the second layer.","Soak the top layer, spread it with a thin layer of blackcurrant jam, and coat with dark chocolate glaze (or glaze made of melted dark chocolate with a little oil).","Chill the cake in the refrigerator until the glaze sets, cut into square portions, and decorate each cake with a rosette of the reserved whipped cream."],"time":75,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wuzetki","page":"Książka kucharska/Wuzetki"},{"id":"oc-plws-44935","title":"Wyborny szczupak z rożna (Roast pike in wine and sour cream sauce)","cuisine":"European","category":"Main","ingredients":["1 pike (orig. 1 pike, skinned)","to taste salt","250 ml dry white wine (orig. 1 glass of French white wine)","250 ml sour cream (orig. 1 glass)","1 lemon (whole)","1 tbsp butter (heaped tablespoon)"],"steps":["Skin the pike, clean the fish thoroughly inside, and season with salt.","Brace the fish from the inside with a wooden skewer and tie it in several places with kitchen twine (in the oven, set it on a rack over a roasting pan).","Combine the white wine, sour cream, lemon, and a heaped tablespoon of butter in a small saucepan and heat until very hot.","Roast the pike in an oven preheated to 190 °C (historically on a spit) for about 35–40 minutes, basting frequently with the hot wine-and-cream mixture until the surface cracks slightly and the flesh begins to flake.","Reduce the pan juices collected from roasting over high heat and pour the sauce over the pike arranged on a platter."],"time":65,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Wyborny_szczupak_z_ro%C5%BCna","page":"365 obiadów za 5 złotych/Wyborny szczupak z rożna"},{"id":"oc-plws-553365","title":"Wódka orzechowa (Green walnut liqueur)","cuisine":"European","category":"Drink","ingredients":["1 l rectified spirit (orig. a litre)","8 green walnuts (quartered; orig. eight)","5 cloves (orig. five)","1 cinnamon stick (orig. a stick)","1 kg sugar (crushed; orig. of one kilogram)","500 ml water (cold; orig. half a litre)"],"steps":["Cut the green walnuts into quarters.","Place the walnuts into a glass container with the rectified spirit.","Add the cloves and the cinnamon stick.","Set aside in the shade for 4320 minutes, which is 3 days.","Strain the macerate through a fine cloth.","Bring the sugar and cold water to a boil to make a syrup.","Remove the syrup from the heat after the first boil.","Pour the strained macerate into the hot syrup.","Mix the liquids.","Filter the liqueur through filter paper.","Bottle and seal tightly with corks.","Set aside in a dry and cool place for about 129600 minutes, which is 3 months."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/W%C3%B3dka_orzechowa","page":"Doświadczone sekreta smażenia konfitur i soków/Wódka orzechowa"},{"id":"oc-plws-553359","title":"Wódka „Orange” (Orange and French prune vodka)","cuisine":"European","category":"Drink","ingredients":["2000 ml rectified spirit","1500 ml boiled water","6 green oranges (small and fresh)","500 g dried French prunes (orig. half a kilo; cut into small pieces or halves)"],"steps":["Mix the rectified spirit with the boiled water.","Divide the mixture between two 2 l demijohns.","Place the green oranges into one demijohn.","Cut the dried prunes into small pieces or halves.","Place the prunes into the second demijohn.","Set both demijohns aside in the shade for 4320 minutes.","Filter the contents of both demijohns through filter paper.","Combine both filtered liquids.","Cork the container tightly and set aside in a cool cellar for three months."],"time":null,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/W%C3%B3dka_%E2%80%9EOrange%E2%80%9C","page":"Doświadczone sekreta smażenia konfitur i soków/Wódka „Orange“"},{"id":"oc-plws-1081059","title":"Yeast-Laminated Danish Pastry","cuisine":"European","category":"Other","ingredients":["600 g wheat flour (originally 1.5 funt)","12.5 g fresh yeast (orig. 1 łut)","250 ml milk (cold, originally 1 kwaterka (historical Polish measure))","3 egg yolks (yolks)","2 eggs (whole (1 whole egg for the dough and 1 for brushing the top))","2 tbsp sugar (1 tablespoon for the dough plus coarse sugar for sprinkling)","to taste grated lemon zest","200 g unsalted butter (originally half a funt, squeezed dry and chilled)"],"steps":["Mix the flour with the yeast dissolved in cold milk, add three egg yolks and one whole egg beaten with a tablespoon of sugar along with the lemon zest, knead the dough until air bubbles appear, and set aside in a moderately warm place to rise.","Squeeze the unsalted butter in a cloth, flatten it on a plate, and chill in the refrigerator until firm.","Roll out the risen dough into a square in a cool place, set the slab of butter in the center, and fold the corners of the dough over the center like an envelope.","Roll out the dough carefully and fold it three times, letting it rest for a few minutes between each turn.","Cut out pastries, crescents, or rings from the dough, let rise on a baking sheet, brush with beaten egg, sprinkle with coarse sugar, and bake in a hot oven (200 °C) for about 15–20 minutes."],"time":140,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/Baby%2C_placki_i_mazurki/Ciasto_p%C3%B3%C5%82_francuskie","page":"Baby, placki i mazurki/Ciasto pół francuskie"},{"id":"oc-plwb-18692","title":"Yogurt cake","cuisine":"European","category":"Cake","ingredients":["750 g wheat flour","2 tbsp baking powder","1 tsp baking soda","250 g butter","150 g sugar","6 eggs","250 ml plain yogurt"],"steps":["Whisk the flour with the baking powder and baking soda together in a bowl.","Cream the butter with the sugar and egg yolks, then gradually add the flour mixture alternately with the plain yogurt.","Whip the egg whites until stiff peaks form and gently fold them into the batter.","Transfer the batter to a baking tin and bake for 45 minutes in an oven preheated to 200 °C."],"time":65,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_jogurtowe","page":"Książka kucharska/Ciasto jogurtowe"},{"id":"oc-plws-45184","title":"Young green peas gently cooked in butter","cuisine":"European","category":"Side","ingredients":["600 g freshly shelled green peas (orig. 1 kwarta)","200 g butter (orig. 2 × 1/4 funt (100 g for cooking the peas and 100 g for creaming with flour))","125 ml water (orig. 1 półkwaterek)","2 white onions (sliced)","25 g caster sugar (orig. 2 łuty)","25 g plain wheat flour (orig. 2 łuty)","1 pinch salt"],"steps":["Put the freshly shelled green peas into a two-litre saucepan with 100 g of butter, 125 ml of water, the sliced white onions, a pinch of salt, and the sugar.","Cover the saucepan and cook gently over low heat for 30 minutes.","Cream the remaining 100 g of butter with the wheat flour until smooth, add to the tender peas, and bring briefly to a boil, shaking the saucepan vigorously without stirring with a spoon, until the sauce comes together.","Remove immediately from the heat so the peas keep their bright green colour, and serve."],"time":50,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Groszek_zielony","page":"365 obiadów za 5 złotych/Groszek zielony"},{"id":"oc-plws-39426","title":"Zacierki lub kluski gryczane na mleku (Buckwheat dumplings in milk)","cuisine":"European","category":"Soup","ingredients":["500 ml buckwheat flour (orig. half a historical Polish kwarta)","1 tbsp plain wheat flour","to taste salt","to taste water (hot, several tablespoons for scalding the flour)","to taste milk (boiling, for cooking the dumplings)"],"steps":["Mix the buckwheat flour with a tablespoon of wheat flour and salt in a bowl.","Gradually pour in several tablespoons of hot water at a time, stirring vigorously the whole time, until all the flour is evenly scalded and moistened.","Bring the milk to a boil in a wide saucepan or pot.","Using a metal spoon, quickly drop oblong dumplings of the scalded dough into the boiling milk.","Simmer for a few minutes until the dumplings float to the surface of the milk, then serve immediately."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zacierki_lub_kluski_gryczane_na_ml%C3%A9ku","page":"365 obiadów za 5 złotych/Zacierki lub kluski gryczane na mléku"},{"id":"oc-plwb-18726","title":"Zander on braised leeks (Sandacz na duszonych porach)","cuisine":"European","category":"Main","ingredients":["150 g zander fillet","100 ml whipping cream","1 egg yolk","50 ml white wine","100 g leek","100 g butter","to taste lemon juice","to taste salt","to taste black pepper"],"steps":["Rinse and pat dry the zander portion, season with salt and pepper, and sprinkle with lemon juice.","Wash the leek, slice it into fairly thick rounds, and gently fry in a skillet in melted butter.","Season the leeks with salt and pepper, then pour in the white wine mixed with the 30% fat whipping cream and egg yolk.","Place the fish on the leeks, cover the skillet, and braise gently over low heat for about 10 minutes."],"time":20,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sandacz_na_duszonych_porach","page":"Książka kucharska/Sandacz na duszonych porach"},{"id":"oc-plwb-2689","title":"Zasypywane (layered semolina and fruit cake)","cuisine":"European","category":"Cake","ingredients":["160 g all-purpose flour (250 ml)","200 g white sugar (250 ml)","180 g semolina (250 ml)","1 tsp baking powder","125 g margarine (half a block, straight from the fridge)","1 kg fruit (strawberries, apples, or peaches) (for layering)","to taste cinnamon (optional, for apples or peaches)","to taste fat (for greasing the baking pan)","to taste breadcrumbs (for dusting the baking pan)"],"steps":["Mix the all-purpose flour, sugar, semolina, and baking powder in a separate dish into a uniform dry mixture.","Wash and chop the fruit; if using apples or peaches, preferably coarsely grate them and mix with cinnamon to taste.","Grease a baking pan with fat and dust with breadcrumbs.","Alternate 3 layers of dry mixture with 2 layers of fruit in the pan, starting with a dry layer.","Grate the chilled margarine straight from the fridge and distribute it evenly over the top of the cake.","Bake for 60 minutes in an oven (or for 50 minutes in an electric tabletop oven)."],"time":80,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zasypywane","page":"Książka kucharska/Zasypywane"},{"id":"oc-plwb-16133","title":"Zawijaniec (pork tenderloin roulade with prunes)","cuisine":"European","category":"Main","ingredients":["1 kg pork tenderloin","300 g dried prunes","to taste marjoram","1 orange juice (squeezed from 1 orange)","5 tbsp butter","to taste orange zest (cut)","3 fresh thyme (sprigs, for garnish)","to taste salt","to taste black pepper"],"steps":["Butterfly the pork tenderloin into a 2 cm thick sheet, sprinkle with orange juice, season with salt and pepper, and refrigerate for about 60 minutes.","Rinse the dried prunes and arrange them over the meat.","Roll the meat into a roulade, sprinkle with marjoram, let stand for 10 minutes, then sear on all sides in heated butter.","Wrap the roulade in aluminum foil and bake in an oven preheated to 200 °C for about 50 minutes.","Towards the end of baking, open the foil, place butter shavings and chopped orange zest on top of the meat, and finish baking.","Slice the roasted meat into thick slices and garnish with fresh thyme sprigs."],"time":130,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zawijaniec","page":"Książka kucharska/Zawijaniec"},{"id":"oc-plwb-14461","title":"Zebra cake (Zebra)","cuisine":"European","category":"Cake","ingredients":["4 eggs","300 g sugar (375 ml)","250 ml vegetable oil (250 ml)","400 g all-purpose flour (625 ml, for the base batter)","3 tbsp all-purpose flour (extra for the light batter)","250 ml sparkling water (250 ml)","3 tsp baking powder (level)","3 tbsp cocoa powder (for the dark batter)"],"steps":["Beat whole eggs with sugar until pale and fluffy.","While stirring continuously, gradually add the oil, flour mixed with baking powder, and sparkling water.","Divide the batter into 2 equal parts; mix 3 tablespoons of flour into one part, and 3 tablespoons of cocoa into the other.","Alternately spoon 3 tablespoons of dark and light batter into the center of a springform pan, starting with the dark batter.","Bake for 60 minutes in an oven preheated to 180 °C."],"time":80,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zebra","page":"Książka kucharska/Zebra"},{"id":"oc-plwb-7882","title":"Zesty almond and cucumber mayonnaise sauce","cuisine":"European","category":"Sauce","ingredients":["250 ml mayonnaise (thick)","2 tbsp almonds (heaped)","1 fresh cucumber","2 tbsp ketchup","1 tbsp tomato paste (level)","2 tbsp dill (heaped, chopped)","to taste lemon juice","to taste salt","to taste icing sugar"],"steps":["Scald the almonds with boiling water, remove the skins, and chop very finely or grind in a grinder.","Peel the fresh cucumber, scoop out the seeds, finely dice the flesh, and place on a sieve to drain excess juice.","Combine the mayonnaise with the chopped almonds, ketchup, tomato paste, chopped dill, and drained cucumber.","Season the sauce to taste with lemon juice, salt, and icing sugar, and serve within 30 minutes of preparation."],"time":20,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_majonezowy_pikantny","page":"Książka kucharska/Sos majonezowy pikantny"},{"id":"oc-plws-39725","title":"Zraziki na prędce w śmietance (Quick pounded beef in cream)","cuisine":"European","category":"Main","ingredients":["400 g beef (orig. 1 historical Polish funt of rump or tender roasting beef)","to taste salt","to taste black pepper","1 onion (whole, grated)","1 tbsp plain wheat flour","50 g butter (orig. 4 łuts (1 tablespoon))","200 ml sweet cream (orig. a scant kwaterka of fresh cream)"],"steps":["Cut the beef into walnut-sized pieces, pound each piece very thoroughly with a mallet into fine shreds, and then pound the whole mass together once more.","Season the meat with salt and pepper, add the grated onion, dust with a tablespoon of flour, and mix thoroughly.","Heat the butter in a skillet or shallow pan until it begins to brown, then add the prepared meat.","Sear over high heat for about 5 minutes, stirring vigorously and breaking the meat apart with a spoon to prevent clumping, until it loses its raw colour.","Pour in a scant kwaterka of cream, stir, and bring briefly to a boil, taking care not to cook the meat too long. Serve immediately with separately pan-fried potatoes."],"time":20,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zraziki_na_pr%C4%99dce","page":"365 obiadów za 5 złotych/Zraziki na prędce"},{"id":"oc-plwb-18669","title":"Zraziki z rusztu (grilled minced meat and kiełbasa rolls)","cuisine":"European","category":"Main","ingredients":["500 g minced meat","200 g Polish kiełbasa sausage for grilling","to taste black pepper (coarsely ground)","to taste salt","2 clove garlic","4 onions (1 for the meat mixture, 3 for serving)","2 tbsp vegetable oil","1 tsp all-purpose flour","4 tbsp parsley leaves (chopped)"],"steps":["Skin the kiełbasa, chop it finely, and mix with the minced meat, salt, and coarsely ground pepper.","Peel and chop the onions and garlic; add 1/4 of the chopped onion, garlic, oil, flour, and parsley to the meat, then knead into a uniform mixture.","Scoop small portions of the mixture using a heaped tablespoon and shape into oblong rolls with slightly flattened ends.","Grill the rolls on a preheated grill on each side until browned, and serve with a salad of the remaining onions and tomatoes."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zraziki_z_rusztu","page":"Książka kucharska/Zraziki z rusztu"},{"id":"oc-plws-39681","title":"Zrazy francuskie z polędwicy z pieczarkami (French-style beef tenderloin zrazy with mushrooms)","cuisine":"European","category":"Main","ingredients":["800 g beef tenderloin (orig. 2 historical Polish funts)","1 tbsp butter (a generous tablespoon for the roux plus extra melted butter for coating the meat)","25 g bouillon cake (orig. 2 łuts of bouillon (solid bouillon concentrate))","125 ml water (orig. half a historical Polish kwaterka of water or meat broth)","1 tbsp plain wheat flour","2 onion (sliced into rounds)","to taste salt","to taste black pepper","to taste button mushrooms (fresh, peeled, scalded, and thinly sliced)","to taste potatoes (parboiled and sliced, for lining the bottom of the platter)"],"steps":["Trim the beef tenderloin of membranes, cut into thin cutlets, and pound lightly.","Arrange the cutlets on a platter, pour fresh melted butter over both sides, and let stand for 1 hour.","Dissolve the bouillon concentrate in 125 ml of water (half a historical Polish kwaterka), or use rich meat broth.","Heat a generous tablespoon of butter with a tablespoon of flour in a casserole, thin with the prepared broth, and add the sliced onions.","Lay the beef cutlets in the casserole, season lightly with salt and pepper, and scatter the thinly sliced, scalded button mushrooms on top.","Cover the casserole tightly with a lid and braise over very low heat for a full 2 hours.","Line the bottom of a serving platter with the sliced, parboiled potatoes, arrange the beef cutlets on top, and pour the braising sauce over the dish."],"time":200,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zrazy_francuzkie","page":"365 obiadów za 5 złotych/Zrazy francuzkie"},{"id":"oc-plws-580473","title":"Zrazy nelsońskie z grzybów (vegetarian Nelson casserole with dried mushrooms and potatoes)","cuisine":"European","category":"Main","ingredients":["12 dried mushrooms (large, sound caps, soaked overnight)","to taste water (or milk, for soaking and boiling the mushrooms)","800 g potatoes (peeled, raw)","2 onion (large, thinly sliced)","1 tbsp butter","to taste salt","to taste black pepper","500 ml sour cream (2 cups)"],"steps":["Soak the dried mushrooms overnight in a bowl of water for about 480 minutes, then boil them until tender for 30 minutes and strain the broth.","Cut the raw potatoes into rounds and the onions into thin slices.","Put the butter on the bottom of a casserole or ovenproof dish, then layer the potatoes, whole cooked dried mushrooms, and onions, seasoning each layer lightly with salt and pepper.","Mix the sour cream with the strained mushroom broth and pour over the dish so that the sauce covers it completely.","Cover the dish with a lid, cook gently over very low heat for about 45 minutes until the potatoes are completely tender, and serve in the same dish."],"time":575,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Zrazy_nelso%C5%84skie_z_grzyb%C3%B3w","page":"100 postnych i jarskich dań/Zrazy nelsońskie z grzybów"},{"id":"oc-plws-44947","title":"Zrazy rybne ze szczupaka (Stuffed pike rolls)","cuisine":"European","category":"Main","ingredients":["1 pike (large)","to taste salt","3 onion (orig. several onions, for the stuffing)","to taste butter (for frying the onion)","1 tbsp breadcrumbs (for the stuffing plus extra for breading)","to taste black pepper","2 eggs (1 whole for the stuffing and 1 beaten for breading)","to taste clarified butter (for frying the rolls)"],"steps":["Chop the onions for the stuffing, squeeze out their juice through a clean cloth, chop finely once more, and sauté in hot butter.","Mix the cooled onion with a tablespoon of breadcrumbs, a pinch of pepper, and one whole egg.","Split the pike lengthwise, bone it, cut into thin slices, and season lightly with salt.","Place a portion of the onion stuffing on each slice of fish and roll up tightly like beef rolls.","Dip the rolls in beaten egg and coat in breadcrumbs, then fry in clarified butter for about 10–12 minutes until golden brown."],"time":55,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zrazy_rybne","page":"365 obiadów za 5 złotych/Zrazy rybne"},{"id":"oc-plws-39710","title":"Zrazy wołowe duszone w wywarze grzybowym (Braised beef zrazy in dried mushroom broth)","cuisine":"European","category":"Main","ingredients":["800 g beef (orig. a couple of historical Polish funts of beef suitable for zrazy)","to taste salt","to taste black pepper","to taste plain wheat flour (for dusting the cutlets)","to taste butter (for browning and braising)","4 tbsp mushroom broth (orig. several tablespoons of dried mushroom stock or meat broth)"],"steps":["Cut the beef into thin cutlets, season with salt and pepper, and dust each piece with wheat flour.","Heat and brown the butter in a casserole, put in the beef cutlets, and braise covered over low heat for 30 minutes.","Pour in several tablespoons of dried mushroom broth or meat stock and continue braising for about 15 minutes, until the sauce thickens and the liquid reduces away, leaving the fat, then serve."],"time":60,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zrazy_ze_%C5%9Bmietan%C4%85","page":"365 obiadów za 5 złotych/Zrazy ze śmietaną"},{"id":"oc-plws-39695","title":"Zrazy wołowe siekane w sosie śmietanowym (Minced beef zrazy in sour cream sauce)","cuisine":"European","category":"Main","ingredients":["1200 g beef (orig. 3 historical Polish funts of good beef)","200 g beef suet (orig. half a historical Polish funt of fresh kidney suet)","1 white wheat roll (whole, soaked)","to taste salt","to taste black pepper","1 onion (grated)","to taste butter (for browning the zrazy)","to taste broth (or stock from bones and soup vegetables, for braising)","1 tbsp sour cream (sour)"],"steps":["Trim the beef of membranes and sinews, scrape with a knife or chop finely together with the fresh kidney suet into a smooth mass (nowadays you can pass it through a mincer).","Add the soaked and squeezed roll, grated onion, salt, and pepper, and knead the mixture very thoroughly.","Shape into large oval patties (zrazy) and brown them on all sides in browned butter for about 10 minutes.","Moisten the browned zrazy with broth or bone-and-vegetable stock, add a tablespoon of sour cream, cover, and braise over low heat for 15 minutes."],"time":55,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zrazy_faszerowane","page":"365 obiadów za 5 złotych/Zrazy faszerowane"},{"id":"oc-plws-580422","title":"Zrazy z kaszy gryczanej nadziewane grzybami (buckwheat zrazy rolls stuffed with mushrooms)","cuisine":"European","category":"Main","ingredients":["300 g buckwheat groats","50 g dried mushrooms (young, or 250 g fresh mushrooms)","to taste water (for boiling the mushrooms to make broth)","to taste salt","2 eggs (1 for the buckwheat mixture and 1 for breading)","to taste plain wheat flour (for binding the buckwheat mixture and thickening the onion sauce)","to taste butter (for the filling, browning the rolls, and the sauce)","2 onion (1 for the mushroom filling and 1 for the onion sauce)","2 tbsp sour cream (for the filling and the sauce)","to taste breadcrumbs (for coating the rolls)"],"steps":["Boil the dried mushrooms in water in a pot for 30 minutes, drain them, and divide the mushroom broth into two equal parts.","Add the buckwheat groats to half of the mushroom broth, season with salt, cook for 20 minutes until very soft, and let cool, then beat in 1 egg and add enough wheat flour to shape into flat patties.","Finely chop the cooked dried mushrooms and 1 onion, fry them in a skillet with butter for 5 minutes, and mix with a little of the sour cream.","Shape the buckwheat mixture into oblong patties, place a portion of the mushroom filling on each, and roll up into zrazy cylinders.","Brush the rolls with the second beaten egg, coat in breadcrumbs, brown on all sides in butter for 5 minutes, and arrange in a deep ovenproof dish.","Fry the second chopped onion in butter with a little wheat flour, stir in the remaining mushroom broth and the rest of the sour cream, pour the sauce over the rolls, and bake in an oven preheated to 180 °C for 5 minutes."],"time":95,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Zrazy_z_kaszy_gryczanej","page":"100 postnych i jarskich dań/Zrazy z kaszy gryczanej"},{"id":"oc-plws-39312","title":"Zupa biała karlsbadzka (Carlsbad white veal and barley soup)","cuisine":"European","category":"Soup","ingredients":["800 g veal (orig. a couple of historical Polish funts of veal (or 1 hen and poultry giblets))","to taste soup vegetables (for the broth)","to taste salt","to taste water (for the broth and the groats)","500 ml pearl barley (orig. half a historical Polish kwarta of spelt groats, pearl barley, oat groats, or rice)","to taste butter (a little for cooking the groats and for frying the croutons)","to taste parsley leaves (chopped, optional for serving)","to taste wheat roll croutons (cubed and fried in butter, optional)"],"steps":["Cover the veal (or hen with poultry giblets) with water, bring to a boil, skim thoroughly, add the soup vegetables and salt, and simmer over low heat for about 2–2.5 hours until a rich broth forms.","In a separate pot, cook the pearl barley, oat groats, or rice in unsalted water with a bit of fresh butter, taking care that it does not scorch and cooks down completely into a thick mass.","Transfer the soft-cooked groats to a sieve and rub them through, moistening with the strained broth until the soup reaches the thickness of split pea soup.","Beat the soup thoroughly with a spoon, bring to a brisk boil, and serve (for healthy diners, garnished with chopped parsley leaves and butter-fried croutons)."],"time":170,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_bia%C5%82a_(karlsbadzka)","page":"365 obiadów za 5 złotych/Zupa biała (karlsbadzka)"},{"id":"oc-plws-39311","title":"Zupa biała z kaszą perłową na podrobach (White pearl barley giblet soup)","cuisine":"European","category":"Soup","ingredients":["to taste poultry giblets (goose or chicken, for the broth)","to taste soup vegetables (for cooking the broth)","to taste water (for the broth and the barley)","to taste salt","250 ml pearl barley (orig. 1 historical Polish kwaterka)","1 tbsp butter (generous tablespoon)","500 ml sour cream (orig. half a historical Polish kwarta)"],"steps":["Simmer a clear broth from the goose or chicken giblets and soup vegetables in salted water, then strain.","In a separate pot, cook the pearl barley until tender, add a generous tablespoon of butter, and beat with a spoon until the mixture turns white.","Stir the sour cream into the barley, thin with the hot broth, bring everything to a boil together, and serve."],"time":90,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_bia%C5%82a","page":"365 obiadów za 5 złotych/Zupa biała"},{"id":"oc-plws-546621","title":"Zupa chlebowa na wywarze jarzynowym (bread soup with vegetable broth)","cuisine":"European","category":"Soup","ingredients":["150 g dry wholemeal bread (orig. 1 full szklanka, measured after grinding)","1.5 l vegetable broth (orig. 1.5 l)","2 bouillon cubes","to taste salt"],"steps":["Finely grind the thoroughly dried wholemeal bread in a meat grinder.","Bring the vegetable broth to a boil, dissolve the bouillon cubes, and season with salt if needed.","Pour the boiling broth over the ground wholemeal bread, stir, and serve immediately."],"time":20,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Zupa_chlebowa","page":"109 potraw/Zupa chlebowa"},{"id":"oc-plws-39052","title":"Zupa cytrynowa (Polish lemon soup)","cuisine":"European","category":"Soup","ingredients":["2 l beef broth (orig. a half-garniec pot of soup (for a meatless version, stock from soup vegetables and dried mushrooms))","500 ml sour cream (orig. half a historical Polish kwarta)","3 egg yolks","1 lemon (large; juice extracted, with a few thin slices optionally reserved for the tureen)","to taste pearl barley (or rice, for thickening the soup)","to taste butter (for cooking the barley or rice)"],"steps":["In a separate pot, cook the pearl barley or rice with butter until soft, then mash thoroughly with a spoon to thicken the soup.","Whisk the sour cream thoroughly with the egg yolks and the juice squeezed from the large lemon.","Temper the sour-cream and egg-yolk liaison with the hot beef broth (or, for a meatless version, stock made from soup vegetables, dried mushrooms, onion, and spices).","Combine the soup with the mashed pearl barley or rice and briefly bring to a boil, taking care not to let the egg yolks curdle. Serve in a tureen with thin slices of lemon."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_cytrynowa","page":"365 obiadów za 5 złotych/Zupa cytrynowa"},{"id":"oc-plws-39079","title":"Zupa grochowa (Grochówka split pea soup)","cuisine":"European","category":"Soup","ingredients":["1 l dried shelled peas (orig. 1 historical Polish kwarta of peas)","3 l water (orig. 3 historical Polish kwarty of soft water)","700 g pork (orig. 1.5–2 historical Polish funts of streaky pork (or a scalded pig's tail, or 1 funt = 400 g of smoked meat))","to taste salt","to taste marjoram (for the tureen)","to taste white wheat roll (cubed for croutons)","to taste butter (for frying the croutons)"],"steps":["Cover the peas with the water and bring to a boil, then add the streaky pork (or scalded pig's tail or smoked meat), season with salt, and simmer over low heat for about 1.5–2 hours until the peas are completely soft.","Remove the cooked meat and press the peas along with their cooking liquid through a fine sieve or colander.","Cut the meat into pieces, return it to the sieved soup, and bring back to a boil.","Cut the wheat roll into small cubes and fry in butter until golden croutons form.","Put the crushed marjoram in the tureen, pour in the hot pea soup, and serve with the croutons."],"time":140,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_grochowa","page":"365 obiadów za 5 złotych/Zupa grochowa"},{"id":"oc-plws-39308","title":"Zupa grzybowa (Polish dried mushroom soup)","cuisine":"European","category":"Soup","ingredients":["10 dried mushrooms (orig. 10 large dried mushrooms for 4–5 people)","to taste water (for cooking the stock)","to taste soup vegetables","2 onion (orig. a couple of whole onions (plus optionally 1 chopped onion for the roux))","2 allspice (orig. a couple of berries)","to taste black pepper","to taste salt","to taste vinegar (optional, for the sour version)","to taste butter (for the roux)","to taste plain wheat flour (for the roux)","to taste hand-cut noodles (oblong noodles or fine groats rubbed with beaten egg)"],"steps":["Scald the dried mushrooms with boiling water, wash thoroughly, cover with cold water, and set over the heat.","Once the mushrooms have parboiled slightly, add the soup vegetables, peeled whole onions, allspice, and pepper, and simmer over low heat for about 45 minutes until the mushrooms are completely tender.","Strain the stock through a sieve, remove the cooked mushrooms, slice them into thin strips, and return them to the clear stock.","Season the soup with salt, add good vinegar to taste for the sour version, and thicken with a butter-and-flour roux, optionally including sautéed onion.","Bring the soup to a boil and cook the oblong hand-cut noodles in it (or, for the mild version, add fine groats rubbed with beaten egg). Season in the tureen with freshly ground pepper and serve."],"time":80,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_grzybowa","page":"365 obiadów za 5 złotych/Zupa grzybowa"},{"id":"oc-plwb-61671","title":"Zupa gulaszowa (Hungarian goulash soup)","cuisine":"European","category":"Soup","ingredients":["500 g pork (e.g. shoulder, ham, collar, or sirloin)","500 g beef (e.g. shoulder, round, rump, or chuck)","3 potatoes (medium)","2 carrots (medium)","1 parsley root (larger)","1 red bell pepper (large)","1 onion (large (or leek))","400 g tomato passata (or canned chopped tomatoes)","3 tbsp tomato paste","4 clove garlic (large cloves, pressed)","1250 ml water (5 glasses (or vegetable or meat broth))","3 tbsp vegetable oil (or lard, for searing)","1 tbsp ground sweet paprika","1 tsp dried thyme","1 tsp dried oregano","0.5 tsp ground black pepper","0.5 tsp ground hot paprika","1 tsp salt (about 1 teaspoon)"],"steps":["Dice the pork and beef, sear in the hot oil or lard for about 5 minutes, and transfer to a bowl.","In the same fat, fry the chopped onion or leek, then add the garlic, chopped carrots, parsley root, and red bell pepper, and fry together for about 10 minutes.","Add the seared meat, pour in 1250 ml (5 glasses) of water or broth, and add the sweet and hot paprika, salt, thyme, oregano, and pepper.","Cook the soup covered over low heat for 90 minutes.","Add the tomato passata or canned tomatoes, tomato paste, and peeled diced potatoes.","Cook covered for another 30 minutes until the potatoes and meat are tender; serve with bread, optionally sprinkled with fresh herbs."],"time":160,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_gulaszowa","page":"Książka kucharska/Zupa gulaszowa"},{"id":"oc-plwb-25764","title":"Zupa jarzynowa (Traditional Polish vegetable soup)","cuisine":"European","category":"Soup","ingredients":["500 ml meat broth","1 bunch Polish soup vegetables (włoszczyzna) (bunch)","2 carrots","50 g beans","100 g potatoes","50 g Brussels sprouts","1 tsp tomato paste","1 tsp sour cream","0.5 tsp wheat flour","0.5 tsp butter (fat for the soup)","to taste salt"],"steps":["Clean, wash, and chop the soup vegetables, additional carrots, beans, and Brussels sprouts.","Pour the meat broth over the vegetables, season with salt, and bring to a boil.","Peel the potatoes, cut into cubes, drop into the simmering soup, and cook until all vegetables are tender.","Mix the tomato paste with the sour cream and flour, pour into the soup, and boil briefly.","Stir in the fat at the end and season to taste with salt (in a second variation, the soup can be prepared from frozen vegetables with Brussels sprouts in chicken broth with meatballs made from 200 g raw white kiełbasa and chopped greens)."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_jarzynowa","page":"Książka kucharska/Zupa jarzynowa"},{"id":"oc-plws-546622","title":"Zupa jarzynowa z kluskami kładzionymi bez jaj (vegetable soup with eggless drop dumplings)","cuisine":"European","category":"Soup","ingredients":["2 l vegetable stock","120 g plain wheat flour (orig. 12 dkg)","60 g butter or lard (orig. 6 dkg)","60 ml cold water (to reach drop dumpling batter consistency)","1.5 tsp baking powder (orig. 1/2 packet baking powder)","1 bunch dill (fresh, salted, or dried)","to taste salt"],"steps":["Beat the butter or lard until fluffy, stir in the plain wheat flour, and continue beating while adding cold water teaspoon by teaspoon until a soft drop-dumpling dough forms.","Stir in the baking powder and a pinch of salt, and mix thoroughly.","Bring the vegetable stock to a boil and drop small portions of the dough into the simmering soup using a teaspoon.","Simmer the dumplings gently for about 8–10 minutes until they all float to the surface and are tender, then ladle the soup into a tureen over the chopped dill."],"time":35,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Zupa_z_k%C5%82adzionymi_kluskami","page":"109 potraw/Zupa z kładzionymi kluskami"},{"id":"oc-plwb-19319","title":"Zupa jarzynowa z rzodkwią (Vegetable soup with white radish and bacon)","cuisine":"European","category":"Soup","ingredients":["300 g carrots","200 g white radish","3 leeks","2 onions","2 potatoes","150 g smoked bacon","30 g butter","2 bay leaves (leaves)","1 l broth","1 pinch thyme","1 bunch parsley (bunch)","to taste salt","to taste pepper"],"steps":["Clean, wash, and cut the carrots, leeks, onions, and white radish into sizeable pieces, then cook them gently covered in the butter for 15 minutes.","Pour in the broth, add the bay leaves, thyme, salt, and pepper, and cook for about 20 minutes until the vegetables soften.","10 minutes before the end of cooking, toss in the peeled and finely diced potatoes.","Cut the smoked bacon into strips, fry in a pan, and add to the cooked soup.","Garnish the soup with finely chopped parsley before serving."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_jarzynowa_z_rzodkwi%C4%85","page":"Książka kucharska/Zupa jarzynowa z rzodkwią"},{"id":"oc-plwb-16256","title":"Zupa kremowa z brokułów (Cream of broccoli soup)","cuisine":"European","category":"Soup","ingredients":["500 g broccoli","1.5 tbsp olive oil","1 onion","2 clove garlic (cloves)","750 ml meat broth (3/4 l meat broth)","1 sour cream (tub)","1 tsp dried dill","to taste salt","to taste pepper"],"steps":["Clean the broccoli, separate it into florets, and cut the stalks into smaller pieces.","Peel and chop the onion and garlic, then fry them in heated olive oil in a large pot.","Place the broccoli into the pot, pour in the meat broth, bring quickly to a boil, then reduce heat and cook gently covered for 5 minutes.","Strain the soup through a sieve, reserving the broth, transfer the drained broccoli to a bowl, add the sour cream, and blend until smooth.","Combine the blended broccoli purée with the broth, season with dried dill, salt, and pepper, and bring to a boil (in a second variation, the soup can be prepared with 300 g broccoli cooked in 1 l chicken broth with the addition of 100 g blue cheese, 50 ml whipping cream (36% fat), and cheese croutons)."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_kremowa_z_broku%C5%82%C3%B3w","page":"Książka kucharska/Zupa kremowa z brokułów"},{"id":"oc-plwb-6267","title":"Zupa kremowa z pieczarek (Cream of mushroom soup)","cuisine":"European","category":"Soup","ingredients":["250 g button mushrooms","2 tbsp wheat flour (level)","500 ml milk","500 ml water","2 tbsp sour cream (thick)","60 g butter","to taste salt","to taste pepper","to taste citric acid (dissolved in a little water, for sprinkling over the mushrooms and seasoning)"],"steps":["Clean, wash, and thoroughly dry the button mushrooms in a cloth, then chop them very finely.","Transfer the chopped mushrooms to a bowl and sprinkle with dissolved citric acid so they do not darken.","Melt the butter in a pressure cooker, add the mushrooms, and cook gently covered for 4–5 minutes, taking care that they do not brown.","Sprinkle the mushrooms with the flour, stir, pour in the water, and season with salt and pepper.","Close the pressure cooker and cook for 5 minutes from the moment full pressure is reached.","Open the pressure cooker after the pressure drops and slowly pour in the milk until the desired consistency is reached.","Enrich the soup with the thick sour cream and season to taste with citric acid; blend into a smooth cream if needed."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_kremowa_z_pieczarek","page":"Książka kucharska/Zupa kremowa z pieczarek"},{"id":"oc-plwb-18503","title":"Zupa leśna (Polish forest mushroom soup)","cuisine":"European","category":"Soup","ingredients":["400 g bay boletes","500 g potatoes","2 bay leaves (leaves)","4 allspice (berries (several berries))","5 black peppercorns (peppercorns (several peppercorns))","1 tsp ground caraway","250 ml sour cream (thick)","500 ml milk","2 tbsp wheat flour","4 egg yolks","to taste salt","to taste pepper","0.5 bunch dill (half a bunch)","500 ml water (for the spice broth)"],"steps":["Clean and slice the bay boletes, and peel and dice the potatoes.","Boil 500 ml of water with the bay leaves, allspice, black peppercorns, and ground caraway, then strain the spiced broth.","Place the potatoes and mushrooms in a saucepan, pour the strained spiced broth over them, and cook over low heat until tender.","Whisk the flour into the milk, blend with the sour cream, slowly pour into the soup, and simmer until thickened.","Salt the soup and season with pepper to taste, then add the egg yolks, quickly whisk them into the soup, and remove the saucepan from the heat just as it starts to simmer.","Sprinkle the soup with chopped dill and serve with croutons or rye bread."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_le%C5%9Bna","page":"Książka kucharska/Zupa leśna"},{"id":"oc-plws-39375","title":"Zupa migdałowa (Polish Christmas Eve almond soup)","cuisine":"European","category":"Soup","ingredients":["400 g sweet almonds (orig. 1 historical Polish funt)","5 bitter almonds (orig. 5 almonds)","2 l water (orig. 2 historical Polish kwarty of boiled water)","to taste milk (for sprinkling the almonds and cooking the rice (replaced with water for a strictly vegan fast))","250 g icing sugar (orig. 0.5–0.75 historical Polish funt (200–300 g) of fine sugar)","to taste rice (cooked until fluffy, for serving)","to taste cinnamon (for the rice)","to taste raisins (seedless, for the rice)"],"steps":["Blanch the sweet and bitter almonds in boiling water, remove their skins, and pound in a mortar or blend into a smooth paste, sprinkling with a little water or milk as you go to prevent the oil from separating.","Pour two kwarty (2 l) of boiled water over the almond paste, stir thoroughly, and wring out firmly through a fine sieve or clean cloth.","Pound the almond pressings a second time, moisten with part of the strained liquid or a little water, and wring out through the cloth again.","Stir the fine sugar into the resulting almond milk until completely dissolved.","Separately cook the rice until fluffy in milk (or water for a strictly meatless fast) with sugar, cinnamon, and raisins, spoon it into a tureen, pour the almond soup over it, and serve warm or cold."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_migda%C5%82owa","page":"365 obiadów za 5 złotych/Zupa migdałowa"},{"id":"oc-plwb-61664","title":"Zupa mleczna (Polish milk soup with drop noodles)","cuisine":"European","category":"Soup","ingredients":["750 ml milk (3 glasses)","2 eggs (medium)","5 tbsp wheat flour (level (in gluten-free version: gluten-free oat flour))","1 pinch salt (optional (in sweet version: 1 tsp vanilla sugar, honey, or syrup))"],"steps":["Place 5 level tablespoons of wheat flour (or gluten-free oat flour) into a bowl, crack in the eggs, and whisk with a fork, whisk, or blender into a smooth batter.","Bring the milk to a boil in a saucepan; in the sweet version add a teaspoon of vanilla sugar, honey, or syrup, and in the savoury version a pinch of salt.","Pour the batter in a thin stream into the gently simmering milk, without stirring right away, so the drop noodles keep their shape and puff up.","When the noodles float to the surface and become fluffy, stir everything, cook for another 1–1.5 minutes, and serve immediately."],"time":10,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_mleczna","page":"Książka kucharska/Zupa mleczna"},{"id":"oc-plws-39428","title":"Zupa nic na mleku (Floating island milk soup Zupa nic)","cuisine":"European","category":"Soup","ingredients":["2 l milk (orig. half a garniec of unskimmed milk)","6 egg yolks","250 g sugar (orig. 1 glass of sugar for the yolks plus a couple of tablespoons for the whites)","to taste cinnamon (pounded, or vanilla)","6 egg whites (beaten to stiff peaks for the meringues)","to taste rice (cooked separately with sugar and cinnamon, for serving in the tureen)"],"steps":["Beat 6 egg yolks vigorously with a glass of sugar until pale and fluffy.","Set the milk over the heat and, stirring constantly, pour in the beaten yolks in a thin stream.","Heat over low heat for a few minutes until the soup thickens, taking care not to let it boil lest the yolks curdle.","Strain the hot soup into a tureen, dust with ground cinnamon or vanilla, and leave in a cool place until completely cold.","Beat the egg whites to stiff peaks, fold in two tablespoons of sugar and a touch of cinnamon, drop small spoonfuls onto a paper-lined baking sheet, and dry in an oven preheated to 120 °C for 10 minutes.","Place the separately cooked and cooled sweet rice in the tureen, pour the chilled soup over it, and float the baked meringue puffs on top."],"time":45,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_zwana_nic_na_ml%C3%A9ku","page":"365 obiadów za 5 złotych/Zupa zwana nic na mléku"},{"id":"oc-plwb-6268","title":"Zupa pieczarkowa (Polish mushroom soup)","cuisine":"European","category":"Soup","ingredients":["2 l vegetable broth","250 ml sour cream","500 g button mushrooms","2 tbsp butter","2 tbsp wheat flour","to taste salt","to taste black pepper","to taste parsley leaves (chopped)"],"steps":["Clean and rinse the button mushrooms, then slice them or cut into strips.","Sauté the mushrooms in melted butter, transfer to a pot, pour in the broth, and simmer over medium heat for about 15 minutes.","Thoroughly mix the sour cream with the flour, temper with a little hot broth, and stir into the soup until it comes to a boil.","Season the soup with salt, pepper, and chopped parsley leaves."],"time":40,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pieczarkowa","page":"Książka kucharska/Pieczarkowa"},{"id":"oc-plwb-13744","title":"Zupa piwna po staropolsku (Traditional Old Polish beer soup)","cuisine":"European","category":"Soup","ingredients":["1 l beer (4 glasses)","3 egg yolks","4 tbsp sugar","125 ml sour cream (half a glass)","250 g farmer's cheese","4 cloves (a few)","1 pinch cinnamon"],"steps":["Beat the egg yolks with the sugar until pale and fluffy, then slowly pour in the sour cream, whisking continuously.","Place the pot with the egg and sour cream mixture over low heat and pour in the beer in a thin stream, stirring constantly.","Season the soup with the cloves and a pinch of cinnamon, and heat over low heat until it begins to thicken.","Cut the farmer's cheese into small cubes, arrange several pieces in bowls, and ladle the warm beer soup over them."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_piwna_po_staropolsku","page":"Książka kucharska/Zupa piwna po staropolsku"},{"id":"oc-plwb-20845","title":"Zupa pomidorowa (Traditional Polish tomato soup)","cuisine":"European","category":"Soup","ingredients":["1 l chicken broth (chicken)","7 tomatoes (6–8 medium tomatoes)","1 tbsp butter (or olive oil)","1 white bread roll (crust removed or half a glass of breadcrumbs (optional, for thickening))","250 g rice (or pasta, for serving)"],"steps":["Wash the tomatoes, peel off skins (if you will not be passing them through a sieve), cut into quarters, and remove the seeds.","Melt the butter or heat the olive oil in a heavy-bottomed saucepan (optionally fry finely chopped garlic or onion in it).","Add the tomatoes along with the cubed crustless bread roll and cook over low heat for 30 minutes, adding a little broth if necessary.","Purée the cooked tomatoes through a fine sieve or blend on low speed.","Combine the tomato purée with the remaining broth and bring to a boil (according to traditional recipes, you can add half a glass of white wine near the end of cooking to enhance flavour).","Serve the soup with separately cooked rice, pasta, or butter-fried croutons."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_pomidorowa","page":"Książka kucharska/Zupa pomidorowa"},{"id":"oc-plws-39051","title":"Zupa pomidorowa klarowna (Clear tomato soup with white wine)","cuisine":"European","category":"Soup","ingredients":["to taste meat broth (good, clear)","7 tomatoes (orig. 6–8 tomatoes depending on size)","to taste butter (for stewing the tomatoes and frying the croutons)","to taste white wheat roll (cubed crumb for the tomatoes plus croutons for serving)","125 ml dry white wine (orig. half a glass)"],"steps":["Cut the tomatoes into several pieces, remove the seeds, and place in a saucepan with melted butter.","Add the cubed bread crumb and cook the tomatoes gently over low heat for 30 minutes.","Press and strain the cooked tomatoes through a very fine sieve.","Combine the tomato purée with the hot broth, pour in half a glass of white wine, heat briefly, and serve with butter-fried croutons."],"time":50,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_pomidorowa_klarowna","page":"365 obiadów za 5 złotych/Zupa pomidorowa klarowna"},{"id":"oc-plwb-21696","title":"Zupa poziomkowa (Wild strawberry soup)","cuisine":"European","category":"Soup","ingredients":["2 l wild strawberries","500 ml water","250 g icing sugar","500 ml sour cream (thin)","250 ml white wine (1 glass)"],"steps":["Gently wash the wild strawberries and press them through a fine sieve, gradually pouring in the water.","Add the icing sugar, thin sour cream, and white wine to the strained purée, and mix thoroughly.","Warm the soup over medium heat, taking care not to bring it to a boil.","Serve with rusks, choux pastry puffs, Polish obwarzanki, or croutons soaked in cream and fried in butter."],"time":25,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_poziomkowa","page":"Książka kucharska/Zupa poziomkowa"},{"id":"oc-plws-39376","title":"Zupa poziomkowa (Wild strawberry soup)","cuisine":"European","category":"Soup","ingredients":["2 l wild strawberries (orig. half a garniec of rinsed wild strawberries)","500 ml water (orig. half a historical Polish kwarta)","200 g icing sugar (orig. half a historical Polish funt of fine sugar)","500 ml sour cream (orig. half a historical Polish kwarta of thin sour cream)","250 ml white wine (orig. 1 glass of light white wine)","to taste wheat roll croutons (soaked in sweet cream and fried in butter (or scalded obwarzanki rings), for serving)"],"steps":["Press the rinsed wild strawberries through a fine sieve, moistening them as you go with half a kwarta (500 ml) of water.","Stir the fine sugar into the wild strawberry purée, pour in the sour cream and a glass of light white wine, and mix thoroughly.","Set the soup over the heat and warm thoroughly for about 5 minutes, taking care not to let it boil.","Serve with croutons soaked in sweet cream and fried in butter, or with scalded bread rings (obwarzanki)."],"time":25,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_poziomkowa","page":"365 obiadów za 5 złotych/Zupa poziomkowa"},{"id":"oc-plwb-56169","title":"Zupa rybna z włoszczyzny (Polish freshwater fish and vegetable soup)","cuisine":"European","category":"Soup","ingredients":["750 g freshwater fish (bream or pike (including heads and backbones))","150 g Polish soup vegetables (włoszczyzna)","2.5 l water (cold)","150 g sour cream","25 g wheat flour","0.1 g black pepper","0.2 g allspice","to taste parsley (chopped)","to taste salt"],"steps":["Clean and rinse the fish, separate fillets, and place the meat along with heads, backbones, and chopped soup vegetables into a pot and pour in 2.5 l of cold water.","Simmer the stock over low heat for about 45 minutes, then strain thoroughly.","Whisk the wheat flour into the sour cream, stir into the strained stock, season with pepper, allspice, and salt, and bring briefly to a boil.","Sprinkle the soup with chopped parsley before serving; serve with fish dumplings, noodles, square pasta (łazanki), or firm groat cubes."],"time":70,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_rybna_z_w%C5%82oszczyzny","page":"Książka kucharska/Zupa rybna z włoszczyzny"},{"id":"oc-plwb-18248","title":"Zupa ryżowa (Polish rice and vegetable soup)","cuisine":"European","category":"Soup","ingredients":["400 g pork bones (approximate amount for broth)","2.5 potatoes (2–3 potatoes)","2 parsley roots","1 carrot","1 celeriac (piece or small root)","1 onion","125 ml rice (half a glass (approx. 95 g))","1 egg","1 tsp lemon juice","10 ml sour cream","1 tsp wheat flour","to taste parsley (chopped)","1 bay leaf (leaf)","to taste salt","1.5 l water (to make the broth and beat the egg)"],"steps":["Place the pork bones into a pot, cover with water, add the bay leaf, peeled onion, and salt, and simmer the broth for about 60 minutes.","Clean and cut the carrot, parsley roots, celeriac, and potatoes, then add them to the broth.","Bring the soup to a boil, stir in the rice, and simmer over low heat until the rice and vegetables are tender (you may remove and discard the cooked onion).","Season the soup with lemon juice, then pour in the egg beaten with a little water, stirring vigorously.","Thicken the soup with the flour mixed into the sour cream, bring briefly to a boil, ladle into soup plates, and garnish with chopped parsley."],"time":95,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_ry%C5%BCowa","page":"Książka kucharska/Zupa ryżowa"},{"id":"oc-plws-546606","title":"Zupa szczawiowa z omletem bez jaj (sorrel soup with eggless pancake strips)","cuisine":"European","category":"Soup","ingredients":["250 g sorrel leaves (orig. 25 dkg)","1 carrot","1 parsley root","1 onion","1 dried mushroom","1 bay leaf","1.5 l water (for the broth and mixing the flour)","65 g plain wheat flour (orig. 1 tbsp (15 g) for soup and 5 dkg (50 g) for pancake)","100 g sour cream (orig. 10 dkg)","125 ml milk (orig. 1/2 szklanki)","20 g butter, lard, or margarine (orig. 2 dkg, for stewing sorrel and frying pancake)","0.5 tsp baking powder (for the pancake)","2 black peppercorns","to taste salt"],"steps":["Cook a vegetable broth from the carrot, parsley root, onion, dried mushroom, bay leaf, and peppercorns in about 1.5 l of water for 30 minutes, then strain.","Sort and wash the sorrel, pass through a meat grinder, and braise gently in half of the fat (10 g) until completely softened.","Mix 15 g of plain wheat flour with a splash of cold water, stir into the braised sorrel, whisk in the hot vegetable broth, bring to a boil, take off the heat, stir in the sour cream, and season with salt.","Whisk the remaining 50 g of plain wheat flour with the milk, a pinch of salt, and baking powder into a thick batter. Pour into a skillet containing the remaining heated fat (10 g), forming a layer about half a finger thick, and fry over low heat on both sides.","Roll the fried pancake into a log, slice diagonally into strips, and arrange in soup plates before ladling in the piping hot sorrel soup."],"time":60,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Szczawiowa_z_omletem_bez_jaj","page":"109 potraw/Szczawiowa z omletem bez jaj"},{"id":"oc-plwb-21698","title":"Zupa wiśniowa (Old Polish sour cherry soup)","cuisine":"European","category":"Soup","ingredients":["2 l sour cherries (stemmed, with pits)","1 pinch cinnamon","4 cloves (a few (optional))","1 lemon zest (piece (optional))","250 g sugar","250 ml red wine (1 glass)","1 tsp potato starch (optional, for thickening)","1 l water (for the strained soup)"],"steps":["Wash the sour cherries, pluck off stems, and crush the fruit together with the pits in a mortar or stoneware dish.","Add the cinnamon and optionally cloves and lemon zest, mix, and set aside for 30 minutes.","Press the cherry mixture through a fine sieve, then add the sugar, red wine, and 1 litre of water.","Bring the soup to a boil and thicken if needed with a teaspoon of potato starch dissolved in a little cold water.","Serve with croutons or small sponge biscuits."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_wi%C5%9Bniowa","page":"Książka kucharska/Zupa wiśniowa"},{"id":"oc-plws-39378","title":"Zupa wiśniowa (Polish sour cherry soup)","cuisine":"European","category":"Soup","ingredients":["2 l sour cherries (orig. half a garniec of ripe stemmed sour cherries)","to taste cinnamon (ground)","2 cloves (orig. a couple of cloves)","200 g sugar (orig. half a historical Polish funt)","250 ml red wine (orig. 1 glass (or alternatively half a historical Polish kwarta = 500 ml of thin sour cream))","1 l water (orig. 1 historical Polish kwarta)","to taste wheat roll croutons (for serving)"],"steps":["In a bowl or stoneware pot, pound the ripe, stemmed sour cherries together with their stones, add a little cinnamon and the cloves, and let stand for 2 hours to release their juice and aroma.","Press the cherry mixture thoroughly through a fine sieve.","Stir the sugar into the strained juice, and pour in a glass of red wine (or alternatively 500 ml of thin sour cream) and a kwarta (1 l) of water.","Bring the soup to a boil together, then chill thoroughly and serve cold with croutons."],"time":155,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_wi%C5%9Bniowa","page":"365 obiadów za 5 złotych/Zupa wiśniowa"},{"id":"oc-plwb-18691","title":"Zupa włoska (Italian-style vegetable soup)","cuisine":"European","category":"Soup","ingredients":["1 bunch Polish soup vegetables (włoszczyzna) (bunch)","2 carrots","40 g fine soup pasta","50 ml sour cream","1 tsp wheat flour","40 g firm cheese","1 egg yolk","to taste all-purpose vegetable seasoning (such as Vegeta)","to taste salt","to taste water (cold to cook the vegetables and water for the pasta)"],"steps":["Clean, wash, and cut the soup vegetables and additional carrots into pieces, cover them with cold water, and cook until tender.","Mix the flour with the sour cream and egg yolk, pour into the simmering vegetables, bring to a boil, and season to taste with salt and vegetable seasoning.","Cook the fine pasta separately, and grate the firm cheese on a coarse grater.","Distribute the cooked pasta into soup bowls, top with grated firm cheese, and ladle over the hot soup."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_w%C5%82oska","page":"Książka kucharska/Zupa włoska"},{"id":"oc-plws-580041","title":"Zupa z białej fasoli przecierana (puréed white bean soup)","cuisine":"European","category":"Soup","ingredients":["1 carrot (large)","1 parsley root (large)","1 leek","1 onion","1 dried mushrooms (tiny mushroom)","2 l water (for the broth, plus extra cold water for soaking and boiling the beans)","to taste salt","400 g white beans (large white beans of the cukrowa variety, soaked the day before)","1 tbsp butter (a generous tablespoon)","1 tbsp plain wheat flour","125 ml sweet cream (sweet cream, or milk (half a szklanka))","2 egg yolks (beaten)"],"steps":["Cover the white beans with cold water in a bowl in the evening and soak for about 480 minutes.","Put the carrot, parsley root, leek, onion, and dried mushroom in a pot, pour in 2 l of water, add salt, and simmer over low heat for 45 minutes until the broth reduces to 1.5 l, then strain.","Boil the soaked white beans separately until tender for about 70 minutes, drain the water, dry the beans over the heat for 2 minutes, and press through a sieve into a smooth purée.","Combine the bean purée with the strained vegetable broth, add the butter and the wheat flour mixed with the sweet cream, and boil everything together for 3 minutes.","Whisk the egg yolks in a soup tureen, temper them with a spoonful of hot soup, pour in the rest of the soup, stir briskly, and serve."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Zupa_z_fasoli","page":"100 postnych i jarskich dań/Zupa z fasoli"},{"id":"oc-plwb-6260","title":"Zupa z cukinii (Polish zucchini soup)","cuisine":"European","category":"Soup","ingredients":["2 onion","1 tbsp dill (chopped)","1 tbsp butter","400 g zucchini (young zucchini)","to taste black pepper","to taste salt","100 ml sour cream (about half a tub)","500 ml vegetable broth","2 tbsp parsley (chopped)","150 g potatoes","to taste water (boiling, small amount to cook the potatoes)"],"steps":["Wash, peel, and cut the potatoes, pour in a small amount of boiling water, salt, and cook.","Peel the onions, cut them into quarters, add to the potatoes, and cook together until tender.","Wash the zucchini, trim off the stem ends and blossom remnants, and cut the flesh into pieces.","Add the zucchini to the simmering vegetable broth, add the butter, and cook until tender for about 10 minutes.","Combine the tender zucchini with the cooked potatoes and onions, then purée everything through a sieve.","Add the sour cream, warm the soup through, ladle into a tureen, and garnish with chopped parsley and dill before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_cukinii","page":"Książka kucharska/Zupa z cukinii"},{"id":"oc-plws-39377","title":"Zupa z czarnych jagód (Polish bilberry soup)","cuisine":"European","category":"Soup","ingredients":["4.25 l bilberries (orig. 1 garniec (4 l) for cooking down plus 1 mug (250 ml) of the finest whole berries)","125 ml water (orig. half a glass for mixing with the flour (or use red wine), plus enough water to moisten the berries)","300 g sugar (orig. three quarters of a historical Polish funt)","3 cinnamon stick (orig. several pieces of cinnamon)","125 ml red wine (orig. half a glass, used instead of water for mixing with the flour)","0.5 tbsp plain wheat flour (orig. half a tablespoon)","to taste lemon peel (optional, for aroma)","to taste wheat roll croutons (fried, or separately cooked hand-cut noodles, for serving)"],"steps":["Set aside one mug (250 ml) of the finest berries from the batch, tip the remaining garniec (4 l) into a pot, add just enough water to moisten them, and simmer for about 10 minutes until the berries burst.","Press the cooked berries through a sieve and let stand briefly for the sediment to settle, then carefully decant the clear juice into a clean pot.","Add the sugar and several pieces of cinnamon bark to the juice, and pour in half a glass of water or red wine mixed smoothly with half a tablespoon of wheat flour.","Set the soup over the heat, and once it comes to a boil, tip in the reserved mug of whole berries and bring briefly back to a boil.","Chill the soup thoroughly, add a piece of lemon peel for aroma before serving, and serve with fried croutons or separately boiled and cold-rinsed hand-cut noodles."],"time":50,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_z_czarnych_jag%C3%B3d","page":"365 obiadów za 5 złotych/Zupa z czarnych jagód"},{"id":"oc-plwb-14721","title":"Zupa z czerwonej fasoli (Red bean soup with smoked bacon)","cuisine":"European","category":"Soup","ingredients":["450 g smoked bacon","400 g dried red kidney beans","500 g potatoes","2 stock cubes (cubes)","2 leeks","2 carrots","0.5 sour cream (tub (half a tub))","to taste salt","to taste pepper","to taste marjoram","to taste all-purpose vegetable seasoning (such as Vegeta)","to taste water (boiling for soaking the beans and water to cook the soup)"],"steps":["Rinse the red beans, pour boiling water over them, soak for about 3 hours, then drain.","Trim the leeks, slice lengthwise and chop, peel the carrots and cut into sticks, and dice the peeled potatoes.","Place the beans in a pot, add the whole piece of smoked bacon, cover with water, and cook for about 60 minutes.","Add the prepared vegetables and stock cubes, and cook for another 30 minutes.","Remove the cooked bacon, cut it into dice, and return it to the pot.","Stir in the sour cream, season to taste with salt, pepper, and vegetable seasoning, and sprinkle with marjoram."],"time":290,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_czerwonej_fasoli","page":"Książka kucharska/Zupa z czerwonej fasoli"},{"id":"oc-plwb-57972","title":"Zupa z dyni (Simple pumpkin purée soup)","cuisine":"European","category":"Soup","ingredients":["400 g pumpkin (weight before removing seeds and skin)","1 tbsp butter (or margarine, oil, or lard)","500 ml chicken broth (chicken)","1 tbsp sour cream (added after cooling slightly)","to taste spices (nutmeg, curry powder, saffron, turmeric, chopped parsley, salt)"],"steps":["Halve the pumpkin, remove seeds and fibrous centre, cut into quarters, peel, and cut into smaller pieces.","Melt the chosen fat in a pot, add the pumpkin pieces, and cook gently covered over low heat, stirring and checking for doneness every 10 minutes or so, until the pumpkin breaks down into a purée.","Remove the pot from the heat, pour the broth over the pumpkin, and blend until smooth.","Set the soup aside to cool slightly, add a tablespoon of sour cream, and stir until smooth.","Season to taste with nutmeg, saffron, turmeric, chopped parsley, and curry powder (omit curry if you plan to freeze the soup)."],"time":45,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_dyni","page":"Książka kucharska/Zupa z dyni"},{"id":"oc-plwb-21700","title":"Zupa z jabłek lub gruszek (Apple or pear soup)","cuisine":"European","category":"Soup","ingredients":["2 kg apples (or pears)","1 tsp cinnamon","250 g sugar (approx. (a little more for apples, a little less for pears))","500 ml sour cream","1 raisins (handful (optional))","to taste water (to cook the fruit)"],"steps":["Wash the apples or pears, cut into unpeeled quarters, and core them.","Transfer the fruit to a pot, cover with water, and simmer until completely tender.","Press the cooked fruit through a colander or sieve, discarding the skins.","Add the sugar, cinnamon, and optional raisins to the purée, stir in the sour cream, and bring to a boil.","Serve warm or chilled with croutons."],"time":40,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_jab%C5%82ek_lub_gruszek","page":"Książka kucharska/Zupa z jabłek lub gruszek"},{"id":"oc-plwb-13747","title":"Zupa z kapusty pekińskiej (Napa cabbage soup)","cuisine":"European","category":"Soup","ingredients":["1 Napa cabbage (small head)","100 g button mushrooms","150 g potatoes","1 onion","125 ml sour cream (thick, half a glass)","750 ml broth (3 glasses of instant broth)","1 tbsp vegetable oil","to taste salt","to taste pepper","to taste marjoram","to taste parsley (chopped)"],"steps":["Peel and chop the onion, cook until translucent in heated oil in a pot, then pour in the broth.","Clean, wash, and shred the Napa cabbage, then add it to the pot.","Peel the potatoes and cut into cubes, and slice the cleaned button mushrooms thinly.","Add the potatoes and mushrooms to the soup, season with salt, pepper, and marjoram, and cook over low heat, taking care that the vegetables do not become overcooked.","Remove the pot from the heat, stir in the thick sour cream, and garnish with chopped parsley before serving."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_kapusty_peki%C5%84skiej","page":"Książka kucharska/Zupa z kapusty pekińskiej"},{"id":"oc-plwb-14341","title":"Zupa z papryki (Polish bell pepper soup)","cuisine":"European","category":"Soup","ingredients":["1 bunch Polish soup vegetables (włoszczyzna) (bunch, without cabbage)","4 potatoes","2 bell peppers (pods)","1 tbsp vegetable oil","to taste lemon juice","1 bay leaf (leaf)","to taste allspice","to taste mustard seeds","to taste pepper","to taste salt","1 pinch sugar","to taste parsley (chopped)","to taste water (boiling water to make the broth)"],"steps":["Clean and chop the soup vegetables, drop them into boiling water, add the bay leaf, allspice, mustard seeds, salt, pepper, and vegetable oil, and cook for about 40 minutes.","Peel and dice the potatoes, and slice the seeded bell peppers into strips.","Add the potatoes and bell peppers to the broth and cook for another 20 minutes until the vegetables are tender.","Season the soup to taste with lemon juice and a pinch of sugar, and sprinkle with chopped parsley before serving."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_papryki","page":"Książka kucharska/Zupa z papryki"},{"id":"oc-plwb-13728","title":"Zupa z sera żółtego (Polish firm cheese soup)","cuisine":"European","category":"Soup","ingredients":["100 g firm cheese","1 l broth (4 glasses)","0.5 sour cream (tub (half a tub))","6 potatoes","1 leek","0.5 tsp curry powder","to taste salt","to taste white pepper","to taste nutmeg","1 bunch chives (bunch)"],"steps":["Peel, wash, and dice the potatoes.","Pour 1 litre (4 glasses) of broth into a pot, add the potatoes, and cook for about 15 minutes.","Blend the cooked potatoes together with the broth, place the pot over low heat, and stir the sour cream into the soup.","Trim, rinse, and slice the leek, add it to the soup, and cook for 5 minutes.","Grate the firm cheese on a fine grater, add it to the pot, and heat until the cheese has melted completely.","Season the soup with salt, white pepper, curry powder, and nutmeg, and sprinkle with chopped chives just before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_sera_%C5%BC%C3%B3%C5%82tego","page":"Książka kucharska/Zupa z sera żółtego"},{"id":"oc-plwb-16927","title":"Zupa z soczewicy (Polish lentil soup with beef and bacon)","cuisine":"European","category":"Soup","ingredients":["300 g beef","1 bunch Polish soup vegetables (włoszczyzna) (bunch)","200 g red lentils","4 potatoes","100 g smoked bacon","1 onion","2 clove garlic (cloves)","1 tbsp vegetable oil","1 tbsp wheat flour","1 tbsp parsley (chopped)","1 bay leaf (leaf)","to taste salt","to taste pepper","1 l water (4 glasses for cooking (plus cold water to soak the lentils))"],"steps":["Cover the lentils with cold water and soak for 8 hours.","Place the beef in a pot, pour in 1 litre (4 glasses) of water, add the soaked lentils along with their water and the bay leaf, season with salt, and cook for about 60 minutes.","Clean the soup vegetables and potatoes, dice them, add to the soup, and cook until tender.","Peel and chop the onion and garlic, and dice the smoked bacon.","Fry the bacon in heated oil together with the onion and garlic, dust with the wheat flour, stir, and transfer into the simmering soup.","Bring everything to a boil, season with pepper, and garnish with chopped parsley before serving (in a second version, the soup can be cooked on smoked meat with the addition of sweet paprika, mustard, sour cream, and lemon juice)."],"time":580,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_soczewicy","page":"Książka kucharska/Zupa z soczewicy"},{"id":"oc-plwb-18344","title":"Zupa z zielonego groszku (green pea soup)","cuisine":"European","category":"Soup","ingredients":["500 g green peas","2 onions","1 plain yogurt (tub (about 150–200 g))","2 clove garlic (cloves, crushed)","to taste soup pearls (choux puffs) (for serving)","to taste salt","to taste black pepper","375 ml water (375 ml, for cooking the peas)","1 tbsp vegetable oil or butter (for frying the onions)"],"steps":["Cook the green peas until tender in 375 ml (1.5 szklanki) of water.","Peel the onions, chop and lightly fry in the heated fat, then blend together with the cooked peas and cooking liquid, and season with salt and black pepper.","Mix the plain yogurt thoroughly with the crushed garlic cloves, and salt and black pepper to taste.","Ladle the soup into bowls, garnish with the garlic yogurt sauce, and sprinkle with soup pearls."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_zielonego_groszku","page":"Książka kucharska/Zupa z zielonego groszku"},{"id":"oc-plwb-15488","title":"Zupa zakonna (monastic bean and vegetable soup)","cuisine":"European","category":"Soup","ingredients":["50 g dried beans (soaked overnight)","100 g carrots","100 g celeriac","100 g onion","1 tsp strained tomato purée","to taste hot paprika powder","to taste marjoram","to taste salt","to taste black pepper","to taste parsley (for sprinkling)","1 l water (cold, for soaking and boiling the beans)"],"steps":["Cover the beans with cold water and soak overnight.","Cook the beans in the soaking water, topping up with more liquid as needed.","Trim, rinse, and chop the carrots, celeriac, and onion, then add them to the simmering beans.","Towards the end of cooking, season the soup with the tomato purée, salt, black pepper, hot paprika, and marjoram, and sprinkle with chopped parsley.","Let the soup cool, refrigerate overnight, and serve reheated the following day."],"time":600,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_zakonna","page":"Książka kucharska/Zupa zakonna"},{"id":"oc-plwb-19081","title":"Zupa zbójecka (bandit's mushroom and sausage soup)","cuisine":"European","category":"Soup","ingredients":["300 g smoked bacon (diced)","200 g kiełbasa (Polish sausage) (sliced)","100 g fat (lard or vegetable oil) (for frying)","500 g porcini mushrooms (sliced)","100 g plain flour (for dusting and thickening the soup)","2 onions (finely chopped)","1 bunch chives (bunch, chopped)","2 tbsp all-purpose vegetable seasoning (such as Vegeta) (about 2 tablespoons)","to taste black pepper","to taste thyme","1 tbsp sweet paprika powder","1 bay leaf (leaf)","to taste salt","100 ml sour cream (for finishing the soup)","1.5 l water (for cooking the soup and blending the sour cream)"],"steps":["Dice the smoked bacon and fry in the fat.","Add the finely chopped onion and sliced porcini. Season with salt, black pepper, thyme, the bay leaf, and one tablespoon of sweet paprika, then cook gently, covered, for a dozen or so minutes.","Pour in the water, add about two tablespoons of vegetable seasoning, and bring to a boil. Dust the soup with one tablespoon of flour and mix thoroughly.","Slice the kiełbasa, add it to the pot, and cook for another few minutes.","Finish the soup with the sour cream whisked with the remaining flour and a little water, bring briefly to a boil, and garnish with chopped chives before serving."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_zb%C3%B3jecka","page":"Książka kucharska/Zupa zbójecka"},{"id":"oc-plws-546601","title":"Zupa ze stynki z ziemniakami (European smelt and potato soup)","cuisine":"European","category":"Soup","ingredients":["400 g cleaned European smelt (orig. 40 dkg)","2 small onions","500 g potatoes (orig. 50 dkg)","1.5 l water (orig. 1.5 l)","3 black peppercorns","1 bay leaf","to taste salt"],"steps":["Wipe the smelt thoroughly with a coarse cloth, salt, and let stand for 60 minutes before cooking.","Boil about 1.5 l of seasoned broth from the onions, peppercorns, bay leaf, and water for 15 minutes.","Peel the potatoes, cut into large dice or rounds, add to the boiling broth, and cook for about 10 minutes until parboiled.","Add the smelt to the partially cooked potatoes and simmer for another 10 minutes until the fish turns opaque and flakes from the bone. Serve immediately."],"time":100,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Zupa_ze_stynki","page":"109 potraw/Zupa ze stynki"},{"id":"oc-plwb-17190","title":"Zupa ze szparagów (white asparagus soup)","cuisine":"European","category":"Soup","ingredients":["500 g white asparagus","750 ml broth (750 ml)","2 tsp sugar (1 teaspoon for the broth, 1 teaspoon for the tomatoes)","250 g tomatoes","1 bunch parsley (bunch, chopped)","1 tsp lemon juice","50 g butter (for roux)","30 g plain flour (for roux)","100 ml whipping cream (30% fat)","to taste nutmeg","to taste salt","to taste black pepper"],"steps":["Wash and peel the white asparagus. Simmer the peelings in the broth with 1 teaspoon of sugar for 10 minutes, then strain the broth.","Cut the peeled asparagus into diagonal pieces and parboil them in the strained broth until tender.","Scald the tomatoes with boiling water, peel them, cut into quarters, and remove the seeds. Dice the flesh and mix with the chopped parsley, lemon juice, and the remaining teaspoon of sugar.","Prepare a roux from the butter and flour, stir it into the soup, and cook covered for 5 minutes.","Pour in the whipping cream, taking care that it does not curdle, and season the soup with salt, black pepper, and nutmeg.","Before serving, add the prepared tomatoes mixed with parsley to the soup."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_ze_szparag%C3%B3w","page":"Książka kucharska/Zupa ze szparagów"},{"id":"oc-plws-580039","title":"Zupa ze świeżych ogórków (fresh cucumber soup)","cuisine":"European","category":"Soup","ingredients":["5 fresh cucumbers (small, peeled)","1 tsp butter (sweet cream butter for creaming with the egg yolks, plus a piece for cooking the cucumbers)","1.5 l water (for the root-vegetable broth)","1 soup vegetables (włoszczyzna) (carrot, parsley root, and onion)","1 porcini mushroom (small, fresh mushroom for the broth)","1 tbsp plain wheat flour","250 ml sweet cream","2 egg yolks","1 tsp fresh dill (finely chopped)","to taste salt"],"steps":["Peel the fresh cucumbers, cut them into thin slices, and cook gently in a small saucepan with a piece of butter over low heat for about 15 minutes until completely soft.","In a separate pot, simmer one and a half litres of broth from the soup vegetables and the small fresh porcini mushroom with salt for about 30 minutes, then strain the broth.","Mash the cooked cucumbers with the wheat flour, stir in the cream, pour into the strained vegetable broth, and briefly bring to a boil.","Beat the egg yolks in a soup tureen with a teaspoon of butter and the chopped dill.","Temper the egg yolks with one ladleful of hot soup, mix thoroughly, pour in the rest of the soup, and serve immediately."],"time":60,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Zupa_ze_%C5%9Bwie%C5%BCych_og%C3%B3rk%C3%B3w","page":"100 postnych i jarskich dań/Zupa ze świeżych ogórków"},{"id":"oc-plwb-13400","title":"Zupa zielona (Polish green herb and potato soup)","cuisine":"European","category":"Soup","ingredients":["1250 ml vegetable broth (hot)","6 potatoes","0.5 bunch spring onions","0.5 bunch parsley","0.5 bunch chives","100 g smoked bacon (diced)","1 tbsp plant-based butter (for cooking the greens)","1 tbsp plain flour (for thickening the soup)","1 lemon (freshly squeezed juice)","4 tbsp sour cream (for finishing the soup)","to taste salt","to taste black pepper","to taste fresh dill (for garnishing before serving)"],"steps":["Peel the potatoes, dice them, rinse, cover with hot vegetable broth, and cook for about 15 minutes.","Finely chop the spring onions, chives, and parsley, and cook gently covered in the plant-based butter.","Add the cooked greens to the simmering potatoes and cook everything together for about 10 minutes.","Dice the smoked bacon, render the fat in a frying pan, and add the bacon cracklings to the soup.","Thicken the soup with the flour whisked into the sour cream and the freshly squeezed lemon juice.","Season to taste with salt and black pepper, and sprinkle with fresh dill before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_zielona","page":"Książka kucharska/Zupa zielona"},{"id":"oc-plwb-15694","title":"Zupa ziemniaczana z kurkami (potato soup with chanterelles)","cuisine":"European","category":"Soup","ingredients":["800 g potatoes","1 onion","300 g chanterelles","1 bunch Polish soup vegetables (włoszczyzna) (bunch)","50 g smoked bacon (diced)","4 tbsp vegetable oil (for frying the onion and mushrooms)","200 g button mushrooms","to taste parsley (for garnish)","to taste nutmeg","to taste salt","to taste black pepper","2 l water (boiling)"],"steps":["Peel and chop the onion, fry in part of the oil, then add the diced smoked bacon and fry together.","Peel and chop the potatoes and soup vegetables, pour over 2 litres of boiling water, add the fried onion and bacon, cook for 15 minutes, then blend into a smooth soup.","Clean the chanterelles and button mushrooms, wash, dry thoroughly, and sauté in the remaining oil, seasoning with salt and black pepper.","Combine the sautéed mushrooms with the blended soup and season to taste with nutmeg, salt, and black pepper.","Serve the soup in ramekins, garnished with chopped parsley."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_ziemniaczana_z_kurkami","page":"Książka kucharska/Zupa ziemniaczana z kurkami"},{"id":"oc-plws-38734","title":"Zupa à la Julienne (Julienne vegetable beef consommé)","cuisine":"European","category":"Soup","ingredients":["2400 g beef (orig. 6 historical Polish funts (5 funts = 2000 g for the broth and 1 funt = 400 g for the browned essence))","to taste beef suet (a piece of fresh suet for browning the meat)","to taste water (for cooking the broth and deglazing the meat essence)","1 onion (whole, deeply roasted in the oven)","to taste carrot (cut into thin matchsticks)","to taste kohlrabi (cut into thin matchsticks)","to taste celeriac (cut into thin matchsticks)","to taste parsley root (cut into thin matchsticks)","to taste cauliflower (divided into tiny florets)","to taste asparagus (diced)","to taste green peas","to taste savoy cabbage (scalded and finely diced)","to taste butter (optional, for gently stewing the vegetables)","to taste salt","to taste wheat roll croutons (dried, for serving)"],"steps":["Simmer a clear, strong broth from 2 kg (5 funts) of the beef together with a whole onion deeply roasted in the oven and salt, then strain.","Place the remaining 400 g (1 funt) of beef in a small saucepan with a piece of fresh beef suet and brown it deeply without adding water, shaking the pan constantly so it does not burn.","Pour off the browned juices that form, moisten the meat with a splash of water, and braise and brown again; repeat this process three times to obtain a dark meat essence.","Cut the carrot, kohlrabi, celeriac, and parsley root into fine matchsticks (julienne), break the cauliflower into tiny florets, dice the asparagus, and cut the scalded savoy cabbage into small pieces.","Add the vegetables along with the green peas to the clear broth and simmer until tender for 1–1.5 hours (alternatively, stew them gently in butter for 30 minutes first, then simmer in the broth for 1 hour).","Before serving, pour the dark braised meat essence into the tureen, ladle the hot vegetable soup over it, and serve with dried wheat roll croutons."],"time":220,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Zupa_%C3%A0_la_Juliene","page":"365 obiadów za 5 złotych/Zupa à la Juliene"},{"id":"oc-plwb-21699","title":"Zupa śliwkowa (Polish plum soup)","cuisine":"European","category":"Soup","ingredients":["2 l European prune plums (preferably węgierki)","250 g sugar","4 cloves (a few)","1 pinch cinnamon","250 ml white wine (1 glass (optional))","500 ml water (to dilute the purée (plus water to cook the plums))"],"steps":["Wash the plums, halve them, and remove the stones.","Place the fruit in a pot, pour in just enough water to barely cover it, and simmer, stirring frequently, until completely soft.","Rub the cooked plums through a sieve or fine colander.","Add the sugar, cloves, cinnamon, optional white wine, and 500 ml of water to the purée, and bring everything to a boil.","Serve with crispy croutons."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_%C5%9Bliwkowa","page":"Książka kucharska/Zupa śliwkowa"},{"id":"oc-plwb-16984","title":"Łosoś w sosie serowym (baked salmon in cheese sauce)","cuisine":"European","category":"Main","ingredients":["2 salmon steak","1 clove garlic","150 g firm cheese (grated)","to taste parsley leaves (chopped)","to taste sour cream 12%","to taste plain yogurt","to taste salt","to taste olive oil (for greasing the dish)"],"steps":["Preheat the oven to 220 °C. Grease an ovenproof dish with olive oil, place the salmon steaks in it, sprinkle with salt, cover with aluminium foil, and bake for 20 minutes.","Combine the 12% sour cream with plain yogurt, add the minced garlic, chopped parsley leaves, and grated firm cheese, and mix thoroughly.","Remove the foil, pour the cheese sauce over the fish, and bake for another 15 minutes."],"time":45,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%81oso%C5%9B_w_sosie_serowym","page":"Książka kucharska/Łosoś w sosie serowym"},{"id":"oc-plwb-13751","title":"Łosoś w śmietanie (salmon baked in cream)","cuisine":"European","category":"Main","ingredients":["500 g salmon fillet","to taste parsley leaves (chopped)","200 ml cream","1 lemon (juiced)","to taste salt","to taste black pepper","1 tbsp butter"],"steps":["Preheat the oven to 180 °C and grease an ovenproof dish with butter.","Place the salmon fillets in the dish, season them with salt and black pepper, and drizzle with lemon juice.","Pour 200 ml of cream over the fish and sprinkle with chopped parsley leaves.","Bake in the preheated oven for 25–30 minutes at 180 °C and serve hot."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%81oso%C5%9B_w_%C5%9Bmietanie","page":"Książka kucharska/Łosoś w śmietanie"},{"id":"oc-plwb-18775","title":"Łosoś z pieczonymi ziemniakami (baked salmon with potatoes)","cuisine":"European","category":"Main","ingredients":["600 g salmon fillet","to taste lemon juice","2 tsp vegetable oil","2 onion (small)","to taste fresh herbs (chopped)","4 potatoes","4 tbsp sour cream","to taste salt"],"steps":["Preheat the oven to 200 °C and prepare sheets of aluminium foil.","Divide the salmon fillets into 4 portions, arrange on pieces of foil, season with salt, drizzle with lemon juice, top with sliced onion and chopped herbs, and wrap tightly.","Wash the potatoes thoroughly without peeling, place on separate pieces of foil, drizzle with oil, and wrap.","Place the fish and potato parcels into the oven and bake for about 25 minutes at 200 °C.","Remove from the oven, unwrap the foil, salt the potatoes, and serve the fish portions with the potatoes drizzled with sour cream."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%81oso%C5%9B_z_pieczonymi_ziemniakami","page":"Książka kucharska/Łosoś z pieczonymi ziemniakami"},{"id":"oc-plwb-16860","title":"Łódeczki z pomidorów (stuffed tomato boats)","cuisine":"European","category":"Salad","ingredients":["6 tomato","4 iceberg lettuce (several leaves)","3 slice firm cheese (thick slices)","0.5 red bell pepper","0.5 yellow bell pepper","1 cucumber","2 tbsp olive oil","1 tbsp lemon juice","to taste salt","to taste black pepper"],"steps":["Wash the tomatoes, slice off their tops, hollow out the flesh, and dice the sliced tops.","Wash, dry, and shred the iceberg lettuce leaves. Peel the cucumber, deseed the red and yellow bell peppers, and cut the vegetables into small pieces.","Mix the lemon juice with a pinch of salt, black pepper, and olive oil, then pour the dressing over the chopped vegetables and toss.","Fill the hollowed tomatoes with the salad. Cut the firm cheese slices into triangles, skewer on toothpicks, and decorate the tomatoes to resemble sails."],"time":15,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%81%C3%B3deczki_z_pomidor%C3%B3w","page":"Książka kucharska/Łódeczki z pomidorów"},{"id":"oc-plwb-14351","title":"Śledź na czerwono (herring in tomato sauce)","cuisine":"European","category":"Snack","ingredients":["4 herring fillets","3 onions","70 ml vegetable oil","70 g tomato paste (small can)","to taste water (if needed to thin the sauce)","to taste salt","to taste sugar","to taste ground paprika","to taste black pepper"],"steps":["Peel and chop the onions, then cook them in vegetable oil until translucent.","Add the tomato paste and a little water if needed, season with salt, sugar, pepper, and paprika, heat for about 1 minute, then cool completely.","Cut the herring fillets into pieces, layer in a jar alternately with the cooled tomato-onion mixture, and chill overnight (about 12 hours)."],"time":600,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%9Aled%C5%BA_na_czerwono","page":"Książka kucharska/Śledź na czerwono"},{"id":"oc-plws-547965","title":"Śledź wędzony faszerowany (stuffed smoked herring)","cuisine":"European","category":"Other","ingredients":["1 dry smoked herring","3 potatoes","2 large onions","2 tbsp vegetable oil (1 tbsp for the onion and 1 tbsp for drizzling)","to taste liquid soup seasoning (Maggi type) (orig. 5 drops)","to taste black pepper","to taste salt"],"steps":["Soak the dry smoked herring in cold water for 24 hours (1440 minutes), then reserve the head and tail, carefully bone the flesh, and grind or mash into a smooth paste.","Boil the potatoes until tender for about 20 minutes, drain, and pass through a ricer.","Finely chop the onions and sauté in 1 tbsp of vegetable oil for about 5 minutes.","Combine the herring paste with the mashed potatoes and sautéed onion, season with liquid seasoning, pepper, and salt if needed, and work into a uniform paste.","Shape the mixture into the form of a fish on a serving platter, attach the reserved head and tail, drizzle with the remaining 1 tbsp of vegetable oil, and chill for 3 hours (180 minutes) before serving."],"time":600,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/%C5%9Aled%C5%BA_w%C4%99dzony%2C_faszerowany","page":"109 potraw/Śledź wędzony, faszerowany"},{"id":"oc-plwb-1506","title":"Śmieciuch (Polish one-bowl cocoa and plum jam cake)","cuisine":"European","category":"Cake","ingredients":["250 g plain flour","200 g sugar","250 ml vegetable oil","250 ml milk","2 eggs","1 tsp baking soda","1 tsp baking powder","3 tbsp cocoa powder","4 tbsp plum jam","to taste fat (for greasing the baking pan)","to taste breadcrumbs (for dusting the baking pan)"],"steps":["Preheat the oven to 180 °C, grease a baking pan, and dust it with breadcrumbs.","Place the flour, sugar, vegetable oil, milk, eggs, baking soda, baking powder, cocoa powder, and plum jam into a bowl and mix into a smooth batter.","Pour the batter onto the prepared pan and bake at 180 °C for about 45 minutes, until the cake cracks on top and a toothpick inserted into the centre comes out clean."],"time":55,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%9Amieciuch","page":"Książka kucharska/Śmieciuch"},{"id":"oc-plws-546701","title":"Świeże śledzie smażone z musztardą (fried fresh herrings with mustard)","cuisine":"European","category":"Main","ingredients":["550 g fresh herrings (orig. 2 fish weighing 50–60 dkg in total)","40 g vegetable oil (orig. 4 dkg)","1 tbsp plain wheat or oat flour","1 tsp mustard","2 tbsp water (for moistening the pan)","to taste salt"],"steps":["Clean and scale the fresh herrings, salt, and let rest for 2 hours (120 minutes).","Dredge the fish in plain wheat or oat flour and fry in hot vegetable oil for about 5 minutes on each side until well browned.","Score the fried herrings along the backbone, spread the cuts with mustard, pour 2 tbsp of water into the skillet, and braise for another 2–3 minutes."],"time":145,"servings":2,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/%C5%9Awie%C5%BCe_%C5%9Bledzie_sma%C5%BCone","page":"109 potraw/Świeże śledzie smażone"},{"id":"oc-plwb-16446","title":"Żur biały (white sour rye soup)","cuisine":"European","category":"Soup","ingredients":["300 g pork belly (finely diced)","2 onions (medium)","500 g smoked kiełbasa","200 g potatoes (diced)","4 dried mushrooms (porcini or bay boletes)","500 ml beef broth","500 ml rye sour (zakwas na żur) (or sour rye soup concentrate)","75 ml sour cream","3.5 tbsp wholemeal flour (preferably wholemeal)","to taste water (for soaking mushrooms, blending the thickening mixture, and adjusting consistency)","to taste marjoram","to taste lovage","1 clove garlic (clove, optional to taste)","to taste grated horseradish (optional)","to taste salt","to taste black pepper"],"steps":["Dice the pork belly finely and fry in a pan. Peel the onions, cut into medium dice, add to the pork belly, and cook until translucent or lightly golden.","Cover the dried mushrooms with hot water, and once softened, drain and chop them finely. Peel and dice the potatoes, and dice or score the kiełbasa.","Heat the beef broth in a pot, add the potatoes, kiełbasa, and mushrooms, and cook until the potatoes are tender.","Add the fried pork belly with onion, pour in the rye sour (or concentrate), season with marjoram, lovage, salt, and black pepper, and bring to a boil.","In a small bowl, whisk the flour into the sour cream until smooth, add a little water to make a pourable mixture, and pour it into the simmering soup, stirring constantly.","Season to taste with a crushed garlic clove or horseradish. Serve hot with a slice of traditional bread (the soup tastes even better when left to rest for a dozen up to 24 hours and reheated)."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%BBur_bia%C5%82y","page":"Książka kucharska/Żur biały"},{"id":"oc-plwb-13742","title":"Żur postny (Lenten sour rye soup)","cuisine":"European","category":"Soup","ingredients":["2 carrots","1 parsley root","1 celeriac (small or a piece of root)","1 leek","5 dried mushrooms","1 l rye sour (zakwas na żur)","2 clove garlic (cloves)","4 potatoes","to taste salt","1 l water (for cooking the vegetable and mushroom broth)"],"steps":["Trim, peel, and cut the carrots, parsley root, celeriac, and leek into pieces.","Pour one litre of water into a pot, add the prepared vegetables and dried mushrooms, and cook a broth.","Strain the broth, pour in the rye sour, and bring the soup to a boil.","Crush the garlic cloves and add them to the simmering soup.","Peel the potatoes, rinse, dice them, and add to the soup; cook until the potatoes are tender, then season with salt to taste."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%BBur_postny","page":"Książka kucharska/Żur postny"},{"id":"oc-plws-546620","title":"Żur z mąki owsianej z ziemniakami (sour oat soup with potatoes)","cuisine":"European","category":"Soup","ingredients":["300 g oat flour (orig. 30 dkg)","1 slice wholemeal bread crust","500 ml lukewarm water (for preparing the sour)","1.5 l vegetable stock (orig. 1.5 l)","40 g fatback (orig. 4 dkg)","400 g potatoes (orig. 40 dkg)","to taste salt"],"steps":["Pour the lukewarm water over the sifted oat flour, add the wholemeal bread crust, and leave in a warm place for 2 days (2880 minutes) to ferment.","Peel the potatoes, boil separately in salted water until tender, and cut into quarters or rounds.","Discard the bread crust from the fermented oat sour, dilute with the vegetable stock, season with salt, and bring to a boil.","Dice the fatback, render into crisp cracklings, and pour with the hot fat directly into the soup.","Add the cooked potatoes, return briefly to a boil, and serve piping hot."],"time":600,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/%C5%BBur_z_m%C4%85ki_owsianej","page":"109 potraw/Żur z mąki owsianej"},{"id":"oc-plwb-2728","title":"Żurek śląski (Silesian sour rye soup)","cuisine":"European","category":"Soup","ingredients":["300 g pork belly (diced or cut into strips)","500 g smoked kiełbasa (cut into pieces)","to taste white kiełbasa or other cured meat (optional)","200 g potatoes (diced)","150 ml sour rye soup concentrate (koncentrat żurku) (100–200 ml, depending on thickness and acidity)","2 clove garlic (cloves, crushed)","to taste marjoram (generous amount)","to taste black pepper","to taste salt","1.5 l water (cold, amount suited to ingredients)"],"steps":["Dice the pork belly or cut it into strips, place it in a pot with cold water, and bring to a boil.","Add the smoked kiełbasa cut into pieces (and optionally the white kiełbasa or other cured meat), the diced potatoes, and the crushed garlic cloves.","Season the soup with a generous amount of marjoram, and salt and black pepper to taste.","Cook for 8–12 minutes, until the potatoes are tender.","Pour in 100–200 ml of sour rye soup concentrate (depending on its thickness, acidity, and personal preference).","Simmer over low heat for 3–5 minutes, stirring constantly."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%BBurek_%C5%9Bl%C4%85ski","page":"Książka kucharska/Żurek śląski"},{"id":"oc-plwb-61743","title":"Aigo boulido (Provençal garlic and herb soup)","cuisine":"French","category":"Soup","ingredients":["1 l water (approx. 1 l for cooking the soup)","560 g potatoes (peeled and cut into 1.5 cm dice)","2 garlic (heads)","3 tbsp olive oil","1 bunch herb bouquet (rosemary, sage, thyme, parsley, bay leaves)","1.5 tsp sea salt","to taste freshly ground black pepper"],"steps":["Remove the papery outer skin from the garlic heads, brush with a little olive oil, wrap in foil, and roast in the oven at 180 °C for about 45 minutes until tender, then cool and squeeze the cloves through a garlic press.","In a large pot, combine 1 litre of water, diced potatoes, roasted garlic, the herb bouquet, remaining olive oil, sea salt, and black pepper.","Bring the soup to a boil and simmer covered over medium heat for 20 minutes until the potatoes are tender.","Discard the herb bouquet, blend the soup until silky smooth, adjust seasoning to taste, and ladle into bowls with a drizzle of olive oil."],"time":80,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Aigo_boulido","page":"Książka kucharska/Aigo boulido"},{"id":"oc-plwb-61834","title":"Artichoke bottom salad with vinaigrette (Sałatka z karczochami w sosie winegret)","cuisine":"French","category":"Salad","ingredients":["2 lollo rosso lettuce (heads)","8 artichoke bottoms (canned or jarred)","16 cherry tomatoes","3 shallots","100 ml chicken broth","2 tbsp peanut oil","2 tbsp sherry vinegar","1 tsp Dijon mustard","8 quail eggs","1 bunch fresh chervil","to taste sea salt","to taste sugar","to taste white pepper (freshly ground)"],"steps":["In a bowl, whisk the chicken broth with the Dijon mustard, sherry vinegar, and peanut oil, then season with sea salt, sugar, and white pepper.","Stir the finely chopped shallots and diced artichoke bottoms into the dressing.","Trim, wash in cold water, and thoroughly dry the lollo rosso lettuce leaves, and halve the washed cherry tomatoes.","Boil the quail eggs for 1.5 minutes from the moment the water boils, then cool in cold water, peel, and cut in half.","Arrange the lettuce leaves on plates, spoon over the artichoke bottoms with vinaigrette, garnish with halved quail eggs and cherry tomatoes, and scatter fresh chervil leaves on top."],"time":17,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_karczochami_w_sosie_winegret","page":"Książka kucharska/Sałatka z karczochami w sosie winegret"},{"id":"oc-plwb-62613","title":"Baked brie in puff pastry with baguette toasts (Ser brie z bułką paryską)","cuisine":"French","category":"Snack","ingredients":["1 baguette","225 g brie cheese (round wheel)","1 puff pastry sheet (chilled, rectangular)","1.5 tbsp olive oil (half for the cheese, half for the baguette toasts)","1 clove garlic (small, optional)","1 tsp dried basil","1 tsp dried oregano","1 pinch salt","to taste black pepper (freshly ground)"],"steps":["Preheat the oven to 200 °C (top-and-bottom heat) and line a baking sheet with parchment paper.","Unwrap the wheel of brie, pat dry with paper towels, and lightly score the top rind in a criss-cross pattern.","In a small bowl, whisk together the olive oil, pressed garlic, dried basil, oregano, a pinch of salt, and pepper.","Unroll the puff pastry sheet on a work surface, place the wheel of brie in the centre, and brush the top with half of the herb oil.","Fold the edges of the pastry inward to wrap the cheese securely, trim any excess dough, and place the parcel seam-side down on the baking sheet.","Lightly score the top of the pastry in a diamond pattern and bake in the oven for 20–25 minutes until puffed and golden brown.","Slice the baguette on an angle, brush the slices with the remaining herb oil, and add to the oven for the last 5–7 minutes of baking until crisp.","Remove the baked brie in pastry from the oven, let rest for 5 minutes, and serve hot with the toasted baguette slices for dipping into the molten centre."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ser_brie_z_bu%C5%82k%C4%85_parysk%C4%85","page":"Książka kucharska/Ser brie z bułką paryską"},{"id":"oc-plwb-15700","title":"Baked snails in garlic butter","cuisine":"French","category":"Snack","ingredients":["4 canned snails with shells (cans)","100 g butter","6 clove garlic"],"steps":["Remove the snails from their shells, drain them, and place them back into the shells.","Crush the peeled garlic cloves, blend thoroughly with the softened butter, and fill the snail shells with the garlic butter.","Place the prepared shells in a preheated oven (about 180 °C) and bake for 5–7 minutes."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%9Alimaki_zapiekane_w_sosie_czosnkowym","page":"Książka kucharska/Ślimaki zapiekane w sosie czosnkowym"},{"id":"oc-plwb-18752","title":"Baked stuffed tomatoes (Zapiekane faszerowane pomidory)","cuisine":"French","category":"Side","ingredients":["5 tomatoes","5 tbsp breadcrumbs","5 clove garlic","1 bunch parsley leaves (bunch)","5 tbsp olive oil","to taste salt","to taste black pepper"],"steps":["Slice off the tomato tops, reserve them, and scoop out the seeds from the inside.","Mix the breadcrumbs with chopped parsley leaves, minced garlic, salt, and pepper.","Fill the tomatoes with the prepared stuffing and cover with the sliced tops.","Place the tomatoes in a baking dish, drizzle generously with olive oil, and bake for 20 minutes in an oven preheated to 200 °C."],"time":35,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekane_faszerowane_pomidory","page":"Książka kucharska/Zapiekane faszerowane pomidory"},{"id":"oc-plwb-20836","title":"Bulion wołowy (white beef and veal stock)","cuisine":"French","category":"Soup","ingredients":["1.5 kg beef shank (cut into 5 cm pieces)","1.5 kg beef marrow bones (cut into 5 cm pieces)","1 kg beef ribs (cut into 5 cm pieces)","1 kg veal leg (cut into 5 cm pieces)","500 g bone-in chicken meat","250 g onion (diced medium)","2 leeks (trimmed and rinsed)","2 carrots (peeled and diced medium)","1 tsp salt","to taste cold water (to cover ingredients by about 5 cm)","6 parsley leaves (sprigs)","2 fresh thyme (sprigs or 1/2 tsp dried)","1 bay leaf","0.5 tsp black peppercorns"],"steps":["Arrange the beef shank, beef marrow bones, beef ribs, veal leg, and bone-in chicken meat in a large stockpot, covering with cold water about 5 cm above the ingredients.","Bring to a boil over medium heat, reduce the flame, and simmer uncovered for 30 minutes, skimming scum regularly.","Skim the scum once more, then add the onion, leeks, carrots, salt, and string-tied bundle of parsley leaves, fresh thyme, bay leaf, and black peppercorns.","Stir, partially cover the pot, and simmer over very low heat for 360–480 minutes.","Remove the bones and vegetables, then strain the stock through a double layer of damp cheesecloth into a clean pot.","Cool the stock quickly in a cold-water bath, refrigerate, and remove the layer of fat from the surface once it has solidified."],"time":390,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bulion_wo%C5%82owy","page":"Książka kucharska/Bulion wołowy"},{"id":"oc-plwb-20829","title":"Bulion z kurczaka (classic chicken stock)","cuisine":"French","category":"Soup","ingredients":["2 kg bone-in chicken meat","125 g onion (diced medium)","60 g carrot (diced medium)","60 g celeriac with leaves (diced medium)","60 g parsley root (optional, diced medium)","60 g leek (optional, sliced into rings)","7.5 l water","to taste salt","8 fresh thyme (sprigs or 1/4 tsp dried)","8 parsley leaves (sprigs)","1 bay leaf","10 black peppercorns (whole peppercorns)","2 clove garlic (unpeeled, crushed cloves)","6 chives (optional, blades)","0.5 tsp coriander (optional, seeds)","0.5 tsp dill seeds (optional)"],"steps":["Place the bone-in chicken meat into a large stockpot, cover with water, and place over medium heat.","When the water boils, reduce the heat and skim any scum from the surface with a slotted spoon.","Tie the thyme, parsley, bay leaf, black peppercorns, garlic, chives, coriander, and dill seeds into a bundle with string, or place them in a muslin bag.","Add the onion, carrot, celeriac with leaves, parsley root, leek, salt, and the prepared bouquet garni to the pot, and simmer gently for 120 minutes.","Strain the finished stock and chill quickly by placing the pot into an ice bath."],"time":140,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bulion_z_kurczaka","page":"Książka kucharska/Bulion z kurczaka"},{"id":"oc-plwb-25813","title":"Béchamel sauce (Sos beszamelowy)","cuisine":"French","category":"Sauce","ingredients":["30 g wheat flour","40 g butter","550 ml milk (500–600 ml)","to taste white pepper","to taste salt","to taste nutmeg (freshly grated)"],"steps":["Melt the butter over low heat in a heavy-bottomed pot, taking care not to let it brown.","Add the wheat flour and cook over low heat for 5–10 minutes, stirring constantly until smoothly combined with the butter.","Warm the milk in a separate pan, then pour in a thin stream into the roux, whisking vigorously until smooth and creamy.","Season to taste with salt, white pepper, and freshly grated nutmeg, passing through a fine sieve if necessary."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Beszamel","page":"Książka kucharska/Beszamel"},{"id":"oc-plws-42453","title":"Calf's Brain Vol-au-Vents in Puff Pastry","cuisine":"French","category":"Snack","ingredients":["500 g puff pastry (for 20 small vol-au-vents)","1 egg (egg white for sealing the rounds and egg yolk for brushing the tops)","1 calf's brain (or a small fresh beef brain (approx. 200 g))","1 tbsp vinegar (for the water to parboil the brain)","1 tbsp butter (for frying the onion)","1 onion (grated)","1 tbsp wheat flour","2 tbsp meat broth (orig. a couple of tablespoons of broth)","1 tbsp sour cream 18%","2 egg yolk (beaten)","1 tsp lemon juice","to taste salt","to taste black pepper"],"steps":["Roll out the puff pastry to a thickness of about 1 cm (half a finger) and cut out 40 rounds with a glass (for 20 vol-au-vents); cut a smaller circle about 2.5 cm in diameter out of the centre of half the rounds.","Brush the solid rounds with beaten egg white, top them with the cut-out rings, brush the tops of the rings and the small cut-out centres (lids) with egg yolk, and bake on a sheet in a hot oven (210 °C) for about 25–30 minutes.","Parboil the calf's or beef brain in water with salt and vinegar, remove the membranes, chop finely or mash with a spoon, and season with salt and pepper.","Sauté the grated onion in 1 tbsp of butter, stir in 1 tbsp of wheat flour, pour in 2 tbsp of broth, and bring to a boil.","Once the roux cools slightly, stir in 1 tbsp of sour cream, add the mashed brain, and bring briefly to a boil, then finally stir in 2 beaten egg yolks and the lemon juice and heat gently until thickened.","Fill the hollow centres of the baked puff-pastry cases with the hot ragout, top with the pastry lids, and return briefly to the oven to heat through."],"time":65,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Paszteciki_z_m%C3%B3zgu_we_francuzkiem_cie%C5%9Bcie","page":"365 obiadów za 5 złotych/Paszteciki z mózgu we francuzkiem cieście"},{"id":"oc-plwb-56197","title":"Chicken escalopes with eggplant","cuisine":"French","category":"Main","ingredients":["4 chicken breast fillets","3 eggplants (aubergines)","2 tomatoes","1 lemon","2 scallions (spring onions)","2 clove garlic","3 tbsp olive oil","1 tbsp butter (for frying meat)","to taste plain flour (for dredging)","1 pinch curry powder","to taste salt","to taste black pepper"],"steps":["Heat 2 tablespoons of olive oil in a deep skillet, add the chopped scallions, quartered tomatoes, and chopped eggplants, and fry over high heat for 5 minutes, stirring constantly.","Add the crushed garlic, sliced lemon half, salt, pepper, and pinch of curry, fry for another 5 minutes, then cover and simmer over low heat for 10 minutes.","Rinse and pat dry the chicken fillets, slice into cutlets, lightly pound to a thickness of about 1 cm, and dredge in flour.","In a separate pan, heat the remaining tablespoon of olive oil with the butter, season the meat with salt and pepper, and fry on both sides for 3–4 minutes.","Transfer the braised vegetables to a serving platter, arrange the fried chicken escalopes on top, and drizzle with the juice squeezed from the remaining lemon half."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Eskalopki_drobiowe_z_bak%C5%82a%C5%BCanem","page":"Książka kucharska/Eskalopki drobiowe z bakłażanem"},{"id":"oc-plwb-15330","title":"Chocolate mousse (mus czekoladowy)","cuisine":"French","category":"Dessert","ingredients":["250 g bittersweet chocolate (dark, firm)","3 egg (yolks and whites separated)","25 g sugar","250 ml whipped cream","1 tbsp almonds (or hazelnuts, chopped)"],"steps":["Separate the egg yolks from the whites and beat the yolks with half of the sugar until pale.","Break the chocolate into small pieces, melt in a water bath while stirring constantly, then remove from the heat and combine with the beaten egg yolks.","Whisk the egg whites over steam until stiff peaks form, adding the remaining sugar near the end of whipping.","Gently fold the whipped egg whites into the chocolate mixture, then fold everything into the whipped cream.","Spoon the mousse into dessert cups, garnish with chopped almonds, and chill in the refrigerator for 60 minutes."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mus_czekoladowy","page":"Książka kucharska/Mus czekoladowy"},{"id":"oc-plwb-19695","title":"Chocolate soufflé (Suflet czekoladowy)","cuisine":"French","category":"Dessert","ingredients":["80 g dark chocolate","80 g icing sugar","100 g egg whites (about 3)","1 pinch salt","to taste butter (softened, or margarine, for greasing ramekins)","to taste granulated sugar (for dusting ramekins)"],"steps":["Preheat the oven to 200–220 °C, grease ceramic ramekins with softened butter, coat with granulated sugar, and tap out the excess.","Melt the dark chocolate in a small bowl placed over a pot of hot simmering water.","Whip the egg whites with a pinch of salt, add the icing sugar towards the end of whipping, and continue beating until stiff.","Add the melted chocolate to the whipped egg whites and gently fold together.","Fill the ramekins level with the rim, smooth the surface with a knife, and bake for 10–12 minutes."],"time":27,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Suflet_czekoladowy","page":"Książka kucharska/Suflet czekoladowy"},{"id":"oc-plwb-20920","title":"Classic poached eggs","cuisine":"French","category":"Breakfast","ingredients":["2 eggs (fresh)","1 tbsp vinegar","1 l water (for poaching)","to taste salt","to taste black pepper"],"steps":["Pour water into a wide, shallow saucepan to a depth of about 3 cm, add salt and vinegar, and bring to a boil.","Crack each egg individually into a small bowl and gently slide into the softly simmering water.","Poach for about 3 minutes until the white is firm and the yolk remains runny.","Lift the eggs out with a slotted spoon onto a plate and sprinkle with salt and black pepper."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_w_koszulkach","page":"Książka kucharska/Jajka w koszulkach"},{"id":"oc-plws-42466","title":"Cold Game Terrine (Pain de Gibier)","cuisine":"French","category":"Main","ingredients":["1 hare (whole (or 3 hare forequarters or a roe-deer forequarter))","1 calf's liver (very large (or 2 smaller ones, approx. 500 g))","250 g fatback (part for larding the meat and liver, and part boiled and sliced for lining the pan)","125 ml meat bouillon (orig. half a Polish kwaterka of strong bouillon)","1 clove garlic (grated)","1 pinch spices (allspice, ginger and mace (a very small amount))","10 egg (beaten in one at a time while creaming)","400 g butter (orig. 1 funt of fresh butter, melted (plus a little for greasing the pan))","to taste salt","to taste black pepper"],"steps":["Trim the sinews and lard the hare (or roe venison) and large calf's liver with fatback, roast until tender, and cool completely.","Remove the roasted meat from the bones, grate the meat and liver, pound the trimmings in a mortar, and rub everything through a wire sieve while moistening with 125 ml (half a Polish kwaterka) of strong bouillon.","Season the sieved paste with salt, pepper, the tiniest pinch of allspice, ginger, and mace, and 1 grated garlic clove.","Transfer the mixture to an earthenware mixing bowl and beat in one direction with a wooden pestle, cracking in 10 eggs one after another.","Pour 400 g of cool melted butter into the smoothly creamed mixture and blend thoroughly again.","Grease a saucepan or mould with butter, line the bottom and sides in a decorative pattern with slices of boiled fresh fatback, and fill with the prepared mixture.","Bake in a slow oven (150 °C) for about 45–60 minutes, then cool completely in the mould, turn out onto a platter like a cake, and serve sliced with olive oil and vinegar."],"time":300,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pasztet_na_zimno_zwany_(pain_de_gibier)","page":"365 obiadów za 5 złotych/Pasztet na zimno zwany (pain de gibier)"},{"id":"oc-plwb-20844","title":"Crêpes","cuisine":"French","category":"Dessert","ingredients":["250 g wheat flour","600 ml milk","3 eggs","10 g butter","2 g salt"],"steps":["Put the wheat flour and salt into a bowl, make a well in the centre, crack in the eggs, and mix.","Slowly pour in 500 ml of milk while whisking vigorously to obtain a smooth, lump-free batter.","Melt the butter, stir it into the batter, and let the mixture rest for 720 minutes.","Stir in the remaining 100 ml of milk and mix thoroughly.","Ladle portions of batter (about 150 ml) into a heated, lightly buttered crepe pan and cook each crepe for 2 minutes on the first side and 1 minute after flipping."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cr%C3%AApes","page":"Książka kucharska/Crêpes"},{"id":"oc-plwb-14352","title":"Diablotins (cheese croutons)","cuisine":"French","category":"Side","ingredients":["0.5 baguette","2 tbsp butter","2 egg yolks","2 tbsp grated semi-hard cheese (sharp in flavour)","1 pinch sweet ground paprika (generous pinch)","to taste salt"],"steps":["Cream the butter with the egg yolks until smooth, then mix in the grated cheese, sweet paprika, and salt.","Cut the baguette into square pieces and spread them generously with the prepared cheese and butter mixture.","Arrange the toasts on a baking sheet and bake in an oven preheated to 180 °C for about 10 minutes until golden."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Diablotki","page":"Książka kucharska/Diablotki"},{"id":"oc-plwb-15683","title":"Eggplant casserole (Zapiekanka z bakłażanów)","cuisine":"French","category":"Side","ingredients":["3 eggplants (medium)","1 zucchini (medium)","4 tomatoes","2 onions","2.5 tsp herbs de Provence","2 tbsp parsley leaves (chopped)","60 ml vegetable oil (62.5 ml)","to taste salt (for salting the eggplants and seasoning)"],"steps":["Wash and pat dry the eggplants, cut into half-slices about 1 cm thick, salt, and let stand for about 30 minutes, then drain and pat dry.","Peel the tomatoes, zucchini, and onions and cut them into large dice.","Heat the oil in a pan, add the eggplants, and brown on both sides.","Add the chopped tomatoes, onion, and zucchini, cover, and cook gently until the vegetables are tender.","Towards the end of braising, season the dish with herbs de Provence, sprinkle with chopped parsley, and serve warm or cold."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_z_bak%C5%82a%C5%BCan%C3%B3w","page":"Książka kucharska/Zapiekanka z bakłażanów"},{"id":"oc-plwb-13273","title":"Escargots de Bourgogne (Burgundy snails)","cuisine":"French","category":"Snack","ingredients":["24 Burgundy snails (pre-cooked, with shells)","175 g butter (softened)","15 g parsley","8 g garlic","8 g salt","15 g shallots","to taste black pepper"],"steps":["Preheat the oven to 160 °C, remove the cooked snails from their shells, and drain thoroughly.","Finely chop the parsley, garlic, and shallots, then cream together with the softened butter, salt, and pepper into a smooth paste.","Place a small dab of herb butter into each shell, insert a snail inside, and fill the shell with butter, pressing lightly.","Arrange the stuffed shells on a flat baking dish and bake for 10–15 minutes at 160 °C."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%9Alimaki_po_burgundzku","page":"Książka kucharska/Ślimaki po burgundzku"},{"id":"oc-plwb-56375","title":"Fondue savoyarde (cheese fondue)","cuisine":"French","category":"Main","ingredients":["400 g Beaufort cheese","400 g Comté cheese","400 g Emmental cheese","600 ml dry white wine (Savoy)","1 tbsp kirsch (cherry brandy) (a splash)","1 tsp potato starch","1 clove garlic","600 g crusty day-old bread (dried, cut into cubes)","to taste freshly ground black pepper (ground)"],"steps":["Cut the stale bread into bite-sized cubes, and finely slice or grate the Beaufort, Comté, and Emmental cheeses.","Peel the garlic clove and rub the inside of the fondue pot or heavy-bottomed saucepan thoroughly with it.","Pour the dry white wine whisked with the potato starch into the pot and heat gently over low heat, stirring constantly.","Gradually add portions of the cheese, stirring until the mixture is uniform and smooth.","Stir in the kirsch, season with ground pepper, and mix well.","Place the fondue pot over a tabletop burner and serve with the bread cubes for dipping."],"time":30,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fondue_po_sabaudzku","page":"Książka kucharska/Fondue po sabaudzku"},{"id":"oc-plws-550065","title":"French herbal liqueur","cuisine":"French","category":"Drink","ingredients":["4.12 l spirit (orig. half a litre (500 ml) for the herbs, half a szklanka (125 ml) for the saffron, and 3.5 litres poured into the hot syrup)","250 g anise (orig. 25 dekagrams of anise)","30 g angelica root (orig. 3 dekagrams of angelica)","10 g sage (orig. 1 dekagram of sage)","10 g saffron (orig. 1 dekagram of saffron, soaked separately)","4 kg sugar (orig. 4 kilograms of finely grated or crushed sugar)","2 l water (orig. 2 litres of water)","0.5 tsp tartaric acid (orig. half a teaspoon of tartaric acid)"],"steps":["Soak 250 g of anise, 30 g of angelica root and 10 g of sage in 500 ml of the best spirit.","In a separate vessel, soak 10 g of saffron in 125 ml of spirit, and leave both infusions for 4 days.","After 4 days, bring a syrup to the boil from 4 kg of finely crushed sugar and 2 l of water, skim it carefully, add half a teaspoon of tartaric acid, and take the pan off the heat.","Pour 3.5 l of plain spirit into the still-hot syrup a little at a time, stirring constantly, then add the herb and saffron infusions strained through flannel. Once completely cool, bottle the crystal-clear liqueur, cork, seal with wax, and leave in a cool place for 6 months."],"time":15,"servings":12,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Likier_francuzki","page":"Doświadczone sekreta smażenia konfitur i soków/Likier francuzki"},{"id":"oc-plwb-56172","title":"French onion soup","cuisine":"French","category":"Soup","ingredients":["250 g onions","3 beef or poultry stock cubes","50 g butter","2 tbsp plain flour","125 ml white wine","8 slice baguette slices","100 g gruyère or firm cheese (grated)","1 clove garlic","1.5 l water","to taste salt","to taste black pepper","to taste thyme"],"steps":["Peel and slice the onions, cook in a skillet with most of the butter until translucent, dust with the flour, and fry briefly with the chopped garlic.","In a pot, bring 1.5 liters of water to a boil, dissolve the stock cubes, add the sautéed onions, and pour in the white wine.","Season the broth with salt, pepper, and thyme, and simmer over low heat for about 15 minutes.","Meanwhile, butter the baguette slices with the remaining butter and toast in the oven for about 5 minutes.","Ladle the hot soup into ovenproof bowls, top with the baguette toasts sprinkled with grated yellow cheese, and bake briefly in the oven until the cheese melts."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Francuska_zupa_cebulowa","page":"Książka kucharska/Francuska zupa cebulowa"},{"id":"oc-plwb-20914","title":"French toast (savory egg bread)","cuisine":"French","category":"Breakfast","ingredients":["1 egg","50 ml milk","1 baguette or roll (slightly stale)","1 tbsp butter","to taste salt","to taste black pepper (for savory version, or sugar for sweet version)"],"steps":["Crack the egg into a deep dish, pour in the milk, season with salt and black pepper, and whisk with a fork.","Slice the baguette or bread roll into rounds.","Melt the butter in a hot skillet.","Dip each slice on both sides into the egg mixture and fry in the pan on both sides until golden brown."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Grzanki_w_jajku","page":"Książka kucharska/Grzanki w jajku"},{"id":"oc-plws-555204","title":"French-style canned raspberries","cuisine":"French","category":"Preserve","ingredients":["500 g raspberries (orig. half a kilogram of fine, not overripe red raspberries)","500 g sugar (orig. half a kilogram of sugar chopped into small pieces)","500 ml water (orig. 2 szklanki of water)"],"steps":["Bring 500 g of finely crushed sugar to the boil with 500 ml (2 szklanki) of water and skim it thoroughly, until you have a thick syrup almost as for a jam.","Drop 500 g of picked-over raspberries into the boiling syrup and keep them on the heat for exactly 1 minute, watch in hand.","Take the pan off the heat and leave the raspberries in the syrup until completely cool.","Transfer the cooled raspberries and syrup carefully with a silver spoon into jars, leaving 5 cm of headspace. Seal them and pasteurize in a kettle of water for at most 15 minutes from the moment the water boils."],"time":55,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/Do%C5%9Bwiadczone_sekreta_sma%C5%BCenia_konfitur_i_sok%C3%B3w/Konserwa_z_malin_francuzkim_sposobem","page":"Doświadczone sekreta smażenia konfitur i soków/Konserwa z malin francuzkim sposobem"},{"id":"oc-plwb-11404","title":"Garlic mayonnaise","cuisine":"French","category":"Sauce","ingredients":["250 ml sunflower oil","250 ml olive oil","4 egg yolk","3 tsp lemon juice","2 tbsp Dijon mustard","4 clove garlic (3–5 cloves)","to taste salt","to taste black pepper","to taste sugar"],"steps":["Leave all ingredients at room temperature for 30 minutes so they reach an even temperature of about 20–25 °C.","Mash the garlic with salt into a smooth paste, then add the egg yolks, Dijon mustard, and lemon juice.","Whisking constantly, pour in the mixture of 250 ml of sunflower oil and 250 ml of olive oil in small portions until the mayonnaise becomes creamy and fluffy.","Season to taste with black pepper, sugar, and salt, stir, and transfer into sterilized jars."],"time":15,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Majonez_czosnkowy","page":"Książka kucharska/Majonez czosnkowy"},{"id":"oc-plwb-61126","title":"Herb rémoulade","cuisine":"French","category":"Sauce","ingredients":["2 hard-boiled egg yolk","2 raw egg yolk","1 tsp mustard","375 ml salad oil","2 tbsp white wine vinegar","1 tsp tarragon vinegar","1 tsp dill vinegar","6 tbsp sour cream (or plain yogurt)","4.5 tbsp mixed fresh herbs (4–5 tbsp, finely chopped)","to taste salt","to taste pepper"],"steps":["Mash the hard-boiled yolks and beat thoroughly with the raw yolks, mustard, a pinch of salt, and pepper.","Whisking constantly as when making mayonnaise, pour in the salad oil in a slow, steady stream, then finish with the white wine vinegar, tarragon vinegar, and dill vinegar.","Once the sauce is smooth and uniform, fold in the sour cream or plain yogurt and the finely chopped herbs."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Remoulade_(zio%C5%82owy)","page":"Książka kucharska/Remoulade (ziołowy)"},{"id":"oc-plwb-13054","title":"Hollandaise sauce","cuisine":"French","category":"Sauce","ingredients":["100 g butter","3.5 egg yolks","0.5 lemon juice (squeezed from half a lemon)","to taste salt","to taste white pepper","to taste nutmeg"],"steps":["Melt the butter in a small saucepan.","Whisk the egg yolks with part of the lemon juice, a pinch of salt, and white pepper.","Without stopping whisking, slowly pour in the melted butter until the sauce becomes smooth and creamy.","Season the finished sauce to taste with salt, white pepper, nutmeg, and a few drops of lemon juice."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_holenderski","page":"Książka kucharska/Sos holenderski"},{"id":"oc-plws-508382","title":"Jaja po bretońsku (poached eggs Bretonne with mushroom sauce)","cuisine":"French","category":"Breakfast","ingredients":["100 g button mushrooms (cut into strips)","1 onion (finely chopped)","50 g butter (for the sauce, plus extra for frying the toast)","1 tbsp plain wheat flour","to taste broth (or water for thinning the sauce)","0.5 lemon (juice, squeezed)","1 tsp caramel colouring (for colouring the sauce)","6 eggs (for poaching)","to taste water (for poaching the eggs)","2 tbsp vinegar (for poaching the eggs)","to taste salt","6 slice wheat roll (slices for toast)"],"steps":["Clean the button mushrooms, cut them into strips, and fry with the finely chopped onion in butter for about 8 minutes.","Sprinkle the mushrooms with the wheat flour, stir in enough broth to make a thick sauce, season with salt, the juice of half a lemon, and a teaspoon of caramel colouring, and simmer for 3 minutes.","Fry the slices of wheat roll in butter on both sides for 3 minutes until golden.","Bring salted water with vinegar to a boil in a shallow saucepan, carefully crack in the eggs, and poach for 2–3 minutes until the whites are set and the yolks remain runny.","Place the poached eggs on the hot toast, spoon the mushroom sauce over them, and serve immediately."],"time":35,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_po_breto%C5%84sku","page":"100 potraw z jaj/Jaja po bretońsku"},{"id":"oc-plws-508380","title":"Jaja à la Tripe (eggs à la tripe)","cuisine":"French","category":"Main","ingredients":["11 eggs (10 hard-boiled and 1 whole raw for the sauce)","3 onion (chopped)","500 ml water (for boiling down the onions to 250 ml)","1 bay leaf (leaf)","to taste black pepper (a few peppercorns)","to taste allspice (a few berries)","1 tbsp butter (a generous tablespoon)","1 tbsp plain wheat flour (a generous tablespoon)","250 ml sour cream","to taste salt"],"steps":["Hard-boil ten eggs for 10 minutes, let cool, peel, and slice into rounds.","Put the chopped onions into the water with the bay leaf, peppercorns, allspice, and a pinch of salt, then boil for about 15 minutes until 250 ml of liquid remains in the pot.","Add the butter mashed with the wheat flour to the onion broth and simmer, stirring, for 2 minutes until the sauce thickens.","Transfer the sauce to a small saucepan, add the sliced hard-boiled eggs, and pour in the sour cream beaten with the raw egg.","Set the saucepan over the heat and boil gently for 1 minute, stirring carefully, then serve immediately."],"time":40,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_%E2%80%9Ea_la_Trippe%E2%80%9C","page":"100 potraw z jaj/Jaja „a la Trippe“"},{"id":"oc-plwb-14228","title":"Kotlety de volaille (Chicken Kyiv)","cuisine":"French","category":"Main","ingredients":["4 chicken breast fillets","2 eggs","150 g butter (chilled)","100 g breadcrumbs","2 tbsp parsley (chopped)","0.5 lemon (freshly squeezed juice)","to taste poultry seasoning","to taste plain flour (for breading)","to taste salt","to taste pepper","to taste frying fat"],"steps":["Wash and dry the chicken fillets, butterfly each lengthwise, and pound gently with a mallet on a board.","Season the meat with salt, pepper, and poultry seasoning, drizzle with the juice squeezed from half a lemon, and scatter with the chopped parsley.","Cut the chilled butter into 4 batons, place one on each piece of meat, and roll up tightly.","Coat the rolled cutlets successively in plain flour, beaten eggs, and breadcrumbs.","Heat the fat and fry the cutlets over high heat for about 3 minutes per side until golden brown, then finish cooking over low heat."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_de_volaille","page":"Książka kucharska/Kotlety de volaille"},{"id":"oc-plws-39712","title":"Lemon Soufflé Omelette","cuisine":"French","category":"Dessert","ingredients":["4 egg (separated into 4 yolks and 4 whites, with the whites to be beaten until stiff peaks form)","2 egg white (extra, for beating with the egg yolks)","100 g sugar (orig. a quarter funt)","0.5 lemon (large, grated zest)","1 tsp clarified butter (for greasing the platter very thinly)"],"steps":["Separate the yolks from the whites of 4 eggs; place the 4 egg yolks in a bowl, add 2 extra raw egg whites, 100 g of sugar, and the zest grated from half a large lemon, and beat with a wooden spoon for 5 minutes.","Beat the remaining 4 egg whites into very stiff peaks and carefully fold them into the beaten yolks with a spoon, making sure the mixture remains stiff.","Grease a metal or ovenproof platter very thinly with clarified butter, pile the entire mixture immediately into a high mound, and smooth the surface with a knife.","Place the platter for 15 minutes into a moderate oven (160 °C) with stronger bottom heat (if the top browns too quickly, cover it with a sheet of paper).","Serve the soufflé immediately upon removing it from the oven."],"time":25,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Omlet_(suflet)_cytrynowy","page":"365 obiadów za 5 złotych/Omlet (suflet) cytrynowy"},{"id":"oc-plws-580446","title":"Nadzienie „aux fines herbes” do omletu (fines herbes mushroom and onion omelette filling)","cuisine":"French","category":"Other","ingredients":["2 onion (sliced)","1 tbsp butter","1 fresh dill (handful, finely chopped)","1 parsley leaves (handful, finely chopped)","2 button mushrooms (or 2 cooked dried mushrooms, finely chopped)"],"steps":["Peel and thinly slice the onions, and finely chop the button mushrooms, dill, and parsley leaves.","Melt the butter in a skillet, add the onions, and cook gently over low heat for about 10 minutes until soft.","Add the chopped button mushrooms, dill, and parsley leaves to the onions, sauté everything together briefly for 2 minutes, and use the hot filling for an omelette."],"time":22,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Nadzienie_%E2%80%9Eaux_fines_herbes%E2%80%9C","page":"100 postnych i jarskich dań/Nadzienie „aux fines herbes“"},{"id":"oc-plwb-18677","title":"Oeufs mimosa (Mimosa stuffed eggs)","cuisine":"French","category":"Snack","ingredients":["4 eggs","4 tbsp mayonnaise","to taste parsley leaves (finely chopped)","to taste lettuce (leaves for serving)","1 tomato (for garnish)","to taste salt","to taste black pepper"],"steps":["Hard-boil the eggs, cool, peel, and cut in half lengthwise.","Remove the yolks and push through a sieve, then mix half of the sieved yolks with the mayonnaise, chopped parsley leaves, salt, and black pepper.","Fill the hollowed egg white halves with the prepared yolk mixture.","Arrange the stuffed eggs on a platter lined with lettuce leaves, sprinkle with the remaining sieved yolks, and garnish with tomato slices."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_mimoza","page":"Książka kucharska/Jajka mimoza"},{"id":"oc-plws-45020","title":"Omelettes","cuisine":"French","category":"Breakfast","ingredients":["6 egg (best proportion for 1 omelette)","3 pinch salt","3 pinch black pepper","0.5 tsp parsley leaves (or chives, finely chopped)","80 g butter (orig. slightly less than a quarter funt of fresh butter (with 8 eggs, a full quarter funt = 100 g))"],"steps":["Crack 6 eggs into a bowl, add 3 pinches of salt, 3 pinches of pepper and half a teaspoon of chopped parsley or chives, and beat with a fork for exactly 1 minute (no longer, to prevent the eggs becoming watery).","Set a clean frying pan over high heat, add 80 g of fresh butter, and swirl the pan until the butter is thoroughly heated but not browned.","Pour the eggs into the pan and stir initially with a fork so that they set evenly across the entire surface.","Once the eggs begin to thicken, shake the pan and use a knife or spatula to fold both edges of the omelette toward the centre, giving it an oval shape.","Hold the omelette over the heat for a brief moment longer to lightly brown the underside, then turn out onto a platter."],"time":10,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Omlety","page":"365 obiadów za 5 złotych/Omlety"},{"id":"oc-plwb-12895","title":"Omlet (classic French omelette)","cuisine":"French","category":"Breakfast","ingredients":["2 eggs","1 tbsp milk","1 tbsp plain flour","1 tbsp sugar (optional, for a sweet version)","1 tsp butter (or oil, for frying)"],"steps":["Crack the eggs into a bowl, add the milk, flour, and optional sugar, and whisk thoroughly.","Heat the butter or oil in a frying pan and pour in the prepared egg mixture.","Fry over medium heat for about 2 minutes, until the bottom is lightly browned and the top is softly set.","Slide the finished omelette onto a plate and serve immediately after frying."],"time":10,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Omlet","page":"Książka kucharska/Omlet"},{"id":"oc-plws-580444","title":"Omlet biszkoptowy do nadziewania (puffy soufflé omelette)","cuisine":"French","category":"Breakfast","ingredients":["5 eggs (yolks and whites separated)","1 tbsp plain wheat flour","5 tbsp milk (or sweet cream)","to taste salt","to taste butter (generous amount, for frying)"],"steps":["Preheat the oven to 180 °C and separate the yolks from the whites of the 5 eggs.","Beat the egg yolks with the wheat flour, milk, and salt until smooth.","Beat the egg whites to stiff peaks and gently fold them into the beaten yolks.","Melt a generous amount of butter in a large ovenproof skillet, pour in the egg mixture, smooth the top with a knife, and cook on the stove for 4 minutes until the underside is golden brown.","Transfer the skillet to the oven preheated to 180 °C for about 6 minutes until the omelette is set on top, then fold in half and serve immediately."],"time":20,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Omlety_nadziewane","page":"100 postnych i jarskich dań/Omlety nadziewane"},{"id":"oc-plws-503330","title":"Plain omelette","cuisine":"French","category":"Breakfast","ingredients":["6 eggs","4 tbsp sweet cream (thick)","to taste salt (a pinch)","1 tbsp butter (generous spoonful)"],"steps":["Beat the eggs vigorously in a bowl with four tablespoons of thick sweet cream and a pinch of salt.","Brown a generous tablespoon of butter in an ovenproof skillet, pour in the egg mixture, and cook over high heat for about 2 minutes until set underneath.","Transfer the skillet to an oven preheated to 190 °C for about 3–4 minutes (or cover over low heat) until the top sets evenly.","Fold the omelette in half with a wide spatula (or fold both edges toward the center), slide carefully onto a platter, and serve piping hot."],"time":11,"servings":3,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Omlet_zwyk%C5%82y","page":"100 potraw z jaj/Omlet zwykły"},{"id":"oc-plwb-12539","title":"Pork tenderloin in mustard and cheese sauce (Polędwica z sosem musztardowo-serowym)","cuisine":"French","category":"Main","ingredients":["500 g pork tenderloin","1 tbsp butter","5 tbsp dry white wine","125 ml heavy cream 30%","1 tbsp fresh herbs (marjoram, thyme) (chopped)","125 g Camembert cheese (rind removed)","1.5 tbsp Dijon mustard","to taste black pepper (freshly ground)"],"steps":["Cut the pork tenderloin into slices and gently pound them.","Melt the butter in a skillet, fry the pork slices for about 6–7 minutes on both sides, then transfer to a warm place.","Pour the white wine into the pan drippings and bring to a boil.","Add the heavy cream, chopped herbs, skinned Camembert, and Dijon mustard.","Simmer the sauce over low heat, stirring until the cheese has melted, and season with freshly ground pepper.","Arrange the pork slices on plates and spoon the hot sauce over them."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pol%C4%99dwica_z_sosem_musztardowo-serowym","page":"Książka kucharska/Polędwica z sosem musztardowo-serowym"},{"id":"oc-plwb-24288","title":"Provençal almond and orange torte (Tort prowansalski)","cuisine":"French","category":"Cake","ingredients":["6 eggs","250 g sugar","2 oranges (squeezed juice)","250 g almonds (ground)","2 tsp potato starch","200 g butter","150 g almonds (ground)","150 g sugar","3 egg yolks","50 ml strong coffee","3 tbsp orange liqueur","to taste mandarins (for decoration)"],"steps":["Separate the yolks from the whites of six eggs, beat the yolks with 250 g of sugar and the juice of two oranges, then mix in 250 g of ground almonds.","Beat the egg whites until stiff, dust with the potato starch, and gently fold into the almond mixture.","Transfer the batter to a springform cake tin and bake for 30 minutes in an oven preheated to 180 °C, and once completely cooled, slice horizontally in half.","Beat the butter until fluffy, adding 150 g of ground almonds, the remaining sugar, and three egg yolks previously beaten with some sugar, then pour in the strong coffee and orange liqueur while continuing to beat.","Spread most of the cream between the sponge layers, coat the top with the rest, and decorate with mandarin segments."],"time":75,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tort_prowansalski","page":"Książka kucharska/Tort prowansalski"},{"id":"oc-plwb-21714","title":"Puff pastry","cuisine":"French","category":"Other","ingredients":["500 g wheat flour","1 egg","250 ml water (1 cup (250 ml))","500 g butter"],"steps":["Knead the wheat flour, egg, and water into a soft, moderately firm dough, shape into a ball, and refrigerate for at least 30 minutes.","Flatten the softened butter into a layer about 2 cm thick and chill it in the refrigerator.","Roll out the dough, place the butter block in the centre, fold the edges over envelope-style, and roll out to a thickness of 1 cm.","Rest the laminated dough in a cold place for 30–120 minutes.","Fold the dough into 3 layers, roll out again, and chill, repeating this folding process 4 to 6 times before baking at about 200 °C."],"time":80,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_francuskie","page":"Książka kucharska/Ciasto francuskie"},{"id":"oc-plwb-18806","title":"Quiche Lorraine","cuisine":"French","category":"Main","ingredients":["300 g savoury shortcrust pastry (frozen)","6 slice smoked bacon","100 g firm cheese (grated)","0.5 onion (chopped)","3 egg","200 ml 12% sour cream","to taste cayenne pepper","to taste salt"],"steps":["Thaw the savoury shortcrust pastry and use it to line a tart tin.","Finely chop the smoked bacon and scatter it over the pastry base along with the chopped onion and grated firm cheese.","Whisk the eggs with the 12% sour cream, season with salt and cayenne pepper, and pour the mixture over the filling in the tin.","Bake the tart for 20 minutes in an oven preheated to 180 °C, then reduce the temperature to 150 °C and bake for another 10 minutes, then let cool."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Quiche_lorraine","page":"Książka kucharska/Quiche lorraine"},{"id":"oc-plwb-57963","title":"Rémoulade","cuisine":"French","category":"Sauce","ingredients":["250 ml mayonnaise","2 pickled gherkin (finely chopped)","1 tbsp capers (drained)","2 tbsp fresh herbs (chervil, tarragon, chives, parsley leaves) (chopped)","0.25 tsp anchovy essence","to taste salt","to taste pepper"],"steps":["Place the mayonnaise in a bowl and dice the gherkins very finely.","Finely chop the chervil, tarragon, chives, and parsley leaves to yield 2 tablespoons of herbs, then add to the mayonnaise along with the gherkins, drained capers, and a few drops of anchovy essence.","Season the sauce with salt and pepper and mix thoroughly."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Remoulade","page":"Książka kucharska/Remoulade"},{"id":"oc-plwb-57960","title":"Sabayon","cuisine":"French","category":"Dessert","ingredients":["6 egg yolks","150 g sugar","250 ml white wine or champagne","1 fresh lemon peel (strip from an unwaxed lemon)"],"steps":["Bring water to a boil in a larger saucepan to prepare a water bath.","In a smaller saucepan, combine the egg yolks, sugar, and white wine or champagne, and add the piece of lemon peel.","Place the smaller saucepan in the vessel of boiling water and whisk vigorously for 2–3 minutes, until the mixture doubles in volume and becomes a thick mousse.","Continue whisking for another 30 seconds, then remove the lemon peel, spoon the sabayon into dessert coupes, and serve immediately."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sabayon","page":"Książka kucharska/Sabayon"},{"id":"oc-plwb-13675","title":"Saffron sauce (Sos szafranowy)","cuisine":"French","category":"Sauce","ingredients":["250 ml mayonnaise (thick)","1 pinch saffron (threads)","500 ml dry white wine","to taste black pepper (ground)","0.33 clove garlic"],"steps":["Pour the white wine into a pot, bring to a boil, and add the saffron threads.","Stir the infusion, remove from the heat, and let stand for 3 minutes.","Add the ground black pepper and finely minced garlic.","Gradually add the mayonnaise, stirring continuously until a smooth sauce forms."],"time":10,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_szafranowy","page":"Książka kucharska/Sos szafranowy"},{"id":"oc-plwb-20260","title":"Sałatka nicejska (Niçoise salad)","cuisine":"French","category":"Salad","ingredients":["1 crisphead or iceberg lettuce (head)","200 g tuna in its own juices","2 tomatoes","20 olives","2 eggs","1 white onion","2 clove garlic","2 tbsp olive oil","1 tbsp lemon juice or wine vinegar","to taste salt","to taste black pepper","1 pinch sugar"],"steps":["Wash and dry the lettuce, then tear the leaves into bite-sized pieces.","Hard-boil the eggs, let cool, peel, and cut into quarters.","Cut the tomatoes into wedges, slice the white onion into rings, and cut the olives in half.","In a salad bowl, combine the lettuce, tomatoes, onion, egg quarters, drained tuna, and olives.","Finely mince the garlic, mash it with a pinch of sugar, salt, and pepper, stir in the lemon juice or wine vinegar, and gradually whisk in the olive oil.","Drizzle the salad with the dressing and gently toss."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_nicejska","page":"Książka kucharska/Sałatka nicejska"},{"id":"oc-plws-499664","title":"Scrambled eggs à la Strasbourgeoise","cuisine":"French","category":"Breakfast","ingredients":["1 goose liver","1 veal kidney (with its surrounding suet)","5 button mushrooms (young (or porcini mushrooms))","1 onion (sizable, finely chopped)","100 g cooked ham (cut into strips (or cooked tongue))","10 eggs","150 ml sweet cream (thick)","100 g butter (for the eggs, plus extra for braising the offal and frying croutons)","to taste salt","to taste wheat roll (sliced and fried into croutons)"],"steps":["Braise the goose liver and trimmed veal kidney (along with its surrounding fat) in butter for about 12 minutes until tender, then cut into thin slices.","Sauté the young mushrooms with the finely chopped onion in the same fat for 6 minutes, chop the mushrooms finely, toss with the sliced liver, kidney, and strips of cooked ham, and keep warm.","Brown the wheat roll croutons in butter for 3 minutes.","Beat the eggs with the thick sweet cream and a pinch of salt.","Melt 100 g of butter in a wide skillet or metal platter, pour in the egg mixture, and cook over low heat for about 5 minutes, gently lifting the set curds from the bottom with a spoon.","Push the scrambled eggs toward the edge of the dish, spoon the warm liver, kidney, mushroom and ham mixture into the centre, arrange the fried croutons around it, and serve immediately."],"time":50,"servings":5,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jajecznica_francuska_(po_Strasbursku)","page":"100 potraw z jaj/Jajecznica francuska (po Strasbursku)"},{"id":"oc-plws-45182","title":"Sliced potatoes braised with butter and herbs (Kartofle à la maître d'hôtel)","cuisine":"French","category":"Side","ingredients":["10 potatoes (orig. 10 potatoes)","2 tbsp water (hot water for braising (or 2 tbsp sweet cream), plus boiling water for scalding)","1 tbsp butter (fresh)","to taste salt (fine)","to taste fresh parsley (or fresh dill, finely chopped)"],"steps":["Peel the potatoes, cut them into slices, scald with boiling water, and drain.","Place a tablespoon of fresh butter in a saucepan, add the drained potato slices, salt lightly, and pour in 2 tablespoons of hot water.","Cover the saucepan with a lid and braise the potatoes over low heat for 20 minutes, shaking the pan frequently without stirring with a spoon.","Sprinkle the hot potatoes with chopped parsley or dill before serving."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Kartofle_a_la_maitre_d'hotel","page":"365 obiadów za 5 złotych/Kartofle a la maitre d'hotel"},{"id":"oc-plwb-13272","title":"Snails with rosemary and potatoes","cuisine":"French","category":"Main","ingredients":["24 in-shell snails","200 g potatoes","12 clove garlic","3 fresh rosemary (sprigs, cut into pieces)","to taste green peppercorns","to taste salt","4 tbsp olive oil","150 ml white wine","1 shallot (finely chopped)","to taste water (for blanching and moistening)"],"steps":["Wash the snails in shells several times, and cut the peeled potatoes into thick chunks.","Drop the snails into salted boiling water for 1 minute, drain, and then fry briefly in heated olive oil over moderate heat.","Add the cut rosemary sprigs, garlic, green peppercorns, and salt, and gently sauté for 12 minutes.","Add the cut potatoes and chopped shallot, and pour in the white wine.","Simmer covered over low heat for about 20 minutes, adding a little water if needed so the snails remain in liquid."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%9Alimaki_z_rozmarynem","page":"Książka kucharska/Ślimaki z rozmarynem"},{"id":"oc-plwb-14172","title":"Sole with spinach and béchamel","cuisine":"French","category":"Main","ingredients":["150 g sole fillet (single serving)","100 g fresh spinach (alternatively use half this weight of frozen spinach)","1 tbsp firm cheese (grated)","1 clove garlic","125 ml milk","1 tbsp plain flour","1 tbsp butter","1 lemon juice (squeezed from 1 lemon)","to taste nutmeg","to taste salt","to taste white pepper"],"steps":["Make a white roux with butter and flour and set a small portion aside. Whisk the milk into the remaining roux, bring to a boil, and season with salt, white pepper, and nutmeg to make a béchamel sauce.","Cook the spinach gently, covered, then mix it with the finely chopped garlic and the reserved roux.","Place the sole fillet drizzled with lemon juice and sprinkled with salt in a baking dish, spread the spinach over it, pour on the béchamel sauce, and sprinkle with grated firm cheese.","Bake in a preheated oven (about 180 °C) for 20–30 minutes."],"time":45,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sola_za_szpinakiem_pod_beszamelem","page":"Książka kucharska/Sola za szpinakiem pod beszamelem"},{"id":"oc-plws-38762","title":"Sos szodonowy (chaudeau wine sauce)","cuisine":"French","category":"Sauce","ingredients":["250 ml caster sugar (orig. 1 kubek of fine sugar (approx. 200 g))","7 egg yolks (orig. 6–8 yolks)","250 ml white wine (orig. 1 kwaterka of French white or Rhine wine)"],"steps":["Beat the egg yolks with the caster sugar in a bowl until pale and fluffy.","Pour in the white wine, mix well, and transfer the mixture to a small saucepan.","Set the saucepan over very low heat (or over a water bath) and whisk constantly until the sauce thickens and foams.","Remove the pan from the heat just before it reaches the boil so the egg yolks do not curdle, and serve immediately as a warm dessert sauce or in cups as a drink."],"time":15,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_szodonowy","page":"365 obiadów za 5 złotych/Sos szodonowy"},{"id":"oc-plws-503331","title":"Soufflé omelette (Omelette soufflée)","cuisine":"French","category":"Breakfast","ingredients":["3 egg yolks (2–3 yolks per omelette)","3 tbsp heavy cream (1 tbsp per yolk)","to taste salt","3 egg whites (beaten to stiff peaks)","to taste butter (generous amount for frying)"],"steps":["Cream the egg yolks in a bowl with a pinch of salt and three tablespoons of heavy cream.","Whip the egg whites to stiff peaks and fold them gently into the yolk mixture.","Heat a generous amount of butter in an ovenproof skillet, pour in the egg mixture, and cook over high heat for about 2 minutes until browned underneath.","Transfer the skillet to an oven preheated to 190 °C for about 4–5 minutes (or finish over the lowest possible stovetop heat) until the top is set.","Gently fold the puffed omelette in half with a spatula and serve immediately on a warmed platter."],"time":15,"servings":1,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Omlet_francuski_(%E2%80%9EOmelette_souffl%C3%A9e%E2%80%9C)","page":"100 potraw z jaj/Omlet francuski („Omelette soufflée“)"},{"id":"oc-plws-42481","title":"Strasbourg-Style Liver Pâté","cuisine":"French","category":"Preserve","ingredients":["500 g calf's liver (orig. 1 calf's liver)","100 g fatback (cut into strips, for thickly larding the liver)","2 tbsp butter (for braising the liver)","250 ml clarified butter (orig. 1 kubek of fresh clarified butter)","to taste salt","to taste black pepper"],"steps":["Lard the calf's liver generously with strips of fatback and braise it covered in butter until tender, then let cool.","Grate the braised liver on a grater, then rub it through a fine sieve.","Season the paste with salt and pepper, pour in 250 ml (1 kubek) of fresh clarified butter, and beat very thoroughly.","Pack the pâté into an earthenware crock or tin, chill, and serve for spreading on fresh rolls."],"time":85,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Pasztet_z_w%C4%85tr%C3%B3bek%2C_na_spos%C3%B3b_Sztrasburgski","page":"365 obiadów za 5 złotych/Pasztet z wątróbek, na sposób Sztrasburgski"},{"id":"oc-plwb-55039","title":"Vanilla ice cream","cuisine":"French","category":"Dessert","ingredients":["500 ml whole milk (3.2%)","125 g sugar","1 vanilla bean (split lengthwise, seeds scraped)","6 egg yolk","100 ml whipping cream (30–36%) (chilled)"],"steps":["Pour 500 ml of milk into a small saucepan, add two-thirds of the 125 g of sugar along with the seeds scraped from the vanilla bean, stir, and bring to a boil over medium heat.","Meanwhile, whisk the egg yolks with the remaining sugar into a pale, fluffy cream.","Pour the boiling milk into the whisked yolks while stirring constantly with a whisk, then pour everything back into the saucepan.","Heat the custard over low heat, stirring with a wooden spoon, until it thickens and lightly coats the back of the spoon, without letting it boil.","Remove from the heat, pour into a bowl, allow to cool, cover with cling film, and chill in the refrigerator.","Mix the cold crème anglaise with 100 ml of chilled whipping cream, churn in an ice cream maker, then transfer to a container and freeze for several hours."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lody_waniliowe","page":"Książka kucharska/Lody waniliowe"},{"id":"oc-plwb-61737","title":"Vichyssoise","cuisine":"French","category":"Soup","ingredients":["3 leeks (large, mainly the white parts)","500 g potatoes","1.5 l chicken or vegetable broth","2 tbsp butter","2 tbsp whipping cream (30% fat) (or goat cheese slices)","1 pinch white pepper","to taste salt"],"steps":["Clean the leeks, cut off the green parts, and slice the white stalks into rings. Peel and dice the potatoes.","Melt the butter in a pot and cook the sliced leeks gently, covered, until soft.","Add the potatoes, sauté briefly, then pour in the hot chicken or vegetable broth.","Simmer the soup covered over low heat for 20–25 minutes until the potatoes are completely tender.","Season the soup with salt and white pepper, blend until completely smooth, stir in the whipping cream, and chill in the refrigerator before serving."],"time":165,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Vichyssoise","page":"Książka kucharska/Vichyssoise"},{"id":"oc-plwb-6384","title":"Vinaigrette dressing (Sos winegret)","cuisine":"French","category":"Sauce","ingredients":["7 clove garlic","1 tsp salt","80 ml wine vinegar (or lemon juice)","250 ml olive oil (or vegetable oil)"],"steps":["Peel the garlic cloves, chop them finely, and place in a jar.","Add the salt, wine vinegar or lemon juice, and olive oil or vegetable oil.","Tightly close the jar and shake vigorously until a uniform emulsion forms."],"time":5,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_winegret","page":"Książka kucharska/Sos winegret"},{"id":"oc-plws-39039","title":"White onion sauce Soubise (sos cebulowy à la Soubise)","cuisine":"French","category":"Sauce","ingredients":["10 large white onions (peeled)","100 g butter (orig. 1/4 Polish funt)","1 tbsp plain wheat flour (heaping)","250 ml fresh cream (orig. 1 szklanka)","1 pinch caster sugar","to taste salt"],"steps":["Immerse the peeled white onions in salted boiling water to steep for 10 minutes, then remove, drain, and slice thinly.","Melt the butter in a pan, add the sliced onions, cover, and sweat over very low heat for about 20–25 minutes until thoroughly tender without browning at all.","Stir in the plain wheat flour, heat briefly, and whisk in the sweet cream.","Simmer over low heat for a few minutes while stirring constantly, season with a pinch of sugar and salt, and rub the thick sauce through a sieve."],"time":55,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Sos_cebulowy_bia%C5%82y_zwany_%C3%A1_la_Soubise","page":"365 obiadów za 5 złotych/Sos cebulowy biały zwany á la Soubise"},{"id":"oc-plwb-20828","title":"Zupa julienne (Potage julienne)","cuisine":"French","category":"Soup","ingredients":["1.5 l broth (clear)","1 bunch Polish soup vegetables (włoszczyzna) (bunch, preferably young)","1 kohlrabi","0.5 cauliflower (half a head)","0.5 savoy cabbage (half a head)","125 ml green peas (half a glass)","1 onion (medium)","to taste parsley (chopped)","2 tbsp butter","to taste salt"],"steps":["Peel the carrot, kohlrabi, celeriac, and parsley root, and cut them into matchstick-sized strips (julienne).","Cut the savoy cabbage into narrow strips of similar size, and divide the cauliflower into small florets.","Cook the savoy cabbage until tender in broth or separately in salted water, and roast the onion in the oven or char it directly over a flame for a dozen or so minutes.","Cook the remaining sliced vegetables and green peas gently covered for a few minutes in the butter, then transfer them along with the cabbage and charred onion into the broth.","Simmer the soup over low heat for 15–20 minutes, season to taste with salt, and sprinkle with chopped parsley before serving."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_julienne","page":"Książka kucharska/Zupa julienne"},{"id":"oc-plwb-22221","title":"Adjika (Caucasian spiced pepper and tomato relish)","cuisine":"Georgian","category":"Sauce","ingredients":["2.5 kg red tomatoes","1 kg carrots","1 kg tart apples (such as Antonovka) (or other tart apples)","1 kg red bell pepper","300 g garlic","2 hot chili peppers","250 ml oil","250 ml sugar","250 ml spirit vinegar 9%","3 tbsp salt"],"steps":["Rinse the tomatoes, carrots, apples, and red bell peppers thoroughly, peel the carrots, apples, and garlic, and remove the seeds from the peppers.","Pass the tomatoes, carrots, apples, bell peppers, and garlic through a meat grinder.","Transfer the minced vegetable mixture to a large pot and simmer over low heat for 120 minutes, stirring occasionally.","Add the chopped hot chili peppers, oil, sugar, vinegar, and salt, stir well, and cook for about 30 minutes more."],"time":190,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ad%C5%BCika","page":"Książka kucharska/Adżika"},{"id":"oc-plwb-61677","title":"Charczo (Georgian beef and walnut soup)","cuisine":"Georgian","category":"Soup","ingredients":["700 g beef cheeks (or beef neck)","1 tbsp plain flour","1 tsp adjika (hot red pepper paste)","2 tsp sweet paprika","50 ml rapeseed oil","50 ml wine vinegar","2 red onions","1 carrot","1 parsley root (root)","0.5 celeriac","1 leek (white part)","4 clove garlic","150 g walnuts","450 g canned tomatoes","2 tbsp tomato paste","125 ml rice","3 tsp ground coriander seeds","1 tsp ground fennel seeds","2 bay leaf","5 allspice (berries)","1 bunch parsley leaves","1 bunch fresh coriander","1 bunch fresh tarragon","2 l water"],"steps":["Finely dice the beef cheeks, chop the garlic, parsley leaves, fresh coriander, and tarragon, dice the red onions and leek, and grate the carrot, parsley root, and celeriac.","Heat some of the rapeseed oil in a pot, cook the onion, leek, and garlic until translucent, stir in the plain flour, then add the grated soup vegetables and sweet paprika, cooking together briefly.","Stir in the tomato paste and canned tomatoes, pour in the water, and bring everything to a boil.","Meanwhile, brown the beef in the remaining oil in a separate skillet, transfer into the soup pot, deglaze the skillet with several spoonfuls of broth, and pour back into the soup.","Add the wine vinegar, adjika paste, allspice berries, bay leaves, ground coriander seeds, ground fennel seeds, and chopped walnuts, and simmer gently for about 40 minutes, skimming any foam.","Stir in the rice and cook for another 40 minutes, stirring so the soup does not stick, and finish with the chopped parsley leaves, fresh coriander, and tarragon before serving."],"time":120,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Charczo","page":"Książka kucharska/Charczo"},{"id":"oc-plwb-14173","title":"Avgolemono (Greek lemon chicken soup with rice)","cuisine":"Greek","category":"Soup","ingredients":["2 l turkey or chicken broth","250 g rice","3 egg yolks","2 lemons (squeezed juice)","to taste salt"],"steps":["Skim the fat from the cold broth, strain it, bring to a boil in a pot, and season with salt.","Add the uncooked rice to the boiling broth and cook for 20 minutes.","Whisk the egg yolks with the freshly squeezed lemon juice, then gradually whisk in a little hot broth to temper the mixture.","Pour the tempered egg-lemon mixture into the soup pot and heat thoroughly over low heat while stirring constantly, without letting it boil."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Awgolemono","page":"Książka kucharska/Awgolemono"},{"id":"oc-plwb-18358","title":"Baked giant beans (Zapiekanka z fasolą / Gigantes plaki)","cuisine":"Greek","category":"Main","ingredients":["500 g giant white beans (fasola Jaś) (dry)","1.5 l water (for soaking and boiling beans)","1 onion (large)","2 clove garlic","3 tomatoes","1 bunch parsley leaves (bunch)","1 tsp butter (for greasing the dish)","180 ml olive oil","1 tsp thyme","to taste salt","to taste black pepper"],"steps":["Soak the beans overnight in water, and the next day boil them (in the original recipe for 10 minutes; culinary note: dry giant white beans should be cooked until tender, approx. 60 minutes, before baking to break down lectins).","Heat olive oil in a large skillet, add the thick-sliced onion, chopped tomatoes, and crushed garlic, fry, sprinkle with chopped parsley, and season with salt and pepper.","Transfer the drained beans to a buttered baking dish, sprinkle with thyme, and cover with the fried vegetables along with the olive oil.","Bake for 30 minutes in an oven preheated to 200 °C and serve with crusty white bread."],"time":600,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_z_fasol%C4%85","page":"Książka kucharska/Zapiekanka z fasolą"},{"id":"oc-plwb-56103","title":"Corfiot veal sofrito (Sofrito Kerkyraiko)","cuisine":"Greek","category":"Main","ingredients":["6 boneless veal chops","5 clove garlic","6 tbsp parsley (finely chopped)","3 tbsp dry white wine (or wine vinegar)","8 tbsp olive oil","3 tsp plain flour","125 ml water","to taste salt","to taste black pepper"],"steps":["Brown the veal chops with finely chopped garlic in heated olive oil in a deep skillet.","Once the meat is browned, pour in 125 ml of water, season with salt and pepper, and braise covered over low heat for about 50 minutes until tender, then transfer the veal to a platter.","Dust the remaining sauce in the pan with the flour and stir until lightly browned.","Pour in the dry white wine and cook over low heat, stirring constantly, until the sauce thickens.","Pour the hot sauce over the veal chops and sprinkle with finely chopped parsley."],"time":75,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sofrito","page":"Książka kucharska/Sofrito"},{"id":"oc-plwb-56155","title":"Cypriot baked lamb with vegetables (Tavas)","cuisine":"Greek","category":"Main","ingredients":["2 kg boneless leg of lamb (boneless)","500 g potatoes","500 g zucchini","4 onions","500 g peeled tomatoes","1 tbsp tomato paste","250 ml water (warm)","125 ml olive oil","1 tbsp ground cinnamon","1 tbsp caraway seeds","to taste salt","to taste black pepper"],"steps":["Cut the lamb into bite-sized cubes.","Clean, wash, and chop the potatoes, zucchini, onions, and peeled tomatoes, and place in a large casserole dish along with the meat.","Dissolve the tomato paste in the warm water, mix with olive oil, cinnamon, caraway, salt, and black pepper, pour into the dish, and toss thoroughly.","Bake covered in an oven preheated to 180 °C for 90–120 minutes until the meat is fork-tender, adding splashes of water if needed."],"time":145,"servings":7,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jagni%C4%99cina_po_cypryjsku","page":"Książka kucharska/Jagnięcina po cypryjsku"},{"id":"oc-plwb-56160","title":"Cypriot pumpkin pastries (Kolokotes / Placuszki z dynią)","cuisine":"Greek","category":"Snack","ingredients":["500 g wheat flour","125 ml olive oil","125 ml water","to taste salt","1 kg pumpkin (grated)","200 g dark raisins","150 g bulgur wheat","2 onions","6 tbsp olive oil","0.5 tsp ground cinnamon","1 tbsp salt"],"steps":["Combine the wheat flour with 125 ml of olive oil and salt, add water, knead into an elastic dough, and set aside for 30 minutes.","Place the grated pumpkin in a colander lined with cheesecloth, toss with a tablespoon of salt, leave to release juices, and squeeze out firmly.","Peel and finely chop the onions, sauté in 6 tablespoons of olive oil, add the drained pumpkin, bulgur, raisins, and cinnamon, and fry while stirring until excess moisture evaporates.","Roll out the dough to a thickness of up to 5 mm, cut rounds 10–15 cm in diameter, place 1–2 tablespoons of filling on each, and crimp the edges.","Bake the turnovers in an oven preheated to 180 °C for about 30 minutes until golden."],"time":60,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Placuszki_z_dyni%C4%85","page":"Książka kucharska/Placuszki z dynią"},{"id":"oc-plwb-18799","title":"Dolmades (Greek stuffed vine leaves)","cuisine":"Greek","category":"Snack","ingredients":["55 young vine leaves (50–60 leaves)","60 ml lemon juice (from 1–2 lemons)","3 onions","125 ml olive oil (125 ml)","200 g rice (250 ml by volume)","2 tbsp parsley leaves (chopped)","2 tbsp fresh dill (chopped)","6 fresh mint leaves","500 ml water (for parboiling rice and braising)","to taste salt","to taste black pepper"],"steps":["Blanch the vine leaves in boiling water and arrange them flat on a plate to cool.","Finely chop the onions and gently fry in the olive oil.","Add the rice, chopped parsley leaves, dill, chopped mint, salt, pepper, and a splash of water to the onions; stir, simmer for 10 minutes, and let cool.","Place a teaspoon of filling near the stem end of each vine leaf, fold the sides inward, and roll tightly into neat parcels.","Line the bottom of the pot with the remaining vine leaves and pack the stuffed rolls closely on top.","Pour the remaining water mixed with the lemon juice over the parcels so they are just submerged, cover, and simmer over low heat for 40–45 minutes until the rice is tender.","Let cool and serve cold."],"time":95,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Faszerowane_li%C5%9Bcie_winogron","page":"Książka kucharska/Faszerowane liście winogron"},{"id":"oc-plwb-12566","title":"Eggplant moussaka","cuisine":"Greek","category":"Main","ingredients":["1.25 kg eggplant","700 g minced beef","3 tomatoes","1 onion (medium)","125 ml white wine","750 ml béchamel sauce","100 g semi-hard cheese (grated)","3 tbsp breadcrumbs (plus extra for dusting the dish)","1 tsp butter (plus extra for greasing the dish)","1 bunch parsley leaves","2 egg (whites and yolks separated)","to taste olive oil (for frying eggplants)","4 tbsp water (hot)","to taste salt","to taste black pepper"],"steps":["Char the eggplants over an open flame, rub off the charred skin, slice, sprinkle with salt, and let stand in a cool place for 60 minutes.","Melt the butter in a frying pan and cook the finely chopped onion until translucent without browning.","Pour in the hot water, add the minced beef, and fry while breaking it up with a fork to prevent lumps.","Add the peeled, seeded tomatoes, chopped parsley leaves, and white wine, season with salt and pepper, and braise covered over very low heat for about 45 minutes.","Remove the meat from the heat, stir in the breadcrumbs, then fold in the lightly beaten egg whites.","Rinse the eggplant slices, dry thoroughly on a kitchen cloth, and fry in heated olive oil on both sides until golden.","Butter and coat with breadcrumbs a shallow baking dish measuring about 30 × 20 cm, arrange a layer of eggplants on the bottom, spread the meat and tomato mixture on top, and cover with the remaining eggplants.","Mix the béchamel sauce with the egg yolks and 60 g of grated cheese, pour over the casserole, scatter with the remaining cheese, and bake in an oven preheated to 180 °C for about 45 minutes until golden."],"time":165,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Musaka_z_bak%C5%82a%C5%BCan%C3%B3w","page":"Książka kucharska/Musaka z bakłażanów"},{"id":"oc-plwb-56115","title":"Fanouropita (Greek spiced orange and walnut cake)","cuisine":"Greek","category":"Cake","ingredients":["500 g plain flour (plus extra for dusting the pan)","300 g sugar (375 ml by volume)","250 ml orange juice (250 ml)","125 ml water (125 ml)","80 ml olive oil (approx. 80 ml, plus extra for the pan)","120 g walnuts (250 ml by volume, chopped)","150 g raisins (250 ml by volume)","2 tsp ground cinnamon","1 tsp ground cloves","2 tsp baking powder","to taste orange zest"],"steps":["Beat the olive oil with the sugar until pale, then pour in the orange juice and stir in the grated orange zest.","Mix the flour with the baking powder, cinnamon, and ground cloves.","Combine the dry ingredients with the water and the orange-oil mixture, beating until a smooth batter forms.","Fold in the raisins and roughly chopped walnuts using a wooden spoon.","Pour the batter into an oiled and floured 25–30 cm round baking tin, and bake for about 60 minutes in an oven preheated to 175 °C."],"time":80,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fanuropita","page":"Książka kucharska/Fanuropita"},{"id":"oc-plwb-56210","title":"Filo pastry","cuisine":"Greek","category":"Other","ingredients":["500 g wheat flour","3.5 tbsp olive oil (3–4 tbsp)","250 ml water (or 120 ml)","2 eggs","to taste wheat flour for dusting (for dusting)"],"steps":["Sift the wheat flour into a large mixing bowl and slowly drizzle in the olive oil while working the dough vigorously.","Pour in the lightly beaten eggs whisked with water and knead firmly until a smooth, pliable dough forms.","Roll the dough out slightly on a floured surface, cover with a damp kitchen cloth, and let rest for 30 minutes.","Divide the dough into 8 portions, roll each out on a floured surface until paper-thin, dusting with flour as needed, then leave to air-dry slightly."],"time":30,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_fyllo","page":"Książka kucharska/Ciasto fyllo"},{"id":"oc-plwb-56383","title":"Giouvetsi (Greek baked lamb with orzo pasta)","cuisine":"Greek","category":"Main","ingredients":["600 g leg of lamb","400 g canned tomatoes (in juice)","6 clove garlic","250 ml olive oil","300 g orzo pasta","to taste herbes de Provence","to taste sweet ground paprika","120 ml dry wine","300 ml water (for basting while baking)","to taste salt"],"steps":["Slice the lamb, season with salt, herbes de Provence, and sweet paprika, and sear in one-third of the olive oil.","Transfer the meat to a baking dish, drizzle with another one-third of the olive oil, and bake in an oven preheated to 180 °C until tender, basting with wine and water.","Finely chop the garlic, crush the canned tomatoes with a fork, and simmer together in the remaining olive oil over low heat until slightly thickened.","Mix the hot tomato sauce with the dry orzo pasta, pour over the baked meat, add extra water if needed, and bake in the oven until the pasta is tender."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jagni%C4%99cina_z_makaronem","page":"Książka kucharska/Jagnięcina z makaronem"},{"id":"oc-plwb-56145","title":"Greek lemon butter lamb with rice (Arni lemonato)","cuisine":"Greek","category":"Main","ingredients":["1 kg leg of lamb","2 lemons","1 onion (large)","250 g butter","500 g rice","500 ml water","to taste salt","to taste black pepper"],"steps":["Trim the lamb and cut into serving portions, chop the onion, and squeeze the juice from the lemons.","Place the meat and onion into a pot, pour in the lemon juice, and braise until the liquid is absorbed.","Add the butter and brown the meat, then season with salt and pepper, pour in the water, and braise covered until tender.","Remove the cooked meat from the pot, stir the rice into the remaining cooking juices, and cook until tender.","Return the lamb to the pot with the rice, warm through for a moment, and serve hot."],"time":105,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jagni%C4%99cina_z_ry%C5%BCem_i_cytryn%C4%85","page":"Książka kucharska/Jagnięcina z ryżem i cytryną"},{"id":"oc-plwb-56094","title":"Greek salad (choriatiki)","cuisine":"Greek","category":"Salad","ingredients":["3 ripe tomatoes","1 sweet bell pepper","1 small cucumber","1 red onion","75 g olives (125 ml by volume)","150 g feta cheese (250 ml by volume, crumbled)","5 tbsp olive oil","2 tbsp wine vinegar","to taste salt","to taste oregano"],"steps":["Cut the tomatoes and sweet pepper into bite-sized wedges, and slice the cucumber and red onion into thick rounds.","Place the vegetables into a salad bowl and toss gently with the olives and diced feta cheese.","Drizzle with the olive oil and wine vinegar, then season to taste with salt and oregano."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Grecka_sa%C5%82atka_wiejska","page":"Książka kucharska/Grecka sałatka wiejska"},{"id":"oc-plwb-18575","title":"Greek salad with mint","cuisine":"Greek","category":"Salad","ingredients":["500 g tomatoes","2 cucumbers","2 onions","1 green bell pepper","100 g black olives","200 g Feta-style cheese","0.5 bunch fresh mint","3 tbsp vinaigrette dressing (for drizzling)"],"steps":["Wash the tomatoes and cucumbers and slice them into rounds.","Peel the onions and slice into rings; wash, core, and slice the green bell pepper into strips.","Dice the feta cheese into cubes and rinse the fresh mint leaves.","Gently toss the vegetables with the black olives, feta cheese, and mint leaves, then drizzle the salad with the vinaigrette."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Grecka_sa%C5%82atka_z_mi%C4%99t%C4%85","page":"Książka kucharska/Grecka sałatka z miętą"},{"id":"oc-plwb-6269","title":"Greek-style bake (Zapiekanka grecka)","cuisine":"Greek","category":"Main","ingredients":["1 kg potatoes","1 red bell pepper (pod)","300 g minced meat","200 g firm cheese (grated)","to taste rosemary","1 Greek casserole seasoning mix (fix type) (packet)","300 ml water (for braising the meat)","to taste fat (for frying and greasing the baking dish)"],"steps":["Slice the potatoes, fry them in a skillet in heated fat, and transfer to a plate.","In the same fat, fry the bell pepper cut into large dice.","Fry the minced meat in a dry skillet, pour in 300 ml of water, add the casserole seasoning mix, stir, and braise for about 5 minutes.","Grease an ovenproof dish with fat and layer the potatoes, bell pepper, grated cheese, and meat with rosemary alternately.","Sprinkle the top of the casserole with grated firm cheese and bake in the oven for about 30 minutes."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_grecka","page":"Książka kucharska/Zapiekanka grecka"},{"id":"oc-plwb-14344","title":"Greek-style chicken with feta and tomatoes","cuisine":"Greek","category":"Main","ingredients":["500 g chicken breast fillet","1 onion","1 red bell pepper","400 g canned tomatoes in juice","5 olives","1 tbsp butter","100 g feta cheese","to taste parsley","to taste salt","to taste sugar","1 pinch chicken seasoning","to taste oregano","to taste pepper","to taste rosemary","to taste sweet ground paprika","3 clove garlic"],"steps":["Dice the chicken breast fillet and brown it in a saucepan in the melted butter.","Add the chopped onion and strips of bell pepper, frying until the vegetables soften.","Add the chopped canned tomatoes with their juice, sliced olives, and chopped garlic, simmering everything over low heat.","Add the diced feta cheese and season with oregano, rosemary, sweet paprika, chicken seasoning, salt, pepper, and a pinch of sugar.","Scatter over the chopped parsley and heat for a few moments more."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_po_grecku","page":"Książka kucharska/Kurczak po grecku"},{"id":"oc-plwb-14640","title":"Gyros (pan-fried seasoned pork strips)","cuisine":"Greek","category":"Main","ingredients":["330 g pork cutlets (3 cutlets, 100–120 g each)","0.5 tsp ground paprika","1 tsp oregano","2 tbsp vegetable oil","125 ml water","to taste salt","to taste black pepper"],"steps":["Rinse the pork in cold water, pat dry with paper towels, slice each cutlet lengthwise, and cut into thin strips.","Mix the salt, black pepper, ground paprika, and oregano in a bowl, stir into the water, and add the vegetable oil.","Add the meat to the marinade and let sit for 90 minutes.","Remove the meat strips and fry in a hot pan without additional fat for 2–3 minutes, turning occasionally."],"time":106,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gyros","page":"Książka kucharska/Gyros"},{"id":"oc-plwb-56153","title":"Herb risotto","cuisine":"Greek","category":"Main","ingredients":["400 g rice","50 g scallion (chopped)","1 tbsp parsley leaves (chopped)","1 tbsp fresh dill (chopped)","1 tbsp fresh tarragon (chopped)","1 tbsp fresh basil (chopped)","1 tbsp dried thyme","125 ml dry white wine","50 g Parmesan (grated)","6 tbsp olive oil","to taste salt","to taste pepper","1.25 l water (warm)"],"steps":["Finely chop the scallions, parsley leaves, dill, basil, and tarragon.","Heat the olive oil in a pot, sauté the scallions, then add the rice and fry together for a few minutes, stirring constantly.","Pour in 1.25 l of warm water and the dry white wine, add the chopped herbs, part of the thyme, salt, and pepper, and cook over low heat for 20–25 minutes until the rice absorbs the liquid.","Sprinkle the finished risotto with grated Parmesan and the rest of the thyme, and serve immediately."],"time":35,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Risotto_z_zio%C5%82ami","page":"Książka kucharska/Risotto z ziołami"},{"id":"oc-plwb-56095","title":"Imam (stuffed eggplant)","cuisine":"Greek","category":"Main","ingredients":["8 eggplants (aubergines)","4 onions (large)","3 clove garlic","3 tomatoes","1 tbsp tomato paste","8 tbsp fresh parsley leaves (chopped)","6 tbsp olive oil (4 tbsp for drizzling and about 2 tbsp for frying)","200 ml water (for braising onions and diluting paste)","to taste salt","to taste black pepper","to taste cayenne pepper"],"steps":["Trim the stalks from the eggplants, make 2–3 lengthwise slits in each, salt well, and set aside for about 60 minutes.","Rinse the eggplants, squeeze out excess moisture thoroughly, and sauté in heated olive oil on all sides until golden.","Slice the onions and simmer in a splash of lightly salted water until the liquid evaporates.","Mix the braised onions with sliced garlic, diced tomatoes, and the tomato paste diluted in 125 ml of warm water, then season with salt, black pepper, and cayenne pepper.","Arrange the eggplants on a baking tray and stuff the slits with the prepared thick filling.","Sprinkle with the chopped fresh parsley leaves, drizzle with the remaining olive oil, and bake in an oven preheated to 180 °C for about 60 minutes."],"time":150,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nadziewany_bak%C5%82a%C5%BCan_(imam)","page":"Książka kucharska/Nadziewany bakłażan (imam)"},{"id":"oc-plwb-56109","title":"Keftedes (Greek meatballs)","cuisine":"Greek","category":"Main","ingredients":["500 g minced veal","3 slice bread","1 onion","1 egg","125 ml sparkling water","1 tbsp ouzo","3 tbsp parsley (chopped)","3 tbsp fresh mint (chopped)","2 tbsp olive oil (for the meat mixture, plus extra for frying)","to taste plain flour (for dredging)","to taste salt","to taste pepper"],"steps":["Soak the bread slices in water and squeeze out thoroughly, grate the onion, and finely chop the parsley and mint.","Combine the minced veal with the squeezed bread, grated onion, egg, 125 ml of sparkling water, the ouzo, parsley, mint, and 2 tbsp of olive oil.","Season the mixture with salt and pepper, knead thoroughly, and refrigerate for about 60 minutes.","Shape the chilled mixture into small balls, dredge them in plain flour, and fry in hot olive oil in a deep skillet for 15 minutes."],"time":90,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Keftedes","page":"Książka kucharska/Keftedes"},{"id":"oc-plwb-61129","title":"Kleftiko (Greek slow-roasted lamb with vegetables)","cuisine":"Greek","category":"Main","ingredients":["1 kg bone-in lamb","2 tomatoes","1 onion","1 garlic (head)","2 fresh rosemary (sprigs)","4 potatoes","1 carrot","190 ml olive oil (65 ml for the marinade, 125 ml for roasting)","125 ml red wine","1 tsp oregano","1 tsp thyme","to taste salt","to taste pepper"],"steps":["Mix 125 ml of red wine with 65 ml of olive oil, the oregano, thyme, and crushed cloves from the whole head of garlic, immerse the lamb in the marinade, and set aside for 6 hours.","Peel the potatoes and onion and cut into quarters, slice the scraped carrot into thick rounds, and cut the tomatoes into smaller pieces.","Pour the remaining 125 ml of olive oil into the bottom of a roasting dish, arrange the chopped vegetables, and place the lamb on top along with the marinade and rosemary sprigs.","Season everything with salt and pepper, cover the dish tightly with a lid or transfer the ingredients to a roasting bag, and bake for 150 minutes."],"time":530,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kleftiko","page":"Książka kucharska/Kleftiko"},{"id":"oc-plwb-14808","title":"Koreczki greckie (Greek party skewers)","cuisine":"Greek","category":"Snack","ingredients":["100 g black olives (in brine)","1 cucumber","3 tomatoes","200 g feta cheese","0.5 tsp herbs de Provence","to taste salt","to taste ground black pepper"],"steps":["Drain the black olives from the brine, wash the cucumber, and cut it into thick dice.","Wash the tomatoes, deseed them, and cut the flesh into pieces, and cut the feta cheese into neat cubes.","Thread onto toothpicks in order: a cucumber piece, a cube of feta, a tomato piece, and an olive.","Layer the skewers in a dish, dusting each layer with herbs de Provence, ground black pepper, and a pinch of salt, then set aside for 15 minutes before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Koreczki_greckie","page":"Książka kucharska/Koreczki greckie"},{"id":"oc-plwb-17997","title":"Kotopita (Greek chicken phyllo pie)","cuisine":"Greek","category":"Main","ingredients":["1 whole chicken","500 g phyllo pastry","250 g butter","250 g firm cheese","1 onion","1 bunch parsley","2 eggs","1 l water","to taste salt","to taste pepper"],"steps":["Place the chicken in a pot, pour over 1 l of salted water, add the sliced onion, and simmer until the meat is tender.","Remove the cooked chicken, reserving the broth and onion. Skin and bone the chicken, and shred or dice the meat finely.","Beat the eggs and mix with the grated firm cheese, chopped parsley, salt, and pepper.","Add the chicken pieces along with the broth and cooked onion, stirring into a cohesive filling.","Divide the phyllo pastry into two portions. Line a buttered baking dish with half of the sheets, brushing each sheet with melted butter, spread the chicken filling over, and top with the second portion of phyllo sheets brushed with butter.","Bake for 60 minutes in an oven preheated to 200 °C."],"time":90,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_zapiekany_w_cie%C5%9Bcie","page":"Książka kucharska/Kurczak zapiekany w cieście"},{"id":"oc-plwb-20805","title":"Koulourakia (Greek butter cookies)","cuisine":"Greek","category":"Cookie","ingredients":["150 g butter (plus extra for greasing the baking sheet)","150 g sugar","2 eggs (1 for dough, 1 for egg wash)","2 egg yolks","150 g plain flour","2 tsp baking powder"],"steps":["Beat the butter with the sugar until smooth, light, and creamy.","Add 1 whole egg and 2 egg yolks and beat until smooth.","Add the flour mixed with the baking powder and knead into a soft dough.","Place the dough in the refrigerator to chill for 60 minutes.","Roll the dough into thin ropes and shape them into small rings or crescents.","Arrange the cookies on a buttered baking sheet, brush the tops with the remaining beaten egg, and bake for 10–12 minutes in an oven preheated to 150 °C."],"time":87,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Greckie_rogaliki_ma%C5%9Blane","page":"Książka kucharska/Greckie rogaliki maślane"},{"id":"oc-plwb-56167","title":"Koupes (Cypriot bulgur and meat croquettes)","cuisine":"Greek","category":"Main","ingredients":["1250 ml bulgur wheat","1250 ml warm water","110 g olive oil","125 g plain flour","to taste salt","500 g minced meat","3 onion","1 clove garlic","2 tbsp parsley (chopped)","1 tsp ground cinnamon","1 egg white","3 tbsp olive oil (plus extra for frying)","to taste pepper"],"steps":["Mix the bulgur wheat with 110 g of olive oil, add salt and 1250 ml of warm water, and set aside for 2 hours to swell.","Finely chop the onions and garlic, sauté in 3 tablespoons of olive oil, add the minced meat, and cook while stirring constantly until browned.","Stir the chopped parsley, cinnamon, salt, and pepper into the meat, remove from heat, let cool, and mix thoroughly with the egg white.","Add the flour to the soaked bulgur and knead into a dough. Take 1 tablespoon of dough at a time, flatten into an oval, place 1 teaspoon of meat filling in the centre, and seal into oblong croquettes.","Fry the croquettes in very hot olive oil until golden and serve hot."],"time":45,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krokiety_kupes","page":"Książka kucharska/Krokiety kupes"},{"id":"oc-plwb-56099","title":"Mutzerta (moutzendra / Cypriot lentils and rice with browned onions)","cuisine":"Greek","category":"Main","ingredients":["500 g lentils (preferably large-seeded)","125 ml white rice","2 onions","6 tbsp olive oil","1.5 l water (for cooking)","to taste salt","to taste black pepper"],"steps":["Cover the lentils with plenty of water and cook for about 30 minutes, until they begin to soften.","Add the rice to the simmering lentils, season with salt and pepper, and cook over low heat for another 20–30 minutes, until the grains absorb the liquid.","Slice the onions and fry in heated olive oil until golden.","Stir the browned onions along with their oil into the cooked lentils and rice before serving."],"time":70,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mutzerta","page":"Książka kucharska/Mutzerta"},{"id":"oc-plwb-57549","title":"Naleśniki ze szpinakiem i serem feta (spinach and feta stuffed crepes)","cuisine":"Greek","category":"Main","ingredients":["3 eggs","400 g plain flour","0.5 tsp sea salt (fine)","150 ml milk","150 ml water","1 tbsp olive oil","1 onion","6 sun-dried tomatoes in oil","400 g spinach","100 g feta cheese (crumbled)","4 tsp rapeseed oil (for frying)","0.5 tsp granulated garlic","1 tsp seasoning mix"],"steps":["Combine the eggs, sea salt, milk, and olive oil in a bowl, add the flour and whisk, gradually pouring in water until a uniform batter forms.","Heat part of the rapeseed oil in a skillet and fry thin crepes.","Dice the onion and sauté in the remaining rapeseed oil until golden brown.","Add the washed and blanched spinach, sliced sun-dried tomatoes, crumbled feta, granulated garlic, and seasoning blend, and mix the filling well.","Spread the spinach-feta filling over the fried crepes, roll into tight cylinders, and sear briefly on both sides in a hot skillet."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nale%C5%9Bniki_ze_szpinakiem_i_serem_feta","page":"Książka kucharska/Naleśniki ze szpinakiem i serem feta"},{"id":"oc-plwb-56150","title":"Paluszki dam (daktyla kyrion / Cypriot almond pastry fingers in syrup)","cuisine":"Greek","category":"Cookie","ingredients":["625 ml plain flour","3 tbsp olive oil","1 tbsp margarine","1 tsp salt","100 ml water (cold, for kneading dough)","250 ml almonds (soaked, peeled and chopped)","2 tbsp sugar","2 tbsp rosewater","1 tsp ground cinnamon","250 ml olive oil (for frying)","500 ml sugar","500 ml water","2 tbsp lemon juice","3 whole cloves","1 cinnamon stick"],"steps":["Mix the flour with salt, rub in the margarine and 3 tablespoons of olive oil with your fingertips, add the cold water, knead into an elastic dough, and rest for 30 minutes.","In a bowl, combine the chopped almonds with 2 tablespoons of sugar, ground cinnamon, and rosewater.","Bring the syrup ingredients (water, sugar, lemon juice, cloves, and cinnamon stick) to a boil in a saucepan, boil for 5 minutes, and leave to cool.","Roll out the dough thinly, cut into squares about 8 cm on each side, place a teaspoon of almond filling on each, moisten the edges with water, and crimp into finger shapes.","Fry the pastry fingers in very hot olive oil until golden.","Remove the hot pastries with a slotted spoon, dip them one by one in the cold syrup, and arrange on a platter."],"time":60,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Paluszki_dam","page":"Książka kucharska/Paluszki dam"},{"id":"oc-plwb-56157","title":"Pasta z ikry - taramosalata (Greek salted fish roe dip)","cuisine":"Greek","category":"Sauce","ingredients":["125 g cured fish roe (taramas)","3 slice stale bread","250 ml olive oil","2 tbsp lemon juice","1 onion (small, finely chopped)","to taste black pepper","100 ml water (for soaking bread)"],"steps":["Soak the bread slices in water, remove crusts once softened, squeeze out excess water thoroughly, and mash into a smooth paste.","Add the fish roe and lemon juice, then whisk or blend while pouring in the olive oil in a slow steady stream until a smooth, creamy emulsion forms.","Season with pepper, fold in the very finely chopped onion at the end, and spoon onto a serving plate."],"time":30,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pasta_z_ikry_-_taramosalata","page":"Książka kucharska/Pasta z ikry - taramosalata"},{"id":"oc-plwb-56158","title":"Psarosoupa avgolemono (Greek fish soup)","cuisine":"Greek","category":"Soup","ingredients":["1 kg fish such as cod or carp","3 tomatoes","2 onions","1 carrot","100 g celeriac (a quarter of a root)","125 g rice","60 ml olive oil","2 eggs","1 lemon (juice)","1 tbsp parsley leaves (chopped)","1.5 l water","1 bay leaf","to taste salt","to taste black pepper"],"steps":["Clean and rinse the fish, cut into steaks, and season with salt.","Chop the onions, slice the carrot and celeriac into rounds, and peel, seed, and quarter the tomatoes.","Bring 1.5 liters of water to a boil in a pot, add the chopped vegetables, bay leaf, salt, pepper, and olive oil, and simmer over low heat for 30 minutes.","Add the fish pieces to the broth and cook for another 15 minutes, then lift them out onto a plate.","Scoop out the cooked vegetables, puree until smooth, and stir back into the broth.","Add the rice and simmer for about 20 minutes until tender, then remove the pot from the heat.","Beat the eggs with the lemon juice, then slowly pour the mixture into the hot soup while stirring vigorously throughout.","Serve the soup garnished with chopped parsley leaves."],"time":85,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Grecka_zupa_rybna","page":"Książka kucharska/Grecka zupa rybna"},{"id":"oc-plwb-14639","title":"Souvlaki (Suwlaki)","cuisine":"Greek","category":"Main","ingredients":["1 lemon (juiced)","60 ml olive oil","60 ml soy sauce","1 tsp oregano","3 clove garlic","2 kg tenderloin (diced)","1 red onion","1 bell pepper (green or red)"],"steps":["Mix the lemon juice, olive oil, soy sauce, oregano, and finely minced garlic in a bowl.","Add the diced tenderloin along with pieces of red onion and bell pepper, toss thoroughly, cover, and chill in the refrigerator for 150 minutes.","Thread the marinated meat along with pieces of onion and pepper onto skewers.","Grill the skewers on a hot grate or in the oven for about 20 minutes until browned."],"time":185,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Suwlaki","page":"Książka kucharska/Suwlaki"},{"id":"oc-plwb-56203","title":"Spanakopita (Szpinak w cieście)","cuisine":"Greek","category":"Main","ingredients":["1 kg fresh spinach","300 g sheep's milk cheese (or farmer's cheese)","500 g filo pastry","3 onions (large)","1 dill (sprig)","375 ml vegetable oil","375 ml unsweetened evaporated milk","2 eggs","to taste salt","to taste pepper","to taste nutmeg"],"steps":["Rinse the spinach, remove tough stems, finely chop the leaves, sprinkle with salt, and let stand for 15 minutes; meanwhile, finely chop the onions and dill.","Prepare the filo sheets and cover with a cloth to prevent drying out.","Firmly squeeze excess liquid from the spinach, combine with the onion, dill, crumbled sheep's cheese, unsweetened evaporated milk, beaten eggs, and half the oil, and season with pepper and nutmeg.","Brush a baking dish with part of the remaining oil, line bottom and sides with half the filo pastry, spread the spinach filling, cover with the remaining pastry, and brush the top with oil.","Bake in a well-preheated oven at 180 °C for 60 minutes and serve piping hot."],"time":105,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szpinak_w_cie%C5%9Bcie","page":"Książka kucharska/Szpinak w cieście"},{"id":"oc-plwb-21298","title":"Spicy Greek tomato and cucumber salad (Pikantna sałatka pomidorowa)","cuisine":"Greek","category":"Salad","ingredients":["0.5 fresh cucumber","2 tomatoes (peeled, seeded)","0.5 onion","2 clove garlic","1 tbsp parsley leaves (chopped)","1 tbsp fresh mint (chopped)","to taste black pepper","to taste cayenne pepper","1 tbsp olive oil","to taste lemon juice"],"steps":["Finely chop the cucumber, peeled and seeded tomatoes, onion, garlic, parsley leaves, and mint leaves, and transfer to a bowl.","Season the salad with black pepper, cayenne pepper, olive oil, and lemon juice, and toss well to combine."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pikantna_sa%C5%82atka_pomidorowa","page":"Książka kucharska/Pikantna sałatka pomidorowa"},{"id":"oc-plwb-2462","title":"Tzatziki sauce (Sos tzatziki)","cuisine":"Greek","category":"Sauce","ingredients":["500 ml plain curd cheese (or thick Greek yogurt)","4 clove garlic","1 fresh cucumber","1 tbsp olive oil","1 tbsp wine vinegar","1 pinch salt","1 pinch thyme","to taste pepper"],"steps":["Peel the cucumber, grate it or dice finely, and squeeze out excess juice thoroughly.","Peel the garlic and press through a garlic press or mince very finely.","Mix the cucumber and garlic with the plain curd cheese, then stir in the olive oil and wine vinegar.","Season the sauce with a pinch of salt, thyme, and pepper.","Mix thoroughly and refrigerate for at least 15 minutes before serving."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_tzatziki","page":"Książka kucharska/Sos tzatziki"},{"id":"oc-plwb-23403","title":"Zorba's delight (pork and bean stew)","cuisine":"Greek","category":"Main","ingredients":["1.5 kg pork","500 g white beans","250 ml tomato juice","1 onion (large)","125 ml olive oil","1 bunch parsley leaves (chopped)","250 ml water (for braising)"],"steps":["Cut the pork into bite-sized pieces and finely chop the large onion.","Heat the olive oil in a saucepan, brown the meat with the onion until golden, then pour in the tomato juice and simmer covered for 40–50 minutes.","Boil the white beans separately for 5 minutes, drain, and add to the simmering meat.","Add 250 ml of water to the pot and simmer until the liquid reduces and the sauce thickens, then sprinkle with chopped parsley leaves."],"time":80,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Przysmak_Zorby","page":"Książka kucharska/Przysmak Zorby"},{"id":"oc-plwb-27340","title":"Dal (Dhal - Indian red lentil soup)","cuisine":"Indian","category":"Soup","ingredients":["3 carrots","2 parsley root (roots)","1 canned diced tomatoes (can or carton)","1 vegetable bouillon cube (cube)","1 l water (for cooking broth)","65 g red lentils (approximately 83 ml)","4 tbsp coconut milk (canned)","1 tsp garam masala (or cardamom and cinnamon)","1 tsp hot paprika"],"steps":["Peel the carrots and parsley root, cover with water and the vegetable bouillon cube, and cook for about 20 minutes.","Blend the cooked vegetables together with the broth until smooth.","Add the diced tomatoes, rinsed red lentils, coconut milk, garam masala, and hot paprika.","Simmer the soup over low heat for another 15 minutes until the lentils are tender."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_Dal_(Dhal)","page":"Książka kucharska/Zupa Dal (Dhal)"},{"id":"oc-plwb-18858","title":"Indian-style baked chicken and lamb with peppers","cuisine":"Indian","category":"Main","ingredients":["1 chicken breast fillet (small)","250 g lamb","2 onions","0.5 green bell pepper","0.5 red bell pepper","0.5 yellow bell pepper","150 g plain yogurt (1 tub)","to taste vegetable oil (for frying)","to taste ground cinnamon","to taste caraway","to taste ground coriander","to taste ground cloves","to taste ground nutmeg","to taste salt","to taste black pepper"],"steps":["Cut the chicken breast fillet and lamb into small pieces, season with salt, black pepper, cinnamon, caraway, coriander, cloves, and nutmeg, and immerse in the plain yogurt for 10 minutes.","Remove the meat from the marinade and bake for 45 minutes in an oven preheated to 190 °C.","Peel the onions, cut into quarters, fry in heated vegetable oil, and remove from the pan.","Seed the green, red, and yellow bell pepper halves, cut into smaller pieces, and fry in the same pan.","Remove the baked meat from the oven and arrange the sautéed onions and bell peppers around it."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mi%C4%99sa_pieczone_po_indyjsku","page":"Książka kucharska/Mięsa pieczone po indyjsku"},{"id":"oc-plwb-61680","title":"Rasam (South Indian tomato soup)","cuisine":"Indian","category":"Soup","ingredients":["750 ml water","2 tbsp vegetable oil","4 tomato (ripe)","10 g fresh coriander (chopped)","1 tsp fresh ginger (grated)","1 tsp mustard seeds","0.5 tsp ground cumin","3 black peppercorns (berries)","1 pinch hot paprika"],"steps":["Scald the tomatoes, peel, seed, and dice the flesh finely, and chop the fresh coriander.","Heat the vegetable oil, sauté the grated ginger, add a splash of water, and simmer for a moment.","Transfer the ginger to a large pot, pour in the remaining water, add the chopped tomatoes, and cook until they break down completely.","Toast the mustard seeds in a separate pan until they begin to pop, then add them to the tomato soup.","Season the soup with ground cumin, black peppercorns, and a pinch of hot paprika, add the chopped coriander, and stir to let the flavours meld."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rasam","page":"Książka kucharska/Rasam"},{"id":"oc-plwb-17766","title":"Spiced mango salad with yogurt (Sałatka z mango)","cuisine":"Indian","category":"Salad","ingredients":["1 mango (large, ripe)","to taste lemon juice (freshly squeezed)","1 tbsp vegetable oil","to taste chili","to taste fresh ginger (finely chopped or grated)","to taste mustard seeds","to taste lemon zest (grated)","to taste plain yogurt","to taste salt"],"steps":["Peel the mango, separate the flesh from the stone, dice it, and toss in a bowl with freshly squeezed lemon juice.","Heat the oil in a frying pan, add the chili, ginger, and mustard seeds, and cook briefly until the mustard seeds begin to pop.","Add the lemon zest to the pan, stir well, and remove from the heat.","Pour the hot spiced oil over the diced mango, stir, and once cooled, fold in the plain yogurt and season with salt."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_mango","page":"Książka kucharska/Sałatka z mango"},{"id":"oc-plwb-61180","title":"Averna Blood Orange Cocktail","cuisine":"Italian","category":"Drink","ingredients":["40 ml Amaro Averna liqueur (4 cl)","to taste ice cubes","to taste blood orange juice (chilled, to top up glass)"],"steps":["Fill a glass with ice cubes and pour in the measured portion of Averna liqueur.","Top up the glass with cold blood orange juice, stir gently, and serve."],"time":3,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Averna","page":"Książka kucharska/Averna"},{"id":"oc-plwb-15574","title":"Baked eggplants (Zapiekane bakłażany)","cuisine":"Italian","category":"Main","ingredients":["2 eggplants","500 g tomatoes","2 tbsp olive oil","6 basil leaves (leaves, chopped)","5 tbsp Parmesan cheese (grated)","300 g mozzarella","to taste salt","to taste black pepper"],"steps":["Cut each eggplant lengthwise into 6 slices and peel the skin from the outer slices.","Salt the eggplant slices, let rest for 30 minutes, then rinse and pat dry.","Brush the eggplants with olive oil on both sides, arrange on a parchment-lined baking sheet, and bake in an oven preheated to 200 °C for 8 minutes per side.","Scald the tomatoes, peel the skin, quarter them, remove the seeds, coarsely chop the flesh, and mix with chopped basil, salt, and pepper.","Place the 4 largest eggplant slices on the baking sheet and layer each with tomatoes, thin slices of mozzarella, Parmesan, and more eggplant slices, finishing with Parmesan on top.","Bake for 10–15 minutes in a hot oven until the mozzarella melts and browns."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekane_bak%C5%82a%C5%BCany","page":"Książka kucharska/Zapiekane bakłażany"},{"id":"oc-plwb-18560","title":"Baked pears with nuts in raspberry wine sauce","cuisine":"Italian","category":"Dessert","ingredients":["4 pears","2 tbsp raspberry juice","125 ml white wine","2 tbsp chopped almonds","2 tbsp raisins","1 tbsp honey","0.5 tsp ground ginger","to taste lemon juice"],"steps":["Chop the raisins, combine with the chopped almonds and honey, and season with ginger.","Core the pears from the bottom, peel them, sprinkle with lemon juice, fill with the nut mixture, and arrange in a baking dish.","Mix the raspberry juice with the white wine and pour over the pears.","Bake for 20 minutes in an oven preheated to 180 °C and serve warm."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gruszki_w_malinowym_sosie","page":"Książka kucharska/Gruszki w malinowym sosie"},{"id":"oc-plwb-31709","title":"Beef and prosciutto ravioli","cuisine":"Italian","category":"Main","ingredients":["300 g tomato pasta dough","1 tbsp olive oil","345 g minced beef","60 g prosciutto ham (chopped)","1 egg","0.5 tsp dried basil","0.5 tsp dried oregano","55 g Pecorino Romano (freshly grated)","2 tbsp butter","2 tbsp plain flour","250 ml 12% sour cream (light)","480 g fresh tomato purée"],"steps":["Prepare the tomato pasta dough, roll it out into thin sheets, and cover with a damp cloth.","Heat the olive oil in a skillet, brown the minced beef, drain off excess fat, let the meat cool, and transfer to a bowl.","Combine the cooled beef with chopped prosciutto, egg, basil, oregano, and grated Romano cheese.","Place portions of filling at even intervals on one pasta sheet, moisten the pasta around the filling with water, cover with a second sheet, press the edges together, and cut out the ravioli with a pastry wheel.","Melt the butter in a saucepan, add the plain flour, and cook over low heat for 2 minutes. Pour in the sour cream, bring to a boil and cook until thickened, then stir in the tomato purée and simmer for 20 minutes.","Cook the ravioli in a large pot of boiling water for about 2 minutes until they float, drain, divide among plates, and spoon the hot tomato and sour cream sauce over them."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ravioli","page":"Książka kucharska/Ravioli"},{"id":"oc-plwb-56361","title":"Beef scaloppine alla napoletana with capers","cuisine":"Italian","category":"Main","ingredients":["600 g boneless beef (tenderloin or round)","4 tbsp butter","2 tbsp olive oil","50 g capers","50 ml wine vinegar","3 tbsp water (a few tablespoons for braising)","to taste plain flour (for dredging)","to taste parsley leaves (chopped)","to taste salt","to taste black pepper"],"steps":["Slice the beef into escalopes, gently pound to a thickness of about 5 mm, and dredge in plain flour.","Heat the butter and olive oil in a skillet, add the scaloppine, and fry for 2–3 minutes on each side until golden.","Add the capers, pour in a few tablespoons of water, season with salt and pepper, and simmer covered over low heat until the meat is tender.","Pour in the wine vinegar, uncover the skillet, and cook for another 2 minutes.","Garnish with the chopped parsley leaves and stir gently before serving."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Eskalopki_po_neapolita%C5%84sku","page":"Książka kucharska/Eskalopki po neapolitańsku"},{"id":"oc-plwb-55024","title":"Blood orange sorbet","cuisine":"Italian","category":"Dessert","ingredients":["4 blood oranges (plus extra slices for garnish)","400 g sugar","400 ml water","to taste fresh mint (leaves for garnish)"],"steps":["Squeeze the juice from the 4 blood oranges.","Dissolve the sugar in 400 ml of water and simmer over low heat until a thick syrup forms.","Combine the syrup with the orange juice, cool completely (about 15 minutes), and freeze for at least 180 minutes, stirring occasionally with a spoon.","Remove the frozen sorbet from the freezer, let stand for 2–3 minutes, then chop with a knife and blend.","Spoon the sorbet into tall glasses and garnish with orange slices and mint leaves."],"time":220,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sorbet_z_czerwonych_pomara%C5%84czy","page":"Książka kucharska/Sorbet z czerwonych pomarańczy"},{"id":"oc-plwb-4648","title":"Bolognese sauce","cuisine":"Italian","category":"Sauce","ingredients":["500 g ground beef","2 carrots (medium)","2 celery (stalks)","1 onion (medium)","2.5 clove garlic","60 g smoked bacon","250 ml milk","375 ml dry red wine","800 g canned tomatoes (cans, or 1 can of tomatoes and 1 small jar of tomato puree)","3 tbsp olive oil","3 bay leaves","to taste salt","to taste sugar","to taste black peppercorns"],"steps":["Peel the carrots and grate them coarsely, finely dice the celery and smoked bacon, chop the onion and garlic, and blend the canned tomatoes.","Heat the olive oil in a deep frying pan with a lid, fry the smoked bacon until golden, then add the onion and garlic and cook until translucent.","Add the grated carrots and celery, and saute for a few minutes, stirring, until the vegetables soften.","Add the ground beef and fry, stirring constantly and breaking up lumps, until it has changed colour throughout.","Pour in the milk, stir, and simmer until partly reduced, then pour in the red wine and reduce as well.","Add the pureed tomatoes, bay leaves, and several peppercorns, and mix thoroughly.","Reduce the heat to low, cover the pan, and simmer the sauce for at least 120 minutes, stirring occasionally, and towards the end season to taste with a pinch of sugar and salt."],"time":160,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_bolognese","page":"Książka kucharska/Sos bolognese"},{"id":"oc-plwb-15157","title":"Bruschetta z łososiem (grilled salmon and vegetable bruschetta)","cuisine":"Italian","category":"Snack","ingredients":["600 g salmon (fillet)","4 panini rolls (Italian)","100 g sun-dried tomatoes in olive oil","4 onion","1 aubergine","1 courgette","2 bell pepper","125 ml olive oil","4 tbsp dark balsamic glaze","0.5 lemon (juice)","to taste dried oregano","to taste basil leaves (a few leaves)","to taste salt","to taste black pepper"],"steps":["Slice the salmon into thin strips, the aubergine and courgette into thin rounds, the seeded bell peppers into wide strips, and halve the onions.","Drizzle the salmon and vegetables with lemon juice and some of the olive oil, sprinkle with dried oregano, and set aside for 60 minutes.","Drain the fish and vegetables, then grill for 5 minutes, turning and basting with the marinade oil.","Remove from the grill, season with salt and black pepper, add chopped sun-dried tomatoes in olive oil, and drizzle with the dark balsamic glaze and remaining olive oil.","Cut the panini rolls in half, toast them quickly on the grill, pile the vegetables and salmon on top, garnish with basil leaves, and serve warm."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bruschetta_z_%C5%82ososiem","page":"Książka kucharska/Bruschetta z łososiem"},{"id":"oc-plwb-1370","title":"Cannelloni po florencku (Florentine cannelloni)","cuisine":"Italian","category":"Main","ingredients":["250 g cannelloni pasta","250 g minced poultry","2 clove garlic","1 egg","500 g tomatoes","3 celery (stalks)","500 ml béchamel sauce","3 tbsp oil","to taste salt","to taste black pepper","to taste dried oregano","2 tbsp firm cheese (grated)"],"steps":["Blanch the tomatoes, peel and chop them, then cut the celery stalks into strips.","Stew the tomatoes and celery in half the heated oil, seasoning with salt and dried oregano.","Fry the minced poultry in the remaining oil together with the crushed garlic paste.","Crack the egg into the slightly cooled meat, mix well, and season to taste with salt and black pepper.","Using a piping bag or cone, stuff the cannelloni pasta tubes with the prepared meat filling.","Preheat the oven to 200 °C. Spread a layer of braised vegetables over the bottom of a baking dish, arrange the stuffed cannelloni on top, and pour over the béchamel sauce.","Bake for 30 minutes at 200 °C, sprinkling the grated firm cheese over the top 10 minutes before the end."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cannelloni_po_florencku","page":"Książka kucharska/Cannelloni po florencku"},{"id":"oc-plwb-1377","title":"Cannelloni ze szpinakiem (spinach cannelloni)","cuisine":"Italian","category":"Main","ingredients":["200 g cannelloni pasta","500 g frozen spinach","1 onion","2 clove garlic","1 egg yolk","80 g feta cheese","60 g parmesan (grated)","1 tbsp butter","to taste salt","to taste nutmeg","to taste black pepper","to taste basil leaves (optional, for serving)","250 ml béchamel sauce (prepared from powder)"],"steps":["Chop the onion and garlic, then sauté in butter together with the thawed spinach until the water evaporates, and let cool.","Mix the spinach with the egg yolk, crumbled feta cheese, and half of the parmesan, then season to taste with salt, black pepper, and nutmeg.","Stuff the cannelloni tubes with the prepared filling, pour half the béchamel sauce into a baking dish, and arrange the tubes on top.","Sprinkle the pasta with the remaining parmesan and pour over the rest of the béchamel sauce.","Bake for 30 minutes in an oven preheated to 210 °C, and sprinkle with basil leaves before serving."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cannelloni_ze_szpinakiem","page":"Książka kucharska/Cannelloni ze szpinakiem"},{"id":"oc-plwb-56177","title":"Caponetti (Italian spinach and breadcrumb dumplings)","cuisine":"Italian","category":"Main","ingredients":["100 g spinach","400 g plain flour","100 g breadcrumbs","50 g butter","4 eggs","25 ml milk","1 onion","1 tsp dried marjoram","to taste fresh sage (leaves)","to taste salt","to taste olive oil"],"steps":["Peel and finely chop the onion and stew it gently in olive oil; in a separate pan, fry the breadcrumbs in some of the butter.","Combine the plain flour with the toasted breadcrumbs and onion, then add the beaten eggs, chopped spinach, and dried marjoram.","Pour in the milk, season with salt, work into a smooth dough, and shape into elongated, finger-shaped dumplings.","Drop the dumplings into boiling water, cook until they float to the surface, drain, and serve with the remaining melted butter and finely chopped fresh sage."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Caponetti","page":"Książka kucharska/Caponetti"},{"id":"oc-plwb-14469","title":"Caprese cherry tomato skewers (Szaszłyki z pomidorków koktajlowych)","cuisine":"Italian","category":"Snack","ingredients":["500 g cherry tomatoes","500 g mini mozzarella balls","to taste fresh basil (leaves)","5 tbsp olive oil","to taste salt","to taste pepper"],"steps":["Wash and dry the cherry tomatoes, and drain the mini mozzarella balls from their brine.","Thread onto skewers alternately whole cherry tomatoes, mozzarella, and fresh basil leaves.","Drizzle the assembled skewers with olive oil and season with salt and pepper."],"time":15,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szasz%C5%82yki_z_pomidork%C3%B3w_koktajlowych","page":"Książka kucharska/Szaszłyki z pomidorków koktajlowych"},{"id":"oc-plwb-56182","title":"Carpaccio (beef carpaccio)","cuisine":"Italian","category":"Snack","ingredients":["300 g beef tenderloin (corrected from 50 g — beef and Parmesan amounts were swapped in source)","50 g parmesan (corrected from 300 g)","125 ml olive oil","1 lemon","1 tbsp brined capers","to taste salt","to taste black pepper"],"steps":["Place the beef tenderloin into the freezer to firm up slightly, then slice with a sharp knife into paper-thin slices.","Cover the meat with olive oil and rest in a cool place for about 120 minutes.","Grate the parmesan on a coarse box grater or shave into thin ribbons.","Lift the beef slices out of the olive oil and arrange them on a plate, season with salt and pepper, sprinkle with Parmesan and brined capers, and drizzle with lemon juice."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Carpaccio","page":"Książka kucharska/Carpaccio"},{"id":"oc-plwb-14281","title":"Chicken fillets in white wine and sage","cuisine":"Italian","category":"Main","ingredients":["2 chicken breast fillet","125 ml dry white wine","1 tbsp olive oil","2 fresh sage leaves","to taste plain flour (for dusting)","to taste salt"],"steps":["Wash and pat dry the chicken fillets, slice them into halves, and gently pound them with a mallet.","Dust the meat with the flour mixed with salt.","Heat the olive oil in a skillet and fry the fillets on one side until golden.","Turn the meat over, place a sage leaf on each piece, and brown on the other side.","Toward the end of cooking, pour in the white wine and simmer briefly until the sauce reduces slightly."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Filety_z_kurczaka_w_bia%C5%82ym_winie","page":"Książka kucharska/Filety z kurczaka w białym winie"},{"id":"oc-plwb-56199","title":"Ciasteczka novaroni (Novaroni sponge fingers)","cuisine":"Italian","category":"Cookie","ingredients":["150 g plain flour","30 g potato starch","150 g sugar","3 eggs","1 vanilla sugar (packet)","to taste granulated sugar (for sprinkling)","1 pinch salt"],"steps":["Sift together the plain flour and potato starch with a pinch of salt.","Whisk the eggs over steam with the sugar and vanilla sugar until fluffy, then gradually add the sifted flour mixture while continuing to beat.","Using a piping bag, pipe fingers of batter about 10 cm long onto a baking sheet lined with baking paper, and sprinkle with granulated sugar.","Bake in an oven preheated to 160–180 °C until pale golden, let cool slightly, remove from the paper, and leave to cool completely on a plate."],"time":40,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasteczka_novaroni","page":"Książka kucharska/Ciasteczka novaroni"},{"id":"oc-plwb-56194","title":"Ciasteczka sanvigilini (San Vigilini cookies)","cuisine":"Italian","category":"Cookie","ingredients":["400 g plain flour","200 g chilled butter","2 eggs","150 g sugar","50 g raisins","2.5 tbsp brandy (2–3 tbsp brandy)","1 tsp baking powder (level)","1 lemon zest (grated from 1 lemon)","to taste icing sugar (for dusting)","1 pinch salt"],"steps":["Pour the brandy over the raisins and set aside for about 60 minutes.","Sift the plain flour onto a pastry board, add the chopped chilled butter, sugar, eggs, baking powder, lemon zest, and salt, and knead into a smooth dough.","Add the drained raisins, knead briefly to distribute, wrap in clingfilm, and chill for about 60 minutes.","Preheat the oven to 180 °C, roll the dough into walnut-sized balls, place onto a baking sheet lined with baking paper, and bake on the middle rack for about 15 minutes.","Cool the baked cookies, transfer to a platter, and dust with icing sugar."],"time":35,"servings":7,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasteczka_sanvigilini","page":"Książka kucharska/Ciasteczka sanvigilini"},{"id":"oc-plwb-20915","title":"Crispy Parmesan crouton toasts","cuisine":"Italian","category":"Side","ingredients":["1 baguette or bread roll","2.5 tbsp butter (2–3 tablespoons)","50 g grated Parmesan cheese"],"steps":["Trim the crusts off the baguette or roll and cut into small slices.","Melt the butter in a small saucepan or skillet.","Dip each slice on both sides in the melted butter, place onto a baking sheet, and sprinkle with grated Parmesan.","Bake in an oven preheated to 180 °C for about 30 minutes until golden."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Grzanki_z_parmezanem","page":"Książka kucharska/Grzanki z parmezanem"},{"id":"oc-plwb-31677","title":"Five-cheese lasagne","cuisine":"Italian","category":"Main","ingredients":["1 green pasta dough (portion)","2 egg (beaten)","225 g farmer's cheese","225 g cheddar cheese (grated)","225 g havarti cheese (grated)","225 g ricotta cheese","170 g parmesan cheese (grated)","2 tbsp butter","2 tbsp wheat flour","250 ml milk","250 ml poultry broth","750 ml tomato sauce (thick)"],"steps":["Roll out the pasta dough into thin sheets and cut them into rectangular strips measuring about 11 × 27.5 cm.","Combine the beaten eggs with the farmer's cheese, cheddar, havarti, ricotta, and most of the parmesan, setting aside about 50 g of parmesan for the topping, then chill the cheese mixture.","Melt the butter in a saucepan, add the wheat flour and cook for 2 minutes, then pour in 250 ml of milk and 250 ml of poultry broth and simmer over low heat until the sauce thickens.","Preheat the oven to 200 °C. Spread a thin layer of the 750 ml of tomato sauce over the bottom of a large greased baking dish, arrange a layer of pasta, drizzle with white sauce and tomato sauce, and cover with the cheese layer.","Continue layering until all ingredients are used up, finishing with tomato sauce, and sprinkle the top with the reserved parmesan.","Cover the dish with aluminium foil and bake for 25 minutes at 200 °C, then remove the foil and bake for another 8 minutes."],"time":75,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lasagna_z_pi%C4%99cioma_serami","page":"Książka kucharska/Lasagna z pięcioma serami"},{"id":"oc-plwb-17855","title":"Florentine meatballs","cuisine":"Italian","category":"Main","ingredients":["500 g boneless pork","100 g smoked bacon","2 onion","2 egg","2 tbsp plain flour","3 tbsp cooking oil","1 tbsp margarine","1 tsp fresh sage (chopped)","0.25 tsp ground rosemary","250 ml dry white wine","2 carrot","1 parsley root","100 g celeriac","0.25 tsp fresh basil (chopped)","2 tbsp lemon juice","1 pinch sugar","2 tbsp parsley leaves (chopped)","to taste pepper","to taste salt"],"steps":["Grind the pork, smoked bacon, and onions in a meat grinder, add chopped sage, ground rosemary, eggs, salt, and pepper, mix thoroughly, and set aside for 30 minutes.","Peel the carrots, parsley root, and celeriac, then grate on a coarse grater.","Melt the margarine in a saucepan, add the grated vegetables, and brown over high heat, then reduce the heat, add salt, basil, and dry white wine, and simmer covered for a few minutes.","With damp hands, shape the meat mixture into small meatballs, dredge in plain flour, and fry in hot oil until golden.","Transfer the browned meatballs to the saucepan with vegetables and simmer together covered for about 30 minutes.","Toward the end of braising, season with a pinch of sugar and lemon juice, stir gently, and sprinkle with chopped parsley leaves."],"time":95,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pulpety_florenckie","page":"Książka kucharska/Pulpety florenckie"},{"id":"oc-plwb-31679","title":"Four-cheese pizza (Pizza quattro formaggi)","cuisine":"Italian","category":"Main","ingredients":["1 pizza dough (1/2 portion basic dough (about 350 g))","500 ml tomato pizza sauce","170 g mozzarella (grated)","170 g medium-sharp cheese (grated)","115 g Parmesan (grated)","115 g provolone cheese (grated)"],"steps":["Preheat the oven to 230 °C.","Line a pizza pan with the pizza dough and spread the tomato sauce over it, leaving a 1.5 cm crust border.","Scatter an even layer of grated mozzarella, medium-sharp cheese, Parmesan, and provolone over the pizza and bake for 15 minutes until golden brown."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pizza_z_czterema_serami","page":"Książka kucharska/Pizza z czterema serami"},{"id":"oc-plwb-7771","title":"Genoese-style meat sauce","cuisine":"Italian","category":"Sauce","ingredients":["200 g minced meat","1 onion (large)","to taste olive oil (for frying)","2 tbsp tomato paste","2 tbsp water (to dilute the tomato paste)","1 tbsp ketchup","1 clove garlic (large)","50 ml dry white wine","1 tbsp plain flour","250 ml broth (may be from a bouillon cube)","to taste salt","to taste black pepper","to taste dried thyme"],"steps":["Finely chop the onion and garlic, and cook in heated olive oil until translucent, taking care not to brown them.","Add the minced meat and fry for a moment, stirring frequently, then dust with the flour and cook briefly until the raw flour taste is gone.","Pour in the broth and mix thoroughly until smooth.","Add the tomato paste diluted in 2 tablespoons of water, ketchup, thyme rubbed between your palms, salt, and pepper.","Finally, pour in the dry white wine and bring the sauce back to a boil."],"time":25,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_genue%C5%84ski","page":"Książka kucharska/Sos genueński"},{"id":"oc-plws-45219","title":"Italian Macaroni with Parmesan","cuisine":"Italian","category":"Main","ingredients":["400 g Italian macaroni (orig. 1 funt (for 8 people))","to taste water (to boil the pasta)","to taste salt (to salt the water)","100 g Parmesan cheese (coarsely grated)","60 g butter (fresh, for browning the breadcrumbs and pouring over the pasta)","3 tbsp breadcrumbs (for browning in butter)"],"steps":["Drop the Italian macaroni into salted boiling water and cook until tender and floating to the surface.","Drain the macaroni and transfer it to a warmed serving platter.","Sprinkle the macaroni generously with coarsely grated Parmesan and pour fresh butter with browned breadcrumbs over the top (alternatively, toss the macaroni with several tablespoons of sour cream and cheese, transfer to a buttered baking platter, top with cheese and breadcrumbs, and bake for 15 minutes in the oven)."],"time":20,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Makaron_w%C5%82oski_z_parmezonem","page":"365 obiadów za 5 złotych/Makaron włoski z parmezonem"},{"id":"oc-plwb-62661","title":"Italian New Year's lentils (Lenticchie di Capodanno)","cuisine":"Italian","category":"Main","ingredients":["300 g lentils (dry)","2 carrots","2 onions","2 celery (stalks)","400 g tomato puree (passata)","3 tbsp olive oil","5 fresh sage (leaves)","to taste water (for soaking and boiling the lentils)","to taste salt"],"steps":["Cover the lentils with water and soak overnight (about 12 hours).","The next day, chop one carrot, one onion, and one celery stalk into pieces, add to the lentils with a pinch of salt, and cook in water for 60 minutes until tender.","Chop the remaining carrot, onion, and celery stalk, add to a skillet with heated olive oil, stir in the chopped sage leaves and tomato puree, and simmer for 15 minutes.","Transfer the cooked lentils and boiled vegetables to the skillet, stir into the tomato sauce, and simmer everything for another 10 minutes."],"time":600,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Soczewica_noworoczna","page":"Książka kucharska/Soczewica noworoczna"},{"id":"oc-plwb-4585","title":"Italian pizza dough","cuisine":"Italian","category":"Bread","ingredients":["2 tsp dried active yeast (or 20–25 g fresh yeast)","0.5 tsp sugar","1 tsp salt","250 ml cold boiled water","450 g plain wheat flour (400–500 g)"],"steps":["Add the dried yeast, sugar, and salt to a large bowl, pour in the cold boiled water, and stir until the yeast is completely dissolved.","Add the wheat flour, stir, and knead by hand on a work surface for about 5–10 minutes until a smooth, elastic dough forms.","Return the dough to the bowl, slash a cross on top, cover with a clean kitchen towel, and set aside in a warm place for about 30 minutes until doubled in volume.","Briefly punch down the risen dough, divide it into 2–4 portions, and stretch by hand or roll out thinly into rounds.","Place the shaped dough on a preheated baking sheet and bake in an oven heated to maximum temperature for 4–15 minutes (or at 180 °C for about 30 minutes)."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciasto_w%C5%82oskie_na_pizz%C4%99","page":"Książka kucharska/Ciasto włoskie na pizzę"},{"id":"oc-plwb-7843","title":"Italian spaghetti sauce (Sos włoski do spaghetti)","cuisine":"Italian","category":"Sauce","ingredients":["3 tomatoes (large and ripe)","100 g raw pork belly (slice)","1 onion (large)","2 clove garlic","1 tsp basil (measured in a level spoonful)","1 tbsp chives (chopped, measured in a generous spoonful)","1 pinch dried thyme","125 ml dry white wine","125 ml olive oil","to taste salt","to taste pepper"],"steps":["Heat the olive oil in a heavy-bottomed saucepan, add the peeled garlic cloves, brown them lightly, and remove.","Add the chopped onion and diced pork belly to the oil and fry, stirring, until the onion turns golden.","Pour in the white wine, bring to a boil, then add the peeled and seeded tomatoes, about 150 ml of hot water, basil, chives, thyme, salt, and pepper.","Cover the saucepan and simmer over low heat for 20 minutes; serve the finished sauce whole or passed through a sieve."],"time":35,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_w%C5%82oski_do_spaghetti","page":"Książka kucharska/Sos włoski do spaghetti"},{"id":"oc-plwb-19268","title":"Italian-style chicken","cuisine":"Italian","category":"Main","ingredients":["4 chicken breast fillet","4 tomatoes","1 canned sweetcorn (can)","2 onion","100 g white mushrooms","1 green bell pepper","8 tbsp olive oil","to taste salt","to taste pepper","to taste lemon juice","to taste tarragon","1 clove garlic (crushed)"],"steps":["Rinse and dry the chicken fillets, rub with salt, pepper, crushed garlic, and tarragon, then cut into bite-sized dice.","Peel the onions and slice into half-moons. Seed and slice the bell pepper into strips, chop the tomatoes, and quarter any larger mushrooms while leaving smaller ones whole.","Heat the olive oil in a pan, sear the chicken, then add the onion, bell pepper, and mushrooms, continuing to fry.","Towards the end of cooking, stir in the drained sweetcorn and diced tomatoes, cook for another 3 minutes, and adjust seasoning with salt, pepper, and lemon juice."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_po_w%C5%82osku","page":"Książka kucharska/Kurczak po włosku"},{"id":"oc-plwb-14695","title":"Italian-style roast veal (Pieczeń cielęca po włosku)","cuisine":"Italian","category":"Main","ingredients":["1 kg raw veal leg","1 onion","1 bunch soup greens (włoszczyzna)","125 ml beef broth","125 ml dry white wine","4 tbsp vegetable oil","to taste dried rosemary","to taste dried sage","to taste sweet ground paprika","250 ml pickled fruit","to taste salt"],"steps":["Wash and pat dry the veal leg, then rub it with rosemary, sage, sweet paprika, and salt.","Peel the onion and cut into quarters, and slice the cleaned soup greens.","Heat the oil and sear the meat on all sides, then add the onion and soup greens and fry together briefly.","Pour hot beef broth and white wine into a roasting pan, add the browned meat and vegetables, and roast for 60–70 minutes in an oven preheated to 220 °C, basting frequently with the pan juices.","Let the tender meat cool, cut into thin slices, arrange on a serving platter, and garnish with pickled fruit."],"time":90,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Piecze%C5%84_ciel%C4%99ca_po_w%C5%82osku","page":"Książka kucharska/Pieczeń cielęca po włosku"},{"id":"oc-plwb-17867","title":"Kaczka po włosku (Italian-style braised duck with oranges and sage)","cuisine":"Italian","category":"Main","ingredients":["1.5 kg young duck","3 oranges","3.5 fresh sage (3–4 sprigs)","1 onion","2 tbsp olive oil","125 ml dry white wine (half a glass)","60 ml broth (quarter glass of rich broth)","1 tbsp sugar","to taste black pepper","to taste salt"],"steps":["Wash the dressed young duck, portion into serving pieces, and rub with black pepper.","Scrub the oranges, blanch in boiling water, peel thin strips of zest with a sharp knife, then peel the fruit, remove seeds, and dice the flesh.","Peel the onion and chop it finely.","Heat olive oil in a wide shallow pan, brown the duck pieces until golden, add onion, sage, and orange zest, then season with salt and pepper.","Pour in the dry white wine and cook uncovered over high heat for a few minutes, then pour in the broth, cover, and simmer over low heat for about 60 minutes.","Transfer the tender duck to an ovenproof platter, blend or sieve the sauce, add sugar and diced orange flesh, and heat until the sugar dissolves.","Pour the orange sauce over the duck and bake for a few minutes in a preheated oven."],"time":100,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kaczka_po_w%C5%82osku","page":"Książka kucharska/Kaczka po włosku"},{"id":"oc-plwb-1390","title":"Lasagne bolognese","cuisine":"Italian","category":"Main","ingredients":["200 g lasagne pasta sheets","250 g minced beef and pork","3 clove garlic (2–4 cloves)","200 g tomato paste (or canned tomatoes)","200 g button mushrooms","4 tbsp vegetable oil or olive oil","2 tomato (several pieces for garnish)","to taste salt","to taste dried oregano","to taste dried thyme","to taste basil (fresh or dried)","250 g firm cheese (150–400 g, grated)","500 ml béchamel sauce"],"steps":["Preheat the oven to 180 °C. Peel the garlic, mince it finely or press it through a garlic press, and fry in 2 tablespoons of oil or olive oil.","Add the minced meat and fry for 10–15 minutes until the fat renders, breaking up any lumps.","Add the tomato paste or canned tomatoes and simmer for about 5 minutes, then season with salt, oregano, thyme, and basil.","Clean the button mushrooms, slice them, and leave them raw or fry them in the remaining fat.","Layer the meat sauce, mushrooms, lasagne pasta sheets, 500 ml of béchamel sauce, and part of the grated firm cheese in an ovenproof dish.","Sprinkle the top with the remaining firm cheese and herbs, arrange the tomato halves, and bake for 30 minutes at 180 °C."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lasagne_bolognese","page":"Książka kucharska/Lasagne bolognese"},{"id":"oc-plwb-4643","title":"Lasagne napoli","cuisine":"Italian","category":"Main","ingredients":["200 g lasagne pasta sheets","to taste dried thyme","to taste dried oregano","to taste basil (fresh or dried)","750 ml Napoli sauce (500–1000 ml)","250 g firm cheese (150–400 g, grated)","500 ml béchamel sauce"],"steps":["Preheat the oven to 180 °C.","In an ovenproof dish, alternately layer the lasagne sheets, 750 ml of Napoli sauce, 500 ml of béchamel sauce, and grated firm cheese.","Sprinkle the top generously with the remaining grated cheese and season with oregano, thyme, and basil.","Bake in the preheated oven for 30 minutes at 180 °C."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lasagne_napoli","page":"Książka kucharska/Lasagne napoli"},{"id":"oc-plwb-4644","title":"Lasagne pasta sheets","cuisine":"Italian","category":"Other","ingredients":["500 g wheat flour","to taste water (lukewarm, for kneading the dough)","2 egg","1 tbsp olive oil (or vegetable oil)"],"steps":["Pour the flour into a bowl, make a well in the center, and crack the eggs into it.","Knead the flour with the eggs, gradually adding lukewarm water until you obtain a smooth dough suitable for rolling out.","Divide the dough into portions, roll out into thin sheets 1–2 mm thick, and cut into rectangular strips about 10 cm wide and 20–30 cm long.","Drop the pasta sheets one by one into boiling water with 1 tablespoon of olive oil added and cook."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_lasagne","page":"Książka kucharska/Makaron lasagne"},{"id":"oc-plws-580445","title":"Nadzienie włoskie do omletu (Italian pasta, tomato, and Parmesan omelette filling)","cuisine":"Italian","category":"Other","ingredients":["100 g pasta (Italian, finely broken)","to taste salt (for boiling the pasta)","to taste butter (a small piece)","1 tbsp tomato paste (or 2 fresh tomatoes sliced into rounds)","1 Parmesan cheese (handful of grated cheese)"],"steps":["Break the pasta into small pieces, drop into boiling salted water, and cook for about 8 minutes until al dente, taking care not to overcook it.","Drain the cooked pasta, return it to the pot, and toss while hot with the butter, tomato paste, and grated Parmesan cheese for 2 minutes.","Spoon the hot filling directly onto a cooked omelette."],"time":15,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_postnych_i_jarskich_da%C5%84/Nadzienie_w%C5%82oskie","page":"100 postnych i jarskich dań/Nadzienie włoskie"},{"id":"oc-plwb-2730","title":"Napoletana sauce","cuisine":"Italian","category":"Sauce","ingredients":["1 kg tomatoes (canned or very ripe fresh tomatoes)","4 clove garlic","to taste fresh basil (leaves, or dried)","2 pinch dried thyme","3 pinch dried oregano","to taste olive oil (or vegetable oil, for frying)"],"steps":["Dice the tomatoes, place them in a bowl, and puree with a food processor or blender at very low speed so the juice does not foam or turn pale.","Pour the olive oil into a skillet, warm it gently, and add the pureed tomatoes.","Fry the sauce in the skillet until it turns a darker shade.","Add torn fresh basil leaves, 2 pinches of dried thyme, and 2–4 pinches of oregano, then simmer everything for 5–10 minutes.","Add the finely chopped garlic cloves and simmer, stirring, for another 2–3 minutes."],"time":23,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_napoli","page":"Książka kucharska/Sos napoli"},{"id":"oc-plwb-16005","title":"Neapolitan pizza (Pizza Napoletana)","cuisine":"Italian","category":"Main","ingredients":["450 g peeled tomatoes (fresh or canned)","1 pizza dough (1 portion (about 400 g))","40 g anchovy fillets in oil (drained and cut into strips)","350 g mozzarella (diced or sliced)","1 tsp dried oregano","3 tbsp olive oil","to taste salt","to taste black pepper"],"steps":["Preheat the oven to 250 °C at least 20 minutes before baking.","Pass the peeled tomatoes through a sieve into a bowl.","Roll out the pizza dough into a round base, spread with the sieved tomatoes leaving a border around the edge, and arrange the mozzarella and anchovy strips on top.","Sprinkle the pizza with dried oregano, season with salt and pepper, drizzle with olive oil, and bake for 15–20 minutes until the edges are browned and the cheese has melted."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pizza_neapolita%C5%84ska","page":"Książka kucharska/Pizza neapolitańska"},{"id":"oc-plws-44925","title":"Neapolitan-Style Italian Macaroni","cuisine":"Italian","category":"Main","ingredients":["400 g Italian macaroni (orig. 1 funt of thick Italian macaroni)","250 ml water (orig. 1 Polish kwaterka of boiling water or broth for the sauce (plus water or light broth to boil the pasta))","to taste salt (for boiling the pasta)","50 g bouillon tablet (orig. 4 Polish łuty of good French bouillon (nowadays thick bouillon concentrate))","1 tbsp butter (fresh)","1 tbsp wheat flour (scant)","80 g Parmesan cheese (grated, to serve)"],"steps":["Break the long, thick Italian macaroni in half and boil it until tender in a wide pot of salted boiling water or light broth, then drain in a colander.","Dissolve 50 g of concentrated bouillon in 250 ml (1 Polish kwaterka) of boiling water or broth.","Bring 1 tbsp of fresh butter and 1 scant tbsp of wheat flour to a boil in a small saucepan, then gradually add the hot bouillon to make a fairly thin sauce.","Transfer the hot macaroni to a serving platter, pour the prepared sauce generously over the top, and serve with grated Parmesan."],"time":25,"servings":8,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Makaron_w%C5%82oski_po_neapolita%C5%84sku","page":"365 obiadów za 5 złotych/Makaron włoski po neapolitańsku"},{"id":"oc-plwb-13056","title":"Panna cotta (caramel cream with red wine reduction)","cuisine":"Italian","category":"Dessert","ingredients":["500 ml heavy whipping cream 36%","150 g sugar","0.5 tsp gelatine (dissolved)","750 ml sweet red wine","125 ml sugar","3 tbsp raspberry vinegar","1 tsp grated lemon or orange zest (heaped)"],"steps":["Bring the cream to a boil in a saucepan and remove it from the heat.","In a separate saucepan, melt 150 g of sugar, heating and stirring until a golden caramel forms.","Remove the caramel from the heat, slowly pour in the hot cream while stirring continuously, then bring the mixture back to a boil.","Take the saucepan off the heat, stir in the dissolved gelatine, and mix until completely incorporated.","Pour the cream into ramekins and refrigerate until fully set.","Combine the wine, remaining sugar, and raspberry vinegar in a saucepan and simmer until the liquid reduces to about 190 ml.","Let the reduced sauce cool, stir in the citrus zest, and drizzle over the chilled dessert before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Panna_cotta","page":"Książka kucharska/Panna cotta"},{"id":"oc-plwb-56116","title":"Papryka po florencku (Florentine stuffed green bell peppers)","cuisine":"Italian","category":"Main","ingredients":["300 g frozen spinach","250 g ground beef","1 onion (small, chopped)","1 clove garlic (chopped)","0.25 tsp dried basil","0.25 tsp dried oregano","2 tbsp raisins","125 ml cooked rice","2 tbsp tomato paste","1 egg white (lightly beaten)","4 green bell peppers","2 tsp pickled bell pepper (finely shredded)","2 tsp fresh parsley leaves (chopped)","1 tbsp olive oil (for the dish and frying)"],"steps":["Preheat the oven to 190 °C, grease a baking dish with olive oil, and squeeze all excess liquid from the thawed spinach.","Slice off the stem tops from the bell peppers and scoop out the seeds and membranes.","Heat a little olive oil in a skillet, brown the minced beef over medium heat, and drain off any rendered fat.","In a bowl, combine the drained spinach, browned beef, cooked rice, beaten egg white, tomato paste, chopped onion, garlic, raisins, basil, and oregano, and mix thoroughly.","Stuff the hollowed peppers with the prepared filling, scatter with chopped parsley and pickled pepper, and arrange upright in the baking dish.","Bake for about 30 minutes at 190 °C, until the tops are nicely browned."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Papryka_po_florencku","page":"Książka kucharska/Papryka po florencku"},{"id":"oc-plwb-15575","title":"Pears poached in Barolo (Pere al Barolo)","cuisine":"Italian","category":"Dessert","ingredients":["4 pears (ripe)","4 cloves","2 bay leaves (small)","1 cinnamon stick (a piece)","1 slice lemon peel (strip)","100 g sugar (half a glass)","750 ml Barolo wine","to taste mint or lemon balm leaves (leaves for serving)"],"steps":["Peel the pears leaving their stems intact, and arrange them upright in a deep pot.","Add the cloves, bay leaves, cinnamon stick, and lemon peel, sprinkle the pears with sugar, and pour in the Barolo wine.","Bring to a boil over high heat, then reduce the heat to low and simmer for 50 minutes.","Check the tenderness of the pears with a fork and carefully remove them from the pot by their stems.","Simmer the remaining wine in the pot until it reduces to a syrup, drizzle over the cooled pears, and garnish with mint or lemon balm leaves."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gruszki_w_barolo","page":"Książka kucharska/Gruszki w barolo"},{"id":"oc-plwb-14946","title":"Pears poached in cider","cuisine":"Italian","category":"Dessert","ingredients":["8 pears","300 ml alcoholic apple cider","2 tbsp sugar","0.5 tsp almond flavoring"],"steps":["Peel the pears, halve them, core them, and arrange the fruit in a shallow dish.","Pour the cider over the pears and sprinkle with sugar.","Cook covered or in the microwave for about 10 minutes until the fruit is tender, then transfer onto a serving dish.","Simmer the remaining liquid for about 2 minutes until slightly thickened, stir in the almond flavoring, and pour over the pears."],"time":22,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gruszki_w_cydrze","page":"Książka kucharska/Gruszki w cydrze"},{"id":"oc-plwb-4759","title":"Pizza calzone (folded stuffed pizza)","cuisine":"Italian","category":"Main","ingredients":["500 g pizza dough (risen)","60 ml olive oil","350 g button mushrooms (sliced)","1 clove garlic (lightly crushed)","1 tbsp parsley leaves (chopped)","400 g canned tomatoes (chopped, with juice)","125 g mozzarella (drained, diced)","50 g Parmesan (freshly grated)","to taste salt"],"steps":["Preheat the oven to 220 °C and lightly brush a large sheet of baking parchment with olive oil.","Heat the remaining olive oil in a deep skillet, add the sliced mushrooms and crushed garlic clove, and fry for 7–10 minutes until the mushrooms soften and most of the liquid evaporates.","Stir in the chopped parsley leaves, season with salt, mix well, remove the pan from the heat, and discard the garlic.","Divide the risen pizza dough into 2 equal portions, roll them out into rounds 3 mm thick, and transfer onto the baking paper.","Spread the chopped canned tomatoes over half of each round, leaving a 2 cm border around the edges, then top with mozzarella, sautéed mushrooms, and grated Parmesan.","Fold the dough rounds in half over the filling and crimp the edges firmly with your fingers.","Bake in the preheated oven for about 30 minutes until golden brown and serve hot."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pizza_calzone","page":"Książka kucharska/Pizza calzone"},{"id":"oc-plwb-31791","title":"Pizza carbonara","cuisine":"Italian","category":"Main","ingredients":["200 g wheat flour","200 ml water (warm)","15 g fresh yeast","1.5 tbsp olive oil","1 tbsp sugar","1 pinch salt","1 pinch ground paprika (sweet or hot)","to taste Italian herbs","4 slice ham","10 button mushrooms","1 onion","to taste pizza seasoning","100 g hard cheese (ser żółty) (grated)","50 g smoked bacon","2.5 clove garlic","40 g Parmesan (freshly grated)","to taste salt","2 eggs","3 tbsp sour cream 18% (thick)","to taste black pepper","1 tbsp olive oil","1 tsp wheat flour (optional for thickening)"],"steps":["Crumble the yeast into a small bowl, mix with sugar, pour in warm water, dust with a pinch of flour, cover, and let stand in a warm place for 20 minutes.","Mix the wheat flour with paprika, salt, and Italian herbs, pour in the risen starter and olive oil, knead into a smooth dough, and leave covered for 20–30 minutes to rise.","Finely dice the smoked bacon, fry until crisp in a tablespoon of olive oil, drain on kitchen paper, and sauté the minced garlic in the remaining fat.","Whisk the eggs with sour cream, salt, and pepper, stir in the grated Parmesan, bacon, and garlic, and heat briefly over very low heat (thickening with a little flour if needed), being careful not to scramble the eggs.","Divide the risen dough into 2 portions, stretch onto baking sheets into thin rounds, and fold the crust edges.","Top the dough with sliced mushrooms, onion, and ham, sprinkle with pizza seasoning, spoon over the carbonara sauce, and top with grated cheese.","Bake in an oven preheated to 180–200 °C for about 20–25 minutes."],"time":85,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pizza_carbonara","page":"Książka kucharska/Pizza carbonara"},{"id":"oc-plwb-11846","title":"Pizza dough (Pizza - ciasto)","cuisine":"Italian","category":"Bread","ingredients":["25 g fresh yeast (or 2 tsp dried yeast)","1 tbsp sugar","1 pinch salt","250 ml water (warm)","480 g plain flour (type 450–500)"],"steps":["Place the yeast in a bowl, sprinkle with sugar, add a pinch of salt and warm water, and stir until the yeast dissolves.","Add the wheat flour and knead the dough by hand until smooth and coming away cleanly from the sides of the bowl.","Divide the dough into 2 equal parts, shape into balls, cover with a kitchen cloth, and let rise in a warm place for 10–15 minutes.","Knead the risen dough briefly on a work surface and stretch by hand into 2 round pizza bases.","Place the bases on baking sheets and bake with your choice of toppings in an oven preheated to 220–250 °C for about 15–20 minutes."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pizza_-_ciasto","page":"Książka kucharska/Pizza - ciasto"},{"id":"oc-plwb-31729","title":"Polenta (Italian cornmeal porridge)","cuisine":"Italian","category":"Side","ingredients":["1 kg cornmeal","2 l water","15 g salt"],"steps":["Bring a litre of salted water to a boil in a large pot, and bring the remaining litre of plain water to a boil in a second pot.","Slowly pour 600 g of cornmeal in a steady stream into the boiling salted water, stirring constantly with a wooden spoon to prevent lumps.","Cook over low heat for 15 minutes, stirring regularly and adding boiling water from the second pot as needed.","Add the remaining 400 g of cornmeal and simmer for another 15–30 minutes, gradually pouring in the rest of the hot water and stirring until the polenta pulls away cleanly from the sides of the pot.","Pour the cooked polenta onto a moistened board or tray, smooth to the desired thickness, and leave to set."],"time":50,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Polenta","page":"Książka kucharska/Polenta"},{"id":"oc-plwb-15577","title":"Ravioli verdi (green herb ravioli)","cuisine":"Italian","category":"Main","ingredients":["500 g plain flour","1 bunch parsley leaves (small bunch)","1 bunch fresh basil (small bunch)","3 egg","2 egg yolk","1 egg white (for sealing the dough)","275 g ricotta cheese (250–300 g)","250 g mozzarella","60 g Parmesan (grated)","1 onion (chopped)","3 clove garlic (chopped)","1 tbsp olive oil","1 tbsp butter","10 fresh basil (leaves)","to taste pepper","2 tomato (1–2 pcs, chopped)","1 tbsp olive oil","1 clove garlic (chopped)","to taste fresh basil (chopped)","to taste salt","to taste pepper","1 pinch saffron","100 ml white wine","1 tbsp butter","150 ml whipping cream"],"steps":["Cook the chopped onion and 3 cloves of garlic in olive oil with butter until translucent, let cool, then mix with the ricotta, shredded mozzarella, Parmesan, 10 chopped basil leaves, and pepper.","Blend the parsley leaves and basil bunch with the whole eggs and egg yolks, knead with the flour into a smooth dough, and roll out thinly.","Cut the dough into strips, place portions of cheese filling along one half, brush the edges with egg white, fold the other half of the dough over, press down, and cut with a knife into square ravioli.","Cook the ravioli in salted boiling water until they float to the surface and drain.","Prepare the red sauce: sauté the chopped garlic and cut tomatoes in olive oil, add the chopped basil, and season with salt and pepper.","Prepare the yellow sauce: steep the saffron in hot white wine with butter, reduce the 30% whipping cream in a skillet, pour in the saffron wine, cook until thickened, season with salt, and serve both sauces with the ravioli."],"time":70,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ravioli_verdi","page":"Książka kucharska/Ravioli verdi"},{"id":"oc-plwb-31676","title":"Red pizza sauce","cuisine":"Italian","category":"Sauce","ingredients":["3 tbsp olive oil","2 clove garlic (minced)","1 onion (finely diced)","0.5 green bell pepper (finely diced)","1.3 kg tomatoes (peeled, seeded, and chopped)","1 tsp oregano (leaves)","1 tsp thyme (leaves)","1 tsp basil (leaves)","1 tsp salt","0.5 tsp black pepper (coarsely ground)","1 tbsp Worcestershire sauce","160 ml tomato paste"],"steps":["Heat the olive oil in a large pot, add the minced garlic, finely diced onion, and green bell pepper, and cook until softened.","Add the peeled, seeded, and chopped tomatoes, tomato paste, Worcestershire sauce, oregano, thyme, basil, salt, and coarsely ground pepper.","Lower the heat and simmer the sauce for 120 minutes, stirring occasionally, until significantly thickened."],"time":145,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_czerwony_do_pizzy","page":"Książka kucharska/Sos czerwony do pizzy"},{"id":"oc-plws-44944","title":"Saffron risotto Milanese-style (risotto alla milanese)","cuisine":"Italian","category":"Main","ingredients":["200 g white rice (orig. 1/2 Polish funt)","3 g saffron (orig. 1/4 łut)","30 ml water (orig. 1 kieliszek for soaking the saffron + boiling water for scalding the rice)","750 ml beef or veal broth (orig. 500 ml at the start + approx. 250 ml during braising)","1 tbsp butter","50 g grated Parmesan cheese","to taste salt"],"steps":["Steep the saffron in 30 ml of lukewarm water. Scald the rice with boiling water, drain, and rinse with cold water.","In a one-litre saucepan, bring 500 ml of beef or veal broth to a boil, add the rice, butter, and a pinch of salt, then braise covered over low heat for about 10 minutes.","When the rice is partly cooked, add the strained saffron infusion and the remaining 250 ml of hot broth. Cook for another 10–15 minutes until the rice is tender and golden and the mixture has thickened.","Spoon the thickened rice mixture onto a platter and sprinkle generously with grated Parmesan."],"time":45,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Ry%C5%BC_z_szafranem_po_w%C5%82osku","page":"365 obiadów za 5 złotych/Ryż z szafranem po włosku"},{"id":"oc-plwb-56183","title":"Salmon scaloppine on spinach","cuisine":"Italian","category":"Main","ingredients":["800 g salmon fillet","200 g spinach","100 ml olive oil","20 g butter","10 g sea salt","1 small onion","1 clove garlic","to taste balsamic vinegar","to taste black pepper"],"steps":["Rinse and pat dry the salmon, season with part of the sea salt, place in a baking dish, drizzle generously with olive oil, and bake for about 60 minutes in an oven heated to 70 °C.","Season the spinach with pressed garlic, the remaining salt, and pepper, and sauté in the melted butter.","Add the peeled and finely chopped onion to the spinach, simmer briefly together, and stir well.","Divide the slow-roasted salmon into portions, arrange over the spinach, and drizzle with the remaining olive oil and balsamic vinegar before serving."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Eskalopki_%C5%82ososiowe_na_szpinaku","page":"Książka kucharska/Eskalopki łososiowe na szpinaku"},{"id":"oc-plwb-56175","title":"Saltimbocca alla romana (veal escalopes with prosciutto and sage)","cuisine":"Italian","category":"Main","ingredients":["700 g veal cutlets (escalopes)","6 slice prosciutto (dry-cured ham)","6 fresh sage leaves","80 ml heavy cream (whipping cream)","125 ml dry white wine","2 tbsp plain flour","2 tbsp olive oil","1 tbsp butter","2 clove garlic","to taste salt","to taste black pepper"],"steps":["Rinse and pat dry the veal, slice into 6 escalopes, and gently pound to a thickness of about 3 mm.","Top each cutlet with a slice of cured ham and a fresh sage leaf, press firmly, and secure with a toothpick.","Mix the flour with salt and pepper and dredge the escalopes lightly in the seasoned flour.","Heat the olive oil and butter in a large skillet, add the minced garlic, and fry the escalopes over medium heat for 2–3 minutes on each side.","Transfer the escalopes to a pan, deglaze the skillet with half the white wine, and pour the juices over the meat.","Simmer covered for 5 minutes, then add the rest of the wine and the heavy cream, season with salt and pepper, and simmer for another 10–15 minutes until tender."],"time":30,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Eskalopki_ciel%C4%99ce_po_rzymsku","page":"Książka kucharska/Eskalopki cielęce po rzymsku"},{"id":"oc-plwb-18571","title":"Sałatka italiana (Italian pasta and vegetable salad)","cuisine":"Italian","category":"Salad","ingredients":["3 tomatoes (large)","1 fresh cucumber","1 canned sweetcorn (can, drained)","500 ml fusilli pasta","3 tbsp olive oil","2 tbsp instant vegetable broth powder","2 tbsp water (for the dressing)","to taste dill (finely chopped)","to taste parsley (finely chopped)","1 lemon balm leaf (finely chopped)","to taste salt","to taste black pepper"],"steps":["Cook the pasta al dente, drain, and let cool, and drain the canned sweetcorn.","Wash the tomatoes and cucumber, slice them, and gently combine with the pasta and sweetcorn.","Mix the instant broth powder with a little water into a thick paste, transfer to a screw-top jar, add the olive oil and 2 tablespoons of water, along with the finely chopped dill, parsley, lemon balm, salt, and pepper.","Screw the lid tightly onto the jar and shake vigorously until the dressing is thoroughly combined.","Pour the dressing over the salad, toss gently, and chill in a cool place for about 30 minutes."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_italiana","page":"Książka kucharska/Sałatka italiana"},{"id":"oc-plwb-62025","title":"Shrimp risotto","cuisine":"Italian","category":"Main","ingredients":["250 g arborio rice","500 g shrimp (frozen or fresh)","120 g onion (cut into chunks)","20 g butter","3 parsley leaves (sprigs, finely chopped)","5.5 tbsp olive oil (5–6 tbsp)","3 tbsp tomato purée","1.5 tbsp lemon juice","2 tbsp plain flour (for coating the shrimp)","to taste salt","to taste pepper"],"steps":["Thaw and pat the shrimp dry with paper towels, dredge in plain flour, sear briefly in hot olive oil, transfer to a plate, and drizzle with the juice of half a lemon.","Add the chopped onion to the remaining oil in the pan, sauté for a few minutes, stir in the tomato purée, season with salt and pepper, and simmer over low heat for 20 minutes, then return the shrimp to the pan and remove from the heat.","Bring the arborio rice to a boil in a small amount of salted water, adding a few tablespoons of boiling water as needed to replace evaporated liquid.","Halfway through cooking the rice, after about 7 minutes, stir in the prepared tomato sauce with shrimp and cook until the grains are tender.","Remove the cooked risotto from the heat, stir in the butter and finely chopped parsley leaves, and serve hot."],"time":50,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Risotto_z_krewetkami","page":"Książka kucharska/Risotto z krewetkami"},{"id":"oc-plwb-8323","title":"Spaghetti alla bolognese","cuisine":"Italian","category":"Main","ingredients":["400 g spaghetti (or tagliatelle)","275 g minced beef (250–300 g)","125 ml sour cream","400 g canned tomatoes (or fresh)","1 onion","1 carrot","1 celery (stalk)","to taste Parmesan (grated)","to taste salt","to taste pepper","to taste oregano","to taste basil","to taste olive oil (for frying)"],"steps":["Finely chop the onion, carrot, and celery, and fry in heated olive oil.","Add the minced beef and cook, stirring, until it loses its raw pink colour.","Add the tomatoes with their juice, stir, and simmer gently over low heat. Towards the end, stir in the sour cream and season with salt, pepper, oregano, and basil.","Cook the pasta in salted water, drain, spoon the hot sauce over, and sprinkle with grated Parmesan."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Spaghetti_alla_bolognese","page":"Książka kucharska/Spaghetti alla bolognese"},{"id":"oc-plwb-1369","title":"Spaghetti alla carbonara","cuisine":"Italian","category":"Main","ingredients":["400 g spaghetti (or tagliatelle)","200 g smoked bacon","125 ml sour cream","2 tbsp parsley (chopped)","4 tbsp Parmesan (grated)","4 egg yolks","to taste salt","to taste pepper"],"steps":["Cook the pasta in salted water and drain, keeping it warm.","Dice the smoked bacon and fry it in a pan.","Warm the sour cream, combine it with the grated Parmesan, egg yolks and chopped parsley, and season to taste with salt and pepper.","Toss the warm pasta with the fried bacon and pour over the prepared sauce."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Spaghetti_alla_carbonara","page":"Książka kucharska/Spaghetti alla carbonara"},{"id":"oc-plwb-21439","title":"Spaghetti alla puttanesca","cuisine":"Italian","category":"Main","ingredients":["250 g spaghetti","1 canned tomatoes (can)","1 black olives (small jar)","4 anchovy fillets","1 tbsp capers","2 clove garlic","1 pinch hot paprika","to taste olive oil","to taste pepper"],"steps":["Cook the spaghetti al dente and drain.","Peel and crush the garlic, sauté in heated olive oil, then add the black olives, finely chopped anchovy fillets, and capers.","Fry the ingredients briefly, add the canned tomatoes, and season to taste with hot paprika and pepper.","Simmer the sauce until excess water evaporates, then toss with the cooked pasta."],"time":25,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Spaghetti_alla_puttanesca","page":"Książka kucharska/Spaghetti alla puttanesca"},{"id":"oc-plwb-11334","title":"Spaghetti con sugo alla diavola","cuisine":"Italian","category":"Main","ingredients":["400 g spaghetti","1 kg peeled tomatoes","2 celery (stalks)","1 onion (large)","2 carrots","1 fresh chili pepper (sliced into rings, seeded)","3 clove garlic","1 fresh rosemary (sprig)","125 ml olive oil","1 pinch dried chili (generous pinch)","to taste black pepper (coarsely ground)","to taste salt","200 g Parmesan (or pecorino, grated)"],"steps":["Blend the celery, carrots, onion, garlic, and fresh rosemary leaves, then sauté well in heated olive oil.","Add the finely diced peeled tomatoes, salt, coarsely ground black pepper, and dried chili, pour in 250 ml of water, and simmer over low heat for about 30 minutes, stirring occasionally.","A few minutes before finishing the sauce, stir in the fresh chili sliced into rings.","Cook the spaghetti in salted water, drain, toss with the hot sauce and grated cheese, and arrange on plates."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Spaghetti_con_sugo_alla_diavola","page":"Książka kucharska/Spaghetti con sugo alla diavola"},{"id":"oc-plwb-14634","title":"Spaghetti with broccoli in cheese sauce (Spaghetti z brokułami w sosie serowym)","cuisine":"Italian","category":"Main","ingredients":["400 g spaghetti","350 g broccoli (300–400 g, fresh or frozen)","to taste Parmesan (grated)","2 tbsp vegetable oil","to taste salt","to taste pepper","200 g firm cheese (1–3 varieties)","1 processed cheese (packet)","1 tsp butter","50 ml dry white wine (or milk)","50 ml sour cream (thick)"],"steps":["Divide the broccoli into florets and lightly sauté in hot oil. Add a little water, cook gently until tender, then break into smaller pieces with a wooden spoon.","Melt the butter in a saucepan, add the grated firm cheese, processed cheese, and white wine or milk, and heat while stirring continuously until the cheeses melt completely.","Pour the cheese sauce over the broccoli, fold in the thick sour cream, and season to taste with salt and pepper.","Cook the spaghetti in salted water until al dente, drain, arrange onto plates, spoon the sauce over, and top with grated Parmesan."],"time":30,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Spaghetti_z_broku%C5%82ami_w_sosie_serowym","page":"Książka kucharska/Spaghetti z brokułami w sosie serowym"},{"id":"oc-plwb-14279","title":"Spaghetti with ham and broccoli (Spaghetti z szynką)","cuisine":"Italian","category":"Main","ingredients":["250 g spaghetti","250 g broccoli","130 g ham","1 tsp butter","2 clove garlic","2 tbsp vegetable oil","250 ml dry white wine","to taste Parmesan (grated)","to taste salt","to taste pepper"],"steps":["Cook the spaghetti in salted water, drain, and set aside in a warm place.","Briefly parboil the broccoli, rinse with cold water, and drain.","Peel and crush the garlic, fry in the butter mixed with oil, then pour in the white wine and simmer until two-thirds of the liquid has evaporated.","Cut the ham into strips, add to the sauce along with the broccoli, and season with salt and pepper.","Portion the spaghetti onto plates, pour over the sauce, and sprinkle with grated Parmesan just before serving."],"time":25,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Spaghetti_z_szynk%C4%85","page":"Książka kucharska/Spaghetti z szynką"},{"id":"oc-plwb-17680","title":"Spaghetti with tomato sauce and olives (Spaghetti z sosem pomidorowym i oliwkami)","cuisine":"Italian","category":"Main","ingredients":["1 spaghetti (packet)","2 canned tomatoes (cans)","to taste salt","to taste black pepper (freshly ground)","0.5 tsp dried oregano (or 1 tsp fresh)","1 tbsp fresh basil","to taste olives","2 tbsp olive oil","1 red onion","2 clove garlic","to taste firm cheese","to taste Rokpol blue cheese"],"steps":["Cook the spaghetti in salted water and drain.","Peel and chop the red onion and garlic, cook in hot olive oil until translucent, then add the canned tomatoes.","Simmer the sauce until slightly reduced, season with salt, pepper, oregano, and basil, add the cooked pasta, and heat over low heat for 5 minutes.","Portion the spaghetti onto plates, arrange olives over top, and scatter with grated firm cheese and crumbled Rokpol blue cheese."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Spaghetti_z_sosem_pomidorowym_i_oliwkami","page":"Książka kucharska/Spaghetti z sosem pomidorowym i oliwkami"},{"id":"oc-plwb-14458","title":"Spaghetti with tuna (Spaghetti z tuńczykiem)","cuisine":"Italian","category":"Main","ingredients":["450 g spaghetti (400–500 g)","2 canned diced tomatoes (cans)","2 canned tuna in its own juices (cans)","2 tbsp vegetable oil","1 onion","1 clove garlic","to taste firm cheese (grated, optional)","to taste salt","to taste pepper"],"steps":["Cook the spaghetti in salted water and drain.","Heat the oil in a pan, fry the diced onion until golden, then add the pressed or finely minced garlic.","Add the tuna, followed shortly by the diced tomatoes, and simmer over low heat for about 10–15 minutes.","Season the sauce with salt and pepper, spoon over the cooked pasta, and optionally sprinkle with grated cheese."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Spaghetti_z_tu%C5%84czykiem","page":"Książka kucharska/Spaghetti z tuńczykiem"},{"id":"oc-plwb-31710","title":"Spinach lasagne","cuisine":"Italian","category":"Main","ingredients":["15 lasagne pasta sheets","300 g fresh spinach","2 tbsp vegetable oil","1 onion","5 clove garlic","1 green bell pepper","60 g Grana Padano cheese","100 g mozzarella cheese","2 egg","400 g ricotta cheese","2 canned chopped tomatoes (cans of peeled tomatoes)","to taste salt","to taste black pepper"],"steps":["Heat the oil in a frying pan, add the finely chopped seeded green pepper and chopped onion, and fry until golden. Towards the end, add the thinly sliced garlic, fry briefly, and let cool.","Beat the eggs in a bowl, add the ricotta, finely chopped spinach, half of the grated Grana Padano, and half of the grated mozzarella, season with salt and pepper, then combine with the cooled vegetables.","Finely chop the canned tomatoes and mix with their juices, season with salt and pepper, then spread half of the sauce over the bottom of an ovenproof dish.","Drop the lasagne sheets 3 at a time into boiling salted water and parboil briefly until slightly softened.","Layer alternately in the dish with 3 pasta sheets and one-quarter of the spinach-cheese filling; pour the remaining tomato sauce over the final pasta layer and sprinkle with the remaining Grana Padano and mozzarella.","Cover the dish with aluminium foil and bake for 30 minutes in an oven preheated to 180 °C, then remove the foil and bake for another 15–20 minutes until the cheese is browned."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lasagne_ze_szpinakiem","page":"Książka kucharska/Lasagne ze szpinakiem"},{"id":"oc-plwb-5484","title":"Tiramisu","cuisine":"Italian","category":"Dessert","ingredients":["250 g mascarpone","2 eggs (additional egg yolks can be added)","200 ml strong coffee (preferably espresso, cooled)","130 g ladyfingers","1 tbsp unsweetened cocoa powder (for dusting the layers)","4 tbsp amaretto liqueur","50 g icing sugar","1 tbsp Marsala wine (Sicilian)"],"steps":["Brew 200 ml of strong coffee (preferably espresso), add 2 to 6 tablespoons of amaretto liqueur, and set aside to cool.","Separate the egg yolks from the whites, and beat the yolks with the icing sugar using a mixer until pale and fluffy.","Gradually add the mascarpone and a tablespoon of Marsala wine to the yolks, mixing until a smooth, lump-free cream forms.","Beat the egg whites until stiff peaks form, then very gently fold them into the mascarpone and yolk mixture with a spatula.","Briefly dip each ladyfinger into the cooled coffee with amaretto and arrange an even layer across the bottom of the dish.","Spread half of the cream over the ladyfingers and dust the top with sifted cocoa powder, then arrange a second layer of soaked ladyfingers and the remaining cream.","Refrigerate the dessert for 24 hours, and just before serving, generously dust the top with unsweetened cocoa powder."],"time":600,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tiramisu","page":"Książka kucharska/Tiramisu"},{"id":"oc-plwb-62560","title":"Tortelli della Vigilia (Italian Christmas Eve ricotta dumplings)","cuisine":"Italian","category":"Main","ingredients":["250 g ricotta cheese","275 g plain flour (250–300 g)","3 eggs (2 for the dough and 1 for the filling)","250 ml tomato purée (passata) (1/4 litre)","5 fresh parsley (4–5 stalks)","80 g Parmesan cheese (30 g for the filling and 50 g for serving)","0.5 onion","5 tbsp olive oil","to taste ground nutmeg","to taste sugar","to taste salt","to taste black pepper"],"steps":["Knead a smooth dough from the plain flour, two eggs, and a pinch of salt.","Fry the finely chopped half onion in hot olive oil until browned, add the passata with a pinch of salt and sugar, then cook gently for about 20 minutes until the sauce thickens.","Grate the Parmesan and finely chop the parsley, then mix the ricotta, 30 g of Parmesan, parsley, and one egg in a bowl, seasoning the filling with salt, pepper, and nutmeg.","Roll out the dough thinly and cut it into rectangles measuring 10 × 5 cm.","Place a teaspoon of filling on each rectangle and pinch the edges firmly together with your fingers to seal the dumplings.","Cook the dumplings in salted boiling water for 4–5 minutes, drain, spoon over the thick tomato sauce, and sprinkle with the remaining grated Parmesan."],"time":65,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/W%C5%82oskie_piero%C5%BCki_wigilijne","page":"Książka kucharska/Włoskie pierożki wigilijne"},{"id":"oc-plwb-7898","title":"Vegetable risotto","cuisine":"Italian","category":"Main","ingredients":["150 g green beans (trimmed, chopped)","2 scallions with greens (chopped)","2 carrot (diced)","1 bell pepper (diced)","200 g broccoli (divided into florets)","200 g rice","750 ml vegetable broth (hot)","50 g firm cheese (grated)","3 tbsp cooking oil","to taste salt","to taste pepper"],"steps":["Dice the carrots and bell pepper, and finely chop the scallions with their greens.","Heat the oil in a pot or deep skillet, add the carrots, bell pepper, and scallions, and sauté for 3 minutes.","Add the rice and fry together for another 3 minutes, stirring constantly.","Pour in the hot vegetable broth and simmer over low heat for 20 minutes.","Add the chopped green beans and broccoli florets, and cook for another 15 minutes until the vegetables and rice are tender.","Season the dish with salt and pepper, and sprinkle with grated cheese before serving."],"time":56,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Risotto","page":"Książka kucharska/Risotto"},{"id":"oc-plwb-17826","title":"Zrazy cielęce (veal roulades)","cuisine":"Italian","category":"Main","ingredients":["600 g veal round","5 slice ham (4–6 slices)","1 tbsp lemon juice","2 tbsp fresh sage (chopped leaves (or 2 teaspoons dried))","1.5 tbsp all-purpose flour (1–2 tablespoons, for dusting and dredging)","2 tbsp margarine (for frying)","250 ml dry white wine (250 ml)","to taste salt"],"steps":["Wash and pat dry the veal, cut into 6 cutlets, pound lightly, sprinkle with lemon juice, season with salt, and dust lightly with flour.","Place a slice of ham on each cutlet, sprinkle with sage, roll up tightly, secure with white kitchen twine or toothpicks, and dredge in flour.","Brown the roulades in heated margarine on all sides until golden.","Transfer the roulades to a saucepan, pour over the pan drippings, add the white wine, and simmer covered over low heat for about 20 minutes.","Serve with fries or pasta and braised carrots."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zrazy_ciel%C4%99ce","page":"Książka kucharska/Zrazy cielęce"},{"id":"oc-plwb-17832","title":"Zucchini à la caprese","cuisine":"Italian","category":"Side","ingredients":["1 kg zucchini (small ones)","1 egg","4 tomatoes","100 g wheat flour","125 ml sunflower oil","to taste freshly ground black pepper","to taste salt","2 clove garlic","to taste fresh basil"],"steps":["Wash the zucchini, trim the ends and slice into rounds about 0.5 cm thick, season with salt and freshly ground black pepper, and rub with half of the crushed garlic.","Whisk the flour with water, the egg, and a pinch of salt to form a smooth batter with the consistency of heavy cream.","Dip the zucchini slices into the batter and fry in well-heated sunflower oil until golden on both sides.","Slice the tomatoes, add the remaining crushed garlic, and fry briefly in the pan.","Layer the fried zucchini slices alternately with the tomatoes on a platter and garnish with fresh basil leaves."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cukinia_a'la_caprese","page":"Książka kucharska/Cukinia a'la caprese"},{"id":"oc-plwb-8979","title":"Zupa minestrone (Minestrone)","cuisine":"Italian","category":"Soup","ingredients":["2 celery (stalks)","2 carrots","2 zucchini (small)","3 potatoes","150 g dried beans (white or red)","100 g smoked bacon","1 parsley root","1 onion (medium)","250 g tomatoes","5 parsley (sprigs)","1 clove garlic (clove)","0.25 savoy cabbage (head)","100 g green beans","300 g green peas (or 1 head of fennel)","150 g pasta (or rice)","1 tbsp Parmesan (grated (or other firm cheese))","4 fresh sage (leaves (a few leaves, or basil))","to taste olive oil (for frying)","to taste salt","2.5 l water (for cooking the soup (plus water to soak and boil the beans))"],"steps":["Cover the dried beans with cold water and leave to soak overnight, then the next day boil and drain them.","Dice the bacon, zucchini, peeled potatoes, and onion, and cut the celery and carrots into strips.","Scald the tomatoes with boiling water, rinse with cold water, peel off the skins, and cut into pieces.","Finely chop the parsley and garlic, and shred the savoy cabbage and sage or basil leaves into thin strips.","Trim the ends of the green beans and cut the pods into two-centimetre pieces (if using fennel, cut it into batons).","Place the bacon, onion, garlic, parsley, and sage or basil into a large pot, add the olive oil, and fry for 5 minutes.","Add the remaining vegetables except the tomatoes, beans, green beans, and peas, and fry briefly.","Pour in 2.5 l of water, add the cooked beans, season with salt, and simmer covered for 90 minutes.","Add the tomatoes, green beans, and peas (if using young peas, add them later together with the pasta or rice) and cook for 30 minutes.","Add the pasta or rice and optionally the young peas, and cook for another 20 minutes.","Season the soup with salt to taste and serve sprinkled with grated Parmesan."],"time":600,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_minestrone","page":"Książka kucharska/Zupa minestrone"},{"id":"oc-plwb-21756","title":"Nigiri sushi (tuna nigiri sushi)","cuisine":"Japanese","category":"Main","ingredients":["750 ml cooked sushi rice","350 g tuna fillet (thinly sliced)","2 tsp wasabi paste","60 ml soy sauce (for serving)"],"steps":["Shape the prepared sushi rice into small oblong mounds.","Lay a slice of tuna in the palm of your hand and swipe a touch of wasabi paste down its centre.","Place a rice mound onto the fish and press gently so that the fish and rice adhere closely.","Turn the sushi piece fish side up, neaten the edges, and press gently again to shape.","Repeat with the remaining rice and tuna, and serve the finished nigiri with soy sauce."],"time":20,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nigiri_sushi","page":"Książka kucharska/Nigiri sushi"},{"id":"oc-plwb-19291","title":"Okonomiyaki (Hiroshima-style Japanese savoury pancake)","cuisine":"Japanese","category":"Main","ingredients":["180 ml plain flour","180 ml water (ice cold)","1 egg","150 g white cabbage (two handfuls, finely shredded)","4 slice fresh pork belly (uncured bacon) (thin slices, preferably unsmoked)","200 ml Japanese wheat noodles (cooked)","100 g chicken breast","2 eggs","50 ml celery (thin slices)","50 ml leek (green part, thinly sliced)","50 ml fresh parsley leaves (chopped)","to taste okonomiyaki sauce","1 tsp soy sauce (optional)","1 tbsp vegetable oil (for greasing the pan)"],"steps":["Shred the white cabbage into thin strips about 3 mm wide, slice the pork belly into thin ribbons, and cut the chicken breast into strips.","Thinly slice the celery and leek, chop the parsley, and toss the greens together in a small bowl.","Cook and drain the noodles, and whisk the flour, cold water, and one egg into a smooth crepe batter.","Heat two frying pans lightly greased with oil; in the first pan fry a thin crepe, flip it over, and splash with soy sauce.","Layer the shredded cabbage, chicken pieces, and pork belly slices on top of the crepe.","Invert the second pan over the top, flip so that the crepe is on top, and cook over medium heat until the cabbage softens and the bacon browns.","In the smaller pan, lightly fry the cooked noodles, then flip the pancake using the pan, layer the noodles on top, and invert again so the crepe is facing up.","Fry two sunny-side-up eggs in the small pan, place them on top of the pancake, and flip the whole stack one last time for a moment.","Transfer the okonomiyaki to a large plate, cut into at least four wedges, drizzle generously with okonomiyaki sauce, and scatter the celery, leek, and parsley mixture over the top."],"time":45,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Okonomiyaki","page":"Książka kucharska/Okonomiyaki"},{"id":"oc-plwb-20819","title":"Morkovcha (Korean-style spiced carrot salad)","cuisine":"Korean","category":"Salad","ingredients":["500 g carrots","3.5 onions","125 ml vegetable oil","2.5 tbsp vinegar","1 tbsp sugar","3.5 clove garlic","2 tsp hot ground paprika","to taste salt"],"steps":["Peel the carrots and cut into long, thin matchsticks or shred on a coarse grater.","Salt the carrots, toss, set aside for 30 minutes, then drain off the released juices.","Add salt, sugar, and hot ground paprika to the drained carrots.","Peel and chop the onion, fry in the vegetable oil until deep golden, then remove the onion from the pan and discard.","Let the infused oil cool slightly, carefully pour in the vinegar, stir, and pour the hot mixture over the carrots.","Add the pressed garlic, toss thoroughly, and chill in the refrigerator for 2–3 hours before serving."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Marchewka_po_korea%C5%84sku","page":"Książka kucharska/Marchewka po koreańsku"},{"id":"oc-plwb-20804","title":"Zupa z pulpecikami (Korean-style meatball and tofu soup)","cuisine":"Korean","category":"Soup","ingredients":["200 g minced beef","200 g tofu","2 eggs","2 tbsp wheat flour","1 tbsp sesame seeds (seeds)","1 tsp sesame oil","1 leek","3 clove garlic (cloves)","500 ml beef broth","to taste soy sauce","to taste salt"],"steps":["Finely chop the cleaned leek and peeled garlic.","Mix thoroughly in a bowl the minced beef, mashed tofu, chopped leek, garlic, eggs, flour, sesame seeds, and sesame oil.","Shape the prepared mixture into small balls about 2 cm in diameter.","Pour the beef broth into a pot, bring to a boil, and carefully drop in the shaped meatballs.","Cook over moderate heat until boiling again and the meatballs are cooked through, and finish by seasoning with salt and soy sauce; serve alone or with bread."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_pulpecikami","page":"Książka kucharska/Zupa z pulpecikami"},{"id":"oc-plwb-6272","title":"Buritos (machaca beef burritos)","cuisine":"Mexican","category":"Main","ingredients":["600 g beef","2 clove garlic","2 tbsp lemon juice","1 tbsp oregano","0.5 tbsp salt (for marinade and extra to taste)","0.25 tsp black pepper","1 onion (small)","1 tbsp oil","12 tortillas (or crêpes)"],"steps":["Rinse the beef and rub it with a blended paste of garlic, lemon juice, oregano, salt, and black pepper, then marinate for 240–360 minutes.","Fry the marinated meat, shred it into small pieces, and air-dry in a well-ventilated spot for about 360 minutes.","Peel the onion, rinse it, finely chop, and sauté in heated oil in a pot.","Add the prepared beef to the onion, fry until well browned, then season with salt and stir.","Warm the tortillas in the oven, place several spoonfuls of meat onto each, roll up, and serve hot."],"time":55,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Buritos","page":"Książka kucharska/Buritos"},{"id":"oc-plwb-10735","title":"Burritos (chicken and red bean burritos)","cuisine":"Mexican","category":"Main","ingredients":["1 chicken breast","2 canned red kidney beans (2–3 cans)","1 canned tomatoes (can)","2 onion (2–3 onions)","2 clove garlic","250 g semi-hard yellow cheese (200–300 g, grated)","1 chili pepper (or chili powder)","to taste hot paprika","to taste chives","0.5 tsp ground cinnamon","to taste salt","to taste black pepper","to taste basil","to taste oregano","2 tbsp olive oil (for frying and dough)","300 g wheat flour (about 300 g for making dough for 6 flatbreads)","180 ml water (about 180 ml of warm water for making the dough)"],"steps":["Dice the chicken breast, season with salt, black pepper, oregano, cinnamon, and hot paprika, then fry in hot olive oil and transfer to a pot.","In the same pan, fry the minced garlic and sliced onion rings, add the drained canned red kidney beans and canned tomatoes, and cook together briefly.","Transfer the pan contents to the pot with the chicken, add the chopped chili pepper, and braise for about 10 minutes, finishing with the basil and chopped chives.","Knead a pliable, soft dough from wheat flour, water, and a splash of olive oil, then rest for 20 minutes.","Divide the dough into portions, roll each into a thin round flatbread, and cook on both sides in a hot dry skillet.","Place the grated yellow cheese and hot filling on the cooked flatbreads, then fold them in half or roll them up."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Burritos","page":"Książka kucharska/Burritos"},{"id":"oc-plwb-13951","title":"Chili con carne (Mexican beef and bean chili)","cuisine":"Mexican","category":"Main","ingredients":["250 g canned red kidney beans","500 g minced beef","2 red chili peppers (2–3 peppers)","1 red bell pepper","1 onion","1 tbsp tomato purée","2 clove garlic","800 g canned peeled tomatoes (2–3 cans)","500 ml broth (from a stock cube)","100 g canned sweetcorn","2 bay leaf","to taste olive oil (for frying)","to taste basil (fresh, for garnish)","to taste salt","to taste black pepper","to taste cayenne pepper"],"steps":["Dice the red bell pepper and onion, and finely chop the red chili peppers and garlic.","Brown the minced beef in heated olive oil together with the onion and garlic.","Add the chili peppers, red bell pepper, tomato purée, and cayenne pepper, and braise briefly.","Pour in the broth, add the bay leaves and canned tomatoes with their juice, and simmer covered for 15–20 minutes.","Stir in the canned red kidney beans and canned sweetcorn, and cook for another 2–3 minutes until the sauce thickens.","Season to taste with salt, black pepper, and cayenne pepper, then garnish with fresh basil before serving."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chili_con_carne","page":"Książka kucharska/Chili con carne"},{"id":"oc-plwb-18025","title":"Fajitas","cuisine":"Mexican","category":"Main","ingredients":["300 g beef or chicken breast fillets","1 red bell pepper (medium-sized)","1 large onion","3 tbsp cooking oil","to taste garlic","to taste marjoram","to taste ground cumin","to taste hot paprika","to taste black pepper","3 flour tortillas","to taste firm cheese (grated)","to taste guacamole","to taste salsa sauce","to taste sour cream"],"steps":["Cut the meat and red bell pepper into thin strips, and slice the onion into thick wedges.","Mix the oil with the garlic, marjoram, cumin, hot paprika, and black pepper.","Toss the meat in the marinade and let sit for about 40 minutes.","Heat a grill pan and sear the meat together with the bell pepper and onion for 6–9 minutes until browned and cooked through.","Serve with warm flour tortillas, sprinkled with grated cheese, alongside guacamole, sour cream, and salsa."],"time":58,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fajitas","page":"Książka kucharska/Fajitas"},{"id":"oc-plwb-11553","title":"Kakao korzenne (spiced hot cocoa)","cuisine":"Mexican","category":"Drink","ingredients":["2 tbsp unsweetened cocoa powder (dark)","2.5 tsp brown sugar (2–3 teaspoons)","1 pinch cinnamon","1 pinch ginger","1 pinch ground chili (a knife-tip amount)","0.5 vanilla bean","500 ml milk (2 szklanki)","2 tbsp cold water (to dissolve the cocoa)"],"steps":["Bring the milk and brown sugar to a boil in a saucepan.","Slit the vanilla bean lengthwise in half and scrape out the seeds.","Dissolve the unsweetened cocoa powder in cold water, then add the cinnamon, ginger, ground chili, and vanilla.","Pour the cocoa mixture into the boiling milk, stir thoroughly, remove from the heat, and serve hot."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kakao_korzenne","page":"Książka kucharska/Kakao korzenne"},{"id":"oc-plwb-18093","title":"Ryż po meksykańsku (Mexican-style rice with stewing meat and beans)","cuisine":"Mexican","category":"Main","ingredients":["500 g stewing meat","300 g rice","1 bell pepper","2 clove garlic","1 tomato paste (small jar)","1 canned sweetcorn (can, drained)","1 canned red kidney beans (can, drained)","2 tbsp parsley (chopped)","to taste cooking fat","to taste salt","to taste black pepper","to taste hot ground paprika","to taste sweet paprika"],"steps":["Dice the stewing meat finely, brown it in hot cooking fat, and season generously with salt, pepper, sweet paprika and hot paprika.","Wash the bell pepper, remove the seeds, and dice the flesh; press the peeled garlic through a garlic press.","Once the meat has browned and softened slightly, add water, tomato paste, diced bell pepper, garlic, and the uncooked rice.","Simmer everything gently over low heat until the rice is almost tender, then stir in the drained sweetcorn and red kidney beans, and heat through for a few minutes.","Sprinkle the finished dish with chopped parsley before serving."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ry%C5%BC_po_meksyka%C5%84sku","page":"Książka kucharska/Ryż po meksykańsku"},{"id":"oc-plwb-10449","title":"Chir (Middle Eastern milk and rice dessert)","cuisine":"Middle Eastern","category":"Dessert","ingredients":["6 cardamom pods (seeds)","1 l milk","250 ml rice (or 6 chopped carrots)","to taste butter","60 ml raisins","125 ml sugar","1 tbsp rose syrup","to taste pistachios (or almonds, for sprinkling)"],"steps":["Bring the milk to a boil in a wide pot, stir in the rice, and simmer over medium heat for about 5 minutes until the mixture begins to thicken.","Stirring continuously, add the sugar, raisins, seeds from the cardamom pods, and butter.","Cook for another 10–15 minutes until thick, stirring in the rose syrup along the way.","Pour the pudding into a serving dish or mould, scatter chopped pistachios over the top, cover, and chill before serving."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chir","page":"Książka kucharska/Chir"},{"id":"oc-plwb-62614","title":"Chopped liver (Wątróbka po żydowsku z drobiu)","cuisine":"Middle Eastern","category":"Snack","ingredients":["400 g poultry liver (chicken or turkey)","4 eggs","4 onions (large)","3.5 tbsp vegetable oil or goose fat","1.5 tbsp butter (optional)","to taste salt","to taste freshly ground black pepper","1 bunch fresh parsley (small bunch)"],"steps":["Hard-boil the eggs for 8–9 minutes, cool in cold water, peel, and cut into pieces.","Peel the onions, slice into fine dice or thin half-moons, fry in half of the fat over low heat until translucent and lightly caramelised, then transfer to a bowl.","Trim the liver of membranes and veins, rinse, pat dry with paper towels, and fry in the remaining fat over medium heat for 5–7 minutes, until no longer bloody but still tender.","Season the liver with salt and pepper towards the end of frying, transfer to the bowl with the onions, let cool slightly, and add the chopped eggs.","Chop the ingredients very finely with a large knife or pulse in a food processor to make a slightly grainy spread. Add the softened butter and some of the chopped parsley, and season to taste with salt and pepper.","Garnish with the remaining parsley, cover, and chill in the refrigerator for 1–2 hours before serving."],"time":170,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/W%C4%85tr%C3%B3bka_po_%C5%BCydowsku_z_drobiu","page":"Książka kucharska/Wątróbka po żydowsku z drobiu"},{"id":"oc-plwb-13843","title":"Czulent (traditional Jewish Sabbath stew)","cuisine":"Middle Eastern","category":"Main","ingredients":["500 ml pearl barley","500 ml large white runner beans (Jaś)","4 clove garlic","2 onion","3 potatoes","2 carrots","2 bay leaves","3 allspice berries","1.5 tsp freshly ground black pepper (1.5–2 tsp)","1.5 tsp salt","4 goose legs with fat (or half a goose with fat)"],"steps":["Soak the large white beans in cold water the day before preparing the stew.","Peel the onions, potatoes, carrots, and garlic and cut into large chunks, and divide the goose legs with fat into portions.","Place the meat, drained beans, pearl barley, vegetables, bay leaves, and allspice berries into a roasting pan, and season with salt and freshly ground pepper.","Pour in water to about 2 cm above the ingredients and cover the pan tightly.","Place the roasting pan in an oven preheated to 100 °C (reduce temperature to 80 °C if needed) and bake for 1440 minutes."],"time":600,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Czulent","page":"Książka kucharska/Czulent"},{"id":"oc-plwb-56213","title":"Farfel (Jewish egg noodle pellets)","cuisine":"Middle Eastern","category":"Side","ingredients":["200 g plain flour","2 eggs","to taste salt (for cooking water)"],"steps":["Whisk the eggs with a fork, pour into the flour, and knead by hand for about 5 minutes into a very stiff, compact dough.","Divide the dough into smaller portions, roll into finger-thick ropes, and set aside to dry slightly.","Chop the dried dough ropes into tiny pellets the size of rice grains and leave to dry completely.","Before serving, drop the farfel into boiling salted water and cook for about 5 minutes, then drain."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Farfelki","page":"Książka kucharska/Farfelki"},{"id":"oc-plwb-61682","title":"Harira (Moroccan spiced meat and lentil soup)","cuisine":"Middle Eastern","category":"Soup","ingredients":["300 g bone-in beef (e.g. flank)","125 g dried chickpeas (or 250 g cooked)","50 g red lentils","1 onion (medium)","0.5 celery stalk","50 g fine vermicelli noodles","400 g canned tomatoes","1.5 l water","1 tsp ground ginger","0.5 tsp ground coriander","0.5 tbsp tomato paste","0.5 tbsp butter","1 pinch saffron","2 tbsp parsley leaves (chopped)","to taste fresh coriander","to taste salt","to taste black pepper"],"steps":["Soak the dried chickpeas in plenty of cold water overnight, then drain.","Place the diced beef and the bone into a large pot, pour in 1.5 l of water, bring to a boil, and skim the foam.","Add the drained chickpeas, red lentils, butter, chopped onion, and diced celery, season with saffron, ginger, ground coriander, salt, and black pepper, and simmer covered over low heat for 75 minutes.","Add the blended canned tomatoes and tomato paste, season to taste with salt and black pepper, and simmer for another 30 minutes.","Add the dry fine vermicelli noodles, cook for about 15 minutes until the pasta is tender, and finish by stirring in chopped parsley leaves and fresh coriander."],"time":140,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Harira","page":"Książka kucharska/Harira"},{"id":"oc-plwb-9357","title":"Hummus","cuisine":"Middle Eastern","category":"Sauce","ingredients":["250 g dried chickpeas","1.5 l water (for soaking and cooking chickpeas)","3 clove garlic","2 lemon (juice)","100 g tahini sesame paste","1 bunch parsley leaves","3 tbsp olive oil","to taste salt","to taste black pepper (or ground cumin)","to taste herbs and spices"],"steps":["Soak the chickpeas in cold water for several hours or overnight.","Drain the chickpeas, cover with fresh water, and cook until tender.","Blend the cooked chickpeas until smooth with the crushed garlic, freshly squeezed lemon juice, tahini, and olive oil.","Season the hummus to taste with salt, black pepper, and herbs and spices, then garnish with chopped parsley leaves before serving."],"time":110,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Hummus","page":"Książka kucharska/Hummus"},{"id":"oc-plwb-56385","title":"Karp po żydowsku (Jewish gefilte fish carp in sweet almond jelly)","cuisine":"Middle Eastern","category":"Main","ingredients":["2 kg whole carp","350 g onions","3 eggs","200 g matzo","80 g almonds","200 g onions","50 g gelatin","50 g raisins","50 g almonds","1 bunch fresh dill","1 bunch celery leaves","1.5 l water (for stock and soaking)","to taste salt","to taste black pepper","to taste sugar"],"steps":["Scale the carp, cut off head, fins, and tail, eviscerate without slitting the belly open, and carefully peel the skin off whole.","Debone the meat, place the fish heads without eyes and the backbones in a saucepan with water, simmer to make a fish stock, and strain.","Grind the fish meat in a meat grinder together with the soaked and squeezed matzo and 350 g of peeled onions.","Combine the fish mixture with egg yolks, beaten egg white foam, and 80 g of blanched, peeled, and chopped almonds, then season with salt, sugar, and pepper.","Stuff the carp skin with the filling, arrange in a wide pan, pour over warm fish stock, and simmer gently for 10 minutes.","Add the remaining 200 g of finely chopped onions, 50 g of chopped almonds, and the raisins to the broth, season with salt, pepper, and sugar, and simmer for another 15 minutes.","Towards the end of cooking, dissolve the pre-soaked gelatin in the hot broth.","Remove the cooked fish, slice into portions, arrange on a serving platter, pour over the broth, garnish with celery leaves and dill, and chill until set."],"time":100,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Karp_po_%C5%BCydowsku","page":"Książka kucharska/Karp po żydowsku"},{"id":"oc-plwb-21695","title":"Kawa po turecku (Turkish coffee with spices)","cuisine":"Middle Eastern","category":"Drink","ingredients":["180 ml water","4 tsp finely ground coffee","2 tsp sugar","1 pinch cinnamon or cardamom (or ginger or anise)"],"steps":["Pour water into the cezve, heat without bringing to a boil, stir in sugar until dissolved.","Add the finely ground coffee and cinnamon or cardamom, and stir.","Heat the coffee over low heat without stirring until foam starts to rise, then remove from heat just before boiling.","Repeat heating and taking off heat twice more, then pour the coffee with its foam into small cups."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kawa_po_turecku","page":"Książka kucharska/Kawa po turecku"},{"id":"oc-plwb-62038","title":"Palce wezyra (vezir parmağı / Turkish choux pastry fingers in syrup)","cuisine":"Middle Eastern","category":"Cookie","ingredients":["2 tbsp butter","375 ml water","250 ml plain flour","2 eggs","1 egg yolk","0.5 tsp salt","310 ml olive oil (for shaping and frying)","500 ml sugar","440 ml water","1 tbsp lemon juice"],"steps":["Boil a thick syrup from the sugar, 440 ml of water, and lemon juice, and set aside to cool completely.","Melt the butter in a saucepan, add 375 ml of water and salt, and bring to a boil.","Lower the heat, dump in all the flour at once, and beat vigorously with a wooden spoon until the dough pulls away from the sides, then remove from the heat and let cool.","Add the eggs and egg yolk to the cooled dough and beat with a wooden spoon for about 10 minutes.","Pinch off portions of dough and, with oiled hands, shape into small finger-sized cylinders.","Fry the fingers in hot olive oil until golden, lift out with a slotted spoon, and drain on baking paper.","Submerge the cooled pastries in the cold syrup for 15 minutes, then drain and arrange on a serving platter."],"time":60,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Palce_wezyra","page":"Książka kucharska/Palce wezyra"},{"id":"oc-plwb-18844","title":"Pomegranate and orange salad (Sałatka z granatem)","cuisine":"Middle Eastern","category":"Salad","ingredients":["1 pomegranate (ripe)","3 oranges","to taste olive oil","to taste herbs","to taste salt"],"steps":["Cut the pomegranate in half, squeeze the juice into a bowl, and pick out all the seeds from inside.","Peel the oranges and slice the flesh into rounds.","Arrange the orange slices in a shallow salad dish, scatter the pomegranate seeds on top, drizzle with olive oil, and dust with salt and herbs."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_granatem","page":"Książka kucharska/Sałatka z granatem"},{"id":"oc-plwb-32800","title":"Potato kugel","cuisine":"Middle Eastern","category":"Side","ingredients":["8 potatoes","1 onion (large)","6 tbsp matzo meal","3 eggs (estimated quantity)","to taste margarine","to taste sunflower oil (for greasing the tin)","to taste salt","to taste pepper"],"steps":["Peel and rinse the potatoes and onion, grate them finely, and squeeze out the excess liquid in a colander.","Separate the egg whites from the yolks and beat the whites until stiff peaks form.","Add the egg yolks, whipped egg whites, matzo meal, margarine, salt, and pepper to the potato mixture, folding together thoroughly.","Transfer the mixture to a baking dish greased with sunflower oil and bake in the oven for about 60 minutes until crisp and golden on top."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kugel","page":"Książka kucharska/Kugel"},{"id":"oc-plwb-56402","title":"Pstrąg po galicyjsku (Galician-style trout with horseradish)","cuisine":"Middle Eastern","category":"Main","ingredients":["4 trout","4 clove garlic","2 lemon (part for juice, part sliced for garnish)","4.5 tbsp cooking oil (4–5 tbsp)","1 bunch parsley leaves","50 g fresh horseradish (root, freshly grated)","to taste salt","to taste pepper"],"steps":["Clean the trout, leaving the heads on after removing the eyes, rinse several times in cold water, and pat dry thoroughly.","Mince and crush the garlic cloves, and squeeze the juice from the lemons.","Rub the fish with crushed garlic and salt, season lightly with pepper, stuff the cavities with parsley leaves, and drizzle with lemon juice.","Place the trout into a skillet with well-heated oil and fry for 15 minutes on both sides.","Before serving, sprinkle the fried fish with freshly grated horseradish and garnish with halved lemon slices."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pstr%C4%85g_po_galicyjsku","page":"Książka kucharska/Pstrąg po galicyjsku"},{"id":"oc-plwb-56165","title":"Sałatka tapuli (Tabbouleh salad)","cuisine":"Middle Eastern","category":"Salad","ingredients":["250 ml bulgur wheat (preferably fine)","250 ml tomatoes (diced)","250 ml cucumbers (diced)","1 onion","6 tbsp olive oil","5 tbsp fresh mint (chopped)","2 tbsp parsley (chopped)","2 lemons (juiced)","to taste salt","to taste black pepper"],"steps":["Cover the bulgur wheat with water and let stand for 120 minutes to plump, then drain thoroughly.","Combine the drained bulgur with the diced tomatoes and cucumbers and the finely chopped onion.","Add the chopped fresh mint and parsley and toss the ingredients together.","Pour in the olive oil and freshly squeezed lemon juice, season with salt and pepper, and mix thoroughly."],"time":135,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_tapuli","page":"Książka kucharska/Sałatka tapuli"},{"id":"oc-plwb-62034","title":"Syrian Pistachio Baklava (Baklawa syryjska)","cuisine":"Middle Eastern","category":"Dessert","ingredients":["8 phyllo pastry sheets","350 g pistachio nuts (shelled and unsalted)","100 g butter (chilled)","150 g sugar","1 lemon (squeezed juice)","to taste orange flavouring (a few drops)","500 ml water (for the syrup)"],"steps":["Grease a baking sheet with a little butter, line with 4 sheets of phyllo pastry, and scatter with half of the chilled butter shaved into thin curls.","Evenly spread the coarsely ground pistachios, cover with the remaining 4 sheets of phyllo, and top with the rest of the butter shavings.","Place the pan in an oven preheated to 170 °C, bake for 35 minutes, then increase the temperature to 210 °C and bake for another 10 minutes.","Dissolve the sugar in water, bring to a boil, stir in the lemon juice, and simmer until syrupy, then add a few drops of orange flavouring, cook for 2 minutes more, and allow to cool.","Slice the baked pastry into diamonds and soak evenly with the prepared syrup."],"time":70,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Baklawa_(syryjska)","page":"Książka kucharska/Baklawa (syryjska)"},{"id":"oc-plws-44928","title":"Szczupak faszerowany po żydowsku (Jewish-style stuffed pike)","cuisine":"Middle Eastern","category":"Main","ingredients":["1 pike (whole with head, liver, and milt (approx. 1.2 kg))","2 onion (1 scalded with boiling water and chopped for the stuffing, and 1 for the stock)","1 white wheat roll (soaked in milk and squeezed dry)","100 ml milk (for soaking the roll)","1 pinch mace (or nutmeg)","2 tbsp butter (orig. a couple of tablespoons of butter for the stuffing (plus optional extra for drizzling with breadcrumbs))","2 eggs (orig. a couple of eggs)","1 bunch soup vegetables (a bunch, for the stock)","1.5 l water (for boiling the soup-vegetable stock and scalding the onion)","to taste salt","to taste black pepper"],"steps":["Clean the pike, slit it lengthwise, and carefully remove all the flesh, leaving the skin intact along with the head and tail.","Carefully bone the fish flesh, salt it, and chop it very finely together with the boiling-water-scalded onion and the pike's liver and milt.","Add the milk-soaked and squeezed wheat roll, black pepper, a pinch of mace, 2 tablespoons of butter, and 2 eggs to the chopped fish, and knead the mixture thoroughly.","Fill the pike skin with the stuffing, sew it up tightly, wrap the fish firmly in a clean linen cloth, and tie with kitchen twine.","Lay the pike in an oblong fish kettle or pan, pour over the boiling stock made from the soup vegetables and onion, and simmer over low heat for 30 minutes.","Lift out the fish, unwrap the cloth, and serve whole while hot (for example with melted butter and browned breadcrumbs or parsley sauce) or cooled and sliced with olive oil and vinegar."],"time":75,"servings":6,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Szczupak_faszerowany%2C_po_%C5%BCydowsku","page":"365 obiadów za 5 złotych/Szczupak faszerowany, po żydowsku"},{"id":"oc-plwb-56135","title":"Turkish spiced minced lamb kebabs (Kofte)","cuisine":"Middle Eastern","category":"Main","ingredients":["375 g lean ground lamb","4 spring onions","0.5 tsp granulated garlic","1 tbsp parsley leaves (chopped)","0.5 tsp sweet ground paprika","0.5 tsp ground allspice","0.5 tsp ground cumin","0.5 tsp dried oregano","1 egg white","to taste salt","to taste black pepper"],"steps":["Finely chop the spring onions and mix in a large bowl with the ground lamb, granulated garlic, parsley leaves, sweet paprika, allspice, cumin, oregano, egg white, salt, and black pepper.","Divide the meat mixture into 6 portions and shape into elongated kebabs on skewers or 6 oval patties.","Cook under a preheated oven grill or fry in a pan for 4–5 minutes on each side until nicely browned."],"time":25,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jagni%C4%99cina_po_turecku","page":"Książka kucharska/Jagnięcina po turecku"},{"id":"oc-plwb-18810","title":"Turkish-style braised vegetables (Warzywa po turecku)","cuisine":"Middle Eastern","category":"Main","ingredients":["2 green bell peppers","2 yellow bell peppers","2 red bell peppers","500 g tomatoes","300 g courgette","500 g aubergines","200 g onions","200 g green beans","2 tbsp lemon juice","1 tbsp plain flour","6 tbsp olive oil","2 bunch fresh parsley (chopped)","to taste salt","to taste black pepper","500 ml water (for braising the vegetables)"],"steps":["Scald and peel the tomatoes, cut them and the onions into thin rounds, cut the peppers into pieces, and slice the courgette and aubergines.","Season the aubergine slices with salt and pepper, sprinkle with lemon juice, and set aside for 10 minutes, then dredge in flour, fry in 3 tablespoons of olive oil until golden, and drain.","Cook the green beans for 2 minutes in a small amount of salted boiling water and drain.","Season the remaining vegetables with salt and pepper, arrange them in layers in a shallow pot, top with the fried aubergines, and pour over 500 ml of water and the remaining 3 tablespoons of olive oil.","Braise covered for about 45 minutes, and garnish generously with chopped fresh parsley before serving."],"time":90,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Warzywa_po_turecku","page":"Książka kucharska/Warzywa po turecku"},{"id":"oc-plwb-5734","title":"Janssons frestelse (Swedish potato and anchovy casserole)","cuisine":"Nordic","category":"Main","ingredients":["9 potatoes (8–10 pieces)","2 onions (large)","200 g anchovies (fillets or 15 whole anchovies)","300 ml sour cream","to taste breadcrumbs","1.5 tbsp butter (1–2 tablespoons)"],"steps":["Preheat the oven to 225 °C.","Peel the potatoes and cut them into strips, slice or finely chop the onions, and cut the anchovies into smaller pieces.","Grease a baking dish with butter.","Layer the potatoes, onions, and anchovies in the dish, starting and finishing with a layer of potatoes.","Pour half of the sour cream (150 ml) over the casserole, sprinkle with a thin layer of breadcrumbs, and place in the oven.","After 30 minutes of baking, pour the remaining sour cream over the dish and bake for another 15 minutes, until the top is golden brown and the potatoes are tender."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Janssons_frestelse","page":"Książka kucharska/Janssons frestelse"},{"id":"oc-plwb-5617","title":"Kräftströmming (Swedish baked herring)","cuisine":"Nordic","category":"Main","ingredients":["550 g fresh herring fillets (500–600 g)","1.5 tsp salt (1–2 tsp)","4.5 tomatoes (4–5 tomatoes)","2 tbsp tomato purée or paste","2 tbsp water","2 tbsp butter or margarine","100 ml fresh dill (chopped)","2 tbsp breadcrumbs"],"steps":["Preheat the oven to 225 °C.","Season the herring fillets with salt on the flesh side, roll them up skin-side inwards, and arrange tightly in a baking dish.","Top the herring rolls with tomato slices, pour over the tomato purée mixed with water, and dot with butter or margarine.","Scatter the chopped dill and breadcrumbs over the top.","Place the dish in the oven and bake for 20–25 minutes."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kr%C3%A4ftstr%C3%B6mming","page":"Książka kucharska/Kräftströmming"},{"id":"oc-plwb-28634","title":"Köttbullar (Swedish meatballs)","cuisine":"Nordic","category":"Main","ingredients":["300 g minced beef or pork","125 ml breadcrumbs","1 red onion (medium)","1 egg","to taste salt","to taste pepper","to taste butter or olive oil (for frying)","2 tbsp honey","60 ml sour cream or cream"],"steps":["Mix the breadcrumbs with the cream and let stand for several minutes to swell.","Finely chop the red onion and sauté in a pan in butter or olive oil until softened.","In a bowl, combine the minced meat with the egg, honey, salt, pepper, soaked breadcrumbs, and cooked onion, working into a smooth mixture.","Shape into small spherical meatballs and fry in a pan until golden brown."],"time":null,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/K%C3%B6ttbullar","page":"Książka kucharska/Köttbullar"},{"id":"oc-plwb-30757","title":"Nalewka Glögg (Nordic spiced mulled wine)","cuisine":"Nordic","category":"Drink","ingredients":["10 g cardamom seeds (whole)","10 g whole cloves","25 g cinnamon bark (in pieces)","1 l vodka","750 ml dry red wine","500 ml port wine","250 g sugar (for syrup)","250 ml water (for syrup)","100 ml brandy","0.5 lemon (juiced)","to taste raisins (for serving)","to taste almonds (for serving)"],"steps":["Place the cardamom seeds, cloves, and cinnamon pieces into a jar, pour over the vodka, and leave to infuse for 3 days.","Bring the water and sugar to a boil to make a simple syrup.","Strain the spiced vodka from the aromatics and combine in a large pot with the red wine, port, brandy, simple syrup, and lemon juice.","Heat the mixture gently without letting it boil.","Drop a few raisins and almonds into small glasses and ladle in the steaming glögg."],"time":30,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_Gl%C3%B6gg","page":"Książka kucharska/Nalewka Glögg"},{"id":"oc-plwb-14403","title":"Norwegian-style marinated salmon","cuisine":"Nordic","category":"Snack","ingredients":["3 salmon fillet","1 kg lemon","300 g French whole-grain mustard","3 bunch dill"],"steps":["Clean, rinse, and gently dry the salmon fillets, trim off the skin, and slice the flesh diagonally into strips about 5 mm thick.","Scald and dry the lemons, set aside a few slices for garnish, and squeeze the juice from the rest.","Place the salmon strips in a dish, pour over the lemon juice, add the French mustard and finely chopped dill, and mix thoroughly.","Cover the dish with plastic wrap and chill in the refrigerator for 24 hours, then garnish with the reserved lemon slices before serving."],"time":20,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Marynowany_%C5%82oso%C5%9B_po_norwesku","page":"Książka kucharska/Marynowany łosoś po norwesku"},{"id":"oc-plwb-61744","title":"Nyponsoppa (Swedish rosehip soup)","cuisine":"Nordic","category":"Soup","ingredients":["1 l fresh rosehips (stalks removed)","1.5 l water (cold)","125 g sugar","3 tbsp potato starch (optional, for thickening)"],"steps":["Trim the green tips from the rosehips, slice them into halves or quarters, and optionally remove some of the seeds.","Cover the rosehips with water and boil for 15 minutes, skimming off the foam and floating seeds regularly.","Puree the soup with an immersion blender until smooth, simmer for another 2 minutes, then press through a fine sieve into a clean pot.","Stir in the sugar until dissolved, and if desired, thicken the soup with potato starch slurried in a little cold water, bringing it briefly to a boil."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nyponsoppa","page":"Książka kucharska/Nyponsoppa"},{"id":"oc-plwb-16841","title":"Owocowy chłodnik duński (Danish strawberry buttermilk cold soup / koldskål)","cuisine":"Nordic","category":"Soup","ingredients":["300 g strawberries","750 ml buttermilk (well chilled)","125 ml whipping cream (30% fat) (for whipping)","2 egg yolks","100 g sugar","1 tbsp lemon juice","4 tbsp flaked almonds","to taste mini meringues (for garnish)"],"steps":["Wash the strawberries, hull them and set aside a few berries for garnish; blend the remainder, press through a sieve, and chill.","Whisk the egg yolks with sugar and lemon juice until pale and fluffy.","Whip the cream to stiff peaks, lightly whisk the chilled buttermilk, and pour it into the whisked yolks.","Fold in the whipped cream and strawberry puree until gently combined.","Ladle the cold soup into four bowls, scatter with flaked almonds, and garnish with sliced strawberries and mini meringues."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Owocowy_ch%C5%82odnik_du%C5%84ski","page":"Książka kucharska/Owocowy chłodnik duński"},{"id":"oc-plwb-61739","title":"Suaasat (Greenlandic game soup)","cuisine":"Nordic","category":"Soup","ingredients":["1 kg venison or game meat (such as reindeer, diced)","3 onions (chopped)","2 carrots (sliced)","300 g wild mushrooms","200 g dried sour cherries","200 g pearl barley","1 lemon (grated zest only)","1 tsp fresh rosemary","1 tsp fresh thyme","1 tsp fresh sage","to taste sea salt","to taste black pepper (freshly ground)"],"steps":["Put the diced game meat, chopped onions, sliced carrots, cleaned wild mushrooms and dried sour cherries in a large pot.","Cover the ingredients with water, add the chopped rosemary, thyme, sage, sea salt, and pepper, and cook over medium heat for about 60 minutes until the meat is tender.","Add the pearl barley and grated lemon zest, season to taste, and simmer for another 30 minutes until the soup thickens."],"time":110,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Suaasat","page":"Książka kucharska/Suaasat"},{"id":"oc-plwb-18840","title":"Almond-stuffed dried figs in citrus syrup","cuisine":"Other","category":"Dessert","ingredients":["12 dried figs","80 ml orange juice (from 1 orange)","70 g almonds","70 g sugar","20 ml lemon juice (from half a lemon)","100 ml milk (for poaching the almonds)","75 ml water"],"steps":["Wash and dry the dried figs, then make a hollow pocket inside each fruit.","Chop the almonds, simmer them briefly in the milk, drain, and stuff them into the fig cavities.","Dissolve the sugar in the water, stir in the orange juice and lemon juice, and mix well.","Place the stuffed figs into the citrus syrup and simmer over gentle heat until tender.","Serve warm or thoroughly chilled."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Figi_nadziewane_migda%C5%82ami","page":"Książka kucharska/Figi nadziewane migdałami"},{"id":"oc-plwb-18042","title":"Aphrodite's Smile (Uśmiech Afrodyty)","cuisine":"Other","category":"Dessert","ingredients":["450 ml plain yogurt","3 tbsp honey","1 tsp ground cinnamon","50 g almonds","50 g dark chocolate"],"steps":["Chop the almonds and toast them gently in a dry frying pan.","Mix the plain yogurt with the honey, cinnamon, and toasted almonds.","Spoon the mixture into dessert glasses and refrigerate for 60 minutes.","Grate the dark chocolate into shavings and sprinkle over the chilled dessert before serving."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/U%C5%9Bmiech_Afrodyty","page":"Książka kucharska/Uśmiech Afrodyty"},{"id":"oc-plwb-14449","title":"Apricot and white wine mousse","cuisine":"Other","category":"Dessert","ingredients":["500 g apricots","100 g honey","6 gelatin sheets","250 ml dry white wine","to taste whipped cream (for garnish)"],"steps":["Wash and dry the apricots, cut them in half, discard the pits, then simmer in a small amount of water and blend into a smooth puree.","Pour the dry white wine into the fruit puree and sweeten to taste with honey.","Soak the gelatin sheets in cold water, dissolve them in a few tablespoons of hot water, and stir into the apricot mixture.","Spoon the dessert into dessert bowls, chill in the refrigerator until set, and garnish with whipped cream before serving."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Deser_morelowy","page":"Książka kucharska/Deser morelowy"},{"id":"oc-plwb-15994","title":"Avocado Stuffed with Beef Tartare","cuisine":"Other","category":"Snack","ingredients":["2 avocados (large)","2 onions (small)","3 tbsp mayonnaise","3 tbsp chopped parsley leaves and chives","to taste lettuce leaves","225 g beef steak tartare meat (200–250 g)","1.5 tbsp capers","to taste lemon juice","to taste ketchup","to taste salt","to taste black pepper"],"steps":["Season the mayonnaise with salt and pepper, set aside 1 tablespoon for the meat, and blend the rest with ketchup and 1 tablespoon of chopped parsley leaves and chives.","Mix the steak tartare meat with the finely chopped onion, the reserved tablespoon of mayonnaise, 1 tablespoon of herbs, and 1 tablespoon of capers.","Cut the avocados in half lengthwise, remove the pits, rub the flesh with lemon juice, and fill the hollows with the prepared beef tartare.","Line a platter with lettuce leaves, arrange the stuffed avocado halves on top, garnish with the remaining capers and herbs, and place the sauce in the centre."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Awokado_z_tatarem","page":"Książka kucharska/Awokado z tatarem"},{"id":"oc-plwb-21945","title":"Avocado Stuffed with Hard-Boiled Egg Salad","cuisine":"Other","category":"Snack","ingredients":["1 avocado","2 hard-boiled eggs","2 tomatoes","0.5 bunch chives","2 tbsp mayonnaise","to taste lemon juice","to taste salt","to taste black pepper"],"steps":["Wash the avocado, cut in half lengthwise, remove the pit, and scoop out the flesh leaving a half-centimetre rim next to the skin.","Dice the avocado flesh and toss it, along with the hollowed shells, with lemon juice to prevent discoloration.","Dice the hard-boiled eggs and tomatoes, and finely snip the rinsed and dried chives.","Gently combine the avocado with the eggs, tomatoes, chives, and mayonnaise, season with salt and pepper, and spoon the salad into the fruit halves."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Awokado_nadziewane_jajkiem","page":"Książka kucharska/Awokado nadziewane jajkiem"},{"id":"oc-plwb-8982","title":"Avocado Stuffed with Seafood","cuisine":"Other","category":"Snack","ingredients":["1 avocado","100 g canned shrimp or crab meat (1 can)","2.5 tbsp mayonnaise (2–3 tbsp)","1 tbsp cognac, brandy, or orange juice","1 tsp tomato purée","15 ml lemon juice (from 1/2 small lemon)"],"steps":["Drain the shrimp or crab meat in a sieve.","Mix the mayonnaise with the tomato purée and one tablespoon of cognac, brandy, or orange juice.","Cut the unpeeled avocado in half lengthwise, remove the pit, and scoop out the flesh without damaging the skin.","Drizzle the insides of the hollowed avocado skins with lemon juice to prevent browning.","Finely dice the avocado flesh, combine with the prepared dressing and seafood, and spoon the filling into the shells."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Awokado_z_owocami_morza","page":"Książka kucharska/Awokado z owocami morza"},{"id":"oc-plwb-1388","title":"Bacon-stuffed pasta nests","cuisine":"Other","category":"Main","ingredients":["400 g thin vermicelli noodles","200 g lean bacon","1 onion","3 tbsp cooking oil","2 tomato","0.5 bunch chives","to taste salt","to taste thyme"],"steps":["Cook the vermicelli noodles until tender and drain.","Finely dice the bacon and onion, fry in 1 tablespoon of oil, and season with salt and thyme.","Preheat the oven to 200 °C and grease a baking tray with 1 tablespoon of oil.","Shape the cooked noodles into nests, arrange them on the baking sheet, and fill the center of each nest with the bacon and onion mixture.","Drizzle the nests with the remaining oil, place a tomato slice on each, and sprinkle lightly with salt.","Bake in the oven for 10 minutes, and sprinkle with chopped chives before serving."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gniazdka_nadziewane_bekonem","page":"Książka kucharska/Gniazdka nadziewane bekonem"},{"id":"oc-plwb-21461","title":"Baked avocado with curd cheese and walnuts (Twaróg z awokado)","cuisine":"Other","category":"Snack","ingredients":["2 avocados","200 g farmer's cheese","100 g button mushrooms","1 onion","2 tbsp cooking oil","2 tbsp fresh parsley (chopped)","2 tbsp walnuts (chopped)","to taste lemon juice","to taste salt","to taste pepper"],"steps":["Dice the mushrooms and finely chop the onion, then cook the onion until translucent in hot oil, add the mushrooms, and cook gently.","Mash the farmer's cheese until smooth and combine with the cooled mushrooms, chopped parsley, and walnuts.","Wash the avocados, halve them lengthwise, remove the stones, and scoop out the flesh, leaving a rim about 1 cm thick along the skin.","Mash the scooped-out avocado flesh with a fork, sprinkle with lemon juice, combine with the cheese mixture, and season to taste with salt and pepper.","Fill the avocado halves with the prepared filling and bake for 10 minutes in an oven preheated to 200 °C."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Twar%C3%B3g_z_awokado","page":"Książka kucharska/Twaróg z awokado"},{"id":"oc-plwb-15327","title":"Baked ham with raisins (Szynka pieczona z rodzynkami)","cuisine":"Other","category":"Main","ingredients":["1 kg cooked ham","250 ml dry white wine","250 ml water","250 ml raisins","2 tbsp butter","2 tbsp brandy"],"steps":["Place the cooked ham in a baking dish, pour over the water and white wine, spread the ham with butter, and sprinkle the raisins over it.","Drizzle the meat with brandy and bake in an oven preheated to 180 °C for about 40 minutes.","Remove the meat from the oven, slice, and serve warm or chilled together with the raisins."],"time":50,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szynka_pieczona_z_rodzynkami","page":"Książka kucharska/Szynka pieczona z rodzynkami"},{"id":"oc-plwb-18787","title":"Baked potatoes with herb butter (Ziemniaki z masłem ziołowym)","cuisine":"Other","category":"Side","ingredients":["500 g potatoes","400 g herb butter (400 g in the original, probably intended to mean 40 g)","50 g firm cheese (grated)","1 tsp butter","1 clove garlic","to taste fresh herbs","to taste salt","to taste black pepper","to taste lemon juice","to taste fat (for greasing the baking dish)"],"steps":["Wash the potatoes, boil them in their skins, rinse with cold water, and slice into rounds about 0.5 cm thick.","Grease an ovenproof baking dish, arrange the potato slices in it, and season with salt.","Distribute half of the herb butter and crushed garlic over the potatoes, and sprinkle with lemon juice.","Sprinkle everything with grated firm cheese, fresh herbs, and pepper, dot the top with the remaining butter, and bake for 25 minutes in a very hot oven (approx. 200 °C).","Serve hot."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ziemniaki_z_mas%C5%82em_zio%C5%82owym","page":"Książka kucharska/Ziemniaki z masłem ziołowym"},{"id":"oc-plwb-13756","title":"Baked salmon on zucchini with mint salsa","cuisine":"Other","category":"Main","ingredients":["4 salmon steak","1 zucchini (large)","100 g butter","3.5 tbsp extra virgin olive oil (3–4 tablespoons)","1 tbsp wine vinegar","0.5 lemon (juiced)","1 bunch fresh mint","2 tomato (medium)","to taste coarsely ground black pepper","to taste salt"],"steps":["Mix the extra virgin olive oil with the wine vinegar and juice from half a lemon.","Peel the skin off the tomatoes, remove the seeds, dice the flesh finely, and combine with the dressing and finely chopped mint; season the salsa with salt and pepper.","Preheat the oven to 180 °C. Slice the zucchini into rounds 0.5 cm thick, arrange 4 rounds on each of four sheets of aluminium foil, and sprinkle with salt and pepper.","Salt the salmon steaks, sprinkle generously with coarsely ground black pepper, and arrange on the zucchini.","Place a portion of butter on each piece of fish, wrap the foil tightly, and bake for about 30 minutes at 180 °C. Serve with the salsa in separate small bowls."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/%C5%81oso%C5%9B_pieczony_na_cukinii_z_sals%C4%85_mi%C4%99tow%C4%85","page":"Książka kucharska/Łosoś pieczony na cukinii z salsą miętową"},{"id":"oc-plwb-14331","title":"Baked vegetable stew","cuisine":"Other","category":"Main","ingredients":["2 onion","1 zucchini (small)","200 g potatoes","1 eggplant (small)","1 red bell pepper","0.5 bunch parsley leaves","4 tbsp vegetable oil","to taste basil","to taste oregano","to taste salt","to taste black pepper"],"steps":["Peel and finely chop the onion, and wash the remaining vegetables.","Peel the potatoes, deseed the bell pepper, dice the zucchini, potatoes, and pepper, and cut the eggplant into bite-sized pieces.","Heat 3 tablespoons of oil in a frying pan, saute the vegetables with the onion for 7–8 minutes, and season with salt and black pepper.","Grease a baking dish with the remaining oil, transfer the vegetables into it, sprinkle with oregano and basil, and press down lightly.","Bake in an oven preheated to 180 °C for about 20 minutes, and garnish with chopped parsley leaves before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gulasz_warzywny","page":"Książka kucharska/Gulasz warzywny"},{"id":"oc-plwb-14338","title":"Bakłażanowe zawijasy (eggplant rolls wrapped in smoked bacon)","cuisine":"Other","category":"Snack","ingredients":["2 eggplants (long)","12 slice smoked bacon (thin slices)","1 onion","1 green bell pepper (whole pepper)","3 tbsp dried herbs: basil and tarragon","4 tbsp oil (3 tbsp for the stuffing, 1 tbsp for greasing the baking dish)","1 lemon juice (squeezed from 1 lemon)","to taste salt","to taste black pepper"],"steps":["Wash the eggplants, slice them lengthwise into slices about 5 mm thick, arrange on a baking sheet, and roast in the oven for 10 minutes.","Peel and chop the onion, and finely dice the green bell pepper.","Combine the onion and bell pepper with 3 tablespoons of oil and dried herbs, then season with salt, pepper, and lemon juice.","Spread a portion of the vegetable stuffing over each eggplant slice, roll up, wrap with a slice of smoked bacon, and secure with a toothpick.","Arrange the rolls in a baking dish greased with the remaining tablespoon of oil and bake for 10 minutes at 220 °C."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bak%C5%82a%C5%BCanowe_zawijasy","page":"Książka kucharska/Bakłażanowe zawijasy"},{"id":"oc-plwb-2720","title":"Banana milkshake","cuisine":"Other","category":"Drink","ingredients":["1 banana","300 ml milk","1 vanilla or cream ice cream (scoop)","to taste ground cinnamon (for dusting)","1 tsp lemon juice","1.5 ice cubes (optional, for froth)"],"steps":["Peel the banana, place it in a blender or food processor, and drizzle with lemon juice so it does not brown.","Add a scoop of vanilla or cream ice cream, pour in the milk, and optionally add 1–2 ice cubes to create a light froth.","Blend everything for 1–3 minutes until the ingredients are well combined and the ice is crushed.","Pour the cold drink into glasses and lightly dust the top with ground cinnamon."],"time":5,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Shake_Bananowy","page":"Książka kucharska/Shake Bananowy"},{"id":"oc-plwb-18658","title":"Bananas in Honey-Orange Sauce","cuisine":"Other","category":"Dessert","ingredients":["1 tsp butter (level teaspoon)","1 orange juice (squeezed from 1 orange)","1 tbsp honey","4 bananas","to taste whipped cream (for serving)"],"steps":["Combine the butter, freshly squeezed orange juice, and honey in a microwave-safe dish, microwave for about 2 minutes, and stir thoroughly.","Peel the bananas, slice them in half lengthwise, place in the prepared sauce, and turn to coat.","Microwave the bananas in the sauce for about 4 minutes, then serve with whipped cream."],"time":11,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Banany_w_sosie_miodowo-pomara%C5%84czowym","page":"Książka kucharska/Banany w sosie miodowo-pomarańczowym"},{"id":"oc-plwb-56122","title":"Banitsa with Cheese (Banica z serem)","cuisine":"Other","category":"Bread","ingredients":["425 g phyllo pastry sheets (400–450 g)","450 g feta-style cheese (400–500 g)","200 g oil","4 eggs","200 ml sparkling mineral water"],"steps":["Grease a baking sheet with a little oil, lay down a layer of phyllo pastry, and scatter with crumbled feta cheese.","Repeat layering the phyllo pastry and feta cheese until all ingredients are used, finishing with pastry on top, then cut into squares or rectangles.","Heat the remaining oil well and pour it over the sliced pastry.","Whisk the eggs with the sparkling mineral water and pour the mixture evenly over the top of the pastry.","Bake the banitsa in an oven preheated to 180–190 °C for about 35 minutes, until the pastry turns golden brown."],"time":55,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Banica_z_serem","page":"Książka kucharska/Banica z serem"},{"id":"oc-plwb-56124","title":"Banitsa with Minced Meat (Banica z mięsem)","cuisine":"Other","category":"Main","ingredients":["425 g phyllo pastry sheets (400–450 g)","450 g minced meat (400–500 g)","2 onions","2.5 bell peppers (2–3 pieces)","1.75 tsp salt (1.5–2 tsp)","1 tsp black pepper","1 tsp summer savory","3 eggs","250 ml sparkling mineral water","125 ml olive oil"],"steps":["Roast the bell peppers in the oven or on a grill, peel off the skins, and finely chop.","Peel and finely dice the onions, fry for 1–2 minutes in a portion of the olive oil, then add the minced meat, salt, pepper, and savory, frying and stirring for 3–4 minutes.","Stir the chopped peppers into the meat and divide the filling into 3 equal portions.","Grease a baking sheet with olive oil, place 2 flat sheets and 1 gently crumpled sheet of phyllo on the bottom, spread the first portion of filling, then repeat with more pastry and the remaining portions of filling, covering the top with the last sheets.","Cut the layered pastry into squares or rectangles with a sharp knife.","Whisk the eggs with the sparkling water and remaining olive oil, pour evenly over the top, and bake at 180–190 °C until golden brown."],"time":70,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Banica_z_mi%C4%99sem","page":"Książka kucharska/Banica z mięsem"},{"id":"oc-plwb-17148","title":"Basil chicken with carrots in sour cream sauce","cuisine":"Other","category":"Main","ingredients":["500 g chicken breast fillet","500 g carrots","2 onion","2 clove garlic","250 ml sour cream 18%","1 bunch fresh basil","250 ml chicken broth","1 tbsp plain flour","to taste salt","to taste pepper","to taste cooking fat"],"steps":["Cut the chicken fillets into large dice. Peel the carrots and onions and slice into rounds, and peel and mince the garlic.","Melt the cooking fat in a frying pan, add the chicken, and cook for 8–10 minutes, then season with salt and pepper.","Add the carrots, onion, and garlic, and cook together for 3 minutes.","Pour in the chicken broth and sour cream, bring to a brief boil, and thicken the sauce with the flour.","Lower the heat and braise for 10 minutes, then stir in the finely chopped basil and adjust the seasoning to taste."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_bazyliowy","page":"Książka kucharska/Kurczak bazyliowy"},{"id":"oc-plwb-16876","title":"Beef with pears (Wołowina z gruszkami)","cuisine":"Other","category":"Main","ingredients":["400 g lean beef or pork (listed as pork in ingredients, but beef in title and steps)","2 pears (firm)","2 carrots","1 fennel bulb (bulb)","2 tbsp soy sauce","to taste salt","to taste black pepper","3 fresh rosemary (a few sprigs)","1 l broth","1 onion (large)","2 bay leaf (leaves)","100 g mold-ripened cheese (any variety)"],"steps":["Cut the meat into four slices, sprinkle with soy sauce, cover, and let rest for 2 hours.","Pour the broth into a pot, add the rosemary sprigs, carrots, fennel, onion, bay leaves, and marinated meat slices, and cook until tender.","Peel the pears, halve, core, and slice them, then season each slice with salt and pepper and sprinkle with crumbled mold-ripened cheese.","Arrange the cooked meat slices alternately with the pear slices topped with mold-ripened cheese on a platter."],"time":195,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wo%C5%82owina_z_gruszkami","page":"Książka kucharska/Wołowina z gruszkami"},{"id":"oc-plwb-17747","title":"Beer-battered vegetables (Warzywa w cieście piwnym)","cuisine":"Other","category":"Snack","ingredients":["125 g plain flour","2 eggs","125 ml beer","3 courgettes (small)","1 broccoli","3 carrots","12 button mushrooms (small)","1 onion","1 tbsp herb grill seasoning","to taste fat for deep-frying","to taste salt (for blanching the vegetables and seasoning the mushrooms)"],"steps":["Mix the plain flour thoroughly with the egg yolks, beer, and herb seasoning, then gently fold in the stiffly beaten egg whites.","Trim and cut the courgettes, broccoli, carrots, and onion into pieces or slices, blanch in salted water for 2–3 minutes, then rinse with cold water, drain, and cool.","Clean the button mushrooms, cook gently covered until tender, and sprinkle with salt once cooled.","Dip the vegetables and mushrooms in batches into the beer batter and deep-fry for about 2 minutes until golden."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Warzywa_w_cie%C5%9Bcie_piwnym","page":"Książka kucharska/Warzywa w cieście piwnym"},{"id":"oc-plwb-55030","title":"Blackberry lemonade","cuisine":"Other","category":"Drink","ingredients":["200 g sugar","250 ml water (for the syrup)","60 ml blackberries (sorted berries)","1 fresh mint (sprig)","250 ml lemon juice","1 l water (for topping up)","to taste ice cubes","1 lemon (for garnish)"],"steps":["Prepare a syrup from 200 g of sugar and 250 ml of water, then pour in 250 ml of lemon juice and stir.","Blend 60 ml of blackberries, pass the puree through a sieve, and combine with the lemon syrup.","Top up the drink with 1 l of water and stir.","Add ice and mint leaves, and garnish with lemon slices."],"time":15,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_je%C5%BCynowa","page":"Książka kucharska/Lemoniada jeżynowa"},{"id":"oc-plwb-56437","title":"Bob chorba (Bulgarian bean soup / Bob czorba)","cuisine":"Other","category":"Soup","ingredients":["500 g dry white beans","2.5 l water (for soaking and fresh for cooking)","3.5 onions (3–4 onions)","4 hot chili peppers (chushki) (3–5 pods)","1 tsp sweet paprika powder","1 bunch fresh mint (bunch)","to taste vinegar","to taste salt"],"steps":["Sort and wash the dry beans, cover with cold water, and leave to soak overnight.","The next day, drain the soaking water (or bring to a boil and discard the first water), cover the beans with about 2 liters of fresh water, and simmer over low heat until tender.","Add the chopped onions, hot chili peppers, and ground paprika to the tender beans and simmer for about 30 minutes more (in variant II, also add finely chopped carrot, celery stalk, and parsley greens, and thicken the soup with a roux of oil, flour, and paprika).","Towards the end of cooking, season the soup with salt and vinegar to taste, and after removing from the heat, sprinkle generously with finely chopped fresh mint."],"time":600,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_fasolowa","page":"Książka kucharska/Zupa fasolowa"},{"id":"oc-plwb-22573","title":"Bobotie (South African spiced minced beef bake)","cuisine":"Other","category":"Main","ingredients":["30 ml oil or butter","2 onions (chopped)","1 clove garlic (large, minced)","1 green bell pepper (finely chopped)","1 carrot (grated)","1 Granny Smith apple (grated, optional)","500 g minced beef","2 slice bread","250 ml milk","2 eggs","15 ml curry powder","5 ml ground turmeric","5 ml ground cinnamon","2.5 ml ground coriander (half tsp)","15 ml sugar (optional)","10 ml salt","2.5 ml black pepper (half tsp)","30 ml vinegar or lemon juice","11 whole almonds (10–12 pieces)","125 ml raisins","45 ml chutney sauce","4 bay leaves or lemon leaves (or grated lemon zest)"],"steps":["Preheat the oven to 180 °C, and brown the chopped onion, garlic, green bell pepper, grated carrot, and apple in a pan with oil or butter.","Soak the slices of bread in the milk, then squeeze dry, saving the leftover milk for later.","Combine the minced beef with the fried vegetables, squeezed bread, 1 egg, curry, turmeric, cinnamon, coriander, sugar, 9 ml salt, pepper, vinegar or lemon juice, almonds, raisins, and chutney.","Transfer the meat mixture to a baking dish, tuck the rolled bay or lemon leaves upright into the surface, and bake for 40 minutes at 180 °C.","Beat the remaining egg with the reserved milk and the rest of the salt, pour over the casserole, and bake for another 20 minutes."],"time":85,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bobotie","page":"Książka kucharska/Bobotie"},{"id":"oc-plwb-17770","title":"Bomba z kremem (Strawberry cream bombe)","cuisine":"Other","category":"Cake","ingredients":["1 strawberry cream sponge cake roll","150 g strawberries","4 egg yolks","100 g powdered sugar","1 tbsp vanilla sugar","250 ml milk (for the cream)","8 tsp instant gelatin","250 ml whipping cream (30% fat, for the cream)","125 ml whipping cream (30% fat, for the decoration)","50 g apricot preserves","1 tsp vanilla sugar (for the decoration)","1 tbsp hazelnuts (chopped)"],"steps":["Cut the sponge cake roll into slices and line the bottom and sides of a 2-litre bowl, setting aside some slices to cover the top.","Cut the strawberries into pieces and toss with a tablespoon of vanilla sugar.","Dissolve the instant gelatin in a little hot water, beat the egg yolks with half the powdered sugar, combine with the hot milk and dissolved gelatin, then refrigerate until slightly set.","Whip the whipping cream for the cream filling with the remaining icing sugar, gently fold into the setting custard along with the strawberries, spoon into the roll-lined bowl, and cover with the reserved roll slices.","Refrigerate the dessert for 2–3 hours until completely set.","Invert the bombe onto a serving platter, brush with warmed apricot jam, decorate with the whipping cream for the decoration whipped with vanilla sugar, and sprinkle with chopped hazelnuts."],"time":50,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bomba_z_kremem","page":"Książka kucharska/Bomba z kremem"},{"id":"oc-plwb-30765","title":"Brain booster oat and fruit energy bars","cuisine":"Other","category":"Cookie","ingredients":["200 g walnuts (chopped)","200 g rolled oats (natural)","50 g cane sugar (or granulated white sugar)","30 g spelt flour","1 tsp baking powder","1 tsp ground cinnamon","50 g dark chocolate","50 g pumpkin seeds","30 g desiccated coconut (optional)","100 g dried apricots","125 ml honey","125 g butter (softened)"],"steps":["Combine the rolled oats, cane sugar, spelt flour, baking powder, cinnamon, coarsely grated dark chocolate, pumpkin seeds, and desiccated coconut in a bowl.","Finely dice the dried apricots, mash into a paste, and mix with the honey and softened butter.","Fold the apricot-butter paste thoroughly into the dry ingredients until evenly moistened.","Line a baking sheet with parchment paper, spread the mixture evenly while pressing down firmly, and bake for about 45 minutes at 160 °C.","Top the baked slab with the chopped walnuts, let cool completely, and slice into 12 bars."],"time":65,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Dopalacz_m%C3%B3zgu","page":"Książka kucharska/Dopalacz mózgu"},{"id":"oc-plwb-14285","title":"Braised beef with vegetables (Wołowina z warzywami)","cuisine":"Other","category":"Main","ingredients":["400 g beef","4 onions","2 tbsp vegetable oil","4 tbsp dry red wine","100 g carrots","100 g turnip","100 g celeriac","to taste salt","to taste sugar","2 bay leaf (leaves)","to taste thyme","to taste soy sauce","to taste black pepper","to taste water (for cooking vegetables)"],"steps":["Peel and chop the onions, fry them in oil, and sprinkle with sugar.","Add the beef cut into strips and brown, then add the red wine, soy sauce, bay leaves, and thyme, and braise until the meat is tender.","Wash and peel the carrots, turnip, and celeriac, cut into small dice, and cook until tender-crisp in lightly salted water.","Just before the vegetables are fully cooked, add the braised meat with sauce, simmer covered until done, and season to taste with salt and pepper."],"time":80,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wo%C5%82owina_z_warzywami","page":"Książka kucharska/Wołowina z warzywami"},{"id":"oc-plwb-18727","title":"Braised turkey breast with apricots and curry","cuisine":"Other","category":"Main","ingredients":["400 g turkey breast fillets","200 g canned apricots (plus 100 ml canning liquid)","2 onions","100 ml vegetable broth","2 tbsp olive oil","1 tbsp spicy fruit chutney","1 tsp potato starch","0.5 tsp curry powder","to taste salt","to taste black pepper"],"steps":["Slice the turkey breast fillets into thin strips and season with curry powder, salt, and black pepper.","Heat the olive oil in a saucepan, saute the chopped onion, add the meat strips, and brown on all sides.","Pour the hot vegetable broth over the meat and braise over low heat for about 15 minutes.","Add the sliced apricots, fruit chutney, and potato starch mixed with 100 ml of the apricot canning liquid, bring to a boil while stirring constantly, and season to taste with salt and black pepper."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Indyk_z_morelami","page":"Książka kucharska/Indyk z morelami"},{"id":"oc-plwb-15001","title":"Brzoskwinie w winnym sosie (peaches in white wine sabayon)","cuisine":"Other","category":"Dessert","ingredients":["500 g ripe peaches","250 ml white wine","4 egg yolks","50 g sugar"],"steps":["Wash the ripe peaches, cut them in half, discard the stones, and arrange the halves in dessert bowls.","Pour the white wine into a saucepan, cover, and bring to a boil.","Whisk the egg yolks with sugar until pale, then slowly pour in the hot wine, whisking constantly over a steam bath until the sauce thickens.","Pour the hot wine sauce over the peaches and set aside to cool."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Brzoskwinie_w_winnym_sosie","page":"Książka kucharska/Brzoskwinie w winnym sosie"},{"id":"oc-plwb-14358","title":"Bułeczki faszerowane (stuffed bread rolls)","cuisine":"Other","category":"Snack","ingredients":["2 red bell peppers (whole peppers)","6 small bread rolls","6 tbsp pesto sauce","200 g ham (thinly sliced)","1 tbsp lemon juice","4 tbsp olive oil","300 g mould-ripened cheese","1 pickled mushrooms (small jar)","50 g pickled green olives stuffed with pimiento","1 bunch parsley leaves"],"steps":["Roast the red bell peppers lightly in the oven, peel away the skin, remove the seeds, and cut the flesh into strips.","Slice the tops off the small bread rolls and hollow out the crumb from the bottoms.","Blend the scooped crumb with the pesto sauce, chopped parsley leaves, lemon juice, and olive oil, then spoon the filling into the rolls.","Top the rolls with ham slices, pepper strips, slices of mould-ripened cheese, pickled mushrooms, and pickled green olives with pimiento."],"time":40,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bu%C5%82eczki_faszerowane","page":"Książka kucharska/Bułeczki faszerowane"},{"id":"oc-plwb-61117","title":"Caldeirada de peixe (Portuguese fisherman's seafood stew)","cuisine":"Other","category":"Main","ingredients":["1 kg mussels","500 g shrimp","500 g cod fillets","2 sweet bell peppers","2 onions","2 tomatoes","1 chili pepper","8 clove garlic (1 head)","125 ml olive oil (half a glass)","100 ml red wine (1 small glass)","200 ml water (for adding to the pot during cooking)","1 bunch fresh coriander","1 tbsp thyme (a handful)","to taste salt"],"steps":["Pour the olive oil into a pot, add the chopped sweet peppers, onions, fresh coriander, and cut-up cod fillets, and fry for 3 minutes, stirring gently.","Add the thyme, chopped chili pepper, chopped tomatoes, and chopped garlic, then add some water.","Add the cleaned mussels and shrimp, season with salt, and simmer, covered, until the mussels open.","Pour in the red wine at the end, stir gently, and heat through for a moment."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gulasz_rybacki","page":"Książka kucharska/Gulasz rybacki"},{"id":"oc-plwb-61676","title":"Caldo verde (Portuguese potato and kale soup with chorizo)","cuisine":"Other","category":"Soup","ingredients":["2.5 l vegetable broth (or chicken broth)","300 g potatoes","1 leek","0.5 onion","1 clove garlic","100 g kale","100 g chorizo sausage (spicy)","1 tbsp tomato paste","1 tbsp butter","1 tbsp olive oil","2 tbsp fresh dill (chopped)","to taste salt","to taste black pepper"],"steps":["Cook the diced onion in melted butter until translucent, add the minced garlic towards the end, then pour in olive oil, add sliced leek, and braise for about 3 minutes.","Add the peeled, diced potatoes, season with salt, and cook for 3 minutes, then pour in the hot vegetable broth, season with black pepper, and simmer for 15 minutes.","Toss in the washed and shredded kale leaves along with the tomato paste, and simmer for another 10 minutes.","Fry the diced or sliced chorizo sausage in a skillet for 2–3 minutes.","Transfer the sausage and rendered fat into the soup, heat for 1 minute, and stir in the fresh dill."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Caldo_verde","page":"Książka kucharska/Caldo verde"},{"id":"oc-plwb-14548","title":"Caramel fish","cuisine":"Other","category":"Main","ingredients":["4 tbsp vegetable oil (2 tbsp for the fish, 2 tbsp for the onion)","400 g fish fillet","1 red onion (small)","1.5 clove garlic","3 tsp dark soy sauce","60 g brown sugar","3 tbsp fish sauce","to taste pepper","1 lime (or lemon, for juice and wedges for serving)"],"steps":["Heat 2 tablespoons of vegetable oil in a skillet, add the fish fillets and fry for a few minutes on one side until lightly browned, then turn and fry for 1 minute.","Remove the fish from the skillet, pour in the remaining 2 tablespoons of oil, add the chopped red onion and minced garlic, and fry for 3 minutes, stirring constantly.","Pour in the dark soy sauce and fish sauce, and add the brown sugar.","Return the fish to the skillet and braise until the sauce thickens to a syrupy consistency.","Season the fish with pepper, drizzle with lime or lemon juice, and serve garnished with citrus wedges."],"time":22,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ryba_w_karmelu","page":"Książka kucharska/Ryba w karmelu"},{"id":"oc-plwb-15840","title":"Carrot and mushroom gratin (Zapiekanka z marchwi)","cuisine":"Other","category":"Side","ingredients":["1 kg carrots","2 tbsp butter","0.5 tbsp sugar","4 tbsp white wine","250 g button mushrooms","150 g firm cheese","100 ml sour cream","to taste parsley leaves (chopped)","to taste salt","to taste black pepper"],"steps":["Peel and wash the carrots, cut into thick batons, then sauté in butter with sugar for about 3 minutes and season with salt and pepper.","Pour the white wine into a saucepan, simmer over low heat for 6 minutes, and stir in half of the sour cream.","Peel the button mushrooms, slice them, and sauté in butter.","Arrange the carrots and mushrooms in a baking dish, pour the wine sauce over them, sprinkle with chopped parsley and finely diced firm cheese, then pour over the remaining sour cream and bake briefly."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_z_marchwi","page":"Książka kucharska/Zapiekanka z marchwi"},{"id":"oc-plwb-61796","title":"Celery and nectarine salad with smoked ham (Sałatka z selera naciowego z nektarynkami)","cuisine":"Other","category":"Salad","ingredients":["400 g celery stalks","5 nectarines (ripe)","50 g wheat sprouts (fresh)","250 g smoked ham (diced)","250 ml whole milk","125 ml apricot juice","1 lemon (juiced)","to taste fresh mint (a few leaves for garnish)","1 pinch cayenne pepper","to taste sea salt"],"steps":["Trim and wash the celery stalks, then slice them thinly into crescents.","Wash the nectarines, cut them in half, discard the stones, and slice into eighths.","Rinse the wheat sprouts under cold water in a sieve, drain thoroughly, and combine in a bowl with the celery, nectarines, and diced smoked ham.","Combine the whole milk, apricot juice, and lemon juice, then season the dressing with sea salt and cayenne pepper.","Pour the dressing over the salad, chill in the refrigerator for 15 minutes, and garnish with fresh mint leaves before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_selera_naciowego_z_nektarynkami","page":"Książka kucharska/Sałatka z selera naciowego z nektarynkami"},{"id":"oc-plwb-18631","title":"Chicken in curry yogurt marinade","cuisine":"Other","category":"Main","ingredients":["2 chicken breast","2 tbsp vegetable oil","250 ml plain yogurt","2 onion","1 clove garlic","2.5 tsp curry powder (2–3 tsp)","to taste salt"],"steps":["Peel and finely dice the onions and garlic, sauté in hot oil, and set aside to cool.","Mix the cooled onion and garlic with the plain yogurt, curry powder, and salt.","Cut the chicken breasts into bite-sized pieces, submerge in the yogurt marinade, and set aside for at least 30 minutes.","Transfer the marinated chicken along with all the marinade into a pot and braise covered over low heat until the meat is tender."],"time":null,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_w_zalewie_jogurtowej","page":"Książka kucharska/Kurczak w zalewie jogurtowej"},{"id":"oc-plwb-17248","title":"Chicken with peas and pineapple in curry cream sauce","cuisine":"Other","category":"Main","ingredients":["4 chicken breast","3 tbsp vegetable oil","1 canned peas (can)","4 slice pineapple","1 tbsp butter","60 ml 30% fat whipping cream","1.5 tbsp curry powder (1–2 tbsp)","to taste salt","to taste pepper"],"steps":["Rinse the chicken breasts, pound lightly with a meat mallet, season with salt and pepper, and fry in hot oil, then drain on paper towels.","Dice the pineapple slices, add to a pan together with the drained peas, add the butter and curry powder, and cook gently for a few moments.","Pour in the whipping cream, stir, return the fried chicken breasts to the pan, and braise together for several minutes.","Season the dish to taste with salt and pepper before serving."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_z_groszkiem_i_ananasem","page":"Książka kucharska/Kurczak z groszkiem i ananasem"},{"id":"oc-plwb-22070","title":"Chicken with pineapple in soy sauce","cuisine":"Other","category":"Main","ingredients":["2 chicken breast fillet","1 canned pineapple with its packing liquid (can)","8 tbsp soy sauce","1 tbsp potato starch","0.5 tsp ground ginger","to taste vegetable oil (for frying)"],"steps":["Rinse and trim the chicken fillets, slice into strips, and fry in hot oil until golden brown.","Add the chopped pineapple, reserving its packing liquid, along with the ginger and soy sauce, and fry, stirring, for 3 minutes.","Mix about 190 ml of the pineapple packing liquid with the potato starch, pour into the pan, and cook, stirring, until the sauce thickens."],"time":null,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_z_ananasem","page":"Książka kucharska/Kurczak z ananasem"},{"id":"oc-plwb-62522","title":"Chleb z czosnkiem (garlic bread)","cuisine":"Other","category":"Bread","ingredients":["1 long wheat baguette (or small loaf of bread)","2 clove garlic","50 g softened butter","1 pinch salt","1 tbsp parsley leaves (optional, chopped or dried herbs)"],"steps":["Preheat the oven to 190 °C.","Peel the garlic, press through a garlic press, and blend in a bowl with the softened butter, salt, and chopped parsley leaves into a smooth paste.","Cut the baguette crosswise into slices, leaving them attached at the base.","Spread the prepared garlic butter into each slit and over the top of the baguette, then wrap tightly in aluminium foil.","Bake in the preheated oven for about 15 minutes at 190 °C until the butter is completely melted, and serve hot right away."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chleb_z_czosnkiem","page":"Książka kucharska/Chleb z czosnkiem"},{"id":"oc-plwb-21322","title":"Chocolate Lava Cakes (Babeczki czekoladowe)","cuisine":"Other","category":"Cake","ingredients":["100 g butter (plus a little for ramekins)","150 g chocolate","4 eggs (4–5 pieces)","200 g sugar","100 g wheat flour (plus a little for ramekins)"],"steps":["Melt the butter and chopped chocolate together in a heatproof bowl set over simmering water and let cool slightly.","Whisk the eggs with sugar, stir into the melted chocolate mixture, fold in the wheat flour, and mix until smooth.","Butter and flour individual ramekins, fill with the batter, and place in the freezer until completely frozen.","Preheat the oven to 245 °C, bake the cakes directly from the freezer without thawing for about 4 minutes."],"time":24,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Babeczki_czekoladowe","page":"Książka kucharska/Babeczki czekoladowe"},{"id":"oc-plwb-20898","title":"Chrupiący kurczak (crispy cornflake chicken)","cuisine":"Other","category":"Main","ingredients":["1 kg chicken","250 ml plain yogurt","1 lemon (zest and juice)","1 onion (grated)","1 tbsp honey","1 tbsp mustard","2 tbsp grated ginger","to taste salt","to taste cayenne pepper","to taste vegetable oil (for frying)","2 eggs","250 ml cornflakes"],"steps":["Rinse the chicken, remove skin, debone, and cut the meat into 10–12 pieces.","Mix the plain yogurt with the lemon zest and juice, grated onion, honey, grated ginger, and mustard, then season with salt and cayenne pepper.","Place the meat pieces into the marinade and refrigerate for 180–240 minutes.","Beat the eggs in a bowl and crush the cornflakes in another dish.","Remove the chicken from the marinade, dip into the egg, dredge in the cornflakes, and fry in hot vegetable oil until golden brown."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chrupi%C4%85cy_kurczak","page":"Książka kucharska/Chrupiący kurczak"},{"id":"oc-plwb-17584","title":"Chutney pomidorowy (sweet and sour spiced tomato chutney)","cuisine":"Other","category":"Preserve","ingredients":["1 kg ripe tomatoes","500 g tart apples","250 g white onion","6 clove garlic","1 fresh ginger (piece)","120 g raisins","2 small hot chili peppers","1 cinnamon bark (small piece)","1 tbsp mustard seeds","1.5 tsp green peppercorns (1–2 tsp)","0.5 tsp salt","300 g brown sugar","375 ml red wine vinegar"],"steps":["Blanch the ripe tomatoes, rinse them with cold water, peel, and dice.","Peel the tart apples, core them, and cut into eighths, then cut the peeled white onion into eighths as well.","Peel and finely mince the garlic and fresh ginger, and slice the small hot chili peppers.","Combine the tomatoes, apples, onion, garlic, ginger, raisins, chili peppers, cinnamon bark, mustard seeds, green peppercorns, salt, and brown sugar in a saucepan.","Pour in about 60 ml of the red wine vinegar and bring the mixture to a boil while stirring.","Simmer gently over low heat for 60–75 minutes, stirring frequently and gradually adding the remaining red wine vinegar.","Ladle the hot chutney into sterilised jars and seal tightly at once."],"time":100,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Chutney_pomidorowy","page":"Książka kucharska/Chutney pomidorowy"},{"id":"oc-plwb-19347","title":"Ciastka serowe (savoury Emmental cheese biscuits)","cuisine":"Other","category":"Cookie","ingredients":["500 g Emmental cheese","2 egg yolks","200 g plain flour","1 tsp baking powder","to taste salt"],"steps":["Grate the Emmental cheese on a fine box grater.","Add the plain flour mixed with baking powder, the egg yolks, and a little salt, then work into a smooth dough.","Roll out the dough to a thickness of about 2 cm and cut out biscuits using a cookie cutter.","Arrange the biscuits on a floured baking sheet and bake for about 15 minutes in an oven preheated to 180 °C."],"time":30,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ciastka_serowe","page":"Książka kucharska/Ciastka serowe"},{"id":"oc-plwb-62938","title":"Cinnamon candied almonds","cuisine":"Other","category":"Snack","ingredients":["250 g whole almonds (whole, skin-on)","200 g white sugar (divided into 150 g and 50 g)","180 ml water (or plant-based milk)","16 g vanillin sugar","4 g ground cinnamon (1 level tsp)"],"steps":["Pour the water into a wide skillet or heavy-bottomed pot, add 150 g of white sugar, vanillin sugar, and ground cinnamon, and stir over medium heat until dissolved and boiling rapidly.","Add the whole almonds to the boiling syrup and cook for about 10 minutes, stirring frequently, until the liquid thickens noticeably.","Reduce the heat and continue cooking for another 5–10 minutes until most of the water evaporates and a thick syrup coats the almonds.","Sprinkle in the remaining 50 g of white sugar and roast for an additional 4–5 minutes, stirring vigorously until a crunchy crystalline crust coats the nuts.","Spread the hot candied almonds onto a sheet of parchment paper, separating them so they do not stick, and allow to cool completely."],"time":30,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Cynamonowe_migda%C5%82y_w_chrupi%C4%85cym_karmelu","page":"Książka kucharska/Cynamonowe migdały w chrupiącym karmelu"},{"id":"oc-plwb-19650","title":"Citrus marmalade","cuisine":"Other","category":"Preserve","ingredients":["1 kg citrus fruit pulp","2 citrus peel (thickly pared from 2 whole fruits)","1 kg gelling sugar"],"steps":["Peel the citrus fruits, remove the white membrane from the pulp, and chop finely.","Wash two whole citrus fruits thoroughly, thickly pare the peel, and slice into thin strips.","Combine the citrus pulp, sliced peel, and gelling sugar, and let stand for about 12 hours.","Bring the mixture to a boil while stirring constantly, and cook for several minutes until the proper gelling point is reached.","Ladle the hot marmalade into sterilized jars, seal immediately and tightly, and invert the jars several times while cooling to distribute the peel evenly."],"time":45,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Marmolada","page":"Książka kucharska/Marmolada"},{"id":"oc-plwb-56812","title":"Coconut ice cream","cuisine":"Other","category":"Dessert","ingredients":["400 ml coconut milk","400 ml Greek yogurt","4 tbsp agave syrup","4 tbsp cane sugar"],"steps":["Pour 400 ml of coconut milk and 400 ml of Greek yogurt into a bowl and mix.","Gradually add the agave syrup and cane sugar, mixing thoroughly.","Place the mixture in the freezer for 1–2 hours or until the desired consistency is reached, taking it out halfway through freezing to stir."],"time":10,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lody_kokosowe","page":"Książka kucharska/Lody kokosowe"},{"id":"oc-plwb-55051","title":"Coconut water lemonade","cuisine":"Other","category":"Drink","ingredients":["1 coconut (coconut water from inside)","2 lime","2 red grapefruit","3 tbsp agave syrup","0.5 melon","to taste ice cubes","to taste fresh mint (leaves)"],"steps":["Crack the top of the coconut and pour out the coconut water. Peel half of the melon and dice into cubes.","Squeeze the juice from the limes and red grapefruits.","Place the ice cubes into a blender, pour in the coconut water, squeezed citrus juice, and agave syrup, add half of the diced melon, and blend.","Pour the lemonade into tumblers and garnish with the remaining melon pieces and fresh mint leaves."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_z_wod%C4%85_kokosow%C4%85","page":"Książka kucharska/Lemoniada z wodą kokosową"},{"id":"oc-plwb-16857","title":"Cod in spicy tomato sauce","cuisine":"Other","category":"Main","ingredients":["600 g skinless cod fillets (skinless)","2 onion (medium)","5 tomatoes (ripe)","1 tbsp vinegar","5 tbsp olive oil","2 red chili peppers","to taste salt","to taste black pepper"],"steps":["Blanch the tomatoes in boiling water, peel and dice them, and finely chop the peeled onion and seeded red chili peppers.","Heat the olive oil in a large saucepan and cook the chopped onion until translucent.","Add the diced tomatoes, chili peppers, and vinegar, season with salt and pepper, then cover and simmer for about 20 minutes.","Rinse and pat dry the cod fillets, nestle them into the sauce in the pan, cover, and simmer for another 15 minutes."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Dorsz_w_pikantnym_sosie_czerwonym","page":"Książka kucharska/Dorsz w pikantnym sosie czerwonym"},{"id":"oc-plwb-15033","title":"Cold green bean salad with tomato and olives","cuisine":"Other","category":"Salad","ingredients":["500 g green beans","1 onion","1 tomato","1 clove garlic","0.5 lemon (juice)","8 black olives (a few olives)","1 pinch rosemary","1 pinch oregano","3 tbsp olive oil (for frying and dressing)","to taste salt","to taste sugar","to taste parsley leaves (chopped)"],"steps":["Boil the green beans in salted water for about 15 minutes, drain, and allow to cool.","Peel and chop the onion, fry it in some of the olive oil, and place it over the beans.","Wash the tomato, cut into quarters, briefly sauté in the pan, arrange over the beans, and scatter with the black olives.","Peel the garlic, crush with salt and sugar, then mix with the juice squeezed from half a lemon, the remaining olive oil, rosemary, and oregano.","Drizzle the dressing over the beans and garnish with chopped parsley leaves."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Fasolka_szparagowa_na_zimno","page":"Książka kucharska/Fasolka szparagowa na zimno"},{"id":"oc-plwb-14307","title":"Corn-stuffed tomato and cucumber cups (Warzywne miseczki)","cuisine":"Other","category":"Salad","ingredients":["4 tomatoes","1 cucumber (large)","2 corn on the cob","1 clove garlic","1 tbsp fresh parsley (chopped)","1 tbsp vegetable oil","1 tsp lemon juice","1 tbsp sugar (for cooking the corn)","to taste salt","to taste white pepper"],"steps":["Remove the silks and husks from the ears of corn, place them into boiling water with a tablespoon of sugar, and cook until tender for 20–25 minutes.","Slice the tops off the tomatoes, trim the ends of the cucumber, and cut it into large chunks.","Hollow out the pulp from the tomatoes and cucumber chunks, leaving the bottoms intact to create cups, and dice the scooped-out flesh.","Cut the cooked corn kernels from the cobs and mix them with the diced vegetable pulp and chopped fresh parsley.","Mash the minced garlic with the oil, salt, white pepper, and lemon juice, combine with the corn mixture, and spoon the filling into the hollowed-out vegetables."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Warzywne_miseczki","page":"Książka kucharska/Warzywne miseczki"},{"id":"oc-plwb-24438","title":"Couscous with eggplant and tomatoes","cuisine":"Other","category":"Main","ingredients":["250 ml couscous","1 eggplant","to taste parsley","400 g canned chopped tomatoes","1 onion (medium)","3 tbsp olive oil (2–3 tbsp plus extra for drizzling over eggplant)","to taste salt","to taste sweet ground paprika or poultry seasoning","to taste boiling water (for steeping couscous)"],"steps":["Slice the eggplant, sprinkle with salt, leave for fifteen to twenty minutes, then pat dry with paper towels.","Cut the onion in half and slice thinly. Heat 2–3 tablespoons of olive oil in a pan and sauté the onion.","Add the eggplant slices, drizzle generously with olive oil, dust with sweet paprika or seasoning, and fry for about 10 minutes.","Pour the canned chopped tomatoes into the pan and braise everything for another 5 minutes.","Meanwhile, place the couscous in a bowl, pour over boiling water, cover, and let stand for 5 minutes to swell.","Fluff the couscous, combine with the braised vegetables, and sprinkle with chopped parsley leaves before serving."],"time":40,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kuskus_z_bak%C5%82a%C5%BCanem","page":"Książka kucharska/Kuskus z bakłażanem"},{"id":"oc-plwb-8319","title":"Couscous with vegetables","cuisine":"Other","category":"Main","ingredients":["2 carrots","1 parsley root with greens","1 leek","1 onion (medium)","2.5 tbsp couscous (2–3 tbsp)","to taste salt","to taste pepper","to taste water (for cooking)"],"steps":["Peel and rinse the vegetables: slice the carrots, parsley root, and leek into rounds or matchsticks, slice the onion into thin strips, and chop the parsley leaves.","Transfer the vegetables to a pot, pour in enough water to just barely cover them, season with salt and pepper, and simmer until tender, topping up with water if needed.","Towards the end of cooking, stir in the couscous and simmer over low heat for 3–6 minutes, stirring occasionally.","Cover the pot and set aside briefly until the couscous swells, then serve in bowls scattered with chopped parsley leaves."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kuskus_z_warzywami","page":"Książka kucharska/Kuskus z warzywami"},{"id":"oc-plwb-14455","title":"Crispy homemade waffles","cuisine":"Other","category":"Dessert","ingredients":["200 g margarine","100 g sugar","16 g vanilla sugar","3 eggs","400 g plain flour","0.5 tsp baking powder","375 ml milk"],"steps":["Melt the margarine and allow it to cool.","Separate the egg yolks from the whites, then beat the yolks with the sugar and vanilla sugar until fluffy.","Pour the cooled melted margarine into the beaten yolks and mix thoroughly.","Mix the flour with the baking powder and add it gradually to the batter alternately with the milk.","Whip the egg whites until stiff peaks form and gently fold them into the batter.","Bake portions of batter in a preheated waffle maker until golden and crisp."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gofry","page":"Książka kucharska/Gofry"},{"id":"oc-plwb-18628","title":"Crystal strawberry sorbet","cuisine":"Other","category":"Dessert","ingredients":["150 g strawberries","4 tbsp sour cherry juice","2 tbsp sugar","4 tbsp crushed ice","to taste lemon balm leaves (for garnish)"],"steps":["Rinse, dry, and hull the strawberries, then arrange them on a tray and place in the freezer for about 30 minutes.","Transfer the semi-frozen strawberries to a blender, add the sour cherry juice, sugar, and crushed ice, and blend.","Return the mixture to the freezer for 30 minutes, then blend again upon removing.","Spoon the sorbet into dessert cups and garnish with lemon balm leaves."],"time":70,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sorbet_kryszta%C5%82owy","page":"Książka kucharska/Sorbet kryształowy"},{"id":"oc-plwb-1431","title":"Curry spaghetti (makaron z curry)","cuisine":"Other","category":"Main","ingredients":["400 g spaghetti pasta","125 ml whipping cream (30% fat)","4 tbsp Parmesan cheese (grated)","1 tsp curry powder","1 tbsp butter"],"steps":["Cook the spaghetti pasta al dente and drain.","Whisk the whipping cream with the grated Parmesan and curry powder, then gently warm the sauce in a saucepan.","Toss the hot spaghetti with the butter and pour over the prepared curry sauce."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_curry","page":"Książka kucharska/Makaron z curry"},{"id":"oc-plwb-18502","title":"Date and fig muffins","cuisine":"Other","category":"Cake","ingredients":["300 g wheat flour","2 egg","3 tbsp sugar (heaped, for the batter)","10 dried figs","15 dried dates (pitted)","100 g butter (plus extra for the tin)","190 ml milk","1 tsp baking powder (level teaspoon)","1 tsp vanilla sugar","1 pinch salt","1 tbsp sugar (for sprinkling)"],"steps":["Finely chop the dried figs and dried dates, and preheat the oven to 210 °C.","Melt the butter and let it cool, and whisk the eggs with the milk.","Sift the wheat flour into a bowl and mix with the chopped fruit, 3 tablespoons of sugar, the vanilla sugar, baking powder, and salt.","Pour the egg and milk mixture along with the melted butter into the dry ingredients and stir into a uniform batter.","Spoon the batter into a buttered or paper-lined muffin tin to 3/4 of its height, sprinkle with the remaining tablespoon of sugar, and bake for about 25 minutes at 210 °C, then let cool."],"time":40,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Muffiny_z_daktylami_i_figami","page":"Książka kucharska/Muffiny z daktylami i figami"},{"id":"oc-plwb-5278","title":"Egg salad with herb dressing (Sałatka z jajek w sosie ziołowym)","cuisine":"Other","category":"Salad","ingredients":["4 eggs (hard-boiled)","8 lettuce (large leaves)","4 tomatoes (small)","8 slice cucumber (peeled)","1 carrot (finely grated)","1 avocado (ripe, peeled, and quartered)","1 pinch ground paprika","100 g plain yogurt (sheep's or cow's milk)","2.5 tsp fresh herbs (finely chopped (such as parsley, mint, chives))","1 tsp balsamic vinegar","1 pinch salt","to taste black pepper (freshly ground)"],"steps":["Cut the hard-boiled eggs in half lengthwise.","Gently toss together the lettuce leaves, sliced tomatoes, cucumber slices, grated carrot, and avocado quarters.","Divide the vegetable mixture between two plates and arrange the egg halves on top.","Combine the plain yogurt, chopped herbs, balsamic vinegar, salt, and pepper in a small jar or blender, then shake vigorously or blend until smooth.","Drizzle the salad with the yogurt-herb dressing and dust with a pinch of ground paprika."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_jajek_w_sosie_zio%C5%82owym","page":"Książka kucharska/Sałatka z jajek w sosie ziołowym"},{"id":"oc-plwb-61785","title":"Farfalle salad with chanterelles and Parma ham (Sałatka z makaronem i kurkami)","cuisine":"Other","category":"Salad","ingredients":["200 g farfalle pasta","150 g chanterelles (fresh)","3 fresh tarragon (sprigs)","0.5 bunch garden chervil","200 g crème fraîche","4 tbsp red wine","to taste sea salt","to taste black pepper (ground)","2 shallots","1 bunch scallions","150 g Parma ham (thinly sliced (or smoked ham))","1 tbsp olive oil"],"steps":["Rinse, pat dry, and finely chop the fresh tarragon and garden chervil.","Whisk the crème fraîche with the red wine, season with sea salt and black pepper, stir in the chopped fresh herbs, and chill in the refrigerator for about 60 minutes.","Cook the farfalle pasta in salted boiling water for about 9 minutes until al dente, then drain and let cool.","Clean, rinse, and dry the chanterelles, peel and finely chop the shallots, slice the scallions into thin rounds, and cut the Parma ham into narrow strips.","Heat the olive oil in a skillet, cook the shallots briefly until translucent, add the chanterelles, and fry until tender, then let cool.","In a salad bowl, combine the pasta, cooled mushrooms and shallots, ham, and scallions, pour over the chilled dressing, and let stand for 60 minutes before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_makaronem_i_kurkami","page":"Książka kucharska/Sałatka z makaronem i kurkami"},{"id":"oc-plwb-21429","title":"Fava bean purée","cuisine":"Other","category":"Side","ingredients":["500 g fava beans (shelled and peeled)","1 tsp fresh thyme (a few leaves)","4 tbsp olive oil","to taste salt","to taste pepper"],"steps":["Rinse the fava beans and peel the skins from the beans.","Blend the peeled fava beans with thyme leaves and olive oil into a smooth purée, seasoning to taste with salt and pepper."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pur%C3%A9e_z_bobu","page":"Książka kucharska/Purée z bobu"},{"id":"oc-plwb-61832","title":"Fennel and Corinthian currant salad (Sałatka z kopru włoskiego z rodzynkami korynckimi)","cuisine":"Other","category":"Salad","ingredients":["3 fennel bulbs (medium)","8 tomatoes (ripe)","2 radicchio (small heads)","150 g Corinthian currants","100 g blanched almonds (halved)","200 g crème fraîche","1 bunch fresh dill","8 tbsp white wine vinegar","to taste sea salt","to taste black pepper (freshly ground)"],"steps":["Pour hot water over the Corinthian currants, let soak for 15 minutes, then drain.","Trim, wash, and dry the fennel bulbs, reserving the feathery fronds for garnish; slice the bulbs into thin strips and marinate for 15 minutes in white wine vinegar seasoned with salt and pepper.","Scald the tomatoes with boiling water, peel off the skins, discard the seeds, and cut the flesh into eighths.","Toast the almond halves for about 5 minutes in an oven preheated to 250 °C.","Wash, dry, and finely chop the dill (reserving a sprig for garnish), then mix with the crème fraîche, drained currants, marinated fennel, and 3/4 of the tomatoes.","Arrange the washed and dried radicchio leaves on serving plates, mound the fennel salad onto them, and garnish with the toasted almonds, remaining tomatoes, and fresh dill."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_kopru_w%C5%82oskiego_z_rodzynkami_korynckimi","page":"Książka kucharska/Sałatka z kopru włoskiego z rodzynkami korynckimi"},{"id":"oc-plwb-62943","title":"Fettuccine with chicken and curry","cuisine":"Other","category":"Main","ingredients":["600 g chicken breast (cut into 2 cm cubes)","1 tbsp curry powder","1 tbsp sweet paprika","0.5 tsp ground turmeric","1 tbsp wheat flour (for dusting during frying)","2 tbsp vegetable oil","250 g fettuccine pasta (or pappardelle)","200 ml whipping cream 30%","200 ml pasta cooking water","70 g sun-dried tomatoes in oil (chopped)","3 clove garlic (pressed through a garlic press)","10 g fresh ginger (finely grated)","20 g clarified butter (for frying)","0.5 tsp salt"],"steps":["Toss the diced chicken in a bowl with the vegetable oil, curry powder, sweet paprika, and turmeric, then set aside for at least 15 minutes to marinate.","Cook the pasta al dente in salted water, reserving 200 ml of the cooking water before draining.","Heat the clarified butter in a large skillet, add the chicken, dust with 1 tablespoon of wheat flour, and fry over medium heat for 10–12 minutes until golden and cooked through.","Pour 200 ml of 30% whipping cream and 200 ml of the reserved pasta water into the skillet with the chicken, add the chopped sun-dried tomatoes, pressed garlic, grated ginger, and salt.","Simmer over low heat for 2–3 minutes until the sauce thickens slightly, then toss in the cooked pasta, mix thoroughly, and serve immediately."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_fettuccine_z_kurczakiem_i_curry","page":"Książka kucharska/Makaron fettuccine z kurczakiem i curry"},{"id":"oc-plwb-16689","title":"Fresh strawberry and citrus salad (Sałatka z truskawkami)","cuisine":"Other","category":"Salad","ingredients":["300 g strawberries","2 oranges","2 bananas","3 kiwis","1 lemon (scalded, 4 slices and zest for garnish, juice for dressing)","5 tbsp orange juice","5 tbsp orange liqueur","2 tbsp honey","1 fresh ginger (small piece, peeled and grated)","to taste lemon balm (leaves for garnish)"],"steps":["Wash and hull the strawberries, peel the kiwis and bananas, and slice the fruit.","Peel the oranges, slice them into half-rounds, and divide all the fruit among four salad bowls.","Scald the lemon, cut off 4 thin slices for garnish, pare thin strips of zest from the rest, and squeeze the juice from the pulp.","Whisk the lemon juice with the orange juice, orange liqueur, honey, and finely grated ginger.","Drizzle the fruit in the bowls with the prepared dressing and garnish with lemon slices, zest strips, and lemon balm leaves."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_truskawkami","page":"Książka kucharska/Sałatka z truskawkami"},{"id":"oc-plwb-17473","title":"Frykadele w sosie (meatballs in sauce)","cuisine":"Other","category":"Main","ingredients":["500 g minced meat","1 onion","1 egg","1 white bread roll (soaked and squeezed dry)","4 tbsp cooking oil","3 clove garlic","to taste salt","to taste black pepper"],"steps":["Soak the bread roll, squeeze it out, and combine it with the ground meat.","Add the finely chopped onion, egg, and pressed garlic, then season with salt and pepper.","Knead the meat mixture thoroughly and shape it into small balls.","Heat the oil in a frying pan and fry the meatballs on all sides until golden brown."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Frykadele_w_sosie","page":"Książka kucharska/Frykadele w sosie"},{"id":"oc-plwb-61665","title":"Garlic and potato cream soup (Zupa czosnkowa)","cuisine":"Other","category":"Soup","ingredients":["2 garlic (heads)","1 kg potatoes","1 l vegetable or poultry broth","2 onions (small)","250 g mascarpone cheese (1 tub (alternatively grated firm cheese with cream, or processed cheese))","2 tbsp clarified butter","2 tbsp olive oil","0.5 tsp salt (level)","0.5 tsp black pepper (level)","0.25 tsp caraway (level)","0.25 tsp thyme (level)"],"steps":["Cook the sliced onion in a pot in clarified butter and olive oil until translucent, about 10 minutes.","Pour in the broth, add the peeled and diced potatoes, and simmer covered for 15 minutes.","Add the peeled cloves from both heads of garlic to the pot and simmer covered for another 10 minutes.","Add the mascarpone (or grated firm cheese with cream, or processed cheese), along with salt, pepper, caraway, and thyme.","Cook the soup uncovered for the final 5 minutes, then blend until smooth and serve with croutons or crispy fried onions."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_czosnkowa","page":"Książka kucharska/Zupa czosnkowa"},{"id":"oc-plwb-16777","title":"Garlic braised chicken","cuisine":"Other","category":"Main","ingredients":["1 whole chicken","2 garlic (heads)","2 onion","125 ml broth","50 ml white wine","4 tbsp vegetable oil","2 tbsp lemon juice","to taste fresh herbs","to taste salt","to taste pepper"],"steps":["Rinse and pat dry the chicken, sprinkle with lemon juice, rub with salt and pepper, chill for 2 hours, then joint into portions.","Peel the onions and slice into thin crescents. Separate the garlic heads into cloves and peel them.","Heat the oil in a braising pan and brown the chicken portions on all sides.","Add the onion, whole peeled garlic cloves, and a portion of the herbs, pour in the broth, and braise gently over low heat for about 50 minutes.","Remove the softened garlic cloves and herbs from the pan, pour in the white wine, and simmer for a few minutes more. Scatter fresh herbs over the dish before serving."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_czosnkowy","page":"Książka kucharska/Kurczak czosnkowy"},{"id":"oc-plwb-6265","title":"Garlic bread sauce","cuisine":"Other","category":"Sauce","ingredients":["10 clove garlic","2 slice white sandwich bread","190 ml milk","2 parsley (sprigs)","to taste nutmeg","to taste salt","to taste pepper","to taste water (for parboiling the garlic)"],"steps":["Bring water to a boil in a small pot, drop in the peeled garlic cloves, parboil for 3 minutes, then drain and crush.","Remove the crusts and cut out the soft crumb from the bread slices.","Warm the milk, then add the crushed garlic, bread crumb, and parsley sprigs.","Simmer the sauce gently for about 15 minutes, seasoning along the way with nutmeg, salt, and pepper while mashing the ingredients with a wooden spoon until smooth."],"time":18,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krem_czosnkowy","page":"Książka kucharska/Krem czosnkowy"},{"id":"oc-plwb-18789","title":"Golden balls (Złote kule)","cuisine":"Other","category":"Salad","ingredients":["2 oranges","2 apples","2 tbsp lemon juice","4 tbsp grated horseradish","to taste sugar","to taste salt","to taste black pepper"],"steps":["Scrub the oranges, scald with boiling water, dry, cut in half, and carefully scoop out the pulp.","Peel the apples, core them, grate finely on a box grater, and immediately drizzle with lemon juice.","Finely chop the orange pulp, combine it with the grated apples and grated horseradish, and season with sugar, salt, and pepper.","Mix the salad thoroughly, chill in the refrigerator, and fill the hollowed orange halves before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Z%C5%82ote_kule","page":"Książka kucharska/Złote kule"},{"id":"oc-plwb-55052","title":"Grapefruit lemonade","cuisine":"Other","category":"Drink","ingredients":["1 tsp cardamom seeds","200 g sugar","200 ml water (for the syrup)","4 pink grapefruit","2 lime","2 lemongrass (stalks)","600 ml sparkling water","to taste ice cubes","to taste fresh basil (leaves)"],"steps":["Crush the cardamom seeds in a mortar, bring to a boil with 200 g of sugar and 200 ml of water, simmer over low heat for 3 minutes, then cool and strain through a sieve.","Squeeze the juice from 3 grapefruits and 2 limes and combine with the cardamom syrup.","Trim the lemongrass, cut into large pieces, add to the citrus base, and refrigerate for at least 2 hours.","Peel the remaining grapefruit, slice into thin rounds, and distribute into tumblers together with ice cubes and fresh basil leaves.","Remove the lemongrass, pour the lemonade base into tumblers, and top up with 600 ml of chilled sparkling water."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_grejpfrutowa","page":"Książka kucharska/Lemoniada grejpfrutowa"},{"id":"oc-plwb-14615","title":"Green bean and cranberry salad","cuisine":"Other","category":"Salad","ingredients":["150 g green beans (frozen)","2 tsp olive oil","1 tsp wine vinegar","0.5 red onion","30 g cranberries","to taste salt","to taste black pepper"],"steps":["Cook the green beans in salted boiling water for about 3 minutes, then drain and cool.","Peel the red onion and slice it into thin feathers.","Toss the cooled green beans, red onion, and cranberries with the olive oil and wine vinegar, then season to taste with salt and pepper."],"time":13,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Czerwona_sa%C5%82atka_z_%C5%BCurawin%C4%85","page":"Książka kucharska/Czerwona sałatka z żurawiną"},{"id":"oc-plwb-18705","title":"Green island salad (Zielona sałatka z wysp)","cuisine":"Other","category":"Salad","ingredients":["2 cucumbers","2 yellow zucchini","1 arugula (head or bunch)","1 lemon (grated zest and freshly squeezed juice)","5 tbsp plain yogurt","3 fresh mint (sprigs)","to taste salt","to taste black pepper"],"steps":["Tear the arugula into smaller pieces, salt lightly, and let stand for a few minutes.","Peel the zucchini and cucumbers, dice them, toss with arugula, and season with salt and pepper.","Whisk the plain yogurt with the lemon zest and squeezed lemon juice, then pour the dressing over the salad.","Sprinkle with chopped fresh mint leaves and serve as a side dish for meat."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zielona_sa%C5%82atka_z_wysp","page":"Książka kucharska/Zielona sałatka z wysp"},{"id":"oc-plwb-16560","title":"Green onion soup (Zielona zupa cebulowa)","cuisine":"Other","category":"Soup","ingredients":["4 spring onions with greens","2 onions","1 leek (small)","100 g blue cheese (preferably Rokpol type)","2 bouillon cube (cubes)","1 l boiling water (for pouring over vegetables)","3 tbsp vegetable oil","1 pinch hot paprika powder (for sprinkling)","1 pinch salt","to taste black pepper (freshly ground)"],"steps":["Finely chop 3 spring onions, leek, and yellow onions, and chop the fourth spring onion separately for serving.","Heat the oil in a saucepan, add the chopped vegetables, and fry until golden, stirring constantly.","Pour a liter of boiling water over the vegetables, add the bouillon cubes, and bring to a boil.","Season the soup with freshly ground pepper and a pinch of salt, and simmer covered for about 10 minutes.","Dice the blue cheese into small cubes, divide among plates, ladle the hot soup over, and garnish with the reserved chopped spring onion and a pinch of hot paprika."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zielona_zupa_cebulowa","page":"Książka kucharska/Zielona zupa cebulowa"},{"id":"oc-plwb-14948","title":"Grilled beef steaks (Steki wołowe z rusztu)","cuisine":"Other","category":"Main","ingredients":["4 bone-in beef steaks","4 clove garlic","3 fresh thyme (sprigs)","3 fresh oregano (sprigs)","3 fresh basil (sprigs)","2 tbsp wine vinegar","250 ml vegetable oil","2 tbsp mustard","1 tsp dried marjoram","to taste pepper","to taste salt"],"steps":["Peel the garlic and press through a garlic press, and finely chop the fresh thyme, oregano, and basil.","Mix the garlic and fresh herbs with the wine vinegar, oil, mustard, dried marjoram, and pepper.","Coat the beef steaks in the marinade and refrigerate overnight (about 480 minutes).","Remove the steaks from the marinade, drain, grill on both sides on a hot grate, and sprinkle with salt after grilling."],"time":507,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Steki_wo%C5%82owe_z_rusztu","page":"Książka kucharska/Steki wołowe z rusztu"},{"id":"oc-plwb-21304","title":"Grilled salmon on asparagus with citrus salsa","cuisine":"Other","category":"Main","ingredients":["800 g salmon fillet (raw)","16 green asparagus","12 white asparagus","2 l water (for cooking asparagus)","1 orange","1 grapefruit","1 kiwi","1 lime","100 ml olive oil","50 ml white balsamic vinegar","5 fresh mint (leaves)","1 tsp pickled ginger (chopped)","1 pinch sugar (for cooking asparagus)","to taste salt","to taste black pepper (freshly ground)"],"steps":["Clean the salmon fillet, divide into four equal portions, season with salt and pepper, drizzle with part of the lime juice and olive oil, and grill.","Trim and peel the asparagus, and cook green and white separately in boiling water with a pinch of salt and sugar until tender.","Cut away the peel and white pith from the orange and grapefruit, segment the citrus and chop finely, and finely dice the peeled kiwi.","Combine the chopped fruit with the minced pickled ginger, remaining olive oil, balsamic vinegar, chopped mint, and lime juice, then season with salt and pepper.","Arrange the cooked asparagus spears on plates, top with the grilled salmon, and spoon the fruit salsa over top."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Grillowany_%C5%82oso%C5%9B_na_szparagach","page":"Książka kucharska/Grillowany łosoś na szparagach"},{"id":"oc-plwb-21428","title":"Grilled sesame salmon with horseradish sauce","cuisine":"Other","category":"Main","ingredients":["4 skin-on salmon fillets","4 tsp olive oil","1 tbsp sesame seeds (seeds)","2 tbsp mayonnaise","2 tbsp plain yogurt","1 tbsp grated horseradish","to taste salt"],"steps":["Clean the salmon fillets, place skin-side down on a hot grill, season with salt, drizzle with olive oil, and sprinkle with sesame seeds.","Grill the fish for about 12 minutes.","Combine the mayonnaise with plain yogurt, and season with grated horseradish and salt.","Serve the grilled salmon with the prepared horseradish sauce."],"time":22,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Grillowany_%C5%82oso%C5%9B_w_sezamie_z_sosem_chrzanowym","page":"Książka kucharska/Grillowany łosoś w sezamie z sosem chrzanowym"},{"id":"oc-plwb-56114","title":"Gyuvech (Bulgarian pork and vegetable bake)","cuisine":"Other","category":"Main","ingredients":["120 ml olive oil","650 g pork (600–700 g)","5 potatoes (4–6 potatoes)","300 g fresh sweet bell peppers","375 g tomatoes (350–400 g)","125 g okra (100–150 g)","1 onion","1 tsp sweet paprika","3 hot chili peppers (3–4 peppers)","to taste parsley leaves (chopped)","to taste salt"],"steps":["Pour the olive oil into a clay or ovenproof baking dish, add the cubed and salted pork, and roast for about 20 minutes in an oven preheated to 180 °C.","Chop the potatoes, fresh bell peppers, tomatoes, okra, and onion into bite-sized chunks.","Add the vegetables to the partially roasted meat, season with salt, dust with the sweet paprika, and continue baking for about 45 minutes until the meat and vegetables are tender.","Garnish with the chopped parsley leaves and sliced hot chili peppers before serving."],"time":90,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Giuwecz","page":"Książka kucharska/Giuwecz"},{"id":"oc-plwb-26015","title":"Hachee (Dutch beef and onion stew)","cuisine":"Other","category":"Main","ingredients":["500 g beef stew meat","700 g onions (3 large onions)","5 cloves","2 bay leaves","30 g butter","2 tbsp plain flour (for coating meat)","250 ml beef broth (from 1 bouillon cube dissolved in 250 ml warm water)","1 tbsp wine vinegar (dash)","330 ml dark beer","to taste salt","to taste black pepper (freshly ground)"],"steps":["Cut the beef into large cubes and dredge in flour seasoned with salt and pepper.","Peel the onions and slice into thick chunks or rings.","Melt the butter in a heavy-bottomed pot and brown the meat on all sides.","Add the sliced onions, bay leaves, and cloves, and cook while stirring until the onion becomes translucent.","Pour in the warm beef broth, dark beer, and wine vinegar so the liquid covers the meat, and bring to a boil.","Reduce the heat to low and braise with the lid slightly ajar for 3 hours, stirring regularly until the meat is meltingly tender and the sauce is thick, then remove the bay leaves and cloves and season to taste."],"time":205,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gulasz_holenderski","page":"Książka kucharska/Gulasz holenderski"},{"id":"oc-plwb-61833","title":"Halibut and roasted pepper salad with saffron dressing (Sałatka z pieczoną papryką i halibutem)","cuisine":"Other","category":"Salad","ingredients":["400 g halibut fillets","1 radicchio (medium head)","1 oak leaf lettuce (small head)","3 bell peppers (1 green, 1 red, and 1 yellow)","1 onion (small)","2 clove garlic","150 g crème fraîche","100 ml white wine vinegar","8 tbsp olive oil","1 pinch saffron","50 g pine nuts","1 bunch fresh parsley","to taste sea salt","to taste cayenne pepper","to taste black pepper (freshly ground)"],"steps":["Wash and dry the radicchio and oak leaf lettuce leaves, removing any tough ribs.","Wash the bell peppers, remove the seeds, and slice into strips, then slice the peeled onion and garlic thinly.","Toast the pine nuts in a dry skillet until golden.","Rinse and pat dry the halibut fillets, slice them into 1.5 cm thick pieces, and arrange in an oiled baking dish.","Bring the white wine vinegar to a boil with a splash of water, remaining olive oil, sea salt, cayenne pepper, black pepper, sliced onion, garlic, and pepper strips, pour the hot marinade over the fish, and let stand for 60 minutes.","Dissolve the saffron in 1 tbsp of the marinade liquid, whisk into the crème fraîche, and season with salt and pepper.","Arrange the salad leaves on plates, place the marinated halibut and drained vegetables on top, drizzle with the saffron dressing, and scatter with pine nuts and fresh parsley leaves."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_pieczon%C4%85_papryk%C4%85_i_halibutem","page":"Książka kucharska/Sałatka z pieczoną papryką i halibutem"},{"id":"oc-plwb-26094","title":"Haupia (Hawaiian coconut pudding)","cuisine":"Other","category":"Dessert","ingredients":["750 ml coconut milk","100 g sugar","1 pinch salt","65 g cornstarch"],"steps":["Combine the coconut milk, sugar, and a pinch of salt in a pot and warm over medium heat.","Gradually stir in the cornstarch, whisking constantly, and cook until the pudding thickens.","Pour the hot coconut mixture into a square baking dish.","Chill in the refrigerator for at least 60 minutes, then cut into neat squares and serve."],"time":75,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Haupia","page":"Książka kucharska/Haupia"},{"id":"oc-plwb-55053","title":"Herbal lemonade","cuisine":"Other","category":"Drink","ingredients":["1.5 l sparkling water (1.2–1.8 l)","5 lemon (preferably unwaxed)","300 g sugar","100 ml water (for the syrup)","0.5 bunch fresh mint (from 0.5 pot)","6 fresh thyme (sprigs)","3.5 fresh basil (3–4 stalks)","3.5 fresh lemon balm (3–4 stalks)","1 fresh rosemary (stalk)","1 fresh sage (stalk)"],"steps":["Scald 2 lemons with boiling water, wipe dry, and pare the zest very thinly. Squeeze the juice from all 5 lemons, measuring out 300 ml of juice.","Combine 300 ml of lemon juice with 300 g of sugar and 100 ml of water, bring to a boil, boil over high heat for 3 minutes, then let cool.","Wash and dry the mint, thyme, basil, lemon balm, rosemary, and sage, add together with the lemon zest to the lukewarm syrup, and set aside for 2–3 hours.","Strain the base through a sieve into a pitcher or bottles and top up with 1.5 l of chilled sparkling water."],"time":20,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_zio%C5%82owa","page":"Książka kucharska/Lemoniada ziołowa"},{"id":"oc-plwb-55057","title":"Honey lemonade","cuisine":"Other","category":"Drink","ingredients":["1.5 l sparkling water","1.5 lemon","5 tbsp honey","to taste fresh mint (several leaves)","to taste ice cubes"],"steps":["Squeeze the juice from one and a half lemons.","Sweeten 1.5 l of sparkling water with honey and stir until dissolved.","Pour in the squeezed lemon juice, add ice and fresh mint leaves, and stir."],"time":5,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_miodowa","page":"Książka kucharska/Lemoniada miodowa"},{"id":"oc-plwb-19352","title":"Jagoda świętych (Pistachio-crusted grape and quark truffles)","cuisine":"Other","category":"Snack","ingredients":["250 g grapes","200 g smooth full-fat quark (thick)","200 g pistachios (shelled)","to taste salt"],"steps":["Rinse and thoroughly dry the grapes, and blend the quark with a pinch of salt until smooth.","Take small portions of quark and coat each individual grape evenly.","Arrange the shaped balls on a tray and refrigerate for 30 minutes.","Crush the pistachios in a mortar or chop finely, roll the chilled cheese balls in them to coat, and serve."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jagoda_%C5%9Bwi%C4%99tych","page":"Książka kucharska/Jagoda świętych"},{"id":"oc-plwb-19523","title":"Jajka po żmudzku (Samogitian egg salad in shells)","cuisine":"Other","category":"Snack","ingredients":["6 eggs","1 onion (large)","3.5 tbsp mayonnaise (3–4 tablespoons thick mayonnaise)","2 tbsp parsley leaves (chopped)","to taste salt","to taste black pepper"],"steps":["Peel the large onion and chop it finely.","Hard-boil the eggs, let them cool, cut them in half lengthwise through the shell, scoop out the contents, and chop finely.","Mix the chopped eggs with the onion, mayonnaise, and parsley leaves, and season with salt and black pepper.","Spoon the egg salad back into the shell halves and arrange on a plate."],"time":25,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_po_%C5%BCmudzku","page":"Książka kucharska/Jajka po żmudzku"},{"id":"oc-plwb-13770","title":"Jajka w mięsie (Scotch eggs with sweetcorn and parmesan)","cuisine":"Other","category":"Main","ingredients":["500 g minced meat","5 eggs (4 hard-boiled, 1 raw)","3 tbsp canned sweetcorn (a few tablespoons)","50 g grated parmesan","1 stale bread roll","1 onion (small)","2.5 clove garlic (2–3 cloves)","to taste oil (for deep frying)","to taste herbs (of your choice)","to taste salt","to taste black pepper"],"steps":["Hard-boil 4 eggs, let them cool, and peel them.","Combine the minced meat with the remaining raw egg, canned sweetcorn, grated onion, grated parmesan, and the stale roll soaked and squeezed dry.","Season the meat mixture with herbs, salt, pepper, and minced garlic, knead until smooth, divide into 4 portions, and flatten into thin patties.","Place a peeled hard-boiled egg in the center of each patty and wrap the meat around the egg to form smooth balls.","Fry the meat-wrapped eggs in deep hot oil for about 15 minutes.","Remove the fried meat eggs, drain on paper towels, and cut into portions."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajka_w_mi%C4%99sie","page":"Książka kucharska/Jajka w mięsie"},{"id":"oc-plwb-14552","title":"Kaczka po czesku (Czech-style braised duck with quark and citrus sauce)","cuisine":"Other","category":"Main","ingredients":["1 whole duck","50 g wheat flour","to taste cooking fat (for frying)","3 tbsp cream","200 g quark (farmer's cheese)","1 tsp grated lemon zest","1 tsp grated orange zest","40 g raisins","to taste salt","to taste nutmeg"],"steps":["Wash the dressed duck, cut into 4 pieces, rub with salt and nutmeg, and dust with wheat flour.","Heat cooking fat in a skillet, brown the duck pieces on all sides, drizzle with cream, cover, and braise until tender.","Remove the tender meat, partially debone, and arrange the duck pieces in a baking dish.","Mix the braising juices with the ground quark, grated lemon zest, grated orange zest, and rinsed raisins.","Pour the prepared sauce over the duck and bake in the oven."],"time":95,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kaczka_po_czesku","page":"Książka kucharska/Kaczka po czesku"},{"id":"oc-plwb-10349","title":"Kaczka z winogronami (duck braised with red wine and dark grapes)","cuisine":"Other","category":"Main","ingredients":["1 whole duck (medium-sized)","500 g dark grapes (very ripe)","3 tbsp cooking oil","200 ml red wine","to taste salt","to taste black pepper","to taste nutmeg","to taste sugar","1 bouillon cube","100 ml water (to dissolve the bouillon cube)"],"steps":["Wash and pat dry the whole duck, cut into 8–10 pieces, sprinkle with half of the red wine, and place in the refrigerator.","Pluck the grapes from their stems, rinse, and dry them.","Sear the duck pieces on all sides in heated oil and transfer to a saucepan.","Season the meat with salt and pepper, cover, and braise, basting with the remaining wine and water with the dissolved bouillon cube.","Towards the end of braising, add the grapes and heat briefly so they release juice without bursting apart.","Season the dish with ground nutmeg, salt, and a pinch of sugar."],"time":80,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kaczka_z_winogronami","page":"Książka kucharska/Kaczka z winogronami"},{"id":"oc-plwb-14152","title":"Kalmary w winie (calamari braised in red wine and cognac)","cuisine":"Other","category":"Main","ingredients":["500 g squid (calamari)","2 onions","1 tbsp tomato purée","580 ml table red wine (2 and 1/3 glasses)","125 ml plain yogurt (half a glass)","2 tbsp cognac","1 pinch ground cinnamon","to taste salt (approx. 0.5 tbsp for boiling and to taste)","to taste black pepper","3 bay leaves (a few leaves)","1 tbsp butter (for frying)","1 l water (for boiling)"],"steps":["Thoroughly remove the membranes from the squid, wash the squid, cover with one litre of cold salted water in a saucepan, and cook covered for 4–5 minutes from the time it comes to a boil.","Drain the squid, slice into rings, and sauté in a skillet with melted butter.","Add the finely diced, briefly parboiled onions, tomato purée, bay leaves, salt, and pepper, and stir thoroughly.","Pour in the red wine and cook over low heat for 4–5 minutes.","Stir in the plain yogurt, sprinkle with ground cinnamon, bring to a boil, cover, and braise for 5–7 minutes.","Before serving, stir in the cognac, mix well, and transfer the dish to a platter."],"time":40,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kalmary_w_winie","page":"Książka kucharska/Kalmary w winie"},{"id":"oc-plwb-19579","title":"Kapuśniak czeski (Czech sauerkraut soup with pork, bacon, and wild mushrooms)","cuisine":"Other","category":"Soup","ingredients":["200 g sauerkraut","50 g smoked bacon","200 g pork","100 g potatoes","1 onion","1.3 l water (1 l for soup and 300 ml for potatoes)","30 g dried forest mushrooms","125 ml sour cream","5 tsp sugar","1 tsp salt","1 tbsp sweet paprika (1 tsp in ingredients, 1 tbsp in method)","2 clove garlic","3 allspice","to taste black pepper","4 slice bread with butter (thick slices for serving)"],"steps":["Dice the smoked bacon and pork into small cubes, and peel and chop the onion and garlic.","Boil the peeled potatoes in 300 ml of water until tender and mash them with a potato masher.","Render the fat from the bacon in a pan, remove the cracklings, and in the rendered fat sauté the onion until translucent and dust with sweet paprika.","Transfer the skillet contents into a pot, pour in 1 liter of water, and add the sauerkraut, bacon cracklings, dried mushrooms, allspice, salt, pepper, sugar, garlic, and sour cream.","Simmer the soup over low heat for 30 minutes, then add the diced pork and cook for another 10 minutes.","Stir the mashed potatoes into the soup, combine well, and serve with thick buttered slices of bread."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kapu%C5%9Bniak_czeski","page":"Książka kucharska/Kapuśniak czeski"},{"id":"oc-plwb-56206","title":"Kapuśniak portugalski (Portuguese savoy cabbage soup).","cuisine":"Other","category":"Soup","ingredients":["0.25 savoy cabbage (1/4 large head or 1/2 small head)","500 g potatoes","3 tbsp olive oil","1.5 clove garlic (1–2 cloves)","1 l meat broth","to taste salt","to taste black pepper","1.5 tbsp grated parmesan (1–2 tablespoons)"],"steps":["Bring the broth to a boil, add the peeled, diced potatoes, and cook for 15 minutes.","Wash and finely shred the savoy cabbage, add to the potatoes, season with salt and pepper, and cook for about 5 minutes.","Pour in the olive oil, add the pressed garlic and grated parmesan, stir, and heat over low heat until the soup is very thick."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kapu%C5%9Bniak_portugalski","page":"Książka kucharska/Kapuśniak portugalski"},{"id":"oc-plwb-13753","title":"Karmazyn pieczony (baked redfish with leeks and tomatoes in beer sauce)","cuisine":"Other","category":"Main","ingredients":["500 g redfish fillets (2 fillets, 250 g each)","1.5 tbsp butter","2 leeks","2 shallots","150 ml lager beer (1 teacup (150 ml))","to taste salt","to taste black pepper","150 ml fish stock (1 teacup (150 ml))","2 tomatoes"],"steps":["Preheat the oven to 200 °C.","Melt part of the butter in a saucepan, add the thinly sliced white parts of the leeks, cover, and cook gently for 2–3 minutes.","Add the chopped shallots, cover, and cook gently for another 3–4 minutes.","Pour in the lager beer and fish stock, season with salt and pepper, and simmer uncovered until reduced by about 1/3.","Arrange the redfish fillets in the saucepan, cover with sliced tomatoes, season, and bake in the oven for about 10 minutes.","Transfer the fish to plates, stir the remaining butter into the sauce, adjust seasoning to taste, and pour over the fillets."],"time":35,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Karmazyn_pieczony","page":"Książka kucharska/Karmazyn pieczony"},{"id":"oc-plwb-15964","title":"Kawa elegantissimo (iced dark chocolate espresso with whipped cream)","cuisine":"Other","category":"Drink","ingredients":["4 tsp ground coffee (Guatemalan)","6 tsp sugar","30 g dark chocolate","to taste whipped cream (for garnish)","to taste crushed ice"],"steps":["Brew two servings of strong espresso from the ground coffee.","Dissolve the sugar and most of the chopped dark chocolate in the hot coffee, grating the rest into chocolate shavings.","Place the coffee drink in the refrigerator for at least 180 minutes.","Fill glasses with crushed ice, pour in the chilled coffee, and garnish with whipped cream and chocolate shavings."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kawa_elegantissimo","page":"Książka kucharska/Kawa elegantissimo"},{"id":"oc-plwb-16989","title":"Kawa mrożona (iced coffee with whipped cream)","cuisine":"Other","category":"Drink","ingredients":["40 g ground coffee","30 g sugar","150 g heavy whipping cream","40 g powdered sugar","500 ml water (boiling)"],"steps":["Pour boiling water over the ground coffee, strain the brew, sweeten with sugar, and let cool.","Place the cooled coffee in the freezer and chill until semi-frozen.","Whip the heavy whipping cream into stiff peaks, beating in the powdered sugar towards the end.","Pour the frozen coffee into cups and garnish with whipped cream."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kawa_mro%C5%BCona","page":"Książka kucharska/Kawa mrożona"},{"id":"oc-plwb-21447","title":"Kawa mrożona z lodami (iced coffee dessert with ice cream)","cuisine":"Other","category":"Dessert","ingredients":["125 ml black coffee (half a glass of strong brew)","2 tsp sugar","2 tsp coffee liqueur","100 g coffee ice cream (2 scoops)","1 tsp grated chocolate","2 chocolate wafer rolls","4 lemon balm leaves"],"steps":["Sweeten the hot black coffee with sugar, allow to cool, and stir in the coffee liqueur.","Place the coffee in the freezer to chill thoroughly.","Pour the chilled coffee into chilled sundae dishes and top with scoops of coffee ice cream.","Garnish the dessert with grated chocolate, chocolate wafer rolls, and lemon balm leaves."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kawa_mro%C5%BCona_z_lodami","page":"Książka kucharska/Kawa mrożona z lodami"},{"id":"oc-plwb-56113","title":"Kawarma (Balkan meat and vegetable clay pot bake)","cuisine":"Other","category":"Main","ingredients":["750 g pork, veal, or chicken meat (700–800 g)","6.5 potatoes (6–7 medium pieces)","4 tbsp olive oil (3–5 tablespoons)","2 onions (finely chopped)","1 leek (sliced)","2.5 bell peppers (2–3 sliced pieces)","1 tsp tomato paste","125 ml wine","125 ml water (1/2 glass to dilute paste)","1 tsp summer savory","3.5 pinch dried mint (3–4 pinches)","1 tsp sweet paprika","to taste salt","to taste black pepper"],"steps":["Cut the pork, veal, or chicken into chunks and season lightly with salt, and dice the peeled potatoes.","Dilute the tomato paste in 125 ml of water.","Pour olive oil into the bottom of an earthenware or baking dish, then layer the meat, finely chopped onions, sliced leek, potatoes, and bell peppers.","Pour the diluted tomato paste and wine over the ingredients, and season the top with summer savory, mint, sweet paprika, salt, and pepper.","Bake covered in an oven preheated to 170–180 °C for 45–55 minutes until the meat and potatoes are tender."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kawarma","page":"Książka kucharska/Kawarma"},{"id":"oc-plwb-56170","title":"Kebapczeta (Bulgarian grilled minced meat rolls)","cuisine":"Other","category":"Main","ingredients":["1 kg minced meat (preferably lamb or mixed)","1 tbsp ground caraway","1 tbsp ground black pepper","1 tbsp summer savory","3.5 tsp salt (3–4 tsp)"],"steps":["Mix the minced meat thoroughly with the ground caraway, ground pepper, summer savory, and salt into a uniform mixture, and refrigerate for 60 minutes.","Shape the chilled mixture into oblong rolls shaped like small sausages.","Grill slowly on a hot barbecue grate, turning regularly so the patties brown evenly and stay juicy inside."],"time":90,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kebapczeta","page":"Książka kucharska/Kebapczeta"},{"id":"oc-plwb-18812","title":"Keks warzywny (savoury vegetable loaf cake)","cuisine":"Other","category":"Cake","ingredients":["150 g carrots","1 red bell pepper","100 g green beans","100 g courgette","300 g plain flour","200 g butter (plus extra for greasing the tin)","5 eggs","1 tsp baking powder","to taste salt","to taste white pepper"],"steps":["Dice the carrots, red bell pepper, and courgette, trim the woody ends off the green beans, and cut the pods into smaller pieces.","Parboil the vegetables in boiling water: the bell pepper and courgette for 5 minutes, and the carrots and green beans for 10 minutes, then drain, pat dry, and toss in a little plain flour.","Separate the egg yolks from the whites and beat the yolks with 200 g of butter until smooth and fluffy.","Add the remaining plain flour mixed with the baking powder, season with salt and white pepper, and combine with the cooled vegetables.","Beat the egg whites until stiff peaks form and gently fold them into the batter.","Transfer the mixture into the buttered loaf tin, bake for 50–60 minutes in an oven preheated to 210 °C, and slice once cooled."],"time":85,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Keks_warzywny","page":"Książka kucharska/Keks warzywny"},{"id":"oc-plwb-13089","title":"Kerststol (Dutch Christmas fruit bread)","cuisine":"Other","category":"Bread","ingredients":["125 g blanched almonds (white)","125 g granulated sugar","1 egg","200 g raisins (assorted types)","2 tbsp candied lemon peel (finely chopped)","60 g candied cherries","3 tbsp rum","7 g dried yeast","80 ml water (warm)","60 g butter","120 ml milk","125 g brown sugar","3 tbsp candied bitter orange peel (finely chopped)","450 g plain flour (400–500 g)","0.5 tsp salt","1 egg","20 g butter (extra portion for brushing)","to taste icing sugar (for dusting)"],"steps":["Grind the blanched almonds in a food processor or grinder, add the beaten egg and granulated sugar, and mix into a uniform, compact almond paste, then wrap in cling film and chill in the refrigerator.","In a bowl, combine the raisins, candied lemon peel, candied orange peel, and candied cherries, pour over the rum, cover, and set aside for at least 2 hours.","Dissolve the dried yeast in 80 ml of warm water, and in a separate pot heat 120 ml of milk with 60 g of butter and brown sugar until the fat melts.","Sift the plain flour with the salt into a bowl, make a well, and pour in the dissolved yeast, cooled milk with butter and sugar, and beaten egg.","Mix the ingredients and knead the dough on a floured board for at least 10 minutes until smooth and elastic.","Brush the dough with a little butter, place into a bowl, cover with a damp cloth, and set aside in a warm place for 60 minutes to rise.","Turn out the dough, knead for 1 minute, flatten into a disc, scatter the drained soaked dried fruits on top, and gently knead them into the dough.","Roll out the dough into an oval measuring 20 by 30 cm, transfer to a greased baking tin, and brush the top with the extra 20 g of butter.","Press a lengthwise indent along the centre with a rolling pin, shape 100 g of the prepared almond filling into a log, place it into the groove, and fold the dough over the filling.","Cover the shaped bread with a cloth and set aside in a warm place for another 60 minutes to rise.","Bake in an oven preheated to 180 °C for 30–35 minutes until golden brown, and once cool, dust generously with icing sugar."],"time":245,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kerststol","page":"Książka kucharska/Kerststol"},{"id":"oc-plwb-18681","title":"Koktajl karambolowy (starfruit cocktail)","cuisine":"Other","category":"Drink","ingredients":["1 starfruit","4 ice cubes","100 ml vermouth","100 ml pineapple juice","to taste pineapple (sliced)","125 ml champagne (chilled)"],"steps":["Wash the starfruit, slice off a few star-shaped rounds for garnish, and cut the remainder into small pieces.","Dice the pineapple slices finely, crush the ice cubes, and place them into glasses.","Mix the pineapple juice with the vermouth and 125 ml of chilled champagne, then pour into the ice-filled glasses.","Add the diced pineapple and starfruit pieces to the cocktail, and garnish the glasses with the starfruit slices."],"time":5,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Koktajl_karambolowy","page":"Książka kucharska/Koktajl karambolowy"},{"id":"oc-plwb-14816","title":"Koktajl z kurczaka (chicken cocktail salad)","cuisine":"Other","category":"Salad","ingredients":["400 g chicken breast (roasted or boiled, skinless)","3 slice pineapple","1 canned mandarin oranges (can)","3 tbsp flaked almonds","to taste sweet paprika","to taste pepper","to taste salt","1 mayonnaise (small jar)","2 tbsp lemon juice","3 tbsp ketchup","3 tbsp cognac","to taste lettuce leaves (a few leaves)","125 ml compote fruit (drained)","to taste parsley (for garnish)"],"steps":["Dice the chicken breast and pineapple slices finely, add the halved canned mandarin segments and the flaked almonds.","Season the ingredients with salt, pepper, and sweet paprika, toss, and set aside in a cool place.","Slowly pour the cognac, ketchup, and lemon juice into the mayonnaise and mix thoroughly into a smooth dressing.","Line glass bowls with lettuce leaves, spoon in portions of the chicken salad, drizzle with the dressing, and garnish with the drained compote fruit and parsley."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Koktajl_z_kurczaka","page":"Książka kucharska/Koktajl z kurczaka"},{"id":"oc-plwb-18081","title":"Kolorowe ciasteczka (colourful candy butter cookies)","cuisine":"Other","category":"Cookie","ingredients":["100 g butter (softened)","80 g sugar","150 g plain flour","1 tsp baking powder","85 g colourful chocolate dragées (or icing with natural food colouring)"],"steps":["Beat the softened butter with the sugar using a mixer until light and fluffy.","Add the plain flour and baking powder, and knead by hand into a uniform dough.","Shape the dough into 14 balls and arrange them well-spaced on a baking sheet without flattening them.","Decorate the tops of the dough balls with colourful chocolate dragées before baking, or with icing towards the end of baking.","Bake in an oven preheated to 180 °C for 11–12 minutes.","Wait a moment after removing from the oven, then transfer the cookies to a wire rack to cool completely."],"time":27,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kolorowe_ciasteczka","page":"Książka kucharska/Kolorowe ciasteczka"},{"id":"oc-plwb-60166","title":"Kotleciki z groszku (green pea patties)","cuisine":"Other","category":"Main","ingredients":["1 canned green peas (can)","to taste potato starch (to thicken the mixture)","2 clove garlic","to taste smoked paprika powder","to taste sunflower seeds","to taste vegetable oil (for frying)"],"steps":["Drain the canned green peas and blend them with the peeled garlic and enough potato starch so that the mixture is easy to shape.","Shape the thick mixture into small patties.","Fry the patties in hot vegetable oil for about 3 minutes per side, then transfer to a plate, dust with smoked paprika, and sprinkle with sunflower seeds."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotleciki_z_groszku","page":"Książka kucharska/Kotleciki z groszku"},{"id":"oc-plwb-14809","title":"Kotlety mielone w sosie miętowym (minced meat patties with mint sauce)","cuisine":"Other","category":"Main","ingredients":["400 g mixed minced meat","2 Kaiser rolls","2 eggs","1 tbsp mustard","10 fresh mint (leaves)","to taste salt","to taste pepper","375 ml vegetable oil (for deep-frying)","100 ml plain yogurt","20 fresh mint (leaves)","2 tbsp wine vinegar","to taste salt"],"steps":["Tear the Kaiser rolls into smaller pieces and pass through a grinder, and rinse and finely chop 10 fresh mint leaves.","Combine the minced meat with the ground bread, chopped mint, mustard, and eggs, season with salt and pepper, and knead into a smooth mixture.","Shape the mixture into small round patties and fry them in 375 ml of very hot oil.","Rinse and finely chop the remaining 20 mint leaves, mix them with the plain yogurt, wine vinegar, and salt, and pour the sauce over the fried patties."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kotlety_mielone_w_sosie_mi%C4%99towym","page":"Książka kucharska/Kotlety mielone w sosie miętowym"},{"id":"oc-plwb-61667","title":"Kulajda (Czech mushroom and potato soup)","cuisine":"Other","category":"Soup","ingredients":["500 g fresh wild mushrooms (such as porcini, birch boletes)","1375 ml broth or stock (1250–1500 ml)","250 ml dry white wine","4 potatoes","125 ml sour cream","1 tbsp butter","1 onion","3 pinch ground caraway","to taste salt","1 tsp vinegar (plus a splash for poaching eggs)","1 tsp sugar","1 parsley (handful, chopped)","4 eggs (for poaching)"],"steps":["Clean the fresh mushrooms and dice them, leaving any smaller caps whole.","Melt 1 tablespoon of butter in a pot, add the chopped onion and cook until translucent, then add the mushrooms and sauté briefly over high heat.","Pour in 250 ml of dry white wine, reduce until evaporated, and sprinkle in several pinches of ground caraway.","Add the diced potatoes and 1250–1500 ml of broth, season with salt, and simmer covered until the potatoes are tender.","Meanwhile, poach the eggs by slipping them individually into simmering water with a splash of vinegar for about 3 minutes.","Temper 125 ml of sour cream with a little hot broth, then stir it into the soup to thicken it.","Season the soup with 1 teaspoon of vinegar, 1 teaspoon of sugar, and chopped parsley, and serve topped with a poached egg."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kulajda","page":"Książka kucharska/Kulajda"},{"id":"oc-plwb-15527","title":"Kąski drobiowe (marinated chicken and banana bites)","cuisine":"Other","category":"Snack","ingredients":["400 g chicken breast fillet","1 banana","1 tsp honey","4 tbsp vegetable oil","1 tbsp soy sauce","1 tbsp lemon juice","1 tsp sesame seeds","1 pinch ground ginger","to taste ground hot paprika","to taste salt","to taste black pepper"],"steps":["Cut the chicken fillet into large cubes and slice the peeled banana.","Mix oil with soy sauce, lemon juice, ginger, honey, and sesame seeds, then season the marinade with salt, pepper, and ground hot paprika.","Place the chicken and banana into the marinade, cover the dish, and refrigerate for 30 minutes.","Remove the ingredients from the marinade, brown on all sides in a hot oiled skillet, then transfer to a baking tray and bake for 10 minutes, basting frequently with leftover marinade."],"time":55,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/K%C4%85ski_drobiowe","page":"Książka kucharska/Kąski drobiowe"},{"id":"oc-plwb-14330","title":"Leek lasagne","cuisine":"Other","category":"Main","ingredients":["3 leek (thick)","2 carrot (large)","2 zucchini","2 tomato","1 celeriac (small)","200 g green peas","3 tbsp vegetable oil","to taste salt","to taste black pepper"],"steps":["Trim and wash the vegetables. Cut off the green parts and root ends from the leeks, slice the white stalks lengthwise, and cut into 10–12 cm sections.","Drop the leeks into salted boiling water, cook for 4 minutes, then drain and rinse with cold water.","Dice the zucchini, celeriac, and carrots. Heat 2 tablespoons of oil in a large frying pan and fry the carrots with the celeriac.","Add the zucchini and green peas and cook gently, covered, for 20 minutes; after 10 minutes add the blanched, peeled, and diced tomatoes, then season with salt and pepper.","Grease a baking dish with the remaining 1 tablespoon of oil, arrange 4 layers of leek sheets and vegetable mixture, and bake for 10 minutes in the oven preheated to 200 °C."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lazania_z_pora","page":"Książka kucharska/Lazania z pora"},{"id":"oc-plwb-14012","title":"Lemon rice soup (Zupa cytrynowa z ryżem)","cuisine":"Other","category":"Soup","ingredients":["100 g rice (1 bag)","4 tsp turkey broth powder","1 l water","to taste salt","1 lemon (for juice)","250 ml plain yogurt (or sour cream) (250 ml)","1 tbsp dill (chopped)"],"steps":["Cook the rice until tender and drain.","Cut the lemon in half and squeeze out the juice.","Bring the water to a boil, stir in the broth powder, and cook for several minutes, then add the drained rice.","Mix the yogurt (or sour cream) with lemon juice, pour into the soup, and season with salt if needed.","Sprinkle the soup with chopped dill before serving."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_cytrynowa_z_ry%C5%BCem","page":"Książka kucharska/Zupa cytrynowa z ryżem"},{"id":"oc-plwb-55031","title":"Lemon, lime, and mint lemonade","cuisine":"Other","category":"Drink","ingredients":["2 lemon","2 lime","3 fresh mint (sprigs)","3 tbsp honey (2–4 tablespoons)","2 l spring or mineral water","to taste ice cubes"],"steps":["Cut the lemons and limes in half.","Squeeze the juice from three lemon halves and three lime halves, and slice the remaining two halves into slices.","Place the sliced citrus into a pitcher, add honey, pour in the squeezed juice and 2 l of water, and stir until the honey dissolves.","Add the sprigs of fresh mint and ice cubes to the drink."],"time":10,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_z_cytryny%2C_limonki_i_mi%C4%99ty","page":"Książka kucharska/Lemoniada z cytryny, limonki i mięty"},{"id":"oc-plwb-55055","title":"Lemon-ginger lemonade","cuisine":"Other","category":"Drink","ingredients":["500 g lemon","90 g fresh ginger (80–100 g rhizome)","80 ml maple syrup or honey","2 tbsp apple cider vinegar (optional)","1.5 l water (cold, filtered or sparkling)","3 slice lemon (several slices for garnish)","to taste ice cubes"],"steps":["Peel the lemons, leaving a little zest on one fruit. Scrub the ginger and cut into smaller pieces.","Pass the lemons and ginger alternately through a juicer.","Combine the extracted lemon-ginger juice with 80 ml of maple syrup or honey, apple cider vinegar, and 1.5 l of cold water.","Place ice cubes and lemon slices into a pitcher, pour in the prepared lemonade, and stir."],"time":15,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_cytrynowo-imbirowa","page":"Książka kucharska/Lemoniada cytrynowo-imbirowa"},{"id":"oc-plwb-55023","title":"Lemonade with lemon, orange, and mint","cuisine":"Other","category":"Drink","ingredients":["250 ml water (for the syrup)","to taste still mineral water (for topping up the pitcher)","1 lemon","1 orange","3 tbsp brown sugar","to taste fresh mint (leaves)"],"steps":["Boil 250 ml of water, dissolve 3 tablespoons of brown sugar in it, let cool, and pour the syrup into a pitcher.","Thoroughly wash the lemon and orange, cut the fruits in half, and squeeze out their juice.","Slice the remaining portions of the fruits into rounds, place them into the pitcher, and pour in the squeezed juice.","Top up the pitcher with still mineral water, stir thoroughly, add fresh mint leaves, and refrigerate to chill."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_z_cytryn%C4%85%2C_pomara%C5%84cz%C4%85_i_mi%C4%99t%C4%85","page":"Książka kucharska/Lemoniada z cytryną, pomarańczą i miętą"},{"id":"oc-plwb-55027","title":"Limeade","cuisine":"Other","category":"Drink","ingredients":["1.5 l still spring water","2 lime","4 tbsp sugar","to taste fresh mint (leaves)","to taste ice cubes"],"steps":["Pound the fresh mint leaves with 1 tablespoon of sugar.","Squeeze the juice from one lime, and slice the other into rounds.","Dissolve the remaining 3 tablespoons of sugar in 1.5 l of spring water, then add the muddled mint, juice, and lime slices.","Stir everything thoroughly, add ice, and serve."],"time":10,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_limonkowa","page":"Książka kucharska/Lemoniada limonkowa"},{"id":"oc-plwb-56200","title":"Lisbon-style spinach and sardine bake (Zapiekanka lizbońska)","cuisine":"Other","category":"Main","ingredients":["500 g frozen spinach","1 onion","2 canned sardines in olive oil (cans)","50 g breadcrumbs (part for the mixture, part for topping)","0.5 lemon juice (squeezed from half a lemon)","1 egg (hard-boiled)","1 tbsp butter (or margarine) (for greasing the dish and dotting on top)","to taste water (small amount for cooking spinach)","to taste salt","to taste black pepper"],"steps":["Cook the spinach until tender in a small amount of salted water, then drain and squeeze out all excess moisture thoroughly.","Grate the onion, drain the sardines from the oil, remove the backbones, and flake with a fork.","Mix the spinach with the flaked sardines, grated onion, some of the breadcrumbs, lemon juice, and finely chopped hard-boiled egg, and season with salt and pepper.","Transfer the mixture into a greased baking dish, sprinkle the top with the remaining breadcrumbs, and dot with cold butter shavings.","Bake in a preheated oven for 20–30 minutes until the top is lightly golden; serve alone or as a side to fish or poultry."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_lizbo%C5%84ska","page":"Książka kucharska/Zapiekanka lizbońska"},{"id":"oc-plwb-1456","title":"Lithuanian apple cheese (Ser jabłkowy)","cuisine":"Other","category":"Preserve","ingredients":["7 kg tart apples (e.g. Antonovka, peeled)","1.5 kg sugar","to taste ground cinnamon"],"steps":["Peel the apples, remove the cores, and cut the fruit into eighths or sixteenths.","Toss the apples with the sugar, mix thoroughly, and set aside for 1–2 days until plenty of juice is released.","Pour the released juice into a wide pot and simmer over very low heat until it darkens, thickens, and reduces by about half.","Add the sliced apples and cinnamon to the reduced juice (to achieve a marbled look, stir in 3/4 of the fruit first, and the rest right at the end).","Cook the mixture over low heat, stirring constantly, until it becomes very thick and pulls away cleanly from the sides of the pot.","Transfer the apple mixture into damp cheesecloth or linen bags (or into shallow dishes moistened with cold water), shape, and hang in a breezy place to dry.","Once the apple cheese has set and dried firm, wrap it in parchment paper and store in a cool, dry place or in the refrigerator."],"time":285,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ser_jab%C5%82kowy","page":"Książka kucharska/Ser jabłkowy"},{"id":"oc-plwb-62815","title":"Lotus Biscoff cheesecake","cuisine":"Other","category":"Cake","ingredients":["300 g spiced caramel biscuits (200 g for the crust, 100 g for decoration)","65 g butter (melted)","300 g spiced cookie spread (200 g for the filling, 100 g for topping)","650 g cream cheese (600–700 g, min. 18% fat)","50 g powdered sugar"],"steps":["Line the bottom of a 20 cm springform tin with baking parchment.","Blend or crush 200 g of spiced biscuits into fine crumbs, pour in 65 g of melted butter, mix, and press firmly into the base of the springform tin.","Mix 200 g of cookie spread with 650 g of cream cheese by hand or on low mixer speed, add 50 g of powdered sugar, and mix until combined.","Transfer the cream cheese filling into the springform tin and smooth the top.","Melt the remaining 100 g of cookie spread, pour over the cheesecake, and scatter the remaining 100 g of crushed spiced biscuits on top."],"time":25,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lotus_cheesecake","page":"Książka kucharska/Lotus cheesecake"},{"id":"oc-plwb-17769","title":"Malakoff Torte (Bomba Malakoff)","cuisine":"Other","category":"Dessert","ingredients":["500 ml milk","1 cream-flavoured pudding powder (packet, about 40 g)","250 g butter","1 tbsp vanilla sugar","300 g sponge ladyfinger biscuits","to taste dried fruit and nuts (for decoration)"],"steps":["Cook the cream-flavoured pudding with the milk and set aside to cool completely.","Beat the softened butter with vanilla sugar until light and fluffy, then gradually incorporate the cooled pudding.","In a springform tin, alternate layers of sponge biscuits and custard buttercream, finishing with a dense layer of biscuits on top.","Cover the tin with cling film, weigh it down lightly, and refrigerate for at least 24 hours.","Before serving, garnish the top of the dessert with mixed nuts and dried fruits."],"time":40,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bomba_Malakoff","page":"Książka kucharska/Bomba Malakoff"},{"id":"oc-plwb-62616","title":"Marinated pork skewers (Wieprzowe szaszłyki)","cuisine":"Other","category":"Main","ingredients":["700 g pork shoulder or collar","3 tbsp soy sauce","2 tbsp lime or lemon juice","1 tbsp honey or brown sugar","1 tbsp sesame oil (or other fragrant vegetable oil)","2 clove garlic (crushed)","1 tsp fresh ginger (grated)","1 tsp curry powder","0.5 tsp chili flakes or hot paprika (optional)","2.5 tbsp cooking oil for grilling or frying","2 tbsp sesame seeds (lightly toasted)","to taste salt","to taste freshly ground black pepper"],"steps":["Rinse the pork, pat dry with paper towels, and cut into long strips or large cubes.","Mix the soy sauce, lime or lemon juice, honey or brown sugar, sesame oil, crushed garlic, grated ginger, curry powder, chili flakes, and a pinch of salt and pepper in a bowl.","Add the pork to the marinade, coat each piece thoroughly, cover, and refrigerate for a minimum of 4 hours (or overnight).","Soak wooden skewers in cold water for about 20 minutes, then thread the marinated pork tightly onto the skewers, reserving the leftover marinade.","Grill or pan-fry the skewers in hot oil over medium heat for 10–12 minutes, turning regularly and brushing with the reserved marinade until browned and juicy.","Sprinkle the skewers with the toasted sesame seeds towards the end of cooking, pressing them down lightly."],"time":272,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wieprzowe_szasz%C5%82yki","page":"Książka kucharska/Wieprzowe szaszłyki"},{"id":"oc-plwb-18838","title":"Mashed potato and vegetable bake (Zapiekanka z warzywami)","cuisine":"Other","category":"Main","ingredients":["750 g potatoes (boiled, for mash)","300 g broccoli","300 g cauliflower","300 g carrots","300 g celeriac","2 tbsp butter (1 tablespoon for mash, 1 tablespoon for greasing the dish)","3 tbsp cream (for mash)","2 egg yolks (yolks, for mash)","5 tbsp vegetable oil (for braising vegetables)","8 olives (a few)","to taste salt","to taste nutmeg (for mash)"],"steps":["Mash the boiled potatoes and beat into a smooth purée with half the butter, cream, egg yolks, salt, and nutmeg.","Divide the broccoli and cauliflower into florets, slice the carrots and celeriac, then cook gently covered in hot oil and season with salt.","Grease an ovenproof baking dish with the remaining butter, spread half of the mashed potatoes on the bottom, arrange the braised vegetables with olives over it, and cover with the remaining mash.","Bake for 30 minutes in an oven preheated to 200 °C."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_z_warzywami","page":"Książka kucharska/Zapiekanka z warzywami"},{"id":"oc-plwb-15579","title":"Melon and peach preserve with mint","cuisine":"Other","category":"Preserve","ingredients":["0.5 honeydew melon","10 peaches","3 fresh mint (sprigs)","1 kg gelling sugar"],"steps":["Cut the mint leaves into thin strips.","Peel the half honeydew melon, scoop out the seeds, and cut the flesh into small dice.","Prick the peaches with a fork, scald for a minute, cool, peel off the skin, remove the stones, and dice the flesh.","Blend the fruit until smooth, transfer to a pot, stir in the gelling sugar, and boil for 4 minutes while stirring constantly and skimming off any foam.","Stir the chopped mint into the hot preserve, spoon into jars, seal tightly, and turn upside down."],"time":20,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Marmolada_melonowa","page":"Książka kucharska/Marmolada melonowa"},{"id":"oc-plwb-18043","title":"Minced pork curry with apples","cuisine":"Other","category":"Main","ingredients":["500 g ground pork","4 carrots","1 parsley root","1 celeriac","3 apples","1 onion","125 ml broth","1 tbsp curry powder","50 g raisins","1 tsp ground cinnamon","to taste olive oil"],"steps":["Peel the carrots, parsley root, celeriac, onion, and apples, then cut into thin matchsticks or grate coarsely.","Brown the ground pork in hot olive oil, then add the prepared vegetables and apples.","Pour in the broth, stir in the curry powder, and simmer for about 10 minutes until the vegetables soften.","Add the raisins and ground cinnamon, then simmer for another 5 minutes."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Curry_z_mi%C4%99sa_mielonego","page":"Książka kucharska/Curry z mięsa mielonego"},{"id":"oc-plwb-62940","title":"Mini yeast-free coconut doughnuts","cuisine":"Other","category":"Dessert","ingredients":["220 g cake flour","150 g coconut milk (thick, canned)","2 egg (large, at room temperature)","50 g desiccated coconut","16 g vanilla-flavoured sugar","0.5 tsp baking soda","0.5 tsp baking powder","100 g desiccated coconut (for coating)","80 g powdered sugar","25 ml water (boiling, for glaze)","400 ml vegetable oil (or lard, for frying)"],"steps":["Whisk together the cake flour, 50 g of desiccated coconut, vanilla-flavoured sugar, baking soda, and baking powder in a large bowl.","Add the eggs and thick coconut milk, and stir vigorously with a spoon or spatula into a very thick, uniform batter.","Heat the vegetable oil in a saucepan to 165–170 °C.","Shape small walnut-sized balls with greased hands or drop portions of dough with two teaspoons directly into the hot oil.","Fry the doughnuts in batches for about 3–4 minutes until deep golden, then lift out with a slotted spoon and drain on paper towels.","Mix the powdered sugar with the boiling water in a small bowl into a thin glaze, and place the remaining 100 g of desiccated coconut in a second bowl.","Dip the warm doughnuts one by one into the glaze and immediately coat in the desiccated coconut."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Mini_bezdro%C5%BCd%C5%BCowe_p%C4%85czki_kokosowe","page":"Książka kucharska/Mini bezdrożdżowe pączki kokosowe"},{"id":"oc-plwb-14814","title":"Mint yogurt sauce","cuisine":"Other","category":"Sauce","ingredients":["300 g plain yogurt","20 fresh mint (leaves, or 4 tablespoons dried mint)","2 tbsp wine vinegar (alternatively use half this volume of olive oil)","to taste salt","to taste black pepper","1 fresh cucumber (small, optional)"],"steps":["Dice the small cucumber, sprinkle with salt, and set aside for about 10 minutes to draw out moisture.","Rinse the fresh mint leaves, chop them finely, and mix with the plain yogurt and wine vinegar.","Squeeze the excess liquid from the cucumber, add it to the sauce, season to taste with salt and pepper, and refrigerate for about 20 minutes."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_mi%C4%99towy_jogurtowy","page":"Książka kucharska/Sos miętowy jogurtowy"},{"id":"oc-plwb-18605","title":"Mixed green salad with fresh herbs (Sałaty w ziołach)","cuisine":"Other","category":"Salad","ingredients":["1.5 mixed salad greens (half head each of several varieties)","1 cucumber","1 bunch radishes","0.5 red bell pepper","0.5 yellow bell pepper","2 tbsp parsley leaves","2 tbsp fresh basil","2 tbsp fresh tarragon","2 tbsp fresh thyme","6 tbsp olive oil","3 tbsp wine vinegar","1 tsp mustard","to taste salt","to taste black pepper"],"steps":["Rinse and pat dry the salad greens, tear large leaves into bite-sized pieces, and arrange them in a salad bowl.","Finely chop the parsley leaves, basil, tarragon, and thyme.","Whisk the wine vinegar with mustard, olive oil, salt, and pepper, stir in the chopped herbs, and drizzle the dressing over the salad greens.","Peel and slice the cucumber, quarter the radishes, and cut the seeded bell pepper halves into thin strips.","Scatter the sliced vegetables over the dressed salad leaves and serve immediately."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82aty_w_zio%C5%82ach","page":"Książka kucharska/Sałaty w ziołach"},{"id":"oc-plwb-15509","title":"Nectarine and chocolate cornflake parfait","cuisine":"Other","category":"Dessert","ingredients":["200 g nectarines","100 g dark chocolate (1 bar)","50 g cornflakes","1 tbsp vegetable oil","300 g smooth quark (2 packs)","80 ml orange juice (from 1 orange)","2 tbsp sugar"],"steps":["Melt the dark chocolate in a small saucepan, add the vegetable oil and cornflakes, stir gently to coat, and divide among the bottom of dessert bowls.","Mix the smooth quark with the orange juice and sugar, then spoon the mixture into the dessert bowls as the second layer.","Wash the nectarines, cut them into thin slices, and arrange them neatly on top of the dessert."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Deser_z_nektarynkami","page":"Książka kucharska/Deser z nektarynkami"},{"id":"oc-plwb-16380","title":"North Star cocktail","cuisine":"Other","category":"Drink","ingredients":["60 ml brandy","20 ml gin","1 tsp dry vermouth","30 ml grapefruit juice","to taste ice cubes"],"steps":["Fill a cocktail shaker halfway with ice cubes.","Pour in the grapefruit juice, dry vermouth, brandy, and gin, and mix thoroughly.","Strain the cocktail into a tall cocktail glass."],"time":5,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gwiazda_P%C3%B3%C5%82nocy","page":"Książka kucharska/Gwiazda Północy"},{"id":"oc-plwb-25341","title":"Orgeat almond syrup drink (Syrop orszadowy)","cuisine":"Other","category":"Drink","ingredients":["250 g sweet almonds","100 g sugar","1 l water (or milk, max 1 l)"],"steps":["Pour boiling water over the almonds, soak for 5 minutes, and peel off their skins.","Finely grind or pound the peeled almonds together with the sugar and a small amount of water or milk.","Pour the remaining water or milk over the ground mixture, stir, and let stand for about 30 minutes.","Strain the liquid through a fine sieve or cheesecloth, squeezing the almonds firmly, and chill the drink for about 30 minutes before serving."],"time":75,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Syrop_orszadowy","page":"Książka kucharska/Syrop orszadowy"},{"id":"oc-plwb-19161","title":"Owoce pod kruszonką (strawberry and mango oat crumble)","cuisine":"Other","category":"Dessert","ingredients":["450 g frozen strawberries","4 mangoes","3 tbsp sugar","3 tbsp potato starch","250 ml rolled oats","250 ml sugar","200 g butter (frozen)"],"steps":["Peel the mangoes, chop into pieces, toss in a bowl with the strawberries, 3 tablespoons of sugar, and potato starch, and transfer to a baking dish.","In a separate bowl, mix the rolled oats with the remaining sugar, add the grated frozen butter, and rub together with your hands until clumps form.","Scatter the crumble topping evenly over the fruit layer.","Bake in an oven preheated to 180 °C for 45 minutes."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Owoce_pod_kruszonk%C4%85","page":"Książka kucharska/Owoce pod kruszonką"},{"id":"oc-plwb-18747","title":"Owocowe pucharki (summer fruit salad cups with honey yogurt)","cuisine":"Other","category":"Salad","ingredients":["8 apricots (fresh)","500 g watermelon","500 g melon","4 kiwi","1 lemon (juiced)","to taste vanilla sugar","430 g plain yogurt","6 tbsp honey (liquid)","to taste fresh mint (leaves for garnish)"],"steps":["Wash the fruit, peel the watermelon, melon, and kiwi, stone the apricots, and cut everything into bite-sized cubes.","Squeeze the lemon juice, dissolve the vanilla sugar in it, and drizzle over the prepared fruit.","Whisk the yogurt with the runny honey into a smooth dressing.","Divide the fruit among dessert cups, spoon the honey-yogurt sauce on top, and garnish with fresh mint leaves."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Owocowe_pucharki","page":"Książka kucharska/Owocowe pucharki"},{"id":"oc-plwb-10140","title":"Pan-browned braised rice","cuisine":"Other","category":"Side","ingredients":["200 g long-grain rice (dry boil-in-bag rice)","500 ml broth","to taste vegetable oil (to coat the bottom of the pan)"],"steps":["Pour enough oil into a cold skillet to coat the bottom, add the dry long-grain rice, and spread it in an even layer.","Fry the rice, stirring occasionally and re-spreading into an even layer until most grains are golden, while heating the broth in a separate pot.","Gradually pour the hot broth in small splashes through a gap under a slightly tilted lid, waiting each time until the liquid stops violently steaming and splattering.","Once all the broth is added, cook the rice covered over higher heat until the grains swell and absorb all the liquid."],"time":25,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sma%C5%BCony_ry%C5%BC","page":"Książka kucharska/Smażony ryż"},{"id":"oc-plwb-56174","title":"Papryka faszerowana serem (baked feta-stuffed sweet peppers / burek piperki)","cuisine":"Other","category":"Side","ingredients":["4 sweet bell peppers (large, elongated)","250 g feta cheese","2 eggs","2 tbsp olive oil"],"steps":["Cut the peppers in half lengthwise and remove the seeds.","Crumble the feta cheese into a bowl and mix thoroughly with the beaten eggs.","Stuff the pepper halves with the filling, brush generously on the outside with olive oil, and cover with the other halves.","Bake in an oven preheated to 165 °C for about 30 minutes."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Papryka_faszerowana_serem","page":"Książka kucharska/Papryka faszerowana serem"},{"id":"oc-plwb-14336","title":"Paprykowy tort (layered bell pepper and mozzarella meatloaf)","cuisine":"Other","category":"Main","ingredients":["500 g ground beef and pork","1 egg","3 red bell pepper","3 yellow bell pepper","100 g mozzarella","4 slice smoked bacon (thin slices, lean)","1 tbsp vegetable oil","1 tbsp thyme","to taste fresh parsley leaves (a few leaves for garnish)","to taste salt","to taste black pepper"],"steps":["Wash the bell peppers, halve them lengthwise and remove the seeds, then cut the mozzarella into cubes.","Mix the minced meat with the egg and thyme, and season the mixture with salt and pepper.","Line a round baking tin with aluminium foil and grease it with oil.","Arrange the bell pepper halves on the bottom of the tin and line the sides with slices of smoked bacon.","Spoon half of the meat mixture into the tin, scatter the mozzarella cubes over it, and cover with the remaining meat.","Bake in an oven preheated to 200 °C for 30 minutes.","Turn the finished casserole out onto a serving platter and garnish with chopped fresh parsley leaves."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Paprykowy_tort","page":"Książka kucharska/Paprykowy tort"},{"id":"oc-plwb-21803","title":"Parówki w cieście (battered fried frankfurters)","cuisine":"Other","category":"Snack","ingredients":["125 ml plain flour","125 ml water","3 eggs","0.25 tsp salt","3 tbsp vegetable oil (for frying)","6 frankfurters"],"steps":["Whisk the eggs into the water, then gradually beat in the flour and salt until a smooth batter slightly thicker than crepe batter forms.","Heat the oil in a frying pan, dip each frankfurter into the batter, and lower into the hot fat.","Fry the frankfurters for 2 minutes, turning them over, until the batter is evenly golden brown."],"time":10,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Par%C3%B3wki_w_cie%C5%9Bcie","page":"Książka kucharska/Parówki w cieście"},{"id":"oc-plwb-1513","title":"Pasta with parsley and toasted seeds","cuisine":"Other","category":"Main","ingredients":["400 g farfalle pasta","1 bunch parsley leaves (large bunch)","3 clove garlic","8 tbsp olive oil (or vegetable oil)","to taste sunflower seeds (or pumpkin seeds)"],"steps":["Cook the farfalle pasta al dente and drain.","Toast the sunflower seeds in a dry frying pan.","Finely chop the parsley leaves along with the peeled garlic cloves and mix with the olive oil.","Combine the hot pasta with the parsley-garlic mixture and sprinkle with the toasted sunflower seeds."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_natk%C4%85_i_pestkami","page":"Książka kucharska/Makaron z natką i pestkami"},{"id":"oc-plwb-16425","title":"Pasta with poached salmon in sour cream sauce","cuisine":"Other","category":"Main","ingredients":["2.5 tbsp pasta (dry)","80 g salmon fillet","2 tbsp sour cream 12%","1 tbsp margarine (flat tablespoon)","1 tbsp Parmesan cheese (grated, flat tablespoon)","0.5 tsp parsley leaves (chopped)","to taste vegetable broth (for poaching salmon and sauce)","1 pinch nutmeg","to taste salt","to taste black pepper"],"steps":["Rinse the salmon fillet, poach in the vegetable broth, let cool, and cut into pieces.","Cook the pasta al dente, drain thoroughly in a sieve, and cover to keep warm.","Whisk the vegetable broth with the 12% sour cream in a saucepan, simmer for 5 minutes, and season with salt, pepper, and nutmeg.","Add the salmon pieces and margarine to the sauce and warm briefly without boiling.","Pour the prepared sauce over the pasta and sprinkle with grated Parmesan and chopped parsley leaves."],"time":20,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_%C5%82ososiem_w_sosie_%C5%9Bmietanowym","page":"Książka kucharska/Makaron z łososiem w sosie śmietanowym"},{"id":"oc-plwb-3213","title":"Pasta with tuna and leek","cuisine":"Other","category":"Main","ingredients":["400 g pasta","340 g canned tuna in its own juices","1 leek (large)","200 g sour cream 18%","to taste olive oil (or vegetable oil, for frying)","to taste garlic (crushed)","to taste black pepper"],"steps":["Cook the pasta al dente and drain.","Slice the leek into rounds and gently fry in heated olive oil until tender.","Add the drained canned tuna and black pepper, and warm together for a moment.","Add the crushed garlic, remove the pan from the heat, stir in the sour cream, and pour the sauce over the cooked pasta."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Makaron_z_tu%C5%84czykiem","page":"Książka kucharska/Makaron z tuńczykiem"},{"id":"oc-plwb-19090","title":"Pickled Camembert cheese (nakládaný hermelín)","cuisine":"Other","category":"Snack","ingredients":["4 Camembert cheese (Hermelín or Camembert)","15 juniper berries","1 pinch sweet ground paprika","1 tsp thyme","1 tsp rosemary","4 bay leaf","8 clove garlic","2 hot chili pepper","to taste vegetable oil (to cover the jar)"],"steps":["Peel the garlic cloves and slice them thinly.","Cut the cheese rounds horizontally in half and coat the inside with the garlic slices, sweet ground paprika, thyme, and rosemary.","Place the filled cheese rounds into a jar, add the juniper berries, bay leaves, and halved hot chili peppers.","Pour vegetable oil into the jar until the cheese is completely submerged, seal, and let stand for several days."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Marynowany_ser_ple%C5%9Bniowy","page":"Książka kucharska/Marynowany ser pleśniowy"},{"id":"oc-plwb-17824","title":"Pickled garlic in white wine vinegar and olive oil","cuisine":"Other","category":"Preserve","ingredients":["650 g garlic (fresh)","500 ml white wine vinegar","3 tbsp honey","3.5 hot chili pepper (small, red)","6 bay leaf","1 tbsp allspice","1 tbsp white peppercorns","2 tsp mustard seeds","6 whole cloves","2 tbsp salt","125 ml olive oil"],"steps":["Peel the cloves of fresh garlic.","Bring the white wine vinegar to a boil in a pot with the honey, hot chili peppers, bay leaves, allspice, white peppercorns, mustard seeds, whole cloves, and salt.","Add the peeled garlic to the boiling brine and simmer for 5 minutes.","Remove the garlic and chili peppers, drain, and place in a sterilized jar.","Bring the pickling liquid back to a boil, pour it along with the olive oil into the jar, seal immediately and tightly, and store in a cool place."],"time":30,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Marynowany_czosnek","page":"Książka kucharska/Marynowany czosnek"},{"id":"oc-plwb-61675","title":"Pie floater pea soup","cuisine":"Other","category":"Soup","ingredients":["800 g frozen green peas","2 onion","1 leek","1 tbsp all-purpose vegetable seasoning","1 tbsp vegetable oil (for frying)","1 tsp butter","to taste barbecue sauce (for serving)","to taste salt","to taste black pepper (freshly ground)","2 l water"],"steps":["Peel and chop the onions and cleaned leek, then sauté the vegetables in a pot in hot oil and butter for 2–3 minutes.","Pour in 2 litres of water, add the vegetable seasoning, and simmer covered over low heat for about 20 minutes.","Add the frozen green peas to the broth and return the soup to a boil.","Blend the soup until smooth and creamy, season to taste with salt and freshly ground pepper, and serve with barbecue sauce."],"time":35,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pie_floater","page":"Książka kucharska/Pie floater"},{"id":"oc-plwb-449","title":"Piña colada","cuisine":"Other","category":"Drink","ingredients":["0.5 pineapple (peeled flesh)","100 ml coconut milk (chilled)","200 ml buttermilk","30 ml rum","to taste lemon juice"],"steps":["Peel the half pineapple, cut out the tough core, chop the flesh into chunks, and blend in a blender until smooth.","Pour in the chilled coconut milk, buttermilk, and rum, then blend again until well combined.","Season the cocktail to taste with lemon juice and pour into glasses."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pi%C3%B1a_colada","page":"Książka kucharska/Piña colada"},{"id":"oc-plwb-57964","title":"Pljeskavica (Balkan grilled spiced meat patty)","cuisine":"Other","category":"Main","ingredients":["400 g ground pork","400 g ground mutton (or veal)","250 g onion","1 hot chili pepper (small)","to taste black pepper","to taste salt","2 tbsp water (cold, for kneading the meat)"],"steps":["Grind the pork and mutton twice through a fine mincer plate together with the hot chili pepper.","Peel the onion, grate one tablespoon and add to the meat, and finely chop the remaining onion and dust with salt for serving.","Season the meat mixture with salt and pepper, splash with cold water, knead thoroughly by hand, and refrigerate for 3 hours.","Shape the meat into flat oval patties, grill on both sides on a barbecue grate or electric grill, and serve on a bed of chopped raw onion."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Pleskawica","page":"Książka kucharska/Pleskawica"},{"id":"oc-plwb-31872","title":"Pork curry with bell pepper and cream (Wieprzowina curry)","cuisine":"Other","category":"Main","ingredients":["400 g pork loin","1 onion (medium)","1.5 tbsp curry powder","1 pinch ground ginger","500 ml vegetable broth","150 ml whipping cream (30% fat) or coconut milk","0.5 tsp sweet paprika powder or flakes","1 pinch hot paprika powder","to taste cooking oil","to taste salt","to taste pepper","to taste fresh basil (leaves for garnish)","1 fresh bell pepper"],"steps":["Wash and pat dry the pork loin, cut into small strips or cubes, and season with salt and pepper.","Remove the seeds from the fresh bell pepper and cut into strips or dice, and finely chop the peeled onion.","Heat the oil in a deep frying pan or casserole, add the pork, sprinkle with curry powder and ginger, and fry stirring until lightly browned.","Add the onion and cook until translucent, then add the diced bell pepper and cook over moderate heat for about 5 minutes.","Stir in the sweet and hot paprika, pour in the vegetable broth, and simmer covered for 30–45 minutes, stirring occasionally.","Pour in the whipping cream or coconut milk, simmer for another 5 minutes, season to taste with salt and pepper, and garnish with basil leaves."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wieprzowina_curry","page":"Książka kucharska/Wieprzowina curry"},{"id":"oc-plwb-14459","title":"Potato gratin (Zapiekanka ziemniaczana)","cuisine":"Other","category":"Side","ingredients":["500 g potatoes","50 g firm cheese (grated)","125 ml milk","1 clove garlic (for rubbing the baking dish)","to taste nutmeg","to taste salt","to taste black pepper"],"steps":["Peel the potatoes, wash them, and cut into thin slices.","Rub a baking dish with garlic and arrange the potatoes in layers.","Season each layer with salt, pepper, nutmeg, and grated firm cheese, finishing with a layer of cheese on top.","Bring the milk to a boil and pour it over the potatoes.","Place the dish in an oven preheated to 200 °C and bake for about 40 minutes."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_ziemniaczana","page":"Książka kucharska/Zapiekanka ziemniaczana"},{"id":"oc-plwb-22452","title":"Potjiekos (South African layered stew)","cuisine":"Other","category":"Main","ingredients":["2 tbsp vegetable oil","2 onion (large, diced)","1.4 kg mutton neck (14 bone-in pieces)","250 g bacon (diced)","16 potatoes (small, cut into chunks)","1 white cabbage (small head, cut into 8 wedges)","1 tbsp lemon juice","500 ml water","to taste meat seasoning","to taste salt","to taste pepper"],"steps":["Heat the vegetable oil in a cast-iron Dutch oven or potjie pot, add the diced onion, bacon, and mutton neck pieces, and fry for about 30 minutes, stirring occasionally.","Layer the cut potatoes over the meat, top with cabbage wedges, pour over the water mixed with lemon juice, and season with meat spices, salt, and pepper, without stirring the layers.","Cover the pot with a tight-fitting lid and simmer over very low heat for about 120 minutes, adding a little water if needed, until the meat is falling off the bone.","Just before serving, stir the contents of the pot thoroughly."],"time":170,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Potjiekos","page":"Książka kucharska/Potjiekos"},{"id":"oc-plwb-16378","title":"Purple Passion cocktail","cuisine":"Other","category":"Drink","ingredients":["40 ml vodka","40 ml dark grape juice","40 ml grapefruit juice","1 slice lemon","2 tsp sugar","8 ice cubes"],"steps":["Pour the sugar onto a saucer, rub the rim of a highball glass with a lemon slice, dip the rim into the sugar, and leave to dry.","Fill a cocktail shaker halfway with ice cubes, pour in the vodka, dark grape juice, and grapefruit juice, and shake vigorously.","Fill the prepared glass three-quarters full with fresh ice cubes and strain the cocktail into it."],"time":5,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Purpurowa_nami%C4%99tno%C5%9B%C4%87","page":"Książka kucharska/Purpurowa namiętność"},{"id":"oc-plwb-61797","title":"Radicchio and kumquat salad with gouda (Sałatka z kumkwatami)","cuisine":"Other","category":"Salad","ingredients":["2 radicchio (heads)","200 g gouda cheese (diced)","2 kiwis (peeled)","6 kumquats (fresh)","6 tbsp corn oil (corn germ oil)","4 tbsp lemon juice","1 tbsp liquid honey","1 tbsp mild mustard","to taste salt","to taste black pepper (freshly ground)"],"steps":["Trim the radicchio leaves, rinse them in lukewarm water, pat dry, and cut into ribbons.","Wash the kumquats in warm water, pat dry, slice thinly, and remove any seeds.","Slice the peeled kiwis into rounds 3 mm thick and combine in a bowl with the radicchio, kumquats, and diced gouda cheese.","Whisk together the lemon juice, liquid honey, and mild mustard, season with salt and freshly ground pepper, then slowly drizzle in the corn oil while whisking constantly.","Pour the prepared dressing over the salad and toss gently just before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_kumkwatami","page":"Książka kucharska/Sałatka z kumkwatami"},{"id":"oc-plwb-55026","title":"Raspberry lemonade","cuisine":"Other","category":"Drink","ingredients":["300 g raspberries","750 g lemon (3 large lemons)","150 g sugar","1 fresh mint (sprig)","1 l still water (cold)","to taste ice cubes (several cubes)"],"steps":["Rinse the raspberries in a sieve, set aside 40 g of whole berries for garnish, and blend the remaining 260 g with a blender into a puree and strain through a sieve.","Wash and dry the lemons; cut one into half-slices about 0.5 cm thick, place in the bottom of a pitcher, and pour in 750 ml of cold water.","Squeeze about 200 ml of juice from the remaining two lemons.","Heat the remaining 250 ml of water in a pot, add 150 g of sugar, stir until completely dissolved, and chill the resulting syrup.","Pour the lemon juice, raspberry puree, and cooled syrup into the pitcher, add a mint sprig rolled in your hands, stir, and refrigerate to chill.","Before serving, drop ice cubes and the reserved whole raspberries into the pitcher or tumblers."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_malinowa","page":"Książka kucharska/Lemoniada malinowa"},{"id":"oc-plwb-11117","title":"Red soup with rice and minced beef","cuisine":"Other","category":"Soup","ingredients":["200 g white rice (2 boil-in bags)","250 g ground beef","4 onion (medium-sized)","1 clove garlic","1 tbsp olive oil","1 l tomato juice","500 ml vegetable broth (from fresh vegetables or a bouillon cube)","2 tbsp sour cream","1 tsp ground caraway","1 bay leaf","to taste salt","to taste black pepper","to taste sugar"],"steps":["Peel the onions, dice them finely, and cook in a pot with heated olive oil until translucent.","Add the minced garlic, ground beef, and white rice, and fry for a few minutes while stirring constantly.","Pour in the tomato juice and vegetable broth, add the bay leaf and ground caraway, then simmer over low heat for about 20 minutes.","Season the soup to taste with salt, pepper, and sugar.","Remove the pot from the heat, stir in the sour cream, and serve."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Czerwona_zupa_z_ry%C5%BCem","page":"Książka kucharska/Czerwona zupa z ryżem"},{"id":"oc-plwb-18905","title":"Rice and lentil veggie burger","cuisine":"Other","category":"Main","ingredients":["200 g rice and lentil mix (dry mix)","500 ml water (for cooking rice and lentils)","1 red bell pepper (small, finely chopped)","60 g grated semi-hard cheese","2 tsp plain flour (level teaspoons)","2 eggs (beaten)","4 sesame seed buns (large)","4 tbsp mayonnaise","1 red onion (small, sliced)","0.5 lettuce (small head, shredded)","0.25 cucumber (sliced)","60 g breadcrumbs (for breading)","3 tbsp vegetable oil (for frying)","to taste salt","to taste black pepper"],"steps":["Cook the rice and lentils in salted water until tender, then drain.","Heat a tablespoon of oil in a pan and saute the finely chopped bell pepper for 5 minutes.","Remove the pan from the heat, combine the pepper with the cooked rice, lentils, and grated cheese, and season with salt and black pepper.","Shape the mixture into a round disk about 20 cm in diameter on a moistened plate, chill in the refrigerator for 2 hours, then cut into 4 patties.","Dredge each patty in flour, dip in beaten egg, coat in breadcrumbs, and fry in hot oil for 2–3 minutes per side.","Halve and toast the sesame buns, spread with mayonnaise, assemble with the patties, onion slices, shredded lettuce, and cucumber, and cover with the top buns."],"time":165,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Hamburger_ry%C5%BCowo-soczewicowy","page":"Książka kucharska/Hamburger ryżowo-soczewicowy"},{"id":"oc-plwb-14284","title":"Roast beef in green peppercorn sauce (Wołowina w sosie pieprzowym)","cuisine":"Other","category":"Main","ingredients":["800 g boneless beef","2 onions","250 ml vegetable broth (250 ml)","125 ml sour cream (125 ml)","50 ml dry white wine (1 small glass)","6 green peppercorns (a few peppercorns)","1 tbsp all-purpose flour","1 tsp mustard","1 clove garlic","to taste butter (for braising the onion)","to taste salt","to taste black pepper"],"steps":["Wash and pat dry the meat, rub with salt and pepper, roll up, place in an oven roasting bag, and set on a baking sheet.","Roast the beef for about 60 minutes in an oven preheated to 180 °C.","Melt the butter in a pot, add the chopped onion and garlic, pour in the white wine, add the mustard, and cook gently covered for 5 minutes.","Blend the braised onion, pour in the vegetable broth, add the green peppercorns, and cook for 15 minutes.","Whisk the sour cream with the flour, pour into the sauce, and stir.","Cook the sauce for a moment longer, stirring, season with salt and pepper, pour into a gravy boat, and serve with the roasted meat."],"time":80,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wo%C5%82owina_w_sosie_pieprzowym","page":"Książka kucharska/Wołowina w sosie pieprzowym"},{"id":"oc-plwb-16893","title":"Roast meat and broccoli casserole (Zapiekanka z pieczonym mięsem)","cuisine":"Other","category":"Main","ingredients":["150 g roast meat (sliced)","2 potatoes","2 carrots","1 broccoli (small head)","3 tbsp firm cheese (a few tablespoons, grated)","2 tbsp vegetable oil (for greasing the dish)","to taste salt","to taste black pepper"],"steps":["Boil the potatoes and carrots in their skins, peel, and slice the potatoes and dice the carrots.","Parboil the broccoli briefly and divide into florets.","Grease an ovenproof baking dish with oil, layer the slices of potatoes and roast meat alternately, arrange the broccoli florets and carrots around them, season with salt and pepper, and sprinkle the top with grated cheese.","Bake for about 30 minutes in an oven preheated to 180 °C."],"time":55,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_z_pieczonym_mi%C4%99sem","page":"Książka kucharska/Zapiekanka z pieczonym mięsem"},{"id":"oc-plwb-16688","title":"Roast turkey breast in citrus ginger sauce","cuisine":"Other","category":"Main","ingredients":["1 kg turkey breast","11 mandarin oranges (10–12 pieces)","250 ml orange juice","2 tbsp lemon juice","20 g fresh ginger (grated)","1 tsp grated lemon zest","1 tbsp sesame seeds (seeds)","1 tbsp butter","1 tbsp vegetable oil","to taste salt","to taste black pepper"],"steps":["Rub the turkey breast with salt and black pepper, place in a roasting pan, brush with oil, and roast for about 50 minutes at 200 °C, basting with pan juices.","Cool the roasted meat, slice thinly, and arrange on a platter.","Toast the sesame seeds in a saucepan, add the butter, and once melted, pour in the orange juice and lemon juice, add the lemon zest and grated ginger, and simmer until the sauce thickens.","Pour the sauce over the turkey slices, chill in the refrigerator, and garnish with mandarin orange segments."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Indyk_w_sosie_imbirowym","page":"Książka kucharska/Indyk w sosie imbirowym"},{"id":"oc-plwb-14282","title":"Ryżowe kulki nadziewane mielonym mięsem (rice balls stuffed with minced meat)","cuisine":"Other","category":"Main","ingredients":["500 g minced meat","500 g rice","125 ml almonds","125 ml raisins","1 onion","1 egg","to taste oil (for frying)","to taste breadcrumbs (for breading)","to taste salt","to taste black pepper"],"steps":["Cook the rice until parboiled and slightly tender, then let it cool slightly.","Peel and chop the onion, cook until translucent in the hot oil, then add the minced meat, blanched and chopped almonds, and rinsed raisins.","Cook the filling until the meat is browned and cooked through, and season with salt and pepper.","Shape the rice into small, thin patties, place a spoonful of meat filling in the centre of each, seal the edges, and roll into neat balls.","Roll the rice balls in beaten egg and breadcrumbs, then fry in hot oil on all sides until golden brown."],"time":60,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ry%C5%BCowe_kulki_nadziewane_mielonym_mi%C4%99sem","page":"Książka kucharska/Ryżowe kulki nadziewane mielonym mięsem"},{"id":"oc-plwb-14696","title":"Salmon and avocado appetizer","cuisine":"Other","category":"Snack","ingredients":["300 g smoked salmon","6 celery (stalks)","6 scallion (5–6 small bulbs)","8 avocado (ripe)","4 tbsp lemon juice","4 tbsp sour cream","4 tbsp mayonnaise","2 tsp ketchup","0.25 tsp Tabasco sauce (a few drops)","2 tbsp flaked almonds (heaping, toasted)","to taste salt","to taste pepper"],"steps":["Cut the smoked salmon into thin strips or chop it, and finely chop the trimmed celery stalks and scallions.","Wash the avocados, cut them in half, remove the stones, and gently scoop out some of the flesh with a teaspoon.","Drizzle the scooped-out avocado flesh and the avocado shells with lemon juice, then mix the flesh with the salmon, celery, and scallions.","Fill the avocado halves with the prepared salmon salad.","Whisk the sour cream with the mayonnaise and ketchup, season with salt, pepper, and Tabasco sauce, spoon over each portion, and garnish with toasted flaked almonds."],"time":20,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Przystawka_z_%C5%82ososia_i_awokado","page":"Książka kucharska/Przystawka z łososia i awokado"},{"id":"oc-plwb-18826","title":"Salmon spread on toast (Tosty z łososiem)","cuisine":"Other","category":"Snack","ingredients":["8 slice sliced sandwich bread","150 g fresh salmon fillet","100 g smoked salmon","3 tbsp mayonnaise","50 g olives","1 lemon (juice and slices for garnish)","1 bunch fresh dill","3 tbsp cooking oil","to taste salt","to taste pepper"],"steps":["Season the fresh salmon with salt and pepper, fry in a portion of the oil, and flake into small pieces once cooled.","Finely dice the smoked salmon and combine with the fried fish.","Add the mayonnaise, chopped olives, juice from part of the lemon, and chopped dill, mix thoroughly, and season to taste with salt and pepper.","Brush the bread slices with the remaining oil, toast in the oven until golden, and once cooled, spread with the salmon mixture and garnish with dill and lemon slices."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tosty_z_%C5%82ososiem","page":"Książka kucharska/Tosty z łososiem"},{"id":"oc-plwb-17120","title":"Salt-crusted sea bream","cuisine":"Other","category":"Main","ingredients":["4 sea bream (gutted and scaled)","45 ml lemon juice (from 1 lemon)","3 clove garlic","1 fresh thyme (1 sprig)","3 kg sea salt","2 lemon (for serving)"],"steps":["Rinse the cleaned sea bream, pat dry with paper towels, and rub the cavity with lemon juice.","Peel and halve the garlic cloves, then place them and the thyme sprig inside the fish.","Cover the base of a baking dish with a finger-thick layer of sea salt, arrange the fish on top, bury completely with the remaining salt, press down gently, and mist with water.","Cover the dish with foil, bake for about 45 minutes in an oven preheated to 250 °C, crack open the salt crust, and serve the fish with lemon wedges."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Dorada_w_soli","page":"Książka kucharska/Dorada w soli"},{"id":"oc-plwb-19272","title":"Sardine and egg salad (Sałatka z sardynek)","cuisine":"Other","category":"Salad","ingredients":["1 canned sardines (can)","1 tsp capers","to taste vinegar","2 lettuce (heads)","to taste vegetable oil","2 eggs","to taste salt"],"steps":["Hard-boil the eggs, let cool, peel, and finely chop.","Drain the canned sardines and mash them with a fork.","Wash and pat dry the lettuce, tear the leaves into bite-sized pieces, and combine with the sardines and chopped eggs.","Add the capers, drizzle the salad with oil and vinegar, season with salt, and serve chilled."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_sardynek","page":"Książka kucharska/Sałatka z sardynek"},{"id":"oc-plwb-15329","title":"Savory quark tart (Wytrawny serowiec)","cuisine":"Other","category":"Main","ingredients":["250 g all-purpose flour (for the pastry)","6 eggs (1 for the dough, 5 for the cheese filling)","125 g butter (for the pastry)","200 g cherry tomatoes (for the cheese filling)","3 bunch chives (bunches)","500 g farmer's cheese (for the cheese filling)","2 clove garlic (for the cheese filling)","300 g goat cheese log (for topping)","to taste salt (half a teaspoon for the dough, and to taste for the filling)","to taste black pepper","to taste fat (for greasing the baking pan)"],"steps":["Knead the flour with 1 egg, butter, and half a teaspoon of salt, form the dough into a ball, wrap in plastic wrap, and refrigerate for 30 minutes.","Wash the cherry tomatoes, rinse, dry, and chop the chives, reserving 1 tablespoon for garnishing before serving.","Blend the farmer's cheese with the remaining 5 eggs, garlic, salt, and pepper, then stir the chopped chives and cherry tomatoes into the mixture.","Line a greased springform pan with the chilled pastry, spread the farmer's cheese mixture over it, and arrange sliced goat cheese on top.","Bake for 50–60 minutes in an oven preheated to 200 °C, and sprinkle with the reserved chives before serving."],"time":95,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wytrawny_serowiec","page":"Książka kucharska/Wytrawny serowiec"},{"id":"oc-plwb-14998","title":"Sałatka egzotyczna (tropical fruit salad)","cuisine":"Other","category":"Salad","ingredients":["2 oranges","1 melon","1 avocado","2 bananas","3 kiwi","1 mango","2 slice pineapple","5 g raisins","0.5 lemon (juiced)","50 ml fruit juice"],"steps":["Soak the raisins in warm water until plump, then drain thoroughly.","Peel the oranges, remove any seeds and white pith, and dice the flesh.","Peel the melon, avocado, bananas, kiwi, and mango and cut into dice or slices, and chop the pineapple slices into smaller pieces.","Transfer all the fruit and drained raisins to a glass bowl, drizzle with fruit juice and the freshly squeezed lemon juice, and toss gently.","Refrigerate the salad for 2–3 hours before serving."],"time":170,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_egzotyczna","page":"Książka kucharska/Sałatka egzotyczna"},{"id":"oc-plwb-16690","title":"Sałatka miłosna (celery, pineapple, and grape salad)","cuisine":"Other","category":"Salad","ingredients":["3 tbsp wheat sprouts","1 apple","1 canned pineapple (can, drained)","3 celery (stalks with leaves reserved for garnish)","1 bunch grapes (small bunch)","150 g plain yogurt","2 tsp lemon juice","1 tsp grated horseradish","1 tsp honey","to taste salt","to taste black pepper"],"steps":["Wash the celery stalks and slice them into pieces, reserving the tender leaves for garnish.","Wash and dry the grapes, cut them in half, and slice the peeled apple thinly.","Rinse the wheat sprouts, drain the canned pineapple and cut into chunks, then place all the prepared ingredients into a salad bowl.","Whisk the plain yogurt with the horseradish, lemon juice, and honey, season with salt and pepper, pour over the salad, and garnish with the reserved celery leaves."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_mi%C5%82osna","page":"Książka kucharska/Sałatka miłosna"},{"id":"oc-plwb-14689","title":"Sałatka orientalna (oriental pepper and cucumber salad)","cuisine":"Other","category":"Salad","ingredients":["2 green bell peppers","1 cucumber","3 onions (1 for the marinade, 2 for the salad)","3 tbsp vinegar","1 clove garlic","5 black peppercorns","to taste salt","1 bay leaf","375 ml water"],"steps":["Peel one onion and the garlic clove, and finely chop them.","Pour the water and vinegar into a pot, add the chopped onion, garlic, peppercorns, bay leaf, and salt, and simmer the marinade for about 15 minutes.","Wash and dry the green bell peppers, halve them, remove the seeds, and slice the flesh into thin strips.","Add the pepper strips to the boiling marinade, parboil briefly, remove with a slotted spoon, and let the marinade cool completely.","Peel the cucumber and the remaining two onions, finely chop them, combine with the parboiled peppers, and pour over the cooled marinade."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_orientalna","page":"Książka kucharska/Sałatka orientalna"},{"id":"oc-plwb-19096","title":"Sałatka owocowa na ostro (spiced wine fruit salad)","cuisine":"Other","category":"Salad","ingredients":["2 pears","2 apples","2 peaches","4 apricots","100 g sweet cherries","4 tbsp dry white wine (for drizzling over the fruit)","200 ml dry white wine","1 tbsp olive oil","1 tbsp mustard","0.5 tsp lemon zest (grated)","0.25 tsp ground nutmeg","1.5 tsp icing sugar"],"steps":["Peel and core the pears and apples, cut the fruit into eighths, and drizzle with 4 tablespoons of dry white wine.","Pit the remaining fruit, quarter the peaches, halve the apricots, and pit the cherries.","Whisk the mustard with the olive oil and 200 ml of dry white wine, then stir in the grated lemon zest, ground nutmeg, and icing sugar.","Combine all the fruit in a large bowl, pour over the prepared dressing, and chill in the refrigerator for 60 minutes."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_owocowa_na_ostro","page":"Książka kucharska/Sałatka owocowa na ostro"},{"id":"oc-plwb-61788","title":"Sałatka pomarańczowa z bananem i pistacjami (orange, banana, and pistachio salad)","cuisine":"Other","category":"Salad","ingredients":["6 oranges","4 bananas (ripe)","60 g dark chocolate (grated)","60 g pistachios (shelled)","5 tbsp instant coffee","60 g honey (such as acacia)","2.5 tbsp orange liqueur","1 tbsp icing sugar","1 pinch ground cinnamon","20 g butter","500 ml water (for brewing coffee)"],"steps":["Scrub the oranges in hot water, peel them, julienne the zest into thin strips, blanch in boiling water and drain, and slice the fruit thinly.","Bring the instant coffee and a pinch of cinnamon to a boil in 500 ml of water, strain through a filter, and stir with the honey, grated dark chocolate, and orange liqueur until fully dissolved.","Peel the bananas, slice them thinly, combine with the orange slices and blanched zest, and pour the coffee marinade over the fruit.","Heat the shelled pistachios with butter and icing sugar in a skillet, stirring until coated in a glossy glaze, and place them on the salad before serving."],"time":30,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_pomara%C5%84czowa_z_bananem_i_orzechami_pistacjowymi","page":"Książka kucharska/Sałatka pomarańczowa z bananem i orzechami pistacjowymi"},{"id":"oc-plwb-56110","title":"Sałatka szopska (Shopska salad)","cuisine":"Other","category":"Salad","ingredients":["4 tomatoes (3–4 pieces)","1 cucumber","2 bell peppers (large, or 4 small)","1 onion","175 g sirene or feta cheese (thick slice)","3 tbsp olive oil or sunflower oil","3 olives (2–3 chopped, or 5–7 whole)","to taste parsley (chopped)","to taste salt","to taste black pepper"],"steps":["Wash the vegetables, deseed the peppers, then dice the tomatoes, cucumber, and bell peppers, and finely chop the peeled onion.","Transfer the vegetables to a salad bowl, drizzle with olive or sunflower oil, and toss gently.","Top the salad generously with coarsely grated sirene or feta cheese, chopped parsley, and olives, and season to taste with salt and pepper."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_szopska","page":"Książka kucharska/Sałatka szopska"},{"id":"oc-plwb-61783","title":"Sałatka szparagowa z kurczakiem i ananasem (asparagus, chicken, and pineapple salad)","cuisine":"Other","category":"Salad","ingredients":["700 g roast chicken (1 small whole chicken, approximately 600–800 g)","250 g fresh asparagus","200 g white grapes","1 fresh pineapple (small, ripe, juice reserved for dressing)","1 apple","200 g Greek yogurt","2 tbsp mayonnaise","1.5 tbsp soy sauce","0.5 lemon (juiced)","to taste sea salt","to taste ground white pepper"],"steps":["Peel the asparagus, cut into 2 cm pieces, cook in boiling salted water for 2–3 minutes, then drain and let cool.","Quarter the pineapple, core and peel it, and cut the flesh into 1 cm slices, reserving any released juice.","Peel the apple, dice it, and toss with a splash of lemon juice; halve the grapes and remove the seeds.","Remove the roast chicken meat from the bones, cut it into two-centimetre pieces, and combine in a bowl with the prepared fruit and asparagus.","Whisk the Greek yogurt with the mayonnaise, remaining lemon juice, reserved pineapple juice, and soy sauce, and season with sea salt and white pepper.","Pour the dressing over the salad and chill in the refrigerator for about 20 minutes before serving."],"time":28,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_szparagowa_z_kurczakiem_i_ananasem","page":"Książka kucharska/Sałatka szparagowa z kurczakiem i ananasem"},{"id":"oc-plwb-61786","title":"Sałatka szparagowa z pomidorami (asparagus and tomato salad with herb dressing)","cuisine":"Other","category":"Salad","ingredients":["600 g white asparagus","600 g green asparagus","1 green lettuce (head)","4 tomatoes (ripe)","2 tbsp fresh sorrel","0.5 bunch chives","0.5 bunch curly parsley","2 fresh chervil (sprigs)","2 lemons (juiced)","8 tbsp corn oil","1 tbsp butter","1 tsp sugar","to taste sea salt","to taste black pepper (freshly ground)"],"steps":["Peel the white asparagus and only the lower part of the green asparagus, trim the tough ends, and cut all the stalks into three-centimetre pieces.","Bring water to a boil with salt, sugar, and butter, add the white asparagus, after 5 minutes add the green asparagus, cook everything for another 10 minutes, and drain.","Blanch the tomatoes in boiling water, slip off the skins, remove the seeds, and cut the flesh into eighths.","Wash, dry, and finely chop the chives, curly parsley, and chervil, and slice the sorrel leaves into thin strips.","Wash and dry the lettuce leaves, trim away any tough ribs, and arrange on plates along with the asparagus and tomato wedges.","Whisk the freshly squeezed lemon juice with sea salt and pepper, gradually whisk in the oil until emulsified, stir in the chopped herbs and sorrel, and spoon over the salad before serving."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_szparagowa_z_pomidorami","page":"Książka kucharska/Sałatka szparagowa z pomidorami"},{"id":"oc-plwb-61793","title":"Sałatka z bakłażanów (fried aubergine salad with red pepper puree)","cuisine":"Other","category":"Salad","ingredients":["800 g aubergines","3 red bell peppers","1 lettuce (head, such as lollo rosso)","4 shallots","170 ml pine nut or almond oil (part for stewing and frying, remainder for the vinaigrette)","100 ml white wine vinegar","1 tbsp mustard","2 clove garlic","100 g pine nuts","1 bunch fresh parsley","to taste sea salt","to taste black pepper (freshly ground)"],"steps":["Wash the red bell peppers, deseed and dice the flesh, and cook gently covered in part of the heated oil with a splash of water for 10 minutes until soft.","Blend the stewed peppers into a smooth purée, pass through a fine sieve, and season with sea salt and pepper.","Slice the aubergines into 0.5 cm thick rounds, fry in heated oil until golden brown on both sides, and season with salt and pepper.","Peel and finely chop the shallots and garlic, wash and chop the parsley, then mix them with the white wine vinegar, mustard, remaining oil, salt and pepper.","Toast the pine nuts in a dry pan until golden.","Wash and dry the lettuce leaves, tear out any tough central ribs, tear into bite-sized pieces, and arrange on plates.","Arrange the fried aubergine slices over the lettuce, drizzle with the vinaigrette, spoon dollops of the red pepper purée over top, and scatter with toasted pine nuts."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_bak%C5%82a%C5%BCan%C3%B3w","page":"Książka kucharska/Sałatka z bakłażanów"},{"id":"oc-plwb-61787","title":"Sałatka z brukselki z kiełkami (Brussels sprout, lentil sprout, and grape salad)","cuisine":"Other","category":"Salad","ingredients":["1 orange (juiced)","0.5 lemon (juiced)","2 egg yolks (fresh)","4 tbsp grapeseed oil","to taste Tabasco sauce","1 pinch sugar","to taste sea salt","to taste white pepper (freshly ground)","500 g Brussels sprouts","200 g lentil sprouts","150 g grapes (any colour)","2 grapefruits","50 g almonds (blanched and chopped)"],"steps":["Whisk the orange juice, juice from half a lemon, and fresh egg yolks together, then gradually drizzle in the grapeseed oil while whisking continuously until thick and creamy.","Season the dressing with sea salt, a pinch of sugar, freshly ground white pepper, and a few drops of Tabasco sauce.","Trim the Brussels sprouts, separate the individual leaves from the cores, rinse, and blanch for 2 minutes in boiling salted water, then refresh in ice water and drain.","Rinse and dry the lentil sprouts, halve the grapes and remove any seeds, and segment the grapefruits, removing all white pith and membranes.","In a bowl, toss the Brussels sprout leaves, lentil sprouts, and halved grapes with the prepared dressing.","Arrange the salad on plates, garnish with the grapefruit segments, and sprinkle with chopped almonds."],"time":27,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_brukselki_z_kie%C5%82kami","page":"Książka kucharska/Sałatka z brukselki z kiełkami"},{"id":"oc-plwb-61835","title":"Sałatka z cukinii i orzeszków ziemnych (courgette and roasted peanut salad)","cuisine":"Other","category":"Salad","ingredients":["800 g courgettes","1 radicchio (large head)","4 tomatoes (ripe)","2 shallots","120 ml peanut oil (part for frying, remainder for vinaigrette)","100 ml white wine vinegar","1 tbsp mustard","1 bunch fresh thyme","100 g peanuts (unsalted, skinned)","to taste fresh thyme sprigs (for garnish)","to taste sea salt","to taste black pepper (freshly ground)"],"steps":["Wash the courgettes, cut into 0.5 cm thick rounds, season with salt and pepper, and fry in part of the heated peanut oil on both sides until golden.","Blanch the tomatoes in boiling water, slip off the skins, remove the seeds, and finely dice the flesh.","Preheat the oven to 250 °C, spread the peanuts on a baking sheet, and roast for about 10 minutes until golden brown.","Peel and finely mince the shallots, and rinse, dry, and chop the bunch of thyme leaves.","Whisk together the shallots, chopped thyme, mustard, and white wine vinegar, gradually pour in the remaining peanut oil while whisking, and season the vinaigrette with sea salt and pepper.","Wash and dry the radicchio, cut out any tough core parts, arrange the leaves on plates, top with the courgette slices, drizzle with vinaigrette, and scatter with diced tomatoes, roasted peanuts, and thyme sprigs."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_cukinii_i_pra%C5%BConych_orzeszk%C3%B3w_ziemnych","page":"Książka kucharska/Sałatka z cukinii i prażonych orzeszków ziemnych"},{"id":"oc-plwb-61789","title":"Sałatka z kiwi i truskawkami (kiwi and strawberry salad)","cuisine":"Other","category":"Salad","ingredients":["8 kiwis (ripe)","600 g strawberries (fresh)","2 oranges","1 lemon","100 g honey","2.5 tbsp amaretto liqueur","1 tbsp cane sugar","100 g almonds (blanched)","2 tbsp butter","1 tbsp icing sugar"],"steps":["Peel the kiwis and slice into rounds about 3 mm thick, then halve the washed and dried strawberries.","Wash the oranges and lemon in hot water, pare the zest thinly, cut into fine julienne strips, and simmer in a syrup of water and cane sugar until tender, then drain.","Squeeze the juice from the peeled oranges and lemon, then mix with the honey and amaretto liqueur.","In a bowl, combine the kiwis, strawberries, and drained citrus zest, pour over the dressing, and set aside for about 10 minutes.","Toast the blanched almonds in a skillet with the butter and icing sugar until golden brown and caramelised.","Divide the marinated fruit among salad bowls and scatter the candied almonds over the top."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_kiwi_i_truskawkami","page":"Książka kucharska/Sałatka z kiwi i truskawkami"},{"id":"oc-plwb-14156","title":"Shrimp omelette","cuisine":"Other","category":"Main","ingredients":["150 g fresh prawns","3 eggs","5 white mushrooms","2 tbsp bean sprouts","1 onion (large)","1 tsp soy sauce","2 tbsp vegetable oil","2 tbsp water (cold)","to taste salt","to taste hot ground paprika"],"steps":["Drain the prawns. Whisk the eggs with 2 tablespoons of cold water and a pinch of salt, then stir in the prawns.","Wash, peel, and finely chop the mushrooms and onion, then sauté them in a frying pan in heated oil and reduce the heat.","Combine the egg and prawn mixture with the bean sprouts and soy sauce, season with salt and hot paprika, and mix vigorously.","Pour the mixture into the pan over the mushrooms and onion. Once the underside is golden brown, carefully flip the omelette over and fry for a few minutes more."],"time":30,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krewetki_w_omlecie","page":"Książka kucharska/Krewetki w omlecie"},{"id":"oc-plwb-12557","title":"Shrimp skewers (Szaszłyki z krewetek)","cuisine":"Other","category":"Main","ingredients":["500 g shrimp","1 pickled shallots (jar)","2 red bell peppers (fresh)","to taste fish seasoning blend","100 ml olive oil","8 clove garlic (large cloves, pureed)","1 onion","4 clove garlic","125 ml dry white wine","to taste Tabasco sauce (a few drops)","to taste olive oil (for frying)"],"steps":["Mix 100 ml of olive oil with 8 blended garlic cloves, immerse the shrimp in the marinade, and chill in the refrigerator for about 120 minutes.","Cut the red bell peppers into pieces, then thread the shrimp onto skewers in a horseshoe shape wrapping around a pickled shallot, alternating with pieces of bell pepper.","Dust the skewers with fish seasoning and cook on a hot grill.","Chop the onion and 4 cloves of garlic, sauté in olive oil, add the white wine and a few drops of Tabasco sauce, and simmer for 3 minutes.","Brush the grilled skewers with the prepared sauce and serve hot."],"time":145,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szasz%C5%82yki_z_krewetek","page":"Książka kucharska/Szaszłyki z krewetek"},{"id":"oc-plwb-14618","title":"Smoked halibut and mandarin salad (Sałatka z wędzonego halibuta i mandarynki)","cuisine":"Other","category":"Salad","ingredients":["2 beetroots (cooked)","3 mandarin oranges","2 tbsp olive oil","150 g smoked halibut (sliced)","1 fresh mint (handful of leaves)"],"steps":["Cut the smoked halibut slices into smaller bite-sized pieces.","Peel the cooked beetroots and cut them into thin slices.","Peel the mandarins, separate into segments, and gently toss with the sliced beetroots and fish pieces.","Transfer the salad to a serving dish, drizzle with olive oil, and garnish with fresh mint leaves."],"time":10,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_w%C4%99dzonego_halibuta_i_mandarynki","page":"Książka kucharska/Sałatka z wędzonego halibuta i mandarynki"},{"id":"oc-plwb-17809","title":"Sole with asparagus and strawberry sauce","cuisine":"Other","category":"Main","ingredients":["1 sole fillet","10 asparagus spears","0.5 leek (piece for tying strips)","250 g spinach","15 strawberries","500 ml vegetable broth","80 ml white wine","1 tbsp butter","0.5 clove garlic","1 onion (small)","to taste tabasco sauce","to taste salt","to taste black pepper"],"steps":["Roll the sole fillet into roulades, tie them with blanched leek strips, and simmer along with the asparagus in vegetable broth combined with white wine.","Finely chop the onion and garlic, cook in part of the butter until translucent, add the spinach, sauté, and season with salt and pepper.","Wash the strawberries, blend them, glaze in the remaining melted butter, and season with a dash of tabasco sauce.","Arrange the sautéed spinach, asparagus, and sole roulades on a plate, and drizzle everything with the strawberry sauce."],"time":30,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sola_w_sosie_truskawkowym","page":"Książka kucharska/Sola w sosie truskawkowym"},{"id":"oc-plwb-19274","title":"Spiced braised root vegetables with corn (Warzywa na sposób orientalny)","cuisine":"Other","category":"Side","ingredients":["300 g canned sweetcorn (drained)","1 celeriac","2 carrots","1 parsley root","1 onion","1 clove garlic","to taste pepper","to taste salt","to taste ginger","to taste ground nutmeg","to taste curry powder","to taste vegetable oil (for frying the onion)","to taste water (for braising the vegetables)"],"steps":["Peel the carrots, parsley root, and celeriac, and grate them on the coarse side of a grater.","Peel and chop the onion, then sauté it in hot oil.","Add the grated root vegetables, drained sweetcorn, and crushed garlic clove, season with salt, pepper, ginger, nutmeg, and curry powder, then pour in a splash of water.","Braise the vegetables covered over low heat for about 15 minutes until tender, adding a little water if needed."],"time":35,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Warzywa_na_spos%C3%B3b_orientalny","page":"Książka kucharska/Warzywa na sposób orientalny"},{"id":"oc-plwb-17641","title":"Spiced hot chocolate","cuisine":"Other","category":"Drink","ingredients":["1 l milk","2 whole cloves","1 cinnamon stick","100 g chocolate","to taste almond flavouring (a few drops)","to taste whipped cream (for garnish)"],"steps":["Heat the milk gently in a saucepan along with the cinnamon stick and cloves.","Finely chop the chocolate, add it to the hot milk, and stir over low heat until completely melted and smooth.","Strain the drink through a sieve, add a few drops of almond flavouring, and froth with a mixer.","Pour the hot chocolate into cups or mugs and crown with whipped cream."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Czekolada_na_gor%C4%85co","page":"Książka kucharska/Czekolada na gorąco"},{"id":"oc-plwb-5654","title":"Spicy garlic prawns in white wine","cuisine":"Other","category":"Main","ingredients":["500 g prawns (large, peeled (e.g. black tiger, frozen))","1 onion","3 chili pepper (small, very hot)","3 clove garlic","125 ml grapeseed oil","2 tbsp mayonnaise (large tablespoons)","1 fresh rosemary (sprig)","250 ml semi-dry white wine"],"steps":["Finely chop the onion, slice the garlic thinly, and deseed the chili peppers and cut them into strips.","Heat the grapeseed oil in a frying pan, add the onion and garlic, and cook until translucent without browning.","Add the chili strips and fry briefly.","Pour in the white wine, strip the leaves from the rosemary sprig into the pan, and reduce the liquid over high heat.","Add the prawns and cook over high heat until any released liquid evaporates, the prawns curl, and their tails turn pink.","Stir in the mayonnaise right in the pan and serve immediately while hot."],"time":null,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Krewetki_%E2%80%9Enajlepsze%E2%80%9D","page":"Książka kucharska/Krewetki „najlepsze”"},{"id":"oc-plwb-15767","title":"Spicy pasta bake (Zapiekanka pikantna)","cuisine":"Other","category":"Main","ingredients":["1 kg minced meat","500 g tomatoes","500 g button mushrooms","3 tomato purée (small cans)","500 g pasta","400 g firm cheese (grated)","2 onions","3 allspice (berries)","to taste vegetable oil (for frying and greasing the dish)","to taste hot paprika powder","1 bay leaf (leaf)","to taste chili","to taste salt","to taste black pepper"],"steps":["Cook the pasta until al dente, rinse with cold water, and drain.","Fry the minced meat with chopped onion and seasonings (allspice, bay leaf, hot paprika, chili, salt, and pepper).","Clean the button mushrooms and fry them in oil, adding the peeled and diced tomatoes towards the end of frying.","Combine the mushrooms and tomatoes with the browned meat and stir in the tomato purée.","Grease an ovenproof baking dish, arrange alternating layers of pasta and meat filling, and sprinkle the top with grated firm cheese.","Bake for about 20 minutes in an oven preheated to 200 °C."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_pikantna","page":"Książka kucharska/Zapiekanka pikantna"},{"id":"oc-plwb-16999","title":"Spiked iced tea with rum and lemon","cuisine":"Other","category":"Drink","ingredients":["250 ml strong brewed black tea","2 tsp sugar","1 tsp rum","to taste ice cubes (several cubes)","to taste lemon peel (several strips)","2 slice lemon","to taste fresh lemon balm (leaves)"],"steps":["Cool the brewed tea, stir in the sugar, rum, and lemon peel, and chill in the refrigerator.","Fill a tall glass one-third full with ice cubes and pour in the cold tea.","Garnish the drink with lemon slices and fresh lemon balm leaves."],"time":10,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Herbata_mro%C5%BCona","page":"Książka kucharska/Herbata mrożona"},{"id":"oc-plwb-18808","title":"Strawberry and red wine sorbet","cuisine":"Other","category":"Dessert","ingredients":["300 g strawberries","100 g sugar","125 ml red wine","1 egg white","1 pomegranate (seeds for garnish)","to taste lime (slices for garnish)"],"steps":["Puree the strawberries until smooth, dissolve the sugar in the red wine, and whip the egg white to stiff peaks.","Combine the strawberry puree with the sweetened wine and whipped egg white, cover, and place in the freezer for 180 minutes, stirring several times during freezing.","Transfer the sorbet from the freezer to the top refrigerator shelf 15 minutes before serving.","Break up the slightly softened sorbet, blend briefly, spoon into chilled dessert dishes, and serve immediately garnished with pomegranate seeds and lime slices."],"time":210,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sorbet_z_czerwonym_winem","page":"Książka kucharska/Sorbet z czerwonym winem"},{"id":"oc-plwb-55025","title":"Strawberry lemonade","cuisine":"Other","category":"Drink","ingredients":["500 g strawberries (fresh or frozen)","1 lemon","1 l water (still or sparkling)","3 tbsp powdered sugar","to taste ice cubes","to taste fresh mint (leaves)"],"steps":["Wash the strawberries under cold running water, hull them, and place into a tall container or blender jug.","Squeeze the lemon juice over the strawberries, add a few fresh mint leaves and 3 tablespoons of powdered sugar, and blend into a smooth puree.","Pour the strawberry puree into a pitcher, add 1 l of water, stir thoroughly, and serve with ice cubes and the remaining mint."],"time":10,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_truskawkowa","page":"Książka kucharska/Lemoniada truskawkowa"},{"id":"oc-plwb-55056","title":"Strawberry mint lemonade","cuisine":"Other","category":"Drink","ingredients":["500 g strawberries (sweet)","1 bunch fresh mint","0.5 lemon (juiced)","0.5 lemon (sliced)","3 tbsp powdered sugar or honey (several tablespoons)","1.5 l mineral water (chilled, sparkling or still)","to taste ice cubes (optional)"],"steps":["Wash the strawberries, remove the hulls, add the washed mint leaves, and blend with a blender into a smooth puree.","Add powdered sugar or honey, juice from half a lemon, and 1.5 l of chilled mineral water, stir thoroughly, and strain through a sieve if desired.","Place ice cubes and slices from the other half of the lemon into tumblers and pour in the strawberry lemonade."],"time":10,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_truskawkowa_z_mi%C4%99t%C4%85","page":"Książka kucharska/Lemoniada truskawkowa z miętą"},{"id":"oc-plwb-10362","title":"Stuffed melon with berries and orange liqueur","cuisine":"Other","category":"Dessert","ingredients":["2 melon (ripe, small)","300 g raspberries (or redcurrants)","60 ml orange liqueur","100 g powdered sugar","to taste lemon juice","to taste almonds (sweet)"],"steps":["Wash the melons thoroughly, cut in half, scoop out the seeds, and scoop the flesh into small balls, leaving a layer of about 5 mm next to the rind.","Hull the raspberries, rinse, and leave in a sieve to drain.","Combine the raspberries with the melon balls, drizzle with the orange liqueur, dust with powdered sugar, season with lemon juice, and chill in the refrigerator together with the hollowed-out melon halves.","Scald the almonds, peel off the skins, chop, and mix with the chilled fruits, then spoon the salad into the melon halves."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Melon_nadziewany","page":"Książka kucharska/Melon nadziewany"},{"id":"oc-plwb-16997","title":"Stuffed Pineapple Fruit Salad","cuisine":"Other","category":"Salad","ingredients":["1 fresh pineapple","1 orange","1 apple","100 g strawberries","2 tbsp honey","to taste vanilla flavouring","to taste lemon juice"],"steps":["Slice off and reserve the leafy top of the pineapple, scoop out the flesh from the base, chop it finely, and save any released juice.","Peel and core the apple, dice the flesh finely, and toss with lemon juice to prevent browning.","Peel the orange, remove the bitter white membranes from the segments, and cut into bite-sized pieces.","Combine the chopped pineapple and orange pieces with the reserved juice, honey, and vanilla flavouring, then add the diced apple and sliced strawberries.","Fill the hollowed pineapple shell with the fruit salad, cover with the reserved top, and chill in the refrigerator before serving."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ananas_nadziewany","page":"Książka kucharska/Ananas nadziewany"},{"id":"oc-plwb-19524","title":"Sudovian breaded pork roulades (Zawijasy z Sudowy)","cuisine":"Other","category":"Main","ingredients":["800 g pork (e.g. pork loin or leg cutlets)","1 egg (for breading)","to taste salt","to taste black pepper","to taste breadcrumbs (for breading)","2 tbsp clarified butter (for frying the rolls)","6 bay leaf (leaves, to fasten the sides of the rolls)","2 cooked carrots (for the filling)","150 g ham (for the filling)","2 onions (for the filling)","1 tbsp butter (for sautéing the filling)","250 ml white wine (for the sauce)","250 ml sour cream (for the sauce)","3 tbsp butter (cold, for thickening the sauce)"],"steps":["Slice the pork into cutlets, pound with a mallet, and season with salt and pepper.","Chop the cooked carrot, ham, and onions, and sauté together in 1 tablespoon of butter.","Spread the filling over the pork cutlets, roll them up, and secure with toothpicks, affixing bay leaves at each side where the toothpicks are inserted.","Dredge the roulades in beaten egg and breadcrumbs, and fry on all sides in clarified butter.","Pour the white wine and sour cream into the pan drippings, season with salt and pepper, and bring to a boil. Stir constantly while adding 3 tablespoons of cold butter a piece at a time, then pour the sauce over the roulades."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zawijasy_z_Sudowy","page":"Książka kucharska/Zawijasy z Sudowy"},{"id":"oc-plwb-10348","title":"Sweet and spicy skewers (Szaszłyki słodko-pikantne)","cuisine":"Other","category":"Main","ingredients":["250 g cooked ham","10 peaches (ripe)","1 orange","to taste vegetable oil","to taste pepper","to taste fresh lemon balm (leaves)"],"steps":["Wash the peaches, cut into quarters, and remove the pits.","Scrub the orange, grate a little zest, peel the fruit, divide into segments, and slice each crosswise into three pieces.","Cut the cooked ham into thick slices, then cut into quarters.","Thread onto skewers alternately pieces of ham, peach, a lemon balm leaf, and a piece of orange.","Brush the skewers with oil, sprinkle with grated orange zest and pepper, and grill away from direct flame until lightly browned."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szasz%C5%82yki_s%C5%82odko-pikantne","page":"Książka kucharska/Szaszłyki słodko-pikantne"},{"id":"oc-plwb-16030","title":"Sweet and spicy turkey stew with pineapple","cuisine":"Other","category":"Main","ingredients":["750 g turkey thigh (boneless)","2 red bell pepper","3 carrots","2 red onion","4 slice canned pineapple (rings)","5 tbsp olive oil","250 ml broth","1 tbsp rice vinegar","0.5 tsp ground ginger","0.5 tsp hot ground paprika","1 pinch ground cinnamon","to taste salt"],"steps":["Dice the turkey meat and brown in a saucepan in heated olive oil.","Add the diced red onion and fry, stirring constantly, until golden.","Pour in the hot broth and rice vinegar, add the ground ginger, hot paprika, cinnamon, and salt, then braise covered.","Peel the carrots and cut into thin matchsticks, cut the bell pepper into strips, and cut the pineapple rings into pieces.","When the meat is almost tender, add the carrots, bell pepper, and pineapple, and braise everything until tender."],"time":65,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gulasz_z_ananasem","page":"Książka kucharska/Gulasz z ananasem"},{"id":"oc-plwb-15510","title":"Sweet baked chicken with fruit","cuisine":"Other","category":"Main","ingredients":["1 whole chicken","1 canned peaches in syrup (can)","2 apples (large)","to taste raisins","125 ml wine","1 orange (large)","to taste all-purpose vegetable seasoning (such as Vegeta)","to taste olive oil"],"steps":["Pour the wine over the raisins and leave to soak for about 60 minutes.","Cut the chicken into portions, rub with vegetable seasoning, and set aside for 30 minutes.","Transfer the chicken to a baking dish, drizzle with olive oil, and bake in an oven preheated to 180 °C for 45 minutes.","Arrange the sliced apples, peaches, and orange segments around the meat, scatter over the raisins, and pour over the soaking wine mixed with syrup from the peach can.","Bake everything for another 30 minutes."],"time":75,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_na_s%C5%82odko_z_owocami","page":"Książka kucharska/Kurczak na słodko z owocami"},{"id":"oc-plwb-14752","title":"Tarator (Bulgarian cold cucumber soup)","cuisine":"Other","category":"Soup","ingredients":["400 g kefir","1 cucumber (large)","2 clove garlic","1 bunch fresh dill","2 tbsp vegetable oil","to taste salt","to taste pepper"],"steps":["Peel the cucumber and cut it into fine dice.","Mix the kefir thoroughly with the oil.","Peel the garlic, mince it finely, and mash with a pinch of salt.","Rinse, dry, and finely chop the fresh dill, then combine all ingredients and season the cold soup to taste with salt and pepper."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tarator","page":"Książka kucharska/Tarator"},{"id":"oc-plwb-14379","title":"Tilapia with chanterelles, porcini, and rosemary (Tilapia z kurkami, borowikami i rozmarynem)","cuisine":"Other","category":"Main","ingredients":["300 g tilapia (fillet)","140 g penne pasta (dry)","1 beetroot","1 onion","3 tbsp truffle oil","400 ml red wine","100 ml white wine","1 tbsp butter","100 g chanterelles","100 g porcini mushrooms","to taste rosemary","to taste fresh parsley","to taste lemon pepper","1 bay leaf","to taste salt"],"steps":["Marinate the fish with lemon pepper and part of the truffle oil.","Clean the chanterelles and porcini, sauté them with the chopped onion in butter, pour in the white wine, and set aside.","Cook the beetroot until tender in red wine with the bay leaf, then slice it.","Cook the penne pasta in salted water, drain, and toss with the chanterelle and porcini sauce, seasoning with salt, pepper, rosemary, and chopped fresh parsley.","Pan-fry the marinated fish, arrange it on plates alongside the mushroom pasta and beetroot slices, and drizzle everything with the remaining truffle oil."],"time":65,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tirapia_z_kurkami%2C_borowikami_i_rozmarynem","page":"Książka kucharska/Tirapia z kurkami, borowikami i rozmarynem"},{"id":"oc-plwb-12828","title":"Tomato and mushroom tart (Tarta z pomidorami)","cuisine":"Other","category":"Main","ingredients":["250 g coarse wheat flour (krupczatka)","150 g butter (plus extra for greasing the tin)","1 tsp caster sugar (heaped)","1 tsp salt (level)","3 tbsp cold water (added tablespoon by tablespoon to bind the dough)","150 g button mushrooms","400 g tomatoes","150 g canned sweetcorn","200 g firm cheese","to taste fresh basil (leaves)","to taste oregano","to taste thyme"],"steps":["Sift the flour with the sugar and salt, add the diced butter, chop with a knife into fine crumbs, and rub together with your fingertips.","Add the cold water tablespoon by tablespoon and knead into a springy, uniform dough, then wrap in cling film and refrigerate for 30 minutes.","Preheat the oven to 190 °C, wash and slice the tomatoes into rounds, slice the button mushrooms and firm cheese, drain the sweetcorn, and prepare the basil leaves.","Divide the chilled dough into two portions in a 2/3 and 1/3 ratio, roll out the larger portion, and press it into the bottom and sides of a buttered 28 cm tart tin.","Arrange a layer of firm cheese, button mushrooms, tomatoes, and basil leaves over the base, sprinkle with sweetcorn, oregano, and thyme, and top with another layer of cheese, tomatoes, and mushrooms, pressing the filling down gently.","Roll out the remaining portion of dough, cover the filling, and bake for 50 minutes, making sure the edges do not burn."],"time":110,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tarta_z_pomidorami","page":"Książka kucharska/Tarta z pomidorami"},{"id":"oc-plwb-14310","title":"Tomato tartlets (Tartaletki z pomidorami)","cuisine":"Other","category":"Snack","ingredients":["500 g tomatoes (firm)","1 tsp potato starch","to taste salt (half a teaspoon for the dough and to taste for the filling)","to taste sugar","to taste fresh mint or basil (fresh leaves for garnish)","125 g plain flour","125 g margarine","100 g farmer's cheese (minced)"],"steps":["Sift the plain flour onto a pastry board, add half a teaspoon of salt, the margarine, and minced farmer's cheese, quickly knead into a dough, wrap in cling film, and refrigerate for 30 minutes.","Roll out the chilled dough into a thin sheet, line tartlet tins with it, and bake until golden in an oven preheated to 200 °C for 15–20 minutes.","Wash the tomatoes, cut them into quarters, transfer to a saucepan, and simmer over low heat for about 15 minutes until completely broken down.","Pass the cooked tomatoes through a sieve, reheat the purée, season with salt and sugar, then thicken with the potato starch dissolved in a splash of water and simmer briefly.","Remove the cooled tartlets from the tins, fill them with the thick tomato purée, and garnish with fresh mint or basil leaves."],"time":95,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tartaletki_z_pomidorami","page":"Książka kucharska/Tartaletki z pomidorami"},{"id":"oc-plwb-7766","title":"Tuna and rice salad (Sałatka z tuńczyka)","cuisine":"Other","category":"Salad","ingredients":["2 tuna in brine (cans)","300 ml cooked rice (fluffy, grains separated)","2 red onions","4 tomatoes (large, peeled)","to taste lettuce (leaves for serving)","to taste fresh greens (for garnish)","3 tbsp spicy ketchup","2 tbsp olive oil (or vegetable oil)","4 tbsp lemon juice (freshly squeezed)","1 tsp icing sugar"],"steps":["Thoroughly mix together the ketchup, olive oil, lemon juice, and icing sugar, then set the dressing aside in a cool place for 30 minutes.","Drain the canned tuna in a sieve and flake it into bite-sized chunks.","Finely chop the red onions, and cut the peeled tomatoes into wedges.","Combine the cooked rice with the chilled dressing, add the tuna, onion, and tomatoes, and gently toss.","Cover the salad bowl with cling film or foil and chill in the refrigerator for several hours.","Serve the well-chilled salad on crisp lettuce leaves, garnished with chopped fresh greens."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_tu%C5%84czyka","page":"Książka kucharska/Sałatka z tuńczyka"},{"id":"oc-plwb-18080","title":"Turkey and baby corn skewers (Szaszłyki z indyka i kukurydzy)","cuisine":"Other","category":"Main","ingredients":["200 g turkey breast fillet","12 button mushrooms","4 red onions (small)","100 g pork belly","12 baby corn cobs","1 red bell pepper","6 tbsp vegetable oil","2 tbsp wine vinegar","1 tbsp thyme","to taste salt","to taste pepper"],"steps":["Cut the turkey breast fillet into cubes.","Mix the wine vinegar with oil, thyme, salt, and pepper, pour over the meat, and marinate for 15 minutes.","Clean the button mushrooms, peel the red onions and halve them lengthwise, halve the baby corn cobs, and cut the pork belly and red bell pepper into chunks.","Thread alternately turkey, bell pepper, pork belly, onion, mushrooms, and corn onto skewers, sprinkle with salt and pepper, and bake for about 20 minutes, turning occasionally."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Szasz%C5%82yki_z_indyka_i_kukurydzy","page":"Książka kucharska/Szaszłyki z indyka i kukurydzy"},{"id":"oc-plwb-19113","title":"Two-bean casserole (Zapiekanka z fasoli)","cuisine":"Other","category":"Main","ingredients":["100 g Romano flat green beans","150 g minced meat","1 canned white beans (can)","1 tomato","0.5 yellow bell pepper (half)","1 onion","100 ml meat broth","2 tbsp white wine","1 tbsp olive oil","3 fresh marjoram (sprigs)","to taste water (for boiling green beans)","to taste salt","to taste black pepper"],"steps":["Trim the green beans, cut into pieces, boil for 6–8 minutes in salted water, and drain.","Heat the olive oil in a skillet, add the minced meat, season with salt and pepper, and fry for about 5 minutes.","Add the diced onion and bell pepper cut into small pieces to the meat and fry, stirring, for another 5 minutes.","Drain the canned white beans, and cut the tomato into eighths; add them along with the cooked green beans one minute before the end of frying.","Pour the broth and white wine over everything, cook for 5 minutes, and sprinkle with fresh marjoram leaves before serving."],"time":35,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zapiekanka_z_fasoli","page":"Książka kucharska/Zapiekanka z fasoli"},{"id":"oc-plwb-15409","title":"Utopence (Czech pickled sausages)","cuisine":"Other","category":"Preserve","ingredients":["8 sausages (Czech špekáčky or Polish serdelki)","2 red onions","3 white onions (ordinary)","3 clove garlic","2 sweet bell peppers (red or green)","2 chili peppers","2 fresh dill (sprigs)","1 l water","500 ml vinegar","2 tbsp granulated sugar","1 tsp salt","1 tsp black peppercorns","1 tsp allspice berries","1 pinch hot chili powder","2 fresh lovage (sprigs)","5 bay leaves"],"steps":["Bring the water, vinegar, sugar, salt, peppercorns, allspice, pinch of chili, lovage, and bay leaves to the boil, then set the brine aside to cool completely to room temperature.","Peel the casings off the sausages (you can dip them in boiling water for 30 seconds beforehand and cool them), then slice them lengthwise into halves or quarters.","Slice the red and white onions into thin rounds, cut the sweet peppers and chili peppers into strips or rings, and mix the vegetables with the finely chopped garlic.","Pack the vegetables and sliced sausages tightly in alternating layers into a large jar, pour over the cooled brine, and top with the dill sprigs and bay leaves from the marinade.","Seal the jar tightly and leave in a cool place at 15–18 °C for 1–2 weeks (or for a minimum of 3 days)."],"time":10,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Utopence","page":"Książka kucharska/Utopence"},{"id":"oc-plwb-14616","title":"Valentine's sorbet cocktail","cuisine":"Other","category":"Drink","ingredients":["1 raspberry or blueberry sorbet (tub)","150 ml currant juice","75 ml vodka (chilled)"],"steps":["Transfer the raspberry or blueberry sorbet to a blender jar, pour in the currant juice and chilled vodka, and blend until smooth.","Pour the cocktail into chilled dessert glasses and serve immediately."],"time":5,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sorbet_walentynkowy","page":"Książka kucharska/Sorbet walentynkowy"},{"id":"oc-plwb-56120","title":"Vegan wholemeal streusel","cuisine":"Other","category":"Other","ingredients":["200 g wholemeal flour","50 g cane sugar","125 g vegan margarine (melted)"],"steps":["Place the wholemeal flour and cane sugar into a bowl, then pour in the melted vegan margarine.","Work the ingredients together with your fingers (or first with a mixer dough hook, then finishing by hand) until they form cohesive crumbs ready to scatter over the cake."],"time":10,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kruszonka_wega%C5%84ska","page":"Książka kucharska/Kruszonka wegańska"},{"id":"oc-plwb-15382","title":"Vegetarian vegetable stew","cuisine":"Other","category":"Main","ingredients":["2 yellow bell pepper","2 red bell pepper","1 eggplant","1 zucchini (large)","1 onion","1 clove garlic","2 tbsp olive oil","50 g black olives","125 ml vegetable broth","to taste fresh basil (sprigs)","to taste salt","to taste black pepper"],"steps":["Wash the vegetables, halve the eggplant lengthwise, sprinkle with salt and set aside for several minutes, then cut into pieces.","Deseed the yellow and red bell peppers and cut into pieces, slice the peeled onion into rings, and slice the zucchini into rounds.","Heat the olive oil in a pan, cook the onion until translucent, add the peppers, eggplant, zucchini, and chopped garlic, season with salt, and fry for 5 minutes.","Pour in the vegetable broth and cook gently, covered, for 20 minutes.","Add the black olives and basil, simmer for a few moments longer, and season to taste with salt and black pepper."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gulasz_wegetaria%C5%84ski","page":"Książka kucharska/Gulasz wegetariański"},{"id":"oc-plwb-55029","title":"Watermelon lemonade","cuisine":"Other","category":"Drink","ingredients":["500 g lemon","500 g lime","1 watermelon (medium)","6 tbsp sugar","500 ml water (still or sparkling)"],"steps":["Grate 1 teaspoon each of lemon and lime zest, and squeeze the juice from the fruits.","Transfer the watermelon flesh into a blender, pour in the lemon and lime juice, add the grated citrus zest and 6 tablespoons of sugar.","Blend the ingredients until smooth and the sugar is completely dissolved.","Pour in 500 ml of water, stir again, transfer into a pitcher, and refrigerate to chill."],"time":15,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Lemoniada_arbuzowa","page":"Książka kucharska/Lemoniada arbuzowa"},{"id":"oc-plwb-14470","title":"Zupa gulaszowa z kasztanami i winem (Goulash soup with chestnuts and wine)","cuisine":"Other","category":"Soup","ingredients":["450 g turkey meat (or beef (turkey in ingredient list, beef in method))","1 onion","2 fresh thyme (sprigs)","to taste vegetable oil (small amount for frying)","300 ml poultry broth (turkey broth)","200 g sweet chestnuts (canned)","2 carrots","250 ml dry red wine","to taste rye flour (for dusting the meat)"],"steps":["Cut the meat into small pieces, dust with rye flour, and fry in a small amount of hot oil until lightly browned.","Add the finely chopped onion and fry until golden.","Add the thyme sprigs, pour in the red wine and broth, bring to a boil, then reduce heat and braise covered for 60 minutes.","Add the sliced carrots and canned chestnuts and simmer for another 60 minutes until all ingredients are tender."],"time":145,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_gulaszowa_z_kasztanami_i_winem","page":"Książka kucharska/Zupa gulaszowa z kasztanami i winem"},{"id":"oc-plwb-27351","title":"Zupa kremowa z dyni (Cream of pumpkin soup)","cuisine":"Other","category":"Soup","ingredients":["1.5 kg pumpkin (or carrots)","2 oranges (large, for juice)","1 onion (large)","2 tbsp fresh ginger (grated)","2 tbsp butter","2 tbsp vegetable oil","1 tsp cinnamon","500 ml vegetable broth","to taste salt","to taste pepper","to taste sour cream (for finishing)","to taste croutons (or choux pastry puffs, for serving)"],"steps":["Cut the pumpkin into quarters, scoop out seeds and fibrous pulp, slice the firm flesh, peel off skin, and grate on a coarse grater.","Grate the fresh ginger, and peel and dice the onion.","Place the grated pumpkin, ginger, and onion in a pot, add the butter and oil, and cook gently covered until completely tender and beginning to break down.","Pour in the vegetable broth and squeezed orange juice and simmer gently for a few minutes (you may substitute carrots for pumpkin, slightly increasing the amount of broth).","Add the cinnamon, salt, and pepper, and simmer over low heat for another 10–15 minutes.","Blend the soup into a smooth cream, stir in the sour cream, and serve with croutons or choux pastry puffs."],"time":55,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_kremowa_z_dyni","page":"Książka kucharska/Zupa kremowa z dyni"},{"id":"oc-plwb-13990","title":"Zupa kremowa z kukurydzy (Cream of corn soup)","cuisine":"Other","category":"Soup","ingredients":["2 canned sweetcorn (large cans)","250 g potatoes","4 spring onions (bulbs)","800 ml vegetable broth","200 ml sour cream","1 tbsp ground sweet paprika","3 tbsp olive oil","to taste salt","to taste pepper"],"steps":["Mix the ground sweet paprika with the olive oil and set aside.","Peel, rinse, and finely dice the potatoes, place in a pot, add half of the sweetcorn, vegetable broth, and sour cream, season with salt and pepper, and cook covered for 15 minutes.","Peel the spring onions and slice into thin rings.","Let the soup cool slightly and blend until smooth, then add the sliced spring onion bulbs and the remaining sweetcorn.","Stir everything together and cook for about 3 minutes more.","Season to taste with salt and pepper, and drizzle with the paprika oil before serving."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_kremowa_z_kukurydzy","page":"Książka kucharska/Zupa kremowa z kukurydzy"},{"id":"oc-plwb-18820","title":"Zupa kremowa z orzechów (Walnut cream soup)","cuisine":"Other","category":"Soup","ingredients":["120 g walnuts (1 glass)","3 tbsp wheat flour","3 tbsp butter","2 onions","1 apple","750 ml vegetable broth","300 ml milk","200 ml sour cream","1 orange (zest and squeezed juice)","1 tsp curry powder","1 pinch nutmeg","to taste parsley (chopped)","to taste salt","to taste pepper"],"steps":["Grate the zest from the washed orange and squeeze out its juice.","Peel and chop the onions, cook until translucent in melted butter, then add the chopped walnuts and the peeled, diced apple.","Dust the ingredients with the flour, curry powder, and nutmeg, and stir briefly.","Pour in the broth, milk, and orange juice, add the grated orange zest, and simmer over low heat for 15–20 minutes.","Blend the soup into a smooth cream and season to taste with salt and pepper.","Stir the sour cream into the slightly cooled soup, mix thoroughly, and sprinkle with chopped parsley before serving."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_kremowa_z_orzech%C3%B3w","page":"Książka kucharska/Zupa kremowa z orzechów"},{"id":"oc-plwb-56151","title":"Zupa kurban (Bulgarian lamb kurban chorba)","cuisine":"Other","category":"Soup","ingredients":["550 g lamb (500–600 g, or mutton)","1 onion","1 carrot","2 potatoes","1 hot red chili pepper (pod)","2.5 bay leaves (2–3 leaves)","4.5 allspice (4–5 berries)","to taste mint","to taste pepper","to taste salt","to taste water (cold, to cook the meat)","to taste vegetable oil (a little for lightly frying the pepper)"],"steps":["Wash the lamb or mutton, place in a pot, and cover with cold salted water.","Add the peeled halved onion, roughly chopped carrot and potatoes, bay leaves, allspice, pepper, and mint.","Simmer the soup over low heat for about 2 hours until the meat becomes completely tender (in the traditional ritual version, the meat is simmered only in salted water without vegetables).","Towards the end of cooking, add the lightly fried hot red chili pepper and season the soup to taste."],"time":135,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_kurban","page":"Książka kucharska/Zupa kurban"},{"id":"oc-plwb-13135","title":"Zupa marchwiowa z curry (Carrot curry soup)","cuisine":"Other","category":"Soup","ingredients":["500 g carrots","800 ml broth","150 ml sour cream","4 tbsp butter","2 onions","1 clove garlic (clove)","1 apple","2 tbsp wheat flour","1 tbsp chives (chopped)","2 tsp ginger","1 tbsp curry powder","1 egg yolk (for whisking with sour cream)","to taste salt"],"steps":["Peel and chop the onions and garlic, and peel and grate the carrots and apple.","Melt the butter in a saucepan, add the onions, garlic, apple, carrots, and ginger, and fry everything together.","Dust the vegetables with the flour and curry powder, stir, and pour in the broth.","Cook the soup covered for about 10 minutes.","Whisk the sour cream with the egg yolk, pour into the soup, mix thoroughly, and bring briefly to a boil.","Season to taste with salt, and just before serving sprinkle with the chopped chives."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_marchwiowa_z_curry","page":"Książka kucharska/Zupa marchwiowa z curry"},{"id":"oc-plwb-14448","title":"Zupa pomidorowo-czosnkowa (Tomato and garlic soup)","cuisine":"Other","category":"Soup","ingredients":["5 tomatoes","3 clove garlic (cloves)","500 ml vegetable broth (2 glasses, from stock cube)","2 tbsp vegetable oil","to taste lemon juice","to taste salt","to taste pepper","to taste parsley (chopped)"],"steps":["Scald the tomatoes with boiling water, peel off the skins, and chop finely.","Peel and very finely chop the garlic, and wash, dry, and chop the parsley.","Heat the oil in a pot, add the garlic, tomatoes, and part of the parsley, and fry for 10 minutes, stirring frequently.","Pour in the hot vegetable broth and bring everything to a boil.","Season the soup with salt, pepper, and lemon juice, ladle into bowls, and sprinkle with the remaining parsley."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_pomidorowo-czosnkowa","page":"Książka kucharska/Zupa pomidorowo-czosnkowa"},{"id":"oc-plwb-14424","title":"Zupa serowa (Quick cheese soup)","cuisine":"Other","category":"Soup","ingredients":["1 onion","1 tsp butter (for cooking the onion gently covered and rubbing with flour)","500 ml vegetable broth (2 glasses)","1 bay leaf (leaf)","50 g firm cheese (grated)","0.5 tsp wheat flour","to taste salt","to taste pepper"],"steps":["Peel and finely chop the onion.","Melt the butter in a pot, add the onion, and cook gently covered for 5 minutes, taking care that it does not brown.","Add the bay leaf, pour in the vegetable broth, and thicken the soup with the flour rubbed with a little butter, stirring vigorously.","Simmer over low heat for 5 minutes, then season with salt and pepper, add the grated firm cheese, and stir thoroughly.","Remove the bay leaf before serving and serve the soup with cheese toasts."],"time":15,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_serowa","page":"Książka kucharska/Zupa serowa"},{"id":"oc-plwb-17119","title":"Zupa serowa zapiekana (Baked cheese soup)","cuisine":"Other","category":"Soup","ingredients":["2 chicken and vegetable stock cubes (cubes)","2 onions","4 tbsp butter","1 tbsp wheat flour","500 ml milk (2 glasses)","500 g firm cheese (grated)","to taste salt","to taste pepper","1 l water (boiling water to dissolve the stock cubes)"],"steps":["Pour 1 litre of boiling water over the stock cubes and stir until dissolved.","Peel the onions, dice them, and cook until translucent in heated butter in a pot.","Add the flour and fry together with the onions for about 2 minutes, then gradually pour in the hot broth, stirring constantly.","Cook the soup for 10 minutes, stirring frequently.","Pour in the milk, season with salt and pepper, and stir in the grated firm cheese.","Pour the soup into an ovenproof dish, place in an oven preheated to 180 °C, and bake for 15 minutes; serve with croutons."],"time":40,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_serowa_zapiekana","page":"Książka kucharska/Zupa serowa zapiekana"},{"id":"oc-plwb-56134","title":"Zupa soczewicowa (Bulgarian lentil soup / Leshta supa)","cuisine":"Other","category":"Soup","ingredients":["200 g lentils","80 ml olive oil (1/3 glass)","1 bell pepper (fresh)","2 tomatoes","1 carrot","1 onion","0.5 leek (half)","1 tsp ground sweet paprika","to taste salt","1.75 l water (1.5–2 l)"],"steps":["Rinse the lentils, place in a pot, pour in 1.5–2 l of water and the olive oil.","Peel and finely chop the onion, carrot, leek, and fresh bell pepper, and add to the pot.","Stir in the ground sweet paprika and salt to taste (optionally add crushed garlic mixed with a splash of vinegar).","Simmer the soup over low heat until the lentils are completely tender.","Add the finely diced tomatoes and cook for another 5 minutes."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_soczewicowa","page":"Książka kucharska/Zupa soczewicowa"},{"id":"oc-plwb-18579","title":"Zupa szpinakowa (Spinach soup with chicken and cinnamon)","cuisine":"Other","category":"Soup","ingredients":["500 g spinach (fresh or frozen)","1.5 l broth (6 glasses of broth)","150 g chicken meat (finely chopped)","1 chicken stock cube (cube)","1 cinnamon stick (stick)","2 tbsp finely ground corn flour","to taste salt","to taste pepper","125 ml water (half a glass, for mixing with the corn flour)"],"steps":["Wash the fresh spinach and finely chop or blend it (if using frozen, thaw and blend into a purée).","Heat the broth in a deep saucepan, add the finely chopped chicken, and bring to a boil.","Add the spinach, crumbled stock cube, and cinnamon stick, stir well, and cook over medium heat for 5 minutes.","Mix the corn flour with 125 ml (half a glass) of water to make a smooth slurry, pour into the soup, and stir until thickened.","Remove the cinnamon stick and season the soup to taste with salt and pepper."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_szpinakowa","page":"Książka kucharska/Zupa szpinakowa"},{"id":"oc-plwb-14690","title":"Zupa z cykorii i pora (Chicory and leek soup)","cuisine":"Other","category":"Soup","ingredients":["100 g leek","100 g chicory","1 clove garlic (clove)","20 g butter","250 ml milk (1 glass)","250 ml vegetable broth (1 glass)","to taste caraway","to taste nutmeg","to taste salt","to taste pepper"],"steps":["Trim the leek and cut it into slices, cut the core out of the chicory, and cut the leaves into narrow strips.","Finely chop the garlic, cook gently in the melted butter, then add the leek and chicory and fry briefly together.","Pour in the milk and vegetable broth, and season everything with salt, pepper, nutmeg, and caraway.","Cook the soup over low heat for about 5 minutes and serve with garlic toasts."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_cykorii_i_pora","page":"Książka kucharska/Zupa z cykorii i pora"},{"id":"oc-plwb-21701","title":"Zupa z głogu (Lithuanian-Polish hawthorn berry soup)","cuisine":"Other","category":"Soup","ingredients":["1.5 l hawthorn berries (fresh or dried)","2.5 kaiser rolls (2–3 rolls (or half a baguette), crusts removed)","500 ml wine (2 glasses)","500 ml water (for the wine syrup (plus water to cook the hawthorn and rolls))","125 g sugar","1 tsp cinnamon"],"steps":["Trim the crusts off the rolls, crumble the bread into a pot, add the hawthorn berries (fresh or dried), cover with water, and simmer until completely soft.","Mash the cooked hawthorn thoroughly with the bread and press the mixture through a fine sieve.","In a separate pot, boil 500 ml of water with the wine, sugar, and cinnamon.","Pour the hot wine syrup into the sieved hawthorn, stir thoroughly, and serve with croutons."],"time":50,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_g%C5%82ogu","page":"Książka kucharska/Zupa z głogu"},{"id":"oc-plwb-17716","title":"Zupa z wina (wine soup)","cuisine":"Other","category":"Soup","ingredients":["6 egg yolks","8 tbsp sugar","1 l dry or semi-dry white wine","0.5 lemon (half, grated zest)","1 pinch ground cinnamon","4 whole cloves (a few cloves)"],"steps":["Beat the egg yolks with the sugar until pale and fluffy.","Heat the wine in a covered pan with the grated zest of half a lemon, a pinch of cinnamon, and the cloves.","Strain the hot wine and pour it slowly into the beaten yolks, whisking constantly with a whisk or mixer.","Place the saucepan back over low heat and whisk until the soup thickens, without letting it boil so the yolks do not curdle.","Serve in large goblets or decorative glass cups."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_z_wina","page":"Książka kucharska/Zupa z wina"},{"id":"oc-plwb-19520","title":"Zupa ziołowa (potato and fresh herb soup)","cuisine":"Other","category":"Soup","ingredients":["1 l vegetable broth","500 g potatoes (diced)","1 onion (finely chopped)","1 tbsp olive oil","1 fresh basil (sprig)","1 fresh rosemary (sprig)","1 fresh mint (sprig)","1 fresh thyme (sprig)","to taste salt","to taste Polish herb and spice seasoning (pieprz ziołowy)"],"steps":["Peel and dice the potatoes, and finely chop the onion.","Place the potatoes and onion in a pot, add the olive oil, pour over the prepared vegetable broth, and cook until the potatoes are tender.","Blend the soup into a smooth purée and season to taste with salt and Polish herb and spice seasoning (pieprz ziołowy).","Before serving, sprinkle the soup with finely chopped leaves of basil, rosemary, mint, and thyme."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_zio%C5%82owa","page":"Książka kucharska/Zupa ziołowa"},{"id":"oc-plwb-6266","title":"Barszcz ukraiński (Ukrainian-style hearty borscht)","cuisine":"Russian","category":"Soup","ingredients":["500 g pork (or veal or chicken)","3 l water (1 l for soaking beans and 2 l for broth)","1 soup greens with savoy cabbage (carrot, celeriac, parsley root, leek, and savoy cabbage)","1 onion","250 ml small white beans","2 beetroots (medium-sized)","5 potatoes","1 tbsp tomato purée (generous tablespoon)","250 ml thick sour cream","1 bunch dill","to taste salt","to taste black pepper","to taste sugar","to taste lemon juice"],"steps":["The day before, soak the beans in 1 litre of lukewarm boiled water, and the next day boil them until tender.","Cover the pork in a pot with cold water and simmer over low heat until tender, salting lightly towards the end, to yield 2 litres of broth.","Grate the carrots, celeriac, parsley root, and onion on a coarse grater, add the finely shredded leek from the soup greens, pour in the meat broth, and bring to a boil.","Shortly after, add the grated beetroots, and once the vegetables begin to soften, toss in the diced potatoes and shredded savoy cabbage.","When all the vegetables are tender, season the soup with the tomato purée, lemon juice, salt, pepper, and sugar.","Add the cooked beans along with their cooking liquid and simmer gently for a short while longer.","Finally, stir in the finely chopped dill and thick sour cream, and mix well."],"time":120,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Barszcz_ukrai%C5%84ski","page":"Książka kucharska/Barszcz ukraiński"},{"id":"oc-plwb-14226","title":"Beef Stroganoff","cuisine":"Russian","category":"Main","ingredients":["500 g beef tenderloin","1 onion","300 g button mushrooms","2 tbsp tomato paste","250 ml beef broth","1 fermented (brine) pickle","1 tbsp wheat flour","150 ml sour cream (150 ml (adjusted from 1 tsp for 500 g beef))","to taste salt","to taste coarsely ground black pepper","1 pinch hot paprika powder"],"steps":["Rinse and pat dry the beef tenderloin, slice into long thin strips, fry until browned, then transfer to a saucepan and pour in the beef broth.","Peel the onion and mushrooms, slice them along with the fermented pickle, add to the meat, and braise covered over low heat for about 30 minutes.","Stir the wheat flour into a little water, pour into the saucepan with the tomato paste, and bring to a boil.","Stir in the sour cream and season the dish with salt, coarsely ground black pepper, and a pinch of hot paprika powder."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Boeuf_Strogonow","page":"Książka kucharska/Boeuf Strogonow"},{"id":"oc-plwb-21811","title":"Buckwheat and Wheat Blini (Bliny pszenno-gryczane)","cuisine":"Russian","category":"Main","ingredients":["750 ml wheat flour","250 ml buckwheat flour","625 ml water","450 ml milk (1.5–2 glasses (450 ml))","25 g dry yeast (20–30 g)","250 ml butter (melted)","1 tbsp salt","1 tsp sugar"],"steps":["5–6 hours before frying, mix the wheat flour, water, dry yeast, and 1 tablespoon of melted butter, beat the batter, and leave in a warm place for 2–3 hours to rise.","Beat the risen dough again, stir in the salt, sugar, and buckwheat flour, and let rise once more.","60 minutes before frying, pour in the hot milk, mix thoroughly, and allow the batter to rise.","Without stirring the batter, ladle onto a hot skillet, drizzle with the remaining melted butter as the blini brown, and flip to finish cooking."],"time":60,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bliny_pszenno-gryczane","page":"Książka kucharska/Bliny pszenno-gryczane"},{"id":"oc-plws-44938","title":"Buckwheat and wheat yeast blini","cuisine":"Russian","category":"Main","ingredients":["600 g plain wheat flour (orig. 1 kwarta)","600 g buckwheat flour (orig. 1 kwarta)","25 g dry yeast (orig. 2 łuty)","1 l lukewarm water (orig. 250 ml overnight + approx. 750 ml in the morning)","125 ml boiling water (orig. 1/2 szklanka)","80 g clarified butter (for brushing the pans)","1 tsp salt (for the batter)"],"steps":["In the evening (10–12 hours before baking), dissolve the yeast in 250 ml of lukewarm water and mix with the wheat flour to form a sponge; leave covered overnight to rise.","In the morning, add the buckwheat flour, salt, and about 750 ml of lukewarm water to the risen sponge, beating into a loose batter; set aside to rise again.","Once the batter has risen a second time, pour 125 ml of boiling water right into the centre, stir quickly (the batter should be slightly thicker than crêpe batter), and let rise a third time.","Heat small blini pans until very hot, brush with hot clarified butter, and ladle in a fairly thick layer of batter.","Bake the blini in a very hot oven (220 °C) or covered for about 4–5 minutes without flipping, until risen and browned on top. Transfer immediately to plates and serve hot."],"time":600,"servings":10,"image":"","source":"https://pl.wikisource.org/wiki/365_obiad%C3%B3w_za_5_z%C5%82otych/Bliny","page":"365 obiadów za 5 złotych/Bliny"},{"id":"oc-plwb-21795","title":"Buckwheat Blini (Russian bliny gryczane)","cuisine":"Russian","category":"Main","ingredients":["1 l buckwheat flour","1.25 l milk or water","25 g dry yeast (20–30 g)","250 ml butter (melted)","2 eggs (separated into yolks and whites)","1 tbsp salt","1 tsp sugar"],"steps":["5–6 hours before frying, mix the buckwheat flour, 750 ml of warm milk or water, dry yeast, 2 egg yolks, and 1 tablespoon of melted butter, beat with a whisk, and set in a warm place for 2–3 hours to rise.","Beat the risen batter again, stir in the salt and sugar, pour in the remaining 500 ml of hot milk or water, and beat thoroughly.","Gently fold in the egg whites whipped to stiff peaks and leave the batter to rise once more.","Without stirring the risen batter, ladle spoonfuls onto a heated small skillet.","When the blini begin to puff and brown on the bottom, drizzle with the remaining melted butter, flip over, and finish cooking."],"time":60,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bliny_gryczane","page":"Książka kucharska/Bliny gryczane"},{"id":"oc-plws-502915","title":"Jaja po rosyjsku — Draczena (Russian baked egg puff)","cuisine":"Russian","category":"Breakfast","ingredients":["50 g butter (for creaming until fluffy)","1 tbsp butter (a generous tablespoon for melting in the baking dish)","5 egg yolks","1 tsp salt","125 ml plain wheat flour","375 ml milk","5 egg whites (beaten to stiff peaks)"],"steps":["Cream 50 g of butter in a bowl until fluffy, add the egg yolks, salt, wheat flour, and milk, and beat everything together until smooth.","Beat the egg whites to stiff peaks and gently fold them into the batter.","Melt a tablespoon of butter in an ovenproof skillet or deep baking dish and pour the egg batter into the hot fat.","Place the dish in an oven preheated to 180 °C and bake for 20 minutes until the drachena puffs high and turns golden brown, then cut into portions and serve immediately."],"time":35,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/100_potraw_z_jaj/Jaja_po_rosyjsku_(Draczena)","page":"100 potraw z jaj/Jaja po rosyjsku (Draczena)"},{"id":"oc-plwb-21802","title":"Oładki (oladyi / thick yeast pancakes)","cuisine":"Russian","category":"Breakfast","ingredients":["1.5 l plain flour","500 ml milk","2 tbsp fresh yeast","3 eggs","500 g butter (or lard, for frying)","to taste salt"],"steps":["Add the flour to a bowl, pour in the warm milk, eggs, fresh yeast, and salt, and stir into a thick batter.","Cover the bowl and set the batter in a warm place to rise.","Melt a portion of butter or lard in a frying pan.","Scoop spoonfuls of risen batter from the edge of the bowl using a large spoon dipped in the melted fat, dropping oblong mounds into the pan.","Fry the oladyi on both sides until golden brown and cooked through."],"time":70,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/O%C5%82adki","page":"Książka kucharska/Oładki"},{"id":"oc-plwb-61742","title":"Rassolnik (Russian pickle and barley soup)","cuisine":"Russian","category":"Soup","ingredients":["450 g lean beef (diced)","2.8 l water","60 g barley groats (rinsed)","3 potatoes (medium, diced)","1 carrot (sliced)","1 carrot (grated)","1 onion (finely chopped)","2 celery (stalks, thinly sliced)","6 vinegar-pickled gherkins (small, cut into pieces)","1 tbsp tomato paste","4 tbsp olive oil (1 tbsp for the pickles, 3 tbsp for the vegetables)","2 bay leaf","2 tbsp fresh dill (chopped, optional)","0.5 tsp ground black pepper (freshly ground)","0.5 tbsp salt (plus to taste)"],"steps":["Pour 2.8 litres of water into a large pot, add the diced beef, rinsed barley groats, and half a tablespoon of salt, and cook partially covered for about 30 minutes, skimming off any foam regularly.","Sauté the cut-up pickles in 1 tablespoon of olive oil, transfer them to the pot along with the diced potatoes and sliced carrot, and cook for another 10 minutes.","Heat the remaining 3 tablespoons of olive oil in a separate skillet, fry the chopped onion for 2 minutes, add the grated carrot and thinly sliced celery, and cook gently, covered, for 5 minutes until tender.","Stir the tomato paste into the skillet and transfer everything into the soup pot.","Add 2 bay leaves, black pepper, chopped dill, and salt to taste, and simmer over low heat for about 2 minutes until the potatoes are tender."],"time":70,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Razsolnik","page":"Książka kucharska/Razsolnik"},{"id":"oc-plws-546595","title":"Russian ruffe fish soup (ucha z jazgarzy)","cuisine":"Russian","category":"Soup","ingredients":["500 g ruffe fish (orig. 0.5 kg)","2 onions (with only the innermost thin yellow skin left on)","400 g potatoes (orig. 40 dkg)","1 parsley root","2 l water","4 peppercorns (coarsely crushed)","0.5 bay leaf","to taste salt"],"steps":["Carefully scale the ruffe, snip off gills and tails with scissors, gut, salt, and set aside for 60 minutes before rinsing.","In a pot, bring 2 l of water to a boil with the parsley root quartered into 4 pieces, bay leaf, coarsely crushed peppercorns, and halved onions left in their thin yellow skins.","Peel the potatoes, cut into walnut-sized pieces (about 25 g), and drop into the simmering broth.","After cooking the potatoes for 5 minutes, add the rinsed ruffe and simmer for about 15–20 minutes until the fish flesh begins separating from the bones.","Remove the ruffe, flake the meat from the bones (discarding the heads), place the picked meat into a soup tureen, and ladle over the hot soup with potatoes."],"time":110,"servings":4,"image":"","source":"https://pl.wikisource.org/wiki/109_potraw/Ucha_z_jazgarzy","page":"109 potraw/Ucha z jazgarzy"},{"id":"oc-plwb-25810","title":"Sałatka rosyjska (Olivier salad)","cuisine":"Russian","category":"Salad","ingredients":["500 g potatoes","5 carrots (boiled)","250 ml green peas (cooked or canned)","4 fermented brine pickles","3 eggs (hard-boiled)","375 ml mayonnaise","2 tbsp vinegar","1 tbsp parsley (finely chopped)","to taste salt","to taste black pepper"],"steps":["Peel the potatoes, boil them in lightly salted water until tender, then let cool and cut into dice.","Separate the hard-boiled egg whites from the yolks, then finely dice the egg whites, cooked carrots, and fermented brine pickles.","Transfer the diced vegetables and egg whites to a bowl, add the drained peas, mayonnaise, and vinegar, season with salt and pepper, and mix well.","Garnish the top of the salad with finely chopped parsley and the egg yolks pressed through a sieve."],"time":45,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_rosyjska","page":"Książka kucharska/Sałatka rosyjska"},{"id":"oc-plwb-21798","title":"Wheat Blini (Russian bliny pszenne)","cuisine":"Russian","category":"Main","ingredients":["750 ml coarse wheat flour","625 ml milk","25 g dry yeast (20–30 g)","200 g butter (melted)","2 eggs (separated into yolks and whites)","125 ml heavy cream (half glass (125 ml))","2 tsp salt","2 tsp sugar"],"steps":["Dissolve the sugar, salt, and dry yeast in 375 ml of warm milk, add 560 ml of coarse wheat flour, mix thoroughly, and leave covered in a warm place to rise.","Once the sponge has risen, add 2 egg yolks and the remaining 190 ml of flour, adjusting the consistency with the rest of the milk.","Whip the egg whites to stiff peaks, separately whip the heavy cream, fold both gently into the batter, and let rise again in a warm place.","Without stirring the risen batter, ladle portions onto a heated small skillet.","When the blini rise and brown on the bottom, drizzle with melted butter, flip, and fry until golden."],"time":60,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bliny_pszenne","page":"Książka kucharska/Bliny pszenne"},{"id":"oc-plwb-21812","title":"Yeast-Free Blini (Quick buckwheat and wheat pancakes)","cuisine":"Russian","category":"Main","ingredients":["500 g wheat flour","500 g buckwheat flour","1.3 l water (4.5–5 glasses warm water plus 0.5 glass cold)","1 tsp baking soda","250 ml butter (melted)","2 tsp salt","2 tsp sugar"],"steps":["In a bowl, mix together the wheat flour, buckwheat flour, salt, sugar, and 1.2 litres of warm water into a smooth batter.","Just before frying, dissolve the baking soda in the remaining 125 ml of cold water and stir briefly into the batter.","Ladle spoonfuls of batter onto a heated small skillet, and when the blini puff and brown on the bottom, drizzle with melted butter and flip over."],"time":40,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Bliny_bez_dro%C5%BCd%C5%BCy","page":"Książka kucharska/Bliny bez drożdży"},{"id":"oc-plwb-21571","title":"Aioli","cuisine":"Spanish","category":"Sauce","ingredients":["1 egg yolk","10 tbsp olive oil","1 tbsp white wine vinegar","2 clove garlic","to taste salt","to taste black pepper"],"steps":["Chop the garlic cloves, combine with the egg yolk, white wine vinegar, salt, and pepper, and pound in a mortar or blend in a food processor into a smooth paste.","Whisking constantly and gently, slowly drizzle in the olive oil a few drops at a time until a thick, stable emulsion forms."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_a%C3%AFoli","page":"Książka kucharska/Sos aïoli"},{"id":"oc-plwb-18815","title":"Aragonese-style pork with ham and olives (Wieprzowina Aragończyka)","cuisine":"Spanish","category":"Main","ingredients":["500 g pork","200 g cured pork ham","1 onion","15 black olives","5 tbsp olive oil","1 tbsp tomato paste","125 ml dry white wine","1 tbsp plain flour","to taste salt"],"steps":["Peel the onion and dice it along with the ham and black olives.","Trim the pork of excess fat, cut into 4 slices, pound lightly, season with salt, and dredge in flour.","Brown the meat slices on both sides in hot olive oil, then transfer them along with the cooking fat to a saucepan.","Add the onion, ham, and olives, cook gently for a moment, then stir in the tomato paste, cover, and simmer until the meat is tender.","Towards the end of braising, pour in the dry white wine, bring to the boil, transfer the meat to a serving platter, and spoon the sauce over it."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Wieprzowina_Arago%C5%84czyka","page":"Książka kucharska/Wieprzowina Aragończyka"},{"id":"oc-plwb-56111","title":"Barcelona-style chicken salad (Sałatka z kurczaka po barcelońsku)","cuisine":"Spanish","category":"Salad","ingredients":["190 ml roast chicken (diced)","80 ml green peas (cooked)","2 tbsp pickled bell pepper (finely diced)","1 scallion (finely chopped)","3 tbsp orange juice","2 tbsp olive oil (or vegetable oil)","2 tbsp walnuts (chopped)","1 tbsp raisins","to taste lettuce (leaves for serving)","to taste salt","to taste black pepper"],"steps":["In a salad bowl, combine the diced roast chicken, cooked green peas, and finely chopped pickled bell pepper, then chill in the refrigerator.","In a small bowl, whisk together the orange juice, olive oil, finely chopped scallion, raisins, and chopped walnuts.","Pour the prepared dressing over the chilled ingredients, toss gently, and season to taste with salt and pepper.","Line a clean salad bowl with fresh lettuce leaves and spoon the prepared salad onto them."],"time":15,"servings":5,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sa%C5%82atka_z_kurczaka_po_barcelo%C5%84sku","page":"Książka kucharska/Sałatka z kurczaka po barcelońsku"},{"id":"oc-plwb-20949","title":"Crema catalana","cuisine":"Spanish","category":"Dessert","ingredients":["6 eggs (5 yolks and 1 whole egg)","625 ml cream (2 1/2 cups (625 ml))","60 ml milk (1/4 cup (62.5 ml))","2 cinnamon sticks (2–3 sticks)","1 lemon (zest)","90 g icing sugar (approximately 1/2 cup (125 ml))","1.5 tbsp brown sugar","0.25 tsp ground cinnamon"],"steps":["Pare 3 strips of zest from the lemon, place them into a saucepan with the cinnamon sticks, pour in the cream and milk, and heat gently almost to a boil.","Remove the pan from the heat, let infuse for 3–5 minutes to cool slightly, then strain through a fine sieve, discarding the cinnamon and lemon peel.","Separate the yolks from 5 eggs and whisk with 1 whole egg and 75 g of icing sugar until smooth, then whisk into the warm cream and divide among 6 ramekins.","Place the ramekins in a roasting tin filled halfway up their sides with boiling water and bake at about 150 °C for 30–40 minutes until just set.","Lift the ramekins from the water bath, let cool, and refrigerate for at least 240 minutes.","Mix the ground cinnamon, brown sugar, and remaining tablespoon of icing sugar, sift over the chilled custards, and caramelise with a kitchen blowtorch or in a very hot oven."],"time":65,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Crema_catalana","page":"Książka kucharska/Crema catalana"},{"id":"oc-plwb-15303","title":"Gazpacho","cuisine":"Spanish","category":"Soup","ingredients":["6 large ripe tomatoes","2 red bell pepper (ripe)","1 green bell pepper","1 large cucumber (peeled)","125 ml olive oil","3 tbsp wine vinegar","3 clove garlic","1 onion","1 slice white bread","125 ml mineral water","1 tsp salt","1 pinch ground cumin (cumin)"],"steps":["Cut the crust off the slice of white bread, keeping only the soft crumb.","Wash and roughly chop the tomatoes, red and green bell peppers, and peeled cucumber.","Peel and roughly chop the onion and garlic cloves.","Blend all the vegetables with the bread crumb, olive oil, wine vinegar, mineral water, salt, and ground cumin until completely smooth.","Chill the soup in the refrigerator before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Gazpacho","page":"Książka kucharska/Gazpacho"},{"id":"oc-plwb-18728","title":"Iberian white bean soup with croutons","cuisine":"Spanish","category":"Soup","ingredients":["100 g dried white beans","1 l water (for soaking and cooking beans)","0.5 onion","2 clove garlic","0.5 red bell pepper","3 tbsp olive oil","250 ml chicken broth","2 tbsp fresh marjoram (chopped)","1 tbsp parsley leaves (chopped)","2 slice white bread","1 tbsp butter","to taste salt","to taste black pepper (freshly ground)"],"steps":["Soak the white beans overnight in cold water, then drain and cover with fresh water.","Finely chop the onion, garlic, and red bell pepper, add to the beans with the olive oil, and simmer until tender.","Pass the soup through a sieve or blend until smooth, pour in the chicken broth, add the fresh marjoram and parsley leaves, season with salt and black pepper, and cook for about 30 minutes more.","Dice the white bread, brown in butter to make golden croutons, and serve floating on the hot soup."],"time":105,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Iberyjska_zupa_fasolowa","page":"Książka kucharska/Iberyjska zupa fasolowa"},{"id":"oc-plwb-20552","title":"Marmitako (Basque tuna and potato stew)","cuisine":"Spanish","category":"Soup","ingredients":["500 g fresh tuna","1 green bell pepper","3 potatoes","1 onion","75 ml olive oil","750 ml water","to taste sweet ground paprika","to taste salt"],"steps":["Cut the fresh tuna into bite-sized pieces.","Peel the potatoes and onion, dice the potatoes, chop the onion, and slice the green bell pepper into strips.","Heat the olive oil in a pot, add the onion and cook until translucent, then add the green bell pepper and fry for 3–5 minutes.","Add the diced potatoes and sweet ground paprika, stir, pour in the water, bring to a boil, and simmer over low heat for 20–25 minutes.","Season the soup to taste with salt, add the tuna pieces, and cook for about 5 minutes longer."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Marmitako","page":"Książka kucharska/Marmitako"},{"id":"oc-plwb-30758","title":"Nalewka Orszada (almond horchata / orgeat drink)","cuisine":"Spanish","category":"Drink","ingredients":["1 kg almonds","1 kg sugar","5 l water","1 cinnamon stick"],"steps":["Rinse the almonds several times and soak them in part of the water for 12 hours.","Drain the almonds, rinse again, pat dry, and pound in a mortar or grind finely into a smooth paste.","Mix the almond paste with the remaining water and cinnamon stick, and leave in a cool place for 2 hours.","Remove the cinnamon stick, add the sugar, and stir until completely dissolved.","Strain the beverage through a fine sieve lined with cheesecloth to obtain a smooth, milky liquid, and chill thoroughly before serving."],"time":40,"servings":12,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Nalewka_Orszada","page":"Książka kucharska/Nalewka Orszada"},{"id":"oc-plwb-21570","title":"Patatas bravas (Spanish roasted potato wedges)","cuisine":"Spanish","category":"Snack","ingredients":["1.5 kg potatoes","1 clove garlic (crushed)","2.5 tbsp olive oil","to taste salt"],"steps":["Thoroughly scrub the unpeeled potatoes, halve them, and cut each half lengthwise into 3 wedges.","Transfer the potatoes to a bowl, add the olive oil, crushed garlic clove, and salt, and toss thoroughly.","Preheat the oven to 175 °C, arrange the potato wedges in a single layer on a baking sheet, and roast for about 90 minutes until golden and crisp."],"time":105,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Patatas_bravas","page":"Książka kucharska/Patatas bravas"},{"id":"oc-plwb-20544","title":"Romesco sauce","cuisine":"Spanish","category":"Sauce","ingredients":["4 dried hot chili pepper (3–4 pcs)","1 fresh hot chili pepper","6 clove garlic (crushed)","2 tomato","24 almonds (blanched, peeled)","24 hazelnuts (skinned)","2 slice bread","1 tbsp parsley leaves (finely chopped)","3 tbsp olive oil (1 tbsp for sautéing and roasting, 2 tbsp for the sauce)","1 tbsp wine vinegar (to taste)","to taste salt"],"steps":["Soak the dried hot chilies in warm water for about 60 minutes, then finely chop them together with the fresh chili.","Lightly sauté the chopped chilies and bread slices in a little olive oil.","Preheat the oven to 200 °C, toast the peeled almonds and hazelnuts until lightly golden, and roast the tomatoes in an oiled baking dish for 10 minutes.","Let the roasted tomatoes cool, peel off their skins, and chop finely.","Blend or pound in a mortar the sautéed chilies, bread, crushed garlic, hazelnuts, almonds, and 1 tablespoon of chopped parsley leaves.","Add the chopped tomatoes, blend again, then stir in 2 tablespoons of olive oil and season with wine vinegar and salt."],"time":80,"servings":6,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Romesco","page":"Książka kucharska/Romesco"},{"id":"oc-plwb-56133","title":"Ryż z fasolą (Spanish brown rice with white kidney beans)","cuisine":"Spanish","category":"Main","ingredients":["1 tbsp olive oil","2 spring onions","1 clove garlic","1 celery (stalk)","1 carrot","250 ml long-grain brown rice","190 ml water","400 g canned tomatoes (with juices)","450 g canned cannellini beans (drained)","1 tbsp fresh mint or basil (chopped)","to taste salt","to taste black pepper"],"steps":["Dice the spring onions, celery stalk, and peeled carrot, and finely mince the garlic.","Heat the olive oil over moderate heat in a large heavy-bottomed pot, add the prepared vegetables, and sauté until tender.","Add the brown rice, pour in the water and tomatoes with their juice, stir thoroughly, reduce the heat, and simmer covered for 40–45 minutes.","Rinse and drain the canned beans, stir into the pot along with the chopped mint or basil, and simmer covered for about 5 minutes, until the rice is tender and the beans are hot.","Season with salt and pepper to taste before serving."],"time":65,"servings":8,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Ry%C5%BC_z_fasol%C4%85","page":"Książka kucharska/Ryż z fasolą"},{"id":"oc-plwb-22417","title":"Samfaina (Catalan braised vegetables)","cuisine":"Spanish","category":"Side","ingredients":["1 courgette","1 aubergine","2 red bell peppers","6.5 tomatoes (medium)","2 clove garlic","1 onion (medium)","to taste olive oil","to taste salt","to taste black pepper"],"steps":["Dice the onion and crush the garlic, then cut the courgette and aubergine into cubes.","Score the skins of the tomatoes, scald in boiling water, plunge into cold water, peel, and dice the pulp.","Remove the seeds from the red bell peppers and slice into thin strips.","Heat the olive oil in a wide pot, add the onion, garlic, aubergine, and courgette, stir well, and braise covered for about 10 minutes.","Uncover the pot, stir in the tomatoes and bell peppers, season with salt and pepper, and simmer gently uncovered until the vegetables are tender and the sauce thickens."],"time":50,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Samfaina","page":"Książka kucharska/Samfaina"},{"id":"oc-plwb-56141","title":"Spanish almond snowball cookies","cuisine":"Spanish","category":"Cookie","ingredients":["250 ml softened butter","250 ml icing sugar","125 ml ground almonds","500 ml plain flour","1 tbsp vanilla extract"],"steps":["Preheat the oven to 165 °C and line a baking sheet (25 × 35 cm) with baking parchment.","Beat the softened butter with the icing sugar in a bowl until pale and fluffy, gradually incorporating the ground almonds, vanilla extract, and flour.","Dust your hands with flour, shape the dough into small balls up to 3 cm in diameter, and arrange them on the prepared baking sheet.","Bake in the preheated oven for 15–18 minutes until crisp yet still pale."],"time":18,"servings":10,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kuleczki_migda%C5%82owe","page":"Książka kucharska/Kuleczki migdałowe"},{"id":"oc-plwb-19360","title":"Spanish scrambled eggs with tomatoes","cuisine":"Spanish","category":"Breakfast","ingredients":["6 eggs","4 tomatoes (ripe)","3 onions (medium)","4 clove garlic","3 tbsp olive oil","1 tbsp parsley leaves (chopped)","to taste salt","to taste black pepper"],"steps":["Scald the tomatoes with boiling water, remove the skins, and dice the pulp.","Heat the olive oil in a skillet and sauté the peeled, finely chopped onion and pressed garlic.","Add the diced tomatoes, simmer for about 15 minutes, and season with salt and black pepper.","Pour in the beaten eggs, mix thoroughly, fry until set, and sprinkle with chopped parsley leaves before serving."],"time":30,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Jajecznica_po_hiszpa%C5%84sku","page":"Książka kucharska/Jajecznica po hiszpańsku"},{"id":"oc-plwb-18625","title":"Spanish tomato salad","cuisine":"Spanish","category":"Salad","ingredients":["500 g tomatoes","1 tbsp hot mustard","1 tbsp vinegar","2 tbsp olive oil","1 clove garlic","1 bunch parsley leaves","to taste tarragon","to taste salt","to taste white pepper"],"steps":["Blanch the tomatoes, remove the skins, and dice them.","Rub the bottom of a salad bowl with a halved garlic clove, arrange the tomatoes in it, season with salt and white pepper, and sprinkle with chopped parsley leaves.","Whisk the mustard with the vinegar, olive oil, and tarragon, pour the dressing over the tomatoes, toss well, and chill in the refrigerator before serving."],"time":15,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Hiszpa%C5%84ska_sa%C5%82atka_pomidorowa","page":"Książka kucharska/Hiszpańska sałatka pomidorowa"},{"id":"oc-plwb-20465","title":"Spanish-style sheep cheese turnovers (Pierożki po hiszpańsku)","cuisine":"Spanish","category":"Snack","ingredients":["200 g wheat flour","2 tbsp olive oil","100 ml dry white wine","1 tsp grated lemon zest","1 onion","2 eggs (1 for the filling, 1 yolk for brushing the tops)","150 g sheep's milk cheese","1 tbsp olive oil","2 clove garlic","3 tbsp butter (melted, for brushing pastry and baking sheet)","2 tbsp parsley leaves (chopped)","to taste salt","to taste black pepper"],"steps":["Combine the wheat flour with 2 tablespoons of olive oil, dry white wine, and grated lemon zest, knead into a smooth dough, wrap in clingfilm, and chill in the fridge for 2 hours.","Peel and chop the onion, then cook until translucent in a tablespoon of olive oil.","Grate the sheep's milk cheese, mix with one egg, chopped parsley leaves, minced garlic, and the translucent onion, and season with salt and pepper.","Roll out the chilled dough, cut out rounds, and brush them with melted butter.","Spoon the filling onto the rounds, fold in half, crimp the edges to seal, and brush the tops with the yolk of the second egg.","Place the pastries on a buttered baking sheet and bake for about 10 minutes in an oven preheated to 200 °C."],"time":45,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Piero%C5%BCki_po_hiszpa%C5%84sku","page":"Książka kucharska/Pierożki po hiszpańsku"},{"id":"oc-plwb-19522","title":"Spanish-style tomato and garlic sauce","cuisine":"Spanish","category":"Sauce","ingredients":["5 tomatoes (medium)","1 wheat roll","4 tbsp olive oil","5 clove garlic","1 tbsp wine vinegar","0.5 tsp hot paprika powder","to taste salt","to taste black pepper"],"steps":["Scald the tomatoes with boiling water, remove the skins, and dice the flesh.","Press the garlic through a crusher and cook in a saucepan with 1 tablespoon of heated olive oil until translucent.","Add the diced tomatoes, crumbled roll, wine vinegar, and hot paprika, and simmer over low heat until the sauce is moderately thick but still fairly fluid.","Pass the cooked sauce through a sieve.","Stirring constantly, slowly pour in the remaining 3 tablespoons of olive oil, season with salt and pepper, and warm gently for a moment."],"time":30,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Sos_pomidorowy_po_hiszpa%C5%84sku","page":"Książka kucharska/Sos pomidorowy po hiszpańsku"},{"id":"oc-plwb-20568","title":"Torrijas (Spanish Easter French toast)","cuisine":"Spanish","category":"Dessert","ingredients":["6 slice bread (slices)","250 ml milk","2 eggs","2 tbsp sugar (for the milk and extra for sprinkling)","to taste ground cinnamon (for sprinkling)","to taste olive oil (for frying)"],"steps":["Mix the milk with two tablespoons of sugar.","Cut the bread slices into smaller pieces, soak them in the sweetened milk, and leave until thoroughly saturated.","Lift the soaked bread pieces from the milk and coat them in the lightly beaten eggs.","Fry the toasts in hot olive oil on both sides until golden, and serve sprinkled with sugar and cinnamon."],"time":25,"servings":3,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Torrijas","page":"Książka kucharska/Torrijas"},{"id":"oc-plwb-20534","title":"Tortilla de patatas (Spanish potato omelette)","cuisine":"Spanish","category":"Main","ingredients":["4 eggs","5 potatoes (medium)","1 onion","to taste olive oil (generous amount for frying the potatoes)","to taste salt"],"steps":["Peel the potatoes and cut them into thin slices, and finely chop the onion.","Heat a generous amount of olive oil in a deep skillet, cook the onion until translucent, add the potato slices, and fry over moderate heat, turning every few minutes until tender and lightly golden.","Season the potatoes with salt towards the end of frying, remove from heat, and drain thoroughly along with the onion of excess oil.","Beat the eggs lightly in a bowl with a pinch of salt, gently combine with the drained potatoes and onion, then set aside for 10–15 minutes.","Heat a little of the reserved oil in the skillet, pour in the egg and potato mixture, and cook over medium heat for 4–5 minutes, gently shaking the pan.","Cover the skillet with a large flat plate, invert the tortilla onto the plate, slide it back into the hot skillet uncooked side down, and cook for a few more minutes until the eggs are set."],"time":55,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tortilla_de_patatas","page":"Książka kucharska/Tortilla de patatas"},{"id":"oc-plwb-20519","title":"Tumbet (Mallorcan baked vegetables)","cuisine":"Spanish","category":"Main","ingredients":["2 aubergines (sliced)","to taste olive oil (for frying the vegetables and making the sauce)","500 g potatoes (peeled and sliced)","2 red bell peppers (cut into strips)","to taste fresh parsley (for garnish)","6 tomatoes (diced)","3 clove garlic","to taste oregano","to taste salt"],"steps":["Heat olive oil in a pan, fry the potato slices until golden, and drain on paper towels.","Fry the aubergine slices in the same oil, set aside, then fry the red pepper strips.","Arrange the vegetables in layers in a baking dish: potatoes on the bottom, aubergines over them, and peppers on top.","Sauté the chopped garlic in a little olive oil, add the diced tomatoes, season with salt and oregano, and simmer covered for about 20 minutes.","Pour the tomato sauce over the vegetables, bake in an oven preheated to 200 °C for about 15 minutes, and garnish with fresh parsley before serving."],"time":70,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Tumbet","page":"Książka kucharska/Tumbet"},{"id":"oc-plwb-56147","title":"Valencian orange chicken","cuisine":"Spanish","category":"Main","ingredients":["500 g chicken meat (skinless and boneless)","2 tsp olive oil or rapeseed oil","0.5 tsp sweet ground paprika","2 spring onions","1 tomato","60 ml parsley (chopped)","125 ml orange juice","125 ml raisins"],"steps":["Cut the chicken meat into 4 portions and rub evenly with sweet paprika.","Heat the olive oil or rapeseed oil in a large frying pan over medium heat, add the chicken portions, and brown on all sides until golden.","Dice the spring onions and tomato, and add to the chicken along with the chopped parsley.","Pour in the orange juice, stir in the raisins, reduce the heat, and braise covered for 15–20 minutes until the meat is tender, turning the portions once or twice."],"time":25,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Kurczak_po_walencku","page":"Książka kucharska/Kurczak po walencku"},{"id":"oc-plwb-61768","title":"Zarzuela de mariscos (Catalan seafood stew)","cuisine":"Spanish","category":"Soup","ingredients":["500 g white fish fillets (cod, hake, or perch)","500 g mixed seafood (shrimp, mussels, and squid)","2 ripe tomatoes (or canned diced tomatoes) (or 1 can diced)","1 onion","1 red bell pepper","2 clove garlic","250 ml fish stock","150 ml white wine","2 tbsp olive oil","2 tbsp tomato paste","0.5 tsp sweet paprika powder","1 bay leaf (leaf)","1 tbsp parsley leaves (chopped)","to taste salt","to taste black pepper","1 pinch saffron (optional)"],"steps":["Cut the fish fillets into chunks and clean the seafood.","Heat olive oil in a pot, cook finely chopped onion and garlic until translucent, then add chopped tomatoes and red bell pepper, and simmer for 10 minutes until a thick sauce forms.","Pour in the white wine and reduce by half, then add fish stock, tomato paste, sweet paprika, bay leaf, and optionally saffron, and simmer gently for 15–20 minutes.","Add the fish chunks to the sauce and simmer for 10 minutes, then add the seafood, cover, and cook for 5–7 minutes until the mussels open.","Before serving, remove the bay leaf, season with salt and pepper, and garnish with chopped parsley leaves."],"time":60,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zarzuela_de_mariscos","page":"Książka kucharska/Zarzuela de mariscos"},{"id":"oc-plwb-19216","title":"Red curry rice with vegetables","cuisine":"Thai","category":"Main","ingredients":["100 g rice (cooked)","1 carrot","0.25 cauliflower","1 onion","1 clove garlic","1 tbsp olive oil","0.25 tsp red curry paste","to taste salt"],"steps":["Slice the carrot and divide the quarter head of cauliflower into small florets.","Heat the olive oil in a skillet, add the sliced onion and garlic, sauté until tender, and season with salt.","Add the carrot and cauliflower, pour in a splash of water, and simmer in the skillet for 15 minutes.","Add the cooked rice, pour in a little more water, lower the heat, and stir to combine.","Stir in a quarter teaspoon of red curry paste, cook together for another 5 minutes, and transfer to a bowl."],"time":35,"servings":1,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Potrawa_z_ry%C5%BCu_i_warzyw_z_przypraw%C4%85_red_curry","page":"Książka kucharska/Potrawa z ryżu i warzyw z przyprawą red curry"},{"id":"oc-plwb-14464","title":"Warming shrimp soup","cuisine":"Thai","category":"Soup","ingredients":["0.67 red chili pepper (chopped)","1 lemongrass","5 g fresh ginger (finely chopped)","0.33 bunch fresh coriander","500 ml broth","5 shiitake mushrooms (sliced)","6 shrimp (large, peeled)","200 g sea fish fillet (cut into 6 pieces)","2 tbsp lime juice","25 g cane sugar","1 tbsp fish sauce"],"steps":["Pound the chopped chili pepper, lemongrass, ginger, and part of the fresh coriander in a mortar.","Bring the broth to a boil in a pot, then add the sliced shiitake mushrooms, peeled shrimp, and sea fish pieces.","Add the pounded herb paste, lime juice, cane sugar, and fish sauce, and simmer for 2 minutes.","Chop the remaining coriander leaves, stir into the soup, adjust seasoning with extra lime juice or fish sauce if needed, and ladle into bowls."],"time":20,"servings":2,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Rozgrzewaj%C4%85ca_zupa_z_krewetkami","page":"Książka kucharska/Rozgrzewająca zupa z krewetkami"},{"id":"oc-plwb-17823","title":"Zupa tajska ostra (Spicy Thai soup)","cuisine":"Thai","category":"Soup","ingredients":["250 g shrimp","3.5 oyster mushrooms (3–4 small mushrooms)","2 tbsp fish sauce","250 ml lemon juice (1 glass)","1 fresh ginger (small piece)","10 fresh coriander (leaves (plus for garnish))","1 spring onion (bulb)","1 chili pepper (pod)","250 ml coconut milk (1 glass)","750 ml water (3 glasses)"],"steps":["Rinse and peel the shrimp, leaving the shell on the tail.","Cut the oyster mushrooms into strips, and finely chop the chili pepper and spring onion.","Bring the water and coconut milk to a boil in a pot, add the ginger, coriander leaves, and oyster mushrooms, and reduce heat.","Pour in the lemon juice and fish sauce, add the chopped chili, spring onion, and shrimp, and boil everything together for a few minutes until the shrimp change colour.","Ladle the soup into bowls and garnish with fresh coriander leaves."],"time":20,"servings":4,"image":"","source":"https://pl.wikibooks.org/wiki/Ksi%C4%85%C5%BCka_kucharska/Zupa_tajska_ostra","page":"Książka kucharska/Zupa tajska ostra"}];

if (typeof module !== 'undefined') module.exports = { OPENCORPUS_RECIPES, OPENCORPUS_LICENSE };
